    dict: LIR.BoxyDictId,
};

/// What a derived procedure over one representation receives from the frame
/// that calls or builds it, after its two arguments: the operand's own
/// descriptor, the descriptors of the type variables the operand names, and
/// the dictionaries of those variables. A derived type that names no type
/// variable receives none of them.
const DerivedFrameShape = struct {
    operand_desc: bool = false,
    variables: []Plan.TypeRepId = &.{},
    dictionaries: []Plan.Span = &.{},

    fn deinit(self: DerivedFrameShape, allocator: Allocator) void {
        allocator.free(self.variables);
        allocator.free(self.dictionaries);
    }
};

/// A procedure performing a derived method over a recursive tag union, which
/// calls itself where the union recurs.
const DerivedHelper = struct {
    method: Plan.DerivedMethod,
    rep: Plan.TypeRepId,
    frame: ?Plan.WorkerPlanId,
    env: u32,
    proc: LIR.LirProcSpecId,
    shape: DerivedFrameShape,
};

const DescriptorDictCacheEntry = struct {
    dictionaries: Plan.Span,
    dict: LIR.BoxyDictId,
};

const DescriptorMethodSlotCacheEntry = struct {
    worker: Plan.WorkerPlanId,
    slot: LirProgram.BoxyMethodSlotId,
};

/// The frame a template dictionary is built in. Method-slot descriptors and
/// nested dictionaries that only this frame supplies are its locals, and the
/// dictionary is materialized with their values where it is assigned.
const DictTemplateFrame = struct {
    frame: *ProcBodyBuilder,
    captures: std.ArrayList(LIR.LocalId) = .empty,

    fn capture(self: *DictTemplateFrame, allocator: Allocator, local: LIR.LocalId) Allocator.Error!void {
        if (std.mem.findScalar(LIR.LocalId, self.captures.items, local) != null) return;
        try self.captures.append(allocator, local);
    }

    fn captureSpan(self: *DictTemplateFrame, allocator: Allocator, span: LIR.LocalSpan) Allocator.Error!void {
        const locals = self.frame.parent.result.store.getLocalSpan(span);
        for (0..GuardedList.borrowLen(locals)) |index| try self.capture(allocator, GuardedList.at(locals, index));
    }
};

/// A descriptor of a template dictionary's method that only the building
/// frame supplies: a requirement-side descriptor, or a type variable the
/// frame binds that the method's checked callable type names. The slot
/// carries it after the worker's hidden descriptors, and the method adapter
/// binds it to `desc` for `rep`.
const FrameRequirementDescriptor = struct {
    desc: Plan.DescriptorRequirementId,
    rep: Plan.TypeRepId,
    slot: u32,
    kind: Kind,

    const Kind = enum {
        /// Bound only where the requirement side is lowered: it can share
        /// its descriptor requirement with the worker.
        requirement,
        /// The building frame's own type variable, bound throughout.
        frame_variable,
    };
};

fn frameDescriptorRefForRequirement(
    descriptors: []const FrameSuppliedDescriptor,
    maybe_desc: ?Plan.DescriptorRequirementId,
) ?LIR.BoxyDescRef {
    const desc = maybe_desc orelse return null;
    for (descriptors) |entry| {
        if (entry.desc == desc) return entry.ref;
    }
    return null;
}

fn frameRequirementDescriptorIndex(descs: []const FrameRequirementDescriptor, desc: Plan.DescriptorRequirementId) ?usize {
    for (descs, 0..) |entry, index| {
        if (entry.desc == desc) return index;
    }
    return null;
}

/// A template dictionary a frame built, with the frame locals it names.
const TemplateDictCacheEntry = struct {
    source_rep: Plan.TypeRepId,
    worker_dictionaries: Plan.Span,
    method_evidence: Plan.Span,
    env: u32,
    dict: LIR.BoxyDictId,
    captures: []LIR.LocalId,
};

/// Descriptors of one descriptor's inspect call; see
/// `BoxyTypeDesc.inspect_arg_descs`.
const StaticDescriptorSourceMapEntry = struct {
    worker_desc: Plan.DescriptorRequirementId,
    source_rep: Plan.TypeRepId,
};

const StaticDescriptorSourceMap = struct {
    entries: std.ArrayList(StaticDescriptorSourceMapEntry) = .empty,

    fn deinit(self: *StaticDescriptorSourceMap, allocator: Allocator) void {
        self.entries.deinit(allocator);
    }

    fn get(self: *const StaticDescriptorSourceMap, desc: Plan.DescriptorRequirementId) ?Plan.TypeRepId {
        for (self.entries.items) |*entry| {
            if (entry.worker_desc == desc) return entry.source_rep;
        }
        return null;
    }

    fn put(
        self: *StaticDescriptorSourceMap,
        allocator: Allocator,
        desc: Plan.DescriptorRequirementId,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        for (self.entries.items) |*entry| {
            if (entry.worker_desc != desc) continue;
            if (entry.source_rep != source_rep) {
                boxyLowerInvariant("static dictionary descriptor source map assigned one worker descriptor to two source reps");
            }
            return;
        }
        try self.entries.append(allocator, .{
            .worker_desc = desc,
            .source_rep = source_rep,
        });
    }
};

const StaticDescriptorBindingScope = enum {
    worker_hidden_params,
    all_worker_descriptors,
};

const StaticMethodCallDescIndexEntry = struct {
    desc: Plan.DescriptorRequirementId,
    index: u32,
};

const StaticMethodCallDescIndexMap = struct {
    entries: std.ArrayList(StaticMethodCallDescIndexEntry) = .empty,

    fn deinit(self: *StaticMethodCallDescIndexMap, allocator: Allocator) void {
        self.entries.deinit(allocator);
    }

    fn get(self: *const StaticMethodCallDescIndexMap, desc: Plan.DescriptorRequirementId) ?u32 {
        for (self.entries.items) |entry| {
            if (entry.desc == desc) return entry.index;
        }
        return null;
    }

    fn put(
        self: *StaticMethodCallDescIndexMap,
        allocator: Allocator,
        desc: Plan.DescriptorRequirementId,
    ) Allocator.Error!void {
        if (self.get(desc) != null) return;
        try self.entries.append(allocator, .{
            .desc = desc,
            .index = @intCast(self.entries.items.len),
        });
    }
};

const StaticMethodCallDescRepMap = struct {
    reps: std.ArrayList(?Plan.TypeRepId) = .empty,

    fn deinit(self: *StaticMethodCallDescRepMap, allocator: Allocator) void {
        self.reps.deinit(allocator);
    }

    fn ensureLen(self: *StaticMethodCallDescRepMap, allocator: Allocator, len: usize) Allocator.Error!void {
        while (self.reps.items.len < len) try self.reps.append(allocator, null);
    }

    fn put(self: *StaticMethodCallDescRepMap, allocator: Allocator, index: u32, rep: Plan.TypeRepId) Allocator.Error!void {
        try self.ensureLen(allocator, @as(usize, index) + 1);
        if (self.reps.items[index]) |existing| {
            if (existing != rep) boxyLowerInvariant("static dictionary method call descriptor aligned to two worker representations");
            return;
        }
        self.reps.items[index] = rep;
    }
};

const StaticMethodCallDescSourceEntry = struct {
    worker_desc: Plan.DescriptorRequirementId,
    source: LirProgram.BoxyMethodHiddenDescSource,
};

const StaticMethodCallDescSourceMap = struct {
    entries: std.ArrayList(StaticMethodCallDescSourceEntry) = .empty,

    fn deinit(self: *StaticMethodCallDescSourceMap, allocator: Allocator) void {
        self.entries.deinit(allocator);
    }

    fn get(self: *const StaticMethodCallDescSourceMap, desc: Plan.DescriptorRequirementId) ?LirProgram.BoxyMethodHiddenDescSource {
        for (self.entries.items) |entry| {
            if (entry.worker_desc == desc) return entry.source;
        }
        return null;
    }

    fn put(
        self: *StaticMethodCallDescSourceMap,
        allocator: Allocator,
        desc: Plan.DescriptorRequirementId,
        source: LirProgram.BoxyMethodHiddenDescSource,
    ) Allocator.Error!void {
        for (self.entries.items) |*entry| {
            if (entry.worker_desc != desc) continue;
            switch (entry.source) {
                .slot => |old_slot| switch (source) {
                    .slot => |new_slot| {
                        if (old_slot != new_slot) {
                            boxyLowerInvariant("static dictionary method descriptor source map assigned one worker descriptor to two slot sources");
                        }
                    },
                    .call, .argument => entry.source = source,
                },
                .call => switch (source) {
                    .slot => {},
                    // A recursive type folds into a single worker rep with one
                    // descriptor, while the generic requirement unrolls the same
                    // type into distinct descriptor slots. Both slots unify to the
                    // worker's concrete type, so the caller passes the same runtime
                    // descriptor to each; the worker descriptor may draw from any of
                    // them. The outermost occurrence is recorded first and kept.
                    .call => {},
                    .argument => entry.source = source,
                },
                .argument => |old_arg| switch (source) {
                    .slot, .call => {},
                    .argument => |new_arg| {
                        if (old_arg != new_arg) {
                            boxyLowerInvariant("static dictionary method descriptor source map assigned one worker descriptor to two argument sources");
                        }
                    },
                },
            }
            return;
        }
        try self.entries.append(allocator, .{
            .worker_desc = desc,
            .source = source,
        });
    }
};

const StaticMethodDescriptorMapping = struct {
    indexes: StaticMethodCallDescIndexMap = .{},
    reps: StaticMethodCallDescRepMap = .{},
    hidden_sources: StaticMethodCallDescSourceMap = .{},

    fn deinit(self: *StaticMethodDescriptorMapping, allocator: Allocator) void {
        self.indexes.deinit(allocator);
        self.reps.deinit(allocator);
        self.hidden_sources.deinit(allocator);
    }
};

const StaticDescInstantiationEntry = struct {
    worker_rep: Plan.TypeRepId,
    source_rep: ?Plan.TypeRepId,
    desc: LIR.BoxyTypeDescId,
    env: u32,
};

/// A descriptor a template dictionary's building frame supplies for one
/// descriptor requirement.
const FrameSuppliedDescriptor = struct {
    desc: Plan.DescriptorRequirementId,
    ref: LIR.BoxyDescRef,
};

const StaticDescInstantiationContext = struct {
    entries: std.ArrayList(StaticDescInstantiationEntry) = .empty,
    environments: std.ArrayList(Environment) = .empty,
    env: u32 = 0,
    /// Requirements a template dictionary's building frame describes. A
    /// position naming one reads the frame's descriptor, which the runtime
    /// resolves when it materializes the template.
    frame_descriptors: []const FrameSuppliedDescriptor = &.{},

    const Binding = struct {
        formal: Plan.TypeRepId,
        actual: Plan.TypeRepId,
        source: ?Plan.TypeRepId,
        env: u32,
    };
    const Environment = struct { parent: u32, binding: Binding };

    fn bound(self: *const StaticDescInstantiationContext, rep: Plan.TypeRepId) ?Binding {
        var env = self.env;
        while (env != 0) {
            const environment = self.environments.items[env - 1];
            if (environment.binding.formal == rep) return environment.binding;
            env = environment.parent;
        }
        return null;
    }

    fn bind(self: *StaticDescInstantiationContext, allocator: Allocator, binding: Binding) Allocator.Error!void {
        if (self.bound(binding.formal)) |existing| {
            if (std.meta.eql(existing, binding)) return;
        }
        const key = Environment{ .parent = self.env, .binding = binding };
        for (self.environments.items, 0..) |environment, index| {
            if (std.meta.eql(environment, key)) {
                self.env = @intCast(index + 1);
                return;
            }
        }
        try self.environments.append(allocator, key);
        self.env = @intCast(self.environments.items.len);
    }

    fn deinit(self: *StaticDescInstantiationContext, allocator: Allocator) void {
        self.entries.deinit(allocator);
        self.environments.deinit(allocator);
    }

    fn get(
        self: *const StaticDescInstantiationContext,
        worker_rep: Plan.TypeRepId,
        source_rep: ?Plan.TypeRepId,
    ) ?LIR.BoxyTypeDescId {
        for (self.entries.items) |entry| {
            if (entry.worker_rep == worker_rep and entry.source_rep == source_rep and entry.env == self.env) return entry.desc;
        }
        return null;
    }

    fn put(
        self: *StaticDescInstantiationContext,
        allocator: Allocator,
        worker_rep: Plan.TypeRepId,
        source_rep: ?Plan.TypeRepId,
        desc: LIR.BoxyTypeDescId,
    ) Allocator.Error!void {
        try self.entries.append(allocator, .{
            .worker_rep = worker_rep,
            .source_rep = source_rep,
            .desc = desc,
            .env = self.env,
        });
    }
};

