const ProcedureBuilder = struct {
    literal_dicts: std.ArrayList(?LIR.BoxyDictId) = .empty,
    literal_const_plans: ?ConstPlanBuilder = null,
    frozen_callable_recipes: std.ArrayList(FrozenCallableRecipe) = .empty,

    packed_plans: collections.DenseMap(layout.Idx, lir_core.PackedData.Plan),
    packed_literals: std.AutoHashMap(PackedLiteralKey, LIR.ListLiteral),
    allocator: Allocator,
    modules: Common.CheckedModules,
    plan: *const Plan.ProgramPlan,
    layout_plan: *const Layouts.LayoutPlan,
    resolved_workers: *const ResolvedWorkers,
    result: *LirProgram.Result,
    options: Options,
    worker_procs: []?LIR.LirProcSpecId,
    erased_worker_procs: []?LIR.LirProcSpecId,
    hosted_external_procs: []?LIR.LirProcSpecId,
    type_desc_ids: []?LIR.BoxyTypeDescId,
    /// Per representation, whether an erased callable sits in its structure;
    /// see `ProcBodyBuilder.repHoldsCallableInStructure`.
    rep_holds_callable: []?bool,
    generated_evidence_desc_ids: [4]?LIR.BoxyTypeDescId,
    internal_leaf_desc_ids: std.AutoHashMapUnmanaged(layout.Idx, LIR.BoxyTypeDescId),
    /// Exact-storage template descriptors that read no procedure's bound
    /// descriptor locals, so every procedure describes the representation
    /// with the same descriptor.
    exact_template_desc_ids: std.AutoHashMapUnmanaged(Plan.TypeRepId, LIR.BoxyTypeDescId) = .empty,
    static_dict_cache: std.ArrayList(StaticDictCacheEntry),
    /// The procedures every descriptor dictionary's `is_eq` and `to_hash`
    /// slots call; see `descriptorDict`.
    descriptor_equality_proc: ?LIR.LirProcSpecId = null,
    descriptor_hash_proc: ?LIR.LirProcSpecId = null,
    descriptor_dicts: std.ArrayList(DescriptorDictCacheEntry) = .empty,
    derived_helpers: std.ArrayList(DerivedHelper) = .empty,
    descriptor_method_slot_cache: std.ArrayList(DescriptorMethodSlotCacheEntry),
    callable_adapter_cache: std.ArrayList(CallableAdapterCacheEntry),
    pending_direct_call_descriptor_abis: std.ArrayList(PendingDirectCallDescriptorAbi),
    descriptor_read_steps: std.ArrayList(DescriptorReadStep),
    source_file_ids: std.StringHashMapUnmanaged(u32),
    hosted_catalog: []HostedCatalogEntry = &.{},
    symbols: Common.SymbolGen = .{},
    /// Procedures reserved for the emission scheduler, in reservation order.
    proc_jobs: std.ArrayList(ProcJob) = .empty,
    /// Every reserved job, in reservation order; the scheduler takes them
    /// from `next_queued_proc_job` on.
    queued_proc_jobs: std.ArrayList(u32) = .empty,
    next_queued_proc_job: usize = 0,
    /// Jobs waiting on the workers they call directly, innermost last.
    proc_job_stack: std.ArrayList(u32) = .empty,
    /// Per worker, its non-erased procedure's emission job.
    worker_jobs: []?u32 = &.{},
    /// Per worker, the return local its reserved header was built with.
    worker_return_locals: []?LIR.LocalId = &.{},
    /// Per worker, where its planned direct callees start in
    /// `planned_direct_callees`.
    planned_direct_callee_starts: []u32 = &.{},
    planned_direct_callees: []Plan.WorkerPlanId = &.{},

    const FrozenCallableRecipe = struct {
        worker: Plan.WorkerPlanId,
        source_rep: Plan.TypeRepId,
        entry: LIR.LirProcSpecId,
        key: [32]u8,
        capture_layout: layout.Idx,
        on_drop: LIR.ErasedCallableOnDrop,
        fields: []const FrozenCaptureRecipe,
        result_rep: Plan.TypeRepId,
        rep: Plan.TypeRepId,
        /// The literal initializer whose frame built this callable, which
        /// then describes it under that initializer's own bindings.
        literal_initializer: ?u32 = null,
    };
    /// A frozen callable's captured descriptor: the creating frame built it
    /// for `source_rep`, the representation it described there, and the
    /// callable reads it for its own `worker_rep`. `exact` is the static
    /// descriptor the creating frame stored when it read none of its own
    /// descriptor bindings.
    const FrozenDescriptorCapture = struct {
        worker_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        exact: ?LIR.BoxyTypeDescId = null,
    };

    const FrozenCaptureRecipe = union(enum) {
        value: Plan.TypeRepId,
        descriptor: FrozenDescriptorCapture,
        dictionary: Plan.Span,
        literal: u32,
    };

    fn sourceLoc(self: *ProcedureBuilder, module: ProcedureModuleView, region: base.Region) Allocator.Error!base.SourceLoc {
        if (self.source_file_ids.count() == 0) {
            for (0..self.result.store.sourceFileCount()) |file| {
                const file_id: u32 = @intCast(file);
                try self.source_file_ids.put(self.allocator, self.result.store.sourceFileQualifiedName(file_id), file_id);
            }
        }
        const qualified_name = module.module_env.qualifiedModuleName();
        if (self.source_file_ids.get(qualified_name)) |file_id| {
            const info = module.module_env.calcRegionInfo(region);
            return .{
                .file = file_id,
                .line = info.start_line_idx + 1,
                .column = info.start_col_idx + 1,
            };
        }
        boxyLowerInvariant("boxy expect source module was absent from the LIR source table");
    }

    /// Origin for a body whose demanding construct has no checked source
    /// region recorded in the plan (dictionary method slots).
    fn constructlessOrigin(kind: LIR.OriginKind) LIR.StmtOrigin {
        return .{
            .loc = base.SourceLoc.none,
            .region = base.Region.zero(),
            .inline_scope = LIR.InlineScopeId.none,
            .kind = kind,
        };
    }

    /// Origin of a worker body's scaffolding. A checked-expression worker
    /// names its root expression; generated and intrinsic workers are derived
    /// code whose plan source records only types, so they carry no region.
    fn workerOrigin(self: *ProcedureBuilder, resolved: ResolvedWorker) Allocator.Error!LIR.StmtOrigin {
        return switch (resolved.body) {
            .checked_expr => |body| blk: {
                const region = resolved.module.checked_bodies.expr(body.root_expr).source_region;
                break :blk .{
                    .loc = try self.sourceLoc(resolved.module, region),
                    .region = region,
                    .inline_scope = LIR.InlineScopeId.none,
                    .kind = .scaffold,
                };
            },
            .hosted, .unimplemented, .const_crash => constructlessOrigin(.scaffold),
            .intrinsic,
            .generated_codec,
            .generated_field_iterator,
            => constructlessOrigin(.derived),
        };
    }

    fn expectSite(self: *ProcedureBuilder, module: ProcedureModuleView, region: base.Region) Allocator.Error!?LIR.ExpectSiteId {
        if (!self.options.observe_expects) return null;
        return try self.result.addExpectSite(try self.sourceLoc(module, region), region);
    }

    /// The module data the shared label-comparing plan queries need.
    pub fn moduleNames(self: *ProcedureBuilder, module_id: checked.ModuleId) Plan.ModuleNames {
        const view = procedureModuleById(self.modules, module_id);
        return .{ .key = view.key, .canonical_names = view.canonical_names };
    }

    /// Shared read-only queries over the representation plan.
    fn repQuery(self: *const ProcedureBuilder) Plan.RepQuery {
        return .{ .plan = self.plan, .allocator = self.allocator };
    }

    /// Shared label-comparing queries over the representation plan.
    fn namedQuery(self: *ProcedureBuilder) Plan.NamedRepQuery(*ProcedureBuilder) {
        return .{ .query = self.repQuery(), .modules = self };
    }

    fn init(
        allocator: Allocator,
        modules: Common.CheckedModules,
        plan: *const Plan.ProgramPlan,
        layout_plan: *const Layouts.LayoutPlan,
        resolved_workers: *const ResolvedWorkers,
        result: *LirProgram.Result,
        options: Options,
    ) ProcedureBuilder {
        return .{
            .allocator = allocator,
            .modules = modules,
            .plan = plan,
            .layout_plan = layout_plan,
            .resolved_workers = resolved_workers,
            .result = result,
            .options = options,
            .worker_procs = &.{},
            .erased_worker_procs = &.{},
            .hosted_external_procs = &.{},
            .type_desc_ids = &.{},
            .rep_holds_callable = &.{},
            .generated_evidence_desc_ids = .{ null, null, null, null },
            .internal_leaf_desc_ids = .empty,
            .static_dict_cache = .empty,
            .descriptor_method_slot_cache = .empty,
            .callable_adapter_cache = .empty,
            .pending_direct_call_descriptor_abis = .empty,
            .descriptor_read_steps = .empty,
            .source_file_ids = .empty,
            .packed_plans = collections.DenseMap(layout.Idx, lir_core.PackedData.Plan).init(allocator),
            .packed_literals = std.AutoHashMap(PackedLiteralKey, LIR.ListLiteral).init(allocator),
        };
    }

    fn deinit(self: *ProcedureBuilder) void {
        self.literal_dicts.deinit(self.allocator);
        if (self.literal_const_plans) |*plans| plans.deinit();
        for (self.frozen_callable_recipes.items) |recipe| self.allocator.free(recipe.fields);
        self.frozen_callable_recipes.deinit(self.allocator);
        var plans = self.packed_plans.valueIterator();
        while (plans.next()) |plan| plan.deinit();
        self.packed_plans.deinit();
        self.packed_literals.deinit();
        self.source_file_ids.deinit(self.allocator);
        self.descriptor_read_steps.deinit(self.allocator);
        self.pending_direct_call_descriptor_abis.deinit(self.allocator);
        for (self.callable_adapter_cache.items) |entry| self.allocator.free(entry.materialize_reps);
        self.callable_adapter_cache.deinit(self.allocator);
        self.descriptor_method_slot_cache.deinit(self.allocator);
        self.internal_leaf_desc_ids.deinit(self.allocator);
        self.exact_template_desc_ids.deinit(self.allocator);
        self.static_dict_cache.deinit(self.allocator);
        self.descriptor_dicts.deinit(self.allocator);
        for (self.derived_helpers.items) |helper| helper.shape.deinit(self.allocator);
        self.derived_helpers.deinit(self.allocator);
        self.allocator.free(self.hosted_catalog);
        self.allocator.free(self.type_desc_ids);
        self.allocator.free(self.rep_holds_callable);
        self.allocator.free(self.hosted_external_procs);
        self.allocator.free(self.erased_worker_procs);
        self.allocator.free(self.worker_procs);
        for (self.proc_jobs.items) |*job| self.freeProcJobBody(job);
        self.proc_jobs.deinit(self.allocator);
        self.queued_proc_jobs.deinit(self.allocator);
        self.proc_job_stack.deinit(self.allocator);
        self.allocator.free(self.worker_jobs);
        self.allocator.free(self.worker_return_locals);
        self.allocator.free(self.planned_direct_callee_starts);
        self.allocator.free(self.planned_direct_callees);
        self.* = undefined;
    }

    fn addDescriptorReadPath(
        self: *ProcedureBuilder,
        steps: []const DescriptorReadStep,
    ) Allocator.Error!Plan.Span {
        if (steps.len == 0) return .{};
        if (steps.len > std.math.maxInt(u32) or self.descriptor_read_steps.items.len > std.math.maxInt(u32) - steps.len) {
            boxyLowerInvariant("boxy descriptor read_path table exceeded LIR range");
        }
        const start: u32 = @intCast(self.descriptor_read_steps.items.len);
        try self.descriptor_read_steps.appendSlice(self.allocator, steps);
        return .{ .start = start, .len = @intCast(steps.len) };
    }

    fn descriptorReadPathSlice(
        self: *const ProcedureBuilder,
        span: Plan.Span,
    ) []const DescriptorReadStep {
        return self.descriptor_read_steps.items[span.start..][0..span.len];
    }

    fn ensureTypeDescIds(self: *ProcedureBuilder) Allocator.Error!void {
        if (self.type_desc_ids.len != 0) return;
        self.type_desc_ids = try self.allocator.alloc(?LIR.BoxyTypeDescId, self.plan.representations.items.len);
        @memset(self.type_desc_ids, null);
    }

    fn staticDescRefForRep(self: *ProcedureBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.BoxyDescRef {
        return .{ .static = try self.typeDescForRep(rep_id) };
    }

    fn typeDescForRep(self: *ProcedureBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.BoxyTypeDescId {
        return switch (try self.runStatic(.{ .desc = rep_id })) {
            .desc => |desc| desc,
            .ref, .dict, .slot_id, .span, .method_slot, .adapter => boxyLowerInvariant("static descriptor request delivered a non-descriptor value"),
        };
    }

    fn staticTagVariantsForRep(self: *ProcedureBuilder, rep_id: Plan.TypeRepId, payload_layout: layout.Idx) Allocator.Error!LIR.BoxySpan {
        return staticValueSpan(try self.runStatic(.{ .tag_variants = .{
            .position = .{ .worker = rep_id },
            .payload_layout = payload_layout,
        } }));
    }

    fn staticTagExtDescForRep(self: *ProcedureBuilder, rep_id: Plan.TypeRepId) Allocator.Error!?LIR.BoxyDescRef {
        return staticValueRef(try self.runStatic(.{ .tag_ext = .{ .worker = rep_id } }));
    }

    fn typeDescForWorkerRepWithSourceMap(
        self: *ProcedureBuilder,
        worker_rep_id: Plan.TypeRepId,
        source_rep_id: ?Plan.TypeRepId,
        descriptor_sources: *const StaticDescriptorSourceMap,
        context: *StaticDescInstantiationContext,
    ) Allocator.Error!LIR.BoxyTypeDescId {
        return switch (try self.runStatic(.{ .source_desc = .{
            .worker = worker_rep_id,
            .source = source_rep_id,
            .mapping = .{ .sources = descriptor_sources, .context = context },
        } })) {
            .desc => |desc| desc,
            .ref, .dict, .slot_id, .span, .method_slot, .adapter => boxyLowerInvariant("source-mapped descriptor request delivered a non-descriptor value"),
        };
    }

    fn staticDescRefForWorkerRepWithSourceMap(
        self: *ProcedureBuilder,
        worker_rep_id: Plan.TypeRepId,
        source_rep_id: ?Plan.TypeRepId,
        descriptor_sources: *const StaticDescriptorSourceMap,
        context: *StaticDescInstantiationContext,
    ) Allocator.Error!LIR.BoxyDescRef {
        return staticValueRef(try self.runStatic(.{ .source_desc_ref = .{
            .worker = worker_rep_id,
            .source = source_rep_id,
            .mapping = .{ .sources = descriptor_sources, .context = context },
        } })) orelse boxyLowerInvariant("source-mapped descriptor reference request delivered no descriptor");
    }

    fn staticDictRefForRep(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
    ) Allocator.Error!LIR.BoxyDictRef {
        return try self.staticDictRefForRepWithEvidence(rep_id, worker_dictionaries, .{}, 0);
    }

    fn staticDictRefForRepWithEvidence(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
        method_evidence: Plan.Span,
        env: u32,
    ) Allocator.Error!LIR.BoxyDictRef {
        return .{ .static = staticValueDict(try self.runStatic(.{ .dict = .{
            .rep = rep_id,
            .worker_dictionaries = worker_dictionaries,
            .method_evidence = method_evidence,
            .template = null,
            .env = env,
        } })) };
    }

    /// A dictionary built in `template`'s frame: a template when its method
    /// evidence names values only that frame supplies, otherwise the shared
    /// static dictionary.
    fn dictForRepInFrame(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
        method_evidence: Plan.Span,
        template: *DictTemplateFrame,
        env: u32,
    ) Allocator.Error!LIR.BoxyDictId {
        return staticValueDict(try self.runStatic(.{ .dict_in_frame = .{
            .rep = rep_id,
            .worker_dictionaries = worker_dictionaries,
            .method_evidence = method_evidence,
            .template = template,
            .env = env,
        } }));
    }

    /// The descriptor-carried inspect slot of `rep_id`'s planned override. It
    /// holds only what every instantiation of the owning nominal shares; each
    /// descriptor supplies its own instantiation's receiver and hidden
    /// descriptors, which the slot's `.slot` sources index.
    fn descriptorMethodSlotForRep(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        kind: Plan.DescriptorMethod,
    ) Allocator.Error!?LirProgram.BoxyMethodSlotId {
        return switch (try self.runStatic(.{ .inspect_slot = .{ .rep = rep_id, .kind = kind } })) {
            .slot_id => |slot| slot,
            .desc, .ref, .dict, .span, .method_slot, .adapter => boxyLowerInvariant("inspect slot request delivered a non-slot value"),
        };
    }

    /// The descriptor sources a worker representation's positions are
    /// instantiated by.
    const StaticSourceMapping = struct {
        sources: *const StaticDescriptorSourceMap,
        context: *StaticDescInstantiationContext,
    };

    const StaticSourceDescRequest = struct {
        worker: Plan.TypeRepId,
        source: ?Plan.TypeRepId,
        mapping: StaticSourceMapping,
    };

    /// A descriptor position: a representation described statically, or,
    /// with a mapping, a worker representation instantiated by it and by
    /// the aligned source.
    const StaticDescPosition = struct {
        worker: Plan.TypeRepId,
        source: ?Plan.TypeRepId = null,
        mapping: ?StaticSourceMapping = null,
    };

    const StaticDictRequest = struct {
        rep: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
        method_evidence: Plan.Span,
        template: ?*DictTemplateFrame,
        /// The derived-method formal bindings a dictionary for a
        /// representation inside a generic nominal's backing is
        /// instantiated at.
        env: u32,
    };

    const StaticTagVariantsRequest = struct {
        position: StaticDescPosition,
        payload_layout: layout.Idx,
    };

    const StaticPayloadDescsRequest = struct {
        payloads: []const Plan.RepChild,
        source_payloads: []const Plan.RepChild,
        payload_layout: layout.Idx,
        mapping: ?StaticSourceMapping,
    };

    /// An inspect call's descriptors for the descriptor `self_desc` under
    /// construction; see `BoxyTypeDesc.inspect_hidden_descs` and
    /// `BoxyTypeDesc.inspect_arg_descs`.
    const StaticDescriptorMethodRequest = struct {
        kind: Plan.DescriptorMethod,
        rep: Plan.TypeRepId,
        self_desc: LIR.BoxyTypeDescId,
        building_worker_rep: ?Plan.TypeRepId = null,
        mapping: ?StaticSourceMapping = null,
    };

    const StaticStructuralSlotRequest = struct {
        rep: Plan.TypeRepId,
        requirement: Plan.DictionaryRequirement,
        fn_type: Plan.CheckedTypeIdentity,
        method: Plan.DerivedMethod,
        template: ?*DictTemplateFrame,
        env: u32,
    };

    const StaticMethodAdapterRequest = struct {
        worker_id: Plan.WorkerPlanId,
        requirement_fn_ty: Plan.CheckedTypeIdentity,
        descriptor_sources: *const StaticDescriptorSourceMap,
        desc_context: *StaticDescInstantiationContext,
        evidence_requirement_fn_ty: ?Plan.CheckedTypeIdentity,
        worker_desc_args: ?Plan.Span,
        requirement_desc_args: ?Plan.Span,
        requirement_desc_sources: ?Plan.Span,
        requirement_leaf_sources: ?Plan.Span,
        hidden_desc_sources: ?Plan.Span,
        frame_requirement_descs: []const FrameRequirementDescriptor,
    };

    /// Static descriptors, dictionaries, and inspect slots are built by one
    /// explicit machine. Building one can need another of any kind, to the
    /// depth of the described types, so each need is a request the machine
    /// runs as a frame; every table entry is reserved and appended in the
    /// order a depth-first walk reaches it.
    const StaticRequest = union(enum) {
        /// The static descriptor of a representation.
        desc: Plan.TypeRepId,
        /// A worker representation's descriptor instantiated by descriptor
        /// sources.
        source_desc: StaticSourceDescRequest,
        /// As `source_desc`, except that a position the building frame
        /// describes reads that frame's descriptor.
        source_desc_ref: StaticSourceDescRequest,
        dict: StaticDictRequest,
        /// A dictionary built in the request's template frame.
        dict_in_frame: StaticDictRequest,
        inspect_slot: struct { rep: Plan.TypeRepId, kind: Plan.DescriptorMethod },
        method_dicts: struct { rep: Plan.TypeRepId, kind: Plan.DescriptorMethod },
        nested_descs: StaticDescPosition,
        tag_variants: StaticTagVariantsRequest,
        tag_ext: StaticDescPosition,
        payload_descs: StaticPayloadDescsRequest,
        inspect_hidden: StaticDescriptorMethodRequest,
        inspect_arg: StaticDescriptorMethodRequest,
        structural_slot: StaticStructuralSlotRequest,
        method_adapter: StaticMethodAdapterRequest,
    };

    const StaticValue = union(enum) {
        desc: LIR.BoxyTypeDescId,
        ref: ?LIR.BoxyDescRef,
        dict: LIR.BoxyDictId,
        slot_id: ?LirProgram.BoxyMethodSlotId,
        span: LIR.BoxySpan,
        method_slot: LirProgram.BoxyMethodSlot,
        adapter: LirProgram.BoxyMethodAdapter,
    };

    fn staticValueRef(value: StaticValue) ?LIR.BoxyDescRef {
        return switch (value) {
            .desc => |desc| .{ .static = desc },
            .ref => |ref| ref,
            .dict, .slot_id, .span, .method_slot, .adapter => boxyLowerInvariant("static descriptor machine delivered a non-descriptor value"),
        };
    }

    fn staticValueSpan(value: StaticValue) LIR.BoxySpan {
        return switch (value) {
            .span => |span| span,
            .desc, .ref, .dict, .slot_id, .method_slot, .adapter => boxyLowerInvariant("static descriptor machine delivered a non-span value"),
        };
    }

    fn staticValueDict(value: StaticValue) LIR.BoxyDictId {
        return switch (value) {
            .dict => |dict| dict,
            .desc, .ref, .span, .slot_id, .method_slot, .adapter => boxyLowerInvariant("static descriptor machine delivered a non-dictionary value"),
        };
    }

    const StaticStep = union(enum) {
        request: StaticRequest,
        done: StaticValue,
    };

    const StaticFrame = union(enum) {
        desc: *StaticDescFrame,
        source_desc: *StaticSourceDescFrame,
        dict: *StaticDictFrame,
        inspect_slot: *StaticDescriptorMethodSlotFrame,
        method_dicts: *StaticDescriptorMethodDictFrame,
        nested_descs: *StaticNestedDescsFrame,
        tag_variants: *StaticTagVariantsFrame,
        payload_descs: *StaticPayloadDescsFrame,
        inspect_hidden: *StaticDescriptorMethodHiddenFrame,
        inspect_arg: *StaticDescriptorMethodArgFrame,
        structural_slot: *StaticStructuralSlotFrame,
        method_adapter: *StaticMethodAdapterFrame,
    };

    const DescriptorMethodParts = struct {
        method: ?LirProgram.BoxyMethodSlotId = null,
        hidden: LIR.BoxySpan = .{},
        args: LIR.BoxySpan = .{},
        dictionaries: LIR.BoxySpan = .{},
    };
    const descriptor_method_kinds = [_]Plan.DescriptorMethod{ .inspect, .equality, .hash };

    /// A representation's static descriptor.
    const StaticDescFrame = struct {
        rep: Plan.TypeRepId,
        phase: Phase = .start,
        desc_id: LIR.BoxyTypeDescId = undefined,
        payload_layout: layout.Idx = undefined,
        nested_descs: LIR.BoxySpan = .{},
        tag_variants: LIR.BoxySpan = .{},
        tag_ext_desc: ?LIR.BoxyDescRef = null,
        field_names: LIR.BoxySpan = .{},
        method_index: usize = 0,
        methods: [3]DescriptorMethodParts = @splat(.{}),
        /// A nominal backing's descriptor sources and instantiation context.
        sources: StaticDescriptorSourceMap = .{},
        context: StaticDescInstantiationContext = .{},

        const Phase = enum { start, forward, nested, variants, ext, inspect_method, inspect_hidden, inspect_arg, inspect_dict };

        fn deinit(frame: *StaticDescFrame, allocator: Allocator) void {
            frame.sources.deinit(allocator);
            frame.context.deinit(allocator);
        }
    };

    /// A worker representation's descriptor instantiated by descriptor
    /// sources.
    const StaticSourceDescFrame = struct {
        request: StaticSourceDescRequest,
        phase: Phase = .start,
        worker: Plan.TypeRepId = undefined,
        source: ?Plan.TypeRepId = null,
        /// The context environment the descriptor's enclosing scope binds,
        /// restored once the descriptor's own positions are built.
        outer_env: u32 = 0,
        desc_id: LIR.BoxyTypeDescId = undefined,
        payload_layout: layout.Idx = undefined,
        nested_descs: LIR.BoxySpan = .{},
        tag_variants: LIR.BoxySpan = .{},
        tag_ext_desc: ?LIR.BoxyDescRef = null,
        field_names: LIR.BoxySpan = .{},
        method_index: usize = 0,
        methods: [3]DescriptorMethodParts = @splat(.{}),

        const Phase = enum { start, redirect, forward, nested, variants, ext, inspect_method, inspect_hidden, inspect_arg, inspect_dict };

        fn deinit(_: *StaticSourceDescFrame, _: Allocator) void {}
    };

    const StaticNestedDescsFrame = struct {
        position: StaticDescPosition,
        started: bool = false,
        source_children: []const Plan.RepChild = &.{},
        slots: std.ArrayList(NestedDescriptorSlot) = .empty,
        refs: std.ArrayList(LIR.BoxyDescRef) = .empty,

        fn deinit(frame: *StaticNestedDescsFrame, allocator: Allocator) void {
            frame.slots.deinit(allocator);
            frame.refs.deinit(allocator);
        }
    };

    const StaticTagVariantsFrame = struct {
        request: StaticTagVariantsRequest,
        phase: Phase = .start,
        worker_tag: Plan.TypeRepId = undefined,
        source_tag: ?Plan.TypeRepId = null,
        variants: []const Plan.TagVariant = &.{},
        source_variants: []const Plan.TagVariant = &.{},
        index: usize = 0,
        /// A source-mapped variant's name, inserted before its payloads.
        name: @FieldType(LirProgram.BoxyTagVariant, "name") = undefined,
        entries: std.ArrayList(LirProgram.BoxyTagVariant) = .empty,

        const Phase = enum { start, zst_payloads, has_ext, variant_payloads };

        fn deinit(frame: *StaticTagVariantsFrame, allocator: Allocator) void {
            frame.entries.deinit(allocator);
        }
    };

    const StaticPayloadDescsFrame = struct {
        request: StaticPayloadDescsRequest,
        index: usize = 0,
        pending_index: u32 = 0,
        descs: std.ArrayList(LirProgram.BoxyTagPayloadDesc) = .empty,

        fn deinit(frame: *StaticPayloadDescsFrame, allocator: Allocator) void {
            frame.descs.deinit(allocator);
        }
    };

    const StaticDescriptorMethodHiddenFrame = struct {
        request: StaticDescriptorMethodRequest,
        started: bool = false,
        hidden_desc_args: Plan.Span = .{},
        refs: std.ArrayList(LIR.BoxyDescRef) = .empty,

        fn deinit(frame: *StaticDescriptorMethodHiddenFrame, allocator: Allocator) void {
            frame.refs.deinit(allocator);
        }
    };

    const StaticDescriptorMethodArgFrame = struct {
        request: StaticDescriptorMethodRequest,
        arg_sources: StaticDescriptorSourceMap = .{},
        local_context: StaticDescInstantiationContext = .{},

        fn deinit(frame: *StaticDescriptorMethodArgFrame, allocator: Allocator) void {
            frame.arg_sources.deinit(allocator);
            frame.local_context.deinit(allocator);
        }
    };

    const StaticDescriptorMethodDictFrame = struct {
        rep: Plan.TypeRepId,
        kind: Plan.DescriptorMethod,
        args: Plan.Span = .{},
        started: bool = false,
        refs: std.ArrayList(LIR.BoxyDictRef) = .empty,
        fn deinit(frame: *StaticDescriptorMethodDictFrame, allocator: Allocator) void {
            frame.refs.deinit(allocator);
        }
    };

    const StaticDescriptorMethodSlotFrame = struct {
        kind: Plan.DescriptorMethod,
        rep: Plan.TypeRepId,
        inspect: ?Plan.DescriptorMethodPlan = null,
        slot_id: LirProgram.BoxyMethodSlotId = undefined,
        nested_dict_refs: std.ArrayList(LIR.BoxyDictRef) = .empty,

        fn deinit(frame: *StaticDescriptorMethodSlotFrame, allocator: Allocator) void {
            frame.nested_dict_refs.deinit(allocator);
        }
    };

    /// A static dictionary, built one method slot at a time. The slots are
    /// collected here and appended contiguously once every slot is built,
    /// since building a slot can append other dictionaries' slots.
    const StaticDictFrame = struct {
        request: StaticDictRequest,
        phase: Phase = .start,
        dict_id: LIR.BoxyDictId = undefined,
        /// A template's own captures, recorded once it is built; a nested use
        /// of it while building reads them from the frame's cache entry.
        own_template: ?DictTemplateFrame = null,
        slots: std.ArrayList(LirProgram.BoxyMethodSlot) = .empty,
        method_index: usize = 0,
        /// The slot being built.
        requirement: Plan.DictionaryRequirement = undefined,
        slot_index: usize = 0,
        exact_method: ?Plan.DictionaryMethodEvidence = null,
        resolved: Plan.WorkerPlanId = undefined,
        fn_type: Plan.CheckedTypeIdentity = undefined,
        method_proc: LIR.LirProcSpecId = undefined,
        item: usize = 0,
        descriptor_sources: StaticDescriptorSourceMap = .{},
        desc_context: StaticDescInstantiationContext = .{},
        adapter_desc_context: StaticDescInstantiationContext = .{},
        hidden_desc_refs: std.ArrayList(LIR.BoxyDescRef) = .empty,
        nested_dict_refs: std.ArrayList(LIR.BoxyDictRef) = .empty,
        frame_requirement_descs: std.ArrayList(FrameRequirementDescriptor) = .empty,
        frame_descriptors: std.ArrayList(FrameSuppliedDescriptor) = .empty,

        const Phase = enum { start, structural, hidden_descs, nested_dicts, adapter };

        fn slotTemplate(frame: *StaticDictFrame) ?*DictTemplateFrame {
            return if (frame.own_template) |*own| own else null;
        }

        fn resetSlot(frame: *StaticDictFrame, allocator: Allocator) void {
            frame.descriptor_sources.deinit(allocator);
            frame.descriptor_sources = .{};
            frame.desc_context.deinit(allocator);
            frame.desc_context = .{};
            frame.adapter_desc_context.deinit(allocator);
            frame.adapter_desc_context = .{};
            frame.hidden_desc_refs.clearRetainingCapacity();
            frame.nested_dict_refs.clearRetainingCapacity();
            frame.frame_requirement_descs.clearRetainingCapacity();
            frame.frame_descriptors.clearRetainingCapacity();
            frame.item = 0;
        }

        fn deinit(frame: *StaticDictFrame, allocator: Allocator) void {
            if (frame.own_template) |*own| own.captures.deinit(allocator);
            frame.slots.deinit(allocator);
            frame.descriptor_sources.deinit(allocator);
            frame.desc_context.deinit(allocator);
            frame.adapter_desc_context.deinit(allocator);
            frame.hidden_desc_refs.deinit(allocator);
            frame.nested_dict_refs.deinit(allocator);
            frame.frame_requirement_descs.deinit(allocator);
            frame.frame_descriptors.deinit(allocator);
        }
    };

    /// A dictionary slot performing a derived `is_eq` or `to_hash` over a
    /// representation. When the derived type names the building frame's type
    /// variables, the slot's procedure receives that frame's descriptors and
    /// dictionaries for them, after its two arguments, and its components
    /// dispatch through them exactly as they would in the frame.
    const StaticStructuralSlotFrame = struct {
        request: StaticStructuralSlotRequest,
        phase: Phase = .start,
        frame_template: ?*DictTemplateFrame = null,
        shape: DerivedFrameShape = .{},
        proc_id: LIR.LirProcSpecId = undefined,
        second_rep: Plan.TypeRepId = undefined,
        source_layout: layout.Idx = undefined,
        second_layout: layout.Idx = undefined,
        operand_desc: LIR.BoxyDescRef = undefined,
        arg_layout_start: u32 = 0,
        frame_desc_refs: std.ArrayList(LIR.BoxyDescRef) = .empty,
        frame_dict_refs: std.ArrayList(LIR.BoxyDictRef) = .empty,
        frame_descriptors: std.ArrayList(FrameSuppliedDescriptor) = .empty,
        context: StaticDescInstantiationContext = .{},
        sources: StaticDescriptorSourceMap = .{},

        const Phase = enum { start, operand_frame_desc, operand, second };

        fn deinit(frame: *StaticStructuralSlotFrame, allocator: Allocator) void {
            frame.shape.deinit(allocator);
            frame.frame_desc_refs.deinit(allocator);
            frame.frame_dict_refs.deinit(allocator);
            frame.frame_descriptors.deinit(allocator);
            frame.context.deinit(allocator);
            frame.sources.deinit(allocator);
        }
    };

    /// The adapter a static dictionary method slot calls its method through.
    const StaticMethodAdapterFrame = struct {
        request: StaticMethodAdapterRequest,
        phase: Phase = .start,
        mapping: StaticMethodDescriptorMapping = .{},
        requirement_sources: StaticDescriptorSourceMap = .{},
        requirement_args: []const Plan.RepChild = &.{},
        arg_layouts_start: u32 = 0,
        arg_refs: std.ArrayList(LIR.BoxyDescRef) = .empty,
        arg_descs: LIR.BoxySpan = .{},
        /// Whether the call descriptors follow the planned evidence rather
        /// than the worker's descriptor mapping.
        evidence_call_descs: bool = false,
        indexes: StaticMethodCallDescIndexMap = .{},
        call_sources: StaticDescriptorSourceMap = .{},
        call_context: StaticDescInstantiationContext = .{},
        index: usize = 0,
        pending_slot: u32 = 0,
        call_descs: std.ArrayList(LIR.BoxyDescRef) = .empty,
        runtime_sources: std.ArrayList(LirProgram.BoxyMethodHiddenDescSource) = .empty,

        const Phase = enum { start, arg_descs, call_descs };

        fn deinit(frame: *StaticMethodAdapterFrame, allocator: Allocator) void {
            frame.mapping.deinit(allocator);
            frame.requirement_sources.deinit(allocator);
            frame.arg_refs.deinit(allocator);
            frame.indexes.deinit(allocator);
            frame.call_sources.deinit(allocator);
            frame.call_context.deinit(allocator);
            frame.call_descs.deinit(allocator);
            frame.runtime_sources.deinit(allocator);
        }
    };

    fn runStatic(self: *ProcedureBuilder, request: StaticRequest) Allocator.Error!StaticValue {
        var stack: std.ArrayList(StaticFrame) = .empty;
        defer {
            for (stack.items) |frame| self.destroyStaticFrame(frame);
            stack.deinit(self.allocator);
        }
        var delivered = try self.beginStatic(&stack, request);
        while (stack.items.len != 0) {
            const top = stack.items[stack.items.len - 1];
            const step = try self.stepStaticFrame(top, delivered);
            delivered = null;
            switch (step) {
                .request => |child| delivered = try self.beginStatic(&stack, child),
                .done => |value| {
                    _ = stack.pop();
                    self.destroyStaticFrame(top);
                    delivered = value;
                },
            }
        }
        return delivered orelse boxyLowerInvariant("static descriptor machine finished without a value");
    }

    fn pushStaticFrame(
        self: *ProcedureBuilder,
        stack: *std.ArrayList(StaticFrame),
        comptime tag: std.meta.Tag(StaticFrame),
        initial: @typeInfo(@FieldType(StaticFrame, @tagName(tag))).pointer.child,
    ) Allocator.Error!?StaticValue {
        const Frame = @typeInfo(@FieldType(StaticFrame, @tagName(tag))).pointer.child;
        const frame = try self.allocator.create(Frame);
        frame.* = initial;
        stack.append(self.allocator, @unionInit(StaticFrame, @tagName(tag), frame)) catch |err| {
            self.allocator.destroy(frame);
            return err;
        };
        return null;
    }

    fn destroyStaticFrame(self: *ProcedureBuilder, frame: StaticFrame) void {
        switch (frame) {
            inline .desc, .source_desc, .dict, .inspect_slot, .method_dicts, .nested_descs, .tag_variants, .payload_descs, .inspect_hidden, .inspect_arg, .structural_slot, .method_adapter => |payload| {
                payload.deinit(self.allocator);
                self.allocator.destroy(payload);
            },
        }
    }

    /// Answer `request` at once when a cache or the request itself holds
    /// its value, else push the frame that builds it.
    fn beginStatic(
        self: *ProcedureBuilder,
        stack: *std.ArrayList(StaticFrame),
        request: StaticRequest,
    ) Allocator.Error!?StaticValue {
        next: switch (request) {
            .desc => |rep_id| {
                try self.ensureTypeDescIds();
                const rep_index = @backingInt(rep_id);
                if (rep_index >= self.type_desc_ids.len) {
                    boxyLowerInvariant("boxy descriptor referenced a representation outside the descriptor cache");
                }
                if (self.type_desc_ids[rep_index]) |existing| return .{ .desc = existing };
                return try self.pushStaticFrame(stack, .desc, .{ .rep = rep_id });
            },
            .source_desc => |source_desc| return try self.pushStaticFrame(stack, .source_desc, .{ .request = source_desc }),
            .source_desc_ref => |source_desc| {
                const mapping = source_desc.mapping;
                if (mapping.context.frame_descriptors.len != 0) {
                    if (self.frameDescriptorRefForWorkerRep(source_desc.worker, source_desc.source, mapping.sources, mapping.context)) |ref| {
                        return .{ .ref = ref };
                    }
                }
                return try self.pushStaticFrame(stack, .source_desc, .{ .request = source_desc });
            },
            .dict => |dict| {
                if (dict.template == null) {
                    for (self.static_dict_cache.items) |entry| {
                        if (entry.source_rep == dict.rep and
                            entry.env == dict.env and
                            std.meta.eql(entry.worker_dictionaries, dict.worker_dictionaries) and
                            std.meta.eql(entry.method_evidence, dict.method_evidence))
                        {
                            return .{ .dict = entry.dict };
                        }
                    }
                }
                return try self.pushStaticFrame(stack, .dict, .{ .request = dict });
            },
            .dict_in_frame => |dict| {
                const template = dict.template orelse boxyLowerInvariant("frame dictionary request had no template frame");
                var visited = std.ArrayList(Plan.Span).empty;
                defer visited.deinit(self.allocator);
                // Structural slots describe the dictionary's own
                // representation, so it needs the frame whenever that
                // representation does.
                const env_needs_frame = dict.env != 0 and
                    try self.plan.derivedFrame(self.allocator, template.frame.worker_layout.worker, dict.rep, dict.env) != null;
                if (!try template.frame.repDescriptorNeedsFrame(dict.rep) and !env_needs_frame and
                    !try self.dictEvidenceNeedsFrame(template.frame, dict.method_evidence, &visited))
                {
                    var shared = dict;
                    shared.template = null;
                    continue :next .{ .dict = shared };
                }
                for (template.frame.template_dict_cache.items) |entry| {
                    if (entry.source_rep == dict.rep and
                        entry.env == dict.env and
                        std.meta.eql(entry.worker_dictionaries, dict.worker_dictionaries) and
                        std.meta.eql(entry.method_evidence, dict.method_evidence))
                    {
                        for (entry.captures) |local| try template.capture(self.allocator, local);
                        return .{ .dict = entry.dict };
                    }
                }
                return try self.pushStaticFrame(stack, .dict, .{ .request = dict });
            },
            .inspect_slot => |request_slot| return try self.pushStaticFrame(stack, .inspect_slot, .{ .rep = request_slot.rep, .kind = request_slot.kind }),
            .method_dicts => |request_method| return try self.pushStaticFrame(stack, .method_dicts, .{ .rep = request_method.rep, .kind = request_method.kind }),
            .nested_descs => |position| return try self.pushStaticFrame(stack, .nested_descs, .{ .position = position }),
            .tag_variants => |tag_variants| return try self.pushStaticFrame(stack, .tag_variants, .{ .request = tag_variants }),
            .tag_ext => |position| {
                continue :next try self.staticTagExtRequest(position) orelse return .{ .ref = null };
            },
            .payload_descs => |payload_descs| return try self.pushStaticFrame(stack, .payload_descs, .{ .request = payload_descs }),
            .inspect_hidden => |inspect| return try self.pushStaticFrame(stack, .inspect_hidden, .{ .request = inspect }),
            .inspect_arg => |inspect| return try self.pushStaticFrame(stack, .inspect_arg, .{ .request = inspect }),
            .structural_slot => |slot| return try self.pushStaticFrame(stack, .structural_slot, .{ .request = slot }),
            .method_adapter => |adapter| return try self.pushStaticFrame(stack, .method_adapter, .{ .request = adapter }),
        }
    }

    fn stepStaticFrame(self: *ProcedureBuilder, frame: StaticFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        return switch (frame) {
            .desc => |desc| try self.stepStaticDesc(desc, delivered),
            .source_desc => |source_desc| try self.stepStaticSourceDesc(source_desc, delivered),
            .dict => |dict| try self.stepStaticDict(dict, delivered),
            .inspect_slot => |inspect_slot| try self.stepStaticDescriptorMethodSlot(inspect_slot, delivered),
            .method_dicts => |method| try self.stepStaticDescriptorMethodDict(method, delivered),
            .nested_descs => |nested| try self.stepStaticNestedDescs(nested, delivered),
            .tag_variants => |tag_variants| try self.stepStaticTagVariants(tag_variants, delivered),
            .payload_descs => |payload_descs| try self.stepStaticPayloadDescs(payload_descs, delivered),
            .inspect_hidden => |inspect_hidden| try self.stepStaticDescriptorMethodHidden(inspect_hidden, delivered),
            .inspect_arg => |inspect_arg| try self.stepStaticDescriptorMethodArg(inspect_arg, delivered),
            .structural_slot => |slot| try self.stepStaticStructuralSlot(slot, delivered),
            .method_adapter => |adapter| try self.stepStaticMethodAdapter(adapter, delivered),
        };
    }

    /// The request for a position's own descriptor.
    fn staticPositionDescRequest(
        worker: Plan.TypeRepId,
        source: ?Plan.TypeRepId,
        mapping: ?StaticSourceMapping,
    ) StaticRequest {
        if (mapping) |source_mapping| return .{ .source_desc_ref = .{
            .worker = worker,
            .source = source,
            .mapping = source_mapping,
        } };
        return .{ .desc = worker };
    }

    fn stepStaticDesc(self: *ProcedureBuilder, frame: *StaticDescFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        const rep_index = @backingInt(frame.rep);
        switch (frame.phase) {
            .start => {
                const source_rep = self.plan.representations.items[rep_index];
                if (source_rep.sealed_default) |sealed_default| {
                    frame.phase = .forward;
                    return .{ .request = .{ .desc = sealed_default } };
                }
                if (source_rep.kind == .dynamic and source_rep.children.len == 0 and source_rep.tag_variants.len == 0) {
                    // A variable nothing binds where it is read is at its default.
                    if (self.plan.sharedClosedRep(frame.rep)) |closed| {
                        frame.phase = .forward;
                        return .{ .request = .{ .desc = closed } };
                    }
                }
                if (source_rep.nominal_backing_arg_substitutions.len != 0) {
                    try self.collectStaticNominalBackingDescriptorSources(frame.rep, &frame.sources);
                    frame.phase = .forward;
                    return .{ .request = .{ .source_desc = .{
                        .worker = frame.rep,
                        .source = frame.rep,
                        .mapping = .{ .sources = &frame.sources, .context = &frame.context },
                    } } };
                }

                frame.desc_id = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.boxy_type_descs.items.len))));
                self.type_desc_ids[rep_index] = frame.desc_id;
                try self.result.boxy_type_descs.append(self.allocator, reserved_boxy_type_desc);

                const rep_layout = self.layout_plan.rep_layouts[rep_index];
                frame.payload_layout = rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
                if (source_rep.kind == .dynamic and source_rep.children.len == 0 and source_rep.tag_variants.len == 0 and
                    frame.payload_layout == rep_layout.worker.layoutIdx())
                {
                    boxyLowerInvariant("unresolved bare dynamic representation required a static descriptor");
                }
                frame.phase = .nested;
                return .{ .request = .{ .nested_descs = .{ .worker = frame.rep } } };
            },
            .forward => {
                const desc_id = switch (delivered.?) {
                    .desc => |desc| desc,
                    .ref, .dict, .slot_id, .span, .method_slot, .adapter => boxyLowerInvariant("forwarded static descriptor delivered a non-descriptor value"),
                };
                self.type_desc_ids[rep_index] = desc_id;
                return .{ .done = .{ .desc = desc_id } };
            },
            .nested => {
                frame.nested_descs = staticValueSpan(delivered.?);
                frame.phase = .variants;
                return .{ .request = .{ .tag_variants = .{
                    .position = .{ .worker = frame.rep },
                    .payload_layout = frame.payload_layout,
                } } };
            },
            .variants => {
                frame.tag_variants = staticValueSpan(delivered.?);
                frame.phase = .ext;
                return .{ .request = .{ .tag_ext = .{ .worker = frame.rep } } };
            },
            .ext => {
                frame.tag_ext_desc = staticValueRef(delivered.?);
                frame.field_names = try self.staticFieldNamesForRep(frame.rep);
                frame.phase = .inspect_method;
                return .{ .request = .{ .inspect_slot = .{ .rep = frame.rep, .kind = descriptor_method_kinds[frame.method_index] } } };
            },
            .inspect_method => {
                frame.methods[frame.method_index].method = switch (delivered.?) {
                    .slot_id => |slot| slot,
                    .desc, .ref, .dict, .span, .method_slot, .adapter => boxyLowerInvariant("descriptor inspect slot request delivered a non-slot value"),
                };
                frame.phase = .inspect_hidden;
                return .{ .request = .{ .inspect_hidden = .{ .kind = descriptor_method_kinds[frame.method_index], .rep = frame.rep, .self_desc = frame.desc_id } } };
            },
            .inspect_hidden => {
                frame.methods[frame.method_index].hidden = staticValueSpan(delivered.?);
                frame.phase = .inspect_arg;
                return .{ .request = .{ .inspect_arg = .{ .kind = descriptor_method_kinds[frame.method_index], .rep = frame.rep, .self_desc = frame.desc_id } } };
            },
            .inspect_arg => {
                frame.methods[frame.method_index].args = staticValueSpan(delivered.?);
                frame.phase = .inspect_dict;
                return .{ .request = .{ .method_dicts = .{ .rep = frame.rep, .kind = descriptor_method_kinds[frame.method_index] } } };
            },
            .inspect_dict => {
                frame.methods[frame.method_index].dictionaries = staticValueSpan(delivered.?);
                frame.method_index += 1;
                if (frame.method_index < descriptor_method_kinds.len) {
                    frame.phase = .inspect_method;
                    return .{ .request = .{ .inspect_slot = .{ .rep = frame.rep, .kind = descriptor_method_kinds[frame.method_index] } } };
                }
                const rep = self.plan.representations.items[rep_index];
                const layout_value = self.result.layouts.getLayout(frame.payload_layout);
                self.result.boxy_type_descs.items[@backingInt(frame.desc_id)] = .{
                    .payload_layout = frame.payload_layout,
                    .contains_refcounted = self.result.layouts.layoutContainsRefcounted(layout_value) or rep.contains_dynamic,
                    .shape = self.descriptorShapeForRep(frame.rep),
                    .nested_descs = frame.nested_descs,
                    .tag_variants = frame.tag_variants,
                    .tag_ext_desc = frame.tag_ext_desc,
                    .field_names = frame.field_names,
                    .inspect_opaque = self.repInspectsOpaque(frame.rep),
                    .inspect_method = frame.methods[0].method,
                    .inspect_hidden_descs = frame.methods[0].hidden,
                    .inspect_arg_descs = frame.methods[0].args,
                    .eq_method = frame.methods[1].method,
                    .eq_hidden_descs = frame.methods[1].hidden,
                    .eq_arg_descs = frame.methods[1].args,
                    .eq_nested_dicts = frame.methods[1].dictionaries,
                    .hash_method = frame.methods[2].method,
                    .hash_hidden_descs = frame.methods[2].hidden,
                    .hash_arg_descs = frame.methods[2].args,
                    .hash_nested_dicts = frame.methods[2].dictionaries,
                    .presence_slot_present_discriminant = rep.presence_slot_present_discriminant,
                    .eq_rejected = self.plan.descriptorMethodRejected(frame.rep, .equality),
                    .hash_rejected = self.plan.descriptorMethodRejected(frame.rep, .hash),
                    .is_bool = self.repDescribesBool(frame.rep),
                    .debug_checked_type = rep.source_type.ty,
                };
                return .{ .done = .{ .desc = frame.desc_id } };
            },
        }
    }

    /// Descend into the descriptor a context binding names, under that
    /// binding's environment.
    fn redirectStaticSourceDesc(
        _: *ProcedureBuilder,
        frame: *StaticSourceDescFrame,
        binding: StaticDescInstantiationContext.Binding,
    ) StaticStep {
        const context = frame.request.mapping.context;
        frame.outer_env = context.env;
        context.env = binding.env;
        frame.phase = .redirect;
        return .{ .request = .{ .source_desc = .{
            .worker = binding.actual,
            .source = binding.source,
            .mapping = frame.request.mapping,
        } } };
    }

    fn stepStaticSourceDesc(self: *ProcedureBuilder, frame: *StaticSourceDescFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        const mapping = frame.request.mapping;
        const context = mapping.context;
        switch (frame.phase) {
            .start => {
                const identity_worker = self.descriptorStorageRep(frame.request.worker);
                if (context.bound(identity_worker)) |binding| return self.redirectStaticSourceDesc(frame, binding);
                const effective_source = self.effectiveStaticDescriptorSource(identity_worker, frame.request.source, mapping.sources);
                const identity_source = if (effective_source) |source| self.descriptorIdentityRep(source) else null;

                const worker_rep = self.plan.representations.items[@backingInt(identity_worker)];
                if (worker_rep.kind == .dynamic) {
                    if (identity_source) |source| {
                        if (context.bound(source)) |binding| return self.redirectStaticSourceDesc(frame, binding);
                        const source_rep = self.plan.representations.items[@backingInt(source)];
                        if (!source_rep.contains_dynamic or (worker_rep.children.len == 0 and worker_rep.tag_variants.len == 0)) {
                            frame.phase = .forward;
                            return .{ .request = .{ .desc = source } };
                        }
                    } else if (worker_rep.children.len == 0 and worker_rep.tag_variants.len == 0) {
                        frame.phase = .forward;
                        return .{ .request = .{ .desc = identity_worker } };
                    }
                }

                frame.outer_env = context.env;
                // The descriptor describes the complete backing-shape chain, so
                // every nominal on it binds its formals, outermost first.
                var shape_worker: ?Plan.TypeRepId = identity_worker;
                var shape_source = identity_source;
                while (shape_worker) |current_worker| : ({
                    shape_worker = self.descriptorBackingShapeRep(current_worker);
                    shape_source = if (shape_source) |current_source| self.descriptorBackingShapeRep(current_source) else null;
                }) {
                    const current_rep = self.plan.representations.items[@backingInt(current_worker)];
                    if (current_rep.nominal_backing_arg_substitutions.len == 0) continue;
                    const level_env = context.env;
                    var substitutions = self.plan.nominalBackingSubstitutions(current_rep.nominal_backing_arg_substitutions);
                    var bindings = std.ArrayList(StaticDescInstantiationContext.Binding).empty;
                    defer bindings.deinit(self.allocator);
                    while (substitutions.next()) |substitution| {
                        const formal_rep = substitution.formal_rep orelse continue;
                        const formal = self.plan.representations.items[@backingInt(formal_rep)];
                        if (formal.descriptor == null) continue;
                        const actual_source = if (shape_source) |source| blk: {
                            const source_rep = self.plan.representations.items[@backingInt(source)];
                            break :blk self.plan.nominalBackingActual(source_rep.nominal_backing_arg_substitutions, substitution.arg_index);
                        } else null;
                        if (formal_rep == substitution.actual_rep and
                            (actual_source == null or actual_source == formal_rep)) continue;
                        var binding = StaticDescInstantiationContext.Binding{
                            .formal = formal_rep,
                            .actual = substitution.actual_rep,
                            .source = actual_source,
                            .env = level_env,
                        };
                        // A formal forwarded from an enclosing nominal retains
                        // that nominal's environment, rather than referring to
                        // this new scope.
                        while (context.bound(binding.actual)) |forwarded| {
                            binding.actual = forwarded.actual;
                            binding.source = forwarded.source;
                            binding.env = forwarded.env;
                            context.env = forwarded.env;
                        }
                        context.env = level_env;
                        if (!self.plan.representations.items[@backingInt(binding.actual)].contains_dynamic) binding.env = 0;
                        try bindings.append(self.allocator, binding);
                    }
                    for (bindings.items) |binding| try context.bind(self.allocator, binding);
                }

                if (context.get(identity_worker, identity_source)) |existing| {
                    context.env = frame.outer_env;
                    return .{ .done = .{ .desc = existing } };
                }

                frame.worker = identity_worker;
                frame.source = identity_source;
                frame.desc_id = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.boxy_type_descs.items.len))));
                try context.put(self.allocator, identity_worker, identity_source, frame.desc_id);
                try self.result.boxy_type_descs.append(self.allocator, reserved_boxy_type_desc);

                const rep_layout = self.layout_plan.rep_layouts[@backingInt(identity_worker)];
                frame.payload_layout = rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
                frame.phase = .nested;
                return .{ .request = .{ .nested_descs = .{
                    .worker = identity_worker,
                    .source = identity_source,
                    .mapping = mapping,
                } } };
            },
            .redirect => {
                context.env = frame.outer_env;
                return .{ .done = delivered.? };
            },
            .forward => return .{ .done = delivered.? },
            .nested => {
                frame.nested_descs = staticValueSpan(delivered.?);
                frame.phase = .variants;
                return .{ .request = .{ .tag_variants = .{
                    .position = .{ .worker = frame.worker, .source = frame.source, .mapping = mapping },
                    .payload_layout = frame.payload_layout,
                } } };
            },
            .variants => {
                frame.tag_variants = staticValueSpan(delivered.?);
                frame.phase = .ext;
                return .{ .request = .{ .tag_ext = .{ .worker = frame.worker, .source = frame.source, .mapping = mapping } } };
            },
            .ext => {
                frame.tag_ext_desc = staticValueRef(delivered.?);
                // The described nominal's type arguments belong to its
                // enclosing scope, not to the backing scope bound above.
                context.env = frame.outer_env;
                frame.field_names = try self.staticFieldNamesForRep(frame.worker);
                frame.phase = .inspect_method;
                return .{ .request = .{ .inspect_slot = .{ .rep = frame.source orelse frame.worker, .kind = descriptor_method_kinds[frame.method_index] } } };
            },
            .inspect_method => {
                frame.methods[frame.method_index].method = switch (delivered.?) {
                    .slot_id => |slot| slot,
                    .desc, .ref, .dict, .span, .method_slot, .adapter => boxyLowerInvariant("descriptor inspect slot request delivered a non-slot value"),
                };
                frame.phase = .inspect_hidden;
                return .{ .request = .{ .inspect_hidden = if (frame.source) |source_rep|
                    .{ .kind = descriptor_method_kinds[frame.method_index], .rep = source_rep, .self_desc = frame.desc_id }
                else
                    .{ .kind = descriptor_method_kinds[frame.method_index], .rep = frame.worker, .self_desc = frame.desc_id, .mapping = mapping } } };
            },
            .inspect_hidden => {
                frame.methods[frame.method_index].hidden = staticValueSpan(delivered.?);
                frame.phase = .inspect_arg;
                return .{ .request = .{ .inspect_arg = if (frame.source) |source_rep|
                    .{ .kind = descriptor_method_kinds[frame.method_index], .rep = source_rep, .self_desc = frame.desc_id, .building_worker_rep = frame.worker }
                else
                    .{ .kind = descriptor_method_kinds[frame.method_index], .rep = frame.worker, .self_desc = frame.desc_id, .building_worker_rep = frame.worker, .mapping = mapping } } };
            },
            .inspect_arg => {
                frame.methods[frame.method_index].args = staticValueSpan(delivered.?);
                frame.phase = .inspect_dict;
                return .{ .request = .{ .method_dicts = .{ .rep = frame.source orelse frame.worker, .kind = descriptor_method_kinds[frame.method_index] } } };
            },
            .inspect_dict => {
                frame.methods[frame.method_index].dictionaries = staticValueSpan(delivered.?);
                frame.method_index += 1;
                if (frame.method_index < descriptor_method_kinds.len) {
                    frame.phase = .inspect_method;
                    return .{ .request = .{ .inspect_slot = .{ .rep = frame.source orelse frame.worker, .kind = descriptor_method_kinds[frame.method_index] } } };
                }
                const worker_rep = self.plan.representations.items[@backingInt(frame.worker)];
                const layout_value = self.result.layouts.getLayout(frame.payload_layout);
                self.result.boxy_type_descs.items[@backingInt(frame.desc_id)] = .{
                    .payload_layout = frame.payload_layout,
                    .contains_refcounted = self.result.layouts.layoutContainsRefcounted(layout_value) or worker_rep.contains_dynamic,
                    .shape = self.descriptorShapeForRep(frame.worker),
                    .nested_descs = frame.nested_descs,
                    .tag_variants = frame.tag_variants,
                    .tag_ext_desc = frame.tag_ext_desc,
                    .field_names = frame.field_names,
                    .inspect_opaque = self.repInspectsOpaque(frame.worker),
                    .inspect_method = frame.methods[0].method,
                    .inspect_hidden_descs = frame.methods[0].hidden,
                    .inspect_arg_descs = frame.methods[0].args,
                    .eq_method = frame.methods[1].method,
                    .eq_hidden_descs = frame.methods[1].hidden,
                    .eq_arg_descs = frame.methods[1].args,
                    .eq_nested_dicts = frame.methods[1].dictionaries,
                    .hash_method = frame.methods[2].method,
                    .hash_hidden_descs = frame.methods[2].hidden,
                    .hash_arg_descs = frame.methods[2].args,
                    .hash_nested_dicts = frame.methods[2].dictionaries,
                    .presence_slot_present_discriminant = worker_rep.presence_slot_present_discriminant,
                    .eq_rejected = self.plan.descriptorMethodRejected(frame.source orelse frame.worker, .equality),
                    .hash_rejected = self.plan.descriptorMethodRejected(frame.source orelse frame.worker, .hash),
                    .is_bool = self.repDescribesBool(frame.worker),
                    .debug_checked_type = worker_rep.source_type.ty,
                };
                return .{ .done = .{ .desc = frame.desc_id } };
            },
        }
    }

    fn stepStaticNestedDescs(self: *ProcedureBuilder, frame: *StaticNestedDescsFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.refs.append(self.allocator, staticValueRef(value) orelse
                boxyLowerInvariant("nested descriptor request delivered no descriptor"));
        } else {
            frame.started = true;
            // A backing-shape wrapper's positions are its backing's.
            while (self.descriptorBackingShapeRep(frame.position.worker)) |worker_backing| {
                frame.position.worker = worker_backing;
                if (frame.position.mapping != null) {
                    frame.position.source = if (frame.position.source) |source|
                        self.descriptorBackingShapeRep(source) orelse source
                    else
                        null;
                }
            }
            const worker_rep = self.plan.representations.items[@backingInt(frame.position.worker)];
            if (try self.staticGeneratedEvidenceNestedDescRefs(worker_rep.kind)) |nested_descs| {
                return .{ .done = .{ .span = nested_descs } };
            }
            if (frame.position.mapping != null) {
                if (frame.position.source) |source| {
                    frame.source_children = self.plan.childSlice(self.plan.representations.items[@backingInt(source)].children);
                }
            }
            try self.appendNestedDescriptorSlots(frame.position.worker, self.descriptorPayloadLayoutForRep(frame.position.worker), &frame.slots);
            if (frame.slots.items.len == 0) return .{ .done = .{ .span = .{} } };
        }
        if (frame.refs.items.len < frame.slots.items.len) {
            const slot = frame.slots.items[frame.refs.items.len];
            const slot_source = if (frame.position.mapping == null)
                null
            else if (slot.declared_field) |field|
                try self.matchingDeclaredFieldInstantiationSource(frame.position.source, field)
            else
                try self.matchingInstantiationSource(frame.source_children, slot.child.?);
            return .{ .request = staticPositionDescRequest(self.nestedDescriptorSlotDescRep(slot), slot_source, frame.position.mapping) };
        }
        const start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.appendSlice(self.allocator, frame.refs.items);
        return .{ .done = .{ .span = .{ .start = start, .len = @intCast(frame.refs.items.len) } } };
    }

    /// The request for a tag position's extension descriptor, or null when
    /// it has none.
    fn staticTagExtRequest(self: *ProcedureBuilder, position: StaticDescPosition) Allocator.Error!?StaticRequest {
        const tag_rep_id = self.tagVariantRepForDesc(position.worker);
        const tag_rep = self.plan.representations.items[@backingInt(tag_rep_id)];
        if (tag_rep.kind == .bool_tag_union) return null;
        const mapping = position.mapping orelse {
            if (tag_rep.tag_variants.len == 0 and tag_rep.kind != .tag_union and tag_rep.kind != .dynamic) return null;
            var found: ?Plan.TypeRepId = null;
            for (self.plan.childSlice(tag_rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                if (found != null) boxyLowerInvariant("boxy tag representation had duplicate row extension children");
                found = child.rep;
            }
            const ext_rep_id = found orelse return null;
            if (ext_rep_id == tag_rep_id) return null;
            if (self.plan.representations.items[@backingInt(ext_rep_id)].kind == .empty_tag_union) return null;
            return .{ .desc = ext_rep_id };
        };
        if (tag_rep.children.len == 0) return null;

        var worker_ext: ?Plan.RepChild = null;
        for (self.plan.childSlice(tag_rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            if (worker_ext != null) boxyLowerInvariant("boxy descriptor saw duplicate tag extension children");
            worker_ext = child;
        }
        const ext_child = worker_ext orelse return null;
        const ext_rep_id = ext_child.rep;
        if (ext_rep_id == tag_rep_id) return null;
        if (self.plan.representations.items[@backingInt(ext_rep_id)].kind == .empty_tag_union) return null;

        const source_ext = if (position.source) |source| blk: {
            const source_tag_rep_id = self.tagVariantRepForDesc(source);
            const source_children = self.plan.childSlice(self.plan.representations.items[@backingInt(source_tag_rep_id)].children);
            break :blk try self.matchingInstantiationSource(source_children, ext_child);
        } else null;
        return .{ .source_desc_ref = .{ .worker = ext_rep_id, .source = source_ext, .mapping = mapping } };
    }

    /// The payloads of the source variant matching `variant`.
    fn staticSourceVariantPayloads(
        self: *ProcedureBuilder,
        frame: *const StaticTagVariantsFrame,
        variant: Plan.TagVariant,
    ) []const Plan.RepChild {
        if (frame.source_tag == null) return &.{};
        const source_variant = self.findMatchingTagVariant(frame.source_variants, variant) orelse return &.{};
        return self.plan.childSlice(source_variant.payloads);
    }

    fn stepStaticTagVariants(self: *ProcedureBuilder, frame: *StaticTagVariantsFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        const mapping = frame.request.position.mapping;
        switch (frame.phase) {
            .start => {
                frame.worker_tag = self.tagVariantRepForDesc(frame.request.position.worker);
                if (mapping != null) {
                    if (frame.request.position.source) |source| frame.source_tag = self.tagVariantRepForDesc(source);
                }
                if (frame.source_tag) |source_tag| {
                    frame.source_variants = self.plan.tagVariantSlice(self.plan.representations.items[@backingInt(source_tag)].tag_variants);
                }
                const worker_tag_rep = self.plan.representations.items[@backingInt(frame.worker_tag)];
                const layout_value = self.result.layouts.getLayout(frame.request.payload_layout);
                if (layout_value.tag == .zst) {
                    const variants = self.plan.tagVariantSlice(worker_tag_rep.tag_variants);
                    if (variants.len == 0) return .{ .done = .{ .span = .{} } };
                    if (variants.len != 1) {
                        if (mapping == null) boxyLowerInvariant("zero-sized boxy tag descriptor had multiple variants");
                        boxyLowerInvariant("zero-sized source-mapped boxy tag descriptor had multiple variants");
                    }
                    frame.variants = variants;
                    frame.phase = .zst_payloads;
                    // The payload descriptors are built before this variant's
                    // slot is reserved: they can append nested descriptors'
                    // variants to the same pool.
                    return .{ .request = .{ .payload_descs = .{
                        .payloads = self.plan.childSlice(variants[0].payloads),
                        .source_payloads = self.staticSourceVariantPayloads(frame, variants[0]),
                        .payload_layout = .zst,
                        .mapping = mapping,
                    } } };
                }
                const tag_layout = if (layout_value.tag == .tag_union)
                    layout_value
                else if (layout_value.tag == .box)
                    self.result.layouts.getLayout(layout_value.getIdx())
                else
                    return .{ .done = .{ .span = .{} } };
                if (tag_layout.tag != .tag_union) return .{ .done = .{ .span = .{} } };

                if (worker_tag_rep.kind == .bool_tag_union) {
                    const tag_info = self.result.layouts.getTagUnionInfo(tag_layout);
                    if (tag_info.variants.len != 2) {
                        boxyLowerInvariant("Bool descriptor variant count disagreed with identity layout");
                    }
                    if (tag_info.variants.get(0).payload_layout != .zst or tag_info.variants.get(1).payload_layout != .zst) {
                        boxyLowerInvariant("Bool descriptor payload layout disagreed with identity layout");
                    }

                    const start: u32 = @intCast(self.result.boxy_tag_variants.items.len);
                    try self.result.boxy_tag_variants.appendSlice(self.allocator, &.{
                        .{
                            .name = try self.result.store.insertBoxyName("False"),
                            .discriminant = 0,
                            .payload_count = 0,
                            .payload_layout = .zst,
                            .payload_descs = .{},
                        },
                        .{
                            .name = try self.result.store.insertBoxyName("True"),
                            .discriminant = 1,
                            .payload_count = 0,
                            .payload_layout = .zst,
                            .payload_descs = .{},
                        },
                    });
                    return .{ .done = .{ .span = .{ .start = start, .len = 2 } } };
                }

                frame.variants = self.plan.tagVariantSlice(worker_tag_rep.tag_variants);
                if (frame.variants.len == 0) return .{ .done = .{ .span = .{} } };
                frame.phase = .has_ext;
                return .{ .request = .{ .tag_ext = .{
                    .worker = frame.worker_tag,
                    .source = frame.source_tag,
                    .mapping = mapping,
                } } };
            },
            .zst_payloads => {
                const variant = frame.variants[0];
                const name = try self.result.store.insertBoxyName(self.tagVariantNameText(variant));
                const start: u32 = @intCast(self.result.boxy_tag_variants.items.len);
                try self.result.boxy_tag_variants.append(self.allocator, .{
                    .name = name,
                    .discriminant = 0,
                    .payload_count = @intCast(self.plan.childSlice(variant.payloads).len),
                    .payload_layout = .zst,
                    .payload_descs = staticValueSpan(delivered.?),
                });
                return .{ .done = .{ .span = .{ .start = start, .len = 1 } } };
            },
            .has_ext => {
                const has_ext = staticValueRef(delivered.?) != null;
                const tag_info = self.result.layouts.getTagUnionInfo(self.staticTagVariantsTagLayout(frame));
                const expected_layout_variants = frame.variants.len + @intFromBool(has_ext);
                if (tag_info.variants.len != expected_layout_variants) {
                    boxyLowerInvariant("boxy tag descriptor variant count disagreed with committed layout");
                }
            },
            .variant_payloads => {
                const index = frame.index;
                const variant = frame.variants[index];
                const tag_info = self.result.layouts.getTagUnionInfo(self.staticTagVariantsTagLayout(frame));
                const payload_descs = staticValueSpan(delivered.?);
                try frame.entries.append(self.allocator, .{
                    .name = if (mapping != null) frame.name else try self.result.store.insertBoxyName(self.tagVariantNameText(variant)),
                    .discriminant = @intCast(index),
                    .payload_count = @intCast(self.plan.childSlice(variant.payloads).len),
                    .payload_layout = tag_info.variants.get(index).payload_layout,
                    .payload_descs = payload_descs,
                });
                frame.index += 1;
            },
        }
        if (frame.index < frame.variants.len) {
            const variant = frame.variants[frame.index];
            const tag_info = self.result.layouts.getTagUnionInfo(self.staticTagVariantsTagLayout(frame));
            if (mapping != null) frame.name = try self.result.store.insertBoxyName(self.tagVariantNameText(variant));
            frame.phase = .variant_payloads;
            return .{ .request = .{ .payload_descs = .{
                .payloads = self.plan.childSlice(variant.payloads),
                .source_payloads = self.staticSourceVariantPayloads(frame, variant),
                .payload_layout = tag_info.variants.get(frame.index).payload_layout,
                .mapping = mapping,
            } } };
        }
        const start: u32 = @intCast(self.result.boxy_tag_variants.items.len);
        try self.result.boxy_tag_variants.appendSlice(self.allocator, frame.entries.items);
        return .{ .done = .{ .span = .{ .start = start, .len = @intCast(frame.entries.items.len) } } };
    }

    fn staticTagVariantsTagLayout(self: *ProcedureBuilder, frame: *const StaticTagVariantsFrame) layout.Layout {
        const layout_value = self.result.layouts.getLayout(frame.request.payload_layout);
        return if (layout_value.tag == .box) self.result.layouts.getLayout(layout_value.getIdx()) else layout_value;
    }

    fn stepStaticPayloadDescs(self: *ProcedureBuilder, frame: *StaticPayloadDescsFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.descs.append(self.allocator, .{
                .payload_index = frame.pending_index,
                .desc = staticValueRef(value) orelse boxyLowerInvariant("tag payload descriptor request delivered no descriptor"),
            });
        }
        const payloads = frame.request.payloads;
        while (frame.index < payloads.len) {
            const index = frame.index;
            frame.index += 1;
            const child = payloads[index];
            const field_layout = self.tagVariantPayloadFieldLayout(frame.request.payload_layout, index, payloads.len);
            // Payload descriptors are forced even for concrete payloads: a
            // static descriptor can describe a value that flows into a worker
            // whose own view of the payload is erased, and such a worker reads
            // tag payloads through the descriptor it was handed.
            const desc_rep = self.tagPayloadStorageDescRepForLayout(child.rep, field_layout, true) orelse continue;
            frame.pending_index = @intCast(index);
            const source_child = if (frame.request.mapping != null)
                self.matchingTagPayloadInstantiationSource(frame.request.source_payloads, child)
            else
                null;
            return .{ .request = staticPositionDescRequest(desc_rep, source_child, frame.request.mapping) };
        }
        if (frame.descs.items.len == 0) return .{ .done = .{ .span = .{} } };
        const start: u32 = @intCast(self.result.boxy_tag_payload_descs.items.len);
        try self.result.boxy_tag_payload_descs.appendSlice(self.allocator, frame.descs.items);
        return .{ .done = .{ .span = .{ .start = start, .len = @intCast(frame.descs.items.len) } } };
    }

    /// The planned inspect worker's hidden descriptors for the request's
    /// representation, built statically; a mapping instantiates a worker
    /// representation whose descriptor sources an enclosing dictionary
    /// method planned.
    fn stepStaticDescriptorMethodHidden(self: *ProcedureBuilder, frame: *StaticDescriptorMethodHiddenFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.refs.append(self.allocator, staticValueRef(value) orelse
                boxyLowerInvariant("inspect hidden descriptor request delivered no descriptor"));
        } else {
            frame.started = true;
            const inspect = self.plan.descriptorMethodForRep(frame.request.rep, frame.request.kind) orelse return .{ .done = .{ .span = .{} } };
            if (inspect.hidden_desc_args.len == 0) return .{ .done = .{ .span = .{} } };
            frame.hidden_desc_args = inspect.hidden_desc_args;
        }
        const args = self.plan.directCallHiddenDescriptorArgSlice(frame.hidden_desc_args);
        const identity_rep = self.descriptorIdentityRep(frame.request.rep);
        while (frame.refs.items.len < args.len) {
            const arg = args[frame.refs.items.len];
            // The whole inspected value is described by the descriptor under
            // construction.
            if (self.descriptorIdentityRep(arg.rep) == identity_rep) {
                try frame.refs.append(self.allocator, .{ .static = frame.request.self_desc });
                continue;
            }
            return .{ .request = staticPositionDescRequest(arg.rep, null, frame.request.mapping) };
        }
        return .{ .done = .{ .span = try self.appendStaticHiddenDescRefs(frame.refs.items) } };
    }

    /// The inspected value's descriptor in the inspect worker's parameter
    /// storage: the worker parameter instantiated by the planned hidden
    /// descriptor arguments.
    fn stepStaticDescriptorMethodArg(self: *ProcedureBuilder, frame: *StaticDescriptorMethodArgFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            const ref = staticValueRef(value) orelse boxyLowerInvariant("inspect argument descriptor request delivered no descriptor");
            return .{ .done = .{ .span = try self.appendDescriptorMethodArgRefs(self.plan.descriptorMethodForRep(frame.request.rep, frame.request.kind).?, ref) } };
        }
        const rep_id = frame.request.rep;
        const inspect = self.plan.descriptorMethodForRep(rep_id, frame.request.kind) orelse return .{ .done = .{ .span = .{} } };
        // A descriptor already built as the worker parameter's instantiation
        // describes the value in that parameter's storage.
        const is_worker_instantiation = if (frame.request.building_worker_rep) |building|
            self.descriptorIdentityRep(building) == self.descriptorIdentityRep(self.descriptorMethodWorkerArgRep(inspect))
        else
            false;
        if (is_worker_instantiation or self.descriptorMethodArgumentIsIdentity(inspect)) {
            return .{ .done = .{ .span = try self.appendDescriptorMethodArgRefs(inspect, .{ .static = frame.request.self_desc }) } };
        }
        const worker_arg = self.descriptorMethodWorkerArgRep(inspect);
        // The worker parameter's own structure is instantiated at the
        // descriptors of its type parameters.
        for (self.plan.directCallHiddenDescriptorArgSlice(inspect.hidden_desc_args)) |arg| {
            const worker_param = self.plan.representations.items[@backingInt(self.descriptorIdentityRep(arg.worker_rep))];
            if (worker_param.kind != .dynamic or worker_param.children.len != 0 or worker_param.tag_variants.len != 0) continue;
            const source_rep = if (frame.request.mapping) |mapping|
                mapping.sources.get(self.plan.representations.items[@backingInt(arg.rep)].descriptor orelse arg.worker_desc) orelse arg.rep
            else
                arg.rep;
            try frame.arg_sources.put(self.allocator, arg.worker_desc, source_rep);
        }
        return .{ .request = .{ .source_desc_ref = .{
            .worker = worker_arg,
            .source = null,
            .mapping = .{
                .sources = &frame.arg_sources,
                .context = if (frame.request.mapping) |mapping| mapping.context else &frame.local_context,
            },
        } } };
    }

    fn stepStaticDescriptorMethodSlot(self: *ProcedureBuilder, frame: *StaticDescriptorMethodSlotFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.nested_dict_refs.append(self.allocator, .{ .static = staticValueDict(value) });
        } else {
            const inspect = self.plan.descriptorMethodForRep(frame.rep, frame.kind) orelse return .{ .done = .{ .slot_id = null } };
            for (self.descriptor_method_slot_cache.items) |entry| {
                if (entry.worker == inspect.worker) return .{ .done = .{ .slot_id = entry.slot } };
            }
            const method_view = procedureModuleById(self.modules, inspect.method_module);
            if (!std.mem.eql(u8, method_view.canonical_names.methodNameText(inspect.method), switch (frame.kind) {
                .inspect => "to_inspect",
                .equality => "is_eq",
                .hash => "to_hash",
            })) {
                boxyLowerInvariant("planned boxy inspect method had an unexpected checked method identity");
            }

            frame.inspect = inspect;
            frame.slot_id = @fromBackingInt(@as(u32, @intCast(self.result.boxy_method_slots.items.len)));
            try self.descriptor_method_slot_cache.append(self.allocator, .{
                .worker = inspect.worker,
                .slot = frame.slot_id,
            });
            try self.result.boxy_method_slots.append(self.allocator, .{
                .method = inspect.method,
                .proc = undefined,
            });
        }
        const inspect = frame.inspect.?;
        const worker = self.plan.workers.items[@backingInt(inspect.worker)];
        const hidden_dict_args: []const Plan.DirectCallHiddenDictionaryArg = if (frame.kind == .inspect) self.plan.directCallHiddenDictionaryArgSlice(inspect.hidden_dict_args) else &.{};
        while (frame.nested_dict_refs.items.len < hidden_dict_args.len) {
            const arg = hidden_dict_args[frame.nested_dict_refs.items.len];
            const source_rep = switch (arg.source) {
                .static_rep => |source_rep| source_rep,
                .bound_dictionaries => boxyLowerInvariant("boxy inspect slot received a caller-bound dictionary source"),
                // A slot is called from no frame, so each literal the worker
                // converts is closed at the described representation.
                .literal => |literal| switch (literal) {
                    .result => |index| {
                        try frame.nested_dict_refs.append(self.allocator, .{ .static = try self.emitLiteralAccessor(index) });
                        continue;
                    },
                    .parameter => boxyLowerInvariant("boxy inspect slot received an open literal argument"),
                },
            };
            return .{ .request = .{ .dict = .{
                .rep = source_rep,
                .worker_dictionaries = arg.worker_dictionaries,
                .method_evidence = arg.method_evidence,
                .template = null,
                .env = arg.env,
            } } };
        }

        // The inspected descriptor supplies the argument descriptor and the
        // worker's hidden descriptors (`inspect_arg_descs`,
        // `inspect_hidden_descs`), so the shared slot names only their order.
        const worker_layout = self.layout_plan.workerLayoutFor(inspect.worker);
        const worker_args = self.layout_plan.workerLayoutSlice(worker_layout.args);
        if (worker_args.len != frame.kind.argCount()) boxyLowerInvariant("boxy inspect worker did not take exactly one argument");
        const arg_layouts_start: u32 = @intCast(self.result.boxy_method_arg_layouts.items.len);
        for (worker_args) |arg| try self.result.boxy_method_arg_layouts.append(self.allocator, arg.layoutIdx());
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        const hidden_sources_start: u32 = @intCast(self.result.boxy_method_hidden_desc_sources.items.len);
        for (0..params.len) |slot_index| {
            try self.result.boxy_method_hidden_desc_sources.append(self.allocator, .{ .slot = @intCast(slot_index) });
        }

        const ret_rep: ?Plan.TypeRepId = if (inspect.ret_type) |ty|
            self.plan.repForSourceType(ty) orelse boxyLowerInvariant("descriptor method result type was not analyzed")
        else
            null;
        const ret_desc = if (ret_rep) |rep| try self.staticDescRefForRep(rep) else null;
        const slot = LirProgram.BoxyMethodSlot{
            .method = inspect.method,
            .proc = try self.reserveWorkerProc(inspect.worker),
            .nested_dicts = try self.appendStaticHiddenDictRefs(frame.nested_dict_refs.items),
            .adapter = .{
                .arg_layouts = .{ .start = arg_layouts_start, .len = frame.kind.argCount() },
                .hidden_desc_sources = .{ .start = hidden_sources_start, .len = @intCast(params.len) },
                .ret_layout = if (ret_rep) |rep| self.layout_plan.rep_layouts[@backingInt(rep)].worker.layoutIdx() else null,
                .ret_desc = ret_desc,
            },
        };
        self.result.boxy_method_slots.items[@backingInt(frame.slot_id)] = slot;
        return .{ .done = .{ .slot_id = frame.slot_id } };
    }

    fn stepStaticDict(self: *ProcedureBuilder, frame: *StaticDictFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        switch (frame.phase) {
            .start => {
                const request = frame.request;
                frame.dict_id = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.boxy_dicts.items.len))));
                if (request.template) |outer| {
                    frame.own_template = .{ .frame = outer.frame };
                    try outer.frame.template_dict_cache.append(self.allocator, .{
                        .source_rep = request.rep,
                        .worker_dictionaries = request.worker_dictionaries,
                        .method_evidence = request.method_evidence,
                        .env = request.env,
                        .dict = frame.dict_id,
                        .captures = &.{},
                    });
                } else {
                    try self.static_dict_cache.append(self.allocator, .{
                        .source_rep = request.rep,
                        .worker_dictionaries = request.worker_dictionaries,
                        .method_evidence = request.method_evidence,
                        .env = request.env,
                        .dict = frame.dict_id,
                    });
                }
                try self.result.boxy_dicts.append(self.allocator, .{});

                const requirements = self.plan.dictionarySlice(request.worker_dictionaries);
                const exact_methods = self.plan.dictionaryMethodEvidenceSlice(request.method_evidence);
                if (exact_methods.len != 0 and exact_methods.len != requirements.len) {
                    boxyLowerInvariant("static dictionary checked evidence did not cover every method slot");
                }
                try frame.slots.appendNTimes(self.allocator, .{
                    .present = false,
                    .method = undefined,
                    .proc = undefined,
                }, self.plan.dictionary_method_slots.items.len);
            },
            .structural => frame.slots.items[frame.slot_index] = switch (delivered.?) {
                .method_slot => |slot| slot,
                .desc, .ref, .dict, .slot_id, .span, .adapter => boxyLowerInvariant("structural dictionary slot request delivered a non-slot value"),
            },
            .hidden_descs => return try self.stepStaticDictHiddenDescs(frame, delivered),
            .nested_dicts => return try self.stepStaticDictNestedDicts(frame, delivered),
            .adapter => {
                const adapter = switch (delivered.?) {
                    .adapter => |adapter| adapter,
                    .desc, .ref, .dict, .slot_id, .span, .method_slot => boxyLowerInvariant("dictionary method adapter request delivered a non-adapter value"),
                };
                frame.slots.items[frame.slot_index] = .{
                    .method = frame.requirement.fn_name,
                    .proc = frame.method_proc,
                    .hidden_descs = try self.appendStaticHiddenDescRefs(frame.hidden_desc_refs.items),
                    .nested_dicts = try self.appendStaticHiddenDictRefs(frame.nested_dict_refs.items),
                    .adapter = adapter,
                };
            },
        }
        return try self.beginStaticDictSlot(frame);
    }

    /// Begin the dictionary's next method slot, or finish the dictionary
    /// once every slot is built.
    fn beginStaticDictSlot(self: *ProcedureBuilder, frame: *StaticDictFrame) Allocator.Error!StaticStep {
        const rep_id = frame.request.rep;
        const requirements = self.plan.dictionarySlice(frame.request.worker_dictionaries);
        const exact_methods = self.plan.dictionaryMethodEvidenceSlice(frame.request.method_evidence);
        while (frame.method_index < requirements.len) {
            const method_index = frame.method_index;
            frame.method_index += 1;
            const requirement = requirements[method_index];
            const slot_index: usize = requirement.slot;
            if (slot_index >= frame.slots.items.len) {
                boxyLowerInvariant("planned dictionary method slot exceeded the program-wide slot table");
            }
            if (frame.slots.items[slot_index].present) {
                boxyLowerInvariant("one static dictionary supplied the same program-wide method slot twice");
            }
            const exact_method: ?Plan.DictionaryMethodEvidence = if (exact_methods.len == 0) null else exact_methods[method_index];
            const structural_kind: ?static_dispatch.StructuralKind = if (exact_method) |method|
                if (method.resolution == .structural) method.resolution.structural else null
            else
                null;
            const fn_type = if (exact_method) |method| method.callable_type else requirement.fn_ty;
            const structural_method: ?Plan.DerivedMethod = if (structural_kind == .equality or
                (exact_method == null and self.staticDictionarySlotIsStructural(base.Ident.IS_EQ_METHOD_NAME, rep_id, requirement)))
                .equality
            else if (structural_kind == .hash or
                (exact_method == null and self.staticDictionarySlotIsStructural(base.Ident.TO_HASH_METHOD_NAME, rep_id, requirement)))
                .hash
            else
                null;
            if (structural_method) |method| {
                frame.slot_index = slot_index;
                frame.phase = .structural;
                return .{ .request = .{ .structural_slot = .{
                    .rep = rep_id,
                    .requirement = requirement,
                    .fn_type = fn_type,
                    .method = method,
                    .template = frame.slotTemplate(),
                    .env = frame.request.env,
                } } };
            }
            if (exact_method) |method| {
                const crash: ?CrashingDictionaryMethod = switch (method.resolution) {
                    .checked_error => .checked_error,
                    .unreachable_value => .unreachable_value,
                    .worker, .structural, .constraint, .builtin_numeral => null,
                };
                if (crash) |kind| {
                    frame.slots.items[slot_index] = try self.crashingDictionaryMethodSlot(requirement, method.requirement_type, kind);
                    continue;
                }
            }
            const resolved = if (exact_method) |method| switch (method.resolution) {
                .worker => |worker| worker,
                .structural => boxyLowerInvariant("unsupported structural dictionary method reached boxy lowering"),
                .constraint => boxyLowerInvariant("forwarded dictionary evidence reached static dictionary lowering"),
                .builtin_numeral => boxyLowerInvariant("compile-time numeral proof reached a runtime dictionary"),
                .checked_error, .unreachable_value => unreachable,
            } else self.methodWorkerForStaticDictionary(rep_id, requirement) orelse
                boxyLowerInvariant("static boxy dictionary method target was not planned");

            frame.resetSlot(self.allocator);
            frame.requirement = requirement;
            frame.slot_index = slot_index;
            frame.exact_method = exact_method;
            frame.resolved = resolved;
            frame.fn_type = fn_type;
            if (exact_method) |method| {
                try self.collectPlannedStaticDescriptorSources(resolved, method.worker_desc_args, &frame.descriptor_sources);
            } else {
                try self.collectStaticDictionaryDescriptorSources(
                    resolved,
                    rep_id,
                    self.plan.representations.items[@backingInt(rep_id)].source_type,
                    fn_type,
                    &frame.descriptor_sources,
                );
            }
            frame.phase = .hidden_descs;
            return try self.stepStaticDictHiddenDescs(frame, null);
        }

        const method_start: u32 = @intCast(self.result.boxy_method_slots.items.len);
        try self.result.boxy_method_slots.appendSlice(self.allocator, frame.slots.items);
        self.result.boxy_dicts.items[@backingInt(frame.dict_id)] = .{
            .method_slots = .{
                .start = method_start,
                .len = @intCast(frame.slots.items.len),
            },
            .template = frame.request.template != null,
        };
        if (frame.request.template) |outer| {
            const own = &frame.own_template.?;
            for (outer.frame.template_dict_cache.items) |*entry| {
                if (entry.dict != frame.dict_id) continue;
                entry.captures = try self.allocator.dupe(LIR.LocalId, own.captures.items);
            }
            for (own.captures.items) |local| try outer.capture(self.allocator, local);
        }
        return .{ .done = .{ .dict = frame.dict_id } };
    }

    /// The method worker's hidden descriptors, one per step.
    fn stepStaticDictHiddenDescs(self: *ProcedureBuilder, frame: *StaticDictFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.hidden_desc_refs.append(self.allocator, staticValueRef(value) orelse
                boxyLowerInvariant("dictionary hidden descriptor request delivered no descriptor"));
        }
        const worker = self.plan.workers.items[@backingInt(frame.resolved)];
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        const mapping = StaticSourceMapping{ .sources = &frame.descriptor_sources, .context = &frame.desc_context };
        if (frame.exact_method) |method| {
            const sources = self.plan.dictionaryMethodHiddenDescriptorSourceSlice(method.hidden_desc_sources);
            if (params.len != sources.len) {
                boxyLowerInvariant("planned static dictionary hidden descriptor sources did not cover every worker descriptor");
            }
            while (frame.item < params.len) {
                const param = params[frame.item];
                const source = sources[frame.item];
                frame.item += 1;
                switch (source) {
                    .argument, .call => {},
                    .slot => |slot| {
                        if (slot != frame.hidden_desc_refs.items.len) {
                            boxyLowerInvariant("planned static dictionary descriptor slot order was not contiguous");
                        }
                        if (frame.slotTemplate()) |frame_template| {
                            const source_rep = frame.descriptor_sources.get(param.desc) orelse
                                boxyLowerInvariant("planned static dictionary descriptor slot had no source representation");
                            if (try frame_template.frame.repDescriptorNeedsFrame(source_rep)) {
                                const materialization = try frame_template.frame.descriptorMaterializationForSourceRep(source_rep);
                                if (materialization.desc.localOrNull()) |local| try frame_template.capture(self.allocator, local);
                                try frame_template.captureSpan(self.allocator, materialization.captures);
                                try frame.hidden_desc_refs.append(self.allocator, materialization.desc);
                                continue;
                            }
                        }
                        return .{ .request = .{ .source_desc_ref = .{ .worker = param.rep, .source = null, .mapping = mapping } } };
                    },
                }
            }
            if (worker.hidden_dicts.len != method.nested_dict_args.len) {
                boxyLowerInvariant("planned dictionary method nested evidence did not cover every hidden dictionary");
            }
        } else if (frame.item < params.len) {
            const param = params[frame.item];
            frame.item += 1;
            return .{ .request = .{ .source_desc_ref = .{ .worker = param.rep, .source = null, .mapping = mapping } } };
        }
        frame.item = 0;
        frame.phase = .nested_dicts;
        return try self.stepStaticDictNestedDicts(frame, null);
    }

    /// The method worker's hidden dictionaries, one per step, then the
    /// slot's method procedure and adapter.
    fn stepStaticDictNestedDicts(self: *ProcedureBuilder, frame: *StaticDictFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.nested_dict_refs.append(self.allocator, .{ .static = staticValueDict(value) });
        }
        const slot_template = frame.slotTemplate();
        if (frame.exact_method) |method| {
            const args = self.plan.directCallHiddenDictionaryArgSlice(method.nested_dict_args);
            while (frame.item < args.len) {
                const arg = args[frame.item];
                frame.item += 1;
                switch (arg.source) {
                    .literal => |literal| {
                        const ref: LIR.BoxyDictRef = switch (literal) {
                            .result => |index| .{ .static = try self.emitLiteralAccessor(index) },
                            .parameter => |index| blk: {
                                const template = slot_template orelse boxyLowerInvariant("literal evidence needs its building frame");
                                const local = template.frame.literal_locals.items[index];
                                try template.capture(self.allocator, local);
                                break :blk .{ .local = local };
                            },
                        };
                        try frame.nested_dict_refs.append(self.allocator, ref);
                    },
                    .bound_dictionaries => |dictionaries| {
                        const template = slot_template orelse
                            boxyLowerInvariant("static dictionary method retained a runtime-bound nested dictionary");
                        const local = template.frame.boundDictionaryLocal(dictionaries);
                        try template.capture(self.allocator, local);
                        try frame.nested_dict_refs.append(self.allocator, .{ .local = local });
                    },
                    .static_rep => |source_rep| {
                        const request = StaticDictRequest{
                            .rep = source_rep,
                            .worker_dictionaries = arg.worker_dictionaries,
                            .method_evidence = arg.method_evidence,
                            .template = slot_template,
                            .env = arg.env,
                        };
                        return .{ .request = if (slot_template != null) .{ .dict_in_frame = request } else .{ .dict = request } };
                    },
                }
            }
        } else {
            const worker = self.plan.workers.items[@backingInt(frame.resolved)];
            const params = self.plan.hiddenDictionaryParamSlice(worker.hidden_dicts);
            if (frame.item < params.len) {
                const param = params[frame.item];
                frame.item += 1;
                return .{ .request = .{ .dict = .{
                    .rep = param.rep,
                    .worker_dictionaries = param.dictionaries,
                    .method_evidence = .{},
                    .template = null,
                    .env = 0,
                } } };
            }
        }

        const rep_id = frame.request.rep;
        const requirement = frame.requirement;
        const resolved = frame.resolved;
        const fn_type = frame.fn_type;
        const exact_method = frame.exact_method;
        if (slot_template) |frame_template| {
            if (exact_method) |method| {
                // An instantiated method's requirement dispatcher stands for
                // this dictionary's own type, as a checked call's
                // substitution states for its scheme variables.
                var substitution_pairs = std.ArrayList(Plan.SchemeRepSubstitution).empty;
                defer substitution_pairs.deinit(self.allocator);
                try substitution_pairs.appendSlice(self.allocator, self.plan.schemeRepSubstitutionSlice(method.requirement_substitution));
                if (self.staticMethodInstantiation(method) != null) {
                    try substitution_pairs.append(self.allocator, .{
                        .scheme_rep = self.plan.repForSourceType(requirement.source_type) orelse
                            boxyLowerInvariant("static dictionary requirement dispatcher type was not analyzed"),
                        .site_rep = rep_id,
                    });
                }
                for (substitution_pairs.items) |pair| {
                    const desc = self.plan.representations.items[@backingInt(pair.scheme_rep)].descriptor orelse continue;
                    if (!try frame_template.frame.repDescriptorNeedsFrame(pair.site_rep)) continue;
                    const materialization = try frame_template.frame.descriptorMaterializationForSourceRep(pair.site_rep);
                    if (materialization.desc.localOrNull()) |local| try frame_template.capture(self.allocator, local);
                    try frame_template.captureSpan(self.allocator, materialization.captures);
                    try frame.frame_requirement_descs.append(self.allocator, .{
                        .desc = desc,
                        .rep = pair.scheme_rep,
                        .slot = @intCast(frame.hidden_desc_refs.items.len),
                        .kind = .requirement,
                    });
                    try frame.hidden_desc_refs.append(self.allocator, materialization.desc);
                }
                var visited = collections.DenseMap(Plan.TypeRepId, void).init(self.allocator);
                defer visited.deinit();
                if (self.staticMethodInstantiation(method)) |instantiation| {
                    const call = try self.concreteMethodCall(method.callable_type, instantiation);
                    defer self.allocator.free(call.arg_reps);
                    for (call.arg_reps) |arg_rep| {
                        try self.collectFrameCallableDescriptors(frame_template, arg_rep, &visited, &frame.frame_requirement_descs, &frame.hidden_desc_refs);
                    }
                    try self.collectFrameCallableDescriptors(frame_template, call.ret, &visited, &frame.frame_requirement_descs, &frame.hidden_desc_refs);
                } else {
                    const callable_rep = self.plan.repForSourceType(method.callable_type) orelse
                        boxyLowerInvariant("static dictionary method callable type was not analyzed");
                    try self.collectFrameCallableDescriptors(
                        frame_template,
                        callable_rep,
                        &visited,
                        &frame.frame_requirement_descs,
                        &frame.hidden_desc_refs,
                    );
                }
            }
        }
        const worker_proc = try self.reserveWorkerProc(resolved);
        frame.method_proc = try self.emitStaticMethodBoundaryAdapter(
            resolved,
            worker_proc,
            fn_type,
            &frame.descriptor_sources,
            if (exact_method) |method| method.requirement_type else null,
            if (exact_method) |method| method.worker_desc_args else null,
            if (exact_method) |method| method.requirement_desc_sources else null,
            if (exact_method) |method| method.hidden_desc_sources else null,
            if (exact_method) |method| method.requirement_substitution else .{},
            frame.frame_requirement_descs.items,
            if (exact_method) |method| self.staticMethodInstantiation(method) else null,
        );
        if (self.needsFrozenCallableRecipes()) {
            const contract = if (exact_method) |method| method.requirement_type else fn_type;
            try self.result.boxy_frozen_method_origins.put(self.allocator, frame.method_proc, .{
                .worker = self.result.store.getProcSpec(worker_proc).identity,
                .requirement_module = contract.module,
                .requirement_type = contract.ty,
                .callable_module = fn_type.module,
                .callable_type = fn_type.ty,
            });
        }
        // A template slot's adapter descriptors name the building frame's
        // descriptors wherever they describe a requirement it supplies.
        for (frame.frame_requirement_descs.items) |frame_desc| {
            try frame.frame_descriptors.append(self.allocator, .{
                .desc = frame_desc.desc,
                .ref = frame.hidden_desc_refs.items[frame_desc.slot],
            });
        }
        frame.adapter_desc_context = .{ .frame_descriptors = frame.frame_descriptors.items };
        frame.phase = .adapter;
        return .{ .request = .{ .method_adapter = .{
            .worker_id = resolved,
            .requirement_fn_ty = fn_type,
            .descriptor_sources = &frame.descriptor_sources,
            .desc_context = if (frame.frame_descriptors.items.len == 0) &frame.desc_context else &frame.adapter_desc_context,
            .evidence_requirement_fn_ty = if (exact_method) |method| method.requirement_type else null,
            .worker_desc_args = if (exact_method) |method| method.worker_desc_args else null,
            .requirement_desc_args = if (exact_method) |method| method.requirement_desc_args else null,
            .requirement_desc_sources = if (exact_method) |method| method.requirement_desc_sources else null,
            .requirement_leaf_sources = if (exact_method) |method| method.requirement_leaf_sources else null,
            .hidden_desc_sources = if (exact_method) |method| method.hidden_desc_sources else null,
            .frame_requirement_descs = frame.frame_requirement_descs.items,
        } } };
    }

    /// The descriptor of a structural slot's operand when it is available
    /// without building a descriptor: in a template built by a frame whose
    /// descriptors the operand's representation names, that frame's
    /// descriptor for the representation.
    fn structuralSlotFrameOperandDesc(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        template: ?*DictTemplateFrame,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const frame_template = template orelse return null;
        if (!try frame_template.frame.repDescriptorNeedsFrame(rep_id)) return null;
        const materialization = try frame_template.frame.descriptorMaterializationForSourceRep(rep_id);
        if (materialization.desc.localOrNull()) |local| try frame_template.capture(self.allocator, local);
        try frame_template.captureSpan(self.allocator, materialization.captures);
        return materialization.desc;
    }

    fn stepStaticStructuralSlot(self: *ProcedureBuilder, frame: *StaticStructuralSlotFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        const request = frame.request;
        const rep_id = request.rep;
        switch (frame.phase) {
            .start => {
                const requirement_rep = self.plan.repForSourceType(request.fn_type) orelse
                    boxyLowerInvariant("structural dictionary function type was not analyzed");
                const function = self.staticMethodFunctionForRep(requirement_rep) orelse
                    boxyLowerInvariant("structural dictionary requirement was not a function");
                if (function.arg_count != 2) {
                    boxyLowerInvariant("structural dictionary requirement did not have two arguments");
                }
                const function_children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
                frame.second_rep = switch (request.method) {
                    .equality => rep_id,
                    .hash => function_children[function.args_start + 1].rep,
                };
                frame.source_layout = self.layout_plan.rep_layouts[@backingInt(rep_id)].worker.layoutIdx();
                frame.second_layout = self.layout_plan.rep_layouts[@backingInt(frame.second_rep)].worker.layoutIdx();
                const ret_layout = self.layout_plan.rep_layouts[@backingInt(function.ret)].worker.layoutIdx();
                if (request.method == .hash and frame.second_layout != ret_layout) {
                    boxyLowerInvariant("structural hash dictionary hasher argument and result layouts differed");
                }

                const frame_worker: ?Plan.WorkerPlanId = if (request.template) |outer| outer.frame.worker_layout.worker else null;
                const derived_frame = try self.plan.derivedFrame(self.allocator, frame_worker, rep_id, request.env);
                frame.frame_template = if (derived_frame != null) request.template.? else null;
                frame.shape = try self.derivedFrameShape(rep_id, derived_frame, request.env, .slot);
                frame.proc_id = try self.emitDerivedProc(.{
                    .method = request.method,
                    .rep = rep_id,
                    .second = .{ .rep = frame.second_rep },
                    .ret_layout = ret_layout,
                    .frame = derived_frame,
                    .env = request.env,
                    .shape = frame.shape,
                });
                if (frame.frame_template) |outer| {
                    if (frame.shape.operand_desc) {
                        if (try self.structuralSlotFrameOperandDesc(rep_id, outer)) |desc| {
                            try frame.frame_desc_refs.append(self.allocator, desc);
                        } else {
                            frame.phase = .operand_frame_desc;
                            return .{ .request = .{ .desc = rep_id } };
                        }
                    }
                    try self.finishStructuralSlotFrameRefs(frame, outer);
                }
                return try self.beginStructuralSlotOperand(frame);
            },
            .operand_frame_desc => {
                try frame.frame_desc_refs.append(self.allocator, staticValueRef(delivered.?).?);
                try self.finishStructuralSlotFrameRefs(frame, frame.frame_template.?);
                return try self.beginStructuralSlotOperand(frame);
            },
            .operand => {
                frame.operand_desc = staticValueRef(delivered.?) orelse
                    boxyLowerInvariant("structural slot operand descriptor request delivered no descriptor");
                return try self.structuralSlotSecondDesc(frame);
            },
            .second => return try self.finishStructuralSlot(frame, staticValueRef(delivered.?) orelse
                boxyLowerInvariant("structural slot hasher descriptor request delivered no descriptor")),
        }
    }

    fn finishStructuralSlotFrameRefs(self: *ProcedureBuilder, frame: *StaticStructuralSlotFrame, outer: *DictTemplateFrame) Allocator.Error!void {
        for (frame.shape.variables) |variable| {
            const materialization = try outer.frame.descriptorMaterializationForSourceRep(variable);
            const local = materialization.desc.localOrNull() orelse
                boxyLowerInvariant("derived method frame type variable had no descriptor local");
            if (materialization.captures.len != 0) {
                boxyLowerInvariant("derived method frame type variable descriptor captured other locals");
            }
            try outer.capture(self.allocator, local);
            try frame.frame_desc_refs.append(self.allocator, materialization.desc);
        }
        for (frame.shape.dictionaries) |dictionaries| {
            const local = outer.frame.boundDictionaryLocal(dictionaries);
            try outer.capture(self.allocator, local);
            try frame.frame_dict_refs.append(self.allocator, .{ .local = local });
        }
    }

    /// The descriptor a derived slot's operand is passed with. Inside a
    /// generic nominal's backing it is the representation described under
    /// the environment's actuals, the frame's type variables read through
    /// the frame's descriptors.
    fn beginStructuralSlotOperand(self: *ProcedureBuilder, frame: *StaticStructuralSlotFrame) Allocator.Error!StaticStep {
        const rep_id = frame.request.rep;
        frame.phase = .operand;
        if (frame.request.env == 0) {
            if (try self.structuralSlotFrameOperandDesc(rep_id, frame.frame_template)) |desc| {
                frame.operand_desc = desc;
                return try self.structuralSlotSecondDesc(frame);
            }
            return .{ .request = .{ .desc = rep_id } };
        }
        const variable_refs_start: usize = if (frame.shape.operand_desc) 1 else 0;
        if (frame.frame_template != null) {
            for (frame.shape.variables, 0..) |variable, index| {
                try frame.frame_descriptors.append(self.allocator, .{
                    .desc = self.plan.representations.items[@backingInt(variable)].descriptor orelse
                        boxyLowerInvariant("derived method type variable had no descriptor requirement"),
                    .ref = frame.frame_desc_refs.items[variable_refs_start + index],
                });
            }
        }
        frame.context = .{ .frame_descriptors = frame.frame_descriptors.items };
        try self.bindDerivedEnvInContext(&frame.context, frame.request.env);
        return .{ .request = .{ .source_desc_ref = .{
            .worker = rep_id,
            .source = null,
            .mapping = .{ .sources = &frame.sources, .context = &frame.context },
        } } };
    }

    fn structuralSlotSecondDesc(self: *ProcedureBuilder, frame: *StaticStructuralSlotFrame) Allocator.Error!StaticStep {
        frame.arg_layout_start = @intCast(self.result.boxy_method_arg_layouts.items.len);
        try self.result.boxy_method_arg_layouts.appendSlice(self.allocator, &.{ frame.source_layout, frame.second_layout });
        switch (frame.request.method) {
            .equality => return try self.finishStructuralSlot(frame, frame.operand_desc),
            .hash => {
                frame.phase = .second;
                return .{ .request = .{ .desc = frame.second_rep } };
            },
        }
    }

    fn finishStructuralSlot(self: *ProcedureBuilder, frame: *StaticStructuralSlotFrame, second_desc: LIR.BoxyDescRef) Allocator.Error!StaticStep {
        const arg_desc_start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.appendSlice(self.allocator, &.{ frame.operand_desc, second_desc });
        const hidden_sources_start: u32 = @intCast(self.result.boxy_method_hidden_desc_sources.items.len);
        for (0..frame.frame_desc_refs.items.len) |index| {
            try self.result.boxy_method_hidden_desc_sources.append(self.allocator, .{ .slot = @intCast(index) });
        }
        return .{ .done = .{ .method_slot = .{
            .method = frame.request.requirement.fn_name,
            .proc = frame.proc_id,
            .hidden_descs = try self.appendStaticHiddenDescRefs(frame.frame_desc_refs.items),
            .nested_dicts = try self.appendStaticHiddenDictRefs(frame.frame_dict_refs.items),
            .adapter = .{
                .arg_layouts = .{ .start = frame.arg_layout_start, .len = 2 },
                .arg_descs = .{ .start = arg_desc_start, .len = 2 },
                .hidden_desc_sources = .{ .start = hidden_sources_start, .len = @intCast(frame.frame_desc_refs.items.len) },
            },
        } } };
    }

    fn stepStaticMethodAdapter(self: *ProcedureBuilder, frame: *StaticMethodAdapterFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        const request = frame.request;
        switch (frame.phase) {
            .start => {
                const worker_layout = self.layout_plan.workerLayoutFor(request.worker_id);
                const worker_args = self.layout_plan.workerLayoutSlice(worker_layout.args);
                const worker = self.plan.workers.items[@backingInt(request.worker_id)];
                const function = self.staticMethodFunctionForRep(worker.rep) orelse
                    boxyLowerInvariant("static boxy dictionary method worker was not a function");
                if (function.arg_count != worker_args.len) {
                    boxyLowerInvariant("static boxy dictionary method worker arity disagreed with layout plan");
                }

                frame.mapping = if (request.worker_desc_args) |worker_sources|
                    try self.staticMethodDescriptorMappingForEvidence(
                        request.worker_id,
                        request.evidence_requirement_fn_ty orelse
                            boxyLowerInvariant("planned dictionary descriptor sources had no requirement type"),
                        worker_sources,
                        request.requirement_desc_sources orelse
                            boxyLowerInvariant("planned worker descriptor sources had no requirement descriptor sources"),
                        request.hidden_desc_sources orelse
                            boxyLowerInvariant("planned worker descriptors had no runtime source plan"),
                    )
                else
                    try self.staticMethodDescriptorMappingForWorker(
                        request.worker_id,
                        request.evidence_requirement_fn_ty orelse request.requirement_fn_ty,
                        request.descriptor_sources,
                    );

                const requirement_rep = self.plan.repForSourceType(request.evidence_requirement_fn_ty orelse request.requirement_fn_ty) orelse
                    boxyLowerInvariant("static boxy dictionary method requirement type was not analyzed");
                const requirement_function = self.staticMethodFunctionForRep(requirement_rep) orelse
                    boxyLowerInvariant("static boxy dictionary method requirement was not callable");
                if (requirement_function.arg_count != worker_args.len) {
                    boxyLowerInvariant("static boxy dictionary method requirement arity disagreed with worker layout plan");
                }
                const requirement_children = self.plan.childSlice(
                    self.plan.representations.items[@backingInt(requirement_function.rep)].children,
                );
                frame.requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
                try self.collectStaticMethodRequirementDescriptorSources(&frame.mapping, &frame.requirement_sources);

                frame.arg_layouts_start = @intCast(self.result.boxy_method_arg_layouts.items.len);
                for (frame.requirement_args) |arg| {
                    try self.result.boxy_method_arg_layouts.append(
                        self.allocator,
                        self.layout_plan.rep_layouts[@backingInt(arg.rep)].worker.layoutIdx(),
                    );
                }
                frame.phase = .arg_descs;
            },
            .arg_descs => try frame.arg_refs.append(self.allocator, staticValueRef(delivered.?) orelse
                boxyLowerInvariant("dictionary method argument descriptor request delivered no descriptor")),
            .call_descs => return try self.stepStaticMethodCallDescs(frame, delivered),
        }
        if (frame.arg_refs.items.len < frame.requirement_args.len) {
            return .{ .request = .{ .source_desc_ref = .{
                .worker = frame.requirement_args[frame.arg_refs.items.len].rep,
                .source = null,
                .mapping = .{ .sources = &frame.requirement_sources, .context = request.desc_context },
            } } };
        }
        // The argument descriptors are appended together once built, since
        // building one can append nested descriptors' references.
        const arg_descs_start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.appendSlice(self.allocator, frame.arg_refs.items);
        frame.arg_descs = .{ .start = arg_descs_start, .len = @intCast(frame.arg_refs.items.len) };

        if (request.requirement_desc_sources) |sources| {
            frame.evidence_call_descs = true;
            const planned_args = self.plan.directCallHiddenDescriptorArgSlice(request.requirement_desc_args orelse
                boxyLowerInvariant("planned dictionary requirement descriptors had no argument plan"));
            const planned_sources = self.plan.dictionaryMethodDescriptorSourceSlice(sources);
            const requirement_rep = self.plan.repForSourceType(request.evidence_requirement_fn_ty orelse
                boxyLowerInvariant("planned dictionary descriptor sources had no requirement type")) orelse
                boxyLowerInvariant("planned dictionary method requirement type was not analyzed");
            const requirement_function = self.staticMethodFunctionForRep(requirement_rep) orelse
                boxyLowerInvariant("planned dictionary method requirement was not a function");
            try self.collectStaticMethodCallDescIndexesForFunction(requirement_function, &frame.indexes);
            if (frame.indexes.entries.items.len != planned_args.len or planned_args.len != planned_sources.len) {
                boxyLowerInvariant("planned dictionary method descriptor sources disagreed with requirement descriptors");
            }
            const leaf_sources = self.plan.requirementLeafRepSlice(request.requirement_leaf_sources orelse .{});
            if (planned_sources.len == 0 and leaf_sources.len == 0) return try self.finishStaticMethodAdapter(frame, .{});
            for (frame.indexes.entries.items, planned_args, planned_sources) |entry, arg, source| {
                if (source.rep != arg.rep or entry.desc != arg.worker_desc) {
                    boxyLowerInvariant("planned dictionary method descriptor source identity disagreed with its requirement argument");
                }
                if (source.source == .static_rep) {
                    try frame.call_sources.put(self.allocator, entry.desc, source.rep);
                }
            }
            try frame.runtime_sources.ensureTotalCapacity(self.allocator, planned_sources.len + leaf_sources.len);
        } else {
            if (frame.mapping.indexes.entries.items.len == 0) return try self.finishStaticMethodAdapter(frame, .{});
            for (frame.mapping.indexes.entries.items) |entry| {
                const source_rep = frame.mapping.reps.reps.items[entry.index] orelse
                    boxyLowerInvariant("static boxy dictionary method call descriptor had no source representation");
                try frame.call_sources.put(self.allocator, entry.desc, source_rep);
            }
        }
        frame.phase = .call_descs;
        return try self.stepStaticMethodCallDescs(frame, null);
    }

    /// The descriptors a dictionary method's call supplies, one per step.
    fn stepStaticMethodCallDescs(self: *ProcedureBuilder, frame: *StaticMethodAdapterFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (delivered) |value| {
            try frame.call_descs.append(self.allocator, staticValueRef(value) orelse
                boxyLowerInvariant("dictionary method call descriptor request delivered no descriptor"));
            if (frame.evidence_call_descs) frame.runtime_sources.appendAssumeCapacity(.{ .slot = frame.pending_slot });
        }
        if (!frame.evidence_call_descs) {
            const entries = frame.mapping.indexes.entries.items;
            if (frame.index < entries.len) {
                const entry = entries[frame.index];
                frame.index += 1;
                return .{ .request = .{ .source_desc_ref = .{
                    .worker = self.plan.descriptors.items[@backingInt(entry.desc)].rep,
                    .source = null,
                    .mapping = .{ .sources = &frame.call_sources, .context = &frame.call_context },
                } } };
            }
            const start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
            try self.result.boxy_desc_refs.appendSlice(self.allocator, frame.call_descs.items);
            return try self.finishStaticMethodAdapter(frame, .{ .refs = .{ .start = start, .len = @intCast(entries.len) } });
        }

        const planned_sources = self.plan.dictionaryMethodDescriptorSourceSlice(frame.request.requirement_desc_sources.?);
        const entries = frame.indexes.entries.items;
        while (frame.index < entries.len) {
            const call_index = frame.index;
            frame.index += 1;
            const entry = entries[call_index];
            switch (planned_sources[call_index].source) {
                .static_rep => {
                    frame.pending_slot = @intCast(frame.call_descs.items.len);
                    return .{ .request = .{ .source_desc_ref = .{
                        .worker = self.plan.descriptors.items[@backingInt(entry.desc)].rep,
                        .source = null,
                        .mapping = .{ .sources = &frame.call_sources, .context = frame.request.desc_context },
                    } } };
                },
                .argument => |arg_index| frame.runtime_sources.appendAssumeCapacity(.{ .argument = arg_index }),
                .call => |planned_call_index| {
                    if (planned_call_index != call_index) {
                        boxyLowerInvariant("planned dictionary invocation descriptor did not name its requirement index");
                    }
                    frame.runtime_sources.appendAssumeCapacity(.{ .call = planned_call_index });
                },
            }
        }
        const leaf_sources = self.plan.requirementLeafRepSlice(frame.request.requirement_leaf_sources orelse .{});
        if (frame.index - entries.len < leaf_sources.len) {
            const source_rep = leaf_sources[frame.index - entries.len];
            frame.index += 1;
            frame.pending_slot = @intCast(frame.call_descs.items.len);
            return .{ .request = .{ .source_desc_ref = .{
                .worker = source_rep,
                .source = null,
                .mapping = .{ .sources = &frame.call_sources, .context = frame.request.desc_context },
            } } };
        }
        const refs_start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.appendSlice(self.allocator, frame.call_descs.items);
        const sources_start: u32 = @intCast(self.result.boxy_method_hidden_desc_sources.items.len);
        try self.result.boxy_method_hidden_desc_sources.appendSlice(self.allocator, frame.runtime_sources.items);
        return try self.finishStaticMethodAdapter(frame, .{
            .refs = .{ .start = refs_start, .len = @intCast(frame.call_descs.items.len) },
            .sources = .{ .start = sources_start, .len = @intCast(frame.runtime_sources.items.len) },
        });
    }

    fn finishStaticMethodAdapter(
        self: *ProcedureBuilder,
        frame: *StaticMethodAdapterFrame,
        call_desc_plan: StaticMethodCallDescriptorPlan,
    ) Allocator.Error!StaticStep {
        const request = frame.request;
        return .{ .done = .{ .adapter = .{
            .arg_layouts = .{
                .start = frame.arg_layouts_start,
                .len = @intCast(frame.requirement_args.len),
            },
            .arg_descs = frame.arg_descs,
            .call_descs = call_desc_plan.refs,
            .call_desc_sources = call_desc_plan.sources,
            .hidden_desc_sources = try self.staticMethodHiddenDescSourcesForWorker(
                request.worker_id,
                request.descriptor_sources,
                &frame.mapping,
                request.frame_requirement_descs,
            ),
        } } };
    }

    fn staticDescRefForRepIfNeeded(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor == null) return null;
        return try self.staticDescRefForRep(identity_rep);
    }

    /// Whether a dictionary built from `method_evidence` names values only
    /// `frame` supplies: a nested dictionary the frame binds, or a method
    /// descriptor whose representation the frame's own descriptors describe.
    /// Whether any method evidence `root` reaches reads a value only the
    /// building frame supplies. Which evidence is reached does not depend
    /// on visiting order.
    fn dictEvidenceNeedsFrame(
        self: *ProcedureBuilder,
        frame: *ProcBodyBuilder,
        root: Plan.Span,
        visited: *std.ArrayList(Plan.Span),
    ) Allocator.Error!bool {
        var pending: std.ArrayList(Plan.Span) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        spans: while (pending.pop()) |method_evidence| {
            for (visited.items) |seen| {
                if (std.meta.eql(seen, method_evidence)) continue :spans;
            }
            try visited.append(self.allocator, method_evidence);
            if (try self.dictEvidenceSpanNeedsFrame(frame, method_evidence, &pending)) return true;
        }
        return false;
    }

    /// Whether one span of method evidence reads a frame value directly;
    /// the nested evidence it carries is queued.
    fn dictEvidenceSpanNeedsFrame(
        self: *ProcedureBuilder,
        frame: *ProcBodyBuilder,
        method_evidence: Plan.Span,
        pending: *std.ArrayList(Plan.Span),
    ) Allocator.Error!bool {
        for (self.plan.dictionaryMethodEvidenceSlice(method_evidence)) |method| {
            switch (method.resolution) {
                .worker => {},
                .builtin_numeral, .structural, .constraint, .checked_error, .unreachable_value => continue,
            }
            const worker_args = self.plan.directCallHiddenDescriptorArgSlice(method.worker_desc_args);
            const hidden_sources = self.plan.dictionaryMethodHiddenDescriptorSourceSlice(method.hidden_desc_sources);
            for (worker_args, 0..) |arg, index| {
                if (index >= hidden_sources.len) break;
                switch (hidden_sources[index]) {
                    .slot => if (try frame.repDescriptorNeedsFrame(arg.rep)) return true,
                    .call, .argument => {},
                }
            }
            for (self.plan.dictionaryMethodDescriptorSourceSlice(method.requirement_desc_sources)) |source| {
                switch (source.source) {
                    .static_rep => if (try frame.repDescriptorNeedsFrame(source.rep)) return true,
                    .argument, .call => {},
                }
            }
            for (self.plan.requirementLeafRepSlice(method.requirement_leaf_sources)) |source_rep| {
                if (try frame.repDescriptorNeedsFrame(source_rep)) return true;
            }
            for (self.plan.directCallHiddenDictionaryArgSlice(method.nested_dict_args)) |arg| {
                switch (arg.source) {
                    .bound_dictionaries => return true,
                    .literal => |literal| if (literal == .parameter) return true,
                    .static_rep => |source_rep| {
                        if (try frame.repDescriptorNeedsFrame(source_rep)) return true;
                        try pending.append(self.allocator, arg.method_evidence);
                    },
                }
            }
        }
        return false;
    }

    /// The type variables `frame_template`'s frame binds that `rep_id`
    /// names, each carried by the method slot for its adapter.
    /// Collect, in pre-order, the frame descriptors `root` reaches.
    fn collectFrameCallableDescriptors(
        self: *ProcedureBuilder,
        frame_template: *DictTemplateFrame,
        root: Plan.TypeRepId,
        visited: *collections.DenseMap(Plan.TypeRepId, void),
        descs: *std.ArrayList(FrameRequirementDescriptor),
        refs: *std.ArrayList(LIR.BoxyDescRef),
    ) Allocator.Error!void {
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        reps: while (pending.pop()) |rep_id| {
            if ((try visited.getOrPut(rep_id)).found_existing) continue;
            const rep = self.plan.representations.items[@backingInt(rep_id)];
            if (rep.descriptor) |desc| {
                if (!try frame_template.frame.repDescriptorNeedsFrame(rep_id)) continue;
                const materialization = try frame_template.frame.descriptorMaterializationForSourceRep(rep_id);
                if (materialization.desc.localOrNull()) |local| {
                    if (materialization.captures.len == 0) {
                        if (frameRequirementDescriptorIndex(descs.items, desc) != null) continue :reps;
                        try frame_template.capture(self.allocator, local);
                        try descs.append(self.allocator, .{
                            .desc = desc,
                            .rep = rep_id,
                            .slot = @intCast(refs.items.len),
                            .kind = .frame_variable,
                        });
                        try refs.append(self.allocator, materialization.desc);
                        continue :reps;
                    }
                }
            }
            const children = self.plan.childSlice(rep.children);
            var index = children.len;
            while (index > 0) {
                index -= 1;
                try pending.append(self.allocator, children[index].rep);
            }
        }
    }

    fn collectPlannedStaticDescriptorSources(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        hidden_args: Plan.Span,
        sources: *StaticDescriptorSourceMap,
    ) Allocator.Error!void {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        const args = self.plan.directCallHiddenDescriptorArgSlice(hidden_args);
        if (params.len != args.len) {
            boxyLowerInvariant("planned static descriptor arguments did not cover every worker descriptor");
        }
        for (params, args) |param, arg| {
            if (param.desc != arg.worker_desc or param.rep != arg.worker_rep) {
                boxyLowerInvariant("planned static descriptor argument order disagreed with worker descriptors");
            }
            try sources.put(self.allocator, param.desc, arg.rep);
        }
    }

    /// The dictionaries `rep_id`'s `kind` method worker receives at that
    /// representation.
    fn descriptorMethodDictRefs(self: *ProcedureBuilder, rep_id: Plan.TypeRepId, kind: Plan.DescriptorMethod) Allocator.Error!LIR.BoxySpan {
        return staticValueSpan(try self.runStatic(.{ .method_dicts = .{ .rep = rep_id, .kind = kind } }));
    }

    fn stepStaticDescriptorMethodDict(self: *ProcedureBuilder, frame: *StaticDescriptorMethodDictFrame, delivered: ?StaticValue) Allocator.Error!StaticStep {
        if (frame.kind == .inspect) return .{ .done = .{ .span = .{} } };
        if (delivered) |value| {
            try frame.refs.append(self.allocator, .{ .static = staticValueDict(value) });
        } else if (!frame.started) {
            frame.started = true;
            const method = self.plan.descriptorMethodForRep(frame.rep, frame.kind) orelse return .{ .done = .{ .span = .{} } };
            const worker = self.plan.workers.items[@backingInt(method.worker)];
            const params = self.plan.hiddenDictionaryParamSlice(worker.hidden_dicts);
            if (params.len == 0) return .{ .done = .{ .span = .{} } };
            if (!method.static_hidden_dicts) {
                for (params) |param| {
                    try frame.refs.append(self.allocator, .{ .static = try self.descriptorDict(param.dictionaries, method.method_module) });
                }
                return .{ .done = .{ .span = try self.appendStaticHiddenDictRefs(frame.refs.items) } };
            }
            frame.args = method.hidden_dict_args;
            if (frame.args.len != params.len) boxyLowerInvariant("descriptor method dictionaries disagreed with its worker parameters");
        }
        const args = self.plan.directCallHiddenDictionaryArgSlice(frame.args);
        while (frame.refs.items.len < args.len) {
            const arg = args[frame.refs.items.len];
            const source_rep = switch (arg.source) {
                .static_rep => |rep| rep,
                // A slot is called from no frame, so each literal the worker
                // converts is closed at the described representation.
                .literal => |literal| switch (literal) {
                    .result => |index| {
                        try frame.refs.append(self.allocator, .{ .static = try self.emitLiteralAccessor(index) });
                        continue;
                    },
                    .parameter => boxyLowerInvariant("descriptor method at a concrete representation took an open literal"),
                },
                .bound_dictionaries => boxyLowerInvariant("descriptor method at a concrete representation took a non-static dictionary"),
            };
            return .{ .request = .{ .dict = .{ .rep = source_rep, .worker_dictionaries = arg.worker_dictionaries, .method_evidence = arg.method_evidence, .template = null, .env = arg.env } } };
        }
        return .{ .done = .{ .span = try self.appendStaticHiddenDictRefs(frame.refs.items) } };
    }

    /// A dictionary for `dictionaries`, each an `is_eq` or a `to_hash`, that
    /// compares or hashes its first argument by that argument's own
    /// descriptor: the derived method at whatever type the argument has,
    /// including each component type's own method. Each slot reads the
    /// descriptor of its first argument.
    fn descriptorDict(self: *ProcedureBuilder, dictionaries: Plan.Span, module_id: checked.ModuleId) Allocator.Error!LIR.BoxyDictId {
        for (self.descriptor_dicts.items) |entry| {
            if (std.meta.eql(entry.dictionaries, dictionaries)) return entry.dict;
        }
        const dynamic_layout = try self.result.layouts.insertErasedBox();
        var slots = std.ArrayList(LirProgram.BoxyMethodSlot).empty;
        defer slots.deinit(self.allocator);
        try slots.appendNTimes(self.allocator, .{
            .present = false,
            .method = undefined,
            .proc = undefined,
        }, self.plan.dictionary_method_slots.items.len);
        for (self.plan.dictionarySlice(dictionaries)) |requirement| {
            const view = procedureModuleById(self.modules, requirement.source_type.module);
            const name = view.canonical_names.methodNameText(requirement.fn_name);
            const second_layout = if (std.mem.eql(u8, name, "is_eq"))
                dynamic_layout
            else if (std.mem.eql(u8, name, "to_hash"))
                try self.descriptorDictHasherLayout(requirement)
            else
                boxyLowerInvariant("descriptor dictionary was required to supply a method other than is_eq or to_hash");
            const proc = if (second_layout == dynamic_layout)
                try self.descriptorEqualityProc(module_id)
            else
                try self.descriptorHashProc(module_id, second_layout);
            const arg_layouts_start: u32 = @intCast(self.result.boxy_method_arg_layouts.items.len);
            try self.result.boxy_method_arg_layouts.appendSlice(self.allocator, &.{ dynamic_layout, second_layout });
            const hidden_sources_start: u32 = @intCast(self.result.boxy_method_hidden_desc_sources.items.len);
            try self.result.boxy_method_hidden_desc_sources.append(self.allocator, .{ .argument = 0 });
            slots.items[requirement.slot] = .{
                .method = requirement.fn_name,
                .proc = proc,
                .adapter = .{
                    .arg_layouts = .{ .start = arg_layouts_start, .len = 2 },
                    .hidden_desc_sources = .{ .start = hidden_sources_start, .len = 1 },
                },
            };
        }
        const dict_id: LIR.BoxyDictId = @fromBackingInt(@as(u32, @intCast(self.result.boxy_dicts.items.len)));
        const method_start: u32 = @intCast(self.result.boxy_method_slots.items.len);
        try self.result.boxy_method_slots.appendSlice(self.allocator, slots.items);
        try self.result.boxy_dicts.append(self.allocator, .{
            .method_slots = .{ .start = method_start, .len = @intCast(slots.items.len) },
        });
        try self.descriptor_dicts.append(self.allocator, .{ .dictionaries = dictionaries, .dict = dict_id });
        return dict_id;
    }

    /// The Hasher layout of a `to_hash` requirement: its second argument's.
    fn descriptorDictHasherLayout(self: *ProcedureBuilder, requirement: Plan.DictionaryRequirement) Allocator.Error!layout.Idx {
        const fn_rep = self.plan.repForSourceType(requirement.fn_ty) orelse
            boxyLowerInvariant("descriptor dictionary to_hash requirement type was not analyzed");
        const function = self.staticMethodFunctionForRep(fn_rep) orelse
            boxyLowerInvariant("descriptor dictionary to_hash requirement was not a function");
        if (function.arg_count != 2) boxyLowerInvariant("descriptor dictionary to_hash requirement did not take two arguments");
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        return self.layout_plan.rep_layouts[@backingInt(children[function.args_start + 1].rep)].worker.layoutIdx();
    }

    /// `to_hash(value, hasher)` over a dynamic value described by one hidden
    /// descriptor: the descriptor-guided hashing of `assign_boxy_hash`.
    fn descriptorHashProc(self: *ProcedureBuilder, module_id: checked.ModuleId, hasher_layout: layout.Idx) Allocator.Error!LIR.LirProcSpecId {
        if (self.descriptor_hash_proc) |proc_id| return proc_id;
        if (self.layout_plan.worker_layouts.len == 0) {
            boxyLowerInvariant("descriptor hash procedure was emitted without a worker layout context");
        }
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        var proc = ProcBodyBuilder.initSyntheticAdapter(
            self,
            procedureModuleById(self.modules, module_id),
            self.layout_plan.worker_layouts[0],
            constructlessOrigin(.derived),
        );
        defer proc.deinit();

        const dynamic_layout = try self.result.layouts.insertErasedBox();
        const value = try proc.addArgLocal(dynamic_layout);
        const hasher = try proc.addArgLocal(hasher_layout);
        const desc = try proc.addFrameLocal(.opaque_ptr);
        try proc.markReadOnlyDescriptorInput(desc);
        try proc.arg_locals.append(self.allocator, desc);
        self.result.store.setLocalBoxyDesc(value, .{ .local = desc });
        const result = try proc.addFrameLocal(hasher_layout);
        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = result } }, proc.derivedOrigin());
        const body = try self.result.store.addCFStmt(.{ .assign_boxy_hash = .{
            .target = result,
            .value = value,
            .hasher = hasher,
            .desc = .{ .local = desc },
            .next = ret_stmt,
        } }, proc.derivedOrigin());
        const args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        const proc_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = args_span,
            .frame_locals = frame_span,
            .body = body,
            .ret_layout = hasher_layout,
            .boxy_runtime_entry = true,
            .stack_probe = self.stackProbeForProc(args_span, frame_span, hasher_layout),
        }, proc.origin.loc);
        const proc_spec = self.result.store.getProcSpecPtr(proc_id);
        proc_spec.shapes = proc_spec.shapes.merged(self.result.store.shapes);
        self.descriptor_hash_proc = proc_id;
        return proc_id;
    }

    /// `is_eq(lhs, rhs)` over two dynamic values described by one hidden
    /// descriptor: the descriptor-guided equality of `assign_boxy_eq`.
    fn descriptorEqualityProc(self: *ProcedureBuilder, module_id: checked.ModuleId) Allocator.Error!LIR.LirProcSpecId {
        if (self.descriptor_equality_proc) |proc_id| return proc_id;
        if (self.layout_plan.worker_layouts.len == 0) {
            boxyLowerInvariant("descriptor equality procedure was emitted without a worker layout context");
        }
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        var proc = ProcBodyBuilder.initSyntheticAdapter(
            self,
            procedureModuleById(self.modules, module_id),
            self.layout_plan.worker_layouts[0],
            constructlessOrigin(.derived),
        );
        defer proc.deinit();

        const dynamic_layout = try self.result.layouts.insertErasedBox();
        const lhs = try proc.addArgLocal(dynamic_layout);
        const rhs = try proc.addArgLocal(dynamic_layout);
        const desc = try proc.addFrameLocal(.opaque_ptr);
        try proc.markReadOnlyDescriptorInput(desc);
        try proc.arg_locals.append(self.allocator, desc);
        self.result.store.setLocalBoxyDesc(lhs, .{ .local = desc });
        self.result.store.setLocalBoxyDesc(rhs, .{ .local = desc });
        const result = try proc.addFrameLocal(.bool);
        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = result } }, proc.derivedOrigin());
        const body = try self.result.store.addCFStmt(.{ .assign_boxy_eq = .{
            .target = result,
            .lhs = lhs,
            .rhs = rhs,
            .desc = .{ .local = desc },
            .next = ret_stmt,
        } }, proc.derivedOrigin());
        const args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        const proc_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = args_span,
            .frame_locals = frame_span,
            .body = body,
            .ret_layout = .bool,
            .boxy_runtime_entry = true,
            .stack_probe = self.stackProbeForProc(args_span, frame_span, .bool),
        }, proc.origin.loc);
        const proc_spec = self.result.store.getProcSpecPtr(proc_id);
        proc_spec.shapes = proc_spec.shapes.merged(self.result.store.shapes);
        self.descriptor_equality_proc = proc_id;
        return proc_id;
    }

    /// The argument descriptors of a `method` call over the value `ref`
    /// describes: `ref` for each value argument, and a hash call's Hasher.
    fn appendDescriptorMethodArgRefs(self: *ProcedureBuilder, method: Plan.DescriptorMethodPlan, ref: LIR.BoxyDescRef) Allocator.Error!LIR.BoxySpan {
        const second = if (method.second_type) |ty|
            try self.staticDescRefForRep(self.plan.repForSourceType(ty) orelse
                boxyLowerInvariant("descriptor method second argument type was not analyzed"))
        else
            ref;
        const refs = [_]LIR.BoxyDescRef{ ref, second };
        return try self.appendStaticHiddenDescRefs(refs[0..method.kind.argCount()]);
    }

    /// Whether the inspect call instantiates its worker at the worker's own
    /// type parameters; the inspected descriptor then already describes the
    /// value in the worker parameter's storage.
    fn descriptorMethodArgumentIsIdentity(self: *const ProcedureBuilder, method: Plan.DescriptorMethodPlan) bool {
        if (self.descriptorIdentityRep(method.source_rep) != self.descriptorIdentityRep(self.descriptorMethodWorkerArgRep(method))) return false;
        for (self.plan.directCallHiddenDescriptorArgSlice(method.hidden_desc_args)) |arg| {
            if (self.descriptorIdentityRep(arg.rep) != self.descriptorIdentityRep(arg.worker_rep)) return false;
        }
        return true;
    }

    /// The worker's first receiver-typed parameter; an `is_eq` worker's two
    /// parameters share its type.
    fn descriptorMethodWorkerArgRep(self: *const ProcedureBuilder, method: Plan.DescriptorMethodPlan) Plan.TypeRepId {
        const worker = self.plan.workers.items[@backingInt(method.worker)];
        const function = self.repQuery().functionChildren(worker.rep) orelse
            boxyLowerInvariant("boxy descriptor method worker was not callable");
        if (function.arg_count != method.kind.argCount()) boxyLowerInvariant("boxy descriptor method worker had unexpected arity");
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        return children[function.args_start].rep;
    }

    fn appendStaticHiddenDescRefs(
        self: *ProcedureBuilder,
        refs: []const LIR.BoxyDescRef,
    ) Allocator.Error!LIR.BoxySpan {
        if (refs.len == 0) return .{};
        const start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.appendSlice(self.allocator, refs);
        return .{ .start = start, .len = @intCast(refs.len) };
    }

    fn appendStaticHiddenDictRefs(
        self: *ProcedureBuilder,
        refs: []const LIR.BoxyDictRef,
    ) Allocator.Error!LIR.BoxySpan {
        if (refs.len == 0) return .{};
        const start: u32 = @intCast(self.result.boxy_dict_refs.items.len);
        try self.result.boxy_dict_refs.appendSlice(self.allocator, refs);
        return .{ .start = start, .len = @intCast(refs.len) };
    }

    const StaticMethodFunction = struct {
        rep: Plan.TypeRepId,
        args_start: u32,
        arg_count: u32,
        ret: Plan.TypeRepId,
    };

    const StaticMethodCallDescriptorPlan = struct {
        refs: LIR.BoxySpan = .{},
        sources: LIR.BoxySpan = .{},
    };

    /// A dictionary method called at its recorded instantiation rather than
    /// at a checked evidence callable.
    const StaticMethodInstantiation = struct {
        arg_types: []const Plan.CheckedTypeIdentity,
        ret_type: Plan.CheckedTypeIdentity,
        rep: ?Plan.TypeRepId = null,
    };

    fn staticMethodInstantiation(self: *const ProcedureBuilder, method: Plan.DictionaryMethodEvidence) ?StaticMethodInstantiation {
        const ret_type = method.instantiation_ret_type orelse return null;
        return .{
            .arg_types = self.plan.dictionaryMethodCallTypeSlice(method.instantiation_arg_types),
            .ret_type = ret_type,
            .rep = method.instantiation_rep,
        };
    }

    /// The argument and result representations of the edge a static
    /// dictionary method is called at.
    const ConcreteMethodCall = struct {
        arg_reps: []Plan.TypeRepId,
        ret: Plan.TypeRepId,
    };

    fn concreteMethodCall(
        self: *ProcedureBuilder,
        callable_type: Plan.CheckedTypeIdentity,
        instantiation: ?StaticMethodInstantiation,
    ) Allocator.Error!ConcreteMethodCall {
        if (instantiation) |call| {
            if (call.rep) |rep| {
                const function = self.staticMethodFunctionForRep(rep) orelse boxyLowerInvariant("literal method instantiation was not callable");
                const args = try self.allocator.alloc(Plan.TypeRepId, function.arg_count);
                const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
                for (children[function.args_start..][0..function.arg_count], args) |child, *arg| arg.* = child.rep;
                return .{ .arg_reps = args, .ret = function.ret };
            }
            const arg_reps = try self.allocator.alloc(Plan.TypeRepId, call.arg_types.len);
            for (call.arg_types, arg_reps) |arg_type, *arg_rep| {
                arg_rep.* = self.plan.repForSourceType(arg_type) orelse
                    boxyLowerInvariant("static dictionary method instantiation argument type was not analyzed");
            }
            return .{
                .arg_reps = arg_reps,
                .ret = self.plan.repForSourceType(call.ret_type) orelse
                    boxyLowerInvariant("static dictionary method instantiation result type was not analyzed"),
            };
        }
        const concrete_rep = self.plan.repForSourceType(callable_type) orelse
            boxyLowerInvariant("static dictionary method callable type was not analyzed");
        const concrete = self.staticMethodFunctionForRep(concrete_rep) orelse
            boxyLowerInvariant("static dictionary method callable type was not callable");
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(concrete.rep)].children);
        const arg_reps = try self.allocator.alloc(Plan.TypeRepId, concrete.arg_count);
        for (children[concrete.args_start..][0..concrete.arg_count], arg_reps) |child, *arg_rep| arg_rep.* = child.rep;
        return .{ .arg_reps = arg_reps, .ret = concrete.ret };
    }

    /// A static dictionary method adapter's body, with the builder its
    /// reserved header set up. The body calls the method worker, so it is
    /// built once the worker's signature is final.
    const StaticMethodAdapterJob = struct {
        proc_id: LIR.LirProcSpecId,
        worker_id: Plan.WorkerPlanId,
        worker_proc: LIR.LirProcSpecId,
        proc: ProcBodyBuilder,
        worker_function: StaticMethodFunction,
        requirement_function: StaticMethodFunction,
        worker_args: []const Plan.RepChild,
        requirement_args: []const Plan.RepChild,
        worker_ret_layout: @FieldType(Layouts.WorkerLayouts, "value"),
        concrete_function: ?ConcreteMethodCall = null,
        slot_sources: StaticDescriptorSourceMap = .{},
        desc_context: StaticDescInstantiationContext = .{},
        requirement_sources: StaticDescriptorSourceMap = .{},
        requirement_context: StaticDescInstantiationContext = .{},
        frame_requirement_descs: []FrameRequirementDescriptor = &.{},
        frame_requirement_locals: []LIR.LocalId = &.{},
        worker_call_args: []LIR.LocalId = &.{},
        /// The dictionary construction's inputs, which the header reads.
        requirement_fn_ty: Plan.CheckedTypeIdentity = undefined,
        descriptor_sources: StaticDescriptorSourceMap = .{},
        evidence_requirement_fn_ty: ?Plan.CheckedTypeIdentity = null,
        worker_desc_args: ?Plan.Span = null,
        requirement_desc_sources: ?Plan.Span = null,
        hidden_desc_sources: ?Plan.Span = null,
        requirement_substitution: Plan.Span = .{},
        instantiation: ?StaticMethodInstantiation = null,
        header_built: bool = false,
        arg_local_count: usize = 0,
        ret_layout: layout.Idx = undefined,
        args_span: LIR.LocalSpan = undefined,

        fn deinit(job: *StaticMethodAdapterJob, allocator: Allocator) void {
            job.proc.deinit();
            if (job.concrete_function) |concrete| allocator.free(concrete.arg_reps);
            job.slot_sources.deinit(allocator);
            job.descriptor_sources.deinit(allocator);
            job.desc_context.deinit(allocator);
            job.requirement_sources.deinit(allocator);
            job.requirement_context.deinit(allocator);
            allocator.free(job.frame_requirement_descs);
            allocator.free(job.frame_requirement_locals);
            allocator.free(job.worker_call_args);
        }
    };

    /// The procedure a static dictionary exposes for `worker_id`'s method:
    /// the worker itself when its ABI already matches the requirement, else
    /// an adapter whose header is reserved here and whose body is queued.
    fn emitStaticMethodBoundaryAdapter(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        worker_proc: LIR.LirProcSpecId,
        requirement_fn_ty: Plan.CheckedTypeIdentity,
        descriptor_sources: *const StaticDescriptorSourceMap,
        evidence_requirement_fn_ty: ?Plan.CheckedTypeIdentity,
        worker_desc_args: ?Plan.Span,
        requirement_desc_sources: ?Plan.Span,
        hidden_desc_sources: ?Plan.Span,
        requirement_substitution: Plan.Span,
        frame_requirement_descs: []const FrameRequirementDescriptor,
        instantiation: ?StaticMethodInstantiation,
    ) Allocator.Error!LIR.LirProcSpecId {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const worker_function = self.staticMethodFunctionForRep(worker.rep) orelse
            boxyLowerInvariant("static boxy dictionary method worker was not callable");
        const requirement_rep = self.plan.repForSourceType(evidence_requirement_fn_ty orelse requirement_fn_ty) orelse
            boxyLowerInvariant("static boxy dictionary method requirement type was not analyzed");
        const requirement_function = self.staticMethodFunctionForRep(requirement_rep) orelse
            boxyLowerInvariant("static boxy dictionary method requirement was not callable");
        if (worker_function.arg_count != requirement_function.arg_count) {
            boxyLowerInvariant("static boxy dictionary method adapter saw mismatched method arity");
        }

        const resolved = self.resolved_workers.items[@backingInt(worker_id)];
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        var worker_origin = try self.workerOrigin(resolved);
        worker_origin.kind = .scaffold;
        const job = try self.allocator.create(StaticMethodAdapterJob);
        var job_owned = true;
        job.* = .{
            .proc_id = undefined,
            .worker_id = worker_id,
            .worker_proc = worker_proc,
            .proc = ProcBodyBuilder.initSyntheticAdapter(
                self,
                resolved.module,
                self.layout_plan.workerLayoutFor(worker_id),
                worker_origin,
            ),
            .worker_function = worker_function,
            .requirement_function = requirement_function,
            .worker_args = undefined,
            .requirement_args = undefined,
            .worker_ret_layout = undefined,
        };
        defer if (job_owned) {
            job.deinit(self.allocator);
            self.allocator.destroy(job);
        };
        const proc = &job.proc;

        const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
        const worker_layout = self.layout_plan.workerLayoutFor(worker_id);
        const worker_arg_layouts = self.layout_plan.workerLayoutSlice(worker_layout.args);
        const worker_ret_layout = if (worker_layout.ret) |ret| ret else worker_layout.value;
        const requirement_children = self.plan.childSlice(self.plan.representations.items[@backingInt(requirement_function.rep)].children);
        const requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
        job.worker_args = worker_args;
        job.requirement_args = requirement_args;
        job.worker_ret_layout = worker_ret_layout;

        // Frame-supplied requirement descriptors arrive as arguments the
        // worker does not take, so only an adapter can receive them.
        var needs_adapter = frame_requirement_descs.len != 0 or
            worker_ret_layout.layoutIdx() != proc.workerRuntimeLayoutForRep(requirement_function.ret).layoutIdx() or
            !try proc.callableValueBoundaryIsDirect(requirement_function.ret, worker_function.ret);
        for (worker_args, worker_arg_layouts, requirement_args) |worker_arg, worker_arg_layout, requirement_arg| {
            if (worker_arg_layout.layoutIdx() != proc.workerRuntimeLayoutForRep(requirement_arg.rep).layoutIdx() or
                !try proc.callableValueBoundaryIsDirect(worker_arg.rep, requirement_arg.rep))
            {
                needs_adapter = true;
                break;
            }
        }
        if (!needs_adapter) return worker_proc;

        job.requirement_fn_ty = requirement_fn_ty;
        job.descriptor_sources = .{ .entries = try descriptor_sources.entries.clone(self.allocator) };
        job.evidence_requirement_fn_ty = evidence_requirement_fn_ty;
        job.worker_desc_args = worker_desc_args;
        job.requirement_desc_sources = requirement_desc_sources;
        job.hidden_desc_sources = hidden_desc_sources;
        job.requirement_substitution = requirement_substitution;
        job.frame_requirement_descs = try self.allocator.dupe(FrameRequirementDescriptor, frame_requirement_descs);
        job.instantiation = instantiation;
        job.ret_layout = proc.workerRuntimeLayoutForRep(requirement_function.ret).layoutIdx();
        const proc_symbol = self.symbols.fresh();
        job.proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = LIR.LocalSpan.empty(),
            .body = null,
            .ret_layout = job.ret_layout,
            .boxy_runtime_entry = true,
        }, proc.origin.loc);
        try self.appendProcJob(.{ .static_method_adapter = job });
        job_owned = false;
        return job.proc_id;
    }

    /// Build a static dictionary method adapter's header: its arguments,
    /// descriptor sources, and the arguments it passes the worker.
    fn buildStaticMethodAdapterHeader(self: *ProcedureBuilder, job: *StaticMethodAdapterJob) Allocator.Error!void {
        if (job.header_built) return;
        job.header_built = true;
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        const proc = &job.proc;
        const worker_id = job.worker_id;
        const requirement_function = job.requirement_function;
        const worker_args = job.worker_args;
        const requirement_args = job.requirement_args;
        const worker_arg_layouts = self.layout_plan.workerLayoutSlice(self.layout_plan.workerLayoutFor(worker_id).args);
        const requirement_fn_ty = job.requirement_fn_ty;
        const descriptor_sources = &job.descriptor_sources;
        const evidence_requirement_fn_ty = job.evidence_requirement_fn_ty;
        const worker_desc_args = job.worker_desc_args;
        const requirement_desc_sources = job.requirement_desc_sources;
        const hidden_desc_sources = job.hidden_desc_sources;
        const requirement_substitution = job.requirement_substitution;
        const frame_requirement_descs = job.frame_requirement_descs;
        const instantiation = job.instantiation;

        var descriptor_mapping = if (worker_desc_args) |worker_sources|
            try self.staticMethodDescriptorMappingForEvidence(
                worker_id,
                evidence_requirement_fn_ty orelse
                    boxyLowerInvariant("planned dictionary descriptor sources had no requirement type"),
                worker_sources,
                requirement_desc_sources orelse
                    boxyLowerInvariant("planned worker descriptor sources had no requirement descriptor sources"),
                hidden_desc_sources orelse
                    boxyLowerInvariant("planned worker descriptors had no runtime source plan"),
            )
        else
            try self.staticMethodDescriptorMappingForWorker(
                worker_id,
                evidence_requirement_fn_ty orelse requirement_fn_ty,
                descriptor_sources,
            );
        defer descriptor_mapping.deinit(self.allocator);

        const requirement_sources = &job.requirement_sources;
        try self.collectStaticMethodRequirementDescriptorSources(&descriptor_mapping, requirement_sources);
        // The requirement type is written in the scheme variables of the
        // worker receiving this dictionary. Positions the call descriptors do
        // not cover, such as inside a function-typed argument, take the type the
        // supplying call's checked substitution gave the variable.
        for (self.plan.schemeRepSubstitutionSlice(requirement_substitution)) |pair| {
            const desc = self.plan.representations.items[@backingInt(pair.scheme_rep)].descriptor orelse continue;
            if (requirement_sources.get(desc) != null) continue;
            if (frameRequirementDescriptorIndex(frame_requirement_descs, desc) != null) continue;
            try requirement_sources.put(self.allocator, desc, pair.site_rep);
        }
        // A dictionary a worker passes to its own recursive instantiation has
        // a requirement written in that worker's scheme variables, so one
        // descriptor names the requirement's instantiation and the worker's.
        // Such an adapter converts through the checked callable type at this
        // edge: the requirement side is lowered apart from the worker's
        // descriptor bindings, and each side reads only its own sources.
        job.concrete_function = if (try proc.staticMethodSidesShareDescriptors(requirement_function, worker_id))
            try self.concreteMethodCall(requirement_fn_ty, instantiation)
        else
            null;
        if (job.concrete_function) |concrete| {
            if (concrete.arg_reps.len != requirement_function.arg_count) {
                boxyLowerInvariant("static dictionary method callable type arity disagreed with its requirement");
            }
        }
        for (descriptor_sources.entries.items) |entry| {
            try job.slot_sources.put(self.allocator, entry.worker_desc, entry.source_rep);
        }
        if (job.concrete_function == null) {
            for (requirement_sources.entries.items) |entry| {
                try job.slot_sources.put(self.allocator, entry.worker_desc, entry.source_rep);
            }
        }
        proc.static_descriptor_materialization_scope = .{
            .sources = &job.slot_sources,
            .context = &job.desc_context,
        };

        const requirement_arg_locals = try self.allocator.alloc(LIR.LocalId, requirement_args.len);
        defer self.allocator.free(requirement_arg_locals);
        for (requirement_args, requirement_arg_locals) |arg, *local| {
            local.* = try proc.addArgLocalForRep(arg.rep);
        }
        try proc.bindPassthroughHiddenDescriptorArgs();
        const worker_hidden_desc_end = proc.arg_locals.items.len;
        job.frame_requirement_locals = try self.allocator.alloc(LIR.LocalId, frame_requirement_descs.len);
        const frame_requirement_locals = job.frame_requirement_locals;
        for (frame_requirement_locals) |*local| {
            local.* = try proc.addArgLocal(.opaque_ptr);
            try proc.markReadOnlyDescriptorInput(local.*);
        }
        const frame_requirement_end = proc.arg_locals.items.len;
        try proc.bindHiddenDictionaryArgs();
        try proc.bindWorkerDictionaryDescriptors();
        proc.template_frame_descriptors = frame_requirement_descs.len != 0;
        try proc.bindFrameRequirementDescriptors(frame_requirement_descs, frame_requirement_locals, job.concrete_function == null);
        for (requirement_args, requirement_arg_locals) |arg, local| {
            const arg_desc = self.plan.representations.items[@backingInt(self.descriptorIdentityRep(arg.rep))].descriptor;
            const frame_index = if (arg_desc) |desc| frameRequirementDescriptorIndex(frame_requirement_descs, desc) else null;
            self.result.store.setLocalBoxyDesc(local, if (frame_index) |index|
                .{ .local = frame_requirement_locals[index] }
            else
                try self.staticDescRefForWorkerRepWithSourceMap(
                    arg.rep,
                    null,
                    requirement_sources,
                    &job.desc_context,
                ));
        }

        job.worker_call_args = try self.allocator.alloc(LIR.LocalId, proc.arg_locals.items.len - frame_requirement_descs.len);
        const worker_call_args = job.worker_call_args;
        for (worker_args, worker_arg_layouts, requirement_args, 0..) |worker_arg, worker_arg_layout, requirement_arg, arg_index| {
            worker_call_args[arg_index] = if (worker_arg_layout.layoutIdx() == self.result.store.getLocal(proc.arg_locals.items[arg_index]).layout_idx and
                try proc.callableValueBoundaryIsDirect(worker_arg.rep, requirement_arg.rep))
                proc.arg_locals.items[arg_index]
            else
                try proc.addFrameLocalForRuntimeRep(worker_arg_layout, worker_arg.rep);
        }
        // The worker takes its own hidden descriptors and dictionaries, not
        // the frame-supplied requirement descriptors between them.
        const worker_hidden_descs = proc.arg_locals.items[requirement_args.len..worker_hidden_desc_end];
        @memcpy(worker_call_args[worker_args.len..][0..worker_hidden_descs.len], worker_hidden_descs);
        @memcpy(
            worker_call_args[worker_args.len + worker_hidden_descs.len ..],
            proc.arg_locals.items[frame_requirement_end..],
        );

        job.arg_local_count = proc.arg_locals.items.len;
        job.args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        const proc_spec = self.result.store.getProcSpecPtr(job.proc_id);
        proc_spec.args = job.args_span;
        proc_spec.stack_probe = self.stackProbeForProc(job.args_span, LIR.LocalSpan.empty(), job.ret_layout);
    }

    fn buildStaticMethodAdapterBody(self: *ProcedureBuilder, job: *StaticMethodAdapterJob) Allocator.Error!void {
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        const proc = &job.proc;
        const worker_function = job.worker_function;
        const requirement_function = job.requirement_function;
        const worker_args = job.worker_args;
        const requirement_args = job.requirement_args;
        const worker_call_args = job.worker_call_args;
        const frame_requirement_descs = job.frame_requirement_descs;
        const frame_requirement_locals = job.frame_requirement_locals;
        const concrete_function = job.concrete_function;
        const concrete_arg_reps: []const Plan.TypeRepId = if (concrete_function) |concrete| concrete.arg_reps else &.{};
        const requirement_scope = StaticDescriptorMaterializationScope{
            .sources = &job.requirement_sources,
            .context = &job.requirement_context,
        };

        const worker_spec = self.result.store.getProcSpec(job.worker_proc);
        if (worker_spec.body == null) {
            boxyLowerInvariant("static dictionary method adapter body was built before its worker");
        }
        const worker_proc_args = self.result.store.getLocalSpan(worker_spec.args);
        if (worker_call_args.len != worker_proc_args.len) {
            boxyLowerInvariant("static boxy dictionary method adapter argument ABI disagreed with its worker");
        }
        for (worker_call_args, 0..) |adapter_arg, arg_index| {
            const worker_arg = GuardedList.at(worker_proc_args, arg_index);
            if (self.result.store.getLocal(adapter_arg).layout_idx != self.result.store.getLocal(worker_arg).layout_idx) {
                boxyLowerInvariant("static boxy dictionary method adapter argument layout disagreed with its worker");
            }
        }
        const worker_returns_runtime_desc = worker_spec.runtime_ret_desc != null;
        const result = try proc.addFrameLocalForRep(requirement_function.ret);
        const raw_result = if (worker_returns_runtime_desc)
            try proc.addFrameLocalForRepWithRequiredFreshDescriptor(worker_function.ret)
        else
            try proc.addFrameLocalForRuntimeRep(job.worker_ret_layout, worker_function.ret);
        const raw_result_desc = if (worker_returns_runtime_desc)
            proc.callResultOutputDescriptorLocal(raw_result) orelse
                boxyLowerInvariant("static dictionary method adapter result had no descriptor output local")
        else
            null;
        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = result } }, proc.origin);
        var continuation = if (concrete_function) |concrete| split: {
            const concrete_result = try proc.addFrameLocalForRep(concrete.ret);
            const detached = try proc.enterDetachedDescriptorScope(requirement_scope);
            try proc.bindFrameRequirementDescriptors(frame_requirement_descs, frame_requirement_locals, true);
            const to_requirement = try proc.assignPlannedCallBoundary(result, concrete_result, requirement_function.ret, concrete.ret, ret_stmt);
            const requirement_step = try proc.leaveDetachedDescriptorScope(detached, to_requirement);
            break :split try proc.assignPlannedCallBoundary(concrete_result, raw_result, concrete.ret, worker_function.ret, requirement_step);
        } else try proc.assignPlannedCallBoundary(
            result,
            raw_result,
            requirement_function.ret,
            worker_function.ret,
            ret_stmt,
        );
        continuation = try self.result.store.addCFStmt(.{ .assign_call = .{
            .target = raw_result,
            .proc = job.worker_proc,
            .args = try self.result.store.addLocalSpan(worker_call_args),
            .out_desc = raw_result_desc,
            .next = continuation,
        } }, proc.origin);
        var arg_index = worker_args.len;
        while (arg_index > 0) {
            arg_index -= 1;
            if (worker_call_args[arg_index] == proc.arg_locals.items[arg_index]) continue;
            if (concrete_function != null) {
                const concrete_arg = concrete_arg_reps[arg_index];
                const concrete_local = try proc.addFrameLocalForRep(concrete_arg);
                continuation = try proc.assignPlannedCallBoundary(
                    worker_call_args[arg_index],
                    concrete_local,
                    worker_args[arg_index].rep,
                    concrete_arg,
                    continuation,
                );
                const detached = try proc.enterDetachedDescriptorScope(requirement_scope);
                try proc.bindFrameRequirementDescriptors(frame_requirement_descs, frame_requirement_locals, true);
                const to_concrete = try proc.assignPlannedCallBoundary(
                    concrete_local,
                    proc.arg_locals.items[arg_index],
                    concrete_arg,
                    requirement_args[arg_index].rep,
                    continuation,
                );
                continuation = try proc.leaveDetachedDescriptorScope(detached, to_concrete);
                continue;
            }
            continuation = try proc.assignPlannedCallBoundary(
                worker_call_args[arg_index],
                proc.arg_locals.items[arg_index],
                worker_args[arg_index].rep,
                requirement_args[arg_index].rep,
                continuation,
            );
        }
        continuation = try proc.prependStaticDescriptorMaterializationsForSlotsWithSources(
            &job.slot_sources,
            &job.desc_context,
            continuation,
        );
        continuation = try proc.prependWorkerArgumentDescriptorInitializers(continuation);
        if (proc.arg_locals.items.len != job.arg_local_count) {
            boxyLowerInvariant("static dictionary method adapter body added arguments after its header was reserved");
        }

        const proc_spec = self.result.store.getProcSpecPtr(job.proc_id);
        proc_spec.body = continuation;
        const return_desc = try self.returnDescriptorInfoForBody(
            continuation,
            job.args_span,
            self.result.store.getLocal(result).boxy_desc,
            &proc.frame_locals,
        );
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        proc_spec.frame_locals = frame_span;
        proc_spec.ret_desc = return_desc.external;
        proc_spec.runtime_ret_desc = return_desc.runtime_local;
        proc_spec.stack_probe = self.stackProbeForProc(job.args_span, frame_span, job.ret_layout);
    }

    fn staticMethodDescriptorMappingForWorker(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        requirement_fn_ty: Plan.CheckedTypeIdentity,
        descriptor_sources: *const StaticDescriptorSourceMap,
    ) Allocator.Error!StaticMethodDescriptorMapping {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const worker_function = self.staticMethodFunctionForRep(worker.rep) orelse
            boxyLowerInvariant("static boxy dictionary method worker was not a function");
        const requirement_rep = self.plan.repForSourceType(requirement_fn_ty) orelse
            boxyLowerInvariant("static boxy dictionary method requirement type was not analyzed");
        const requirement_function = self.staticMethodFunctionForRep(requirement_rep) orelse
            boxyLowerInvariant("static boxy dictionary method requirement was not a function");
        if (worker_function.arg_count != requirement_function.arg_count) {
            boxyLowerInvariant("static boxy dictionary method adapter saw mismatched worker and requirement arity");
        }

        var mapping = StaticMethodDescriptorMapping{};
        errdefer mapping.deinit(self.allocator);
        try self.collectStaticMethodCallDescIndexesForFunction(requirement_function, &mapping.indexes);
        try mapping.reps.ensureLen(self.allocator, mapping.indexes.entries.items.len);
        try self.collectStaticMethodCallDescSourcesForFunction(
            worker_function,
            requirement_function,
            self.plan.hiddenDescriptorParamSlice(worker.hidden_descs),
            descriptor_sources,
            &mapping.indexes,
            &mapping.reps,
            &mapping.hidden_sources,
        );
        return mapping;
    }

    fn staticMethodDescriptorMappingForEvidence(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        requirement_fn_ty: Plan.CheckedTypeIdentity,
        worker_desc_args: Plan.Span,
        requirement_desc_sources: Plan.Span,
        hidden_desc_sources: Plan.Span,
    ) Allocator.Error!StaticMethodDescriptorMapping {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const requirement_rep = self.plan.repForSourceType(requirement_fn_ty) orelse
            boxyLowerInvariant("planned dictionary method requirement type was not analyzed");
        const requirement_function = self.staticMethodFunctionForRep(requirement_rep) orelse
            boxyLowerInvariant("planned dictionary method requirement was not a function");

        var mapping = StaticMethodDescriptorMapping{};
        errdefer mapping.deinit(self.allocator);
        try self.collectStaticMethodCallDescIndexesForFunction(requirement_function, &mapping.indexes);
        const requirement_sources = self.plan.dictionaryMethodDescriptorSourceSlice(requirement_desc_sources);
        if (mapping.indexes.entries.items.len != requirement_sources.len) {
            boxyLowerInvariant("planned dictionary method requirement descriptor map had the wrong length");
        }
        try mapping.reps.ensureLen(self.allocator, requirement_sources.len);
        for (requirement_sources, 0..) |source, index| {
            try mapping.reps.put(self.allocator, @intCast(index), source.rep);
        }

        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        const worker_sources = self.plan.directCallHiddenDescriptorArgSlice(worker_desc_args);
        const planned_hidden_sources = self.plan.dictionaryMethodHiddenDescriptorSourceSlice(hidden_desc_sources);
        if (params.len != worker_sources.len or params.len != planned_hidden_sources.len) {
            boxyLowerInvariant("planned dictionary worker descriptor map had the wrong length");
        }
        for (params, worker_sources, planned_hidden_sources) |param, source, planned_source| {
            if (param.desc != source.worker_desc or param.rep != source.worker_rep) {
                boxyLowerInvariant("planned dictionary worker descriptor map disagreed with worker parameter order");
            }
            try mapping.hidden_sources.put(self.allocator, param.desc, switch (planned_source) {
                .slot => |slot_index| .{ .slot = slot_index },
                .call => |call_index| .{ .call = call_index },
                .argument => |arg_index| .{ .argument = arg_index },
            });
        }
        return mapping;
    }

    fn staticMethodHiddenDescSourcesForWorker(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        descriptor_sources: *const StaticDescriptorSourceMap,
        mapping: *const StaticMethodDescriptorMapping,
        frame_requirement_descs: []const FrameRequirementDescriptor,
    ) Allocator.Error!LIR.BoxySpan {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        if (params.len == 0 and frame_requirement_descs.len == 0) return .{};

        const start: u32 = @intCast(self.result.boxy_method_hidden_desc_sources.items.len);
        for (params, 0..) |param, slot_index| {
            const static_source = descriptor_sources.get(param.desc);
            const adapter_source = mapping.hidden_sources.get(param.desc);
            if (adapter_source) |source| {
                try self.result.boxy_method_hidden_desc_sources.append(self.allocator, source);
            } else if (static_source != null) {
                try self.result.boxy_method_hidden_desc_sources.append(self.allocator, .{ .slot = @intCast(slot_index) });
            } else {
                boxyLowerInvariant("static boxy dictionary method descriptor was neither static nor mapped to a call descriptor");
            }
        }
        // The method adapter receives the frame-supplied requirement
        // descriptors after the worker's own.
        for (frame_requirement_descs) |extra| {
            try self.result.boxy_method_hidden_desc_sources.append(self.allocator, .{ .slot = extra.slot });
        }
        return .{ .start = start, .len = @intCast(params.len + frame_requirement_descs.len) };
    }

    fn collectStaticMethodRequirementDescriptorSources(
        self: *ProcedureBuilder,
        mapping: *const StaticMethodDescriptorMapping,
        sources: *StaticDescriptorSourceMap,
    ) Allocator.Error!void {
        for (mapping.indexes.entries.items) |entry| {
            const source_rep = mapping.reps.reps.items[entry.index] orelse
                boxyLowerInvariant("static boxy dictionary method requirement descriptor had no source representation");
            try sources.put(self.allocator, entry.desc, source_rep);
        }
    }

    fn staticMethodFunctionForRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) ?StaticMethodFunction {
        var current = rep_id;
        while (true) {
            const rep = self.plan.representations.items[@backingInt(current)];
            if (rep.kind == .alias) {
                current = self.singleChildRepForDesc(current, .alias_backing) orelse
                    boxyLowerInvariant("static boxy dictionary method alias had no backing child");
            } else if (rep.kind == .nominal) {
                switch (rep.kind.nominal) {
                    .transparent => current = self.singleChildRepForDesc(current, .nominal_backing) orelse
                        boxyLowerInvariant("static boxy dictionary method transparent nominal had no backing child"),
                    .opaque_nominal, .builtin_other => return null,
                }
            } else if (rep.kind == .erased_callable) {
                const children = self.plan.childSlice(rep.children);
                var args_start: ?u32 = null;
                var arg_count: u32 = 0;
                var ret: ?Plan.TypeRepId = null;
                for (children, 0..) |child, i| {
                    if (child.role == .function_arg) {
                        if (args_start == null) args_start = @intCast(i);
                        arg_count += 1;
                    } else if (child.role == .function_ret) {
                        ret = child.rep;
                    }
                }
                return .{
                    .rep = current,
                    .args_start = args_start orelse 0,
                    .arg_count = arg_count,
                    .ret = ret orelse boxyLowerInvariant("static boxy dictionary method function had no return child"),
                };
            } else {
                return null;
            }
        }
    }

    fn collectStaticMethodCallDescIndexesForFunction(
        self: *ProcedureBuilder,
        function: StaticMethodFunction,
        indexes: *StaticMethodCallDescIndexMap,
    ) Allocator.Error!void {
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.allocator);
        defer seen_descs.deinit();

        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        for (children[function.args_start..][0..function.arg_count]) |child| {
            try self.collectStaticMethodCallDescIndexesForRep(child.rep, indexes, &seen_reps, &seen_descs);
        }
        try self.collectStaticMethodCallDescIndexesForRep(function.ret, indexes, &seen_reps, &seen_descs);
    }

    /// Index, in pre-order, the descriptors `root` carries.
    fn collectStaticMethodCallDescIndexesForRep(
        self: *ProcedureBuilder,
        root: Plan.TypeRepId,
        indexes: *StaticMethodCallDescIndexMap,
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |rep_id| {
            const rep_entry = try seen_reps.getOrPut(rep_id);
            if (rep_entry.found_existing) continue;

            const rep = self.plan.representations.items[@backingInt(rep_id)];
            if (rep.descriptor) |desc| {
                const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
                const identity_desc = self.plan.representations.items[@backingInt(identity_rep)].descriptor orelse desc;
                const desc_entry = try seen_descs.getOrPut(identity_desc);
                if (!desc_entry.found_existing) {
                    try indexes.put(self.allocator, desc);
                }
            }

            if (rep.kind == .erased_callable) continue;
            const children = self.plan.childSlice(rep.children);
            var index = children.len;
            while (index > 0) {
                index -= 1;
                if (!self.plan.childCarriesHiddenDescriptor(rep_id, children[index])) continue;
                try pending.append(self.allocator, children[index].rep);
            }
        }
    }

    fn collectStaticMethodCallDescSourcesForFunction(
        self: *ProcedureBuilder,
        worker_function: StaticMethodFunction,
        requirement_function: StaticMethodFunction,
        params: []const Plan.HiddenDescriptorParam,
        descriptor_sources: *const StaticDescriptorSourceMap,
        call_desc_indexes: *const StaticMethodCallDescIndexMap,
        call_desc_reps: *StaticMethodCallDescRepMap,
        call_sources: *StaticMethodCallDescSourceMap,
    ) Allocator.Error!void {
        if (worker_function.arg_count != requirement_function.arg_count) {
            boxyLowerInvariant("static dictionary method descriptor source mapping saw mismatched function arity");
        }

        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();

        const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_function.rep)].children);
        const requirement_children = self.plan.childSlice(self.plan.representations.items[@backingInt(requirement_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
        const requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
        for (worker_args, requirement_args) |worker_arg, requirement_arg| {
            try self.collectStaticMethodCallDescSourcesForRep(
                worker_arg.rep,
                requirement_arg.rep,
                params,
                descriptor_sources,
                call_desc_indexes,
                call_desc_reps,
                call_sources,
                &seen,
            );
        }
        try self.collectStaticMethodCallDescSourcesForRep(
            worker_function.ret,
            requirement_function.ret,
            params,
            descriptor_sources,
            call_desc_indexes,
            call_desc_reps,
            call_sources,
            &seen,
        );
    }

    /// The fixed inputs of one static method call's descriptor source walk.
    const StaticMethodCallDescWalk = struct {
        params: []const Plan.HiddenDescriptorParam,
        descriptor_sources: *const StaticDescriptorSourceMap,
        call_desc_indexes: *const StaticMethodCallDescIndexMap,
        call_desc_reps: *StaticMethodCallDescRepMap,
        call_sources: *StaticMethodCallDescSourceMap,
        seen: *std.AutoHashMap(u64, void),
    };

    /// A worker and requirement representation pair whose children are
    /// being aligned.
    const StaticMethodCallDescFrame = struct {
        worker_rep_id: Plan.TypeRepId,
        requirement_rep_id: Plan.TypeRepId,
        phase: enum {
            /// An empty worker row against the requirement's children.
            requirement_under_empty_worker,
            /// The worker's children against an empty requirement row.
            worker_under_empty_requirement,
            worker_children,
            requirement_children,
        },
        wrapper_bindings: Plan.CallWrapperBindings = .{},
        structure_call_rep_id: Plan.TypeRepId = undefined,
        through_wrapper: bool = false,
        index: usize = 0,
    };

    fn collectStaticMethodCallDescSourcesForRep(
        self: *ProcedureBuilder,
        worker_rep_id: Plan.TypeRepId,
        requirement_rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        descriptor_sources: *const StaticDescriptorSourceMap,
        call_desc_indexes: *const StaticMethodCallDescIndexMap,
        call_desc_reps: *StaticMethodCallDescRepMap,
        call_sources: *StaticMethodCallDescSourceMap,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        const walk = StaticMethodCallDescWalk{
            .params = params,
            .descriptor_sources = descriptor_sources,
            .call_desc_indexes = call_desc_indexes,
            .call_desc_reps = call_desc_reps,
            .call_sources = call_sources,
            .seen = seen,
        };
        var frames: std.ArrayList(StaticMethodCallDescFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.wrapper_bindings.deinit(self.allocator);
            frames.deinit(self.allocator);
        }
        try self.enterStaticMethodCallDescPair(&walk, &frames, worker_rep_id, requirement_rep_id);
        while (frames.items.len != 0) {
            const next = try self.nextStaticMethodCallDescPair(&walk, &frames.items[frames.items.len - 1]) orelse {
                var done = frames.pop().?;
                done.wrapper_bindings.deinit(self.allocator);
                continue;
            };
            try self.enterStaticMethodCallDescPair(&walk, &frames, next[0], next[1]);
        }
    }

    /// Record one pair's descriptor sources and push the frame that aligns
    /// its children, unless the pair was already walked.
    fn enterStaticMethodCallDescPair(
        self: *ProcedureBuilder,
        walk: *const StaticMethodCallDescWalk,
        frames: *std.ArrayList(StaticMethodCallDescFrame),
        worker_rep_id: Plan.TypeRepId,
        requirement_rep_id: Plan.TypeRepId,
    ) Allocator.Error!void {
        const seen_key = (@as(u64, @backingInt(worker_rep_id)) << 32) | @as(u64, @backingInt(requirement_rep_id));
        const seen_entry = try walk.seen.getOrPut(seen_key);
        if (seen_entry.found_existing) return;

        const worker_rep = self.plan.representations.items[@backingInt(worker_rep_id)];
        const requirement_rep = self.plan.representations.items[@backingInt(requirement_rep_id)];

        if (requirement_rep.descriptor) |requirement_desc| {
            const call_index = walk.call_desc_indexes.get(requirement_desc) orelse
                boxyLowerInvariant("static dictionary method call descriptor mapping referenced an unindexed generic descriptor");
            const call_source_rep = if (worker_rep.descriptor) |worker_desc|
                walk.descriptor_sources.get(worker_desc) orelse worker_rep_id
            else
                worker_rep_id;
            try walk.call_desc_reps.put(self.allocator, call_index, call_source_rep);
        }

        if (worker_rep.descriptor) |worker_desc| {
            const static_source = walk.descriptor_sources.get(worker_desc);
            const source_needs_runtime_instantiation = if (static_source) |source_rep|
                try self.repQuery().repSubtreeHasDescriptor(source_rep)
            else
                true;
            if (hiddenDescriptorParamContains(walk.params, worker_desc) and source_needs_runtime_instantiation) {
                if (requirement_rep.descriptor) |requirement_desc| {
                    const call_index = walk.call_desc_indexes.get(requirement_desc) orelse
                        boxyLowerInvariant("static dictionary method call descriptor mapping referenced an unindexed generic descriptor");
                    try walk.call_sources.put(self.allocator, worker_desc, .{ .call = call_index });
                } else {
                    const slot_index = hiddenDescriptorParamIndex(walk.params, worker_desc) orelse
                        boxyLowerInvariant("static dictionary method worker descriptor was missing from its hidden parameter list");
                    try walk.call_sources.put(self.allocator, worker_desc, .{ .slot = slot_index });
                }
            }
        }

        if (requirement_rep.kind == .erased_callable) return;

        if (worker_rep.kind == .empty_tag_union and requirement_rep.children.len != 0) {
            try frames.append(self.allocator, .{ .worker_rep_id = worker_rep_id, .requirement_rep_id = requirement_rep_id, .phase = .requirement_under_empty_worker });
            return;
        }

        if (worker_rep.children.len == 0) return;

        // Children align with the structure the requirement's value stands for.
        var wrapper_bindings: Plan.CallWrapperBindings = .{};
        errdefer wrapper_bindings.deinit(self.allocator);
        const structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(self.allocator, worker_rep_id, requirement_rep_id, &wrapper_bindings);
        const structure_rep = self.plan.representations.items[@backingInt(structure_call_rep_id)];
        try frames.append(self.allocator, .{
            .worker_rep_id = worker_rep_id,
            .requirement_rep_id = requirement_rep_id,
            .phase = if (structure_rep.kind == .empty_tag_union) .worker_under_empty_requirement else .worker_children,
            .wrapper_bindings = wrapper_bindings,
            .structure_call_rep_id = structure_call_rep_id,
            .through_wrapper = structure_call_rep_id != requirement_rep_id,
        });
    }

    /// The next child pair `frame` aligns, or null once its children are
    /// aligned.
    fn nextStaticMethodCallDescPair(
        self: *ProcedureBuilder,
        walk: *const StaticMethodCallDescWalk,
        frame: *StaticMethodCallDescFrame,
    ) Allocator.Error!?[2]Plan.TypeRepId {
        const worker_rep_id = frame.worker_rep_id;
        const requirement_rep_id = frame.requirement_rep_id;
        const worker_rep = self.plan.representations.items[@backingInt(worker_rep_id)];
        const requirement_rep = self.plan.representations.items[@backingInt(requirement_rep_id)];
        const worker_children = self.plan.childSlice(worker_rep.children);
        const requirement_children = self.plan.childSlice(requirement_rep.children);
        while (true) switch (frame.phase) {
            .requirement_under_empty_worker => {
                while (frame.index < requirement_children.len) {
                    const requirement_child = requirement_children[frame.index];
                    frame.index += 1;
                    if (!self.plan.childCarriesHiddenDescriptor(requirement_rep_id, requirement_child)) continue;
                    if (!try self.repQuery().repSubtreeHasDescriptor(requirement_child.rep)) continue;
                    return .{ worker_rep_id, requirement_child.rep };
                }
                return null;
            },
            .worker_under_empty_requirement => {
                while (frame.index < worker_children.len) {
                    const worker_child = worker_children[frame.index];
                    frame.index += 1;
                    if (!self.plan.childCarriesHiddenDescriptor(worker_rep_id, worker_child)) continue;
                    if (!try self.repSubtreeHasCallSuppliedDescriptor(worker_child.rep, walk.params, walk.descriptor_sources)) continue;
                    return .{ worker_child.rep, requirement_rep_id };
                }
                return null;
            },
            .worker_children => {
                const structure_call_rep_id = frame.structure_call_rep_id;
                const requirement_structure_children = self.plan.childSlice(self.plan.representations.items[@backingInt(structure_call_rep_id)].children);
                while (frame.index < worker_children.len) {
                    const worker_child = worker_children[frame.index];
                    frame.index += 1;
                    if (!self.plan.childCarriesHiddenDescriptor(worker_rep_id, worker_child)) continue;
                    const has_call_supplied_desc = try self.repSubtreeHasCallSuppliedDescriptor(worker_child.rep, walk.params, walk.descriptor_sources);
                    if (self.namedQuery().rowInstantiationTarget(worker_rep_id, structure_call_rep_id, worker_child)) |structure_row_target| {
                        const row_target = if (structure_row_target == structure_call_rep_id)
                            requirement_rep_id
                        else
                            Plan.structureChildCallRep(&frame.wrapper_bindings, frame.through_wrapper, structure_row_target);
                        return .{ worker_child.rep, row_target };
                    }
                    if (self.namedQuery().findMatchingChildByRole(requirement_structure_children, worker_child)) |requirement_child| {
                        return .{ worker_child.rep, Plan.structureChildCallRep(&frame.wrapper_bindings, frame.through_wrapper, requirement_child.rep) };
                    }
                    if (self.repQuery().structuralWrapperBackingRep(requirement_rep_id)) |requirement_backing| {
                        const backing_children = self.plan.childSlice(self.plan.representations.items[@backingInt(requirement_backing)].children);
                        if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |requirement_child| {
                            return .{ worker_child.rep, requirement_child.rep };
                        }
                    }
                    if (!has_call_supplied_desc) continue;
                    if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(worker_rep_id, worker_child)) {
                        return .{ worker_child.rep, requirement_rep_id };
                    }
                    if (worker_child.role == .tag_ext and requirement_structure_children.len == 0 and requirement_rep.descriptor != null) {
                        return .{ worker_child.rep, requirement_rep_id };
                    }
                    boxyLowerInvariant("static dictionary method call descriptor mapping saw mismatched child roles");
                }
                frame.phase = .requirement_children;
                frame.index = 0;
            },
            .requirement_children => {
                while (frame.index < requirement_children.len) {
                    const requirement_child = requirement_children[frame.index];
                    frame.index += 1;
                    if (!self.plan.childCarriesHiddenDescriptor(requirement_rep_id, requirement_child)) continue;
                    if (!try self.repSubtreeHasUnmappedCallDesc(requirement_child.rep, walk.call_desc_indexes, walk.call_desc_reps)) continue;
                    if (self.namedQuery().findMatchingChildByRole(worker_children, requirement_child)) |worker_child| {
                        return .{ worker_child.rep, requirement_child.rep };
                    }
                    if (self.repQuery().structuralWrapperBackingRep(worker_rep_id)) |worker_backing| {
                        const backing_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_backing)].children);
                        if (self.namedQuery().findMatchingChildByRole(backing_children, requirement_child)) |worker_child| {
                            return .{ worker_child.rep, requirement_child.rep };
                        }
                    }
                    if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(requirement_rep_id, requirement_child)) {
                        return .{ worker_rep_id, requirement_child.rep };
                    }
                    if (requirement_child.role == .tag_ext and worker_children.len == 0 and worker_rep.descriptor != null) {
                        return .{ worker_rep_id, requirement_child.rep };
                    }
                    boxyLowerInvariant("static dictionary method call descriptor alignment saw mismatched child roles");
                }
                return null;
            },
        };
    }

    fn repSubtreeHasUnmappedCallDesc(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        indexes: *const StaticMethodCallDescIndexMap,
        reps: *const StaticMethodCallDescRepMap,
    ) Allocator.Error!bool {
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, rep_id);
        while (pending.pop()) |current| {
            if ((try seen.getOrPut(current)).found_existing) continue;
            const rep = self.plan.representations.items[@backingInt(current)];
            if (rep.descriptor) |desc| {
                const index = indexes.get(desc) orelse
                    boxyLowerInvariant("static dictionary method call descriptor mapping referenced an unindexed generic descriptor");
                if (reps.reps.items[index] == null) return true;
            }
            if (rep.kind == .erased_callable) continue;
            for (self.plan.childSlice(rep.children)) |child| {
                if (!self.plan.childCarriesHiddenDescriptor(current, child)) continue;
                try pending.append(self.allocator, child.rep);
            }
        }
        return false;
    }

    fn repSubtreeHasCallSuppliedDescriptor(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        descriptor_sources: *const StaticDescriptorSourceMap,
    ) Allocator.Error!bool {
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.allocator);
        defer seen.deinit();
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, rep_id);
        while (pending.pop()) |current| {
            if ((try seen.getOrPut(current)).found_existing) continue;
            const rep = self.plan.representations.items[@backingInt(current)];
            if (rep.descriptor) |desc| {
                if (hiddenDescriptorParamContains(params, desc) and descriptor_sources.get(desc) == null) return true;
            }
            for (self.plan.childSlice(rep.children)) |child| {
                if (self.plan.childIsSharedBackingTemplate(current, child)) continue;
                try pending.append(self.allocator, child.rep);
            }
        }
        return false;
    }

    fn collectStaticDictionaryDescriptorSources(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        source_rep: Plan.TypeRepId,
        requirement_owner_type: Plan.CheckedTypeIdentity,
        requirement_fn_ty: Plan.CheckedTypeIdentity,
        sources: *StaticDescriptorSourceMap,
    ) Allocator.Error!void {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const params = self.plan.hiddenDescriptorParamSlice(worker.hidden_descs);

        const worker_function = self.staticMethodFunctionForRep(worker.rep) orelse
            boxyLowerInvariant("static boxy dictionary method worker with hidden descriptors was not a function");
        const requirement_rep = self.plan.repForSourceType(requirement_fn_ty) orelse
            boxyLowerInvariant("static boxy dictionary method requirement type was not analyzed");
        const requirement_function = self.staticMethodFunctionForRep(requirement_rep) orelse
            boxyLowerInvariant("static boxy dictionary method requirement was not a function");
        if (worker_function.arg_count != requirement_function.arg_count) {
            boxyLowerInvariant("static boxy dictionary descriptor source mapping saw mismatched worker and requirement arity");
        }
        const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
        const requirement_children = self.plan.childSlice(self.plan.representations.items[@backingInt(requirement_function.rep)].children);
        const requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
        const owner_requirement_rep = self.plan.repForSourceType(requirement_owner_type) orelse
            boxyLowerInvariant("static boxy dictionary requirement owner type was not analyzed");
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();

        for (worker_args, requirement_args) |worker_arg, requirement_arg| {
            try self.collectStaticDictionaryDescriptorSourcesForAlignedRep(
                worker_arg.rep,
                requirement_arg.rep,
                owner_requirement_rep,
                source_rep,
                params,
                .all_worker_descriptors,
                sources,
                &seen,
            );
        }
        try self.collectStaticDictionaryDescriptorSourcesForAlignedRep(
            worker_function.ret,
            requirement_function.ret,
            owner_requirement_rep,
            source_rep,
            params,
            .all_worker_descriptors,
            sources,
            &seen,
        );
    }

    /// Record, in pre-order, the static descriptor sources a worker
    /// representation aligned with a dictionary requirement reaches.
    fn collectStaticDictionaryDescriptorSourcesForAlignedRep(
        self: *ProcedureBuilder,
        root_worker_rep_id: Plan.TypeRepId,
        root_requirement_rep_id: Plan.TypeRepId,
        owner_requirement_rep_id: Plan.TypeRepId,
        source_rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        binding_scope: StaticDescriptorBindingScope,
        sources: *StaticDescriptorSourceMap,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList([2]Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ root_worker_rep_id, root_requirement_rep_id });
        while (pending.pop()) |pair| {
            const worker_rep_id = pair[0];
            const requirement_rep_id = pair[1];
            const identity_requirement = self.repQuery().descriptorArgumentIdentityRep(requirement_rep_id);
            const identity_owner = self.repQuery().descriptorArgumentIdentityRep(owner_requirement_rep_id);
            if (identity_requirement == identity_owner) {
                var source_seen = std.AutoHashMap(u64, void).init(self.allocator);
                defer source_seen.deinit();
                try self.collectStaticDescriptorSourcesForWorkerSource(worker_rep_id, source_rep_id, params, binding_scope, sources, &source_seen);
                continue;
            }
            if (binding_scope == .all_worker_descriptors and !try self.repQuery().repSubtreeHasDescriptor(requirement_rep_id)) {
                var source_seen = std.AutoHashMap(u64, void).init(self.allocator);
                defer source_seen.deinit();
                try self.collectStaticDescriptorSourcesForWorkerSource(worker_rep_id, requirement_rep_id, params, binding_scope, sources, &source_seen);
                continue;
            }

            const seen_key = (@as(u64, @backingInt(worker_rep_id)) << 32) | @as(u64, @backingInt(requirement_rep_id));
            const seen_entry = try seen.getOrPut(seen_key);
            if (seen_entry.found_existing) continue;
            try self.pushAlignedDescriptorSourceChildren(&pending, worker_rep_id, requirement_rep_id);
        }
    }

    /// Queue, so that they are visited in child order, the child pairs of a
    /// worker representation aligned with a source representation.
    fn pushAlignedDescriptorSourceChildren(
        self: *ProcedureBuilder,
        pending: *std.ArrayList([2]Plan.TypeRepId),
        worker_rep_id: Plan.TypeRepId,
        source_rep_id: Plan.TypeRepId,
    ) Allocator.Error!void {
        const worker_rep = self.plan.representations.items[@backingInt(worker_rep_id)];
        if (worker_rep.children.len == 0) return;

        const source_rep = self.plan.representations.items[@backingInt(source_rep_id)];
        // Children align with the structure the source's value stands for.
        var wrapper_bindings: Plan.CallWrapperBindings = .{};
        defer wrapper_bindings.deinit(self.allocator);
        const structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(self.allocator, worker_rep_id, source_rep_id, &wrapper_bindings);
        const through_wrapper = structure_call_rep_id != source_rep_id;
        const structure_rep = self.plan.representations.items[@backingInt(structure_call_rep_id)];
        const children_start = pending.items.len;
        defer std.mem.reverse([2]Plan.TypeRepId, pending.items[children_start..]);

        const worker_children = self.plan.childSlice(worker_rep.children);
        if (structure_rep.kind == .empty_tag_union) {
            for (worker_children) |worker_child| {
                if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
                try pending.append(self.allocator, .{ worker_child.rep, source_rep_id });
            }
            return;
        }

        const source_children = self.plan.childSlice(structure_rep.children);
        for (worker_children) |worker_child| {
            if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
            if (self.namedQuery().rowInstantiationTarget(worker_rep_id, structure_call_rep_id, worker_child)) |structure_row_target| {
                const row_target = if (structure_row_target == structure_call_rep_id)
                    source_rep_id
                else
                    Plan.structureChildCallRep(&wrapper_bindings, through_wrapper, structure_row_target);
                try pending.append(self.allocator, .{ worker_child.rep, row_target });
                continue;
            }
            if (self.namedQuery().findMatchingChildByRole(source_children, worker_child)) |source_child| {
                try pending.append(self.allocator, .{ worker_child.rep, Plan.structureChildCallRep(&wrapper_bindings, through_wrapper, source_child.rep) });
                continue;
            }
            if (self.repQuery().structuralWrapperBackingRep(source_rep_id)) |source_backing| {
                const backing_children = self.plan.childSlice(self.plan.representations.items[@backingInt(source_backing)].children);
                if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |source_child| {
                    try pending.append(self.allocator, .{ worker_child.rep, source_child.rep });
                    continue;
                }
            }
            if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(worker_rep_id, worker_child)) {
                try pending.append(self.allocator, .{ worker_child.rep, source_rep_id });
                continue;
            }
            if (worker_child.role == .tag_ext and source_children.len == 0 and source_rep.descriptor != null) {
                try pending.append(self.allocator, .{ worker_child.rep, source_rep_id });
                continue;
            }
        }
    }

    /// Record, in pre-order, the static descriptor source of each worker
    /// descriptor a worker representation aligned with a source reaches.
    fn collectStaticDescriptorSourcesForWorkerSource(
        self: *ProcedureBuilder,
        root_worker_rep_id: Plan.TypeRepId,
        root_source_rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        binding_scope: StaticDescriptorBindingScope,
        sources: *StaticDescriptorSourceMap,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        var pending: std.ArrayList([2]Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, .{ root_worker_rep_id, root_source_rep_id });
        while (pending.pop()) |pair| {
            const identity_worker = self.descriptorStorageRep(pair[0]);
            const identity_source = self.repQuery().descriptorArgumentIdentityRep(pair[1]);
            const seen_key = (@as(u64, @backingInt(identity_worker)) << 32) | @as(u64, @backingInt(identity_source));
            const entry = try seen.getOrPut(seen_key);
            if (entry.found_existing) continue;

            const worker_rep = self.plan.representations.items[@backingInt(identity_worker)];
            if (worker_rep.descriptor) |worker_desc| {
                if (binding_scope == .all_worker_descriptors or hiddenDescriptorParamContains(params, worker_desc)) {
                    try sources.put(self.allocator, worker_desc, identity_source);
                }
            }
            try self.pushAlignedDescriptorSourceChildren(&pending, identity_worker, identity_source);
        }
    }

    /// The building frame's descriptor for this position, when the position
    /// (through the context's nominal bindings) or the source it describes
    /// is a requirement that frame supplies.
    fn frameDescriptorRefForWorkerRep(
        self: *ProcedureBuilder,
        worker_rep_id: Plan.TypeRepId,
        source_rep_id: ?Plan.TypeRepId,
        descriptor_sources: *const StaticDescriptorSourceMap,
        context: *StaticDescInstantiationContext,
    ) ?LIR.BoxyDescRef {
        const outer_env = context.env;
        defer context.env = outer_env;
        var worker = self.descriptorStorageRep(worker_rep_id);
        var source = source_rep_id;
        while (context.bound(worker)) |binding| {
            worker = self.descriptorStorageRep(binding.actual);
            source = binding.source;
            context.env = binding.env;
        }
        if (frameDescriptorRefForRequirement(context.frame_descriptors, self.plan.representations.items[@backingInt(worker)].descriptor)) |ref| return ref;
        const effective_source = self.effectiveStaticDescriptorSource(worker, source, descriptor_sources) orelse return null;
        return frameDescriptorRefForRequirement(
            context.frame_descriptors,
            self.plan.representations.items[@backingInt(self.descriptorStorageRep(effective_source))].descriptor,
        );
    }

    fn effectiveStaticDescriptorSource(
        self: *const ProcedureBuilder,
        worker_rep_id: Plan.TypeRepId,
        source_rep_id: ?Plan.TypeRepId,
        descriptor_sources: *const StaticDescriptorSourceMap,
    ) ?Plan.TypeRepId {
        const worker_rep = self.plan.representations.items[@backingInt(worker_rep_id)];
        var current = if (worker_rep.descriptor) |desc|
            descriptor_sources.get(desc) orelse source_rep_id orelse return null
        else
            source_rep_id orelse return null;

        while (true) {
            const identity = self.descriptorIdentityRep(current);
            const source_rep = self.plan.representations.items[@backingInt(identity)];
            const desc = source_rep.descriptor orelse return current;
            const mapped = descriptor_sources.get(desc) orelse return current;
            if (mapped == current or mapped == identity) return current;
            current = mapped;
        }
    }

    /// Declared fields ordered by their identity (alphabetical) index. Nested
    /// descriptor refs are consumed by materialization in ascending identity
    /// index order, so they must be produced in that order regardless of the
    /// declaration order the fields are stored in. The returned slice is owned
    /// by the caller.
    fn declaredFieldsInLayoutOrder(
        self: *ProcedureBuilder,
        fields: []const Plan.DeclaredField,
    ) Allocator.Error![]Plan.DeclaredField {
        const ordered = try self.allocator.alloc(Plan.DeclaredField, fields.len);
        @memcpy(ordered, fields);
        std.mem.sort(Plan.DeclaredField, ordered, {}, struct {
            fn lessThan(_: void, a: Plan.DeclaredField, b: Plan.DeclaredField) bool {
                return a.index < b.index;
            }
        }.lessThan);
        return ordered;
    }

    fn matchingInstantiationSource(
        self: *ProcedureBuilder,
        source_children: []const Plan.RepChild,
        worker_child: Plan.RepChild,
    ) Allocator.Error!?Plan.TypeRepId {
        if (source_children.len == 0) return null;
        if (self.namedQuery().findMatchingChildByRole(source_children, worker_child)) |source_child| return source_child.rep;
        return null;
    }

    fn matchingTagPayloadInstantiationSource(
        _: *ProcedureBuilder,
        source_payloads: []const Plan.RepChild,
        worker_child: Plan.RepChild,
    ) ?Plan.TypeRepId {
        if (worker_child.role != .tag_payload) {
            boxyLowerInvariant("boxy tag descriptor payload had a non-payload child role");
        }
        const worker_index = worker_child.role.tag_payload.index;
        var found: ?Plan.TypeRepId = null;
        for (source_payloads) |source_child| {
            if (source_child.role != .tag_payload) {
                boxyLowerInvariant("source-mapped boxy tag descriptor payload had a non-payload child role");
            }
            const source_index = source_child.role.tag_payload.index;
            if (source_index != worker_index) continue;
            if (found != null) boxyLowerInvariant("source-mapped boxy tag descriptor had duplicate payload indexes");
            found = source_child.rep;
        }
        return found;
    }

    fn matchingDeclaredFieldInstantiationSource(
        self: *ProcedureBuilder,
        source_rep_id: ?Plan.TypeRepId,
        worker_field: Plan.DeclaredField,
    ) Allocator.Error!?Plan.TypeRepId {
        var current = source_rep_id orelse return null;
        while (true) {
            const source_rep = self.plan.representations.items[@backingInt(current)];
            if (source_rep.declared_fields.len != 0) {
                for (self.plan.declaredFieldSlice(source_rep.declared_fields)) |source_field| {
                    if (source_field.index == worker_field.index) return source_field.rep;
                }
            }

            if (self.matchingRecordChildByDeclaredFieldIndex(self.plan.childSlice(source_rep.children), worker_field.index)) |source_child| {
                return source_child.rep;
            }
            if (try self.matchingChildByDeclaredFieldSourceType(self.plan.childSlice(source_rep.children), worker_field)) |source_child| {
                return source_child.rep;
            }

            current = self.repQuery().structuralWrapperBackingRep(current) orelse return null;
        }
    }

    fn matchingRecordChildByDeclaredFieldIndex(
        _: *ProcedureBuilder,
        children: []const Plan.RepChild,
        declared_index: u32,
    ) ?Plan.RepChild {
        var field_index: u32 = 0;
        for (children) |child| {
            if (child.role == .record_field) {
                if (field_index == declared_index) return child;
                field_index += 1;
            }
        }
        return null;
    }

    fn matchingChildByDeclaredFieldSourceType(
        self: *ProcedureBuilder,
        children: []const Plan.RepChild,
        worker_field: Plan.DeclaredField,
    ) Allocator.Error!?Plan.RepChild {
        var found: ?Plan.RepChild = null;
        for (children) |child| {
            if (!planTypeRefEql(child.source_type, worker_field.source_type)) continue;
            if (!try self.repQuery().repSubtreeHasDescriptor(child.rep)) continue;
            if (found != null) boxyLowerInvariant("declared-field descriptor source mapping found ambiguous checked-type children");
            found = child;
        }
        return found;
    }

    /// Whether this dictionary slot is fulfilled by the runtime's structural
    /// comparison: the requirement is the equality method and the source type
    /// resolves no `is_eq` method of its own (an anonymous structural type, or a
    /// nominal that neither declares nor derives equality).
    fn staticDictionarySlotIsStructural(
        self: *ProcedureBuilder,
        comptime structural_method: []const u8,
        rep_id: Plan.TypeRepId,
        requirement: Plan.DictionaryRequirement,
    ) bool {
        const requirement_module = procedureModuleById(self.modules, requirement.source_type.module);
        const method_text = requirement_module.canonical_names.methodNameText(requirement.fn_name);
        if (!std.mem.eql(u8, method_text, structural_method)) return false;
        const source_rep = self.plan.representations.items[@backingInt(rep_id)];
        const source_module = procedureModuleById(self.modules, source_rep.source_type.module);
        const owner = methodOwnerForProcedureType(source_module, source_rep.source_type.ty) orelse return true;
        return self.lookupMethodTarget(source_module, owner, requirement_module, requirement.fn_name) == null;
    }

    /// Bind each formal of `env` to its actual in `context`, so static
    /// descriptors of a generic nominal's backing describe that use.
    fn bindDerivedEnvInContext(self: *ProcedureBuilder, context: *StaticDescInstantiationContext, env: u32) Allocator.Error!void {
        for (self.plan.derivedEnvBindings(env)) |binding| {
            try context.bind(self.allocator, .{
                .formal = binding.formal,
                .actual = binding.actual,
                .source = null,
                // Environment actuals name no formal of the environment.
                .env = 0,
            });
        }
    }

    /// The frame values a derived procedure over `rep_id` receives from the
    /// frame that calls or builds it.
    fn derivedFrameShape(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        frame: ?Plan.WorkerPlanId,
        env: u32,
        kind: enum { slot, helper },
    ) Allocator.Error!DerivedFrameShape {
        const rep_desc = self.plan.representations.items[@backingInt(rep_id)].descriptor;
        // A slot's operand is described by the frame that builds it, and
        // inside a generic nominal's backing through the environment's
        // actuals instead. A recursive helper's operand is a generic backing
        // whose descriptor its caller passes.
        const operand_desc = switch (kind) {
            .slot => if (frame != null and env == 0) rep_desc else null,
            .helper => rep_desc,
        };
        if (frame == null) return .{ .operand_desc = operand_desc != null };
        var variables = std.ArrayList(Plan.TypeRepId).empty;
        errdefer variables.deinit(self.allocator);
        var visited = collections.DenseMap(Plan.TypeRepId, void).init(self.allocator);
        defer visited.deinit();
        try self.collectDerivedFrameVariables(rep_id, self.plan.derivedEnvBindings(env), &visited, &variables);
        // One descriptor per requirement: a variable described by the operand
        // or an earlier variable's requirement reads that descriptor.
        var kept: usize = 0;
        for (variables.items, 0..) |variable, index| {
            const desc = self.plan.representations.items[@backingInt(variable)].descriptor;
            if (operand_desc != null and std.meta.eql(desc, operand_desc)) continue;
            for (variables.items[0..kept]) |earlier| {
                if (std.meta.eql(self.plan.representations.items[@backingInt(earlier)].descriptor, desc)) break;
            } else {
                variables.items[kept] = variables.items[index];
                kept += 1;
            }
        }
        variables.shrinkRetainingCapacity(kept);
        var dictionaries = std.ArrayList(Plan.Span).empty;
        errdefer dictionaries.deinit(self.allocator);
        for (variables.items) |variable| {
            const span = self.plan.representations.items[@backingInt(variable)].dictionaries;
            if (span.len == 0) continue;
            for (dictionaries.items) |existing| {
                if (std.meta.eql(existing, span)) break;
            } else try dictionaries.append(self.allocator, span);
        }
        return .{
            .operand_desc = operand_desc != null,
            .variables = try variables.toOwnedSlice(self.allocator),
            .dictionaries = try dictionaries.toOwnedSlice(self.allocator),
        };
    }

    /// The type variables `rep_id` names outside nominal backing templates,
    /// each once, a formal of `bindings` naming what its actual names.
    /// Collect, in pre-order, the type variables `root` reaches under
    /// `bindings`.
    fn collectDerivedFrameVariables(
        self: *ProcedureBuilder,
        root: Plan.TypeRepId,
        bindings: []const Plan.DerivedBinding,
        visited: *collections.DenseMap(Plan.TypeRepId, void),
        variables: *std.ArrayList(Plan.TypeRepId),
    ) Allocator.Error!void {
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, root);
        while (pending.pop()) |rep_id| {
            if ((try visited.getOrPut(rep_id)).found_existing) continue;
            const rep = self.plan.representations.items[@backingInt(rep_id)];
            if (rep.kind == .dynamic) {
                if (Plan.derivedEnvActual(bindings, rep_id)) |actual| {
                    try pending.append(self.allocator, actual);
                } else if (rep.sealed_default) |sealed| {
                    try pending.append(self.allocator, sealed);
                } else {
                    try variables.append(self.allocator, rep_id);
                }
                continue;
            }
            const children_start = pending.items.len;
            if (rep.nominal_backing_arg_substitutions.len != 0) {
                var substitutions = self.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                while (substitutions.next()) |substitution| try pending.append(self.allocator, substitution.actual_rep);
            } else {
                for (self.plan.childSlice(rep.children)) |child| try pending.append(self.allocator, child.rep);
                for (self.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                    for (self.plan.childSlice(variant.payloads)) |payload| try pending.append(self.allocator, payload.rep);
                }
            }
            std.mem.reverse(Plan.TypeRepId, pending.items[children_start..]);
        }
    }

    const DerivedProcRequest = struct {
        method: Plan.DerivedMethod,
        rep: Plan.TypeRepId,
        second: union(enum) {
            rep: Plan.TypeRepId,
            layout: layout.Idx,
        },
        ret_layout: layout.Idx,
        frame: ?Plan.WorkerPlanId,
        env: u32,
        shape: DerivedFrameShape,
        /// A recursive helper: registered before its body lowers, so the
        /// union's recursion calls it, and its body expands the union itself.
        helper: bool = false,
    };

    /// A derived method procedure whose header and body the scheduler
    /// builds.
    const DerivedJob = struct {
        proc_id: LIR.LirProcSpecId,
        method: Plan.DerivedMethod,
        rep: Plan.TypeRepId,
        second_input: @FieldType(DerivedProcRequest, "second"),
        frame: ?Plan.WorkerPlanId,
        env: u32,
        helper: bool,
        ret_layout: layout.Idx,
        shape: DerivedFrameShape,
        header: ?struct {
            proc: ProcBodyBuilder,
            first: LIR.LocalId,
            second: LIR.LocalId,
            result: LIR.LocalId,
            args_span: LIR.LocalSpan,
        } = null,
    };

    /// A procedure `(operand, second, frame descriptors..., frame
    /// dictionaries...) -> result` performing a derived method over
    /// `request.rep` under the formal bindings of `request.env`, reserved
    /// here with its header and body queued.
    fn emitDerivedProc(self: *ProcedureBuilder, request: DerivedProcRequest) Allocator.Error!LIR.LirProcSpecId {
        if (self.layout_plan.worker_layouts.len == 0) {
            boxyLowerInvariant("derived method procedure was emitted without a worker layout context");
        }
        const proc_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = LIR.LocalSpan.empty(),
            .body = null,
            .ret_layout = request.ret_layout,
            .boxy_runtime_entry = true,
        }, constructlessOrigin(.derived).loc);
        if (request.helper) {
            try self.derived_helpers.append(self.allocator, .{
                .method = request.method,
                .rep = request.rep,
                .frame = request.frame,
                .env = request.env,
                .proc = proc_id,
                .shape = .{
                    .operand_desc = request.shape.operand_desc,
                    .variables = try self.allocator.dupe(Plan.TypeRepId, request.shape.variables),
                    .dictionaries = try self.allocator.dupe(Plan.Span, request.shape.dictionaries),
                },
            });
        }
        const job = try self.allocator.create(DerivedJob);
        errdefer self.allocator.destroy(job);
        const variables = try self.allocator.dupe(Plan.TypeRepId, request.shape.variables);
        errdefer self.allocator.free(variables);
        const dictionaries = try self.allocator.dupe(Plan.Span, request.shape.dictionaries);
        errdefer self.allocator.free(dictionaries);
        job.* = .{
            .proc_id = proc_id,
            .method = request.method,
            .rep = request.rep,
            .second_input = request.second,
            .frame = request.frame,
            .env = request.env,
            .helper = request.helper,
            .ret_layout = request.ret_layout,
            .shape = .{ .operand_desc = request.shape.operand_desc, .variables = variables, .dictionaries = dictionaries },
        };
        try self.appendProcJob(.{ .derived = job });
        return proc_id;
    }

    fn buildDerivedHeader(self: *ProcedureBuilder, job: *DerivedJob) Allocator.Error!void {
        if (job.header != null) return;
        const rep = self.plan.representations.items[@backingInt(job.rep)];
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        job.header = .{
            .proc = ProcBodyBuilder.initSyntheticAdapter(
                self,
                procedureModuleById(self.modules, rep.source_type.module),
                self.layout_plan.worker_layouts[0],
                constructlessOrigin(.derived),
            ),
            .first = undefined,
            .second = undefined,
            .result = undefined,
            .args_span = undefined,
        };
        const header = &job.header.?;
        const proc = &header.proc;
        const shape = job.shape;

        var frame_descs = std.ArrayList(FrameRequirementDescriptor).empty;
        defer frame_descs.deinit(self.allocator);
        if (shape.operand_desc) {
            try frame_descs.append(self.allocator, .{
                .desc = rep.descriptor.?,
                .rep = job.rep,
                .slot = @intCast(frame_descs.items.len),
                .kind = .frame_variable,
            });
        }
        for (shape.variables) |variable| {
            try frame_descs.append(self.allocator, .{
                .desc = self.plan.representations.items[@backingInt(variable)].descriptor orelse
                    boxyLowerInvariant("derived method type variable had no descriptor requirement"),
                .rep = variable,
                .slot = @intCast(frame_descs.items.len),
                .kind = .frame_variable,
            });
        }
        const frame_desc_locals = try self.allocator.alloc(LIR.LocalId, frame_descs.items.len);
        defer self.allocator.free(frame_desc_locals);
        for (frame_desc_locals) |*local| {
            local.* = try proc.addFrameLocal(.opaque_ptr);
            try proc.markReadOnlyDescriptorInput(local.*);
        }
        const frame_dict_locals = try self.allocator.alloc(LIR.LocalId, shape.dictionaries.len);
        defer self.allocator.free(frame_dict_locals);
        for (frame_dict_locals) |*local| local.* = try proc.addFrameLocal(.opaque_ptr);
        if (frame_descs.items.len != 0) {
            proc.template_frame_descriptors = true;
            try proc.bindFrameRequirementDescriptors(frame_descs.items, frame_desc_locals, true);
        }
        if (shape.dictionaries.len != 0) {
            try proc.ensureDictionaryLocals();
            for (shape.dictionaries, frame_dict_locals) |dictionaries, local| {
                for (0..dictionaries.len) |offset| {
                    const index = dictionaries.start + offset;
                    proc.dictionary_slots[index] = local;
                    proc.dictionary_locals[index] = local;
                    proc.dictionary_bound[index] = true;
                }
            }
        }

        const first = try proc.addArgLocalForRep(job.rep);
        const second = switch (job.second_input) {
            .rep => |second_rep| try proc.addArgLocalForRep(second_rep),
            .layout => |second_layout| try proc.addArgLocal(second_layout),
        };
        // The operand descriptor describes the operands themselves, as a
        // worker argument's does.
        if (shape.operand_desc) {
            self.result.store.setLocalBoxyDesc(first, .{ .local = frame_desc_locals[0] });
            if (job.method == .equality) self.result.store.setLocalBoxyDesc(second, .{ .local = frame_desc_locals[0] });
        }
        try proc.arg_locals.appendSlice(self.allocator, frame_desc_locals);
        try proc.arg_locals.appendSlice(self.allocator, frame_dict_locals);
        header.first = first;
        header.second = second;
        header.result = try proc.addFrameLocal(job.ret_layout);
        header.args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        const proc_spec = self.result.store.getProcSpecPtr(job.proc_id);
        proc_spec.args = header.args_span;
        proc_spec.stack_probe = self.stackProbeForProc(header.args_span, LIR.LocalSpan.empty(), job.ret_layout);
    }

    fn buildDerivedBody(self: *ProcedureBuilder, job: *DerivedJob) Allocator.Error!void {
        const header = &(job.header orelse boxyLowerInvariant("boxy derived body was built before its header"));
        const proc = &header.proc;
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = header.result } }, proc.derivedOrigin());
        proc.derived_context = .{ .frame = job.frame, .bindings_start = 0 };
        if (job.helper) proc.derived_expanding = job.rep;
        // The environment's formals are bound throughout, as by the nominal
        // backings that enclosed this representation.
        const env_scope = proc.beginNominalBackingFormalScope();
        errdefer proc.dropNominalBackingFormalScope(env_scope);
        try proc.nominal_formal_bindings.appendSlice(self.allocator, self.plan.derivedEnvBindings(job.env));
        const scoped_body = switch (job.method) {
            .equality => try proc.lowerEqRepLocalsInto(header.result, header.first, header.second, job.rep, false, ret_stmt),
            .hash => try proc.lowerHashRepLocalsInto(header.result, header.first, header.second, job.rep, ret_stmt),
        };
        const derived_body = try proc.leaveNominalBackingFormalScope(env_scope, scoped_body);
        proc.derived_context = null;
        const body = try proc.prependStaticDescriptorMaterializationsForScopedSlots(null, derived_body);
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        const proc_spec = self.result.store.getProcSpecPtr(job.proc_id);
        proc_spec.body = body;
        proc_spec.shapes = proc_spec.shapes.merged(self.result.store.shapes);
        proc_spec.frame_locals = frame_span;
        proc_spec.stack_probe = self.stackProbeForProc(header.args_span, frame_span, job.ret_layout);
    }

    /// An erased-callable adapter's body, with the builder its reserved
    /// header set up.
    const CallableAdapterJob = struct {
        proc_id: LIR.LirProcSpecId,
        adapter_proc: ProcBodyBuilder,
        source_function: ProcBodyBuilder.FunctionChildren,
        target_function: ProcBodyBuilder.FunctionChildren,
        descriptor_captures: []CallableAdapterDescriptorCapture,
        capture_layout: layout.Idx,
        source_closure: LIR.LocalId,
        target_arg_locals: []LIR.LocalId,
        capture_arg: LIR.LocalId,
        descriptor_locals: []LIR.LocalId,
        capture_descriptor_initializers: std.ArrayList(ProcBodyBuilder.DescriptorArgLocal),
        erased_arg_desc_params: LIR.BoxySpan,
        ret_local: LIR.LocalId,
        ret_layout: layout.Idx,
        args_span: LIR.LocalSpan,

        fn deinit(job: *CallableAdapterJob, allocator: Allocator) void {
            job.adapter_proc.deinit();
            allocator.free(job.descriptor_captures);
            allocator.free(job.target_arg_locals);
            allocator.free(job.descriptor_locals);
            job.capture_descriptor_initializers.deinit(allocator);
        }
    };

    fn buildCallableAdapterBody(self: *ProcedureBuilder, job: *CallableAdapterJob) Allocator.Error!void {
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        const adapter_proc = &job.adapter_proc;
        const source_function = job.source_function;
        const target_function = job.target_function;
        const target_args = adapter_proc.functionArgChildren(target_function);
        const source_args = adapter_proc.functionArgChildren(source_function);
        const target_arg_locals = job.target_arg_locals;
        const proc_id = job.proc_id;
        const ret_local = job.ret_local;

        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } }, adapter_proc.origin);
        var continuation = ret_stmt;

        // A result that crosses unchanged is written straight to the return
        // local, which leaves the wrapped callable's call in tail position.
        const ret_desc_is_shared = if (self.result.store.getLocal(ret_local).boxy_desc) |desc|
            if (desc.localOrNull()) |local| adapter_proc.localIsDescriptorSlot(local) else false
        else
            false;
        const source_ret_layout = adapter_proc.workerRuntimeLayoutForRep(source_function.ret).layoutIdx();
        const call_target = if (!ret_desc_is_shared and
            self.result.store.getLocal(ret_local).layout_idx == source_ret_layout and
            (adapter_proc.erasedCallResultCanUseTarget(target_function.ret, source_function.ret) or
                adapter_proc.callResultAdoptsCalleeDescriptor(ret_local, target_function.ret)))
            ret_local
        else blk: {
            const raw_ret = try adapter_proc.addFrameLocalForRepWithFreshDescriptor(source_function.ret);
            continuation = try adapter_proc.assignPlannedCallBoundary(
                ret_local,
                raw_ret,
                target_function.ret,
                source_function.ret,
                continuation,
            );
            break :blk raw_ret;
        };

        const out_desc = adapter_proc.callResultOutputDescriptorLocal(call_target);
        if (out_desc) |local| {
            try adapter_proc.markDescriptorLocalBound(local);
        }

        const call_args = try self.allocator.alloc(LIR.LocalId, source_function.arg_count);
        defer self.allocator.free(call_args);
        for (source_args, target_args, target_arg_locals, call_args) |source_arg, target_arg, target_arg_local, *call_arg| {
            call_arg.* = if (try adapter_proc.callableValueBoundaryIsDirect(source_arg.rep, target_arg.rep))
                target_arg_local
            else
                try adapter_proc.addFrameBoundaryTargetLocalForRep(source_arg.rep);
        }

        const call_placeholder = try self.result.store.addCFStmt(.runtime_error, adapter_proc.origin);
        var call_with_args = call_placeholder;
        var arg_index = source_function.arg_count;
        while (arg_index > 0) {
            arg_index -= 1;
            if (call_args[arg_index] == target_arg_locals[arg_index]) continue;
            call_with_args = try adapter_proc.assignPlannedCallBoundaryCopyingSource(
                call_args[arg_index],
                target_arg_locals[arg_index],
                source_args[arg_index].rep,
                target_args[arg_index].rep,
                call_with_args,
            );
        }

        var arg_desc_initializers = std.ArrayList(ProcBodyBuilder.DescriptorArgLocal).empty;
        defer arg_desc_initializers.deinit(self.allocator);
        const arg_descs = try adapter_proc.erasedCallArgumentDescriptorRefs(
            source_args,
            call_args,
            &arg_desc_initializers,
        );
        const expected_result_desc = if (adapter_proc.repIsOpenRecord(source_function.ret)) ProcBodyBuilder.ResultDescriptorSource{} else try adapter_proc.exactCallResultDescriptorRef(source_function.ret);
        try adapter_proc.appendResultDescriptorInitializers(&arg_desc_initializers, expected_result_desc);
        const call_stmt = try self.result.store.addCFStmt(.{
            .assign_call_erased = .{
                .target = call_target,
                .closure = job.source_closure,
                .args = try self.result.store.addLocalSpan(call_args),
                .arg_layouts = try adapter_proc.appendErasedArgumentLayouts(call_args),
                .arg_plan = try adapter_proc.erasedCallArgsPlan(call_args),
                .arg_descs = arg_descs.locals,
                .arg_desc_keys = arg_descs.keys,
                // `result_desc` governs materialization into the source
                // signature's result layout. `out_desc` separately
                // preserves the exact descriptor returned by the callable.
                .result_desc = expected_result_desc.desc,
                .out_desc = out_desc,
                .reuse_closure = false,
                .reuse_source = null,
                .next = continuation,
            },
        }, adapter_proc.origin);
        const call_entry = try adapter_proc.prependDescriptorArgMaterializations(arg_desc_initializers.items, call_stmt);
        try self.result.store.replaceCFStmt(call_placeholder, self.result.store.getCFStmt(call_entry), self.result.store.stmtOrigin(call_entry));
        continuation = call_with_args;

        continuation = try adapter_proc.prependStaticDescriptorMaterializationsForSlots(continuation);
        continuation = try adapter_proc.prependWorkerArgumentDescriptorInitializers(continuation);
        continuation = try adapter_proc.prependCallableAdapterCaptureBindings(
            job.capture_arg,
            job.capture_layout,
            job.source_closure,
            job.descriptor_locals,
            try adapter_proc.prependDescriptorArgMaterializations(
                job.capture_descriptor_initializers.items,
                continuation,
            ),
        );

        const proc_spec = self.result.store.getProcSpecPtr(proc_id);
        proc_spec.body = continuation;
        proc_spec.erased_arg_desc_offsets = try adapter_proc.callableAdapterArgumentDescriptorCaptureOffsets(
            target_function,
            job.descriptor_captures,
            job.capture_layout,
        );
        proc_spec.erased_arg_layouts = try adapter_proc.appendErasedArgumentLayouts(target_arg_locals);
        proc_spec.erased_arg_desc_params = job.erased_arg_desc_params;
        proc_spec.erased_capture_arg = job.capture_arg;
        const return_desc = try self.returnDescriptorInfoForBody(
            continuation,
            job.args_span,
            self.result.store.getLocal(ret_local).boxy_desc,
            &adapter_proc.frame_locals,
        );
        const frame_span = try self.result.store.addLocalSpan(adapter_proc.frame_locals.items);
        proc_spec.frame_locals = frame_span;
        proc_spec.ret_desc = return_desc.external;
        proc_spec.runtime_ret_desc = return_desc.runtime_local;
        proc_spec.stack_probe = self.stackProbeForProc(job.args_span, frame_span, job.ret_layout);
    }

    /// The recursive helper for a derived method over `rep_id` in `frame`
    /// under `env`, emitted on first use.
    fn derivedHelperIndex(
        self: *ProcedureBuilder,
        method: Plan.DerivedMethod,
        rep_id: Plan.TypeRepId,
        frame: ?Plan.WorkerPlanId,
        env: u32,
        second_layout: layout.Idx,
        ret_layout: layout.Idx,
    ) Allocator.Error!usize {
        for (self.derived_helpers.items, 0..) |helper, index| {
            if (helper.method == method and helper.rep == rep_id and helper.env == env and
                std.meta.eql(helper.frame, frame)) return index;
        }
        const shape = try self.derivedFrameShape(rep_id, frame, env, .helper);
        defer shape.deinit(self.allocator);
        const index = self.derived_helpers.items.len;
        _ = try self.emitDerivedProc(.{
            .method = method,
            .rep = rep_id,
            .second = .{ .layout = second_layout },
            .ret_layout = ret_layout,
            .frame = frame,
            .env = env,
            .shape = shape,
            .helper = true,
        });
        return index;
    }

    /// Whether `rep_id` reaches itself through the positions a derived method
    /// descends: a recursive type's recursion point.
    fn repOnRuntimeCycle(self: *ProcedureBuilder, rep_id: Plan.TypeRepId) Allocator.Error!bool {
        var visited = collections.DenseMap(Plan.TypeRepId, void).init(self.allocator);
        defer visited.deinit();
        var stack = std.ArrayList(Plan.TypeRepId).empty;
        defer stack.deinit(self.allocator);
        try self.pushDerivedChildren(rep_id, &stack);
        while (stack.pop()) |current| {
            if (current == rep_id) return true;
            if ((try visited.getOrPut(current)).found_existing) continue;
            try self.pushDerivedChildren(current, &stack);
        }
        return false;
    }

    fn pushDerivedChildren(self: *ProcedureBuilder, rep_id: Plan.TypeRepId, stack: *std.ArrayList(Plan.TypeRepId)) Allocator.Error!void {
        const rep = self.plan.representations.items[@backingInt(rep_id)];
        for (self.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .alias_backing, .nominal_backing, .record_field, .tuple_elem, .box_payload => try stack.append(self.allocator, child.rep),
                .alias_arg, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem => {},
            }
        }
        for (self.plan.tagVariantSlice(rep.tag_variants)) |variant| {
            for (self.plan.childSlice(variant.payloads)) |payload| try stack.append(self.allocator, payload.rep);
        }
    }

    /// Why a static dictionary method slot crashes instead of calling a
    /// method: the checked evidence for that slot is a rejected dispatch.
    const CrashingDictionaryMethod = enum {
        /// Checking rejected the dispatch and already reported it.
        checked_error,
        /// The dispatcher is a value that can never exist.
        unreachable_value,
    };

    fn crashingDictionaryMethodSlot(
        self: *ProcedureBuilder,
        requirement: Plan.DictionaryRequirement,
        fn_type: Plan.CheckedTypeIdentity,
        crash: CrashingDictionaryMethod,
    ) Allocator.Error!LirProgram.BoxyMethodSlot {
        const requirement_rep = self.plan.repForSourceType(fn_type) orelse
            boxyLowerInvariant("crashing dictionary function type was not analyzed");
        const function = self.staticMethodFunctionForRep(requirement_rep) orelse
            boxyLowerInvariant("crashing dictionary requirement was not a function");
        if (self.layout_plan.worker_layouts.len == 0) {
            boxyLowerInvariant("crashing dictionary method was emitted without a worker layout context");
        }

        const ret_layout = self.layout_plan.rep_layouts[@backingInt(function.ret)].worker.layoutIdx();
        const proc_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = LIR.LocalSpan.empty(),
            .body = null,
            .ret_layout = ret_layout,
            .boxy_runtime_entry = true,
        }, constructlessOrigin(.scaffold).loc);
        try self.appendProcJob(.{ .crashing_method = .{ .proc_id = proc_id, .fn_type = fn_type, .crash = crash } });
        return .{
            .method = requirement.fn_name,
            .proc = proc_id,
        };
    }

    /// Build a dictionary method that crashes when called: the crash a
    /// direct dispatch with the same rejected resolution lowers to.
    fn buildCrashingDictionaryMethod(
        self: *ProcedureBuilder,
        proc_id: LIR.LirProcSpecId,
        fn_type: Plan.CheckedTypeIdentity,
        crash: CrashingDictionaryMethod,
    ) Allocator.Error!void {
        const requirement_rep = self.plan.repForSourceType(fn_type) orelse
            boxyLowerInvariant("crashing dictionary function type was not analyzed");
        const function = self.staticMethodFunctionForRep(requirement_rep) orelse
            boxyLowerInvariant("crashing dictionary requirement was not a function");
        const function_children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        const function_args = function_children[function.args_start..][0..function.arg_count];
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        var proc = ProcBodyBuilder.initSyntheticAdapter(
            self,
            procedureModuleById(self.modules, fn_type.module),
            self.layout_plan.worker_layouts[0],
            constructlessOrigin(.scaffold),
        );
        defer proc.deinit();
        for (function_args) |arg| {
            _ = try proc.addArgLocalForRep(arg.rep);
        }
        const args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        const message = switch (crash) {
            .checked_error => "method dispatch failed to check",
            .unreachable_value => "dispatch on a value that can never exist",
        };
        const body = try self.result.store.addCFStmt(.{ .crash = .{
            .msg = .{ .literal = try self.result.store.insertString(message) },
            .checked_error = crash == .checked_error,
        } }, proc.origin);
        const proc_spec = self.result.store.getProcSpecPtr(proc_id);
        proc_spec.args = args_span;
        proc_spec.body = body;
        proc_spec.frame_locals = frame_span;
        proc_spec.stack_probe = self.stackProbeForProc(args_span, frame_span, proc_spec.ret_layout);
    }

    fn methodWorkerForStaticDictionary(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        requirement: Plan.DictionaryRequirement,
    ) ?Plan.WorkerPlanId {
        const source_rep = self.plan.representations.items[@backingInt(rep_id)];
        const source_module = procedureModuleById(self.modules, source_rep.source_type.module);
        const requirement_module = procedureModuleById(self.modules, requirement.source_type.module);
        const owner = methodOwnerForProcedureType(source_module, source_rep.source_type.ty) orelse return null;
        const target_lookup = self.lookupMethodTarget(
            source_module,
            owner,
            requirement_module,
            requirement.fn_name,
        ) orelse return null;
        const source = self.workerSourceForMethodTarget(target_lookup, source_rep.source_type);
        const worker_type = Plan.CheckedTypeIdentity{
            .module = target_lookup.module.key,
            .ty = target_lookup.target.callable_ty,
        };
        return self.plan.workerForSourceType(source, worker_type);
    }

    fn workerSourceForMethodTarget(
        _: *ProcedureBuilder,
        lookup: MethodTargetLookup,
        shape: Plan.CheckedTypeIdentity,
    ) Plan.WorkerSource {
        return switch (lookup.target.kind) {
            .procedure => |procedure| .{ .procedure_template = procedure.template },
            .local_proc => |local| if (topLevelProcedureBindingForExpr(lookup.module, local.expr)) |binding|
                .{ .procedure_binding = binding }
            else
                .{ .nested_expr = .{ .module = lookup.module.key, .expr = nestedCallableSiteExprForExpr(lookup.module, local.expr) orelse local.expr } },
            .structural => |kind| switch (kind) {
                .parser => .{ .generated_codec = .{
                    .kind = .parser_constructor,
                    .shape = shape,
                } },
                .encoder => .{ .generated_codec = .{
                    .kind = .encoder_constructor,
                    .shape = shape,
                } },
                .equality, .hash, .map, .map_effectful => boxyLowerInvariant("non-codec structural target reached Boxy method worker selection"),
            },
        };
    }

    /// The planned worker for the checked `to_inspect` override of this
    /// representation's owner, or null when inspection renders the default
    /// form.
    fn inspectOverrideWorkerForRep(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
    ) ?Plan.WorkerPlanId {
        const source_rep = self.plan.representations.items[@backingInt(rep_id)];
        const source_module = procedureModuleById(self.modules, source_rep.source_type.module);
        const owner = methodOwnerForProcedureType(source_module, source_rep.source_type.ty) orelse return null;
        const target_lookup = self.lookupInspectOverride(source_module, owner) orelse return null;
        const source = switch (target_lookup.target.kind) {
            .procedure => |procedure| Plan.WorkerSource{ .procedure_template = procedure.template },
            .local_proc,
            .structural,
            => boxyLowerInvariant("boxy nominal method target reached lowering without a procedure worker"),
        };
        return self.plan.workerForSourceType(source, .{
            .module = target_lookup.module.key,
            .ty = target_lookup.target.callable_ty,
        });
    }

    const MethodTargetLookup = struct {
        module: ProcedureModuleView,
        target: static_dispatch.MethodTarget,
    };

    fn lookupMethodTarget(
        self: *ProcedureBuilder,
        owner_module: ProcedureModuleView,
        owner: static_dispatch.MethodOwner,
        method_module: ProcedureModuleView,
        method: names.MethodNameId,
    ) ?MethodTargetLookup {
        const method_text = method_module.canonical_names.methodNameText(method);
        if (self.lookupMethodTargetInModule(owner_module, owner_module, owner, method_text)) |target| return target;
        for (self.modules.imports) |imported| {
            const module = procedureModuleFromImport(imported);
            if (checked_moduleKeyEqual(module.key, owner_module.key)) continue;
            if (self.lookupMethodTargetInModule(module, owner_module, owner, method_text)) |target| return target;
        }
        for (self.modules.root.relation_modules) |relation| {
            const module = procedureModuleFromImport(relation);
            if (checked_moduleKeyEqual(module.key, owner_module.key)) continue;
            if (self.lookupMethodTargetInModule(module, owner_module, owner, method_text)) |target| return target;
        }
        return null;
    }

    /// Selects the module that declares `owner.to_inspect` exactly as
    /// `lookupMethodTarget` does; that declaration's checked eligibility is
    /// the answer.
    fn lookupInspectOverride(
        self: *ProcedureBuilder,
        owner_module: ProcedureModuleView,
        owner: static_dispatch.MethodOwner,
    ) ?MethodTargetLookup {
        if (inspectOverrideInModule(owner_module, owner_module, owner)) |decision| return decision.target;
        for (self.modules.imports) |imported| {
            const module = procedureModuleFromImport(imported);
            if (checked_moduleKeyEqual(module.key, owner_module.key)) continue;
            if (inspectOverrideInModule(module, owner_module, owner)) |decision| return decision.target;
        }
        for (self.modules.root.relation_modules) |relation| {
            const module = procedureModuleFromImport(relation);
            if (checked_moduleKeyEqual(module.key, owner_module.key)) continue;
            if (inspectOverrideInModule(module, owner_module, owner)) |decision| return decision.target;
        }
        return null;
    }

    const InspectOverrideDecision = struct {
        target: ?MethodTargetLookup,
    };

    fn inspectOverrideInModule(
        candidate: ProcedureModuleView,
        owner_module: ProcedureModuleView,
        owner: static_dispatch.MethodOwner,
    ) ?InspectOverrideDecision {
        const candidate_owner = Plan.methodOwnerInNames(owner_module.canonical_names, candidate.canonical_names, owner) orelse return null;
        const candidate_method = candidate.canonical_names.lookupMethodName("to_inspect") orelse return null;
        const key: static_dispatch.MethodKey = .{ .owner = candidate_owner, .method = candidate_method };
        // A declared `to_inspect` decides inspection in this module; the
        // registry records an override only for an eligible, unrejected
        // declaration.
        _ = candidate.method_registry.lookup(key) orelse return null;
        const override = candidate.method_registry.lookupInspectOverride(key) orelse return .{ .target = null };
        // Inspection calls the method at its checked `T -> Str` instance.
        var target = override.target;
        target.callable_ty = override.callable_ty;
        return .{ .target = .{ .module = candidate, .target = target } };
    }

    fn lookupMethodTargetInModule(
        _: *ProcedureBuilder,
        candidate: ProcedureModuleView,
        owner_module: ProcedureModuleView,
        owner: static_dispatch.MethodOwner,
        method_text: []const u8,
    ) ?MethodTargetLookup {
        const candidate_owner = Plan.methodOwnerInNames(owner_module.canonical_names, candidate.canonical_names, owner) orelse return null;
        const candidate_method = candidate.canonical_names.lookupMethodName(method_text) orelse return null;
        const found = candidate.method_registry.lookup(.{ .owner = candidate_owner, .method = candidate_method }) orelse return null;
        return .{ .module = candidate, .target = found.requireTarget("boxy procedure lowering") };
    }

    /// Compose the explicit substitutions along the storage wrapper chain.
    /// Layout planning has already committed finite storage; a wrapper cycle
    /// would violate that contract. The representation count bounds the walk
    /// without allocating a visited set for every static descriptor.
    fn collectStaticNominalBackingDescriptorSources(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        sources: *StaticDescriptorSourceMap,
    ) Allocator.Error!void {
        var current = rep_id;
        for (0..self.plan.representations.items.len) |_| {
            const rep = self.plan.representations.items[@backingInt(current)];
            var substitutions = self.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
            while (substitutions.next()) |substitution| {
                const formal_rep = substitution.formal_rep orelse continue;
                const formal = self.plan.representations.items[@backingInt(formal_rep)];
                const desc = formal.descriptor orelse continue;
                const actual = self.effectiveStaticDescriptorSource(substitution.actual_rep, substitution.actual_rep, sources).?;
                if (formal_rep != actual) {
                    try sources.put(self.allocator, desc, actual);
                }
            }
            current = self.descriptorBackingShapeRep(current) orelse return;
        }
        boxyLowerInvariant("cyclic static descriptor storage wrapper");
    }

    /// Where one `nested_descs` position's value is stored.
    const NestedDescriptorSlotKind = union(enum) {
        /// A struct field or tuple element stored in the parent payload.
        field: layout.Idx,
        /// A list item stored in the list's allocation.
        list_elem: layout.Idx,
        /// A box payload stored in the box's own allocation.
        box_payload,
    };

    /// One position of a descriptor's `nested_descs`.
    const NestedDescriptorSlot = struct {
        rep: Plan.TypeRepId,
        kind: NestedDescriptorSlotKind,
        /// The structural child this position describes, for a representation
        /// shaped by its children.
        child: ?Plan.RepChild = null,
        /// The declared field this position describes, for a declared-field
        /// nominal.
        declared_field: ?Plan.DeclaredField = null,
    };

    /// Append the `nested_descs` positions of `rep_id`'s descriptor, in
    /// position order: struct field `i` (by original field index) is position
    /// `i`, and a list's item or a box's payload is position 0. Every child
    /// has a position, including zero-sized and scalar ones, because the
    /// child's descriptor is the only runtime record of its source-language
    /// identity.
    fn appendNestedDescriptorSlots(
        self: *ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        payload_layout: layout.Idx,
        slots: *std.ArrayList(NestedDescriptorSlot),
    ) Allocator.Error!void {
        const rep = self.plan.representations.items[@backingInt(rep_id)];
        const first = slots.items.len;
        if (rep.declared_fields.len != 0) {
            const ordered = try self.declaredFieldsInLayoutOrder(self.plan.declaredFieldSlice(rep.declared_fields));
            defer self.allocator.free(ordered);
            for (ordered) |field| {
                if (field.index != slots.items.len - first) {
                    boxyLowerInvariant("declared nominal fields did not cover every payload field position");
                }
                try slots.append(self.allocator, .{
                    .rep = field.rep,
                    .kind = .{ .field = self.recordPayloadFieldLayout(payload_layout, field.index) },
                    .declared_field = field,
                });
            }
            return;
        }

        var record_field_index: usize = 0;
        for (self.plan.childSlice(rep.children)) |child| {
            const kind: NestedDescriptorSlotKind = switch (child.role) {
                .record_field => blk: {
                    const field_layout = self.recordPayloadFieldLayout(payload_layout, record_field_index);
                    record_field_index += 1;
                    break :blk .{ .field = field_layout };
                },
                .tuple_elem => |index| blk: {
                    if (index != slots.items.len - first) {
                        boxyLowerInvariant("tuple representation elements were not in position order");
                    }
                    break :blk .{ .field = self.recordPayloadFieldLayout(payload_layout, index) };
                },
                .list_elem => .{ .list_elem = self.listElementLayout(payload_layout) },
                .box_payload => .box_payload,
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
            };
            try slots.append(self.allocator, .{ .rep = child.rep, .kind = kind, .child = child });
        }
    }

    /// The representation whose descriptor describes `slot`'s stored value.
    fn nestedDescriptorSlotDescRep(self: *const ProcedureBuilder, slot: NestedDescriptorSlot) Plan.TypeRepId {
        return switch (slot.kind) {
            .field, .list_elem => |storage_layout| self.tagPayloadStorageDescRepForLayout(slot.rep, storage_layout, true) orelse
                boxyLowerInvariant("forced nested descriptor representation was not selected"),
            .box_payload => self.tagPayloadStorageDescRep(slot.rep),
        };
    }

    /// Whether `slot`'s stored value carries a runtime descriptor for its
    /// memory operations, rather than having only a static identity.
    fn nestedDescriptorSlotCarriesRuntimeDesc(self: *const ProcedureBuilder, slot: NestedDescriptorSlot) bool {
        return switch (slot.kind) {
            .field, .list_elem => |storage_layout| self.layoutIsBoxStorage(storage_layout) or self.layoutNeedsNestedBoxyDesc(storage_layout),
            .box_payload => true,
        };
    }

    /// Source-language shape of the value `rep_id`'s descriptor describes.
    /// Whether `rep_id` is builtin Bool, through aliases, nominals, and sealed
    /// defaults, which derived hashing writes as a Bool.
    fn repDescribesBool(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) bool {
        var current = rep_id;
        for (0..self.plan.representations.items.len + 1) |_| {
            const rep = self.plan.representations.items[@backingInt(current)];
            if (rep.sealed_default) |sealed_default| {
                current = sealed_default;
                continue;
            }
            switch (rep.kind) {
                .bool_tag_union => return true,
                .alias => current = self.singleChildRepForDesc(current, .alias_backing) orelse return false,
                .nominal => current = self.singleChildRepForDesc(current, .nominal_backing) orelse return false,
                .in_progress,
                .dynamic,
                .primitive,
                .tag_union,
                .empty_tag_union,
                .erased_callable,
                .record,
                .empty_record,
                .tuple,
                .list,
                .box,
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                => return false,
            }
        }
        boxyLowerInvariant("cyclic boxy descriptor Bool wrapper chain");
    }

    fn descriptorShapeForRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) LirProgram.BoxyDescShape {
        var current = rep_id;
        for (0..self.plan.representations.items.len + 1) |_| {
            const rep = self.plan.representations.items[@backingInt(current)];
            if (rep.sealed_default) |sealed_default| {
                current = sealed_default;
                continue;
            }
            if (rep.declared_fields.len != 0) return .record;
            switch (rep.kind) {
                .in_progress => boxyLowerInvariant("in-progress boxy representation reached descriptor shape selection"),
                .dynamic => return if (rep.tag_variants.len != 0) .tag_union else .erased,
                .primitive => return .primitive,
                .bool_tag_union, .tag_union, .empty_tag_union => return .tag_union,
                .erased_callable => return .function,
                .record, .empty_record => return .record,
                .tuple => return .tuple,
                .list => return .list,
                .box => return .box,
                .generated_field, .generated_field_names, .generated_tag_union_spec => return .internal,
                .alias => current = self.singleChildRepForDesc(current, .alias_backing) orelse
                    boxyLowerInvariant("alias descriptor shape had no backing child"),
                .nominal => current = self.singleChildRepForDesc(current, .nominal_backing) orelse
                    boxyLowerInvariant("nominal descriptor shape had no backing child"),
            }
        }
        boxyLowerInvariant("cyclic boxy descriptor shape wrapper chain");
    }

    fn staticGeneratedEvidenceNestedDescRefs(
        self: *ProcedureBuilder,
        kind: Plan.RepresentationKind,
    ) Allocator.Error!?LIR.BoxySpan {
        const evidence = self.layout_plan.generated_evidence;
        return switch (kind) {
            .generated_field => try self.generatedEvidenceStructNestedDescRefs(
                evidence.field,
                .{ .static = try self.internalLeafTypeDesc(.str) },
            ),
            .generated_field_names => try self.generatedEvidenceStructNestedDescRefs(
                evidence.field_names,
                .{ .static = try self.generatedEvidenceTypeDesc(.field_list) },
            ),
            .generated_tag_union_spec => try self.generatedEvidenceStructNestedDescRefs(
                evidence.tag_union_spec,
                .{ .static = try self.generatedEvidenceTypeDesc(.field_names_list) },
            ),
            .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .empty_record, .tag_union, .empty_tag_union => null,
        };
    }

    /// Nested descriptors of a generated evidence struct stored in
    /// `struct_layout`: `first` describes its first field, and every later
    /// field is a compiler-internal scalar.
    fn generatedEvidenceStructNestedDescRefs(
        self: *ProcedureBuilder,
        struct_layout: layout.Idx,
        first: LIR.BoxyDescRef,
    ) Allocator.Error!LIR.BoxySpan {
        const layout_value = self.result.layouts.getLayout(struct_layout);
        if (layout_value.tag != .struct_) {
            boxyLowerInvariant("generated evidence descriptor had a non-struct layout");
        }
        const struct_idx = layout_value.getStruct().idx;
        const field_count = self.result.layouts.getStructData(struct_idx).fields.count;
        const refs = try self.allocator.alloc(LIR.BoxyDescRef, field_count);
        defer self.allocator.free(refs);
        refs[0] = first;
        for (refs[1..], 1..) |*ref, field_index| {
            const field_layout = self.result.layouts.getStructFieldLayoutByOriginalIndex(struct_idx, @intCast(field_index));
            ref.* = .{ .static = try self.internalLeafTypeDesc(field_layout) };
        }
        const start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.appendSlice(self.allocator, refs);
        return .{ .start = start, .len = @intCast(refs.len) };
    }

    /// Nested descriptors of a generated evidence list: its element.
    fn generatedEvidenceListNestedDescRefs(
        self: *ProcedureBuilder,
        elem: LIR.BoxyTypeDescId,
    ) Allocator.Error!LIR.BoxySpan {
        const start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
        try self.result.boxy_desc_refs.append(self.allocator, .{ .static = elem });
        return .{ .start = start, .len = 1 };
    }

    /// The descriptor of a kind of generated evidence. Each kind's contents
    /// are described by the next inner kind's descriptor, so descriptors
    /// along that chain are reserved outermost first and filled innermost
    /// first.
    fn generatedEvidenceTypeDesc(
        self: *ProcedureBuilder,
        root: GeneratedEvidenceDescKind,
    ) Allocator.Error!LIR.BoxyTypeDescId {
        var chain: [4]GeneratedEvidenceDescKind = undefined;
        var chain_len: usize = 0;
        var next_kind: ?GeneratedEvidenceDescKind = root;
        while (next_kind) |kind| {
            if (self.generated_evidence_desc_ids[@backingInt(kind)] != null) break;
            const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.boxy_type_descs.items.len))));
            self.generated_evidence_desc_ids[@backingInt(kind)] = desc_id;
            try self.result.boxy_type_descs.append(self.allocator, reserved_boxy_type_desc);
            chain[chain_len] = kind;
            chain_len += 1;
            next_kind = switch (kind) {
                .field => null,
                .field_list => .field,
                .field_names => .field_list,
                .field_names_list => .field_names,
            };
        }
        var index = chain_len;
        while (index > 0) {
            index -= 1;
            const kind = chain[index];
            const desc_id = self.generated_evidence_desc_ids[@backingInt(kind)].?;
            const payload_layout = switch (kind) {
                .field => self.layout_plan.generated_evidence.field,
                .field_list => self.layout_plan.generated_evidence.field_list,
                .field_names => self.layout_plan.generated_evidence.field_names,
                .field_names_list => self.layout_plan.generated_evidence.field_names_list,
            };
            const nested_descs: LIR.BoxySpan = switch (kind) {
                .field => try self.generatedEvidenceStructNestedDescRefs(payload_layout, .{ .static = try self.internalLeafTypeDesc(.str) }),
                .field_list => try self.generatedEvidenceListNestedDescRefs(self.generated_evidence_desc_ids[@backingInt(GeneratedEvidenceDescKind.field)].?),
                .field_names => try self.generatedEvidenceStructNestedDescRefs(payload_layout, .{ .static = self.generated_evidence_desc_ids[@backingInt(GeneratedEvidenceDescKind.field_list)].? }),
                .field_names_list => try self.generatedEvidenceListNestedDescRefs(self.generated_evidence_desc_ids[@backingInt(GeneratedEvidenceDescKind.field_names)].?),
            };
            const layout_value = self.result.layouts.getLayout(payload_layout);
            self.result.boxy_type_descs.items[@backingInt(desc_id)] = .{
                .payload_layout = payload_layout,
                .contains_refcounted = self.result.layouts.layoutContainsRefcounted(layout_value),
                .shape = .internal,
                .nested_descs = nested_descs,
                .inspect_opaque = true,
            };
        }
        return self.generated_evidence_desc_ids[@backingInt(root)].?;
    }

    /// Descriptor for a compiler-internal leaf value stored in `layout_idx`,
    /// such as a field of generated evidence or a pointer in a capture struct.
    fn internalLeafTypeDesc(self: *ProcedureBuilder, layout_idx: layout.Idx) Allocator.Error!LIR.BoxyTypeDescId {
        if (self.internal_leaf_desc_ids.get(layout_idx)) |existing| return existing;
        const layout_value = self.result.layouts.getLayout(layout_idx);
        if (layout_value.tag != .scalar) {
            boxyLowerInvariant("boxy internal leaf descriptor requested for a non-scalar layout");
        }
        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.boxy_type_descs.items.len))));
        try self.result.boxy_type_descs.append(self.allocator, .{
            .payload_layout = layout_idx,
            .contains_refcounted = self.result.layouts.layoutContainsRefcounted(layout_value),
            .shape = .internal,
        });
        try self.internal_leaf_desc_ids.put(self.allocator, layout_idx, desc_id);
        return desc_id;
    }

    /// Descriptor for a compiler-internal pointer field.
    fn internalPointerTypeDesc(self: *ProcedureBuilder) Allocator.Error!LIR.BoxyTypeDescId {
        return try self.internalLeafTypeDesc(.opaque_ptr);
    }

    fn tagVariantRepForDesc(self: *const ProcedureBuilder, root: Plan.TypeRepId) Plan.TypeRepId {
        var rep_id = root;
        while (true) {
            const rep = self.plan.representations.items[@backingInt(rep_id)];
            const backing = if (rep.kind == .alias)
                self.singleChildRepForDesc(rep_id, .alias_backing)
            else if (rep.kind == .nominal) switch (rep.kind.nominal) {
                .transparent, .builtin_other => self.singleChildRepForDesc(rep_id, .nominal_backing),
                .opaque_nominal => return rep_id,
            } else return rep_id;
            // A wrapper without its backing child describes its own variants.
            rep_id = backing orelse return rep_id;
        }
    }

    fn tagPayloadStorageDescRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        const identity_rep = self.descriptorIdentityRep(rep_id);
        const rep = self.plan.representations.items[@backingInt(identity_rep)];
        if (rep.kind == .box) {
            const payload_rep = self.singleChildRepForDesc(identity_rep, .box_payload) orelse
                boxyLowerInvariant("box payload descriptor representation had no payload child");
            return self.descriptorStorageRep(payload_rep);
        }
        return identity_rep;
    }

    fn tagPayloadStorageDescRepIfNeeded(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        if (!self.repNeedsTagPayloadDesc(rep_id)) return null;
        return self.tagPayloadStorageDescRep(rep_id);
    }

    fn descriptorPayloadLayoutForRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) layout.Idx {
        const rep_layout = self.layout_plan.rep_layouts[@backingInt(rep_id)];
        return rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
    }

    fn descriptorTemplatePayloadLayoutForRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) layout.Idx {
        const identity_rep = self.descriptorIdentityRep(rep_id);
        const worker_layout = self.layout_plan.rep_layouts[@backingInt(rep_id)].worker.layoutIdx();
        const identity_worker_layout = self.layout_plan.rep_layouts[@backingInt(identity_rep)].worker.layoutIdx();
        return if (worker_layout != identity_worker_layout)
            worker_layout
        else
            self.descriptorPayloadLayoutForRep(rep_id);
    }

    fn layoutIsBoxStorage(self: *const ProcedureBuilder, layout_idx: layout.Idx) bool {
        const tag = self.result.layouts.getLayout(layout_idx).tag;
        return tag == .box or tag == .box_of_zst or tag == .erased_box;
    }

    /// Whether a value stored in `layout_idx` carries a runtime descriptor that
    /// its memory operations follow. A value in any other layout has a
    /// statically known identity; its descriptor still occupies its position
    /// in a parent's `nested_descs`.
    fn layoutNeedsNestedBoxyDesc(self: *const ProcedureBuilder, layout_idx: layout.Idx) bool {
        const value_layout = self.result.layouts.getLayout(layout_idx);
        return switch (value_layout.tag) {
            .box,
            .erased_box,
            .list,
            .list_of_zst,
            .struct_,
            .tag_union,
            => true,
            .scalar => value_layout.getScalar().tag == .vector,
            .box_of_zst,
            .closure,
            .erased_callable,
            .zst,
            .ptr,
            => false,
        };
    }

    fn tagPayloadStorageDescRepForLayout(
        self: *const ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        storage_layout: layout.Idx,
        force: bool,
    ) ?Plan.TypeRepId {
        return switch (self.tagPayloadStorageDescRepMatch(rep_id, storage_layout, force)) {
            .not_needed => null,
            .rep => |rep| rep,
            .layout_mismatch => boxyLowerInvariant("boxy descriptor payload field layout disagreed with selected nested descriptor representation"),
        };
    }

    const TagPayloadStorageDescRepMatch = union(enum) {
        not_needed,
        rep: Plan.TypeRepId,
        layout_mismatch,
    };

    /// The representation of `rep_id` whose descriptor describes a payload
    /// stored in `storage_layout`.
    fn tagPayloadStorageDescRepMatch(
        self: *const ProcedureBuilder,
        rep_id: Plan.TypeRepId,
        storage_layout: layout.Idx,
        force: bool,
    ) TagPayloadStorageDescRepMatch {
        const initial = if (force)
            self.tagPayloadStorageDescRep(rep_id)
        else
            self.tagPayloadStorageDescRepIfNeeded(rep_id) orelse return .not_needed;

        if (self.layoutIsBoxStorage(storage_layout)) return .{ .rep = initial };
        if (self.descriptorPayloadLayoutForRep(initial) == storage_layout) return .{ .rep = initial };

        const identity = self.descriptorIdentityRep(rep_id);
        if ((force or self.repNeedsTagPayloadDesc(identity)) and
            self.descriptorPayloadLayoutForRep(identity) == storage_layout)
        {
            return .{ .rep = identity };
        }
        return .layout_mismatch;
    }

    fn tagVariantPayloadFieldLayout(
        self: *const ProcedureBuilder,
        payload_layout: layout.Idx,
        payload_index: usize,
        payload_count: usize,
    ) layout.Idx {
        if (payload_count == 1) return payload_layout;
        if (payload_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("tag payload index exceeded layout field range");
        }
        const payload_layout_value = self.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag == .struct_) {
            return self.result.layouts.getStructFieldLayoutByOriginalIndex(
                payload_layout_value.getStruct().idx,
                @intCast(payload_index),
            );
        }
        if (payload_layout_value.tag == .zst) return .zst;
        boxyLowerInvariant("multi-payload tag descriptor had non-struct payload layout");
    }

    fn recordPayloadFieldLayout(
        self: *const ProcedureBuilder,
        payload_layout: layout.Idx,
        field_index: usize,
    ) layout.Idx {
        if (field_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("record payload field index exceeded layout field range");
        }
        const payload_layout_value = self.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag == .struct_) {
            return self.result.layouts.getStructFieldLayoutByOriginalIndex(
                payload_layout_value.getStruct().idx,
                @intCast(field_index),
            );
        }
        if (payload_layout_value.tag == .zst) return .zst;
        boxyLowerInvariant("record descriptor had non-struct payload layout");
    }

    fn listElementLayout(self: *const ProcedureBuilder, payload_layout: layout.Idx) layout.Idx {
        const payload_layout_value = self.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag == .list) return payload_layout_value.getIdx();
        if (payload_layout_value.tag == .list_of_zst) return .zst;
        boxyLowerInvariant("list descriptor had non-list payload layout");
    }

    fn descriptorStorageRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.plan.representations.items[@backingInt(current)];
            if (rep.kind == .alias) {
                current = self.singleChildRepForDesc(current, .alias_backing) orelse
                    boxyLowerInvariant("alias descriptor representation had no backing child");
            } else if (rep.kind == .nominal) {
                switch (rep.kind.nominal) {
                    .transparent => {
                        if (rep.declared_fields.len != 0 or
                            rep.nominal_backing_arg_substitutions.len != 0) return current;
                        current = self.singleChildRepForDesc(current, .nominal_backing) orelse
                            boxyLowerInvariant("transparent nominal descriptor representation had no backing child");
                    },
                    .opaque_nominal, .builtin_other => return current,
                }
            } else if (rep.kind == .box) {
                const child = self.singleChildRepForDesc(current, .box_payload) orelse
                    boxyLowerInvariant("box descriptor representation had no payload child");
                if (self.layout_plan.rep_layouts[@backingInt(current)].worker.layoutIdx() != self.layout_plan.rep_layouts[@backingInt(child)].worker.layoutIdx()) return current;
                current = child;
            } else {
                return current;
            }
        }
    }

    fn descriptorIdentityRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            if (self.plan.repOwnsDescriptorMethod(current)) return current;

            const rep = self.plan.representations.items[@backingInt(current)];
            // An opaque type's descriptor must keep its opacity.
            if (rep.inspect_opaque) return current;
            if (rep.kind == .alias) {
                current = self.singleChildRepForDesc(current, .alias_backing) orelse
                    boxyLowerInvariant("alias descriptor identity had no backing child");
            } else if (rep.kind == .nominal) {
                switch (rep.kind.nominal) {
                    .transparent => {
                        if (rep.declared_fields.len != 0 or
                            rep.nominal_backing_arg_substitutions.len != 0) return current;
                        current = self.singleChildRepForDesc(current, .nominal_backing) orelse
                            boxyLowerInvariant("transparent nominal descriptor identity had no backing child");
                    },
                    .opaque_nominal, .builtin_other => return current,
                }
            } else if (rep.kind == .box) {
                const child = self.singleChildRepForDesc(current, .box_payload) orelse
                    boxyLowerInvariant("box descriptor identity had no payload child");
                if (self.layout_plan.rep_layouts[@backingInt(current)].worker.layoutIdx() != self.layout_plan.rep_layouts[@backingInt(child)].worker.layoutIdx()) return current;
                current = child;
            } else {
                return current;
            }
        }
    }

    fn descriptorBackingShapeRep(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        const rep = self.plan.representations.items[@backingInt(rep_id)];
        if (rep.kind == .alias) return self.singleChildRepForDesc(rep_id, .alias_backing);
        if (rep.kind == .nominal) {
            return switch (rep.kind.nominal) {
                .transparent => if (rep.declared_fields.len == 0)
                    self.singleChildRepForDesc(rep_id, .nominal_backing)
                else
                    null,
                .builtin_other => self.singleChildRepForDesc(rep_id, .nominal_backing),
                .opaque_nominal => null,
            };
        }
        return null;
    }

    fn repNeedsTagPayloadDesc(self: *const ProcedureBuilder, root: Plan.TypeRepId) bool {
        var rep_id = root;
        while (true) {
            const rep = self.plan.representations.items[@backingInt(rep_id)];
            if (rep.descriptor != null) return true;
            return switch (rep.kind) {
                .tag_union,
                .bool_tag_union,
                .record,
                .tuple,
                .list,
                .box,
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                => true,
                .alias => {
                    rep_id = self.singleChildRepForDesc(rep_id, .alias_backing) orelse return true;
                    continue;
                },
                .nominal => {
                    rep_id = self.singleChildRepForDesc(rep_id, .nominal_backing) orelse return true;
                    continue;
                },
                .primitive => |primitive| Common.primitiveInspectLowering(primitive) == .builtin_method,
                .in_progress,
                .dynamic,
                .erased_callable,
                .empty_record,
                .empty_tag_union,
                => false,
            };
        }
    }

    fn singleChildRepForDesc(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId, role: Plan.ChildRole) ?Plan.TypeRepId {
        const rep = self.plan.representations.items[@backingInt(rep_id)];
        var found: ?Plan.TypeRepId = null;
        for (self.plan.childSlice(rep.children)) |child| {
            if (!std.meta.eql(child.role, role)) continue;
            if (found != null) return null;
            found = child.rep;
        }
        return found;
    }

    fn findMatchingTagVariant(
        self: *ProcedureBuilder,
        variants: []const Plan.TagVariant,
        target: Plan.TagVariant,
    ) ?Plan.TagVariant {
        const target_name = self.tagVariantNameText(target);
        for (variants) |variant| {
            if (std.mem.eql(u8, self.tagVariantNameText(variant), target_name)) return variant;
        }
        return null;
    }

    fn tagVariantNameText(self: *const ProcedureBuilder, variant: Plan.TagVariant) []const u8 {
        const module = procedureModuleById(self.modules, variant.name_module);
        return module.canonical_names.tagLabelText(variant.name);
    }

    fn repInspectsOpaque(self: *const ProcedureBuilder, rep_id: Plan.TypeRepId) bool {
        return self.plan.representations.items[@backingInt(rep_id)].inspect_opaque;
    }

    /// Record field names for a record-shaped representation, one per payload
    /// field in payload field order. Returns an empty span for non-record
    /// shapes (tuples and other payloads print positionally). An alias or
    /// backed nominal stores exactly its backing's fields, so it names them; a
    /// structural record can then receive it by field name. A declared
    /// nominal's unnamed padding field is named `padding_field`.
    fn staticFieldNamesForRep(self: *ProcedureBuilder, root: Plan.TypeRepId) Allocator.Error!LIR.BoxySpan {
        // Field names describe the same payload the nested descriptors do.
        var rep_id = root;
        while (self.descriptorBackingShapeRep(rep_id)) |backing_rep| rep_id = backing_rep;
        const rep = self.plan.representations.items[@backingInt(rep_id)];

        var field_name_ids = std.ArrayList(LIR.BoxyNameId).empty;
        defer field_name_ids.deinit(self.allocator);
        if (rep.declared_fields.len != 0) {
            // A declared field's index is its payload field index; it names
            // the backing record field with that structural rank.
            const backing = self.singleChildRepForDesc(rep_id, .nominal_backing) orelse
                boxyLowerInvariant("declared-field nominal had no backing record");
            var backing_fields = std.ArrayList(Plan.RepChild).empty;
            defer backing_fields.deinit(self.allocator);
            for (self.plan.childSlice(self.plan.representations.items[@backingInt(backing)].children)) |child| {
                if (child.role == .record_field) try backing_fields.append(self.allocator, child);
            }
            const declared = self.plan.declaredFieldSlice(rep.declared_fields);
            try field_name_ids.resize(self.allocator, declared.len);
            for (declared) |field| {
                if (field.index >= declared.len) {
                    boxyLowerInvariant("declared nominal field index exceeded its declared fields");
                }
                if (field.is_padding) {
                    field_name_ids.items[field.index] = .padding_field;
                    continue;
                }
                if (field.index >= backing_fields.items.len) {
                    boxyLowerInvariant("declared nominal field index exceeded its backing record fields");
                }
                const child = backing_fields.items[field.index];
                const view = procedureModuleById(self.modules, child.source_type.module);
                field_name_ids.items[field.index] = try self.result.store.insertBoxyName(
                    view.canonical_names.recordFieldLabelText(child.role.record_field),
                );
            }
            const start: u32 = @intCast(self.result.boxy_field_names.items.len);
            try self.result.boxy_field_names.appendSlice(self.allocator, field_name_ids.items);
            return .{ .start = start, .len = @intCast(field_name_ids.items.len) };
        }
        for (self.plan.childSlice(rep.children)) |child| {
            if (child.role == .record_field) {
                const view = procedureModuleById(self.modules, child.source_type.module);
                try field_name_ids.append(
                    self.allocator,
                    try self.result.store.insertBoxyName(view.canonical_names.recordFieldLabelText(child.role.record_field)),
                );
            } else if (child.role != .record_ext) {
                return .{};
            }
        }
        if (field_name_ids.items.len == 0) return .{};

        const start: u32 = @intCast(self.result.boxy_field_names.items.len);
        try self.result.boxy_field_names.appendSlice(self.allocator, field_name_ids.items);
        return .{ .start = start, .len = @intCast(field_name_ids.items.len) };
    }

    fn initHostedCatalog(self: *ProcedureBuilder) Allocator.Error!void {
        if (self.resolved_workers.items.len == 0) return;

        var entries = std.ArrayList(HostedCatalogEntry).empty;
        defer entries.deinit(self.allocator);

        try self.appendHostedCatalogFromModule(&entries, rootProcedureModule(self.modules));
        for (self.modules.imports, 0..) |imported, index| {
            if (self.importModuleAlreadyScanned(imported.key, index)) continue;
            try self.appendHostedCatalogFromModule(&entries, procedureModuleFromImport(imported));
        }
        for (self.modules.root.relation_modules, 0..) |relation, index| {
            if (self.relationModuleAlreadyScanned(relation.key, index)) continue;
            try self.appendHostedCatalogFromModule(&entries, procedureModuleFromImport(relation));
        }

        if (self.hostedBindingView()) |binding_view| {
            // The platform header's hosted section is what gives each hosted
            // function its linker symbol and its host dispatch slot, so build
            // the catalog from the bindings checking output for that section
            // rather than from every hosted declaration in scope.
            var declared_by_target = std.AutoHashMap(HostedProcedureKey, usize).init(self.allocator);
            defer declared_by_target.deinit();
            try declared_by_target.ensureTotalCapacity(@intCast(entries.items.len));
            for (entries.items, 0..) |entry, index| {
                declared_by_target.putAssumeCapacityNoClobber(.{
                    .module_key = entry.module_key,
                    .def_idx = entry.def_idx,
                }, index);
            }

            var bound = std.ArrayList(HostedCatalogEntry).empty;
            errdefer bound.deinit(self.allocator);
            try bound.ensureTotalCapacity(self.allocator, binding_view.table.bindings.len);
            for (binding_view.table.bindings, 0..) |binding, dispatch_index| {
                const entry_index = declared_by_target.get(.{
                    .module_key = binding.target_checked_module.bytes,
                    .def_idx = @backingInt(binding.target_def),
                }) orelse boxyLowerInvariant("hosted section names a function with no hosted declaration in scope");
                var entry = entries.items[entry_index];
                entry.dispatch_index = @intCast(dispatch_index);
                entry.symbol_text = binding_view.names.externalSymbolNameText(binding.external_symbol_name);
                bound.appendAssumeCapacity(entry);
            }

            // Bindings are walked in declaration order, so the catalog is
            // already ordered by dispatch index.
            self.hosted_catalog = try bound.toOwnedSlice(self.allocator);
            return;
        }

        // Without a platform header there is no section to bind against, so
        // every declaration in scope is its own dispatch slot in a stable order.
        const SortContext = struct {
            pub fn lessThan(_: void, a: HostedCatalogEntry, b: HostedCatalogEntry) bool {
                return switch (std.mem.order(u8, a.order, b.order)) {
                    .lt => true,
                    .gt => false,
                    // Two modules can declare the same order key at the same def
                    // index, so the owning module breaks the remaining tie the
                    // way Monotype and the default roc command both break it.
                    .eq => if (a.def_idx != b.def_idx)
                        a.def_idx < b.def_idx
                    else
                        std.mem.order(u8, &a.module_key, &b.module_key) == .lt,
                };
            }
        };
        std.mem.sort(HostedCatalogEntry, entries.items, {}, SortContext.lessThan);

        for (entries.items, 0..) |*entry, index| {
            entry.dispatch_index = @intCast(index);
        }

        self.hosted_catalog = try entries.toOwnedSlice(self.allocator);
    }

    /// The hosted bindings of the one platform module visible to this lowering.
    fn hostedBindingView(self: *ProcedureBuilder) ?HostedBindingView {
        if (self.modules.root.module.module_identity.kind == .platform) {
            return .{
                .table = &self.modules.root.module.hosted_bindings,
                .names = &self.modules.root.module.canonical_names,
            };
        }
        for (self.modules.imports) |imported| {
            if (imported.module_identity.kind == .platform) {
                return .{ .table = imported.hosted_bindings, .names = imported.canonical_names };
            }
        }
        for (self.modules.root.relation_modules) |relation| {
            if (relation.module_identity.kind == .platform) {
                return .{ .table = relation.hosted_bindings, .names = relation.canonical_names };
            }
        }
        return null;
    }

    fn appendHostedCatalogFromModule(
        self: *ProcedureBuilder,
        entries: *std.ArrayList(HostedCatalogEntry),
        module: ProcedureModuleView,
    ) Allocator.Error!void {
        for (module.hosted_procs.procs) |hosted| {
            try entries.append(self.allocator, .{
                .template = hosted.template,
                .symbol_text = module.canonical_names.externalSymbolNameText(hosted.external_symbol_name),
                .dispatch_index = 0,
                .order = hosted.orderKey(module.hosted_procs),
                .module_key = module.key.bytes,
                .def_idx = @backingInt(hosted.def_idx),
            });
        }
    }

    fn importModuleAlreadyScanned(self: *ProcedureBuilder, module_key: checked.CheckedModuleArtifactKey, import_index: usize) bool {
        if (checked_moduleKeyEqual(module_key, self.modules.root.module.key)) return true;
        for (self.modules.imports[0..import_index]) |imported| {
            if (checked_moduleKeyEqual(module_key, imported.key)) return true;
        }
        return false;
    }

    fn relationModuleAlreadyScanned(self: *ProcedureBuilder, module_key: checked.CheckedModuleArtifactKey, relation_index: usize) bool {
        if (checked_moduleKeyEqual(module_key, self.modules.root.module.key)) return true;
        for (self.modules.imports) |imported| {
            if (checked_moduleKeyEqual(module_key, imported.key)) return true;
        }
        for (self.modules.root.relation_modules[0..relation_index]) |relation| {
            if (checked_moduleKeyEqual(module_key, relation.key)) return true;
        }
        return false;
    }

    fn lirHostedProcForTemplate(self: *ProcedureBuilder, template_ref: names.ProcedureTemplateRef) Allocator.Error!LIR.HostedProc {
        for (self.hosted_catalog) |entry| {
            if (!names.procedureTemplateRefEql(entry.template, template_ref)) continue;
            return .{
                .symbol = try self.result.store.insertString(entry.symbol_text),
                .dispatch_index = entry.dispatch_index,
            };
        }
        boxyLowerInvariant("hosted procedure template was not output in the hosted catalog");
    }

    fn emitRoots(self: *ProcedureBuilder, roots: Common.RootRequests) Allocator.Error!void {
        self.worker_procs = try self.allocator.alloc(?LIR.LirProcSpecId, self.resolved_workers.items.len);
        @memset(self.worker_procs, null);
        self.erased_worker_procs = try self.allocator.alloc(?LIR.LirProcSpecId, self.resolved_workers.items.len);
        @memset(self.erased_worker_procs, null);
        self.hosted_external_procs = try self.allocator.alloc(?LIR.LirProcSpecId, self.resolved_workers.items.len);
        @memset(self.hosted_external_procs, null);
        self.worker_jobs = try self.allocator.alloc(?u32, self.resolved_workers.items.len);
        @memset(self.worker_jobs, null);
        self.worker_return_locals = try self.allocator.alloc(?LIR.LocalId, self.resolved_workers.items.len);
        @memset(self.worker_return_locals, null);

        if (self.plan.literal_evidence) |*evidence| {
            try self.literal_dicts.appendNTimes(self.allocator, null, evidence.initializers.items.len);
            try self.result.literal_roots.appendNTimes(self.allocator, undefined, evidence.initializers.items.len);
            self.literal_const_plans = try ConstPlanBuilder.init(self.allocator, self.modules, self.plan, self.layout_plan, self, self.result);
            for (evidence.initializers.items, 0..) |_, index| _ = try self.emitLiteralAccessor(@intCast(index));
        }

        for (self.plan.roots.items, self.layout_plan.roots.items) |root, root_layout| {
            if (root.id != root_layout.root) boxyLowerInvariant("boxy root layout table disagreed with root plan order");
            if (root.worker != root_layout.worker) boxyLowerInvariant("boxy root layout table disagreed with root worker plan");
            _ = try self.reserveWorkerProc(root.worker);
        }
        // Host wrappers read their workers' finished signatures.
        try self.runProcJobs();

        for (self.plan.roots.items, self.layout_plan.roots.items, 0..) |root, root_layout, request_index| {
            const worker_layout = self.layout_plan.workerLayoutFor(root.worker);
            const worker_proc = try self.reserveWorkerProc(root.worker);
            const worker_plan = self.plan.workers.items[@backingInt(root.worker)];
            const hidden_count = self.plan.hiddenDescriptorParamSlice(worker_plan.hidden_descs).len +
                self.plan.hiddenDictionaryParamSlice(worker_plan.hidden_dicts).len;
            const host_arg_count = self.layout_plan.rootLayoutSlice(root_layout.host_args).len;
            const worker_arg_count = self.result.store.getLocalSpan(self.result.store.getProcSpec(worker_proc).args).len;
            // Hidden worker parameters never cross the platform boundary; when
            // the host-facing arity plus the hidden parameters reconciles with
            // the worker's actual arity, wrap the worker and materialize the
            // hidden arguments statically.
            const needs_hidden_wrapper = hidden_count != 0 and host_arg_count + hidden_count == worker_arg_count;
            const root_proc = if (needs_hidden_wrapper or root.wrapper_kind == .host_shaped_wrapper)
                try self.emitHostWrapper(root_layout, worker_layout, worker_proc, worker_plan)
            else
                worker_proc;
            if (self.options.proc_debug_names and root.wrapper_kind == .host_shaped_wrapper) {
                try self.result.store.copyProcDebugInfo(root_proc, worker_proc);
            }
            try self.result.root_procs.append(self.allocator, root_proc);
            var metadata = RootMetadata.fromCheckedRoot(root.request);
            metadata.test_plan = Common.testPlanMetadataForRoot(roots, root.request, request_index);
            try self.result.root_metadata.append(self.allocator, metadata);
        }
        try self.runProcJobs();
    }

    /// Descriptor templates remain mutable graph reservations while lowering
    /// is active. Finalize capture closure only after every recursive
    /// reservation has been filled, before ARC or a backend consumes LIR.
    fn finalizeDescriptorMaterializationCaptures(self: *ProcedureBuilder) Allocator.Error!void {
        var capture_sets = try self.buildDescriptorCaptureSets();
        defer capture_sets.deinit();

        var proc_index: usize = 0;
        while (proc_index < self.result.store.procSpecCount()) : (proc_index += 1) {
            const proc_id: LIR.LirProcSpecId = @fromBackingInt(@intCast(@as(u32, @intCast(proc_index))));
            const body = self.result.store.getProcSpec(proc_id).body orelse continue;

            var visited = std.AutoHashMap(u32, void).init(self.allocator);
            defer visited.deinit();
            var stack = std.ArrayList(LIR.CFStmtId).empty;
            defer stack.deinit(self.allocator);
            try stack.append(self.allocator, body);

            while (stack.pop()) |stmt_id| {
                const entry = try visited.getOrPut(@backingInt(stmt_id));
                if (entry.found_existing) continue;

                switch (self.result.store.getCFStmt(stmt_id)) {
                    .assign_boxy_desc_ref => |assign| {
                        try stack.append(self.allocator, assign.next);
                        const desc_id = switch (assign.desc) {
                            .static => |id| id,
                            .local, .runtime, .dict_method_arg, .dict_method_hidden => continue,
                        };
                        const captures = capture_sets.items[@backingInt(desc_id)].items;
                        if (std.mem.findScalar(LIR.LocalId, captures, assign.target) != null) {
                            boxyLowerInvariant("boxy descriptor materialization template captured its own output local");
                        }
                        var updated = assign;
                        updated.captures = if (captures.len == 0)
                            LIR.LocalSpan.empty()
                        else
                            try self.result.store.addLocalSpan(captures);
                        self.result.store.getCFStmtPtr(stmt_id).* = .{ .assign_boxy_desc_ref = updated };
                    },
                    inline .assign_ref,
                    .assign_literal,
                    .init_uninitialized,
                    .assign_call,
                    .assign_call_erased,
                    .assign_packed_erased_fn,
                    .assign_boxy_dict_ref,
                    .assign_boxy_box,
                    .assign_boxy_record_update,
                    .assign_boxy_reuse_box,
                    .assign_boxy_unbox,
                    .assign_boxy_adapt,
                    .assign_boxy_inspect,
                    .assign_boxy_eq,
                    .assign_boxy_hash,
                    .assign_boxy_tag,
                    .assign_boxy_tag_payload,
                    .assign_call_dict,
                    .assign_low_level,
                    .assign_list,
                    .assign_struct,
                    .assign_tag,
                    .store_struct,
                    .store_tag,
                    .set_local,
                    .debug,
                    .expect,
                    .comptime_branch_taken,
                    .incref,
                    .decref,
                    .decref_if_initialized,
                    .free,
                    => |stmt| try stack.append(self.allocator, stmt.next),
                    .switch_stmt => |stmt| {
                        const branches = self.result.store.getCFSwitchBranches(stmt.branches);
                        for (0..GuardedList.borrowLen(branches)) |index| {
                            try stack.append(self.allocator, GuardedList.at(branches, index).body);
                        }
                        try stack.append(self.allocator, stmt.default_branch);
                        if (stmt.continuation) |continuation| try stack.append(self.allocator, continuation);
                    },
                    .switch_initialized_payload => |stmt| {
                        try stack.append(self.allocator, stmt.initialized_branch);
                        try stack.append(self.allocator, stmt.uninitialized_branch);
                    },
                    .str_match => |stmt| {
                        try stack.append(self.allocator, stmt.on_match);
                        try stack.append(self.allocator, stmt.on_miss);
                    },
                    .str_match_set => |stmt| {
                        const arms = self.result.store.getStrMatchArms(stmt.arms);
                        for (0..GuardedList.borrowLen(arms)) |index| {
                            try stack.append(self.allocator, GuardedList.at(arms, index).on_match);
                        }
                        try stack.append(self.allocator, stmt.on_miss);
                    },
                    .boxy_tag_match => |stmt| {
                        try stack.append(self.allocator, stmt.on_match);
                        try stack.append(self.allocator, stmt.on_miss);
                    },
                    .join => |stmt| {
                        try stack.append(self.allocator, stmt.body);
                        try stack.append(self.allocator, stmt.remainder);
                    },
                    .jump,
                    .ret,
                    .crash,
                    .expect_err,
                    .runtime_error,
                    .comptime_exhaustiveness_failed,
                    .loop_continue,
                    .loop_break,
                    => {},
                }
            }
        }
    }

    fn buildDescriptorCaptureSets(self: *ProcedureBuilder) Allocator.Error!DescriptorCaptureSets {
        const desc_count = self.result.boxy_type_descs.items.len;
        const captures = try self.allocator.alloc(std.ArrayList(LIR.LocalId), desc_count);
        for (captures) |*capture_set| capture_set.* = .empty;
        errdefer {
            for (captures) |*capture_set| capture_set.deinit(self.allocator);
            self.allocator.free(captures);
        }

        const parents = try self.allocator.alloc(std.ArrayList(LIR.BoxyTypeDescId), desc_count);
        for (parents) |*parent_set| parent_set.* = .empty;
        errdefer {
            for (parents) |*parent_set| parent_set.deinit(self.allocator);
            self.allocator.free(parents);
        }

        for (self.result.boxy_type_descs.items, 0..) |desc, parent_index| {
            const parent: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(parent_index))));
            try self.collectDescriptorGraphRefs(desc.nested_descs, parent, captures, parents);
            try self.collectDescriptorGraphRefs(desc.inspect_hidden_descs, parent, captures, parents);
            try self.collectDescriptorGraphRefs(desc.inspect_arg_descs, parent, captures, parents);
            try self.collectDescriptorGraphRefs(desc.eq_hidden_descs, parent, captures, parents);
            try self.collectDescriptorGraphRefs(desc.eq_arg_descs, parent, captures, parents);
            try self.collectDescriptorGraphRefs(desc.hash_hidden_descs, parent, captures, parents);
            try self.collectDescriptorGraphRefs(desc.hash_arg_descs, parent, captures, parents);
            if (desc.tag_ext_desc) |desc_ref| {
                try self.collectDescriptorGraphRef(desc_ref, parent, captures, parents);
            }

            const variant_start: usize = desc.tag_variants.start;
            const variant_end = variant_start + desc.tag_variants.len;
            if (variant_end > self.result.boxy_tag_variants.items.len) {
                boxyLowerInvariant("boxy descriptor tag variant span exceeded its table");
            }
            for (self.result.boxy_tag_variants.items[variant_start..variant_end]) |variant| {
                const payload_start: usize = variant.payload_descs.start;
                const payload_end = payload_start + variant.payload_descs.len;
                if (payload_end > self.result.boxy_tag_payload_descs.items.len) {
                    boxyLowerInvariant("boxy descriptor tag payload span exceeded its table");
                }
                for (self.result.boxy_tag_payload_descs.items[payload_start..payload_end]) |payload| {
                    try self.collectDescriptorGraphRef(payload.desc, parent, captures, parents);
                }
            }

            try self.collectDescriptorPayloadStepRefs(desc.copy_plan, parent, captures, parents);
            try self.collectDescriptorPayloadStepRefs(desc.drop_plan, parent, captures, parents);
        }

        var queue = std.ArrayList(LIR.BoxyTypeDescId).empty;
        defer queue.deinit(self.allocator);
        const queued = try self.allocator.alloc(bool, desc_count);
        defer self.allocator.free(queued);
        @memset(queued, true);
        for (0..desc_count) |index| {
            try queue.append(self.allocator, @fromBackingInt(@intCast(@as(u32, @intCast(index)))));
        }

        var read_index: usize = 0;
        while (read_index < queue.items.len) : (read_index += 1) {
            const child = queue.items[read_index];
            queued[@backingInt(child)] = false;
            for (parents[@backingInt(child)].items) |parent| {
                var changed = false;
                for (captures[@backingInt(child)].items) |local| {
                    const parent_captures = &captures[@backingInt(parent)];
                    if (std.mem.findScalar(LIR.LocalId, parent_captures.items, local) != null) continue;
                    try parent_captures.append(self.allocator, local);
                    changed = true;
                }
                if (changed and !queued[@backingInt(parent)]) {
                    queued[@backingInt(parent)] = true;
                    try queue.append(self.allocator, parent);
                }
            }
        }

        for (captures) |*capture_set| {
            const Sort = struct {
                fn lessThan(_: void, a: LIR.LocalId, b: LIR.LocalId) bool {
                    return @backingInt(a) < @backingInt(b);
                }
            };
            std.mem.sort(LIR.LocalId, capture_set.items, {}, Sort.lessThan);
        }
        for (parents) |*parent_set| parent_set.deinit(self.allocator);
        self.allocator.free(parents);
        return .{ .allocator = self.allocator, .items = captures };
    }

    fn collectDescriptorGraphRefs(
        self: *ProcedureBuilder,
        span: LIR.BoxySpan,
        parent: LIR.BoxyTypeDescId,
        captures: []std.ArrayList(LIR.LocalId),
        parents: []std.ArrayList(LIR.BoxyTypeDescId),
    ) Allocator.Error!void {
        const start: usize = span.start;
        const end = start + span.len;
        if (end > self.result.boxy_desc_refs.items.len) {
            boxyLowerInvariant("boxy descriptor reference span exceeded its table");
        }
        for (self.result.boxy_desc_refs.items[start..end]) |desc_ref| {
            try self.collectDescriptorGraphRef(desc_ref, parent, captures, parents);
        }
    }

    fn collectDescriptorPayloadStepRefs(
        self: *ProcedureBuilder,
        span: LIR.BoxySpan,
        parent: LIR.BoxyTypeDescId,
        captures: []std.ArrayList(LIR.LocalId),
        parents: []std.ArrayList(LIR.BoxyTypeDescId),
    ) Allocator.Error!void {
        const start: usize = span.start;
        const end = start + span.len;
        if (end > self.result.boxy_payload_steps.items.len) {
            boxyLowerInvariant("boxy descriptor payload step span exceeded its table");
        }
        for (self.result.boxy_payload_steps.items[start..end]) |step| {
            switch (step) {
                .concrete => {},
                .dynamic => |dynamic| try self.collectDescriptorGraphRef(dynamic.desc, parent, captures, parents),
            }
        }
    }

    fn collectDescriptorGraphRef(
        self: *ProcedureBuilder,
        desc_ref: LIR.BoxyDescRef,
        parent: LIR.BoxyTypeDescId,
        captures: []std.ArrayList(LIR.LocalId),
        parents: []std.ArrayList(LIR.BoxyTypeDescId),
    ) Allocator.Error!void {
        switch (desc_ref) {
            .local => |local| {
                const set = &captures[@backingInt(parent)];
                if (std.mem.findScalar(LIR.LocalId, set.items, local) == null) {
                    try set.append(self.allocator, local);
                }
            },
            .static => |child| {
                if (@backingInt(child) >= captures.len) {
                    boxyLowerInvariant("boxy descriptor graph referenced a missing static descriptor");
                }
                const reverse = &parents[@backingInt(child)];
                if (std.mem.findScalar(LIR.BoxyTypeDescId, reverse.items, parent) == null) {
                    try reverse.append(self.allocator, parent);
                }
            },
            .runtime, .dict_method_arg, .dict_method_hidden => {},
        }
    }

    /// A procedure whose header is reserved at its first reference and whose
    /// body the emission scheduler builds later, so building one body never
    /// builds another.
    const ProcJob = struct {
        status: enum {
            /// Reserved; the body is not started.
            queued,
            /// On the scheduler's stack while the workers its body calls
            /// directly are built first.
            waiting,
            finished,
        } = .queued,
        /// The body still to build; null once built.
        body: ?union(enum) {
            worker: *WorkerJob,
            derived: *DerivedJob,
            callable_adapter: *CallableAdapterJob,
            static_method_adapter: *StaticMethodAdapterJob,
            /// A literal conversion's procedures, filling its reserved
            /// dictionary's method slot.
            literal: struct { index: u32, method_slot: u32 },
            crashing_method: struct { proc_id: LIR.LirProcSpecId, fn_type: Plan.CheckedTypeIdentity, crash: CrashingDictionaryMethod },
        },
    };

    /// A worker's procedure, or its erased-callable entry, whose header and
    /// body are built by the scheduler.
    const WorkerJob = struct {
        worker: Plan.WorkerPlanId,
        proc_id: LIR.LirProcSpecId,
        erased: bool,
        header: ?WorkerHeader = null,
    };

    /// The builder a worker's header set up, which its body continues.
    const WorkerHeader = struct {
        proc: ProcBodyBuilder,
        body_source: WorkerBodySource,
        ret_local: LIR.LocalId,
        args_span: LIR.LocalSpan,
        erased: ?struct {
            worker_function: ProcBodyBuilder.FunctionChildren,
            erased_arg_desc_params: LIR.BoxySpan,
        },
    };

    fn freeProcJobBody(self: *ProcedureBuilder, job: *ProcJob) void {
        const body = job.body orelse return;
        job.body = null;
        switch (body) {
            .worker => |worker_job| {
                if (worker_job.header) |*header| header.proc.deinit();
                self.allocator.destroy(worker_job);
            },
            .derived => |derived_job| {
                if (derived_job.header) |*header| header.proc.deinit();
                derived_job.shape.deinit(self.allocator);
                self.allocator.destroy(derived_job);
            },
            .callable_adapter => |adapter_job| {
                adapter_job.deinit(self.allocator);
                self.allocator.destroy(adapter_job);
            },
            .static_method_adapter => |adapter_job| {
                adapter_job.deinit(self.allocator);
                self.allocator.destroy(adapter_job);
            },
            .literal, .crashing_method => {},
        }
    }

    fn appendProcJob(self: *ProcedureBuilder, body: @FieldType(ProcJob, "body")) Allocator.Error!void {
        const index: u32 = @intCast(self.proc_jobs.items.len);
        try self.proc_jobs.ensureUnusedCapacity(self.allocator, 1);
        try self.queued_proc_jobs.append(self.allocator, index);
        self.proc_jobs.appendAssumeCapacity(.{ .body = body });
    }

    /// The workers `worker` calls directly, as the plan records them: the
    /// callees whose finished signatures its body's call sites read.
    fn plannedDirectCallees(self: *ProcedureBuilder, worker: Plan.WorkerPlanId) Allocator.Error![]const Plan.WorkerPlanId {
        if (self.planned_direct_callee_starts.len == 0) {
            const worker_count = self.plan.workers.items.len;
            const starts = try self.allocator.alloc(u32, worker_count + 1);
            errdefer self.allocator.free(starts);
            @memset(starts, 0);
            inline for (.{ "direct_calls", "iterator_calls", "generated_codec_calls" }) |table| {
                for (@field(self.plan, table).items) |call| starts[@backingInt(call.caller) + 1] += 1;
            }
            for (1..starts.len) |index| starts[index] += starts[index - 1];
            const callees = try self.allocator.alloc(Plan.WorkerPlanId, starts[worker_count]);
            errdefer self.allocator.free(callees);
            const cursors = try self.allocator.dupe(u32, starts[0..worker_count]);
            defer self.allocator.free(cursors);
            inline for (.{ "direct_calls", "iterator_calls", "generated_codec_calls" }) |table| {
                for (@field(self.plan, table).items) |call| {
                    const caller = @backingInt(call.caller);
                    callees[cursors[caller]] = call.worker;
                    cursors[caller] += 1;
                }
            }
            self.planned_direct_callee_starts = starts;
            self.planned_direct_callees = callees;
        }
        const index = @backingInt(worker);
        return self.planned_direct_callees[self.planned_direct_callee_starts[index]..self.planned_direct_callee_starts[index + 1]];
    }

    /// Build every reserved body. A job's body first waits on the workers it
    /// calls directly, so their signatures are final at its call sites; a
    /// callee already waiting (a cycle) is called through the provisional
    /// descriptor ABI resolved when it finishes. Bodies build in reservation
    /// order otherwise.
    fn runProcJobs(self: *ProcedureBuilder) Allocator.Error!void {
        while (true) {
            if (self.proc_job_stack.items.len != 0) {
                const job_index = self.proc_job_stack.items[self.proc_job_stack.items.len - 1];
                switch (self.proc_jobs.items[job_index].status) {
                    .finished => self.proc_job_stack.items.len -= 1,
                    .queued => {
                        self.proc_jobs.items[job_index].status = .waiting;
                        try self.pushProcJobCallees(job_index);
                    },
                    .waiting => {
                        self.proc_job_stack.items.len -= 1;
                        try self.buildProcJob(job_index);
                    },
                }
                continue;
            }
            if (self.next_queued_proc_job == self.queued_proc_jobs.items.len) return;
            const next = self.queued_proc_jobs.items[self.next_queued_proc_job];
            self.next_queued_proc_job += 1;
            if (self.proc_jobs.items[next].status == .queued) {
                try self.proc_job_stack.append(self.allocator, next);
            }
        }
    }

    /// Push the unstarted jobs of the workers `job_index`'s body calls
    /// directly, first callee on top.
    fn pushProcJobCallees(self: *ProcedureBuilder, job_index: u32) Allocator.Error!void {
        const body = self.proc_jobs.items[job_index].body orelse
            boxyLowerInvariant("boxy emission job waited after its body was built");
        switch (body) {
            .worker => |worker_job| {
                try self.buildWorkerHeader(worker_job);
                const callees = try self.plannedDirectCallees(worker_job.worker);
                var index = callees.len;
                while (index > 0) {
                    index -= 1;
                    try self.pushWorkerJob(callees[index]);
                }
            },
            .static_method_adapter => |adapter_job| {
                try self.buildStaticMethodAdapterHeader(adapter_job);
                try self.pushWorkerJob(adapter_job.worker_id);
            },
            .derived => |derived_job| try self.buildDerivedHeader(derived_job),
            .callable_adapter, .literal, .crashing_method => {},
        }
    }

    fn pushWorkerJob(self: *ProcedureBuilder, worker: Plan.WorkerPlanId) Allocator.Error!void {
        _ = try self.reserveWorkerProc(worker);
        const job_index = self.worker_jobs[@backingInt(worker)] orelse
            boxyLowerInvariant("reserved boxy worker had no emission job");
        if (self.proc_jobs.items[job_index].status == .queued) {
            try self.proc_job_stack.append(self.allocator, job_index);
        }
    }

    fn buildProcJob(self: *ProcedureBuilder, job_index: u32) Allocator.Error!void {
        const body = self.proc_jobs.items[job_index].body orelse
            boxyLowerInvariant("boxy emission job was built twice");
        switch (body) {
            .worker => |worker_job| if (worker_job.erased)
                try self.buildErasedWorkerBody(worker_job)
            else
                try self.buildWorkerBody(worker_job),
            .derived => |derived_job| try self.buildDerivedBody(derived_job),
            .callable_adapter => |adapter_job| try self.buildCallableAdapterBody(adapter_job),
            .static_method_adapter => |adapter_job| try self.buildStaticMethodAdapterBody(adapter_job),
            .literal => |literal| try self.buildLiteralAccessor(literal.index, literal.method_slot),
            .crashing_method => |method| try self.buildCrashingDictionaryMethod(method.proc_id, method.fn_type, method.crash),
        }
        const job = &self.proc_jobs.items[job_index];
        job.status = .finished;
        self.freeProcJobBody(job);
    }

    /// The worker's procedure, reserving its id and queueing its header and
    /// body at the first reference.
    fn reserveWorkerProc(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
    ) Allocator.Error!LIR.LirProcSpecId {
        return try self.reserveWorkerJobProc(worker_id, false);
    }

    fn reserveErasedWorkerProc(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
    ) Allocator.Error!LIR.LirProcSpecId {
        return try self.reserveWorkerJobProc(worker_id, true);
    }

    fn reserveWorkerJobProc(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        erased: bool,
    ) Allocator.Error!LIR.LirProcSpecId {
        const index = @backingInt(worker_id);
        const procs = if (erased) self.erased_worker_procs else self.worker_procs;
        if (index >= procs.len) boxyLowerInvariant("boxy procedure referenced a missing worker proc");
        if (procs[index]) |existing| return existing;

        const resolved = self.resolved_workers.items[index];
        const worker_layout = self.layout_plan.workerLayoutFor(worker_id);
        const ret_layout = if (worker_layout.ret) |ret| ret.layoutIdx() else worker_layout.value.layoutIdx();
        const proc_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = LIR.LocalSpan.empty(),
            .body = null,
            .ret_layout = ret_layout,
            .abi = if (erased) .erased_callable else .roc,
            .boxy_runtime_entry = erased,
        }, (try self.workerOrigin(resolved)).loc);
        procs[index] = proc_id;
        try self.setProcDebugName(proc_id, resolved);
        const job = try self.allocator.create(WorkerJob);
        errdefer self.allocator.destroy(job);
        job.* = .{
            .worker = worker_id,
            .proc_id = proc_id,
            .erased = erased,
        };
        if (!erased) self.worker_jobs[index] = @intCast(self.proc_jobs.items.len);
        try self.appendProcJob(.{ .worker = job });
        return proc_id;
    }

    /// Build the header of `worker`'s reserved procedure, when it is not
    /// built yet: the builder, arguments, and return local its body and its
    /// callers read.
    fn ensureWorkerHeader(self: *ProcedureBuilder, worker: Plan.WorkerPlanId) Allocator.Error!void {
        _ = try self.reserveWorkerProc(worker);
        const job_index = self.worker_jobs[@backingInt(worker)] orelse
            boxyLowerInvariant("reserved boxy worker had no emission job");
        const body = self.proc_jobs.items[job_index].body orelse return;
        try self.buildWorkerHeader(body.worker);
    }

    fn buildWorkerHeader(self: *ProcedureBuilder, job: *WorkerJob) Allocator.Error!void {
        if (job.header != null) return;
        const worker_id = job.worker;
        const index = @backingInt(worker_id);
        const resolved = self.resolved_workers.items[index];
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        job.header = .{
            .proc = ProcBodyBuilder.init(self, resolved.module, self.layout_plan.workerLayoutFor(worker_id), try self.workerOrigin(resolved)),
            .body_source = undefined,
            .ret_local = undefined,
            .args_span = undefined,
            .erased = null,
        };
        const header = &job.header.?;
        const proc = &header.proc;
        if (!job.erased) {
            proc.erased_argument_descriptors = true;
            header.body_source = try self.bodySourceForWorker(resolved, proc);
            try proc.bindHiddenDescriptorArgs();
            try proc.bindHiddenDictionaryArgs();
            try proc.bindWorkerDictionaryDescriptors();
            try proc.bindLambdaArgDescriptors();
            header.ret_local = try proc.addWorkerReturnLocal(true);
            proc.worker_return_local = header.ret_local;
            header.args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
            self.worker_return_locals[index] = header.ret_local;
            const proc_spec = self.result.store.getProcSpecPtr(job.proc_id);
            proc_spec.args = header.args_span;
            proc_spec.stack_probe = self.stackProbeForProc(header.args_span, LIR.LocalSpan.empty(), proc_spec.ret_layout);
            return;
        }
        header.body_source = try self.bodySourceForWorker(resolved, proc);
        try proc.prepareErasedWorkerCaptures();
        const worker = self.plan.workers.items[index];
        const worker_function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy erased worker representation was not callable");
        const erased_arg_desc_params = try proc.bindErasedArgumentDescriptorParams(worker_function);
        const erased_reuse_arg = try proc.addArgLocal(try self.result.layouts.insertErasedCallable());
        try proc.bindLambdaArgDescriptors();
        header.ret_local = try proc.addWorkerReturnLocal(true);
        proc.worker_return_local = header.ret_local;
        header.args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        header.erased = .{ .worker_function = worker_function, .erased_arg_desc_params = erased_arg_desc_params };
        const erased_call_args = try proc.erasedCallArgsPlan(proc.arg_locals.items[0..worker_function.arg_count]);
        const proc_spec = self.result.store.getProcSpecPtr(job.proc_id);
        proc_spec.args = header.args_span;
        proc_spec.erased_reuse_arg = erased_reuse_arg;
        proc_spec.erased_call_args = erased_call_args;
        proc_spec.stack_probe = self.stackProbeForProc(header.args_span, LIR.LocalSpan.empty(), proc_spec.ret_layout);
    }

    fn buildWorkerBody(self: *ProcedureBuilder, job: *WorkerJob) Allocator.Error!void {
        const resolved = self.resolved_workers.items[@backingInt(job.worker)];
        const header = &(job.header orelse boxyLowerInvariant("boxy worker body was built before its header"));
        const proc = &header.proc;
        const proc_id = job.proc_id;
        const ret_local = header.ret_local;
        const args_span = header.args_span;
        const ret_layout = self.result.store.getProcSpec(proc_id).ret_layout;
        const saved_tail_builder = self.result.store.tail_call_builder;
        defer self.result.store.tail_call_builder = saved_tail_builder;
        var tail_builder = lir_core.TailCallBuilder.init(self.allocator, proc_id);
        defer tail_builder.deinit();
        self.result.store.tail_call_builder = &tail_builder;
        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } }, proc.origin);
        var body_stmt = try self.lowerWorkerBodyInto(resolved, proc, header.body_source, ret_local, ret_stmt);
        body_stmt = try proc.prependWorkerReturnDescriptorInitializers(body_stmt);
        body_stmt = try proc.prependStoredCaptureInitializers(body_stmt);
        body_stmt = try proc.prependStaticDescriptorMaterializationsForSlots(body_stmt);
        // Body descriptor templates may capture rebuilt argument descriptors.
        // Initialize those roots from hidden inputs before consuming them.
        body_stmt = try proc.prependWorkerArgumentDescriptorInitializers(body_stmt);
        const proc_spec = self.result.store.getProcSpecPtr(proc_id);
        proc_spec.body = body_stmt;
        proc_spec.shapes = proc_spec.shapes.merged(self.result.store.shapes);
        const return_desc = try self.returnDescriptorInfoForBody(
            body_stmt,
            args_span,
            self.result.store.getLocal(ret_local).boxy_desc,
            &proc.frame_locals,
        );
        self.requireReturnDescriptorAbi(ret_local, return_desc);
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        proc_spec.frame_locals = frame_span;
        proc_spec.ret_desc = return_desc.external;
        proc_spec.runtime_ret_desc = return_desc.runtime_local;
        proc_spec.stack_probe = self.stackProbeForProc(args_span, frame_span, ret_layout);
        try self.resolvePendingDirectCallDescriptorAbis(proc_id, return_desc.runtime_local != null);
        // All self-call ABI fixups are resolved with this worker's signature.
        // Later descriptor capture finalization does not change continuations.
        tail_builder.adapters = self.result.boxy_adapters.items;
        const tail_sites = try tail_builder.finish(&self.result.store);
        self.result.store.getProcSpecPtr(proc_id).tail_calls = tail_sites;
    }

    /// A worker returns a runtime descriptor only through the descriptor
    /// local its return local was reserved with, so a caller can read from
    /// the reserved header whether an unfinished callee might.
    fn requireReturnDescriptorAbi(self: *const ProcedureBuilder, ret_local: LIR.LocalId, return_desc: ReturnDescriptorInfo) void {
        if (return_desc.runtime_local == null) return;
        const desc = self.result.store.getLocal(ret_local).boxy_desc orelse
            boxyLowerInvariant("boxy worker returned a runtime descriptor from a return local reserved without one");
        if (desc.localOrNull() == null) {
            boxyLowerInvariant("boxy worker returned a runtime descriptor from a return local reserved with a static one");
        }
    }

    /// Whether a direct call to `worker` must use the provisional descriptor
    /// ABI: the callee's body is not built yet and its return local can carry
    /// a runtime descriptor.
    fn directCallNeedsProvisionalAbi(self: *ProcedureBuilder, worker: Plan.WorkerPlanId, callee_proc: LIR.LirProcSpecId) Allocator.Error!bool {
        if (self.result.store.getProcSpec(callee_proc).body != null) return false;
        try self.ensureWorkerHeader(worker);
        const ret_local = self.worker_return_locals[@backingInt(worker)] orelse
            boxyLowerInvariant("boxy direct call reached a worker without a reserved return local");
        const desc = self.result.store.getLocal(ret_local).boxy_desc orelse return false;
        return desc.localOrNull() != null;
    }

    fn buildErasedWorkerBody(self: *ProcedureBuilder, job: *WorkerJob) Allocator.Error!void {
        const resolved = self.resolved_workers.items[@backingInt(job.worker)];
        const header = &(job.header orelse boxyLowerInvariant("boxy erased worker body was built before its header"));
        const proc = &header.proc;
        const proc_id = job.proc_id;
        const ret_local = header.ret_local;
        const args_span = header.args_span;
        const erased = header.erased.?;
        const ret_layout = self.result.store.getProcSpec(proc_id).ret_layout;
        const saved_tail_builder = self.result.store.tail_call_builder;
        self.result.store.tail_call_builder = null;
        defer self.result.store.tail_call_builder = saved_tail_builder;

        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } }, proc.origin);
        var body_stmt = try self.lowerWorkerBodyInto(resolved, proc, header.body_source, ret_local, ret_stmt);
        body_stmt = try proc.prependWorkerReturnDescriptorInitializers(body_stmt);
        body_stmt = try proc.prependStoredCaptureInitializers(body_stmt);
        body_stmt = try proc.prependStaticDescriptorMaterializationsForSlots(body_stmt);
        body_stmt = try proc.prependWorkerArgumentDescriptorInitializers(body_stmt);
        body_stmt = try proc.prependErasedCaptureBindings(body_stmt);
        const proc_spec = self.result.store.getProcSpecPtr(proc_id);
        proc_spec.body = body_stmt;
        proc_spec.shapes = proc_spec.shapes.merged(self.result.store.shapes);
        proc_spec.erased_arg_desc_offsets = try proc.erasedArgumentDescriptorCaptureOffsets();
        proc_spec.erased_arg_layouts = try proc.appendErasedArgumentLayouts(
            proc.arg_locals.items[0..erased.worker_function.arg_count],
        );
        proc_spec.erased_arg_desc_params = erased.erased_arg_desc_params;
        proc_spec.erased_capture_arg = proc.erased_capture_arg;
        const return_desc = try self.returnDescriptorInfoForBody(
            body_stmt,
            args_span,
            self.result.store.getLocal(ret_local).boxy_desc,
            &proc.frame_locals,
        );
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        proc_spec.frame_locals = frame_span;
        proc_spec.ret_desc = return_desc.external;
        proc_spec.runtime_ret_desc = return_desc.runtime_local;
        proc_spec.stack_probe = self.stackProbeForProc(args_span, frame_span, ret_layout);
    }

    /// The dictionary a literal conversion's evidence names, reserving it and
    /// queueing its procedures at the first reference.
    fn emitLiteralAccessor(self: *ProcedureBuilder, index: u32) Allocator.Error!LIR.BoxyDictId {
        if (self.literal_dicts.items[index]) |id| return id;
        const evidence = &self.plan.literal_evidence.?;
        const initializer = evidence.initializers.items[index];
        const site = self.plan.literal_sites.items[initializer.site];
        const module = procedureModuleById(self.modules, site.source.module);
        const dict: LIR.BoxyDictId = @fromBackingInt(@intCast(self.result.boxy_dicts.items.len));
        const method: u32 = @intCast(self.result.boxy_method_slots.items.len);
        try self.result.boxy_method_slots.append(self.allocator, .{
            .method = module.static_dispatch_plans.plans[@backingInt(site.dispatch)].method,
            .proc = undefined,
        });
        try self.result.boxy_dicts.append(self.allocator, .{ .method_slots = .{ .start = method, .len = 1 } });
        self.literal_dicts.items[index] = dict;
        try self.appendProcJob(.{ .literal = .{ .index = index, .method_slot = method } });
        return dict;
    }

    /// Build a literal conversion's accessor, the getter its dictionary
    /// exposes, and its initializer.
    fn buildLiteralAccessor(self: *ProcedureBuilder, index: u32, method_slot: u32) Allocator.Error!void {
        const evidence = &self.plan.literal_evidence.?;
        const initializer = evidence.initializers.items[index];
        const site = self.plan.literal_sites.items[initializer.site];
        const module = procedureModuleById(self.modules, site.source.module);
        const expr = module.checked_bodies.expr(site.source.expr);
        const origin = LIR.StmtOrigin{ .loc = try self.sourceLoc(module, expr.source_region), .region = expr.source_region, .inline_scope = .none, .kind = .scaffold };
        const ret_layout = self.layout_plan.rep_layouts[@backingInt(initializer.rep)].worker.layoutIdx();
        const constant_plan = try self.literal_const_plans.?.constPlanForRep(initializer.rep);
        const producer: LIR.ComptimeProducer = .{ .literal = @fromBackingInt(@intCast(index)) };
        const failure_layout = try self.result.layouts.putStructFields(&.{ .{ .index = 0, .layout = .u8 }, .{ .index = 1, .layout = .str } });
        const failure_struct = self.result.layouts.getLayout(failure_layout).getStruct().idx;
        const failure_slot: LIR.StaticDataId = @fromBackingInt(@intCast(self.result.static_data_values.items.len));
        try self.result.static_data_values.append(self.allocator, .{
            .initializer = null,
            .layout_idx = failure_layout,
            .compile_time_root = .{ .module = site.source.module, .root = producer, .const_locator = null, .role = .{ .failure_message = .{
                .failed_field = 0,
                .message_field = 1,
                .failed_offset = self.result.layouts.getStructFieldOffsetByOriginalIndex(failure_struct, 0),
                .message_offset = self.result.layouts.getStructFieldOffsetByOriginalIndex(failure_struct, 1),
            } } },
        });
        const value_slot: LIR.StaticDataId = @fromBackingInt(@intCast(self.result.static_data_values.items.len));
        try self.result.static_data_values.append(self.allocator, .{
            .initializer = null,
            .layout_idx = ret_layout,
            .compile_time_root = .{ .module = site.source.module, .root = producer, .const_locator = null, .role = .{ .value = .{ .failure_slot = failure_slot, .plan = constant_plan } } },
        });
        var accessor = ProcBodyBuilder.initSyntheticAdapter(self, module, self.layout_plan.workerLayoutFor(site.worker), origin);
        defer accessor.deinit();
        const value = try accessor.addFrameLocalForRep(initializer.rep);
        const ret = try self.result.store.addCFStmt(.{ .ret = .{ .value = value } }, origin);
        const read = try self.result.store.addCFStmt(.{ .assign_literal = .{ .target = value, .value = .{ .static_data = value_slot }, .next = ret } }, origin);
        const symbol = self.symbols.fresh();
        const accessor_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(symbol)),
            .args = .empty(),
            .frame_locals = try self.result.store.addLocalSpan(accessor.frame_locals.items),
            .body = read,
            .ret_layout = ret_layout,
            .ret_desc = try self.staticDescRefForRepIfNeeded(initializer.rep),
        }, origin.loc);
        self.result.static_data_values.items[@backingInt(value_slot)].accessor = accessor_id;
        // The dictionary entry returns the checked site's worker representation.
        // Its conversion is ordinary LIR, so every execution engine sees the
        // same explicit boundary and ARC owns its allocation lifetime.
        var getter = ProcBodyBuilder.initSyntheticAdapter(self, module, self.layout_plan.workerLayoutFor(site.worker), origin);
        defer getter.deinit();
        var getter_descriptors = std.ArrayList(ProcBodyBuilder.DescriptorArgLocal).empty;
        defer getter_descriptors.deinit(self.allocator);
        for (evidence.bindings.items[initializer.bindings.start..][0..initializer.bindings.len]) |binding| {
            const descriptor = self.plan.representations.items[@backingInt(binding.scheme_rep)].descriptor orelse continue;
            try getter.ensureDescriptorLocals();
            const local = try getter.addFrameLocal(.opaque_ptr);
            try getter.bindDescriptorRequirementLocalForRep(descriptor, binding.scheme_rep, local, true);
            try getter.bindDescriptorIdentityLocalForRep(binding.scheme_rep, local, true);
            try getter_descriptors.append(self.allocator, .{ .local = local, .materialize = try self.staticDescRefForRep(binding.site_rep) });
        }
        const site_rep = getter.repForType(Plan.literalSiteValueType(module.checked_bodies, site.source.expr));
        const frozen_value = try getter.addFrameLocalForRep(initializer.rep);
        const returned_value = try getter.addFrameLocalForRep(site_rep);
        const getter_ret = try self.result.store.addCFStmt(.{ .ret = .{ .value = returned_value } }, origin);
        const getter_adapt = try getter.assignRepresentationBoundary(returned_value, frozen_value, site_rep, initializer.rep, getter_ret);
        var getter_body = try self.result.store.addCFStmt(.{ .assign_call = .{ .target = frozen_value, .proc = accessor_id, .args = .empty(), .next = getter_adapt } }, origin);
        getter_body = try getter.prependStaticDescriptorMaterializationsForSlots(getter_body);
        getter_body = try getter.prependDescriptorArgMaterializations(getter_descriptors.items, getter_body);
        const getter_return = try self.returnDescriptorInfoForBody(getter_body, .empty(), self.result.store.getLocal(returned_value).boxy_desc, &getter.frame_locals);
        const getter_symbol = self.symbols.fresh();
        const getter_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(getter_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(getter_symbol)),
            .args = .empty(),
            .frame_locals = try self.result.store.addLocalSpan(getter.frame_locals.items),
            .body = getter_body,
            .ret_layout = self.result.store.getLocal(returned_value).layout_idx,
            .ret_desc = getter_return.external,
            .runtime_ret_desc = getter_return.runtime_local,
            .boxy_runtime_entry = true,
        }, origin.loc);
        self.result.boxy_method_slots.items[method_slot].proc = getter_id;

        var proc = ProcBodyBuilder.initSyntheticAdapter(self, module, self.layout_plan.workerLayoutFor(site.worker), origin);
        defer proc.deinit();
        proc.literal_initializer = index;
        var descriptor_initializers = std.ArrayList(ProcBodyBuilder.DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.allocator);
        for (evidence.bindings.items[initializer.bindings.start..][0..initializer.bindings.len]) |binding| {
            const rep = self.plan.representations.items[@backingInt(binding.scheme_rep)];
            const desc = rep.descriptor orelse continue;
            try proc.ensureDescriptorLocals();
            const local = try proc.addFrameLocal(.opaque_ptr);
            try proc.bindDescriptorRequirementLocalForRep(desc, binding.scheme_rep, local, true);
            try proc.bindDescriptorIdentityLocalForRep(binding.scheme_rep, local, true);
            try descriptor_initializers.append(self.allocator, .{ .local = local, .materialize = try self.staticDescRefForRep(binding.site_rep) });
        }
        var dictionary_initializer: ?ProcBodyBuilder.DictionaryArgLocal = null;
        if (!initializer.builtin_numeral) if (self.plan.dictionaryDispatchPlanForCall(site.source, site.worker)) |dispatch| {
            const match = if (dispatch.scheme_requirement) |requirement|
                ProcBodyBuilder.DictionaryMethodMatch{ .requirement = requirement, .slot = self.plan.dictionaries.items[@backingInt(requirement)].slot }
            else
                proc.dictionaryMethodForRep(dispatch.dispatcher_rep, dispatch.method).?;
            const dictionaries = Plan.Span{ .start = @backingInt(match.requirement), .len = 1 };
            try proc.ensureDictionaryLocals();
            const local = try proc.addFrameLocal(.opaque_ptr);
            proc.dictionary_locals[dictionaries.start] = local;
            proc.dictionary_slots[dictionaries.start] = local;
            proc.dictionary_bound[dictionaries.start] = true;
            dictionary_initializer = .{ .local = local, .materialize = try self.staticDictRefForRepWithEvidence(initializer.rep, dictionaries, initializer.method_evidence, 0) };
        };
        const result_value = try proc.addFrameLocalForRep(initializer.rep);
        const generic_rep = proc.repForType(Plan.literalSiteValueType(module.checked_bodies, site.source.expr));
        const generic_value = try proc.addFrameLocalForRepWithFreshDescriptor(generic_rep);
        const done = try self.result.store.addCFStmt(.{ .ret = .{ .value = result_value } }, origin);
        const adapted = try proc.assignRepresentationBoundary(result_value, generic_value, initializer.rep, generic_rep, done);
        var body = switch (expr.data) {
            .str_from_quote => |quote| try proc.lowerRuntimeStringConversionInto(generic_value, site.source.expr, expr.ty, quote.plan, "invalid string literal", adapted),
            .interpolation => |interpolation| try proc.lowerRuntimeStringConversionInto(generic_value, site.source.expr, interpolation.assembler_ty, interpolation.plan, "invalid string interpolation", adapted),
            .numeral => |numeral| if (initializer.builtin_numeral)
                try proc.lowerNumFromNumeralInto(result_value, numeral.plan, done)
            else
                try proc.lowerPendingNumeralConversionInto(generic_value, site.source.expr, expr.ty, numeral.plan, adapted),
            .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level, .closure, .lambda => boxyLowerInvariant("literal initializer did not name a checked conversion"),
        };
        if (dictionary_initializer) |dictionary| body = try proc.prependHiddenDictionaryArgMaterialization(&.{dictionary}, body);
        body = try proc.prependStaticDescriptorMaterializationsForSlots(body);
        body = try proc.prependDescriptorArgMaterializations(descriptor_initializers.items, body);
        const initializer_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(initializer_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(initializer_symbol)),
            .args = .empty(),
            .frame_locals = try self.result.store.addLocalSpan(proc.frame_locals.items),
            .body = body,
            .ret_layout = ret_layout,
            .ret_desc = try self.staticDescRefForRepIfNeeded(initializer.rep),
        }, origin.loc);
        const owner = self.result.loweringModuleId(module.key) orelse blk: {
            const id: LIR.LoweringModuleId = @fromBackingInt(@intCast(self.result.lowering_modules.items.len));
            try self.result.lowering_modules.append(self.allocator, module.key);
            break :blk id;
        };
        self.result.literal_roots.items[index] = .{
            .module = module.key,
            .id = @fromBackingInt(index),
            .site = .{ .owner = owner, .checked_expr = @backingInt(site.source.expr), .kind = switch (expr.data) {
                .numeral => .numeral,
                .str_from_quote => .quote,
                .interpolation => .interpolation,
                .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyLowerInvariant("literal root did not name a checked literal conversion"),
            } },
            .proc = proc_id,
            .ret_layout = ret_layout,
            .plan = constant_plan,
            .value_slot = value_slot,
        };
    }

    fn needsFrozenCallableRecipes(self: *const ProcedureBuilder) bool {
        return self.literal_const_plans != null and self.plan.literal_evidence.?.freeze_contexts.items.len != 0;
    }

    fn recordFrozenCallable(self: *ProcedureBuilder, worker: Plan.WorkerPlanId, literal_initializer: ?u32, source_rep: Plan.TypeRepId, target_rep: Plan.TypeRepId, entry: LIR.LirProcSpecId, capture_layout: layout.Idx, on_drop: LIR.ErasedCallableOnDrop, result_rep: Plan.TypeRepId, fields: []const FrozenCaptureRecipe) Allocator.Error!void {
        if (!self.needsFrozenCallableRecipes()) return;
        var hash = base.Sha256.init(.{});
        const identities = [_]u32{ @backingInt(worker), @backingInt(source_rep), @backingInt(target_rep), if (literal_initializer) |index| index + 1 else 0 };
        hash.update(std.mem.asBytes(&identities));
        for (fields) |field| {
            const identity = [_]u32{ @backingInt(std.meta.activeTag(field)), switch (field) {
                .value => |rep| @backingInt(rep),
                .descriptor => |descriptor| @backingInt(descriptor.worker_rep),
                .dictionary => |span| span.start,
                .literal => |index| index,
            }, switch (field) {
                .descriptor => |descriptor| @backingInt(descriptor.source_rep),
                .value, .dictionary, .literal => 0,
            }, switch (field) {
                .descriptor => |descriptor| if (descriptor.exact) |id| @backingInt(id) + 1 else 0,
                .value, .dictionary, .literal => 0,
            } };
            hash.update(std.mem.asBytes(&identity));
        }
        var key: [32]u8 = undefined;
        hash.final(&key);
        for (self.frozen_callable_recipes.items) |existing| {
            if (std.mem.eql(u8, &existing.key, &key)) return;
        }
        try self.frozen_callable_recipes.append(self.allocator, .{ .worker = worker, .source_rep = source_rep, .entry = entry, .key = key, .capture_layout = capture_layout, .on_drop = on_drop, .result_rep = result_rep, .rep = target_rep, .fields = try self.allocator.dupe(FrozenCaptureRecipe, fields), .literal_initializer = literal_initializer });
    }

    fn emitHostedExternalProc(
        self: *ProcedureBuilder,
        worker_id: Plan.WorkerPlanId,
        resolved: ResolvedWorker,
    ) Allocator.Error!LIR.LirProcSpecId {
        const index = @backingInt(worker_id);
        if (index >= self.hosted_external_procs.len) boxyLowerInvariant("boxy hosted worker referenced a missing external proc slot");
        if (self.hosted_external_procs[index]) |existing| return existing;

        if (resolved.body != .hosted) {
            boxyLowerInvariant("non-hosted worker tried to emit a hosted external proc");
        }

        const worker_layout = self.layout_plan.workerLayoutFor(worker_id);
        if (worker_layout.hidden_dicts.len != 0) {
            boxyLowerInvariant("hosted procedure worker tried to expose hidden dictionary arguments through worker ABI");
        }

        const template_ref = resolved.template_ref orelse
            boxyLowerInvariant("hosted worker had no checked procedure template identity");
        const template = resolved.template orelse
            boxyLowerInvariant("hosted worker had no checked procedure template");
        const host_fn_rep = self.plan.workers.items[index].host_fn_rep orelse
            boxyLowerInvariant("hosted worker had no host ABI signature");
        const host_function = (Plan.RepQuery{ .plan = self.plan, .allocator = self.allocator }).functionChildren(host_fn_rep) orelse
            boxyLowerInvariant("hosted ABI signature is not a function");
        const worker_function = checkedFunctionPayload(resolved.module, template.checked_fn_root);
        if (host_function.arg_count != worker_function.args.len) {
            boxyLowerInvariant("hosted host signature arity disagreed with worker signature");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(host_function.rep)].children);
        const arg_locals = try self.allocator.alloc(LIR.LocalId, host_function.arg_count);
        defer self.allocator.free(arg_locals);
        for (children[host_function.args_start..][0..host_function.arg_count], arg_locals) |child, *local| {
            const runtime = self.layout_plan.rep_layouts[@backingInt(child.rep)].worker;
            // The host never sees a descriptor, and a type variable slot has no
            // static one: its caller describes it on the Roc side of the call.
            const desc = if (self.plan.representations.items[@backingInt(child.rep)].contains_dynamic)
                null
            else
                try self.staticDescRefForRepIfNeeded(child.rep);
            local.* = try self.addLocalWithBoxyDesc(runtime.layoutIdx(), desc);
        }
        const ret_layout = self.layout_plan.rep_layouts[@backingInt(host_function.ret)].worker.layoutIdx();

        const args_span = try self.result.store.addLocalSpan(arg_locals);
        const proc_symbol = self.symbols.fresh();
        const proc_id = try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = args_span,
            .body = null,
            .ret_layout = ret_layout,
            .hosted = try self.lirHostedProcForTemplate(template_ref),
            .stack_probe = self.stackProbeForProc(args_span, LIR.LocalSpan.empty(), ret_layout),
        }, .none);
        self.hosted_external_procs[index] = proc_id;
        try self.setProcDebugName(proc_id, resolved);
        return proc_id;
    }

    fn setProcDebugName(
        self: *ProcedureBuilder,
        proc_id: LIR.LirProcSpecId,
        resolved: ResolvedWorker,
    ) Allocator.Error!void {
        if (!self.options.proc_debug_names) return;
        const template = resolved.template orelse return;
        const proc_base = resolved.module.canonical_names.procBase(template.proc_base);
        const export_name = proc_base.export_name orelse return;
        try self.result.store.setProcDebugName(proc_id, resolved.module.canonical_names.exportNameText(export_name));
    }

    const WorkerBodySource = union(enum) {
        checked_expr: checked.CheckedExprId,
        hosted,
        unimplemented,
        const_crash: checked.ConstNodeId,
        generated_codec: Plan.GeneratedCodecSource,
        generated_field_iterator: Plan.GeneratedFieldIteratorSource,
        generated_evidence_intrinsic: checked.IntrinsicId,
        str_inspect: struct {
            arg: LIR.LocalId,
            arg_ty: checked.CheckedTypeId,
        },
    };

    fn bodySourceForWorker(
        self: *ProcedureBuilder,
        resolved: ResolvedWorker,
        proc: *ProcBodyBuilder,
    ) Allocator.Error!WorkerBodySource {
        try proc.bindStoredFnCaptures(resolved.stored_fn);
        return switch (resolved.body) {
            .checked_expr => |body| blk: {
                const root_expr = resolved.module.checked_bodies.expr(body.root_expr);
                if (root_expr.data != .lambda) break :blk .{ .checked_expr = body.root_expr };
                const lambda = root_expr.data.lambda;
                const worker_args = self.layout_plan.workerLayoutSlice(proc.worker_layout.args);
                if (lambda.args.len != worker_args.len) {
                    boxyLowerInvariant("boxy worker lambda arity disagreed with worker root layout");
                }
                proc.current_lambda = body.root_expr;
                try proc.bindLambdaArgs(lambda.args);
                break :blk .{ .checked_expr = lambda.body };
            },
            .intrinsic => |intrinsic| try self.bodySourceForIntrinsic(resolved, proc, intrinsic),
            .hosted => try self.bodySourceForHosted(proc),
            .unimplemented => try self.bodySourceForUnimplemented(proc),
            .const_crash => |node| blk: {
                _ = try self.bodySourceForUnimplemented(proc);
                break :blk .{ .const_crash = node };
            },
            .generated_codec => |source| try self.bodySourceForGeneratedCodec(proc, source),
            .generated_field_iterator => |source| try self.bodySourceForGeneratedFieldIterator(proc, source),
        };
    }

    fn bodySourceForGeneratedFieldIterator(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedFieldIteratorSource,
    ) Allocator.Error!WorkerBodySource {
        const worker = proc.parent.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated FieldNames iterator worker was not callable");
        if (function.arg_count != 0 or proc.worker_layout.args.len != 0) {
            boxyLowerInvariant("generated FieldNames iterator step worker was not zero-argument");
        }
        return .{ .generated_field_iterator = source };
    }

    fn bodySourceForGeneratedCodec(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
    ) Allocator.Error!WorkerBodySource {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated codec worker did not have a function representation");
        const worker_args = self.layout_plan.workerLayoutSlice(proc.worker_layout.args);
        if (function.arg_count != worker_args.len) {
            boxyLowerInvariant("generated codec worker arity disagreed with worker layout");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        for (worker_args, children[function.args_start..][0..function.arg_count]) |arg_layout, child| {
            const local = try proc.addArgLocalForRep(child.rep);
            if (self.result.store.getLocal(local).layout_idx != arg_layout.layoutIdx()) {
                boxyLowerInvariant("generated codec argument layout disagreed with its representation");
            }
        }
        return .{ .generated_codec = source };
    }

    /// Bind the declared parameters of a procedure whose declaration has no
    /// implementation. The body crashes, but the procedure still has to
    /// present the declared ABI so direct calls keep passing their arguments
    /// to a matching signature.
    fn bodySourceForUnimplemented(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
    ) Allocator.Error!WorkerBodySource {
        const worker_args = proc.parent.layout_plan.workerLayoutSlice(proc.worker_layout.args);
        for (worker_args) |arg_layout| {
            _ = try proc.addArgLocal(arg_layout.layoutIdx());
        }
        return .unimplemented;
    }

    /// Bind a hosted worker's arguments at the worker's own representation.
    /// `lowerHostedWorkerBodyInto` adapts them and the result across the
    /// extern boundary, whose host ABI signature can differ from the worker's.
    fn bodySourceForHosted(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
    ) Allocator.Error!WorkerBodySource {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("hosted procedure worker did not have a function representation");
        const worker_args = self.layout_plan.workerLayoutSlice(proc.worker_layout.args);
        if (function.arg_count != worker_args.len) {
            boxyLowerInvariant("hosted procedure worker arity disagreed with worker root layout");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        for (worker_args, children[function.args_start..][0..function.arg_count]) |arg_layout, child| {
            const local = try proc.addArgLocalForRep(child.rep);
            if (self.result.store.getLocal(local).layout_idx != arg_layout.layoutIdx()) {
                boxyLowerInvariant("hosted procedure argument layout disagreed with its representation");
            }
        }
        return .hosted;
    }

    fn bodySourceForIntrinsic(
        self: *ProcedureBuilder,
        resolved: ResolvedWorker,
        proc: *ProcBodyBuilder,
        intrinsic: checked.IntrinsicId,
    ) Allocator.Error!WorkerBodySource {
        const template = resolved.template orelse
            boxyLowerInvariant("intrinsic worker had no checked procedure template");
        const function = checkedFunctionPayload(resolved.module, template.checked_fn_root);
        return switch (intrinsic) {
            .str_inspect => {
                if (function.args.len != 1) {
                    boxyLowerInvariant("Str.inspect intrinsic wrapper had an unexpected arity");
                }
                const worker_args = self.layout_plan.workerLayoutSlice(proc.worker_layout.args);
                if (worker_args.len != 1) {
                    boxyLowerInvariant("Str.inspect intrinsic worker layout had an unexpected arity");
                }
                if (proc.workerRuntimeLayoutForType(function.args[0]).layoutIdx() != worker_args[0].layoutIdx()) {
                    boxyLowerInvariant("Str.inspect intrinsic argument layout disagreed with checked type");
                }
                if (proc.workerRuntimeLayoutForType(function.ret).layoutIdx() != proc.workerReturnLayout()) {
                    boxyLowerInvariant("Str.inspect intrinsic return layout disagreed with checked type");
                }
                const arg = try proc.addArgLocal(worker_args[0].layoutIdx());
                return .{ .str_inspect = .{
                    .arg = arg,
                    .arg_ty = function.args[0],
                } };
            },
            .structural_eq => boxyLowerInvariant("structural equality intrinsic wrapper must lower through checked dispatch plans"),
            .parse_tag_union,
            .field_names_rename_fields,
            .field_names_shortest_name,
            .field_names_longest_name,
            .field_names_iter,
            .field_names_for_size,
            .field_name,
            => {
                const worker_args = self.layout_plan.workerLayoutSlice(proc.worker_layout.args);
                if (function.args.len != worker_args.len) {
                    boxyLowerInvariant("serialization intrinsic worker arity disagreed with its checked function");
                }
                for (function.args, worker_args) |arg_ty, arg_layout| {
                    const arg_rep = proc.repForType(arg_ty);
                    const local = try proc.addArgLocalForRep(arg_rep);
                    if (self.result.store.getLocal(local).layout_idx != arg_layout.layoutIdx()) {
                        boxyLowerInvariant("serialization intrinsic argument layout disagreed with its checked type");
                    }
                }
                return .{ .generated_evidence_intrinsic = intrinsic };
            },
        };
    }

    fn lowerWorkerBodyInto(
        self: *ProcedureBuilder,
        resolved: ResolvedWorker,
        proc: *ProcBodyBuilder,
        body_source: WorkerBodySource,
        ret_local: LIR.LocalId,
        ret_stmt: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (body_source) {
            .checked_expr => |body_expr| blk: {
                const worker_plan = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
                const worker_function = proc.functionChildrenForRep(worker_plan.rep) orelse
                    boxyLowerInvariant("boxy checked worker body did not have a function representation");
                const body = try proc.lowerExprIntoRep(ret_local, worker_function.ret, body_expr, ret_stmt);
                break :blk try proc.prependLambdaArgPatternBindings(body);
            },
            .hosted => try self.lowerHostedWorkerBodyInto(resolved, proc, ret_local, ret_stmt),
            .unimplemented => try self.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.result.store.insertString(Common.unimplemented_declaration_crash) },
            } }, proc.origin),
            .const_crash => |node| switch (resolved.module.const_store.get(node)) {
                .crash => |str| try self.result.store.addCFStmt(.{ .crash = .{
                    .msg = .{ .literal = try self.result.store.insertString(resolved.module.const_store.strBytes(str)) },
                } }, proc.origin),
                .checked_error => |str| try self.result.store.addCFStmt(.{ .crash = .{
                    .msg = .{ .literal = try self.result.store.insertString(resolved.module.const_store.strBytes(str)) },
                    .checked_error = true,
                } }, proc.origin),
                .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .tag, .nominal, .fn_value => boxyLowerInvariant("boxy constant crash worker's constant was not a crash"),
            },
            .generated_codec => |source| try self.lowerGeneratedCodecWorkerInto(proc, source, ret_local, ret_stmt),
            .generated_field_iterator => |source| try self.lowerGeneratedFieldIteratorStepInto(proc, source, ret_local, ret_stmt),
            .generated_evidence_intrinsic => |intrinsic| try self.lowerGeneratedEvidenceIntrinsicInto(proc, intrinsic, ret_local, ret_stmt),
            .str_inspect => |inspect| blk: {
                try proc.markLocalDescriptorForType(inspect.arg, inspect.arg_ty);
                break :blk try proc.lowerInspectLocalInto(ret_local, inspect.arg, inspect.arg_ty, ret_stmt);
            },
        };
    }

    fn lowerGeneratedEvidenceIntrinsicInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        intrinsic: checked.IntrinsicId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (intrinsic) {
            .field_name => try proc.lowerGeneratedFieldNameNameInto(target, next),
            .field_names_shortest_name => try proc.lowerGeneratedFieldNamesBoundInto(target, 1, next),
            .field_names_longest_name => try proc.lowerGeneratedFieldNamesBoundInto(target, 2, next),
            .field_names_iter => try self.lowerGeneratedFieldIteratorIntrinsicInto(proc, .all, target, next),
            .field_names_for_size => try self.lowerGeneratedFieldIteratorIntrinsicInto(proc, .for_size, target, next),
            .field_names_rename_fields => try self.lowerGeneratedFieldNamesRenameFieldsInto(proc, target, next),
            .parse_tag_union => try self.lowerGeneratedParseTagUnionIntrinsicInto(proc, target, next),
            .str_inspect, .structural_eq => boxyLowerInvariant("non-evidence intrinsic reached generated evidence lowering"),
        };
    }

    fn lowerGeneratedParseTagUnionIntrinsicInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("ParseTagUnionSpec.parse intrinsic was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2) {
            boxyLowerInvariant("ParseTagUnionSpec.parse intrinsic had an unexpected argument count");
        }
        const function_children = self.plan.childSlice(
            self.plan.representations.items[@backingInt(function.rep)].children,
        );
        const args = function_children[function.args_start..][0..function.arg_count];
        if (proc.workerRuntimeLayoutForRep(args[0].rep).layoutIdx() != self.layout_plan.generated_evidence.tag_union_spec) {
            boxyLowerInvariant("ParseTagUnionSpec.parse intrinsic had an unexpected spec layout");
        }

        const options = proc.arg_locals.items[1];
        const tag_child = proc.generatedRecordFieldChild(args[1].rep, "tag");
        const encoding_child = proc.generatedRecordFieldChild(args[1].rep, "encoding");
        const state_child = proc.generatedRecordFieldChild(args[1].rep, "state");
        const missing_child = proc.generatedRecordFieldChild(args[1].rep, "missing");
        const start_child = proc.generatedRecordFieldChild(args[1].rep, "start_payloads");
        const next_child = proc.generatedRecordFieldChild(args[1].rep, "next_payload");
        const finish_child = proc.generatedRecordFieldChild(args[1].rep, "finish_payloads");
        const callbacks = GeneratedTagPayloadCallbacks{
            .start = try proc.addFrameLocalForRep(start_child.rep),
            .start_rep = start_child.rep,
            .next = try proc.addFrameLocalForRep(next_child.rep),
            .next_rep = next_child.rep,
            .finish = try proc.addFrameLocalForRep(finish_child.rep),
            .finish_rep = finish_child.rep,
        };
        const tag = try proc.addFrameLocalForRep(tag_child.rep);
        const encoding = try proc.addFrameLocalForRep(encoding_child.rep);
        const state = try proc.addFrameLocalForRep(state_child.rep);
        const missing = try proc.addFrameLocalForRep(missing_child.rep);
        const runtime_id = try proc.addFrameLocal(.u64);

        var branch_count: usize = 0;
        for (self.plan.generated_parser_tag_union_plans.items) |plan| {
            if (plan.intrinsic_worker == proc.worker_layout.worker) branch_count += 1;
        }
        if (branch_count == 0) {
            boxyLowerInvariant("ParseTagUnionSpec.parse intrinsic had no generated parser plans");
        }
        const branches = try self.allocator.alloc(LIR.CFSwitchBranch, branch_count);
        defer self.allocator.free(branches);
        var branch_index: usize = 0;
        for (self.plan.generated_parser_tag_union_plans.items) |plan| {
            if (plan.intrinsic_worker != proc.worker_layout.worker) continue;
            branches[branch_index] = .{
                .value = plan.runtime_id,
                .body = try self.lowerGeneratedParseTagUnionPlan(
                    proc,
                    plan,
                    args[0].rep,
                    tag,
                    encoding,
                    encoding_child,
                    state,
                    state_child,
                    missing,
                    missing_child,
                    callbacks,
                    target,
                    function.ret,
                    next,
                ),
            };
            branch_index += 1;
        }
        const invalid_plan = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        var continuation = try self.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = runtime_id,
            .branches = try self.result.store.addCFSwitchBranches(branches),
            .default_branch = invalid_plan,
            .continuation = null,
        } }, proc.derivedOrigin());
        continuation = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = runtime_id,
            .op = .{ .field = .{ .source = proc.arg_locals.items[0], .field_idx = 1 } },
            .next = continuation,
        } }, proc.derivedOrigin());
        continuation = try proc.generatedParserReadRecordField(
            missing,
            missing_child.rep,
            options,
            args[1],
            "missing",
            continuation,
        );
        continuation = try proc.generatedParserReadRecordField(callbacks.finish, finish_child.rep, options, args[1], "finish_payloads", continuation);
        continuation = try proc.generatedParserReadRecordField(callbacks.next, next_child.rep, options, args[1], "next_payload", continuation);
        continuation = try proc.generatedParserReadRecordField(callbacks.start, start_child.rep, options, args[1], "start_payloads", continuation);
        continuation = try proc.generatedParserReadRecordField(
            state,
            state_child.rep,
            options,
            args[1],
            "state",
            continuation,
        );
        continuation = try proc.generatedParserReadRecordField(
            encoding,
            encoding_child.rep,
            options,
            args[1],
            "encoding",
            continuation,
        );
        return try proc.generatedParserReadRecordField(
            tag,
            tag_child.rep,
            options,
            args[1],
            "tag",
            continuation,
        );
    }

    fn lowerGeneratedParseTagUnionPlan(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        plan: Plan.GeneratedParserTagUnionPlan,
        spec_rep: Plan.TypeRepId,
        tag: LIR.LocalId,
        encoding: LIR.LocalId,
        encoding_child: Plan.RepChild,
        state: LIR.LocalId,
        state_child: Plan.RepChild,
        missing: LIR.LocalId,
        missing_child: Plan.RepChild,
        callbacks: GeneratedTagPayloadCallbacks,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const shape_rep = proc.repForTypeRef(plan.shape_type);
        const variants = try self.generatedParserTagVariants(proc, shape_rep);
        defer self.allocator.free(variants);
        var exact_encoding_child = encoding_child;
        exact_encoding_child.source_type = plan.encoding_type;
        exact_encoding_child.rep = proc.repForTypeRef(plan.encoding_type);
        var exact_state_child = state_child;
        exact_state_child.source_type = plan.state_type;
        exact_state_child.rep = proc.repForTypeRef(plan.state_type);
        const exact_encoding = try proc.addFrameLocalForRep(exact_encoding_child.rep);
        const exact_state = try proc.addFrameLocalForRep(exact_state_child.rep);

        const err = proc.generatedParserTagVariant(target_rep, "Err");
        var dispatch = try proc.assignGeneratedParserTag(
            target,
            target_rep,
            err,
            missing,
            missing_child.rep,
            next,
        );
        var index = variants.len;
        while (index > 0) {
            index -= 1;
            const variant_body = try self.lowerGeneratedParseTagUnionVariant(
                proc,
                plan,
                variants[index],
                spec_rep,
                exact_encoding,
                exact_encoding_child,
                exact_state,
                exact_state_child,
                callbacks,
                target,
                target_rep,
                next,
            );
            const matches = try proc.addFrameLocal(.bool);
            const expected = try proc.addFrameLocal(.str);
            const choose = try proc.boolSwitchNoContinuation(matches, variant_body, dispatch);
            dispatch = try proc.assignBinaryLowLevel(matches, .str_is_eq, tag, expected, choose);
            dispatch = try proc.assignStringBytesLiteral(
                expected,
                proc.tagVariantNameText(variants[index].variant),
                dispatch,
            );
        }
        dispatch = try proc.assignRepresentationBoundary(
            exact_state,
            state,
            exact_state_child.rep,
            state_child.rep,
            dispatch,
        );
        return try proc.assignRepresentationBoundary(
            exact_encoding,
            encoding,
            exact_encoding_child.rep,
            encoding_child.rep,
            dispatch,
        );
    }

    fn generatedParserTagVariants(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_rep: Plan.TypeRepId,
    ) Allocator.Error![]GeneratedParserTagVariant {
        var variants = std.ArrayList(GeneratedParserTagVariant).empty;
        defer variants.deinit(self.allocator);
        const root = proc.tagVariantRepForBoundary(shape_rep) orelse
            boxyLowerInvariant("generated tag-union plan shape had no tag representation");
        var current = root;
        while (true) {
            const rep = self.plan.representations.items[@backingInt(current)];
            for (self.plan.tagVariantSlice(rep.tag_variants), 0..) |variant, index| {
                if (index > std.math.maxInt(u32)) boxyLowerInvariant("generated tag-union variant index exceeded LIR range");
                try variants.append(self.allocator, .{
                    .boundary_rep = shape_rep,
                    .tag_rep = root,
                    .owner_rep = current,
                    .index = @intCast(index),
                    .variant = variant,
                });
            }
            var extension: ?Plan.TypeRepId = null;
            for (self.plan.childSlice(rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                if (extension != null) boxyLowerInvariant("generated tag-union plan row had duplicate extensions");
                extension = proc.tagVariantRepForBoundary(child.rep);
            }
            const next_rep = extension orelse break;
            if (next_rep == current) boxyLowerInvariant("generated tag-union plan row was cyclic");
            current = next_rep;
        }
        return try variants.toOwnedSlice(self.allocator);
    }

    /// The payload-boundary callbacks a format passes to
    /// `ParseTagUnionSpec.parse`; each returns `Try(state, err)`.
    const GeneratedTagPayloadCallbacks = struct {
        start: LIR.LocalId,
        start_rep: Plan.TypeRepId,
        next: LIR.LocalId,
        next_rep: Plan.TypeRepId,
        finish: LIR.LocalId,
        finish_rep: Plan.TypeRepId,
    };

    /// Parse one matched variant: `start_payloads` once, each payload in
    /// order with `next_payload` before every payload after the first, then
    /// `finish_payloads` once. Each callback is told the payload count.
    fn lowerGeneratedParseTagUnionVariant(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        plan: Plan.GeneratedParserTagUnionPlan,
        variant: GeneratedParserTagVariant,
        spec_rep: Plan.TypeRepId,
        encoding: LIR.LocalId,
        encoding_child: Plan.RepChild,
        state: LIR.LocalId,
        state_child: Plan.RepChild,
        callbacks: GeneratedTagPayloadCallbacks,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const shape_rep = proc.repForTypeRef(plan.shape_type);
        const value = try proc.addGeneratedParserOutputLocalForRep(shape_rep);
        const rest = try proc.addGeneratedParserOutputLocalForRep(state_child.rep);
        const context = GeneratedParserShapeContext{
            .worker = plan.contract_worker,
            .encoding_type = encoding_child.source_type,
            .encoding = encoding,
            .state_type = state_child.source_type,
            .state_rep = state_child.rep,
            .result = target,
            .result_rep = target_rep,
            .next = next,
            .tag_union_spec = proc.arg_locals.items[0],
            .tag_union_spec_rep = spec_rep,
            .tag_union_plan = plan,
        };
        const success = try self.lowerGeneratedParserSuccess(proc, context, value, shape_rep, rest);
        const payloads = self.plan.childSlice(variant.variant.payloads);
        const items = try self.allocator.alloc(GeneratedParserTupleItem, payloads.len);
        defer self.allocator.free(items);
        for (payloads, items) |payload, *item| {
            item.* = .{
                .source_type = payload.source_type,
                .rep = payload.rep,
                .value = try proc.addGeneratedParserOutputLocalForRep(payload.rep),
            };
        }
        const construct = try self.lowerGeneratedParserTagConstruction(proc, shape_rep, variant, value, items, success);

        const count = try proc.addFrameLocal(.u64);
        const start = try beginGeneratedParserTryStep(proc, generatedCallbackReturnRep(proc, callbacks.start_rep));
        const finish = try beginGeneratedParserTryStep(proc, generatedCallbackReturnRep(proc, callbacks.finish_rep));
        const separators = try self.allocator.alloc(GeneratedParserTryCall, items.len);
        defer self.allocator.free(separators);
        for (separators[@min(1, items.len)..]) |*separator| {
            separator.* = try beginGeneratedParserTryStep(proc, generatedCallbackReturnRep(proc, callbacks.next_rep));
        }
        const parsed_rests = try self.allocator.alloc(LIR.LocalId, items.len);
        defer self.allocator.free(parsed_rests);
        for (parsed_rests) |*local| local.* = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);

        var continuation = try proc.assignRepresentationBoundary(rest, finish.ok_payload.local, context.state_rep, finish.ok_payload.child.rep, construct);
        continuation = try self.dispatchGeneratedParserTryStep(proc, finish, target, target_rep, next, continuation);
        continuation = if (items.len == 0)
            try self.lowerGeneratedPayloadCallback(proc, finish, callbacks.finish, callbacks.finish_rep, &.{ start.ok_payload.local, count }, &.{ start.ok_payload.child.rep, null }, continuation)
        else
            try self.lowerGeneratedPayloadCallback(proc, finish, callbacks.finish, callbacks.finish_rep, &.{ parsed_rests[items.len - 1], count }, &.{ context.state_rep, null }, continuation);
        var index = items.len;
        while (index > 0) {
            index -= 1;
            const boundary = if (index == 0) start else separators[index];
            const item_state = try proc.addFrameLocalForRep(context.state_rep);
            continuation = try self.lowerGeneratedParseShapeFromState(
                proc,
                context,
                items[index].source_type,
                items[index].rep,
                item_state,
                items[index].value,
                parsed_rests[index],
                continuation,
            );
            continuation = try proc.assignRepresentationBoundary(item_state, boundary.ok_payload.local, context.state_rep, boundary.ok_payload.child.rep, continuation);
            if (index == 0) continue;
            continuation = try self.dispatchGeneratedParserTryStep(proc, boundary, target, target_rep, next, continuation);
            const item_index = try proc.addFrameLocal(.u64);
            continuation = try self.lowerGeneratedPayloadCallback(proc, boundary, callbacks.next, callbacks.next_rep, &.{ parsed_rests[index - 1], item_index, count }, &.{ context.state_rep, null, null }, continuation);
            continuation = try proc.assignIntLiteral(item_index, @intCast(index), continuation);
        }
        continuation = try self.dispatchGeneratedParserTryStep(proc, start, target, target_rep, next, continuation);
        continuation = try self.lowerGeneratedPayloadCallback(proc, start, callbacks.start, callbacks.start_rep, &.{ state, count }, &.{ state_child.rep, null }, continuation);
        return try proc.assignIntLiteral(count, @intCast(items.len), continuation);
    }

    fn generatedCallbackReturnRep(proc: *ProcBodyBuilder, callback_rep: Plan.TypeRepId) Plan.TypeRepId {
        const function = proc.functionChildrenForRep(callback_rep) orelse
            boxyLowerInvariant("generated tag payload callback was not callable");
        return function.ret;
    }

    /// Call one format-supplied payload callback into `step.step`. A null
    /// argument representation means the callback's own declared parameter
    /// representation (the payload count and index are plain `U64`s).
    fn lowerGeneratedPayloadCallback(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        step: GeneratedParserTryCall,
        callback: LIR.LocalId,
        callback_rep: Plan.TypeRepId,
        args: []const LIR.LocalId,
        arg_reps: []const ?Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const function = proc.functionChildrenForRep(callback_rep) orelse
            boxyLowerInvariant("generated tag payload callback was not callable");
        if (function.arg_count != args.len) boxyLowerInvariant("generated tag payload callback had an unexpected arity");
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        const params = children[function.args_start..][0..function.arg_count];
        var reps: [3]Plan.TypeRepId = undefined;
        for (arg_reps, params, 0..) |arg_rep, param, index| reps[index] = arg_rep orelse param.rep;
        return try proc.lowerErasedCallLocalsInto(step.step, step.step_rep, callback_rep, callback, args, reps[0..args.len], next);
    }

    fn lowerGeneratedParserTagConstruction(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_rep: Plan.TypeRepId,
        variant: GeneratedParserTagVariant,
        value: LIR.LocalId,
        items: []const GeneratedParserTupleItem,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        switch (items.len) {
            0 => return try proc.assignGeneratedParserZeroTag(value, shape_rep, variant, success),
            1 => return try proc.assignGeneratedParserTag(value, shape_rep, variant, items[0].value, items[0].rep, success),
            else => {},
        }
        const payload = switch (proc.workerRuntimeLayoutForRep(variant.tag_rep)) {
            .concrete => blk: {
                const payload_layout = if (proc.isZstLocal(value))
                    layout.Idx.zst
                else
                    proc.tagUnionPayloadLayout(self.result.store.getLocal(value).layout_idx, variant.index);
                break :blk ProcBodyBuilder.DynamicTagPayloadLocal{
                    .local = try proc.addFrameLocal(payload_layout),
                    .layout_idx = payload_layout,
                };
            },
            .dynamic_box => try proc.dynamicTagPayloadLocalForChildren(self.plan.childSlice(variant.variant.payloads)),
        };
        const construct = try proc.assignGeneratedParserMultiTag(value, shape_rep, variant, payload, items, success);
        // The payloads are fields of the variant's payload struct, which the
        // tag's descriptor describes; the struct is not a value of its own.
        const fields = try self.allocator.alloc(LIR.LocalId, items.len);
        defer self.allocator.free(fields);
        for (items, fields) |item, *field| field.* = item.value;
        return try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload.local,
            .fields = try self.result.store.addLocalSpan(fields),
            .next = construct,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedFieldNamesRenameFieldsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const intrinsic_worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(intrinsic_worker.rep) orelse
            boxyLowerInvariant("FieldNames.rename_fields intrinsic was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2) {
            boxyLowerInvariant("FieldNames.rename_fields intrinsic had an unexpected argument count");
        }
        const function_children = self.plan.childSlice(
            self.plan.representations.items[@backingInt(function.rep)].children,
        );
        const arg_children = function_children[function.args_start..][0..function.arg_count];
        if (proc.workerRuntimeLayoutForRep(arg_children[0].rep).layoutIdx() != self.layout_plan.generated_evidence.field_names or
            proc.workerRuntimeLayoutForRep(function.ret).layoutIdx() != self.layout_plan.generated_evidence.field_names or
            self.result.store.getLocal(target).layout_idx != self.layout_plan.generated_evidence.field_names)
        {
            boxyLowerInvariant("FieldNames.rename_fields did not use the fixed generated evidence layout");
        }
        if (proc.functionChildrenForRep(arg_children[1].rep) == null) {
            boxyLowerInvariant("FieldNames.rename_fields renamer was not callable");
        }

        const source_items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const len = try proc.addFrameLocal(.u64);
        const zero = try proc.addFrameLocal(.u64);
        const initial_shortest = try proc.addFrameLocal(.u64);
        const initial_items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const index = try proc.addFrameLocal(.u64);
        const items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const shortest = try proc.addFrameLocal(.u64);
        const longest = try proc.addFrameLocal(.u64);
        const join_id = proc.freshJoinPointId();

        const body = try self.lowerGeneratedFieldNamesRenameLoopBody(
            proc,
            target,
            source_items,
            proc.arg_locals.items[1],
            arg_children[1].rep,
            len,
            zero,
            index,
            items,
            shortest,
            longest,
            join_id,
            next,
        );

        var initial_jump = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        initial_jump = try proc.setLocalInitializeJoinParam(longest, zero, initial_jump);
        initial_jump = try proc.setLocalInitializeJoinParam(shortest, initial_shortest, initial_jump);
        initial_jump = try proc.setLocalInitializeJoinParam(items, initial_items, initial_jump);
        initial_jump = try proc.setLocalInitializeJoinParam(index, zero, initial_jump);
        initial_jump = try proc.assignUnaryLowLevel(initial_items, .list_with_capacity, len, initial_jump);
        initial_jump = try proc.assignIntLiteral(initial_shortest, std.math.maxInt(u64), initial_jump);
        initial_jump = try proc.assignIntLiteral(zero, 0, initial_jump);
        initial_jump = try proc.assignUnaryLowLevel(len, .list_len, source_items, initial_jump);
        initial_jump = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = source_items,
            .op = .{ .field = .{ .source = proc.arg_locals.items[0], .field_idx = 0 } },
            .next = initial_jump,
        } }, proc.derivedOrigin());

        return try self.result.store.addCFStmt(.{ .join = .{
            .id = join_id,
            .params = try proc.joinParamSpan(&.{ index, items, shortest, longest }),
            .body = body,
            .remainder = initial_jump,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedFieldNamesRenameLoopBody(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        source_items: LIR.LocalId,
        renamer: LIR.LocalId,
        renamer_rep: Plan.TypeRepId,
        len: LIR.LocalId,
        zero: LIR.LocalId,
        index: LIR.LocalId,
        items: LIR.LocalId,
        shortest: LIR.LocalId,
        longest: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const done = try proc.addFrameLocal(.bool);
        const finish = try self.lowerGeneratedFieldNamesRenameFinish(
            proc,
            target,
            len,
            zero,
            items,
            shortest,
            longest,
            next,
        );
        const step = try self.lowerGeneratedFieldNamesRenameStep(
            proc,
            source_items,
            renamer,
            renamer_rep,
            index,
            items,
            shortest,
            longest,
            join_id,
        );
        const choose = try proc.boolSwitchNoContinuation(done, finish, step);
        return try proc.assignBinaryLowLevel(done, .num_is_eq, index, len, choose);
    }

    fn lowerGeneratedFieldNamesRenameFinish(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        len: LIR.LocalId,
        zero: LIR.LocalId,
        items: LIR.LocalId,
        shortest: LIR.LocalId,
        longest: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const final_shortest = try proc.addFrameLocal(.u64);
        const finish_join = proc.freshJoinPointId();
        const finish_body = try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.result.store.addLocalSpan(&.{ items, final_shortest, longest }),
            .next = next,
        } }, proc.derivedOrigin());
        const jump = try self.result.store.addCFStmt(.{ .jump = .{ .target = finish_join } }, proc.derivedOrigin());
        const empty = try proc.setLocalInitializeJoinParam(final_shortest, zero, jump);
        const nonempty = try proc.setLocalInitializeJoinParam(final_shortest, shortest, jump);
        const is_empty = try proc.addFrameLocal(.bool);
        const choose = try proc.boolSwitchNoContinuation(is_empty, empty, nonempty);
        const compare = try proc.assignBinaryLowLevel(is_empty, .num_is_eq, len, zero, choose);
        return try self.result.store.addCFStmt(.{ .join = .{
            .id = finish_join,
            .params = try proc.joinParamSpan(&.{final_shortest}),
            .body = finish_body,
            .remainder = compare,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedFieldNamesRenameStep(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source_items: LIR.LocalId,
        renamer: LIR.LocalId,
        renamer_rep: Plan.TypeRepId,
        index: LIR.LocalId,
        items: LIR.LocalId,
        shortest: LIR.LocalId,
        longest: LIR.LocalId,
        join_id: LIR.JoinPointId,
    ) Allocator.Error!LIR.CFStmtId {
        const renamer_fn = proc.functionChildrenForRep(renamer_rep) orelse
            boxyLowerInvariant("generated FieldNames renamer was not callable");
        const renamer_rep_data = self.plan.representations.items[@backingInt(renamer_fn.rep)];
        const renamer_children = self.plan.childSlice(renamer_rep_data.children);
        const renamer_args = renamer_children[renamer_fn.args_start..][0..renamer_fn.arg_count];
        if (renamer_args.len != 1) boxyLowerInvariant("generated FieldNames renamer had an unexpected arity");
        const source_field = try proc.addFrameLocal(self.layout_plan.generated_evidence.field);
        const source_name = try proc.addFrameLocal(.str);
        const source_index = try proc.addFrameLocal(.u64);
        const renamed = try proc.addFrameLocal(.str);
        const renamed_len = try proc.addFrameLocal(.u64);
        const renamed_field = try proc.addFrameLocal(self.layout_plan.generated_evidence.field);
        const next_items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const next_shortest = try proc.addFrameLocal(.u64);
        const next_longest = try proc.addFrameLocal(.u64);
        const one = try proc.addFrameLocal(.u64);
        const next_index = try proc.addFrameLocal(.u64);

        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(longest, next_longest, continuation);
        continuation = try proc.setLocalInitializeJoinParam(shortest, next_shortest, continuation);
        continuation = try proc.setLocalInitializeJoinParam(items, next_items, continuation);
        continuation = try proc.setLocalInitializeJoinParam(index, next_index, continuation);
        continuation = try proc.assignListAppendMovingElement(next_items, items, renamed_field, continuation);
        continuation = try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = renamed_field,
            .fields = try self.result.store.addLocalSpan(&.{ renamed, source_index, renamed_len }),
            .next = continuation,
        } }, proc.derivedOrigin());
        continuation = try proc.assignGeneratedParserU64Select(
            next_longest,
            renamed_len,
            longest,
            .num_is_gt,
            continuation,
        );
        continuation = try proc.assignGeneratedParserU64Select(
            next_shortest,
            renamed_len,
            shortest,
            .num_is_lt,
            continuation,
        );
        continuation = try proc.assignUnaryLowLevel(renamed_len, .str_count_utf8_bytes, renamed, continuation);
        continuation = try proc.lowerErasedCallLocalsInto(
            renamed,
            renamer_fn.ret,
            renamer_rep,
            renamer,
            &.{source_name},
            &.{renamer_args[0].rep},
            continuation,
        );
        continuation = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = source_index,
            .op = .{ .field = .{ .source = source_field, .field_idx = 1 } },
            .next = continuation,
        } }, proc.derivedOrigin());
        continuation = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = source_name,
            .op = .{ .field = .{ .source = source_field, .field_idx = 0 } },
            .next = continuation,
        } }, proc.derivedOrigin());
        continuation = try proc.assignBinaryLowLevel(source_field, .list_get_unsafe, source_items, index, continuation);
        continuation = try proc.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, continuation);
        return try proc.assignIntLiteral(one, 1, continuation);
    }

    fn lowerGeneratedFieldIteratorIntrinsicInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        mode: Plan.GeneratedFieldIteratorMode,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const intrinsic_worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(intrinsic_worker.rep) orelse
            boxyLowerInvariant("FieldNames iterator intrinsic was not callable");
        const expected_arity: u32 = switch (mode) {
            .all => 1,
            .for_size => 2,
        };
        if (function.arg_count != expected_arity or proc.arg_locals.items.len < expected_arity) {
            boxyLowerInvariant("FieldNames iterator intrinsic had an unexpected argument count");
        }
        const first_step = self.plan.generatedFieldIteratorFirstStep(proc.worker_layout.worker) orelse
            boxyLowerInvariant("FieldNames iterator intrinsic had no generated first step");
        const worker_source = self.plan.workers.items[@backingInt(first_step)].source;
        if (worker_source != .generated_field_iterator) {
            boxyLowerInvariant("FieldNames iterator link did not reference a generated step worker");
        }
        const source = worker_source.generated_field_iterator;
        if (source.mode != mode) {
            boxyLowerInvariant("FieldNames iterator first step disagreed with its intrinsic");
        }
        const items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const index = try proc.addFrameLocal(.u64);
        const len = try proc.addFrameLocal(.u64);
        var capture_values: [4]LIR.LocalId = undefined;
        capture_values[0] = proc.arg_locals.items[0];
        capture_values[1] = index;
        capture_values[2] = len;
        const capture_count: usize = switch (mode) {
            .all => 3,
            .for_size => blk: {
                capture_values[3] = proc.arg_locals.items[1];
                break :blk 4;
            },
        };
        var continuation = try self.lowerGeneratedFieldIteratorValueInto(
            proc,
            target,
            function.ret,
            first_step,
            capture_values[0..capture_count],
            mode,
            if (mode == .all) len else null,
            next,
        );
        continuation = try proc.assignIntLiteral(index, 0, continuation);
        continuation = try proc.assignUnaryLowLevel(len, .list_len, items, continuation);
        return try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = items,
            .op = .{ .field = .{ .source = proc.arg_locals.items[0], .field_idx = 0 } },
            .next = continuation,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedFieldIteratorValueInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        iter_rep: Plan.TypeRepId,
        step_worker: Plan.WorkerPlanId,
        capture_values: []const LIR.LocalId,
        mode: Plan.GeneratedFieldIteratorMode,
        known_remaining: ?LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const len_child = proc.generatedRecordFieldChild(iter_rep, "len_if_known");
        const step_child = proc.generatedRecordFieldChild(iter_rep, "step");
        const len_local = try proc.addFrameLocalForRep(len_child.rep);
        const step_local = try proc.addFrameLocalForRep(step_child.rep);

        var continuation = try proc.assignGeneratedParserTwoFieldRecord(
            target,
            iter_rep,
            "len_if_known",
            len_local,
            len_child.rep,
            "step",
            step_local,
            step_child.rep,
            next,
        );
        // The step's type is written against the iterator's backing formals,
        // which this iterator's arguments bind.
        const formal_scope = try proc.enterNominalWrapperFormalScopes(iter_rep);
        errdefer proc.dropNominalBackingFormalScope(formal_scope);
        continuation = try proc.leaveNominalBackingFormalScope(formal_scope, try self.packGeneratedFieldIteratorStep(
            proc,
            step_local,
            step_child.rep,
            step_worker,
            capture_values,
            continuation,
        ));
        return try proc.assignGeneratedIteratorLength(len_local, len_child.rep, mode, known_remaining, continuation);
    }

    fn packGeneratedFieldIteratorStep(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        worker_id: Plan.WorkerPlanId,
        capture_values: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const captures = self.plan.erasedCaptureSlice(worker.erased_captures);
        var descriptor_initializers = std.ArrayList(ProcBodyBuilder.DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.allocator);
        var dictionary_initializers = std.ArrayList(ProcBodyBuilder.DictionaryArgLocal).empty;
        defer dictionary_initializers.deinit(self.allocator);
        // The step's type names the field shape of the frame creating it, which
        // that frame describes.
        const all_capture_values = try self.generatedCodecCaptureValues(proc, worker_id, captures, capture_values, &descriptor_initializers, &dictionary_initializers);
        defer self.allocator.free(all_capture_values);
        if (dictionary_initializers.items.len != 0) {
            boxyLowerInvariant("generated FieldNames iterator step unexpectedly captured literal evidence");
        }

        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated FieldNames iterator step worker was not callable");
        const worker_layout = self.layout_plan.workerLayoutFor(worker_id);
        const erased_proc = try self.reserveErasedWorkerProc(worker_id);
        const result_desc = try proc.exactCallResultDescriptorRef(function.ret);
        const boundary = try self.generatedCallablePackBoundary(proc, target, target_rep, function, next);
        const capture_layout_value = self.result.layouts.getLayout(worker_layout.erased_capture_layout);
        if (capture_layout_value.tag != .struct_ and capture_layout_value.tag != .zst) {
            boxyLowerInvariant("generated FieldNames iterator capture did not have a struct layout");
        }
        const entry = try proc.packGeneratedErasedCallable(
            boundary.target,
            erased_proc,
            worker_id,
            function.rep,
            function.ret,
            result_desc,
            captures,
            all_capture_values,
            worker_layout.erased_capture_layout,
            boundary.next,
        );
        try self.finishGeneratedCallablePackBoundary(proc, boundary);
        return try proc.prependDescriptorArgMaterializations(descriptor_initializers.items, entry);
    }

    fn lowerGeneratedFieldIteratorStepInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedFieldIteratorSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        // The value captures precede the step's descriptor captures.
        const expected_captures: usize = if (source.mode == .for_size) 4 else 3;
        const worker_captures = self.plan.erasedCaptureSlice(worker.erased_captures);
        if (proc.erased_capture_locals.items.len != worker_captures.len or worker_captures.len < expected_captures) {
            boxyLowerInvariant("generated FieldNames iterator step had invalid capture metadata");
        }
        for (worker_captures, 0..) |capture, index| {
            if ((capture.kind == .captured_value) != (index < expected_captures)) {
                boxyLowerInvariant("generated FieldNames iterator step had invalid capture metadata");
            }
        }
        const captures = proc.erased_capture_locals.items[0..expected_captures];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated FieldNames iterator step worker was not callable");
        const done = proc.generatedParserTagVariant(function.ret, "Done");
        const done_body = try proc.assignGeneratedParserZeroTag(target, function.ret, done, next);

        const one = proc.generatedParserTagVariant(function.ret, "One");
        const one_payloads = self.plan.childSlice(one.variant.payloads);
        if (one_payloads.len != 1) boxyLowerInvariant("generated iterator One tag did not have one payload");
        const one_payload_rep = one_payloads[0].rep;
        const item_child = proc.generatedRecordFieldChild(one_payload_rep, "item");
        const rest_child = proc.generatedRecordFieldChild(one_payload_rep, "rest");
        const item = try proc.addFrameLocalForRep(item_child.rep);
        const rest = try proc.addFrameLocalForRep(rest_child.rep);
        const one_payload = try proc.addFrameLocalForRep(one_payload_rep);
        const raw_item = try proc.addFrameLocal(self.layout_plan.generated_evidence.field);

        var one_body = try proc.assignGeneratedParserTag(
            target,
            function.ret,
            one,
            one_payload,
            one_payload_rep,
            next,
        );
        one_body = try proc.assignGeneratedParserTwoFieldRecord(
            one_payload,
            one_payload_rep,
            "item",
            item,
            item_child.rep,
            "rest",
            rest,
            rest_child.rep,
            one_body,
        );

        var dispatch = one_body;
        if (source.mode == .for_size) {
            const skip = proc.generatedParserTagVariant(function.ret, "Skip");
            const skip_payloads = self.plan.childSlice(skip.variant.payloads);
            if (skip_payloads.len != 1) boxyLowerInvariant("generated iterator Skip tag did not have one payload");
            const skip_payload_rep = skip_payloads[0].rep;
            _ = proc.generatedRecordFieldChild(skip_payload_rep, "rest");
            const skip_payload = try proc.addFrameLocalForRep(skip_payload_rep);
            var skip_body = try proc.assignGeneratedParserTag(
                target,
                function.ret,
                skip,
                skip_payload,
                skip_payload_rep,
                next,
            );
            skip_body = try proc.assignGeneratedParserOneFieldRecord(
                skip_payload,
                skip_payload_rep,
                "rest",
                rest,
                rest_child.rep,
                skip_body,
            );
            const name_len = try proc.addFrameLocal(.u64);
            const matches = try proc.addFrameLocal(.bool);
            dispatch = try proc.boolSwitchNoContinuation(matches, one_body, skip_body);
            dispatch = try proc.assignBinaryLowLevel(matches, .num_is_eq, name_len, captures[3], dispatch);
            dispatch = try self.result.store.addCFStmt(.{ .assign_ref = .{
                .target = name_len,
                .op = .{ .field = .{ .source = raw_item, .field_idx = 2 } },
                .next = dispatch,
            } }, proc.derivedOrigin());
        }

        const next_index = try proc.addFrameLocal(.u64);
        const remaining = try proc.addFrameLocal(.u64);
        var next_captures: [4]LIR.LocalId = .{ captures[0], next_index, captures[2], undefined };
        const next_capture_count: usize = switch (source.mode) {
            .all => 3,
            .for_size => blk: {
                next_captures[3] = captures[3];
                break :blk 4;
            },
        };
        dispatch = try self.lowerGeneratedFieldIteratorValueInto(
            proc,
            rest,
            rest_child.rep,
            proc.worker_layout.worker,
            next_captures[0..next_capture_count],
            source.mode,
            if (source.mode == .all) remaining else null,
            dispatch,
        );
        const items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const field_layout = self.layout_plan.generated_evidence.field;
        if (self.result.store.getLocal(item).layout_idx != field_layout) {
            // The step's item is the iterator's element variable, which boxes
            // the field at the descriptor the creating frame captured.
            dispatch = try self.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = item,
                .payload = raw_item,
                .payload_layout = field_layout,
                .payload_desc = try proc.descriptorRefForKnownRep(item_child.rep),
                .payload_mode = .copy,
                .next = dispatch,
            } }, proc.derivedOrigin());
        } else {
            dispatch = try proc.assignLocal(item, raw_item, dispatch);
        }
        dispatch = try proc.assignBinaryLowLevel(raw_item, .list_get_unsafe, items, captures[1], dispatch);
        if (source.mode == .all) {
            dispatch = try proc.assignBinaryLowLevel(remaining, .num_int_sub_crash_on_overflow, captures[2], next_index, dispatch);
        }
        const one_literal = try proc.addFrameLocal(.u64);
        dispatch = try proc.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, captures[1], one_literal, dispatch);
        dispatch = try proc.assignIntLiteral(one_literal, 1, dispatch);
        dispatch = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = items,
            .op = .{ .field = .{ .source = captures[0], .field_idx = 0 } },
            .next = dispatch,
        } }, proc.derivedOrigin());
        const at_end = try proc.addFrameLocal(.bool);
        const choose = try proc.boolSwitchNoContinuation(at_end, done_body, dispatch);
        return try proc.assignBinaryLowLevel(at_end, .num_is_eq, captures[1], captures[2], choose);
    }

    fn lowerGeneratedCodecWorkerInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (source.kind) {
            .parser_constructor,
            .encoder_constructor,
            => try self.lowerGeneratedCodecConstructorInto(proc, target, next),
            .parser_runtime => try self.lowerGeneratedParserRuntimeInto(proc, source, target, next),
            .encoder_runtime => try self.lowerGeneratedEncoderRuntimeInto(proc, source, target, next),
            .encoder_record_fields => try self.lowerGeneratedEncoderRecordFieldsInto(proc, source, target, next),
            .encoder_dict_fields => try self.lowerGeneratedEncoderDictFieldsInto(proc, source, target, next),
            .encoder_sequence_elements => try self.lowerGeneratedEncoderSequenceElementsInto(proc, source, target, next),
            .encoder_tag_payload_elements => try self.lowerGeneratedEncoderTagPayloadElementsInto(proc, source, target, next),
            .encoder_value_thunk => try self.lowerGeneratedEncoderValueThunkInto(proc, source, target, next),
            .encoder_dict_key_thunk => try self.lowerGeneratedEncoderDictKeyThunkInto(proc, source, target, next),
        };
    }

    fn lowerGeneratedEncoderRuntimeInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated encoder runtime was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len == 0) {
            boxyLowerInvariant("generated encoder runtime did not bind encoding, value, and state");
        }
        const body_shape = self.plan.generatedEncoderRuntimeBody(proc.worker_layout.worker) orelse
            boxyLowerInvariant("generated encoder runtime had no planned body shape");
        return try self.lowerGeneratedEncoderShapeInto(
            proc,
            source,
            body_shape,
            proc.arg_locals.items[0],
            proc.arg_locals.items[1],
            target,
            next,
        );
    }

    fn lowerGeneratedEncoderValueThunkInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated encoder value thunk was not callable");
        if (function.arg_count != 1 or proc.arg_locals.items.len < 1 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated encoder value thunk did not bind encoding, value, and state");
        }
        if (source.value_type != null and (source.optional_missing or source.optional_null)) {
            return try self.lowerGeneratedOptionalEncoderValueThunkInto(proc, source, target, next);
        }
        return try self.lowerGeneratedEncoderSchemaInto(
            proc,
            source,
            source.shape,
            source.value_type orelse source.shape,
            proc.erased_capture_locals.items[1],
            proc.arg_locals.items[0],
            target,
            next,
        );
    }

    fn lowerGeneratedOptionalEncoderValueThunkInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const value_type = source.value_type orelse
            boxyLowerInvariant("generated optional encoder thunk had no Try value type");
        if (source.optional_null and source.capture_type == null) {
            boxyLowerInvariant("generated optional encoder thunk had no encoding type");
        }
        var frames: std.ArrayList(EncoderSchemaFrame) = .empty;
        defer frames.deinit(self.allocator);
        const first = try self.beginTryEncoder(proc, &frames, source, source.shape, value_type, proc.erased_capture_locals.items[1], proc.arg_locals.items[0], target, next, source.optional_missing, source.optional_null);
        return try self.runEncoderSchema(proc, &frames, first);
    }

    /// One nested encoder: encode `value` of `subject_type` by `schema_type`
    /// into `target`, then continue with `next`.
    const EncoderSchemaRequest = struct {
        source: Plan.GeneratedCodecSource,
        schema_type: Plan.CheckedTypeIdentity,
        subject_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    };

    const EncoderSchemaStep = union(enum) {
        /// The encoder whose statement the top frame receives next.
        request: EncoderSchemaRequest,
        done: LIR.CFStmtId,
    };

    /// An encoder waiting on the encoder of the one value inside it.
    const EncoderSchemaFrame = union(enum) {
        /// Unbox the value before its payload's encoder.
        box: struct { payload_value: LIR.LocalId, value: LIR.LocalId, payload_rep: Plan.TypeRepId },
        /// Encode a `Try`'s `Ok` payload, or its `Err` as a missing or null
        /// value.
        try_value: struct {
            source: Plan.GeneratedCodecSource,
            value: LIR.LocalId,
            value_rep: Plan.TypeRepId,
            ok: GeneratedParserTagVariant,
            err: GeneratedParserTagVariant,
            ok_payload: ProcBodyBuilder.GeneratedParserTagPayload,
            state: LIR.LocalId,
            target: LIR.LocalId,
            next: LIR.CFStmtId,
            missing: bool,
            null_value: bool,
        },
    };

    fn lowerGeneratedEncoderSchemaInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        schema_type: Plan.CheckedTypeIdentity,
        subject_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var frames: std.ArrayList(EncoderSchemaFrame) = .empty;
        defer frames.deinit(self.allocator);
        return try self.runEncoderSchema(proc, &frames, .{ .request = .{
            .source = source,
            .schema_type = schema_type,
            .subject_type = subject_type,
            .value = value,
            .state = state,
            .target = target,
            .next = next,
        } });
    }

    /// Lower nested encoders down to the innermost, then wrap each outer
    /// encoder around the encoder inside it, innermost first.
    fn runEncoderSchema(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(EncoderSchemaFrame),
        first: EncoderSchemaStep,
    ) Allocator.Error!LIR.CFStmtId {
        var step = first;
        var stmt = while (true) switch (step) {
            .request => |request| step = try self.beginEncoderSchema(proc, frames, request),
            .done => |stmt| break stmt,
        };
        while (frames.pop()) |frame| {
            stmt = switch (frame) {
                .box => |box| try proc.assignBoxBoundary(box.payload_value, box.value, box.payload_rep, .box_unbox, stmt),
                .try_value => |try_value| try self.finishTryEncoder(proc, try_value, stmt),
            };
        }
        return stmt;
    }

    fn beginEncoderSchema(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(EncoderSchemaFrame),
        request: EncoderSchemaRequest,
    ) Allocator.Error!EncoderSchemaStep {
        const source = request.source;
        const schema_type = request.schema_type;
        const subject_type = request.subject_type;
        const value = request.value;
        const state = request.state;
        const target = request.target;
        const next = request.next;
        const caller = proc.worker_layout.worker;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated encoder body had no encoding type");
        const encoding = proc.erased_capture_locals.items[0];

        if (proc.generatedCodecCallPlanOrNull(caller, schema_type, base.Ident.ENCODER_FOR_METHOD_NAME, schema_type)) |constructor_call| {
            const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
            const function = proc.functionChildrenForRep(worker.rep) orelse
                boxyLowerInvariant("generated encoder worker was not callable");
            const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
            const worker_args = worker_children[function.args_start..][0..function.arg_count];
            if (worker_args.len != 1) boxyLowerInvariant("generated encoder worker had an unexpected arity");
            const callable_rep = proc.repForTypeRef(constructor_call.ret_type);
            const callable = try proc.addFrameLocalForRep(callable_rep);
            var continuation = try proc.lowerErasedCallLocalsInto(
                target,
                function.ret,
                callable_rep,
                callable,
                &.{ value, state },
                &.{ proc.repForTypeRef(subject_type), worker_args[0].rep },
                next,
            );
            continuation = try self.lowerGeneratedCodecCallLocalsInto(
                proc,
                constructor_call,
                callable,
                &.{encoding},
                continuation,
            );
            return .{ .done = continuation };
        }

        for (self.plan.generated_encoder_try_plans.items) |try_plan| {
            if (try_plan.worker == caller and planTypeRefEql(try_plan.try_type, schema_type)) {
                if (try_plan.null and source.capture_type == null) {
                    boxyLowerInvariant("generated Try encoder had no encoding type");
                }
                return try self.beginTryEncoder(proc, frames, source, try_plan.ok_type, try_plan.try_type, value, state, target, next, try_plan.missing, try_plan.null);
            }
        }

        const shape_rep = proc.repForTypeRef(schema_type);
        const schema_view = procedureModuleById(self.modules, schema_type.module);
        if (checkedBuiltinNominalForType(schema_view, schema_type.ty)) |builtin| {
            if (builtin == .box) {
                const payload = proc.repQuery().requiredSingleChild(shape_rep, .box_payload);
                const payload_value = try proc.addFrameLocalForRep(payload.rep);
                try frames.append(self.allocator, .{ .box = .{ .payload_value = payload_value, .value = value, .payload_rep = payload.rep } });
                return .{ .request = .{
                    .source = source,
                    .schema_type = payload.source_type,
                    .subject_type = payload.source_type,
                    .value = payload_value,
                    .state = state,
                    .target = target,
                    .next = next,
                } };
            }
            if (builtin == .list) return .{ .done = try self.lowerGeneratedSequenceEncoderInto(
                proc,
                source,
                schema_type,
                subject_type,
                subject_type,
                value,
                state,
                target,
                next,
                "encode_list",
            ) };
            if (builtin == .set) return .{ .done = try self.lowerGeneratedSetEncoderInto(
                proc,
                source,
                schema_type,
                subject_type,
                value,
                state,
                target,
                next,
            ) };
            if (builtin == .dict) return .{ .done = try self.lowerGeneratedDictEncoderInto(
                proc,
                source,
                schema_type,
                subject_type,
                value,
                state,
                target,
                next,
            ) };
        }
        const shape_plan = self.plan.representations.items[@backingInt(shape_rep)];
        if (shape_plan.kind == .alias or shape_plan.kind == .nominal) {
            const role: Plan.ChildRole = if (shape_plan.kind == .alias) .alias_backing else .nominal_backing;
            const backing = proc.repQuery().requiredSingleChild(shape_rep, role);
            var backing_request = request;
            backing_request.schema_type = backing.source_type;
            if (shape_plan.kind == .alias and planTypeRefEql(subject_type, schema_type)) backing_request.subject_type = backing.source_type;
            return .{ .request = backing_request };
        }
        if (generatedCodecScalarMethodForRep(self.plan, shape_rep, "encode_")) |method_text| {
            const call = proc.generatedCodecCallPlan(caller, encoding_type, method_text, subject_type);
            return .{ .done = try self.lowerGeneratedCodecCallLocalsInto(
                proc,
                call,
                target,
                &.{ value, state },
                next,
            ) };
        }
        if (proc.recordRepForBoundary(shape_rep) != null or
            self.plan.representations.items[@backingInt(shape_rep)].kind == .empty_record)
        {
            return .{ .done = try self.lowerGeneratedRecordEncoderInto(
                proc,
                source,
                schema_type,
                subject_type,
                value,
                state,
                target,
                next,
            ) };
        }
        if (proc.tupleRepForBoundary(shape_rep) != null) {
            return .{ .done = try self.lowerGeneratedSequenceEncoderInto(
                proc,
                source,
                schema_type,
                subject_type,
                subject_type,
                value,
                state,
                target,
                next,
                "encode_tuple",
            ) };
        }
        if (proc.tagVariantRepForBoundary(shape_rep) != null) {
            return .{ .done = try self.lowerGeneratedTagEncoderInto(
                proc,
                source,
                schema_type,
                subject_type,
                value,
                state,
                target,
                next,
            ) };
        }
        boxyLowerInvariant("generated encoder shape body is not implemented");
    }

    /// Begin encoding a `Try` whose `Ok` payload is encoded by `ok_type`.
    fn beginTryEncoder(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(EncoderSchemaFrame),
        source: Plan.GeneratedCodecSource,
        ok_type: Plan.CheckedTypeIdentity,
        try_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
        missing: bool,
        null_value: bool,
    ) Allocator.Error!EncoderSchemaStep {
        const value_rep = proc.repForTypeRef(try_type);
        const ok = proc.generatedParserTagVariant(value_rep, "Ok");
        const err = proc.generatedParserTagVariant(value_rep, "Err");
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
        try frames.append(self.allocator, .{ .try_value = .{
            .source = source,
            .value = value,
            .value_rep = value_rep,
            .ok = ok,
            .err = err,
            .ok_payload = ok_payload,
            .state = state,
            .target = target,
            .next = next,
            .missing = missing,
            .null_value = null_value,
        } });
        return .{ .request = .{
            .source = source,
            .schema_type = ok_type,
            .subject_type = ok_type,
            .value = ok_payload.local,
            .state = state,
            .target = target,
            .next = next,
        } };
    }

    fn finishTryEncoder(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        try_value: @FieldType(EncoderSchemaFrame, "try_value"),
        ok_encoded: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const value = try_value.value;
        const err = try_value.err;
        const ok_body = try proc.generatedParserReadTagPayload(value, try_value.ok, try_value.ok_payload, ok_encoded);

        const err_payload = try proc.generatedParserSingleTagPayloadLocal(err);
        const missing_body = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const null_body = if (try_value.null_value) blk: {
            const call = proc.generatedCodecCallPlan(
                proc.worker_layout.worker,
                try_value.source.capture_type.?,
                "encode_null",
                null,
            );
            break :blk try self.lowerGeneratedCodecCallLocalsInto(
                proc,
                call,
                try_value.target,
                &.{try_value.state},
                try_value.next,
            );
        } else missing_body;
        const err_action = if (try_value.missing and try_value.null_value) blk: {
            const missing = proc.generatedParserTagVariant(err_payload.child.rep, "Missing");
            const null_variant = proc.generatedParserTagVariant(err_payload.child.rep, "Null");
            const error_variants = [_]GeneratedParserTagVariant{ missing, null_variant };
            const error_bodies = [_]LIR.CFStmtId{ missing_body, null_body };
            const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
            break :blk try proc.generatedParserTagDispatch(
                err_payload.local,
                err_payload.child.rep,
                &error_variants,
                &error_bodies,
                impossible,
            );
        } else if (try_value.null_value)
            null_body
        else
            missing_body;
        const err_body = try proc.generatedParserReadTagPayload(value, err, err_payload, err_action);
        const variants = [_]GeneratedParserTagVariant{ try_value.ok, err };
        const bodies = [_]LIR.CFStmtId{ ok_body, err_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        return try proc.generatedParserTagDispatch(value, try_value.value_rep, &variants, &bodies, impossible);
    }

    fn lowerGeneratedEncoderShapeInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        shape_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.lowerGeneratedEncoderSchemaInto(
            proc,
            source,
            shape_type,
            shape_type,
            value,
            state,
            target,
            next,
        );
    }

    const GeneratedEncoderRecordField = struct {
        source_type: Plan.CheckedTypeIdentity,
        encode_type: Plan.CheckedTypeIdentity,
        rep: Plan.TypeRepId,
        renamed: LIR.LocalId,
        index: usize,
        optional_error_type: ?Plan.CheckedTypeIdentity,
        optional_missing: bool,
        optional_null: bool,
    };

    fn lowerGeneratedRecordEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        shape_type: Plan.CheckedTypeIdentity,
        value_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const contract_worker = source.contract_worker orelse caller;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated record encoder had no encoding type");
        const call = proc.generatedCodecCallPlan(caller, encoding_type, "encode_record", value_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 3) boxyLowerInvariant("generated encode_record call did not have three arguments");

        const callback_source = Plan.GeneratedCodecSource{
            .kind = .encoder_record_fields,
            .shape = shape_type,
            .value_type = value_type,
            .capture_type = encoding_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const callback_worker = self.plan.workerForSourceType(
            .{ .generated_codec = callback_source },
            arg_types[2],
        ) orelse boxyLowerInvariant("generated record encoder had no planned field callback");
        const callback = try proc.addFrameLocalForRep(proc.repForTypeRef(arg_types[2]));
        const count = try proc.addFrameLocal(.u64);
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = value;
        @memcpy(capture_values[2..], name_captures);

        const fields = try self.generatedEncoderRecordFields(proc, contract_worker, shape_type);
        defer self.allocator.free(fields);
        var continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            target,
            &.{ state, count, callback },
            next,
        );
        continuation = try self.packGeneratedCodecCallable(
            proc,
            callback,
            proc.repForTypeRef(arg_types[2]),
            callback_worker,
            capture_values,
            continuation,
        );
        continuation = try self.lowerGeneratedEncoderRecordCount(
            proc,
            fields,
            0,
            value,
            count,
            continuation,
        );
        return try proc.assignIntLiteral(count, @intCast(fields.len), continuation);
    }

    /// Count the fields from `first_field` on that are present, built from
    /// the last field backward.
    fn lowerGeneratedEncoderRecordCount(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        fields: []const GeneratedEncoderRecordField,
        first_field: usize,
        record_value: LIR.LocalId,
        count: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        var field_index = fields.len;
        while (field_index > first_field) {
            field_index -= 1;
            continuation = try self.lowerGeneratedEncoderRecordFieldCount(proc, fields[field_index], record_value, count, continuation);
        }
        return continuation;
    }

    /// Decrement `count` when an optional field is missing, before
    /// `continuation`.
    fn lowerGeneratedEncoderRecordFieldCount(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        field: GeneratedEncoderRecordField,
        record_value: LIR.LocalId,
        count: LIR.LocalId,
        continuation: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!field.optional_missing) return continuation;

        const field_value = try proc.addFrameLocalForRep(field.rep);
        const ok = proc.generatedParserTagVariant(field.rep, "Ok");
        const err = proc.generatedParserTagVariant(field.rep, "Err");
        const err_payload = try proc.generatedParserSingleTagPayloadLocal(err);
        const missing = proc.generatedParserTagVariant(err_payload.child.rep, "Missing");
        const one = try proc.addFrameLocal(.u64);
        const decremented = try proc.addFrameLocal(.u64);
        var missing_body = try proc.setLocalReplace(count, decremented, continuation);
        missing_body = try proc.assignBinaryLowLevel(decremented, .num_int_sub_crash_on_overflow, count, one, missing_body);
        missing_body = try proc.assignIntLiteral(one, 1, missing_body);

        const error_dispatch = if (field.optional_null) blk: {
            const null_variant = proc.generatedParserTagVariant(err_payload.child.rep, "Null");
            const variants = [_]GeneratedParserTagVariant{ missing, null_variant };
            const bodies = [_]LIR.CFStmtId{ missing_body, continuation };
            const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
            break :blk try proc.generatedParserTagDispatch(
                err_payload.local,
                err_payload.child.rep,
                &variants,
                &bodies,
                impossible,
            );
        } else missing_body;
        const err_body = try proc.generatedParserReadTagPayload(field_value, err, err_payload, error_dispatch);
        const variants = [_]GeneratedParserTagVariant{ ok, err };
        const bodies = [_]LIR.CFStmtId{ continuation, err_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const dispatch = try proc.generatedParserTagDispatch(field_value, field.rep, &variants, &bodies, impossible);
        return try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = field_value,
            .op = .{ .field = .{ .source = record_value, .field_idx = @intCast(field.index) } },
            .next = dispatch,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedSequenceEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        shape_type: Plan.CheckedTypeIdentity,
        value_type: Plan.CheckedTypeIdentity,
        call_subject_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
        method_text: []const u8,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const contract_worker = source.contract_worker orelse caller;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated sequence encoder had no encoding type");
        const call = proc.generatedCodecCallPlan(caller, encoding_type, method_text, call_subject_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 3) boxyLowerInvariant("generated sequence encoder call did not have three arguments");
        const callback_source = Plan.GeneratedCodecSource{
            .kind = .encoder_sequence_elements,
            .shape = shape_type,
            .value_type = value_type,
            .capture_type = encoding_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const callback_worker = self.plan.workerForSourceType(
            .{ .generated_codec = callback_source },
            arg_types[2],
        ) orelse boxyLowerInvariant("generated sequence encoder had no planned element callback");
        const callback = try proc.addFrameLocalForRep(proc.repForTypeRef(arg_types[2]));
        const count = try proc.addFrameLocal(.u64);
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = value;
        @memcpy(capture_values[2..], name_captures);
        const shape_rep = proc.repForTypeRef(shape_type);
        const tuple_items = if (proc.tupleRepForBoundary(shape_rep) != null)
            try self.generatedParserTupleItems(proc, shape_rep)
        else
            null;
        defer if (tuple_items) |items| self.allocator.free(items);
        if (tuple_items == null and proc.listRepForBoundary(shape_rep) == null) {
            boxyLowerInvariant("generated sequence encoder shape was neither a tuple nor a List");
        }

        var continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            target,
            &.{ state, count, callback },
            next,
        );
        continuation = try self.packGeneratedCodecCallable(
            proc,
            callback,
            proc.repForTypeRef(arg_types[2]),
            callback_worker,
            capture_values,
            continuation,
        );
        return if (tuple_items) |items|
            try proc.assignIntLiteral(count, @intCast(items.len), continuation)
        else
            try proc.assignUnaryLowLevel(count, .list_len, value, continuation);
    }

    fn lowerGeneratedSetEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        set_type: Plan.CheckedTypeIdentity,
        subject_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const to_list = proc.generatedCodecCallPlan(caller, set_type, "to_list", set_type);
        const list = try proc.addFrameLocalForRep(proc.repForTypeRef(to_list.ret_type));
        var continuation = try self.lowerGeneratedSequenceEncoderInto(
            proc,
            source,
            to_list.ret_type,
            to_list.ret_type,
            subject_type,
            list,
            state,
            target,
            next,
            "encode_list",
        );
        continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            to_list,
            list,
            &.{value},
            continuation,
        );
        return continuation;
    }

    fn lowerGeneratedDictEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        dict_type: Plan.CheckedTypeIdentity,
        subject_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const contract_worker = source.contract_worker orelse caller;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated Dict encoder had no encoding type");
        const to_list = proc.generatedCodecCallPlan(caller, dict_type, "to_list", dict_type);
        const entries_type = to_list.ret_type;
        const entries = try proc.addFrameLocalForRep(proc.repForTypeRef(entries_type));
        const call = proc.generatedCodecCallPlan(caller, encoding_type, "encode_dict", subject_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 3) boxyLowerInvariant("generated Dict encode_dict call did not have three arguments");
        const callback_source = Plan.GeneratedCodecSource{
            .kind = .encoder_dict_fields,
            .shape = entries_type,
            .value_type = entries_type,
            .capture_type = encoding_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const callback_worker = self.plan.workerForSourceType(
            .{ .generated_codec = callback_source },
            arg_types[2],
        ) orelse boxyLowerInvariant("generated Dict encoder had no planned field callback");
        const callback = try proc.addFrameLocalForRep(proc.repForTypeRef(arg_types[2]));
        const count = try proc.addFrameLocal(.u64);
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = entries;
        @memcpy(capture_values[2..], name_captures);

        var continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            target,
            &.{ state, count, callback },
            next,
        );
        continuation = try self.packGeneratedCodecCallable(
            proc,
            callback,
            proc.repForTypeRef(arg_types[2]),
            callback_worker,
            capture_values,
            continuation,
        );
        continuation = try proc.assignUnaryLowLevel(count, .list_len, entries, continuation);
        return try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            to_list,
            entries,
            &.{value},
            continuation,
        );
    }

    fn lowerGeneratedTagEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        shape_type: Plan.CheckedTypeIdentity,
        value_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const contract_worker = source.contract_worker orelse caller;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated tag encoder had no encoding type");
        const call = proc.generatedCodecCallPlan(caller, encoding_type, "encode_tag", value_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 4) boxyLowerInvariant("generated tag encode_tag call did not have four arguments");
        const callback_source = Plan.GeneratedCodecSource{
            .kind = .encoder_tag_payload_elements,
            .shape = shape_type,
            .value_type = value_type,
            .capture_type = encoding_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const callback_worker = self.plan.workerForSourceType(
            .{ .generated_codec = callback_source },
            arg_types[3],
        ) orelse boxyLowerInvariant("generated tag encoder had no planned payload callback");
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);

        const variants = try self.generatedEncoderTagVariants(proc, shape_type, false);
        defer self.allocator.free(variants);
        const bodies = try self.allocator.alloc(LIR.CFStmtId, variants.len);
        defer self.allocator.free(bodies);
        for (variants, bodies) |variant, *body| {
            const tag_name = try proc.addFrameLocal(.str);
            const count = try proc.addFrameLocal(.u64);
            const callback_rep = proc.repForTypeRef(arg_types[3]);
            const callback = try proc.addFrameLocalForRep(callback_rep);
            const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
            defer self.allocator.free(capture_values);
            capture_values[0] = proc.erased_capture_locals.items[0];
            capture_values[1] = value;
            @memcpy(capture_values[2..], name_captures);

            var continuation = try self.lowerGeneratedCodecCallLocalsInto(
                proc,
                call,
                target,
                &.{ state, tag_name, count, callback },
                next,
            );
            continuation = try self.packGeneratedCodecCallable(
                proc,
                callback,
                callback_rep,
                callback_worker,
                capture_values,
                continuation,
            );
            continuation = try proc.assignIntLiteral(
                count,
                @intCast(self.plan.childSlice(variant.variant.payloads).len),
                continuation,
            );
            body.* = try proc.assignStringBytesLiteral(tag_name, proc.tagVariantNameText(variant.variant), continuation);
        }
        return try self.lowerGeneratedEncoderTagDispatch(proc, value, variants, bodies);
    }

    fn generatedEncoderTagVariants(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_type: Plan.CheckedTypeIdentity,
        payload_only: bool,
    ) Allocator.Error![]GeneratedParserTagVariant {
        const application_rep = proc.repForTypeRef(shape_type);
        const tag_rep = proc.tagVariantRepForBoundary(application_rep) orelse
            boxyLowerInvariant("generated tag encoder shape had no closed tag representation");
        const rep = self.plan.representations.items[@backingInt(tag_rep)];
        if (rep.kind != .tag_union) {
            boxyLowerInvariant("generated structural tag encoder required a concrete tag representation");
        }
        for (self.plan.childSlice(rep.children)) |child| {
            if (child.role == .tag_ext) {
                var extension = child.rep;
                while (true) {
                    const extension_rep = self.plan.representations.items[@backingInt(extension)];
                    if (extension_rep.kind == .alias) {
                        extension = proc.repQuery().requiredSingleChild(extension, .alias_backing).rep;
                    } else if (extension_rep.kind == .nominal) {
                        extension = proc.repQuery().requiredSingleChild(extension, .nominal_backing).rep;
                    } else if (extension_rep.kind == .empty_tag_union) {
                        break;
                    } else {
                        boxyLowerInvariant("generated tag encoder required a flattened closed tag row");
                    }
                }
            }
        }
        const planned = self.plan.tagVariantSlice(rep.tag_variants);
        var count: usize = 0;
        for (planned) |variant| {
            if (!payload_only or self.plan.childSlice(variant.payloads).len != 0) count += 1;
        }
        if (count == 0) boxyLowerInvariant("generated tag encoder dispatch had no applicable variants");
        const variants = try self.allocator.alloc(GeneratedParserTagVariant, count);
        var out_index: usize = 0;
        for (planned, 0..) |variant, index| {
            if (payload_only and self.plan.childSlice(variant.payloads).len == 0) continue;
            if (index > std.math.maxInt(u32)) boxyLowerInvariant("generated tag encoder variant index exceeded LIR range");
            variants[out_index] = .{
                .boundary_rep = proc.repForTypeRef(shape_type),
                .tag_rep = tag_rep,
                .owner_rep = tag_rep,
                .index = @intCast(index),
                .variant = variant,
            };
            out_index += 1;
        }
        return variants;
    }

    fn lowerGeneratedEncoderTagDispatch(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: LIR.LocalId,
        variants: []const GeneratedParserTagVariant,
        bodies: []const LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (variants.len != bodies.len or variants.len == 0) {
            boxyLowerInvariant("generated tag encoder dispatch metadata was invalid");
        }
        if (variants.len == 1) return bodies[0];
        return try proc.generatedParserTagDispatch(
            source,
            variants[0].tag_rep,
            variants[0 .. variants.len - 1],
            bodies[0 .. bodies.len - 1],
            bodies[bodies.len - 1],
        );
    }

    fn generatedEncoderNameCaptureLocals(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        contract_worker: Plan.WorkerPlanId,
    ) []const LIR.LocalId {
        var count: usize = 0;
        for (self.plan.generated_parser_field_captures.items) |capture| {
            if (capture.worker == contract_worker) count += 1;
        }
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        var captured_value_count: usize = 0;
        for (self.plan.erasedCaptureSlice(worker.erased_captures)) |capture| {
            if (capture.kind == .captured_value) captured_value_count += 1;
        }
        if (captured_value_count < count or proc.erased_capture_locals.items.len < captured_value_count) {
            boxyLowerInvariant("generated encoder field-name captures exceeded bound captures");
        }
        return proc.erased_capture_locals.items[captured_value_count - count .. captured_value_count];
    }

    fn generatedEncoderRecordFields(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        contract_worker: Plan.WorkerPlanId,
        shape_type: Plan.CheckedTypeIdentity,
    ) Allocator.Error![]GeneratedEncoderRecordField {
        const shape_rep = proc.repForTypeRef(shape_type);
        const record_rep_id = proc.recordRepForBoundary(shape_rep);
        if (record_rep_id == null) {
            if (self.plan.representations.items[@backingInt(shape_rep)].kind != .empty_record) {
                boxyLowerInvariant("generated encoder record shape had no record representation");
            }
            return try self.allocator.alloc(GeneratedEncoderRecordField, 0);
        }
        const record = self.plan.representations.items[@backingInt(record_rep_id.?)];
        const children = self.plan.childSlice(record.children);
        var field_count: usize = 0;
        for (children) |child| {
            if (child.role == .record_field) {
                field_count += 1;
            } else if (child.role == .record_ext) {
                proc.requireEmptyRecordExtension(child.rep);
            } else {
                boxyLowerInvariant("generated encoder record representation had a non-record child");
            }
        }
        const fields = try self.allocator.alloc(GeneratedEncoderRecordField, field_count);
        const record_view = procedureModuleById(self.modules, record.source_type.module);
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);

        var out_index: usize = 0;
        for (children) |child| {
            if (child.role == .record_ext) continue;
            if (child.role != .record_field) unreachable;
            const label = child.role.record_field;
            var capture_index: usize = 0;
            var renamed: ?LIR.LocalId = null;
            var field_capture: ?Plan.GeneratedParserFieldCapture = null;
            for (self.plan.generated_parser_field_captures.items) |capture| {
                if (capture.worker != contract_worker) continue;
                if (capture_index >= name_captures.len) {
                    boxyLowerInvariant("generated encoder field capture exceeded bound names");
                }
                const capture_view = procedureModuleById(self.modules, capture.field_module);
                if (planTypeRefEql(capture.record_type, shape_type) and
                    Plan.recordFieldNameMatches(viewNames(record_view), label, viewNames(capture_view), capture.field_name))
                {
                    if (renamed != null) boxyLowerInvariant("generated encoder record field had duplicate renamed captures");
                    renamed = name_captures[capture_index];
                    field_capture = capture;
                }
                capture_index += 1;
            }
            const capture = field_capture orelse
                boxyLowerInvariant("generated encoder record field had no checked capture metadata");
            fields[out_index] = .{
                .source_type = child.source_type,
                .encode_type = capture.parse_type,
                .rep = child.rep,
                .renamed = renamed orelse boxyLowerInvariant("generated encoder record field had no renamed capture"),
                .index = out_index,
                .optional_error_type = capture.optional_error_type,
                .optional_missing = capture.optional_missing,
                .optional_null = capture.optional_null,
            };
            out_index += 1;
        }
        return fields;
    }

    fn packGeneratedCodecCallable(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        worker_id: Plan.WorkerPlanId,
        capture_values: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(worker_id)];
        const captures = self.plan.erasedCaptureSlice(worker.erased_captures);
        var descriptor_initializers = std.ArrayList(ProcBodyBuilder.DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.allocator);
        var dictionary_initializers = std.ArrayList(ProcBodyBuilder.DictionaryArgLocal).empty;
        defer dictionary_initializers.deinit(self.allocator);
        const all_capture_values = try self.generatedCodecCaptureValues(proc, worker_id, captures, capture_values, &descriptor_initializers, &dictionary_initializers);
        defer self.allocator.free(all_capture_values);
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated codec callback worker was not callable");
        const worker_layout = self.layout_plan.workerLayoutFor(worker_id);
        const erased_proc = try self.reserveErasedWorkerProc(worker_id);
        const boundary = try self.generatedCallablePackBoundary(proc, target, target_rep, function, next);
        const result_desc = try proc.exactCallResultDescriptorRef(function.ret);
        const entry = try proc.packGeneratedErasedCallable(
            boundary.target,
            erased_proc,
            worker_id,
            function.rep,
            function.ret,
            result_desc,
            captures,
            all_capture_values,
            worker_layout.erased_capture_layout,
            boundary.next,
        );
        try self.finishGeneratedCallablePackBoundary(proc, boundary);
        return try proc.prependDescriptorArgMaterializations(descriptor_initializers.items, try proc.prependHiddenDictionaryArgMaterialization(dictionary_initializers.items, entry));
    }

    const GeneratedCallableAdapterBoundary = struct {
        target: LIR.LocalId,
        target_function: ProcBodyBuilder.FunctionChildren,
        source_function: ProcBodyBuilder.FunctionChildren,
        next: LIR.CFStmtId,
        placeholder: LIR.CFStmtId,
    };

    const GeneratedCallablePackBoundary = struct {
        target: LIR.LocalId,
        next: LIR.CFStmtId,
        adapter: ?GeneratedCallableAdapterBoundary,
    };

    fn generatedCallablePackBoundary(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_function: ProcBodyBuilder.FunctionChildren,
        next: LIR.CFStmtId,
    ) Allocator.Error!GeneratedCallablePackBoundary {
        const target_function = proc.functionChildrenForRep(target_rep) orelse
            boxyLowerInvariant("generated callable target representation was not callable");
        const needs_adapter = try proc.callableBoundaryNeedsAdapter(target_function, source_function);
        if (!needs_adapter) {
            return .{ .target = target, .next = next, .adapter = null };
        }

        const raw_target = try proc.addFrameLocalForRep(source_function.rep);
        const placeholder = try proc.parent.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        return .{
            .target = raw_target,
            .next = placeholder,
            .adapter = .{
                .target = target,
                .target_function = target_function,
                .source_function = source_function,
                .next = next,
                .placeholder = placeholder,
            },
        };
    }

    fn finishGeneratedCallablePackBoundary(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        boundary: GeneratedCallablePackBoundary,
    ) Allocator.Error!void {
        const adapter = boundary.adapter orelse return;
        const adapted = try proc.assignErasedCallableBoundary(
            adapter.target,
            boundary.target,
            adapter.target_function,
            adapter.source_function,
            adapter.next,
        );
        try proc.parent.result.store.replaceCFStmt(adapter.placeholder, proc.parent.result.store.getCFStmt(adapted), proc.parent.result.store.stmtOrigin(adapted));
    }

    fn generatedCodecCaptureValues(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        captures: []const Plan.ErasedCapture,
        captured_values: []const LIR.LocalId,
        descriptor_initializers: *std.ArrayList(ProcBodyBuilder.DescriptorArgLocal),
        dictionary_initializers: *std.ArrayList(ProcBodyBuilder.DictionaryArgLocal),
    ) Allocator.Error![]LIR.LocalId {
        const values = try self.allocator.alloc(LIR.LocalId, captures.len);
        errdefer self.allocator.free(values);

        var value_index: usize = 0;
        for (captures, values) |capture, *value| {
            switch (capture.kind) {
                .captured_value => {
                    if (value_index >= captured_values.len) {
                        boxyLowerInvariant("generated codec callable had fewer value captures than its worker");
                    }
                    value.* = captured_values[value_index];
                    value_index += 1;
                    if (self.result.store.getLocal(value.*).layout_idx != proc.workerRuntimeLayoutForRep(capture.rep).layoutIdx()) {
                        boxyLowerInvariant("generated codec callable value capture layout disagreed with its worker");
                    }
                },
                .hidden_desc => {
                    const desc = capture.desc orelse
                        boxyLowerInvariant("generated codec callable descriptor capture had no requirement");
                    // A generated callback is instantiated at the enclosing
                    // frame's types, so the frame describes each of its
                    // descriptor captures.
                    value.* = proc.descriptorLocalForRequirementAndRepOrNull(desc, capture.rep) orelse materialized: {
                        const materialization = try proc.descriptorMaterializationForSourceRep(capture.rep);
                        const local = try proc.addFrameLocal(.opaque_ptr);
                        try descriptor_initializers.append(self.allocator, materialization.initializer(local));
                        break :materialized local;
                    };
                },
                .hidden_literal => {
                    const arguments = self.plan.literal_evidence.?.generated_captures.get(.{
                        .caller = proc.worker_layout.worker,
                        .worker = worker_id,
                    }) orelse boxyLowerInvariant("generated callable omitted planned literal captures");
                    const reference = try proc.literalReference(arguments[capture.literal_parameter.?]);
                    value.* = switch (reference) {
                        .local => |local| local,
                        .static, .runtime => materialized: {
                            const local = try proc.addFrameLocal(.opaque_ptr);
                            try dictionary_initializers.append(self.allocator, .{ .local = local, .materialize = reference });
                            break :materialized local;
                        },
                    };
                },
                .hidden_dict => boxyLowerInvariant("generated codec callable unexpectedly required a dictionary capture"),
            }
        }
        if (value_index != captured_values.len) {
            boxyLowerInvariant("generated codec callable had more value captures than its worker");
        }
        return values;
    }

    fn lowerGeneratedEncoderRecordFieldsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated encoder record callback was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated encoder record callback had invalid arguments or captures");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated encoder record callback had no contract worker");
        const fields = try self.generatedEncoderRecordFields(proc, contract_worker, source.shape);
        defer self.allocator.free(fields);
        return try self.lowerGeneratedEncoderRecordFieldsFrom(
            proc,
            source,
            fields,
            0,
            proc.erased_capture_locals.items[1],
            proc.arg_locals.items[0],
            args[0].rep,
            proc.arg_locals.items[1],
            args[1].rep,
            function.ret,
            target,
            next,
        );
    }

    /// One record field's encoder, waiting on the encoder of the fields
    /// after it: once after writing the field, and, for a field that can be
    /// absent, once more after skipping it.
    const EncoderRecordFieldFrame = struct {
        field_index: usize,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        writer_args: []const Plan.RepChild,
        contract_worker: Plan.WorkerPlanId,
        thunk_worker: Plan.WorkerPlanId,
        presence: ?ProcBodyBuilder.PresenceSlotVariants,
        field_slot: LIR.LocalId,
        present_payload: ?ProcBodyBuilder.GeneratedParserTagPayload,
        field_value: LIR.LocalId,
        field_value_rep: Plan.TypeRepId,
        thunk_rep: Plan.TypeRepId,
        thunk: LIR.LocalId,
        result: LIR.LocalId,
        ok: GeneratedParserTagVariant,
        ok_payload: ProcBodyBuilder.GeneratedParserTagPayload,
        /// The field's write, once built; the fields after a skipped field
        /// are encoded next.
        written: ?LIR.CFStmtId = null,
    };

    fn lowerGeneratedEncoderRecordFieldsFrom(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        fields: []const GeneratedEncoderRecordField,
        first_field_index: usize,
        record_value: LIR.LocalId,
        first_state: LIR.LocalId,
        first_state_rep: Plan.TypeRepId,
        field_writer: LIR.LocalId,
        field_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var frames: std.ArrayList(EncoderRecordFieldFrame) = .empty;
        defer frames.deinit(self.allocator);
        var field_index = first_field_index;
        var state = first_state;
        var state_rep = first_state_rep;
        while (true) {
            // Begin the fields from `field_index` at `state`.
            var encoded = if (field_index == fields.len) blk: {
                const ok = proc.generatedParserTagVariant(target_rep, "Ok");
                const payloads = self.plan.childSlice(ok.variant.payloads);
                if (payloads.len != 1) boxyLowerInvariant("generated encoder Ok did not have one state payload");
                break :blk try proc.assignGeneratedParserTag(target, target_rep, ok, state, state_rep, next);
            } else {
                const field = fields[field_index];
                const writer_fn = proc.functionChildrenForRep(field_writer_rep) orelse
                    boxyLowerInvariant("generated encoder field writer was not callable");
                const writer_children = self.plan.childSlice(self.plan.representations.items[@backingInt(writer_fn.rep)].children);
                const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
                if (writer_args.len != 3) boxyLowerInvariant("generated encoder field writer had an unexpected arity");
                const thunk_type = writer_args[2].source_type;
                const contract_worker = source.contract_worker orelse
                    boxyLowerInvariant("generated encoder record callback had no contract worker");
                const thunk_source = Plan.GeneratedCodecSource{
                    .kind = .encoder_value_thunk,
                    .shape = field.encode_type,
                    .value_type = if (field.optional_error_type != null) field.source_type else null,
                    .optional_missing = field.optional_missing,
                    .optional_null = field.optional_null,
                    .capture_type = source.capture_type,
                    .contract_worker = contract_worker,
                    .contract_expr = source.contract_expr,
                };
                const thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = thunk_source }, thunk_type) orelse
                    boxyLowerInvariant("generated encoder field had no planned value thunk");
                // A still-undetermined field's storage is its presence slot; the
                // encoder writes the Present payload and skips a Missing field.
                const presence = proc.presenceSlotVariants(field.rep);
                const field_slot = try proc.addFrameLocalForRep(field.rep);
                const present_payload = if (presence) |slot| try proc.generatedParserSingleTagPayloadLocal(slot.present) else null;
                const thunk_rep = proc.repForTypeRef(thunk_type);
                const thunk = try proc.addFrameLocalForRep(thunk_rep);
                const result = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(target_rep);
                const ok = proc.generatedParserTagVariant(target_rep, "Ok");
                const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
                try frames.append(self.allocator, .{
                    .field_index = field_index,
                    .state = state,
                    .state_rep = state_rep,
                    .writer_args = writer_args,
                    .contract_worker = contract_worker,
                    .thunk_worker = thunk_worker,
                    .presence = presence,
                    .field_slot = field_slot,
                    .present_payload = present_payload,
                    .field_value = if (present_payload) |payload| payload.local else field_slot,
                    .field_value_rep = if (present_payload) |payload| payload.child.rep else field.rep,
                    .thunk_rep = thunk_rep,
                    .thunk = thunk,
                    .result = result,
                    .ok = ok,
                    .ok_payload = ok_payload,
                });
                field_index += 1;
                state = ok_payload.local;
                state_rep = ok_payload.child.rep;
                continue;
            };
            // Finish each field waiting on the fields after it.
            while (frames.items.len != 0) {
                const frame = &frames.items[frames.items.len - 1];
                const field = fields[frame.field_index];
                if (frame.written == null) {
                    var success = try proc.generatedParserReadTagPayload(frame.result, frame.ok, frame.ok_payload, encoded);
                    const err = try proc.assignRepresentationBoundary(target, frame.result, target_rep, target_rep, next);
                    const variants = [_]GeneratedParserTagVariant{frame.ok};
                    const bodies = [_]LIR.CFStmtId{success};
                    success = try proc.generatedParserTagDispatch(frame.result, target_rep, &variants, &bodies, err);
                    success = try proc.lowerErasedCallLocalsInto(
                        frame.result,
                        target_rep,
                        field_writer_rep,
                        field_writer,
                        &.{ frame.state, field.renamed, frame.thunk },
                        &.{ frame.state_rep, frame.writer_args[1].rep, frame.thunk_rep },
                        success,
                    );

                    const name_captures = self.generatedEncoderNameCaptureLocals(proc, frame.contract_worker);
                    const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
                    defer self.allocator.free(capture_values);
                    capture_values[0] = proc.erased_capture_locals.items[0];
                    capture_values[1] = frame.field_value;
                    @memcpy(capture_values[2..], name_captures);
                    frame.written = try self.packGeneratedCodecCallable(proc, frame.thunk, frame.thunk_rep, frame.thunk_worker, capture_values, success);
                    if (field.optional_missing or frame.presence != null) {
                        // Encode the fields after this one again, skipping it.
                        field_index = frame.field_index + 1;
                        state = frame.state;
                        state_rep = frame.state_rep;
                        break;
                    }
                    encoded = try self.finishGeneratedEncoderRecordField(proc, record_value, field, frame.*, null);
                } else {
                    encoded = try self.finishGeneratedEncoderRecordField(proc, record_value, field, frame.*, encoded);
                }
                frames.items.len -= 1;
            } else return encoded;
        }
    }

    /// Dispatch on whether a field is present, then read it from the record.
    fn finishGeneratedEncoderRecordField(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        record_value: LIR.LocalId,
        field: GeneratedEncoderRecordField,
        frame: EncoderRecordFieldFrame,
        skipped: ?LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = frame.written.?;
        const field_value = frame.field_value;
        const field_value_rep = frame.field_value_rep;
        if (field.optional_missing) {
            const field_ok = proc.generatedParserTagVariant(field_value_rep, "Ok");
            const field_err = proc.generatedParserTagVariant(field_value_rep, "Err");
            const err_payload = try proc.generatedParserSingleTagPayloadLocal(field_err);
            const missing = proc.generatedParserTagVariant(err_payload.child.rep, "Missing");
            const err_dispatch = if (field.optional_null) blk: {
                const null_variant = proc.generatedParserTagVariant(err_payload.child.rep, "Null");
                const error_variants = [_]GeneratedParserTagVariant{ missing, null_variant };
                const error_bodies = [_]LIR.CFStmtId{ skipped.?, continuation };
                const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                break :blk try proc.generatedParserTagDispatch(
                    err_payload.local,
                    err_payload.child.rep,
                    &error_variants,
                    &error_bodies,
                    impossible,
                );
            } else skipped.?;
            const err_body = try proc.generatedParserReadTagPayload(field_value, field_err, err_payload, err_dispatch);
            const optional_variants = [_]GeneratedParserTagVariant{ field_ok, field_err };
            const optional_bodies = [_]LIR.CFStmtId{ continuation, err_body };
            const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
            continuation = try proc.generatedParserTagDispatch(
                field_value,
                field_value_rep,
                &optional_variants,
                &optional_bodies,
                impossible,
            );
        }
        if (frame.presence) |slot| {
            const present_body = try proc.generatedParserReadTagPayload(frame.field_slot, slot.present, frame.present_payload.?, continuation);
            const slot_variants = [_]GeneratedParserTagVariant{ slot.present, slot.missing };
            const slot_bodies = [_]LIR.CFStmtId{ present_body, skipped.? };
            const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
            continuation = try proc.generatedParserTagDispatch(
                frame.field_slot,
                field.rep,
                &slot_variants,
                &slot_bodies,
                impossible,
            );
        }
        return try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = frame.field_slot,
            .op = .{ .field = .{ .source = record_value, .field_idx = @intCast(field.index) } },
            .next = continuation,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedEncoderSequenceElementsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated encoder sequence callback was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated encoder sequence callback had invalid arguments or captures");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];
        const shape_rep = proc.repForTypeRef(source.shape);
        if (proc.listRepForBoundary(shape_rep)) |list_rep| {
            return try self.lowerGeneratedEncoderListElementsInto(
                proc,
                source,
                list_rep,
                proc.erased_capture_locals.items[1],
                proc.arg_locals.items[0],
                args[0].rep,
                proc.arg_locals.items[1],
                args[1].rep,
                function.ret,
                target,
                next,
            );
        }
        const items = try self.generatedParserTupleItems(proc, shape_rep);
        defer self.allocator.free(items);
        return try self.lowerGeneratedEncoderSequenceElementsFrom(
            proc,
            source,
            items,
            0,
            proc.erased_capture_locals.items[1],
            proc.arg_locals.items[0],
            args[0].rep,
            proc.arg_locals.items[1],
            args[1].rep,
            function.ret,
            target,
            next,
        );
    }

    /// One element's encoder, waiting on the encoder of the elements after it.
    const EncoderElementFrame = struct {
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        contract_worker: Plan.WorkerPlanId,
        thunk_worker: Plan.WorkerPlanId,
        value: ProcBodyBuilder.ExtractedTagPayloadLocal,
        thunk_rep: Plan.TypeRepId,
        thunk: LIR.LocalId,
        result: LIR.LocalId,
        ok: GeneratedParserTagVariant,
        ok_payload: ProcBodyBuilder.GeneratedParserTagPayload,
    };

    /// Write one element through the element writer, continuing into the
    /// elements after it when the write succeeds.
    fn finishGeneratedEncoderElement(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frame: EncoderElementFrame,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
        rest: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const success = try proc.generatedParserReadTagPayload(frame.result, frame.ok, frame.ok_payload, rest);
        const err = try proc.assignRepresentationBoundary(target, frame.result, target_rep, target_rep, next);
        const result_variants = [_]GeneratedParserTagVariant{frame.ok};
        const result_bodies = [_]LIR.CFStmtId{success};
        var continuation = try proc.generatedParserTagDispatch(
            frame.result,
            target_rep,
            &result_variants,
            &result_bodies,
            err,
        );
        continuation = try proc.lowerErasedCallLocalsInto(
            frame.result,
            target_rep,
            element_writer_rep,
            element_writer,
            &.{ frame.state, frame.thunk },
            &.{ frame.state_rep, frame.thunk_rep },
            continuation,
        );
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, frame.contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = frame.value.local;
        @memcpy(capture_values[2..], name_captures);
        return try self.packGeneratedCodecCallable(proc, frame.thunk, frame.thunk_rep, frame.thunk_worker, capture_values, continuation);
    }

    /// The element writer's value thunk type for an element of `element_type`,
    /// and the worker planned for it.
    fn generatedEncoderElementThunk(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        element_type: Plan.CheckedTypeIdentity,
        element_writer_rep: Plan.TypeRepId,
        comptime what: []const u8,
    ) struct { thunk_type: Plan.CheckedTypeIdentity, contract_worker: Plan.WorkerPlanId, thunk_worker: Plan.WorkerPlanId } {
        const writer_fn = proc.functionChildrenForRep(element_writer_rep) orelse
            boxyLowerInvariant("generated " ++ what ++ " writer was not callable");
        const writer_children = self.plan.childSlice(self.plan.representations.items[@backingInt(writer_fn.rep)].children);
        const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
        if (writer_args.len != 2) boxyLowerInvariant("generated " ++ what ++ " writer had an unexpected arity");
        const thunk_type = writer_args[1].source_type;
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated " ++ what ++ " callback had no contract worker");
        const thunk_source = Plan.GeneratedCodecSource{
            .kind = .encoder_value_thunk,
            .shape = element_type,
            .capture_type = source.capture_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = thunk_source }, thunk_type) orelse
            boxyLowerInvariant("generated " ++ what ++ " had no planned value thunk");
        return .{ .thunk_type = thunk_type, .contract_worker = contract_worker, .thunk_worker = thunk_worker };
    }

    /// Reserve an element's thunk and write result, after its value.
    fn generatedEncoderElementFrame(
        proc: *ProcBodyBuilder,
        thunk: anytype,
        value: ProcBodyBuilder.ExtractedTagPayloadLocal,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!EncoderElementFrame {
        const thunk_rep = proc.repForTypeRef(thunk.thunk_type);
        const thunk_local = try proc.addFrameLocalForRep(thunk_rep);
        const result = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(target_rep);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        return .{
            .state = state,
            .state_rep = state_rep,
            .contract_worker = thunk.contract_worker,
            .thunk_worker = thunk.thunk_worker,
            .value = value,
            .thunk_rep = thunk_rep,
            .thunk = thunk_local,
            .result = result,
            .ok = ok,
            .ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok),
        };
    }

    fn lowerGeneratedEncoderSequenceElementsFrom(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        items: []const GeneratedParserTupleItem,
        first_item_index: usize,
        sequence_value: LIR.LocalId,
        first_state: LIR.LocalId,
        first_state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var frames: std.ArrayList(EncoderElementFrame) = .empty;
        defer frames.deinit(self.allocator);
        var state = first_state;
        var state_rep = first_state_rep;
        for (items[first_item_index..]) |item| {
            const thunk = self.generatedEncoderElementThunk(proc, source, item.source_type, element_writer_rep, "encoder element");
            const item_value = try proc.addFrameLocalForRep(item.rep);
            const frame = try generatedEncoderElementFrame(proc, thunk, .{ .local = item_value }, state, state_rep, target_rep);
            try frames.append(self.allocator, frame);
            state = frame.ok_payload.local;
            state_rep = frame.ok_payload.child.rep;
        }

        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const payloads = self.plan.childSlice(ok.variant.payloads);
        if (payloads.len != 1) boxyLowerInvariant("generated sequence encoder Ok did not have one state payload");
        var encoded = try proc.assignGeneratedParserTag(target, target_rep, ok, state, state_rep, next);

        var offset = frames.items.len;
        while (offset > 0) {
            offset -= 1;
            const frame = frames.items[offset];
            const continuation = try self.finishGeneratedEncoderElement(proc, frame, element_writer, element_writer_rep, target_rep, target, next, encoded);
            const item_index = first_item_index + offset;
            if (item_index > std.math.maxInt(u32)) {
                boxyLowerInvariant("generated encoder tuple element index exceeded LIR range");
            }
            encoded = try proc.lowerTupleFieldReadInto(
                frame.value.local,
                sequence_value,
                proc.repForTypeRef(source.shape),
                @intCast(item_index),
                continuation,
            );
        }
        return encoded;
    }

    fn lowerGeneratedEncoderTagPayloadElementsFrom(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        variant: GeneratedParserTagVariant,
        payloads: []const Plan.RepChild,
        first_payload_index: usize,
        tag_value: LIR.LocalId,
        first_state: LIR.LocalId,
        first_state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var frames: std.ArrayList(EncoderElementFrame) = .empty;
        defer frames.deinit(self.allocator);
        var state = first_state;
        var state_rep = first_state_rep;
        const tag_rep_plan = self.plan.representations.items[@backingInt(variant.tag_rep)];
        for (payloads[first_payload_index..]) |payload| {
            const thunk = self.generatedEncoderElementThunk(proc, source, payload.source_type, element_writer_rep, "tag payload element");
            const extracted = try proc.addExtractedTagPayloadLocal(payload.rep, tag_rep_plan.descriptor != null);
            const frame = try generatedEncoderElementFrame(proc, thunk, extracted, state, state_rep, target_rep);
            try frames.append(self.allocator, frame);
            state = frame.ok_payload.local;
            state_rep = frame.ok_payload.child.rep;
        }

        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payloads = self.plan.childSlice(ok.variant.payloads);
        if (ok_payloads.len != 1) boxyLowerInvariant("generated tag element encoder Ok did not have one state payload");
        var encoded = try proc.assignGeneratedParserTag(target, target_rep, ok, state, state_rep, next);

        var offset = frames.items.len;
        while (offset > 0) {
            offset -= 1;
            const frame = frames.items[offset];
            const payload_index = first_payload_index + offset;
            const continuation = try self.finishGeneratedEncoderElement(proc, frame, element_writer, element_writer_rep, target_rep, target, next, encoded);
            encoded = try proc.assignConcreteTagPayloadRead(
                frame.value.local,
                payloads[payload_index].rep,
                frame.value.desc_local,
                tag_value,
                variant.tag_rep,
                variant.variant.name,
                variant.index,
                @intCast(payload_index),
                payloads.len,
                continuation,
            );
        }
        return encoded;
    }

    fn lowerGeneratedEncoderListElementsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        list_rep: Plan.TypeRepId,
        list_value: LIR.LocalId,
        initial_state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const elem = proc.repQuery().requiredSingleChild(list_rep, .list_elem);
        const len = try proc.addFrameLocal(.u64);
        const index = try proc.addFrameLocal(.u64);
        const state = try proc.addFrameLocal(self.result.store.getLocal(initial_state).layout_idx);
        const zero = try proc.addFrameLocal(.u64);
        const join_id = proc.freshJoinPointId();
        const body = try self.lowerGeneratedEncoderListLoop(
            proc,
            source,
            elem,
            list_value,
            len,
            index,
            state,
            state_rep,
            element_writer,
            element_writer_rep,
            target_rep,
            target,
            join_id,
            next,
        );
        var initial = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        initial = try proc.setLocalInitializeJoinParamFromRep(state, initial_state, state_rep, initial);
        initial = try proc.setLocalInitializeJoinParam(index, zero, initial);
        initial = try proc.assignIntLiteral(zero, 0, initial);
        initial = try proc.assignUnaryLowLevel(len, .list_len, list_value, initial);
        return try self.result.store.addCFStmt(.{ .join = .{
            .id = join_id,
            .params = try proc.joinParamSpan(&.{ index, state }),
            .body = body,
            .remainder = initial,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedEncoderListLoop(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        elem: Plan.RepChild,
        list_value: LIR.LocalId,
        len: LIR.LocalId,
        index: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const done = try proc.addFrameLocal(.bool);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payloads = self.plan.childSlice(ok.variant.payloads);
        if (ok_payloads.len != 1) boxyLowerInvariant("generated list encoder Ok did not have one state payload");
        const finish = try proc.assignGeneratedParserTag(target, target_rep, ok, state, state_rep, next);
        const step = try self.lowerGeneratedEncoderListStep(
            proc,
            source,
            elem,
            list_value,
            index,
            state,
            state_rep,
            element_writer,
            element_writer_rep,
            target_rep,
            target,
            join_id,
            next,
        );
        const choose = try proc.boolSwitchNoContinuation(done, finish, step);
        return try proc.assignBinaryLowLevel(done, .num_is_eq, index, len, choose);
    }

    fn lowerGeneratedEncoderListStep(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        elem: Plan.RepChild,
        list_value: LIR.LocalId,
        index: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const writer_fn = proc.functionChildrenForRep(element_writer_rep) orelse
            boxyLowerInvariant("generated list element writer was not callable");
        const writer_children = self.plan.childSlice(self.plan.representations.items[@backingInt(writer_fn.rep)].children);
        const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
        if (writer_args.len != 2) boxyLowerInvariant("generated list element writer had an unexpected arity");
        const thunk_type = writer_args[1].source_type;
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated list element callback had no contract worker");
        const thunk_source = Plan.GeneratedCodecSource{
            .kind = .encoder_value_thunk,
            .shape = elem.source_type,
            .capture_type = source.capture_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = thunk_source }, thunk_type) orelse
            boxyLowerInvariant("generated list element had no planned value thunk");
        const elem_value = try proc.addFrameLocalForRep(elem.rep);
        const thunk_rep = proc.repForTypeRef(thunk_type);
        const thunk = try proc.addFrameLocalForRep(thunk_rep);
        const result = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(target_rep);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
        const one = try proc.addFrameLocal(.u64);
        const next_index = try proc.addFrameLocal(.u64);

        var success = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        success = try proc.setLocalInitializeJoinParamFromRep(state, ok_payload.local, ok_payload.child.rep, success);
        success = try proc.setLocalInitializeJoinParam(index, next_index, success);
        success = try proc.generatedParserReadTagPayload(result, ok, ok_payload, success);
        const err = try proc.assignRepresentationBoundary(target, result, target_rep, target_rep, next);
        const variants = [_]GeneratedParserTagVariant{ok};
        const bodies = [_]LIR.CFStmtId{success};
        var continuation = try proc.generatedParserTagDispatch(result, target_rep, &variants, &bodies, err);
        continuation = try proc.lowerErasedCallLocalsInto(
            result,
            target_rep,
            element_writer_rep,
            element_writer,
            &.{ state, thunk },
            &.{ state_rep, thunk_rep },
            continuation,
        );
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = elem_value;
        @memcpy(capture_values[2..], name_captures);
        continuation = try self.packGeneratedCodecCallable(proc, thunk, thunk_rep, thunk_worker, capture_values, continuation);
        continuation = try proc.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, continuation);
        continuation = try proc.assignIntLiteral(one, 1, continuation);
        if (!proc.isZstLocal(elem_value)) {
            continuation = try proc.assignBinaryLowLevel(elem_value, .list_get_unsafe, list_value, index, continuation);
        }
        return continuation;
    }

    fn lowerGeneratedEncoderDictFieldsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated Dict field callback was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated Dict field callback had invalid arguments or captures");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];
        const list_rep = proc.listRepForBoundary(proc.repForTypeRef(source.shape)) orelse
            boxyLowerInvariant("generated Dict field callback capture was not a List");
        const entry = proc.repQuery().requiredSingleChild(list_rep, .list_elem);
        const entry_items = try self.generatedParserTupleItems(proc, entry.rep);
        defer self.allocator.free(entry_items);
        if (entry_items.len != 2) boxyLowerInvariant("generated Dict entry did not have key and value elements");

        const entries = proc.erased_capture_locals.items[1];
        const len = try proc.addFrameLocal(.u64);
        const index = try proc.addFrameLocal(.u64);
        const state = try proc.addFrameLocal(self.result.store.getLocal(proc.arg_locals.items[0]).layout_idx);
        const zero = try proc.addFrameLocal(.u64);
        const join_id = proc.freshJoinPointId();
        const body = try self.lowerGeneratedEncoderDictLoop(
            proc,
            source,
            entry,
            entry_items,
            entries,
            len,
            index,
            state,
            args[0].rep,
            proc.arg_locals.items[1],
            args[1].rep,
            function.ret,
            target,
            join_id,
            next,
        );
        var initial = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        initial = try proc.setLocalInitializeJoinParamFromRep(state, proc.arg_locals.items[0], args[0].rep, initial);
        initial = try proc.setLocalInitializeJoinParam(index, zero, initial);
        initial = try proc.assignIntLiteral(zero, 0, initial);
        initial = try proc.assignUnaryLowLevel(len, .list_len, entries, initial);
        return try self.result.store.addCFStmt(.{ .join = .{
            .id = join_id,
            .params = try proc.joinParamSpan(&.{ index, state }),
            .body = body,
            .remainder = initial,
        } }, proc.derivedOrigin());
    }

    fn lowerGeneratedEncoderDictLoop(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        entry: Plan.RepChild,
        entry_items: []const GeneratedParserTupleItem,
        entries: LIR.LocalId,
        len: LIR.LocalId,
        index: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        field_writer: LIR.LocalId,
        field_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const done = try proc.addFrameLocal(.bool);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payloads = self.plan.childSlice(ok.variant.payloads);
        if (ok_payloads.len != 1) boxyLowerInvariant("generated Dict encoder Ok did not have one state payload");
        const finish = try proc.assignGeneratedParserTag(target, target_rep, ok, state, state_rep, next);
        const step = try self.lowerGeneratedEncoderDictStep(
            proc,
            source,
            entry,
            entry_items,
            entries,
            index,
            state,
            state_rep,
            field_writer,
            field_writer_rep,
            target_rep,
            target,
            join_id,
            next,
        );
        const choose = try proc.boolSwitchNoContinuation(done, finish, step);
        return try proc.assignBinaryLowLevel(done, .num_is_eq, index, len, choose);
    }

    fn lowerGeneratedEncoderDictStep(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        entry: Plan.RepChild,
        entry_items: []const GeneratedParserTupleItem,
        entries: LIR.LocalId,
        index: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        field_writer: LIR.LocalId,
        field_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const writer_fn = proc.functionChildrenForRep(field_writer_rep) orelse
            boxyLowerInvariant("generated Dict entry writer was not callable");
        const writer_children = self.plan.childSlice(self.plan.representations.items[@backingInt(writer_fn.rep)].children);
        const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
        if (writer_args.len != 3) boxyLowerInvariant("generated Dict entry writer had an unexpected arity");
        const key_thunk_type = writer_args[1].source_type;
        const value_thunk_type = writer_args[2].source_type;
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated Dict entry callback had no contract worker");
        const key_item = entry_items[0];
        const value_item = entry_items[1];
        const key_thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = .{
            .kind = .encoder_dict_key_thunk,
            .shape = key_item.source_type,
            .capture_type = source.capture_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        } }, key_thunk_type) orelse
            boxyLowerInvariant("generated Dict key had no planned key writer");
        const value_thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = .{
            .kind = .encoder_value_thunk,
            .shape = value_item.source_type,
            .capture_type = source.capture_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        } }, value_thunk_type) orelse
            boxyLowerInvariant("generated Dict value had no planned encoder thunk");
        const entry_value = try proc.addFrameLocalForRep(entry.rep);
        const key_value = try proc.addFrameLocalForRep(key_item.rep);
        const item_value = try proc.addFrameLocalForRep(value_item.rep);
        const key_thunk_rep = proc.repForTypeRef(key_thunk_type);
        const key_thunk = try proc.addFrameLocalForRep(key_thunk_rep);
        const value_thunk_rep = proc.repForTypeRef(value_thunk_type);
        const value_thunk = try proc.addFrameLocalForRep(value_thunk_rep);
        const entry_result = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(target_rep);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
        const one = try proc.addFrameLocal(.u64);
        const next_index = try proc.addFrameLocal(.u64);

        var entry_success = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        entry_success = try proc.setLocalInitializeJoinParamFromRep(state, ok_payload.local, ok_payload.child.rep, entry_success);
        entry_success = try proc.setLocalInitializeJoinParam(index, next_index, entry_success);
        entry_success = try proc.generatedParserReadTagPayload(entry_result, ok, ok_payload, entry_success);
        const entry_err = try proc.assignRepresentationBoundary(target, entry_result, target_rep, target_rep, next);
        const entry_variants = [_]GeneratedParserTagVariant{ok};
        const entry_bodies = [_]LIR.CFStmtId{entry_success};
        var write_entry = try proc.generatedParserTagDispatch(
            entry_result,
            target_rep,
            &entry_variants,
            &entry_bodies,
            entry_err,
        );
        write_entry = try proc.lowerErasedCallLocalsInto(
            entry_result,
            target_rep,
            field_writer_rep,
            field_writer,
            &.{ state, key_thunk, value_thunk },
            &.{ state_rep, key_thunk_rep, value_thunk_rep },
            write_entry,
        );
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        @memcpy(capture_values[2..], name_captures);
        capture_values[1] = item_value;
        write_entry = try self.packGeneratedCodecCallable(proc, value_thunk, value_thunk_rep, value_thunk_worker, capture_values, write_entry);
        capture_values[1] = key_value;
        write_entry = try self.packGeneratedCodecCallable(proc, key_thunk, key_thunk_rep, key_thunk_worker, capture_values, write_entry);
        write_entry = try proc.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, write_entry);
        write_entry = try proc.assignIntLiteral(one, 1, write_entry);
        write_entry = try proc.lowerTupleFieldReadInto(item_value, entry_value, entry.rep, 1, write_entry);
        write_entry = try proc.lowerTupleFieldReadInto(key_value, entry_value, entry.rep, 0, write_entry);
        if (!proc.isZstLocal(entry_value)) {
            write_entry = try proc.assignBinaryLowLevel(entry_value, .list_get_unsafe, entries, index, write_entry);
        }
        return write_entry;
    }

    /// Write one dict key with the key protocol the checker validated for
    /// it: a scalar key method, a unit tag's name through `encode_key_str`,
    /// or `encode_key_start` followed by the key's own encoder.
    fn lowerGeneratedEncoderDictKeyThunkInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated Dict key writer was not callable");
        if (function.arg_count != 1 or proc.arg_locals.items.len < 1 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated Dict key writer did not bind encoding, key, and state");
        }
        const caller = proc.worker_layout.worker;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated Dict key writer had no encoding type");
        const encoding = proc.erased_capture_locals.items[0];
        const key_value = proc.erased_capture_locals.items[1];
        const state = proc.arg_locals.items[0];
        const key_type = source.shape;

        if (generatedEncoderKeyMethodForType(
            procedureModuleById(self.modules, key_type.module),
            key_type.ty,
        )) |method_text| {
            const call = proc.generatedCodecCallPlan(caller, encoding_type, method_text, key_type);
            return try self.lowerGeneratedCodecCallLocalsInto(proc, call, target, &.{ encoding, key_value, state }, next);
        }

        if (proc.generatedCodecCallPlanOrNull(caller, encoding_type, "encode_key_start", key_type)) |start_call| {
            const opened_rep = proc.repForTypeRef(start_call.ret_type);
            const opened = try proc.addFrameLocalForRep(opened_rep);
            const ok = proc.generatedParserTagVariant(opened_rep, "Ok");
            const err = proc.generatedParserTagVariant(opened_rep, "Err");
            const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
            var ok_body = try self.lowerGeneratedEncoderShapeInto(proc, source, key_type, key_value, ok_payload.local, target, next);
            ok_body = try proc.generatedParserReadTagPayload(opened, ok, ok_payload, ok_body);
            const err_body = try proc.forwardGeneratedParserError(target, function.ret, opened, err, next);
            const variants = [_]GeneratedParserTagVariant{ ok, err };
            const bodies = [_]LIR.CFStmtId{ ok_body, err_body };
            const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
            const dispatch = try proc.generatedParserTagDispatch(opened, opened_rep, &variants, &bodies, impossible);
            return try self.lowerGeneratedCodecCallLocalsInto(proc, start_call, opened, &.{ encoding, state }, dispatch);
        }

        const str_call = proc.generatedCodecCallPlanForMethod(caller, encoding_type, "encode_key_str");
        const key_str = try proc.addFrameLocal(.str);
        const write_key = try self.lowerGeneratedCodecCallLocalsInto(proc, str_call, target, &.{ encoding, key_str, state }, next);
        const variants = try self.generatedEncoderTagVariants(proc, key_type, false);
        defer self.allocator.free(variants);
        const bodies = try self.allocator.alloc(LIR.CFStmtId, variants.len);
        defer self.allocator.free(bodies);
        for (variants, bodies) |variant, *body| {
            if (self.plan.childSlice(variant.variant.payloads).len != 0) {
                boxyLowerInvariant("generated Dict tag key carried a payload");
            }
            body.* = try proc.assignStringBytesLiteral(key_str, proc.tagVariantNameText(variant.variant), write_key);
        }
        return try self.lowerGeneratedEncoderTagDispatch(proc, key_value, variants, bodies);
    }

    fn lowerGeneratedEncoderTagPayloadElementsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated tag payload element callback was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated tag payload element callback had invalid arguments or captures");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];
        const variants = try self.generatedEncoderTagVariants(proc, source.shape, false);
        defer self.allocator.free(variants);
        const bodies = try self.allocator.alloc(LIR.CFStmtId, variants.len);
        defer self.allocator.free(bodies);
        for (variants, bodies) |variant, *body| {
            body.* = try self.lowerGeneratedEncoderTagPayloadElementsFrom(
                proc,
                source,
                variant,
                self.plan.childSlice(variant.variant.payloads),
                0,
                proc.erased_capture_locals.items[1],
                proc.arg_locals.items[0],
                args[0].rep,
                proc.arg_locals.items[1],
                args[1].rep,
                function.ret,
                target,
                next,
            );
        }
        return try self.lowerGeneratedEncoderTagDispatch(
            proc,
            proc.erased_capture_locals.items[1],
            variants,
            bodies,
        );
    }

    fn lowerGeneratedParserRuntimeInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker_id = proc.worker_layout.worker;
        const schema_type = self.plan.generatedParserRuntimeSchema(worker_id) orelse
            boxyLowerInvariant("generated parser runtime had no planned schema type");
        const shape_rep = proc.repForTypeRef(schema_type);
        var schema_source = source;
        schema_source.shape = schema_type;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated parser runtime had no encoding capture type");
        if (generatedCodecScalarMethodForRep(self.plan, shape_rep, "parse_")) |method_text| {
            return try self.lowerGeneratedScalarParserRuntimeInto(
                proc,
                worker_id,
                schema_type,
                encoding_type,
                method_text,
                target,
                next,
            );
        }
        if (proc.recordRepForBoundary(shape_rep) != null or
            self.plan.representations.items[@backingInt(shape_rep)].kind == .empty_record)
        {
            return try self.lowerGeneratedRecordParserRuntimeInto(
                proc,
                schema_source,
                encoding_type,
                target,
                next,
            );
        }
        return try self.lowerGeneratedTupleParserRuntimeInto(
            proc,
            schema_source,
            encoding_type,
            target,
            next,
        );
    }

    fn lowerGeneratedScalarParserRuntimeInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        shape_type: Plan.CheckedTypeIdentity,
        encoding_type: Plan.CheckedTypeIdentity,
        method_text: []const u8,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const call = proc.generatedCodecCallPlan(worker_id, encoding_type, method_text, shape_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 2 or proc.arg_locals.items.len < 1 or proc.erased_capture_locals.items.len < 1) {
            boxyLowerInvariant("generated scalar parser call had unexpected argument or capture arity");
        }

        return try proc.lowerWorkerCallLocalsInto(
            target,
            call.ret_type,
            arg_types,
            arg_types,
            &.{ proc.erased_capture_locals.items[0], proc.arg_locals.items[0] },
            null,
            null,
            null,
            call.worker,
            self.plan.directCallHiddenDescriptorArgSlice(call.hidden_desc_args),
            self.plan.directCallHiddenDictionaryArgSlice(call.hidden_dict_args),
            next,
        );
    }

    const GeneratedParserShapeContext = struct {
        worker: Plan.WorkerPlanId,
        encoding_type: Plan.CheckedTypeIdentity,
        encoding: LIR.LocalId,
        state_type: Plan.CheckedTypeIdentity,
        state_rep: Plan.TypeRepId,
        result: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
        tag_union_spec: ?LIR.LocalId = null,
        tag_union_spec_rep: ?Plan.TypeRepId = null,
        tag_union_plan: ?Plan.GeneratedParserTagUnionPlan = null,
    };

    const GeneratedParserTupleItem = struct {
        source_type: Plan.CheckedTypeIdentity,
        rep: Plan.TypeRepId,
        value: LIR.LocalId,
    };

    fn lowerGeneratedTupleParserRuntimeInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        encoding_type: Plan.CheckedTypeIdentity,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = proc.worker_layout.worker;
        const worker_plan = self.plan.workers.items[@backingInt(worker)];
        const worker_fn = proc.functionChildrenForRep(worker_plan.rep) orelse
            boxyLowerInvariant("generated tuple parser worker was not a function");
        if (worker_fn.arg_count != 1 or proc.arg_locals.items.len < 1 or proc.erased_capture_locals.items.len < 1) {
            boxyLowerInvariant("generated tuple parser had unexpected argument or capture metadata");
        }
        const worker_children = self.plan.childSlice(
            self.plan.representations.items[@backingInt(worker_fn.rep)].children,
        );
        const state_child = worker_children[worker_fn.args_start];

        const shape_rep = proc.repForTypeRef(source.shape);
        const state_type = state_child.source_type;
        const state_rep = proc.repForTypeRef(state_type);
        const value = try proc.addGeneratedParserOutputLocalForRep(shape_rep);
        const rest = try proc.addGeneratedParserOutputLocalForRep(state_rep);
        const context = GeneratedParserShapeContext{
            .worker = worker,
            .encoding_type = encoding_type,
            .encoding = proc.erased_capture_locals.items[0],
            .state_type = state_type,
            .state_rep = state_rep,
            .result = target,
            .result_rep = worker_fn.ret,
            .next = next,
        };
        const success = try self.lowerGeneratedParserSuccess(proc, context, value, shape_rep, rest);
        return try self.lowerGeneratedParseShapeFromState(
            proc,
            context,
            source.shape,
            shape_rep,
            proc.arg_locals.items[0],
            value,
            rest,
            success,
        );
    }

    fn lowerGeneratedParserSuccess(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        value: LIR.LocalId,
        value_rep: Plan.TypeRepId,
        rest: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        try proc.ensureGeneratedParserOutputDescriptorForRep(value, value_rep);
        try proc.ensureGeneratedParserOutputDescriptorForRep(rest, context.state_rep);
        const ok = proc.generatedParserTagVariant(context.result_rep, "Ok");
        const payloads = self.plan.childSlice(ok.variant.payloads);
        if (payloads.len != 1) boxyLowerInvariant("generated parser final Ok did not have one payload");
        // `Try`'s declared `Ok` payload is its formal `ok`; the record is
        // built at this result's actual `{ value, rest }` representation.
        const record_rep = proc.nominalBackingActualRep(context.result_rep, payloads[0].rep);
        const result_record = try proc.addFrameLocalForRep(record_rep);
        const continuation = try proc.assignGeneratedParserTag(
            context.result,
            context.result_rep,
            ok,
            result_record,
            record_rep,
            context.next,
        );
        return try proc.assignGeneratedParserTwoFieldRecord(
            result_record,
            record_rep,
            "value",
            value,
            value_rep,
            "rest",
            rest,
            context.state_rep,
            continuation,
        );
    }

    /// One nested parser shape: parse `shape_type` from `state` into `value`,
    /// leaving the state after it in `rest`, then continue with `success`.
    const ParseShapeRequest = struct {
        context: GeneratedParserShapeContext,
        shape_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        state: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
    };

    const ParseShapeStep = union(enum) {
        /// The shape whose parser the top frame receives next.
        request: ParseShapeRequest,
        /// A frame was pushed and has not yet run.
        pushed,
        /// The statement the top frame receives next, or the whole parser
        /// when no frame is left.
        done: LIR.CFStmtId,
    };

    /// A parser waiting on its nested shapes' parsers.
    const ParseShapeFrame = struct {
        /// Whether the frame's last requested parser is still due.
        awaiting: bool = false,
        state: union(enum) {
            try_shape: GeneratedTryParseState,
            tuple: GeneratedTupleParseState,
            list: GeneratedListParseState,
            dict: GeneratedDictParseState,
            dict_entry: GeneratedDictEntryParseState,
            record: GeneratedRecordParseState,
        },
    };

    /// A `Try` parsed as `Null` or its `Ok` shape.
    const GeneratedTryParseState = struct {
        context: GeneratedParserShapeContext,
        call: Plan.GeneratedCodecCallPlan,
        state: LIR.LocalId,
        parsed: LIR.LocalId,
        parsed_rep: Plan.TypeRepId,
        null_ok: GeneratedParserTagVariant,
        null_err: GeneratedParserTagVariant,
        null_body: LIR.CFStmtId,
        ok: ParseShapeRequest,
    };

    /// A tuple's elements parsed last first.
    const GeneratedTupleParseState = struct {
        request: ParseShapeRequest,
        items: []GeneratedParserTupleItem,
        parsed_rests: []LIR.LocalId,
        separators: []GeneratedParserTryCall,
        start: GeneratedParserTryCall,
        len: LIR.LocalId,
        /// The element being parsed; the elements after it are done.
        remaining: usize,
        current: LIR.CFStmtId,
        item_state: LIR.LocalId = undefined,
    };

    /// A list parsed by a loop whose counted and uncounted steps each parse
    /// one element.
    const GeneratedListParseState = struct {
        context: GeneratedParserShapeContext,
        subject_type: Plan.CheckedTypeIdentity,
        state: LIR.LocalId,
        target_desc: ProcBodyBuilder.ResultDescriptorSource,
        loop: GeneratedListLoop,
        phase: enum { counted, uncounted },
        counted_element: ParseShapeRequest,
        counted_done: LIR.CFStmtId,
        counted_step: LIR.CFStmtId = undefined,
        uncounted: struct {
            call: Plan.GeneratedCodecCallPlan,
            step_rep: Plan.TypeRepId,
            step: LIR.LocalId,
            ok: GeneratedParserTagVariant,
            err: GeneratedParserTagVariant,
            err_body: LIR.CFStmtId,
            ok_payload: ProcBodyBuilder.GeneratedParserTagPayload,
            element: GeneratedParserTagVariant,
            done: GeneratedParserTagVariant,
            element_payload: ProcBodyBuilder.GeneratedParserTagPayload,
        } = undefined,
    };

    /// A dictionary parsed by a loop whose counted and uncounted steps each
    /// parse one entry.
    const GeneratedDictParseState = struct {
        context: GeneratedParserShapeContext,
        state: LIR.LocalId,
        shape_type: Plan.CheckedTypeIdentity,
        loop: GeneratedDictLoop,
        phase: enum { counted, uncounted },
        counted_done: LIR.CFStmtId,
        counted_step: LIR.CFStmtId = undefined,
        uncounted: struct {
            next: GeneratedParserTryCall,
            entry_variant: GeneratedParserTagVariant,
            done_variant: GeneratedParserTagVariant,
            entry_payload: ProcBodyBuilder.GeneratedParserTagPayload,
            done_payload: ProcBodyBuilder.GeneratedParserTagPayload,
            entry_state: LIR.LocalId,
        } = undefined,
    };

    /// One dictionary entry: its value parsed, then its key.
    const GeneratedDictEntryParseState = struct {
        context: GeneratedParserShapeContext,
        loop: GeneratedDictLoop,
        entry_state: LIR.LocalId,
        key: LIR.LocalId,
        after_key: LIR.LocalId,
        phase: enum { value, key },
        value: ParseShapeRequest,
        key_start: GeneratedParserTryCall = undefined,
        key_state: LIR.LocalId = undefined,
    };

    /// A record parsed by a loop whose field events each select one matched
    /// field. Each field's value parser is built once, in its own join whose
    /// parameter is the state after the field's key; the `Field`, `TryField`,
    /// and `TryFieldCaseless` events jump to it. Every error inside the loop
    /// writes the parser result into `context.target` and jumps to
    /// `error_join`, which retains the field names and payload slots and
    /// forwards that result to `shape_context`.
    const GeneratedRecordParseState = struct {
        shape_context: GeneratedParserShapeContext,
        error_join: LIR.JoinPointId,
        state: LIR.LocalId,
        field_names_source: GeneratedParserFieldNamesSource,
        parse_call: Plan.GeneratedCodecCallPlan,
        context: GeneratedParserRecordContext,
        step_join: LIR.JoinPointId,
        step: GeneratedParserTryCall,
        variants: [5]GeneratedParserTagVariant,
        bodies: [5]LIR.CFStmtId,
        /// The field whose value parser is being built.
        field_cursor: usize = 0,
        field_joins: []LIR.JoinPointId,
        /// Each field join's parameter: the state its value parser starts at.
        field_states: []LIR.LocalId,
        field_bodies: []LIR.CFStmtId,
    };

    fn lowerGeneratedParseShapeFromState(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        shape_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        state: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var frames: std.ArrayList(ParseShapeFrame) = .empty;
        defer self.releaseParseShapeFrames(&frames);
        const first = try self.beginParseShape(proc, &frames, .{
            .context = context,
            .shape_type = shape_type,
            .shape_rep = shape_rep,
            .state = state,
            .value = value,
            .rest = rest,
            .success = success,
        });
        return try self.runParseShapeFrames(proc, &frames, first);
    }

    fn lowerGeneratedRecordFromState(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_context: GeneratedParserShapeContext,
        shape_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        state: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
        field_names_source: GeneratedParserFieldNamesSource,
    ) Allocator.Error!LIR.CFStmtId {
        var frames: std.ArrayList(ParseShapeFrame) = .empty;
        defer self.releaseParseShapeFrames(&frames);
        const first = try self.beginGeneratedRecordParse(proc, &frames, shape_context, shape_type, shape_rep, state, value, rest, success, field_names_source);
        return try self.runParseShapeFrames(proc, &frames, first);
    }

    fn runParseShapeFrames(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        first: ParseShapeStep,
    ) Allocator.Error!LIR.CFStmtId {
        var step = first;
        while (true) {
            switch (step) {
                .request => |request| step = try self.beginParseShape(proc, frames, request),
                .pushed => step = try self.stepParseShapeFrame(proc, frames, null),
                .done => |stmt| {
                    if (frames.items.len == 0) return stmt;
                    step = try self.stepParseShapeFrame(proc, frames, stmt);
                },
            }
        }
    }

    fn releaseParseShapeFrames(self: *ProcedureBuilder, frames: *std.ArrayList(ParseShapeFrame)) void {
        var index = frames.items.len;
        while (index > 0) {
            index -= 1;
            self.releaseParseShapeFrame(&frames.items[index]);
        }
        frames.deinit(self.allocator);
    }

    /// Free what an unfinished frame owns, as the direct build's defers
    /// would.
    fn releaseParseShapeFrame(self: *ProcedureBuilder, frame: *ParseShapeFrame) void {
        switch (frame.state) {
            .try_shape, .list, .dict, .dict_entry => {},
            .tuple => |state| {
                self.allocator.free(state.items);
                self.allocator.free(state.parsed_rests);
                self.allocator.free(state.separators);
            },
            .record => |state| {
                self.allocator.free(state.context.fields);
                self.allocator.free(state.context.presence);
                self.allocator.free(state.field_joins);
                self.allocator.free(state.field_states);
                self.allocator.free(state.field_bodies);
            },
        }
    }

    fn pushParseShapeFrame(self: *ProcedureBuilder, frames: *std.ArrayList(ParseShapeFrame), frame: ParseShapeFrame) Allocator.Error!ParseShapeStep {
        var owned = frame;
        frames.append(self.allocator, owned) catch |err| {
            self.releaseParseShapeFrame(&owned);
            return err;
        };
        return .pushed;
    }

    fn finishParseShapeFrame(self: *ProcedureBuilder, frames: *std.ArrayList(ParseShapeFrame), stmt: LIR.CFStmtId) ParseShapeStep {
        var frame = frames.pop().?;
        self.releaseParseShapeFrame(&frame);
        return .{ .done = stmt };
    }

    fn beginParseShape(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        root: ParseShapeRequest,
    ) Allocator.Error!ParseShapeStep {
        var request = root;
        while (true) {
            const context = request.context;
            const shape_type = request.shape_type;
            const shape_rep = request.shape_rep;
            const state = request.state;
            const value = request.value;
            const rest = request.rest;
            const success = request.success;
            try proc.ensureGeneratedParserOutputDescriptorForRep(value, shape_rep);
            try proc.ensureGeneratedParserOutputDescriptorForRep(rest, context.state_rep);
            const shape_module = procedureModuleById(self.modules, shape_type.module);
            // An alias parses as its backing, which is the shape the planner
            // walked and every planned call names.
            switch (shape_module.checked_types.payload(shape_type.ty)) {
                .alias => |alias| {
                    const backing_type = Plan.CheckedTypeIdentity{ .module = shape_type.module, .ty = alias.backing };
                    request.shape_type = backing_type;
                    request.shape_rep = proc.repForTypeRef(backing_type);
                    continue;
                },
                .pending, .err, .flex, .rigid, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => {},
            }
            if (checkedBuiltinNominalForType(shape_module, shape_type.ty) == .box) {
                const payload = proc.repQuery().requiredSingleChild(shape_rep, .box_payload);
                const payload_value = try proc.addGeneratedParserOutputLocalForRep(payload.rep);
                const construct = try proc.assignBoxBoundary(
                    value,
                    payload_value,
                    shape_rep,
                    .box_box,
                    success,
                );
                request.shape_type = payload.source_type;
                request.shape_rep = payload.rep;
                request.value = payload_value;
                request.success = construct;
                continue;
            }

            if (self.plan.generatedParserTryPlan(context.worker, shape_type)) |try_plan| {
                return try self.beginGeneratedTryParse(proc, frames, request, try_plan);
            }

            const constructor_call = proc.generatedCodecCallPlanOrNull(
                context.worker,
                shape_type,
                base.Ident.PARSER_FOR_METHOD_NAME,
                shape_type,
            );
            const scalar_call = if (constructor_call == null) blk: {
                const method = generatedCodecScalarMethodForRep(self.plan, shape_rep, "parse_") orelse break :blk null;
                break :blk proc.generatedCodecCallPlan(context.worker, context.encoding_type, method, shape_type);
            } else null;
            if (constructor_call != null or scalar_call != null) {
                const parsed_rep = if (constructor_call) |call| blk: {
                    const callable_rep = proc.repForTypeRef(call.ret_type);
                    const callable_fn = proc.functionChildrenForRep(callable_rep) orelse
                        boxyLowerInvariant("generated custom parser constructor did not return a callable");
                    if (callable_fn.arg_count != 1) {
                        boxyLowerInvariant("generated custom parser runtime had an unexpected arity");
                    }
                    break :blk callable_fn.ret;
                } else proc.repForTypeRef(scalar_call.?.ret_type);
                const parsed = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(parsed_rep);
                const ok = proc.generatedParserTagVariant(parsed_rep, "Ok");
                const err = proc.generatedParserTagVariant(parsed_rep, "Err");
                const err_body = try proc.forwardGeneratedParserError(
                    context.result,
                    context.result_rep,
                    parsed,
                    err,
                    context.next,
                );
                const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
                var parsed_success = try proc.generatedParserReadRecordField(
                    rest,
                    context.state_rep,
                    ok_payload.local,
                    ok_payload.child,
                    "rest",
                    success,
                );
                parsed_success = try proc.generatedParserReadRecordField(
                    value,
                    shape_rep,
                    ok_payload.local,
                    ok_payload.child,
                    "value",
                    parsed_success,
                );
                parsed_success = try proc.generatedParserReadTagPayload(parsed, ok, ok_payload, parsed_success);
                const variants = [_]GeneratedParserTagVariant{ ok, err };
                const bodies = [_]LIR.CFStmtId{ parsed_success, err_body };
                const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                const dispatch = try proc.generatedParserTagDispatch(parsed, parsed_rep, &variants, &bodies, impossible);
                if (constructor_call) |call| {
                    const callable_rep = proc.repForTypeRef(call.ret_type);
                    const callable = try proc.addFrameLocalForRep(callable_rep);
                    var continuation = try proc.lowerErasedCallLocalsInto(
                        parsed,
                        parsed_rep,
                        callable_rep,
                        callable,
                        &.{state},
                        &.{context.state_rep},
                        dispatch,
                    );
                    continuation = try self.lowerGeneratedCodecCallLocalsInto(
                        proc,
                        call,
                        callable,
                        &.{context.encoding},
                        continuation,
                    );
                    return .{ .done = continuation };
                }
                return .{ .done = try self.lowerGeneratedCodecCallLocalsInto(
                    proc,
                    scalar_call.?,
                    parsed,
                    &.{ context.encoding, state },
                    dispatch,
                ) };
            }

            const shape_builtin = checkedBuiltinNominalForType(shape_module, shape_type.ty);
            if (shape_builtin == .set) {
                return try self.beginGeneratedSetParse(proc, frames, request);
            }
            if (shape_builtin == .dict) {
                return try self.beginGeneratedDictParse(proc, frames, request);
            }

            if (proc.recordRepForBoundary(shape_rep) != null or
                self.plan.representations.items[@backingInt(shape_rep)].kind == .empty_record)
            {
                const field_names_source: GeneratedParserFieldNamesSource = if (context.tag_union_spec) |spec|
                    .{ .tag_union_spec = .{
                        .spec = spec,
                        .plan = context.tag_union_plan orelse
                            boxyLowerInvariant("generated tag payload record had no explicit evidence plan"),
                    } }
                else
                    .captures;
                return try self.beginGeneratedRecordParse(
                    proc,
                    frames,
                    context,
                    shape_type,
                    shape_rep,
                    state,
                    value,
                    rest,
                    success,
                    field_names_source,
                );
            }

            if (proc.tupleRepForBoundary(shape_rep) != null) {
                return try self.beginGeneratedTupleParse(proc, frames, request);
            }
            if (proc.listRepForBoundary(shape_rep) != null) {
                return try self.beginGeneratedListParse(proc, frames, context, shape_type, shape_rep, null, state, value, rest, success);
            }
            if (proc.tagVariantRepForBoundary(shape_rep) != null) {
                return .{ .done = try self.lowerGeneratedTagUnionFromState(
                    proc,
                    context,
                    shape_type,
                    shape_rep,
                    state,
                    value,
                    rest,
                    success,
                ) };
            }
            boxyLowerInvariant("generated parser nested shape body is not implemented");
        }
    }

    fn stepParseShapeFrame(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        delivered: ?LIR.CFStmtId,
    ) Allocator.Error!ParseShapeStep {
        // A dictionary frame pushes at most one entry frame per step, so the
        // top frame stays in place.
        try frames.ensureUnusedCapacity(self.allocator, 1);
        const frame = &frames.items[frames.items.len - 1];
        const child: ?LIR.CFStmtId = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("generated parser frame resumed without its nested parser")
        else if (delivered != null)
            boxyLowerInvariant("generated parser frame received a parser it did not request")
        else
            null;
        frame.awaiting = false;
        switch (frame.state) {
            .try_shape => |*state| {
                const child_body = child orelse {
                    frame.awaiting = true;
                    return .{ .request = state.ok };
                };
                const variants = [_]GeneratedParserTagVariant{ state.null_ok, state.null_err };
                const bodies = [_]LIR.CFStmtId{ state.null_body, child_body };
                const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                const dispatch = try proc.generatedParserTagDispatch(state.parsed, state.parsed_rep, &variants, &bodies, impossible);
                const stmt = try self.lowerGeneratedCodecCallLocalsInto(
                    proc,
                    state.call,
                    state.parsed,
                    &.{ state.context.encoding, state.state },
                    dispatch,
                );
                return self.finishParseShapeFrame(frames, stmt);
            },
            .tuple => |*state| {
                const context = state.request.context;
                if (child) |parsed| {
                    const index = state.remaining;
                    const boundary = if (index == 0) state.start else state.separators[index];
                    var continuation = try proc.assignRepresentationBoundary(state.item_state, boundary.ok_payload.local, context.state_rep, boundary.ok_payload.child.rep, parsed);
                    if (index != 0) {
                        const item_index = try proc.addFrameLocal(.u64);
                        continuation = try self.finishGeneratedParserTryCall(
                            proc,
                            state.separators[index],
                            &.{ context.encoding, state.parsed_rests[index - 1], item_index, state.len },
                            context.result,
                            context.result_rep,
                            context.next,
                            continuation,
                        );
                        continuation = try proc.assignIntLiteral(item_index, @intCast(index), continuation);
                    }
                    state.current = continuation;
                }
                if (state.remaining > 0) {
                    state.remaining -= 1;
                    const index = state.remaining;
                    state.item_state = try proc.addFrameLocalForRep(context.state_rep);
                    frame.awaiting = true;
                    return .{ .request = .{
                        .context = context,
                        .shape_type = state.items[index].source_type,
                        .shape_rep = state.items[index].rep,
                        .state = state.item_state,
                        .value = state.items[index].value,
                        .rest = state.parsed_rests[index],
                        .success = state.current,
                    } };
                }
                var continuation = try self.finishGeneratedParserTryCall(
                    proc,
                    state.start,
                    &.{ context.encoding, state.request.state, state.len },
                    context.result,
                    context.result_rep,
                    context.next,
                    state.current,
                );
                continuation = try proc.assignIntLiteral(state.len, @intCast(state.items.len), continuation);
                return self.finishParseShapeFrame(frames, continuation);
            },
            .list => |*state| switch (state.phase) {
                .counted => {
                    const element = child orelse {
                        frame.awaiting = true;
                        return .{ .request = state.counted_element };
                    };
                    const loop = state.loop;
                    const context = state.context;
                    const remaining_is_zero = try proc.addFrameLocal(.bool);
                    const zero = try proc.addFrameLocal(.u64);
                    var counted_step = try proc.boolSwitchNoContinuation(remaining_is_zero, state.counted_done, element);
                    counted_step = try proc.assignBinaryLowLevel(remaining_is_zero, .num_is_eq, loop.remaining, zero, counted_step);
                    state.counted_step = try proc.assignIntLiteral(zero, 0, counted_step);

                    // One step of an uncounted list: `parse_list_next` reports
                    // whether an item follows.
                    const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_list_next", loop.subject_type);
                    const step_rep = proc.repForTypeRef(call.ret_type);
                    const step = try proc.addFrameLocalForRep(step_rep);
                    const ok = proc.generatedParserTagVariant(step_rep, "Ok");
                    const err = proc.generatedParserTagVariant(step_rep, "Err");
                    const err_body = try proc.forwardGeneratedParserError(
                        context.result,
                        context.result_rep,
                        step,
                        err,
                        context.next,
                    );
                    const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
                    const event_element = proc.generatedParserTagVariant(ok_payload.child.rep, "Item");
                    const event_done = proc.generatedParserTagVariant(ok_payload.child.rep, "Done");
                    const element_payload = try proc.generatedParserSingleTagPayloadLocal(event_element);
                    const elem_value = try proc.addGeneratedParserOutputLocalForRep(loop.elem.rep);
                    const parsed_rest = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);
                    const after_element = try self.lowerGeneratedListAfterElement(
                        proc,
                        context,
                        loop.subject_type,
                        elem_value,
                        loop.cursor,
                        loop.acc,
                        loop.value,
                        loop.rest,
                        loop.join_id,
                        parsed_rest,
                        loop.success,
                    );
                    state.uncounted = .{
                        .call = call,
                        .step_rep = step_rep,
                        .step = step,
                        .ok = ok,
                        .err = err,
                        .err_body = err_body,
                        .ok_payload = ok_payload,
                        .element = event_element,
                        .done = event_done,
                        .element_payload = element_payload,
                    };
                    state.phase = .uncounted;
                    frame.awaiting = true;
                    return .{ .request = .{
                        .context = context,
                        .shape_type = loop.elem.source_type,
                        .shape_rep = loop.elem.rep,
                        .state = element_payload.local,
                        .value = elem_value,
                        .rest = parsed_rest,
                        .success = after_element,
                    } };
                },
                .uncounted => {
                    const parsed_element = child orelse boxyLowerInvariant("generated list parser uncounted step ran before its element");
                    const loop = state.loop;
                    const context = state.context;
                    const uncounted = state.uncounted;
                    const event = uncounted.ok_payload.local;
                    const element_body = try proc.generatedParserReadTagPayload(event, uncounted.element, uncounted.element_payload, parsed_element);
                    const done_body = try self.lowerGeneratedListDone(
                        proc,
                        context,
                        loop.shape_rep,
                        loop.acc,
                        loop.value,
                        loop.rest,
                        event,
                        uncounted.done,
                        loop.success,
                    );
                    const event_variants = [_]GeneratedParserTagVariant{ uncounted.element, uncounted.done };
                    const event_bodies = [_]LIR.CFStmtId{ element_body, done_body };
                    const event_impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                    var ok_body = try proc.generatedParserTagDispatch(event, uncounted.ok_payload.child.rep, &event_variants, &event_bodies, event_impossible);
                    ok_body = try proc.generatedParserReadTagPayload(uncounted.step, uncounted.ok, uncounted.ok_payload, ok_body);
                    const variants = [_]GeneratedParserTagVariant{ uncounted.ok, uncounted.err };
                    const bodies = [_]LIR.CFStmtId{ ok_body, uncounted.err_body };
                    const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                    const dispatch = try proc.generatedParserTagDispatch(uncounted.step, uncounted.step_rep, &variants, &bodies, impossible);
                    const uncounted_step = try self.lowerGeneratedCodecCallLocalsInto(proc, uncounted.call, uncounted.step, &.{ context.encoding, loop.cursor }, dispatch);
                    return self.finishParseShapeFrame(frames, try self.finishGeneratedListParse(proc, state, uncounted_step));
                },
            },
            .dict => |*state| switch (state.phase) {
                .counted => {
                    const entry = child orelse {
                        frame.awaiting = true;
                        return try self.beginGeneratedDictEntryParse(proc, frames, state.context, state.loop, state.loop.cursor, .counted);
                    };
                    const loop = state.loop;
                    const context = state.context;
                    const remaining_is_zero = try proc.addFrameLocal(.bool);
                    const zero = try proc.addFrameLocal(.u64);
                    var counted_step = try proc.boolSwitchNoContinuation(remaining_is_zero, state.counted_done, entry);
                    counted_step = try proc.assignBinaryLowLevel(remaining_is_zero, .num_is_eq, loop.remaining, zero, counted_step);
                    state.counted_step = try proc.assignIntLiteral(zero, 0, counted_step);

                    // One step of an uncounted dictionary: `parse_dict_next`
                    // reports whether an entry follows.
                    const next = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_dict_next", loop.subject_type));
                    const event = next.ok_payload;
                    const entry_variant = proc.generatedParserTagVariant(event.child.rep, "Entry");
                    const done_variant = proc.generatedParserTagVariant(event.child.rep, "Done");
                    const entry_payload = try proc.generatedParserSingleTagPayloadLocal(entry_variant);
                    const done_payload = try proc.generatedParserSingleTagPayloadLocal(done_variant);
                    const entry_state = try proc.addFrameLocalForRep(context.state_rep);
                    state.uncounted = .{
                        .next = next,
                        .entry_variant = entry_variant,
                        .done_variant = done_variant,
                        .entry_payload = entry_payload,
                        .done_payload = done_payload,
                        .entry_state = entry_state,
                    };
                    state.phase = .uncounted;
                    frame.awaiting = true;
                    return try self.beginGeneratedDictEntryParse(proc, frames, context, loop, entry_state, .uncounted);
                },
                .uncounted => {
                    const entry = child orelse boxyLowerInvariant("generated dictionary parser uncounted step ran before its entry");
                    const loop = state.loop;
                    const context = state.context;
                    const uncounted = state.uncounted;
                    const event = uncounted.next.ok_payload;
                    const entry_at_rep = try proc.assignRepresentationBoundary(uncounted.entry_state, uncounted.entry_payload.local, context.state_rep, uncounted.entry_payload.child.rep, entry);
                    const variants = [_]GeneratedParserTagVariant{ uncounted.entry_variant, uncounted.done_variant };
                    const bodies = [_]LIR.CFStmtId{
                        try proc.generatedParserReadTagPayload(
                            event.local,
                            uncounted.entry_variant,
                            uncounted.entry_payload,
                            entry_at_rep,
                        ),
                        try proc.generatedParserReadTagPayload(
                            event.local,
                            uncounted.done_variant,
                            uncounted.done_payload,
                            try self.lowerGeneratedDictDone(proc, context, loop, loop.acc, uncounted.done_payload.local, uncounted.done_payload.child.rep),
                        ),
                    };
                    const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                    const ok_body = try proc.generatedParserTagDispatch(event.local, event.child.rep, &variants, &bodies, impossible);
                    const uncounted_step = try self.finishGeneratedParserTryCall(
                        proc,
                        uncounted.next,
                        &.{ context.encoding, loop.cursor },
                        context.result,
                        context.result_rep,
                        context.next,
                        ok_body,
                    );
                    return self.finishParseShapeFrame(frames, try self.finishGeneratedDictParse(proc, state, uncounted_step));
                },
            },
            .dict_entry => |*state| switch (state.phase) {
                .value => {
                    const parsed_value = child orelse {
                        frame.awaiting = true;
                        return .{ .request = state.value };
                    };
                    const loop = state.loop;
                    const context = state.context;
                    const separator = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_dict_after_key", loop.subject_type));
                    var continuation = try proc.assignRepresentationBoundary(state.value.state, separator.ok_payload.local, context.state_rep, separator.ok_payload.child.rep, parsed_value);
                    continuation = try self.finishGeneratedParserTryCall(
                        proc,
                        separator,
                        &.{ context.encoding, state.after_key },
                        context.result,
                        context.result_rep,
                        context.next,
                        continuation,
                    );
                    // Read one key at the entry state into `key`, leaving the
                    // state after it in `after_key`, by the strategy the
                    // planner recorded for this key type.
                    const field_selection = self.plan.generatedParserDictionaryFieldSelection(context.worker, loop.key_type) orelse
                        boxyLowerInvariant("generated dictionary key parser had no checked strategy");
                    switch (field_selection.strategy) {
                        .method => |method| {
                            const call = proc.generatedCodecCallPlanByIdentity(context.worker, context.encoding_type, loop.key_type, method.module, method.name);
                            return self.finishParseShapeFrame(frames, try self.lowerGeneratedDictKeyString(proc, context, call, state.entry_state, state.key, loop.key_rep, state.after_key, continuation));
                        },
                        .unit_tags => |key_str_subject| {
                            const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_key_str", key_str_subject);
                            const key_str = try proc.addFrameLocal(.str);
                            const matched = try self.lowerGeneratedDictUnitTagKey(proc, context, loop.key_rep, key_str, state.key, state.after_key, continuation);
                            return self.finishParseShapeFrame(frames, try self.lowerGeneratedDictKeyString(proc, context, call, state.entry_state, key_str, proc.repForTypeRef(key_str_subject), state.after_key, matched));
                        },
                        .key_start => {
                            state.key_start = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_key_start", loop.key_type));
                            state.key_state = try proc.addFrameLocalForRep(context.state_rep);
                            state.phase = .key;
                            frame.awaiting = true;
                            return .{ .request = .{
                                .context = context,
                                .shape_type = loop.key_type,
                                .shape_rep = loop.key_rep,
                                .state = state.key_state,
                                .value = state.key,
                                .rest = state.after_key,
                                .success = continuation,
                            } };
                        },
                    }
                },
                .key => {
                    const parsed_key = child orelse boxyLowerInvariant("generated dictionary key parser ran before its key");
                    const context = state.context;
                    const continuation = try proc.assignRepresentationBoundary(state.key_state, state.key_start.ok_payload.local, context.state_rep, state.key_start.ok_payload.child.rep, parsed_key);
                    const stmt = try self.finishGeneratedParserTryCall(
                        proc,
                        state.key_start,
                        &.{ context.encoding, state.entry_state },
                        context.result,
                        context.result_rep,
                        context.next,
                        continuation,
                    );
                    return self.finishParseShapeFrame(frames, stmt);
                },
            },
            .record => |*state| {
                if (child) |matched| {
                    state.field_bodies[state.field_cursor] = matched;
                    state.field_cursor += 1;
                }
                if (state.field_cursor < state.context.fields.len) {
                    frame.awaiting = true;
                    return .{ .request = try self.beginGeneratedMatchedRecordField(
                        proc,
                        &state.context,
                        state.field_cursor,
                        state.field_states[state.field_cursor],
                    ) };
                }
                return self.finishParseShapeFrame(frames, try self.finishGeneratedRecordParse(proc, state));
            },
        }
    }

    fn beginGeneratedTryParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        request: ParseShapeRequest,
        try_plan: Plan.GeneratedParserTryPlan,
    ) Allocator.Error!ParseShapeStep {
        const context = request.context;
        const shape_rep = request.shape_rep;
        const value = request.value;
        const rest = request.rest;
        const success = request.success;
        if (!try_plan.null) {
            boxyLowerInvariant("generated parser Try plan did not include Null handling");
        }
        const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_null", null);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 2 or !planTypeRefEql(arg_types[1], context.state_type)) {
            boxyLowerInvariant("generated parse_null call disagreed with parser state metadata");
        }

        const parsed_rep = proc.repForTypeRef(call.ret_type);
        const parsed = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(parsed_rep);
        const null_ok = proc.generatedParserTagVariant(parsed_rep, "Ok");
        const null_err = proc.generatedParserTagVariant(parsed_rep, "Err");

        const try_ok = proc.generatedParserTagVariant(shape_rep, "Ok");
        const try_err = proc.generatedParserTagVariant(shape_rep, "Err");
        const error_rep = proc.repForTypeRef(try_plan.error_type);
        const error_value = try proc.addFrameLocalForRep(error_rep);
        const null_marker = proc.generatedParserTagVariant(error_rep, "Null");
        const null_payload = try proc.generatedParserSingleTagPayloadLocal(null_ok);
        var null_body = try proc.assignGeneratedParserTag(
            value,
            shape_rep,
            try_err,
            error_value,
            error_rep,
            success,
        );
        null_body = try proc.assignGeneratedParserZeroTag(error_value, error_rep, null_marker, null_body);
        null_body = try proc.assignRepresentationBoundary(
            rest,
            null_payload.local,
            context.state_rep,
            null_payload.child.rep,
            null_body,
        );
        null_body = try proc.generatedParserReadTagPayload(parsed, null_ok, null_payload, null_body);
        const ok_rep = proc.repForTypeRef(try_plan.ok_type);
        const ok_value = try proc.addGeneratedParserOutputLocalForRep(ok_rep);
        const child_success = try proc.assignGeneratedParserTag(
            value,
            shape_rep,
            try_ok,
            ok_value,
            ok_rep,
            success,
        );
        return try self.pushParseShapeFrame(frames, .{ .state = .{ .try_shape = .{
            .context = context,
            .call = call,
            .state = request.state,
            .parsed = parsed,
            .parsed_rep = parsed_rep,
            .null_ok = null_ok,
            .null_err = null_err,
            .null_body = null_body,
            .ok = .{
                .context = context,
                .shape_type = try_plan.ok_type,
                .shape_rep = ok_rep,
                .state = request.state,
                .value = ok_value,
                .rest = rest,
                .success = child_success,
            },
        } } });
    }

    /// A tuple's arity is static: `parse_tuple_start` opens it, every element
    /// after the first is preceded by `parse_tuple_next`, and
    /// `parse_tuple_end` closes it. Each call is told the element count.
    fn beginGeneratedTupleParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        request: ParseShapeRequest,
    ) Allocator.Error!ParseShapeStep {
        const context = request.context;
        const shape_type = request.shape_type;
        const shape_rep = request.shape_rep;
        var frame: ParseShapeFrame = .{ .state = .{ .tuple = .{
            .request = request,
            .items = &.{},
            .parsed_rests = &.{},
            .separators = &.{},
            .start = undefined,
            .len = undefined,
            .remaining = 0,
            .current = undefined,
        } } };
        errdefer self.releaseParseShapeFrame(&frame);
        const state = &frame.state.tuple;
        state.items = try self.generatedParserTupleItems(proc, shape_rep);
        const items = state.items;
        for (items) |*item| item.value = try proc.addGeneratedParserOutputLocalForRep(item.rep);
        state.parsed_rests = try self.allocator.alloc(LIR.LocalId, items.len);
        for (state.parsed_rests) |*local| local.* = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);

        state.len = try proc.addFrameLocal(.u64);
        state.start = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_tuple_start", shape_type));
        const end = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_tuple_end", shape_type));
        const next_call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_tuple_next", shape_type);
        // `separators[i]` precedes element `i`; element 0 has none.
        state.separators = try self.allocator.alloc(GeneratedParserTryCall, items.len);
        for (state.separators[@min(1, items.len)..]) |*separator| separator.* = try beginGeneratedParserTryCall(proc, next_call);

        var continuation = try self.lowerGeneratedTupleFinish(proc, shape_rep, request.value, items, request.success);
        continuation = try proc.assignRepresentationBoundary(request.rest, end.ok_payload.local, context.state_rep, end.ok_payload.child.rep, continuation);
        state.current = try self.finishGeneratedParserTryCall(
            proc,
            end,
            &.{ context.encoding, if (items.len == 0) state.start.ok_payload.local else state.parsed_rests[items.len - 1], state.len },
            context.result,
            context.result_rep,
            context.next,
            continuation,
        );
        state.remaining = items.len;
        try frames.append(self.allocator, frame);
        return .pushed;
    }

    fn beginGeneratedListParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        context: GeneratedParserShapeContext,
        subject_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        explicit_elem: ?Plan.RepChild,
        state: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
    ) Allocator.Error!ParseShapeStep {
        const list_rep = proc.listRepForBoundary(shape_rep) orelse
            boxyLowerInvariant("generated list parser shape had no list representation");
        const elem = explicit_elem orelse proc.repQuery().requiredSingleChild(list_rep, .list_elem);
        const elem_layout = proc.workerRuntimeLayoutForRep(elem.rep).layoutIdx();
        if (elem_layout != proc.localListElemLayout(value)) {
            boxyLowerInvariant("generated list parser element worker and storage layouts disagreed");
        }

        const list_layout = self.result.store.getLocal(value).layout_idx;
        const acc = try proc.addFrameLocal(list_layout);
        const target_desc = try proc.stableDescriptorForConstructedValue(value, shape_rep);
        if (target_desc.desc) |desc| {
            self.result.store.setLocalBoxyDesc(value, desc);
            self.result.store.setLocalBoxyDesc(acc, desc);
        }
        const loop = GeneratedListLoop{
            .subject_type = subject_type,
            .shape_rep = shape_rep,
            .state_rep = context.state_rep,
            .elem = elem,
            .cursor = try proc.addGeneratedParserOutputLocalForRep(context.state_rep),
            .acc = acc,
            .counted = try proc.addFrameLocal(.bool),
            .remaining = try proc.addFrameLocal(.u64),
            .value = value,
            .rest = rest,
            .join_id = proc.freshJoinPointId(),
            .success = success,
        };

        // One step of a counted list: finish once no elements remain,
        // otherwise parse the next element directly at the cursor.
        var done = try proc.assignRepresentationBoundary(loop.rest, loop.cursor, context.state_rep, context.state_rep, loop.success);
        done = try proc.assignRepresentationBoundary(loop.value, loop.acc, loop.shape_rep, loop.shape_rep, done);

        const elem_value = try proc.addGeneratedParserOutputLocalForRep(loop.elem.rep);
        const parsed_rest = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);
        const next_acc = try proc.addFrameLocal(self.result.store.getLocal(loop.acc).layout_idx);
        if (self.result.store.getLocal(loop.acc).boxy_desc) |desc| self.result.store.setLocalBoxyDesc(next_acc, desc);
        const one = try proc.addFrameLocal(.u64);
        const next_remaining = try proc.addFrameLocal(.u64);
        var element = try self.result.store.addCFStmt(.{ .jump = .{ .target = loop.join_id } }, proc.derivedOrigin());
        element = try proc.setLocalInitializeJoinParam(loop.remaining, next_remaining, element);
        element = try proc.setLocalInitializeJoinParam(loop.acc, next_acc, element);
        element = try proc.setLocalInitializeJoinParamFromRep(loop.cursor, parsed_rest, context.state_rep, element);
        element = try proc.assignBinaryLowLevel(next_remaining, .num_int_sub_wrap, loop.remaining, one, element);
        element = try proc.assignIntLiteral(one, 1, element);
        element = try proc.assignListAppendGrowingMovingElement(next_acc, loop.acc, elem_value, element);
        return try self.pushParseShapeFrame(frames, .{ .state = .{ .list = .{
            .context = context,
            .subject_type = subject_type,
            .state = state,
            .target_desc = target_desc,
            .loop = loop,
            .phase = .counted,
            .counted_element = .{
                .context = context,
                .shape_type = loop.elem.source_type,
                .shape_rep = loop.elem.rep,
                .state = loop.cursor,
                .value = elem_value,
                .rest = parsed_rest,
                .success = element,
            },
            .counted_done = done,
        } } });
    }

    /// Finish the list parser once both loop steps are built.
    fn finishGeneratedListParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        state: *const GeneratedListParseState,
        uncounted_step: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const context = state.context;
        const loop = state.loop;
        const target_desc = state.target_desc;
        const loop_body = try proc.boolSwitchNoContinuation(loop.counted, state.counted_step, uncounted_step);

        const start_call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_list_start", state.subject_type);
        const start = try beginGeneratedParserTryCall(proc, start_call);
        const event = start.ok_payload;
        const counted_variant = proc.generatedParserTagVariant(event.child.rep, "Counted");
        const uncounted_variant = proc.generatedParserTagVariant(event.child.rep, "Uncounted");

        const counted_payload = try proc.generatedParserSingleTagPayloadLocal(counted_variant);
        const counted_len = try proc.addFrameLocal(.u64);
        const counted_rest = try proc.addFrameLocalForRep(context.state_rep);
        var counted_body = try self.lowerGeneratedListStartJump(proc, loop, target_desc.desc, counted_rest, context.state_rep, true, counted_len);
        counted_body = try proc.generatedParserReadRecordField(counted_rest, context.state_rep, counted_payload.local, counted_payload.child, "rest", counted_body);
        counted_body = try proc.generatedParserReadRecordField(counted_len, proc.repForTypeRef(try proc.generatedParserRecordFieldType(counted_payload.child.source_type, "len")), counted_payload.local, counted_payload.child, "len", counted_body);
        counted_body = try proc.generatedParserReadTagPayload(event.local, counted_variant, counted_payload, counted_body);

        const uncounted_payload = try proc.generatedParserSingleTagPayloadLocal(uncounted_variant);
        const zero = try proc.addFrameLocal(.u64);
        var uncounted_body = try self.lowerGeneratedListStartJump(proc, loop, target_desc.desc, uncounted_payload.local, uncounted_payload.child.rep, false, zero);
        uncounted_body = try proc.assignIntLiteral(zero, 0, uncounted_body);
        uncounted_body = try proc.generatedParserReadTagPayload(event.local, uncounted_variant, uncounted_payload, uncounted_body);

        const variants = [_]GeneratedParserTagVariant{ counted_variant, uncounted_variant };
        const bodies = [_]LIR.CFStmtId{ counted_body, uncounted_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const ok_body = try proc.generatedParserTagDispatch(event.local, event.child.rep, &variants, &bodies, impossible);
        var initial = try self.finishGeneratedParserTryCall(
            proc,
            start,
            &.{ context.encoding, state.state },
            context.result,
            context.result_rep,
            context.next,
            ok_body,
        );
        initial = try proc.prependOptionalDescriptorMaterialization(target_desc.materialize, initial);
        return try self.result.store.addCFStmt(.{ .join = .{
            .id = loop.join_id,
            .params = try proc.joinParamSpan(&.{ loop.cursor, loop.acc, loop.counted, loop.remaining }),
            .body = loop_body,
            .remainder = initial,
        } }, proc.derivedOrigin());
    }

    fn beginGeneratedSetParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        request: ParseShapeRequest,
    ) Allocator.Error!ParseShapeStep {
        const context = request.context;
        const shape_type = request.shape_type;
        const call = proc.generatedCodecCallPlan(context.worker, shape_type, "from_list", shape_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 1) boxyLowerInvariant("generated Set.from_list call had unexpected arity");
        const list_rep = proc.repForTypeRef(arg_types[0]);
        if (proc.listRepForBoundary(list_rep) == null) {
            boxyLowerInvariant("generated Set.from_list call did not accept a List");
        }
        const list = try proc.addFrameLocalForRep(list_rep);
        const convert = try self.lowerGeneratedCodecCallLocalsInto(proc, call, request.value, &.{list}, request.success);
        const shape_module = procedureModuleById(self.modules, shape_type.module);
        const nominal = resolvedNominalPayload(shape_module, shape_type.ty);
        if (nominal.builtin != .set or nominal.args.len != 1) {
            boxyLowerInvariant("generated Set parser shape did not have one public element type");
        }
        var public_elem = proc.repQuery().requiredSingleChild(proc.listRepForBoundary(list_rep).?, .list_elem);
        public_elem.source_type = .{ .module = shape_type.module, .ty = nominal.args[0] };
        public_elem.rep = proc.repForTypeRef(public_elem.source_type);
        return try self.beginGeneratedListParse(
            proc,
            frames,
            context,
            shape_type,
            list_rep,
            public_elem,
            request.state,
            list,
            request.rest,
            convert,
        );
    }

    fn beginGeneratedDictParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        request: ParseShapeRequest,
    ) Allocator.Error!ParseShapeStep {
        const context = request.context;
        const shape_type = request.shape_type;
        const shape_rep = request.shape_rep;
        const insert_call = proc.generatedCodecCallPlan(context.worker, shape_type, "insert", shape_type);
        const insert_arg_types = self.plan.generatedCodecCallTypeSlice(insert_call.arg_types);
        if (insert_arg_types.len != 3 or !planTypeRefEql(insert_arg_types[0], shape_type)) {
            boxyLowerInvariant("generated Dict.insert call had unexpected arguments");
        }
        const shape_module = procedureModuleById(self.modules, shape_type.module);
        const nominal = resolvedNominalPayload(shape_module, shape_type.ty);
        if (nominal.builtin != .dict or nominal.args.len != 2) {
            boxyLowerInvariant("generated Dict parser shape did not have public key and value types");
        }
        const key_type = Plan.CheckedTypeIdentity{ .module = shape_type.module, .ty = nominal.args[0] };
        const value_type = Plan.CheckedTypeIdentity{ .module = shape_type.module, .ty = nominal.args[1] };
        const loop = GeneratedDictLoop{
            .subject_type = shape_type,
            .shape_rep = shape_rep,
            .key_type = key_type,
            .key_rep = proc.repForTypeRef(key_type),
            .value_type = value_type,
            .value_rep = proc.repForTypeRef(value_type),
            .insert_call = insert_call,
            .cursor = try proc.addGeneratedParserOutputLocalForRep(context.state_rep),
            .acc = try proc.addFrameLocalForRep(shape_rep),
            .counted = try proc.addFrameLocal(.bool),
            .remaining = try proc.addFrameLocal(.u64),
            .value = request.value,
            .rest = request.rest,
            .join_id = proc.freshJoinPointId(),
            .success = request.success,
        };

        // One step of a counted dictionary: finish once no entries remain,
        // otherwise parse the next entry directly at the cursor.
        const done = try self.lowerGeneratedDictDone(proc, context, loop, loop.acc, loop.cursor, context.state_rep);
        return try self.pushParseShapeFrame(frames, .{ .state = .{ .dict = .{
            .context = context,
            .state = request.state,
            .shape_type = shape_type,
            .loop = loop,
            .phase = .counted,
            .counted_done = done,
        } } });
    }

    /// Finish the dictionary parser once both loop steps are built.
    fn finishGeneratedDictParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        state: *const GeneratedDictParseState,
        uncounted_step: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const context = state.context;
        const loop = state.loop;
        const loop_body = try proc.boolSwitchNoContinuation(loop.counted, state.counted_step, uncounted_step);

        const start = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_dict_start", state.shape_type));
        const event = start.ok_payload;
        const counted_variant = proc.generatedParserTagVariant(event.child.rep, "Counted");
        const uncounted_variant = proc.generatedParserTagVariant(event.child.rep, "Uncounted");

        const counted_payload = try proc.generatedParserSingleTagPayloadLocal(counted_variant);
        const counted_len = try proc.addFrameLocal(.u64);
        const counted_rest = try proc.addFrameLocalForRep(context.state_rep);
        var counted_body = try self.lowerGeneratedDictStartJump(proc, context, loop, counted_rest, context.state_rep, true, counted_len);
        counted_body = try proc.generatedParserReadRecordField(counted_rest, context.state_rep, counted_payload.local, counted_payload.child, "rest", counted_body);
        counted_body = try proc.generatedParserReadRecordField(counted_len, proc.repForTypeRef(try proc.generatedParserRecordFieldType(counted_payload.child.source_type, "len")), counted_payload.local, counted_payload.child, "len", counted_body);
        counted_body = try proc.generatedParserReadTagPayload(event.local, counted_variant, counted_payload, counted_body);

        const uncounted_payload = try proc.generatedParserSingleTagPayloadLocal(uncounted_variant);
        const zero = try proc.addFrameLocal(.u64);
        var uncounted_body = try self.lowerGeneratedDictStartJump(proc, context, loop, uncounted_payload.local, uncounted_payload.child.rep, false, zero);
        uncounted_body = try proc.assignIntLiteral(zero, 0, uncounted_body);
        uncounted_body = try proc.generatedParserReadTagPayload(event.local, uncounted_variant, uncounted_payload, uncounted_body);

        const variants = [_]GeneratedParserTagVariant{ counted_variant, uncounted_variant };
        const bodies = [_]LIR.CFStmtId{ counted_body, uncounted_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const ok_body = try proc.generatedParserTagDispatch(event.local, event.child.rep, &variants, &bodies, impossible);
        const initial = try self.finishGeneratedParserTryCall(
            proc,
            start,
            &.{ context.encoding, state.state },
            context.result,
            context.result_rep,
            context.next,
            ok_body,
        );
        return try self.result.store.addCFStmt(.{ .join = .{
            .id = loop.join_id,
            .params = try proc.joinParamSpan(&.{ loop.cursor, loop.acc, loop.counted, loop.remaining }),
            .body = loop_body,
            .remainder = initial,
        } }, proc.derivedOrigin());
    }

    const GeneratedDictEntryEnd = enum { counted, uncounted };

    /// One entry: key, `parse_dict_after_key`, value, insert, then the entry
    /// end (counting down, or asking `parse_dict_after_entry`).
    fn beginGeneratedDictEntryParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        context: GeneratedParserShapeContext,
        loop: GeneratedDictLoop,
        entry_state: LIR.LocalId,
        end: GeneratedDictEntryEnd,
    ) Allocator.Error!ParseShapeStep {
        const key = try proc.addGeneratedParserOutputLocalForRep(loop.key_rep);
        const after_key = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);
        const value_state = try proc.addFrameLocalForRep(context.state_rep);
        const parsed_value = try proc.addGeneratedParserOutputLocalForRep(loop.value_rep);
        const after_value = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);
        const next_acc = try proc.addFrameLocalForRep(loop.shape_rep);

        var continuation = switch (end) {
            .counted => blk: {
                const one = try proc.addFrameLocal(.u64);
                const next_remaining = try proc.addFrameLocal(.u64);
                var counted = try self.lowerGeneratedDictLoopJump(proc, loop, next_acc, after_value, context.state_rep);
                counted = try proc.setLocalInitializeJoinParam(loop.remaining, next_remaining, counted);
                counted = try proc.assignBinaryLowLevel(next_remaining, .num_int_sub_wrap, loop.remaining, one, counted);
                break :blk try proc.assignIntLiteral(one, 1, counted);
            },
            .uncounted => blk: {
                const after = try beginGeneratedParserTryCall(proc, proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_dict_after_entry", loop.subject_type));
                const event = after.ok_payload;
                const continue_variant = proc.generatedParserTagVariant(event.child.rep, "Continue");
                const done_variant = proc.generatedParserTagVariant(event.child.rep, "Done");
                const continue_payload = try proc.generatedParserSingleTagPayloadLocal(continue_variant);
                const done_payload = try proc.generatedParserSingleTagPayloadLocal(done_variant);
                const variants = [_]GeneratedParserTagVariant{ continue_variant, done_variant };
                const bodies = [_]LIR.CFStmtId{
                    try proc.generatedParserReadTagPayload(
                        event.local,
                        continue_variant,
                        continue_payload,
                        try self.lowerGeneratedDictLoopJump(proc, loop, next_acc, continue_payload.local, continue_payload.child.rep),
                    ),
                    try proc.generatedParserReadTagPayload(
                        event.local,
                        done_variant,
                        done_payload,
                        try self.lowerGeneratedDictDone(proc, context, loop, next_acc, done_payload.local, done_payload.child.rep),
                    ),
                };
                const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
                const ok_body = try proc.generatedParserTagDispatch(event.local, event.child.rep, &variants, &bodies, impossible);
                break :blk try self.finishGeneratedParserTryCall(
                    proc,
                    after,
                    &.{ context.encoding, after_value },
                    context.result,
                    context.result_rep,
                    context.next,
                    ok_body,
                );
            },
        };
        continuation = try self.lowerGeneratedCodecCallLocalsInto(proc, loop.insert_call, next_acc, &.{ loop.acc, key, parsed_value }, continuation);
        return try self.pushParseShapeFrame(frames, .{ .state = .{ .dict_entry = .{
            .context = context,
            .loop = loop,
            .entry_state = entry_state,
            .key = key,
            .after_key = after_key,
            .phase = .value,
            .value = .{
                .context = context,
                .shape_type = loop.value_type,
                .shape_rep = loop.value_rep,
                .state = value_state,
                .value = parsed_value,
                .rest = after_value,
                .success = continuation,
            },
        } } });
    }

    fn beginGeneratedRecordParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        frames: *std.ArrayList(ParseShapeFrame),
        shape_context: GeneratedParserShapeContext,
        shape_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        state: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
        field_names_source: GeneratedParserFieldNamesSource,
    ) Allocator.Error!ParseShapeStep {
        try proc.ensureGeneratedParserOutputDescriptorForRep(value, shape_rep);
        try proc.ensureGeneratedParserOutputDescriptorForRep(rest, shape_context.state_rep);
        const parse_call = proc.generatedCodecCallPlan(
            shape_context.worker,
            shape_context.encoding_type,
            "parse_record_field",
            shape_type,
        );
        const parse_arg_types = self.plan.generatedCodecCallTypeSlice(parse_call.arg_types);
        if (parse_arg_types.len != 3 or !planTypeRefEql(parse_arg_types[2], shape_context.state_type)) {
            boxyLowerInvariant("generated parse_record_field call disagreed with parser state metadata");
        }

        const error_join = proc.freshJoinPointId();
        const error_target = try proc.addFrameBoundaryTargetLocalForRep(shape_context.result_rep);
        const cursor = try proc.addGeneratedParserOutputLocalForRep(shape_context.state_rep);
        const counted = try proc.addFrameLocal(.bool);
        const remaining = try proc.addFrameLocal(.u64);
        const entry_pending = try proc.addFrameLocal(.bool);
        const evidence = try proc.addFrameLocalForRep(proc.repForTypeRef(parse_arg_types[1]));
        var frame: ParseShapeFrame = .{ .state = .{ .record = .{
            .shape_context = shape_context,
            .error_join = error_join,
            .state = state,
            .field_names_source = field_names_source,
            .parse_call = parse_call,
            .context = .{
                .worker = shape_context.worker,
                .encoding_type = shape_context.encoding_type,
                .encoding = shape_context.encoding,
                .shape_type = shape_type,
                .shape_rep = shape_rep,
                .target = error_target,
                .target_rep = shape_context.result_rep,
                .state_type = shape_context.state_type,
                .state_rep = shape_context.state_rep,
                .cursor = cursor,
                .counted = counted,
                .remaining = remaining,
                .entry_pending = entry_pending,
                .evidence = evidence,
                .fields = &.{},
                .presence = &.{},
                .join_id = undefined,
                .next = try proc.joinJump(error_join),
                .value = value,
                .rest = rest,
                .success = success,
            },
            .step_join = undefined,
            .step = undefined,
            .variants = undefined,
            .bodies = undefined,
            .field_joins = &.{},
            .field_states = &.{},
            .field_bodies = &.{},
        } } };
        errdefer self.releaseParseShapeFrame(&frame);
        const record = &frame.state.record;
        record.context.fields = try self.generatedParserRecordFields(
            proc,
            shape_context.worker,
            shape_type,
            shape_rep,
            field_names_source,
        );
        const fields = record.context.fields;
        const presence_count = (fields.len + 63) / 64;
        record.context.presence = try self.allocator.alloc(LIR.LocalId, presence_count);
        for (record.context.presence) |*local| local.* = try proc.addFrameLocal(.u64);
        for (fields) |*field| field.payload = try proc.addGeneratedParserOutputLocalForRep(field.rep);
        record.context.join_id = proc.freshJoinPointId();

        // The loop head reads the next `parse_record_field` event.
        record.step_join = proc.freshJoinPointId();
        record.step = try beginGeneratedParserTryCall(proc, parse_call);
        const event = record.step.ok_payload.local;
        const event_child = record.step.ok_payload.child;
        const continue_variant = proc.generatedParserTagVariant(event_child.rep, "Continue");
        const done_variant = proc.generatedParserTagVariant(event_child.rep, "Done");
        const field_variant = proc.generatedParserTagVariant(event_child.rep, "Field");
        const try_field_variant = proc.generatedParserTagVariant(event_child.rep, "TryField");
        const caseless_variant = proc.generatedParserTagVariant(event_child.rep, "TryFieldCaseless");
        record.variants = .{
            continue_variant,
            done_variant,
            field_variant,
            try_field_variant,
            caseless_variant,
        };
        record.bodies[0] = try self.lowerGeneratedRecordContinueEvent(proc, record.context, event, continue_variant);
        record.bodies[1] = try self.lowerGeneratedRecordDoneEvent(proc, record.context, event, done_variant);

        record.field_joins = try self.allocator.alloc(LIR.JoinPointId, fields.len);
        for (record.field_joins) |*join_id| join_id.* = proc.freshJoinPointId();
        record.field_states = try self.allocator.alloc(LIR.LocalId, fields.len);
        for (record.field_states) |*local| local.* = try proc.addGeneratedParserOutputLocalForRep(record.context.state_rep);
        record.field_bodies = try self.allocator.alloc(LIR.CFStmtId, fields.len);
        try frames.append(self.allocator, frame);
        return .pushed;
    }

    /// Enter a field's value parser at `rest`, the state after its key.
    fn lowerGeneratedRecordFieldJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        state: *const GeneratedRecordParseState,
        field_index: usize,
        rest: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        const jump = try self.result.store.addCFStmt(.{ .jump = .{ .target = state.field_joins[field_index] } }, proc.derivedOrigin());
        return try proc.setLocalInitializeJoinParamFromRep(state.field_states[field_index], rest, state.context.state_rep, jump);
    }

    /// A `Field` event names its field by handle index.
    fn lowerGeneratedRecordDirectFieldEvent(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        state: *const GeneratedRecordParseState,
    ) Allocator.Error!LIR.CFStmtId {
        const context = state.context;
        const fields = context.fields;
        const payload = try proc.generatedParserSingleTagPayloadLocal(state.variants[2]);
        const field_handle = try proc.addFrameLocal(self.layout_plan.generated_evidence.field);
        const rest = try proc.addFrameLocalForRep(context.state_rep);
        const index = try proc.addFrameLocal(.u64);
        const branches = try self.allocator.alloc(LIR.CFSwitchBranch, fields.len);
        defer self.allocator.free(branches);
        for (fields, branches, 0..) |field, *branch, field_index| {
            branch.* = .{
                .value = field.index,
                .body = try self.lowerGeneratedRecordFieldJump(proc, state, field_index, rest),
            };
        }
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const field_switch = try self.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = index,
            .branches = try self.result.store.addCFSwitchBranches(branches),
            .default_branch = impossible,
            .continuation = null,
        } }, proc.derivedOrigin());
        var continuation = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = index,
            .op = .{ .field = .{ .source = field_handle, .field_idx = 1 } },
            .next = field_switch,
        } }, proc.derivedOrigin());
        continuation = try proc.generatedParserReadRecordField(
            rest,
            context.state_rep,
            payload.local,
            payload.child,
            "rest",
            continuation,
        );
        continuation = try proc.generatedParserReadRecordField(
            field_handle,
            proc.repForTypeRef(try proc.generatedParserRecordFieldType(payload.child.source_type, "field")),
            payload.local,
            payload.child,
            "field",
            continuation,
        );
        return try proc.generatedParserReadTagPayload(state.step.ok_payload.local, state.variants[2], payload, continuation);
    }

    /// A `TryField` or `TryFieldCaseless` event compares the name with each
    /// field's name, first field first, skipping an unmatched entry.
    fn lowerGeneratedRecordNamedFieldEvent(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        state: *const GeneratedRecordParseState,
        variant: GeneratedParserTagVariant,
        compare_op: LIR.LowLevel,
    ) Allocator.Error!LIR.CFStmtId {
        const context = state.context;
        const fields = context.fields;
        const payload = try proc.generatedParserSingleTagPayloadLocal(variant);
        const name = try proc.addFrameLocal(.str);
        const rest = try proc.addFrameLocalForRep(context.state_rep);
        var dispatch = try self.lowerGeneratedSkipRecordField(proc, context, rest);
        var field_index = fields.len;
        while (field_index > 0) {
            field_index -= 1;
            const matches = try proc.addFrameLocal(.bool);
            const matched = try self.lowerGeneratedRecordFieldJump(proc, state, field_index, rest);
            const switch_stmt = try proc.boolSwitchNoContinuation(matches, matched, dispatch);
            dispatch = try proc.assignBinaryLowLevel(matches, compare_op, name, fields[field_index].renamed, switch_stmt);
        }
        dispatch = try proc.generatedParserReadRecordField(
            rest,
            context.state_rep,
            payload.local,
            payload.child,
            "rest",
            dispatch,
        );
        dispatch = try proc.generatedParserReadRecordField(
            name,
            proc.repForTypeRef(try proc.generatedParserRecordFieldType(payload.child.source_type, "name")),
            payload.local,
            payload.child,
            "name",
            dispatch,
        );
        return try proc.generatedParserReadTagPayload(state.step.ok_payload.local, variant, payload, dispatch);
    }

    /// The parser for a matched record field's value, reserving the value
    /// and building the loop update that follows it.
    fn beginGeneratedMatchedRecordField(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: *const GeneratedParserRecordContext,
        field_index: usize,
        rest: LIR.LocalId,
    ) Allocator.Error!ParseShapeRequest {
        const field = context.fields[field_index];
        const value = try proc.addGeneratedParserOutputLocalForRep(field.rep);
        // A field stored in a wrapper (`Ok` of an optional `Try`, `#Present`
        // of a presence slot) is parsed at the wrapped payload type.
        const present_tag: ?[]const u8 = switch (field.kind) {
            .missing_try => "Ok",
            .optional_slot, .undetermined_slot => "#Present",
            .required, .defaulted => null,
        };
        const parsed_value = if (present_tag != null)
            try proc.addGeneratedParserOutputLocalForRep(field.parse_rep)
        else
            value;
        const next_rest = try proc.addGeneratedParserOutputLocalForRep(context.state_rep);
        var success = try self.lowerGeneratedRecordLoopUpdate(proc, context.*, field_index, value, next_rest);
        if (present_tag) |tag_text| {
            success = try proc.assignGeneratedParserTag(
                value,
                field.rep,
                proc.generatedParserTagVariant(field.rep, tag_text),
                parsed_value,
                field.parse_rep,
                success,
            );
        }
        return .{
            .context = .{
                .worker = context.worker,
                .encoding_type = context.encoding_type,
                .encoding = context.encoding,
                .state_type = context.state_type,
                .state_rep = context.state_rep,
                .result = context.target,
                .result_rep = context.target_rep,
                .next = context.next,
            },
            .shape_type = field.parse_type,
            .shape_rep = field.parse_rep,
            .state = rest,
            .value = parsed_value,
            .rest = next_rest,
            .success = success,
        };
    }

    /// Finish the record parser once every field event is built.
    fn finishGeneratedRecordParse(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        state: *const GeneratedRecordParseState,
    ) Allocator.Error!LIR.CFStmtId {
        const context = state.context;
        const fields = context.fields;
        const presence = context.presence;
        var bodies = state.bodies;
        bodies[2] = try self.lowerGeneratedRecordDirectFieldEvent(proc, state);
        bodies[3] = try self.lowerGeneratedRecordNamedFieldEvent(proc, state, state.variants[3], .str_is_eq);
        bodies[4] = try self.lowerGeneratedRecordNamedFieldEvent(proc, state, state.variants[4], .str_caseless_ascii_equals);
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        var event_body = try proc.generatedParserTagDispatch(state.step.ok_payload.local, state.step.ok_payload.child.rep, &state.variants, &bodies, impossible);
        var field_index = fields.len;
        while (field_index > 0) {
            field_index -= 1;
            event_body = try self.result.store.addCFStmt(.{ .join = .{
                .id = state.field_joins[field_index],
                .params = try proc.joinParamSpan(&.{state.field_states[field_index]}),
                .body = state.field_bodies[field_index],
                .remainder = event_body,
            } }, proc.derivedOrigin());
        }
        const read_event = try self.finishGeneratedParserTryCall(
            proc,
            state.step,
            &.{ context.encoding, context.evidence, context.cursor },
            context.target,
            context.target_rep,
            context.next,
            event_body,
        );

        // The loop head. A pending entry end runs first; otherwise a counted
        // record with nothing remaining finishes, and anything else reads the
        // next `parse_record_field` event.
        const jump_step = try self.result.store.addCFStmt(.{ .jump = .{ .target = state.step_join } }, proc.derivedOrigin());
        const finish = try self.lowerGeneratedRecordFinish(proc, context);
        const remaining_is_zero = try proc.addFrameLocal(.bool);
        const zero = try proc.addFrameLocal(.u64);
        var counted_head = try proc.boolSwitchNoContinuation(remaining_is_zero, finish, jump_step);
        counted_head = try proc.assignBinaryLowLevel(remaining_is_zero, .num_is_eq, context.remaining, zero, counted_head);
        counted_head = try proc.assignIntLiteral(zero, 0, counted_head);
        const jump_step_uncounted = try self.result.store.addCFStmt(.{ .jump = .{ .target = state.step_join } }, proc.derivedOrigin());
        const head = try proc.boolSwitchNoContinuation(context.counted, counted_head, jump_step_uncounted);

        const entry_end = try self.lowerGeneratedRecordEntryEnd(proc, context);
        const head_dispatch = try proc.boolSwitchNoContinuation(context.entry_pending, entry_end, head);
        const step_loop = try self.result.store.addCFStmt(.{ .join = .{
            .id = state.step_join,
            .params = LIR.LocalSpan.empty(),
            .body = read_event,
            .remainder = head_dispatch,
        } }, proc.derivedOrigin());

        const maybe_payloads = try self.allocator.alloc(LIR.LocalId, fields.len);
        defer self.allocator.free(maybe_payloads);
        const maybe_conditions = try self.allocator.alloc(LIR.LocalId, fields.len);
        defer self.allocator.free(maybe_conditions);
        const maybe_masks = try self.allocator.alloc(u64, fields.len);
        defer self.allocator.free(maybe_masks);
        for (fields, 0..) |field, index| {
            maybe_payloads[index] = field.payload;
            maybe_conditions[index] = presence[index / 64];
            maybe_masks[index] = @as(u64, 1) << @intCast(index % 64);
        }

        // The loop's one error continuation. Its retained environment is the
        // field-name evidence, the field names this worker owns, and the
        // payload slots, so their cleanup exists once rather than at every
        // fallible call inside the loop.
        const retained = try self.allocator.alloc(LIR.LocalId, 1 + fields.len * 2);
        defer self.allocator.free(retained);
        var retained_len: usize = 0;
        retained[retained_len] = context.evidence;
        retained_len += 1;
        switch (state.field_names_source) {
            .captures => for (fields) |field| {
                retained[retained_len] = field.renamed;
                retained_len += 1;
            },
            .tag_union_spec => {},
        }
        for (fields) |field| {
            retained[retained_len] = field.payload;
            retained_len += 1;
        }
        const error_body = try proc.assignRepresentationBoundaryConsumingSource(
            state.shape_context.result,
            context.target,
            state.shape_context.result_rep,
            context.target_rep,
            state.shape_context.next,
        );
        const loop_body = try self.result.store.addCFStmt(.{ .join = .{
            .id = state.error_join,
            .params = try proc.joinParamSpan(&.{context.target}),
            .retained = try self.result.store.addLocalSpan(retained[0..retained_len]),
            .maybe_uninitialized_params = try self.result.store.addLocalSpan(maybe_payloads),
            .maybe_uninitialized_conditions = try self.result.store.addLocalSpan(maybe_conditions),
            .maybe_uninitialized_condition_masks = try self.result.store.addU64Span(maybe_masks),
            .body = error_body,
            .remainder = step_loop,
        } }, proc.derivedOrigin());

        // `parse_record_start` runs before the loop holds any payload, so its
        // error goes straight to the parser result.
        var start_context = context;
        start_context.target = state.shape_context.result;
        start_context.next = state.shape_context.next;
        var initial = try self.lowerGeneratedRecordStart(proc, start_context, state.state);
        field_index = fields.len;
        while (field_index > 0) {
            field_index -= 1;
            initial = try proc.initUninitializedLocal(fields[field_index].payload, initial);
        }
        var presence_index = presence.len;
        while (presence_index > 0) {
            presence_index -= 1;
            initial = try proc.assignIntLiteral(presence[presence_index], 0, initial);
        }

        // Payloads precede presence words: ARC releases an overwritten payload
        // immediately before its write, testing the old presence bit.
        const control_params = [_]LIR.LocalId{ context.cursor, context.counted, context.remaining, context.entry_pending };
        const join_params = try self.allocator.alloc(LIR.LocalId, control_params.len + fields.len + presence.len);
        defer self.allocator.free(join_params);
        @memcpy(join_params[0..control_params.len], &control_params);
        for (fields, 0..) |field, index| join_params[control_params.len + index] = field.payload;
        for (presence, 0..) |local, index| join_params[control_params.len + fields.len + index] = local;

        const join = try self.result.store.addCFStmt(.{ .join = .{
            .id = context.join_id,
            .params = try proc.joinParamSpan(join_params),
            .maybe_uninitialized_params = try self.result.store.addLocalSpan(maybe_payloads),
            .maybe_uninitialized_conditions = try self.result.store.addLocalSpan(maybe_conditions),
            .maybe_uninitialized_condition_masks = try self.result.store.addU64Span(maybe_masks),
            .body = loop_body,
            .remainder = initial,
        } }, proc.derivedOrigin());
        const with_evidence = try self.lowerGeneratedFieldNamesValue(proc, context.evidence, fields, join);
        return try self.lowerGeneratedRecordFieldNamesSource(
            proc,
            state.field_names_source,
            context.shape_rep,
            fields,
            with_evidence,
        );
    }

    fn lowerGeneratedTagUnionFromState(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        shape_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        state: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const call_shape_type = self.plan.generatedParserTagCallShape(context.worker, shape_type) orelse
            boxyLowerInvariant("generated tag-union parser shape had no exact checked call link");
        const plan = self.plan.generatedParserTagUnionPlanForContract(context.worker, call_shape_type) orelse
            boxyLowerInvariant("generated tag-union parser call had no explicit intrinsic plan");
        const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_tag_union", call_shape_type);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 3 or !planTypeRefEql(arg_types[2], context.state_type)) {
            boxyLowerInvariant("generated parse_tag_union call disagreed with parser state metadata");
        }

        const spec_rep = proc.repForTypeRef(arg_types[1]);
        const spec = try proc.addFrameLocalForRep(spec_rep);
        const parsed_rep = proc.repForTypeRef(call.ret_type);
        const parsed = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(parsed_rep);
        const ok = proc.generatedParserTagVariant(parsed_rep, "Ok");
        const err = proc.generatedParserTagVariant(parsed_rep, "Err");
        const err_body = try proc.forwardGeneratedParserError(
            context.result,
            context.result_rep,
            parsed,
            err,
            context.next,
        );
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
        var ok_body = try proc.generatedParserReadRecordField(
            rest,
            context.state_rep,
            ok_payload.local,
            ok_payload.child,
            "rest",
            success,
        );
        ok_body = try proc.generatedParserReadRecordField(
            value,
            shape_rep,
            ok_payload.local,
            ok_payload.child,
            "value",
            ok_body,
        );
        ok_body = try proc.generatedParserReadTagPayload(parsed, ok, ok_payload, ok_body);
        const variants = [_]GeneratedParserTagVariant{ ok, err };
        const bodies = [_]LIR.CFStmtId{ ok_body, err_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const dispatch = try proc.generatedParserTagDispatch(parsed, parsed_rep, &variants, &bodies, impossible);
        var continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            parsed,
            &.{ context.encoding, spec, state },
            dispatch,
        );
        if (context.tag_union_spec) |existing_spec| {
            return try proc.assignRepresentationBoundary(
                spec,
                existing_spec,
                spec_rep,
                context.tag_union_spec_rep orelse
                    boxyLowerInvariant("generated nested tag-union spec had no representation metadata"),
                continuation,
            );
        }
        continuation = try self.lowerGeneratedTagUnionSpecValue(proc, context.worker, plan, spec, continuation);
        return continuation;
    }

    fn lowerGeneratedTagUnionSpecValue(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        worker: Plan.WorkerPlanId,
        plan: Plan.GeneratedParserTagUnionPlan,
        spec: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.result.store.getLocal(spec).layout_idx != self.layout_plan.generated_evidence.tag_union_spec) {
            boxyLowerInvariant("generated tag-union spec did not use its fixed evidence layout");
        }
        const record_types = self.plan.generatedParserTagUnionRecordTypes(plan.record_types);
        const evidence = try self.allocator.alloc(LIR.LocalId, record_types.len);
        defer self.allocator.free(evidence);
        for (evidence) |*local| local.* = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_names);

        const evidence_list = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_names_list);
        const runtime_id = try proc.addFrameLocal(.u64);
        var continuation = try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = spec,
            .fields = try self.result.store.addLocalSpan(&.{ evidence_list, runtime_id }),
            .next = next,
        } }, proc.derivedOrigin());
        continuation = try self.result.store.addCFStmt(.{ .assign_list = .{
            .target = evidence_list,
            .elems = try self.result.store.addLocalSpan(evidence),
            .next = continuation,
        } }, proc.derivedOrigin());
        continuation = try proc.assignIntLiteral(runtime_id, plan.runtime_id, continuation);
        var index = record_types.len;
        while (index > 0) {
            index -= 1;
            const record_rep = proc.repForTypeRef(record_types[index]);
            const fields = try self.generatedParserRecordFields(
                proc,
                worker,
                record_types[index],
                record_rep,
                .captures,
            );
            defer self.allocator.free(fields);
            continuation = try self.lowerGeneratedFieldNamesValue(proc, evidence[index], fields, continuation);
        }
        return continuation;
    }

    fn generatedParserTupleItems(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_rep: Plan.TypeRepId,
    ) Allocator.Error![]GeneratedParserTupleItem {
        const tuple_rep = proc.tupleRepForBoundary(shape_rep) orelse
            boxyLowerInvariant("generated tuple parser shape had no tuple representation");
        const rep = self.plan.representations.items[@backingInt(tuple_rep)];
        const children = self.plan.childSlice(rep.children);
        const items = try self.allocator.alloc(GeneratedParserTupleItem, children.len);
        const initialized = try self.allocator.alloc(bool, children.len);
        defer self.allocator.free(initialized);
        @memset(initialized, false);
        for (children) |child| {
            if (child.role != .tuple_elem) {
                boxyLowerInvariant("generated tuple parser representation had a non-tuple child");
            }
            const index = child.role.tuple_elem;
            if (index >= items.len or initialized[index]) {
                boxyLowerInvariant("generated tuple parser representation had invalid element indices");
            }
            initialized[index] = true;
            items[index] = .{
                .source_type = child.source_type,
                .rep = child.rep,
                .value = undefined,
            };
        }
        for (initialized) |is_initialized| {
            if (!is_initialized) boxyLowerInvariant("generated tuple parser representation had a missing element");
        }
        return items;
    }

    fn lowerGeneratedTupleFinish(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_rep: Plan.TypeRepId,
        value: LIR.LocalId,
        items: []const GeneratedParserTupleItem,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const fields = try self.allocator.alloc(LIR.LocalId, items.len);
        defer self.allocator.free(fields);
        const descriptor_fields = try self.allocator.alloc(ProcBodyBuilder.AggregateDescriptorField, items.len);
        defer self.allocator.free(descriptor_fields);
        for (items, fields, descriptor_fields) |item, *field, *descriptor_field| {
            field.* = item.value;
            descriptor_field.* = .{
                .local = item.value,
                .target_rep = item.rep,
                .source_rep = item.rep,
            };
        }
        const aggregate_desc = try proc.constructedAggregateDescriptorForFields(
            value,
            shape_rep,
            descriptor_fields,
        );
        defer aggregate_desc.deinit(self.allocator);
        var continuation = try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = value,
            .fields = try self.result.store.addLocalSpan(fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = success,
        } }, proc.derivedOrigin());
        continuation = try proc.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        return try proc.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    /// Locals that carry one generated list parser loop between iterations.
    const GeneratedListLoop = struct {
        /// The shape the checker validated the list protocol calls against:
        /// the `List` itself, or the `Set` parsed through it.
        subject_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        state_rep: Plan.TypeRepId,
        elem: Plan.RepChild,
        cursor: LIR.LocalId,
        acc: LIR.LocalId,
        /// Whether `parse_list_start` reported an element count; `remaining`
        /// is then the number of elements still to parse.
        counted: LIR.LocalId,
        remaining: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        join_id: LIR.JoinPointId,
        success: LIR.CFStmtId,
    };

    /// Enter the list loop with an empty list reserved to `capacity` elements
    /// (the reported count, or zero when uncounted).
    fn lowerGeneratedListStartJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        loop: GeneratedListLoop,
        list_desc: ?LIR.BoxyDescRef,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
        counted: bool,
        capacity: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        const initial_list = try proc.addFrameLocal(self.result.store.getLocal(loop.acc).layout_idx);
        if (list_desc) |desc| self.result.store.setLocalBoxyDesc(initial_list, desc);
        const counted_value = try proc.addFrameLocal(.bool);
        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = loop.join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(loop.remaining, capacity, continuation);
        continuation = try proc.setLocalInitializeJoinParam(loop.counted, counted_value, continuation);
        continuation = try proc.setLocalInitializeJoinParam(loop.acc, initial_list, continuation);
        continuation = try proc.setLocalInitializeJoinParamFromRep(loop.cursor, cursor, cursor_rep, continuation);
        continuation = try proc.assignBoolLiteral(counted_value, counted, continuation);
        return try proc.assignUnaryLowLevel(initial_list, .list_with_capacity, capacity, continuation);
    }

    /// Locals that carry one generated dictionary parser loop between entries.
    const GeneratedDictLoop = struct {
        subject_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        key_type: Plan.CheckedTypeIdentity,
        key_rep: Plan.TypeRepId,
        value_type: Plan.CheckedTypeIdentity,
        value_rep: Plan.TypeRepId,
        insert_call: Plan.GeneratedCodecCallPlan,
        cursor: LIR.LocalId,
        acc: LIR.LocalId,
        /// Whether `parse_dict_start` reported an entry count; `remaining`
        /// is then the number of entries still to parse.
        counted: LIR.LocalId,
        remaining: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        join_id: LIR.JoinPointId,
        success: LIR.CFStmtId,
    };

    /// Enter the dictionary loop with an empty dictionary reserved to
    /// `capacity` entries (the reported count, or zero when uncounted).
    fn lowerGeneratedDictStartJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        loop: GeneratedDictLoop,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
        counted: bool,
        capacity: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        const initial_dict = try proc.addFrameLocalForRep(loop.shape_rep);
        const counted_value = try proc.addFrameLocal(.bool);
        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = loop.join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(loop.remaining, capacity, continuation);
        continuation = try proc.setLocalInitializeJoinParam(loop.counted, counted_value, continuation);
        continuation = try proc.setLocalInitializeJoinParam(loop.acc, initial_dict, continuation);
        continuation = try proc.setLocalInitializeJoinParamFromRep(loop.cursor, cursor, cursor_rep, continuation);
        continuation = try proc.assignBoolLiteral(counted_value, counted, continuation);
        const with_capacity = proc.generatedCodecCallPlan(context.worker, loop.subject_type, "with_capacity", loop.subject_type);
        const capacity_types = self.plan.generatedCodecCallTypeSlice(with_capacity.arg_types);
        if (capacity_types.len != 1) boxyLowerInvariant("generated Dict.with_capacity call had unexpected arity");
        return try self.lowerGeneratedCodecCallLocalsInto(proc, with_capacity, initial_dict, &.{capacity}, continuation);
    }

    /// Finish with the accumulated dictionary and the state after it.
    fn lowerGeneratedDictDone(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        loop: GeneratedDictLoop,
        dict: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
    ) Allocator.Error!LIR.CFStmtId {
        const continuation = try proc.assignRepresentationBoundary(loop.rest, state, context.state_rep, state_rep, loop.success);
        return try proc.assignRepresentationBoundary(loop.value, dict, loop.shape_rep, loop.shape_rep, continuation);
    }

    /// Re-enter the dictionary loop with the grown dictionary. The counted
    /// state is unchanged; a counted entry end also updates `remaining`.
    fn lowerGeneratedDictLoopJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        loop: GeneratedDictLoop,
        dict: LIR.LocalId,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = loop.join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(loop.acc, dict, continuation);
        return try proc.setLocalInitializeJoinParamFromRep(loop.cursor, cursor, cursor_rep, continuation);
    }

    /// Call a format key method `(encoding, state) -> Try({ value, rest }, err)`.
    fn lowerGeneratedDictKeyString(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        call: Plan.GeneratedCodecCallPlan,
        state: LIR.LocalId,
        key: LIR.LocalId,
        key_rep: Plan.TypeRepId,
        after_key: LIR.LocalId,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const parsed = try beginGeneratedParserTryCall(proc, call);
        const payload = parsed.ok_payload;
        var continuation = try proc.generatedParserReadRecordField(after_key, context.state_rep, payload.local, payload.child, "rest", success);
        continuation = try proc.generatedParserReadRecordField(key, key_rep, payload.local, payload.child, "value", continuation);
        return try self.finishGeneratedParserTryCall(
            proc,
            parsed,
            &.{ context.encoding, state },
            context.result,
            context.result_rep,
            context.next,
            continuation,
        );
    }

    /// Match a key string against a closed unit-tag key's tag names; any
    /// other string is the format's checked `invalid_value` at `after_key`.
    fn lowerGeneratedDictUnitTagKey(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        key_rep: Plan.TypeRepId,
        key_string: LIR.LocalId,
        key: LIR.LocalId,
        after_key: LIR.LocalId,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const invalid_call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "invalid_value", null);
        const error_rep = proc.repForTypeRef(invalid_call.ret_type);
        const error_value = try proc.addFrameLocalForRep(error_rep);
        const result_err = proc.generatedParserTagVariant(context.result_rep, "Err");
        var dispatch = try proc.assignGeneratedParserTag(
            context.result,
            context.result_rep,
            result_err,
            error_value,
            error_rep,
            context.next,
        );
        dispatch = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            invalid_call,
            error_value,
            &.{ context.encoding, after_key },
            dispatch,
        );

        const variants = try self.generatedParserTagVariants(proc, key_rep);
        defer self.allocator.free(variants);
        var index = variants.len;
        while (index > 0) {
            index -= 1;
            const variant = variants[index];
            if (self.plan.childSlice(variant.variant.payloads).len != 0) {
                boxyLowerInvariant("generated Dict unit-tag key carried a payload");
            }
            const name = try proc.addFrameLocal(.str);
            const matches = try proc.addFrameLocal(.bool);
            const matched = try proc.assignGeneratedParserZeroTag(key, key_rep, variant, success);
            const branch = try proc.boolSwitchNoContinuation(matches, matched, dispatch);
            dispatch = try proc.assignBinaryLowLevel(matches, .str_is_eq, key_string, name, branch);
            dispatch = try proc.assignStringBytesLiteral(name, proc.tagVariantNameText(variant.variant), dispatch);
        }
        return dispatch;
    }

    fn lowerGeneratedListAfterElement(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        subject_type: Plan.CheckedTypeIdentity,
        elem: LIR.LocalId,
        cursor: LIR.LocalId,
        acc: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        join_id: LIR.JoinPointId,
        state: LIR.LocalId,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_list_after_item", subject_type);
        const step_rep = proc.repForTypeRef(call.ret_type);
        const step = try proc.addFrameLocalForRep(step_rep);
        const ok = proc.generatedParserTagVariant(step_rep, "Ok");
        const err = proc.generatedParserTagVariant(step_rep, "Err");
        const err_body = try proc.forwardGeneratedParserError(
            context.result,
            context.result_rep,
            step,
            err,
            context.next,
        );
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
        const event = ok_payload.local;
        const continue_variant = proc.generatedParserTagVariant(ok_payload.child.rep, "Continue");
        const done = proc.generatedParserTagVariant(ok_payload.child.rep, "Done");
        const continue_body = try self.lowerGeneratedListContinue(
            proc,
            cursor,
            acc,
            elem,
            join_id,
            event,
            continue_variant,
        );
        const done_body = try self.lowerGeneratedListDoneAfterElement(
            proc,
            context,
            acc,
            elem,
            value,
            rest,
            event,
            done,
            success,
        );
        const event_variants = [_]GeneratedParserTagVariant{ continue_variant, done };
        const event_bodies = [_]LIR.CFStmtId{ continue_body, done_body };
        const event_impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        var ok_body = try proc.generatedParserTagDispatch(event, ok_payload.child.rep, &event_variants, &event_bodies, event_impossible);
        ok_body = try proc.generatedParserReadTagPayload(step, ok, ok_payload, ok_body);
        const variants = [_]GeneratedParserTagVariant{ ok, err };
        const bodies = [_]LIR.CFStmtId{ ok_body, err_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const dispatch = try proc.generatedParserTagDispatch(step, step_rep, &variants, &bodies, impossible);
        return try self.lowerGeneratedCodecCallLocalsInto(proc, call, step, &.{ context.encoding, state }, dispatch);
    }

    fn lowerGeneratedListContinue(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        cursor: LIR.LocalId,
        acc: LIR.LocalId,
        elem: LIR.LocalId,
        join_id: LIR.JoinPointId,
        event: LIR.LocalId,
        variant: GeneratedParserTagVariant,
    ) Allocator.Error!LIR.CFStmtId {
        const payload = try proc.generatedParserSingleTagPayloadLocal(variant);
        const next_acc = try proc.addFrameLocal(self.result.store.getLocal(acc).layout_idx);
        if (self.result.store.getLocal(acc).boxy_desc) |desc| self.result.store.setLocalBoxyDesc(next_acc, desc);
        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(acc, next_acc, continuation);
        continuation = try proc.setLocalInitializeJoinParamFromRep(cursor, payload.local, payload.child.rep, continuation);
        continuation = try proc.assignListAppendGrowingMovingElement(next_acc, acc, elem, continuation);
        return try proc.generatedParserReadTagPayload(event, variant, payload, continuation);
    }

    fn lowerGeneratedListDone(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        shape_rep: Plan.TypeRepId,
        acc: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        event: LIR.LocalId,
        variant: GeneratedParserTagVariant,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const payload = try proc.generatedParserSingleTagPayloadLocal(variant);
        var continuation = try proc.assignRepresentationBoundary(
            rest,
            payload.local,
            context.state_rep,
            payload.child.rep,
            success,
        );
        continuation = try proc.assignRepresentationBoundary(value, acc, shape_rep, shape_rep, continuation);
        return try proc.generatedParserReadTagPayload(event, variant, payload, continuation);
    }

    fn lowerGeneratedListDoneAfterElement(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserShapeContext,
        acc: LIR.LocalId,
        elem: LIR.LocalId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        event: LIR.LocalId,
        variant: GeneratedParserTagVariant,
        success: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const payload = try proc.generatedParserSingleTagPayloadLocal(variant);
        var continuation = try proc.assignRepresentationBoundary(
            rest,
            payload.local,
            context.state_rep,
            payload.child.rep,
            success,
        );
        continuation = try proc.assignListAppendGrowingMovingElement(value, acc, elem, continuation);
        return try proc.generatedParserReadTagPayload(event, variant, payload, continuation);
    }

    const GeneratedParserTagVariant = struct {
        /// The representation the variant was looked up through. For a
        /// nominal such as `Try` its payload children are the declaration's
        /// formals, which this boundary maps to the actual payloads.
        boundary_rep: Plan.TypeRepId,
        /// The root tag domain whose descriptor describes the runtime value.
        tag_rep: Plan.TypeRepId,
        /// The row node that explicitly declares this variant.
        owner_rep: Plan.TypeRepId,
        index: u32,
        variant: Plan.TagVariant,
    };

    const GeneratedParserRecordField = struct {
        name_module: checked.ModuleId,
        name: names.RecordFieldLabelId,
        source_type: Plan.CheckedTypeIdentity,
        rep: Plan.TypeRepId,
        parse_type: Plan.CheckedTypeIdentity,
        parse_rep: Plan.TypeRepId,
        kind: Plan.GeneratedParserFieldKind,
        renamed: LIR.LocalId,
        payload: LIR.LocalId,
        index: usize,
    };

    const GeneratedParserRecordContext = struct {
        worker: Plan.WorkerPlanId,
        encoding_type: Plan.CheckedTypeIdentity,
        encoding: LIR.LocalId,
        shape_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        state_type: Plan.CheckedTypeIdentity,
        state_rep: Plan.TypeRepId,
        cursor: LIR.LocalId,
        /// Whether `parse_record_start` reported an entry count. A `Done`
        /// event also sets it (with `remaining` zero), so the loop head's
        /// single "counted and nothing remaining" test is the only finish site.
        counted: LIR.LocalId,
        remaining: LIR.LocalId,
        /// Set after a field value or skipped entry is consumed: the loop head
        /// then ends that entry (counting it down, or asking the format via
        /// `parse_record_after_field`) before reading the next event.
        entry_pending: LIR.LocalId,
        evidence: LIR.LocalId,
        fields: []GeneratedParserRecordField,
        presence: []LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
        value: LIR.LocalId,
        rest: LIR.LocalId,
        success: LIR.CFStmtId,
    };

    const GeneratedParserFieldNamesSource = union(enum) {
        captures,
        tag_union_spec: struct {
            spec: LIR.LocalId,
            plan: Plan.GeneratedParserTagUnionPlan,
        },
    };

    fn lowerGeneratedRecordParserRuntimeInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        encoding_type: Plan.CheckedTypeIdentity,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = proc.worker_layout.worker;
        const worker_plan = self.plan.workers.items[@backingInt(worker)];
        const worker_fn = proc.functionChildrenForRep(worker_plan.rep) orelse
            boxyLowerInvariant("generated record parser worker was not a function");
        if (proc.arg_locals.items.len < 1) boxyLowerInvariant("generated record parser runtime had no state argument");
        if (proc.erased_capture_locals.items.len == 0) boxyLowerInvariant("generated record parser runtime had no bound captures");

        const shape_rep = proc.repForTypeRef(source.shape);
        const parse_call = proc.generatedCodecCallPlan(worker, encoding_type, "parse_record_field", source.shape);
        const parse_arg_types = self.plan.generatedCodecCallTypeSlice(parse_call.arg_types);
        if (parse_arg_types.len != 3) boxyLowerInvariant("generated parse_record_field call did not have three arguments");
        const state_rep = proc.repForTypeRef(parse_arg_types[2]);
        const value = try proc.addGeneratedParserOutputLocalForRep(shape_rep);
        const rest = try proc.addGeneratedParserOutputLocalForRep(state_rep);
        const shape_context = GeneratedParserShapeContext{
            .worker = worker,
            .encoding_type = encoding_type,
            .encoding = proc.erased_capture_locals.items[0],
            .state_type = parse_arg_types[2],
            .state_rep = state_rep,
            .result = target,
            .result_rep = worker_fn.ret,
            .next = next,
        };
        const success = try self.lowerGeneratedParserSuccess(proc, shape_context, value, shape_rep, rest);
        return try self.lowerGeneratedRecordFromState(
            proc,
            shape_context,
            source.shape,
            shape_rep,
            proc.arg_locals.items[0],
            value,
            rest,
            success,
            .captures,
        );
    }

    fn generatedParserRecordFields(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        worker: Plan.WorkerPlanId,
        record_type: Plan.CheckedTypeIdentity,
        shape_rep: Plan.TypeRepId,
        field_names_source: GeneratedParserFieldNamesSource,
    ) Allocator.Error![]GeneratedParserRecordField {
        const record_rep = proc.recordRepForBoundary(shape_rep);
        if (record_rep == null) {
            if (self.plan.representations.items[@backingInt(shape_rep)].kind != .empty_record) {
                boxyLowerInvariant("generated record parser shape had no record representation");
            }
            return try self.allocator.alloc(GeneratedParserRecordField, 0);
        }
        const record = self.plan.representations.items[@backingInt(record_rep.?)];
        const children = self.plan.childSlice(record.children);
        var field_count: usize = 0;
        for (children) |child| {
            if (child.role == .record_field) {
                field_count += 1;
            } else if (child.role == .record_ext) {
                proc.requireEmptyRecordExtension(child.rep);
            } else {
                boxyLowerInvariant("generated record parser representation had a non-record child");
            }
        }
        const fields = try self.allocator.alloc(GeneratedParserRecordField, field_count);
        const record_view = procedureModuleById(self.modules, record.source_type.module);

        var out_index: usize = 0;
        for (children) |child| {
            if (child.role == .record_ext) continue;
            if (child.role != .record_field) unreachable;
            const label = child.role.record_field;
            var capture_local_index: usize = 1;
            var renamed: ?LIR.LocalId = null;
            var parse_type: ?Plan.CheckedTypeIdentity = null;
            var kind: Plan.GeneratedParserFieldKind = .required;
            for (self.plan.generated_parser_field_captures.items) |capture| {
                if (capture.worker != worker) continue;
                const capture_view = procedureModuleById(self.modules, capture.field_module);
                if (planTypeRefEql(capture.record_type, record_type) and
                    Plan.recordFieldNameMatches(viewNames(record_view), label, viewNames(capture_view), capture.field_name))
                {
                    if (renamed != null) boxyLowerInvariant("generated parser record field had duplicate renamed captures");
                    renamed = switch (field_names_source) {
                        .captures => blk: {
                            if (capture_local_index >= proc.erased_capture_locals.items.len) {
                                boxyLowerInvariant("generated parser field capture exceeded bound erased captures");
                            }
                            break :blk proc.erased_capture_locals.items[capture_local_index];
                        },
                        .tag_union_spec => try proc.addFrameLocal(.str),
                    };
                    parse_type = capture.parse_type;
                    kind = capture.parser_kind;
                }
                capture_local_index += 1;
            }
            fields[out_index] = .{
                .name_module = record.source_type.module,
                .name = label,
                .source_type = child.source_type,
                .rep = child.rep,
                .parse_type = parse_type orelse
                    boxyLowerInvariant("generated parser record field had no planned parse type"),
                .parse_rep = proc.repForTypeRef(parse_type orelse
                    boxyLowerInvariant("generated parser record field had no planned parse representation")),
                .kind = kind,
                .renamed = renamed orelse boxyLowerInvariant("generated parser record field had no renamed capture"),
                .payload = undefined,
                .index = out_index,
            };
            out_index += 1;
        }
        if (out_index != fields.len) boxyLowerInvariant("generated parser record field count changed during lowering");
        return fields;
    }

    fn lowerGeneratedRecordFieldNamesSource(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: GeneratedParserFieldNamesSource,
        shape_rep: Plan.TypeRepId,
        fields: []const GeneratedParserRecordField,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const tag_source = switch (source) {
            .captures => return next,
            .tag_union_spec => |tag_source| tag_source,
        };
        if (fields.len == 0) return next;

        const record_rep = proc.recordRepForBoundary(shape_rep) orelse
            boxyLowerInvariant("generated tag-union record evidence had no record representation");
        const record_type = self.plan.representations.items[@backingInt(record_rep)].source_type;
        const record_types = self.plan.generatedParserTagUnionRecordTypes(tag_source.plan.record_types);
        var maybe_record_index: ?usize = null;
        for (record_types, 0..) |candidate, index| {
            if (!planTypeRefEql(candidate, record_type)) continue;
            if (maybe_record_index != null) {
                boxyLowerInvariant("generated tag-union spec contained duplicate record evidence");
            }
            maybe_record_index = index;
        }
        const record_index_value = maybe_record_index orelse
            boxyLowerInvariant("generated tag-union spec was missing record evidence");

        const field_names = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_names);
        const evidence_list = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_names_list);
        const items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        var continuation = next;
        var index = fields.len;
        while (index > 0) {
            index -= 1;
            const field = try proc.addFrameLocal(self.layout_plan.generated_evidence.field);
            const field_index = try proc.addFrameLocal(.u64);
            continuation = try self.result.store.addCFStmt(.{ .assign_ref = .{
                .target = fields[index].renamed,
                .op = .{ .field = .{ .source = field, .field_idx = 0 } },
                .next = continuation,
            } }, proc.derivedOrigin());
            continuation = try proc.assignBinaryLowLevel(field, .list_get_unsafe, items, field_index, continuation);
            continuation = try proc.assignIntLiteral(field_index, @intCast(index), continuation);
        }
        continuation = try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = items,
            .op = .{ .field = .{ .source = field_names, .field_idx = 0 } },
            .next = continuation,
        } }, proc.derivedOrigin());
        const record_index = try proc.addFrameLocal(.u64);
        continuation = try proc.assignBinaryLowLevel(
            field_names,
            .list_get_unsafe,
            evidence_list,
            record_index,
            continuation,
        );
        continuation = try proc.assignIntLiteral(record_index, @intCast(record_index_value), continuation);
        return try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = evidence_list,
            .op = .{ .field = .{ .source = tag_source.spec, .field_idx = 0 } },
            .next = continuation,
        } }, proc.derivedOrigin());
    }

    const GeneratedParserTryCall = struct {
        /// The format method producing the step; null for a step produced by
        /// calling a format-supplied callback.
        call: ?Plan.GeneratedCodecCallPlan,
        step: LIR.LocalId,
        step_rep: Plan.TypeRepId,
        ok: GeneratedParserTagVariant,
        err: GeneratedParserTagVariant,
        ok_payload: ProcBodyBuilder.GeneratedParserTagPayload,
    };

    /// Prepare a call to a generated-parser format method returning
    /// `Try(payload, err)`; `ok_payload.local` names the `Ok` payload that
    /// `finishGeneratedParserTryCall`'s success body may read.
    fn beginGeneratedParserTryCall(
        proc: *ProcBodyBuilder,
        call: Plan.GeneratedCodecCallPlan,
    ) Allocator.Error!GeneratedParserTryCall {
        var step = try beginGeneratedParserTryStep(proc, proc.repForTypeRef(call.ret_type));
        step.call = call;
        return step;
    }

    /// Prepare a `Try(payload, err)` step whose producer the caller emits.
    fn beginGeneratedParserTryStep(
        proc: *ProcBodyBuilder,
        step_rep: Plan.TypeRepId,
    ) Allocator.Error!GeneratedParserTryCall {
        const ok = proc.generatedParserTagVariant(step_rep, "Ok");
        return .{
            .call = null,
            .step = try proc.addFrameLocalForRep(step_rep),
            .step_rep = step_rep,
            .ok = ok,
            .err = proc.generatedParserTagVariant(step_rep, "Err"),
            .ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok),
        };
    }

    /// Emit the prepared call: `Err` is forwarded into the parser result
    /// `target` before `next`, and `Ok` reads its payload and runs `ok_body`.
    fn finishGeneratedParserTryCall(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        try_call: GeneratedParserTryCall,
        args: []const LIR.LocalId,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
        ok_body: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const call = try_call.call orelse boxyLowerInvariant("generated parser try call had no planned format method");
        const dispatch = try self.dispatchGeneratedParserTryStep(proc, try_call, target, target_rep, next, ok_body);
        return try self.lowerGeneratedCodecCallLocalsInto(proc, call, try_call.step, args, dispatch);
    }

    /// Branch on a produced step: `Err` is forwarded into the parser result
    /// `target` before `next`, and `Ok` reads its payload and runs `ok_body`.
    fn dispatchGeneratedParserTryStep(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        try_call: GeneratedParserTryCall,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
        ok_body: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const err_body = try proc.forwardGeneratedParserError(target, target_rep, try_call.step, try_call.err, next);
        const read_ok = try proc.generatedParserReadTagPayload(try_call.step, try_call.ok, try_call.ok_payload, ok_body);
        const variants = [_]GeneratedParserTagVariant{ try_call.ok, try_call.err };
        const bodies = [_]LIR.CFStmtId{ read_ok, err_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        return try proc.generatedParserTagDispatch(try_call.step, try_call.step_rep, &variants, &bodies, impossible);
    }

    /// `parse_record_start` selects counted or uncounted iteration and the
    /// first cursor; every other loop slot starts empty.
    fn lowerGeneratedRecordStart(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        state: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_record_start", context.shape_type);
        const start = try beginGeneratedParserTryCall(proc, call);
        const event = start.ok_payload;
        const counted_variant = proc.generatedParserTagVariant(event.child.rep, "Counted");
        const uncounted_variant = proc.generatedParserTagVariant(event.child.rep, "Uncounted");

        const counted_payload = try proc.generatedParserSingleTagPayloadLocal(counted_variant);
        const counted_len = try proc.addFrameLocal(.u64);
        const counted_rest = try proc.addFrameLocalForRep(context.state_rep);
        var counted_body = try self.lowerGeneratedRecordLoopJump(proc, context, counted_rest, context.state_rep, true, counted_len, false);
        counted_body = try proc.generatedParserReadRecordField(counted_rest, context.state_rep, counted_payload.local, counted_payload.child, "rest", counted_body);
        counted_body = try proc.generatedParserReadRecordField(counted_len, proc.repForTypeRef(try proc.generatedParserRecordFieldType(counted_payload.child.source_type, "len")), counted_payload.local, counted_payload.child, "len", counted_body);
        counted_body = try proc.generatedParserReadTagPayload(event.local, counted_variant, counted_payload, counted_body);

        const uncounted_payload = try proc.generatedParserSingleTagPayloadLocal(uncounted_variant);
        const zero = try proc.addFrameLocal(.u64);
        var uncounted_body = try self.lowerGeneratedRecordLoopJump(proc, context, uncounted_payload.local, uncounted_payload.child.rep, false, zero, false);
        uncounted_body = try proc.assignIntLiteral(zero, 0, uncounted_body);
        uncounted_body = try proc.generatedParserReadTagPayload(event.local, uncounted_variant, uncounted_payload, uncounted_body);

        const variants = [_]GeneratedParserTagVariant{ counted_variant, uncounted_variant };
        const bodies = [_]LIR.CFStmtId{ counted_body, uncounted_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const ok_body = try proc.generatedParserTagDispatch(event.local, event.child.rep, &variants, &bodies, impossible);
        return try self.finishGeneratedParserTryCall(
            proc,
            start,
            &.{ context.encoding, state },
            context.target,
            context.target_rep,
            context.next,
            ok_body,
        );
    }

    /// Re-enter the record loop with the given cursor and control slots.
    /// Field payloads and presence words keep their current values.
    fn lowerGeneratedRecordLoopJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
        counted: bool,
        remaining: LIR.LocalId,
        entry_pending: bool,
    ) Allocator.Error!LIR.CFStmtId {
        const counted_value = try proc.addFrameLocal(.bool);
        const pending_value = try proc.addFrameLocal(.bool);
        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = context.join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(context.entry_pending, pending_value, continuation);
        continuation = try proc.setLocalInitializeJoinParam(context.remaining, remaining, continuation);
        continuation = try proc.setLocalInitializeJoinParam(context.counted, counted_value, continuation);
        continuation = try proc.setLocalInitializeJoinParamFromRep(context.cursor, cursor, cursor_rep, continuation);
        continuation = try proc.assignBoolLiteral(pending_value, entry_pending, continuation);
        return try proc.assignBoolLiteral(counted_value, counted, continuation);
    }

    /// Re-enter the loop after one entry of a counted record: its remaining
    /// count drops by one. `cursor` already follows the entry.
    fn lowerGeneratedRecordCountedEntryJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
    ) Allocator.Error!LIR.CFStmtId {
        const one = try proc.addFrameLocal(.u64);
        const next_remaining = try proc.addFrameLocal(.u64);
        var continuation = try self.lowerGeneratedRecordLoopJump(proc, context, cursor, cursor_rep, true, next_remaining, false);
        continuation = try proc.assignBinaryLowLevel(next_remaining, .num_int_sub_wrap, context.remaining, one, continuation);
        return try proc.assignIntLiteral(one, 1, continuation);
    }

    /// Re-enter the loop once the format reported that the record ended:
    /// counted with nothing remaining is the loop head's finish condition.
    fn lowerGeneratedRecordDoneJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
    ) Allocator.Error!LIR.CFStmtId {
        const zero = try proc.addFrameLocal(.u64);
        const continuation = try self.lowerGeneratedRecordLoopJump(proc, context, cursor, cursor_rep, true, zero, false);
        return try proc.assignIntLiteral(zero, 0, continuation);
    }

    /// End the entry whose value (or skip) just completed: a counted record
    /// counts it down, and an uncounted one asks `parse_record_after_field`
    /// whether another entry follows.
    fn lowerGeneratedRecordEntryEnd(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
    ) Allocator.Error!LIR.CFStmtId {
        const counted_body = try self.lowerGeneratedRecordCountedEntryJump(proc, context, context.cursor, context.state_rep);

        const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "parse_record_after_field", context.shape_type);
        const after = try beginGeneratedParserTryCall(proc, call);
        const event = after.ok_payload;
        const continue_variant = proc.generatedParserTagVariant(event.child.rep, "Continue");
        const done_variant = proc.generatedParserTagVariant(event.child.rep, "Done");
        const continue_payload = try proc.generatedParserSingleTagPayloadLocal(continue_variant);
        const done_payload = try proc.generatedParserSingleTagPayloadLocal(done_variant);
        const variants = [_]GeneratedParserTagVariant{ continue_variant, done_variant };
        const bodies = [_]LIR.CFStmtId{
            try proc.generatedParserReadTagPayload(
                event.local,
                continue_variant,
                continue_payload,
                try self.lowerGeneratedRecordLoopJump(proc, context, continue_payload.local, continue_payload.child.rep, false, context.remaining, false),
            ),
            try proc.generatedParserReadTagPayload(
                event.local,
                done_variant,
                done_payload,
                try self.lowerGeneratedRecordDoneJump(proc, context, done_payload.local, done_payload.child.rep),
            ),
        };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const ok_body = try proc.generatedParserTagDispatch(event.local, event.child.rep, &variants, &bodies, impossible);
        const uncounted_body = try self.finishGeneratedParserTryCall(
            proc,
            after,
            &.{ context.encoding, context.cursor },
            context.target,
            context.target_rep,
            context.next,
            ok_body,
        );
        return try proc.boolSwitchNoContinuation(context.counted, counted_body, uncounted_body);
    }

    /// `Continue` means the format consumed a whole entry itself and the
    /// cursor already sits at the next entry boundary, so no entry end runs.
    fn lowerGeneratedRecordContinueEvent(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        event: LIR.LocalId,
        variant: GeneratedParserTagVariant,
    ) Allocator.Error!LIR.CFStmtId {
        const payload = try proc.generatedParserSingleTagPayloadLocal(variant);
        const counted_body = try self.lowerGeneratedRecordCountedEntryJump(proc, context, payload.local, payload.child.rep);
        const uncounted_body = try self.lowerGeneratedRecordLoopJump(proc, context, payload.local, payload.child.rep, false, context.remaining, false);
        const choose = try proc.boolSwitchNoContinuation(context.counted, counted_body, uncounted_body);
        return try proc.generatedParserReadTagPayload(event, variant, payload, choose);
    }

    fn lowerGeneratedRecordLoopUpdate(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        field_index: usize,
        value: LIR.LocalId,
        rest: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        const word_index = field_index / 64;
        const mask_value = @as(u64, 1) << @intCast(field_index % 64);
        const mask = try proc.addFrameLocal(.u64);
        const next_presence = try proc.addFrameLocal(.u64);
        var continuation = try self.lowerGeneratedRecordEntryPendingJump(proc, context, rest, context.state_rep);
        continuation = try proc.setLocalInitializeJoinParam(context.presence[word_index], next_presence, continuation);
        continuation = try proc.setLocalInitializeJoinParam(context.fields[field_index].payload, value, continuation);
        continuation = try proc.assignBinaryLowLevel(
            next_presence,
            .num_bitwise_or,
            context.presence[word_index],
            mask,
            continuation,
        );
        return try proc.assignIntLiteral(mask, @intCast(mask_value), continuation);
    }

    /// Re-enter the loop after an entry's value was consumed, leaving the
    /// counted state as it is and marking the entry end as pending.
    fn lowerGeneratedRecordEntryPendingJump(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        cursor: LIR.LocalId,
        cursor_rep: Plan.TypeRepId,
    ) Allocator.Error!LIR.CFStmtId {
        const pending_value = try proc.addFrameLocal(.bool);
        var continuation = try self.result.store.addCFStmt(.{ .jump = .{ .target = context.join_id } }, proc.derivedOrigin());
        continuation = try proc.setLocalInitializeJoinParam(context.entry_pending, pending_value, continuation);
        continuation = try proc.setLocalInitializeJoinParamFromRep(context.cursor, cursor, cursor_rep, continuation);
        return try proc.assignBoolLiteral(pending_value, true, continuation);
    }

    fn lowerGeneratedSkipRecordField(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        rest: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        const call = proc.generatedCodecCallPlan(context.worker, context.encoding_type, "skip_record_field", null);
        const skipped_rep = proc.repForTypeRef(call.ret_type);
        const skipped = try proc.addFrameLocalForRep(skipped_rep);
        const ok = proc.generatedParserTagVariant(skipped_rep, "Ok");
        const err = proc.generatedParserTagVariant(skipped_rep, "Err");
        const err_body = try proc.forwardGeneratedParserError(
            context.target,
            context.target_rep,
            skipped,
            err,
            context.next,
        );
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);
        var success = try self.lowerGeneratedRecordEntryPendingJump(proc, context, ok_payload.local, ok_payload.child.rep);
        success = try proc.generatedParserReadTagPayload(skipped, ok, ok_payload, success);
        const variants = [_]GeneratedParserTagVariant{ ok, err };
        const bodies = [_]LIR.CFStmtId{ success, err_body };
        const impossible = try self.result.store.addCFStmt(.runtime_error, proc.derivedOrigin());
        const dispatch = try proc.generatedParserTagDispatch(skipped, skipped_rep, &variants, &bodies, impossible);
        return try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            skipped,
            &.{ context.encoding, rest },
            dispatch,
        );
    }

    fn lowerGeneratedRecordDoneEvent(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        event: LIR.LocalId,
        variant: GeneratedParserTagVariant,
    ) Allocator.Error!LIR.CFStmtId {
        const payload = try proc.generatedParserSingleTagPayloadLocal(variant);
        const done = try self.lowerGeneratedRecordDoneJump(proc, context, payload.local, payload.child.rep);
        return try proc.generatedParserReadTagPayload(event, variant, payload, done);
    }

    /// The single record-construction site, reached from the loop head once
    /// the record has ended. Every absent field is resolved before any
    /// payload is consumed.
    fn lowerGeneratedRecordFinish(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try self.lowerGeneratedFinishedRecord(proc, context, context.cursor);
        var index = context.fields.len;
        while (index > 0) {
            index -= 1;
            const missing = try self.lowerGeneratedMissingRecordField(proc, context, index, continuation);
            continuation = try self.result.store.addCFStmt(.{ .switch_initialized_payload = .{
                .cond = context.presence[index / 64],
                .cond_mask = @as(u64, 1) << @intCast(index % 64),
                .payload = context.fields[index].payload,
                .uninitialized_is_cold = switch (context.fields[index].kind) {
                    .required, .undetermined_slot => true,
                    .missing_try, .optional_slot, .defaulted => false,
                },
                .initialized_branch = continuation,
                .uninitialized_branch = missing,
            } }, proc.derivedOrigin());
        }
        return continuation;
    }

    fn lowerGeneratedMissingRecordField(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        field_index: usize,
        present_continuation: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const field = context.fields[field_index];
        switch (field.kind) {
            .required, .undetermined_slot => {},
            .missing_try => |error_type| {
                const error_rep = proc.repForTypeRef(error_type);
                const error_value = try proc.addFrameLocalForRep(error_rep);
                const continuation = try proc.assignGeneratedParserTag(
                    field.payload,
                    field.rep,
                    proc.generatedParserTagVariant(field.rep, "Err"),
                    error_value,
                    error_rep,
                    present_continuation,
                );
                return try proc.assignGeneratedParserZeroTag(
                    error_value,
                    error_rep,
                    proc.generatedParserTagVariant(error_rep, "Missing"),
                    continuation,
                );
            },
            .optional_slot => return try proc.lowerOptionalSlotMissingInto(field.payload, field.rep, present_continuation),
            .defaulted => |defaulted| return try proc.lowerDefaultedRecordFieldIntoFromModule(
                procedureModuleById(self.modules, defaulted.module),
                field.payload,
                defaulted.default,
                field.source_type,
                present_continuation,
            ),
        }

        const target_err = proc.generatedParserTagVariant(context.target_rep, "Err");
        const error_rep = proc.repForTypeRef(self.plan.generatedParserMissingRequiredField(context.worker));
        const error_value = try proc.addFrameLocalForRep(error_rep);
        const missing = proc.generatedParserTagVariant(error_rep, "MissingRequiredField");
        const missing_payloads = self.plan.childSlice(missing.variant.payloads);
        if (missing_payloads.len != 1) boxyLowerInvariant("MissingRequiredField did not carry one Str payload");
        const continuation = try proc.assignGeneratedParserTag(
            context.target,
            context.target_rep,
            target_err,
            error_value,
            error_rep,
            context.next,
        );
        return try proc.assignGeneratedParserTag(
            error_value,
            error_rep,
            missing,
            field.renamed,
            missing_payloads[0].rep,
            continuation,
        );
    }

    fn lowerGeneratedFinishedRecord(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        context: GeneratedParserRecordContext,
        rest: LIR.LocalId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try proc.assignRepresentationBoundary(
            context.rest,
            rest,
            context.state_rep,
            context.state_rep,
            context.success,
        );
        const shape_fields = try self.allocator.alloc(LIR.LocalId, context.fields.len);
        defer self.allocator.free(shape_fields);
        const descriptor_fields = try self.allocator.alloc(ProcBodyBuilder.AggregateDescriptorField, context.fields.len);
        defer self.allocator.free(descriptor_fields);
        for (context.fields, 0..) |field, index| {
            shape_fields[index] = field.payload;
            descriptor_fields[index] = .{
                .local = field.payload,
                .target_rep = field.rep,
                .source_rep = field.rep,
            };
        }
        const aggregate_desc = try proc.constructedAggregateDescriptorForFields(
            context.value,
            context.shape_rep,
            descriptor_fields,
        );
        defer aggregate_desc.deinit(self.allocator);
        continuation = try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = context.value,
            .fields = try self.result.store.addLocalSpan(shape_fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = continuation,
        } }, proc.derivedOrigin());
        continuation = try proc.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        return try proc.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    fn lowerGeneratedFieldNamesValue(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        evidence: LIR.LocalId,
        fields: []const GeneratedParserRecordField,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const field_values = try self.allocator.alloc(LIR.LocalId, fields.len);
        defer self.allocator.free(field_values);
        const lengths = try self.allocator.alloc(LIR.LocalId, fields.len);
        defer self.allocator.free(lengths);
        for (field_values) |*local| local.* = try proc.addFrameLocal(self.layout_plan.generated_evidence.field);
        for (lengths) |*local| local.* = try proc.addFrameLocal(.u64);

        const items = try proc.addFrameLocal(self.layout_plan.generated_evidence.field_list);
        const shortest = try proc.addFrameLocal(.u64);
        const longest = try proc.addFrameLocal(.u64);
        var continuation = try self.result.store.addCFStmt(.{ .assign_struct = .{
            .target = evidence,
            .fields = try self.result.store.addLocalSpan(&.{ items, shortest, longest }),
            .next = next,
        } }, proc.derivedOrigin());
        continuation = try self.result.store.addCFStmt(.{ .assign_list = .{
            .target = items,
            .elems = try self.result.store.addLocalSpan(field_values),
            .next = continuation,
        } }, proc.derivedOrigin());

        if (fields.len == 0) {
            continuation = try proc.assignIntLiteral(longest, 0, continuation);
            continuation = try proc.assignIntLiteral(shortest, 0, continuation);
        } else {
            const shortest_values = try self.allocator.alloc(LIR.LocalId, fields.len);
            defer self.allocator.free(shortest_values);
            const longest_values = try self.allocator.alloc(LIR.LocalId, fields.len);
            defer self.allocator.free(longest_values);
            shortest_values[0] = lengths[0];
            longest_values[0] = lengths[0];
            for (1..fields.len) |index| {
                shortest_values[index] = if (index + 1 == fields.len) shortest else try proc.addFrameLocal(.u64);
                longest_values[index] = if (index + 1 == fields.len) longest else try proc.addFrameLocal(.u64);
            }
            if (fields.len == 1) {
                continuation = try proc.assignLocalRef(longest, lengths[0], continuation);
                continuation = try proc.assignLocalRef(shortest, lengths[0], continuation);
            } else {
                var index = fields.len;
                while (index > 1) {
                    index -= 1;
                    continuation = try proc.assignGeneratedParserU64Select(
                        longest_values[index],
                        lengths[index],
                        longest_values[index - 1],
                        .num_is_gt,
                        continuation,
                    );
                }
                index = fields.len;
                while (index > 1) {
                    index -= 1;
                    continuation = try proc.assignGeneratedParserU64Select(
                        shortest_values[index],
                        lengths[index],
                        shortest_values[index - 1],
                        .num_is_lt,
                        continuation,
                    );
                }
            }
        }

        var index = fields.len;
        while (index > 0) {
            index -= 1;
            const field_index = try proc.addFrameLocal(.u64);
            continuation = try self.result.store.addCFStmt(.{ .assign_struct = .{
                .target = field_values[index],
                .fields = try self.result.store.addLocalSpan(&.{ fields[index].renamed, field_index, lengths[index] }),
                .next = continuation,
            } }, proc.derivedOrigin());
            continuation = try proc.assignIntLiteral(field_index, @intCast(index), continuation);
            continuation = try proc.assignUnaryLowLevel(lengths[index], .str_count_utf8_bytes, fields[index].renamed, continuation);
        }
        return continuation;
    }

    fn lowerGeneratedCodecCallLocalsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        call: Plan.GeneratedCodecCallPlan,
        target: LIR.LocalId,
        args: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != args.len) boxyLowerInvariant("generated codec call argument arity disagreed with its plan");
        return try proc.lowerWorkerCallLocalsInto(
            target,
            call.ret_type,
            arg_types,
            arg_types,
            args,
            null,
            null,
            null,
            call.worker,
            self.plan.directCallHiddenDescriptorArgSlice(call.hidden_desc_args),
            self.plan.directCallHiddenDictionaryArgSlice(call.hidden_dict_args),
            next,
        );
    }

    fn lowerGeneratedCodecConstructorInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const constructor_worker = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const constructor_fn = proc.functionChildrenForRep(constructor_worker.rep) orelse
            boxyLowerInvariant("generated codec constructor was not a function");
        if (constructor_fn.arg_count != 1 or proc.arg_locals.items.len < 1) {
            boxyLowerInvariant("generated codec constructor did not bind one encoding argument");
        }
        const constructor_children = self.plan.childSlice(self.plan.representations.items[@backingInt(constructor_fn.rep)].children);
        const encoding_child = constructor_children[constructor_fn.args_start];
        const encoding_type = encoding_child.source_type;
        const encoding = proc.arg_locals.items[0];
        try proc.markLocalDescriptorForRep(encoding, encoding_child.rep);
        const runtime_worker_id = self.plan.generatedCodecRuntimeWorker(proc.worker_layout.worker) orelse
            boxyLowerInvariant("generated codec constructor had no planned runtime worker");
        const runtime_worker = self.plan.workers.items[@backingInt(runtime_worker_id)];
        const runtime_fn = proc.functionChildrenForRep(runtime_worker.rep) orelse
            boxyLowerInvariant("generated codec runtime worker was not a function");
        const captures = self.plan.erasedCaptureSlice(runtime_worker.erased_captures);
        if (captures.len == 0 or captures[0].kind != .captured_value or
            !planTypeRefEql(captures[0].source_type, encoding_type))
        {
            boxyLowerInvariant("generated codec runtime did not have its exact encoding capture");
        }

        const runtime_layout = self.layout_plan.workerLayoutFor(runtime_worker_id);
        const erased_proc = try self.reserveErasedWorkerProc(runtime_worker_id);
        const result_desc = try proc.exactCallResultDescriptorRef(runtime_fn.ret);
        var captured_value_count: usize = 0;
        for (captures) |capture| {
            if (capture.kind == .captured_value) captured_value_count += 1;
        }
        const captured_values = try self.allocator.alloc(LIR.LocalId, captured_value_count);
        defer self.allocator.free(captured_values);
        captured_values[0] = encoding;
        var field_capture_index: usize = 1;
        for (self.plan.generated_parser_field_captures.items) |field_capture| {
            if (field_capture.worker != runtime_worker_id) continue;
            if (field_capture_index >= captured_values.len) {
                boxyLowerInvariant("generated parser capture plan exceeded runtime capture layout");
            }
            captured_values[field_capture_index] = try proc.addFrameLocalForRep(
                proc.repForTypeRef(field_capture.source_type),
            );
            field_capture_index += 1;
        }
        if (field_capture_index != captured_values.len) {
            boxyLowerInvariant("generated parser capture plan did not fill runtime capture layout");
        }
        var descriptor_initializers = std.ArrayList(ProcBodyBuilder.DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.allocator);
        var dictionary_initializers = std.ArrayList(ProcBodyBuilder.DictionaryArgLocal).empty;
        defer dictionary_initializers.deinit(self.allocator);
        const capture_fields = try self.generatedCodecCaptureValues(proc, runtime_worker_id, captures, captured_values, &descriptor_initializers, &dictionary_initializers);
        defer self.allocator.free(capture_fields);

        const boundary = try self.generatedCallablePackBoundary(
            proc,
            target,
            constructor_fn.ret,
            runtime_fn,
            next,
        );
        var continuation = try proc.packGeneratedErasedCallable(
            boundary.target,
            erased_proc,
            runtime_worker_id,
            runtime_fn.rep,
            runtime_fn.ret,
            result_desc,
            captures,
            capture_fields,
            runtime_layout.erased_capture_layout,
            boundary.next,
        );
        try self.finishGeneratedCallablePackBoundary(proc, boundary);
        var planned_capture_index = captured_values.len;
        var plan_index = self.plan.generated_parser_field_captures.items.len;
        while (plan_index > 0) {
            plan_index -= 1;
            const field_capture = self.plan.generated_parser_field_captures.items[plan_index];
            if (field_capture.worker != runtime_worker_id) continue;
            planned_capture_index -= 1;
            const call = proc.generatedCodecCallPlan(runtime_worker_id, encoding_type, "rename_field", null);
            const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
            if (arg_types.len != 2) {
                boxyLowerInvariant("generated rename_field call did not have two arguments");
            }
            const field_name = try proc.addFrameLocalForRep(proc.repForTypeRef(arg_types[1]));
            continuation = try proc.lowerWorkerCallLocalsInto(
                captured_values[planned_capture_index],
                call.ret_type,
                arg_types,
                arg_types,
                &.{ encoding, field_name },
                null,
                null,
                null,
                call.worker,
                self.plan.directCallHiddenDescriptorArgSlice(call.hidden_desc_args),
                self.plan.directCallHiddenDictionaryArgSlice(call.hidden_dict_args),
                continuation,
            );
            const field_module = procedureModuleById(self.modules, field_capture.field_module);
            continuation = try proc.assignStringBytesLiteral(
                field_name,
                field_module.canonical_names.recordFieldLabelText(field_capture.field_name),
                continuation,
            );
        }
        if (planned_capture_index != 1) {
            boxyLowerInvariant("generated parser capture emission did not consume all renamed fields");
        }
        return try proc.prependDescriptorArgMaterializations(descriptor_initializers.items, try proc.prependHiddenDictionaryArgMaterialization(dictionary_initializers.items, continuation));
    }

    fn lowerHostedWorkerBodyInto(
        self: *ProcedureBuilder,
        resolved: ResolvedWorker,
        proc: *ProcBodyBuilder,
        ret_local: LIR.LocalId,
        ret_stmt: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker_plan = self.plan.workers.items[@backingInt(proc.worker_layout.worker)];
        const host_fn_rep = worker_plan.host_fn_rep orelse
            boxyLowerInvariant("hosted worker had no host ABI signature");
        const host_function = proc.functionChildrenForRep(host_fn_rep) orelse
            boxyLowerInvariant("hosted host signature was not a function");
        const worker_function = proc.functionChildrenForRep(worker_plan.rep) orelse
            boxyLowerInvariant("hosted worker signature was not a function");
        if (host_function.arg_count != worker_function.arg_count) {
            boxyLowerInvariant("hosted host signature arity disagreed with worker signature");
        }

        const host_children = self.plan.childSlice(self.plan.representations.items[@backingInt(host_function.rep)].children);
        const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_function.rep)].children);
        const host_arg_children = host_children[host_function.args_start..][0..host_function.arg_count];
        const worker_arg_children = worker_children[worker_function.args_start..][0..worker_function.arg_count];

        // A position whose host representation is structurally the worker's
        // own crosses the boundary unchanged: the host sees the same bytes,
        // and the worker's descriptors keep describing them on the Roc side.
        const worker_arg_locals = proc.arg_locals.items[0..host_function.arg_count];
        const host_arg_locals = try self.allocator.alloc(LIR.LocalId, host_function.arg_count);
        defer self.allocator.free(host_arg_locals);
        for (host_arg_children, worker_arg_children, worker_arg_locals, host_arg_locals) |host_child, worker_child, worker_local, *local| {
            local.* = if (try self.plan.repsStructurallyIdentical(self.allocator, host_child.rep, worker_child.rep))
                worker_local
            else
                try proc.addFrameLocalForRuntimeRep(proc.hostRuntimeLayoutForRep(host_child.rep), host_child.rep);
        }

        const host_ret_rep = if (try self.plan.repsStructurallyIdentical(self.allocator, host_function.ret, worker_function.ret))
            worker_function.ret
        else
            host_function.ret;
        const host_ret_layout = proc.hostRuntimeLayoutForRep(host_function.ret);
        const host_result_desc = try proc.descriptorRefForRepIfNeeded(host_ret_rep);
        const host_ret_local = try proc.addFrameLocal(host_ret_layout.layoutIdx());
        // The hosted call produces this exact descriptor. Generic frame-local
        // allocation can reserve a runtime descriptor for nested dynamic data,
        // which would conflict with the call's descriptor even on a fresh local.
        if (host_result_desc) |desc| {
            self.result.store.setLocalBoxyDesc(host_ret_local, desc);
        }

        var continuation = ret_stmt;
        if (host_ret_local != ret_local) {
            continuation = try proc.assignRepresentationBoundary(
                ret_local,
                host_ret_local,
                worker_function.ret,
                host_ret_rep,
                continuation,
            );
        }
        continuation = try self.result.store.addCFStmt(.{ .assign_call = .{
            .target = host_ret_local,
            .proc = try self.emitHostedExternalProc(proc.worker_layout.worker, resolved),
            .args = try self.result.store.addLocalSpan(host_arg_locals),
            .result_desc = host_result_desc,
            .next = continuation,
        } }, proc.origin);

        var index = host_function.arg_count;
        while (index > 0) {
            index -= 1;
            if (host_arg_locals[index] == worker_arg_locals[index]) continue;
            continuation = try proc.assignRepresentationBoundary(
                host_arg_locals[index],
                worker_arg_locals[index],
                host_arg_children[index].rep,
                worker_arg_children[index].rep,
                continuation,
            );
        }
        return continuation;
    }

    fn emitHostWrapper(
        self: *ProcedureBuilder,
        root_layout: Layouts.RootLayouts,
        worker_layout: Layouts.WorkerLayouts,
        worker_proc: LIR.LirProcSpecId,
        worker_plan: Plan.WorkerPlan,
    ) Allocator.Error!LIR.LirProcSpecId {
        const root_plan = self.plan.roots.items[@backingInt(root_layout.root)];
        const resolved = self.resolved_workers.items[@backingInt(root_plan.worker)];
        var host_origin = try self.workerOrigin(resolved);
        host_origin.kind = .scaffold;
        var proc = ProcBodyBuilder.initSyntheticAdapter(self, resolved.module, worker_layout, host_origin);
        defer proc.deinit();
        // Only a host-shaped root crosses the host ABI. A private root is
        // wrapped just to supply its worker's hidden arguments, at its own
        // representation, as its layouts were planned.
        const host_rep = if (root_plan.wrapper_kind == .host_shaped_wrapper)
            self.plan.hostRepFor(root_plan.host_rep)
        else
            root_plan.host_rep;
        const host_function = proc.functionChildrenForRep(host_rep);
        const worker_function = proc.functionChildrenForRep(worker_plan.rep);
        const host_args = self.layout_plan.rootLayoutSlice(root_layout.host_args);
        const host_ret = root_layout.host_ret orelse root_layout.host_value orelse switch (root_plan.wrapper_kind) {
            .host_shaped_wrapper => boxyLowerInvariant("boxy host wrapper had no host return layout"),
            // A private root returns what its worker returns.
            .private_worker_only => worker_layout.ret orelse worker_layout.value,
        };
        const host_ret_rep = if (host_function) |function| function.ret else host_rep;
        const worker_ret_rep = if (worker_function) |function| function.ret else worker_plan.rep;
        const hidden_desc_params = self.plan.hiddenDescriptorParamSlice(worker_plan.hidden_descs);
        const hidden_dict_params = self.plan.hiddenDictionaryParamSlice(worker_plan.hidden_dicts);
        const hidden_dict_args = self.plan.directCallHiddenDictionaryArgSlice(root_plan.hidden_dict_args);
        if (hidden_dict_args.len != hidden_dict_params.len) {
            boxyLowerInvariant("boxy host wrapper dictionary arguments disagreed with its worker parameters");
        }

        var descriptor_sources = StaticDescriptorSourceMap{};
        defer descriptor_sources.deinit(self.allocator);
        try self.collectPlannedStaticDescriptorSources(root_plan.worker, root_plan.hidden_desc_args, &descriptor_sources);
        var desc_context = StaticDescInstantiationContext{};
        defer desc_context.deinit(self.allocator);
        proc.static_descriptor_materialization_scope = .{ .sources = &descriptor_sources, .context = &desc_context };

        const call_arg_count = host_args.len + hidden_desc_params.len + hidden_dict_params.len;
        const call_locals = try self.allocator.alloc(LIR.LocalId, call_arg_count);
        defer self.allocator.free(call_locals);
        if (host_function) |function| {
            const host_children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
            const worker_fn = worker_function orelse boxyLowerInvariant("host wrapper worker was not a function");
            const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_fn.rep)].children);
            if (function.arg_count != worker_fn.arg_count) boxyLowerInvariant("host wrapper argument arity mismatch");
            for (host_children[function.args_start..][0..function.arg_count], worker_children[worker_fn.args_start..][0..worker_fn.arg_count], 0..) |host_arg, worker_arg, index| {
                const arg = try proc.addArgLocalForRep(host_arg.rep);
                call_locals[index] = if (try proc.callableValueBoundaryIsDirect(worker_arg.rep, host_arg.rep)) arg else try proc.addFrameLocalForRep(worker_arg.rep);
            }
        }
        for (call_locals[host_args.len..]) |*local| local.* = try proc.addFrameLocal(.opaque_ptr);
        const worker_spec = self.result.store.getProcSpec(worker_proc);
        const worker_returns_desc = worker_spec.runtime_ret_desc != null;
        // A worker whose result descriptor is one of its own inputs returns a
        // value described by the argument this wrapper passes in that position.
        const external_result_desc: ?LIR.BoxyDescRef = if (worker_returns_desc) null else if (worker_spec.ret_desc) |ret_desc| switch (ret_desc) {
            .local => |worker_local| blk: {
                const worker_args = self.result.store.getLocalSpan(worker_spec.args);
                if (worker_args.len != call_locals.len) {
                    boxyLowerInvariant("boxy host wrapper call arity disagreed with its worker");
                }
                for (0..worker_args.len) |index| {
                    if (GuardedList.at(worker_args, index) == worker_local) break :blk .{ .local = call_locals[index] };
                }
                boxyLowerInvariant("boxy host wrapper worker result descriptor was not one of its arguments");
            },
            .static => ret_desc,
            .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy host wrapper worker result descriptor was not a static or argument descriptor"),
        } else if (self.plan.representations.items[@backingInt(proc.descriptorStorageRep(worker_ret_rep))].descriptor != null)
            // The worker result carries no descriptor of its own; the wrapper
            // knows the root's exact instantiation and describes it statically.
            try self.staticDescRefForWorkerRepWithSourceMap(worker_ret_rep, null, &descriptor_sources, &desc_context)
        else
            null;
        const raw_result = if (worker_returns_desc)
            try proc.addFrameLocalForRepWithRequiredFreshDescriptor(worker_ret_rep)
        else if (external_result_desc) |desc| blk: {
            const local = try proc.addFrameLocal(proc.workerRuntimeLayoutForRep(worker_ret_rep).layoutIdx());
            self.result.store.setLocalBoxyDesc(local, desc);
            break :blk local;
        } else try proc.addFrameLocalForRep(worker_ret_rep);
        const ret_desc_local = if (worker_returns_desc)
            proc.callResultOutputDescriptorLocal(raw_result) orelse boxyLowerInvariant("host wrapper worker result has no output descriptor")
        else
            null;
        const ret_local = if (!worker_returns_desc and proc.representationBoundaryIsDirect(host_ret_rep, worker_ret_rep)) raw_result else try proc.addFrameLocalForRep(host_ret_rep);
        const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } }, proc.origin);
        var continuation = if (ret_local == raw_result) ret_stmt else try proc.assignRepresentationBoundary(ret_local, raw_result, host_ret_rep, worker_ret_rep, ret_stmt);
        continuation = try self.result.store.addCFStmt(.{ .assign_call = .{
            .target = raw_result,
            .proc = worker_proc,
            .args = try self.result.store.addLocalSpan(call_locals),
            .result_desc = external_result_desc,
            .out_desc = ret_desc_local,
            .next = continuation,
        } }, proc.origin);
        if (host_function) |function| {
            const host_children = self.plan.childSlice(self.plan.representations.items[@backingInt(function.rep)].children);
            const worker_fn = worker_function.?;
            const worker_children = self.plan.childSlice(self.plan.representations.items[@backingInt(worker_fn.rep)].children);
            var index = function.arg_count;
            while (index > 0) {
                index -= 1;
                if (call_locals[index] != proc.arg_locals.items[index]) {
                    continuation = try proc.assignRepresentationBoundary(call_locals[index], proc.arg_locals.items[index], worker_children[worker_fn.args_start + index].rep, host_children[function.args_start + index].rep, continuation);
                }
            }
        }
        var dict_index = hidden_dict_params.len;
        while (dict_index > 0) {
            dict_index -= 1;
            const param = hidden_dict_params[dict_index];
            const arg = hidden_dict_args[dict_index];
            if (!std.meta.eql(arg.worker_dictionaries, param.dictionaries)) {
                boxyLowerInvariant("boxy host wrapper dictionary argument order disagreed with its worker parameters");
            }
            const dict = switch (arg.source) {
                .static_rep => |source_rep| try self.staticDictRefForRepWithEvidence(
                    source_rep,
                    arg.worker_dictionaries,
                    arg.method_evidence,
                    arg.env,
                ),
                .bound_dictionaries => boxyLowerInvariant("boxy host wrapper received a caller-bound dictionary source"),
                .literal => |literal| switch (literal) {
                    .result => |index| LIR.BoxyDictRef{ .static = try self.emitLiteralAccessor(index) },
                    .parameter => boxyLowerInvariant("host wrapper received an open literal requirement"),
                },
            };
            continuation = try self.result.store.addCFStmt(.{ .assign_boxy_dict_ref = .{
                .target = call_locals[host_args.len + hidden_desc_params.len + dict_index],
                .dict = dict,
                .next = continuation,
            } }, proc.origin);
        }
        var desc_index = hidden_desc_params.len;
        while (desc_index > 0) {
            desc_index -= 1;
            const param = hidden_desc_params[desc_index];
            continuation = try self.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = call_locals[host_args.len + desc_index],
                .desc = try self.staticDescRefForWorkerRepWithSourceMap(param.rep, null, &descriptor_sources, &desc_context),
                .next = continuation,
            } }, proc.origin);
        }
        const args_span = try self.result.store.addLocalSpan(proc.arg_locals.items);
        const frame_span = try self.result.store.addLocalSpan(proc.frame_locals.items);
        const proc_symbol = self.symbols.fresh();
        return try self.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = args_span,
            .frame_locals = frame_span,
            .body = continuation,
            .ret_layout = host_ret.layoutIdx(),
            .stack_probe = self.stackProbeForProc(args_span, frame_span, host_ret.layoutIdx()),
        }, proc.origin.loc);
    }

    const ReturnDescriptorState = union(enum) {
        unseen,
        none,
        uniform: LIR.BoxyDescRef,
        divergent,
    };

    const ReturnDescriptorInfo = struct {
        external: ?LIR.BoxyDescRef = null,
        runtime_local: ?LIR.LocalId = null,
    };

    const ReturnDescriptorEdge = struct {
        stmt: LIR.CFStmtId,
        value: LIR.LocalId,
        desc: ?LIR.BoxyDescRef,
    };

    fn mergeReturnDescriptor(state: *ReturnDescriptorState, desc: ?LIR.BoxyDescRef) void {
        switch (state.*) {
            .unseen => state.* = if (desc) |value| .{ .uniform = value } else .none,
            .none => if (desc != null) {
                state.* = .divergent;
            },
            .uniform => |existing| if (desc == null or !std.meta.eql(existing, desc.?)) {
                state.* = .divergent;
            },
            .divergent => {},
        }
    }

    /// Finalize the descriptor source that a dictionary dispatch thunk can
    /// return for this procedure. A thunk can expose a descriptor only when
    /// every return edge names the same immutable source.
    fn returnDescriptorInfoForBody(
        self: *ProcedureBuilder,
        body: LIR.CFStmtId,
        args: LIR.LocalSpan,
        default_desc: ?LIR.BoxyDescRef,
        frame_locals: *std.ArrayList(LIR.LocalId),
    ) Allocator.Error!ReturnDescriptorInfo {
        var state: ReturnDescriptorState = .unseen;
        var return_edges = std.ArrayList(ReturnDescriptorEdge).empty;
        defer return_edges.deinit(self.allocator);
        var statements = std.ArrayList(LIR.CFStmtId).empty;
        defer statements.deinit(self.allocator);
        var visited = std.AutoHashMap(u32, void).init(self.allocator);
        defer visited.deinit();
        var stack = std.ArrayList(LIR.CFStmtId).empty;
        defer stack.deinit(self.allocator);
        try stack.append(self.allocator, body);

        while (stack.pop()) |stmt_id| {
            const entry = try visited.getOrPut(@backingInt(stmt_id));
            if (entry.found_existing) continue;
            try statements.append(self.allocator, stmt_id);
            switch (self.result.store.getCFStmt(stmt_id)) {
                inline .assign_ref,
                .assign_literal,
                .init_uninitialized,
                .assign_call,
                .assign_call_erased,
                .assign_packed_erased_fn,
                .assign_boxy_desc_ref,
                .assign_boxy_dict_ref,
                .assign_boxy_box,
                .assign_boxy_record_update,
                .assign_boxy_reuse_box,
                .assign_boxy_unbox,
                .assign_boxy_adapt,
                .assign_boxy_inspect,
                .assign_boxy_eq,
                .assign_boxy_hash,
                .assign_boxy_tag,
                .assign_boxy_tag_payload,
                .assign_call_dict,
                .assign_low_level,
                .assign_list,
                .assign_struct,
                .assign_tag,
                .store_struct,
                .store_tag,
                .set_local,
                .debug,
                .expect,
                .comptime_branch_taken,
                .incref,
                .decref,
                .decref_if_initialized,
                .free,
                => |stmt| try stack.append(self.allocator, stmt.next),
                .switch_stmt => |switch_stmt| {
                    const branches = self.result.store.getCFSwitchBranches(switch_stmt.branches);
                    for (0..branches.len) |index| {
                        try stack.append(self.allocator, GuardedList.at(branches, index).body);
                    }
                    try stack.append(self.allocator, switch_stmt.default_branch);
                },
                .switch_initialized_payload => |switch_stmt| {
                    try stack.append(self.allocator, switch_stmt.initialized_branch);
                    try stack.append(self.allocator, switch_stmt.uninitialized_branch);
                },
                .str_match => |str_match| {
                    try stack.append(self.allocator, str_match.on_match);
                    try stack.append(self.allocator, str_match.on_miss);
                },
                .str_match_set => |str_match_set| {
                    const arms = self.result.store.getStrMatchArms(str_match_set.arms);
                    for (0..arms.len) |index| {
                        try stack.append(self.allocator, GuardedList.at(arms, index).on_match);
                    }
                    try stack.append(self.allocator, str_match_set.on_miss);
                },
                .boxy_tag_match => |tag_match| {
                    try stack.append(self.allocator, tag_match.on_match);
                    try stack.append(self.allocator, tag_match.on_miss);
                },
                .join => |join| {
                    try stack.append(self.allocator, join.body);
                    try stack.append(self.allocator, join.remainder);
                },
                .ret => |ret| {
                    const desc = self.result.store.getLocal(ret.value).boxy_desc;
                    mergeReturnDescriptor(&state, desc);
                    try return_edges.append(self.allocator, .{
                        .stmt = stmt_id,
                        .value = ret.value,
                        .desc = desc,
                    });
                },
                .jump,
                .crash,
                .expect_err,
                .runtime_error,
                .comptime_exhaustiveness_failed,
                .loop_continue,
                .loop_break,
                => {},
            }
        }

        return switch (state) {
            .uniform => |desc| switch (desc) {
                .static => .{ .external = desc },
                .local => |local| blk: {
                    const arg_locals = self.result.store.getLocalSpan(args);
                    for (0..arg_locals.len) |index| {
                        if (GuardedList.at(arg_locals, index) == local) break :blk .{ .external = desc };
                    }
                    break :blk if (try self.descriptorLocalIsRuntimeProduced(statements.items, args, local))
                        .{ .runtime_local = local }
                    else
                        .{};
                },
                .runtime, .dict_method_arg, .dict_method_hidden => .{},
            },
            .divergent => blk: {
                for (return_edges.items) |edge| {
                    if (edge.desc == null and default_desc == null) {
                        boxyLowerInvariant("descriptor-bearing procedure had a return edge without an exact descriptor");
                    }
                }

                const runtime_local = try self.addLocal(.opaque_ptr);
                try frame_locals.append(self.allocator, runtime_local);
                for (return_edges.items) |edge| {
                    const ret_stmt = try self.result.store.addCFStmt(.{ .ret = .{ .value = edge.value } }, self.result.store.stmtOrigin(edge.stmt));
                    self.result.store.getCFStmtPtr(edge.stmt).* = .{ .assign_boxy_desc_ref = .{
                        .target = runtime_local,
                        .desc = edge.desc orelse default_desc.?,
                        .next = ret_stmt,
                    } };
                }
                break :blk .{ .runtime_local = runtime_local };
            },
            .unseen, .none => .{},
        };
    }

    fn descriptorLocalIsRuntimeProduced(
        self: *ProcedureBuilder,
        statements: []const LIR.CFStmtId,
        args: LIR.LocalSpan,
        result_local: LIR.LocalId,
    ) Allocator.Error!bool {
        var dynamic = collections.DenseMap(LIR.LocalId, void).init(self.allocator);
        defer dynamic.deinit();

        const arg_locals = self.result.store.getLocalSpan(args);
        for (0..arg_locals.len) |index| {
            try dynamic.put(GuardedList.at(arg_locals, index), {});
        }

        var changed = true;
        while (changed) {
            changed = false;
            for (statements) |stmt_id| {
                switch (self.result.store.getCFStmt(stmt_id)) {
                    .assign_call => |assign| if (assign.out_desc) |out_desc| {
                        const entry = try dynamic.getOrPut(out_desc);
                        changed = changed or !entry.found_existing;
                    },
                    .assign_call_erased => |assign| if (assign.out_desc) |out_desc| {
                        const entry = try dynamic.getOrPut(out_desc);
                        changed = changed or !entry.found_existing;
                    },
                    .assign_boxy_desc_ref => |assign| {
                        var depends = if (assign.desc.localOrNull()) |local| dynamic.contains(local) else false;
                        if (!depends) {
                            const captures = self.result.store.getLocalSpan(assign.captures);
                            for (0..captures.len) |index| {
                                if (dynamic.contains(GuardedList.at(captures, index))) {
                                    depends = true;
                                    break;
                                }
                            }
                        }
                        if (depends) {
                            const entry = try dynamic.getOrPut(assign.target);
                            changed = changed or !entry.found_existing;
                        }
                    },
                    .assign_boxy_adapt => |assign| {
                        const source_local = if (assign.source_desc) |desc| desc.localOrNull() else null;
                        if (source_local == null or !dynamic.contains(source_local.?)) continue;
                        const target_desc = self.result.store.getLocal(assign.target).boxy_desc orelse continue;
                        const target_local = target_desc.localOrNull() orelse continue;
                        const entry = try dynamic.getOrPut(target_local);
                        changed = changed or !entry.found_existing;
                    },
                    .assign_ref => |assign| {
                        const source = switch (assign.op) {
                            .local => |local| local,
                            .field => |field| field.source,
                            inline .discriminant, .tag_payload, .tag_payload_struct => |op| op.source,
                            inline .list_reinterpret, .nominal => |op| op.backing_ref,
                        };
                        if (!dynamic.contains(source)) continue;
                        const entry = try dynamic.getOrPut(assign.target);
                        changed = changed or !entry.found_existing;
                    },
                    .set_local => |assign| if (dynamic.contains(assign.value)) {
                        const entry = try dynamic.getOrPut(assign.target);
                        changed = changed or !entry.found_existing;
                    },
                    .init_uninitialized,
                    .assign_literal,
                    .assign_packed_erased_fn,
                    .assign_boxy_dict_ref,
                    .assign_boxy_box,
                    .assign_boxy_record_update,
                    .assign_boxy_reuse_box,
                    .assign_boxy_unbox,
                    .assign_boxy_inspect,
                    .assign_boxy_eq,
                    .assign_boxy_hash,
                    .assign_boxy_tag,
                    .assign_boxy_tag_payload,
                    .boxy_tag_match,
                    .assign_call_dict,
                    .assign_low_level,
                    .assign_list,
                    .assign_struct,
                    .assign_tag,
                    .store_struct,
                    .store_tag,
                    .debug,
                    .expect,
                    .expect_err,
                    .runtime_error,
                    .comptime_exhaustiveness_failed,
                    .comptime_branch_taken,
                    .incref,
                    .decref,
                    .decref_if_initialized,
                    .free,
                    .switch_stmt,
                    .switch_initialized_payload,
                    .str_match,
                    .str_match_set,
                    .loop_continue,
                    .loop_break,
                    .join,
                    .jump,
                    .ret,
                    .crash,
                    => {},
                }
            }
        }
        return dynamic.contains(result_local);
    }

    fn verifyDirectCallAbis(self: *ProcedureBuilder) Allocator.Error!void {
        // A provisional call kept in its descriptor-returning form is exempt:
        // its replacement form is unused.
        var unused_static_calls = collections.DenseMap(LIR.CFStmtId, void).init(self.allocator);
        defer unused_static_calls.deinit();
        for (self.pending_direct_call_descriptor_abis.items) |pending| {
            if (!pending.resolved) {
                boxyLowerInvariant("boxy recursive direct-call descriptor ABI remained unresolved after procedure emission");
            }
            if (!pending.uses_static_replacement) try unused_static_calls.put(pending.static_call, {});
        }
        for (0..self.result.store.cfStmtCount()) |stmt_index| {
            const stmt_id: LIR.CFStmtId = @fromBackingInt(@intCast(@as(u32, @intCast(stmt_index))));
            switch (self.result.store.getCFStmt(stmt_id)) {
                .assign_call => |assign| {
                    const callee = self.result.store.getProcSpec(assign.proc);
                    const call_args = self.result.store.getLocalSpan(assign.args);
                    const callee_args = self.result.store.getLocalSpan(callee.args);
                    if (call_args.len != callee_args.len) {
                        base.invariant(
                            "boxy lower invariant violated: direct-call argument count disagreed with finalized callee ABI: stmt={d} callee={d} call_args={d} callee_args={d}",
                            .{ stmt_index, @backingInt(assign.proc), call_args.len, callee_args.len },
                        );
                    }
                    if (!unused_static_calls.contains(stmt_id)) {
                        if ((assign.out_desc != null) != (callee.runtime_ret_desc != null)) {
                            base.invariant(
                                "boxy lower invariant violated: direct-call descriptor output disagreed with finalized callee ABI: stmt={d} callee={d} call_out={any} callee_out={any}",
                                .{ stmt_index, @backingInt(assign.proc), assign.out_desc != null, callee.runtime_ret_desc != null },
                            );
                        }
                    }
                },
                .init_uninitialized,
                .assign_ref,
                .assign_literal,
                .assign_call_erased,
                .assign_packed_erased_fn,
                .assign_boxy_desc_ref,
                .assign_boxy_dict_ref,
                .assign_boxy_box,
                .assign_boxy_record_update,
                .assign_boxy_reuse_box,
                .assign_boxy_unbox,
                .assign_boxy_adapt,
                .assign_boxy_inspect,
                .assign_boxy_eq,
                .assign_boxy_hash,
                .assign_boxy_tag,
                .assign_boxy_tag_payload,
                .boxy_tag_match,
                .assign_call_dict,
                .assign_low_level,
                .assign_list,
                .assign_struct,
                .assign_tag,
                .store_struct,
                .store_tag,
                .set_local,
                .debug,
                .expect,
                .expect_err,
                .runtime_error,
                .comptime_exhaustiveness_failed,
                .comptime_branch_taken,
                .incref,
                .decref,
                .decref_if_initialized,
                .free,
                .switch_stmt,
                .switch_initialized_payload,
                .str_match,
                .str_match_set,
                .loop_continue,
                .loop_break,
                .join,
                .jump,
                .ret,
                .crash,
                => {},
            }
        }
    }

    fn resolvePendingDirectCallDescriptorAbis(
        self: *ProcedureBuilder,
        callee: LIR.LirProcSpecId,
        has_runtime_output: bool,
    ) Allocator.Error!void {
        for (self.pending_direct_call_descriptor_abis.items) |*pending| {
            if (pending.callee != callee or pending.resolved) continue;
            if (!has_runtime_output) {
                try self.result.store.replaceCFStmt(
                    pending.provisional_call,
                    self.result.store.getCFStmt(pending.static_replacement),
                    self.result.store.stmtOrigin(pending.static_replacement),
                );
                pending.uses_static_replacement = true;
            }
            pending.resolved = true;
        }
    }

    fn addLocal(self: *ProcedureBuilder, layout_idx: @import("layout").Idx) Allocator.Error!LIR.LocalId {
        return try self.result.store.addLocal(.{ .layout_idx = layout_idx });
    }

    fn addLocalWithBoxyDesc(
        self: *ProcedureBuilder,
        layout_idx: @import("layout").Idx,
        desc: ?LIR.BoxyDescRef,
    ) Allocator.Error!LIR.LocalId {
        return try self.result.store.addLocal(.{ .layout_idx = layout_idx, .boxy_desc = desc });
    }

    fn stackProbeForProc(
        self: *ProcedureBuilder,
        args: LIR.LocalSpan,
        frame_locals: LIR.LocalSpan,
        ret_layout: @import("layout").Idx,
    ) LIR.StackProbe {
        if (self.result.store.localSpanNeedsStackProbe(&self.result.layouts, args)) return .required;
        if (self.result.store.localSpanNeedsStackProbe(&self.result.layouts, frame_locals)) return .required;
        if (LIR.layoutNeedsStackProbe(&self.result.layouts, ret_layout)) return .required;
        return .default;
    }
};

const ProcBodyBuilder = struct {
    literal_locals: std.ArrayList(LIR.LocalId) = .empty,
    literal_initializer: ?u32 = null,
    parent: *ProcedureBuilder,
    module: ProcedureModuleView,
    worker_layout: Layouts.WorkerLayouts,
    synthetic_adapter: bool,
    erased_argument_descriptors: bool,
    arg_locals: std.ArrayList(LIR.LocalId),
    lambda_arg_patterns: []const checked.CheckedPatternId,
    lambda_arg_binding_locals: []LIR.LocalId,
    lambda_arg_worker_reps: []Plan.TypeRepId,
    frame_locals: std.ArrayList(LIR.LocalId),
    loop_stack: std.ArrayList(LoopContext),
    binder_locals: []?LIR.LocalId,
    binder_reps: []?Plan.TypeRepId,
    descriptor_locals: []?LIR.LocalId,
    descriptor_local_reps: []?Plan.TypeRepId,
    descriptor_bound: []bool,
    descriptor_evidence_bound: []bool,
    descriptor_slots: []?LIR.LocalId,
    descriptor_slot_reps: []?Plan.TypeRepId,
    descriptor_rep_bindings: std.ArrayList(DescriptorRepBinding),
    adapter_descriptor_entries: std.ArrayList(AdapterDescriptorEntry),
    runtime_initialized_descriptor_locals: std.ArrayList(LIR.LocalId),
    descriptor_local_templates: std.ArrayList(DescriptorLocalTemplate),
    /// Each templated local's position in `descriptor_local_templates`.
    descriptor_local_template_positions: std.AutoHashMapUnmanaged(LIR.LocalId, u32) = .empty,
    nominal_formal_bindings: std.ArrayList(NominalFormalBinding) = .empty,
    scoped_descriptor_locals: std.ArrayList(ScopedDescriptorLocal) = .empty,
    /// First scoped descriptor local of the innermost active scope.
    scoped_descriptor_locals_start: usize = 0,
    local_descriptor_environments: std.ArrayList(LocalDescriptorEnvironment),
    descriptor_transfer_aliases: std.ArrayList(DescriptorTransferAlias),
    /// The values a declared local closure's reassignable captures held at
    /// its declaration. Every construction of that closure's callable reads
    /// these instead of the variables' current values.
    closure_capture_snapshots: std.ArrayList(ClosureCaptureSnapshot) = .empty,
    /// This frame is a template dictionary's method adapter, which binds
    /// descriptors the building frame supplied.
    template_frame_descriptors: bool = false,
    /// Template dictionaries this frame built, with the locals each names.
    template_dict_cache: std.ArrayList(TemplateDictCacheEntry) = .empty,
    static_descriptor_materialization_scope: ?StaticDescriptorMaterializationScope,
    /// The planned hidden descriptor arguments of the direct call whose
    /// operands are being adapted. They name, for each callee worker
    /// descriptor representation, the caller representation it stands for
    /// at this call.
    call_boundary_substitution: []const Plan.DirectCallHiddenDescriptorArg = &.{},
    read_only_descriptor_inputs: std.ArrayList(LIR.LocalId),
    dictionary_locals: []?LIR.LocalId,
    dictionary_bound: []bool,
    dictionary_slots: []?LIR.LocalId,
    erased_capture_arg: ?LIR.LocalId,
    erased_capture_contents_desc: ?LIR.LocalId,
    erased_capture_locals: std.ArrayList(LIR.LocalId),
    /// Boxed slot of each recursive value binder in scope: reserved with the
    /// declaring block, or received as an erased capture.
    recursive_value_slots: std.AutoHashMapUnmanaged(checked.PatternBinderId, LIR.LocalId),
    worker_argument_desc_initializers: std.ArrayList(DescriptorArgLocal),
    erased_capture_value_desc_initializers: std.ArrayList(DescriptorArgLocal),
    stored_capture_initializers: std.ArrayList(StoredCaptureInitializer),
    worker_return_descriptor_initializers: std.ArrayList(DescriptorArgLocal),
    /// The derived `is_eq`/`to_hash` being lowered: the frame its component
    /// decisions were planned for, and the formal bindings below it, which
    /// belong to code outside the derivation.
    derived_context: ?DerivedContext = null,
    /// The union a recursive derived helper is being emitted for, until its
    /// body first reaches it.
    derived_expanding: ?Plan.TypeRepId = null,
    next_join_point: u32,
    current_lambda: ?checked.CheckedExprId,
    worker_return_local: ?LIR.LocalId = null,
    /// Provenance of the construct this builder is currently lowering. The
    /// body's creator states it explicitly (scaffold or derived, naming the
    /// construct that demanded the body), and the expression machine
    /// (`runExprTasks`) restates it as `source` for each checked node it
    /// lowers, restoring the enclosing origin when that node is done.
    origin: LIR.StmtOrigin,

    const LoopContext = struct {
        join_id: LIR.JoinPointId,
        result_target: LIR.LocalId,
        after_loop: LIR.CFStmtId,
    };

    const DescriptorTransferAlias = struct {
        source: LIR.LocalId,
        target: LIR.LocalId,
    };

    const ClosureCaptureSnapshot = struct {
        closure: Plan.CheckedExprIdentity,
        /// One entry per source capture, null for an immutable capture.
        locals: []?LIR.LocalId,
    };

    const PatternMiss = struct {
        join_id: LIR.JoinPointId,
    };

    const InspectPart = union(enum) {
        literal: []const u8,
        field: struct {
            source: LIR.LocalId,
            field_index: u32,
            rep: Plan.TypeRepId,
        },
        tag_payload: struct {
            source: LIR.LocalId,
            variant_index: u32,
            payload_index: ?u32,
            rep: Plan.TypeRepId,
        },
    };

    const LiteralPattern = union(enum) {
        int: can.CIR.IntValue,
        dec: builtins.dec.RocDec,
        frac_f32: f32,
        frac_f64: f64,
        str: checked.CheckedStringLiteralId,
    };

    const DescriptorArgLocal = struct {
        local: LIR.LocalId,
        materialize: ?LIR.BoxyDescRef = null,
        read_path: Plan.Span = .{},
        nested_index: ?u32 = null,
        tag_ext: bool = false,
        tag_residual_for: ?LIR.BoxyDescRef = null,
        captures: LIR.LocalSpan = .{ .start = 0, .len = 0 },
        from_source_value: bool = false,
    };

    const ResultDescriptorSource = struct {
        desc: ?LIR.BoxyDescRef = null,
        template: ?DescriptorMaterialization = null,
        prerequisite: ?DescriptorArgLocal = null,
        materialize: ?DescriptorArgLocal = null,
        preserves_source_desc: bool = false,
    };

    const DescriptorMaterializationVisit = enum {
        pending,
        visiting,
        done,
    };

    const ErasedCaptureDescriptorMode = enum {
        reuse_existing,
        snapshot_existing,
    };

    const DictionaryArgLocal = struct {
        local: LIR.LocalId,
        materialize: ?LIR.BoxyDictRef = null,
        /// The frame locals a template dictionary names.
        captures: LIR.LocalSpan = .{ .start = 0, .len = 0 },
    };

    /// A dictionary reference built in this frame, with the frame locals it
    /// names when it is a template.
    const FrameDictionary = struct {
        dict: LIR.BoxyDictRef,
        captures: LIR.LocalSpan = .{ .start = 0, .len = 0 },
    };

    /// Whether describing `rep_id` reads a descriptor only this frame holds.
    fn repDescriptorNeedsFrame(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!bool {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor) |desc| {
            if (self.descriptorBindingIsBoundForRep(identity_rep) and
                self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep) != null) return true;
        }
        return try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep);
    }

    /// The local this frame binds for `dictionaries`.
    fn boundDictionaryLocal(self: *ProcBodyBuilder, dictionaries: Plan.Span) LIR.LocalId {
        if (dictionaries.len == 0) {
            boxyLowerInvariant("boxy bound dictionary source was empty");
        }
        const first: Plan.DictionaryRequirementId = @fromBackingInt(@intCast(dictionaries.start));
        if (!self.dictionaryBindingIsBound(first)) {
            boxyLowerInvariant("boxy dictionary source was not bound in the enclosing worker");
        }
        return self.dictionaryLocalForRequirementOrNull(first) orelse
            boxyLowerInvariant("boxy bound dictionary source had no local");
    }

    /// The dictionary a planned `static_rep` source names in this frame.
    fn staticDictRefInFrame(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
        method_evidence: Plan.Span,
        env: u32,
    ) Allocator.Error!FrameDictionary {
        var template = DictTemplateFrame{ .frame = self };
        defer template.captures.deinit(self.parent.allocator);
        const dict_id = try self.parent.dictForRepInFrame(source_rep, worker_dictionaries, method_evidence, &template, env);
        return .{
            .dict = .{ .static = dict_id },
            .captures = if (template.captures.items.len == 0)
                .{ .start = 0, .len = 0 }
            else
                try self.parent.result.store.addLocalSpan(template.captures.items),
        };
    }

    const ErasedCallArgumentDescriptors = struct {
        locals: LIR.LocalSpan = .empty(),
        keys: LIR.BoxySpan = .empty(),
    };

    const DescriptorLocalReservation = struct {
        local: LIR.LocalId,
        fresh: bool,
        /// Initialized by the enclosing nominal backing scope rather than
        /// bound as a type-wide descriptor slot.
        scoped: bool = false,
    };

    const DescriptorMaterialization = struct {
        desc: LIR.BoxyDescRef,
        captures: LIR.LocalSpan = .{ .start = 0, .len = 0 },

        /// The initializer that materializes this descriptor into `local`.
        fn initializer(self: DescriptorMaterialization, local: LIR.LocalId) DescriptorArgLocal {
            return .{ .local = local, .materialize = self.desc, .captures = self.captures };
        }
    };

    const StoredCaptureInitializer = struct {
        local: LIR.LocalId,
        node: checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        store_module: checked.ModuleId,
        target_rep: Plan.TypeRepId,
        stored_rep: Plan.TypeRepId,
    };

    const AdapterDescriptorIdentity = struct {
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_desc: LIR.BoxyDescRef,
    };

    const AdapterDescriptorEntry = struct {
        key: AdapterDescriptorIdentity,
        recursive_desc: ?LIR.BoxyTypeDescId = null,
    };

    const DescriptorRepBinding = struct {
        desc: Plan.DescriptorRequirementId,
        rep: Plan.TypeRepId,
        local: LIR.LocalId,
        bound: bool,
        /// True only when the boundness was established by binding the
        /// requirement to evidence (`markDescriptorRequirementBoundForRep`):
        /// an entry hidden descriptor argument/capture, a prologue-rebuilt
        /// argument root, or a snapshot-scoped call/pattern-boundary bind
        /// whose initializer is prepended above every observer. A local
        /// marked bound by a mid-body descriptor write
        /// (`markDescriptorLocalBound`) does NOT set this: lowering visits
        /// statements in reverse execution order, so such a mark can be
        /// visible while lowering an earlier-executing statement even though
        /// the write has not happened yet at that point at runtime.
        evidence_bound: bool,
    };

    const LocalDescriptorEnvironmentBinding = struct {
        desc: Plan.DescriptorRequirementId,
        rep: Plan.TypeRepId,
        local: LIR.LocalId,
    };

    const LocalDescriptorEnvironment = struct {
        local: LIR.LocalId,
        rep: Plan.TypeRepId,
        bindings: []LocalDescriptorEnvironmentBinding,
    };

    /// One nominal backing formal bound to the argument rep a nominal supplied
    /// for it, together with whatever that formal was bound to outside this
    /// nominal so descending out of it restores the outer binding.
    const DescriptorTemplateBinding = struct {
        formal: Plan.TypeRepId,
        outer: ?Plan.TypeRepId,
        actual: Plan.TypeRepId,
    };

    /// Identity of a substitution environment, interned as a link to the
    /// environment it extends. Descents that bind the same formals to the same
    /// arguments in the same order reach the same id and share descriptors.
    const DescriptorTemplateEnvId = enum(u32) { empty = 0, _ };

    const DescriptorTemplateEnvKey = struct {
        parent: DescriptorTemplateEnvId,
        formal: Plan.TypeRepId,
        actual: Plan.TypeRepId,
    };

    /// A descriptor is only shared between positions that agree on both the
    /// representation and the substitution environment it was emitted under:
    /// one nominal's backing shape is reached once per argument instantiation.
    const DescriptorTemplateDescKey = struct {
        rep: Plan.TypeRepId,
        env: DescriptorTemplateEnvId,
    };

    /// What a descent restores on the way back out.
    const DescriptorTemplateScope = struct {
        bindings_start: usize,
        env: DescriptorTemplateEnvId,
    };

    const DescriptorTemplateContext = struct {
        ids: std.AutoHashMap(DescriptorTemplateDescKey, LIR.BoxyTypeDescId),
        env_ids: std.AutoHashMap(DescriptorTemplateEnvKey, DescriptorTemplateEnvId),
        bindings: std.ArrayList(DescriptorTemplateBinding),
        /// The descriptor local a constructed value forces at a
        /// representation. A template names few, so the map is sparse.
        forced_refs: std.AutoHashMapUnmanaged(Plan.TypeRepId, LIR.LocalId) = .empty,
        /// The environment of the root's own instantiation, where descriptor
        /// locals named by representation describe what they were bound to.
        root_env: ?DescriptorTemplateEnvId = null,
        /// The actual each currently bound nominal formal stands for.
        exact_reps: std.AutoHashMapUnmanaged(Plan.TypeRepId, Plan.TypeRepId) = .empty,
        exact_storage: bool,
        env: DescriptorTemplateEnvId = .empty,
        excluded_local: ?LIR.LocalId = null,
        /// Whether the build asked which descriptor locals this procedure
        /// has bound, making its descriptor specific to the procedure.
        read_bound_locals: bool = false,

        fn deinit(self: *DescriptorTemplateContext, allocator: Allocator) void {
            self.ids.deinit();
            self.env_ids.deinit();
            self.bindings.deinit(allocator);
            self.forced_refs.deinit(allocator);
            self.exact_reps.deinit(allocator);
        }

        /// Restore `formal` to `outer`, its value before a binding. An
        /// `outer` representation was read from this map, so its entry is
        /// still present and restoring it needs no allocation.
        fn restoreExactRep(self: *DescriptorTemplateContext, formal: Plan.TypeRepId, outer: ?Plan.TypeRepId) void {
            if (outer) |rep| {
                const entry = self.exact_reps.getPtr(formal) orelse
                    boxyLowerInvariant("boxy descriptor template restored a formal it never bound");
                entry.* = rep;
            } else {
                _ = self.exact_reps.remove(formal);
            }
        }
    };

    const DescriptorTemplateOverride = struct {
        rep: Plan.TypeRepId,
        local: LIR.LocalId,
    };

    const DescriptorLocalTemplate = struct {
        local: LIR.LocalId,
        /// Null when control-flow paths initialize this descriptor local from
        /// different structural templates. The runtime descriptor remains
        /// exact; later adapters must specialize from that value directly.
        template: ?DescriptorMaterialization,
    };

    const DescriptorBindingsSnapshot = struct {
        locals: []?LIR.LocalId,
        local_reps: []?Plan.TypeRepId,
        bound: []bool,
        evidence_bound: []bool,
        slots: []?LIR.LocalId,
        slot_reps: []?Plan.TypeRepId,
        rep_bindings: []DescriptorRepBinding,
        runtime_initialized_len: usize,

        fn deinit(self: DescriptorBindingsSnapshot, allocator: Allocator) void {
            allocator.free(self.locals);
            allocator.free(self.local_reps);
            allocator.free(self.bound);
            allocator.free(self.evidence_bound);
            allocator.free(self.slots);
            allocator.free(self.slot_reps);
            allocator.free(self.rep_bindings);
        }
    };

    /// Bindings of shared backing formals to the actual representations the
    /// enclosing nominal uses supply, innermost last. Each actual is already
    /// resolved against the bindings before it, so one lookup suffices.
    const NominalFormalBinding = Plan.DerivedBinding;

    const DerivedContext = struct {
        frame: ?Plan.WorkerPlanId,
        bindings_start: usize,
    };

    /// A descriptor local for a representation whose meaning depends on the
    /// active formal bindings. It is initialized at the start of the scope
    /// that reserved it, never in the worker prologue.
    const ScopedDescriptorLocal = struct {
        rep: Plan.TypeRepId,
        local: LIR.LocalId,
    };

    /// What a nominal backing scope restores when it ends.
    const NominalBackingFormalScope = struct {
        bindings_len: usize,
        scoped_locals_start: usize,
        outer_scoped_locals_start: usize,
    };

    const AggregateDescriptorField = struct {
        local: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    };

    const RecordFieldReadUnbox = struct {
        source: LIR.LocalId,
        source_desc: LIR.BoxyDescRef,
        target_desc: ?LIR.BoxyDescRef = null,
        target_layout: layout.Idx,
    };

    const RecordFieldReadSource = struct {
        local: LIR.LocalId,
        record_rep: Plan.TypeRepId,
        record_desc: ?LIR.BoxyDescRef = null,
        materialize: ?DescriptorArgLocal = null,
        unbox: ?RecordFieldReadUnbox = null,
    };

    const ConstructedAggregateDescriptor = struct {
        desc: ?LIR.BoxyDescRef = null,
        field_initializers: []DescriptorArgLocal = &.{},
        materialize: ?DescriptorArgLocal = null,
        /// A static descriptor recorded on the aggregate construction that ARC
        /// adopts only when a constructed field carries a runtime descriptor,
        /// keeping the aggregate releasable without forcing a descriptor onto
        /// aggregates whose fields remain concrete.
        contents_desc: ?LIR.BoxyDescRef = null,

        fn deinit(self: ConstructedAggregateDescriptor, allocator: Allocator) void {
            if (self.field_initializers.len != 0) allocator.free(self.field_initializers);
        }
    };

    const DynamicTagPayloadLocal = struct {
        local: LIR.LocalId,
        layout_idx: layout.Idx,
        desc_rep: ?Plan.TypeRepId = null,
    };

    const ExtractedTagPayloadLocal = struct {
        local: LIR.LocalId,
        desc_local: ?LIR.LocalId = null,
    };

    /// The module data the shared label-comparing plan queries need.
    pub fn moduleNames(self: *ProcBodyBuilder, module_id: checked.ModuleId) Plan.ModuleNames {
        const view = procedureModuleById(self.parent.modules, module_id);
        return .{ .key = view.key, .canonical_names = view.canonical_names };
    }

    /// Shared read-only queries over the representation plan.
    fn repQuery(self: *const ProcBodyBuilder) Plan.RepQuery {
        return .{ .plan = self.parent.plan, .allocator = self.parent.allocator };
    }

    /// Shared label-comparing queries over the representation plan.
    fn namedQuery(self: *ProcBodyBuilder) Plan.NamedRepQuery(*ProcBodyBuilder) {
        return .{ .query = self.repQuery(), .modules = self };
    }

    fn init(parent: *ProcedureBuilder, module: ProcedureModuleView, worker_layout: Layouts.WorkerLayouts, origin: LIR.StmtOrigin) ProcBodyBuilder {
        return .{
            .origin = origin,
            .parent = parent,
            .module = module,
            .worker_layout = worker_layout,
            .synthetic_adapter = false,
            .erased_argument_descriptors = false,
            .arg_locals = .empty,
            .lambda_arg_patterns = &.{},
            .lambda_arg_binding_locals = &.{},
            .lambda_arg_worker_reps = &.{},
            .frame_locals = .empty,
            .loop_stack = .empty,
            .binder_locals = &.{},
            .binder_reps = &.{},
            .descriptor_locals = &.{},
            .descriptor_local_reps = &.{},
            .descriptor_bound = &.{},
            .descriptor_evidence_bound = &.{},
            .descriptor_slots = &.{},
            .descriptor_slot_reps = &.{},
            .descriptor_rep_bindings = .empty,
            .adapter_descriptor_entries = .empty,
            .runtime_initialized_descriptor_locals = .empty,
            .descriptor_local_templates = .empty,
            .local_descriptor_environments = .empty,
            .descriptor_transfer_aliases = .empty,
            .static_descriptor_materialization_scope = null,
            .read_only_descriptor_inputs = .empty,
            .dictionary_locals = &.{},
            .dictionary_bound = &.{},
            .dictionary_slots = &.{},
            .erased_capture_arg = null,
            .erased_capture_contents_desc = null,
            .erased_capture_locals = .empty,
            .recursive_value_slots = .empty,
            .worker_argument_desc_initializers = .empty,
            .erased_capture_value_desc_initializers = .empty,
            .stored_capture_initializers = .empty,
            .worker_return_descriptor_initializers = .empty,
            .next_join_point = 0,
            .current_lambda = null,
        };
    }

    fn initSyntheticAdapter(parent: *ProcedureBuilder, module: ProcedureModuleView, worker_layout: Layouts.WorkerLayouts, origin: LIR.StmtOrigin) ProcBodyBuilder {
        var builder = ProcBodyBuilder.init(parent, module, worker_layout, origin);
        builder.synthetic_adapter = true;
        builder.erased_argument_descriptors = true;
        return builder;
    }

    /// Origin of a checked source node lowered by this builder.
    fn sourceOrigin(self: *ProcBodyBuilder, region: base.Region) Allocator.Error!LIR.StmtOrigin {
        return .{
            .loc = try self.parent.sourceLoc(self.module, region),
            .region = region,
            .inline_scope = LIR.InlineScopeId.none,
            .kind = .source,
        };
    }

    /// Origin of control-flow, representation, descriptor, or iterator glue
    /// introduced for the construct currently being lowered. Glue inside a
    /// scaffold or derived body belongs to that body and keeps its kind.
    fn glueOrigin(self: *const ProcBodyBuilder) LIR.StmtOrigin {
        var origin = self.origin;
        if (origin.kind == .source) origin.kind = .lowering_glue;
        return origin;
    }

    /// Origin of compiler-derived code (inspect, equality, hashing, generated
    /// codecs) demanded by the construct currently being lowered.
    fn derivedOrigin(self: *const ProcBodyBuilder) LIR.StmtOrigin {
        var origin = self.origin;
        origin.kind = .derived;
        return origin;
    }

    /// Origin of procedure scaffolding (adapters, compile-time constant value
    /// reconstruction) demanded by the construct currently being lowered.
    fn scaffoldOrigin(self: *const ProcBodyBuilder) LIR.StmtOrigin {
        var origin = self.origin;
        origin.kind = .scaffold;
        return origin;
    }

    fn deinit(self: *ProcBodyBuilder) void {
        for (self.closure_capture_snapshots.items) |snapshot| self.parent.allocator.free(snapshot.locals);
        self.closure_capture_snapshots.deinit(self.parent.allocator);
        self.literal_locals.deinit(self.parent.allocator);
        self.worker_return_descriptor_initializers.deinit(self.parent.allocator);
        self.stored_capture_initializers.deinit(self.parent.allocator);
        self.erased_capture_value_desc_initializers.deinit(self.parent.allocator);
        self.worker_argument_desc_initializers.deinit(self.parent.allocator);
        self.erased_capture_locals.deinit(self.parent.allocator);
        self.recursive_value_slots.deinit(self.parent.allocator);
        self.parent.allocator.free(self.dictionary_slots);
        self.parent.allocator.free(self.dictionary_bound);
        self.parent.allocator.free(self.dictionary_locals);
        self.parent.allocator.free(self.descriptor_slot_reps);
        self.parent.allocator.free(self.descriptor_slots);
        self.parent.allocator.free(self.descriptor_evidence_bound);
        self.parent.allocator.free(self.descriptor_bound);
        self.parent.allocator.free(self.descriptor_local_reps);
        self.parent.allocator.free(self.descriptor_locals);
        self.read_only_descriptor_inputs.deinit(self.parent.allocator);
        for (self.local_descriptor_environments.items) |env| {
            self.parent.allocator.free(env.bindings);
        }
        self.local_descriptor_environments.deinit(self.parent.allocator);
        self.descriptor_transfer_aliases.deinit(self.parent.allocator);
        for (self.template_dict_cache.items) |entry| self.parent.allocator.free(entry.captures);
        self.template_dict_cache.deinit(self.parent.allocator);
        self.descriptor_local_templates.deinit(self.parent.allocator);
        self.descriptor_local_template_positions.deinit(self.parent.allocator);
        self.nominal_formal_bindings.deinit(self.parent.allocator);
        self.scoped_descriptor_locals.deinit(self.parent.allocator);
        self.runtime_initialized_descriptor_locals.deinit(self.parent.allocator);
        self.adapter_descriptor_entries.deinit(self.parent.allocator);
        self.descriptor_rep_bindings.deinit(self.parent.allocator);
        self.parent.allocator.free(self.binder_reps);
        self.parent.allocator.free(self.binder_locals);
        self.loop_stack.deinit(self.parent.allocator);
        self.parent.allocator.free(self.lambda_arg_worker_reps);
        self.parent.allocator.free(self.lambda_arg_binding_locals);
        self.frame_locals.deinit(self.parent.allocator);
        self.arg_locals.deinit(self.parent.allocator);
        self.* = undefined;
    }

    fn bindLambdaArgs(self: *ProcBodyBuilder, args: []const checked.CheckedPatternId) Allocator.Error!void {
        try self.ensureBinderLocals();
        self.lambda_arg_patterns = args;

        const worker_args = self.parent.layout_plan.workerLayoutSlice(self.worker_layout.args);
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy lambda args reached a non-function worker");
        if (worker_function.arg_count != args.len or worker_args.len != args.len) {
            boxyLowerInvariant("boxy lambda argument count disagreed with worker function representation");
        }
        const worker_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(worker_function.rep)].children);
        const worker_arg_children = worker_children[worker_function.args_start..][0..worker_function.arg_count];

        const binding_locals = try self.parent.allocator.alloc(LIR.LocalId, args.len);
        errdefer self.parent.allocator.free(binding_locals);
        const worker_reps = try self.parent.allocator.alloc(Plan.TypeRepId, args.len);
        errdefer self.parent.allocator.free(worker_reps);

        for (worker_arg_children, worker_reps) |worker_arg, *worker_rep| {
            worker_rep.* = worker_arg.rep;
        }
        self.lambda_arg_binding_locals = binding_locals;
        self.lambda_arg_worker_reps = worker_reps;

        for (args, worker_args, worker_arg_children, 0..) |pattern_id, arg_layout, worker_arg, index| {
            const local = try self.addArgLocalForRep(worker_arg.rep);
            if (self.parent.result.store.getLocal(local).layout_idx != arg_layout.layoutIdx()) {
                boxyLowerInvariant("boxy worker lambda argument layout disagreed with worker argument representation");
            }
            const pattern_ty = self.module.checked_bodies.pattern(pattern_id).ty;
            const pattern_rep = self.repForType(pattern_ty);
            const binding_local = if (self.representationBoundaryIsDirect(pattern_rep, worker_arg.rep))
                local
            else
                try self.addFrameBoundaryTargetLocalForRep(pattern_rep);
            binding_locals[index] = binding_local;

            const pattern = self.module.checked_bodies.pattern(pattern_id);
            if (pattern.data == .assign)
                self.bindPatternToLocal(pattern_id, binding_local)
            else
                try self.reservePatternBindings(pattern_id);
        }
    }

    fn bindStoredFnCaptures(self: *ProcBodyBuilder, stored_fn: ?Plan.StoredFnSource) Allocator.Error!void {
        const source = stored_fn orelse return;
        const store_module = procedureModuleById(self.parent.modules, source.module);
        const raw = @backingInt(source.fn_id);
        if (raw >= store_module.const_store.fns.items.len) {
            boxyLowerInvariant("stored function capture plan referenced a missing ConstStore function");
        }
        const fn_value = store_module.const_store.getFn(source.fn_id);
        try self.ensureBinderLocals();

        for (fn_value.captures) |capture| {
            if (!capture.id.isCanonical()) continue;
            const binder = capture.id.binder();
            const ty = checkedBinderType(self.module, binder);
            const target_rep = self.repForType(ty);
            const stored_rep = self.parent.plan.repForStoredType(.{
                .module = store_module.key,
                .ty = capture.ty,
            }) orelse boxyLowerInvariant("stored function capture type was missing from the boxy representation plan");
            const local = try self.addFrameBoundaryTargetLocalForRep(target_rep);
            self.bindLocal(binder, local);
            try self.stored_capture_initializers.append(self.parent.allocator, .{
                .local = local,
                .node = capture.value,
                .stored_type = capture.ty,
                .store_module = source.module,
                .target_rep = target_rep,
                .stored_rep = stored_rep,
            });
        }
    }

    fn prependStoredCaptureInitializers(
        self: *ProcBodyBuilder,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        var index = self.stored_capture_initializers.items.len;
        while (index > 0) {
            index -= 1;
            const capture = self.stored_capture_initializers.items[index];
            const store_module = procedureModuleById(self.parent.modules, capture.store_module);
            continuation = try self.restoreStoredConstNodeAcrossBoundary(
                capture.local,
                store_module,
                capture.node,
                capture.stored_type,
                capture.target_rep,
                capture.stored_rep,
                continuation,
            );
        }
        return continuation;
    }

    fn prependLambdaArgPatternBindings(self: *ProcBodyBuilder, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.lambda_arg_patterns.len == 0) return next;
        const worker_args = self.parent.layout_plan.workerLayoutSlice(self.worker_layout.args);
        if (self.lambda_arg_patterns.len != worker_args.len or
            self.lambda_arg_patterns.len > self.arg_locals.items.len or
            self.lambda_arg_patterns.len != self.lambda_arg_binding_locals.len or
            self.lambda_arg_patterns.len != self.lambda_arg_worker_reps.len)
        {
            boxyLowerInvariant("boxy lambda argument pattern bindings disagreed with worker arguments");
        }

        var continuation = next;
        var index = self.lambda_arg_patterns.len;
        while (index > 0) {
            index -= 1;
            const pattern_id = self.lambda_arg_patterns[index];
            const binding_local = self.lambda_arg_binding_locals[index];
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            switch (pattern.data) {
                .assign => {},
                .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => continuation = try self.bindPatternFromLocal(pattern_id, binding_local, continuation),
            }

            const arg_local = self.arg_locals.items[index];
            if (binding_local != arg_local) {
                continuation = try self.assignPlannedCallBoundary(
                    binding_local,
                    arg_local,
                    self.repForType(pattern.ty),
                    self.lambda_arg_worker_reps[index],
                    continuation,
                );
            }
        }
        return continuation;
    }

    fn bindLambdaArgDescriptors(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.lambda_arg_patterns.len == 0) return;
        if (self.lambda_arg_patterns.len > self.arg_locals.items.len or
            self.lambda_arg_patterns.len != self.lambda_arg_binding_locals.len or
            self.lambda_arg_patterns.len != self.lambda_arg_worker_reps.len)
        {
            boxyLowerInvariant("boxy lambda argument descriptor binding disagreed with worker arguments");
        }
        for (
            self.lambda_arg_patterns,
            self.arg_locals.items[0..self.lambda_arg_patterns.len],
            self.lambda_arg_binding_locals,
            self.lambda_arg_worker_reps,
        ) |pattern_id, arg_local, binding_local, worker_rep| {
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            try self.markLocalDescriptorForRep(arg_local, worker_rep);
            if (binding_local == arg_local or self.parent.result.store.getLocal(binding_local).boxy_desc == null) {
                try self.markLocalDescriptorForType(binding_local, pattern.ty);
            }
        }
    }

    fn bindHiddenDescriptorArgs(self: *ProcBodyBuilder) Allocator.Error!void {
        try self.bindPassthroughHiddenDescriptorArgs();
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const params = self.parent.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        if (params.len != 0) try self.prepareHiddenDescriptorArgumentRoots(params);
    }

    /// A static dictionary method adapter accepts the requirement's explicit
    /// ABI but forwards the concrete worker's hidden descriptor suffix. Bind
    /// those descriptor parameters for planned boundary materialization without
    /// attaching them to the adapter's requirement-side argument locals.
    fn bindPassthroughHiddenDescriptorArgs(self: *ProcBodyBuilder) Allocator.Error!void {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const params = self.parent.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        const layouts = self.parent.layout_plan.workerLayoutSlice(self.worker_layout.hidden_descs);
        if (params.len != layouts.len) {
            boxyLowerInvariant("boxy worker hidden descriptor param count disagreed with layout plan");
        }
        if (params.len == 0) return;

        try self.ensureDescriptorLocals();
        for (params, layouts) |param, runtime_layout| {
            const layout_idx = runtime_layout.layoutIdx();
            if (layout_idx != .opaque_ptr) {
                boxyLowerInvariant("boxy hidden descriptor arg layout was not opaque_ptr");
            }
            const local = try self.addArgLocal(layout_idx);
            try self.markReadOnlyDescriptorInput(local);
            try self.bindDescriptorRequirementLocalForRep(param.desc, param.rep, local, true);
            if (self.repOwnsDescriptor(param.rep, param.desc)) {
                try self.bindDescriptorIdentityLocalForRep(param.rep, local, true);
            }
        }
    }

    fn prepareHiddenDescriptorArgumentRoots(
        self: *ProcBodyBuilder,
        worker_params: []const Plan.HiddenDescriptorParam,
    ) Allocator.Error!void {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy worker hidden descriptor params belonged to a non-function representation");
        const args = self.functionArgChildren(function);
        if (args.len > self.arg_locals.items.len) {
            boxyLowerInvariant("boxy worker hidden descriptor params exceeded explicit argument locals");
        }

        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        var next_param: usize = 0;

        for (args, self.arg_locals.items[0..args.len]) |arg, arg_local| {
            var abi_params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer abi_params.deinit(self.parent.allocator);
            try self.collectHiddenDescriptorParamsForRep(.all, arg.rep, &abi_params, &seen_reps, &seen_descs);
            for (abi_params.items) |param| {
                if (next_param >= worker_params.len or
                    worker_params[next_param].desc != param.desc or
                    self.descriptorStorageRep(worker_params[next_param].rep) != self.descriptorStorageRep(param.rep))
                {
                    boxyLowerInvariant("boxy worker argument descriptor traversal disagreed with hidden parameter ABI");
                }
                next_param += 1;
            }

            var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer params.deinit(self.parent.allocator);
            try self.collectAllHiddenDescriptorParamsForRep(arg.rep, &params);

            var root_param_index: ?usize = null;
            var governing_param_index: ?usize = null;
            var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
            defer overrides.deinit(self.parent.allocator);
            var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
            defer bindings.deinit(self.parent.allocator);
            const arg_layout = self.parent.result.store.getLocal(arg_local).layout_idx;
            const governing_rep = if (self.parent.layoutNeedsNestedBoxyDesc(arg_layout))
                self.parent.tagPayloadStorageDescRepForLayout(arg.rep, arg_layout, true)
            else
                null;
            const governing_desc = if (governing_rep) |field_rep|
                self.parent.plan.representations.items[@backingInt(self.descriptorStorageRep(field_rep))].descriptor
            else
                null;
            const arg_identity_rep = self.descriptorShapeIdentityRep(arg.rep);

            for (params.items, 0..) |param, param_index| {
                const local = self.descriptorLocalForRequirementAndRepOrNull(param.desc, param.rep) orelse
                    boxyLowerInvariant("boxy worker argument descriptor had no exact hidden parameter local");
                try self.appendLocalDescriptorEnvironmentBinding(&bindings, param.desc, param.rep, local);
                try self.appendDescriptorIdentityLocalEnvironmentBinding(&bindings, param.desc, param.rep, local);

                if (governing_rep) |field_rep| {
                    if (governing_desc == param.desc and
                        self.descriptorStorageRep(field_rep) == self.descriptorStorageRep(param.rep))
                    {
                        if (governing_param_index != null) {
                            boxyLowerInvariant("boxy worker argument had multiple governing storage descriptors");
                        }
                        governing_param_index = param_index;
                    }
                }

                const is_root = self.repOwnsShapeDescriptor(param.rep, param.desc) and
                    arg_identity_rep == self.descriptorShapeIdentityRep(param.rep);
                if (is_root) {
                    if (root_param_index != null) {
                        boxyLowerInvariant("boxy worker argument had multiple root descriptor parameters");
                    }
                    root_param_index = param_index;
                    continue;
                }
                const identity_rep = self.parent.descriptorIdentityRep(param.rep);
                // A parameter whose representation shares its descriptor
                // identity with another—a box stored exactly as its dynamic
                // payload—describes that same identity. The parameter for the
                // identity itself is the one that overrides it.
                if (identity_rep != param.rep) continue;
                for (overrides.items) |override| {
                    if (override.rep != identity_rep) continue;
                    if (override.local != local) {
                        boxyLowerInvariant("boxy worker argument had conflicting exact descriptors for one representation");
                    }
                    break;
                } else {
                    try overrides.append(self.parent.allocator, .{ .rep = identity_rep, .local = local });
                }
            }
            // A collapsed parameter still overrides an identity that has no
            // parameter of its own.
            for (params.items, 0..) |param, param_index| {
                if (root_param_index == param_index) continue;
                const identity_rep = self.parent.descriptorIdentityRep(param.rep);
                if (identity_rep == param.rep) continue;
                for (overrides.items) |override| {
                    if (override.rep == identity_rep) break;
                } else {
                    const local = self.descriptorLocalForRequirementAndRepOrNull(param.desc, param.rep) orelse
                        boxyLowerInvariant("boxy worker argument descriptor had no exact hidden parameter local");
                    try overrides.append(self.parent.allocator, .{ .rep = identity_rep, .local = local });
                }
            }

            // An open record's descriptor describes the complete record its
            // caller passed; the row's named fields describe only their static view.
            if (root_param_index != null and overrides.items.len != 0 and
                !self.repIsOpenRecord(params.items[root_param_index.?].rep))
            {
                const root_param = params.items[root_param_index.?];
                const rebuilt = try self.addFrameLocal(.opaque_ptr);
                const materialization = try self.descriptorMaterializationForKnownRepWithOverrides(arg.rep, overrides.items);
                try self.worker_argument_desc_initializers.append(self.parent.allocator, materialization.initializer(rebuilt));
                try appendUniqueLocal(self.parent.allocator, &self.runtime_initialized_descriptor_locals, rebuilt);
                try self.recordDescriptorLocalTemplate(rebuilt, materialization);
                try self.bindDescriptorRequirementLocalForRep(root_param.desc, root_param.rep, rebuilt, true);
                if (self.repOwnsDescriptor(root_param.rep, root_param.desc)) {
                    try self.bindDescriptorIdentityLocalForRep(root_param.rep, rebuilt, true);
                }
                for (bindings.items) |*binding| {
                    if (binding.desc == root_param.desc and
                        self.descriptorStorageRep(binding.rep) == self.descriptorStorageRep(root_param.rep))
                    {
                        binding.local = rebuilt;
                    }
                }
            }
            var governing_local = if (governing_param_index) |index|
                self.descriptorLocalForRequirementAndRepOrNull(params.items[index].desc, params.items[index].rep) orelse
                    boxyLowerInvariant("boxy worker argument governing descriptor had no exact local")
            else
                null;
            if (root_param_index != null and governing_param_index == root_param_index and overrides.items.len != 0) {
                governing_local = self.descriptorLocalForRequirementAndRepOrNull(
                    params.items[root_param_index.?].desc,
                    params.items[root_param_index.?].rep,
                );
            }
            if (governing_local) |local| {
                if (self.parent.result.store.getLocal(arg_local).boxy_desc) |existing| {
                    if (existing.localOrNull() != local) {
                        boxyLowerInvariant("boxy worker argument was pre-bound to a different storage descriptor");
                    }
                } else {
                    self.parent.result.store.setLocalBoxyDesc(arg_local, .{ .local = local });
                }
            }
            try self.recordLocalDescriptorEnvironment(arg_local, arg.rep, bindings.items);
        }
    }

    fn bindHiddenDictionaryArgs(self: *ProcBodyBuilder) Allocator.Error!void {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const params = self.parent.plan.hiddenDictionaryParamSlice(worker.hidden_dicts);
        const layouts = self.parent.layout_plan.workerLayoutSlice(self.worker_layout.hidden_dicts);
        if (params.len != layouts.len) {
            boxyLowerInvariant("boxy worker hidden dictionary param count disagreed with layout plan");
        }
        if (params.len == 0) return;

        try self.ensureDictionaryLocals();
        for (params, layouts) |param, runtime_layout| {
            const layout_idx = runtime_layout.layoutIdx();
            if (layout_idx != .opaque_ptr) {
                boxyLowerInvariant("boxy hidden dictionary arg layout was not opaque_ptr");
            }
            const local = try self.addArgLocal(layout_idx);
            if (param.literal_parameter) |index| {
                std.debug.assert(index == self.literal_locals.items.len);
                try self.literal_locals.append(self.parent.allocator, local);
                continue;
            }
            var dict_offset: u32 = 0;
            while (dict_offset < param.dictionaries.len) : (dict_offset += 1) {
                const dict_index: usize = @intCast(param.dictionaries.start + dict_offset);
                self.dictionary_slots[dict_index] = local;
                self.dictionary_locals[dict_index] = local;
                self.dictionary_bound[dict_index] = true;
            }
        }
    }

    fn prepareErasedWorkerCaptures(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.erased_capture_arg != null) {
            boxyLowerInvariant("boxy erased worker capture argument was prepared twice");
        }
        self.erased_capture_arg = try self.addArgLocal(.opaque_ptr);

        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const captures = self.parent.plan.erasedCaptureSlice(worker.erased_captures);
        if (captures.len == 0) return;
        const generated_runtime = switch (worker.source) {
            .generated_codec => |codec| switch (codec.kind) {
                .parser_runtime,
                .encoder_runtime,
                .encoder_record_fields,
                .encoder_dict_fields,
                .encoder_sequence_elements,
                .encoder_tag_payload_elements,
                .encoder_value_thunk,
                .encoder_dict_key_thunk,
                => true,
                .parser_constructor, .encoder_constructor => false,
            },
            .generated_field_iterator => true,
            .procedure_template, .procedure_binding, .procedure_use, .nested_expr => false,
        };

        try self.erased_capture_locals.ensureTotalCapacity(self.parent.allocator, captures.len);
        const source_captures = self.workerSourceCaptures();
        var source_capture_index: usize = 0;

        for (captures) |capture| {
            const local = try self.addFrameLocal(self.erasedCaptureSlotLayout(capture));
            try self.erased_capture_locals.append(self.parent.allocator, local);
            switch (capture.kind) {
                .captured_value => {
                    if (generated_runtime) continue;
                    if (source_capture_index >= source_captures.len) {
                        boxyLowerInvariant("boxy erased capture plan had more value captures than the source closure");
                    }
                    try self.reservePatternBindings(source_captures[source_capture_index].pattern);
                    source_capture_index += 1;
                },
                .hidden_desc => {
                    const desc = capture.desc orelse
                        boxyLowerInvariant("boxy hidden descriptor capture had no descriptor requirement");
                    try self.ensureDescriptorLocals();
                    try self.markReadOnlyDescriptorInput(local);
                    try self.bindDescriptorRequirementLocalForRep(desc, capture.rep, local, true);
                    if (self.repOwnsDescriptor(capture.rep, desc)) {
                        try self.bindDescriptorIdentityLocalForRep(capture.rep, local, true);
                    }
                },
                .hidden_dict => {
                    try self.ensureDictionaryLocals();
                    var dict_offset: u32 = 0;
                    while (dict_offset < capture.dictionaries.len) : (dict_offset += 1) {
                        const dict_index: usize = @intCast(capture.dictionaries.start + dict_offset);
                        self.dictionary_slots[dict_index] = local;
                        self.dictionary_locals[dict_index] = local;
                        self.dictionary_bound[dict_index] = true;
                    }
                },
                .hidden_literal => {
                    std.debug.assert(capture.literal_parameter.? == self.literal_locals.items.len);
                    try self.literal_locals.append(self.parent.allocator, local);
                },
            }
        }
        if (!generated_runtime and source_capture_index != source_captures.len) {
            boxyLowerInvariant("boxy erased capture plan did not cover every source closure capture");
        }

        try self.prepareErasedWorkerCaptureContentsDescriptorEnvironments(captures);
        try self.prepareErasedWorkerCaptureDescriptorEnvironments(captures);
        try self.prepareErasedCapturedValueFieldDescriptors(
            captures,
            self.erased_capture_locals.items,
            &self.erased_capture_value_desc_initializers,
            .reuse_existing,
            null,
        );
    }

    fn prepareErasedWorkerCaptureContentsDescriptorEnvironments(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
    ) Allocator.Error!void {
        if (!self.erasedCaptureNeedsContentsDescriptor(captures, self.erased_capture_locals.items)) return;
        if (self.erased_capture_contents_desc != null) {
            boxyLowerInvariant("boxy erased worker capture contents descriptor was prepared twice");
        }

        const contents_desc = try self.addFrameLocal(.opaque_ptr);
        self.erased_capture_contents_desc = contents_desc;
        try self.markReadOnlyDescriptorInput(contents_desc);

        for (captures, self.erased_capture_locals.items, 0..) |capture, captured_local, capture_index| {
            if (capture.kind != .captured_value) continue;
            const field_layout = self.parent.result.store.getLocal(captured_local).layout_idx;
            if (!self.parent.layoutNeedsNestedBoxyDesc(field_layout)) continue;

            const field_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(capture.rep, field_layout, true) orelse
                boxyLowerInvariant("boxy erased worker capture descriptor did not match its field layout");
            const field_desc_local = try self.addFrameLocal(.opaque_ptr);
            const field_desc_ref = LIR.BoxyDescRef{ .local = field_desc_local };
            self.parent.result.store.setLocalBoxyDesc(captured_local, field_desc_ref);
            try self.erased_capture_value_desc_initializers.append(self.parent.allocator, .{
                .local = field_desc_local,
                .materialize = .{ .local = contents_desc },
                .nested_index = @intCast(capture_index),
            });

            var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
            defer bindings.deinit(self.parent.allocator);
            var initializers = std.ArrayList(DescriptorArgLocal).empty;
            defer initializers.deinit(self.parent.allocator);
            var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer seen.deinit();
            try self.collectDescriptorEnvironmentForRep(
                field_desc_rep,
                field_desc_ref,
                &bindings,
                &initializers,
                &seen,
            );
            for (bindings.items) |*binding| {
                if (self.descriptorBindingIsBoundForRep(binding.rep)) {
                    if (self.descriptorLocalForRequirementAndRepOrNull(binding.desc, binding.rep)) |local| {
                        binding.local = local;
                    } else {
                        try self.bindDescriptorRequirementLocalForRep(binding.desc, binding.rep, binding.local, false);
                    }
                } else {
                    try self.bindDescriptorRequirementLocalForRep(binding.desc, binding.rep, binding.local, false);
                }
            }
            try self.erased_capture_value_desc_initializers.appendSlice(self.parent.allocator, initializers.items);
            try self.recordLocalDescriptorEnvironment(captured_local, capture.rep, bindings.items);
        }
    }

    fn prepareErasedWorkerCaptureDescriptorEnvironments(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
    ) Allocator.Error!void {
        if (captures.len != self.erased_capture_locals.items.len) {
            boxyLowerInvariant("boxy erased worker descriptor environment saw mismatched capture fields");
        }

        for (captures, self.erased_capture_locals.items) |capture, captured_local| {
            if (capture.kind != .captured_value) continue;
            if (self.parent.result.store.getLocal(captured_local).boxy_desc != null) continue;

            var root_desc: ?LIR.BoxyDescRef = null;
            for (captures, self.erased_capture_locals.items) |candidate, candidate_local| {
                if (candidate.kind != .hidden_desc) continue;
                const desc = candidate.desc orelse
                    boxyLowerInvariant("boxy hidden descriptor capture had no descriptor requirement");
                if (!self.repOwnsShapeDescriptor(capture.rep, desc)) continue;
                if (self.descriptorStorageRep(candidate.rep) != self.descriptorStorageRep(capture.rep)) continue;
                if (root_desc != null) {
                    boxyLowerInvariant("boxy erased captured value had multiple root descriptor captures");
                }
                root_desc = .{ .local = candidate_local };
            }
            const desc_ref = root_desc orelse continue;

            var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
            defer bindings.deinit(self.parent.allocator);
            var initializers = std.ArrayList(DescriptorArgLocal).empty;
            defer initializers.deinit(self.parent.allocator);
            var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer seen.deinit();
            try self.collectShapeDescriptorEnvironmentForRep(
                capture.rep,
                desc_ref,
                &bindings,
                &initializers,
                &seen,
            );

            for (bindings.items) |*binding| {
                if (self.descriptorBindingIsBoundForRep(binding.rep)) {
                    if (self.descriptorLocalForRequirementAndRepOrNull(binding.desc, binding.rep)) |local| {
                        binding.local = local;
                    } else {
                        try self.bindDescriptorRequirementLocalForRep(binding.desc, binding.rep, binding.local, false);
                    }
                } else {
                    try self.bindDescriptorRequirementLocalForRep(binding.desc, binding.rep, binding.local, false);
                }
            }
            try self.erased_capture_value_desc_initializers.appendSlice(self.parent.allocator, initializers.items);
            try self.recordLocalDescriptorEnvironment(captured_local, capture.rep, bindings.items);
        }
    }

    fn erasedArgumentDescriptorCaptureOffsets(self: *ProcBodyBuilder) Allocator.Error!LIR.BoxySpan {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy erased worker representation was not a function");
        const children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];

        var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
        defer params.deinit(self.parent.allocator);
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        const param_starts = try self.parent.allocator.alloc(usize, args.len + 1);
        defer self.parent.allocator.free(param_starts);
        param_starts[0] = 0;
        for (args, 0..) |arg, arg_index| {
            try self.collectHiddenDescriptorParamsForRep(.all, arg.rep, &params, &seen_reps, &seen_descs);
            param_starts[arg_index + 1] = params.items.len;
        }
        if (params.items.len == 0) return .{};

        const captures = self.parent.plan.erasedCaptureSlice(worker.erased_captures);
        const capture_layout = self.parent.result.layouts.getLayout(self.worker_layout.erased_capture_layout);
        if (capture_layout.tag != .struct_) {
            boxyLowerInvariant("boxy erased argument descriptors required a non-struct capture layout");
        }
        const start = self.parent.result.boxy_erased_arg_desc_offsets.items.len;
        for (args, 0..) |_, arg_index| {
            const arg_params = params.items[param_starts[arg_index]..param_starts[arg_index + 1]];
            for (arg_params, 0..) |param, descriptor_index| {
                if (arg_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy erased argument descriptor key exceeded its index range");
                }
                if (descriptor_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy erased argument descriptor index exceeded its key range");
                }
                const source = try self.erasedArgumentDescriptorParamSource(arg_params, descriptor_index);
                if (source.read != .call_key) continue;
                var capture_index: ?u32 = null;
                for (captures, 0..) |capture, index| {
                    if (capture.kind != .hidden_desc or
                        capture.desc != param.desc or
                        self.descriptorStorageRep(capture.rep) != self.descriptorStorageRep(param.rep))
                    {
                        continue;
                    }
                    if (capture_index != null) {
                        boxyLowerInvariant("boxy erased argument descriptor had multiple exact hidden capture fields");
                    }
                    capture_index = @intCast(index);
                }
                const index = capture_index orelse
                    boxyLowerInvariant("boxy erased argument descriptor had no hidden capture field");
                try self.parent.result.boxy_erased_arg_desc_offsets.append(self.parent.allocator, .{
                    .key = .{
                        .arg_index = @intCast(arg_index),
                        .descriptor_index = @intCast(descriptor_index),
                    },
                    .offset = self.parent.result.layouts.getStructFieldOffsetByOriginalIndex(capture_layout.getStruct().idx, index),
                });
            }
        }
        return .{
            .start = @intCast(start),
            .len = @intCast(self.parent.result.boxy_erased_arg_desc_offsets.items.len - start),
        };
    }

    fn bindErasedArgumentDescriptorParams(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
    ) Allocator.Error!LIR.BoxySpan {
        const args = self.functionArgChildren(function);
        if (self.arg_locals.items.len < args.len) {
            boxyLowerInvariant("boxy erased descriptor parameters exceeded the explicit argument locals");
        }
        const start = self.parent.result.boxy_erased_arg_desc_params.items.len;
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();

        for (args, 0..) |arg, arg_index| {
            const arg_local = self.arg_locals.items[arg_index];
            const arg_layout = self.parent.result.store.getLocal(arg_local).layout_idx;
            const governing_rep = if (self.parent.layoutNeedsNestedBoxyDesc(arg_layout))
                self.parent.tagPayloadStorageDescRepForLayout(arg.rep, arg_layout, true)
            else
                null;
            const governing_desc = if (governing_rep) |field_rep|
                self.parent.plan.representations.items[@backingInt(self.descriptorStorageRep(field_rep))].descriptor
            else
                null;
            const arg_identity_rep = self.descriptorShapeIdentityRep(arg.rep);
            var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer params.deinit(self.parent.allocator);
            var param_locals = std.ArrayList(LIR.LocalId).empty;
            defer param_locals.deinit(self.parent.allocator);
            var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
            defer bindings.deinit(self.parent.allocator);
            try self.collectHiddenDescriptorParamsForRep(.all, arg.rep, &params, &seen_reps, &seen_descs);
            for (params.items, 0..) |param, param_index| {
                if (arg_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy erased argument descriptor parameter key exceeded its index range");
                }
                if (param_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy erased argument descriptor parameter index exceeded its key range");
                }
                const descriptor_index: u32 = @intCast(param_index);
                const descriptor_source = try self.erasedArgumentDescriptorParamSource(params.items, param_index);
                const is_root_descriptor = self.repOwnsShapeDescriptor(param.rep, param.desc) and
                    arg_identity_rep == self.descriptorShapeIdentityRep(param.rep);
                const governs_arg_storage = if (governing_rep) |field_rep|
                    governing_desc == param.desc and
                        self.descriptorStorageRep(field_rep) == self.descriptorStorageRep(param.rep)
                else
                    is_root_descriptor;
                const existing_root_local = if (governs_arg_storage)
                    if (self.parent.result.store.getLocal(arg_local).boxy_desc) |desc| desc.localOrNull() else null
                else
                    null;
                const local = existing_root_local orelse try self.addFrameLocal(.opaque_ptr);
                try self.markReadOnlyDescriptorInput(local);
                try self.bindDescriptorRequirementLocalForRep(param.desc, param.rep, local, true);
                if (self.repOwnsDescriptor(param.rep, param.desc)) {
                    try self.bindDescriptorIdentityLocalForRep(param.rep, local, true);
                }
                try self.parent.result.boxy_erased_arg_desc_params.append(self.parent.allocator, .{
                    .key = .{
                        .arg_index = @intCast(arg_index),
                        .descriptor_index = descriptor_index,
                    },
                    .local = local,
                    .source_descriptor_index = descriptor_source.descriptor_index,
                    .source_nested_index = descriptor_source.nested_index,
                    .source_tag_name = descriptor_source.tag_name,
                    .read = descriptor_source.read,
                });
            }

            var all_params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer all_params.deinit(self.parent.allocator);
            try self.collectAllHiddenDescriptorParamsForRep(arg.rep, &all_params);
            var governing_param_local: ?LIR.LocalId = null;
            var governing_param_index: ?usize = null;
            for (all_params.items, 0..) |param, param_index| {
                const local = self.descriptorLocalForRequirementAndRepOrNull(param.desc, param.rep) orelse
                    boxyLowerInvariant("boxy erased argument descriptor had no exact ABI parameter local");
                const is_root_descriptor = self.repOwnsShapeDescriptor(param.rep, param.desc) and
                    arg_identity_rep == self.descriptorShapeIdentityRep(param.rep);
                const governs_arg_storage = if (governing_rep) |field_rep|
                    governing_desc == param.desc and
                        self.descriptorStorageRep(field_rep) == self.descriptorStorageRep(param.rep)
                else
                    is_root_descriptor;
                if (governs_arg_storage) {
                    if (governing_param_local != null and governing_param_local.? != local) {
                        boxyLowerInvariant("boxy erased argument had multiple governing descriptor parameters");
                    }
                    governing_param_local = local;
                    governing_param_index = param_index;
                }
                try self.appendLocalDescriptorEnvironmentBinding(&bindings, param.desc, param.rep, local);
                try self.appendDescriptorIdentityLocalEnvironmentBinding(&bindings, param.desc, param.rep, local);
                try param_locals.append(self.parent.allocator, local);
            }

            var root_param_index: ?usize = null;
            var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
            defer overrides.deinit(self.parent.allocator);
            for (all_params.items, param_locals.items, 0..) |param, local, param_index| {
                const is_root = self.repOwnsShapeDescriptor(param.rep, param.desc) and
                    arg_identity_rep == self.descriptorShapeIdentityRep(param.rep);
                if (is_root) {
                    if (root_param_index != null) {
                        boxyLowerInvariant("boxy erased argument had multiple root descriptor parameters");
                    }
                    root_param_index = param_index;
                    continue;
                }
                const identity_rep = self.parent.descriptorIdentityRep(param.rep);
                for (overrides.items) |override| {
                    if (override.rep != identity_rep) continue;
                    if (override.local != local) {
                        boxyLowerInvariant("boxy erased argument had conflicting exact descriptors for one representation");
                    }
                    break;
                } else {
                    try overrides.append(self.parent.allocator, .{ .rep = identity_rep, .local = local });
                }
            }

            var body_root_local = governing_param_local;
            if (root_param_index != null and overrides.items.len != 0 and
                !self.repIsOpenRecord(all_params.items[root_param_index.?].rep))
            {
                const root_param = all_params.items[root_param_index.?];
                const rebuilt = try self.addFrameLocal(.opaque_ptr);
                const materialization = try self.descriptorMaterializationForKnownRepWithOverrides(arg.rep, overrides.items);
                try self.worker_argument_desc_initializers.append(self.parent.allocator, materialization.initializer(rebuilt));
                try appendUniqueLocal(self.parent.allocator, &self.runtime_initialized_descriptor_locals, rebuilt);
                try self.recordDescriptorLocalTemplate(rebuilt, materialization);
                try self.bindDescriptorRequirementLocalForRep(root_param.desc, root_param.rep, rebuilt, true);
                if (self.repOwnsDescriptor(root_param.rep, root_param.desc)) {
                    try self.bindDescriptorIdentityLocalForRep(root_param.rep, rebuilt, true);
                }
                if (governing_param_index == root_param_index) body_root_local = rebuilt;
                for (bindings.items) |*binding| {
                    if (binding.desc == root_param.desc and
                        self.descriptorStorageRep(binding.rep) == self.descriptorStorageRep(root_param.rep))
                    {
                        binding.local = rebuilt;
                    }
                }
            }
            if (body_root_local) |local| {
                if (self.parent.result.store.getLocal(arg_local).boxy_desc) |existing| {
                    if (existing.localOrNull() != local) {
                        boxyLowerInvariant("boxy erased argument value was pre-bound to a different root descriptor");
                    }
                } else {
                    self.parent.result.store.setLocalBoxyDesc(arg_local, .{ .local = local });
                }
            }
            try self.recordLocalDescriptorEnvironment(arg_local, arg.rep, bindings.items);
        }
        return .{
            .start = @intCast(start),
            .len = @intCast(self.parent.result.boxy_erased_arg_desc_params.items.len - start),
        };
    }

    /// The tag name an erased descriptor parameter carries when it is not a
    /// `tag_payload` read; images store fixed bytes for it.
    const no_tag_payload_read: LIR.BoxyNameId = @fromBackingInt(@intCast(std.math.maxInt(u32)));

    const ErasedArgumentDescriptorParamSource = struct {
        descriptor_index: u32,
        nested_index: u32,
        tag_name: LIR.BoxyNameId,
        read: LIR.ErasedArgDescRead,
    };

    /// Every descriptor of an erased argument that an earlier parameter holds
    /// is read from that parent, so any caller supplies it through the
    /// parent's key, whatever its view of the argument's type.
    fn erasedArgumentDescriptorParamSource(
        self: *ProcBodyBuilder,
        params: []const Plan.HiddenDescriptorParam,
        param_index: usize,
    ) Allocator.Error!ErasedArgumentDescriptorParamSource {
        if (param_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("boxy erased argument descriptor source index exceeded its key range");
        }
        const direct = ErasedArgumentDescriptorParamSource{
            .descriptor_index = @intCast(param_index),
            .nested_index = std.math.maxInt(u32),
            .tag_name = no_tag_payload_read,
            .read = .call_key,
        };
        if (param_index == 0) return direct;

        const target_rep = self.descriptorStorageRep(params[param_index].rep);
        var source: ?ErasedArgumentDescriptorParamSource = null;
        for (params[0..param_index], 0..) |candidate, candidate_index| {
            const parent_rep = self.descriptorStorageRep(candidate.rep);
            const projected: ErasedArgumentDescriptorParamSource = if (try self.immediateNestedDescriptorIndexForRep(parent_rep, target_rep)) |nested_index| nested: {
                if (nested_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy erased argument nested descriptor index exceeded its ABI range");
                }
                break :nested .{
                    .descriptor_index = @intCast(candidate_index),
                    .nested_index = @intCast(nested_index),
                    .tag_name = no_tag_payload_read,
                    .read = .nested,
                };
            } else (try self.immediateTagPayloadDescriptorForRep(parent_rep, target_rep, candidate_index)) orelse continue;
            if (source != null) {
                boxyLowerInvariant("boxy erased argument descriptor had multiple direct parent parameters");
            }
            source = projected;
        }
        return source orelse direct;
    }

    /// The tag payload of `parent_rep_id`'s descriptor that describes
    /// `target_rep` directly, read from parameter `parent_index`.
    fn immediateTagPayloadDescriptorForRep(
        self: *ProcBodyBuilder,
        parent_rep_id: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        parent_index: usize,
    ) Allocator.Error!?ErasedArgumentDescriptorParamSource {
        if (self.tagVariantRepForBoundary(parent_rep_id) == null) return null;
        var read_path = std.ArrayList(DescriptorReadStep).empty;
        defer read_path.deinit(self.parent.allocator);
        var active = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer active.deinit();
        if (!try self.findDescriptorReadPath(parent_rep_id, target_rep, &read_path, &active)) return null;
        if (read_path.items.len != 1) return null;
        const payload = switch (read_path.items[0]) {
            .tag_payload => |payload| payload,
            .nested, .tag_ext, .box_payload => return null,
        };
        if (payload.payload_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("boxy erased argument tag payload descriptor index exceeded its ABI range");
        }
        return .{
            .descriptor_index = @intCast(parent_index),
            .nested_index = @intCast(payload.payload_index),
            .tag_name = payload.tag_name,
            .read = .tag_payload,
        };
    }

    fn prependErasedCaptureBindings(self: *ProcBodyBuilder, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const captures = self.parent.plan.erasedCaptureSlice(worker.erased_captures);
        if (captures.len == 0) return next;
        if (captures.len != self.erased_capture_locals.items.len) {
            boxyLowerInvariant("boxy erased capture local count disagreed with capture plan");
        }

        const capture_arg = self.erased_capture_arg orelse
            boxyLowerInvariant("boxy erased capture bindings had no capture pointer argument");
        const capture_layout = if (self.erased_capture_contents_desc != null)
            try self.erasedCaptureLayoutWithOnDropDescriptor(self.worker_layout.erased_capture_layout, captures.len)
        else
            self.worker_layout.erased_capture_layout;
        const capture_value = try self.addFrameLocal(capture_layout);
        const source_captures = self.workerSourceCaptures();
        const generated_runtime = switch (worker.source) {
            .generated_codec => |codec| switch (codec.kind) {
                .parser_runtime,
                .encoder_runtime,
                .encoder_record_fields,
                .encoder_dict_fields,
                .encoder_sequence_elements,
                .encoder_tag_payload_elements,
                .encoder_value_thunk,
                .encoder_dict_key_thunk,
                => true,
                .parser_constructor, .encoder_constructor => false,
            },
            .generated_field_iterator => true,
            .procedure_template, .procedure_binding, .procedure_use, .nested_expr => false,
        };

        var continuation = next;
        var source_capture_index = source_captures.len;
        var index = captures.len;
        while (index > 0) {
            index -= 1;
            const capture = captures[index];
            const slot_local = self.erased_capture_locals.items[index];
            if (capture.kind != .captured_value) continue;
            if (generated_runtime) {
                continuation = try self.prependErasedCaptureSlotRead(slot_local, capture_value, @intCast(index), continuation);
                continue;
            }
            if (source_capture_index == 0) {
                boxyLowerInvariant("boxy erased capture binding underflowed source captures");
            }
            source_capture_index -= 1;
            const pattern_id = source_captures[source_capture_index].pattern;
            const pattern_rep = self.repForType(self.module.checked_bodies.pattern(pattern_id).ty);
            // A recursive value's slot is filled before any call can run this
            // worker, so its value is read once on entry. The slot stays in
            // scope for callables this worker builds that capture it too.
            const slot_wrapper_rep = if (capture.recursive_slot)
                self.repQuery().requiredSingleChild(capture.rep, .box_payload).rep
            else
                null;
            const value_rep = if (slot_wrapper_rep) |wrapper_rep|
                self.repQuery().requiredSingleChild(wrapper_rep, .{ .tuple_elem = 0 }).rep
            else
                capture.rep;
            const slot_wrapper_local = if (slot_wrapper_rep) |wrapper_rep| wrapper: {
                const local = try self.addFrameLocal(self.workerRuntimeLayoutForRep(wrapper_rep).layoutIdx());
                try self.prepareRecursiveValueSlotRead(local, wrapper_rep);
                break :wrapper local;
            } else null;
            const value_local = if (capture.recursive_slot) recursive: {
                const local = try self.addFrameLocal(self.workerRuntimeLayoutForRep(value_rep).layoutIdx());
                try self.prepareRecursiveValueSlotRead(local, value_rep);
                break :recursive local;
            } else slot_local;
            const binding_local = if (self.representationBoundaryIsDirect(pattern_rep, value_rep))
                value_local
            else
                try self.addFrameBoundaryTargetLocalForRep(pattern_rep);
            continuation = try self.bindPatternFromLocal(pattern_id, binding_local, continuation);
            if (binding_local != value_local) {
                continuation = try self.assignPlannedCallBoundary(
                    binding_local,
                    value_local,
                    pattern_rep,
                    value_rep,
                    continuation,
                );
            }
            if (capture.recursive_slot) {
                try self.recursive_value_slots.put(
                    self.parent.allocator,
                    source_captures[source_capture_index].capture_id.binder(),
                    slot_local,
                );
                const wrapper_local = slot_wrapper_local.?;
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = value_local,
                    .op = .{ .field = .{ .source = wrapper_local, .field_idx = 0 } },
                    .next = continuation,
                } }, self.glueOrigin());
                continuation = try self.assignUnaryLowLevel(wrapper_local, .box_unbox, slot_local, continuation);
            }
            continuation = try self.prependErasedCaptureSlotRead(slot_local, capture_value, @intCast(index), continuation);
        }
        if (!generated_runtime and source_capture_index != 0) {
            boxyLowerInvariant("boxy erased capture binding did not cover every source capture");
        }

        continuation = try self.prependDescriptorArgMaterializations(
            self.erased_capture_value_desc_initializers.items,
            continuation,
        );

        index = captures.len;
        while (index > 0) {
            index -= 1;
            const capture = captures[index];
            if (capture.kind == .captured_value) continue;
            const slot_local = self.erased_capture_locals.items[index];
            continuation = try self.prependErasedCaptureSlotRead(slot_local, capture_value, @intCast(index), continuation);
        }

        if (self.erased_capture_contents_desc) |contents_desc| {
            continuation = try self.prependErasedCaptureSlotRead(
                contents_desc,
                capture_value,
                @intCast(captures.len),
                continuation,
            );
        }

        const args = [_]LIR.LocalId{capture_arg};
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = capture_value,
            .op = .erased_capture_load,
            .rc_effect = LIR.LowLevel.erased_capture_load.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&args),
            .next = continuation,
        } }, self.scaffoldOrigin());
    }

    /// Read each open record descriptor the worker's own dictionaries supply
    /// on entry, before any body statement observes it.
    fn bindWorkerDictionaryDescriptors(self: *ProcBodyBuilder) Allocator.Error!void {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        for (self.parent.plan.workerDictionaryDescriptorSlice(worker.dictionary_descs)) |entry| {
            const dict_local = self.dictionaryLocalForRequirementOrNull(entry.requirement) orelse
                boxyLowerInvariant("boxy worker dictionary descriptor had no bound dictionary");
            const requirement = self.parent.plan.dictionaries.items[@backingInt(entry.requirement)];
            const desc = self.parent.plan.representations.items[@backingInt(entry.rep)].descriptor orelse
                boxyLowerInvariant("boxy worker dictionary descriptor representation had no descriptor");
            const local = try self.addFrameLocal(.opaque_ptr);
            try self.worker_argument_desc_initializers.append(self.parent.allocator, .{
                .local = local,
                .materialize = .{ .dict_method_hidden = .{
                    .dict = dict_local,
                    .method = requirement.fn_name,
                    .method_slot = requirement.slot,
                    .hidden_index = entry.hidden_index,
                    .shape = .requirement,
                } },
            });
            try self.bindDescriptorRequirementLocalForRep(desc, entry.rep, local, true);
        }
    }

    fn prependWorkerArgumentDescriptorInitializers(
        self: *ProcBodyBuilder,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.prependDescriptorArgMaterializations(
            self.worker_argument_desc_initializers.items,
            next,
        );
    }

    fn prependErasedCaptureSlotRead(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        capture_value: LIR.LocalId,
        field_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(target)) return try self.assignZst(target, next);
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .field = .{
                .source = capture_value,
                .field_idx = field_index,
            } },
            .next = next,
        } }, self.scaffoldOrigin());
    }

    fn erasedCaptureSlotLayout(self: *ProcBodyBuilder, capture: Plan.ErasedCapture) layout.Idx {
        return switch (capture.kind) {
            .captured_value => self.workerRuntimeLayoutForRep(capture.rep).layoutIdx(),
            .hidden_desc, .hidden_dict, .hidden_literal => .opaque_ptr,
        };
    }

    fn workerSourceCaptures(self: *ProcBodyBuilder) []const checked.CheckedCapture {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        return switch (worker.source) {
            .nested_expr => |expr_ref| nestedCallableExprRuntimeCaptures(procedureModuleById(self.parent.modules, expr_ref.module), expr_ref.expr),
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .generated_codec,
            .generated_field_iterator,
            => &.{},
        };
    }

    /// One pending piece of expression lowering. Lowering builds statements
    /// from the continuation backwards, so each piece waits on the components
    /// it lowers: a component's entry statement becomes the continuation of
    /// the component lowered before it. Source nesting therefore becomes
    /// frames on an explicit stack rather than native calls.
    const ExprTask = union(enum) {
        expr: struct { target: LIR.LocalId, expr_id: checked.CheckedExprId, next: LIR.CFStmtId },
        expected: struct { target: LIR.LocalId, expected_ty: checked.CheckedTypeId, expr_id: checked.CheckedExprId, next: LIR.CFStmtId },
        expected_ref: struct { target: LIR.LocalId, expected_ty: Plan.CheckedTypeIdentity, expr_id: checked.CheckedExprId, next: LIR.CFStmtId },
        into_rep: struct { target: LIR.LocalId, target_rep: Plan.TypeRepId, expr_id: checked.CheckedExprId, next: LIR.CFStmtId },
        payload_storage: struct { target: LIR.LocalId, target_rep: Plan.TypeRepId, expr_id: checked.CheckedExprId, next: LIR.CFStmtId },
        list: struct { target: LIR.LocalId, list_ty: checked.CheckedTypeId, items: []const checked.CheckedExprId, next: LIR.CFStmtId },
        tuple_rep: struct { target: LIR.LocalId, rep_id: Plan.TypeRepId, items: []const checked.CheckedExprId, next: LIR.CFStmtId },
        tag_rep: struct { target: LIR.LocalId, tag_ty: checked.CheckedTypeId, rep_id: Plan.TypeRepId, name: names.TagNameId, args: []const checked.CheckedExprId, next: LIR.CFStmtId },
        tag_variant: struct { target: LIR.LocalId, rep_id: Plan.TypeRepId, variant: TagVariantLookup, args: []const checked.CheckedExprId, next: LIR.CFStmtId },
        record_rep: struct {
            target: LIR.LocalId,
            record_expr: checked.CheckedExprId,
            rep_id: Plan.TypeRepId,
            expr_fields: []const checked.CheckedRecordExprField,
            unset_fields: []const check.CanonicalNames.RecordFieldLabelId,
            extension: ?RecordExtension,
            next: LIR.CFStmtId,
        },
        defaulted_field: struct { field_module: ProcedureModuleView, target: LIR.LocalId, default: checked.CheckedFieldDefault, field_type: Plan.CheckedTypeIdentity, next: LIR.CFStmtId },
        module_expr: struct {
            expr_module: ProcedureModuleView,
            target: LIR.LocalId,
            expr_id: checked.CheckedExprId,
            /// The type the expression is lowered at, when it differs from
            /// the expression's own.
            expected: ?Plan.CheckedTypeIdentity = null,
            next: LIR.CFStmtId,
            saved: ?ModuleExprSaved = null,
        },
        statement: struct { statement_id: checked.CheckedStatementId, next: LIR.CFStmtId },
        decl_pattern: struct { pattern: checked.CheckedPatternId, expr: checked.CheckedExprId, next: LIR.CFStmtId },
        if_: struct {
            target: LIR.LocalId,
            if_ty: checked.CheckedTypeId,
            branches: []const checked.CheckedIfBranch,
            final_else: checked.CheckedExprId,
            next: LIR.CFStmtId,
            done: LIR.JoinPointId = undefined,
            index: usize = 0,
            current: LIR.CFStmtId = undefined,
        },
        bool_binop: struct {
            target: LIR.LocalId,
            op: can.CIR.Expr.Binop.Op,
            lhs: checked.CheckedExprId,
            rhs: checked.CheckedExprId,
            next: LIR.CFStmtId,
            true_body: LIR.CFStmtId = undefined,
            false_body: LIR.CFStmtId = undefined,
        },
        match_: struct {
            target: LIR.LocalId,
            match_ty: checked.CheckedTypeId,
            cond: checked.CheckedExprId,
            branches: []const checked.CheckedMatchBranch,
            next: LIR.CFStmtId,
            cond_local: LIR.LocalId = undefined,
            cond_rep: Plan.TypeRepId = undefined,
            outer_descriptors: ?DescriptorBindingsSnapshot = null,
            done: LIR.JoinPointId = undefined,
            index: usize = 0,
            current: LIR.CFStmtId = undefined,
            condition_started: bool = false,
        },
        match_branch: struct {
            branch: checked.CheckedMatchBranch,
            source: LIR.LocalId,
            source_rep: Plan.TypeRepId,
            target: LIR.LocalId,
            result_ty: checked.CheckedTypeId,
            done: LIR.JoinPointId,
            next: LIR.CFStmtId,
            outer_descriptors: ?DescriptorBindingsSnapshot = null,
            branch_body: LIR.CFStmtId = undefined,
            on_match: LIR.CFStmtId = undefined,
            alternatives_started: bool = false,
            /// The alternative whose pattern is being lowered; the ones after
            /// it are done.
            alt_index: usize = 0,
            alt_current: LIR.CFStmtId = undefined,
            alt_miss: ?PatternMiss = null,
            alt_snapshot: ?DescriptorBindingsSnapshot = null,
        },
        shared_rep: struct { target: LIR.LocalId, target_rep: Plan.TypeRepId, expr_id: checked.CheckedExprId, next: LIR.CFStmtId },
        while_: struct {
            cond_id: checked.CheckedExprId,
            body_id: checked.CheckedExprId,
            can_exit: bool,
            next: LIR.CFStmtId,
            cond_local: LIR.LocalId = undefined,
            join_id: LIR.JoinPointId = undefined,
            after_loop: LIR.CFStmtId = undefined,
            loop_pushed: bool = false,
        },
        iter_dispatch: struct {
            target: LIR.LocalId,
            plan_id: static_dispatch.IteratorForPlanId,
            kind: Plan.IteratorCallKind,
            plan: static_dispatch.IteratorForPlan,
            call: static_dispatch.IteratorDispatchCall,
            loop_iterator: ?LIR.LocalId,
            next: LIR.CFStmtId,
            snapshot: ?DescriptorBindingsSnapshot = null,
        },
        iterator_for: struct {
            target: LIR.LocalId,
            for_: ForLoop,
            next: LIR.CFStmtId,
            state: ?*IteratorForState = null,
        },
        iterator_loop_body: struct {
            target: LIR.LocalId,
            for_: ForLoop,
            plan_id: static_dispatch.IteratorForPlanId,
            plan: static_dispatch.IteratorForPlan,
            step_ty: Plan.CheckedTypeIdentity,
            iterator_param: LIR.LocalId,
            join_id: LIR.JoinPointId,
            next: LIR.CFStmtId,
            step: IteratorStepShape = undefined,
            step_local: LIR.LocalId = undefined,
            dynamic: bool = false,
            done_variant: TagVariantLookup = undefined,
            one_variant: TagVariantLookup = undefined,
            skip_variant: TagVariantLookup = undefined,
            done_body: LIR.CFStmtId = undefined,
        },
        iterator_one_branch: struct {
            for_: ForLoop,
            step: IteratorStepShape,
            step_local: LIR.LocalId,
            variant_index: ?u32,
            iterator_param: LIR.LocalId,
            join_id: LIR.JoinPointId,
            next: LIR.CFStmtId,
            payload: LIR.LocalId = undefined,
            payload_desc: ?LIR.LocalId = undefined,
            item: LIR.LocalId = undefined,
            rest: LIR.LocalId = undefined,
            miss: ?PatternMiss = null,
        },
        const_node: struct { target: LIR.LocalId, store_module: ProcedureModuleView, type_module: ProcedureModuleView, node: checked.ConstNodeId, checked_ty: checked.CheckedTypeId, next: LIR.CFStmtId },
        stored_node: struct { target: LIR.LocalId, store_module: ProcedureModuleView, node: checked.ConstNodeId, stored_type: check.ConstStore.ConstTypeId, rep_id: Plan.TypeRepId, next: LIR.CFStmtId },
        const_storage: struct { storage_local: LIR.LocalId, store_module: ProcedureModuleView, type_module: ProcedureModuleView, node: checked.ConstNodeId, value_ty: checked.CheckedTypeId, storage_rep: Plan.TypeRepId, next: LIR.CFStmtId },
        stored_storage: struct { storage_local: LIR.LocalId, store_module: ProcedureModuleView, node: checked.ConstNodeId, stored_type: check.ConstStore.ConstTypeId, value_rep: Plan.TypeRepId, next: LIR.CFStmtId },
        const_optional_slot: struct { target: LIR.LocalId, store_module: ProcedureModuleView, type_module: ProcedureModuleView, node: checked.ConstNodeId, payload_ty: checked.CheckedTypeId, slot_rep: Plan.TypeRepId, next: LIR.CFStmtId },
        planned_call: struct {
            target: LIR.LocalId,
            target_rep: Plan.TypeRepId,
            checked_ret_ty: checked.CheckedTypeId,
            direct_plan: Plan.DirectCallPlan,
            next: LIR.CFStmtId,
            state: ?*PlannedCallState = null,
        },
        pattern: PatternTask,
        /// Expressions lowered into a struct's fields.
        exprs_struct: struct {
            target: LIR.LocalId,
            target_rep: ?Plan.TypeRepId,
            items: []const checked.CheckedExprId,
            item_reps: []const Plan.RepChild,
            next: LIR.CFStmtId,
        },
        /// A stored constant restored at its stored representation and
        /// converted into `target_rep`.
        stored_across: struct { target: LIR.LocalId, store_module: ProcedureModuleView, node: checked.ConstNodeId, stored_type: check.ConstStore.ConstTypeId, target_rep: Plan.TypeRepId, stored_rep: Plan.TypeRepId, next: LIR.CFStmtId },
        chain: ExprChain,
    };

    /// The builder state a module-context swap replaced.
    const ModuleExprSaved = struct {
        module: ProcedureModuleView,
        binder_locals: []?LIR.LocalId,
        binder_reps: []?Plan.TypeRepId,
        lambda_arg_patterns: []const checked.CheckedPatternId,
        lambda_arg_binding_locals: []LIR.LocalId,
        lambda_arg_worker_reps: []Plan.TypeRepId,
        current_lambda: ?checked.CheckedExprId,
    };

    /// What a planned worker call keeps between lowering its operands and
    /// building the call they feed.
    const PlannedCallState = struct {
        descriptor_snapshot: DescriptorBindingsSnapshot,
        operand_types: []Plan.CheckedTypeIdentity,
        call_types: []Plan.CheckedTypeIdentity,
        storage_arg_reps: []Plan.TypeRepId,
        actual_arg_reps: []Plan.TypeRepId,
        lowered: []LIR.LocalId,
        call_result_target: LIR.LocalId,
        continuation: LIR.CFStmtId,
        call_placeholder: LIR.CFStmtId,
    };

    /// A sequence of lowering pieces and statement builders applied from the
    /// continuation backwards: each lowering piece continues into the
    /// statement built so far, and each builder wraps it.
    const ExprChain = struct {
        items: []ExprChainItem,
        index: usize = 0,
        current: LIR.CFStmtId,
        /// Aggregate descriptor state the chain's builders read.
        aggregate_desc: ?ConstructedAggregateDescriptor = null,
        /// A nominal backing formal scope the chain leaves, dropped on error.
        scope: ?NominalBackingFormalScope = null,
        /// Locals a builder records, owned by the chain.
        locals: []LIR.LocalId = &.{},
        /// Descriptor bindings to restore once a piece lowered under a
        /// shared descriptor is done.
        snapshot: ?DescriptorBindingsSnapshot = null,
    };

    const ExprChainItem = union(enum) {
        /// Lower a piece continuing into the current statement.
        lower: ExprTask,
        propagate_desc: struct { target: LIR.LocalId, source: LIR.LocalId },
        /// Materialize the aggregate descriptor's field initializers.
        prepend_field_initializers,
        /// Record the aggregate environment of `target` over the chain's locals.
        record_aggregate_env: struct { target: LIR.LocalId, rep_id: Plan.TypeRepId },
        /// Leave the chain's nominal backing formal scope.
        leave_scope,
        str_concat: struct { target: LIR.LocalId, lhs: LIR.LocalId, rhs: LIR.LocalId },
        missing_optional_slot: struct { target: LIR.LocalId, rep: Plan.TypeRepId },
        record_ext_field: struct { field_local: LIR.LocalId, target_rep: Plan.TypeRepId, ext_local: LIR.LocalId, ext_rep: Plan.TypeRepId, field_view: ProcedureModuleView, label: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label) },
        /// A call operand lowered into its local at the call's expected type.
        call_operand: struct {
            operand: Plan.CallOperand,
            operand_type: Plan.CheckedTypeIdentity,
            arg_type: Plan.CheckedTypeIdentity,
            storage_arg_rep: Plan.TypeRepId,
            lowered: LIR.LocalId,
        },
        boundary_assign: struct { target: LIR.LocalId, source: LIR.LocalId, target_rep: Plan.TypeRepId, source_rep: Plan.TypeRepId },
        const_list_element_box: struct { elem_local: LIR.LocalId, source: LIR.LocalId, source_elem_rep: Plan.TypeRepId },
        /// Mark a shared descriptor bound, keeping the bindings to restore.
        bind_shared_descriptor: LIR.LocalId,
        /// Restore the bindings `bind_shared_descriptor` kept.
        restore_descriptors,
        /// Materialize descriptor initializers, owning the slice.
        prepend_descriptor_initializers: []DescriptorArgLocal,
        capture_snapshots: checked.CheckedExprId,
        recursive_value_slots: checked.CheckedPatternId,
        runtime_error,
        /// Crash when a declaration's pattern misses.
        pattern_miss_crash: LIR.JoinPointId,
        /// Record a local's descriptor environment, owning the bindings.
        record_local_env: struct { target: LIR.LocalId, rep: Plan.TypeRepId, bindings: []LocalDescriptorEnvironmentBinding },
        /// Build the adapter a raw callable value continues into.
        callable_adapter: CallableAdapterBoundary,
    };

    const ExprFrame = struct {
        task: ExprTask,
        stage: u32 = 0,
        /// The origin this frame lowers under.
        origin: LIR.StmtOrigin,
    };

    const ExprStep = union(enum) {
        /// Lower a piece; the frame resumes with its entry statement.
        child: ExprTask,
        /// This frame's result is the piece's result.
        tail: ExprTask,
        done: LIR.CFStmtId,
    };

    fn exprDone(stmt: LIR.CFStmtId) ExprStep {
        return .{ .done = stmt };
    }

    /// A chain step over `items`, continuing into `next`.
    fn exprChain(items: []ExprChainItem, next: LIR.CFStmtId) ExprStep {
        return .{ .tail = .{ .chain = .{ .items = items, .current = next } } };
    }

    fn withNext(task: ExprTask, next: LIR.CFStmtId) ExprTask {
        var copy = task;
        switch (copy) {
            .chain => |*chain| chain.current = next,
            inline .expr, .expected, .expected_ref, .into_rep, .payload_storage, .list, .tuple_rep, .tag_rep, .tag_variant, .record_rep, .defaulted_field, .module_expr, .statement, .decl_pattern, .if_, .bool_binop, .match_, .match_branch, .shared_rep, .while_, .iter_dispatch, .iterator_for, .iterator_loop_body, .iterator_one_branch, .const_node, .stored_node, .const_storage, .stored_storage, .const_optional_slot, .planned_call, .pattern, .stored_across, .exprs_struct => |*payload| payload.next = next,
        }
        return copy;
    }

    fn runExprTasks(self: *ProcBodyBuilder, root: ExprTask) Allocator.Error!LIR.CFStmtId {
        const saved_origin = self.origin;
        defer self.origin = saved_origin;
        var frames = std.ArrayList(ExprFrame).empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseExprTask(&frames.items[index].task);
            }
            frames.deinit(self.parent.allocator);
        }
        try frames.append(self.parent.allocator, .{ .task = root, .origin = self.origin });
        var input: ?LIR.CFStmtId = null;
        while (true) {
            const frame = &frames.items[frames.items.len - 1];
            self.origin = frame.origin;
            const stage = frame.stage;
            frame.stage += 1;
            const step = try self.stepExprTask(&frame.task, stage, input);
            input = null;
            // A piece that set its own origin lowers the rest of its stages,
            // and the pieces it waits on, under it.
            frame.origin = self.origin;
            switch (step) {
                .child => |task| try frames.append(self.parent.allocator, .{ .task = task, .origin = self.origin }),
                .tail => |task| {
                    self.releaseExprTask(&frame.task);
                    frame.* = .{ .task = task, .origin = self.origin };
                },
                .done => |stmt| {
                    var finished = frames.pop().?;
                    self.releaseExprTask(&finished.task);
                    if (frames.items.len == 0) return stmt;
                    input = stmt;
                },
            }
        }
    }

    /// Free what an unfinished task owns and undo the scopes it holds, as
    /// the direct lowering's defers would. Idempotent.
    fn releaseExprTask(self: *ProcBodyBuilder, task: *ExprTask) void {
        switch (task.*) {
            .chain => |*chain| {
                for (chain.items[chain.index..]) |item| switch (item) {
                    .record_local_env => |env| self.parent.allocator.free(env.bindings),
                    .prepend_descriptor_initializers => |initializers| self.parent.allocator.free(initializers),
                    .capture_snapshots, .recursive_value_slots, .lower, .propagate_desc, .prepend_field_initializers, .record_aggregate_env, .leave_scope, .str_concat, .missing_optional_slot, .record_ext_field, .call_operand, .boundary_assign, .const_list_element_box, .bind_shared_descriptor, .restore_descriptors, .runtime_error, .pattern_miss_crash, .callable_adapter => {},
                };
                if (chain.scope) |scope| self.dropNominalBackingFormalScope(scope);
                chain.scope = null;
                if (chain.aggregate_desc) |desc| desc.deinit(self.parent.allocator);
                chain.aggregate_desc = null;
                if (chain.snapshot) |snapshot| snapshot.deinit(self.parent.allocator);
                chain.snapshot = null;
                self.parent.allocator.free(chain.locals);
                chain.locals = &.{};
                self.parent.allocator.free(chain.items);
                chain.items = &.{};
            },
            .module_expr => |*module_expr| {
                if (module_expr.saved) |saved| self.restoreModuleExprContext(saved);
                module_expr.saved = null;
            },
            .planned_call => |*call| {
                if (call.state) |state| {
                    self.restoreDescriptorBindings(state.descriptor_snapshot);
                    self.freePlannedCallState(state);
                }
                call.state = null;
            },
            .match_ => |*match_| {
                if (match_.outer_descriptors) |snapshot| snapshot.deinit(self.parent.allocator);
                match_.outer_descriptors = null;
            },
            .match_branch => |*branch| {
                if (branch.outer_descriptors) |snapshot| snapshot.deinit(self.parent.allocator);
                branch.outer_descriptors = null;
                if (branch.alt_snapshot) |snapshot| snapshot.deinit(self.parent.allocator);
                branch.alt_snapshot = null;
            },
            .pattern => |*pattern| {
                if (pattern.state) |state| self.releasePatternState(state);
                pattern.state = null;
            },
            .iter_dispatch => |*dispatch| {
                if (dispatch.snapshot) |snapshot| {
                    self.restoreDescriptorBindings(snapshot);
                    snapshot.deinit(self.parent.allocator);
                }
                dispatch.snapshot = null;
            },
            .iterator_for => |*for_task| {
                if (for_task.state) |state| self.freeIteratorForState(state);
                for_task.state = null;
            },
            .iterator_loop_body, .iterator_one_branch => {},
            .while_ => |*while_| {
                if (while_.loop_pushed) _ = self.loop_stack.pop();
                while_.loop_pushed = false;
            },
            .expr, .expected, .expected_ref, .into_rep, .payload_storage, .list, .tuple_rep, .tag_rep, .tag_variant, .record_rep, .defaulted_field, .statement, .decl_pattern, .if_, .bool_binop, .shared_rep, .const_node, .stored_node, .const_storage, .stored_storage, .const_optional_slot, .stored_across, .exprs_struct => {},
        }
    }

    fn freePlannedCallState(self: *ProcBodyBuilder, state: *PlannedCallState) void {
        const allocator = self.parent.allocator;
        state.descriptor_snapshot.deinit(allocator);
        allocator.free(state.operand_types);
        allocator.free(state.call_types);
        allocator.free(state.storage_arg_reps);
        allocator.free(state.actual_arg_reps);
        allocator.free(state.lowered);
        allocator.destroy(state);
    }

    fn restoreModuleExprContext(self: *ProcBodyBuilder, saved: ModuleExprSaved) void {
        self.parent.allocator.free(self.binder_reps);
        self.parent.allocator.free(self.binder_locals);
        self.module = saved.module;
        self.binder_locals = saved.binder_locals;
        self.binder_reps = saved.binder_reps;
        self.lambda_arg_patterns = saved.lambda_arg_patterns;
        self.lambda_arg_binding_locals = saved.lambda_arg_binding_locals;
        self.lambda_arg_worker_reps = saved.lambda_arg_worker_reps;
        self.current_lambda = saved.current_lambda;
    }

    fn stepExprTask(self: *ProcBodyBuilder, task: *ExprTask, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        return switch (task.*) {
            .expr => |t| try self.beginExpr(t.target, t.expr_id, t.next),
            .expected => |t| try self.beginExprExpected(t.target, t.expected_ty, t.expr_id, t.next),
            .expected_ref => |t| try self.beginExprExpectedTypeRef(t.target, t.expected_ty, t.expr_id, t.next),
            .into_rep => |t| try self.beginExprIntoRep(t.target, t.target_rep, t.expr_id, t.next),
            .payload_storage => |t| try self.beginExprIntoTagPayloadStorage(t.target, t.target_rep, t.expr_id, t.next),
            .list => |t| try self.beginList(t.target, t.list_ty, t.items, t.next),
            .tuple_rep => |t| try self.beginTupleRep(t.target, t.rep_id, t.items, t.next),
            .tag_rep => |t| try self.beginTagRep(t.target, t.tag_ty, t.rep_id, t.name, t.args, t.next),
            .tag_variant => |t| try self.beginPlannedTagVariant(t.target, t.rep_id, t.variant, t.args, t.next),
            .record_rep => |t| try self.beginRecordRep(t.target, t.record_expr, t.rep_id, t.expr_fields, t.unset_fields, t.extension, t.next),
            .defaulted_field => |t| try self.beginDefaultedRecordField(t.field_module, t.target, t.default, t.field_type, t.next),
            .module_expr => |*t| try self.stepModuleExpr(t, stage, input),
            .statement => |t| try self.beginStatement(t.statement_id, t.next),
            .decl_pattern => |t| try self.beginDeclPattern(t.pattern, t.expr, t.next),
            .if_ => |*t| try self.stepIf(t, stage, input),
            .bool_binop => |*t| try self.stepBoolBinop(t, stage, input),
            .shared_rep => |t| try self.beginSharedRep(t.target, t.target_rep, t.expr_id, t.next),
            .while_ => |*t| try self.stepWhile(t, stage, input),
            .const_node => |t| try self.beginRestoreConstNode(t.target, t.store_module, t.type_module, t.node, t.checked_ty, t.next),
            .stored_node => |t| try self.beginRestoreStoredConstNode(t.target, t.store_module, t.node, t.stored_type, t.rep_id, t.next),
            .const_storage => |t| try self.beginRestoreConstIntoStorageRep(t.storage_local, t.store_module, t.type_module, t.node, t.value_ty, t.storage_rep, t.next),
            .stored_storage => |t| try self.beginRestoreStoredConstIntoStorageRep(t.storage_local, t.store_module, t.node, t.stored_type, t.value_rep, t.next),
            .const_optional_slot => |t| try self.beginRestoreConstOptionalSlot(t.target, t.store_module, t.type_module, t.node, t.payload_ty, t.slot_rep, t.next),
            .iter_dispatch => |*t| try self.stepIteratorDispatch(t, stage, input),
            .iterator_for => |*t| try self.stepIteratorFor(t, stage, input),
            .iterator_loop_body => |*t| try self.stepIteratorLoopBody(t, stage, input),
            .iterator_one_branch => |*t| try self.stepIteratorOneBranch(t, stage, input),
            .match_ => |*t| try self.stepMatch(t, stage, input),
            .match_branch => |*t| try self.stepMatchBranch(t, stage, input),
            .planned_call => |*t| try self.stepPlannedWorkerCall(t, stage, input),
            .pattern => |*t| try self.stepPattern(t, input),
            .exprs_struct => |t| try self.beginExprsAsStructWithReps(t.target, t.target_rep, t.items, t.item_reps, t.next),
            .stored_across => |t| try self.beginRestoreStoredConstNodeAcrossBoundary(t.target, t.store_module, t.node, t.stored_type, t.target_rep, t.stored_rep, t.next),
            .chain => |*chain| try self.stepExprChain(chain, input),
        };
    }

    fn stepExprChain(self: *ProcBodyBuilder, chain: *ExprChain, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        if (input) |stmt| chain.current = stmt;
        while (chain.index < chain.items.len) {
            const item = chain.items[chain.index];
            chain.index += 1;
            chain.current = switch (item) {
                .lower => |task| return .{ .child = withNext(task, chain.current) },
                .propagate_desc => |pair| blk: {
                    self.propagateBoundaryDescriptorMetadata(pair.target, pair.source);
                    break :blk chain.current;
                },
                .prepend_field_initializers => try self.prependDescriptorArgMaterializations(chain.aggregate_desc.?.field_initializers, chain.current),
                .record_aggregate_env => |env| blk: {
                    try self.recordAggregateLocalDescriptorEnvironment(env.target, env.rep_id, chain.locals);
                    break :blk chain.current;
                },
                .leave_scope => blk: {
                    const scope = chain.scope.?;
                    chain.scope = null;
                    break :blk try self.leaveNominalBackingFormalScope(scope, chain.current);
                },
                .str_concat => |concat| blk: {
                    const args = [_]LIR.LocalId{ concat.lhs, concat.rhs };
                    break :blk try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                        .target = concat.target,
                        .op = .str_concat,
                        .rc_effect = LIR.LowLevel.str_concat.rcEffect(),
                        .args = try self.parent.result.store.addLocalSpan(&args),
                        .next = chain.current,
                    } }, self.origin);
                },
                .missing_optional_slot => |slot| return .{ .child = .{ .tag_variant = .{
                    .target = slot.target,
                    .rep_id = slot.rep,
                    .variant = self.plannedTagVariantByText(slot.rep, "#Missing"),
                    .args = &.{},
                    .next = chain.current,
                } } },
                .record_ext_field => |ext| try self.lowerRecordExtensionFieldInto(ext.field_local, ext.target_rep, ext.ext_local, ext.ext_rep, ext.field_view, ext.label, chain.current),
                .call_operand => |operand| switch (operand.operand) {
                    .checked_expr => |arg| if (operand.storage_arg_rep == self.repForTypeRef(operand.operand_type))
                        return .{ .child = .{ .expected_ref = .{ .target = operand.lowered, .expected_ty = operand.arg_type, .expr_id = arg, .next = chain.current } } }
                    else
                        try self.lowerExprStorageRepInto(operand.lowered, operand.storage_arg_rep, arg, chain.current),
                    .generated_quote => |literal| try self.assignStringLiteral(operand.lowered, literal, chain.current),
                    .generated_numeral => |literal| try self.lowerGeneratedNumeralInto(
                        operand.lowered,
                        operand.storage_arg_rep,
                        literal,
                        chain.current,
                    ),
                    .generated_interpolation_segments => |expr| try self.assignInterpolationSegmentsInto(operand.lowered, operand.storage_arg_rep, expr, chain.current),
                },
                .boundary_assign => |assign| try self.assignRepresentationBoundary(
                    assign.target,
                    assign.source,
                    assign.target_rep,
                    assign.source_rep,
                    chain.current,
                ),
                .const_list_element_box => |element| try self.prependConstListElementBox(element.elem_local, element.source, element.source_elem_rep, chain.current),
                .bind_shared_descriptor => |desc_local| blk: {
                    chain.snapshot = try self.snapshotDescriptorBindings();
                    try self.markDescriptorLocalBound(desc_local);
                    break :blk chain.current;
                },
                .restore_descriptors => blk: {
                    const snapshot = chain.snapshot.?;
                    chain.snapshot = null;
                    self.restoreDescriptorBindings(snapshot);
                    snapshot.deinit(self.parent.allocator);
                    break :blk chain.current;
                },
                .capture_snapshots => |expr| try self.prependClosureCaptureSnapshots(expr, chain.current),
                .recursive_value_slots => |pattern| try self.prependRecursiveValueSlotAllocations(pattern, chain.current),
                .runtime_error => try self.parent.result.store.addCFStmt(.{ .crash = .{
                    .msg = .{ .literal = try self.parent.result.store.insertString("runtime error") },
                    .checked_error = true,
                } }, self.origin),
                .prepend_descriptor_initializers => |initializers| blk: {
                    chain.items[chain.index - 1] = .runtime_error;
                    defer self.parent.allocator.free(initializers);
                    break :blk try self.prependDescriptorArgMaterializations(initializers, chain.current);
                },
                .record_local_env => |env| blk: {
                    chain.items[chain.index - 1] = .runtime_error;
                    defer self.parent.allocator.free(env.bindings);
                    try self.recordLocalDescriptorEnvironment(env.target, env.rep, env.bindings);
                    break :blk chain.current;
                },
                .callable_adapter => |boundary| blk: {
                    try self.finishCallableAdapterBoundary(boundary);
                    break :blk chain.current;
                },
                .pattern_miss_crash => |join_id| blk: {
                    const crash = try self.parent.result.store.addCFStmt(.{ .crash = .{
                        .msg = .{ .literal = try self.parent.result.store.insertString("pattern match failed") },
                    } }, self.origin);
                    break :blk try self.parent.result.store.addCFStmt(.{ .join = .{
                        .id = join_id,
                        .params = LIR.LocalSpan.empty(),
                        .body = crash,
                        .remainder = chain.current,
                    } }, self.origin);
                },
            };
        }
        return exprDone(chain.current);
    }

    /// Run the pieces a `begin` step left, or return its finished statement.
    fn runExprStep(self: *ProcBodyBuilder, step: ExprStep) Allocator.Error!LIR.CFStmtId {
        return switch (step) {
            .done => |stmt| stmt,
            .tail => |task| try self.runExprTasks(task),
            .child => boxyLowerInvariant("a first expression lowering step waited on a piece"),
        };
    }

    /// The first step of lowering `expr_id` into `target`, under the
    /// expression's own source origin.
    fn beginExpr(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        self.origin = try self.sourceOrigin(expr.source_region);

        switch (Plan.divergentStep(self.module, expr_id)) {
            .normal => {},
            .operand => |operand| return try self.beginDivergentOperand(target, expr_id, operand),
        }

        return switch (expr.data) {
            .numeral => |numeral| if (numeral.plan) |plan|
                try self.beginNumeralConversion(target, expr_id, expr.ty, plan, next)
            else
                exprDone(try self.assignCheckedNumeralLiteral(target, expr.ty, numeral.literal, next)),
            .str_segment, .bytes_literal => |literal| exprDone(try self.assignStringLiteral(target, literal, next)),
            .str => |segments| try self.beginStr(target, expr.ty, segments, next),
            .str_from_quote => |quote| try self.beginQuoteConversion(target, expr_id, expr.ty, quote, next),
            .empty_record => try self.beginEmptyRecord(target, expr_id, expr.ty, next),
            .empty_list => try self.beginList(target, expr.ty, &.{}, next),
            .lookup_local => |lookup| try self.beginLookupLocal(target, expr_id, expr.ty, lookup, next),
            .lookup_external, .lookup_required => |ref_id| try self.beginResolvedLookup(target, expr_id, expr.ty, ref_id, next),
            .field_access => |access| try self.beginFieldAccess(target, expr.ty, access.receiver, access.segments, next),
            .tuple_access => |access| try self.beginTupleAccess(target, access.tuple, access.elem_index, next),
            .list => |items| try self.beginList(target, expr.ty, items, next),
            .tuple => |items| try self.beginTuple(target, expr.ty, items, next),
            .tag => |tag| try self.beginTagRep(target, expr.ty, self.repForType(expr.ty), tag.name, tag.args, next),
            .zero_argument_tag => |tag| try self.beginTagRep(target, expr.ty, self.repForType(expr.ty), tag.name, &.{}, next),
            .if_ => |if_| .{ .tail = .{ .if_ = .{
                .target = target,
                .if_ty = expr.ty,
                .branches = if_.branches,
                .final_else = if_.final_else,
                .next = next,
            } } },
            .match_ => |match_| .{ .tail = .{ .match_ = .{
                .target = target,
                .match_ty = expr.ty,
                .cond = match_.cond,
                .branches = match_.branches,
                .next = next,
            } } },
            .unary_minus => |child| try self.beginLowLevel(target, expr.ty, .num_negate, &.{child}, next),
            .unary_not => |child| try self.beginLowLevel(target, expr.ty, .bool_not, &.{child}, next),
            .binop => |binop| .{ .tail = .{ .bool_binop = .{
                .target = target,
                .op = binop.op,
                .lhs = binop.lhs,
                .rhs = binop.rhs,
                .next = next,
            } } },
            .structural_eq => |eq| if (eq.discriminant) |discriminant|
                try self.beginTagDiscriminantEq(target, discriminant, eq.negated, next)
            else
                try self.beginStructuralEq(target, eq.lhs, eq.rhs, null, eq.negated, next),
            .method_eq => |plan| try self.beginMethodEq(target, plan, next),
            .structural_hash => |hash| try self.beginStructuralHash(target, hash.value, hash.hasher, next),
            .record => |record| try self.beginRecordExpr(target, expr_id, expr.ty, record, next),
            .nominal => |nominal| try self.beginNominal(target, expr.ty, nominal.backing_expr, next),
            .call => |call| try self.beginDirectCall(target, expr_id, call, expr.ty, next),
            .dispatch_call, .type_dispatch_call => |maybe_plan| try self.beginDispatchCall(target, expr_id, maybe_plan, expr.ty, next),
            .interpolation => |interpolation| try self.beginInterpolation(target, expr_id, expr.ty, interpolation, next),
            .for_ => |for_| blk: {
                if (self.isZstLocal(target)) {
                    break :blk .{ .tail = .{ .iterator_for = .{ .target = target, .for_ = forLoop(for_), .next = next } } };
                }
                // A for expression always evaluates to the unit record. When
                // the surrounding type is erased, the target is a dynamic box,
                // so run the loop into a unit temporary and box the unit.
                const unit_local = try self.addFrameLocal(.zst);
                const payload_desc = try self.appendLiteralPayloadDesc(.zst, expr.ty);
                self.parent.result.store.setLocalBoxyDesc(target, payload_desc);
                const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = unit_local,
                    .payload_layout = .zst,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.origin);
                break :blk .{ .tail = .{ .iterator_for = .{ .target = unit_local, .for_ = forLoop(for_), .next = box } } };
            },
            .run_low_level => |run_low_level| try self.beginLowLevel(target, expr.ty, run_low_level.op, run_low_level.args, next),
            .block => |block| try self.beginBlock(target, block, next),
            .dbg => |child| blk: {
                const after_dbg = try self.assignZst(target, next);
                const message = try self.addFrameLocal(.str);
                const debug_stmt = try self.parent.result.store.addCFStmt(.{ .debug = .{
                    .message = message,
                    .next = after_dbg,
                } }, self.origin);
                break :blk try self.beginInspectExpr(message, child, debug_stmt);
            },
            .expect => |child| blk: {
                const after = try self.assignZst(target, next);
                break :blk try self.beginExpectStmt(child, after);
            },
            .expect_err => |expect_err| try self.beginExpectErr(expect_err.expr, expect_err.snippet),
            .crash => |msg| exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(self.module.checked_bodies.stringLiteral(msg)) },
            } }, self.origin)),
            .ellipsis => exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString("not implemented") },
            } }, self.origin)),
            .break_ => exprDone(try self.lowerBreak()),
            .return_ => |ret| try self.beginReturn(ret.expr, ret.lambda),
            .runtime_error => |runtime_error| try self.beginRuntimeError(runtime_error.evaluated),
            .lambda,
            .closure,
            => if (try self.nestedCallableUseTypeForCurrentWorker(expr_id)) |use_type|
                try self.beginCallableExprTypeRef(target, use_type, expr_id, next)
            else
                try self.beginCallableExpr(target, expr_id, next),
            .pending, .anno_only, .hosted_lambda => {
                if (comptime zig_builtin.mode == .debug and zig_builtin.target.os.tag != .freestanding) {
                    std.debug.print("boxy lowering unimplemented checked expression form: {s}\n", .{@tagName(expr.data)});
                }
                boxyLowerInvariant("checked expression form reached boxy body lowering before its LIR lowering was implemented");
            },
        };
    }

    /// Lower the operands of a divergent expression up to the one that makes
    /// it diverge: each earlier operand runs for its effects into a discarded
    /// local, then the divergent one. Nothing after it runs, so its value has
    /// no continuation.
    fn beginDivergentOperand(
        self: *ProcBodyBuilder,
        enclosing_target: LIR.LocalId,
        enclosing: checked.CheckedExprId,
        operand: checked.CheckedExprId,
    ) Allocator.Error!ExprStep {
        const unreachable_continuation = try self.parent.result.store.addCFStmt(.runtime_error, self.origin);
        const operand_target = switch (Plan.divergentStep(self.module, operand)) {
            .operand => enclosing_target,
            .normal => switch (self.module.checked_bodies.expr(operand).data) {
                // Terminating forms produce no value.
                .crash, .runtime_error, .ellipsis, .break_, .return_, .expect_err => enclosing_target,
                // A divergent operand with an erroneous result type is
                // lowered at unit.
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .dbg, .expect, .anno_only, .for_, .hosted_lambda, .run_low_level => if (self.module.checked_types.payload(self.module.checked_bodies.expr(operand).ty) == .err)
                    try self.addFrameLocal(.zst)
                else
                    try self.addFrameLocalForRep(self.repForTypeRef(.{
                        .module = self.module.key,
                        .ty = self.module.checked_bodies.expr(operand).ty,
                    })),
            },
        };
        const earlier = try Plan.divergentEarlierOperands(self.module, self.parent.allocator, enclosing, operand);
        defer self.parent.allocator.free(earlier);
        if (earlier.len == 0) return .{ .tail = .{ .expr = .{ .target = operand_target, .expr_id = operand, .next = unreachable_continuation } } };
        // Chain items run from the last to the first.
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, earlier.len + 1);
        chain_items[0] = .{ .lower = .{ .expr = .{ .target = operand_target, .expr_id = operand, .next = undefined } } };
        for (earlier, 0..) |earlier_operand, index| {
            const expr = self.module.checked_bodies.expr(earlier_operand);
            const discarded = if (expr.data == .runtime_error or self.module.checked_types.payload(expr.ty) == .err)
                try self.addFrameLocal(.zst)
            else
                try self.addFrameLocalForType(expr.ty);
            chain_items[earlier.len - index] = .{ .lower = .{ .expr = .{ .target = discarded, .expr_id = earlier_operand, .next = undefined } } };
        }
        return exprChain(chain_items, unreachable_continuation);
    }

    /// Lower `expr_id` into `source`, then `boundary`, which converts
    /// `source` into `target`.
    fn exprThroughBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        boundary: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const items = try self.parent.allocator.alloc(ExprChainItem, 2);
        items[0] = .{ .lower = .{ .expr = .{ .target = source, .expr_id = expr_id, .next = undefined } } };
        items[1] = .{ .propagate_desc = .{ .target = target, .source = source } };
        return exprChain(items, boundary);
    }

    fn beginBlock(self: *ProcBodyBuilder, target: LIR.LocalId, block: anytype, next: LIR.CFStmtId) Allocator.Error!ExprStep {
        var live_statements = block.statements;
        var block_diverges = false;
        for (block.statements, 0..) |statement, i| {
            if (self.module.checked_bodies.statementDiverges(statement, .run)) {
                live_statements = block.statements[0 .. i + 1];
                block_diverges = true;
                break;
            }
        }
        try self.reserveBlockBindings(live_statements);
        const items = try self.parent.allocator.alloc(ExprChainItem, live_statements.len + 1);
        items[0] = if (block_diverges)
            .runtime_error
        else
            .{ .lower = .{ .expr = .{ .target = target, .expr_id = block.final_expr, .next = undefined } } };
        for (live_statements, 0..) |_, offset| {
            const index = live_statements.len - 1 - offset;
            items[1 + offset] = .{ .lower = .{ .statement = .{ .statement_id = live_statements[index], .next = undefined } } };
        }
        return exprChain(items, next);
    }

    fn beginExprExpected(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expected_ty: checked.CheckedTypeId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        // A checked runtime error crashes without producing a value, so it
        // has no storage of its own to convert into the expected
        // representation.
        if (expr.data == .runtime_error) return try self.beginExpr(target, expr_id, next);
        const target_rep = self.repForType(expected_ty);
        const source_rep = self.exprStorageRep(expr, self.repForType(expr.ty));
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const target_uses_expected_layout = target_layout == self.workerRuntimeLayoutForRep(target_rep).layoutIdx();
        if (target_rep != source_rep and self.repHasTagDomain(target_rep)) {
            switch (expr.data) {
                .tag => |tag| if (self.tagDomainHasLocalVariant(target_rep, tag.name)) {
                    return try self.beginTagRep(target, expected_ty, self.repForType(expected_ty), tag.name, tag.args, next);
                },
                .zero_argument_tag => |tag| if (self.tagDomainHasLocalVariant(target_rep, tag.name)) {
                    return try self.beginTagRep(target, expected_ty, self.repForType(expected_ty), tag.name, &.{}, next);
                },
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .nominal, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
            }
        }
        if (expected_ty != expr.ty) {
            if (self.procedureValueRefForExpr(expr) != null) {
                return try self.beginProcedureValueRefTypeRef(
                    target,
                    expr_id,
                    .{ .module = self.module.key, .ty = expected_ty },
                    next,
                );
            }
            switch (expr.data) {
                .call => |call| if (target_uses_expected_layout) return try self.beginDirectCall(target, expr_id, call, expected_ty, next),
                .dispatch_call, .type_dispatch_call => |maybe_plan| if (target_uses_expected_layout) return try self.beginDispatchCall(target, expr_id, maybe_plan, expected_ty, next),
                .lambda,
                .closure,
                => return try self.beginCallableExprTypeRef(target, .{ .module = self.module.key, .ty = expected_ty }, expr_id, next),
                .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .interpolation, .structural_eq, .structural_hash, .method_eq, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
            }
        }
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        try self.ensureBoundaryTargetDescriptorForSourceRep(target, source_rep);
        if (target_layout == source_layout and self.representationBoundaryIsDirect(target_rep, source_rep)) {
            return .{ .tail = .{ .expr = .{ .target = target, .expr_id = expr_id, .next = next } } };
        }

        const source = try self.addFrameBoundaryTargetLocalForRep(source_rep);
        const boundary = try self.assignRepresentationBoundary(target, source, target_rep, source_rep, next);
        return try self.exprThroughBoundary(target, source, expr_id, boundary);
    }

    fn beginExprExpectedTypeRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expected_ty: Plan.CheckedTypeIdentity,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (checked_moduleKeyEqual(expected_ty.module, self.module.key)) {
            return try self.beginExprExpected(target, expected_ty.ty, expr_id, next);
        }

        const expr = self.module.checked_bodies.expr(expr_id);
        // A checked runtime error crashes without producing a value, so it
        // has no storage of its own to convert into the expected
        // representation.
        if (expr.data == .runtime_error) return try self.beginExpr(target, expr_id, next);
        if (self.procedureValueRefForExpr(expr) != null) {
            return try self.beginProcedureValueRefTypeRef(
                target,
                expr_id,
                expected_ty,
                next,
            );
        }
        switch (expr.data) {
            .lambda,
            .closure,
            => return try self.beginCallableExprTypeRef(target, expected_ty, expr_id, next),
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
        }

        const target_rep = self.repForTypeRef(expected_ty);
        const source_rep = self.exprStorageRep(expr, self.repForType(expr.ty));
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        try self.ensureBoundaryTargetDescriptorForSourceRep(target, source_rep);
        if (target_layout == source_layout and self.representationBoundaryIsDirect(target_rep, source_rep)) {
            return .{ .tail = .{ .expr = .{ .target = target, .expr_id = expr_id, .next = next } } };
        }

        const source = try self.addFrameLocalForRep(source_rep);
        const boundary = try self.assignRepresentationBoundary(target, source, target_rep, source_rep, next);
        return try self.exprThroughBoundary(target, source, expr_id, boundary);
    }

    fn beginExprIntoRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        // A checked runtime error crashes without producing a value, so it
        // has no storage of its own to convert into the expected
        // representation.
        if (expr.data == .runtime_error) return try self.beginExpr(target, expr_id, next);
        const source_rep = self.repForType(expr.ty);
        try self.ensureBoundaryTargetDescriptorForSourceRep(target, source_rep);
        if (self.representationBoundaryIsDirect(target_rep, source_rep)) {
            return .{ .tail = .{ .expr = .{ .target = target, .expr_id = expr_id, .next = next } } };
        }

        const source = try self.addFrameBoundaryTargetLocalForRep(source_rep);
        const assign = try self.assignRepresentationBoundary(target, source, target_rep, source_rep, next);
        return try self.exprThroughBoundary(target, source, expr_id, assign);
    }

    fn beginExprIntoTagPayloadStorage(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        // A checked runtime error crashes without producing a value, so it
        // has no storage of its own to convert into the expected
        // representation.
        if (expr.data == .runtime_error) return try self.beginExpr(target, expr_id, next);
        const source_rep = self.repForType(expr.ty);
        if (self.parent.result.store.getLocal(target).layout_idx == self.workerRuntimeLayoutForRep(source_rep).layoutIdx() and
            self.repsUseSameDynamicBoxStorage(target_rep, source_rep))
        {
            return .{ .tail = .{ .expr = .{ .target = target, .expr_id = expr_id, .next = next } } };
        }

        if (self.localUsesWorkerLayoutForRep(target, target_rep)) {
            return try self.beginExprIntoRep(target, target_rep, expr_id, next);
        }

        // A constructed payload owns its descriptor. A shared worker input
        // cannot capture the descriptors produced while evaluating its fields.
        const worker_value = try self.addFrameLocalForRepWithFreshDescriptor(target_rep);
        if (self.parent.result.store.getLocal(target).layout_idx == self.parent.result.store.getLocal(worker_value).layout_idx) {
            if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
                self.parent.result.store.setLocalBoxyDesc(worker_value, target_desc);
            }
        }
        const store_payload = try self.assignWorkerValueToTagPayloadStorage(target, worker_value, target_rep, next);
        return try self.beginExprIntoRep(worker_value, target_rep, expr_id, store_payload);
    }

    fn beginList(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        list_ty: checked.CheckedTypeId,
        items: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const target_rep = self.repForType(list_ty);
        const list_rep = self.listRepForBoundary(target_rep) orelse
            boxyLowerInvariant("list expression contextual representation was not list-shaped");

        const elem_ty = constListElemType(self.module, list_ty);
        const target_elem_rep = self.repQuery().requiredSingleChild(list_rep, .list_elem).rep;
        const source_elem_rep = self.repForType(elem_ty);
        const target_elem_desc_local = try self.reserveDescriptorLocalForRep(target_elem_rep);
        if (target_elem_desc_local) |elem_desc_local| {
            const target_desc_local = self.parent.result.store.getLocal(target).boxy_desc orelse
                boxyLowerInvariant("constructed list target had no descriptor");
            if (target_desc_local.localOrNull() == elem_desc_local) {
                const fresh_target = try self.addFrameLocal(self.parent.result.store.getLocal(target).layout_idx);
                const fresh_desc_local = try self.addFrameLocal(.opaque_ptr);
                self.parent.result.store.setLocalBoxyDesc(fresh_target, .{ .local = fresh_desc_local });
                const transfer = try self.assignLocal(target, fresh_target, next);
                return .{ .tail = .{ .list = .{ .target = fresh_target, .list_ty = list_ty, .items = items, .next = transfer } } };
            }
        }
        const elem_layout = self.localListElemLayout(target);
        const elem_locals = try self.parent.allocator.alloc(LIR.LocalId, items.len);
        defer self.parent.allocator.free(elem_locals);

        for (elem_locals) |*local| {
            local.* = try self.addFrameLocal(elem_layout);
        }

        const target_desc_info = if (target_elem_desc_local) |elem_desc_local|
            try self.constructedListDescriptorForElementLocal(target, target_rep, elem_desc_local)
        else
            try self.stableDescriptorForConstructedValue(target, target_rep);
        if (target_desc_info.desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(target, desc);
        }

        var continuation = try self.assignList(target, elem_locals, next);
        continuation = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, continuation);
        continuation = try self.prependDescriptorRebindForRepFromRep(target_elem_rep, source_elem_rep, continuation);
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, items.len);
        for (chain_items, 0..) |*item, offset| {
            const index = items.len - 1 - offset;
            item.* = .{ .lower = .{ .expected = .{ .target = elem_locals[index], .expected_ty = elem_ty, .expr_id = items[index], .next = undefined } } };
        }
        return exprChain(chain_items, continuation);
    }

    fn beginTuple(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        tuple_ty: checked.CheckedTypeId,
        items: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        return try self.beginTupleRep(target, self.repForType(tuple_ty), items, next);
    }

    fn beginTupleRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        items: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        return switch (rep.kind) {
            .tuple => try self.beginExprsAsStructWithReps(target, rep_id, items, self.parent.plan.childSlice(rep.children), next),
            .alias => .{ .tail = .{ .tuple_rep = .{ .target = target, .rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep, .items = items, .next = next } } },
            .nominal => |kind| switch (kind) {
                .transparent,
                .builtin_other,
                => {
                    const scope = try self.enterNominalBackingFormalScope(rep_id);
                    const chain_items = self.parent.allocator.alloc(ExprChainItem, 2) catch |err| {
                        self.dropNominalBackingFormalScope(scope);
                        return err;
                    };
                    chain_items[0] = .{ .lower = .{ .tuple_rep = .{ .target = target, .rep_id = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, .items = items, .next = undefined } } };
                    chain_items[1] = .leave_scope;
                    return .{ .tail = .{ .chain = .{ .items = chain_items, .current = next, .scope = scope } } };
                },
                .opaque_nominal => boxyLowerInvariant("opaque nominal tuple expression reached boxy lowering"),
            },
            .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("tuple expression checked type did not have a boxy tuple representation"),
        };
    }

    fn beginExprsAsStructWithReps(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: ?Plan.TypeRepId,
        items: []const checked.CheckedExprId,
        item_reps: []const Plan.RepChild,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (items.len != item_reps.len) {
            boxyLowerInvariant("struct expression contextual item reps disagreed with expression count");
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, items.len);
        var field_locals_owned = true;
        defer if (field_locals_owned) self.parent.allocator.free(field_locals);

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        for (item_reps, field_locals, items, 0..) |item_rep, *local, item, index| {
            const field_layout = try self.aggregateFieldLayout(target_layout, index);
            const expr_rep = self.repForType(self.module.checked_bodies.expr(item).ty);
            if (target_rep == null and
                field_layout == self.workerRuntimeLayoutForRep(expr_rep).layoutIdx() and
                self.repsUseSameDynamicBoxStorage(item_rep.rep, expr_rep))
            {
                local.* = try self.addFrameLocalForRep(expr_rep);
            } else {
                local.* = try self.addFrameLocal(field_layout);
            }
        }

        const aggregate_desc = if (target_rep) |rep_id| blk: {
            const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, items.len);
            defer self.parent.allocator.free(descriptor_fields);
            for (items, item_reps, field_locals, descriptor_fields) |item, target_field, local, *field| {
                const expr = self.module.checked_bodies.expr(item);
                field.* = .{
                    .local = local,
                    .target_rep = target_field.rep,
                    .source_rep = self.repForType(expr.ty),
                };
            }
            break :blk try self.constructedAggregateDescriptorForFields(target, rep_id, descriptor_fields);
        } else ConstructedAggregateDescriptor{};
        var aggregate_desc_owned = true;
        defer if (aggregate_desc_owned) aggregate_desc.deinit(self.parent.allocator);

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .contents_desc = aggregate_desc.contents_desc,
            .next = next,
        } }, self.origin);
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        const extra: usize = if (target_rep != null) 2 else 1;
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, items.len + extra);
        for (0..items.len) |offset| {
            const index = items.len - 1 - offset;
            const expr_rep = self.repForType(self.module.checked_bodies.expr(items[index]).ty);
            chain_items[offset] = if (target_rep == null and
                self.parent.result.store.getLocal(field_locals[index]).layout_idx == self.workerRuntimeLayoutForRep(expr_rep).layoutIdx() and
                self.repsUseSameDynamicBoxStorage(item_reps[index].rep, expr_rep))
                .{ .lower = .{ .expr = .{ .target = field_locals[index], .expr_id = items[index], .next = undefined } } }
            else
                .{ .lower = .{ .payload_storage = .{ .target = field_locals[index], .target_rep = item_reps[index].rep, .expr_id = items[index], .next = undefined } } };
        }
        if (target_rep) |rep_id| {
            chain_items[items.len] = .{ .record_aggregate_env = .{ .target = target, .rep_id = rep_id } };
        }
        chain_items[items.len + extra - 1] = .prepend_field_initializers;
        field_locals_owned = false;
        aggregate_desc_owned = false;
        return .{ .tail = .{ .chain = .{
            .items = chain_items,
            .current = continuation,
            .aggregate_desc = aggregate_desc,
            .locals = field_locals,
        } } };
    }

    fn beginTagRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        tag_ty: checked.CheckedTypeId,
        rep_id: Plan.TypeRepId,
        name: names.TagNameId,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        return switch (rep.kind) {
            .tag_union => try self.beginPlannedTagVariant(target, rep_id, self.tagVariant(rep, name), args, next),
            .bool_tag_union => exprDone(try self.lowerBoolTagInto(target, name, args, next)),
            .dynamic => try self.beginDynamicTag(target, rep_id, name, args, next),
            .alias => .{ .tail = .{ .tag_rep = .{
                .target = target,
                .tag_ty = tag_ty,
                .rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep,
                .name = name,
                .args = args,
                .next = next,
            } } },
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => {
                    const backing_ty = checkedTypeAtNominalBacking(self.module, tag_ty);
                    const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
                    const scope = try self.enterNominalBackingFormalScope(rep_id);
                    var scope_owned = true;
                    defer if (scope_owned) self.dropNominalBackingFormalScope(scope);
                    const backing = try self.addFrameLocalForRepWithFreshDescriptor(backing_rep);
                    const assign = try self.assignPlannedCallBoundary(target, backing, rep_id, backing_rep, next);
                    const chain_items = try self.parent.allocator.alloc(ExprChainItem, 3);
                    chain_items[0] = .{ .lower = .{ .tag_rep = .{ .target = backing, .tag_ty = backing_ty, .rep_id = backing_rep, .name = name, .args = args, .next = undefined } } };
                    chain_items[1] = .{ .propagate_desc = .{ .target = target, .source = backing } };
                    chain_items[2] = .leave_scope;
                    scope_owned = false;
                    return .{ .tail = .{ .chain = .{ .items = chain_items, .current = assign, .scope = scope } } };
                },
                .opaque_nominal => boxyLowerInvariant("opaque nominal tag expression reached boxy lowering"),
            },
            .empty_tag_union => boxyLowerInvariant("empty tag union expression reached boxy body lowering"),
            .in_progress, .primitive, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record => boxyLowerInvariant("tag expression checked type did not have a boxy tag-union representation"),
        };
    }

    fn beginPlannedTagVariant(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        variant: TagVariantLookup,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const payload_children = self.parent.plan.childSlice(variant.payloads);
        if (payload_children.len != args.len) {
            boxyLowerInvariant("tag expression payload count disagreed with its checked type representation");
        }
        for (payload_children, 0..) |child, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("tag variant payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag variant payload span included a non-payload child"),
            }
        }

        if (args.len == 0) {
            var target_desc_ref: ?LIR.BoxyDescRef = null;
            var target_desc_materialize: ?DescriptorArgLocal = null;
            if (rep.descriptor != null or rep.contains_dynamic or
                self.parent.result.store.getLocal(target).boxy_desc != null)
            {
                const materialization = try self.descriptorMaterializationForConstructedRep(rep_id);
                if (rep.descriptor == null and materialization.captures.len == 0) {
                    target_desc_ref = materialization.desc;
                } else {
                    const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, materialization);
                    target_desc_ref = target_desc_info.desc;
                    target_desc_materialize = target_desc_info.materialize;
                }
            }
            if (self.isZstLocal(target)) return exprDone(try self.assignZst(target, next));
            const target_layout = self.parent.result.layouts.getLayout(self.parent.result.store.getLocal(target).layout_idx);
            const assign_tag = if (target_layout.tag == .erased_box) blk: {
                const target_desc = target_desc_ref orelse
                    boxyLowerInvariant("descriptor-erased tag construction had no target descriptor");
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                    .target = target,
                    .target_desc = target_desc,
                    .tag_name = try self.lirTagNameForLookup(variant),
                    .next = next,
                } }, self.origin);
            } else try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = target_desc_ref,
                .variant_index = variant.index,
                .discriminant = variant.index,
                .payload = null,
                .next = next,
            } }, self.origin);
            return exprDone(try self.prependOptionalDescriptorMaterialization(target_desc_materialize, assign_tag));
        }

        const payload_layout = if (self.isZstLocal(target))
            layout.Idx.zst
        else
            self.tagUnionPayloadLayout(self.parent.result.store.getLocal(target).layout_idx, variant.index);
        const payload_local = try self.addFrameLocal(payload_layout);
        if (self.isZstLocal(target) and !self.isZstLocal(payload_local)) {
            boxyLowerInvariant("zero-sized tag-union layout had a non-zero-sized payload");
        }

        if (args.len == 1) {
            const descriptor_fields = [_]AggregateDescriptorField{.{
                .local = payload_local,
                .target_rep = payload_children[0].rep,
                .source_rep = self.exprTagPayloadStorageRep(
                    payload_local,
                    payload_children[0].rep,
                    self.repForType(self.module.checked_bodies.expr(args[0]).ty),
                ),
            }};
            const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, rep_id, &descriptor_fields);
            var tag_desc_owned = true;
            defer if (tag_desc_owned) tag_desc.deinit(self.parent.allocator);

            const assign_tag = if (self.isZstLocal(target))
                try self.assignZst(target, next)
            else
                try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                    .target = target,
                    .target_desc = tag_desc.desc,
                    .variant_index = variant.index,
                    .discriminant = variant.index,
                    .payload = payload_local,
                    .next = next,
                } }, self.origin);
            const construct_tag = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, assign_tag);
            const chain_items = try self.parent.allocator.alloc(ExprChainItem, 2);
            chain_items[0] = .{ .lower = .{ .payload_storage = .{ .target = payload_local, .target_rep = payload_children[0].rep, .expr_id = args[0], .next = undefined } } };
            chain_items[1] = .prepend_field_initializers;
            tag_desc_owned = false;
            return .{ .tail = .{ .chain = .{ .items = chain_items, .current = construct_tag, .aggregate_desc = tag_desc } } };
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, args.len);
        defer self.parent.allocator.free(field_locals);
        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, args.len);
        defer self.parent.allocator.free(descriptor_fields);
        for (payload_children, field_locals, descriptor_fields, args, 0..) |child, *field_local, *descriptor_field, arg, index| {
            field_local.* = try self.addFrameLocal(try self.aggregateFieldLayout(payload_layout, index));
            descriptor_field.* = .{
                .local = field_local.*,
                .target_rep = child.rep,
                .source_rep = self.exprTagPayloadStorageRep(
                    field_local.*,
                    child.rep,
                    self.repForType(self.module.checked_bodies.expr(arg).ty),
                ),
            };
            switch (child.role) {
                .tag_payload => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag descriptor field included a non-payload child"),
            }
        }

        const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, rep_id, descriptor_fields);
        var tag_desc_owned = true;
        defer if (tag_desc_owned) tag_desc.deinit(self.parent.allocator);
        const assign_tag = if (self.isZstLocal(target))
            try self.assignZst(target, next)
        else
            try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = tag_desc.desc,
                .variant_index = variant.index,
                .discriminant = variant.index,
                .payload = payload_local,
                .next = next,
            } }, self.origin);
        var continuation = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, assign_tag);
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload_local,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .next = continuation,
        } }, self.origin);
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, args.len + 1);
        for (0..args.len) |offset| {
            const index = args.len - 1 - offset;
            chain_items[offset] = .{ .lower = .{ .payload_storage = .{ .target = field_locals[index], .target_rep = payload_children[index].rep, .expr_id = args[index], .next = undefined } } };
        }
        chain_items[args.len] = .prepend_field_initializers;
        tag_desc_owned = false;
        return .{ .tail = .{ .chain = .{ .items = chain_items, .current = continuation, .aggregate_desc = tag_desc } } };
    }

    fn beginDynamicTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        name: names.TagNameId,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const payloads = try self.dynamicTagPayloadsForName(rep_id, name);
        if (payloads.len != args.len) {
            boxyLowerInvariant("dynamic tag expression payload count disagreed with planned representation");
        }
        if (args.len == 0) {
            const target_desc_materialization = try self.descriptorMaterializationForConstructedRep(rep_id);
            const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, target_desc_materialization);
            const target_desc = target_desc_info.desc orelse
                boxyLowerInvariant("dynamic tag construction had no target descriptor");
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                .target = target,
                .target_desc = target_desc,
                .tag_name = try self.lirTagName(name),
                .next = next,
            } }, self.origin);
            return exprDone(try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, assign_tag));
        }

        const payload = try self.dynamicTagPayloadLocal(payloads, args);
        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, args.len);
        defer self.parent.allocator.free(descriptor_fields);
        const field_locals = if (args.len == 1) null else try self.parent.allocator.alloc(LIR.LocalId, args.len);
        defer if (field_locals) |locals| self.parent.allocator.free(locals);
        if (field_locals) |locals| {
            for (payloads, args, locals, descriptor_fields, 0..) |child, arg, *field_local, *descriptor_field, index| {
                field_local.* = try self.addFrameLocal(try self.aggregateFieldLayout(payload.layout_idx, index));
                descriptor_field.* = .{
                    .local = field_local.*,
                    .target_rep = child.rep,
                    .source_rep = self.repForType(self.module.checked_bodies.expr(arg).ty),
                };
            }
        } else {
            descriptor_fields[0] = .{
                .local = payload.local,
                .target_rep = payloads[0].rep,
                .source_rep = self.repForType(self.module.checked_bodies.expr(args[0]).ty),
            };
        }

        const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, rep_id, descriptor_fields);
        var tag_desc_owned = true;
        defer if (tag_desc_owned) tag_desc.deinit(self.parent.allocator);
        const target_desc = tag_desc.desc orelse
            boxyLowerInvariant("dynamic tag construction had no target descriptor");
        const payload_desc = if (payload.desc_rep) |payload_rep|
            try self.descriptorRefForLocalOrKnownRep(payload.local, payload_rep)
        else
            null;
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
            .target = target,
            .target_desc = target_desc,
            .tag_name = try self.lirTagName(name),
            .payload = payload.local,
            .payload_layout = payload.layout_idx,
            .payload_desc = payload_desc,
            .payload_mode = .move,
            .next = next,
        } }, self.origin);
        var construct_tag = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, assign_tag);

        if (args.len == 1) {
            const chain_items = try self.parent.allocator.alloc(ExprChainItem, 2);
            chain_items[0] = .{ .lower = .{ .payload_storage = .{ .target = payload.local, .target_rep = payloads[0].rep, .expr_id = args[0], .next = undefined } } };
            chain_items[1] = .prepend_field_initializers;
            tag_desc_owned = false;
            return .{ .tail = .{ .chain = .{ .items = chain_items, .current = construct_tag, .aggregate_desc = tag_desc } } };
        }
        construct_tag = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload.local,
            .fields = try self.parent.result.store.addLocalSpan(field_locals.?),
            .next = construct_tag,
        } }, self.origin);
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, args.len + 1);
        for (0..args.len) |offset| {
            const index = args.len - 1 - offset;
            chain_items[offset] = .{ .lower = .{ .payload_storage = .{ .target = field_locals.?[index], .target_rep = payloads[index].rep, .expr_id = args[index], .next = undefined } } };
        }
        chain_items[args.len] = .prepend_field_initializers;
        tag_desc_owned = false;
        return .{ .tail = .{ .chain = .{ .items = chain_items, .current = construct_tag, .aggregate_desc = tag_desc } } };
    }

    fn beginNominal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        nominal_ty: checked.CheckedTypeId,
        backing_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const backing = self.module.checked_bodies.expr(backing_id);
        const nominal_rep = self.repForType(nominal_ty);
        const described = try self.prependNominalOwnDescriptorMaterialization(target, nominal_rep, next);
        // The nominal edge owns the complete constructor representation; its
        // producer-owned tag child may contain only the selected variant.
        if (backing.data == .tag and self.nominalPatternSourceRep(nominal_rep) != null) {
            return .{ .tail = .{ .tag_rep = .{
                .target = target,
                .tag_ty = nominal_ty,
                .rep_id = nominal_rep,
                .name = backing.data.tag.name,
                .args = backing.data.tag.args,
                .next = described,
            } } };
        }
        const backing_ty = self.module.static_dispatch_plans.siteInstanceType(backing_id) orelse backing.ty;
        const backing_local = try self.addFrameLocalForType(backing_ty);
        const assign = try self.assignRepresentationBoundaryConsumingSource(target, backing_local, nominal_rep, self.repForType(backing_ty), described);
        return .{ .tail = .{ .expr = .{ .target = backing_local, .expr_id = backing_id, .next = assign } } };
    }

    fn beginFieldAccess(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_ty: checked.CheckedTypeId,
        receiver_id: checked.CheckedExprId,
        segments: []const checked.CheckedFieldAccessSegment,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (segments.len == 0) {
            boxyLowerInvariant("checked field access path had no segments");
        }
        const receiver = self.module.checked_bodies.expr(receiver_id);
        const receiver_rep = self.repForType(receiver.ty);
        const receiver_layout = self.workerRuntimeLayoutForRep(receiver_rep);
        const receiver_local = try self.addFrameLocalForRep(receiver_rep);
        if (self.parent.result.store.getLocal(receiver_local).layout_idx != receiver_layout.layoutIdx()) {
            boxyLowerInvariant("boxy field access receiver local layout disagreed with checked type");
        }

        for (segments) |segment| {
            if (segment.mode == .optional) {
                const result_rep = self.repForType(result_ty);
                const lowered = try self.lowerOptionalFieldAccessSegments(
                    target,
                    result_rep,
                    segments,
                    0,
                    receiver_local,
                    receiver_rep,
                    next,
                );
                return .{ .tail = .{ .expr = .{ .target = receiver_local, .expr_id = receiver_id, .next = lowered } } };
            }
        }

        const prefix_locals = try self.parent.allocator.alloc(LIR.LocalId, segments.len - 1);
        defer self.parent.allocator.free(prefix_locals);
        for (prefix_locals, segments[0 .. segments.len - 1]) |*local, segment| {
            local.* = try self.addFrameLocalForRep(self.repForType(segment.success_ty));
        }
        var continuation = next;
        var index = segments.len;
        while (index > 0) {
            index -= 1;
            const segment = segments[index];
            const segment_rep = self.repForType(segment.success_ty);
            const destination = if (index + 1 == segments.len)
                target
            else
                prefix_locals[index];
            const source_local = if (index == 0) receiver_local else prefix_locals[index - 1];
            const source_rep = if (index == 0)
                receiver_rep
            else
                self.repForType(segments[index - 1].success_ty);
            continuation = try self.lowerRecordFieldFromLocalInto(
                destination,
                if (index + 1 == segments.len) self.repForType(result_ty) else segment_rep,
                source_local,
                source_rep,
                self.module,
                segment.field_name,
                continuation,
            );
        }
        return .{ .tail = .{ .expr = .{ .target = receiver_local, .expr_id = receiver_id, .next = continuation } } };
    }

    fn beginTupleAccess(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        tuple_id: checked.CheckedExprId,
        elem_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (elem_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("tuple access element index exceeded LIR field index range");
        }
        const tuple = self.module.checked_bodies.expr(tuple_id);
        const tuple_rep = self.repForType(tuple.ty);
        const tuple_local = try self.addFrameLocalForRep(tuple_rep);
        const read = try self.lowerTupleFieldReadInto(
            target,
            tuple_local,
            tuple_rep,
            @intCast(elem_index),
            next,
        );
        return .{ .tail = .{ .expr = .{ .target = tuple_local, .expr_id = tuple_id, .next = read } } };
    }

    fn beginStr(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        str_ty: checked.CheckedTypeId,
        segments: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (segments.len == 0) return exprDone(try self.assignStringBytesLiteral(target, "", next));
        const string_rep = self.repForType(self.module.checked_bodies.expr(segments[0]).ty);
        const str_layout = self.workerRuntimeLayoutForRep(string_rep).layoutIdx();
        const target_rep = self.repForType(str_ty);
        const concat_target = if (self.parent.result.store.getLocal(target).layout_idx == str_layout and
            self.representationBoundaryIsDirect(target_rep, string_rep))
            target
        else
            try self.addFrameLocalForRep(string_rep);
        const after_concat = if (concat_target == target)
            next
        else
            try self.assignRepresentationBoundary(target, concat_target, target_rep, string_rep, next);
        if (segments.len == 1) return try self.beginExprIntoRep(concat_target, string_rep, segments[0], after_concat);

        const segment_locals = try self.parent.allocator.alloc(LIR.LocalId, segments.len);
        defer self.parent.allocator.free(segment_locals);
        for (segments, segment_locals) |segment, *local| {
            const expr = self.module.checked_bodies.expr(segment);
            const layout_idx = self.workerRuntimeLayoutForType(expr.ty).layoutIdx();
            if (layout_idx != str_layout) {
                boxyLowerInvariant("checked string segment required explicit box/adapt lowering before string concatenation");
            }
            local.* = try self.addFrameLocalForRep(string_rep);
        }

        const concat_results = try self.parent.allocator.alloc(LIR.LocalId, segments.len - 1);
        defer self.parent.allocator.free(concat_results);
        for (concat_results[0 .. concat_results.len - 1]) |*local| {
            local.* = try self.addFrameLocal(str_layout);
        }
        concat_results[concat_results.len - 1] = concat_target;

        // Each concatenation is followed, walking backwards, by its right
        // operand, and the first also by its left operand.
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, 2 * concat_results.len + 1);
        var item_index: usize = 0;
        var concat_index = concat_results.len;
        while (concat_index > 0) {
            concat_index -= 1;
            const lhs = if (concat_index == 0) segment_locals[0] else concat_results[concat_index - 1];
            const rhs = segment_locals[concat_index + 1];
            chain_items[item_index] = .{ .str_concat = .{ .target = concat_results[concat_index], .lhs = lhs, .rhs = rhs } };
            chain_items[item_index + 1] = .{ .lower = .{ .into_rep = .{ .target = rhs, .target_rep = string_rep, .expr_id = segments[concat_index + 1], .next = undefined } } };
            item_index += 2;
            if (concat_index == 0) {
                chain_items[item_index] = .{ .lower = .{ .into_rep = .{ .target = lhs, .target_rep = string_rep, .expr_id = segments[0], .next = undefined } } };
                item_index += 1;
            }
        }
        return exprChain(chain_items, after_concat);
    }

    fn beginRecordExpr(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        record_expr: checked.CheckedExprId,
        record_ty: checked.CheckedTypeId,
        record: anytype,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (record.ext) |ext| {
            const ext_expr = self.module.checked_bodies.expr(ext);
            const ext_rep = self.repForType(ext_expr.ty);
            const ext_local = try self.addFrameLocalForRep(ext_rep);
            const chain_items = try self.parent.allocator.alloc(ExprChainItem, 2);
            chain_items[0] = .{ .lower = .{ .record_rep = .{
                .target = target,
                .record_expr = record_expr,
                .rep_id = self.repForType(record_ty),
                .expr_fields = record.fields,
                .unset_fields = record.unsets,
                .extension = .{ .local = ext_local, .rep = ext_rep },
                .next = undefined,
            } } };
            chain_items[1] = .{ .lower = .{ .expr = .{ .target = ext_local, .expr_id = ext, .next = undefined } } };
            return exprChain(chain_items, next);
        }
        return try self.beginRecordRep(target, record_expr, self.repForType(record_ty), record.fields, record.unsets, null, next);
    }

    fn beginEmptyRecord(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        record_expr: checked.CheckedExprId,
        record_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        return try self.beginRecordRep(target, record_expr, self.repForType(record_ty), &.{}, &.{}, null, next);
    }

    fn beginRecordRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        record_expr: checked.CheckedExprId,
        rep_id: Plan.TypeRepId,
        expr_fields: []const checked.CheckedRecordExprField,
        unset_fields: []const check.CanonicalNames.RecordFieldLabelId,
        extension: ?RecordExtension,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        switch (rep.kind) {
            .record,
            => return try self.beginRecordPayload(target, record_expr, rep_id, rep, expr_fields, unset_fields, extension, next),
            .dynamic => return try self.beginDynamicRecord(target, record_expr, rep_id, rep, expr_fields, unset_fields, extension, next),
            .alias => return .{ .tail = .{ .record_rep = .{
                .target = target,
                .record_expr = record_expr,
                .rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep,
                .expr_fields = expr_fields,
                .unset_fields = unset_fields,
                .extension = extension,
                .next = next,
            } } },
            .nominal => |kind| switch (kind) {
                .transparent,
                .opaque_nominal,
                .builtin_other,
                => {
                    const backing = self.repQuery().requiredSingleChild(rep_id, .nominal_backing);
                    const scope = try self.enterNominalBackingFormalScope(rep_id);
                    var scope_owned = true;
                    defer if (scope_owned) self.dropNominalBackingFormalScope(scope);
                    const backing_local = try self.addFrameLocalForRep(backing.rep);
                    const assign = try self.assignRepresentationBoundary(target, backing_local, rep_id, backing.rep, next);
                    const chain_items = try self.parent.allocator.alloc(ExprChainItem, 2);
                    chain_items[0] = .{ .lower = .{ .record_rep = .{
                        .target = backing_local,
                        .record_expr = record_expr,
                        .rep_id = backing.rep,
                        .expr_fields = expr_fields,
                        .unset_fields = unset_fields,
                        .extension = extension,
                        .next = undefined,
                    } } };
                    chain_items[1] = .leave_scope;
                    scope_owned = false;
                    return .{ .tail = .{ .chain = .{ .items = chain_items, .current = assign, .scope = scope } } };
                },
            },
            // A record value with no fields, such as `{}` constructing a
            // nominal type whose backing is the empty record.
            .empty_record => {
                if (expr_fields.len != 0 or unset_fields.len != 0 or extension != null) {
                    boxyLowerInvariant("record expression with fields had an empty-record representation");
                }
                return exprDone(try self.assignZst(target, next));
            },
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .tag_union, .empty_tag_union => boxyLowerInvariant("record expression checked type did not have a boxy record representation"),
        }
    }

    fn beginDynamicRecord(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        record_expr: checked.CheckedExprId,
        rep_id: Plan.TypeRepId,
        rep: Plan.TypeRepresentation,
        expr_fields: []const checked.CheckedRecordExprField,
        unset_fields: []const check.CanonicalNames.RecordFieldLabelId,
        extension: ?RecordExtension,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const payload_layout = self.parent.layout_plan.rep_layouts[@backingInt(rep_id)].descriptor_payload_layout orelse
            boxyLowerInvariant("dynamic record descriptor had no payload layout");
        const payload = try self.addFrameLocal(payload_layout);
        if (extension) |ext| {
            // The base of an update has fields its open row does not name,
            // which only its runtime descriptor knows. The update keeps them
            // and replaces the fields this representation names, which the
            // record's static-field view describes.
            const fields_desc = try self.openRecordViewDescriptorSource(rep_id);
            const update = try self.parent.result.store.addCFStmt(.{ .assign_boxy_record_update = .{
                .target = target,
                .base = ext.local,
                .base_desc = try self.descriptorRefForSourceLocalRep(ext.local, ext.rep),
                .fields = payload,
                .fields_layout = payload_layout,
                .fields_desc = fields_desc.desc.?,
                .next = try self.prependSetLocalDescriptorTransfer(target, ext.local, .replace_existing, next),
            } }, self.origin);
            const with_fields_desc = try self.prependOptionalDescriptorMaterialization(fields_desc.materialize, update);
            return try self.beginRecordPayload(payload, record_expr, rep_id, rep, expr_fields, unset_fields, extension, with_fields_desc);
        }
        const payload_desc_info = try self.descriptorForConstructedTarget(target, try self.descriptorRefForKnownRep(rep_id));
        const payload_desc = payload_desc_info.desc orelse
            boxyLowerInvariant("dynamic record construction had no target descriptor");
        const assign_box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
            .target = target,
            .payload = payload,
            .payload_layout = payload_layout,
            .payload_desc = payload_desc,
            .payload_mode = .move,
            .next = next,
        } }, self.origin);
        return try self.beginRecordPayload(
            payload,
            record_expr,
            rep_id,
            rep,
            expr_fields,
            unset_fields,
            extension,
            try self.prependOptionalDescriptorMaterialization(payload_desc_info.materialize, assign_box),
        );
    }

    fn beginRecordPayload(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        record_expr: checked.CheckedExprId,
        rep_id: Plan.TypeRepId,
        rep: Plan.TypeRepresentation,
        expr_fields: []const checked.CheckedRecordExprField,
        unset_fields: []const check.CanonicalNames.RecordFieldLabelId,
        extension: ?RecordExtension,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const children = self.parent.plan.childSlice(rep.children);
        var field_count: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => field_count += 1,
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record representation had a non-record child role"),
            }
        }
        if (expr_fields.len > field_count) {
            boxyLowerInvariant("record expression had more fields than its checked type representation");
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, field_count);
        defer self.parent.allocator.free(field_locals);
        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, field_count);
        defer self.parent.allocator.free(descriptor_fields);
        const source_field_locals = try self.parent.allocator.alloc(?LIR.LocalId, expr_fields.len);
        defer self.parent.allocator.free(source_field_locals);
        @memset(source_field_locals, null);
        const source_field_target_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, expr_fields.len);
        defer self.parent.allocator.free(source_field_target_reps);
        @memset(source_field_target_reps, null);
        const source_field_kinds = try self.parent.allocator.alloc(checked.CheckedFieldKind.Tag, expr_fields.len);
        defer self.parent.allocator.free(source_field_kinds);
        const field_sources = try self.parent.allocator.alloc(RecordPayloadFieldSource, field_count);
        defer self.parent.allocator.free(field_sources);
        const unset_matched = try self.parent.allocator.alloc(bool, unset_fields.len);
        defer self.parent.allocator.free(unset_matched);
        @memset(unset_matched, false);

        var layout_index: usize = 0;
        const rep_field_view = procedureModuleById(self.parent.modules, rep.source_type.module);
        // Supplied and unset labels, so each representation field finds its
        // source in constant time. They match as `Plan.recordFieldNameMatches`
        // does: by id within the expression's module, by text across modules.
        var expr_field_positions = RecordLabelPositions.init(checked_moduleKeyEqual(self.module.key, rep_field_view.key));
        defer expr_field_positions.deinit(self.parent.allocator);
        for (expr_fields, 0..) |field, index| {
            if (try expr_field_positions.put(self.parent.allocator, self.module.canonical_names, field.label, index)) {
                boxyLowerInvariant("record expression contained the same field label more than once");
            }
        }
        var unset_positions = RecordLabelPositions.init(expr_field_positions.same_module);
        defer unset_positions.deinit(self.parent.allocator);
        for (unset_fields, 0..) |unset_label, index| {
            if (try unset_positions.put(self.parent.allocator, self.module.canonical_names, unset_label, index)) {
                boxyLowerInvariant("record expression contained the same unset field label more than once");
            }
        }

        for (children) |child| {
            switch (child.role) {
                .record_field => |label| {
                    const field_layout = try self.aggregateFieldLayout(
                        self.parent.result.store.getLocal(target).layout_idx,
                        layout_index,
                    );
                    if (expr_field_positions.get(rep_field_view.canonical_names, label)) |source_index| {
                        const local = try self.addFrameLocal(field_layout);
                        field_locals[layout_index] = local;
                        const expr = self.module.checked_bodies.expr(expr_fields[source_index].value);
                        descriptor_fields[layout_index] = .{
                            .local = local,
                            .target_rep = child.rep,
                            .source_rep = if (child.record_field_kind.tag == .optional or child.record_field_kind.tag == .undetermined)
                                child.rep
                            else
                                self.exprTagPayloadStorageRep(local, child.rep, self.repForType(expr.ty)),
                        };
                        if (source_field_locals[source_index] != null) {
                            boxyLowerInvariant("record expression field was selected more than once by representation order");
                        }
                        source_field_locals[source_index] = local;
                        source_field_target_reps[source_index] = child.rep;
                        source_field_kinds[source_index] = child.record_field_kind.tag;
                        field_sources[layout_index] = .expr;
                    } else if (unset_positions.get(rep_field_view.canonical_names, label)) |unset_index| {
                        // An UNSET field (`label: _`) constructs the slot's
                        // Missing tag even under an update—never copied from
                        // the extension (design.md "In Progress: Unsetting an
                        // Optional Field").
                        if (child.record_field_kind.tag != .optional) {
                            boxyLowerInvariant("record expression unset field was not optional after checking");
                        }
                        const local = try self.addFrameLocal(field_layout);
                        field_locals[layout_index] = local;
                        descriptor_fields[layout_index] = .{
                            .local = local,
                            .target_rep = child.rep,
                            .source_rep = child.rep,
                        };
                        field_sources[layout_index] = .{ .missing_optional = child.rep };
                        unset_matched[unset_index] = true;
                    } else if (extension) |ext| {
                        const local = try self.addFrameLocal(field_layout);
                        field_locals[layout_index] = local;
                        const access_field_rep = self.recordFieldAccessInfo(ext.rep, rep_field_view, label).field_rep;
                        descriptor_fields[layout_index] = .{
                            .local = local,
                            .target_rep = child.rep,
                            .source_rep = if (self.representationBoundaryIsDirect(child.rep, access_field_rep))
                                access_field_rep
                            else
                                child.rep,
                        };
                        field_sources[layout_index] = .{ .extension = .{
                            .local = ext.local,
                            .rep = ext.rep,
                            .target_rep = child.rep,
                            .field_view = rep_field_view,
                            .label = label,
                        } };
                    } else switch (child.record_field_kind.tag) {
                        .optional => {
                            const local = try self.addFrameLocal(field_layout);
                            field_locals[layout_index] = local;
                            descriptor_fields[layout_index] = .{
                                .local = local,
                                .target_rep = child.rep,
                                .source_rep = child.rep,
                            };
                            field_sources[layout_index] = .{ .missing_optional = child.rep };
                        },
                        .defaulted => {
                            const default = self.omittedRecordFieldDefault(record_expr, rep_field_view, label) orelse
                                boxyLowerInvariant("defaulted record expression field had no record_omitted_defaults entry");
                            const local = try self.addFrameLocal(field_layout);
                            field_locals[layout_index] = local;
                            descriptor_fields[layout_index] = .{
                                .local = local,
                                .target_rep = child.rep,
                                .source_rep = child.rep,
                            };
                            field_sources[layout_index] = .{ .defaulted = .{
                                .default = default,
                                .field_type = child.source_type,
                            } };
                        },
                        .required, .undetermined, .err => boxyLowerInvariant("record expression was missing a required field from its checked type representation"),
                    }
                    layout_index += 1;
                },
                .record_ext => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => unreachable,
            }
        }
        for (source_field_locals) |maybe_local| {
            if (maybe_local == null) {
                boxyLowerInvariant("record expression had a field outside its checked type representation");
            }
        }
        for (unset_matched) |matched| {
            if (!matched) {
                boxyLowerInvariant("record expression had an unset field outside its checked type representation");
            }
        }

        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, rep_id, descriptor_fields);
        var aggregate_desc_owned = true;
        defer if (aggregate_desc_owned) aggregate_desc.deinit(self.parent.allocator);

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .contents_desc = aggregate_desc.contents_desc,
            .next = next,
        } }, self.origin);
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);

        // Walking backwards: the omitted fields' sources, then the written
        // fields' values, then the field descriptors' initializers.
        var chain_items = std.ArrayList(ExprChainItem).empty;
        errdefer chain_items.deinit(self.parent.allocator);
        var field_index = field_sources.len;
        while (field_index > 0) {
            field_index -= 1;
            switch (field_sources[field_index]) {
                .expr => {},
                .missing_optional => |slot_rep| try chain_items.append(self.parent.allocator, .{ .missing_optional_slot = .{ .target = field_locals[field_index], .rep = slot_rep } }),
                .defaulted => |defaulted| try chain_items.append(self.parent.allocator, .{ .lower = .{ .defaulted_field = .{
                    .field_module = self.module,
                    .target = field_locals[field_index],
                    .default = defaulted.default,
                    .field_type = defaulted.field_type,
                    .next = undefined,
                } } }),
                .extension => |ext| try chain_items.append(self.parent.allocator, .{ .record_ext_field = .{
                    .field_local = field_locals[field_index],
                    .target_rep = ext.target_rep,
                    .ext_local = ext.local,
                    .ext_rep = ext.rep,
                    .field_view = ext.field_view,
                    .label = ext.label,
                } }),
            }
        }
        var source_index = expr_fields.len;
        while (source_index > 0) {
            source_index -= 1;
            const target_local = source_field_locals[source_index].?;
            const target_rep = source_field_target_reps[source_index] orelse
                boxyLowerInvariant("record expression field target rep was not recorded");
            try chain_items.append(self.parent.allocator, if (source_field_kinds[source_index] == .optional or source_field_kinds[source_index] == .undetermined)
                .{ .lower = .{ .tag_variant = .{
                    .target = target_local,
                    .rep_id = target_rep,
                    .variant = self.plannedTagVariantByText(target_rep, "#Present"),
                    .args = @as(*const [1]checked.CheckedExprId, &expr_fields[source_index].value),
                    .next = undefined,
                } } }
            else
                .{ .lower = .{ .payload_storage = .{ .target = target_local, .target_rep = target_rep, .expr_id = expr_fields[source_index].value, .next = undefined } } });
        }
        try chain_items.append(self.parent.allocator, .prepend_field_initializers);
        const items = try chain_items.toOwnedSlice(self.parent.allocator);
        aggregate_desc_owned = false;
        return .{ .tail = .{ .chain = .{ .items = items, .current = continuation, .aggregate_desc = aggregate_desc } } };
    }

    /// Fill an omitted field from the record update's extension value.
    fn lowerRecordExtensionFieldInto(
        self: *ProcBodyBuilder,
        field_local: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        ext_local: LIR.LocalId,
        ext_rep: Plan.TypeRepId,
        field_view: ProcedureModuleView,
        label: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
        continuation: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.localUsesWorkerLayoutForRep(field_local, target_rep)) {
            return try self.lowerRecordFieldFromLocalInto(
                field_local,
                target_rep,
                ext_local,
                ext_rep,
                field_view,
                label,
                continuation,
            );
        }

        const worker_local = try self.addFrameLocalForRep(target_rep);
        const store_field = try self.assignWorkerValueToTagPayloadStorage(field_local, worker_local, target_rep, continuation);
        return try self.lowerRecordFieldFromLocalInto(
            worker_local,
            target_rep,
            ext_local,
            ext_rep,
            field_view,
            label,
            store_field,
        );
    }

    /// `default`'s origin identity is relative to `field_module`, the module
    /// owning the defaulted record field.
    fn beginDefaultedRecordField(
        self: *ProcBodyBuilder,
        field_module: ProcedureModuleView,
        target: LIR.LocalId,
        default: checked.CheckedFieldDefault,
        field_type: Plan.CheckedTypeIdentity,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        // Per-specialization materialization (design.md "Defaulted Fields"):
        // lower the declaring module's archived checked default expression
        // into the omitted field's slot—no archived constant, no root.
        const origin = default.origin() orelse
            boxyLowerInvariant("defaulted record field carried no declaring module identity");
        const origin_hash = field_module.canonical_names.moduleIdentityBytes(origin);
        const declaring_module = self.moduleForIdentityHash(origin_hash) orelse
            boxyLowerInvariant("defaulted record field's declaring module was absent from boxy lowering");
        const default_expr = declaring_module.checked_bodies.defaultExpr(default.expr_node) orelse
            boxyLowerInvariant("defaulted record field's expression was not archived");
        const default_ty = declaring_module.checked_bodies.expr(default_expr).ty;
        const expr_rep = self.repForModuleType(declaring_module, default_ty);
        const field_rep = self.repForTypeRef(field_type);
        const value_local = try self.addFrameLocalForRep(expr_rep);
        const assign = try self.assignRepresentationBoundaryConsumingSource(target, value_local, field_rep, expr_rep, next);
        return .{ .tail = .{ .module_expr = .{ .expr_module = declaring_module, .target = value_local, .expr_id = default_expr, .next = assign } } };
    }

    /// Lower a closed checked expression that belongs to `expr_module` into
    /// a local of this procedure: a scoped module-context swap, the boxy
    /// mirror of monotype lowering's view swap. The per-lambda contextual
    /// rep mapping is neutralized for the duration—its pattern ids are
    /// meaningless against the swapped module's stores, and a closed
    /// expression has no lambda context.
    ///
    /// Binder state is swapped to fresh empty arrays for the duration
    /// (`ensureBinderLocals` re-sizes them lazily against the swapped
    /// module). This is
    /// required even when `expr_module` is the current module: the caller's
    /// binder arrays index the caller's pattern binders, and boxy binder
    /// slots are write-once, so a second materialization of the same closed
    /// expression in one procedure body must not see the first's bindings.
    /// The replaced state lives on this frame, so nested materializations (a
    /// default whose expression constructs another defaulted nominal) stack
    /// naturally.
    fn stepModuleExpr(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        if (stage == 0) {
            task.saved = .{
                .module = self.module,
                .binder_locals = self.binder_locals,
                .binder_reps = self.binder_reps,
                .lambda_arg_patterns = self.lambda_arg_patterns,
                .lambda_arg_binding_locals = self.lambda_arg_binding_locals,
                .lambda_arg_worker_reps = self.lambda_arg_worker_reps,
                .current_lambda = self.current_lambda,
            };
            self.module = task.expr_module;
            self.binder_locals = &.{};
            self.binder_reps = &.{};
            self.lambda_arg_patterns = &.{};
            self.lambda_arg_binding_locals = &.{};
            self.lambda_arg_worker_reps = &.{};
            self.current_lambda = null;
            if (task.expected) |expected_ty| {
                return .{ .child = .{ .expected_ref = .{ .target = task.target, .expected_ty = expected_ty, .expr_id = task.expr_id, .next = task.next } } };
            }
            return .{ .child = .{ .expr = .{ .target = task.target, .expr_id = task.expr_id, .next = task.next } } };
        }
        self.restoreModuleExprContext(task.saved.?);
        task.saved = null;
        return exprDone(input.?);
    }

    fn beginStatement(
        self: *ProcBodyBuilder,
        statement_id: checked.CheckedStatementId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const statement = self.module.checked_bodies.statement(statement_id);
        self.origin = try self.sourceOrigin(statement.source_region);

        const rhs: ?checked.CheckedExprId = switch (statement.data) {
            inline .decl, .var_ => |decl| decl.expr,
            .reassign => |reassign| reassign.expr,
            .expr => |expr| expr,
            .pending,
            .promoted_proc,
            .var_uninitialized,
            .crash,
            .dbg,
            .expect,
            .for_,
            .while_,
            .infinite_loop,
            .breakable_loop,
            .break_,
            .return_,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => null,
        };
        if (rhs) |expr| {
            const data = self.module.checked_bodies.expr(expr).data;
            if (data == .runtime_error) return try self.beginRuntimeError(data.runtime_error.evaluated);
        }
        return switch (statement.data) {
            // A dangling annotation, such as a derived method marker of a
            // type declared in this body, has no runtime value to bind.
            .decl => |decl| if (self.module.checked_bodies.expr(decl.expr).data == .anno_only)
                exprDone(next)
            else if (decl.recursive and !try self.declOmitsRuntimeBinding(decl.pattern, decl.expr)) try self.beginRecursiveValueDecl(decl.pattern, decl.expr, next) else try self.beginDeclPattern(decl.pattern, decl.expr, next),
            // A promoted procedure is declared by its own template.
            .promoted_proc => exprDone(next),
            .var_ => |decl| blk: {
                self.forgetVarDescriptorInitialization(decl.pattern);
                break :blk try self.beginDeclPattern(decl.pattern, decl.expr, next);
            },
            .var_uninitialized => |decl| exprDone(try self.lowerUninitializedPattern(decl.pattern, next)),
            .reassign => |reassign| blk: {
                const pattern = self.module.checked_bodies.pattern(reassign.pattern);
                const source = try self.addFrameLocalForType(pattern.ty);
                const bound = try self.bindReassignPatternFromLocal(reassign.pattern, source, reassign.reassigned_binders, next);
                break :blk .{ .tail = .{ .expr = .{ .target = source, .expr_id = reassign.expr, .next = bound } } };
            },
            .expr => |expr_id| blk: {
                const expr = self.module.checked_bodies.expr(expr_id);
                // A runtime error produces no value, so its discarded local
                // is zero-sized.
                const temp = if (expr.data == .runtime_error)
                    try self.addFrameLocal(.zst)
                else
                    try self.addFrameLocalForType(expr.ty);
                break :blk .{ .tail = .{ .expr = .{ .target = temp, .expr_id = expr_id, .next = next } } };
            },
            .expect => |expr_id| try self.beginExpectStmt(expr_id, next),
            .return_ => |ret| try self.beginReturn(ret.expr, ret.lambda),
            .while_ => |while_| .{ .tail = .{ .while_ = .{ .cond_id = while_.cond, .body_id = while_.body, .can_exit = true, .next = next } } },
            .infinite_loop => |loop| .{ .tail = .{ .while_ = .{ .cond_id = loop.cond, .body_id = loop.body, .can_exit = false, .next = next } } },
            .breakable_loop => |loop| .{ .tail = .{ .while_ = .{ .cond_id = loop.cond, .body_id = loop.body, .can_exit = true, .next = next } } },
            .for_ => |for_| blk: {
                const target = try self.addFrameLocal(.zst);
                break :blk .{ .tail = .{ .iterator_for = .{ .target = target, .for_ = forLoop(for_), .next = next } } };
            },
            .break_ => exprDone(try self.lowerBreak()),
            .dbg => |expr_id| blk: {
                const message = try self.addFrameLocal(.str);
                const debug_stmt = try self.parent.result.store.addCFStmt(.{ .debug = .{
                    .message = message,
                    .next = next,
                } }, self.origin);
                break :blk try self.beginInspectExpr(message, expr_id, debug_stmt);
            },
            .crash => |msg| exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(self.module.checked_bodies.stringLiteral(msg)) },
            } }, self.origin)),
            .runtime_error => exprDone(try self.lowerCheckedRuntimeError()),
            .import_,
            .alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            => exprDone(next),
            .pending, .where_alias_decl => boxyLowerInvariant("checked statement form reached boxy body lowering before its LIR lowering was implemented"),
        };
    }

    /// The closure a local declaration binds, when it binds one.
    fn declaredClosureExpr(self: *ProcBodyBuilder, expr_id: checked.CheckedExprId) ?checked.CheckedExprId {
        const site = nestedCallableSiteExprForExpr(self.module, expr_id) orelse return null;
        if (self.module.checked_bodies.expr(site).data != .closure) return null;
        return site;
    }

    fn captureIsReassignable(self: *ProcBodyBuilder, capture: checked.CheckedCapture) bool {
        const binder = self.module.checked_bodies.pattern_binder_by_pattern[@backingInt(capture.pattern)] orelse
            boxyLowerInvariant("boxy closure capture referenced a non-binding pattern");
        return self.module.checked_bodies.patternBinder(binder).reassignable;
    }

    /// A declared closure's callable is constructed at each use, but its
    /// captures are the values at the declaration. A reassignable capture can
    /// change in between, so its declaration-time value gets its own local.
    fn reserveClosureCaptureSnapshots(self: *ProcBodyBuilder, expr_id: checked.CheckedExprId) Allocator.Error!void {
        const closure_expr = self.declaredClosureExpr(expr_id) orelse return;
        const captures = self.callableExprCaptures(closure_expr);
        for (captures) |capture| {
            if (self.captureIsReassignable(capture)) break;
        } else return;

        const closure = Plan.CheckedExprIdentity{ .module = self.module.key, .expr = closure_expr };
        if (self.closureCaptureSnapshotLocals(closure) != null) {
            boxyLowerInvariant("boxy reserved a declared closure's capture snapshots twice");
        }
        const locals = try self.parent.allocator.alloc(?LIR.LocalId, captures.len);
        errdefer self.parent.allocator.free(locals);
        for (captures, locals) |capture, *local| {
            if (!self.captureIsReassignable(capture)) {
                local.* = null;
                continue;
            }
            const binder = self.module.checked_bodies.pattern_binder_by_pattern[@backingInt(capture.pattern)].?;
            const rep = self.binderStorageRep(binder);
            local.* = if (self.parent.layoutIsBoxStorage(self.workerRuntimeLayoutForRep(rep).layoutIdx()))
                try self.addFrameLocalForRepWithFreshDescriptor(rep)
            else
                try self.addFrameLocalForRep(rep);
        }
        try self.closure_capture_snapshots.append(self.parent.allocator, .{ .closure = closure, .locals = locals });
    }

    fn closureCaptureSnapshotLocals(self: *ProcBodyBuilder, closure: Plan.CheckedExprIdentity) ?[]?LIR.LocalId {
        for (self.closure_capture_snapshots.items) |snapshot| {
            if (snapshot.closure.expr == closure.expr and checked_moduleKeyEqual(snapshot.closure.module, closure.module)) {
                return snapshot.locals;
            }
        }
        return null;
    }

    fn prependClosureCaptureSnapshots(
        self: *ProcBodyBuilder,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const closure_expr = self.declaredClosureExpr(expr_id) orelse return next;
        const locals = self.closureCaptureSnapshotLocals(.{ .module = self.module.key, .expr = closure_expr }) orelse return next;
        var continuation = next;
        for (self.callableExprCaptures(closure_expr), locals) |capture, maybe_local| {
            const local = maybe_local orelse continue;
            continuation = try self.assignLocal(local, self.localForPattern(capture.pattern), continuation);
        }
        return continuation;
    }

    /// The local holding one source capture of a callable being constructed.
    fn sourceCaptureLocal(
        self: *ProcBodyBuilder,
        source: Plan.WorkerSource,
        maybe_expr: ?checked.CheckedExprId,
        capture_index: usize,
        capture: checked.CheckedCapture,
    ) LIR.LocalId {
        const closure: ?Plan.CheckedExprIdentity = if (maybe_expr) |expr_id|
            .{ .module = self.module.key, .expr = expr_id }
        else switch (source) {
            .nested_expr => |expr_ref| expr_ref,
            .procedure_template, .procedure_binding, .procedure_use, .generated_codec, .generated_field_iterator => null,
        };
        if (closure) |closure_ref| {
            if (self.closureCaptureSnapshotLocals(closure_ref)) |locals| {
                if (locals[capture_index]) |local| return local;
            }
        }
        return self.localForPattern(capture.pattern);
    }

    fn beginDeclPattern(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (try self.declOmitsRuntimeBinding(pattern_id, expr_id)) return exprDone(try self.prependClosureCaptureSnapshots(expr_id, next));

        const pattern = self.module.checked_bodies.pattern(pattern_id);
        const source = switch (pattern.data) {
            .assign => self.localForPattern(pattern_id),
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => try self.addFrameLocalForType(pattern.ty),
        };
        const value: ExprChainItem = .{ .lower = .{ .expr = .{ .target = source, .expr_id = expr_id, .next = undefined } } };
        if (try self.patternCanMiss(pattern_id)) {
            const miss = PatternMiss{ .join_id = self.freshJoinPointId() };
            const items = try self.parent.allocator.alloc(ExprChainItem, 4);
            items[0] = .{ .lower = .{ .pattern = .{ .pattern = pattern_id, .source = source, .mode = .{ .match = .{ .miss = miss, .remaps = &.{} } }, .next = undefined } } };
            items[1] = .{ .pattern_miss_crash = miss.join_id };
            items[2] = value;
            items[3] = .{ .capture_snapshots = expr_id };
            return exprChain(items, next);
        }
        const items = try self.parent.allocator.alloc(ExprChainItem, 3);
        items[0] = .{ .lower = .{ .pattern = .{ .pattern = pattern_id, .source = source, .mode = .bind, .next = undefined } } };
        items[1] = value;
        items[2] = .{ .capture_snapshots = expr_id };
        return exprChain(items, next);
    }

    fn beginExpectStmt(
        self: *ProcBodyBuilder,
        child: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const child_expr = self.module.checked_bodies.expr(child);
        const cond = try self.addFrameLocalForType(child_expr.ty);
        const expect_stmt = try self.parent.result.store.addCFStmt(.{ .expect = .{
            .condition = cond,
            .site = try self.parent.expectSite(self.module, self.origin.region),
            .next = next,
        } }, self.origin);
        return .{ .tail = .{ .expr = .{ .target = cond, .expr_id = child, .next = expect_stmt } } };
    }

    fn beginExpectErr(
        self: *ProcBodyBuilder,
        child: checked.CheckedExprId,
        snippet: checked.CheckedStringLiteralId,
    ) Allocator.Error!ExprStep {
        const child_expr = self.module.checked_bodies.expr(child);
        const child_local = try self.addFrameLocalForType(child_expr.ty);
        const rendered = try self.addFrameLocal(.str);
        const prefix = try self.addFrameLocal(.str);
        const with_value = try self.addFrameLocal(.str);
        const suffix = try self.addFrameLocal(.str);
        const message = try self.addFrameLocal(.str);

        const snippet_index = @backingInt(snippet);
        if (snippet_index >= self.module.checked_bodies.stringLiteralCount()) {
            boxyLowerInvariant("checked expect_err snippet referenced a missing string literal");
        }
        const snippet_text = self.module.checked_bodies.stringLiteral(@fromBackingInt(@intCast(snippet_index)));
        const prefix_text = try std.fmt.allocPrint(
            self.parent.allocator,
            "The `?` operator in `{s}` evaluated an `Err` inside an `expect`. The value was: Err(",
            .{snippet_text},
        );
        defer self.parent.allocator.free(prefix_text);

        var continuation = try self.parent.result.store.addCFStmt(.{ .expect_err = .{
            .message = message,
            .region = self.origin.region,
        } }, self.origin);
        continuation = try self.assignStrConcat(message, with_value, suffix, continuation);
        continuation = try self.assignStringBytesLiteral(suffix, ")", continuation);
        continuation = try self.assignStrConcat(with_value, prefix, rendered, continuation);
        continuation = try self.lowerInspectLocalInto(rendered, child_local, child_expr.ty, continuation);
        continuation = try self.assignStringBytesLiteral(prefix, prefix_text, continuation);
        return .{ .tail = .{ .expr = .{ .target = child_local, .expr_id = child, .next = continuation } } };
    }

    fn beginReturn(
        self: *ProcBodyBuilder,
        expr_id: checked.CheckedExprId,
        lambda_id: checked.CheckedExprId,
    ) Allocator.Error!ExprStep {
        const current = self.current_lambda orelse
            boxyLowerInvariant("checked return reached boxy lowering outside a lambda worker");
        if (current != lambda_id) {
            boxyLowerInvariant("checked return target lambda differed from current boxy worker lambda");
        }

        const expr = self.module.checked_bodies.expr(expr_id);
        // A checked runtime error produces no value, so returning it is the
        // crash itself; its own checked type has no representation.
        if (expr.data == .runtime_error) return try self.beginRuntimeError(expr.data.runtime_error.evaluated);
        const expr_rep = self.repForType(expr.ty);
        const expr_layout = self.workerRuntimeLayoutForRep(expr_rep).layoutIdx();
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy explicit return reached a non-function worker");
        const ret_rep = worker_function.ret;
        const ret_layout = self.workerReturnLayout();

        const expr_local = try self.addFrameBoundaryTargetLocalForRep(expr_rep);
        // Every return edge writes the header's value and descriptor locals,
        // so lexical descriptor bindings cannot change the procedure's ABI.
        const ret_local = self.worker_return_local orelse
            boxyLowerInvariant("checked return reached a worker without its reserved return local");
        if (self.parent.result.store.getLocal(expr_local).layout_idx != expr_layout or
            self.parent.result.store.getLocal(ret_local).layout_idx != ret_layout)
        {
            boxyLowerInvariant("boxy explicit return boundary layout disagreed with its planned representations");
        }
        const ret_stmt = try self.parent.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } }, self.origin);
        const assign_ret = try self.assignRepresentationBoundary(ret_local, expr_local, ret_rep, expr_rep, ret_stmt);
        return .{ .tail = .{ .expr = .{ .target = expr_local, .expr_id = expr_id, .next = assign_ret } } };
    }

    fn stepIf(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        // Stage 0 lowers the final else; then each branch, from the last, lowers
        // its body (odd stages) and its condition (even stages).
        if (stage == 0) {
            task.done = self.freshJoinPointId();
            task.index = task.branches.len;
            return .{ .child = .{ .expected = .{ .target = task.target, .expected_ty = task.if_ty, .expr_id = task.final_else, .next = try self.joinJump(task.done) } } };
        }
        if (stage % 2 == 1) {
            task.current = input.?;
            if (task.index == 0) {
                const params = [_]LIR.LocalId{task.target};
                return exprDone(try self.parent.result.store.addCFStmt(.{ .join = .{
                    .id = task.done,
                    .params = try self.joinParamSpan(&params),
                    .body = task.next,
                    .remainder = task.current,
                } }, self.glueOrigin()));
            }
            task.index -= 1;
            const branch = task.branches[task.index];
            return .{ .child = .{ .expected = .{ .target = task.target, .expected_ty = task.if_ty, .expr_id = branch.body, .next = try self.joinJump(task.done) } } };
        }
        const branch = task.branches[task.index];
        const body = input.?;
        const cond_expr = self.module.checked_bodies.expr(branch.cond);
        const cond_local = try self.addFrameLocalForType(cond_expr.ty);
        const switch_stmt = try self.boolSwitchNoContinuation(cond_local, body, task.current);
        return .{ .child = .{ .expr = .{ .target = cond_local, .expr_id = branch.cond, .next = switch_stmt } } };
    }

    fn stepBoolBinop(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        switch (stage) {
            0 => switch (task.op) {
                .@"and" => return .{ .child = .{ .expr = .{ .target = task.target, .expr_id = task.rhs, .next = task.next } } },
                .@"or" => {
                    task.true_body = try self.assignBoolLiteral(task.target, true, task.next);
                    return .{ .child = .{ .expr = .{ .target = task.target, .expr_id = task.rhs, .next = task.next } } };
                },
                .add, .sub, .mul, .div, .rem, .lt, .gt, .le, .ge, .eq, .ne, .div_trunc, .range_exclusive, .range_inclusive => boxyLowerInvariant("non-short-circuit checked binop reached boxy binop lowering before dispatch lowering"),
            },
            1 => {
                switch (task.op) {
                    .@"and" => {
                        task.true_body = input.?;
                        task.false_body = try self.assignBoolLiteral(task.target, false, task.next);
                    },
                    .@"or" => task.false_body = input.?,
                    .add, .sub, .mul, .div, .rem, .lt, .gt, .le, .ge, .eq, .ne, .div_trunc, .range_exclusive, .range_inclusive => unreachable,
                }
                const lhs_expr = self.module.checked_bodies.expr(task.lhs);
                const cond = try self.addFrameLocalForType(lhs_expr.ty);
                const switch_stmt = try self.boolSwitchNoContinuation(cond, task.true_body, task.false_body);
                return .{ .child = .{ .expr = .{ .target = cond, .expr_id = task.lhs, .next = switch_stmt } } };
            },
            else => return exprDone(input.?),
        }
    }

    /// Lower `args` into `lowered`, each continuing into the next, then into
    /// `next`.
    fn loweredExprsChain(
        self: *ProcBodyBuilder,
        args: []const checked.CheckedExprId,
        lowered: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (args.len != lowered.len) {
            boxyLowerInvariant("boxy lowered expression locals disagreed with source expression count");
        }
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, args.len);
        for (chain_items, 0..) |*item, offset| {
            const index = args.len - 1 - offset;
            item.* = .{ .lower = .{ .expr = .{ .target = lowered[index], .expr_id = args[index], .next = undefined } } };
        }
        return exprChain(chain_items, next);
    }

    fn beginDirectCall(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        call_expr: checked.CheckedExprId,
        call: anytype,
        ret_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (call.direct_target == null or
            self.parent.plan.callIsThroughAlias(.{ .module = self.module.key, .expr = call_expr }))
        {
            return try self.beginErasedCall(target, ret_ty, call.func, call.args, next);
        }
        if (self.directTargetIsLocalProc(call.direct_target.?)) {
            if (self.parent.plan.directCallPlanForCall(
                .{ .module = self.module.key, .expr = call_expr },
                self.worker_layout.worker,
            )) |direct_plan| {
                return .{ .tail = .{ .planned_call = .{
                    .target = target,
                    .target_rep = self.repForType(ret_ty),
                    .checked_ret_ty = ret_ty,
                    .direct_plan = direct_plan,
                    .next = next,
                } } };
            }
            return try self.beginErasedCall(target, ret_ty, call.func, call.args, next);
        }
        const direct_plan = self.parent.plan.directCallPlanForCall(
            .{ .module = self.module.key, .expr = call_expr },
            self.worker_layout.worker,
        ) orelse
            boxyLowerInvariant("checked direct call reached boxy lowering without a planned worker");
        return .{ .tail = .{ .planned_call = .{
            .target = target,
            .target_rep = self.repForType(ret_ty),
            .checked_ret_ty = ret_ty,
            .direct_plan = direct_plan,
            .next = next,
        } } };
    }

    fn beginDispatchCall(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        call_expr: checked.CheckedExprId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        ret_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const dispatch = self.staticDispatchPlan(maybe_plan);
        switch (dispatch.resolution) {
            .direct_closed, .direct_parametric => {},
            .direct_pending => boxyLowerInvariant("unfinalized direct call reached Boxy lowering"),
            // A structural parser or encoder runs its generated codec
            // constructor, which planning bound as this call's direct worker.
            .structural => |derivation| switch (derivation.kind()) {
                .parser, .encoder => {},
                .equality, .hash, .map, .map_effectful => return try self.beginUnresolvedDispatchCall(target, call_expr, dispatch, ret_ty, next),
            },
            .evidence_dependent => return try self.beginUnresolvedDispatchCall(target, call_expr, dispatch, ret_ty, next),
            .checked_error, .@"unreachable" => return try self.beginCrashingDispatch(dispatch),
        }

        const direct_plan = if (self.literal_initializer) |index|
            self.parent.plan.literal_evidence.?.initializers.items[index].direct_call orelse
                boxyLowerInvariant("direct literal initializer omitted its closed call plan")
        else
            self.parent.plan.directCallPlanForCall(
                .{ .module = self.module.key, .expr = call_expr },
                self.worker_layout.worker,
            ) orelse
                boxyLowerInvariant("checked static dispatch call reached boxy lowering without a planned worker");

        var continuation = next;
        var call_target = target;
        switch (dispatch.result_mode) {
            .equality => |eq| if (eq.negated) {
                const raw = try self.addFrameLocal(.bool);
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                    .target = target,
                    .op = .bool_not,
                    .rc_effect = LIR.LowLevel.bool_not.rcEffect(),
                    .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{raw}),
                    .next = next,
                } }, self.origin);
                call_target = raw;
            },
            .value,
            .hash,
            .parser_for,
            .encoder_for,
            .map,
            .map_effectful,
            => {},
        }

        return .{ .tail = .{ .planned_call = .{
            .target = call_target,
            .target_rep = self.repForType(ret_ty),
            .checked_ret_ty = ret_ty,
            .direct_plan = direct_plan,
            .next = continuation,
        } } };
    }

    fn beginInspectExpr(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        const checked_rep = self.repForType(expr.ty);
        const storage_rep = self.exprStorageRep(expr, checked_rep);
        const value = try self.addFrameLocalForRep(storage_rep);
        const inspect = try self.lowerInspectRepLocalInto(target, value, storage_rep, next);
        return if (storage_rep == checked_rep)
            .{ .tail = .{ .expr = .{ .target = value, .expr_id = expr_id, .next = inspect } } }
        else
            exprDone(try self.lowerExprStorageRepInto(value, storage_rep, expr_id, inspect));
    }

    /// The checker decided this equality compares against one payload-free
    /// tag, so it is exactly a test of the value's tag, as a `match` arm for
    /// that tag would perform.
    fn beginTagDiscriminantEq(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        discriminant: checked.CheckedTagDiscriminantEquality,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const value_expr = self.module.checked_bodies.expr(discriminant.value);
        const value_rep = self.matchConditionRep(discriminant.value, self.repForType(value_expr.ty));
        const value = try self.addFrameBoundaryTargetLocalForRep(value_rep);
        if (self.parent.result.store.getLocal(value).boxy_desc == null and
            self.matchConditionNeedsExactResultDescriptor(discriminant.value, value_rep))
        {
            const desc_local = try self.addFrameLocal(.opaque_ptr);
            self.parent.result.store.setLocalBoxyDesc(value, .{ .local = desc_local });
        }

        const done = self.freshJoinPointId();
        const miss = PatternMiss{ .join_id = self.freshJoinPointId() };
        const matched = try self.assignBoolLiteral(target, !negated, try self.joinJump(done));
        const state = try self.parent.allocator.create(PatternState);
        state.* = .{ .current = matched };
        defer self.releasePatternState(state);
        try self.expandTagPattern(state, value_expr.ty, value_rep, discriminant.tag, &.{}, value, .{ .miss = miss, .remaps = &.{} });
        while (state.actions.pop()) |action| {
            if (try self.stepPatternAction(state, action) != null) {
                boxyLowerInvariant("payload-free tag equality requested a payload expression");
            }
        }
        const tested = state.current;
        const missed = try self.assignBoolLiteral(target, negated, try self.joinJump(done));
        const test_stmt = try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = miss.join_id,
            .params = LIR.LocalSpan.empty(),
            .body = missed,
            .remainder = tested,
        } }, self.glueOrigin());
        const params = [_]LIR.LocalId{target};
        const joined = try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = done,
            .params = try self.joinParamSpan(&params),
            .body = next,
            .remainder = test_stmt,
        } }, self.glueOrigin());
        return .{ .tail = .{ .into_rep = .{ .target = value, .target_rep = value_rep, .expr_id = discriminant.value, .next = joined } } };
    }

    fn beginStructuralEq(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs_id: checked.CheckedExprId,
        rhs_id: checked.CheckedExprId,
        planned_operand_rep: ?Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const lhs_expr = self.module.checked_bodies.expr(lhs_id);
        const rhs_expr = self.module.checked_bodies.expr(rhs_id);

        const rep_id = planned_operand_rep orelse self.repForType(lhs_expr.ty);
        const operand_layout = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        if (planned_operand_rep == null and self.workerRuntimeLayoutForType(rhs_expr.ty).layoutIdx() != operand_layout) {
            boxyLowerInvariant("checked structural equality operand layouts disagreed");
        }

        const lhs = try self.addStructuralEqOperandLocalForRep(rep_id);
        const rhs = try self.addFrameLocal(operand_layout);
        if (self.parent.result.store.getLocal(lhs).boxy_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(rhs, desc);
        }
        if (self.parent.result.store.getLocal(lhs).layout_idx != operand_layout or
            self.parent.result.store.getLocal(rhs).layout_idx != operand_layout)
        {
            boxyLowerInvariant("boxy structural equality operand local layout disagreed with checked type");
        }

        const outer_derived = try self.enterDerivedContext(self.worker_layout.worker, rep_id);
        const continuation = try self.lowerEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next);
        self.derived_context = outer_derived;
        const shared_desc: ?LIR.LocalId = if (self.parent.result.store.getLocal(lhs).boxy_desc) |desc| desc.localOrNull() else null;
        // Walking backwards: the right operand, lowered into the shared
        // descriptor under bindings that are restored afterwards when the
        // operands share one, then the left operand.
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, if (shared_desc != null) 4 else 2);
        if (shared_desc) |desc_local| {
            chain_items[0] = .{ .bind_shared_descriptor = desc_local };
            chain_items[1] = .{ .lower = .{ .shared_rep = .{ .target = rhs, .target_rep = rep_id, .expr_id = rhs_id, .next = undefined } } };
            chain_items[2] = .restore_descriptors;
        } else {
            chain_items[0] = .{ .lower = .{ .into_rep = .{ .target = rhs, .target_rep = rep_id, .expr_id = rhs_id, .next = undefined } } };
        }
        chain_items[chain_items.len - 1] = .{ .lower = .{ .into_rep = .{ .target = lhs, .target_rep = rep_id, .expr_id = lhs_id, .next = undefined } } };
        return exprChain(chain_items, continuation);
    }

    fn beginSharedRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        const source_rep = self.repForType(expr.ty);
        const source = try self.addFrameBoundaryTargetLocalForRep(source_rep);
        const assign = try self.assignPlannedCallBoundary(target, source, target_rep, source_rep, next);
        return .{ .tail = .{ .expr = .{ .target = source, .expr_id = expr_id, .next = assign } } };
    }

    fn beginStructuralHash(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value_id: checked.CheckedExprId,
        hasher_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const value_expr = self.module.checked_bodies.expr(value_id);
        const hasher_expr = self.module.checked_bodies.expr(hasher_id);
        const value = try self.addFrameLocalForType(value_expr.ty);
        const hasher = try self.addFrameLocalForType(hasher_expr.ty);
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(hasher).layout_idx) {
            boxyLowerInvariant("checked structural hash target layout differed from input hasher layout");
        }
        const value_rep = self.repForType(value_expr.ty);
        const outer_derived = try self.enterDerivedContext(self.worker_layout.worker, value_rep);
        const continuation = try self.lowerHashRepLocalsInto(target, value, hasher, value_rep, next);
        self.derived_context = outer_derived;
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, 2);
        chain_items[0] = .{ .lower = .{ .expr = .{ .target = hasher, .expr_id = hasher_id, .next = undefined } } };
        chain_items[1] = .{ .lower = .{ .expr = .{ .target = value, .expr_id = value_id, .next = undefined } } };
        return exprChain(chain_items, continuation);
    }

    fn beginMethodEq(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const plan = self.staticDispatchPlan(maybe_plan);
        switch (plan.result_mode) {
            .equality => {},
            .value, .hash, .parser_for, .encoder_for, .map, .map_effectful => boxyLowerInvariant("checked method equality used a non-equality dispatch plan"),
        }
        // Equality follows the checked resolution: a builtin nominal's
        // `is_eq` is its own method (`Dict` and `Set` compare contents, not
        // their hash tables), exactly as for any other nominal.
        return switch (plan.resolution) {
            .direct_closed,
            .direct_parametric,
            .evidence_dependent,
            .structural,
            => try self.beginDispatchCall(target, plan.expr, maybe_plan, self.module.checked_bodies.expr(plan.expr).ty, next),
            .direct_pending => boxyLowerInvariant("unfinalized direct call reached Boxy lowering"),
            .checked_error, .@"unreachable" => try self.beginCrashingDispatch(plan),
        };
    }

    /// The local a loop body lowers into; the loop discards its value. A
    /// `runtime_error` body produces no value, and the representation plan
    /// gives its type no representation.
    fn addLoopBodyResultLocal(self: *ProcBodyBuilder, body_id: checked.CheckedExprId) Allocator.Error!LIR.LocalId {
        const body_expr = self.module.checked_bodies.expr(body_id);
        if (body_expr.data == .runtime_error) return try self.addFrameLocal(.zst);
        return try self.addFrameLocalForType(body_expr.ty);
    }

    /// A loop header re-evaluates its condition before each pass of its body,
    /// which jumps back to the header. The loop is the innermost `break`
    /// target while its body lowers.
    fn stepWhile(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        switch (stage) {
            0 => {
                const cond_expr = self.module.checked_bodies.expr(task.cond_id);
                task.cond_local = try self.addFrameLocalForType(cond_expr.ty);
                if (self.parent.result.store.getLocal(task.cond_local).layout_idx != .bool) {
                    boxyLowerInvariant("checked while condition did not lower to Bool layout");
                }

                const body_result = try self.addLoopBodyResultLocal(task.body_id);
                const loop_result = try self.addFrameLocal(.zst);

                task.join_id = self.freshJoinPointId();
                const unreachable_exit = if (task.can_exit) null else try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin());
                task.after_loop = unreachable_exit orelse task.next;
                self.parent.result.store.shapes.loop = true;
                try self.loop_stack.append(self.parent.allocator, .{
                    .join_id = task.join_id,
                    .result_target = loop_result,
                    .after_loop = task.after_loop,
                });
                task.loop_pushed = true;

                const continue_stmt = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = task.join_id } }, self.glueOrigin());
                return .{ .child = .{ .expr = .{ .target = body_result, .expr_id = task.body_id, .next = continue_stmt } } };
            },
            1 => {
                const switch_stmt = try self.boolSwitchNoContinuation(task.cond_local, input.?, task.after_loop);
                return .{ .child = .{ .expr = .{ .target = task.cond_local, .expr_id = task.cond_id, .next = switch_stmt } } };
            },
            else => {
                const header = input.?;
                const initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = task.join_id } }, self.glueOrigin());
                const loop = try self.parent.result.store.addCFStmt(.{ .join = .{
                    .id = task.join_id,
                    .params = LIR.LocalSpan.empty(),
                    .body = header,
                    .remainder = initial_jump,
                } }, self.glueOrigin());
                task.loop_pushed = false;
                _ = self.loop_stack.pop();
                return exprDone(loop);
            },
        }
    }

    /// The parts of a checked `for` loop its lowering reads.
    const ForLoop = struct {
        pattern: checked.CheckedPatternId,
        body: checked.CheckedExprId,
        plan: ?static_dispatch.IteratorForPlanId,
    };

    fn forLoop(for_: anytype) ForLoop {
        return .{ .pattern = for_.pattern, .body = for_.body, .plan = for_.plan };
    }

    /// State of a `for` loop between its lowering stages.
    const IteratorForState = struct {
        outer_descriptors: DescriptorBindingsSnapshot,
        plan_id: static_dispatch.IteratorForPlanId,
        plan: static_dispatch.IteratorForPlan,
        step_type: Plan.CheckedTypeIdentity,
        iterator_param: LIR.LocalId,
        initial_iterator: LIR.LocalId,
        join_id: LIR.JoinPointId,
        loop_pushed: bool = false,
        initial_jump: LIR.CFStmtId = undefined,
    };

    fn freeIteratorForState(self: *ProcBodyBuilder, state: *IteratorForState) void {
        self.restoreDescriptorBindings(state.outer_descriptors);
        state.outer_descriptors.deinit(self.parent.allocator);
        if (state.loop_pushed) _ = self.loop_stack.pop();
        self.parent.allocator.destroy(state);
    }

    /// A `for` loop: the iterator's creation, then the loop body, which
    /// steps the iterator and runs the source body on each item. The loop
    /// is the innermost `break` target while it lowers, and descriptor
    /// bindings made inside it are restored when it is done.
    fn stepIteratorFor(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        switch (stage) {
            0 => {
                const plan_id = task.for_.plan orelse
                    boxyLowerInvariant("checked iterator for reached boxy lowering without an iterator dispatch plan");
                const plan = self.iteratorForPlan(plan_id);
                // An `iter` call that cannot run evaluates the iterable it
                // receives and then crashes; a `next` call that cannot run
                // crashes once `iter` has produced the iterator it receives.
                switch (plan.iter.resolution) {
                    .checked_error, .@"unreachable" => {
                        const iterable = self.module.checked_bodies.expr(plan.iterable);
                        const discarded = if (iterable.data == .runtime_error)
                            try self.addFrameLocal(.zst)
                        else
                            try self.addFrameLocalForType(iterable.ty);
                        const chain_items = try self.parent.allocator.alloc(ExprChainItem, 1);
                        chain_items[0] = .{ .lower = .{ .expr = .{ .target = discarded, .expr_id = plan.iterable, .next = undefined } } };
                        return exprChain(chain_items, try self.lowerDispatchCrashInto(plan.iter.resolution));
                    },
                    .direct_pending => boxyLowerInvariant("unfinalized iterator call reached Boxy lowering"),
                    .direct_closed, .direct_parametric, .evidence_dependent => {},
                    .structural => boxyLowerInvariant("structural iterator dispatch reached boxy lowering"),
                }
                switch (plan.next.resolution) {
                    .checked_error, .@"unreachable" => {
                        const iterator_type = if (self.parent.plan.iteratorCallPlanFor(self.module.key, plan_id, .iter, self.worker_layout.worker)) |call_plan|
                            call_plan.ret_type
                        else
                            Plan.CheckedTypeIdentity{ .module = self.module.key, .ty = plan.iterator_ty };
                        const discarded = try self.addFrameLocalForRepWithFreshDescriptor(self.repForTypeRef(iterator_type));
                        return .{ .tail = .{ .iter_dispatch = .{
                            .target = discarded,
                            .plan_id = plan_id,
                            .kind = .iter,
                            .plan = plan,
                            .call = plan.iter,
                            .loop_iterator = null,
                            .next = try self.lowerDispatchCrashInto(plan.next.resolution),
                        } } };
                    },
                    .direct_pending => boxyLowerInvariant("unfinalized iterator call reached Boxy lowering"),
                    .direct_closed, .direct_parametric, .evidence_dependent => {},
                    .structural => boxyLowerInvariant("structural iterator dispatch reached boxy lowering"),
                }
                if (!self.isZstLocal(task.target)) {
                    boxyLowerInvariant("checked iterator for reached boxy lowering with non-Unit result layout");
                }
                // Descriptor locals reserved and bound while lowering this loop are
                // positional: they do not dominate statements lowered afterwards
                // (which execute earlier), so their bound-ness must not leak out.
                const state = try self.parent.allocator.create(IteratorForState);
                state.* = .{
                    .outer_descriptors = self.snapshotDescriptorBindings() catch |err| {
                        self.parent.allocator.destroy(state);
                        return err;
                    },
                    .plan_id = plan_id,
                    .plan = plan,
                    .step_type = undefined,
                    .iterator_param = undefined,
                    .initial_iterator = undefined,
                    .join_id = undefined,
                };
                task.state = state;
                try self.reserveMatchPatternBindings(task.for_.pattern);
                try self.reserveMatchPatternDescriptors(task.for_.pattern, &.{});

                const iter_call_plan = self.parent.plan.iteratorCallPlanFor(self.module.key, plan_id, .iter, self.worker_layout.worker);
                const next_call_plan = self.parent.plan.iteratorCallPlanFor(self.module.key, plan_id, .next, self.worker_layout.worker);
                const iterator_type = if (iter_call_plan) |call_plan|
                    call_plan.ret_type
                else switch (plan.iter.resolution) {
                    .direct_closed, .direct_parametric => boxyLowerInvariant("checked iterator iter dispatch reached boxy lowering without a planned worker"),
                    .direct_pending => boxyLowerInvariant("unfinalized iterator call reached Boxy lowering"),
                    .evidence_dependent,
                    .structural,
                    .checked_error,
                    .@"unreachable",
                    => Plan.CheckedTypeIdentity{ .module = self.module.key, .ty = plan.iterator_ty },
                };
                state.step_type = if (next_call_plan) |call_plan|
                    call_plan.ret_type
                else switch (plan.next.resolution) {
                    .direct_closed, .direct_parametric => boxyLowerInvariant("checked iterator next dispatch reached boxy lowering without a planned worker"),
                    .direct_pending => boxyLowerInvariant("unfinalized iterator call reached Boxy lowering"),
                    .evidence_dependent,
                    .structural,
                    .checked_error,
                    .@"unreachable",
                    => Plan.CheckedTypeIdentity{ .module = self.module.key, .ty = plan.step_ty },
                };
                const iterator_rep = self.repForTypeRef(iterator_type);
                state.iterator_param = try self.addFrameLocalForRepWithFreshDescriptor(iterator_rep);
                state.initial_iterator = try self.addFrameLocalForRepWithFreshDescriptor(iterator_rep);
                state.join_id = self.freshJoinPointId();

                self.parent.result.store.shapes.loop = true;
                try self.loop_stack.append(self.parent.allocator, .{
                    .join_id = state.join_id,
                    .result_target = task.target,
                    .after_loop = task.next,
                });
                state.loop_pushed = true;

                var initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = state.join_id } }, self.glueOrigin());
                initial_jump = try self.setLocalInitializeJoinParam(state.iterator_param, state.initial_iterator, initial_jump);
                return .{ .child = .{ .iter_dispatch = .{
                    .target = state.initial_iterator,
                    .plan_id = plan_id,
                    .kind = .iter,
                    .plan = plan,
                    .call = plan.iter,
                    .loop_iterator = null,
                    .next = initial_jump,
                } } };
            },
            1 => {
                const state = task.state.?;
                state.initial_jump = input.?;
                if (self.localDescriptorEnvironmentForLocal(state.initial_iterator)) |env| {
                    try self.recordLocalDescriptorEnvironment(state.iterator_param, env.rep, env.bindings);
                }
                return .{ .child = .{ .iterator_loop_body = .{
                    .target = task.target,
                    .for_ = task.for_,
                    .plan_id = state.plan_id,
                    .plan = state.plan,
                    .step_ty = state.step_type,
                    .iterator_param = state.iterator_param,
                    .join_id = state.join_id,
                    .next = task.next,
                } } };
            },
            else => {
                const state = task.state.?;
                const loop = try self.parent.result.store.addCFStmt(.{ .join = .{
                    .id = state.join_id,
                    .params = try self.joinParamSpan(&[_]LIR.LocalId{state.iterator_param}),
                    .body = input.?,
                    .remainder = state.initial_jump,
                } }, self.glueOrigin());
                task.state = null;
                self.freeIteratorForState(state);
                return exprDone(loop);
            },
        }
    }

    /// One pass of a `for` loop: step the iterator, then branch on the step.
    /// The branch taking an item runs the source body before jumping back.
    fn stepIteratorLoopBody(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        if (stage == 0) {
            const step = try self.iteratorStepShapeForTypeRef(task.step_ty);
            task.step = step;
            const step_rep = self.repForTypeRef(task.step_ty);
            task.step_local = try self.addFrameLocalForRepWithFreshDescriptor(step_rep);
            const tag_rep = self.tagVariantRepForBoundary(step_rep) orelse
                boxyLowerInvariant("iterator step type had no tag representation");
            task.dynamic = self.parent.plan.representations.items[@backingInt(tag_rep)].kind == .dynamic;
            if (!task.dynamic) {
                task.done_variant = self.tagVariantForTypeRef(step.step_ty, step.done_tag);
                task.one_variant = self.tagVariantForTypeRef(step.step_ty, step.one_tag);
                task.skip_variant = self.tagVariantForTypeRef(step.step_ty, step.skip_tag);
            }
            task.done_body = try self.assignZst(task.target, task.next);
            return .{ .child = .{ .iterator_one_branch = .{
                .for_ = task.for_,
                .step = step,
                .step_local = task.step_local,
                .variant_index = if (task.dynamic) null else task.one_variant.index,
                .iterator_param = task.iterator_param,
                .join_id = task.join_id,
                .next = undefined,
            } } };
        }
        if (stage == 1) {
            const one_body = input.?;
            const step = task.step;
            const step_local = task.step_local;
            const step_rep = self.repForTypeRef(task.step_ty);
            if (task.dynamic) {
                const skip_body = try self.lowerIteratorSkipBranch(step, step_local, null, task.iterator_param, task.join_id);
                const source_desc = try self.descriptorRefForSourceLocalRep(step_local, step_rep);
                const impossible = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin());
                const skip_match = try self.parent.result.store.addCFStmt(.{ .boxy_tag_match = .{
                    .source = step_local,
                    .source_desc = source_desc,
                    .tag_name = try self.parent.result.store.insertBoxyName(step.module.canonical_names.tagLabelText(step.skip_tag)),
                    .on_match = skip_body,
                    .on_miss = impossible,
                } }, self.glueOrigin());
                const one_match = try self.parent.result.store.addCFStmt(.{ .boxy_tag_match = .{
                    .source = step_local,
                    .source_desc = source_desc,
                    .tag_name = try self.parent.result.store.insertBoxyName(step.module.canonical_names.tagLabelText(step.one_tag)),
                    .on_match = one_body,
                    .on_miss = skip_match,
                } }, self.glueOrigin());
                const done_match = try self.parent.result.store.addCFStmt(.{ .boxy_tag_match = .{
                    .source = step_local,
                    .source_desc = source_desc,
                    .tag_name = try self.parent.result.store.insertBoxyName(step.module.canonical_names.tagLabelText(step.done_tag)),
                    .on_match = task.done_body,
                    .on_miss = one_match,
                } }, self.glueOrigin());
                return .{ .tail = .{ .iter_dispatch = .{
                    .target = step_local,
                    .plan_id = task.plan_id,
                    .kind = .next,
                    .plan = task.plan,
                    .call = task.plan.next,
                    .loop_iterator = task.iterator_param,
                    .next = done_match,
                } } };
            }

            const skip_body = try self.lowerIteratorSkipBranch(step, step_local, task.skip_variant.index, task.iterator_param, task.join_id);

            const discriminant = try self.addFrameLocal(.u32);
            const branches = [_]LIR.CFSwitchBranch{
                .{ .value = task.done_variant.index, .body = task.done_body },
                .{ .value = task.one_variant.index, .body = one_body },
                .{ .value = task.skip_variant.index, .body = skip_body },
            };
            const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
                .cond = discriminant,
                .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
                .default_branch = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin()),
                .continuation = null,
            } }, self.glueOrigin());
            const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = discriminant,
                .op = .{ .discriminant = .{ .source = step_local } },
                .next = switch_stmt,
            } }, self.glueOrigin());
            return .{ .tail = .{ .iter_dispatch = .{
                .target = step_local,
                .plan_id = task.plan_id,
                .kind = .next,
                .plan = task.plan,
                .call = task.plan.next,
                .loop_iterator = task.iterator_param,
                .next = read_discriminant,
            } } };
        }
        unreachable;
    }

    /// The step branch taking an item: bind the item's pattern and run the
    /// source body, then jump back with the rest of the iterator.
    fn stepIteratorOneBranch(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        const step = task.step;
        if (stage == 0) {
            const payload_rep = self.repForTypeRef(step.one_payload_ty);
            task.payload = try self.addFrameLocalForRepWithFreshDescriptor(payload_rep);
            task.payload_desc = try self.ensureTagPayloadTargetDescriptorLocal(task.payload, payload_rep);
            task.item = try self.addFrameLocalForRepWithFreshDescriptor(self.repForTypeRef(.{ .module = step.one_payload_ty.module, .ty = step.one_item.ty }));
            task.rest = try self.addFrameLocalForRepWithFreshDescriptor(self.repForTypeRef(.{ .module = step.one_payload_ty.module, .ty = step.one_rest.ty }));
            const body_result = try self.addLoopBodyResultLocal(task.for_.body);

            var continuation = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = task.join_id } }, self.glueOrigin());
            continuation = try self.setLocalInitializeJoinParam(task.iterator_param, task.rest, continuation);
            return .{ .child = .{ .expr = .{ .target = body_result, .expr_id = task.for_.body, .next = continuation } } };
        }
        if (stage == 1) {
            task.miss = if (try self.patternCanMiss(task.for_.pattern))
                PatternMiss{ .join_id = self.freshJoinPointId() }
            else
                null;
            return .{ .child = .{ .pattern = .{ .pattern = task.for_.pattern, .source = task.item, .mode = .{ .match = .{ .miss = task.miss, .remaps = &.{} } }, .next = input.? } } };
        }
        var continuation = input.?;
        if (task.miss) |miss_info| {
            continuation = try self.parent.result.store.addCFStmt(.{ .join = .{
                .id = miss_info.join_id,
                .params = LIR.LocalSpan.empty(),
                .body = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin()),
                .remainder = continuation,
            } }, self.glueOrigin());
        }

        continuation = try self.lowerRecordFieldFromLocalInto(task.rest, self.repForTypeRef(.{ .module = step.one_payload_ty.module, .ty = step.one_rest.ty }), task.payload, self.repForTypeRef(step.one_payload_ty), step.module, step.one_rest.name, continuation);
        continuation = try self.lowerRecordFieldFromLocalInto(task.item, self.repForTypeRef(.{ .module = step.one_payload_ty.module, .ty = step.one_item.ty }), task.payload, self.repForTypeRef(step.one_payload_ty), step.module, step.one_item.name, continuation);
        return exprDone(try self.readTagPayloadStructInto(task.payload, self.repForTypeRef(step.one_payload_ty), task.payload_desc, task.step_local, self.repForTypeRef(step.step_ty), step.one_tag, task.variant_index, continuation));
    }

    /// An iterator `iter` or `next` dispatch: its operands lower into the
    /// planned worker call's argument locals, under descriptor bindings
    /// restored once the call is done.
    fn stepIteratorDispatch(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        if (stage != 0) {
            const snapshot = task.snapshot.?;
            task.snapshot = null;
            self.restoreDescriptorBindings(snapshot);
            snapshot.deinit(self.parent.allocator);
            return exprDone(input.?);
        }
        task.snapshot = try self.snapshotDescriptorBindings();
        const call = task.call;

        switch (call.resolution) {
            .direct_closed, .direct_parametric => {},
            .direct_pending => boxyLowerInvariant("unfinalized iterator call reached Boxy lowering"),
            .evidence_dependent => return .{ .child = (try self.unresolvedIteratorDispatchStep(task.target, task.plan, task.kind, call, task.loop_iterator, task.next)).tail },
            .structural => boxyLowerInvariant("structural iterator dispatch reached boxy lowering"),
            .checked_error => return .{ .child = .{ .chain = .{ .items = try self.parent.allocator.alloc(ExprChainItem, 0), .current = try self.lowerCheckedErrorDispatchInto("method dispatch failed to check") } } },
            .@"unreachable" => return .{ .child = .{ .chain = .{ .items = try self.parent.allocator.alloc(ExprChainItem, 0), .current = try self.lowerUnexecutableDispatchInto("dispatch on a value that can never exist") } } },
        }

        const call_plan = self.parent.plan.iteratorCallPlanFor(self.module.key, task.plan_id, task.kind, self.worker_layout.worker) orelse
            boxyLowerInvariant("checked iterator dispatch call reached boxy lowering without a planned worker");
        const substitutions = self.parent.plan.callTypeSubstitutionSlice(call_plan.arg_substitutions);
        const operands = call.argsSlice(self.module.static_dispatch_plans);
        if (substitutions.len != operands.len) {
            boxyLowerInvariant("checked iterator dispatch call substitution count disagreed with operands");
        }
        const operand_types = try self.parent.allocator.alloc(Plan.CheckedTypeIdentity, substitutions.len);
        defer self.parent.allocator.free(operand_types);
        const call_types = try self.parent.allocator.alloc(Plan.CheckedTypeIdentity, substitutions.len);
        defer self.parent.allocator.free(call_types);
        for (substitutions, operand_types, call_types) |substitution, *operand_type, *call_type| {
            operand_type.* = substitution.operand_type;
            call_type.* = substitution.call_type;
        }

        const arg_locals = try self.parent.allocator.alloc(LIR.LocalId, operands.len);
        defer self.parent.allocator.free(arg_locals);
        const operand_locals = try self.parent.allocator.alloc(?LIR.LocalId, operands.len);
        defer self.parent.allocator.free(operand_locals);
        for (operands, arg_locals, operand_locals, operand_types, call_types, substitutions) |operand, *local, *operand_local, operand_type, call_type, substitution| {
            if (self.repForTypeRef(operand_type) != substitution.operand_rep or
                self.repForTypeRef(call_type) != substitution.call_rep)
            {
                boxyLowerInvariant("iterator dispatch argument type disagreed with its planned substitution");
            }
            local.* = switch (operand) {
                .checked_expr => blk: {
                    operand_local.* = null;
                    break :blk try self.addFrameBoundaryTargetLocalForRep(substitution.call_rep);
                },
                .loop_iterator_state => blk: {
                    const iterator = task.loop_iterator orelse
                        boxyLowerInvariant("iterator next dispatch reached boxy lowering without loop iterator state");
                    if (self.parent.result.store.getLocal(iterator).layout_idx != self.workerRuntimeLayoutForTypeRef(operand_type).layoutIdx()) {
                        boxyLowerInvariant("iterator next dispatch loop state layout disagreed with iterator plan");
                    }
                    if (self.workerRuntimeLayoutForRep(substitution.operand_rep).layoutIdx() ==
                        self.workerRuntimeLayoutForRep(substitution.call_rep).layoutIdx() and
                        self.representationBoundaryIsDirect(substitution.call_rep, substitution.operand_rep))
                    {
                        operand_local.* = null;
                        break :blk iterator;
                    }
                    operand_local.* = iterator;
                    break :blk try self.addFrameBoundaryTargetLocalForRep(substitution.call_rep);
                },
            };
        }

        const hidden_desc_args = self.parent.plan.directCallHiddenDescriptorArgSlice(call_plan.hidden_desc_args);
        const hidden_dict_args = self.parent.plan.directCallHiddenDictionaryArgSlice(call_plan.hidden_dict_args);

        for (operand_locals, arg_locals, substitutions) |maybe_operand, arg_local, substitution| {
            if (maybe_operand) |operand_local| {
                try self.propagateLocalDescriptorEnvironmentToField(arg_local, substitution.call_rep, operand_local);
            }
        }

        const continuation = try self.lowerWorkerCallLocalsInto(
            task.target,
            call_plan.ret_type,
            operand_types,
            call_types,
            arg_locals,
            null,
            substitutions,
            call_plan.ret_substitution,
            call_plan.worker,
            hidden_desc_args,
            hidden_dict_args,
            task.next,
        );
        var chain_items = std.ArrayList(ExprChainItem).empty;
        errdefer chain_items.deinit(self.parent.allocator);
        var index = operands.len;
        while (index > 0) {
            index -= 1;
            switch (operands[index]) {
                .checked_expr => |expr| try chain_items.append(self.parent.allocator, .{ .lower = .{ .expected_ref = .{ .target = arg_locals[index], .expected_ty = call_types[index], .expr_id = expr, .next = undefined } } }),
                .loop_iterator_state => if (operand_locals[index]) |operand_local| {
                    try chain_items.append(self.parent.allocator, .{ .boundary_assign = .{
                        .target = arg_locals[index],
                        .source = operand_local,
                        .target_rep = substitutions[index].call_rep,
                        .source_rep = substitutions[index].operand_rep,
                    } });
                },
            }
        }
        return .{ .child = .{ .chain = .{ .items = try chain_items.toOwnedSlice(self.parent.allocator), .current = continuation } } };
    }

    /// A planned worker call lowers its operands onto a placeholder, then
    /// builds the call they feed and moves it into the placeholder, under
    /// descriptor bindings restored when the call is done.
    fn stepPlannedWorkerCall(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        const direct_plan = task.direct_plan;
        const operands = self.parent.plan.callOperandSlice(direct_plan.operands);
        const substitutions = self.parent.plan.callTypeSubstitutionSlice(direct_plan.arg_substitutions);
        const ret_substitution = direct_plan.ret_substitution orelse
            boxyLowerInvariant("boxy direct call reached lowering without a planned return substitution");
        if (stage == 0) {
            const allocator = self.parent.allocator;
            const state = try allocator.create(PlannedCallState);
            state.* = .{
                .descriptor_snapshot = self.snapshotDescriptorBindings() catch |err| {
                    allocator.destroy(state);
                    return err;
                },
                .operand_types = &.{},
                .call_types = &.{},
                .storage_arg_reps = &.{},
                .actual_arg_reps = &.{},
                .lowered = &.{},
                .call_result_target = undefined,
                .continuation = undefined,
                .call_placeholder = undefined,
            };
            task.state = state;

            if (substitutions.len != operands.len) {
                boxyLowerInvariant("boxy direct call planned substitution count disagreed with call args");
            }
            state.operand_types = try allocator.alloc(Plan.CheckedTypeIdentity, substitutions.len);
            state.call_types = try allocator.alloc(Plan.CheckedTypeIdentity, substitutions.len);
            state.storage_arg_reps = try allocator.alloc(Plan.TypeRepId, substitutions.len);
            state.actual_arg_reps = try allocator.alloc(Plan.TypeRepId, substitutions.len);
            for (substitutions, operands, state.operand_types, state.call_types, state.storage_arg_reps, state.actual_arg_reps) |substitution, operand, *operand_type, *call_type, *storage_arg_rep, *actual_arg_rep| {
                operand_type.* = substitution.operand_type;
                if (self.repForTypeRef(operand_type.*) != substitution.operand_rep) {
                    boxyLowerInvariant("boxy direct call operand representation disagreed with its planned substitution");
                }
                call_type.* = substitution.call_type;
                storage_arg_rep.* = try self.directCallOperandStorageRep(operand, substitution.operand_rep);
                actual_arg_rep.* = if (storage_arg_rep.* == substitution.operand_rep)
                    substitution.call_rep
                else
                    storage_arg_rep.*;
            }

            state.lowered = try self.lowerCallOperandsExpectedToTemps(operands, state.operand_types, state.actual_arg_reps);

            state.continuation = task.next;
            state.call_result_target = if (task.target_rep == ret_substitution.call_rep) blk: {
                const expected_layout = self.workerRuntimeLayoutForRep(task.target_rep).layoutIdx();
                if (self.parent.result.store.getLocal(task.target).layout_idx != expected_layout) {
                    boxyLowerInvariant("boxy direct call target representation disagreed with its local layout");
                }
                break :blk task.target;
            } else blk: {
                const exact_target = try self.addFrameBoundaryTargetLocalForRep(ret_substitution.call_rep);
                state.continuation = try self.assignPlannedCallBoundary(
                    task.target,
                    exact_target,
                    task.target_rep,
                    ret_substitution.call_rep,
                    state.continuation,
                );
                break :blk exact_target;
            };

            state.call_placeholder = try self.parent.result.store.addCFStmt(.runtime_error, self.origin);
            return .{ .child = .{ .chain = .{
                .items = try self.callOperandChainItems(operands, state.operand_types, state.call_types, state.storage_arg_reps, state.lowered),
                .current = state.call_placeholder,
            } } };
        }

        const state = task.state.?;
        const operands_entry = input.?;
        const ret_type = Plan.CheckedTypeIdentity{ .module = self.module.key, .ty = task.checked_ret_ty };
        const hidden_desc_args = self.parent.plan.directCallHiddenDescriptorArgSlice(direct_plan.hidden_desc_args);
        const hidden_dict_args = self.parent.plan.directCallHiddenDictionaryArgSlice(direct_plan.hidden_dict_args);
        const call_entry = try self.lowerWorkerCallLocalsInto(
            state.call_result_target,
            ret_type,
            state.operand_types,
            state.call_types,
            state.lowered,
            state.actual_arg_reps,
            substitutions,
            ret_substitution,
            direct_plan.worker,
            hidden_desc_args,
            hidden_dict_args,
            state.continuation,
        );
        try self.parent.result.store.replaceCFStmt(state.call_placeholder, self.parent.result.store.getCFStmt(call_entry), self.parent.result.store.stmtOrigin(call_entry));
        for (self.parent.pending_direct_call_descriptor_abis.items) |*pending| {
            if (pending.provisional_call == call_entry) {
                pending.provisional_call = state.call_placeholder;
            }
        }
        self.parent.result.store.getCFStmtPtr(call_entry).* = .runtime_error;
        // Restoring the outer descriptor bindings forgets slots the operands
        // reserved; initialize them before the operands run.
        const entry = try self.prependStaticDescriptorMaterializationsForScopedSlots(&state.descriptor_snapshot, operands_entry);
        task.state = null;
        self.restoreDescriptorBindings(state.descriptor_snapshot);
        self.freePlannedCallState(state);
        return exprDone(entry);
    }

    /// The chain lowering call operands, from the last, each into its
    /// lowered local at its expected type.
    fn callOperandChainItems(
        self: *ProcBodyBuilder,
        operands: []const Plan.CallOperand,
        operand_types: []const Plan.CheckedTypeIdentity,
        arg_types: []const Plan.CheckedTypeIdentity,
        storage_arg_reps: []const Plan.TypeRepId,
        lowered: []const LIR.LocalId,
    ) Allocator.Error![]ExprChainItem {
        if (operands.len != lowered.len or operands.len != operand_types.len or operands.len != arg_types.len or operands.len != storage_arg_reps.len) {
            boxyLowerInvariant("boxy expected lowered expression locals disagreed with source expression count");
        }
        const items = try self.parent.allocator.alloc(ExprChainItem, operands.len);
        for (items, 0..) |*item, offset| {
            const index = operands.len - 1 - offset;
            item.* = .{ .call_operand = .{
                .operand = operands[index],
                .operand_type = operand_types[index],
                .arg_type = arg_types[index],
                .storage_arg_rep = storage_arg_reps[index],
                .lowered = lowered[index],
            } };
        }
        return items;
    }
    fn beginErasedCall(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        ret_ty: checked.CheckedTypeId,
        callee_expr: checked.CheckedExprId,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const callee_ty = self.module.checked_bodies.expr(callee_expr).ty;
        const callee_local = try self.addFrameLocalForType(callee_ty);
        const callee_function = self.functionChildrenForRep(self.repForType(callee_ty)) orelse
            boxyLowerInvariant("erased call callee expression did not have an erased callable representation");
        if (callee_function.arg_count != args.len) {
            boxyLowerInvariant("erased call argument count disagreed with callee function representation");
        }

        const callee_rep = self.parent.plan.representations.items[@backingInt(callee_function.rep)];
        const callee_children = self.parent.plan.childSlice(callee_rep.children);
        const callee_arg_children = callee_children[callee_function.args_start..][0..callee_function.arg_count];

        const source_args = try self.parent.allocator.alloc(LIR.LocalId, args.len);
        defer self.parent.allocator.free(source_args);
        const call_args = try self.parent.allocator.alloc(LIR.LocalId, args.len);
        defer self.parent.allocator.free(call_args);
        for (args, source_args, call_args, callee_arg_children) |arg_expr_id, *source_arg, *call_arg, callee_arg| {
            const target_rep = callee_arg.rep;
            const source_rep = self.repForType(self.module.checked_bodies.expr(arg_expr_id).ty);
            source_arg.* = if (self.parent.layoutIsBoxStorage(self.workerRuntimeLayoutForRep(source_rep).layoutIdx()))
                try self.addFrameLocalForRepWithFreshDescriptor(source_rep)
            else
                try self.addFrameLocalForRep(source_rep);
            const source_layout = self.parent.result.store.getLocal(source_arg.*).layout_idx;
            const target_layout = self.workerRuntimeLayoutForRep(target_rep).layoutIdx();
            call_arg.* = if (source_layout == target_layout and self.descriptorStorageRep(source_rep) == self.descriptorStorageRep(target_rep))
                source_arg.*
            else
                try self.addFrameBoundaryTargetLocalForRep(target_rep);
        }
        const target_rep = self.repForType(ret_ty);
        const callee_ret_rep = callee_function.ret;
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const callee_ret_layout = self.workerRuntimeLayoutForRep(callee_ret_rep).layoutIdx();
        const target_desc_is_shared = if (self.parent.result.store.getLocal(target).boxy_desc) |desc|
            if (desc.localOrNull()) |local| self.localIsDescriptorSlot(local) else false
        else
            false;

        var continuation = next;
        const call_target = if (!target_desc_is_shared and
            target_layout == callee_ret_layout and
            (self.erasedCallResultCanUseTarget(target_rep, callee_ret_rep) or
                self.callResultAdoptsCalleeDescriptor(target, target_rep)))
            target
        else blk: {
            const raw_ret = if (self.parent.result.store.getLocal(target).boxy_desc != null)
                try self.addFrameLocalForRepWithRequiredFreshDescriptor(callee_ret_rep)
            else
                try self.addFrameLocalForRepWithFreshDescriptor(callee_ret_rep);
            if (self.parent.result.store.getLocal(raw_ret).boxy_desc) |desc| {
                if (desc.localOrNull()) |local| {
                    if (!self.repIsOpenRecord(callee_ret_rep)) try self.recordDescriptorLocalTemplate(
                        local,
                        try self.descriptorMaterializationForExactRep(callee_ret_rep),
                    );
                }
            }
            continuation = try self.assignPlannedCallBoundary(target, raw_ret, target_rep, callee_ret_rep, continuation);
            break :blk raw_ret;
        };

        const out_desc = self.callResultOutputDescriptorLocal(call_target);
        if (out_desc) |local| {
            if (self.descriptorTemplateForLocal(local) == null and !self.repIsOpenRecord(callee_ret_rep)) {
                try self.recordDescriptorLocalTemplate(
                    local,
                    try self.descriptorMaterializationForExactRep(callee_ret_rep),
                );
            }
            try self.markDescriptorLocalBound(local);
        }

        var arg_desc_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer arg_desc_initializers.deinit(self.parent.allocator);
        const arg_descs = try self.erasedCallArgumentDescriptorRefs(
            callee_arg_children,
            call_args,
            &arg_desc_initializers,
        );
        const expected_result_desc = try self.erasedCallResultDescriptorRef(
            call_target,
            callee_ret_rep,
            out_desc,
        );
        try self.appendResultDescriptorInitializers(&arg_desc_initializers, expected_result_desc);

        continuation = try self.parent.result.store.addCFStmt(.{ .assign_call_erased = .{
            .target = call_target,
            .closure = callee_local,
            .args = try self.parent.result.store.addLocalSpan(call_args),
            .arg_layouts = try self.appendErasedArgumentLayouts(call_args),
            .arg_plan = try self.erasedCallArgsPlan(call_args),
            .arg_descs = arg_descs.locals,
            .arg_desc_keys = arg_descs.keys,
            .result_desc = expected_result_desc.desc,
            .out_desc = out_desc,
            .reuse_closure = false,
            .reuse_source = null,
            .next = continuation,
        } }, self.origin);
        continuation = try self.prependDescriptorArgMaterializations(arg_desc_initializers.items, continuation);

        var index = args.len;
        while (index > 0) {
            index -= 1;
            if (call_args[index] == source_args[index]) continue;
            const arg_expr = self.module.checked_bodies.expr(args[index]);
            continuation = try self.assignRepresentationBoundary(
                call_args[index],
                source_args[index],
                callee_arg_children[index].rep,
                self.repForType(arg_expr.ty),
                continuation,
            );
        }
        // Walking backwards: the arguments from the last, then the callee.
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, args.len + 1);
        for (0..args.len) |offset| {
            const arg_index = args.len - 1 - offset;
            chain_items[offset] = .{ .lower = .{ .expr = .{ .target = source_args[arg_index], .expr_id = args[arg_index], .next = undefined } } };
        }
        chain_items[args.len] = .{ .lower = .{ .expr = .{ .target = callee_local, .expr_id = callee_expr, .next = undefined } } };
        return exprChain(chain_items, continuation);
    }

    fn beginLowLevel(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_ty: checked.CheckedTypeId,
        op: can.CIR.Expr.LowLevel,
