        ty: checked.CheckedTypeId,
        interpolation: checked.CheckedInterpolation,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const assembler_fn = checkedFunctionPayload(self.module, interpolation.assembler_ty);
        if (assembler_fn.args.len != 1) boxyLowerInvariant("interpolation assembler did not take exactly the values list");
        const assembler_rep = self.repForType(interpolation.assembler_ty);
        const assembler = try self.addFrameLocalForRepWithFreshDescriptor(assembler_rep);
        const values_ty = assembler_fn.args[0];
        const values_rep = self.repForType(values_ty);
        const values = try self.addFrameLocalForRepWithFreshDescriptor(values_rep);
        const call = try self.lowerErasedCallLocalsInto(target, self.repForType(ty), assembler_rep, assembler, &.{values}, &.{values_rep}, next);
        const convert = if (try self.lowerPlannedLiteralInto(assembler, expr_id, interpolation.assembler_ty, call)) |body|
            body
        else
            try self.lowerRuntimeStringConversionInto(assembler, expr_id, interpolation.assembler_ty, interpolation.plan, "invalid string interpolation", call);
        return try self.beginList(values, values_ty, interpolation.values, convert);
    }

    /// An interpolation's literal segments, as the `List(Str)` its conversion
    /// receives.
    fn assignInterpolationSegmentsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const interpolation = switch (self.module.checked_bodies.expr(expr_id).data) {
            .interpolation => |value| value,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyLowerInvariant("interpolation segments operand referenced a non-interpolation expression"),
        };
        const elem_layout = self.localListElemLayout(target);
        const elem_locals = try self.parent.allocator.alloc(LIR.LocalId, interpolation.segments.len);
        defer self.parent.allocator.free(elem_locals);
        for (elem_locals) |*local| local.* = try self.addFrameLocal(elem_layout);
        const target_desc_info = try self.stableDescriptorForConstructedValue(target, target_rep);
        if (target_desc_info.desc) |desc| self.parent.result.store.setLocalBoxyDesc(target, desc);
        var continuation = try self.assignList(target, elem_locals, next);
        continuation = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, continuation);
        var index = interpolation.segments.len;
        while (index > 0) {
            index -= 1;
            const literal = switch (self.module.checked_bodies.expr(interpolation.segments[index]).data) {
                .str_segment => |literal| literal,
                .pending, .numeral, .str_from_quote, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyLowerInvariant("interpolation segment was not a checked string segment"),
            };
            continuation = try self.assignStringLiteral(elem_locals[index], literal, continuation);
        }
        return continuation;
    }

    fn lowerLiteralConversionResultInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        invalid_message: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.literal_initializer) |index| {
            const initializer = self.parent.plan.literal_evidence.?.initializers.items[index];
            const callable = self.functionChildrenForRep(initializer.callable_rep).?;
            if (source_rep != callable.ret) {
                // The result is read at the initializer's own result
                // representation.
                const concrete = try self.addFrameLocalForRep(callable.ret);
                const unwrap = try self.lowerLiteralConversionResultAtRepInto(target, target_rep, concrete, callable.ret, invalid_message, next);
                return try self.assignRepresentationBoundary(concrete, source, callable.ret, source_rep, unwrap);
            }
        }
        return try self.lowerLiteralConversionResultAtRepInto(target, target_rep, source, source_rep, invalid_message, next);
    }

    /// Unwrap a literal conversion's `Ok` result read at its own
    /// representation.
    fn lowerLiteralConversionResultAtRepInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        invalid_message: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const tag_rep_id = self.tagVariantRepForBoundary(source_rep) orelse
            boxyLowerInvariant("literal conversion result did not have a tag-union representation");
        const tag_rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
        var ok_variant: ?Plan.TagVariant = null;
        var ok_index: u32 = 0;
        for (self.parent.plan.tagVariantSlice(tag_rep.tag_variants), 0..) |variant, index| {
            if (!std.mem.eql(u8, self.tagVariantNameText(variant), "Ok")) continue;
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("literal conversion Ok variant index exceeded LIR range");
            }
            ok_variant = variant;
            ok_index = @intCast(index);
            break;
        }
        const ok = ok_variant orelse
            boxyLowerInvariant("literal conversion result had no Ok variant");
        const payloads = self.parent.plan.childSlice(ok.payloads);
        if (payloads.len != 1) {
            boxyLowerInvariant("literal conversion Ok variant did not have one payload");
        }

        const payload_rep = payloads[0].rep;
        const payload = try self.addExtractedTagPayloadLocal(payload_rep, tag_rep.descriptor != null);
        const moved = try self.assignRepresentationBoundary(
            target,
            payload.local,
            target_rep,
            payload_rep,
            next,
        );
        const read_ok = if (tag_rep.kind == .dynamic)
            try self.assignBoxyTagPayloadWithName(
                payload.local,
                payload.desc_local,
                source,
                source_rep,
                try self.parent.result.store.insertBoxyName("Ok"),
                0,
                moved,
            )
        else
            try self.assignConcreteTagPayloadRead(
                payload.local,
                payload_rep,
                payload.desc_local,
                source,
                tag_rep_id,
                ok.name,
                ok_index,
                0,
                1,
                moved,
            );
        const invalid = if (self.literal_initializer) |index|
            try self.lowerLiteralRejection(source, tag_rep_id, index)
        else
            try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(invalid_message) },
            } }, self.origin);

        if (tag_rep.kind == .dynamic) {
            return try self.parent.result.store.addCFStmt(.{ .boxy_tag_match = .{
                .source = source,
                .source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep),
                .tag_name = try self.parent.result.store.insertBoxyName("Ok"),
                .on_match = read_ok,
                .on_miss = invalid,
            } }, self.origin);
        }

        const discriminant = try self.addFrameLocal(.u32);
        const branches = [_]LIR.CFSwitchBranch{.{ .value = ok_index, .body = read_ok }};
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = invalid,
            .continuation = null,
        } }, self.origin);
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } }, self.origin);
    }

    /// A checked conversion's Err row has one Str payload per tag. Keep the
    /// selected message and literal identity in LIR before freezing a failure.
    fn lowerLiteralRejection(self: *ProcBodyBuilder, source: LIR.LocalId, try_rep: Plan.TypeRepId, initializer_index: u32) Allocator.Error!LIR.CFStmtId {
        const initializer = self.parent.plan.literal_evidence.?.initializers.items[initializer_index];
        const site = self.parent.plan.literal_sites.items[initializer.site];
        const owner = self.parent.result.loweringModuleId(site.source.module) orelse blk: {
            const id: LIR.LoweringModuleId = @fromBackingInt(@intCast(self.parent.result.lowering_modules.items.len));
            try self.parent.result.lowering_modules.append(self.parent.allocator, site.source.module);
            break :blk id;
        };
        const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(try_rep)].tag_variants);
        const err_index = for (variants, 0..) |variant, index| {
            if (std.mem.eql(u8, self.tagVariantNameText(variant), "Err")) break index;
        } else return try self.parent.result.store.addCFStmt(.runtime_error, self.origin);
        const err_variant = variants[err_index];
        const err_payloads = self.parent.plan.childSlice(err_variant.payloads);
        if (err_payloads.len != 1) boxyLowerInvariant("literal conversion Err did not carry one error row");
        const error_rep = self.tagVariantRepForBoundary(err_payloads[0].rep) orelse
            boxyLowerInvariant("literal conversion Err payload was not a tag row");
        const error_value = try self.addFrameLocalForRep(error_rep);
        const error_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(error_rep)].tag_variants);
        var branches = std.ArrayList(LIR.CFSwitchBranch).empty;
        defer branches.deinit(self.parent.allocator);
        for (error_variants, 0..) |variant, index| {
            const payloads = self.parent.plan.childSlice(variant.payloads);
            if (payloads.len != 1) boxyLowerInvariant("literal conversion error tag did not carry one message");
            const message = try self.addFrameLocalForRep(payloads[0].rep);
            const rejected = try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .local = message },
                .literal_rejection = .{
                    .owner = owner,
                    .checked_expr = @backingInt(site.source.expr),
                    .kind = switch (self.module.checked_bodies.expr(site.source.expr).data) {
                        .numeral => .numeral,
                        .str_from_quote => .quote,
                        .interpolation => .interpolation,
                        .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyLowerInvariant("literal rejection site did not name a checked literal conversion"),
                    },
                },
            } }, self.origin);
            const read_message = try self.assignConcreteTagPayloadRead(message, payloads[0].rep, null, error_value, error_rep, variant.name, @intCast(index), 0, 1, rejected);
            try branches.append(self.parent.allocator, .{ .value = @intCast(index), .body = read_message });
        }
        const impossible = try self.parent.result.store.addCFStmt(.runtime_error, self.origin);
        const discriminant = try self.addFrameLocal(.u32);
        const select = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches.items),
            .default_branch = impossible,
            .continuation = null,
        } }, self.origin);
        const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = error_value } },
            .next = select,
        } }, self.origin);
        return try self.assignConcreteTagPayloadRead(error_value, error_rep, null, source, try_rep, err_variant.name, @intCast(err_index), 0, 1, read_discriminant);
    }

    fn beginNumeralConversion(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        checked_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (try self.lowerPlannedLiteralInto(target, expr_id, checked_ty, next)) |body| return exprDone(body);
        const root = self.module.compile_time_roots.root(self.module.checked_bodies.literalConversionRoot(expr_id) orelse
            return exprDone(try self.lowerNumFromNumeralInto(target, maybe_plan, next)));
        return switch (root.payload) {
            .const_node => |node| .{ .tail = .{ .const_node = .{
                .target = target,
                .store_module = self.module,
                .type_module = self.module,
                .node = node,
                .checked_ty = checked_ty,
                .next = next,
            } } },
            .pending => try self.beginRuntimeStringConversion(target, expr_id, checked_ty, maybe_plan, "invalid numeric literal", next),
            .fn_value,
            .discarded,
            .expect,
            .runtime,
            => boxyLowerInvariant("from_numeral conversion root had a non-data payload"),
        };
    }

    fn lowerPendingNumeralConversionInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        target_ty: checked.CheckedTypeId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.runExprStep(try self.beginRuntimeStringConversion(target, expr_id, target_ty, maybe_plan, "invalid numeric literal", next));
    }

    fn exprStorageRep(
        self: *ProcBodyBuilder,
        expr: checked.CheckedExpr,
        default_rep: Plan.TypeRepId,
    ) Plan.TypeRepId {
        const maybe_binder = switch (expr.data) {
            .lookup_local => |lookup| if (lookup.resolved) |ref_id|
                self.resolvedLookupBinder(ref_id)
            else blk: {
                const pattern_index = @backingInt(lookup.pattern);
                if (pattern_index >= self.module.checked_bodies.pattern_binder_by_pattern.len) {
                    boxyLowerInvariant("boxy local lookup referenced missing binder metadata");
                }
                break :blk self.module.checked_bodies.pattern_binder_by_pattern[pattern_index];
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        };
        return if (maybe_binder) |binder| self.binderStorageRep(binder) else default_rep;
    }

    fn lowerExprStorageRepInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        storage_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const expr = self.module.checked_bodies.expr(expr_id);
        if (self.parent.result.store.getLocal(target).layout_idx != self.workerRuntimeLayoutForRep(storage_rep).layoutIdx()) {
            boxyLowerInvariant("boxy expression storage representation disagreed with target local layout");
        }

        const binder = switch (expr.data) {
            .lookup_local => |lookup| if (lookup.resolved) |ref_id|
                self.resolvedLookupBinder(ref_id)
            else blk: {
                const pattern_index = @backingInt(lookup.pattern);
                if (pattern_index >= self.module.checked_bodies.pattern_binder_by_pattern.len) {
                    boxyLowerInvariant("boxy local lookup referenced missing binder metadata");
                }
                break :blk self.module.checked_bodies.pattern_binder_by_pattern[pattern_index];
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        } orelse boxyLowerInvariant("boxy expression had explicit storage representation without a binder source");
        const binder_rep = self.binderStorageRep(binder);
        if (storage_rep != binder_rep) {
            boxyLowerInvariant("boxy expression storage representation disagreed with its binder representation");
        }
        return try self.assignTypedLocalFromRep(
            target,
            self.localForBinder(binder),
            storage_rep,
            binder_rep,
            next,
        );
    }

    fn resolvedLookupBinder(
        self: *ProcBodyBuilder,
        ref_id: checked.ResolvedValueRefId,
    ) ?checked.PatternBinderId {
        return switch (self.resolvedValueRecord(ref_id).ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            => |local| local.binder,
            .selected_hoisted_const => |selected| if (self.binderLocalOrNull(selected.local.binder) != null)
                selected.local.binder
            else
                null,
            .local_proc, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => null,
        };
    }

    fn ensureBoundaryTargetDescriptorForSourceRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        if (self.parent.result.store.getLocal(target).boxy_desc != null) return;

        const identity_rep = self.descriptorStorageRep(source_rep);
        const source = self.parent.plan.representations.items[@backingInt(source_rep)];
        const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (source.descriptor == null and identity.descriptor == null and
            !source.contains_dynamic and !identity.contains_dynamic)
        {
            return;
        }

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.parent.layoutNeedsNestedBoxyDesc(target_layout)) return;
        self.parent.result.store.setLocalBoxyDesc(target, .{ .local = try self.addFrameLocal(.opaque_ptr) });
    }

    fn propagateBoundaryDescriptorMetadata(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
    ) void {
        if (self.parent.result.store.getLocal(target).boxy_desc != null) return;
        if (self.parent.result.store.getLocal(source).boxy_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(target, desc);
        }
    }

    fn beginLookupLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        checked_ty: checked.CheckedTypeId,
        lookup: anytype,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (lookup.resolved) |ref_id| {
            return try self.beginResolvedLookup(target, expr_id, checked_ty, ref_id, next);
        }
        const binder = self.module.checked_bodies.pattern_binder_by_pattern[@backingInt(lookup.pattern)] orelse
            boxyLowerInvariant("boxy unresolved local lookup referenced a non-binding pattern");
        return exprDone(try self.assignTypedLocalFromRep(
            target,
            self.localForPattern(lookup.pattern),
            self.repForType(checked_ty),
            self.binderStorageRep(binder),
            next,
        ));
    }

    fn beginResolvedLookup(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        checked_ty: checked.CheckedTypeId,
        maybe_ref: ?checked.ResolvedValueRefId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const ref_id = maybe_ref orelse
            boxyLowerInvariant("checked lookup reached boxy lowering without a resolved value ref");
        const record = self.resolvedValueRecord(ref_id);
        return switch (record.ref) {
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            => |local| exprDone(try self.assignTypedLocalFromRep(
                target,
                self.localForBinder(local.binder),
                self.repForType(checked_ty),
                self.binderStorageRep(local.binder),
                next,
            )),
            .selected_hoisted_const => |selected| blk: {
                if (self.binderLocalOrNull(selected.local.binder)) |local| {
                    break :blk exprDone(try self.assignTypedLocalFromRep(
                        target,
                        local,
                        self.repForType(checked_ty),
                        self.binderStorageRep(selected.local.binder),
                        next,
                    ));
                }
                break :blk try self.beginRestoreConstUse(target, checked_ty, selected.const_use, next);
            },
            .top_level_const,
            .imported_const,
            => |const_use| try self.beginRestoreConstUse(target, checked_ty, const_use, next),
            .platform_required_const => |required| try self.beginRestoreConstUse(target, checked_ty, required.const_use, next),
            .platform_required_checked_error => exprDone(try self.lowerCheckedErrorDispatchInto("platform requirement failed checking")),
            .local_proc => try self.beginProcedureValueRef(target, expr_id, checked_ty, ref_id, next),
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => try self.beginProcedureValueRef(target, expr_id, checked_ty, ref_id, next),
            .platform_required_declaration => boxyLowerInvariant("unbound platform-required declaration reached boxy lookup lowering"),
        };
    }

    fn assignTypedLocalFromRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (target_layout == source_layout and self.descriptorStorageRep(target_rep) == self.descriptorStorageRep(source_rep)) {
            if (self.parent.result.store.getLocal(source).boxy_desc == null and self.repContainsDynamicStorage(source_rep)) {
                const desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
                self.parent.result.store.setLocalBoxyDesc(source, desc);
            }
            if (self.parent.result.store.getLocal(source).boxy_desc == null) {
                return try self.assignDescriptorAwareNominalBoundary(
                    target,
                    source,
                    target_rep,
                    source_rep,
                    .borrow,
                    next,
                );
            }
            return try self.assignLocal(target, source, next);
        }
        return try self.assignRepresentationBoundary(target, source, target_rep, source_rep, next);
    }

    fn staticDispatchPlan(
        self: *ProcBodyBuilder,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
    ) static_dispatch.StaticDispatchCallPlan {
        const plan_id = maybe_plan orelse
            boxyLowerInvariant("checked dispatch expression reached boxy lowering without a dispatch plan");
        const raw = @backingInt(plan_id);
        if (raw >= self.module.static_dispatch_plans.plans.len) {
            boxyLowerInvariant("checked dispatch expression referenced a missing dispatch plan");
        }
        return self.module.static_dispatch_plans.plans[raw];
    }

    fn generatedCodecCallPlan(
        self: *const ProcBodyBuilder,
        caller: Plan.WorkerPlanId,
        dispatch_type: Plan.CheckedTypeIdentity,
        method_text: []const u8,
        subject_type: ?Plan.CheckedTypeIdentity,
    ) Plan.GeneratedCodecCallPlan {
        return self.generatedCodecCallPlanOrNull(caller, dispatch_type, method_text, subject_type) orelse
            boxyLowerInvariant("generated codec body referenced an unplanned method call");
    }

    fn generatedCodecCallPlanOrNull(
        self: *const ProcBodyBuilder,
        caller: Plan.WorkerPlanId,
        dispatch_type: Plan.CheckedTypeIdentity,
        method_text: []const u8,
        subject_type: ?Plan.CheckedTypeIdentity,
    ) ?Plan.GeneratedCodecCallPlan {
        for (self.parent.plan.generated_codec_calls.items) |*call| {
            if (call.caller != caller or !planTypeRefEql(call.dispatch_type, dispatch_type)) continue;
            if (!optionalPlanTypeRefEql(call.subject_type, subject_type)) continue;
            const method_module = procedureModuleById(self.parent.modules, call.method_module);
            if (std.mem.eql(u8, method_module.canonical_names.methodNameText(call.method), method_text)) return call.*;
        }
        return null;
    }

    fn generatedCodecCallPlanByIdentity(
        self: *const ProcBodyBuilder,
        caller: Plan.WorkerPlanId,
        dispatch_type: Plan.CheckedTypeIdentity,
        subject_type: Plan.CheckedTypeIdentity,
        method_module: checked.ModuleId,
        method: names.MethodNameId,
    ) Plan.GeneratedCodecCallPlan {
        for (self.parent.plan.generated_codec_calls.items) |*call| {
            if (call.caller != caller or !planTypeRefEql(call.dispatch_type, dispatch_type)) continue;
            if (!optionalPlanTypeRefEql(call.subject_type, subject_type)) continue;
            if (checked_moduleKeyEqual(call.method_module, method_module) and call.method == method) return call.*;
        }
        boxyLowerInvariant("generated codec body referenced an unplanned exact method call");
    }

    fn generatedCodecCallPlanForMethod(
        self: *const ProcBodyBuilder,
        caller: Plan.WorkerPlanId,
        dispatch_type: Plan.CheckedTypeIdentity,
        method_text: []const u8,
    ) Plan.GeneratedCodecCallPlan {
        var found: ?Plan.GeneratedCodecCallPlan = null;
        for (self.parent.plan.generated_codec_calls.items) |*call| {
            if (call.caller != caller or !planTypeRefEql(call.dispatch_type, dispatch_type)) continue;
            const method_module = procedureModuleById(self.parent.modules, call.method_module);
            if (!std.mem.eql(u8, method_module.canonical_names.methodNameText(call.method), method_text)) continue;
            if (found != null) boxyLowerInvariant("generated codec body referenced an ambiguously planned method call");
            found = call.*;
        }
        return found orelse boxyLowerInvariant("generated codec body referenced an unplanned method call");
    }

    const PresenceSlotVariants = struct {
        present: ProcedureBuilder.GeneratedParserTagVariant,
        missing: ProcedureBuilder.GeneratedParserTagVariant,
    };

    /// The Present and Missing variants of a record field's presence slot,
    /// selected by the slot's explicit Present discriminant.
    fn presenceSlotVariants(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?PresenceSlotVariants {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const present: u32 = rep.presence_slot_present_discriminant orelse return null;
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        if (variants.len != 2 or present >= variants.len) {
            boxyLowerInvariant("presence slot did not have exactly two variants");
        }
        const missing: u32 = if (present == 0) 1 else 0;
        if (variants[missing].payloads.len != 0) boxyLowerInvariant("presence slot Missing variant carried a payload");
        return .{
            .present = .{ .boundary_rep = rep_id, .tag_rep = rep_id, .owner_rep = rep_id, .index = present, .variant = variants[present] },
            .missing = .{ .boundary_rep = rep_id, .tag_rep = rep_id, .owner_rep = rep_id, .index = missing, .variant = variants[missing] },
        };
    }

    fn generatedParserTagVariant(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        tag_text: []const u8,
    ) ProcedureBuilder.GeneratedParserTagVariant {
        const root_rep = self.tagVariantRepForBoundary(rep_id) orelse
            boxyLowerInvariant("generated parser expected a closed tag-union representation");
        var current = root_rep;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            for (self.parent.plan.tagVariantSlice(rep.tag_variants), 0..) |variant, index| {
                if (!std.mem.eql(u8, self.tagVariantNameText(variant), tag_text)) continue;
                if (index > std.math.maxInt(u32)) boxyLowerInvariant("generated parser tag index exceeded LIR range");
                return .{
                    .boundary_rep = rep_id,
                    .tag_rep = root_rep,
                    .owner_rep = current,
                    .index = @intCast(index),
                    .variant = variant,
                };
            }

            var extension: ?Plan.TypeRepId = null;
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                if (extension != null) boxyLowerInvariant("generated parser tag row had duplicate extension children");
                extension = self.tagVariantRepForBoundary(child.rep);
            }
            const next_rep = extension orelse break;
            if (next_rep == current) boxyLowerInvariant("generated parser tag row extension was cyclic");
            current = next_rep;
        }
        boxyLowerInvariant("generated parser result type was missing a required tag");
    }

    fn generatedParserTagDispatch(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        variants: []const ProcedureBuilder.GeneratedParserTagVariant,
        bodies: []const LIR.CFStmtId,
        default_branch: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (variants.len != bodies.len or variants.len == 0) {
            boxyLowerInvariant("generated parser tag dispatch had invalid branch metadata");
        }

        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse
            boxyLowerInvariant("generated parser dispatch source had no tag representation");
        return switch (self.workerRuntimeLayoutForRep(source_tag_rep)) {
            .concrete => blk: {
                const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
                defer self.parent.allocator.free(branches);
                const variant_count = self.parent.plan.representations.items[@backingInt(source_tag_rep)].tag_variants.len;
                const dispatched = try self.parent.allocator.alloc(bool, variant_count);
                defer self.parent.allocator.free(dispatched);
                @memset(dispatched, false);
                for (variants, bodies, branches) |variant, body, *branch| {
                    if (variant.tag_rep != source_tag_rep or variant.owner_rep != source_tag_rep) {
                        boxyLowerInvariant("generated parser concrete dispatch referenced a nonlocal row variant");
                    }
                    if (variant.index >= variant_count or dispatched[variant.index]) {
                        boxyLowerInvariant("generated parser concrete dispatch repeated or exceeded its union's variants");
                    }
                    dispatched[variant.index] = true;
                    branch.* = .{ .value = variant.index, .body = body };
                }
                // A dispatch over every variant of the union cannot miss, so
                // its last variant is the default rather than an impossible
                // branch.
                const exhaustive = variants.len == variant_count;
                const switch_branches = if (exhaustive) branches[0 .. branches.len - 1] else branches;
                const discriminant = try self.addFrameLocal(.u32);
                const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
                    .cond = discriminant,
                    .branches = try self.parent.result.store.addCFSwitchBranches(switch_branches),
                    .default_branch = if (exhaustive) branches[branches.len - 1].body else default_branch,
                    .continuation = null,
                } }, self.derivedOrigin());
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = discriminant,
                    .op = .{ .discriminant = .{ .source = source } },
                    .next = switch_stmt,
                } }, self.derivedOrigin());
            },
            .dynamic_box => blk: {
                const source_desc = try self.descriptorRefForLocalOrKnownRep(source, source_rep);
                var dispatch = default_branch;
                var index = variants.len;
                while (index > 0) {
                    index -= 1;
                    dispatch = try self.parent.result.store.addCFStmt(.{ .boxy_tag_match = .{
                        .source = source,
                        .source_desc = source_desc,
                        .tag_name = try self.lirTagNameForVariant(variants[index].variant),
                        .on_match = bodies[index],
                        .on_miss = dispatch,
                    } }, self.derivedOrigin());
                }
                break :blk dispatch;
            },
        };
    }

    const GeneratedParserTagPayload = struct {
        /// The payload at its actual representation (`child.rep`).
        local: LIR.LocalId,
        /// The payload as stored by the tag, at the declared payload
        /// representation `stored_rep`; the same local as `local` unless the
        /// variant belongs to a nominal whose declared payload is a formal.
        stored: LIR.LocalId,
        stored_rep: Plan.TypeRepId,
        desc_local: ?LIR.LocalId,
        child: Plan.RepChild,
    };

    fn generatedParserSingleTagPayloadLocal(
        self: *ProcBodyBuilder,
        variant: ProcedureBuilder.GeneratedParserTagVariant,
    ) Allocator.Error!GeneratedParserTagPayload {
        const payloads = self.parent.plan.childSlice(variant.variant.payloads);
        if (payloads.len != 1) boxyLowerInvariant("generated parser tag did not have one payload");
        const tag_rep = self.parent.plan.representations.items[@backingInt(variant.tag_rep)];
        const actual_rep = self.nominalBackingActualRep(variant.boundary_rep, payloads[0].rep);
        var child = payloads[0];
        child.rep = actual_rep;
        child.source_type = self.parent.plan.representations.items[@backingInt(actual_rep)].source_type;
        // A tag union is laid out from its declared payload representations,
        // which for a nominal such as `Try` are the declaration's formals; the
        // payload is read at that storage representation and then converted.
        const stored_rep = payloads[0].rep;
        const extracted = try self.addExtractedTagPayloadLocal(stored_rep, tag_rep.descriptor != null);
        return .{
            .local = if (actual_rep == stored_rep) extracted.local else try self.addFrameLocalForRep(actual_rep),
            .stored = extracted.local,
            .stored_rep = stored_rep,
            .desc_local = extracted.desc_local,
            .child = child,
        };
    }

    fn generatedParserReadTagPayload(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        variant: ProcedureBuilder.GeneratedParserTagVariant,
        payload: GeneratedParserTagPayload,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const converted = if (payload.local == payload.stored)
            next
        else
            try self.assignRepresentationBoundary(payload.local, payload.stored, payload.child.rep, payload.stored_rep, next);
        return try self.readGeneratedParserStoredTagPayload(source, variant, payload, converted);
    }

    /// Read the payload as the tag stores it, then continue with `next`.
    fn readGeneratedParserStoredTagPayload(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        variant: ProcedureBuilder.GeneratedParserTagVariant,
        payload: GeneratedParserTagPayload,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignConcreteTagPayloadRead(
            payload.stored,
            payload.stored_rep,
            payload.desc_local,
            source,
            variant.tag_rep,
            variant.variant.name,
            variant.index,
            0,
            1,
            next,
        );
    }

    fn forwardGeneratedParserError(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
        source_err: ProcedureBuilder.GeneratedParserTagVariant,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_payload = try self.generatedParserSingleTagPayloadLocal(source_err);
        // A method whose error row is empty has no error value, so its Err
        // arm never runs and contributes nothing to the parent row.
        if (self.repIsEmptyTagUnion(source_payload.child.rep)) {
            return try self.parent.result.store.addCFStmt(.runtime_error, self.origin);
        }
        const target_err = self.generatedParserTagVariant(target_rep, "Err");
        const target_payloads = self.parent.plan.childSlice(target_err.variant.payloads);
        if (target_payloads.len != 1) boxyLowerInvariant("generated parser result Err did not have one payload");
        const error_rep = self.nominalBackingActualRep(target_rep, target_payloads[0].rep);
        // Store the error at the result's exact row representation, so the
        // payload bytes and the callable's result descriptor agree.
        const error_value = if (error_rep == source_payload.child.rep)
            source_payload.local
        else
            try self.addFrameLocalForRep(error_rep);
        var continuation = try self.assignGeneratedParserTag(target, target_rep, target_err, error_value, error_rep, next);
        if (error_value != source_payload.local) {
            continuation = try self.assignRepresentationBoundary(error_value, source_payload.local, error_rep, source_payload.child.rep, continuation);
        }
        return try self.generatedParserReadTagPayload(source, source_err, source_payload, continuation);
    }

    fn generatedParserRecordFieldType(
        self: *const ProcBodyBuilder,
        record_type: Plan.CheckedTypeIdentity,
        field_text: []const u8,
    ) Allocator.Error!Plan.CheckedTypeIdentity {
        const view = procedureModuleById(self.parent.modules, record_type.module);
        const field = checkedRecordFieldByName(view, record_type.ty, field_text);
        return .{ .module = record_type.module, .ty = field.ty };
    }

    fn generatedRecordFieldChild(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        field_text: []const u8,
    ) Plan.RepChild {
        var current = self.recordRepForBoundary(rep_id) orelse
            boxyLowerInvariant("generated record field lookup did not receive a record representation");
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            const view = procedureModuleById(self.parent.modules, rep.source_type.module);
            var extension: ?Plan.TypeRepId = null;
            for (self.parent.plan.childSlice(rep.children)) |child| {
                switch (child.role) {
                    .record_field => |name| {
                        if (std.mem.eql(u8, view.canonical_names.recordFieldLabelText(name), field_text)) return child;
                    },
                    .record_ext => {
                        if (extension != null) boxyLowerInvariant("generated record field lookup found duplicate row extensions");
                        extension = self.recordRepForBoundary(child.rep);
                    },
                    .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("generated record field lookup found a non-record child"),
                }
            }
            const next = extension orelse
                boxyLowerInvariant("generated record type was missing a required field");
            if (next == current) boxyLowerInvariant("generated record field lookup found a cyclic row extension");
            current = next;
        }
    }

    fn assignGeneratedIteratorLength(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        mode: Plan.GeneratedFieldIteratorMode,
        known_remaining: ?LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (mode) {
            .all => blk: {
                const known = self.generatedParserTagVariant(target_rep, "Known");
                const payloads = self.parent.plan.childSlice(known.variant.payloads);
                if (payloads.len != 1) boxyLowerInvariant("Iter Known length tag did not have one payload");
                const length = try self.addFrameLocalForRep(payloads[0].rep);
                var continuation = try self.assignGeneratedParserTag(
                    target,
                    target_rep,
                    known,
                    length,
                    payloads[0].rep,
                    next,
                );
                continuation = try self.assignLocalRef(
                    length,
                    known_remaining orelse boxyLowerInvariant("known iterator length had no explicit value"),
                    continuation,
                );
                break :blk continuation;
            },
            .for_size => {
                if (known_remaining != null) boxyLowerInvariant("size-filtered iterator unexpectedly had a known length");
                const unknown = self.generatedParserTagVariant(target_rep, "Unknown");
                return try self.assignGeneratedParserZeroTag(target, target_rep, unknown, next);
            },
        };
    }

    fn lowerGeneratedFieldNameNameInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.arg_locals.items.len < 1) {
            boxyLowerInvariant("FieldName.name intrinsic had no explicit argument");
        }
        if (self.parent.result.store.getLocal(target).layout_idx != .str) {
            boxyLowerInvariant("FieldName.name intrinsic result was not Str");
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .field = .{ .source = self.arg_locals.items[0], .field_idx = 0 } },
            .next = next,
        } }, self.derivedOrigin());
    }

    fn lowerGeneratedFieldNamesBoundInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        field_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.arg_locals.items.len < 1) {
            boxyLowerInvariant("FieldNames bound intrinsic had no explicit argument");
        }
        if (self.parent.result.store.getLocal(target).layout_idx != .u64) {
            boxyLowerInvariant("FieldNames bound intrinsic result was not U64");
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .field = .{ .source = self.arg_locals.items[0], .field_idx = field_index } },
            .next = next,
        } }, self.derivedOrigin());
    }

    fn generatedParserReadRecordField(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
        source_child: Plan.RepChild,
        field_text: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const view = procedureModuleById(self.parent.modules, source_child.source_type.module);
        const field = checkedRecordFieldByName(view, source_child.source_type.ty, field_text);
        return try self.lowerRecordFieldFromLocalInto(
            target,
            target_rep,
            source,
            source_child.rep,
            view,
            field.name,
            next,
        );
    }

    fn assignGeneratedParserTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        variant: ProcedureBuilder.GeneratedParserTagVariant,
        payload: LIR.LocalId,
        payload_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_payloads = self.parent.plan.childSlice(variant.variant.payloads);
        if (target_payloads.len != 1) boxyLowerInvariant("generated parser constructed tag did not have one payload");
        const target_child = target_payloads[0];

        return switch (self.workerRuntimeLayoutForRep(variant.tag_rep)) {
            .concrete => blk: {
                if (variant.owner_rep != variant.tag_rep) {
                    boxyLowerInvariant("generated parser concrete construction referenced a nonlocal row variant");
                }
                const payload_layout = self.tagUnionPayloadLayout(
                    self.parent.result.store.getLocal(target).layout_idx,
                    variant.index,
                );
                const payload_storage = try self.addFrameLocal(payload_layout);
                self.propagateBoundaryDescriptorMetadata(payload_storage, payload);
                const descriptor_fields = [_]AggregateDescriptorField{.{
                    .local = payload_storage,
                    .target_rep = target_child.rep,
                    .source_rep = payload_rep,
                }};
                const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, &descriptor_fields);
                defer tag_desc.deinit(self.parent.allocator);
                const assign = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                    .target = target,
                    .target_desc = tag_desc.desc,
                    .variant_index = variant.index,
                    .discriminant = variant.index,
                    .payload = payload_storage,
                    .next = next,
                } }, self.derivedOrigin());
                var continuation = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, assign);
                continuation = try self.assignGeneratedParserValueToStorage(
                    payload_storage,
                    target_child.rep,
                    payload,
                    payload_rep,
                    continuation,
                );
                break :blk try self.prependDescriptorArgMaterializations(tag_desc.field_initializers, continuation);
            },
            .dynamic_box => blk: {
                try self.bindConstructedTargetDescriptor(target, target_rep);
                const target_desc = try self.constructedTargetDescForRep(target_rep);
                const dynamic_payload = try self.dynamicTagPayloadLocalForChildren(target_payloads);
                self.propagateBoundaryDescriptorMetadata(dynamic_payload.local, payload);
                const descriptor_fields = [_]AggregateDescriptorField{.{
                    .local = dynamic_payload.local,
                    .target_rep = target_child.rep,
                    .source_rep = payload_rep,
                }};
                const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, &descriptor_fields);
                defer tag_desc.deinit(self.parent.allocator);
                const payload_desc = if (dynamic_payload.desc_rep) |desc_rep|
                    try self.descriptorRefForKnownRep(desc_rep)
                else
                    null;
                const assign = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                    .target = target,
                    .target_desc = tag_desc.desc orelse target_desc,
                    .tag_name = try self.lirTagNameForVariant(variant.variant),
                    .payload = dynamic_payload.local,
                    .payload_layout = dynamic_payload.layout_idx,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.derivedOrigin());
                var continuation = try self.prependConstructedDescriptorRebindForRep(target_rep, assign);
                continuation = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, continuation);
                continuation = try self.assignGeneratedParserValueToStorage(
                    dynamic_payload.local,
                    target_child.rep,
                    payload,
                    payload_rep,
                    continuation,
                );
                break :blk try self.prependDescriptorArgMaterializations(tag_desc.field_initializers, continuation);
            },
        };
    }

    fn assignGeneratedParserMultiTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        variant: ProcedureBuilder.GeneratedParserTagVariant,
        payload: DynamicTagPayloadLocal,
        items: []const ProcedureBuilder.GeneratedParserTupleItem,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_payloads = self.parent.plan.childSlice(variant.variant.payloads);
        if (target_payloads.len <= 1 or target_payloads.len != items.len) {
            boxyLowerInvariant("generated parser multi-payload tag had invalid payload metadata");
        }
        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, items.len);
        defer self.parent.allocator.free(descriptor_fields);
        for (items, target_payloads, descriptor_fields) |item, child, *field| {
            field.* = .{
                .local = item.value,
                .target_rep = child.rep,
                .source_rep = item.rep,
            };
        }
        const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, descriptor_fields);
        defer tag_desc.deinit(self.parent.allocator);

        const assign = switch (self.workerRuntimeLayoutForRep(variant.tag_rep)) {
            .concrete => if (self.isZstLocal(target))
                try self.assignZst(target, next)
            else
                try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                    .target = target,
                    .target_desc = tag_desc.desc,
                    .variant_index = variant.index,
                    .discriminant = variant.index,
                    .payload = payload.local,
                    .next = next,
                } }, self.derivedOrigin()),
            .dynamic_box => blk: {
                try self.bindConstructedTargetDescriptor(target, target_rep);
                const target_desc = tag_desc.desc orelse try self.constructedTargetDescForRep(target_rep);
                const payload_desc = if (payload.desc_rep) |desc_rep|
                    try self.descriptorRefForKnownRep(desc_rep)
                else
                    null;
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                    .target = target,
                    .target_desc = target_desc,
                    .tag_name = try self.lirTagNameForVariant(variant.variant),
                    .payload = payload.local,
                    .payload_layout = payload.layout_idx,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.derivedOrigin());
            },
        };
        var continuation = if (self.workerRuntimeLayoutForRep(variant.tag_rep) == .dynamic_box)
            try self.prependConstructedDescriptorRebindForRep(target_rep, assign)
        else
            assign;
        continuation = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, continuation);
        return try self.prependDescriptorArgMaterializations(tag_desc.field_initializers, continuation);
    }

    fn assignGeneratedParserZeroTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        variant: ProcedureBuilder.GeneratedParserTagVariant,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.parent.plan.childSlice(variant.variant.payloads).len != 0) {
            boxyLowerInvariant("generated zero-payload tag had payload children");
        }
        return switch (self.workerRuntimeLayoutForRep(variant.tag_rep)) {
            .concrete => blk: {
                if (variant.owner_rep != variant.tag_rep) {
                    boxyLowerInvariant("generated concrete zero-payload tag referenced a nonlocal row variant");
                }
                if (self.isZstLocal(target)) break :blk try self.assignZst(target, next);
                const materialization = try self.descriptorMaterializationForConstructedRep(target_rep);
                const desc_info = try self.descriptorForConstructedTargetMaterialization(target, materialization);
                const assign = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                    .target = target,
                    .target_desc = desc_info.desc,
                    .variant_index = variant.index,
                    .discriminant = variant.index,
                    .payload = null,
                    .next = next,
                } }, self.derivedOrigin());
                break :blk try self.prependOptionalDescriptorMaterialization(desc_info.materialize, assign);
            },
            .dynamic_box => blk: {
                try self.bindConstructedTargetDescriptor(target, target_rep);
                const target_desc = try self.constructedTargetDescForRep(target_rep);
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                    .target = target,
                    .target_desc = target_desc,
                    .tag_name = try self.lirTagNameForVariant(variant.variant),
                    .next = next,
                } }, self.derivedOrigin());
            },
        };
    }

    fn assignGeneratedParserValueToStorage(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.representationBoundaryIsDirect(target_rep, source_rep) and
            self.parent.result.store.getLocal(source).layout_idx == self.workerRuntimeLayoutForRep(target_rep).layoutIdx())
        {
            return try self.assignWorkerValueToTagPayloadStorage(target, source, target_rep, next);
        }
        const worker_value = try self.addFrameBoundaryTargetLocalForRep(target_rep);
        const store = try self.assignWorkerValueToTagPayloadStorage(target, worker_value, target_rep, next);
        return try self.assignRepresentationBoundary(worker_value, source, target_rep, source_rep, store);
    }

    fn assignGeneratedParserTwoFieldRecord(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        first_name: []const u8,
        first: LIR.LocalId,
        first_rep: Plan.TypeRepId,
        second_name: []const u8,
        second: LIR.LocalId,
        second_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const record_rep = self.recordRepForBoundary(target_rep) orelse
            boxyLowerInvariant("generated parser result payload was not a record");
        const rep = self.parent.plan.representations.items[@backingInt(record_rep)];
        const view = procedureModuleById(self.parent.modules, rep.source_type.module);
        const payload_layout = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => self.parent.result.store.getLocal(target).layout_idx,
            .dynamic_box => self.parent.layout_plan.rep_layouts[@backingInt(record_rep)].descriptor_payload_layout orelse
                boxyLowerInvariant("generated parser dynamic result record had no payload layout"),
        };
        const payload = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => target,
            .dynamic_box => try self.addFrameLocal(payload_layout),
        };
        const payload_layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag != .struct_ and payload_layout_value.tag != .zst) {
            boxyLowerInvariant("generated two-field record did not have a struct payload layout");
        }
        var fields: [2]LIR.LocalId = undefined;
        var sources: [2]LIR.LocalId = undefined;
        var source_reps: [2]Plan.TypeRepId = undefined;
        var target_reps: [2]Plan.TypeRepId = undefined;
        var count: usize = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            const label = switch (child.role) {
                .record_field => |label| label,
                .record_ext => {
                    self.requireEmptyRecordExtension(child.rep);
                    continue;
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("generated parser result record had a non-record child"),
            };
            if (count >= fields.len) boxyLowerInvariant("generated parser result record had too many fields");
            const text = view.canonical_names.recordFieldLabelText(label);
            if (std.mem.eql(u8, text, first_name)) {
                sources[count] = first;
                source_reps[count] = first_rep;
            } else if (std.mem.eql(u8, text, second_name)) {
                sources[count] = second;
                source_reps[count] = second_rep;
            } else {
                boxyLowerInvariant("generated parser result record had an unexpected field");
            }
            target_reps[count] = child.rep;
            fields[count] = try self.addFrameLocal(self.parent.recordPayloadFieldLayout(payload_layout, @intCast(count)));
            count += 1;
        }
        if (count != fields.len) boxyLowerInvariant("generated parser result record did not have two fields");

        const descriptor_fields = [_]AggregateDescriptorField{
            .{ .local = fields[0], .target_rep = target_reps[0], .source_rep = target_reps[0] },
            .{ .local = fields[1], .target_rep = target_reps[1], .source_rep = target_reps[1] },
        };
        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, target_rep, &descriptor_fields);
        defer aggregate_desc.deinit(self.parent.allocator);
        var continuation = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => next,
            .dynamic_box => blk: {
                const payload_desc = aggregate_desc.desc orelse
                    boxyLowerInvariant("generated parser dynamic result record had no descriptor");
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = payload,
                    .payload_layout = payload_layout,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.derivedOrigin());
            },
        };
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload,
            .fields = try self.parent.result.store.addLocalSpan(&fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = continuation,
        } }, self.derivedOrigin());
        var index = fields.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.assignGeneratedParserValueToStorage(
                fields[index],
                target_reps[index],
                sources[index],
                source_reps[index],
                continuation,
            );
        }
        try self.recordAggregateLocalDescriptorEnvironment(target, target_rep, &fields);
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        return try self.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    fn assignGeneratedParserOneFieldRecord(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        field_name: []const u8,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const record_rep = self.recordRepForBoundary(target_rep) orelse
            boxyLowerInvariant("generated one-field value was not a record");
        const rep = self.parent.plan.representations.items[@backingInt(record_rep)];
        const view = procedureModuleById(self.parent.modules, rep.source_type.module);
        const payload_layout = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => self.parent.result.store.getLocal(target).layout_idx,
            .dynamic_box => self.parent.layout_plan.rep_layouts[@backingInt(record_rep)].descriptor_payload_layout orelse
                boxyLowerInvariant("generated dynamic one-field record had no payload layout"),
        };
        const payload = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => target,
            .dynamic_box => try self.addFrameLocal(payload_layout),
        };
        const payload_layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag != .struct_ and payload_layout_value.tag != .zst) {
            boxyLowerInvariant("generated one-field record did not have a struct payload layout");
        }
        var target_child: ?Plan.RepChild = null;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            const label = switch (child.role) {
                .record_field => |label| label,
                .record_ext => {
                    self.requireEmptyRecordExtension(child.rep);
                    continue;
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("generated one-field record had a non-record child"),
            };
            if (!std.mem.eql(u8, view.canonical_names.recordFieldLabelText(label), field_name)) {
                boxyLowerInvariant("generated one-field record had an unexpected field");
            }
            if (target_child != null) boxyLowerInvariant("generated one-field record had too many fields");
            target_child = child;
        }
        const child = target_child orelse
            boxyLowerInvariant("generated one-field record had no field");
        const field = try self.addFrameLocal(self.parent.recordPayloadFieldLayout(payload_layout, 0));
        const descriptor_fields = [_]AggregateDescriptorField{.{
            .local = field,
            .target_rep = child.rep,
            .source_rep = child.rep,
        }};
        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, target_rep, &descriptor_fields);
        defer aggregate_desc.deinit(self.parent.allocator);
        var continuation = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => next,
            .dynamic_box => blk: {
                const payload_desc = aggregate_desc.desc orelse
                    boxyLowerInvariant("generated dynamic one-field record had no descriptor");
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = payload,
                    .payload_layout = payload_layout,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.derivedOrigin());
            },
        };
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload,
            .fields = try self.parent.result.store.addLocalSpan(&.{field}),
            .contents_desc = aggregate_desc.contents_desc,
            .next = continuation,
        } }, self.derivedOrigin());
        continuation = try self.assignGeneratedParserValueToStorage(
            field,
            child.rep,
            source,
            source_rep,
            continuation,
        );
        try self.recordAggregateLocalDescriptorEnvironment(target, target_rep, &.{field});
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        return try self.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    fn assignLocalRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx) {
            boxyLowerInvariant("generated parser local copy required matching layouts");
        }
        if (self.isZstLocal(target)) return next;
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .local = source },
            .next = next,
        } }, self.origin);
    }

    fn assignGeneratedParserU64Select(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        candidate: LIR.LocalId,
        current: LIR.LocalId,
        compare_op: LIR.LowLevel,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const done = self.freshJoinPointId();
        const jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = done } }, self.derivedOrigin());
        const selected = try self.assignLocalRef(target, candidate, jump);
        const retained = try self.assignLocalRef(target, current, jump);
        const cond = try self.addFrameLocal(.bool);
        const switch_stmt = try self.boolSwitchNoContinuation(cond, selected, retained);
        const compare = try self.assignBinaryLowLevel(cond, compare_op, candidate, current, switch_stmt);
        return try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = done,
            .params = try self.joinParamSpan(&.{target}),
            .body = next,
            .remainder = compare,
        } }, self.derivedOrigin());
    }

    fn beginRestoreConstUse(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        checked_ty: checked.CheckedTypeId,
        const_use: checked.ConstUseTemplate,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const requested_ty = const_use.requested_source_ty_payload orelse
            boxyLowerInvariant("checked const use reached boxy lowering without a requested checked type");
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (self.workerRuntimeLayoutForType(checked_ty).layoutIdx() != target_layout) {
            boxyLowerInvariant("checked const lookup expression type disagreed with target layout");
        }

        const store_module = procedureModuleByKey(self.parent.modules, checked.constModuleId(const_use.const_ref));
        const template = store_module.const_templates.get(const_use.const_ref);
        switch (template.state) {
            .reserved => boxyLowerInvariant("reserved checked const template reached runtime boxy lowering"),
            .eval_template => |eval| return exprDone(try self.lowerConstEvalTemplateUseInto(target, checked_ty, requested_ty, eval, next)),
            .unimplemented => return exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(Common.unimplemented_declaration_crash) },
            } }, self.scaffoldOrigin())),
            .stored_const => {},
        }
        const stored = template.state.stored_const;
        const producer_rep = self.parent.plan.repForStoredType(.{
            .module = store_module.key,
            .ty = stored.root_type,
        }) orelse boxyLowerInvariant("stored constant type was missing from the boxy representation plan");
        return try self.beginRestoreStoredConstNodeAcrossBoundary(
            target,
            store_module,
            stored.node,
            stored.root_type,
            self.repForType(checked_ty),
            producer_rep,
            next,
        );
    }

    fn restoreStoredConstNodeAcrossBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        target_rep: Plan.TypeRepId,
        stored_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.runExprStep(try self.beginRestoreStoredConstNodeAcrossBoundary(target, store_module, node, stored_type, target_rep, stored_rep, next));
    }

    const ConstTag = @FieldType(checked.ConstValue, "tag");

    fn beginRestoreStoredConstNodeAcrossBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        target_rep: Plan.TypeRepId,
        stored_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (self.parent.result.store.getLocal(target).layout_idx != self.workerRuntimeLayoutForRep(target_rep).layoutIdx()) {
            boxyLowerInvariant("stored constant boundary target layout disagreed with its representation");
        }
        if (self.representationBoundaryIsDirect(target_rep, stored_rep)) {
            return .{ .tail = .{ .stored_node = .{ .target = target, .store_module = store_module, .node = node, .stored_type = stored_type, .rep_id = stored_rep, .next = next } } };
        }

        const stored_local = try self.addFrameLocalForRep(stored_rep);
        const convert = try self.assignRepresentationBoundary(target, stored_local, target_rep, stored_rep, next);
        return .{ .tail = .{ .stored_node = .{ .target = stored_local, .store_module = store_module, .node = node, .stored_type = stored_type, .rep_id = stored_rep, .next = convert } } };
    }

    fn beginRestoreConstNode(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (@backingInt(node) >= store_module.const_store.values.items.len) {
            boxyLowerInvariant("ConstStore node id was outside the store");
        }
        return switch (store_module.const_store.get(node)) {
            .pending => boxyLowerInvariant("pending ConstStore node reached runtime boxy lowering"),
            .zst => exprDone(try self.assignZst(target, next)),
            .scalar => |scalar| exprDone(try self.assignConstScalar(target, scalar, next)),
            .str => |str| exprDone(try self.assignStringBytesView(target, store_module.const_store.blobData(str.data), str.offset, str.len, next)),
            .crash => |str| exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(store_module.const_store.strBytes(str)) },
            } }, self.scaffoldOrigin())),
            .checked_error => |str| exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(store_module.const_store.strBytes(str)) },
                .checked_error = true,
            } }, self.scaffoldOrigin())),
            .list => |items| try self.beginRestoreConstList(target, store_module, type_module, items, checked_ty, next),
            .box => |payload| try self.beginRestoreConstBox(target, store_module, type_module, payload, checked_ty, next),
            .tuple => |items| try self.beginRestoreConstTuple(target, store_module, type_module, items, checked_ty, next),
            .record => |items| try self.beginRestoreConstRecord(target, store_module, type_module, items, checked_ty, next),
            .tag => |tag| try self.beginRestoreConstTag(target, store_module, type_module, tag, checked_ty, next),
            .nominal => |nominal| try self.beginRestoreConstNominal(target, store_module, type_module, nominal.backing, checked_ty, next),
            .fn_value => |fn_id| try self.beginRestoreConstFnValue(
                target,
                store_module,
                type_module,
                fn_id,
                checked_ty,
                next,
            ),
        };
    }

    fn beginRestoreStoredConstNode(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (@backingInt(node) >= store_module.const_store.values.items.len) {
            boxyLowerInvariant("ConstStore node id was outside the store");
        }
        // A crash or checked-error node is the value of a root whose
        // evaluation stopped. It has no shape to unwrap at any
        // representation, so it restores as that crash before the
        // representation is consulted.
        switch (store_module.const_store.get(node)) {
            .crash => |str| return exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(store_module.const_store.strBytes(str)) },
            } }, self.scaffoldOrigin())),
            .checked_error => |str| return exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(store_module.const_store.strBytes(str)) },
                .checked_error = true,
            } }, self.scaffoldOrigin())),
            .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .tag, .nominal, .fn_value => {},
        }
        const stored_type_value = store_module.const_store.type_store.get(stored_type);
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        switch (rep.kind) {
            .alias => {
                const named = switch (stored_type_value) {
                    .named => |named| named,
                    .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => boxyLowerInvariant("stored alias representation had a non-named stored type"),
                };
                const backing_type = (named.backing orelse
                    boxyLowerInvariant("stored alias type had no backing")).ty;
                const backing_rep = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep;
                return .{ .tail = .{ .stored_node = .{ .target = target, .store_module = store_module, .node = node, .stored_type = backing_type, .rep_id = backing_rep, .next = next } } };
            },
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => {
                    const named = switch (stored_type_value) {
                        .named => |named| named,
                        .primitive, .record, .tuple, .tag_union, .list, .box, .func, .erased, .zst => boxyLowerInvariant("stored nominal representation had a non-named stored type"),
                    };
                    const backing_type = (named.backing orelse
                        boxyLowerInvariant("stored nominal type had no backing")).ty;
                    const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
                    const backing_node = switch (store_module.const_store.get(node)) {
                        .nominal => |nominal| nominal.backing,
                        .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .tag, .fn_value => node,
                        .crash, .checked_error => unreachable,
                    };
                    const backing_local = try self.addFrameLocalForRep(backing_rep);
                    const assign = try self.assignRepresentationBoundary(
                        target,
                        backing_local,
                        rep_id,
                        backing_rep,
                        next,
                    );
                    return .{ .tail = .{ .stored_node = .{ .target = backing_local, .store_module = store_module, .node = backing_node, .stored_type = backing_type, .rep_id = backing_rep, .next = assign } } };
                },
                .opaque_nominal => boxyLowerInvariant("opaque stored constant had no restorable backing representation"),
            },
            // `Bool` is represented as its tag directly, beneath any nominal
            // nodes that wrap the stored tag.
            .bool_tag_union => {
                var bool_node = node;
                while (true) switch (store_module.const_store.get(bool_node)) {
                    .nominal => |nominal| bool_node = nominal.backing,
                    .tag => |tag| return exprDone(try self.restoreConstBoolTagInto(target, tag, next)),
                    .pending, .zst, .scalar, .str, .list, .box, .tuple, .record, .fn_value => boxyLowerInvariant("stored Bool constant was not a tag"),
                    .crash, .checked_error => unreachable,
                };
            },
            .in_progress, .dynamic, .primitive, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => {},
        }

        return switch (store_module.const_store.get(node)) {
            .pending => boxyLowerInvariant("pending ConstStore node reached runtime boxy lowering"),
            .zst => exprDone(try self.assignZst(target, next)),
            .scalar => |scalar| exprDone(try self.assignConstScalar(target, scalar, next)),
            .str => |str| exprDone(try self.assignStringBytesView(target, store_module.const_store.blobData(str.data), str.offset, str.len, next)),
            .crash => |str| exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(store_module.const_store.strBytes(str)) },
            } }, self.scaffoldOrigin())),
            .checked_error => |str| exprDone(try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString(store_module.const_store.strBytes(str)) },
                .checked_error = true,
            } }, self.scaffoldOrigin())),
            .list => |items| try self.beginRestoreStoredConstList(target, store_module, items, stored_type, rep_id, next),
            .box => |payload| try self.beginRestoreStoredConstBox(target, store_module, payload, stored_type, rep_id, next),
            .tuple, .record => |items| try self.beginRestoreStoredConstAggregate(target, store_module, items, stored_type, rep_id, next),
            .tag => |tag| try self.beginRestoreStoredConstTag(target, store_module, tag, stored_type, rep_id, next),
            .nominal => boxyLowerInvariant("stored nominal node reached lowering after its representation was unwrapped"),
            .fn_value => |fn_id| try self.beginRestoreStoredConstFnValue(target, store_module, fn_id, rep_id, next),
        };
    }

    fn storedNodeItem(target: LIR.LocalId, store_module: ProcedureModuleView, node: checked.ConstNodeId, stored_type: check.ConstStore.ConstTypeId, rep_id: Plan.TypeRepId) ExprChainItem {
        return .{ .lower = .{ .stored_node = .{ .target = target, .store_module = store_module, .node = node, .stored_type = stored_type, .rep_id = rep_id, .next = undefined } } };
    }

    fn constNodeItem(target: LIR.LocalId, store_module: ProcedureModuleView, type_module: ProcedureModuleView, node: checked.ConstNodeId, checked_ty: checked.CheckedTypeId) ExprChainItem {
        return .{ .lower = .{ .const_node = .{ .target = target, .store_module = store_module, .type_module = type_module, .node = node, .checked_ty = checked_ty, .next = undefined } } };
    }

    fn beginRestoreStoredConstList(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        list: checked.ConstList,
        stored_type: check.ConstStore.ConstTypeId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const elem_type = switch (store_module.const_store.type_store.get(stored_type)) {
            .list => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .box, .func, .erased, .zst => boxyLowerInvariant("stored list node had a non-list stored type"),
        };
        const elem_rep = self.repQuery().requiredSingleChild(rep_id, .list_elem).rep;
        const elem_layout = self.localListElemLayout(target);
        if (list == .packed_bytes) return exprDone(try self.restorePackedListInto(target, store_module, list.packed_bytes, rep_id, elem_rep, elem_rep, next));
        const list_len: usize = switch (list) {
            .nodes => |items| items.len,
            .packed_bytes => |packed_list| packed_list.len,
            .empty => 0,
        };
        const elems = try self.parent.allocator.alloc(LIR.LocalId, list_len);
        defer self.parent.allocator.free(elems);
        for (elems) |*elem| elem.* = try self.addFrameLocal(elem_layout);

        const continuation = try self.assignList(target, elems, next);
        const items = switch (list) {
            .nodes => |items| items,
            .packed_bytes => unreachable,
            .empty => &.{},
        };
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, items.len);
        for (chain_items, 0..) |*item, offset| {
            const index = items.len - 1 - offset;
            item.* = .{ .lower = .{ .stored_storage = .{ .storage_local = elems[index], .store_module = store_module, .node = items[index], .stored_type = elem_type, .value_rep = elem_rep, .next = undefined } } };
        }
        return exprChain(chain_items, continuation);
    }

    fn beginRestoreStoredConstBox(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        payload: checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const payload_type = switch (store_module.const_store.type_store.get(stored_type)) {
            .box => |elem| elem,
            .primitive, .named, .record, .tuple, .tag_union, .list, .func, .erased, .zst => boxyLowerInvariant("stored box node had a non-box stored type"),
        };
        const payload_rep = self.repQuery().requiredSingleChild(rep_id, .box_payload).rep;
        const payload_local = try self.addFrameLocalForRep(payload_rep);
        const boxed = try self.assignBoxBoundary(target, payload_local, rep_id, .box_box, next);
        return .{ .tail = .{ .stored_node = .{ .target = payload_local, .store_module = store_module, .node = payload, .stored_type = payload_type, .rep_id = payload_rep, .next = boxed } } };
    }

    fn beginRestoreStoredConstAggregate(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        items: []const checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (self.isZstLocal(target)) return exprDone(try self.assignZst(target, next));
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const children = self.parent.plan.childSlice(rep.children);
        if (children.len != items.len) {
            boxyLowerInvariant("stored aggregate node count disagreed with its exact representation");
        }
        const locals = try self.parent.allocator.alloc(LIR.LocalId, items.len);
        defer self.parent.allocator.free(locals);
        for (children, locals) |child, *local| local.* = try self.addFrameLocalForRep(child.rep);
        const continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(locals),
            .next = next,
        } }, self.scaffoldOrigin());
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, items.len);
        for (chain_items, 0..) |*item, offset| {
            const index = items.len - 1 - offset;
            const child_type = switch (store_module.const_store.type_store.get(stored_type)) {
                .tuple => |stored_types| store_module.const_store.type_store.typeSpan(stored_types)[index],
                .record => |fields| store_module.const_store.type_store.fieldSpan(fields)[index].ty,
                .primitive, .named, .tag_union, .list, .box, .func, .erased, .zst => boxyLowerInvariant("stored aggregate node had a non-aggregate stored type"),
            };
            item.* = storedNodeItem(locals[index], store_module, items[index], child_type, children[index].rep);
        }
        return exprChain(chain_items, continuation);
    }

    fn beginRestoreStoredConstTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        tag: ConstTag,
        stored_type: check.ConstStore.ConstTypeId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.kind == .bool_tag_union) return exprDone(try self.restoreConstBoolTagInto(target, tag, next));
        if (rep.kind != .tag_union) {
            boxyLowerInvariant("stored tag node had a non-tag-union exact representation");
        }
        const names_store = store_module.canonical_names;
        var variant: ?struct { plan: Plan.TagVariant, index: u32 } = null;
        for (self.parent.plan.tagVariantSlice(rep.tag_variants), 0..) |candidate, index| {
            if (std.mem.eql(u8, tag.tag_name, names_store.tagLabelText(candidate.name))) {
                variant = .{ .plan = candidate, .index = @intCast(index) };
                break;
            }
        }
        const selected = variant orelse
            boxyLowerInvariant("stored tag node was absent from its exact representation");
        const payload_children = self.parent.plan.childSlice(selected.plan.payloads);
        if (payload_children.len != tag.payloads.len) {
            boxyLowerInvariant("stored tag payload count disagreed with its exact representation");
        }
        const stored_tags = switch (store_module.const_store.type_store.get(stored_type)) {
            .tag_union => |tags| store_module.const_store.type_store.tagSpan(tags),
            .primitive, .named, .record, .tuple, .list, .box, .func, .erased, .zst => boxyLowerInvariant("stored tag node had a non-tag-union stored type"),
        };
        var payload_types: ?[]const check.ConstStore.ConstTypeId = null;
        for (stored_tags) |stored_tag| {
            if (std.mem.eql(u8, tag.tag_name, names_store.tagLabelText(stored_tag.checked_name))) {
                payload_types = store_module.const_store.type_store.typeSpan(stored_tag.payloads);
                break;
            }
        }
        const exact_payload_types = payload_types orelse
            boxyLowerInvariant("stored tag node was absent from its stored type");

        if (tag.payloads.len == 0) {
            if (self.isZstLocal(target)) return exprDone(try self.assignZst(target, next));
            return exprDone(try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .variant_index = selected.index,
                .discriminant = selected.index,
                .payload = null,
                .next = next,
            } }, self.scaffoldOrigin()));
        }

        const payload_layout = self.tagUnionPayloadLayout(
            self.parent.result.store.getLocal(target).layout_idx,
            selected.index,
        );
        const payload = try self.addFrameLocal(payload_layout);
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
            .target = target,
            .variant_index = selected.index,
            .discriminant = selected.index,
            .payload = payload,
            .next = next,
        } }, self.scaffoldOrigin());
        if (tag.payloads.len == 1) {
            return .{ .tail = .{ .stored_storage = .{ .storage_local = payload, .store_module = store_module, .node = tag.payloads[0], .stored_type = exact_payload_types[0], .value_rep = payload_children[0].rep, .next = assign_tag } } };
        }

        const fields = try self.parent.allocator.alloc(LIR.LocalId, tag.payloads.len);
        defer self.parent.allocator.free(fields);
        for (payload_children, fields) |child, *field| field.* = try self.addFrameLocalForRep(child.rep);
        const continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload,
            .fields = try self.parent.result.store.addLocalSpan(fields),
            .next = assign_tag,
        } }, self.scaffoldOrigin());
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, tag.payloads.len);
        for (chain_items, 0..) |*item, offset| {
            const index = tag.payloads.len - 1 - offset;
            item.* = storedNodeItem(fields[index], store_module, tag.payloads[index], exact_payload_types[index], payload_children[index].rep);
        }
        return exprChain(chain_items, continuation);
    }

    fn beginRestoreStoredConstIntoStorageRep(
        self: *ProcBodyBuilder,
        storage_local: LIR.LocalId,
        store_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        stored_type: check.ConstStore.ConstTypeId,
        value_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (self.parent.result.store.getLocal(storage_local).layout_idx ==
            self.workerRuntimeLayoutForRep(value_rep).layoutIdx())
        {
            return .{ .tail = .{ .stored_node = .{ .target = storage_local, .store_module = store_module, .node = node, .stored_type = stored_type, .rep_id = value_rep, .next = next } } };
        }
        const value = try self.addFrameLocalForRep(value_rep);
        const convert = try self.assignRepresentationBoundary(storage_local, value, value_rep, value_rep, next);
        return .{ .tail = .{ .stored_node = .{ .target = value, .store_module = store_module, .node = node, .stored_type = stored_type, .rep_id = value_rep, .next = convert } } };
    }

    fn beginRestoreConstList(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        list: checked.ConstList,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const list_rep = self.repForModuleType(type_module, checked_ty);
        try self.bindConstructedTargetDescriptor(target, list_rep);

        const elem_ty = constListElemType(type_module, checked_ty);
        const target_elem_rep = self.repQuery().requiredSingleChild(list_rep, .list_elem).rep;
        const source_elem_rep = self.repForModuleType(type_module, elem_ty);
        _ = try self.reserveDescriptorLocalForRep(target_elem_rep);
        const elem_layout = self.localListElemLayout(target);
        if (list == .packed_bytes) return exprDone(try self.restorePackedListInto(target, store_module, list.packed_bytes, list_rep, source_elem_rep, target_elem_rep, next));
        const list_len: usize = switch (list) {
            .nodes => |items| items.len,
            .packed_bytes => |packed_list| packed_list.len,
            .empty => 0,
        };
        const elem_locals = try self.parent.allocator.alloc(LIR.LocalId, list_len);
        defer self.parent.allocator.free(elem_locals);
        const source_locals = try self.parent.allocator.alloc(?LIR.LocalId, list_len);
        defer self.parent.allocator.free(source_locals);
        const source_layout = self.workerRuntimeLayoutForType(elem_ty).layoutIdx();

        for (elem_locals, source_locals) |*local, *source_local| {
            local.* = try self.addFrameLocal(elem_layout);
            source_local.* = if (source_layout == elem_layout) null else blk: {
                if (!self.layoutIsBoxyDynamicStorage(elem_layout)) {
                    boxyLowerInvariant("ConstStore list element layout required unsupported non-dynamic adaptation before list construction");
                }
                break :blk try self.addFrameLocal(source_layout);
            };
        }

        var continuation = try self.assignList(target, elem_locals, next);
        continuation = try self.prependConstructedDescriptorRebindForRep(list_rep, continuation);
        continuation = try self.prependDescriptorRebindForRepFromRep(target_elem_rep, source_elem_rep, continuation);

        const items = switch (list) {
            .nodes => |items| items,
            .packed_bytes => unreachable,
            .empty => &.{},
        };
        var chain_items = std.ArrayList(ExprChainItem).empty;
        errdefer chain_items.deinit(self.parent.allocator);
        var index = items.len;
        while (index > 0) {
            index -= 1;
            if (source_locals[index]) |source| {
                try chain_items.append(self.parent.allocator, .{ .const_list_element_box = .{ .elem_local = elem_locals[index], .source = source, .source_elem_rep = source_elem_rep } });
                try chain_items.append(self.parent.allocator, constNodeItem(source, store_module, type_module, items[index], elem_ty));
            } else {
                try chain_items.append(self.parent.allocator, constNodeItem(elem_locals[index], store_module, type_module, items[index], elem_ty));
            }
        }
        return exprChain(try chain_items.toOwnedSlice(self.parent.allocator), continuation);
    }

    fn beginRestoreConstBox(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        payload: checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const payload_ty = constBoxPayloadType(type_module, checked_ty);
        const payload_local = try self.addFrameLocalForType(payload_ty);
        const boxed = try self.assignBoxBoundary(
            target,
            payload_local,
            self.repForType(checked_ty),
            .box_box,
            next,
        );
        return .{ .tail = .{ .const_node = .{ .target = payload_local, .store_module = store_module, .type_module = type_module, .node = payload, .checked_ty = payload_ty, .next = boxed } } };
    }

    fn beginRestoreConstTuple(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        items: []const checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const item_tys = constTupleItemTypes(type_module, checked_ty);
        if (item_tys.len != items.len) {
            boxyLowerInvariant("ConstStore tuple length differed from checked tuple type");
        }
        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, items.len);
        defer self.parent.allocator.free(field_locals);
        for (item_tys, field_locals) |item_ty, *local| {
            local.* = try self.addFrameLocalForType(item_ty);
        }

        const continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .next = next,
        } }, self.scaffoldOrigin());
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, items.len);
        for (chain_items, 0..) |*item, offset| {
            const index = items.len - 1 - offset;
            item.* = constNodeItem(field_locals[index], store_module, type_module, items[index], item_tys[index]);
        }
        return exprChain(chain_items, continuation);
    }

    fn beginRestoreConstRecord(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        items: []const checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const fields = try constRecordFields(self.parent.allocator, type_module, checked_ty);
        defer self.parent.allocator.free(fields);
        if (fields.len != items.len) {
            boxyLowerInvariant("ConstStore record field count differed from checked record type");
        }

        const checked_rep_id = self.repForModuleType(type_module, checked_ty);
        const checked_rep = self.parent.plan.representations.items[@backingInt(checked_rep_id)];
        if (checked_rep.kind == .empty_record) {
            if (items.len != 0) {
                boxyLowerInvariant("ConstStore empty record carried field values");
            }
            return exprDone(try self.assignZst(target, next));
        }
        // A record whose fields are all zero-sized restores as a unit value;
        // constant nodes carry no effects, so the fields need no restoration.
        if (self.isZstLocal(target)) {
            return exprDone(try self.assignZst(target, next));
        }
        const rep_id = self.recordRepForBoundary(checked_rep_id) orelse
            boxyLowerInvariant("ConstStore record restored with a non-record boxy representation");
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const record_target, const record_next = switch (rep.kind) {
            .record,
            => .{ target, next },
            .dynamic => blk: {
                const payload_layout = self.parent.layout_plan.rep_layouts[@backingInt(rep_id)].descriptor_payload_layout orelse
                    boxyLowerInvariant("dynamic ConstStore record descriptor had no payload layout");
                const payload = try self.addFrameLocal(payload_layout);
                const payload_desc_info = try self.descriptorForConstructedTarget(target, try self.descriptorRefForKnownRep(rep_id));
                const payload_desc = payload_desc_info.desc orelse
                    boxyLowerInvariant("dynamic ConstStore record construction had no target descriptor");
                const assign_box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = payload,
                    .payload_layout = payload_layout,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.scaffoldOrigin());
                break :blk .{ payload, try self.prependOptionalDescriptorMaterialization(payload_desc_info.materialize, assign_box) };
            },
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore record restored with a non-record boxy representation"),
        };

        const children = self.parent.plan.childSlice(rep.children);
        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, fields.len);
        defer self.parent.allocator.free(field_locals);
        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, fields.len);
        defer self.parent.allocator.free(descriptor_fields);
        const source_field_locals = try self.parent.allocator.alloc(?LIR.LocalId, fields.len);
        defer self.parent.allocator.free(source_field_locals);
        @memset(source_field_locals, null);
        const source_field_reps = try self.parent.allocator.alloc(Plan.TypeRepId, fields.len);
        defer self.parent.allocator.free(source_field_reps);

        var layout_index: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => |label| {
                    const source_index = constRecordFieldIndex(fields, label) orelse
                        boxyLowerInvariant("ConstStore record representation referenced a field outside checked type");
                    const local = try self.addFrameLocalForRep(child.rep);
                    field_locals[layout_index] = local;
                    descriptor_fields[layout_index] = .{
                        .local = local,
                        .target_rep = child.rep,
                        .source_rep = child.rep,
                    };
                    source_field_locals[source_index] = local;
                    source_field_reps[source_index] = child.rep;
                    layout_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("ConstStore record representation had a non-record child role"),
            }
        }
        if (layout_index != fields.len) {
            boxyLowerInvariant("ConstStore record representation field count differed from checked type");
        }
        for (source_field_locals) |maybe_local| {
            if (maybe_local == null) {
                boxyLowerInvariant("ConstStore record field was not selected by representation order");
            }
        }

        const aggregate_desc = try self.constructedAggregateDescriptorForFields(record_target, rep_id, descriptor_fields);
        var aggregate_desc_owned = true;
        defer if (aggregate_desc_owned) aggregate_desc.deinit(self.parent.allocator);

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = record_target,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .contents_desc = aggregate_desc.contents_desc,
            .next = record_next,
        } }, self.scaffoldOrigin());
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, items.len + 1);
        for (0..items.len) |offset| {
            const source_index = items.len - 1 - offset;
            chain_items[offset] = if (fields[source_index].kind.tag == .optional)
                .{ .lower = .{ .const_optional_slot = .{
                    .target = source_field_locals[source_index].?,
                    .store_module = store_module,
                    .type_module = type_module,
                    .node = items[source_index],
                    .payload_ty = fields[source_index].ty,
                    .slot_rep = source_field_reps[source_index],
                    .next = undefined,
                } } }
            else
                .{ .lower = .{ .const_storage = .{
                    .storage_local = source_field_locals[source_index].?,
                    .store_module = store_module,
                    .type_module = type_module,
                    .node = items[source_index],
                    .value_ty = fields[source_index].ty,
                    .storage_rep = source_field_reps[source_index],
                    .next = undefined,
                } } };
        }
        chain_items[items.len] = .prepend_field_initializers;
        aggregate_desc_owned = false;
        return .{ .tail = .{ .chain = .{ .items = chain_items, .current = continuation, .aggregate_desc = aggregate_desc } } };
    }

    /// An optional field's stored node is its presence slot, while its checked
    /// field type names only the payload. Restore the slot using the planner's
    /// explicit presence representation and restore Present's child at that
    /// checked payload type.
    fn beginRestoreConstOptionalSlot(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        payload_ty: checked.CheckedTypeId,
        slot_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const stored = store_module.const_store.get(node);
        if (stored != .tag) boxyLowerInvariant("stored optional field did not carry its presence tag");
        const slot = self.parent.plan.representations.items[@backingInt(slot_rep)];
        const present = slot.presence_slot_present_discriminant orelse
            boxyLowerInvariant("stored optional field had no planned presence slot");
        const variant = self.plannedTagVariantByText(slot_rep, stored.tag.tag_name);
        const payload_tys: []const checked.CheckedTypeId = if (variant.index == present) &.{payload_ty} else &.{};
        return try self.beginRestoreConstPlannedTagPayloads(
            target,
            store_module,
            type_module,
            variant,
            stored.tag,
            payload_tys,
            next,
        );
    }

    fn beginRestoreConstTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        tag: ConstTag,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        var rep_id = self.repForModuleType(type_module, checked_ty);
        // Each step unwraps one alias or nominal, so a chain longer than the
        // plan's representation count revisits one: a cycle.
        for (0..self.parent.plan.representations.items.len + 1) |_| {
            const wrapper = self.parent.plan.representations.items[@backingInt(rep_id)];
            switch (wrapper.kind) {
                .alias => rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent,
                    .builtin_other,
                    => rep_id = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep,
                    .opaque_nominal => break,
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => break,
            }
        } else boxyLowerInvariant("ConstStore tag representation wrapper chain was cyclic");
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        return switch (rep.kind) {
            .bool_tag_union => exprDone(try self.restoreConstBoolTagInto(target, tag, next)),
            .tag_union => blk: {
                const checked_tag = constTagPayloadTypes(type_module, checked_ty, tag.tag_name);
                break :blk try self.beginRestoreConstPlannedTagPayloads(
                    target,
                    store_module,
                    type_module,
                    self.tagVariantForModule(rep, type_module, checked_tag.name),
                    tag,
                    checked_tag.payload_tys,
                    next,
                );
            },
            .dynamic => try self.beginRestoreConstDynamicTag(target, store_module, type_module, rep_id, tag, checked_ty, next),
            .empty_tag_union => boxyLowerInvariant("ConstStore tag value reached empty tag-union representation"),
            .in_progress, .primitive, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record => boxyLowerInvariant("ConstStore tag restored with a non-tag-union representation"),
        };
    }

    fn constStorageItem(storage_local: LIR.LocalId, store_module: ProcedureModuleView, type_module: ProcedureModuleView, node: checked.ConstNodeId, value_ty: checked.CheckedTypeId, storage_rep: Plan.TypeRepId) ExprChainItem {
        return .{ .lower = .{ .const_storage = .{
            .storage_local = storage_local,
            .store_module = store_module,
            .type_module = type_module,
            .node = node,
            .value_ty = value_ty,
            .storage_rep = storage_rep,
            .next = undefined,
        } } };
    }

    /// Restore a constant tag value into a dynamic representation (an open
    /// tag-union row). The stored value's checked tag-union type supplies the
    /// concrete payload types; the row's payload storage conventions come from
    /// the representation's children, and construction goes through the
    /// descriptor-guided tag statement like any other dynamic tag expression.
    fn beginRestoreConstDynamicTag(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        rep_id: Plan.TypeRepId,
        tag: ConstTag,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const checked_tag = constTagPayloadTypesAllowOpen(type_module, checked_ty, tag.tag_name);
        const payload_tys = checked_tag.payload_tys;
        if (payload_tys.len != tag.payloads.len) {
            boxyLowerInvariant("ConstStore tag payload count differed from checked tag type");
        }
        const target_desc_materialization = try self.descriptorMaterializationForConstructedRep(rep_id);
        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, target_desc_materialization);
        const target_desc = target_desc_info.desc orelse
            boxyLowerInvariant("dynamic tag construction had no target descriptor");

        if (tag.payloads.len == 0) {
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                .target = target,
                .target_desc = target_desc,
                .tag_name = try self.lirTagName(checked_tag.name),
                .next = next,
            } }, self.scaffoldOrigin());
            return exprDone(try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, assign_tag));
        }

        const payloads = try self.dynamicTagPayloadsForName(rep_id, checked_tag.name);
        if (payloads.len != tag.payloads.len) {
            boxyLowerInvariant("ConstStore tag payload count disagreed with its dynamic representation");
        }
        const payload = try self.dynamicTagPayloadLocalForChildren(payloads);
        const payload_desc = if (payload.desc_rep) |payload_rep| try self.descriptorRefForKnownRep(payload_rep) else null;
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
            .target = target,
            .target_desc = target_desc,
            .tag_name = try self.lirTagName(checked_tag.name),
            .payload = payload.local,
            .payload_layout = payload.layout_idx,
            .payload_desc = payload_desc,
            .payload_mode = .move,
            .next = next,
        } }, self.scaffoldOrigin());
        var continuation = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, assign_tag);

        if (tag.payloads.len == 1) {
            return .{ .tail = withNext(constStorageItem(payload.local, store_module, type_module, tag.payloads[0], payload_tys[0], payloads[0].rep).lower, continuation) };
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, tag.payloads.len);
        defer self.parent.allocator.free(field_locals);
        for (payloads, field_locals) |child, *local| {
            local.* = try self.addFrameLocal(self.tagPayloadStorageLayoutForRep(child.rep));
        }
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload.local,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .next = continuation,
        } }, self.scaffoldOrigin());
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, tag.payloads.len);
        for (chain_items, 0..) |*item, offset| {
            const index = tag.payloads.len - 1 - offset;
            item.* = constStorageItem(field_locals[index], store_module, type_module, tag.payloads[index], payload_tys[index], payloads[index].rep);
        }
        return exprChain(chain_items, continuation);
    }

    /// Restore a constant node into a local whose layout follows a (possibly
    /// dynamic) storage representation: restore through the value's own
    /// checked type and adapt across the representation boundary.
    fn beginRestoreConstIntoStorageRep(
        self: *ProcBodyBuilder,
        storage_local: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        node: checked.ConstNodeId,
        value_ty: checked.CheckedTypeId,
        storage_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const value_rep = self.repForTypeRef(.{ .module = type_module.key, .ty = value_ty });
        if (self.parent.result.store.getLocal(storage_local).layout_idx ==
            self.workerRuntimeLayoutForRep(value_rep).layoutIdx() and
            self.descriptorStorageRep(value_rep) == self.descriptorStorageRep(storage_rep))
        {
            return .{ .tail = .{ .const_node = .{ .target = storage_local, .store_module = store_module, .type_module = type_module, .node = node, .checked_ty = value_ty, .next = next } } };
        }
        const temp = try self.addFrameLocalForRep(value_rep);
        const convert = try self.assignRepresentationBoundary(storage_local, temp, storage_rep, value_rep, next);
        return .{ .tail = .{ .const_node = .{ .target = temp, .store_module = store_module, .type_module = type_module, .node = node, .checked_ty = value_ty, .next = convert } } };
    }

    fn beginRestoreConstPlannedTagPayloads(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        variant: TagVariantLookup,
        tag: ConstTag,
        payload_tys: []const checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        if (payload_tys.len != tag.payloads.len) {
            boxyLowerInvariant("ConstStore tag payload count differed from checked tag type");
        }

        const payload_children = self.parent.plan.childSlice(variant.payloads);
        if (payload_children.len != tag.payloads.len) {
            boxyLowerInvariant("ConstStore tag payload count disagreed with its boxy representation");
        }
        for (payload_children, 0..) |child, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("ConstStore tag variant payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("ConstStore tag variant payload span included a non-payload child"),
            }
        }

        if (tag.payloads.len == 0) {
            if (self.isZstLocal(target)) return exprDone(try self.assignZst(target, next));
            return exprDone(try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .variant_index = variant.index,
                .discriminant = variant.index,
                .payload = null,
                .next = next,
            } }, self.scaffoldOrigin()));
        }

        const payload_layout = if (self.isZstLocal(target))
            layout.Idx.zst
        else
            self.tagUnionPayloadLayout(self.parent.result.store.getLocal(target).layout_idx, variant.index);
        const payload_local = try self.addFrameLocal(payload_layout);
        if (self.isZstLocal(target) and !self.isZstLocal(payload_local)) {
            boxyLowerInvariant("zero-sized ConstStore tag-union layout had a non-zero-sized payload");
        }

        const assign_tag = if (self.isZstLocal(target))
            try self.assignZst(target, next)
        else
            try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .variant_index = variant.index,
                .discriminant = variant.index,
                .payload = payload_local,
                .next = next,
            } }, self.scaffoldOrigin());

        if (tag.payloads.len == 1) {
            return .{ .tail = withNext(constStorageItem(payload_local, store_module, type_module, tag.payloads[0], payload_tys[0], payload_children[0].rep).lower, assign_tag) };
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, tag.payloads.len);
        defer self.parent.allocator.free(field_locals);
        for (payload_children, field_locals) |child, *local| {
            local.* = try self.addFrameLocalForRep(child.rep);
        }

        const continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload_local,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .next = assign_tag,
        } }, self.scaffoldOrigin());
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, tag.payloads.len);
        for (chain_items, 0..) |*item, offset| {
            const index = tag.payloads.len - 1 - offset;
            item.* = constStorageItem(field_locals[index], store_module, type_module, tag.payloads[index], payload_tys[index], payload_children[index].rep);
        }
        return exprChain(chain_items, continuation);
    }

    fn beginRestoreConstNominal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        backing: checked.ConstNodeId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const nominal_rep = self.repForModuleType(type_module, checked_ty);
        const nominal_rep_info = self.parent.plan.representations.items[@backingInt(nominal_rep)];
        const backing_child = switch (nominal_rep_info.kind) {
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => self.repQuery().requiredSingleChild(nominal_rep, .nominal_backing),
                .opaque_nominal => boxyLowerInvariant("opaque ConstStore nominal had no restorable backing representation"),
            },
            .alias => self.repQuery().requiredSingleChild(nominal_rep, .alias_backing),
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => boxyLowerInvariant("compiler-owned encoding evidence reached ordinary ConstStore nominal restoration"),
            .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .empty_record, .tag_union, .empty_tag_union => return .{ .tail = .{ .const_node = .{
                .target = target,
                .store_module = store_module,
                .type_module = type_module,
                .node = backing,
                .checked_ty = checked_ty,
                .next = next,
            } } },
        };
        const backing_type_module = procedureModuleById(self.parent.modules, backing_child.source_type.module);
        const backing_local = try self.addFrameLocalForRep(backing_child.rep);
        const assign = try self.assignRepresentationBoundary(
            target,
            backing_local,
            nominal_rep,
            backing_child.rep,
            next,
        );
        return .{ .tail = .{ .const_node = .{
            .target = backing_local,
            .store_module = store_module,
            .type_module = backing_type_module,
            .node = backing,
            .checked_ty = backing_child.source_type.ty,
            .next = assign,
        } } };
    }

    /// A constant whose value is computed by evaluating a body (rather than a
    /// compile-time-stored value) is produced at runtime by calling the
    /// constant's entry-wrapper thunk, which the planner registered as a
    /// zero-argument worker. Emit that call and adapt its result to the use
    /// site's representation.
    fn lowerConstEvalTemplateUseInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        checked_ty: checked.CheckedTypeId,
        requested_ty: checked.CheckedTypeId,
        eval: checked.ConstEvalTemplate,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const entry_view = procedureModuleByCheckedModuleId(self.parent.modules, eval.entry_template.artifact);
        const entry_template = entry_view.checked_procedure_templates.get(eval.entry_template.template);
        const fn_ty_ref = Plan.CheckedTypeIdentity{ .module = entry_view.key, .ty = entry_template.checked_fn_root };
        const worker_id = self.parent.plan.workerForSourceType(.{ .procedure_template = eval.entry_template }, fn_ty_ref) orelse
            boxyLowerInvariant("const eval template use reached boxy lowering without a planned entry-wrapper worker");
        const call_plan = self.parent.plan.constEvalCallFor(worker_id, .{ .module = self.module.key, .ty = requested_ty }) orelse
            boxyLowerInvariant("const eval template use reached boxy lowering without a planned call");

        const hidden_desc_args = self.parent.plan.directCallHiddenDescriptorArgSlice(call_plan.hidden_desc_args);
        const hidden_dict_args = self.parent.plan.directCallHiddenDictionaryArgSlice(call_plan.hidden_dict_args);
        return try self.lowerWorkerCallLocalsInto(
            target,
            .{ .module = self.module.key, .ty = checked_ty },
            &.{},
            &.{},
            &.{},
            null,
            null,
            call_plan.ret_substitution,
            worker_id,
            hidden_desc_args,
            hidden_dict_args,
            next,
        );
    }

    fn beginRestoreStoredConstFnValue(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        fn_id: checked.ConstFnId,
        requested_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const callable = self.functionChildrenForRep(requested_rep) orelse
            boxyLowerInvariant("stored function value had a non-callable stored representation");
        var planned: ?Plan.StaticFnPlan = null;
        for (self.parent.plan.static_fns.items) |candidate| {
            if (candidate.fn_id != fn_id) continue;
            if (!checked_moduleKeyEqual(candidate.store_module, store_module.key)) continue;
            if (candidate.rep != callable.rep) continue;
            if (planned != null) boxyLowerInvariant("stored function value matched duplicate exact static plans");
            planned = candidate;
        }
        const static_fn = planned orelse
            boxyLowerInvariant("stored function value had no producer-selected static plan");
        const worker = self.parent.plan.workers.items[@backingInt(static_fn.worker)];
        return try self.beginWorkerValueWithValueRep(
            target,
            worker.checked_type,
            static_fn.rep,
            worker.source,
            null,
            self.parent.plan.storedCallableCaptureSourceSlice(static_fn.capture_sources),
            self.staticFnHiddenDescArgs(static_fn),
            self.parent.plan.directCallHiddenDictionaryArgSlice(static_fn.hidden_dict_args),
            next,
        );
    }

    fn packedListLiteral(self: *ProcBodyBuilder, module: ProcedureModuleView, data: check.ConstStore.ConstPackedList, elem: layout.Idx) Allocator.Error!LIR.ListLiteral {
        const key = PackedLiteralKey{ .module = module.key.bytes, .data = data.bytes.data, .offset = data.bytes.offset, .byte_len = data.bytes.len, .len = data.len, .element = elem };
        if (self.parent.packed_literals.get(key)) |literal| return literal;
        const gpa = self.parent.allocator;
        if (!self.parent.packed_plans.contains(elem)) {
            var plan = try lir_core.PackedData.Plan.init(gpa, &self.parent.result.layouts, elem);
            errdefer plan.deinit();
            try self.parent.packed_plans.put(elem, plan);
        }
        const plan = self.parent.packed_plans.getPtr(elem).?;
        if (plan.packed_width != data.byteWidth()) boxyLowerInvariant("packed constant width differed from producer representation");
        const bytes = module.const_store.blobBytes(data.bytes);
        var converted: ?[]u8 = null;
        defer if (converted) |owned| gpa.free(owned);
        const target_bytes = if (plan.isIdentity()) bytes else blk: {
            const out = try gpa.alloc(u8, @as(usize, data.len) * plan.memory_width);
            converted = out;
            plan.decode(out, bytes, data.len);
            break :blk out;
        };
        const alignment: u32 = @intCast(@max(self.parent.result.layouts.getLayout(elem).alignment(self.parent.options.target_usize).toByteUnits(), 1));
        const literal = LIR.ListLiteral{ .bytes = try self.parent.result.store.insertStringViewAligned(target_bytes, 0, @intCast(target_bytes.len), alignment), .len = data.len };
        try self.parent.packed_literals.put(key, literal);
        return literal;
    }

    /// A packed source stays one literal. Storage adaptations execute one typed
    /// loop body, with explicit descriptors and ordinary ARC-visible moves.
    fn restorePackedListInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        module: ProcedureModuleView,
        data: check.ConstStore.ConstPackedList,
        list_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        const target_layout = self.localListElemLayout(target);
        try self.bindConstructedTargetDescriptor(target, list_rep);
        const after = try self.prependConstructedDescriptorRebindForRep(list_rep, next);
        if (data.len == 0) return try self.assignList(target, &.{}, after);
        const literal = try self.packedListLiteral(module, data, source_layout);
        if (source_layout == target_layout and self.representationBoundaryIsDirect(target_rep, source_rep)) {
            return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{ .target = target, .value = .{ .bytes_literal = literal }, .next = after } }, self.scaffoldOrigin());
        }
        const list_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_list_layout = try self.parent.result.layouts.insertLayout(layout.Layout.list(source_layout));
        const source = try self.addFrameLocal(source_list_layout);
        const index = try self.addFrameLocal(.u64);
        const acc = try self.addFrameLocal(list_layout);
        const initial = try self.addFrameLocal(list_layout);
        const next_acc = try self.addFrameLocal(list_layout);
        if (self.parent.result.store.getLocal(target).boxy_desc) |desc| {
            for ([_]LIR.LocalId{ acc, initial, next_acc }) |local| self.parent.result.store.setLocalBoxyDesc(local, desc);
        }
        const len = try self.addFrameLocal(.u64);
        const zero = try self.addFrameLocal(.u64);
        const one = try self.addFrameLocal(.u64);
        const next_index = try self.addFrameLocal(.u64);
        const done = try self.addFrameLocal(.bool);
        const item = try self.addFrameLocalForRep(source_rep);
        const stored = try self.addFrameLocal(target_layout);
        const join_id = self.freshJoinPointId();
        var step = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, self.scaffoldOrigin());
        step = try self.setLocalInitializeJoinParam(acc, next_acc, step);
        step = try self.setLocalInitializeJoinParam(index, next_index, step);
        step = try self.assignListAppendMovingElement(next_acc, acc, stored, step);
        step = try self.assignRepresentationBoundary(stored, item, target_rep, source_rep, step);
        if (!self.isZstLocal(item)) step = try self.assignBinaryLowLevel(item, .list_get_unsafe, source, index, step);
        step = try self.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, step);
        const finish = try self.assignLocal(target, acc, after);
        const choose = try self.boolSwitchNoContinuation(done, finish, step);
        const body = try self.assignBinaryLowLevel(done, .num_is_eq, index, len, choose);
        var initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, self.scaffoldOrigin());
        initial_jump = try self.setLocalInitializeJoinParam(acc, initial, initial_jump);
        initial_jump = try self.setLocalInitializeJoinParam(index, zero, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(initial, .list_with_capacity, len, initial_jump);
        initial_jump = try self.assignU64Literal(len, data.len, initial_jump);
        initial_jump = try self.assignU64Literal(one, 1, initial_jump);
        initial_jump = try self.assignU64Literal(zero, 0, initial_jump);
        initial_jump = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{ .target = source, .value = .{ .bytes_literal = literal }, .next = initial_jump } }, self.scaffoldOrigin());
        return try self.parent.result.store.addCFStmt(.{ .join = .{ .id = join_id, .params = try self.joinParamSpan(&.{ index, acc }), .body = body, .remainder = initial_jump } }, self.scaffoldOrigin());
    }

    fn beginRestoreConstFnValue(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        store_module: ProcedureModuleView,
        type_module: ProcedureModuleView,
        fn_id: checked.ConstFnId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const requested_rep = self.repForModuleType(type_module, checked_ty);
        const callable = self.functionChildrenForRep(requested_rep) orelse
            boxyLowerInvariant("ConstStore function value had a non-callable requested representation");
        var planned: ?Plan.StaticFnPlan = null;
        for (self.parent.plan.static_fns.items) |candidate| {
            if (candidate.fn_id != fn_id) continue;
            if (!checked_moduleKeyEqual(candidate.store_module, store_module.key)) continue;
            if (candidate.rep != callable.rep) continue;
            if (planned != null) boxyLowerInvariant("ConstStore function value matched duplicate exact static plans");
            planned = candidate;
        }
        const static_fn = planned orelse
            boxyLowerInvariant("ConstStore function value had no producer-selected static plan");
        const worker = self.parent.plan.workers.items[@backingInt(static_fn.worker)];
        const callable_target = if (static_fn.rep == requested_rep)
            target
        else
            try self.addFrameLocalForRep(static_fn.rep);
        const continuation = if (static_fn.rep == requested_rep)
            next
        else
            try self.assignRepresentationBoundary(
                target,
                callable_target,
                requested_rep,
                static_fn.rep,
                next,
            );
        return try self.beginWorkerValueWithValueRep(
            callable_target,
            worker.checked_type,
            static_fn.rep,
            worker.source,
            null,
            self.parent.plan.storedCallableCaptureSourceSlice(static_fn.capture_sources),
            self.staticFnHiddenDescArgs(static_fn),
            self.parent.plan.directCallHiddenDictionaryArgSlice(static_fn.hidden_dict_args),
            continuation,
        );
    }

    fn staticFnHiddenDescArgs(self: *const ProcBodyBuilder, static_fn: Plan.StaticFnPlan) ?[]const Plan.DirectCallHiddenDescriptorArg {
        if (static_fn.hidden_desc_args.len == 0) return null;
        return self.parent.plan.directCallHiddenDescriptorArgSlice(static_fn.hidden_desc_args);
    }

    /// Emit the boxy box that moves a restored element `source` (in its source
    /// representation) into the list element slot `elem_local`, tagging the
    /// slot with `source_elem_rep`'s runtime descriptor.
    fn prependConstListElementBox(
        self: *ProcBodyBuilder,
        elem_local: LIR.LocalId,
        source: LIR.LocalId,
        source_elem_rep: Plan.TypeRepId,
        continuation: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const payload_desc = try self.descriptorRefForKnownRep(source_elem_rep);
        self.parent.result.store.setLocalBoxyDesc(elem_local, payload_desc);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
            .target = elem_local,
            .payload = source,
            .payload_layout = self.parent.result.store.getLocal(source).layout_idx,
            .payload_desc = payload_desc,
            .payload_mode = .move,
            .next = continuation,
        } }, self.scaffoldOrigin());
    }

    fn restoreConstBoolTagInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        tag: anytype,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (tag.payloads.len != 0) {
            boxyLowerInvariant("ConstStore Bool tag carried a payload");
        }
        if (std.mem.eql(u8, tag.tag_name, "False")) return try self.assignBoolLiteral(target, false, next);
        if (std.mem.eql(u8, tag.tag_name, "True")) return try self.assignBoolLiteral(target, true, next);
        boxyLowerInvariant("ConstStore Bool tag had a non-Bool name");
    }

    fn beginCallableExpr(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const expr = self.module.checked_bodies.expr(expr_id);
        return try self.beginCallableExprTypeRef(target, .{ .module = self.module.key, .ty = expr.ty }, expr_id, next);
    }

    fn beginCallableExprTypeRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        checked_type: Plan.CheckedTypeIdentity,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const source = self.workerSourceForCallableExpr(expr_id);
        const expr = self.module.checked_bodies.expr(expr_id);
        const nested_use = self.parent.plan.nestedCallableUsePlan(
            .{ .module = self.module.key, .expr = expr_id },
            self.worker_layout.worker,
            checked_type,
        );
        const hidden_dict_args = if (nested_use) |use|
            self.parent.plan.directCallHiddenDictionaryArgSlice(use.hidden_dict_args)
        else
            null;
        const hidden_desc_args = if (nested_use) |use|
            self.parent.plan.directCallHiddenDescriptorArgSlice(use.hidden_desc_args)
        else
            null;
        return try self.beginWorkerValueWithCallDictionaryArgs(
            target,
            .{ .module = self.module.key, .ty = expr.ty },
            checked_type,
            source,
            expr_id,
            &.{},
            hidden_desc_args,
            hidden_dict_args,
            next,
        );
    }

    fn nestedCallableUseTypeForCurrentWorker(self: *ProcBodyBuilder, expr_id: checked.CheckedExprId) Allocator.Error!?Plan.CheckedTypeIdentity {
        const source = self.workerSourceForCallableExpr(expr_id);
        const worker = self.parent.plan.workerForSourceType(source, .{ .module = self.module.key, .ty = self.module.checked_bodies.expr(expr_id).ty }) orelse return null;
        const worker_plan = self.parent.plan.workers.items[@backingInt(worker)];
        const captures = self.parent.plan.erasedCaptureSlice(worker_plan.erased_captures);
        const use_ref = Plan.CheckedExprIdentity{ .module = self.module.key, .expr = expr_id };

        var found: ?Plan.CheckedTypeIdentity = null;
        for (self.parent.plan.nested_callable_uses.items) |use| {
            if (use.worker != worker or
                use.caller != self.worker_layout.worker or
                !planExprRefEql(use.use, use_ref))
            {
                continue;
            }
            if (!try self.nestedCallableUseCanMaterializeDictionaries(worker, use, captures)) continue;
            if (found) |existing| {
                if (!planTypeRefEql(existing, use.callable_ty)) return null;
                continue;
            }
            found = use.callable_ty;
        }
        return found;
    }

    fn nestedCallableUseCanMaterializeDictionaries(
        self: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        use: Plan.NestedCallableUsePlan,
        captures: []const Plan.ErasedCapture,
    ) Allocator.Error!bool {
        const value_function = self.functionChildrenForRep(self.repForTypeRef(use.callable_ty)) orelse
            boxyLowerInvariant("boxy nested callable use type was not a function representation");
        const capture_desc_sources = try self.erasedCaptureDescriptorSourcesForFunctionUse(
            worker_id,
            captures,
            self.parent.plan.directCallHiddenDescriptorArgSlice(use.hidden_desc_args),
        );
        defer self.parent.allocator.free(capture_desc_sources);
        const planned_dict_args = self.parent.plan.directCallHiddenDictionaryArgSlice(use.hidden_dict_args);
        const capture_dict_reps = try self.erasedCaptureDictionaryRepsForFunctionUse(worker_id, value_function, captures, planned_dict_args.len);
        defer self.parent.allocator.free(capture_dict_reps);
        var planned_dict_index = planned_dict_args.len;

        for (captures, capture_desc_sources, capture_dict_reps) |capture, desc_source, dict_rep| {
            switch (capture.kind) {
                .hidden_desc => if (!try self.canMaterializeDescriptorRefForKnownRep(desc_source.rep)) return false,
                .hidden_dict, .hidden_literal => {
                    if (planned_dict_index != 0) {
                        planned_dict_index -= 1;
                    } else if (!self.canMaterializeDictionaryRefForKnownRep(dict_rep, capture.dictionaries)) {
                        return false;
                    }
                },
                .captured_value => {},
            }
        }
        if (planned_dict_index != 0) {
            boxyLowerInvariant("boxy nested callable use planned more dictionaries than its erased worker captures");
        }
        return true;
    }

    /// Whether this frame can describe `rep_id`: through its bound descriptor,
    /// or, for a representation built from others, through a template whose
    /// type-variable leaves are each bound or sealed to their default.
    fn canMaterializeDescriptorRefForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!bool {
        var visited = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer visited.deinit();
        return try self.canMaterializeDescriptorRefForKnownRepVisited(rep_id, &visited);
    }

    /// Whether every descriptor `root` reaches can be materialized here.
    /// Which representations are reached does not depend on visiting order.
    fn canMaterializeDescriptorRefForKnownRepVisited(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        visited: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |rep_id| {
            const identity_rep = self.descriptorStorageRep(rep_id);
            if ((try visited.getOrPut(identity_rep)).found_existing) continue;
            const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
            const desc = rep.descriptor orelse continue;
            if (self.descriptorBindingIsBoundForRep(identity_rep) and self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep) != null) continue;
            if (rep.kind == .dynamic and rep.children.len == 0 and rep.tag_variants.len == 0) {
                if (rep.sealed_default == null) return false;
                continue;
            }
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (self.parent.plan.childIsSharedBackingTemplate(identity_rep, child)) continue;
                try pending.append(allocator, child.rep);
            }
        }
        return true;
    }

    fn canMaterializeDictionaryRefForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
    ) bool {
        const identity_rep = self.dictionaryIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.dictionaries.len != 0) {
            const first: Plan.DictionaryRequirementId = @fromBackingInt(@intCast(rep.dictionaries.start));
            if (self.dictionaryBindingIsBound(first)) {
                return self.dictionaryLocalForRequirementOrNull(first) != null;
            }
        }
        if (rep.kind != .dynamic) return true;
        if (worker_dictionaries.len == 0) return false;
        const first: Plan.DictionaryRequirementId = @fromBackingInt(@intCast(worker_dictionaries.start));
        return self.dictionaryBindingIsBound(first) and self.dictionaryLocalForRequirementOrNull(first) != null;
    }

    fn beginProcedureValueRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        checked_ty: checked.CheckedTypeId,
        _: checked.ResolvedValueRefId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        return try self.beginProcedureValueRefTypeRef(
            target,
            expr_id,
            .{ .module = self.module.key, .ty = checked_ty },
            next,
        );
    }

    fn beginProcedureValueRefTypeRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        call_type: Plan.CheckedTypeIdentity,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const use_ref = Plan.CheckedExprIdentity{ .module = self.module.key, .expr = expr_id };
        // A use of a pending callable-eval binding calls the binding's
        // producer, which yields the callable value.
        if (self.parent.plan.directCallPlanForCall(use_ref, self.worker_layout.worker)) |producer_call| {
            if (!checked_moduleKeyEqual(call_type.module, self.module.key)) {
                boxyLowerInvariant("boxy producer call type was not owned by the calling module");
            }
            return .{ .tail = .{ .planned_call = .{
                .target = target,
                .target_rep = self.repForTypeRef(call_type),
                .checked_ret_ty = call_type.ty,
                .direct_plan = producer_call,
                .next = next,
            } } };
        }
        const use = self.parent.plan.callableUsePlan(use_ref, self.worker_layout.worker) orelse
            boxyLowerInvariant("checked procedure lookup reached boxy lowering without a callable use plan");
        const worker = self.parent.plan.workers.items[@backingInt(use.worker)];
        const hidden_desc_args = self.parent.plan.directCallHiddenDescriptorArgSlice(use.hidden_desc_args);
        const hidden_dict_args = self.parent.plan.directCallHiddenDictionaryArgSlice(use.hidden_dict_args);
        return try self.beginWorkerValueWithCallDictionaryArgs(
            target,
            worker.checked_type,
            call_type,
            worker.source,
            null,
            self.parent.plan.storedCallableCaptureSourceSlice(use.stored_capture_sources),
            hidden_desc_args,
            hidden_dict_args,
            next,
        );
    }

    fn procedureValueRefForExpr(
        self: *ProcBodyBuilder,
        expr: checked.CheckedExpr,
    ) ?checked.ResolvedValueRefId {
        const maybe_ref = switch (expr.data) {
            .lookup_local => |lookup| lookup.resolved,
            .lookup_external, .lookup_required => |ref_id| ref_id,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return null,
        };
        const ref_id = maybe_ref orelse return null;
        return switch (self.resolvedValueRecord(ref_id).ref) {
            .local_proc,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_proc,
            .promoted_top_level_proc,
            => ref_id,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => null,
        };
    }

    /// An erased callable adapter a raw worker value continues into once the
    /// value is built: the adapter replaces the placeholder the value's
    /// statements continue into.
    const CallableAdapterBoundary = struct {
        target: LIR.LocalId,
        raw_target: LIR.LocalId,
        value_function: FunctionChildren,
        worker_function: FunctionChildren,
        hidden_desc_args: []const Plan.DirectCallHiddenDescriptorArg,
        next: LIR.CFStmtId,
        placeholder: LIR.CFStmtId,
    };

    fn finishCallableAdapterBoundary(self: *ProcBodyBuilder, adapter: CallableAdapterBoundary) Allocator.Error!void {
        const enclosing_call_boundary_substitution = self.call_boundary_substitution;
        self.call_boundary_substitution = adapter.hidden_desc_args;
        defer self.call_boundary_substitution = enclosing_call_boundary_substitution;
        const adapted = try self.assignErasedCallableBoundary(
            adapter.target,
            adapter.raw_target,
            adapter.value_function,
            adapter.worker_function,
            adapter.next,
        );
        try self.parent.result.store.replaceCFStmt(adapter.placeholder, self.parent.result.store.getCFStmt(adapted), self.parent.result.store.stmtOrigin(adapted));
    }

    fn beginWorkerValueWithCallDictionaryArgs(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        worker_type: Plan.CheckedTypeIdentity,
        call_type: Plan.CheckedTypeIdentity,
        source: Plan.WorkerSource,
        maybe_expr: ?checked.CheckedExprId,
        stored_capture_sources: []const Plan.StoredCallableCaptureSource,
        hidden_desc_args: ?[]const Plan.DirectCallHiddenDescriptorArg,
        hidden_dict_args: ?[]const Plan.DirectCallHiddenDictionaryArg,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        return try self.beginWorkerValueWithValueRep(target, worker_type, self.repForTypeRef(call_type), source, maybe_expr, stored_capture_sources, hidden_desc_args, hidden_dict_args, next);
    }

    fn beginWorkerValueWithValueRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        worker_type: Plan.CheckedTypeIdentity,
        value_rep: Plan.TypeRepId,
        source: Plan.WorkerSource,
        maybe_expr: ?checked.CheckedExprId,
        stored_capture_sources: []const Plan.StoredCallableCaptureSource,
        hidden_desc_args: ?[]const Plan.DirectCallHiddenDescriptorArg,
        hidden_dict_args: ?[]const Plan.DirectCallHiddenDictionaryArg,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const worker_id = self.parent.plan.workerForSourceType(source, worker_type) orelse
            boxyLowerInvariant("planned callable value had no worker for its source type");
        const worker = self.parent.plan.workers.items[@backingInt(worker_id)];
        const value_function = self.functionChildrenForRep(value_rep) orelse
            boxyLowerInvariant("boxy callable value type was not an erased-callable representation");
        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy callable worker was not an erased-callable representation");
        if (try self.callableBoundaryNeedsAdapter(value_function, worker_function)) {
            const raw_target = try self.addFrameLocalForRep(worker_function.rep);
            const boundary_placeholder = try self.parent.result.store.addCFStmt(.runtime_error, self.origin);
            return try self.beginRawWorkerValue(
                raw_target,
                source,
                maybe_expr,
                stored_capture_sources,
                worker_id,
                value_function,
                hidden_desc_args,
                hidden_dict_args,
                boundary_placeholder,
                .{
                    .target = target,
                    .raw_target = raw_target,
                    .value_function = value_function,
                    .worker_function = worker_function,
                    .hidden_desc_args = hidden_desc_args orelse &.{},
                    .next = next,
                    .placeholder = boundary_placeholder,
                },
            );
        }

        return try self.beginRawWorkerValue(target, source, maybe_expr, stored_capture_sources, worker_id, value_function, hidden_desc_args, hidden_dict_args, next, null);
    }

    fn beginRawWorkerValue(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: Plan.WorkerSource,
        maybe_expr: ?checked.CheckedExprId,
        stored_capture_sources: []const Plan.StoredCallableCaptureSource,
        worker_id: Plan.WorkerPlanId,
        value_function: FunctionChildren,
        hidden_desc_args: ?[]const Plan.DirectCallHiddenDescriptorArg,
        hidden_dict_args: ?[]const Plan.DirectCallHiddenDictionaryArg,
        next: LIR.CFStmtId,
        adapter: ?CallableAdapterBoundary,
    ) Allocator.Error!ExprStep {
        const erased_proc = try self.parent.reserveErasedWorkerProc(worker_id);
        const worker = self.parent.plan.workers.items[@backingInt(worker_id)];
        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy raw callable worker was not an erased-callable representation");
        const worker_layout = self.parent.layout_plan.workerLayoutFor(worker_id);
        const captures = self.parent.plan.erasedCaptureSlice(worker.erased_captures);
        const capture_desc_sources = try self.erasedCaptureDescriptorSourcesForFunctionUse(
            worker_id,
            captures,
            hidden_desc_args orelse &.{},
        );
        defer self.parent.allocator.free(capture_desc_sources);
        const capture_dict_reps = try self.erasedCaptureDictionaryRepsForFunctionUse(worker_id, value_function, captures, if (hidden_dict_args) |args| args.len else 0);
        defer self.parent.allocator.free(capture_dict_reps);
        var result_desc_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer result_desc_initializers.deinit(self.parent.allocator);
        var stored_capture_initializers = std.ArrayList(StoredCallableCaptureInitializer).empty;
        defer stored_capture_initializers.deinit(self.parent.allocator);

        if (captures.len == 0) {
            try self.parent.recordFrozenCallable(worker_id, null, worker_function.rep, worker_function.rep, erased_proc, .zst, .none, worker_function.ret, &.{});
            const result_desc = try self.exactCallResultDescriptorRef(worker_function.ret);
            try self.appendResultDescriptorInitializers(&result_desc_initializers, result_desc);
            if (result_desc_initializers.items.len != 0) {
                boxyLowerInvariant("zero-capture erased callable result descriptor unexpectedly needed runtime captures");
            }
            const stmt = try self.parent.result.store.addCFStmt(.{ .assign_packed_erased_fn = .{
                .target = target,
                .proc = erased_proc,
                .capture = null,
                .capture_layout = null,
                .on_drop = .none,
                .result_desc = result_desc.desc,
                .next = next,
            } }, self.origin);
            if (adapter) |boundary| try self.finishCallableAdapterBoundary(boundary);
            return exprDone(stmt);
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, captures.len);
        defer self.parent.allocator.free(field_locals);
        var source_capture_index: usize = 0;
        const source_captures = self.callableValueSourceCaptures(source, maybe_expr);

        for (captures, field_locals) |capture, *field_local| {
            switch (capture.kind) {
                .captured_value => {
                    if (stored_capture_sources.len != 0) {
                        const capture_id = capture.capture_id orelse
                            boxyLowerInvariant("stored callable value capture had no checked capture id");
                        var planned_source: ?Plan.StoredCallableCaptureSource.Source = null;
                        for (stored_capture_sources) |candidate| {
                            if (std.meta.eql(candidate.capture_id, capture_id)) {
                                planned_source = candidate.source;
                                break;
                            }
                        }
                        const capture_source = planned_source orelse
                            boxyLowerInvariant("stored callable capture had no producer-selected value source");
                        const stored_rep = switch (capture_source) {
                            .const_node => |stored| self.parent.plan.repForStoredType(.{
                                .module = stored.store_module,
                                .ty = stored.stored_type,
                            }) orelse boxyLowerInvariant("stored callable capture type was missing from the boxy representation plan"),
                            .checked_expr => null,
                        };
                        field_local.* = try self.addFrameBoundaryTargetLocalForRep(capture.rep);
                        try stored_capture_initializers.append(self.parent.allocator, .{
                            .local = field_local.*,
                            .source_type = capture.source_type,
                            .target_rep = capture.rep,
                            .stored_rep = stored_rep,
                            .source = capture_source,
                        });
                    } else {
                        if (source_capture_index >= source_captures.len) {
                            boxyLowerInvariant("boxy callable capture plan had more value captures than the source closure");
                        }
                        const source_capture = source_captures[source_capture_index];
                        field_local.* = if (capture.recursive_slot)
                            self.recursive_value_slots.get(source_capture.capture_id.binder()) orelse boxyLowerInvariant("recursive value capture had no reserved slot")
                        else
                            self.sourceCaptureLocal(source, maybe_expr, source_capture_index, source_capture);
                        source_capture_index += 1;
                    }
                },
                .hidden_desc => {
                    const desc_local = try self.addFrameLocal(.opaque_ptr);
                    field_local.* = desc_local;
                },
                .hidden_dict, .hidden_literal => {
                    const dict_local = try self.addFrameLocal(.opaque_ptr);
                    field_local.* = dict_local;
                },
            }
        }
        if (stored_capture_sources.len != 0) {
            if (stored_capture_initializers.items.len != stored_capture_sources.len) {
                boxyLowerInvariant("stored callable capture plan did not cover every producer-selected source");
            }
        } else if (source_capture_index != source_captures.len) {
            boxyLowerInvariant("boxy callable capture plan did not cover every source closure capture");
        }

        var descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.parent.allocator);
        const field_desc_overrides = try self.parent.allocator.alloc(?LIR.BoxyDescRef, captures.len);
        defer self.parent.allocator.free(field_desc_overrides);
        @memset(field_desc_overrides, null);
        const descriptor_snapshot = try self.snapshotDescriptorBindings();
        var snapshot_moved = false;
        defer if (!snapshot_moved) {
            self.restoreDescriptorBindings(descriptor_snapshot);
            descriptor_snapshot.deinit(self.parent.allocator);
        };

        const hidden_desc_initializers = try self.parent.allocator.alloc(?DescriptorArgLocal, captures.len);
        defer self.parent.allocator.free(hidden_desc_initializers);
        @memset(hidden_desc_initializers, null);
        // Each planned source is described by the enclosing frame.
        for (captures, field_locals, capture_desc_sources, hidden_desc_initializers) |capture, field_local, desc_source, *hidden_desc_initializer| {
            if (capture.kind != .hidden_desc) continue;
            const materialization = try self.descriptorMaterializationForSourceRep(desc_source.rep);
            hidden_desc_initializer.* = materialization.initializer(field_local);
        }

        // Each hidden descriptor field copies a descriptor from the enclosing
        // environment, so its initializer is chosen before the field locals
        // describe those representations inside this capture window.
        try self.bindErasedCaptureDescriptorFieldLocals(captures, field_locals, capture_desc_sources);
        for (captures, capture_desc_sources) |capture, desc_source| {
            if (capture.kind != .hidden_desc) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("boxy hidden descriptor erased capture had no descriptor requirement");
            self.markDescriptorRequirementBoundForRep(desc, capture.rep);
            self.markDescriptorRequirementBoundForRep(desc, desc_source.rep);
        }

        try self.prepareErasedPackedCapturedValueFieldDescriptors(
            captures,
            field_locals,
            &descriptor_initializers,
            field_desc_overrides,
        );
        try self.prepareErasedCapturedValueFieldDescriptors(
            captures,
            field_locals,
            &descriptor_initializers,
            .snapshot_existing,
            field_desc_overrides,
        );
        var hidden_desc_field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer hidden_desc_field_initializers.deinit(self.parent.allocator);
        for (hidden_desc_initializers) |maybe_initializer| {
            if (maybe_initializer) |initializer| {
                try hidden_desc_field_initializers.append(self.parent.allocator, initializer);
            }
        }

        const needs_capture_contents_desc = self.erasedCaptureNeedsContentsDescriptor(captures, field_locals);
        const capture_layout = if (needs_capture_contents_desc)
            try self.erasedCaptureLayoutWithOnDropDescriptor(worker_layout.erased_capture_layout, captures.len)
        else
            worker_layout.erased_capture_layout;
        const capture_local = try self.addFrameLocal(capture_layout);

        var capture_desc_initializer: ?DescriptorArgLocal = null;
        const capture_contents_desc = if (needs_capture_contents_desc) blk: {
            const materialization = try self.erasedCaptureContentsDescriptorMaterialization(captures, field_locals, field_desc_overrides, capture_layout) orelse
                boxyLowerInvariant("boxy erased capture descriptor need disappeared during materialization");
            const desc_local = try self.addFrameLocal(.opaque_ptr);
            const desc_ref = LIR.BoxyDescRef{ .local = desc_local };
            self.parent.result.store.setLocalBoxyDesc(capture_local, desc_ref);
            capture_desc_initializer = materialization.initializer(desc_local);
            break :blk desc_ref;
        } else null;
        const capture_fields = if (capture_desc_initializer) |initializer| blk: {
            const fields = try self.parent.allocator.alloc(LIR.LocalId, captures.len + 1);
            @memcpy(fields[0..captures.len], field_locals);
            fields[captures.len] = initializer.local;
            break :blk fields;
        } else field_locals;
        defer if (capture_fields.ptr != field_locals.ptr) self.parent.allocator.free(capture_fields);

        const on_drop: LIR.ErasedCallableOnDrop = if (capture_desc_initializer != null) blk: {
            const capture_layout_value = self.parent.result.layouts.getLayout(capture_layout);
            if (capture_layout_value.tag != .struct_) {
                boxyLowerInvariant("boxy erased capture descriptor field expected struct capture layout");
            }
            const desc_field_offset = self.parent.result.layouts.getStructFieldOffsetByOriginalIndex(capture_layout_value.getStruct().idx, @intCast(captures.len));
            break :blk .{ .boxy_capture = .{
                .capture_layout = capture_layout,
                .desc_field_offset = desc_field_offset,
            } };
        } else self.erasedCallableOnDrop(capture_layout);

        const result_desc = self.erasedCallableResultDescriptorFromCaptures(
            worker_function.ret,
            captures,
            field_locals,
        ) orelse try self.exactCallResultDescriptorRef(worker_function.ret);
        try self.appendResultDescriptorInitializers(&result_desc_initializers, result_desc);

        if (self.parent.needsFrozenCallableRecipes()) {
            const fields = try self.parent.allocator.alloc(ProcedureBuilder.FrozenCaptureRecipe, captures.len);
            defer self.parent.allocator.free(fields);
            for (captures, capture_desc_sources, hidden_desc_initializers, fields) |capture, desc_source, hidden_desc_initializer, *field| {
                field.* = switch (capture.kind) {
                    .captured_value => .{ .value = capture.rep },
                    .hidden_desc => .{ .descriptor = .{
                        .worker_rep = capture.rep,
                        .source_rep = desc_source.rep,
                        .exact = if (hidden_desc_initializer) |initializer| if (initializer.materialize) |materialize| switch (materialize) {
                            .static => |id| if (initializer.captures.len == 0) id else null,
                            .local, .runtime, .dict_method_arg, .dict_method_hidden => null,
                        } else null else null,
                    } },
                    .hidden_dict => .{ .dictionary = capture.dictionaries },
                    .hidden_literal => .{ .literal = capture.literal_parameter.? },
                };
            }
            try self.parent.recordFrozenCallable(worker_id, null, worker_function.rep, worker_function.rep, erased_proc, capture_layout, on_drop, worker_function.ret, fields);
        }

        const assign = try self.parent.result.store.addCFStmt(.{ .assign_packed_erased_fn = .{
            .target = target,
            .proc = erased_proc,
            .capture = capture_local,
            .capture_layout = capture_layout,
            .on_drop = on_drop,
            .result_desc = result_desc.desc,
            .next = next,
        } }, self.origin);

        var continuation = if (self.isZstLocal(capture_local))
            try self.assignZst(capture_local, assign)
        else
            try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
                .target = capture_local,
                .fields = try self.parent.result.store.addLocalSpan(capture_fields),
                .contents_desc = capture_contents_desc,
                .next = assign,
            } }, self.origin);
        continuation = try self.prependDescriptorArgMaterializations(result_desc_initializers.items, continuation);
        continuation = try self.prependOptionalDescriptorMaterialization(capture_desc_initializer, continuation);

        // A capture's dictionaries are resolved inside this capture window,
        // where they can name its hidden descriptor fields, so they run after
        // those fields' initializers.
        var hidden_dict_index = if (hidden_dict_args) |args| args.len else 0;
        var index = captures.len;
        while (index > 0) {
            index -= 1;
            if (captures[index].kind == .hidden_dict or captures[index].kind == .hidden_literal) {
                const planned_arg = if (hidden_dict_args) |args| blk: {
                    if (hidden_dict_index == 0) {
                        boxyLowerInvariant("boxy callable use planned fewer dictionaries than its erased worker captures");
                    }
                    hidden_dict_index -= 1;
                    break :blk args[hidden_dict_index];
                } else null;
                continuation = try self.materializeErasedCaptureDictionary(
                    field_locals[index],
                    captures[index],
                    capture_dict_reps[index],
                    planned_arg,
                    continuation,
                );
            }
        }
        if (hidden_dict_index != 0) {
            boxyLowerInvariant("boxy callable use planned more dictionaries than its erased worker captures");
        }
        continuation = try self.prependDescriptorArgMaterializations(descriptor_initializers.items, continuation);

        // The stored captures are lowered inside this capture window, last
        // first, before the callable's descriptor environment is recorded and
        // the window closes. A hidden descriptor field reads only the
        // enclosing frame, while a stored capture restored inside this capture
        // window is described by those fields, so the fields are initialized
        // first.
        var callable_bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer callable_bindings.deinit(self.parent.allocator);
        for (captures, field_locals, capture_desc_sources) |capture, field_local, desc_source| {
            if (capture.kind != .hidden_desc) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("boxy hidden descriptor erased capture had no descriptor requirement");
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, desc, capture.rep, field_local);
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, desc, desc_source.rep, field_local);
        }
        const stored = stored_capture_initializers.items;
        const items = try self.parent.allocator.alloc(ExprChainItem, stored.len + 3 + @intFromBool(adapter != null));
        var items_owned = true;
        defer if (items_owned) self.parent.allocator.free(items);
        // Only `record_local_env` and this item own memory, and they are set
        // last, so an unfinished `items` owns nothing else.
        const hidden_field_initializers = try self.parent.allocator.dupe(DescriptorArgLocal, hidden_desc_field_initializers.items);
        var hidden_field_initializers_owned = true;
        defer if (hidden_field_initializers_owned) self.parent.allocator.free(hidden_field_initializers);
        for (items[0..stored.len], 0..) |*item, offset| {
            const initializer = stored[stored.len - 1 - offset];
            item.* = switch (initializer.source) {
                .const_node => |const_node| .{ .lower = .{ .stored_across = .{
                    .target = initializer.local,
                    .store_module = procedureModuleById(self.parent.modules, const_node.store_module),
                    .node = const_node.node,
                    .stored_type = const_node.stored_type,
                    .target_rep = initializer.target_rep,
                    .stored_rep = initializer.stored_rep orelse
                        boxyLowerInvariant("stored callable capture initializer had no stored representation"),
                    .next = undefined,
                } } },
                .checked_expr => |expr| blk: {
                    if (!checked_moduleKeyEqual(expr.module, self.module.key)) {
                        boxyLowerInvariant("stored callable checked capture expression belonged to a different lowering module");
                    }
                    break :blk .{ .lower = .{ .expected_ref = .{
                        .target = initializer.local,
                        .expected_ty = initializer.source_type,
                        .expr_id = expr.expr,
                        .next = undefined,
                    } } };
                },
            };
        }
        items[stored.len + 1] = .{ .record_local_env = .{
            .target = target,
            .rep = worker_function.rep,
            .bindings = try callable_bindings.toOwnedSlice(self.parent.allocator),
        } };
        items[stored.len] = .{ .prepend_descriptor_initializers = hidden_field_initializers };
        hidden_field_initializers_owned = false;
        items[stored.len + 2] = .restore_descriptors;
        if (adapter) |boundary| items[stored.len + 3] = .{ .callable_adapter = boundary };
        items_owned = false;
        snapshot_moved = true;
        return .{ .tail = .{ .chain = .{ .items = items, .current = continuation, .snapshot = descriptor_snapshot } } };
    }

    fn erasedCallableResultDescriptorFromCaptures(
        self: *const ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
        captures: []const Plan.ErasedCapture,
        field_locals: []const LIR.LocalId,
    ) ?ResultDescriptorSource {
        if (captures.len != field_locals.len) {
            boxyLowerInvariant("boxy erased callable result descriptor saw mismatched capture fields");
        }
        const identity_result = self.descriptorStorageRep(result_rep);
        const result_desc = self.parent.plan.representations.items[@backingInt(identity_result)].descriptor orelse return null;
        var found: ?LIR.LocalId = null;
        for (captures, field_locals) |capture, field_local| {
            if (capture.kind != .hidden_desc) continue;
            if (capture.desc != result_desc) continue;
            if (found != null) {
                boxyLowerInvariant("boxy erased callable result descriptor had multiple matching captures");
            }
            found = field_local;
        }
        return if (found) |local| .{ .desc = .{ .local = local } } else null;
    }

    fn bindErasedCaptureDescriptorFieldLocals(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        field_locals: []const LIR.LocalId,
        capture_desc_sources: []const ErasedCaptureDescriptorSource,
    ) Allocator.Error!void {
        if (captures.len != field_locals.len or captures.len != capture_desc_sources.len) {
            boxyLowerInvariant("boxy erased capture descriptor bindings saw mismatched capture fields");
        }

        for (captures, field_locals, capture_desc_sources) |capture, local, source| {
            if (capture.kind != .hidden_desc) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("boxy hidden descriptor erased capture had no descriptor requirement");
            try self.setDescriptorRequirementLocalForRep(desc, capture.rep, local);
            try self.setDescriptorRequirementLocalForRep(desc, source.rep, local);
        }
    }

    fn prepareErasedPackedCapturedValueFieldDescriptors(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        field_locals: []const LIR.LocalId,
        initializers: *std.ArrayList(DescriptorArgLocal),
        descriptor_overrides: []?LIR.BoxyDescRef,
    ) Allocator.Error!void {
        if (captures.len != field_locals.len or captures.len != descriptor_overrides.len) {
            boxyLowerInvariant("boxy packed erased capture descriptor environment saw mismatched capture fields");
        }

        for (captures, field_locals, 0..) |capture, field_local, capture_index| {
            if (capture.kind != .captured_value) continue;
            const field_layout = self.parent.result.store.getLocal(field_local).layout_idx;
            if (!self.parent.layoutNeedsNestedBoxyDesc(field_layout)) continue;

            const field_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(capture.rep, field_layout, true) orelse
                boxyLowerInvariant("boxy packed erased capture value descriptor did not match its field layout");

            // A descriptor attached to the captured value describes the value
            // that was actually produced. The callable's hidden root descriptor
            // is only a source when no exact value descriptor is available.
            if (self.parent.result.store.getLocal(field_local).boxy_desc != null) continue;
            if (self.localEnvironmentDescriptorForRep(field_local, field_desc_rep)) |local| {
                descriptor_overrides[capture_index] = .{ .local = local };
                continue;
            }

            var root_desc: ?LIR.BoxyDescRef = null;
            for (captures, field_locals) |candidate, candidate_local| {
                if (candidate.kind != .hidden_desc) continue;
                const desc = candidate.desc orelse
                    boxyLowerInvariant("boxy hidden descriptor capture had no descriptor requirement");
                if (!self.repOwnsShapeDescriptor(capture.rep, desc)) continue;
                if (self.descriptorStorageRep(candidate.rep) != self.descriptorStorageRep(capture.rep)) continue;
                if (root_desc != null) {
                    boxyLowerInvariant("boxy packed erased captured value had multiple root descriptor captures");
                }
                root_desc = .{ .local = candidate_local };
            }
            const desc_ref = root_desc orelse continue;

            var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
            defer bindings.deinit(self.parent.allocator);
            var projected = std.ArrayList(DescriptorArgLocal).empty;
            defer projected.deinit(self.parent.allocator);
            var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer seen.deinit();
            try self.collectShapeDescriptorEnvironmentForRep(
                capture.rep,
                desc_ref,
                &bindings,
                &projected,
                &seen,
            );

            const identity_field_desc_rep = self.descriptorStorageRep(field_desc_rep);
            const field_desc = self.parent.plan.representations.items[@backingInt(identity_field_desc_rep)].descriptor orelse
                boxyLowerInvariant("boxy packed erased capture field descriptor had no requirement");
            var field_desc_local: ?LIR.LocalId = null;
            for (bindings.items) |binding| {
                if (binding.desc != field_desc) continue;
                if (self.descriptorStorageRep(binding.rep) != identity_field_desc_rep) continue;
                if (field_desc_local != null and field_desc_local.? != binding.local) {
                    boxyLowerInvariant("boxy packed erased capture field had multiple exact descriptors");
                }
                field_desc_local = binding.local;
            }
            descriptor_overrides[capture_index] = .{ .local = field_desc_local orelse
                boxyLowerInvariant("boxy packed erased capture root descriptor did not cover its stored field") };
            try initializers.appendSlice(self.parent.allocator, projected.items);
        }
    }

    fn prepareErasedCapturedValueFieldDescriptors(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        field_locals: []const LIR.LocalId,
        initializers: *std.ArrayList(DescriptorArgLocal),
        mode: ErasedCaptureDescriptorMode,
        descriptor_overrides: ?[]?LIR.BoxyDescRef,
    ) Allocator.Error!void {
        if (captures.len != field_locals.len) {
            boxyLowerInvariant("boxy erased capture value descriptors saw mismatched capture fields");
        }
        if (descriptor_overrides) |overrides| {
            if (overrides.len != captures.len) {
                boxyLowerInvariant("boxy erased capture descriptor overrides saw mismatched capture fields");
            }
        }

        for (captures, field_locals, 0..) |capture, field_local, index| {
            if (capture.kind != .captured_value) continue;
            if (descriptor_overrides) |overrides| {
                if (overrides[index] != null) continue;
            }

            const field_layout = self.parent.result.store.getLocal(field_local).layout_idx;
            if (!self.parent.layoutNeedsNestedBoxyDesc(field_layout)) continue;

            if (self.parent.result.store.getLocal(field_local).boxy_desc) |existing| {
                switch (mode) {
                    .reuse_existing => continue,
                    .snapshot_existing => {
                        if (existing.localOrNull() != null) {
                            const desc_local = try self.addFrameLocal(.opaque_ptr);
                            try initializers.append(self.parent.allocator, .{
                                .local = desc_local,
                                .materialize = existing,
                            });
                            descriptor_overrides.?[index] = .{ .local = desc_local };
                        } else {
                            descriptor_overrides.?[index] = existing;
                        }
                    },
                }
                continue;
            }

            const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(capture.rep, field_layout, true) orelse
                boxyLowerInvariant("boxy erased capture value descriptor did not match capture field layout");
            const materialization = try self.descriptorMaterializationForSourceRep(desc_rep);
            if (materialization.captures.len == 0) {
                switch (mode) {
                    .reuse_existing => self.parent.result.store.setLocalBoxyDesc(field_local, materialization.desc),
                    .snapshot_existing => descriptor_overrides.?[index] = materialization.desc,
                }
                continue;
            }

            const desc_local = try self.addFrameLocal(.opaque_ptr);
            switch (mode) {
                .reuse_existing => self.parent.result.store.setLocalBoxyDesc(field_local, .{ .local = desc_local }),
                .snapshot_existing => descriptor_overrides.?[index] = .{ .local = desc_local },
            }
            try initializers.append(self.parent.allocator, materialization.initializer(desc_local));
        }
    }

    fn erasedCaptureContentsDescriptorMaterialization(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        field_locals: []const LIR.LocalId,
        descriptor_overrides: []const ?LIR.BoxyDescRef,
        capture_layout: layout.Idx,
    ) Allocator.Error!?DescriptorMaterialization {
        if (captures.len != field_locals.len or captures.len != descriptor_overrides.len) {
            boxyLowerInvariant("boxy erased capture descriptor saw mismatched capture fields");
        }

        var refs = std.ArrayList(LIR.BoxyDescRef).empty;
        defer refs.deinit(self.parent.allocator);
        var desc_captures = std.ArrayList(LIR.LocalId).empty;
        defer desc_captures.deinit(self.parent.allocator);

        if (!self.erasedCaptureNeedsContentsDescriptor(captures, field_locals)) return null;

        // The capture struct stores one field per capture followed by this
        // descriptor's own pointer, and its descriptor describes every field.
        for (captures, field_locals, descriptor_overrides) |capture, field_local, override| {
            const field_layout = self.parent.result.store.getLocal(field_local).layout_idx;
            const field_desc = switch (capture.kind) {
                .captured_value => override orelse if (self.parent.layoutNeedsNestedBoxyDesc(field_layout))
                    try self.descriptorRefForSourceStorageLocalRep(field_local, capture.rep)
                else
                    // A value whose layout carries no runtime descriptor has a
                    // statically known identity.
                    try self.descriptorRefForKnownRep(self.parent.tagPayloadStorageDescRepForLayout(capture.rep, field_layout, true) orelse
                        boxyLowerInvariant("forced capture descriptor representation was not selected")),
                .hidden_desc, .hidden_dict, .hidden_literal => LIR.BoxyDescRef{ .static = try self.parent.internalPointerTypeDesc() },
            };
            if (field_desc.localOrNull()) |local| {
                try appendUniqueLocal(self.parent.allocator, &desc_captures, local);
            }
            try refs.append(self.parent.allocator, field_desc);
        }
        try refs.append(self.parent.allocator, .{ .static = try self.parent.internalPointerTypeDesc() });

        const layout_value = self.parent.result.layouts.getLayout(capture_layout);
        if (layout_value.tag != .struct_ or
            self.parent.result.layouts.getStructData(layout_value.getStruct().idx).fields.count != refs.items.len)
        {
            boxyLowerInvariant("boxy erased capture descriptor fields disagreed with the capture struct layout");
        }

        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.appendSlice(self.parent.allocator, refs.items);

        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = capture_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value),
            .shape = .internal,
            .nested_descs = .{ .start = nested_start, .len = @intCast(refs.items.len) },
        });

        const capture_span = if (desc_captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(desc_captures.items);
        return .{
            .desc = .{ .static = desc_id },
            .captures = capture_span,
        };
    }

    fn materializeErasedCaptureDictionary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        capture: Plan.ErasedCapture,
        source_rep: Plan.TypeRepId,
        planned_arg: ?Plan.DirectCallHiddenDictionaryArg,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (capture.kind != .hidden_dict and capture.kind != .hidden_literal) {
            boxyLowerInvariant("non-dictionary erased capture reached dictionary materialization");
        }
        const dict_ref: FrameDictionary = if (planned_arg) |arg|
            try self.dictionaryRefForPlannedSource(arg)
        else
            .{ .dict = try self.dictionaryRefForKnownRep(source_rep, capture.dictionaries) };
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_dict_ref = .{
            .target = target,
            .dict = dict_ref.dict,
            .captures = dict_ref.captures,
            .next = next,
        } }, self.glueOrigin());
    }

    fn erasedCaptureNeedsContentsDescriptor(
        self: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        field_locals: []const LIR.LocalId,
    ) bool {
        if (captures.len != field_locals.len) {
            boxyLowerInvariant("boxy erased capture descriptor need saw mismatched capture fields");
        }

        for (captures, field_locals) |capture, field_local| {
            if (capture.kind != .captured_value) continue;
            const field_layout = self.parent.result.store.getLocal(field_local).layout_idx;
            if (self.parent.layoutNeedsNestedBoxyDesc(field_layout)) return true;
        }
        return false;
    }

    fn erasedCaptureLayoutWithOnDropDescriptor(
        self: *ProcBodyBuilder,
        base_layout: layout.Idx,
        desc_field_index: usize,
    ) Allocator.Error!layout.Idx {
        if (desc_field_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("boxy erased capture descriptor field index exceeded layout range");
        }

        const layouts = self.parent.result.layouts;
        const layout_value = layouts.getLayout(base_layout);
        var fields = std.ArrayList(layout.StructField).empty;
        defer fields.deinit(self.parent.allocator);

        switch (layout_value.tag) {
            .zst => {},
            .struct_ => {
                const struct_idx = layout_value.getStruct().idx;
                const existing = layouts.struct_fields.sliceRange(layouts.getStructData(struct_idx).getFields());
                try fields.ensureTotalCapacity(self.parent.allocator, existing.len + 1);
                var index: u32 = 0;
                while (index < existing.len) : (index += 1) {
                    const field = existing.get(index);
                    try fields.append(self.parent.allocator, .{
                        .index = field.index,
                        .layout = field.layout,
                        .is_padding = field.is_padding,
                    });
                }
            },
            .scalar, .box, .box_of_zst, .erased_box, .list, .list_of_zst, .closure, .erased_callable, .tag_union, .ptr => boxyLowerInvariant("boxy erased capture descriptor field expected struct capture layout"),
        }

        try fields.append(self.parent.allocator, .{
            .index = @intCast(desc_field_index),
            .layout = .opaque_ptr,
        });
        // Erased workers load `base_layout` directly from the start of the
        // capture pointer. Appending the ARC descriptor must therefore preserve
        // every committed base-field offset; structurally sorting the extended
        // fields can move the pointer ahead of lower-alignment captures.
        return try self.parent.result.layouts.putNominalStructFields(fields.items);
    }

    fn erasedCallableOnDrop(self: *ProcBodyBuilder, maybe_capture_layout: ?layout.Idx) LIR.ErasedCallableOnDrop {
        const capture_layout = maybe_capture_layout orelse return .none;
        // The payload's `on_drop` slot is a host-facing ABI, so it names the
        // host-shaped adapter rather than the plain decref helper.
        const helper_key = layout.RcHelper{ .op = .host_drop, .layout_idx = capture_layout };
        return if (self.parent.result.layouts.rcHelperPlan(helper_key) == .noop)
            .none
        else
            .{ .rc_helper = helper_key };
    }

    fn packGeneratedErasedCallable(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        erased_proc: LIR.LirProcSpecId,
        worker_id: Plan.WorkerPlanId,
        callable_rep: Plan.TypeRepId,
        result_rep: Plan.TypeRepId,
        result_desc: ResultDescriptorSource,
        captures: []const Plan.ErasedCapture,
        capture_values: []const LIR.LocalId,
        base_capture_layout: layout.Idx,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (captures.len != capture_values.len) {
            boxyLowerInvariant("generated erased callable capture metadata disagreed with capture values");
        }
        for (captures, capture_values) |capture, value| {
            switch (capture.kind) {
                .captured_value => {},
                .hidden_desc, .hidden_literal => if (self.parent.result.store.getLocal(value).layout_idx != .opaque_ptr) {
                    boxyLowerInvariant("generated erased callable descriptor capture was not an opaque pointer");
                },
                .hidden_dict => boxyLowerInvariant("generated erased callable unexpectedly had a dictionary capture"),
            }
        }

        var descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.parent.allocator);
        const descriptor_overrides = try self.parent.allocator.alloc(?LIR.BoxyDescRef, captures.len);
        defer self.parent.allocator.free(descriptor_overrides);
        @memset(descriptor_overrides, null);
        try self.prepareErasedPackedCapturedValueFieldDescriptors(
            captures,
            capture_values,
            &descriptor_initializers,
            descriptor_overrides,
        );
        try self.prepareErasedCapturedValueFieldDescriptors(
            captures,
            capture_values,
            &descriptor_initializers,
            .snapshot_existing,
            descriptor_overrides,
        );

        var result_desc_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer result_desc_initializers.deinit(self.parent.allocator);
        try self.appendResultDescriptorInitializers(&result_desc_initializers, result_desc);

        var callable_bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer callable_bindings.deinit(self.parent.allocator);
        for (captures, capture_values) |capture, value| {
            if (capture.kind != .hidden_desc) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("generated erased callable hidden descriptor capture had no requirement");
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, desc, capture.rep, value);
        }
        if (result_desc.desc) |desc| {
            var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer seen.deinit();
            try self.collectDescriptorEnvironmentForRep(
                result_rep,
                desc,
                &callable_bindings,
                &result_desc_initializers,
                &seen,
            );
        }
        try self.recordLocalDescriptorEnvironment(target, callable_rep, callable_bindings.items);

        const needs_contents_desc = self.erasedCaptureNeedsContentsDescriptor(captures, capture_values);
        const capture_layout = if (needs_contents_desc)
            try self.erasedCaptureLayoutWithOnDropDescriptor(base_capture_layout, captures.len)
        else
            base_capture_layout;
        const capture_local = try self.addFrameLocal(capture_layout);

        var capture_desc_initializer: ?DescriptorArgLocal = null;
        const capture_contents_desc = if (needs_contents_desc) blk: {
            const materialization = try self.erasedCaptureContentsDescriptorMaterialization(
                captures,
                capture_values,
                descriptor_overrides,
                capture_layout,
            ) orelse boxyLowerInvariant("generated erased callable capture descriptor need disappeared during materialization");
            const desc_local = try self.addFrameLocal(.opaque_ptr);
            const desc_ref = LIR.BoxyDescRef{ .local = desc_local };
            self.parent.result.store.setLocalBoxyDesc(capture_local, desc_ref);
            capture_desc_initializer = materialization.initializer(desc_local);
            break :blk desc_ref;
        } else null;

        const capture_fields = if (capture_desc_initializer) |initializer| blk: {
            const fields = try self.parent.allocator.alloc(LIR.LocalId, capture_values.len + 1);
            @memcpy(fields[0..capture_values.len], capture_values);
            fields[capture_values.len] = initializer.local;
            break :blk fields;
        } else capture_values;
        defer if (capture_fields.ptr != capture_values.ptr) self.parent.allocator.free(capture_fields);

        const on_drop: LIR.ErasedCallableOnDrop = if (capture_desc_initializer != null) blk: {
            const capture_layout_value = self.parent.result.layouts.getLayout(capture_layout);
            if (capture_layout_value.tag != .struct_) {
                boxyLowerInvariant("generated erased callable capture descriptor field expected struct capture layout");
            }
            break :blk .{ .boxy_capture = .{
                .capture_layout = capture_layout,
                .desc_field_offset = self.parent.result.layouts.getStructFieldOffsetByOriginalIndex(
                    capture_layout_value.getStruct().idx,
                    @intCast(captures.len),
                ),
            } };
        } else self.erasedCallableOnDrop(capture_layout);

        if (self.parent.needsFrozenCallableRecipes()) {
            const fields = try self.parent.allocator.alloc(ProcedureBuilder.FrozenCaptureRecipe, captures.len);
            defer self.parent.allocator.free(fields);
            for (captures, fields) |capture, *field| field.* = switch (capture.kind) {
                .captured_value => .{ .value = capture.rep },
                .hidden_desc => .{ .descriptor = .{ .worker_rep = capture.rep, .source_rep = capture.rep } },
                .hidden_dict => .{ .dictionary = capture.dictionaries },
                .hidden_literal => .{ .literal = capture.literal_parameter.? },
            };
            try self.parent.recordFrozenCallable(worker_id, null, callable_rep, callable_rep, erased_proc, capture_layout, on_drop, result_rep, fields);
        }
        const pack = try self.parent.result.store.addCFStmt(.{ .assign_packed_erased_fn = .{
            .target = target,
            .proc = erased_proc,
            .capture = capture_local,
            .capture_layout = capture_layout,
            .on_drop = on_drop,
            .result_desc = result_desc.desc,
            .next = next,
        } }, self.derivedOrigin());
        var continuation = if (self.isZstLocal(capture_local))
            try self.assignZst(capture_local, pack)
        else
            try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
                .target = capture_local,
                .fields = try self.parent.result.store.addLocalSpan(capture_fields),
                .contents_desc = capture_contents_desc,
                .next = pack,
            } }, self.derivedOrigin());
        continuation = try self.prependDescriptorArgMaterializations(result_desc_initializers.items, continuation);
        continuation = try self.prependOptionalDescriptorMaterialization(capture_desc_initializer, continuation);
        return try self.prependDescriptorArgMaterializations(descriptor_initializers.items, continuation);
    }

    fn callableExprCaptures(self: *ProcBodyBuilder, expr_id: checked.CheckedExprId) []const checked.CheckedCapture {
        return nestedCallableExprRuntimeCaptures(self.module, expr_id);
    }

    fn callableValueSourceCaptures(
        self: *ProcBodyBuilder,
        source: Plan.WorkerSource,
        maybe_expr: ?checked.CheckedExprId,
    ) []const checked.CheckedCapture {
        if (maybe_expr) |expr_id| return self.callableExprCaptures(expr_id);
        return switch (source) {
            .nested_expr => |expr_ref| nestedCallableExprRuntimeCaptures(procedureModuleById(self.parent.modules, expr_ref.module), expr_ref.expr),
            .procedure_template,
            .procedure_binding,
            .procedure_use,
            .generated_codec,
            .generated_field_iterator,
            => &.{},
        };
    }

    fn workerSourceForCallableExpr(self: *ProcBodyBuilder, expr_id: checked.CheckedExprId) Plan.WorkerSource {
        const expr = self.module.checked_bodies.expr(expr_id);
        return switch (expr.data) {
            .lambda, .closure => .{ .nested_expr = .{ .module = self.module.key, .expr = expr_id } },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyLowerInvariant("non-callable checked expression reached callable worker source lookup"),
        };
    }

    fn directTargetIsLocalProc(self: *const ProcBodyBuilder, target: checked.ResolvedValueId) bool {
        return switch (self.resolvedValueRecord(target).ref) {
            .local_proc => true,
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .top_level_proc, .imported_proc, .hosted_proc, .platform_required_declaration, .platform_required_checked_error, .platform_required_const, .platform_required_proc, .promoted_top_level_proc => false,
        };
    }

    fn lowerErasedCallLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        callee_rep: Plan.TypeRepId,
        callee_local: LIR.LocalId,
        args: []const LIR.LocalId,
        arg_reps: []const Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const callee_function = self.functionChildrenForRep(callee_rep) orelse
            boxyLowerInvariant("local erased call did not have a callable representation");
        if (callee_function.arg_count != args.len or args.len != arg_reps.len) {
            boxyLowerInvariant("local erased call argument count disagreed with its callable representation");
        }
        if (self.parent.result.store.getLocal(callee_local).layout_idx != self.workerRuntimeLayoutForRep(callee_rep).layoutIdx()) {
            boxyLowerInvariant("local erased call closure layout disagreed with its callable representation");
        }

        const callee_rep_data = self.parent.plan.representations.items[@backingInt(callee_function.rep)];
        const callee_children = self.parent.plan.childSlice(callee_rep_data.children);
        const callee_arg_children = callee_children[callee_function.args_start..][0..callee_function.arg_count];
        const call_args = try self.parent.allocator.alloc(LIR.LocalId, args.len);
        defer self.parent.allocator.free(call_args);
        for (args, arg_reps, call_args, callee_arg_children) |arg, source_rep, *call_arg, arg_child| {
            if (self.parent.result.store.getLocal(arg).layout_idx != self.workerRuntimeLayoutForRep(source_rep).layoutIdx()) {
                boxyLowerInvariant("local erased call argument layout disagreed with its source representation");
            }
            call_arg.* = if (self.representationBoundaryIsDirect(arg_child.rep, source_rep))
                arg
            else
                try self.addFrameBoundaryTargetLocalForRep(arg_child.rep);
        }
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (target_layout != self.workerRuntimeLayoutForRep(target_rep).layoutIdx()) {
            boxyLowerInvariant("local erased call result layout disagreed with its target representation");
        }
        const callee_ret_layout = self.workerRuntimeLayoutForRep(callee_function.ret).layoutIdx();

        const target_desc_is_shared = if (self.parent.result.store.getLocal(target).boxy_desc) |desc|
            if (desc.localOrNull()) |local| self.localIsDescriptorSlot(local) else false
        else
            false;
        var continuation = next;
        const call_target = if (!target_desc_is_shared and
            target_layout == callee_ret_layout and
            (self.erasedCallResultCanUseTarget(target_rep, callee_function.ret) or
                self.callResultAdoptsCalleeDescriptor(target, target_rep)))
            target
        else blk: {
            const raw_ret = if (self.parent.result.store.getLocal(target).boxy_desc != null)
                try self.addFrameLocalForRepWithRequiredFreshDescriptor(callee_function.ret)
            else
                try self.addFrameLocalForRepWithFreshDescriptor(callee_function.ret);
            if (self.parent.result.store.getLocal(raw_ret).boxy_desc) |desc| {
                if (desc.localOrNull()) |local| {
                    try self.recordDescriptorLocalTemplate(
                        local,
                        try self.descriptorMaterializationForExactRep(callee_function.ret),
                    );
                }
            }
            continuation = try self.assignPlannedCallBoundary(
                target,
                raw_ret,
                target_rep,
                callee_function.ret,
                continuation,
            );
            break :blk raw_ret;
        };

        const out_desc = self.callResultOutputDescriptorLocal(call_target);
        if (out_desc) |local| {
            if (self.descriptorTemplateForLocal(local) == null and !self.repIsOpenRecord(callee_function.ret)) {
                try self.recordDescriptorLocalTemplate(
                    local,
                    try self.descriptorMaterializationForExactRep(callee_function.ret),
                );
            }
            try self.markDescriptorLocalBound(local);
        }

        var descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer descriptor_initializers.deinit(self.parent.allocator);
        const arg_descs = try self.erasedCallArgumentDescriptorRefs(
            callee_arg_children,
            call_args,
            &descriptor_initializers,
        );
        const expected_result_desc = try self.erasedCallResultDescriptorRef(
            call_target,
            callee_function.ret,
            out_desc,
        );
        try self.appendResultDescriptorInitializers(&descriptor_initializers, expected_result_desc);

        continuation = try self.parent.result.store.addCFStmt(.{ .assign_call_erased = .{
            .target = call_target,
            .closure = callee_local,
            .args = try self.parent.result.store.addLocalSpan(call_args),
            .arg_layouts = try self.appendErasedArgumentLayouts(call_args),
            .arg_plan = try self.erasedCallArgsPlan(call_args),
            .arg_descs = arg_descs.locals,
            .arg_desc_keys = arg_descs.keys,
            .result_desc = expected_result_desc.desc,
            .out_desc = out_desc,
            .reuse_closure = false,
            .reuse_source = null,
            .next = continuation,
        } }, self.origin);
        continuation = try self.prependDescriptorArgMaterializations(descriptor_initializers.items, continuation);

        var index = args.len;
        while (index > 0) {
            index -= 1;
            if (call_args[index] == args[index]) continue;
            continuation = try self.assignPlannedCallBoundary(
                call_args[index],
                args[index],
                callee_arg_children[index].rep,
                arg_reps[index],
                continuation,
            );
        }
        return continuation;
    }

    fn appendErasedArgumentLayouts(
        self: *ProcBodyBuilder,
        args: []const LIR.LocalId,
    ) Allocator.Error!LIR.BoxySpan {
        if (args.len == 0) return .{};
        const start = self.parent.result.boxy_erased_arg_layouts.items.len;
        for (args) |arg| {
            const local_layout = self.parent.result.store.getLocal(arg).layout_idx;
            try self.parent.result.boxy_erased_arg_layouts.append(
                self.parent.allocator,
                self.parent.result.layouts.runtimeRepresentationLayoutIdx(local_layout),
            );
        }
        return .{
            .start = @intCast(start),
            .len = @intCast(args.len),
        };
    }

    fn erasedCallArgsPlan(
        self: *ProcBodyBuilder,
        args: []const LIR.LocalId,
    ) Allocator.Error!LIR.ErasedCallArgsPlanId {
        const arg_layouts = try self.parent.allocator.alloc(layout.Idx, args.len);
        defer self.parent.allocator.free(arg_layouts);
        for (args, arg_layouts) |arg, *arg_layout| {
            arg_layout.* = self.parent.result.store.getLocal(arg).layout_idx;
        }
        return try self.parent.result.store.internErasedCallArgsPlan(&self.parent.result.layouts, arg_layouts);
    }

    fn erasedCallArgumentDescriptorRefs(
        self: *ProcBodyBuilder,
        arg_reps: []const Plan.RepChild,
        arg_locals: []const LIR.LocalId,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!ErasedCallArgumentDescriptors {
        if (arg_reps.len != arg_locals.len) {
            boxyLowerInvariant("boxy erased-call argument descriptor arity mismatch");
        }
        const descriptor_snapshot = try self.snapshotDescriptorBindings();
        defer descriptor_snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(descriptor_snapshot);

        var desc_locals = std.ArrayList(LIR.LocalId).empty;
        defer desc_locals.deinit(self.parent.allocator);
        const key_start = self.parent.result.boxy_erased_arg_desc_keys.items.len;
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();

        for (arg_reps, arg_locals, 0..) |arg, source, arg_index| {
            if (arg_index > std.math.maxInt(u32)) {
                boxyLowerInvariant("boxy erased-call argument index exceeded descriptor key range");
            }
            try self.bindLocalDescriptorEnvironment(source);
            var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer params.deinit(self.parent.allocator);
            try self.collectHiddenDescriptorParamsForRep(.all, arg.rep, &params, &seen_reps, &seen_descs);
            if (params.items.len == 0) {
                const materialization = if (self.parent.result.store.getLocal(source).boxy_desc) |desc|
                    DescriptorMaterialization{ .desc = desc }
                else
                    try self.descriptorMaterializationForSourceStorageLocalRep(source, arg.rep);
                const local = try self.erasedCallDescriptorLocal(materialization, initializers);
                try desc_locals.append(self.parent.allocator, local);
                try self.parent.result.boxy_erased_arg_desc_keys.append(self.parent.allocator, .{
                    .arg_index = @intCast(arg_index),
                    .descriptor_index = 0,
                });
                continue;
            }

            const descriptor_args = try self.parent.allocator.alloc(DescriptorArgLocal, params.items.len);
            defer self.parent.allocator.free(descriptor_args);
            var root_indices = std.ArrayList(usize).empty;
            defer root_indices.deinit(self.parent.allocator);
            var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
            defer overrides.deinit(self.parent.allocator);

            for (params.items, 0..) |param, param_index| {
                if (param_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy erased-call descriptor index exceeded key range");
                }
                const is_root = self.repOwnsShapeDescriptor(param.rep, param.desc) and
                    self.descriptorShapeIdentityRep(arg.rep) == self.descriptorShapeIdentityRep(param.rep);
                if (is_root) {
                    try root_indices.append(self.parent.allocator, param_index);
                    continue;
                }

                const descriptor_arg: DescriptorArgLocal = if (self.localEnvironmentDescriptorForRequirementAndRep(source, param.desc, param.rep)) |local|
                    .{ .local = local }
                else if (self.descriptorLocalForRequirementAndRepOrNull(param.desc, param.rep)) |local|
                    .{ .local = local }
                else if (try self.sourceNestedDescriptorLocalForHiddenArg(source, arg.rep, param.rep)) |projected|
                    projected
                else independent: {
                    const materialization = try self.descriptorMaterializationForExactRep(param.rep);
                    break :independent .{
                        .local = try self.erasedCallDescriptorLocal(materialization, initializers),
                    };
                };
                if (descriptor_arg.materialize != null) {
                    try initializers.append(self.parent.allocator, descriptor_arg);
                }
                descriptor_args[param_index] = descriptor_arg;
                const identity_rep = self.parent.descriptorIdentityRep(param.rep);
                for (overrides.items) |override| {
                    if (override.rep != identity_rep) continue;
                    if (override.local != descriptor_arg.local) {
                        boxyLowerInvariant("boxy erased-call argument had conflicting exact descriptors for one representation");
                    }
                    break;
                } else {
                    try overrides.append(self.parent.allocator, .{
                        .rep = identity_rep,
                        .local = descriptor_arg.local,
                    });
                }
            }

            for (root_indices.items) |param_index| {
                const param = params.items[param_index];
                const materialization = if (overrides.items.len != 0 and !self.repIsOpenRecord(param.rep))
                    try self.descriptorMaterializationForKnownRepWithOverrides(arg.rep, overrides.items)
                else if (self.parent.result.store.getLocal(source).boxy_desc) |desc|
                    DescriptorMaterialization{ .desc = desc }
                else if (self.localEnvironmentDescriptorForRequirementAndRep(source, param.desc, param.rep)) |local|
                    DescriptorMaterialization{ .desc = .{ .local = local } }
                else
                    try self.descriptorMaterializationForSourceStorageLocalRep(source, arg.rep);
                descriptor_args[param_index] = .{
                    .local = try self.erasedCallDescriptorLocal(materialization, initializers),
                };
            }

            for (descriptor_args, 0..) |descriptor_arg, param_index| {
                try desc_locals.append(self.parent.allocator, descriptor_arg.local);
                try self.parent.result.boxy_erased_arg_desc_keys.append(self.parent.allocator, .{
                    .arg_index = @intCast(arg_index),
                    .descriptor_index = @intCast(param_index),
                });
            }
        }
        return .{
            .locals = try self.parent.result.store.addLocalSpan(desc_locals.items),
            .keys = .{
                .start = @intCast(key_start),
                .len = @intCast(self.parent.result.boxy_erased_arg_desc_keys.items.len - key_start),
            },
        };
    }

    fn erasedCallDescriptorLocal(
        self: *ProcBodyBuilder,
        materialization: DescriptorMaterialization,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!LIR.LocalId {
        if (materialization.captures.len == 0) {
            if (materialization.desc.localOrNull()) |local| return local;
        }
        const local = try self.addFrameLocal(.opaque_ptr);
        try initializers.append(self.parent.allocator, materialization.initializer(local));
        return local;
    }

    fn beginUnresolvedDispatchCall(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        call_expr: checked.CheckedExprId,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        ret_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const call_ref = Plan.CheckedExprIdentity{ .module = self.module.key, .expr = call_expr };
        if (self.parent.plan.dictionaryDispatchPlanForCall(call_ref, self.worker_layout.worker)) |planned| {
            if (planned.method != dispatch.method) {
                boxyLowerInvariant("planned dictionary dispatch disagreed with its checked call site");
            }
            return try self.beginDictionaryDispatchCall(
                target,
                dispatch,
                planned,
                ret_ty,
                next,
            );
        }

        return switch (dispatch.result_mode) {
            .equality => |eq| if (eq.structural_allowed)
                try self.beginStructuralEqDispatch(target, dispatch, eq.negated, next)
            else
                boxyLowerInvariant("unresolved equality dispatch reached boxy lowering without structural permission or dictionary"),
            .hash => |hash| if (hash.structural_allowed)
                try self.beginStructuralHashDispatch(target, dispatch, next)
            else
                boxyLowerInvariant("unresolved hash dispatch reached boxy lowering without structural permission or dictionary"),
            .value => if (self.dispatchMethodNameIs(dispatch.method, "inspect"))
                try self.beginStructuralInspectDispatch(target, dispatch, next)
            else
                boxyLowerInvariant("unresolved value dispatch reached boxy lowering without dictionary support for that method"),
            .parser_for,
            .encoder_for,
            => boxyLowerInvariant("unresolved parser or encoder dispatch reached boxy lowering before structural parser/encoder support"),
            .map,
            .map_effectful,
            => boxyLowerInvariant("derived map dispatch reached Boxy lowering without an explicit checked implementation"),
        };
    }

    /// The crash a dispatch that cannot run ends in: checking rejected it
    /// (`checked_error`), or no value can reach its dispatcher
    /// (`unreachable`).
    fn lowerDispatchCrashInto(self: *ProcBodyBuilder, resolution: static_dispatch.CheckedCallResolution) Allocator.Error!LIR.CFStmtId {
        return switch (resolution) {
            .checked_error => try self.lowerCheckedErrorDispatchInto("method dispatch failed to check"),
            .@"unreachable" => try self.lowerUnexecutableDispatchInto("dispatch on a value that can never exist"),
            .direct_pending, .direct_closed, .direct_parametric, .evidence_dependent, .structural => boxyLowerInvariant("a runnable dispatch reached dispatch crash lowering"),
        };
    }

    fn lowerUnexecutableDispatchInto(
        self: *ProcBodyBuilder,
        comptime message: []const u8,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .crash = .{
            .msg = .{ .literal = try self.parent.result.store.insertString(message) },
        } }, self.origin);
    }

    /// A checked `runtime_error` is code checking rejected and already
    /// reported; reaching it crashes with the checked-error message.
    fn lowerCheckedRuntimeError(self: *ProcBodyBuilder) Allocator.Error!LIR.CFStmtId {
        return try self.lowerCheckedErrorDispatchInto("runtime error");
    }

    /// A runtime error first evaluates its `evaluated` operands, in order,
    /// each into a discarded local, then crashes with the checked error. When
    /// the last of them is an erroneous operand, its own evaluation crashes
    /// first.
    fn beginRuntimeError(self: *ProcBodyBuilder, evaluated: []const checked.CheckedExprId) Allocator.Error!ExprStep {
        const crash = try self.lowerCheckedRuntimeError();
        if (evaluated.len == 0) return exprDone(crash);
        // Chain items run from the last to the first.
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, evaluated.len);
        for (evaluated, 0..) |expr_id, index| {
            const expr = self.module.checked_bodies.expr(expr_id);
            const discarded = if (expr.data == .runtime_error)
                try self.addFrameLocal(.zst)
            else
                try self.addFrameLocalForType(expr.ty);
            chain_items[evaluated.len - 1 - index] = .{ .lower = .{ .expr = .{ .target = discarded, .expr_id = expr_id, .next = undefined } } };
        }
        return exprChain(chain_items, crash);
    }

    /// A dispatch that cannot run (`checked_error` or `unreachable`) uses
    /// strict evaluation: its receiver and arguments evaluate in order, each
    /// into a discarded local, and then the call crashes. An interpolation's generated segments operand evaluates the
    /// interpolation's segments and values; a generated numeral or quote
    /// operand is literal source text with nothing to evaluate. A checked
    /// runtime error produces no value, so its discarded local is
    /// zero-sized.
    fn beginCrashingDispatch(
        self: *ProcBodyBuilder,
        dispatch: static_dispatch.StaticDispatchCallPlan,
    ) Allocator.Error!ExprStep {
        var exprs: std.ArrayList(checked.CheckedExprId) = .empty;
        defer exprs.deinit(self.parent.allocator);
        for (dispatch.argsSlice(self.module.static_dispatch_plans)) |operand| switch (operand) {
            .checked_expr => |expr| try exprs.append(self.parent.allocator, expr),
            .generated_interpolation_segments => |expr| {
                const interpolation = switch (self.module.checked_bodies.expr(expr).data) {
                    .interpolation => |value| value,
                    .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => boxyLowerInvariant("rejected interpolation segments referenced a non-interpolation expression"),
                };
                try exprs.append(self.parent.allocator, interpolation.segments[0]);
                for (interpolation.values, interpolation.segments[1..]) |value, segment| {
                    try exprs.append(self.parent.allocator, value);
                    try exprs.append(self.parent.allocator, segment);
                }
            },
            .generated_numeral, .generated_quote => {},
        };
        const crash = try self.lowerDispatchCrashInto(dispatch.resolution);
        if (exprs.items.len == 0) return exprDone(crash);
        // Chain items run from the last to the first.
        const chain_items = try self.parent.allocator.alloc(ExprChainItem, exprs.items.len);
        for (exprs.items, 0..) |expr_id, index| {
            const expr = self.module.checked_bodies.expr(expr_id);
            const discarded = if (expr.data == .runtime_error)
                try self.addFrameLocal(.zst)
            else
                try self.addFrameLocalForType(expr.ty);
            chain_items[exprs.items.len - 1 - index] = .{ .lower = .{ .expr = .{ .target = discarded, .expr_id = expr_id, .next = undefined } } };
        }
        return exprChain(chain_items, crash);
    }

    fn lowerCheckedErrorDispatchInto(
        self: *ProcBodyBuilder,
        comptime message: []const u8,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .crash = .{
            .msg = .{ .literal = try self.parent.result.store.insertString(message) },
            .checked_error = true,
        } }, self.origin);
    }

    fn beginStructuralEqDispatch(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const operands = dispatch.argsSlice(self.module.static_dispatch_plans);
        if (operands.len != 2) {
            boxyLowerInvariant("structural equality dispatch did not carry two operands");
        }
        const lhs = switch (operands[0]) {
            .checked_expr => |expr| expr,
            .generated_interpolation_segments, .generated_numeral, .generated_quote => boxyLowerInvariant("structural equality lhs was not a checked expression operand"),
        };
        const rhs = switch (operands[1]) {
            .checked_expr => |expr| expr,
            .generated_interpolation_segments, .generated_numeral, .generated_quote => boxyLowerInvariant("structural equality rhs was not a checked expression operand"),
        };
        return try self.beginStructuralEq(target, lhs, rhs, self.repForType(dispatch.dispatcher_ty), negated, next);
    }

    fn beginStructuralHashDispatch(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const operands = dispatch.argsSlice(self.module.static_dispatch_plans);
        if (operands.len != 2) {
            boxyLowerInvariant("structural hash dispatch did not carry two operands");
        }
        const value = switch (operands[0]) {
            .checked_expr => |expr| expr,
            .generated_interpolation_segments, .generated_numeral, .generated_quote => boxyLowerInvariant("structural hash value was not a checked expression operand"),
        };
        const hasher = switch (operands[1]) {
            .checked_expr => |expr| expr,
            .generated_interpolation_segments, .generated_numeral, .generated_quote => boxyLowerInvariant("structural hash hasher was not a checked expression operand"),
        };
        return try self.beginStructuralHash(target, value, hasher, next);
    }

    fn beginStructuralInspectDispatch(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const operands = dispatch.argsSlice(self.module.static_dispatch_plans);
        if (operands.len != 1) {
            boxyLowerInvariant("structural inspect dispatch did not carry one operand");
        }
        const value = switch (operands[0]) {
            .checked_expr => |expr| expr,
            .generated_interpolation_segments, .generated_numeral, .generated_quote => boxyLowerInvariant("structural inspect operand was not a checked expression operand"),
        };
        return try self.beginInspectExpr(target, value, next);
    }

    fn beginDictionaryDispatchCall(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        dispatch: static_dispatch.StaticDispatchCallPlan,
        planned: Plan.DictionaryDispatchPlan,
        ret_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const descriptor_snapshot = try self.snapshotDescriptorBindings();
        var snapshot_moved = false;
        defer if (!snapshot_moved) {
            self.restoreDescriptorBindings(descriptor_snapshot);
            descriptor_snapshot.deinit(self.parent.allocator);
        };

        const match: DictionaryMethodMatch = if (planned.scheme_requirement) |requirement| .{
            .requirement = requirement,
            .slot = self.parent.plan.dictionaries.items[@backingInt(requirement)].slot,
        } else self.dictionaryMethodForRep(planned.dispatcher_rep, dispatch.method) orelse
            boxyLowerInvariant("dictionary dispatch reached boxy lowering without a matching dictionary requirement");
        const dict_local = self.dictionaryLocalForRequirementOrNull(match.requirement) orelse
            boxyLowerInvariant("dictionary dispatch reached boxy lowering without a bound dictionary local");
        if (!self.dictionaryBindingIsBound(match.requirement)) {
            boxyLowerInvariant("dictionary dispatch reached boxy lowering with an unbound dictionary local");
        }
        const required_method = self.parent.plan.dictionaries.items[@backingInt(match.requirement)].fn_name;

        const operands = self.parent.plan.callOperandSlice(planned.operands);
        const callable = checkedFunctionPayload(self.module, dispatch.callable_ty);
        if (operands.len != callable.args.len) {
            boxyLowerInvariant("planned dictionary operand arity disagreed with its checked callable type");
        }
        const substitutions = self.parent.plan.callTypeSubstitutionSlice(planned.arg_substitutions);
        if (substitutions.len != operands.len) {
            boxyLowerInvariant("planned dictionary substitution arity disagreed with its operands");
        }
        const ret_substitution = planned.ret_substitution orelse
            boxyLowerInvariant("planned dictionary dispatch had no return substitution");

        const arg_reps = try self.parent.allocator.alloc(Plan.TypeRepId, operands.len);
        defer self.parent.allocator.free(arg_reps);
        const storage_arg_reps = try self.parent.allocator.alloc(Plan.TypeRepId, operands.len);
        defer self.parent.allocator.free(storage_arg_reps);
        const operand_types = try self.parent.allocator.alloc(Plan.CheckedTypeIdentity, operands.len);
        defer self.parent.allocator.free(operand_types);
        const arg_types = try self.parent.allocator.alloc(Plan.CheckedTypeIdentity, operands.len);
        defer self.parent.allocator.free(arg_types);
        for (substitutions, operands, operand_types, arg_types, storage_arg_reps, arg_reps) |substitution, operand, *operand_type, *arg_type, *storage_arg_rep, *arg_rep| {
            operand_type.* = substitution.operand_type;
            arg_type.* = substitution.call_type;
            if (self.repForTypeRef(operand_type.*) != substitution.operand_rep or
                self.repForTypeRef(arg_type.*) != substitution.call_rep or
                substitution.worker_rep != substitution.call_rep)
            {
                boxyLowerInvariant("planned dictionary substitution disagreed with its checked representations");
            }
            storage_arg_rep.* = try self.directCallOperandStorageRep(operand, substitution.operand_rep);
            arg_rep.* = if (storage_arg_rep.* == substitution.operand_rep)
                substitution.call_rep
            else
                storage_arg_rep.*;
        }
        const lowered = try self.lowerDictionaryOperandsToTemps(operands, arg_reps);
        defer self.parent.allocator.free(lowered);

        const ret_type = ret_substitution.call_type;
        const method_function_rep = self.dictionaryMethodFunctionRepForCall(dispatch.callable_ty);
        const method_function = self.functionChildrenForRep(method_function_rep) orelse
            boxyLowerInvariant("dictionary dispatch method representation was not a function");
        const hidden_desc_args = try self.dictionaryCallHiddenDescriptorArgs(
            method_function_rep,
            planned.dispatcher_rep,
            match.requirement,
            switch (dispatch.dispatcher) {
                .arg => |index| index,
                .type_only => null,
            },
            arg_types,
            arg_reps,
            ret_type,
        );
        defer self.parent.allocator.free(hidden_desc_args);
        var pre_arg_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer pre_arg_descriptor_initializers.deinit(self.parent.allocator);
        var call_arg_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer call_arg_descriptor_initializers.deinit(self.parent.allocator);
        const argument_desc_locals = try self.dictionaryCallArgumentDescriptorLocals(
            arg_reps,
            lowered,
            &call_arg_descriptor_initializers,
        );
        defer self.parent.allocator.free(argument_desc_locals);
        // A quote conversion's argument is concrete Str, and an
        // interpolation conversion's is its concrete `List(Str)` of segments.
        // The remaining type parameters (the conversion's result and error)
        // belong to the selected dictionary method, rather than to an explicit
        // argument at this call.
        const call_data = self.module.checked_bodies.expr(planned.call.expr).data;
        if (call_data == .str_from_quote or call_data == .interpolation) {
            try self.bindConversionResultDescriptorArgs(hidden_desc_args, dict_local, required_method, match.slot, &pre_arg_descriptor_initializers);
        }
        const hidden_desc_locals = try self.lowerDirectCallHiddenDescriptorArgs(hidden_desc_args, lowered, arg_reps, arg_reps);
        defer self.parent.allocator.free(hidden_desc_locals);

        const hidden_arg_locals = try self.parent.allocator.alloc(LIR.LocalId, hidden_desc_locals.len);
        defer self.parent.allocator.free(hidden_arg_locals);
        for (hidden_desc_locals, 0..) |hidden, index| {
            hidden_arg_locals[index] = hidden.local;
        }

        var continuation = next;
        var call_target = target;
        switch (dispatch.result_mode) {
            .equality => |eq| if (eq.negated) {
                const raw = try self.addFrameLocal(.bool);
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                    .target = target,
                    .op = .bool_not,
                    .rc_effect = LIR.LowLevel.bool_not.rcEffect(),
                    .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{raw}),
                    .next = next,
                } }, self.origin);
                call_target = raw;
            },
            .value,
            .hash,
            .parser_for,
            .encoder_for,
            .map,
            .map_effectful,
            => {},
        }
        const call_returns_method_result = call_target == target;
        if (call_returns_method_result) {
            const target_rep = self.repForType(ret_ty);
            if (method_function.ret != ret_substitution.worker_rep) {
                boxyLowerInvariant("planned dictionary return representation disagreed with its method function");
            }
            if (target_rep != ret_substitution.call_rep) {
                const raw_target = try self.addFrameBoundaryTargetLocalForRep(ret_substitution.call_rep);
                continuation = try self.assignPlannedCallBoundary(
                    target,
                    raw_target,
                    target_rep,
                    ret_substitution.call_rep,
                    continuation,
                );
                call_target = raw_target;
            }
        }
        const result_desc_info = if (call_returns_method_result)
            self.resultDescriptorForCallTarget(
                call_target,
                try self.dictionaryCallResultDescriptorRef(ret_substitution.call_rep, hidden_desc_args, hidden_desc_locals),
            )
        else
            ResultDescriptorSource{};
        if (result_desc_info.desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(call_target, desc);
        }

        continuation = try self.parent.result.store.addCFStmt(.{ .assign_call_dict = .{
            .target = call_target,
            .dict = .{ .local = dict_local },
            .method = required_method,
            .method_slot = match.slot,
            .args = try self.parent.result.store.addLocalSpan(lowered),
            .arg_descs = try self.parent.result.store.addLocalSpan(argument_desc_locals),
            .hidden_args = try self.parent.result.store.addLocalSpan(hidden_arg_locals),
            .result_desc = result_desc_info.desc,
            .next = continuation,
        } }, self.origin);
        if (result_desc_info.materialize) |materialize| {
            const desc = materialize.materialize orelse
                boxyLowerInvariant("boxy dictionary call result descriptor materialization had no descriptor");
            continuation = try self.prependDescriptorArgMaterialization(materialize, desc, continuation);
        }
        continuation = try self.prependDescriptorArgMaterializations(hidden_desc_locals, continuation);
        continuation = try self.prependDescriptorArgMaterializations(call_arg_descriptor_initializers.items, continuation);
        // The operands are lowered last first, under the descriptors this
        // call bound, which are restored once they are lowered. The
        // conversion's leaf descriptors read only the bound dictionary and the
        // enclosing scope, and a generated interpolation iterator operand is
        // built from them, so they are materialized before every operand.
        const items = try self.parent.allocator.alloc(ExprChainItem, operands.len + 2);
        errdefer self.parent.allocator.free(items);
        for (items[0..operands.len], 0..) |*item, offset| {
            const index = operands.len - 1 - offset;
            item.* = .{ .call_operand = .{
                .operand = operands[index],
                .operand_type = operand_types[index],
                .arg_type = arg_types[index],
                .storage_arg_rep = storage_arg_reps[index],
                .lowered = lowered[index],
            } };
        }
        items[operands.len] = .{ .prepend_descriptor_initializers = try self.parent.allocator.dupe(DescriptorArgLocal, pre_arg_descriptor_initializers.items) };
        items[operands.len + 1] = .restore_descriptors;
        snapshot_moved = true;
        return .{ .tail = .{ .chain = .{ .items = items, .current = continuation, .snapshot = descriptor_snapshot } } };
    }

    fn bindConversionResultDescriptorArgs(
        self: *ProcBodyBuilder,
        args: []const Plan.DirectCallHiddenDescriptorArg,
        dict: LIR.LocalId,
        method: names.MethodNameId,
        slot: u32,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!void {
        for (args, 0..) |arg, index| {
            // Constructor descriptors are built by ordinary call lowering from
            // these exact leaf descriptors supplied by conversion evidence.
            if (arg.source_arg_index != null or !self.repIsBareDynamic(arg.rep)) continue;
            const local = try self.addFrameLocal(.opaque_ptr);
            try initializers.append(self.parent.allocator, .{
                .local = local,
                .materialize = .{ .dict_method_hidden = .{
                    .dict = dict,
                    .method = method,
                    .method_slot = slot,
                    .hidden_index = @intCast(index),
                    .shape = .requirement,
                } },
            });
            try self.bindDescriptorIdentityLocalForRep(arg.rep, local, false);
        }
    }

    fn dictionaryCallArgumentDescriptorLocals(
        self: *ProcBodyBuilder,
        arg_reps: []const Plan.TypeRepId,
        arg_locals: []const LIR.LocalId,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error![]LIR.LocalId {
        if (arg_reps.len != arg_locals.len) {
            boxyLowerInvariant("dictionary call argument descriptor arity disagreed with argument locals");
        }
        const desc_locals = try self.parent.allocator.alloc(LIR.LocalId, arg_locals.len);
        errdefer self.parent.allocator.free(desc_locals);
        for (arg_reps, arg_locals, desc_locals) |arg_rep, arg_local, *desc_local| {
            desc_local.* = try self.addFrameLocal(.opaque_ptr);
            const materialization = if (self.parent.result.store.getLocal(arg_local).boxy_desc) |desc|
                DescriptorMaterialization{ .desc = desc }
            else if (self.localDescriptorEnvironmentForLocal(arg_local)) |env| environment: {
                var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
                defer overrides.deinit(self.parent.allocator);
                for (env.bindings) |binding| {
                    if (!try self.repSubtreeContainsDescriptor(arg_rep, binding.desc)) continue;
                    const identity_rep = self.parent.descriptorIdentityRep(binding.rep);
                    for (overrides.items) |override| {
                        if (override.rep != identity_rep) continue;
                        if (override.local != binding.local) {
                            boxyLowerInvariant("dictionary call argument had conflicting exact descriptors for one representation");
                        }
                        break;
                    } else {
                        try overrides.append(self.parent.allocator, .{
                            .rep = identity_rep,
                            .local = binding.local,
                        });
                    }
                }
                if (overrides.items.len != 0) {
                    break :environment try self.descriptorMaterializationForKnownRepWithOverrides(arg_rep, overrides.items);
                }
                break :environment try self.descriptorMaterializationForKnownRep(arg_rep);
            } else try self.descriptorMaterializationForKnownRep(arg_rep);
            try initializers.append(self.parent.allocator, .{
                .local = desc_local.*,
                .materialize = materialization.desc,
                .captures = materialization.captures,
            });
        }
        return desc_locals;
    }

    const DictionaryMethodMatch = struct {
        requirement: Plan.DictionaryRequirementId,
        slot: u32,
    };

    fn dictionaryMethodForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        method: names.MethodNameId,
    ) ?DictionaryMethodMatch {
        const identity_rep = self.dictionaryIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.dictionaries.len == 0) return null;

        const dispatch_name = self.module.canonical_names.methodNameText(method);
        const requirements = self.parent.plan.dictionarySlice(rep.dictionaries);
        for (requirements, 0..) |requirement, requirement_index| {
            const requirement_module = procedureModuleById(self.parent.modules, requirement.source_type.module);
            if (!std.mem.eql(u8, dispatch_name, requirement_module.canonical_names.methodNameText(requirement.fn_name))) continue;
            return .{
                .requirement = @fromBackingInt(@intCast(rep.dictionaries.start + @as(u32, @intCast(requirement_index)))),
                .slot = requirement.slot,
            };
        }
        return null;
    }

    fn dispatchMethodNameIs(
        self: *ProcBodyBuilder,
        method: names.MethodNameId,
        expected: []const u8,
    ) bool {
        return std.mem.eql(u8, self.module.canonical_names.methodNameText(method), expected);
    }

    fn directCallOperandStorageRep(
        self: *ProcBodyBuilder,
        operand: Plan.CallOperand,
        planned_rep: Plan.TypeRepId,
    ) Allocator.Error!Plan.TypeRepId {
        const expr_id = switch (operand) {
            .checked_expr => |expr| expr,
            .generated_interpolation_segments,
            .generated_numeral,
            .generated_quote,
            => return planned_rep,
        };
        const expr = self.module.checked_bodies.expr(expr_id);
        const binder = switch (expr.data) {
            .lookup_local => |lookup| if (lookup.resolved) |ref_id|
                self.resolvedLookupBinder(ref_id)
            else blk: {
                const pattern_index = @backingInt(lookup.pattern);
                if (pattern_index >= self.module.checked_bodies.pattern_binder_by_pattern.len) {
                    boxyLowerInvariant("boxy direct call operand lookup referenced missing binder metadata");
                }
                break :blk self.module.checked_bodies.pattern_binder_by_pattern[pattern_index];
            },
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => null,
        } orelse return planned_rep;
        const binder_index = @backingInt(binder);
        if (binder_index >= self.binder_reps.len) {
            boxyLowerInvariant("boxy direct call operand binder representation exceeded binder storage");
        }
        return self.binder_reps[binder_index] orelse planned_rep;
    }

    fn lowerWorkerCallLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        ret_type: Plan.CheckedTypeIdentity,
        arg_types: []const Plan.CheckedTypeIdentity,
        hidden_desc_arg_types: []const Plan.CheckedTypeIdentity,
        source_args: []const LIR.LocalId,
        actual_arg_reps: ?[]const Plan.TypeRepId,
        arg_substitutions: ?[]const Plan.CallTypeSubstitution,
        ret_substitution: ?Plan.CallTypeSubstitution,
        worker_id: Plan.WorkerPlanId,
        hidden_desc_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_dict_args: []const Plan.DirectCallHiddenDictionaryArg,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker_layout = self.parent.layout_plan.workerLayoutFor(worker_id);
        const worker_args = self.parent.layout_plan.workerLayoutSlice(worker_layout.args);
        if (source_args.len != worker_args.len or arg_types.len != worker_args.len or hidden_desc_arg_types.len != worker_args.len) {
            boxyLowerInvariant("boxy direct call source argument count disagreed with worker layout");
        }
        if (actual_arg_reps) |reps| {
            if (reps.len != source_args.len) {
                boxyLowerInvariant("boxy direct call actual argument representation count disagreed with source args");
            }
        }
        if (arg_substitutions) |substitutions| {
            if (substitutions.len != source_args.len) {
                boxyLowerInvariant("boxy worker call substitution count disagreed with source args");
            }
        }
        const worker_plan = self.parent.plan.workers.items[@backingInt(worker_id)];
        const worker_function = self.functionChildrenForRep(worker_plan.rep) orelse
            boxyLowerInvariant("boxy direct call worker was not a function");
        if (worker_function.arg_count != source_args.len) {
            boxyLowerInvariant("boxy direct call source argument count disagreed with worker representation");
        }
        const worker_function_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(worker_function.rep)].children);
        const worker_arg_children = worker_function_children[worker_function.args_start..][0..worker_function.arg_count];

        const ret_layout = if (worker_layout.ret) |ret| ret else worker_layout.value;
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const target_rep = if (ret_substitution) |substitution| substitution.call_rep else self.repForTypeRef(ret_type);
        const worker_ret_rep = if (ret_substitution) |substitution| substitution.worker_rep else worker_function.ret;
        if (ret_substitution != null and worker_ret_rep != worker_function.ret) {
            boxyLowerInvariant("boxy planned worker return representation disagreed with worker function representation");
        }

        const adapted_args = try self.parent.allocator.alloc(LIR.LocalId, source_args.len);
        defer self.parent.allocator.free(adapted_args);
        const source_arg_reps = try self.parent.allocator.alloc(Plan.TypeRepId, source_args.len);
        defer self.parent.allocator.free(source_arg_reps);
        for (source_args, adapted_args, source_arg_reps, arg_types, worker_args, worker_arg_children, 0..) |source, *adapted, *exact_source_rep, arg_type, arg_layout, worker_arg, arg_index| {
            const source_rep = if (actual_arg_reps) |reps|
                reps[arg_index]
            else if (arg_substitutions) |substitutions|
                substitutions[arg_index].operand_rep
            else
                self.repForTypeRef(arg_type);
            exact_source_rep.* = source_rep;
            const source_layout = self.workerRuntimeLayoutForRep(source_rep);
            if (self.parent.result.store.getLocal(source).layout_idx != source_layout.layoutIdx()) {
                boxyLowerInvariant("boxy direct call actual argument representation disagreed with source local layout");
            }
            const target_arg_rep = if (arg_substitutions) |substitutions| substitutions[arg_index].worker_rep else worker_arg.rep;
            if (arg_substitutions != null and target_arg_rep != worker_arg.rep) {
                boxyLowerInvariant("boxy planned worker argument representation disagreed with worker function representation");
            }
            adapted.* = if (source_layout.layoutIdx() == arg_layout.layoutIdx() and self.descriptorStorageRep(source_rep) == self.descriptorStorageRep(target_arg_rep))
                source
            else
                try self.addFrameBoundaryTargetLocalForRep(target_arg_rep);
            if (adapted.* != source) {
                if (self.localDescriptorEnvironmentForLocal(source)) |env| {
                    try self.recordLocalDescriptorEnvironment(adapted.*, target_arg_rep, env.bindings);
                }
            }
        }
        var pre_adaptation_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer pre_adaptation_descriptor_initializers.deinit(self.parent.allocator);
        const call_arg_reps = try self.parent.allocator.alloc(Plan.TypeRepId, source_args.len);
        defer self.parent.allocator.free(call_arg_reps);
        for (call_arg_reps, arg_types, 0..) |*call_arg_rep, arg_type, arg_index| {
            call_arg_rep.* = if (arg_substitutions) |substitutions| substitutions[arg_index].call_rep else self.repForTypeRef(arg_type);
        }
        const hidden_desc_locals = try self.lowerDirectCallHiddenDescriptorArgs(hidden_desc_args, source_args, source_arg_reps, call_arg_reps);
        defer self.parent.allocator.free(hidden_desc_locals);
        const call_descriptor_snapshot = try self.snapshotDescriptorBindings();
        defer call_descriptor_snapshot.deinit(self.parent.allocator);
        var call_descriptor_bindings_restored = false;
        defer if (!call_descriptor_bindings_restored) self.restoreDescriptorBindings(call_descriptor_snapshot);
        try self.bindDirectCallHiddenDescriptorLocals(hidden_desc_args, hidden_desc_locals, true);
        const hidden_dict_locals = try self.lowerDirectCallHiddenDictionaryArgs(hidden_dict_args);
        defer self.parent.allocator.free(hidden_dict_locals);

        const call_locals = try self.parent.allocator.alloc(LIR.LocalId, adapted_args.len + hidden_desc_locals.len + hidden_dict_locals.len);
        defer self.parent.allocator.free(call_locals);
        @memcpy(call_locals[0..adapted_args.len], adapted_args);
        for (hidden_desc_locals, 0..) |hidden, index| {
            call_locals[adapted_args.len + index] = hidden.local;
        }
        for (hidden_dict_locals, 0..) |hidden, index| {
            call_locals[adapted_args.len + hidden_desc_locals.len + index] = hidden.local;
        }

        var continuation = next;
        const direct_result_desc = try self.directCallResultDescriptorRef(worker_ret_rep, hidden_desc_args, hidden_desc_locals);
        const callee_proc = try self.parent.reserveWorkerProc(worker_id);
        const callee_spec = self.parent.result.store.getProcSpec(callee_proc);
        const provisional_runtime_result_desc = try self.parent.directCallNeedsProvisionalAbi(worker_id, callee_proc);
        const runtime_result_desc = callee_spec.runtime_ret_desc != null or provisional_runtime_result_desc;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc;
        const checked_return_types_match = if (ret_substitution) |substitution|
            planTypeRefEql(substitution.operand_type, substitution.call_type)
        else
            true;
        // A descriptor-bearing target can receive a direct result only when
        // the call can supply that descriptor without changing checked shape.
        const descriptor_boundary_is_direct = !runtime_result_desc and
            ((target_desc == null and direct_result_desc.desc == null) or
                (checked_return_types_match and (target_desc == null or direct_result_desc.desc != null)));
        // A callee that returns its descriptor at runtime writes both the
        // value and that descriptor straight into a target whose descriptor
        // local is this frame's to overwrite, exactly as an erased call does.
        const target_desc_is_shared = if (target_desc) |desc|
            if (desc.localOrNull()) |local| self.localIsDescriptorSlot(local) else false
        else
            false;
        const adopts_callee_descriptor = runtime_result_desc and
            !target_desc_is_shared and
            self.callResultAdoptsCalleeDescriptor(target, target_rep);
        const runtime_boundary_is_direct = runtime_result_desc and
            !target_desc_is_shared and
            self.callResultOutputDescriptorLocal(target) != null and
            self.erasedCallResultCanUseTarget(target_rep, worker_ret_rep);
        var fresh_raw_out_desc: ?LIR.LocalId = null;
        const call_target = if (target_layout == ret_layout.layoutIdx() and
            (adopts_callee_descriptor or
                (self.descriptorStorageRep(target_rep) == self.descriptorStorageRep(worker_ret_rep) and
                    (descriptor_boundary_is_direct or runtime_boundary_is_direct))))
        blk: {
            // A target that only adopts the callee's descriptor keeps the
            // bindings of its own representation; the callee's name nothing
            // the target's other assignments could supply.
            if (self.descriptorStorageRep(target_rep) == self.descriptorStorageRep(worker_ret_rep)) {
                try self.recordDirectCallResultDescriptorEnvironment(target, worker_ret_rep, hidden_desc_args, hidden_desc_locals);
            }
            break :blk target;
        } else blk: {
            const raw_ret = if (runtime_result_desc)
                try self.addFrameLocalForRepWithRequiredFreshDescriptor(worker_ret_rep)
            else
                try self.addFrameLocal(self.workerRuntimeLayoutForRep(worker_ret_rep).layoutIdx());
            try self.recordDirectCallResultDescriptorEnvironment(raw_ret, worker_ret_rep, hidden_desc_args, hidden_desc_locals);
            const raw_result_desc = self.resultDescriptorForCallTarget(raw_ret, direct_result_desc);
            if (self.parent.result.store.getLocal(raw_ret).boxy_desc == null) {
                if (raw_result_desc.desc) |desc| {
                    self.parent.result.store.setLocalBoxyDesc(raw_ret, desc);
                }
            }
            continuation = try self.assignPlannedCallBoundary(target, raw_ret, target_rep, worker_ret_rep, continuation);
            if (runtime_result_desc) {
                if (self.parent.result.store.getLocal(raw_ret).boxy_desc) |fresh_desc| {
                    fresh_raw_out_desc = fresh_desc.localOrNull();
                }
            }
            break :blk raw_ret;
        };
        const out_desc = if (runtime_result_desc)
            fresh_raw_out_desc orelse self.callResultOutputDescriptorLocal(call_target)
        else
            null;
        if (runtime_result_desc and out_desc == null) {
            const identity_rep = self.descriptorStorageRep(worker_ret_rep);
            const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
            const return_layout = self.workerRuntimeLayoutForRep(worker_ret_rep).layoutIdx();
            base.invariant(
                "boxy lower invariant violated: runtime direct-call result had no descriptor output local: worker={d} callee={d} rep={d} identity={d} descriptor={any} dynamic={any} layout={d} nested={any} target_desc={any}",
                .{
                    @backingInt(worker_id),
                    @backingInt(callee_proc),
                    @backingInt(worker_ret_rep),
                    @backingInt(identity_rep),
                    identity.descriptor != null,
                    identity.contains_dynamic,
                    @backingInt(return_layout),
                    self.parent.layoutNeedsNestedBoxyDesc(return_layout),
                    self.parent.result.store.getLocal(call_target).boxy_desc,
                },
            );
        }
        const static_direct_result_desc = if (provisional_runtime_result_desc and direct_result_desc.desc == null)
            ResultDescriptorSource{ .desc = try self.parent.staticDescRefForRep(self.descriptorStorageRep(worker_ret_rep)) }
        else
            direct_result_desc;
        const static_result_desc_info = if (!runtime_result_desc or provisional_runtime_result_desc)
            self.resultDescriptorForCallTarget(call_target, static_direct_result_desc)
        else
            ResultDescriptorSource{};
        const result_desc_info = if (runtime_result_desc) ResultDescriptorSource{} else static_result_desc_info;
        const result_desc = result_desc_info.desc;
        if (self.parent.result.store.getLocal(call_target).boxy_desc == null) {
            if (result_desc) |desc| {
                self.parent.result.store.setLocalBoxyDesc(call_target, desc);
            }
        }

        if (out_desc) |local| try self.markDescriptorLocalBound(local);

        const call_args = try self.parent.result.store.addLocalSpan(call_locals);
        const call_next = continuation;
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_call = .{
            .target = call_target,
            .proc = callee_proc,
            .args = call_args,
            .result_desc = result_desc,
            .out_desc = out_desc,
            .next = call_next,
        } }, self.origin);
        if (provisional_runtime_result_desc) {
            const provisional_call = continuation;
            const static_call = try self.parent.result.store.addCFStmt(.{ .assign_call = .{
                .target = call_target,
                .proc = callee_proc,
                .args = call_args,
                .result_desc = static_result_desc_info.desc,
                .out_desc = null,
                .next = call_next,
            } }, self.origin);
            var static_replacement = static_call;
            if (static_result_desc_info.materialize) |materialize| {
                const desc = materialize.materialize orelse
                    boxyLowerInvariant("boxy recursive direct-call static descriptor materialization had no descriptor");
                static_replacement = try self.prependDescriptorArgMaterialization(materialize, desc, static_replacement);
            } else if (out_desc) |local| {
                // A descriptor local initialized at procedure entry already
                // holds what the static form's result is described by.
                if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) == null) {
                    boxyLowerInvariant("boxy recursive direct-call static form had no descriptor materialization");
                }
            }
            try self.parent.pending_direct_call_descriptor_abis.append(self.parent.allocator, .{
                .callee = callee_proc,
                .provisional_call = provisional_call,
                .static_replacement = static_replacement,
                .static_call = static_call,
            });
        }
        if (result_desc_info.materialize) |materialize| {
            const desc = materialize.materialize orelse
                boxyLowerInvariant("boxy direct call result descriptor materialization had no descriptor");
            continuation = try self.prependDescriptorArgMaterialization(materialize, desc, continuation);
        }
        continuation = try self.prependHiddenDictionaryArgMaterialization(hidden_dict_locals, continuation);
        // Hidden descriptors read only the original operands and the caller
        // frame, so they are initialized before the operands are adapted and
        // describe the worker representations those adaptations target.
        const enclosing_call_boundary_substitution = self.call_boundary_substitution;
        self.call_boundary_substitution = hidden_desc_args;
        defer self.call_boundary_substitution = enclosing_call_boundary_substitution;
        continuation = try self.prependWorkerCallArgAdaptations(arg_types, source_args, adapted_args, worker_arg_children, actual_arg_reps, arg_substitutions, continuation);
        continuation = try self.prependDescriptorArgMaterializations(hidden_desc_locals, continuation);
        self.restoreDescriptorBindings(call_descriptor_snapshot);
        call_descriptor_bindings_restored = true;
        return try self.prependDescriptorArgMaterializations(pre_adaptation_descriptor_initializers.items, continuation);
    }

    fn prependWorkerCallArgAdaptations(
        self: *ProcBodyBuilder,
        arg_types: []const Plan.CheckedTypeIdentity,
        sources: []const LIR.LocalId,
        targets: []const LIR.LocalId,
        worker_arg_children: []const Plan.RepChild,
        actual_arg_reps: ?[]const Plan.TypeRepId,
        arg_substitutions: ?[]const Plan.CallTypeSubstitution,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        var index = arg_types.len;
        while (index > 0) {
            index -= 1;
            if (sources[index] == targets[index]) continue;
            const target_rep = if (arg_substitutions) |substitutions| substitutions[index].worker_rep else worker_arg_children[index].rep;
            const source_rep = if (actual_arg_reps) |reps|
                reps[index]
            else if (arg_substitutions) |substitutions|
                substitutions[index].operand_rep
            else
                self.repForTypeRef(arg_types[index]);
            continuation = try self.assignPlannedCallBoundary(
                targets[index],
                sources[index],
                target_rep,
                source_rep,
                continuation,
            );
        }
        return continuation;
    }

    fn assignPlannedCallBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignPlannedCallBoundaryWithSourceMode(
            target,
            source,
            target_rep,
            source_rep,
            .move,
            next,
        );
    }

    fn assignPlannedCallBoundaryCopyingSource(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignPlannedCallBoundaryWithSourceMode(
            target,
            source,
            target_rep,
            source_rep,
            .copy,
            next,
        );
    }

    fn assignPlannedCallBoundaryWithSourceMode(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (try self.plannedCallBoundaryLowersStructure(target, source, target_rep, source_rep)) {
            return try self.assignRepresentationBoundaryConsumingSource(target, source, target_rep, source_rep, next);
        }
        return try self.assignRuntimeAdapterBoundary(target, source, target_rep, source_rep, source_mode, next);
    }

    /// Whether a planned call boundary converts through lowering rather than
    /// one runtime adapter. A runtime adapter converts bytes through
    /// descriptors, which do not describe a callable's erased-call
    /// convention. A callable directly in the value, or inside its record,
    /// tuple, tag, or named structure, crosses through lowering, which wraps
    /// each callable in an adapter.
    fn plannedCallBoundaryLowersStructure(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_is_callable = self.functionChildrenForRep(target_rep) != null and
            self.parent.result.layouts.getLayout(target_layout).tag == .erased_callable;
        const source_is_callable = self.functionChildrenForRep(source_rep) != null and
            self.parent.result.layouts.getLayout(source_layout).tag == .erased_callable;
        return target_is_callable or source_is_callable or
            try self.repHoldsCallableInStructure(target_rep) or
            try self.repHoldsCallableInStructure(source_rep);
    }

    /// Convert a value through one runtime adapter, which rewrites its bytes by
    /// source and target descriptors. Descriptors do not describe a callable's
    /// erased-call convention, so the value holds no callable outside a shared
    /// nominal backing template.
    fn assignRuntimeAdapterBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (try self.repHoldsCallableInStructure(target_rep) or try self.repHoldsCallableInStructure(source_rep)) {
            boxyLowerInvariant("runtime boxy adapter reached a value holding a callable");
        }
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const source_desc_info = try self.adapterDescriptorForSource(source, source_rep);
        const source_desc = source_desc_info.desc orelse
            boxyLowerInvariant("planned boxy call adapter had no source descriptor");
        var target_desc_prerequisites = std.ArrayList(DescriptorArgLocal).empty;
        defer target_desc_prerequisites.deinit(self.parent.allocator);
        const planned_target_desc_info = if (self.repIsBareDynamic(self.descriptorStorageRep(target_rep)) or
            self.repIsOpenRecord(target_rep))
            ResultDescriptorSource{ .desc = source_desc, .preserves_source_desc = true }
        else
            try self.adapterDescriptorForCallBoundary(
                target_rep,
                source_rep,
                source_desc_info,
                &target_desc_prerequisites,
            );
        const target_desc_info = self.resultDescriptorForCallTarget(target, planned_target_desc_info);
        const target_desc = target_desc_info.desc orelse
            boxyLowerInvariant("planned boxy call adapter had no target descriptor");
        if (self.parent.result.store.getLocal(target).boxy_desc == null) {
            self.parent.result.store.setLocalBoxyDesc(target, target_desc);
        }
        const value_storage_is_interchangeable = source_layout == target_layout or
            (self.parent.layoutIsBoxStorage(source_layout) and
                self.parent.layoutIsBoxStorage(target_layout));
        const operation: LirProgram.BoxyAdapterOperation = if (value_storage_is_interchangeable and
            (std.meta.eql(source_desc, target_desc) or target_desc_info.preserves_source_desc))
            .relabel
        else
            .materialize;
        const adapter = try self.internAdapter(
            operation,
            source_layout,
            target_layout,
            source_mode == .move,
        );
        var continuation = try self.recordDescriptorEnvironmentFromDescriptorRef(
            target,
            target_rep,
            target_desc,
            next,
        );
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
            .target = target,
            .source = source,
            .adapter = adapter,
            .source_desc = source_desc,
            .target_desc = target_desc,
            .source_mode = source_mode,
            .next = continuation,
        } }, self.glueOrigin());
        continuation = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, continuation);
        continuation = try self.prependDescriptorArgMaterializations(target_desc_prerequisites.items, continuation);
        continuation = try self.prependOptionalDescriptorMaterialization(target_desc_info.prerequisite, continuation);
        return try self.prependOptionalDescriptorMaterialization(source_desc_info.materialize, continuation);
    }

    /// Whether an erased callable sits inside this representation's record
    /// fields, tuple items, tag payloads, or alias and nominal backings.
    /// Callables inside list items and box payloads are behind their
    /// container's own allocation and are not structure of this value. A
    /// shared nominal backing template states its callables over the
    /// nominal's formals, so every instantiation shares their erased-call
    /// convention and only the formals' descriptors differ.
    fn repHoldsCallableInStructure(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!bool {
        if (self.parent.rep_holds_callable.len == 0) {
            self.parent.rep_holds_callable = try self.parent.allocator.alloc(?bool, self.parent.plan.representations.items.len);
            @memset(self.parent.rep_holds_callable, null);
        }
        const rep_index = @backingInt(rep_id);
        if (rep_index >= self.parent.rep_holds_callable.len) {
            boxyLowerInvariant("boxy callable-structure query referenced a representation outside its cache");
        }
        if (self.parent.rep_holds_callable[rep_index]) |known| return known;
        var visited = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer visited.deinit();
        const holds = try self.repHoldsCallableInStructureVisited(rep_id, &visited);
        self.parent.rep_holds_callable[rep_index] = holds;
        return holds;
    }

    /// Whether a value of `root` holds a callable in its own structure.
    fn repHoldsCallableInStructureVisited(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        visited: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |rep_id| {
            if ((try visited.getOrPut(rep_id)).found_existing) continue;
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            if (rep.kind == .erased_callable) return true;
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (self.parent.plan.childIsSharedBackingTemplate(rep_id, child)) continue;
                switch (child.role) {
                    .record_field, .tuple_elem, .tag_payload, .alias_backing, .nominal_backing => try pending.append(allocator, child.rep),
                    .alias_arg, .nominal_arg, .nominal_padding_field, .record_ext, .tag_ext, .function_arg, .function_ret, .list_elem, .box_payload => {},
                }
            }
        }
        return false;
    }

    fn adapterDescriptorForSource(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        if (self.parent.result.store.getLocal(source).boxy_desc) |desc| {
            const template = if (desc.localOrNull()) |local|
                self.descriptorTemplateForLocal(local)
            else
                null;
            return .{
                .desc = desc,
                .template = template,
            };
        }
        return try self.adapterDescriptorFromMaterialization(try self.descriptorMaterializationForSourceRep(source_rep));
    }

    fn adapterDescriptorForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const materialization = try self.descriptorMaterializationForKnownRep(rep_id);
        return try self.adapterDescriptorFromMaterialization(materialization);
    }

    fn adapterDescriptorFromMaterialization(
        self: *ProcBodyBuilder,
        materialization: DescriptorMaterialization,
    ) Allocator.Error!ResultDescriptorSource {
        if (materialization.captures.len == 0) return .{ .desc = materialization.desc };

        const local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .desc = .{ .local = local },
            .materialize = materialization.initializer(local),
        };
    }

    fn descriptorTemplateOf(_: *const ProcBodyBuilder, info: ResultDescriptorSource) ?DescriptorMaterialization {
        return resultDescriptorTemplate(info);
    }

    /// The static template `info`'s descriptor instantiates, if any. A
    /// materialization that reads a nested descriptor instantiates the static
    /// nested descriptor of its parent's template; a read path, tag extension
    /// read, or tag residual has no static template.
    fn resultDescriptorTemplate(
        info: ResultDescriptorSource,
    ) ?DescriptorMaterialization {
        const desc = info.desc orelse return null;
        const candidate: DescriptorMaterialization = switch (desc) {
            .static => DescriptorMaterialization{ .desc = desc },
            .local, .runtime, .dict_method_arg, .dict_method_hidden => info.template orelse if (info.materialize) |materialize| materialized: {
                // Only a whole-descriptor materialization is this value's
                // template. Nested, path, and tag-extension reads name the
                // enclosing descriptor they read from.
                if (materialize.nested_index != null or materialize.read_path.len != 0 or
                    materialize.tag_ext or materialize.tag_residual_for != null)
                {
                    return null;
                }
                break :materialized .{
                    .desc = materialize.materialize orelse return null,
                    .captures = materialize.captures,
                };
            } else return null,
        };
        return switch (candidate.desc) {
            .static => candidate,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => null,
        };
    }

    fn recordDescriptorLocalTemplate(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        template: DescriptorMaterialization,
    ) Allocator.Error!void {
        try self.descriptor_local_templates.ensureUnusedCapacity(self.parent.allocator, 1);
        const position = try self.descriptor_local_template_positions.getOrPut(self.parent.allocator, local);
        if (position.found_existing) {
            const entry = &self.descriptor_local_templates.items[position.value_ptr.*];
            const existing = entry.template orelse return;
            if (!std.meta.eql(existing, template)) entry.template = null;
            return;
        }
        position.value_ptr.* = @intCast(self.descriptor_local_templates.items.len);
        self.descriptor_local_templates.appendAssumeCapacity(.{
            .local = local,
            .template = template,
        });
    }

    fn descriptorTemplateForLocal(
        self: *const ProcBodyBuilder,
        local: LIR.LocalId,
    ) ?DescriptorMaterialization {
        const position = self.descriptor_local_template_positions.get(local) orelse return null;
        return self.descriptor_local_templates.items[position].template;
    }

    /// Whether two uses of one nominal declaration, along their backing
    /// chains, bind some formal to actuals with different storage. A formal
    /// holds its value in the worker representation of its use's actual; a
    /// target actual that is a bare type parameter has no storage shape of
    /// its own and keeps the source's.
    fn nominalUsesStoreFormalsDifferently(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        const plan = self.parent.plan;
        var target = target_rep;
        var source = source_rep;
        for (0..plan.representations.items.len) |_| {
            const target_substitutions = plan.representations.items[@backingInt(target)].nominal_backing_arg_substitutions;
            const source_substitutions = plan.representations.items[@backingInt(source)].nominal_backing_arg_substitutions;
            if (target_substitutions.len != 0 and
                plan.nominalBackingDeclaration(target_substitutions) == plan.nominalBackingDeclaration(source_substitutions))
            {
                var substitutions = plan.nominalBackingSubstitutions(target_substitutions);
                while (substitutions.next()) |substitution| {
                    if (substitution.formal_rep == null) continue;
                    if (self.repIsBareDynamic(self.descriptorStorageRep(substitution.actual_rep))) continue;
                    const source_actual = plan.nominalBackingActual(source_substitutions, substitution.arg_index) orelse
                        boxyLowerInvariant("uses of one nominal declaration had different argument counts");
                    if (!self.representationBoundaryIsDirect(substitution.actual_rep, source_actual)) return true;
                }
            }
            target = self.parent.descriptorBackingShapeRep(target) orelse return false;
            source = self.parent.descriptorBackingShapeRep(source) orelse return false;
        }
        boxyLowerInvariant("cyclic nominal backing chain at a call boundary");
    }

    /// Whether a boxed target position's formal is bound, by an enclosing
    /// nominal scope, to a known actual. Such a box stores the actual's own
    /// representation, which the target template describes; materialization
    /// converts the source payload into it rather than boxing the source's
    /// storage.
    fn boxedTargetHasBoundActual(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity = self.descriptorStorageRep(rep_id);
        const actual = self.nominalFormalActualBelow(self.nominal_formal_bindings.items.len, identity) orelse return false;
        return !self.repIsBareDynamic(actual);
    }

    fn adapterTupleDescriptorForCallBoundary(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_desc_info: ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        const target_tuple_rep = self.tupleRepForBoundary(target_rep) orelse return null;
        const source_tuple_rep = self.tupleRepForBoundary(source_rep) orelse return null;
        const target_tuple = self.parent.plan.representations.items[@backingInt(target_tuple_rep)];
        const source_tuple = self.parent.plan.representations.items[@backingInt(source_tuple_rep)];

        const target_materialization = try self.descriptorMaterializationForExactRep(target_rep);
        const target_template_id = switch (target_materialization.desc) {
            .static => |desc_id| desc_id,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy tuple adapter target descriptor template was not static"),
        };
        const target_template = self.parent.result.boxy_type_descs.items[@backingInt(target_template_id)];

        const source_desc = source_desc_info.desc orelse
            boxyLowerInvariant("boxy tuple adapter source had no descriptor");
        const source_materialization = self.descriptorTemplateOf(source_desc_info);
        const source_template: ?LirProgram.BoxyTypeDesc = if (source_materialization) |materialization| blk: {
            const source_template_id = switch (materialization.desc) {
                .static => |desc_id| desc_id,
                .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy tuple adapter source descriptor template was not static"),
            };
            break :blk self.parent.result.boxy_type_descs.items[@backingInt(source_template_id)];
        } else null;

        const target_nested = self.parent.result.boxy_desc_refs.items[target_template.nested_descs.start..][0..target_template.nested_descs.len];
        var specialized_nested = std.ArrayList(LIR.BoxyDescRef).empty;
        defer specialized_nested.deinit(self.parent.allocator);
        try specialized_nested.appendSlice(self.parent.allocator, target_nested);

        var extra_captures = std.ArrayList(LIR.LocalId).empty;
        defer extra_captures.deinit(self.parent.allocator);
        var specialized = false;
        for (self.parent.plan.childSlice(target_tuple.children)) |target_child| {
            const target_index = switch (target_child.role) {
                .tuple_elem => |index| index,
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("boxy tuple adapter target had a non-tuple child role"),
            };
            const storage_layout = self.parent.recordPayloadFieldLayout(target_template.payload_layout, target_index);
            if (!self.parent.layoutIsBoxStorage(storage_layout)) continue;
            if (self.boxedTargetHasBoundActual(target_child.rep)) continue;

            const target_nested_index = self.tupleElemNestedDescriptorIndex(target_tuple_rep, target_index);
            if (target_nested_index >= specialized_nested.items.len) {
                boxyLowerInvariant("boxy tuple adapter target nested descriptor index exceeded template");
            }

            var source_child: ?Plan.RepChild = null;
            for (self.parent.plan.childSlice(source_tuple.children)) |candidate| {
                const source_index = switch (candidate.role) {
                    .tuple_elem => |index| index,
                    .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("boxy tuple adapter source had a non-tuple child role"),
                };
                if (source_index != target_index) continue;
                if (source_child != null) {
                    boxyLowerInvariant("boxy tuple adapter source had duplicate element indexes");
                }
                source_child = candidate;
            }
            const matched_source_child = source_child orelse
                boxyLowerInvariant("boxy tuple adapter source was missing target element");

            const source_nested_index = self.tupleElemNestedDescriptorIndex(source_tuple_rep, target_index);
            const exact_source_desc: LIR.BoxyDescRef = if (source_template) |template| source_nested: {
                if (source_nested_index >= template.nested_descs.len) {
                    boxyLowerInvariant("boxy tuple adapter source nested descriptor index exceeded template");
                }
                break :source_nested self.parent.result.boxy_desc_refs.items[template.nested_descs.start + source_nested_index];
            } else if (self.payloadFieldCarriesRuntimeDesc(source_tuple_rep, source_nested_index)) source_nested: {
                const nested_local = try self.addFrameLocal(.opaque_ptr);
                try prerequisites.append(self.parent.allocator, .{
                    .local = nested_local,
                    .materialize = source_desc,
                    .nested_index = source_nested_index,
                });
                break :source_nested .{ .local = nested_local };
            } else source_known: {
                const source_elem_desc = try self.adapterDescriptorForKnownRep(matched_source_child.rep);
                if (source_elem_desc.prerequisite) |prerequisite| {
                    try prerequisites.append(self.parent.allocator, prerequisite);
                }
                if (source_elem_desc.materialize) |materialize| {
                    try prerequisites.append(self.parent.allocator, materialize);
                }
                break :source_known source_elem_desc.desc orelse
                    boxyLowerInvariant("boxy tuple adapter source element had no exact descriptor");
            };

            specialized_nested.items[target_nested_index] = exact_source_desc;
            if (exact_source_desc.localOrNull()) |local| {
                try appendUniqueLocal(self.parent.allocator, &extra_captures, local);
            }
            specialized = true;
        }
        if (!specialized) return null;

        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.appendSlice(self.parent.allocator, specialized_nested.items);
        const specialized_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        var specialized_template = target_template;
        specialized_template.nested_descs = .{ .start = nested_start, .len = @intCast(specialized_nested.items.len) };
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, specialized_template);

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);
        const target_captures = self.parent.result.store.getLocalSpan(target_materialization.captures);
        for (0..GuardedList.borrowLen(target_captures)) |index| {
            try appendUniqueLocal(self.parent.allocator, &captures, GuardedList.at(target_captures, index));
        }
        if (source_materialization) |materialization| {
            const source_captures = self.parent.result.store.getLocalSpan(materialization.captures);
            for (0..GuardedList.borrowLen(source_captures)) |index| {
                try appendUniqueLocal(self.parent.allocator, &captures, GuardedList.at(source_captures, index));
            }
        }
        for (extra_captures.items) |local| {
            try appendUniqueLocal(self.parent.allocator, &captures, local);
        }

        const capture_span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return try self.adapterDescriptorFromMaterialization(.{
            .desc = .{ .static = specialized_id },
            .captures = capture_span,
        });
    }

    fn appendResultDescriptorInitializers(
        self: *ProcBodyBuilder,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
        info: ResultDescriptorSource,
    ) Allocator.Error!void {
        const initializers = [_]?DescriptorArgLocal{ info.prerequisite, info.materialize };
        for (initializers) |maybe_initializer| {
            const initializer = maybe_initializer orelse continue;
            var already_present = false;
            for (prerequisites.items) |existing| {
                if (existing.local == initializer.local) {
                    already_present = true;
                    break;
                }
            }
            if (!already_present) try prerequisites.append(self.parent.allocator, initializer);
        }
    }

    // Call-boundary adapter descriptors //
    //
    // A boundary's adapter descriptor specializes the target's descriptor
    // template by the adapted descriptors of the source's components, and
    // components follow type nesting, so each boundary still waiting on a
    // component's adapted descriptor is a frame on one heap-backed stack.
    // Frames append descriptors, spans, locals, and prerequisites in the
    // order a direct recursive adaptation would.

    const AdapterRequest = struct {
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_desc_info: ResultDescriptorSource,
    };

    const AdapterStep = union(enum) {
        /// The frame needs this component boundary's adapted descriptor.
        request: AdapterRequest,
        /// The frame's boundary is adapted.
        done: ResultDescriptorSource,
        /// The boundary moved on to a frame of its next specialization, which
        /// runs next.
        next_frame,
    };

    /// An attempt's outcome: its descriptor, its declining, or the component
    /// boundary it needs next.
    const AdapterAttemptStep = union(enum) {
        request: AdapterRequest,
        finished: ?ResultDescriptorSource,
    };

    /// One boundary being adapted.
    const AdapterFrame = struct {
        request: AdapterRequest,
        entry_index: usize,
        stage: union(enum) {
            tag: *AdapterTagState,
            aggregate: *AdapterFieldsState,
            record: *AdapterFieldsState,
            list: *AdapterListState,
        },

        fn deinit(self: *AdapterFrame, allocator: Allocator) void {
            switch (self.stage) {
                .tag => |state| {
                    state.deinit(allocator);
                    allocator.destroy(state);
                },
                .aggregate, .record => |state| {
                    state.deinit(allocator);
                    allocator.destroy(state);
                },
                .list => |state| allocator.destroy(state),
            }
        }
    };

    /// A tag union boundary's payload specialization.
    const AdapterTagState = struct {
        materialization: DescriptorMaterialization,
        template: LirProgram.BoxyTypeDesc,
        source_desc: LIR.BoxyDescRef,
        source_materialization: ?DescriptorMaterialization,
        source_template: LirProgram.BoxyTypeDesc,
        target_plan_variants: []const Plan.TagVariant,
        source_plan_variants: []const Plan.TagVariant,
        // Payload specialization appends to the global tag descriptor
        // tables, so the entries this boundary walks are snapshots.
        target_template_variants: []LirProgram.BoxyTagVariant,
        source_template_variants: []LirProgram.BoxyTagVariant,
        specialized_variants: std.ArrayList(LirProgram.BoxyTagVariant) = .empty,
        payload_desc_specialized: bool = false,
        extra_captures: std.ArrayList(LIR.LocalId) = .empty,
        variant: usize = 0,
        current: ?struct {
            specialized_variant: LirProgram.BoxyTagVariant,
            target_payloads: []const Plan.RepChild,
            source_payloads: []const Plan.RepChild,
            target_descs: []LirProgram.BoxyTagPayloadDesc,
            source_descs: []LirProgram.BoxyTagPayloadDesc,
            specialized_descs: std.ArrayList(LirProgram.BoxyTagPayloadDesc) = .empty,
            variant_specialized: bool = false,
            payload: usize = 0,
            /// The payload descriptor waiting on its adapted descriptor.
            pending: LirProgram.BoxyTagPayloadDesc = undefined,
        } = null,

        fn deinit(self: *AdapterTagState, allocator: Allocator) void {
            allocator.free(self.target_template_variants);
            allocator.free(self.source_template_variants);
            self.specialized_variants.deinit(allocator);
            self.extra_captures.deinit(allocator);
            if (self.current) |*current| {
                allocator.free(current.target_descs);
                allocator.free(current.source_descs);
                current.specialized_descs.deinit(allocator);
            }
        }
    };

    /// A record or declared aggregate boundary's field specialization.
    const AdapterFieldsState = struct {
        kind: AdapterFieldsKind,
        target_materialization: DescriptorMaterialization,
        target_template: LirProgram.BoxyTypeDesc,
        source_desc: LIR.BoxyDescRef,
        source_materialization: ?DescriptorMaterialization,
        source_template: ?LirProgram.BoxyTypeDesc,
        target_aggregate_rep: Plan.TypeRepId,
        source_aggregate_rep: Plan.TypeRepId,
        specialized_nested: std.ArrayList(LIR.BoxyDescRef) = .empty,
        extra_captures: std.ArrayList(LIR.LocalId) = .empty,
        specialized: bool = false,
        /// The declared aggregate's fields in layout order; empty for a record.
        declared_fields: []Plan.DeclaredField = &.{},
        index: usize = 0,
        target_field_index: u32 = 0,
        /// The nested descriptor slot waiting on its adapted descriptor.
        pending_nested_index: usize = 0,

        fn deinit(self: *AdapterFieldsState, allocator: Allocator) void {
            self.specialized_nested.deinit(allocator);
            self.extra_captures.deinit(allocator);
            allocator.free(self.declared_fields);
        }
    };

    /// A list boundary waiting on its element boundary.
    const AdapterListState = struct {
        known: ResultDescriptorSource,
        known_desc: LirProgram.BoxyTypeDesc,
        target_layout: layout.Idx,
        source_elem_desc_info: ResultDescriptorSource,
        element: AdapterRequest,
    };

    /// How an attempt at a specialization begins.
    fn AdapterAttemptBegin(comptime State: type) type {
        return union(enum) {
            /// The attempt finished without a component boundary: with its
            /// descriptor, or declining.
            finished: ?ResultDescriptorSource,
            /// The attempt walks component boundaries.
            state: *State,
        };
    }

    fn adapterDescriptorForCallBoundary(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_desc_info: ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!ResultDescriptorSource {
        const allocator = self.parent.allocator;
        var frames: std.ArrayList(AdapterFrame) = .empty;
        const entries_len = self.adapter_descriptor_entries.items.len;
        defer {
            for (frames.items) |*frame| frame.deinit(allocator);
            frames.deinit(allocator);
            self.adapter_descriptor_entries.shrinkRetainingCapacity(entries_len);
        }
        var result = try self.beginAdapterBoundary(&frames, .{
            .target_rep = target_rep,
            .source_rep = source_rep,
            .source_desc_info = source_desc_info,
        }, prerequisites);
        while (frames.items.len != 0) {
            switch (try self.stepAdapterFrame(&frames, result, prerequisites)) {
                .request => |request| result = try self.beginAdapterBoundary(&frames, request, prerequisites),
                .done => |done| result = done,
                .next_frame => result = null,
            }
        }
        return result.?;
    }

    /// Begin adapting a boundary: its descriptor when no component needs
    /// adapting, or null with its frame pushed.
    fn beginAdapterBoundary(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        request: AdapterRequest,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        const source_desc = request.source_desc_info.desc orelse
            boxyLowerInvariant("planned call adapter source descriptor was unavailable");
        const key = AdapterDescriptorIdentity{
            .target_rep = request.target_rep,
            .source_rep = request.source_rep,
            .source_desc = source_desc,
        };
        for (self.adapter_descriptor_entries.items, 0..) |entry, index| {
            if (!std.meta.eql(entry.key, key)) continue;
            const recursive_desc = entry.recursive_desc orelse reserve: {
                const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
                try self.parent.result.boxy_type_descs.append(self.parent.allocator, reserved_boxy_type_desc);
                self.adapter_descriptor_entries.items[index].recursive_desc = desc_id;
                break :reserve desc_id;
            };
            return .{ .desc = .{ .static = recursive_desc } };
        }

        const entry_index = self.adapter_descriptor_entries.items.len;
        try self.adapter_descriptor_entries.append(self.parent.allocator, .{ .key = key });
        const result = try self.startAdapterBody(frames, request, entry_index, prerequisites) orelse return null;
        return try self.finishAdapterEntry(entry_index, result);
    }

    /// Fill a recursive reservation of this boundary's descriptor, and leave
    /// the boundary.
    fn finishAdapterEntry(self: *ProcBodyBuilder, entry_index: usize, result: ResultDescriptorSource) Allocator.Error!ResultDescriptorSource {
        if (self.adapter_descriptor_entries.items[entry_index].recursive_desc) |recursive_desc| {
            const template_ref = if (result.materialize) |materialize|
                materialize.materialize orelse
                    boxyLowerInvariant("recursive boxy adapter descriptor materialization had no static template")
            else
                result.desc orelse boxyLowerInvariant("recursive boxy adapter descriptor had no result");
            const template_id = switch (template_ref) {
                .static => |desc_id| desc_id,
                .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("recursive boxy adapter descriptor had no static template"),
            };
            if (template_id == recursive_desc) {
                boxyLowerInvariant("recursive boxy adapter descriptor resolved only to its unfinished reservation");
            }
            self.parent.result.boxy_type_descs.items[@backingInt(recursive_desc)] =
                self.parent.result.boxy_type_descs.items[@backingInt(template_id)];
        }
        std.debug.assert(self.adapter_descriptor_entries.items.len == entry_index + 1);
        self.adapter_descriptor_entries.items.len -= 1;
        return result;
    }

    /// The body's result when it needs no component adapted; otherwise
    /// null, with the frame waiting on a component pushed.
    fn startAdapterBody(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        request: AdapterRequest,
        entry_index: usize,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const source_desc_info = request.source_desc_info;
        const target_layout = self.workerRuntimeLayoutForRep(target_rep).layoutIdx();
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        const target_tag = self.parent.result.layouts.getLayout(target_layout).tag;
        const source_tag = self.parent.result.layouts.getLayout(source_layout).tag;
        const target_is_box = target_tag == .box or target_tag == .box_of_zst or target_tag == .erased_box;
        const source_is_box = source_tag == .box or source_tag == .box_of_zst or source_tag == .erased_box;

        // A bare dynamic box has no target shape beyond the concrete source
        // allocation, so its descriptor must remain the exact source
        // descriptor. Structurally constrained dynamic boxes continue through
        // target descriptor specialization below.
        const target_is_bare_dynamic = self.repIsBareDynamic(target_rep) or self.repIsOpenRecord(target_rep);
        if (target_is_bare_dynamic and target_is_box and !source_is_box) {
            var result = source_desc_info;
            result.preserves_source_desc = true;
            return result;
        }
        if (target_is_bare_dynamic and target_is_box and source_is_box and target_layout == source_layout and target_tag == .erased_box) {
            var result = source_desc_info;
            result.preserves_source_desc = true;
            return result;
        }

        // Both sides share one nominal backing template, so its positions do
        // not name either side's storage. When the uses bind a formal to
        // actuals that store differently, the target's storage is its own
        // backing under its own actuals, and the conversion produces it.
        if (self.nominalUsesStoreFormalsDifferently(target_rep, source_rep)) {
            return try self.adapterDescriptorFromMaterialization(
                try self.descriptorMaterializationForExactRep(target_rep),
            );
        }
        switch (try self.beginAdapterTag(request)) {
            .finished => |finished| if (finished) |result| return result,
            .state => |state| {
                try self.pushAdapterFrame(frames, .{ .request = request, .entry_index = entry_index, .stage = .{ .tag = state } });
                return null;
            },
        }
        return try self.continueAdapterAfterTag(frames, request, entry_index, prerequisites);
    }

    fn pushAdapterFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(AdapterFrame), frame: AdapterFrame) Allocator.Error!void {
        var pending = frame;
        frames.append(self.parent.allocator, pending) catch |err| {
            pending.deinit(self.parent.allocator);
            return err;
        };
    }

    fn popAdapterFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(AdapterFrame)) void {
        var frame = frames.pop().?;
        frame.deinit(self.parent.allocator);
    }

    /// Continue a boundary whose tag specialization declined: the declared
    /// aggregate, record, tuple, and list specializations in turn.
    fn continueAdapterAfterTag(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        request: AdapterRequest,
        entry_index: usize,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        if (try self.beginAdapterFields(request, .aggregate)) |state| {
            try self.pushAdapterFrame(frames, .{ .request = request, .entry_index = entry_index, .stage = .{ .aggregate = state } });
            return null;
        }
        return try self.continueAdapterAfterAggregate(frames, request, entry_index, prerequisites);
    }

    fn continueAdapterAfterAggregate(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        request: AdapterRequest,
        entry_index: usize,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        if (try self.beginAdapterFields(request, .record)) |state| {
            try self.pushAdapterFrame(frames, .{ .request = request, .entry_index = entry_index, .stage = .{ .record = state } });
            return null;
        }
        return try self.continueAdapterAfterRecord(frames, request, entry_index, prerequisites);
    }

    fn continueAdapterAfterRecord(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        request: AdapterRequest,
        entry_index: usize,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        if (try self.adapterTupleDescriptorForCallBoundary(
            request.target_rep,
            request.source_rep,
            request.source_desc_info,
            prerequisites,
        )) |tuple_desc| {
            return tuple_desc;
        }
        return try self.beginAdapterList(frames, request, entry_index, prerequisites);
    }

    fn stepAdapterFrame(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        delivered: ?ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!AdapterStep {
        const frame = frames.items[frames.items.len - 1];
        const request = frame.request;
        const entry_index = frame.entry_index;
        const next: ?ResultDescriptorSource = switch (frame.stage) {
            .tag => |state| switch (try self.stepAdapterTag(state, request, delivered, prerequisites)) {
                .request => |component| return .{ .request = component },
                .finished => |finished| declined: {
                    self.popAdapterFrame(frames);
                    if (finished) |result| return .{ .done = try self.finishAdapterEntry(entry_index, result) };
                    break :declined try self.continueAdapterAfterTag(frames, request, entry_index, prerequisites);
                },
            },
            .aggregate => |state| switch (try self.stepAdapterFields(state, request, delivered, prerequisites)) {
                .request => |component| return .{ .request = component },
                .finished => |finished| declined: {
                    self.popAdapterFrame(frames);
                    if (finished) |result| return .{ .done = try self.finishAdapterEntry(entry_index, result) };
                    break :declined try self.continueAdapterAfterAggregate(frames, request, entry_index, prerequisites);
                },
            },
            .record => |state| switch (try self.stepAdapterFields(state, request, delivered, prerequisites)) {
                .request => |component| return .{ .request = component },
                .finished => |finished| declined: {
                    self.popAdapterFrame(frames);
                    if (finished) |result| return .{ .done = try self.finishAdapterEntry(entry_index, result) };
                    break :declined try self.continueAdapterAfterRecord(frames, request, entry_index, prerequisites);
                },
            },
            .list => |state| list: {
                const element = delivered orelse return .{ .request = state.element };
                const result = try self.finishAdapterList(state.*, element, prerequisites);
                self.popAdapterFrame(frames);
                break :list result;
            },
        };
        const result = next orelse return .next_frame;
        return .{ .done = try self.finishAdapterEntry(entry_index, result) };
    }

    /// Begin a tag union boundary's payload specialization.
    fn beginAdapterTag(self: *ProcBodyBuilder, request: AdapterRequest) Allocator.Error!AdapterAttemptBegin(AdapterTagState) {
        const allocator = self.parent.allocator;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const source_desc_info = request.source_desc_info;
        const source_tag_rep = self.parent.tagVariantRepForDesc(source_rep);
        const source_tag = self.parent.plan.representations.items[@backingInt(source_tag_rep)];
        if (source_tag.tag_variants.len == 0 and source_tag.kind != .bool_tag_union) return .{ .finished = null };

        const materialization = try self.descriptorMaterializationForExactRep(target_rep);
        const template_id = switch (materialization.desc) {
            .static => |desc_id| desc_id,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy adapter descriptor template was not static"),
        };
        const template = self.parent.result.boxy_type_descs.items[@backingInt(template_id)];

        const source_desc = source_desc_info.desc orelse
            boxyLowerInvariant("boxy call adapter tag source had no descriptor");
        const source_materialization = self.descriptorTemplateOf(source_desc_info);

        // A fully concrete source has exactly one descriptor, so its static
        // descriptor describes a source whose descriptor was read at runtime.
        const source_template_desc: ?LIR.BoxyDescRef = if (source_materialization) |source_materialize|
            source_materialize.desc
        else if (self.repIsFullyConcrete(source_rep))
            try self.parent.staticDescRefForRep(self.descriptorStorageRep(source_rep))
        else
            null;
        const source_template: LirProgram.BoxyTypeDesc = if (source_template_desc) |template_desc| blk: {
            const source_template_id = switch (template_desc) {
                .static => |desc_id| desc_id,
                .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy call adapter source descriptor template was not static"),
            };
            break :blk self.parent.result.boxy_type_descs.items[@backingInt(source_template_id)];
        } else return .{ .finished = try self.adapterDescriptorFromMaterialization(
            try self.descriptorMaterializationForExactRep(target_rep),
        ) };

        const target_plan_rep = self.parent.tagVariantRepForDesc(target_rep);
        const source_plan_rep = self.parent.tagVariantRepForDesc(source_rep);
        const state = try allocator.create(AdapterTagState);
        errdefer allocator.destroy(state);
        const target_template_variants = try allocator.dupe(
            LirProgram.BoxyTagVariant,
            self.parent.result.boxy_tag_variants.items[template.tag_variants.start..][0..template.tag_variants.len],
        );
        errdefer allocator.free(target_template_variants);
        const source_template_variants = try allocator.dupe(
            LirProgram.BoxyTagVariant,
            self.parent.result.boxy_tag_variants.items[source_template.tag_variants.start..][0..source_template.tag_variants.len],
        );
        state.* = .{
            .materialization = materialization,
            .template = template,
            .source_desc = source_desc,
            .source_materialization = source_materialization,
            .source_template = source_template,
            .target_plan_variants = self.parent.plan.tagVariantSlice(
                self.parent.plan.representations.items[@backingInt(target_plan_rep)].tag_variants,
            ),
            .source_plan_variants = self.parent.plan.tagVariantSlice(
                self.parent.plan.representations.items[@backingInt(source_plan_rep)].tag_variants,
            ),
            .target_template_variants = target_template_variants,
            .source_template_variants = source_template_variants,
        };
        return .{ .state = state };
    }

    fn stepAdapterTag(
        self: *ProcBodyBuilder,
        state: *AdapterTagState,
        request: AdapterRequest,
        delivered: ?ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!AdapterAttemptStep {
        const allocator = self.parent.allocator;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        if (delivered) |adapted| try self.finishAdapterTagPayload(state, adapted, prerequisites);
        while (true) {
            if (state.current) |*current| {
                while (current.payload < current.target_descs.len) {
                    const target_payload_desc = current.target_descs[current.payload];
                    current.payload += 1;
                    const specialized_desc = target_payload_desc;
                    if (target_payload_desc.payload_index >= current.target_payloads.len) {
                        boxyLowerInvariant("boxy tag adapter target payload descriptor index exceeded variant payloads");
                    }
                    const payload_index = target_payload_desc.payload_index;
                    // Payload storage belongs to this nominal application,
                    // not to the declaration formal shared by other uses.
                    const target_payload_rep = self.nominalBackingActualRep(target_rep, current.target_payloads[payload_index].rep);
                    const source_payload_rep = self.nominalBackingActualRep(source_rep, current.source_payloads[payload_index].rep);
                    var source_payload_desc_info: ?ResultDescriptorSource = null;
                    for (current.source_descs) |source_payload_desc| {
                        if (source_payload_desc.payload_index == payload_index) {
                            source_payload_desc_info = .{ .desc = source_payload_desc.desc };
                            break;
                        }
                    }
                    const exact_source_desc_info = source_payload_desc_info orelse
                        try self.adapterDescriptorForKnownRep(source_payload_rep);
                    try self.appendResultDescriptorInitializers(prerequisites, exact_source_desc_info);
                    const exact_source_payload_rep = self.descriptorSourceRep(
                        exact_source_desc_info,
                        source_payload_rep,
                    );

                    const target_payload_layout = self.parent.tagVariantPayloadFieldLayout(
                        current.specialized_variant.payload_layout,
                        payload_index,
                        current.target_payloads.len,
                    );
                    const target_payload_tag = self.parent.result.layouts.getLayout(target_payload_layout).tag;
                    const target_payload_is_box = target_payload_tag == .box or target_payload_tag == .box_of_zst or target_payload_tag == .erased_box;
                    const target_standalone_layout = self.workerRuntimeLayoutForRep(target_payload_rep).layoutIdx();
                    const adapted_payload_desc_info = if (self.representationBoundaryIsDirect(
                        target_payload_rep,
                        exact_source_payload_rep,
                    ) or
                        (target_payload_is_box and
                            self.repIsBareDynamic(self.descriptorStorageRep(target_payload_rep))))
                        exact_source_desc_info
                    else if (target_payload_layout != target_standalone_layout)
                        ResultDescriptorSource{ .desc = target_payload_desc.desc }
                    else {
                        current.pending = specialized_desc;
                        return .{ .request = .{
                            .target_rep = target_payload_rep,
                            .source_rep = exact_source_payload_rep,
                            .source_desc_info = exact_source_desc_info,
                        } };
                    };
                    current.pending = specialized_desc;
                    try self.finishAdapterTagPayload(state, adapted_payload_desc_info, prerequisites);
                }
                var specialized_variant = current.specialized_variant;
                if (current.variant_specialized) {
                    const payload_start: u32 = @intCast(self.parent.result.boxy_tag_payload_descs.items.len);
                    try self.parent.result.boxy_tag_payload_descs.appendSlice(allocator, current.specialized_descs.items);
                    specialized_variant.payload_descs = .{ .start = payload_start, .len = @intCast(current.specialized_descs.items.len) };
                }
                allocator.free(current.target_descs);
                allocator.free(current.source_descs);
                current.specialized_descs.deinit(allocator);
                state.current = null;
                try state.specialized_variants.append(allocator, specialized_variant);
            }
            if (state.variant == state.target_template_variants.len) break;
            const target_variant = state.target_template_variants[state.variant];
            state.variant += 1;
            const target_name = self.parent.result.store.getBoxyName(target_variant.name);
            var target_plan_variant: ?Plan.TagVariant = null;
            for (state.target_plan_variants) |plan_variant| {
                if (std.mem.eql(u8, target_name, self.tagVariantNameText(plan_variant))) {
                    target_plan_variant = plan_variant;
                    break;
                }
            }
            var source_plan_variant: ?Plan.TagVariant = null;
            for (state.source_plan_variants) |plan_variant| {
                if (std.mem.eql(u8, target_name, self.tagVariantNameText(plan_variant))) {
                    source_plan_variant = plan_variant;
                    break;
                }
            }
            var source_variant: ?LirProgram.BoxyTagVariant = null;
            for (state.source_template_variants) |candidate| {
                if (target_variant.name == candidate.name) {
                    source_variant = candidate;
                    break;
                }
            }

            if (target_plan_variant == null or source_plan_variant == null or source_variant == null or target_variant.payload_descs.len == 0) {
                try state.specialized_variants.append(allocator, target_variant);
                continue;
            }
            const target_payloads = self.parent.plan.childSlice(target_plan_variant.?.payloads);
            const source_payloads = self.parent.plan.childSlice(source_plan_variant.?.payloads);
            if (target_payloads.len != source_payloads.len) {
                boxyLowerInvariant("boxy tag adapter matching variants had different payload counts");
            }
            const target_descs = try allocator.dupe(
                LirProgram.BoxyTagPayloadDesc,
                self.parent.result.boxy_tag_payload_descs.items[target_variant.payload_descs.start..][0..target_variant.payload_descs.len],
            );
            errdefer allocator.free(target_descs);
            const source_descs = try allocator.dupe(
                LirProgram.BoxyTagPayloadDesc,
                self.parent.result.boxy_tag_payload_descs.items[source_variant.?.payload_descs.start..][0..source_variant.?.payload_descs.len],
            );
            state.current = .{
                .specialized_variant = target_variant,
                .target_payloads = target_payloads,
                .source_payloads = source_payloads,
                .target_descs = target_descs,
                .source_descs = source_descs,
            };
        }

        if (!state.payload_desc_specialized and state.template.tag_ext_desc == null) return .{ .finished = null };
        const specialized_tag_variants: ?LIR.BoxySpan = if (state.payload_desc_specialized) span: {
            const variants_start: u32 = @intCast(self.parent.result.boxy_tag_variants.items.len);
            try self.parent.result.boxy_tag_variants.appendSlice(allocator, state.specialized_variants.items);
            break :span .{ .start = variants_start, .len = @intCast(state.specialized_variants.items.len) };
        } else null;
        return .{ .finished = try self.finishAdapterTag(state, specialized_tag_variants) };
    }

    /// Record one payload's adapted descriptor in its variant's
    /// specialization.
    fn finishAdapterTagPayload(
        self: *ProcBodyBuilder,
        state: *AdapterTagState,
        adapted_payload_desc_info: ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        const current = &state.current.?;
        var specialized_desc = current.pending;
        try self.appendResultDescriptorInitializers(prerequisites, adapted_payload_desc_info);
        specialized_desc.desc = adapted_payload_desc_info.desc orelse
            boxyLowerInvariant("boxy tag adapter target payload had no descriptor");
        if (specialized_desc.desc.localOrNull()) |local| {
            try appendUniqueLocal(allocator, &state.extra_captures, local);
        }
        current.variant_specialized = true;
        state.payload_desc_specialized = true;
        try current.specialized_descs.append(allocator, specialized_desc);
    }

    /// The specialized tag descriptor once every variant is specialized.
    fn finishAdapterTag(
        self: *ProcBodyBuilder,
        state: *AdapterTagState,
        specialized_tag_variants: ?LIR.BoxySpan,
    ) Allocator.Error!ResultDescriptorSource {
        const allocator = self.parent.allocator;
        const template = state.template;
        const source_desc = state.source_desc;
        const source_template_value = state.source_template;
        const residual_desc: ?LIR.BoxyDescRef = if (template.tag_ext_desc == null) null else static_residual: {
            const target_variants = self.parent.result.boxy_tag_variants.items[template.tag_variants.start..][0..template.tag_variants.len];
            const source_variants = self.parent.result.boxy_tag_variants.items[source_template_value.tag_variants.start..][0..source_template_value.tag_variants.len];
            var has_residual_variant = false;
            for (source_variants) |source_variant| {
                var belongs_to_target = false;
                for (target_variants) |target_variant| {
                    if (source_variant.name == target_variant.name) {
                        belongs_to_target = true;
                        break;
                    }
                }
                if (!belongs_to_target) {
                    has_residual_variant = true;
                    break;
                }
            }

            // Removing local variants would renumber the extension
            // discriminant without changing the source storage layout. Keep
            // the exact source descriptor whenever local residual variants
            // remain or the source row is closed; otherwise project its
            // already-layout-correct extension.
            if (has_residual_variant) break :static_residual source_desc;
            break :static_residual source_template_value.tag_ext_desc orelse source_desc;
        };

        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        var specialized = template;
        if (specialized_tag_variants) |variants| specialized.tag_variants = variants;
        if (template.tag_ext_desc != null) specialized.tag_ext_desc = residual_desc;
        try self.parent.result.boxy_type_descs.append(allocator, specialized);

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(allocator);
        const template_captures = self.parent.result.store.getLocalSpan(state.materialization.captures);
        for (0..GuardedList.borrowLen(template_captures)) |index| {
            try appendUniqueLocal(allocator, &captures, GuardedList.at(template_captures, index));
        }
        if (state.source_materialization) |source_materialize| {
            const source_captures = self.parent.result.store.getLocalSpan(source_materialize.captures);
            for (0..GuardedList.borrowLen(source_captures)) |index| {
                try appendUniqueLocal(allocator, &captures, GuardedList.at(source_captures, index));
            }
        }
        if (residual_desc) |desc| {
            if (desc.localOrNull()) |local| try appendUniqueLocal(allocator, &captures, local);
        }
        for (state.extra_captures.items) |local| {
            try appendUniqueLocal(allocator, &captures, local);
        }

        const capture_span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return try self.adapterDescriptorFromMaterialization(.{
            .desc = .{ .static = desc_id },
            .captures = capture_span,
        });
    }

    const AdapterFieldsKind = enum { aggregate, record };

    /// Begin a record's or declared aggregate's field specialization, or
    /// decline when the boundary is not one.
    fn beginAdapterFields(self: *ProcBodyBuilder, request: AdapterRequest, kind: AdapterFieldsKind) Allocator.Error!?*AdapterFieldsState {
        const allocator = self.parent.allocator;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const source_desc_info = request.source_desc_info;
        const target_aggregate_rep = switch (kind) {
            .aggregate => self.declaredAggregateRepForBoundary(target_rep) orelse return null,
            .record => self.recordRepForBoundary(target_rep) orelse return null,
        };
        const source_aggregate_rep = switch (kind) {
            .aggregate => self.declaredAggregateRepForBoundary(source_rep) orelse return null,
            .record => self.recordRepForBoundary(source_rep) orelse return null,
        };
        if (kind == .record) {
            const target_record = self.parent.plan.representations.items[@backingInt(target_aggregate_rep)];
            const source_record = self.parent.plan.representations.items[@backingInt(source_aggregate_rep)];
            if (!self.repHasRecordFieldChildrenForBoundary(target_record) or
                !self.repHasRecordFieldChildrenForBoundary(source_record))
            {
                return null;
            }
        }

        const target_materialization = try self.descriptorMaterializationForExactRep(target_rep);
        const target_template_id = switch (target_materialization.desc) {
            .static => |desc_id| desc_id,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => switch (kind) {
                .aggregate => boxyLowerInvariant("boxy declared aggregate adapter target descriptor template was not static"),
                .record => boxyLowerInvariant("boxy record adapter target descriptor template was not static"),
            },
        };
        const target_template = self.parent.result.boxy_type_descs.items[@backingInt(target_template_id)];

        const source_desc = source_desc_info.desc orelse switch (kind) {
            .aggregate => boxyLowerInvariant("boxy declared aggregate adapter source had no descriptor"),
            .record => boxyLowerInvariant("boxy record adapter source had no descriptor"),
        };
        const source_materialization = self.descriptorTemplateOf(source_desc_info);
        const source_template: ?LirProgram.BoxyTypeDesc = if (source_materialization) |materialization| blk: {
            const source_template_id = switch (materialization.desc) {
                .static => |desc_id| desc_id,
                .local, .runtime, .dict_method_arg, .dict_method_hidden => switch (kind) {
                    .aggregate => boxyLowerInvariant("boxy declared aggregate adapter source descriptor template was not static"),
                    .record => boxyLowerInvariant("boxy record adapter source descriptor template was not static"),
                },
            };
            break :blk self.parent.result.boxy_type_descs.items[@backingInt(source_template_id)];
        } else null;

        const state = try allocator.create(AdapterFieldsState);
        state.* = .{
            .kind = kind,
            .target_materialization = target_materialization,
            .target_template = target_template,
            .source_desc = source_desc,
            .source_materialization = source_materialization,
            .source_template = source_template,
            .target_aggregate_rep = target_aggregate_rep,
            .source_aggregate_rep = source_aggregate_rep,
        };
        errdefer {
            state.deinit(allocator);
            allocator.destroy(state);
        }
        const target_nested = self.parent.result.boxy_desc_refs.items[target_template.nested_descs.start..][0..target_template.nested_descs.len];
        try state.specialized_nested.appendSlice(allocator, target_nested);
        if (kind == .aggregate) {
            const target_aggregate = self.parent.plan.representations.items[@backingInt(target_aggregate_rep)];
            state.declared_fields = try self.parent.declaredFieldsInLayoutOrder(
                self.parent.plan.declaredFieldSlice(target_aggregate.declared_fields),
            );
        }
        return state;
    }

    fn stepAdapterFields(
        self: *ProcBodyBuilder,
        state: *AdapterFieldsState,
        request: AdapterRequest,
        delivered: ?ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!AdapterAttemptStep {
        if (delivered) |adapted| try self.finishAdapterField(state, adapted, prerequisites);
        while (true) {
            const field = switch (state.kind) {
                .aggregate => try self.nextAdapterAggregateField(state, request, prerequisites) orelse break,
                .record => try self.nextAdapterRecordField(state, prerequisites) orelse break,
            };
            try self.appendResultDescriptorInitializers(prerequisites, field.source_desc_info);
            state.pending_nested_index = field.target_nested_index;
            if (self.representationBoundaryIsDirect(field.target_rep, field.source_rep) or
                self.repIsBareDynamic(self.descriptorStorageRep(field.target_rep)))
            {
                try self.finishAdapterField(state, field.source_desc_info, prerequisites);
                continue;
            }
            return .{ .request = .{
                .target_rep = field.target_rep,
                .source_rep = field.source_rep,
                .source_desc_info = field.source_desc_info,
            } };
        }
        if (!state.specialized) return .{ .finished = null };
        return .{ .finished = try self.finishAdapterFields(state) };
    }

    /// One field boundary of a record or declared aggregate boundary.
    const AdapterField = struct {
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_desc_info: ResultDescriptorSource,
        target_nested_index: usize,
    };

    /// The source field descriptor at `nested_index`: the source template's,
    /// the source descriptor's read at runtime, or the field's known one.
    fn adapterSourceFieldDescriptor(
        self: *ProcBodyBuilder,
        state: *AdapterFieldsState,
        nested_index: u32,
        source_field_rep: Plan.TypeRepId,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!ResultDescriptorSource {
        if (state.source_template) |template| {
            if (nested_index >= template.nested_descs.len) switch (state.kind) {
                .aggregate => boxyLowerInvariant("boxy declared aggregate source nested descriptor index exceeded template"),
                .record => boxyLowerInvariant("boxy record adapter source nested descriptor index exceeded template"),
            };
            return .{ .desc = self.parent.result.boxy_desc_refs.items[template.nested_descs.start + nested_index] };
        }
        if (self.payloadFieldCarriesRuntimeDesc(state.source_aggregate_rep, nested_index)) {
            const nested_local = try self.addFrameLocal(.opaque_ptr);
            try prerequisites.append(self.parent.allocator, .{
                .local = nested_local,
                .materialize = state.source_desc,
                .nested_index = nested_index,
            });
            return .{ .desc = .{ .local = nested_local } };
        }
        return try self.adapterDescriptorForKnownRep(source_field_rep);
    }

    fn nextAdapterRecordField(
        self: *ProcBodyBuilder,
        state: *AdapterFieldsState,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?AdapterField {
        const target_record = self.parent.plan.representations.items[@backingInt(state.target_aggregate_rep)];
        const target_children = self.parent.plan.childSlice(target_record.children);
        while (state.index < target_children.len) {
            const target_child = target_children[state.index];
            state.index += 1;
            switch (target_child.role) {
                .record_field => |target_label| {
                    const target_field_index = state.target_field_index;
                    state.target_field_index += 1;
                    const target_nested_index = self.recordFieldNestedDescriptorIndex(state.target_aggregate_rep, target_field_index);
                    if (target_nested_index >= state.specialized_nested.items.len) {
                        boxyLowerInvariant("boxy record adapter target nested descriptor index exceeded template");
                    }
                    const source_field = self.findRecordFieldByLabel(
                        state.source_aggregate_rep,
                        procedureModuleById(self.parent.modules, target_child.source_type.module),
                        target_label,
                    ) orelse {
                        switch (target_child.record_field_kind.tag) {
                            .optional, .undetermined => continue,
                            .required, .defaulted, .err => boxyLowerInvariant("boxy record adapter source was missing target field"),
                        }
                    };
                    if (self.boundaryFieldKeepsStaticDescriptor(target_child.rep, source_field.rep)) continue;

                    const source_nested_index = self.recordFieldNestedDescriptorIndex(state.source_aggregate_rep, source_field.index);
                    return .{
                        .target_rep = target_child.rep,
                        .source_rep = source_field.rep,
                        .source_desc_info = try self.adapterSourceFieldDescriptor(state, @intCast(source_nested_index), source_field.rep, prerequisites),
                        .target_nested_index = target_nested_index,
                    };
                },
                .record_ext => self.requireEmptyRecordExtension(target_child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("boxy record adapter target had a non-record child role"),
            }
        }
        return null;
    }

    fn nextAdapterAggregateField(
        self: *ProcBodyBuilder,
        state: *AdapterFieldsState,
        request: AdapterRequest,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?AdapterField {
        while (state.index < state.declared_fields.len) {
            const target_field = state.declared_fields[state.index];
            state.index += 1;
            const target_nested_index = self.recordFieldNestedDescriptorIndex(
                state.target_aggregate_rep,
                target_field.index,
            );
            if (target_nested_index >= state.specialized_nested.items.len) {
                boxyLowerInvariant("boxy declared aggregate target nested descriptor index exceeded template");
            }

            // Field storage belongs to this nominal application, not to the
            // declaration formal shared by other uses.
            const target_field_rep = self.nominalBackingActualRep(request.target_rep, target_field.rep);
            const source_field_rep = self.nominalBackingActualRep(request.source_rep, try self.parent.matchingDeclaredFieldInstantiationSource(
                state.source_aggregate_rep,
                target_field,
            ) orelse boxyLowerInvariant("boxy declared aggregate source was missing target field"));
            if (self.boundaryFieldKeepsStaticDescriptor(target_field_rep, source_field_rep)) continue;
            const nested_index = self.recordFieldNestedDescriptorIndex(
                state.source_aggregate_rep,
                target_field.index,
            );
            return .{
                .target_rep = target_field_rep,
                .source_rep = source_field_rep,
                .source_desc_info = try self.adapterSourceFieldDescriptor(state, @intCast(nested_index), source_field_rep, prerequisites),
                .target_nested_index = target_nested_index,
            };
        }
        return null;
    }

    /// Record one field's adapted descriptor in the specialization.
    fn finishAdapterField(
        self: *ProcBodyBuilder,
        state: *AdapterFieldsState,
        adapted_field_desc_info: ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!void {
        try self.appendResultDescriptorInitializers(prerequisites, adapted_field_desc_info);
        const adapted_field_desc = adapted_field_desc_info.desc orelse switch (state.kind) {
            .aggregate => boxyLowerInvariant("boxy declared aggregate target field had no descriptor"),
            .record => boxyLowerInvariant("boxy record adapter target field had no descriptor"),
        };
        state.specialized_nested.items[state.pending_nested_index] = adapted_field_desc;
        if (adapted_field_desc.localOrNull()) |local| {
            try appendUniqueLocal(self.parent.allocator, &state.extra_captures, local);
        }
        state.specialized = true;
    }

    /// The specialized descriptor once every field is specialized.
    fn finishAdapterFields(self: *ProcBodyBuilder, state: *AdapterFieldsState) Allocator.Error!ResultDescriptorSource {
        const allocator = self.parent.allocator;
        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.appendSlice(allocator, state.specialized_nested.items);
        const specialized_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        var specialized_template = state.target_template;
        specialized_template.nested_descs = .{ .start = nested_start, .len = @intCast(state.specialized_nested.items.len) };
        try self.parent.result.boxy_type_descs.append(allocator, specialized_template);

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(allocator);
        const target_captures = self.parent.result.store.getLocalSpan(state.target_materialization.captures);
        for (0..GuardedList.borrowLen(target_captures)) |index| {
            try appendUniqueLocal(allocator, &captures, GuardedList.at(target_captures, index));
        }
        if (state.source_materialization) |materialization| {
            const source_captures = self.parent.result.store.getLocalSpan(materialization.captures);
            for (0..GuardedList.borrowLen(source_captures)) |index| {
                try appendUniqueLocal(allocator, &captures, GuardedList.at(source_captures, index));
            }
        }
        for (state.extra_captures.items) |local| {
            try appendUniqueLocal(allocator, &captures, local);
        }

        const capture_span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return try self.adapterDescriptorFromMaterialization(.{
            .desc = .{ .static = specialized_id },
            .captures = capture_span,
        });
    }

    /// Begin a list boundary's element specialization: its descriptor when
    /// the element needs no adapting, or null with the frame waiting on the
    /// element boundary pushed.
    fn beginAdapterList(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(AdapterFrame),
        request: AdapterRequest,
        entry_index: usize,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?ResultDescriptorSource {
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const source_desc_info = request.source_desc_info;
        const source_desc = source_desc_info.desc orelse
            boxyLowerInvariant("planned call adapter source descriptor was unavailable");
        const target_layout = self.workerRuntimeLayoutForRep(target_rep).layoutIdx();
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        const target_tag = self.parent.result.layouts.getLayout(target_layout).tag;
        const source_tag = self.parent.result.layouts.getLayout(source_layout).tag;
        const source_is_box = source_tag == .box or source_tag == .box_of_zst or source_tag == .erased_box;
        const known = try self.adapterDescriptorFromMaterialization(
            try self.descriptorMaterializationForExactRep(target_rep),
        );
        const target_is_list = target_tag == .list or target_tag == .list_of_zst;
        const source_is_list = source_tag == .list or source_tag == .list_of_zst;
        const source_is_exact_dynamic_box = source_is_box and
            self.repIsBareDynamic(self.descriptorStorageRep(source_rep));
        if (!target_is_list or (!source_is_list and !source_is_exact_dynamic_box)) {
            return known;
        }

        const known_template_ref = if (known.materialize) |materialize|
            materialize.materialize orelse
                boxyLowerInvariant("planned list adapter target descriptor materialization had no template")
        else
            known.desc orelse return known;
        const known_desc_id = switch (known_template_ref) {
            .static => |desc_id| desc_id,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("planned list adapter target descriptor template was not static"),
        };
        const known_desc = self.parent.result.boxy_type_descs.items[@backingInt(known_desc_id)];

        const target_list_rep = self.listRepForBoundary(target_rep) orelse
            boxyLowerInvariant("planned list adapter target representation was not list-shaped");
        const target_elem_rep = self.repQuery().requiredSingleChild(target_list_rep, .list_elem).rep;
        const source_elem_rep = if (source_is_list) blk: {
            const source_list_rep = self.listRepForBoundary(source_rep) orelse
                boxyLowerInvariant("planned list adapter source representation was not list-shaped");
            break :blk self.repQuery().requiredSingleChild(source_list_rep, .list_elem).rep;
        } else null;

        // The incoming descriptor describes the boxed allocation rather than a
        // list. The callable's target-list template carries the explicit
        // element identity required by its generic representation, so
        // materialize against that template directly.
        if (source_is_exact_dynamic_box) {
            return known;
        }

        const source_template = self.descriptorTemplateOf(source_desc_info);
        const source_template_ref = if (source_template) |materialization| materialization.desc else null;
        const source_elem_desc_info: ResultDescriptorSource = if (source_template_ref) |template_ref| template_elem: {
            const source_desc_id = switch (template_ref) {
                .static => |desc_id| desc_id,
                .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("planned list adapter source descriptor template was not static"),
            };
            const source_type_desc = self.parent.result.boxy_type_descs.items[@backingInt(source_desc_id)];
            if (source_type_desc.nested_descs.len != 1) {
                boxyLowerInvariant("planned list adapter source descriptor did not have exactly one element descriptor");
            }
            break :template_elem .{
                .desc = self.parent.result.boxy_desc_refs.items[source_type_desc.nested_descs.start],
            };
        } else runtime_elem: {
            const known_source_elem_rep = source_elem_rep orelse
                boxyLowerInvariant("planned list adapter source representation had no element representation");
            const source_elem_layout = self.parent.listElementLayout(source_layout);
            // An element whose layout carries no runtime descriptor has a
            // statically known identity.
            if (!self.parent.layoutIsBoxStorage(source_elem_layout) and
                !self.parent.layoutNeedsNestedBoxyDesc(source_elem_layout))
            {
                break :runtime_elem try self.adapterDescriptorForKnownRep(known_source_elem_rep);
            }
            const nested_local = try self.addFrameLocal(.opaque_ptr);
            try prerequisites.append(self.parent.allocator, .{
                .local = nested_local,
                .materialize = source_desc,
                .nested_index = 0,
            });
            break :runtime_elem .{ .desc = .{ .local = nested_local } };
        };
        if (source_elem_desc_info.prerequisite) |prerequisite| {
            try prerequisites.append(self.parent.allocator, prerequisite);
        }
        if (source_elem_desc_info.materialize) |materialize| {
            try prerequisites.append(self.parent.allocator, materialize);
        }

        if (self.repIsBareDynamic(self.descriptorStorageRep(target_elem_rep)) or
            (source_elem_rep != null and self.repsUseSameBoxStorage(target_elem_rep, source_elem_rep.?)))
        {
            return try self.finishAdapterList(.{
                .known = known,
                .known_desc = known_desc,
                .target_layout = target_layout,
                .source_elem_desc_info = source_elem_desc_info,
                .element = undefined,
            }, source_elem_desc_info, prerequisites);
        }
        const state = try self.parent.allocator.create(AdapterListState);
        state.* = .{
            .known = known,
            .known_desc = known_desc,
            .target_layout = target_layout,
            .source_elem_desc_info = source_elem_desc_info,
            .element = .{
                .target_rep = target_elem_rep,
                .source_rep = source_elem_rep orelse
                    boxyLowerInvariant("planned non-dynamic list element adapter had no source representation"),
                .source_desc_info = source_elem_desc_info,
            },
        };
        try self.pushAdapterFrame(frames, .{ .request = request, .entry_index = entry_index, .stage = .{ .list = state } });
        return null;
    }

    /// The list descriptor once its element's descriptor is adapted.
    fn finishAdapterList(
        self: *ProcBodyBuilder,
        state: AdapterListState,
        target_elem_desc_info: ResultDescriptorSource,
        prerequisites: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!ResultDescriptorSource {
        const known = state.known;
        const known_desc = state.known_desc;
        const target_layout = state.target_layout;
        const source_elem_desc_info = state.source_elem_desc_info;
        const source_elem_desc = source_elem_desc_info.desc orelse
            boxyLowerInvariant("planned list adapter source element had no descriptor");
        const target_elem_desc = target_elem_desc_info.desc orelse
            boxyLowerInvariant("planned list adapter target element had no descriptor");
        if (!std.meta.eql(source_elem_desc, target_elem_desc)) {
            if (target_elem_desc_info.prerequisite) |prerequisite| {
                try prerequisites.append(self.parent.allocator, prerequisite);
            }
            if (target_elem_desc_info.materialize) |materialize| {
                try prerequisites.append(self.parent.allocator, materialize);
            }
        }

        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.append(self.parent.allocator, target_elem_desc);

        const target_desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        var target_desc = known_desc;
        target_desc.payload_layout = target_layout;
        target_desc.nested_descs = .{ .start = nested_start, .len = 1 };
        target_desc.contains_refcounted = true;
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, target_desc);

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);
        if (known.materialize) |materialize| {
            const known_captures = self.parent.result.store.getLocalSpan(materialize.captures);
            for (0..GuardedList.borrowLen(known_captures)) |index| {
                try appendUniqueLocal(self.parent.allocator, &captures, GuardedList.at(known_captures, index));
            }
        }
        if (target_elem_desc.localOrNull()) |local| {
            try appendUniqueLocal(self.parent.allocator, &captures, local);
        }
        const capture_span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return try self.adapterDescriptorFromMaterialization(.{
            .desc = .{ .static = target_desc_id },
            .captures = capture_span,
        });
    }

    fn internAdapter(
        self: *ProcBodyBuilder,
        operation: LirProgram.BoxyAdapterOperation,
        source_layout: layout.Idx,
        target_layout: layout.Idx,
        consumes_source: bool,
    ) Allocator.Error!LIR.BoxyAdapterId {
        for (self.parent.result.boxy_adapters.items, 0..) |adapter, index| {
            if (adapter.kind == .boxy_to_boxy and
                adapter.operation == operation and
                adapter.source_layout == source_layout and
                adapter.target_layout == target_layout and
                adapter.steps.len == 0 and
                adapter.consumes_source == consumes_source and
                adapter.produces_owned_result)
            {
                return @fromBackingInt(@intCast(@as(u32, @intCast(index))));
            }
        }

        const id: LIR.BoxyAdapterId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_adapters.items.len))));
        try self.parent.result.boxy_adapters.append(self.parent.allocator, .{
            .kind = .boxy_to_boxy,
            .operation = operation,
            .source_layout = source_layout,
            .target_layout = target_layout,
            .consumes_source = consumes_source,
            .produces_owned_result = true,
        });
        return id;
    }

    fn internMoveAdapter(
        self: *ProcBodyBuilder,
        operation: LirProgram.BoxyAdapterOperation,
        source_layout: layout.Idx,
        target_layout: layout.Idx,
    ) Allocator.Error!LIR.BoxyAdapterId {
        return try self.internAdapter(operation, source_layout, target_layout, true);
    }

    /// Lower the branches from the last, each falling through to the one
    /// after it, then the condition, all under the descriptor bindings in
    /// force before the match.
    fn stepMatch(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        if (stage == 0) {
            if (self.listMapCanReuseMatchBody(task.cond, task.branches)) |body| {
                return .{ .tail = .{ .expected = .{ .target = task.target, .expected_ty = task.match_ty, .expr_id = body, .next = task.next } } };
            }
            const cond_expr = self.module.checked_bodies.expr(task.cond);
            task.cond_rep = self.matchConditionRep(task.cond, self.repForType(cond_expr.ty));
            try self.reserveMatchBranchRepresentativeBindings(task.branches, task.cond_rep);
            task.cond_local = try self.addFrameBoundaryTargetLocalForRep(task.cond_rep);
            // Matching an otherwise-direct concrete tag result needs a slot that
            // carries the exact descriptor through the planned call adapter.
            if (self.parent.result.store.getLocal(task.cond_local).boxy_desc == null and
                self.matchConditionNeedsExactResultDescriptor(task.cond, task.cond_rep))
            {
                const desc_local = try self.addFrameLocal(.opaque_ptr);
                self.parent.result.store.setLocalBoxyDesc(task.cond_local, .{ .local = desc_local });
            }
            task.outer_descriptors = try self.snapshotDescriptorBindings();
            task.done = self.freshJoinPointId();
            task.current = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin());
            task.index = task.branches.len;
        } else if (!task.condition_started) {
            task.current = input.?;
        }
        if (!task.condition_started) {
            if (task.index > 0) {
                task.index -= 1;
                return .{ .child = .{ .match_branch = .{
                    .branch = task.branches[task.index],
                    .source = task.cond_local,
                    .source_rep = task.cond_rep,
                    .target = task.target,
                    .result_ty = task.match_ty,
                    .done = task.done,
                    .next = task.current,
                } } };
            }
            task.condition_started = true;
            return .{ .child = self.matchConditionTask(task.cond_local, task.cond_rep, task.cond, task.current) };
        }

        const outer_descriptors = task.outer_descriptors.?;
        const remainder = try self.prependStaticDescriptorMaterializationsForScopedSlots(&outer_descriptors, input.?);
        const params = [_]LIR.LocalId{task.target};
        const match_stmt = try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = task.done,
            .params = try self.joinParamSpan(&params),
            .body = task.next,
            .remainder = remainder,
        } }, self.glueOrigin());
        task.outer_descriptors = null;
        self.restoreDescriptorBindings(outer_descriptors);
        outer_descriptors.deinit(self.parent.allocator);
        return exprDone(match_stmt);
    }

    const ListMapCanReuseMatch = struct {
        args: []const checked.CheckedExprId,
        zero_branch_body: checked.CheckedExprId,
    };

    /// When the explicit target configuration or committed representations
    /// make list-buffer reuse impossible, lower only the arm selected by the
    /// primitive's constant-zero result. This is the Boxy counterpart of
    /// direct lowering's `listMapCanReuseMatch`: both consume the checked
    /// low-level operation and the same exact layout-eligibility decision.
    /// The result is the zero branch's body, or null when reuse stays possible.
    fn listMapCanReuseMatchBody(
        self: *ProcBodyBuilder,
        cond: checked.CheckedExprId,
        branches: []const checked.CheckedMatchBranch,
    ) ?checked.CheckedExprId {
        const match = self.listMapCanReuseMatch(cond, branches) orelse return null;
        const interchangeable = self.listMapLayoutsInterchangeable(match.args, null);
        if (interchangeable.get(.u32) or interchangeable.get(.u64)) return null;
        return match.zero_branch_body;
    }

    fn listMapCanReuseMatch(
        self: *ProcBodyBuilder,
        cond: checked.CheckedExprId,
        branches: []const checked.CheckedMatchBranch,
    ) ?ListMapCanReuseMatch {
        const args = self.listMapCanReuseArgs(cond) orelse return null;

        for (branches) |branch| {
            if (branch.guard != null) return null;
            const patterns = branch.patternsSlice(self.module.checked_bodies);
            if (patterns.len != 1 or patterns[0].degenerate) return null;
            if (patterns[0].binderRemapsSlice(self.module.checked_bodies).len != 0) return null;

            const pattern = self.module.checked_bodies.pattern(patterns[0].pattern);
            switch (pattern.data) {
                .numeral_literal => |literal| {
                    if (literal.guard != null) return null;
                    const magnitude = exact_numeral.intMagnitude(
                        self.module.module_env.exactNumeral(literal.literal),
                    ) orelse return null;
                    if (magnitude == 0) {
                        return .{ .args = args, .zero_branch_body = branch.value };
                    }
                },
                .underscore => return .{ .args = args, .zero_branch_body = branch.value },
                .pending,
                .assign,
                .as,
                .applied_tag,
                .nominal,
                .record_destructure,
                .list,
                .tuple,
                .str_literal,
                .str_interpolation,
                .runtime_error,
                => return null,
            }
        }
        return null;
    }

    fn listMapCanReuseArgs(
        self: *ProcBodyBuilder,
        root: checked.CheckedExprId,
    ) ?[]const checked.CheckedExprId {
        var cond = root;
        while (true) return switch (self.module.checked_bodies.expr(cond).data) {
            .run_low_level => |low_level| if (low_level.op == .list_map_can_reuse) low_level.args else null,
            .block => |block| {
                if (block.statements.len != 0) return null;
                cond = block.final_expr;
                continue;
            },
            .call => |call| blk: {
                if (call.direct_target == null) break :blk null;
                const direct = self.parent.plan.directCallPlanForCall(
                    .{ .module = self.module.key, .expr = cond },
                    self.worker_layout.worker,
                ) orelse break :blk null;
                const resolved = self.parent.resolved_workers.items[@backingInt(direct.worker)];
                if (!resolvedWorkerIsListMapCanReuseWrapper(resolved)) break :blk null;
                break :blk call.args;
            },
            .pending,
            .numeral,
            .str_from_quote,
            .str_segment,
            .str,
            .bytes_literal,
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .list,
            .empty_list,
            .tuple,
            .match_,
            .if_,
            .record,
            .empty_record,
            .tag,
            .nominal,
            .zero_argument_tag,
            .closure,
            .lambda,
            .binop,
            .unary_minus,
            .unary_not,
            .field_access,
            .dispatch_call,
            .interpolation,
            .structural_eq,
            .structural_hash,
            .method_eq,
            .type_dispatch_call,
            .tuple_access,
            .runtime_error,
            .crash,
            .dbg,
            .expect_err,
            .expect,
            .ellipsis,
            .anno_only,
            .break_,
            .return_,
            .for_,
            .hosted_lambda,
            => null,
        };
    }

    fn matchConditionRep(
        self: *ProcBodyBuilder,
        cond: checked.CheckedExprId,
        default_rep: Plan.TypeRepId,
    ) Plan.TypeRepId {
        const call = switch (self.module.checked_bodies.expr(cond).data) {
            .call => |call| call,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return default_rep,
        };
        if (call.direct_target == null) return default_rep;
        const direct_plan = self.parent.plan.directCallPlanForCall(.{
            .module = self.module.key,
            .expr = cond,
        }, self.worker_layout.worker) orelse return default_rep;
        const substitution = direct_plan.ret_substitution orelse
            boxyLowerInvariant("boxy direct match call had no planned return substitution");
        return substitution.call_rep;
    }

    /// The piece lowering a match condition: a direct call planned with the
    /// match's condition representation, or the plain expression.
    fn matchConditionTask(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        cond: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) ExprTask {
        const plain: ExprTask = .{ .expr = .{ .target = target, .expr_id = cond, .next = next } };
        const expr = self.module.checked_bodies.expr(cond);
        const call = switch (expr.data) {
            .call => |call| call,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return plain,
        };
        if (call.direct_target == null) return plain;
        const direct_plan = self.parent.plan.directCallPlanForCall(.{
            .module = self.module.key,
            .expr = cond,
        }, self.worker_layout.worker) orelse return plain;
        const substitution = direct_plan.ret_substitution orelse
            boxyLowerInvariant("boxy direct match call had no planned return substitution");
        if (target_rep != substitution.call_rep) {
            boxyLowerInvariant("boxy direct match result representation disagreed with its planned substitution");
        }
        return .{ .planned_call = .{
            .target = target,
            .target_rep = target_rep,
            .checked_ret_ty = expr.ty,
            .direct_plan = direct_plan,
            .next = next,
        } };
    }

    fn matchConditionNeedsExactResultDescriptor(
        self: *ProcBodyBuilder,
        cond: checked.CheckedExprId,
        cond_rep: Plan.TypeRepId,
    ) bool {
        if (self.tagVariantRepForBoundary(cond_rep) == null) return false;
        const call = switch (self.module.checked_bodies.expr(cond).data) {
            .call => |call| call,
            .pending, .numeral, .str_from_quote, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return false,
        };
        if (call.direct_target == null) return false;
        const direct_plan = self.parent.plan.directCallPlanForCall(
            .{ .module = self.module.key, .expr = cond },
            self.worker_layout.worker,
        ) orelse return false;
        const substitution = direct_plan.ret_substitution orelse return false;
        const worker_plan = self.parent.plan.workers.items[@backingInt(direct_plan.worker)];
        const worker_function = self.functionChildrenForRep(worker_plan.rep) orelse return false;
        if (worker_function.ret != substitution.worker_rep) {
            boxyLowerInvariant("boxy match call result representation disagreed with its worker plan");
        }

        const worker_layout = self.parent.layout_plan.workerLayoutFor(direct_plan.worker);
        const worker_ret_layout = if (worker_layout.ret) |ret| ret else worker_layout.value;
        if (self.workerRuntimeLayoutForRep(cond_rep).layoutIdx() != worker_ret_layout.layoutIdx()) return false;
        if (self.descriptorStorageRep(cond_rep) != self.descriptorStorageRep(worker_function.ret)) return false;

        const identity_worker_ret = self.descriptorStorageRep(worker_function.ret);
        return self.parent.plan.representations.items[@backingInt(identity_worker_ret)].descriptor == null;
    }

    fn reserveMatchBranchRepresentativeBindings(
        self: *ProcBodyBuilder,
        branches: []const checked.CheckedMatchBranch,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        for (branches) |branch| {
            const patterns = branch.patternsSlice(self.module.checked_bodies);
            if (patterns.len == 0) {
                boxyLowerInvariant("checked match branch reached boxy lowering without a representative pattern");
            }
            if (patterns[0].degenerate) {
                boxyLowerInvariant("checked match branch representative pattern was marked degenerate");
            }
            try self.reserveMatchPatternBindingsFromRep(patterns[0].pattern, source_rep);
        }
    }

    /// A match branch: its body, its guard, then its alternatives'
    /// patterns from the last, each falling through to the next on a miss.
    fn stepMatchBranch(self: *ProcBodyBuilder, task: anytype, stage: u32, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        const branch = task.branch;
        const patterns = branch.patternsSlice(self.module.checked_bodies);
        switch (stage) {
            0 => {
                if (patterns.len == 0) {
                    boxyLowerInvariant("checked match branch reached boxy lowering without patterns");
                }
                task.outer_descriptors = try self.snapshotDescriptorBindings();
                for (patterns) |branch_pattern| {
                    if (branch_pattern.degenerate) continue;
                    try self.reserveMatchPatternDescriptors(
                        branch_pattern.pattern,
                        branch_pattern.binderRemapsSlice(self.module.checked_bodies),
                    );
                }
                const branch_done = try self.joinJump(task.done);
                return .{ .child = .{ .expected = .{ .target = task.target, .expected_ty = task.result_ty, .expr_id = branch.value, .next = branch_done } } };
            },
            1 => {
                task.branch_body = input.?;
                if (branch.guard) |guard| {
                    const guard_expr = self.module.checked_bodies.expr(guard);
                    const guard_local = try self.addFrameLocalForType(guard_expr.ty);
                    const guard_switch = try self.boolSwitchNoContinuation(guard_local, task.branch_body, task.next);
                    return .{ .child = .{ .expr = .{ .target = guard_local, .expr_id = guard, .next = guard_switch } } };
                }
            },
            else => {},
        }
        if (!task.alternatives_started) {
            task.on_match = if (branch.guard != null) input.? else task.branch_body;
            const outer_descriptors = task.outer_descriptors.?;
            task.outer_descriptors = null;
            defer outer_descriptors.deinit(self.parent.allocator);
            self.restoreDescriptorBindings(outer_descriptors);
            task.alternatives_started = true;
            task.alt_current = task.next;
            task.alt_index = patterns.len;
        } else {
            const branch_start = input.?;
            const pattern_descriptors = task.alt_snapshot.?;
            task.alt_snapshot = null;
            defer pattern_descriptors.deinit(self.parent.allocator);
            self.restoreDescriptorBindings(pattern_descriptors);
            task.alt_current = if (task.alt_miss) |miss_info|
                try self.parent.result.store.addCFStmt(.{ .join = .{
                    .id = miss_info.join_id,
                    .params = LIR.LocalSpan.empty(),
                    .body = task.alt_current,
                    .remainder = branch_start,
                } }, self.glueOrigin())
            else
                branch_start;
        }
        if (task.alt_index == 0) return exprDone(task.alt_current);
        task.alt_index -= 1;
        const branch_pattern = patterns[task.alt_index];
        if (branch_pattern.degenerate) {
            boxyLowerInvariant("degenerate checked match alternative reached boxy lowering");
        }
        const remaps = branch_pattern.binderRemapsSlice(self.module.checked_bodies);
        const needs_miss_join = try self.patternFromRepCanMiss(branch_pattern.pattern, task.source_rep);
        task.alt_miss = if (needs_miss_join)
            PatternMiss{ .join_id = self.freshJoinPointId() }
        else
            null;
        task.alt_snapshot = try self.snapshotDescriptorBindings();
        return .{ .child = .{ .pattern = .{
            .pattern = branch_pattern.pattern,
            .source = task.source,
            .source_rep = task.source_rep,
            .mode = .{ .match = .{ .miss = task.alt_miss, .remaps = remaps } },
            .next = task.on_match,
        } } };
    }

    fn lowerExprIntoRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.runExprStep(try self.beginExprIntoRep(target, target_rep, expr_id, next));
    }

    fn exprTagPayloadStorageRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) Plan.TypeRepId {
        // A bare type parameter has no storage shape of its own. Boxing the
        // operand preserves its exact payload descriptor.
        if (self.repIsBareDynamic(target_rep)) return source_rep;

        if (self.parent.result.store.getLocal(target).layout_idx == self.workerRuntimeLayoutForRep(source_rep).layoutIdx() and
            self.repsUseSameDynamicBoxStorage(target_rep, source_rep))
        {
            return source_rep;
        }
        return target_rep;
    }

    fn lowerBoolTagInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        name: names.TagNameId,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (args.len != 0) {
            boxyLowerInvariant("builtin Bool tag expression carried a payload");
        }
        const variant_index = self.boolVariantIndex(name);
        return try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
            .target = target,
            .variant_index = variant_index,
            .discriminant = variant_index,
            .payload = null,
            .next = next,
        } }, self.origin);
    }

    fn lowerPlannedTagVariantInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        variant: TagVariantLookup,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.runExprStep(try self.beginPlannedTagVariant(target, rep_id, variant, args, next));
    }

    fn constructedTargetDescForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.descriptor) |desc| {
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id)) |local| {
                return .{ .local = local };
            }
            if (self.descriptorBindingIsBoundForRep(rep_id)) {
                if (try self.descriptorTemplateNeedsCapturesForKnownRep(rep_id)) {
                    boxyLowerInvariant("bound boxy descriptor requirement had no matching local");
                }
            }
        }
        return try self.parent.staticDescRefForRep(rep_id);
    }

    fn bindConstructedTargetDescriptor(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!void {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const desc = rep.descriptor orelse return;
        if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
            if (target_desc.localOrNull()) |target_desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(target_desc_local)) {
                    try self.setDescriptorRequirementLocalForRep(desc, rep_id, target_desc_local);
                    const identity_rep = self.descriptorStorageRep(rep_id);
                    const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
                    if (identity.descriptor) |identity_desc| {
                        try self.setDescriptorRequirementLocalForRep(identity_desc, identity_rep, target_desc_local);
                    }
                    return;
                }
            }
        }
        const local = if (self.descriptorBindingIsBoundForRep(rep_id))
            self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id) orelse
                boxyLowerInvariant("bound constructed descriptor had no matching local")
        else
            (try self.reserveDescriptorLocalForRep(rep_id)) orelse return;
        self.parent.result.store.setLocalBoxyDesc(target, .{ .local = local });
    }

    fn dynamicTagPayloadLocal(
        self: *ProcBodyBuilder,
        payloads: []const Plan.RepChild,
        args: []const checked.CheckedExprId,
    ) Allocator.Error!DynamicTagPayloadLocal {
        if (payloads.len != args.len or args.len == 0) {
            boxyLowerInvariant("dynamic tag payload local requested with invalid payload arity");
        }
        if (args.len == 1) {
            const payload_rep = payloads[0].rep;
            const payload_layout = self.tagPayloadStorageLayoutForRep(payload_rep);
            return .{
                .local = try self.addFrameLocal(payload_layout),
                .layout_idx = payload_layout,
                .desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(payload_rep),
            };
        }

        const fields = try self.parent.allocator.alloc(layout.StructField, args.len);
        defer self.parent.allocator.free(fields);
        for (payloads, fields, 0..) |payload, *field, index| {
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("dynamic tag payload index exceeded layout struct field range");
            }
            field.* = .{
                .index = @intCast(index),
                .layout = self.tagPayloadStorageLayoutForRep(payload.rep),
            };
        }
        const payload_layout = try self.parent.result.layouts.putStructFields(fields);
        return .{ .local = try self.addFrameLocal(payload_layout), .layout_idx = payload_layout };
    }

    fn dynamicTagPayloadLocalForChildren(
        self: *ProcBodyBuilder,
        payloads: []const Plan.RepChild,
    ) Allocator.Error!DynamicTagPayloadLocal {
        if (payloads.len == 0) {
            boxyLowerInvariant("dynamic tag payload local requested for an empty payload list");
        }
        if (payloads.len == 1) {
            const payload_rep = payloads[0].rep;
            const payload_layout = self.tagPayloadStorageLayoutForRep(payload_rep);
            return .{
                .local = try self.addFrameLocal(payload_layout),
                .layout_idx = payload_layout,
                .desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(payload_rep),
            };
        }

        const fields = try self.parent.allocator.alloc(layout.StructField, payloads.len);
        defer self.parent.allocator.free(fields);
        for (payloads, fields, 0..) |payload, *field, index| {
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("dynamic tag payload index exceeded layout struct field range");
            }
            field.* = .{
                .index = @intCast(index),
                .layout = self.tagPayloadStorageLayoutForRep(payload.rep),
            };
        }
        const payload_layout = try self.parent.result.layouts.putStructFields(fields);
        return .{ .local = try self.addFrameLocal(payload_layout), .layout_idx = payload_layout };
    }

    fn addExtractedTagPayloadLocal(
        self: *ProcBodyBuilder,
        payload_rep: Plan.TypeRepId,
        source_has_payload_desc: bool,
    ) Allocator.Error!ExtractedTagPayloadLocal {
        if (source_has_payload_desc and self.parent.repNeedsTagPayloadDesc(payload_rep)) {
            const desc_local = try self.addFrameLocal(.opaque_ptr);
            const layout_idx = self.workerRuntimeLayoutForRep(payload_rep).layoutIdx();
            const local = try self.parent.addLocalWithBoxyDesc(layout_idx, .{ .local = desc_local });
            try self.frame_locals.append(self.parent.allocator, local);
            return .{
                .local = local,
                .desc_local = desc_local,
            };
        }

        return .{
            .local = try self.addFrameLocalForRep(payload_rep),
        };
    }

    fn dynamicTagPayloadsForName(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        name: names.TagNameId,
    ) Allocator.Error![]const Plan.RepChild {
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();

        return try self.dynamicTagPayloadsForTextInner(rep_id, self.module.canonical_names.tagLabelText(name), &seen) orelse
            boxyLowerInvariant("dynamic tag expression referenced a variant outside its checked row representation");
    }

    fn dynamicTagPayloadsForVariantName(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        variant: Plan.TagVariant,
    ) Allocator.Error![]const Plan.RepChild {
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();

        return try self.dynamicTagPayloadsForTextInner(target_rep, self.tagVariantNameText(variant), &seen) orelse
            boxyLowerInvariant("dynamic tag adapter target row did not contain source variant name");
    }

    fn dynamicTagPayloadsForRepTagNameOrNull(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        name_rep: Plan.TypeRepId,
        name: names.TagNameId,
    ) Allocator.Error!?[]const Plan.RepChild {
        const source_module = procedureModuleById(self.parent.modules, self.parent.plan.representations.items[@backingInt(name_rep)].source_type.module);
        const name_text = source_module.canonical_names.tagLabelText(name);

        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();

        return try self.dynamicTagPayloadsForTextInner(target_rep, name_text, &seen);
    }

    /// The payloads of the first variant along the tag row `root` whose
    /// name matches, searching the row and its extensions in order.
    fn dynamicTagPayloadsForTextInner(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        name_text: []const u8,
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!?[]const Plan.RepChild {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |rep_id| {
            const tag_rep_id = self.tagDomainRep(rep_id) orelse continue;
            const entry = try seen.getOrPut(tag_rep_id);
            if (entry.found_existing) continue;

            const rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
            for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                if (std.mem.eql(u8, self.tagVariantNameText(variant), name_text)) {
                    return self.parent.plan.childSlice(variant.payloads);
                }
            }

            const children = self.parent.plan.childSlice(rep.children);
            var index = children.len;
            while (index > 0) {
                index -= 1;
                if (children[index].role != .tag_ext) continue;
                try pending.append(allocator, children[index].rep);
            }
        }
        return null;
    }

    /// A nominal that carries descriptor methods is described by its own
    /// descriptor, not its backing's: the backing's construction describes the
    /// shared storage with the backing's descriptor, so the nominal's is
    /// written once the value becomes the nominal.
    fn prependNominalOwnDescriptorMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        nominal_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!self.parent.plan.repOwnsDescriptorMethod(self.parent.descriptorIdentityRep(nominal_rep))) return next;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return next;
        const local = target_desc.localOrNull() orelse return next;
        if (self.localIsReadOnlyDescriptorInput(local)) return next;
        const materialization = try self.descriptorMaterializationForKnownRepExcludingLocal(nominal_rep, local);
        return try self.prependDescriptorArgMaterialization(.{
            .local = local,
            .materialize = materialization.desc,
            .captures = materialization.captures,
        }, materialization.desc, next);
    }

    /// The locals one field-access segment reads into, made before the
    /// segments after it.
    const OptionalFieldSegmentLocals = union(enum) {
        required: struct { field_local: LIR.LocalId, field_rep: Plan.TypeRepId },
        optional: struct {
            slot_rep: Plan.TypeRepId,
            slot_local: LIR.LocalId,
            present: TagVariantLookup,
            payload_rep: Plan.TypeRepId,
            payload: ExtractedTagPayloadLocal,
        },
    };

    /// Lower the chain `segments[first..]` from `receiver` into a `Try`
    /// result: each segment's locals are made in order, then each segment's
    /// reads are built from the last segment backward.
    fn lowerOptionalFieldAccessSegments(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        segments: []const checked.CheckedFieldAccessSegment,
        first: usize,
        receiver: LIR.LocalId,
        receiver_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const chain = segments[first..];
        const segment_locals = try self.parent.allocator.alloc(OptionalFieldSegmentLocals, chain.len);
        defer self.parent.allocator.free(segment_locals);
        var current = receiver;
        var current_rep = receiver_rep;
        for (chain, segment_locals) |segment, *locals| {
            const access = self.recordFieldAccessInfo(current_rep, self.module, segment.field_name);
            switch (segment.mode) {
                .required => {
                    if (access.field_kind == .optional) {
                        boxyLowerInvariant("required field-access segment selected an optional slot");
                    }
                    const field_rep = self.repForType(segment.success_ty);
                    const field_local = try self.addFrameLocalForRep(field_rep);
                    locals.* = .{ .required = .{ .field_local = field_local, .field_rep = field_rep } };
                    current = field_local;
                    current_rep = field_rep;
                },
                .optional => {
                    if (access.field_kind != .optional) {
                        boxyLowerInvariant("optional field-access segment did not select an optional slot");
                    }
                    const slot_rep = access.field_rep;
                    const slot_local = try self.addFrameLocalForRep(slot_rep);
                    const slot_rep_info = self.parent.plan.representations.items[@backingInt(slot_rep)];
                    const present = self.plannedTagVariantByText(slot_rep, "#Present");
                    const payload_children = self.parent.plan.childSlice(present.payloads);
                    if (payload_children.len != 1) {
                        boxyLowerInvariant("optional field Present slot did not carry one payload");
                    }
                    const payload_rep = payload_children[0].rep;
                    const payload = try self.addExtractedTagPayloadLocal(payload_rep, slot_rep_info.descriptor != null);
                    locals.* = .{ .optional = .{
                        .slot_rep = slot_rep,
                        .slot_local = slot_local,
                        .present = present,
                        .payload_rep = payload_rep,
                        .payload = payload,
                    } };
                    current = payload.local;
                    current_rep = payload_rep;
                },
            }
        }

        const ok = self.generatedParserTagVariant(result_rep, "Ok");
        var rest = try self.assignGeneratedParserTag(
            target,
            result_rep,
            ok,
            current,
            current_rep,
            next,
        );
        var index = chain.len;
        while (index > 0) {
            index -= 1;
            const segment = chain[index];
            const source = if (index == 0) receiver else segmentValueLocal(segment_locals[index - 1]);
            const source_rep = if (index == 0) receiver_rep else segmentValueRep(segment_locals[index - 1]);
            rest = switch (segment_locals[index]) {
                .required => |required| try self.lowerRecordFieldFromLocalInto(
                    required.field_local,
                    required.field_rep,
                    source,
                    source_rep,
                    self.module,
                    segment.field_name,
                    rest,
                ),
                .optional => |optional| try self.lowerOptionalFieldSegmentReads(target, result_rep, segment, optional, source, source_rep, rest, next),
            };
        }
        return rest;
    }

    fn segmentValueLocal(locals: OptionalFieldSegmentLocals) LIR.LocalId {
        return switch (locals) {
            .required => |required| required.field_local,
            .optional => |optional| optional.payload.local,
        };
    }

    fn segmentValueRep(locals: OptionalFieldSegmentLocals) Plan.TypeRepId {
        return switch (locals) {
            .required => |required| required.field_rep,
            .optional => |optional| optional.payload_rep,
        };
    }

    /// Read an optional segment's slot from `source`: its payload continues
    /// the chain into `present_rest`, and a missing slot makes the result
    /// `Err(MissingField)` before `next`.
    fn lowerOptionalFieldSegmentReads(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        segment: checked.CheckedFieldAccessSegment,
        optional: @FieldType(OptionalFieldSegmentLocals, "optional"),
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        present_rest: LIR.CFStmtId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const present = optional.present;
        const present_body = try self.assignConcreteTagPayloadRead(
            optional.payload.local,
            optional.payload_rep,
            optional.payload.desc_local,
            optional.slot_local,
            optional.slot_rep,
            present.name,
            present.index,
            0,
            1,
            present_rest,
        );

        const err = self.generatedParserTagVariant(result_rep, "Err");
        const err_payloads = self.parent.plan.childSlice(err.variant.payloads);
        if (err_payloads.len != 1) {
            boxyLowerInvariant("optional field access Try Err variant did not carry one payload");
        }
        const error_rep = self.nominalBackingActualRep(result_rep, err_payloads[0].rep);
        const error_local = try self.addFrameLocalForRep(error_rep);
        const err_body = try self.assignGeneratedParserTag(
            target,
            result_rep,
            err,
            error_local,
            error_rep,
            next,
        );
        const missing = self.generatedParserTagVariant(error_rep, "MissingField");
        const missing_body = try self.assignGeneratedParserZeroTag(
            error_local,
            error_rep,
            missing,
            err_body,
        );

        const discriminant = try self.addFrameLocal(.u32);
        const branches = [_]LIR.CFSwitchBranch{.{
            .value = present.index,
            .body = present_body,
        }};
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = missing_body,
            .continuation = null,
        } }, self.origin);
        const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = optional.slot_local } },
            .next = switch_stmt,
        } }, self.origin);
        return try self.lowerRecordFieldFromLocalInto(
            optional.slot_local,
            optional.slot_rep,
            source,
            source_rep,
            self.module,
            segment.field_name,
            read_discriminant,
        );
    }

    fn nominalBackingActualRep(
        self: *const ProcBodyBuilder,
        owner_rep: Plan.TypeRepId,
        backing_rep: Plan.TypeRepId,
    ) Plan.TypeRepId {
        var current = owner_rep;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => {
                    var substitution_iter = self.parent.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                    while (substitution_iter.next()) |substitution| {
                        if (substitution.formal_rep == backing_rep) return substitution.actual_rep;
                    }
                    return backing_rep;
                },
                .in_progress,
                .dynamic,
                .primitive,
                .bool_tag_union,
                .erased_callable,
                .record,
                .tuple,
                .list,
                .box,
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return backing_rep,
            }
        }
    }

    fn lowerRecordFieldFromLocalInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        receiver_local: LIR.LocalId,
        receiver_rep: Plan.TypeRepId,
        field_view: ProcedureModuleView,
        field_name: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const access = self.recordFieldAccessInfo(receiver_rep, field_view, field_name);
        const receiver_layout = self.workerRuntimeLayoutForRep(receiver_rep);
        const nested_desc_index: ?u32 = if (self.payloadFieldCarriesRuntimeDesc(access.record_rep, access.field_idx))
            self.recordFieldNestedDescriptorIndex(access.record_rep, access.field_idx)
        else
            null;
        // The receiver's own descriptor describes the record it stores. A
        // nominal receiver's record is its declaration's shared backing
        // template, whose formals only the receiver's descriptor resolves.
        const receiver_desc = if (receiver_layout == .dynamic_box or nested_desc_index != null)
            try self.descriptorRefForLocalOrKnownRep(receiver_local, receiver_rep)
        else
            null;
        const unboxed_receiver_desc_info: ResultDescriptorSource = switch (receiver_layout) {
            .concrete => .{},
            .dynamic_box => if (self.repIsOpenRecord(access.record_rep))
                try self.openRecordViewDescriptorSource(access.record_rep)
            else
                try self.storageDescriptorForRepIfNeeded(receiver_rep),
        };
        const record_desc = unboxed_receiver_desc_info.desc orelse receiver_desc;
        const read_source = switch (receiver_layout) {
            .concrete => receiver_local,
            .dynamic_box => blk: {
                const payload_layout = self.parent.layout_plan.rep_layouts[@backingInt(access.record_rep)].descriptor_payload_layout orelse
                    boxyLowerInvariant("dynamic record field access receiver had no descriptor payload layout");
                const payload = try self.addFrameLocal(payload_layout);
                if (unboxed_receiver_desc_info.desc) |desc| {
                    self.parent.result.store.setLocalBoxyDesc(payload, desc);
                }
                break :blk payload;
            },
        };
        const read_target = if (self.representationBoundaryIsDirect(target_rep, access.field_rep))
            target
        else if (nested_desc_index != null)
            try self.addFrameLocal(self.workerRuntimeLayoutForRep(access.field_rep).layoutIdx())
        else
            try self.addFrameLocalForRep(access.field_rep);
        // Record the descriptor supplied by the field read before lowering its
        // adapter. Its initializer executes before the read and conversion; it
        // must not become a type-wide slot initialized in the worker prologue.
        const field_desc_local = if (nested_desc_index != null) blk: {
            if (self.parent.result.store.getLocal(read_target).boxy_desc) |desc| {
                if (desc.localOrNull() == null) break :blk null;
            }
            const local = try self.mutableDescriptorLocalForValue(read_target);
            break :blk local;
        } else null;
        const descriptor_snapshot = if (read_target != target and field_desc_local != null)
            try self.snapshotDescriptorBindings()
        else
            null;
        defer if (descriptor_snapshot) |snapshot| {
            self.restoreDescriptorBindings(snapshot);
            snapshot.deinit(self.parent.allocator);
        };
        if (descriptor_snapshot != null) try self.bindDescriptorIdentityLocalForRep(access.field_rep, field_desc_local.?, false);
        const after_read = if (read_target == target)
            next
        else
            try self.assignRepresentationBoundary(target, read_target, target_rep, access.field_rep, next);
        const read_source_layout = self.parent.result.store.getLocal(read_source).layout_idx;
        const read_struct_layout = self.parent.result.layouts.getLayout(read_source_layout);
        const physical_field_layout = self.parent.result.layouts.getStructFieldLayoutByOriginalIndex(
            read_struct_layout.getStruct().idx,
            access.field_idx,
        );
        const read_target_layout = self.parent.result.store.getLocal(read_target).layout_idx;
        const stored_field_local = if (physical_field_layout == read_target_layout)
            read_target
        else
            try self.addFrameLocal(physical_field_layout);
        const after_stored_field_read = if (stored_field_local == read_target)
            after_read
        else blk: {
            // A field read borrows the exact stored field. Any conversion to
            // its worker representation is an explicit owned materialization.
            const field_desc = self.parent.result.store.getLocal(read_target).boxy_desc;
            if (field_desc) |desc| self.parent.result.store.setLocalBoxyDesc(stored_field_local, desc);
            break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
                .target = read_target,
                .source = stored_field_local,
                .adapter = try self.internAdapter(.materialize, physical_field_layout, read_target_layout, false),
                .source_desc = field_desc,
                .target_desc = field_desc,
                .source_mode = .borrow,
                .next = after_read,
            } }, self.origin);
        };
        const read = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = stored_field_local,
            .op = .{ .field = .{
                .source = read_source,
                .field_idx = access.field_idx,
            } },
            .next = after_stored_field_read,
        } }, self.origin);
        const before_read = if (field_desc_local) |desc_local| blk: {
            if (self.localIsReadOnlyDescriptorInput(desc_local)) break :blk read;
            break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = desc_local,
                .desc = record_desc orelse
                    boxyLowerInvariant("record field descriptor bind had no source descriptor"),
                .nested_index = nested_desc_index.?,
                .next = read,
            } }, self.origin);
        } else read;
        const after_receiver = switch (receiver_layout) {
            .concrete => before_read,
            .dynamic_box => blk: {
                const unbox = try self.parent.result.store.addCFStmt(.{
                    .assign_boxy_unbox = .{
                        .target = read_source,
                        .source = receiver_local,
                        .source_desc = receiver_desc orelse
                            boxyLowerInvariant("dynamic record field unbox had no source descriptor"),
                        .target_desc = unboxed_receiver_desc_info.desc,
                        .target_layout = self.parent.result.store.getLocal(read_source).layout_idx,
                        // This read materializes a field view. Conversion can
                        // allocate fields, so the view owns its result; copying
                        // retains only fields that still share the source.
                        .source_mode = .copy,
                        .next = before_read,
                    },
                }, self.origin);
                break :blk try self.prependOptionalDescriptorMaterialization(unboxed_receiver_desc_info.materialize, unbox);
            },
        };
        return after_receiver;
    }

    fn prependRecordFieldDescriptorBind(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        record_rep: Plan.TypeRepId,
        field_idx: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!self.payloadFieldCarriesRuntimeDesc(record_rep, field_idx)) return next;
        const nested_desc_index = self.recordFieldNestedDescriptorIndex(record_rep, field_idx);
        const record_desc = try self.descriptorRefForLocalOrKnownRep(source, record_rep);
        if (self.parent.result.store.getLocal(target).boxy_desc) |desc| {
            if (desc.localOrNull() == null) return next;
        }
        const desc_local = try self.mutableDescriptorLocalForValue(target);
        if (self.localIsReadOnlyDescriptorInput(desc_local)) return next;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = desc_local,
            .desc = record_desc,
            .nested_index = nested_desc_index,
            .next = next,
        } }, self.glueOrigin());
    }

    fn lowerTupleFieldReadInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        elem_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(target)) return try self.assignZst(target, next);

        const read = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .field = .{
                .source = source,
                .field_idx = elem_index,
            } },
            .next = next,
        } }, self.origin);
        const tuple_rep = self.tupleRepForBoundary(source_rep) orelse
            boxyLowerInvariant("tuple field read source did not have a tuple representation");
        if (!self.payloadFieldCarriesRuntimeDesc(tuple_rep, elem_index)) return read;
        const nested_index = self.tupleElemNestedDescriptorIndex(tuple_rep, elem_index);
        const desc_local = try self.mutableDescriptorLocalForValue(target);
        if (self.localIsReadOnlyDescriptorInput(desc_local)) {
            boxyLowerInvariant("tuple field read target reused a read-only descriptor input");
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = desc_local,
            .desc = try self.descriptorRefForLocalOrKnownRep(source, tuple_rep),
            .nested_index = nested_index,
            .next = read,
        } }, self.origin);
    }

    fn prependResultAliasDescriptorTransfer(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return next;
        const target_desc_local = target_desc.localOrNull() orelse return next;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return next;
        const source_desc = self.parent.result.store.getLocal(source).boxy_desc orelse return next;
        try self.markDescriptorLocalBound(target_desc_local);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = target_desc_local,
            .desc = source_desc,
            .next = next,
        } }, self.glueOrigin());
    }

    const RecordExtension = struct {
        local: LIR.LocalId,
        rep: Plan.TypeRepId,
    };

    /// Bind `nominal_rep_id`'s backing formals to the actual representations
    /// it supplies while lowering reaches into its shared backing template.
    /// Every actual is resolved in the enclosing scope before any formal is
    /// bound, so a nested use of the same declaration reads the outer binding
    /// of a formal it passes along. Nothing is materialized here: a formal's
    /// descriptor is built from its actual only where lowering needs it.
    fn enterNominalBackingFormalScope(
        self: *ProcBodyBuilder,
        nominal_rep_id: Plan.TypeRepId,
    ) Allocator.Error!NominalBackingFormalScope {
        const scope = self.beginNominalBackingFormalScope();
        try self.bindNominalBackingFormals(nominal_rep_id, scope.bindings_len);
        return scope;
    }

    fn beginNominalBackingFormalScope(self: *ProcBodyBuilder) NominalBackingFormalScope {
        const scope = NominalBackingFormalScope{
            .bindings_len = self.nominal_formal_bindings.items.len,
            .scoped_locals_start = self.scoped_descriptor_locals.items.len,
            .outer_scoped_locals_start = self.scoped_descriptor_locals_start,
        };
        self.scoped_descriptor_locals_start = scope.scoped_locals_start;
        return scope;
    }

    /// Bind `nominal_rep_id`'s formals, resolving each actual against the
    /// bindings below `enclosing_len`.
    fn bindNominalBackingFormals(
        self: *ProcBodyBuilder,
        nominal_rep_id: Plan.TypeRepId,
        enclosing_len: usize,
    ) Allocator.Error!void {
        const rep = self.parent.plan.representations.items[@backingInt(nominal_rep_id)];
        var substitutions = self.parent.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
        while (substitutions.next()) |substitution| {
            const formal_rep = substitution.formal_rep orelse continue;
            const actual = self.nominalFormalActualBelow(enclosing_len, substitution.actual_rep) orelse substitution.actual_rep;
            if (formal_rep == actual) continue;
            try self.nominal_formal_bindings.append(self.parent.allocator, .{ .formal = formal_rep, .actual = actual });
        }
    }

    /// Enter the formal scope of each nominal wrapper between `rep_id` and
    /// the structural representation it stores, outermost first: an inner
    /// wrapper's actuals can name an outer wrapper's formals.
    /// The representation inside `rep_id`'s alias and non-opaque nominal
    /// wrappers, which share their backing's storage.
    fn nominalWrapperBackingRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        for (0..self.parent.plan.representations.items.len) |_| {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return current,
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return current,
            }
        }
        boxyLowerInvariant("cyclic nominal wrapper chain reached boxy boundary lowering");
    }

    /// Bind the formals of each nominal wrapper between `rep_id` and the
    /// callable it stores in the innermost open formal scope. A callable read
    /// from an opaque nominal's backing (inside its module) is stated over
    /// that nominal's formals too.
    fn bindNominalWrapperFormalsInScope(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!void {
        var current = rep_id;
        for (0..self.parent.plan.representations.items.len) |_| {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => {
                    try self.bindNominalBackingFormals(current, self.nominal_formal_bindings.items.len);
                    current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep;
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return,
            }
        }
        boxyLowerInvariant("cyclic nominal wrapper chain reached formal binding");
    }

    fn enterNominalWrapperFormalScopes(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!NominalBackingFormalScope {
        const scope = self.beginNominalBackingFormalScope();
        var current = rep_id;
        for (0..self.parent.plan.representations.items.len) |_| {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => {
                        try self.bindNominalBackingFormals(current, self.nominal_formal_bindings.items.len);
                        current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep;
                    },
                    .opaque_nominal => return scope,
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return scope,
            }
        }
        boxyLowerInvariant("cyclic nominal wrapper chain reached pattern lowering");
    }

    /// End `scope` around `body`, the lowering done inside it: initialize the
    /// descriptor locals it reserved above `body`, under its bindings.
    fn leaveNominalBackingFormalScope(
        self: *ProcBodyBuilder,
        scope: NominalBackingFormalScope,
        body: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = body;
        var index = self.scoped_descriptor_locals.items.len;
        while (index > scope.scoped_locals_start) {
            index -= 1;
            const scoped = self.scoped_descriptor_locals.items[index];
            const materialization = try self.descriptorMaterializationForKnownRepExcludingLocal(scoped.rep, scoped.local);
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = scoped.local,
                .desc = materialization.desc,
                .captures = materialization.captures,
                .next = continuation,
            } }, self.glueOrigin());
        }
        self.dropNominalBackingFormalScope(scope);
        return continuation;
    }

    /// Pop `scope`'s bindings. Every exit path runs this, including errors.
    fn dropNominalBackingFormalScope(self: *ProcBodyBuilder, scope: NominalBackingFormalScope) void {
        self.nominal_formal_bindings.shrinkRetainingCapacity(scope.bindings_len);
        self.scoped_descriptor_locals.shrinkRetainingCapacity(scope.scoped_locals_start);
        self.scoped_descriptor_locals_start = scope.outer_scoped_locals_start;
    }

    /// Whether describing `rep_id` reads a formal an active scope binds.
    fn repDependsOnNominalFormals(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!bool {
        if (self.nominal_formal_bindings.items.len == 0) return false;
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.repDependsOnNominalFormalsInner(rep_id, &seen);
    }

    /// Whether `root` reads a formal an active scope binds. Which
    /// representations are reached does not depend on visiting order.
    fn repDependsOnNominalFormalsInner(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |rep_id| {
            const entry = try seen.getOrPut(rep_id);
            if (entry.found_existing) continue;
            if (self.nominalFormalActualBelow(self.nominal_formal_bindings.items.len, rep_id) != null) return true;
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            // A nested nominal rebinds its own formals: only its actuals can read
            // an enclosing binding.
            if (rep.kind == .nominal and rep.nominal_backing_arg_substitutions.len != 0) {
                var substitutions = self.parent.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                while (substitutions.next()) |substitution| try pending.append(allocator, substitution.actual_rep);
                continue;
            }
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (!Plan.childCarriesRuntimeDescriptor(child.role)) continue;
                try pending.append(allocator, child.rep);
            }
            for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                for (self.parent.plan.childSlice(variant.payloads)) |payload| try pending.append(allocator, payload.rep);
            }
        }
        return false;
    }

    /// The actual the innermost enclosing scope binds `rep_id` to, among the
    /// first `len` bindings.
    fn nominalFormalActualBelow(self: *const ProcBodyBuilder, len: usize, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var index = len;
        while (index > 0) {
            index -= 1;
            const binding = self.nominal_formal_bindings.items[index];
            if (binding.formal == rep_id) return binding.actual;
        }
        return null;
    }

    const RecordPayloadFieldSource = union(enum) {
        expr,
        missing_optional: Plan.TypeRepId,
        defaulted: struct {
            default: checked.CheckedFieldDefault,
            field_type: Plan.CheckedTypeIdentity,
        },
        extension: struct {
            local: LIR.LocalId,
            rep: Plan.TypeRepId,
            target_rep: Plan.TypeRepId,
            field_view: ProcedureModuleView,
            label: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
        },
    };

    fn omittedRecordFieldDefault(
        self: *const ProcBodyBuilder,
        record_expr: checked.CheckedExprId,
        field_view: ProcedureModuleView,
        field_name: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
    ) ?checked.CheckedFieldDefault {
        for (self.module.checked_bodies.record_omitted_defaults) |entry| {
            if (entry.expr != record_expr) continue;
            if (Plan.recordFieldNameMatches(viewNames(self.module), entry.field_name, viewNames(field_view), field_name)) {
                return entry.default;
            }
        }
        return null;
    }

    fn lowerOptionalSlotMissingInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        slot_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const missing = self.plannedTagVariantByText(slot_rep, "#Missing");
        return try self.lowerPlannedTagVariantInto(target, slot_rep, missing, &.{}, next);
    }

    fn plannedTagVariantByText(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        text: []const u8,
    ) TagVariantLookup {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.kind != .tag_union) {
            boxyLowerInvariant("compiler-generated optional slot did not have a tag-union representation");
        }
        for (self.parent.plan.tagVariantSlice(rep.tag_variants), 0..) |variant, index| {
            if (!std.mem.eql(u8, self.tagVariantNameText(variant), text)) continue;
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("compiler-generated optional slot variant index exceeded LIR range");
            }
            return .{
                .index = @intCast(index),
                .name = variant.name,
                .name_module = variant.name_module,
                .payloads = variant.payloads,
            };
        }
        boxyLowerInvariant("compiler-generated optional slot was missing a reserved variant");
    }

    /// `default`'s origin identity is relative to `field_module`, the module
    /// owning the defaulted record field.
    fn lowerDefaultedRecordFieldIntoFromModule(
        self: *ProcBodyBuilder,
        field_module: ProcedureModuleView,
        target: LIR.LocalId,
        default: checked.CheckedFieldDefault,
        field_type: Plan.CheckedTypeIdentity,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.runExprStep(try self.beginDefaultedRecordField(field_module, target, default, field_type, next));
    }

    fn moduleForIdentityHash(
        self: *const ProcBodyBuilder,
        origin_hash: *const [32]u8,
    ) ?ProcedureModuleView {
        const root = rootProcedureModule(self.parent.modules);
        if (procedureModuleIdentityMatches(root, origin_hash)) return root;
        for (self.parent.modules.imports) |imported| {
            const view = procedureModuleFromImport(imported);
            if (procedureModuleIdentityMatches(view, origin_hash)) return view;
        }
        for (self.parent.modules.root.relation_modules) |relation| {
            const view = procedureModuleFromImport(relation);
            if (procedureModuleIdentityMatches(view, origin_hash)) return view;
        }
        return null;
    }

    fn reserveBlockBindings(self: *ProcBodyBuilder, statements: []const checked.CheckedStatementId) Allocator.Error!void {
        for (statements) |statement_id| {
            const statement = self.module.checked_bodies.statement(statement_id);
            const rhs: ?checked.CheckedExprId = switch (statement.data) {
                inline .decl, .var_ => |decl| decl.expr,
                .reassign => |reassign| reassign.expr,
                .pending,
                .promoted_proc,
                .var_uninitialized,
                .crash,
                .dbg,
                .expr,
                .expect,
                .for_,
                .while_,
                .infinite_loop,
                .breakable_loop,
                .break_,
                .return_,
                .import_,
                .alias_decl,
                .where_alias_decl,
                .nominal_decl,
                .type_anno,
                .type_var_alias,
                .runtime_error,
                => null,
            };
            if (rhs) |expr| if (self.module.checked_bodies.expr(expr).data == .runtime_error) continue;
            switch (statement.data) {
                .decl => |decl| {
                    if (!try self.declOmitsRuntimeBinding(decl.pattern, decl.expr)) {
                        try self.reservePatternBindings(decl.pattern);
                        if (decl.recursive) try self.reserveRecursiveValueSlots(decl.pattern);
                    }
                    try self.reserveClosureCaptureSnapshots(decl.expr);
                },
                inline .var_, .var_uninitialized => |decl| try self.reservePatternBindings(decl.pattern),
                .reassign => |reassign| try self.reserveReassignPatternBindings(reassign.pattern),
                .import_,
                .alias_decl,
                .nominal_decl,
                .type_anno,
                .type_var_alias,
                .promoted_proc,
                => {},
                .pending, .crash, .dbg, .expr, .expect, .for_, .while_, .infinite_loop, .breakable_loop, .break_, .return_, .where_alias_decl, .runtime_error => {},
            }
        }
    }

    /// Each binder of a recursive value declaration that a callable captures
    /// through a slot gets one, held by those callables instead of its value.
    fn reserveRecursiveValueSlots(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) Allocator.Error!void {
        var binders = std.ArrayList(checked.PatternBinderId).empty;
        defer binders.deinit(self.parent.allocator);
        try self.appendPatternBinderIds(pattern_id, &binders);
        for (binders.items) |binder| {
            // A binder no callable captures through a slot needs none.
            const slot_rep = self.parent.plan.recursiveSlotRepFor(self.repForType(self.binderType(binder))) orelse continue;
            const slot = try self.addFrameLocal(self.workerRuntimeLayoutForRep(slot_rep).layoutIdx());
            try self.recursive_value_slots.put(self.parent.allocator, binder, slot);
        }
    }

    /// A recursive value declaration allocates each binder's zeroed slot
    /// before lowering its value, so callables in the value capture the slot,
    /// then stores each binder's value into its slot.
    fn beginRecursiveValueDecl(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        var binders = std.ArrayList(checked.PatternBinderId).empty;
        defer binders.deinit(self.parent.allocator);
        try self.appendPatternBinderIds(pattern_id, &binders);

        var current = next;
        var index = binders.items.len;
        while (index > 0) {
            index -= 1;
            const binder = binders.items[index];
            const slot = self.recursive_value_slots.get(binder) orelse continue;
            const rep = self.repForType(self.binderType(binder));
            const slot_rep = self.parent.plan.recursiveSlotRepFor(rep) orelse
                boxyLowerInvariant("boxy recursive value slot had no planned slot representation");
            const wrapper_rep = self.repQuery().requiredSingleChild(slot_rep, .box_payload).rep;
            const value = try self.addFrameLocal(self.workerRuntimeLayoutForRep(rep).layoutIdx());
            const wrapper = try self.addFrameLocal(self.workerRuntimeLayoutForRep(wrapper_rep).layoutIdx());
            const unit = try self.addFrameLocal(.zst);
            // Storing through the slot's Box keeps the slot alive through the
            // store even when nothing captured it.
            const store_args = [_]LIR.LocalId{ slot, wrapper };
            current = try self.assignLowLevelLocals(unit, .ptr_store, &store_args, current);
            current = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
                .target = wrapper,
                .fields = try self.parent.result.store.addLocalSpan(&.{value}),
                .next = current,
            } }, self.origin);
            const wrapper_desc = try self.descriptorForConstructedTargetMaterialization(
                wrapper,
                try self.descriptorMaterializationForExactRep(wrapper_rep),
            );
            current = try self.prependOptionalDescriptorMaterialization(wrapper_desc.materialize, current);
            current = try self.assignTypedLocalFromRep(value, self.localForBinder(binder), rep, self.binderStorageRep(binder), current);
        }
        const items = try self.parent.allocator.alloc(ExprChainItem, 2);
        items[0] = .{ .lower = .{ .decl_pattern = .{ .pattern = pattern_id, .expr = expr_id, .next = undefined } } };
        items[1] = .{ .recursive_value_slots = pattern_id };
        return exprChain(items, current);
    }

    fn prependRecursiveValueSlotAllocations(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        var binders = std.ArrayList(checked.PatternBinderId).empty;
        defer binders.deinit(self.parent.allocator);
        try self.appendPatternBinderIds(pattern_id, &binders);
        var current = next;
        var index = binders.items.len;
        while (index > 0) {
            index -= 1;
            const binder = binders.items[index];
            const slot = self.recursive_value_slots.get(binder) orelse continue;
            const slot_rep = self.parent.plan.recursiveSlotRepFor(self.repForType(self.binderType(binder))) orelse
                boxyLowerInvariant("boxy recursive value slot had no planned slot representation");
            current = try self.assignLowLevelLocals(slot, .box_alloc_zeroed, &.{}, current);
            // The slot is described like any constructed Box of its payload.
            const materialization = try self.descriptorMaterializationForExactRep(slot_rep);
            const slot_desc = try self.descriptorForConstructedTargetMaterialization(slot, materialization);
            current = try self.prependOptionalDescriptorMaterialization(slot_desc.materialize, current);
        }
        return current;
    }

    /// Describe the value a worker reads from a captured recursive value
    /// slot before the value's binding is lowered, the way a captured value
    /// field is described: its descriptor and descriptor environment are
    /// recorded now, and their initializers run with the captured value field
    /// descriptors. The read itself is a plain `Box` payload read.
    fn prepareRecursiveValueSlotRead(self: *ProcBodyBuilder, target: LIR.LocalId, rep: Plan.TypeRepId) Allocator.Error!void {
        if (self.parent.tagPayloadStorageDescRepIfNeeded(rep) == null) return;
        const target_desc_info = try self.descriptorRefForPayloadStorageTarget(target, rep);
        const target_desc = target_desc_info.desc orelse
            boxyLowerInvariant("boxy recursive value slot read had no target descriptor");
        self.parent.result.store.setLocalBoxyDesc(target, target_desc);
        if (target_desc_info.materialize) |materialize| {
            try self.erased_capture_value_desc_initializers.append(self.parent.allocator, materialize);
        }

        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        var initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer initializers.deinit(self.parent.allocator);
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();
        try self.collectDescriptorEnvironmentForRep(rep, target_desc, &bindings, &initializers, &seen);
        try self.recordLocalDescriptorEnvironment(target, rep, bindings.items);
        try self.erased_capture_value_desc_initializers.appendSlice(self.parent.allocator, initializers.items);
    }

    fn appendPatternBinderIds(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        out: *std.ArrayList(checked.PatternBinderId),
    ) Allocator.Error!void {
        var pending: std.ArrayList(checked.CheckedPatternId) = .empty;
        defer pending.deinit(self.parent.allocator);
        try pending.append(self.parent.allocator, pattern_id);
        while (pending.pop()) |current| {
            const pattern = self.module.checked_bodies.pattern(current);
            switch (pattern.data) {
                .assign => |binder| try out.append(self.parent.allocator, binder),
                .as => |as| {
                    try out.append(self.parent.allocator, as.binder);
                    try pending.append(self.parent.allocator, as.pattern);
                },
                .tuple => |items| for (0..items.len) |offset| try pending.append(self.parent.allocator, items[items.len - 1 - offset]),
                .record_destructure => |destructs| for (0..destructs.len) |offset| switch (destructs[destructs.len - 1 - offset].kind) {
                    .required, .sub_pattern, .rest => |child| try pending.append(self.parent.allocator, child),
                },
                .nominal => |nominal| try pending.append(self.parent.allocator, nominal.backing_pattern),
                .applied_tag => |tag| for (0..tag.args.len) |offset| try pending.append(self.parent.allocator, tag.args[tag.args.len - 1 - offset]),
                .list => |list| {
                    if (list.rest) |rest| if (rest.pattern) |rest_pattern| try pending.append(self.parent.allocator, rest_pattern);
                    for (0..list.patterns.len) |offset| try pending.append(self.parent.allocator, list.patterns[list.patterns.len - 1 - offset]);
                },
                .str_interpolation => |str| for (0..str.steps.len) |offset| {
                    if (str.steps[str.steps.len - 1 - offset].capture) |capture| try pending.append(self.parent.allocator, capture);
                },
                .pending, .underscore, .numeral_literal, .str_literal, .runtime_error => {},
            }
        }
    }

    fn declOmitsRuntimeBinding(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        expr_id: checked.CheckedExprId,
    ) Allocator.Error!bool {
        return try Plan.declarationOmitsRuntimeBinding(self.parent.allocator, self.module, pattern_id, expr_id);
    }

    /// How a pattern treats a value it does not match.
    const PatternMode = union(enum) {
        /// An irrefutable binding.
        bind,
        /// A test that jumps to `miss` when the value does not match, binding
        /// through `remaps`.
        match: PatternContext,
    };

    const PatternContext = struct {
        miss: ?PatternMiss,
        remaps: []const checked.CheckedAlternativeBinderRemap,
    };

    /// A pattern test or binding over `source`, continuing into `next`.
    const PatternTask = struct {
        pattern: checked.CheckedPatternId,
        source: LIR.LocalId,
        /// The producer's representation, which a match observes before
        /// narrowing into the pattern's contextual representation.
        source_rep: ?Plan.TypeRepId = null,
        mode: PatternMode,
        next: LIR.CFStmtId,
        state: ?*PatternState = null,
    };

    /// A pattern's pending pieces, applied from the continuation backwards:
    /// each piece wraps the statement built so far, and a nested pattern
    /// expands into the pieces it needs.
    const PatternState = struct {
        actions: std.ArrayList(PatternAction) = .empty,
        current: LIR.CFStmtId,
    };

    /// The payload patterns of one tag, built last payload first.
    const TagPayloadPatterns = struct {
        source_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        variant_index: ?u32,
        args: []const checked.CheckedPatternId,
        source: LIR.LocalId,
        source_tag_rep: Plan.TypeRepId,
        source_payloads: []const Plan.RepChild,
        context: PatternContext,
    };

    /// A list pattern's element and rest tests.
    const ListPatternShape = struct {
        elems: []const checked.CheckedPatternId,
        rest_index: ?u32,
        source: LIR.LocalId,
        len_local: LIR.LocalId,
        fixed_count: i64,
        context: PatternContext,
    };

    const PatternAction = union(enum) {
        /// Lower a pattern against `source`.
        pattern: struct { pattern: checked.CheckedPatternId, source: LIR.LocalId, mode: PatternMode },
        /// Match a pattern against the producer's representation.
        from_rep: struct { pattern: checked.CheckedPatternId, source: LIR.LocalId, source_rep: Plan.TypeRepId, context: PatternContext },
        /// Match an applied tag at `rep_id`.
        tag_rep: struct { tag_ty: checked.CheckedTypeId, rep_id: Plan.TypeRepId, name: names.TagNameId, args: []const checked.CheckedPatternId, source: LIR.LocalId, context: PatternContext },
        /// Match the payload after `index`'s predecessor, or finish the
        /// payloads at zero.
        tag_payload_next: struct { payloads: TagPayloadPatterns, index: usize },
        /// Restore the descriptors a payload pattern bound, then read the
        /// payload.
        tag_payload_read: struct {
            payloads: TagPayloadPatterns,
            index: usize,
            snapshot: DescriptorBindingsSnapshot,
            read: union(enum) {
                /// The pattern's value has the payload's layout.
                direct: struct { pattern_local: LIR.LocalId, pattern_rep: Plan.TypeRepId, pattern_desc: ?LIR.LocalId },
                /// The payload is read at its storage and narrowed.
                extracted: ExtractedTagPayloadLocal,
            },
        },
        /// Test a concrete tag's discriminant unless the union has one variant.
        tag_discriminant: struct { source: LIR.LocalId, variant_index: u32, single_variant: bool, context: PatternContext },
        /// Test a dynamic tag's name unless the contextual union has one
        /// closed variant.
        dynamic_tag_match: struct { source: LIR.LocalId, source_rep: Plan.TypeRepId, name: names.TagNameId, cannot_miss: bool, context: PatternContext },
        match_binder: struct { binder: checked.PatternBinderId, source: LIR.LocalId, remaps: []const checked.CheckedAlternativeBinderRemap },
        assign_binder: struct { binder: checked.PatternBinderId, source: LIR.LocalId },
        tuple_field: struct { tuple_ty: checked.CheckedTypeId, pattern: checked.CheckedPatternId, source: LIR.LocalId, field_index: u32, mode: PatternMode },
        tuple_read: struct { field_local: LIR.LocalId, source: LIR.LocalId, tuple_rep: Plan.TypeRepId, field_index: u32 },
        record_field: struct { pattern: checked.CheckedPatternId, field_read: RecordFieldReadSource, access: RecordFieldAccessInfo, mode: PatternMode },
        record_read: struct { field_local: LIR.LocalId, field_rep: Plan.TypeRepId, field_read: RecordFieldReadSource, access: RecordFieldAccessInfo },
        record_rest: struct { pattern: checked.CheckedPatternId, field_read: RecordFieldReadSource, record_ty: checked.CheckedTypeId, mode: PatternMode },
        record_rest_value: struct { rest_local: LIR.LocalId, field_read: RecordFieldReadSource, record_ty: checked.CheckedTypeId, rest_ty: checked.CheckedTypeId },
        /// Leave the nominal scopes a tuple, record, or tag entered; a
        /// record's field source is read first.
        leave_scope: struct { scope: NominalBackingFormalScope, field_read: ?RecordFieldReadSource },
        boundary: struct { target: LIR.LocalId, source: LIR.LocalId, target_rep: Plan.TypeRepId, source_rep: Plan.TypeRepId },
        /// Read the rest slice of a list pattern that also has elements.
        list_rest: struct { shape: ListPatternShape, rest_local: LIR.LocalId, front_dropped: LIR.LocalId },
        /// Test the element before `index`, or the length at zero.
        list_elem_next: struct { shape: ListPatternShape, index: usize },
        list_elem_read: struct { shape: ListPatternShape, elem_local: LIR.LocalId, index: usize },
        /// Check the list's length before its element tests.
        list_length: struct { shape: ListPatternShape, has_rest: bool },
        /// Match a string pattern once its captures are bound.
        str_match: struct { str: @FieldType(checked.CheckedPatternData, "str_interpolation"), lir_steps: []LIR.StrMatchStep, source: LIR.LocalId, context: PatternContext },
        /// Bind a literal pattern's value before its equality guard.
        guard_binder: struct { binder: checked.PatternBinderId, source: LIR.LocalId },
    };

    fn stepPattern(self: *ProcBodyBuilder, task: *PatternTask, input: ?LIR.CFStmtId) Allocator.Error!ExprStep {
        const allocator = self.parent.allocator;
        const state = if (task.state) |existing| blk: {
            existing.current = input orelse boxyLowerInvariant("boxy pattern resumed without its guard comparison");
            break :blk existing;
        } else blk: {
            const created = try allocator.create(PatternState);
            created.* = .{ .current = task.next };
            task.state = created;
            try created.actions.append(allocator, if (task.source_rep) |source_rep| switch (task.mode) {
                .match => |context| .{ .from_rep = .{ .pattern = task.pattern, .source = task.source, .source_rep = source_rep, .context = context } },
                .bind => boxyLowerInvariant("boxy irrefutable binding matched against a producer representation"),
            } else .{ .pattern = .{ .pattern = task.pattern, .source = task.source, .mode = task.mode } });
            break :blk created;
        };
        while (state.actions.pop()) |action| {
            if (try self.stepPatternAction(state, action)) |guard| return .{ .child = guard };
        }
        const stmt = state.current;
        self.releasePatternState(state);
        task.state = null;
        return exprDone(stmt);
    }

    /// Free a pattern's pending pieces, leaving the scopes they hold,
    /// innermost first, as the direct lowering's defers would.
    fn releasePatternState(self: *ProcBodyBuilder, state: *PatternState) void {
        const allocator = self.parent.allocator;
        var index = state.actions.items.len;
        while (index > 0) {
            index -= 1;
            switch (state.actions.items[index]) {
                .leave_scope => |leave| self.dropNominalBackingFormalScope(leave.scope),
                .tag_payload_read => |read| read.snapshot.deinit(allocator),
                .str_match => |str_match| allocator.free(str_match.lir_steps),
                .pattern, .from_rep, .tag_rep, .tag_payload_next, .tag_discriminant, .dynamic_tag_match, .match_binder, .assign_binder, .tuple_field, .tuple_read, .record_field, .record_read, .record_rest, .record_rest_value, .boundary, .list_rest, .list_elem_next, .list_elem_read, .list_length, .guard_binder => {},
            }
        }
        state.actions.deinit(allocator);
        allocator.destroy(state);
    }

    /// Push an action that owns a scope, dropping the scope if the push
    /// fails.
    fn pushPatternScope(self: *ProcBodyBuilder, state: *PatternState, scope: NominalBackingFormalScope, field_read: ?RecordFieldReadSource) Allocator.Error!void {
        state.actions.append(self.parent.allocator, .{ .leave_scope = .{ .scope = scope, .field_read = field_read } }) catch |err| {
            self.dropNominalBackingFormalScope(scope);
            return err;
        };
    }

    /// Apply one pattern piece to the statement built so far. A literal
    /// pattern's equality guard is returned for the expression machine to
    /// lower into the statement built so far.
    fn stepPatternAction(self: *ProcBodyBuilder, state: *PatternState, action: PatternAction) Allocator.Error!?ExprTask {
        const allocator = self.parent.allocator;
        switch (action) {
            .pattern => |item| return try self.expandPattern(state, item.pattern, item.source, item.mode),
            .from_rep => |item| try self.expandPatternFromRep(state, item.pattern, item.source, item.source_rep, item.context),
            .tag_rep => |item| try self.expandTagPattern(state, item.tag_ty, item.rep_id, item.name, item.args, item.source, item.context),
            .tag_payload_next => |item| {
                if (item.index == 0) return null;
                const index = item.index - 1;
                if (index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("tag match pattern payload index exceeded LIR payload index range");
                }
                const payloads = item.payloads;
                try state.actions.append(allocator, .{ .tag_payload_next = .{ .payloads = payloads, .index = index } });
                const source_payload_rep = payloads.source_payloads[index].rep;
                const payload_pattern = self.module.checked_bodies.pattern(payloads.args[index]);
                const pattern_rep = self.repForType(payload_pattern.ty);
                try state.actions.ensureUnusedCapacity(allocator, 2);
                if (self.workerRuntimeLayoutForRep(pattern_rep).layoutIdx() ==
                    self.workerRuntimeLayoutForRep(source_payload_rep).layoutIdx())
                {
                    const pattern_layout = self.workerRuntimeLayoutForRep(pattern_rep).layoutIdx();
                    const pattern_local = if (self.parent.layoutIsBoxStorage(pattern_layout))
                        try self.addFrameLocalForRepWithRequiredFreshDescriptor(pattern_rep)
                    else
                        try self.addFrameLocalForRep(pattern_rep);
                    const outer_descriptors = try self.snapshotDescriptorBindings();
                    const pattern_desc = self.bindRuntimeDescriptorLocalForValueType(pattern_local, payload_pattern.ty) catch |err| {
                        outer_descriptors.deinit(allocator);
                        return err;
                    };
                    state.actions.appendAssumeCapacity(.{ .tag_payload_read = .{
                        .payloads = payloads,
                        .index = index,
                        .snapshot = outer_descriptors,
                        .read = .{ .direct = .{ .pattern_local = pattern_local, .pattern_rep = pattern_rep, .pattern_desc = pattern_desc } },
                    } });
                    state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = payloads.args[index], .source = pattern_local, .mode = .{ .match = payloads.context } } });
                    return null;
                }
                const source_payload = try self.addExtractedTagPayloadLocal(source_payload_rep, true);
                const outer_descriptors = try self.snapshotDescriptorBindings();
                state.actions.appendAssumeCapacity(.{ .tag_payload_read = .{
                    .payloads = payloads,
                    .index = index,
                    .snapshot = outer_descriptors,
                    .read = .{ .extracted = source_payload },
                } });
                state.actions.appendAssumeCapacity(.{ .from_rep = .{ .pattern = payloads.args[index], .source = source_payload.local, .source_rep = source_payload_rep, .context = payloads.context } });
            },
            .tag_payload_read => |item| {
                defer item.snapshot.deinit(allocator);
                self.restoreDescriptorBindings(item.snapshot);
                const payloads = item.payloads;
                const index = item.index;
                const source_payload_rep = payloads.source_payloads[index].rep;
                state.current = switch (item.read) {
                    .direct => |direct| if (payloads.variant_index) |variant_index|
                        try self.assignConcreteTagPayloadRead(
                            direct.pattern_local,
                            direct.pattern_rep,
                            direct.pattern_desc,
                            payloads.source,
                            payloads.source_tag_rep,
                            payloads.tag_name,
                            variant_index,
                            @intCast(index),
                            payloads.args.len,
                            state.current,
                        )
                    else
                        try self.assignDynamicTagPayloadPatternRead(
                            direct.pattern_local,
                            direct.pattern_rep,
                            payloads.source,
                            payloads.source_rep,
                            payloads.tag_name,
                            @intCast(index),
                            source_payload_rep,
                            state.current,
                        ),
                    .extracted => |source_payload| if (payloads.variant_index) |variant_index|
                        try self.assignConcreteTagPayloadRead(
                            source_payload.local,
                            source_payload_rep,
                            source_payload.desc_local,
                            payloads.source,
                            payloads.source_tag_rep,
                            payloads.tag_name,
                            variant_index,
                            @intCast(index),
                            payloads.args.len,
                            state.current,
                        )
                    else
                        try self.assignBoxyTagPayload(
                            source_payload.local,
                            source_payload.desc_local,
                            payloads.source,
                            payloads.source_rep,
                            payloads.tag_name,
                            @intCast(index),
                            state.current,
                        ),
                };
            },
            .tag_discriminant => |item| {
                if (!item.single_variant) {
                    state.current = try self.lowerTagDiscriminantSwitch(item.source, item.variant_index, state.current, item.context.miss);
                }
            },
            .dynamic_tag_match => |item| {
                if (!item.cannot_miss) {
                    const match_desc = try self.descriptorRefForSourceLocalRep(item.source, item.source_rep);
                    state.current = try self.parent.result.store.addCFStmt(.{ .boxy_tag_match = .{
                        .source = item.source,
                        .source_desc = match_desc,
                        .tag_name = try self.lirTagName(item.name),
                        .on_match = state.current,
                        .on_miss = try self.patternMissJump(item.context.miss),
                    } }, self.origin);
                }
            },
            .match_binder => |item| state.current = try self.bindMatchBinder(item.binder, item.source, item.remaps, state.current),
            .assign_binder => |item| {
                const binder_local = self.localForBinder(item.binder);
                if (binder_local != item.source) state.current = try self.assignLocal(binder_local, item.source, state.current);
            },
            .tuple_field => |field| {
                if (self.patternIsIgnored(field.pattern)) return null;
                const pattern = self.module.checked_bodies.pattern(field.pattern);
                const field_local = try self.addFrameLocalForRepWithFreshDescriptor(self.repForType(pattern.ty));
                // The read below writes the descriptor the tuple stores for this
                // element; the sub-pattern, lowered first, must already see it.
                const tuple_rep = self.tupleRepForBoundary(self.repForType(field.tuple_ty)) orelse
                    boxyLowerInvariant("tuple pattern source did not have a tuple representation");
                if (!self.isZstLocal(field_local) and self.payloadFieldCarriesRuntimeDesc(tuple_rep, field.field_index)) {
                    _ = try self.mutableDescriptorLocalForValue(field_local);
                }
                try state.actions.append(allocator, .{ .tuple_read = .{ .field_local = field_local, .source = field.source, .tuple_rep = self.repForType(field.tuple_ty), .field_index = field.field_index } });
                try state.actions.append(allocator, .{ .pattern = .{ .pattern = field.pattern, .source = field_local, .mode = field.mode } });
            },
            .tuple_read => |read| state.current = try self.lowerTupleFieldReadInto(read.field_local, read.source, read.tuple_rep, read.field_index, state.current),
            .record_field => |field| {
                if (self.patternIsIgnored(field.pattern)) return null;
                const pattern = self.module.checked_bodies.pattern(field.pattern);
                const field_local = try self.addFrameLocalForType(pattern.ty);
                try state.actions.append(allocator, .{ .record_read = .{ .field_local = field_local, .field_rep = self.repForType(pattern.ty), .field_read = field.field_read, .access = field.access } });
                try state.actions.append(allocator, .{ .pattern = .{ .pattern = field.pattern, .source = field_local, .mode = field.mode } });
            },
            .record_read => |read| state.current = try self.lowerRecordFieldReadInto(read.field_local, read.field_rep, read.field_read, read.access, state.current),
            .record_rest => |rest| {
                const pattern = self.module.checked_bodies.pattern(rest.pattern);
                const rest_local = try self.addFrameLocalForType(pattern.ty);
                try state.actions.append(allocator, .{ .record_rest_value = .{ .rest_local = rest_local, .field_read = rest.field_read, .record_ty = rest.record_ty, .rest_ty = pattern.ty } });
                try state.actions.append(allocator, .{ .pattern = .{ .pattern = rest.pattern, .source = rest_local, .mode = rest.mode } });
            },
            .record_rest_value => |value| state.current = try self.lowerRecordRestValueInto(value.rest_local, value.field_read, value.record_ty, value.rest_ty, state.current),
            .leave_scope => |leave| {
                errdefer self.dropNominalBackingFormalScope(leave.scope);
                const body = if (leave.field_read) |field_read|
                    try self.prependRecordFieldReadSource(field_read, state.current)
                else
                    state.current;
                state.current = try self.leaveNominalBackingFormalScope(leave.scope, body);
            },
            .boundary => |item| state.current = try self.assignRepresentationBoundary(item.target, item.source, item.target_rep, item.source_rep, state.current),
            .list_rest => |rest| {
                const shape = rest.shape;
                const keep_len = try self.addFrameLocal(.u64);
                var current = try self.assignBinaryLowLevel(rest.rest_local, .list_take_first, rest.front_dropped, keep_len, state.current);
                current = try self.lenMinusConst(keep_len, shape.len_local, shape.fixed_count, current);
                const keep_after_front = try self.addFrameLocal(.u64);
                current = try self.assignBinaryLowLevel(rest.front_dropped, .list_take_last, shape.source, keep_after_front, current);
                state.current = try self.lenMinusConst(keep_after_front, shape.len_local, @intCast(shape.rest_index.?), current);
            },
            .list_elem_next => |item| {
                var index = item.index;
                while (index > 0) {
                    index -= 1;
                    const elem_pattern = item.shape.elems[index];
                    if (self.patternIsIgnored(elem_pattern)) continue;
                    try state.actions.ensureUnusedCapacity(allocator, 3);
                    state.actions.appendAssumeCapacity(.{ .list_elem_next = .{ .shape = item.shape, .index = index } });
                    const pattern = self.module.checked_bodies.pattern(elem_pattern);
                    const elem_local = try self.addFrameLocalForType(pattern.ty);
                    state.actions.appendAssumeCapacity(.{ .list_elem_read = .{ .shape = item.shape, .elem_local = elem_local, .index = index } });
                    state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = elem_pattern, .source = elem_local, .mode = .{ .match = item.shape.context } } });
                    return null;
                }
            },
            .list_elem_read => |read| {
                const shape = read.shape;
                const index_local = try self.addFrameLocal(.u64);
                const current = try self.assignBinaryLowLevel(read.elem_local, .list_get_unsafe, shape.source, index_local, state.current);
                const matches_from_back = if (shape.rest_index) |rest_index| read.index >= rest_index else false;
                state.current = if (matches_from_back)
                    try self.lenMinusConst(index_local, shape.len_local, shape.fixed_count - @as(i64, @intCast(read.index)), current)
                else
                    try self.assignU64Literal(index_local, @intCast(read.index), current);
            },
            .list_length => |length| {
                const shape = length.shape;
                const required = try self.addFrameLocal(.u64);
                const cond = try self.addFrameLocal(.bool);
                const cmp_op: LIR.LowLevel = if (length.has_rest) .num_is_gte else .num_is_eq;
                const length_check = try self.boolSwitchNoContinuation(cond, state.current, try self.patternMissJump(shape.context.miss));
                var head = try self.assignBinaryLowLevel(cond, cmp_op, shape.len_local, required, length_check);
                head = try self.assignU64Literal(required, shape.fixed_count, head);
                state.current = try self.assignUnaryLowLevel(shape.len_local, .list_len, shape.source, head);
            },
            .str_match => |item| {
                defer allocator.free(item.lir_steps);
                const arm = LIR.StrMatchArm{
                    .prefix = try self.lirStrLiteral(item.str.prefix),
                    .steps = try self.parent.result.store.addStrMatchSteps(item.lir_steps),
                    .end = switch (item.str.end) {
                        .exact => .exact,
                        .tail => .tail,
                    },
                    .on_match = state.current,
                };
                state.current = try self.parent.result.store.addCFStmt(.{ .str_match = .{
                    .source = item.source,
                    .prefix = arm.prefix,
                    .steps = arm.steps,
                    .end = arm.end,
                    .on_match = arm.on_match,
                    .on_miss = try self.patternMissJump(item.context.miss),
                } }, self.origin);
            },
            .guard_binder => |item| state.current = try self.bindMatchBinder(item.binder, item.source, &.{}, state.current),
        }
        return null;
    }

    /// Expand one pattern into the pieces that lower it. A literal pattern's
    /// equality guard is returned for the expression machine to lower.
    fn expandPattern(
        self: *ProcBodyBuilder,
        state: *PatternState,
        pattern_id: checked.CheckedPatternId,
        source: LIR.LocalId,
        mode: PatternMode,
    ) Allocator.Error!?ExprTask {
        const allocator = self.parent.allocator;
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        const context = switch (mode) {
            .match => |context| context,
            .bind => {
                switch (pattern.data) {
                    .assign => {
                        const target = self.localForPattern(pattern_id);
                        if (target != source) state.current = try self.assignLocal(target, source, state.current);
                    },
                    .as => |as| {
                        try state.actions.ensureUnusedCapacity(allocator, 2);
                        state.actions.appendAssumeCapacity(.{ .assign_binder = .{ .binder = as.binder, .source = source } });
                        state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = as.pattern, .source = source, .mode = .bind } });
                    },
                    .tuple => |items| try self.expandTuplePattern(state, pattern.ty, items, source, .bind),
                    .record_destructure => |destructs| try self.expandRecordPattern(state, pattern.ty, destructs, source, .bind),
                    .nominal => |nominal| try self.expandNominalBacking(state, pattern.ty, nominal.backing_pattern, source, .bind),
                    .list => |list| {
                        if (list.patterns.len != 0) {
                            boxyLowerInvariant("refutable list pattern reached boxy irrefutable declaration binding");
                        }
                        if (list.rest) |rest| {
                            if (rest.pattern) |rest_pattern| try state.actions.append(allocator, .{ .pattern = .{ .pattern = rest_pattern, .source = source, .mode = .bind } });
                        }
                    },
                    .applied_tag => |tag| {
                        try self.requireIrrefutableTagPattern(pattern.ty, tag.name, tag.args);
                        try state.actions.append(allocator, .{ .tag_rep = .{
                            .tag_ty = pattern.ty,
                            .rep_id = self.repForType(pattern.ty),
                            .name = tag.name,
                            .args = tag.args,
                            .source = source,
                            .context = .{ .miss = null, .remaps = &.{} },
                        } });
                    },
                    .underscore => {},
                    .numeral_literal,
                    .str_literal,
                    .str_interpolation,
                    .runtime_error,
                    .pending,
                    => boxyLowerInvariant("refutable or pending checked pattern reached boxy irrefutable declaration binding"),
                }
                return null;
            },
        };
        switch (pattern.data) {
            .assign => |binder| state.current = try self.bindMatchBinder(binder, source, context.remaps, state.current),
            .as => |as| {
                state.current = try self.bindMatchBinder(as.binder, source, context.remaps, state.current);
                try state.actions.append(allocator, .{ .pattern = .{ .pattern = as.pattern, .source = source, .mode = mode } });
            },
            .tuple => |items| try self.expandTuplePattern(state, pattern.ty, items, source, mode),
            .record_destructure => |destructs| try self.expandRecordPattern(state, pattern.ty, destructs, source, mode),
            .nominal => |nominal| {
                const nominal_rep = self.repForType(pattern.ty);
                if (self.nominalPatternSourceRep(nominal_rep)) |source_rep| {
                    try state.actions.append(allocator, .{ .from_rep = .{ .pattern = nominal.backing_pattern, .source = source, .source_rep = source_rep, .context = context } });
                    return null;
                }
                try self.expandNominalBacking(state, pattern.ty, nominal.backing_pattern, source, mode);
            },
            .applied_tag => |tag| try state.actions.append(allocator, .{ .tag_rep = .{
                .tag_ty = pattern.ty,
                .rep_id = self.repForType(pattern.ty),
                .name = tag.name,
                .args = tag.args,
                .source = source,
                .context = context,
            } }),
            .numeral_literal => |literal| {
                if (literal.guard) |guard| return try self.expandLiteralGuard(state, pattern_id, guard, source, context);
                state.current = try self.lowerNumeralPatternThen(pattern.ty, source, literal.literal, state.current, context.miss);
            },
            .str_literal => |literal| {
                if (literal.guard) |guard| return try self.expandLiteralGuard(state, pattern_id, guard, source, context);
                state.current = try self.lowerLiteralPatternThen(pattern.ty, source, .{ .str = literal.literal }, state.current, context.miss);
            },
            .underscore => {},
            .list => |list| try self.expandListPattern(state, pattern.ty, list, source, context),
            .str_interpolation => |str| {
                const lir_steps = try allocator.alloc(LIR.StrMatchStep, str.steps.len);
                var owned = true;
                defer if (owned) allocator.free(lir_steps);
                for (str.steps, lir_steps) |input_step, *lir_step| {
                    lir_step.* = .{
                        .capture = if (input_step.capture) |capture| blk: {
                            const capture_pattern = self.module.checked_bodies.pattern(capture);
                            break :blk .{ .view = try self.addFrameLocalForType(capture_pattern.ty) };
                        } else .discard,
                        .delimiter = try self.lirStrLiteral(input_step.delimiter),
                    };
                }
                try state.actions.ensureUnusedCapacity(allocator, 1 + str.steps.len);
                state.actions.appendAssumeCapacity(.{ .str_match = .{ .str = str, .lir_steps = lir_steps, .source = source, .context = context } });
                owned = false;
                // Captures bind last first.
                for (str.steps, lir_steps) |input_step, lir_step| {
                    const capture = input_step.capture orelse continue;
                    const capture_local = switch (lir_step.capture) {
                        .view => |local| local,
                        .discard => boxyLowerInvariant("string-pattern capture step lowered without a capture local"),
                    };
                    state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = capture, .source = capture_local, .mode = .bind } });
                }
            },
            .runtime_error,
            .pending,
            => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match lowering"),
        }
        return null;
    }

    /// Bind the matched value before evaluating its checker-selected equality
    /// guard. Ordinary expression lowering owns conversion and method dispatch.
    fn expandLiteralGuard(
        self: *ProcBodyBuilder,
        state: *PatternState,
        pattern_id: checked.CheckedPatternId,
        guard: checked.CheckedExprId,
        source: LIR.LocalId,
        context: PatternContext,
    ) Allocator.Error!ExprTask {
        const binder = self.module.checked_bodies.literalPatternBinder(pattern_id);
        try self.reserveBinderLocalIfFresh(binder, self.module.checked_bodies.pattern(pattern_id).ty);
        const eq = try self.addFrameLocal(.bool);
        const branch = try self.boolSwitchNoContinuation(eq, state.current, try self.patternMissJump(context.miss));
        try state.actions.append(self.parent.allocator, .{ .guard_binder = .{ .binder = binder, .source = source } });
        return .{ .expr = .{ .target = eq, .expr_id = guard, .next = branch } };
    }

    fn expandTuplePattern(
        self: *ProcBodyBuilder,
        state: *PatternState,
        tuple_ty: checked.CheckedTypeId,
        items: []const checked.CheckedPatternId,
        source: LIR.LocalId,
        mode: PatternMode,
    ) Allocator.Error!void {
        const scope = try self.enterNominalWrapperFormalScopes(self.repForType(tuple_ty));
        try self.pushPatternScope(state, scope, null);
        // Fields bind last first.
        for (items, 0..) |item, index| {
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("tuple pattern index exceeded LIR field index range");
            }
            try state.actions.append(self.parent.allocator, .{ .tuple_field = .{ .tuple_ty = tuple_ty, .pattern = item, .source = source, .field_index = @intCast(index), .mode = mode } });
        }
    }

    fn expandRecordPattern(
        self: *ProcBodyBuilder,
        state: *PatternState,
        record_ty: checked.CheckedTypeId,
        destructs: []const checked.CheckedRecordDestruct,
        source: LIR.LocalId,
        mode: PatternMode,
    ) Allocator.Error!void {
        if (!self.recordDestructureNeedsSource(destructs)) return;
        const scope = try self.enterNominalWrapperFormalScopes(self.repForType(record_ty));
        const field_read = self.recordFieldReadSourceForType(source, record_ty) catch |err| {
            self.dropNominalBackingFormalScope(scope);
            return err;
        };
        try self.pushPatternScope(state, scope, field_read);
        // Destructs bind last first.
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required,
                .sub_pattern,
                => |child_pattern| try state.actions.append(self.parent.allocator, .{ .record_field = .{
                    .pattern = child_pattern,
                    .field_read = field_read,
                    .access = self.recordFieldAccessInfo(self.repForType(record_ty), self.module, destruct.label),
                    .mode = mode,
                } }),
                .rest => |child_pattern| {
                    if (!self.patternIsIgnored(child_pattern)) {
                        try state.actions.append(self.parent.allocator, .{ .record_rest = .{ .pattern = child_pattern, .field_read = field_read, .record_ty = record_ty, .mode = mode } });
                    }
                },
            }
        }
    }

    /// Lower a nominal's backing pattern against its backing value.
    fn expandNominalBacking(
        self: *ProcBodyBuilder,
        state: *PatternState,
        nominal_ty: checked.CheckedTypeId,
        backing_pattern: checked.CheckedPatternId,
        source: LIR.LocalId,
        mode: PatternMode,
    ) Allocator.Error!void {
        const backing = self.module.checked_bodies.pattern(backing_pattern);
        const backing_local = try self.addFrameLocalForType(backing.ty);
        try state.actions.ensureUnusedCapacity(self.parent.allocator, 2);
        state.actions.appendAssumeCapacity(.{ .boundary = .{
            .target = backing_local,
            .source = source,
            .target_rep = self.repForType(backing.ty),
            .source_rep = self.repForType(nominal_ty),
        } });
        state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = backing_pattern, .source = backing_local, .mode = mode } });
    }

    fn expandListPattern(
        self: *ProcBodyBuilder,
        state: *PatternState,
        list_ty: checked.CheckedTypeId,
        list: anytype,
        source: LIR.LocalId,
        context: PatternContext,
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        const elems = list.patterns;
        if (elems.len == 0) {
            if (list.rest) |rest| {
                if (rest.pattern) |rest_pattern| {
                    try state.actions.append(allocator, .{ .pattern = .{ .pattern = rest_pattern, .source = source, .mode = .{ .match = context } } });
                }
                return;
            }
        }

        const shape = ListPatternShape{
            .elems = elems,
            .rest_index = if (list.rest) |rest| rest.index else null,
            .source = source,
            .len_local = try self.addFrameLocal(.u64),
            .fixed_count = @intCast(elems.len),
            .context = context,
        };
        try state.actions.ensureUnusedCapacity(allocator, 4);
        state.actions.appendAssumeCapacity(.{ .list_length = .{ .shape = shape, .has_rest = list.rest != null } });
        state.actions.appendAssumeCapacity(.{ .list_elem_next = .{ .shape = shape, .index = elems.len } });
        const rest = list.rest orelse return;
        const rest_pattern = rest.pattern orelse return;
        if (self.patternIsIgnored(rest_pattern)) return;
        const list_rep = self.repForType(list_ty);
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const rest_local = try self.addFrameLocal(source_layout);
        const front_dropped = try self.addFrameLocal(source_layout);
        try self.recordDescriptorPreservingListResult(front_dropped, source, list_rep);
        try self.recordDescriptorPreservingListResult(rest_local, front_dropped, list_rep);
        state.actions.appendAssumeCapacity(.{ .list_rest = .{ .shape = shape, .rest_local = rest_local, .front_dropped = front_dropped } });
        state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = rest_pattern, .source = rest_local, .mode = .{ .match = context } } });
    }

    /// Match against the representation carried by the producer before
    /// narrowing into the checked pattern's contextual representation. Tag
    /// tests must observe the exact producer row so an unmatched residual tag
    /// reaches the next branch instead of being materialized into a narrower
    /// row first.
    fn expandPatternFromRep(
        self: *ProcBodyBuilder,
        state: *PatternState,
        pattern_id: checked.CheckedPatternId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        context: PatternContext,
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        const pattern_rep = self.repForType(pattern.ty);
        if (pattern_rep == source_rep or
            (self.workerRuntimeLayoutForRep(pattern_rep).layoutIdx() == self.workerRuntimeLayoutForRep(source_rep).layoutIdx()))
        {
            try state.actions.append(allocator, .{ .pattern = .{ .pattern = pattern_id, .source = source, .mode = .{ .match = context } } });
            return;
        }

        switch (pattern.data) {
            .assign => |binder| state.current = try self.bindMatchBinderFromRep(binder, source, source_rep, context.remaps, state.current),
            .as => |as| {
                state.current = try self.bindMatchBinderFromRep(as.binder, source, source_rep, context.remaps, state.current);
                try state.actions.append(allocator, .{ .from_rep = .{ .pattern = as.pattern, .source = source, .source_rep = source_rep, .context = context } });
            },
            .applied_tag => |tag| {
                const tag_rep = self.tagPatternRepForBoundary(source_rep) orelse {
                    const source_identity = self.descriptorStorageRep(source_rep);
                    const source_rep_value = self.parent.plan.representations.items[@backingInt(source_identity)];
                    if (source_rep_value.kind != .dynamic) {
                        boxyLowerInvariant("boxy tag pattern producer had no tag representation");
                    }
                    const pattern_tag_rep = self.tagVariantRepForBoundary(pattern_rep) orelse
                        boxyLowerInvariant("boxy tag pattern contextual type had no tag representation");
                    try self.expandTagPatternFromDynamicSource(state, pattern_tag_rep, source_rep, tag.name, tag.args, source, context);
                    return;
                };
                try state.actions.append(allocator, .{ .tag_rep = .{
                    .tag_ty = pattern.ty,
                    .rep_id = tag_rep,
                    .name = tag.name,
                    .args = tag.args,
                    .source = source,
                    .context = context,
                } });
            },
            .underscore => {},
            .pending, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => {
                const narrowed = try self.addFrameBoundaryTargetLocalForRep(pattern_rep);
                try state.actions.ensureUnusedCapacity(allocator, 2);
                state.actions.appendAssumeCapacity(.{ .boundary = .{ .target = narrowed, .source = source, .target_rep = pattern_rep, .source_rep = source_rep } });
                state.actions.appendAssumeCapacity(.{ .pattern = .{ .pattern = pattern_id, .source = narrowed, .mode = .{ .match = context } } });
            },
        }
    }

    fn expandTagPatternFromDynamicSource(
        self: *ProcBodyBuilder,
        state: *PatternState,
        pattern_tag_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        name: names.TagNameId,
        args: []const checked.CheckedPatternId,
        source: LIR.LocalId,
        context: PatternContext,
    ) Allocator.Error!void {
        const pattern_rep = self.parent.plan.representations.items[@backingInt(pattern_tag_rep)];
        switch (pattern_rep.kind) {
            .bool_tag_union => {
                if (args.len != 0) {
                    boxyLowerInvariant("builtin Bool match pattern carried a payload");
                }
            },
            .tag_union => {
                const variant = self.tagVariant(pattern_rep, name);
                try self.validateTagPatternPayloads(variant.name, variant.payloads, args);
            },
            .dynamic => try self.validateDynamicTagPatternPayloads(pattern_tag_rep, name, args),
            .in_progress, .primitive, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("boxy dynamic-source tag pattern contextual representation was not a tag union"),
        }
        // The contextual representation is the checked type the pattern
        // matches. A closed union with exactly one variant cannot miss,
        // whatever storage its source uses.
        const cannot_miss = pattern_rep.kind == .tag_union and
            !self.tagDomainHasOpenExtension(pattern_tag_rep) and
            self.parent.plan.tagVariantSlice(pattern_rep.tag_variants).len == 1;
        try state.actions.append(self.parent.allocator, .{ .dynamic_tag_match = .{ .source = source, .source_rep = source_rep, .name = name, .cannot_miss = cannot_miss, .context = context } });
        try self.pushTagPayloadPatterns(state, pattern_tag_rep, source_rep, name, null, args, source, context);
    }

    fn expandTagPattern(
        self: *ProcBodyBuilder,
        state: *PatternState,
        tag_ty: checked.CheckedTypeId,
        root_rep: Plan.TypeRepId,
        name: names.TagNameId,
        args: []const checked.CheckedPatternId,
        source: LIR.LocalId,
        context: PatternContext,
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var rep_id = root_rep;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            switch (rep.kind) {
                .bool_tag_union => {
                    if (args.len != 0) {
                        boxyLowerInvariant("builtin Bool match pattern carried a payload");
                    }
                    state.current = try self.lowerTagDiscriminantSwitch(source, self.boolVariantIndex(name), state.current, context.miss);
                    return;
                },
                .tag_union => {
                    const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                    const variant = self.tagVariant(rep, name);
                    try self.validateTagPatternPayloads(variant.name, variant.payloads, args);
                    try state.actions.append(allocator, .{ .tag_discriminant = .{ .source = source, .variant_index = variant.index, .single_variant = variants.len == 1, .context = context } });
                    try self.pushTagPayloadPatterns(state, rep_id, rep_id, name, variant.index, args, source, context);
                    return;
                },
                .dynamic => {
                    try self.validateDynamicTagPatternPayloads(rep_id, name, args);
                    try state.actions.append(allocator, .{ .dynamic_tag_match = .{ .source = source, .source_rep = rep_id, .name = name, .cannot_miss = false, .context = context } });
                    try self.pushTagPayloadPatterns(state, rep_id, rep_id, name, null, args, source, context);
                    return;
                },
                .alias => rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => {
                        const backing_ty = checkedTypeAtNominalBacking(self.module, tag_ty);
                        const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
                        const scope = try self.enterNominalBackingFormalScope(rep_id);
                        try self.pushPatternScope(state, scope, null);
                        try state.actions.append(allocator, .{ .tag_rep = .{
                            .tag_ty = backing_ty,
                            .rep_id = backing_rep,
                            .name = name,
                            .args = args,
                            .source = source,
                            .context = context,
                        } });
                        return;
                    },
                    .opaque_nominal => boxyLowerInvariant("opaque nominal tag match pattern reached boxy lowering"),
                },
                .empty_tag_union => boxyLowerInvariant("empty tag-union match pattern reached boxy lowering"),
                .in_progress, .primitive, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record => boxyLowerInvariant("tag match pattern checked type did not have a boxy tag-union representation"),
            }
        }
    }

    /// Push the tests of a tag's payload patterns, which run before the
    /// action already pushed for the tag itself.
    fn pushTagPayloadPatterns(
        self: *ProcBodyBuilder,
        state: *PatternState,
        pattern_tag_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        variant_index: ?u32,
        args: []const checked.CheckedPatternId,
        source: LIR.LocalId,
        context: PatternContext,
    ) Allocator.Error!void {
        if (args.len == 0) return;

        const source_tag_rep = self.tagVariantRepForBoundary(pattern_tag_rep) orelse
            boxyLowerInvariant("boxy tag payload pattern schema had no tag representation");
        const source_payloads = if (variant_index == null)
            try self.dynamicTagPayloadsForName(source_tag_rep, tag_name)
        else
            self.parent.plan.childSlice(
                self.tagVariant(
                    self.parent.plan.representations.items[@backingInt(source_tag_rep)],
                    tag_name,
                ).payloads,
            );
        if (source_payloads.len != args.len) {
            boxyLowerInvariant("boxy tag match payload count disagreed with planned source representation");
        }
        try state.actions.append(self.parent.allocator, .{ .tag_payload_next = .{
            .payloads = .{
                .source_rep = source_rep,
                .tag_name = tag_name,
                .variant_index = variant_index,
                .args = args,
                .source = source,
                .source_tag_rep = source_tag_rep,
                .source_payloads = source_payloads,
                .context = context,
            },
            .index = args.len,
        } });
    }

    fn bindPatternFromLocal(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.runExprTasks(.{ .pattern = .{ .pattern = pattern_id, .source = source, .mode = .bind, .next = next } });
    }

    fn recordDestructureNeedsSource(
        self: *ProcBodyBuilder,
        destructs: []const checked.CheckedRecordDestruct,
    ) bool {
        for (destructs) |destruct| {
            switch (destruct.kind) {
                .required,
                .sub_pattern,
                .rest,
                => |child_pattern| if (!self.patternIsIgnored(child_pattern)) return true,
            }
        }
        return false;
    }

    fn recordFieldReadSourceForType(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        record_ty: checked.CheckedTypeId,
    ) Allocator.Error!RecordFieldReadSource {
        const source_rep = self.repForType(record_ty);
        const record_rep = self.recordRepForBoundary(source_rep) orelse
            boxyLowerInvariant("record pattern source did not have a record representation");

        return switch (self.workerRuntimeLayoutForRep(source_rep)) {
            .concrete => .{
                .local = source,
                .record_rep = record_rep,
            },
            .dynamic_box => blk: {
                const payload_layout = self.parent.layout_plan.rep_layouts[@backingInt(record_rep)].descriptor_payload_layout orelse
                    boxyLowerInvariant("dynamic record pattern source had no descriptor payload layout");
                const payload = try self.addFrameLocal(payload_layout);
                const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
                const target_desc_info = if (self.repIsOpenRecord(record_rep))
                    try self.openRecordViewDescriptorSource(record_rep)
                else
                    try self.storageDescriptorForRepIfNeeded(record_rep);
                // A `.dynamic`-rep record reports no static storage descriptor, but
                // when its unboxed payload carries an `erased_box` the value
                // must be reference-counted through a descriptor. The unboxed payload
                // has the box's payload shape, so reuse the source box's descriptor.
                const payload_desc: ?LIR.BoxyDescRef = target_desc_info.desc orelse
                    if (self.repContainsDynamicStorage(record_rep)) source_desc else null;
                if (payload_desc) |desc| {
                    self.parent.result.store.setLocalBoxyDesc(payload, desc);
                }
                break :blk .{
                    .local = payload,
                    .record_rep = record_rep,
                    .record_desc = target_desc_info.desc orelse source_desc,
                    .materialize = target_desc_info.materialize,
                    .unbox = .{
                        .source = source,
                        .source_desc = source_desc,
                        .target_desc = payload_desc,
                        .target_layout = payload_layout,
                    },
                };
            },
        };
    }

    fn prependRecordFieldReadSource(
        self: *ProcBodyBuilder,
        field_read: RecordFieldReadSource,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const unbox = field_read.unbox orelse return next;
        const stmt = try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
            .target = field_read.local,
            .source = unbox.source,
            .source_desc = unbox.source_desc,
            .target_desc = unbox.target_desc,
            .target_layout = unbox.target_layout,
            .source_mode = .copy,
            .next = next,
        } }, self.origin);
        return try self.prependOptionalDescriptorMaterialization(field_read.materialize, stmt);
    }

    fn lowerRecordFieldReadInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        field_read: RecordFieldReadSource,
        access: RecordFieldAccessInfo,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(target)) return try self.assignZst(target, next);

        const nested_desc_index: ?u32 = if (self.payloadFieldCarriesRuntimeDesc(access.record_rep, access.field_idx))
            self.recordFieldNestedDescriptorIndex(access.record_rep, access.field_idx)
        else
            null;
        const record_desc = if (nested_desc_index != null)
            field_read.record_desc orelse try self.descriptorRefForLocalOrKnownRep(field_read.local, access.record_rep)
        else
            null;
        const read_target = if (self.representationBoundaryIsDirect(target_rep, access.field_rep))
            target
        else
            try self.addFrameLocalForRep(access.field_rep);
        const after_read = if (read_target == target)
            next
        else
            try self.assignRepresentationBoundary(target, read_target, target_rep, access.field_rep, next);
        const read = if (self.isZstLocal(read_target))
            try self.assignZst(read_target, after_read)
        else
            try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = read_target,
                .op = .{ .field = .{
                    .source = field_read.local,
                    .field_idx = access.field_idx,
                } },
                .next = after_read,
            } }, self.origin);
        if (nested_desc_index) |index| {
            if (self.parent.result.store.getLocal(read_target).boxy_desc) |desc| {
                if (desc.localOrNull() == null) return read;
            }
            const desc_local = try self.mutableDescriptorLocalForValue(read_target);
            if (self.localIsReadOnlyDescriptorInput(desc_local)) return read;
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = desc_local,
                .desc = record_desc orelse
                    boxyLowerInvariant("record pattern field descriptor bind had no source descriptor"),
                .nested_index = index,
                .next = read,
            } }, self.origin);
        }
        return read;
    }

    /// Transparent nominal patterns read the declaration-owned representation,
    /// not the possibly projected backing pattern row. Builtin Bool has the
    /// same contract despite having a dedicated scalar representation.
    fn nominalPatternSourceRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        return switch (self.parent.plan.representations.items[@backingInt(rep_id)].kind) {
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => rep_id,
                .opaque_nominal => null,
            },
            .bool_tag_union => rep_id,
            .in_progress, .dynamic, .primitive, .erased_callable, .alias, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => null,
        };
    }
    fn recordDescriptorPreservingListResult(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        list_rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        if (self.parent.result.store.getLocal(target).layout_idx !=
            self.parent.result.store.getLocal(source).layout_idx)
        {
            boxyLowerInvariant("boxy descriptor-preserving list operation changed storage layout");
        }

        if (self.parent.result.store.getLocal(source).boxy_desc) |source_desc| {
            self.parent.result.store.setLocalBoxyDesc(target, source_desc);
        }
        if (self.localDescriptorEnvironmentForLocal(source)) |env| {
            if (self.descriptorStorageRep(env.rep) != self.descriptorStorageRep(list_rep)) {
                boxyLowerInvariant("boxy descriptor-preserving list operation changed representation identity");
            }
            try self.recordLocalDescriptorEnvironment(target, list_rep, env.bindings);
        }
    }

    fn validateTagPatternPayloads(
        self: *ProcBodyBuilder,
        tag_name: names.TagNameId,
        payload_span: Plan.Span,
        args: []const checked.CheckedPatternId,
    ) Allocator.Error!void {
        const payloads = self.parent.plan.childSlice(payload_span);
        if (payloads.len != args.len) {
            boxyLowerInvariant("tag match pattern payload count disagreed with its checked type representation");
        }
        for (payloads, 0..) |child, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != tag_name or payload.index != index) {
                        boxyLowerInvariant("tag match pattern payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag match pattern payload span included a non-payload child"),
            }
        }
    }

    fn validateDynamicTagPatternPayloads(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        tag_name: names.TagNameId,
        args: []const checked.CheckedPatternId,
    ) Allocator.Error!void {
        const payloads = try self.dynamicTagPayloadsForName(rep_id, tag_name);
        if (payloads.len != args.len) {
            boxyLowerInvariant("dynamic tag match pattern payload count disagreed with planned representation");
        }
    }

    fn assignDynamicTagPayloadPatternRead(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        payload_index: u32,
        source_payload_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_identity = self.descriptorStorageRep(source_rep);
        const source_has_payload_desc = self.parent.plan.representations.items[@backingInt(source_identity)].descriptor != null or
            self.parent.result.store.getLocal(source).boxy_desc != null;
        const source_payload = try self.addExtractedTagPayloadLocal(source_payload_rep, source_has_payload_desc);

        if (self.isZstLocal(source_payload.local) and self.isZstLocal(target)) {
            return try self.assignZst(target, next);
        }
        const after_boundary = try self.assignRepresentationBoundary(
            target,
            source_payload.local,
            target_rep,
            source_payload_rep,
            next,
        );
        return try self.assignBoxyTagPayload(
            source_payload.local,
            source_payload.desc_local,
            source,
            source_rep,
            tag_name,
            payload_index,
            after_boundary,
        );
    }

    fn assignBoxyTagPayload(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_desc: ?LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        payload_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignBoxyTagPayloadWithName(
            target,
            target_desc,
            source,
            source_rep,
            try self.lirTagName(tag_name),
            payload_index,
            next,
        );
    }

    fn assignBoxyTagPayloadWithName(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_desc: ?LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        tag_name: LIR.BoxyNameId,
        payload_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const writable_target_desc = if (target_desc) |desc_local|
            if (self.localIsReadOnlyDescriptorInput(desc_local)) null else desc_local
        else
            null;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag_payload = .{
            .target = target,
            .target_desc = writable_target_desc,
            .source = source,
            .source_desc = try self.descriptorRefForLocalOrKnownRep(source, source_rep),
            .tag_name = tag_name,
            .payload_index = payload_index,
            .source_mode = .copy,
            .next = next,
        } }, self.origin);
    }

    fn lowerTagDiscriminantSwitch(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        variant_index: u32,
        on_match: LIR.CFStmtId,
        miss: ?PatternMiss,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(source)) {
            if (variant_index != 0) {
                boxyLowerInvariant("zero-sized tag-union pattern expected a nonzero discriminant");
            }
            return on_match;
        }

        const discriminant = try self.addFrameLocal(.u32);
        const branches = [_]LIR.CFSwitchBranch{.{ .value = variant_index, .body = on_match }};
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = try self.patternMissJump(miss),
            .continuation = null,
        } }, self.glueOrigin());
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } }, self.glueOrigin());
    }

    fn lowerLiteralPatternThen(
        self: *ProcBodyBuilder,
        pattern_ty: checked.CheckedTypeId,
        source: LIR.LocalId,
        literal: LiteralPattern,
        on_match: LIR.CFStmtId,
        miss: ?PatternMiss,
    ) Allocator.Error!LIR.CFStmtId {
        const literal_local = try self.addFrameLocalForType(pattern_ty);
        const eq = try self.addFrameLocal(.bool);
        const switch_stmt = try self.boolSwitchNoContinuation(eq, on_match, try self.patternMissJump(miss));
        const compare = try self.lowerEqRepLocalsInto(eq, source, literal_local, self.repForType(pattern_ty), false, switch_stmt);
        return try self.assignLiteralPattern(literal_local, literal, compare);
    }

    fn lowerNumeralPatternThen(
        self: *ProcBodyBuilder,
        pattern_ty: checked.CheckedTypeId,
        source: LIR.LocalId,
        literal: can.ModuleEnv.NumeralLiteral,
        on_match: LIR.CFStmtId,
        miss: ?PatternMiss,
    ) Allocator.Error!LIR.CFStmtId {
        const literal_local = try self.addFrameLocalForType(pattern_ty);
        const eq = try self.addFrameLocal(.bool);
        const switch_stmt = try self.boolSwitchNoContinuation(eq, on_match, try self.patternMissJump(miss));
        const compare = try self.lowerEqRepLocalsInto(eq, source, literal_local, self.repForType(pattern_ty), false, switch_stmt);
        return try self.assignCheckedNumeralLiteral(literal_local, pattern_ty, literal, compare);
    }

    fn assignLiteralPattern(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        literal: LiteralPattern,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (literal) {
            .int => |value| try self.assignIntLiteral(target, value.toI128(), next),
            .dec => |value| try self.assignDecLiteral(target, value, next),
            .frac_f32 => |value| try self.assignF32Literal(target, value, next),
            .frac_f64 => |value| try self.assignF64Literal(target, value, next),
            .str => |literal_id| try self.assignStringLiteral(target, literal_id, next),
        };
    }

    fn patternMissJump(self: *ProcBodyBuilder, miss: ?PatternMiss) Allocator.Error!LIR.CFStmtId {
        const miss_info = miss orelse boxyLowerInvariant("refutable checked match pattern reached boxy lowering without a miss target");
        return try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = miss_info.join_id } }, self.glueOrigin());
    }

    fn assignU64Literal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: i64,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .i64_literal = .{ .value = value, .layout_idx = .u64 } },
            .next = next,
        } }, self.origin);
    }

    fn assignDecLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: builtins.dec.RocDec,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = .{ .boxy_dynamic_frac_literal = .{
                    .dec_bits = value.num,
                    .desc = desc_ref,
                    .default_layout = .dec,
                } },
                .next = next,
            } }, self.origin);
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            if (info.payload_layout != .dec) {
                boxyLowerInvariant("boxy dynamic decimal literal descriptor did not resolve to decimal payload layout");
            }
            const payload = try self.addFrameLocal(.dec);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .dec_literal = value.num },
                .next = box,
            } }, self.origin);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .dec_literal = value.num },
            .next = next,
        } }, self.origin);
    }

    fn assignUnaryLowLevel(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        op: LIR.LowLevel,
        arg: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const args = [_]LIR.LocalId{arg};
        return try self.assignLowLevelLocals(target, op, &args, next);
    }

    fn assignBinaryLowLevel(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        op: LIR.LowLevel,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const args = [_]LIR.LocalId{ lhs, rhs };
        return try self.assignLowLevelLocals(target, op, &args, next);
    }

    fn assignListAppendMovingElement(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        list: LIR.LocalId,
        elem: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const args = [_]LIR.LocalId{ list, elem };
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .list_append_unsafe,
            .rc_effect = LIR.LowLevel.RcEffect.consumesArgsReturningConsumedArgsRetainingArgs(0b11, 0),
            .args = try self.parent.result.store.addLocalSpan(&args),
            .next = next,
        } }, self.origin);
    }

    fn assignListAppendGrowingMovingElement(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        list: LIR.LocalId,
        elem: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const reserved = try self.addFrameLocal(self.parent.result.store.getLocal(list).layout_idx);
        if (self.parent.result.store.getLocal(list).boxy_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(reserved, desc);
        }
        const one = try self.addFrameLocal(.u64);
        var continuation = try self.assignListAppendMovingElement(target, reserved, elem, next);
        continuation = try self.assignBinaryLowLevel(reserved, .list_reserve_for_append, list, one, continuation);
        return try self.assignIntLiteral(one, 1, continuation);
    }

    fn assignLowLevelLocals(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        op: LIR.LowLevel,
        args: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = op,
            .rc_effect = op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(args),
            .next = next,
        } }, self.origin);
    }

    fn lenMinusConst(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        len_local: LIR.LocalId,
        value: i64,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const operand = try self.addFrameLocal(.u64);
        const subtract = try self.assignBinaryLowLevel(target, .num_int_sub_crash_on_overflow, len_local, operand, next);
        return try self.assignU64Literal(operand, value, subtract);
    }

    fn bindMatchBinder(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        source: LIR.LocalId,
        remaps: []const checked.CheckedAlternativeBinderRemap,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_binder = self.matchBinderRepresentative(binder, remaps);
        const target = self.localForBinder(target_binder);
        if (target == source) return next;

        const source_ty = self.binderType(binder);
        const source_rep = self.repForType(source_ty);
        const target_rep = self.binderStorageRep(target_binder);
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx or
            self.descriptorStorageRep(target_rep) != self.descriptorStorageRep(source_rep))
        {
            return try self.assignRepresentationBoundary(target, source, target_rep, source_rep, next);
        }
        // A source without a runtime descriptor has its representation's.
        return try self.assignLocalFromRep(target, source, source_rep, next);
    }

    fn bindMatchBinderFromRep(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        remaps: []const checked.CheckedAlternativeBinderRemap,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_binder = self.matchBinderRepresentative(binder, remaps);
        const target = self.localForBinder(target_binder);
        if (target == source) return next;

        const target_rep = self.binderStorageRep(target_binder);
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx or
            self.descriptorStorageRep(target_rep) != self.descriptorStorageRep(source_rep))
        {
            return try self.assignRepresentationBoundary(target, source, target_rep, source_rep, next);
        }
        return try self.assignLocalFromRep(target, source, source_rep, next);
    }

    fn matchBinderRepresentative(
        _: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        remaps: []const checked.CheckedAlternativeBinderRemap,
    ) checked.PatternBinderId {
        for (remaps) |remap| {
            if (remap.candidate_binder == binder) return remap.representative_binder;
        }
        return binder;
    }

    fn binderType(
        self: *const ProcBodyBuilder,
        binder: checked.PatternBinderId,
    ) checked.CheckedTypeId {
        const pattern_id = self.module.checked_bodies.patternBinder(binder).pattern;
        return self.module.checked_bodies.pattern(pattern_id).ty;
    }

    /// One pending step of a reassignment binding. Bindings are built from
    /// their continuation backward: each step wraps the statements the
    /// steps after it built.
    const ReassignAction = union(enum) {
        pattern: struct { pattern_id: checked.CheckedPatternId, source: LIR.LocalId },
        binder: struct { binder: checked.PatternBinderId, source: LIR.LocalId },
        tuple_field: struct { tuple_ty: checked.CheckedTypeId, pattern_id: checked.CheckedPatternId, source: LIR.LocalId, field_index: u32 },
        tuple_read: struct { field_local: LIR.LocalId, source: LIR.LocalId, tuple_rep: Plan.TypeRepId, field_index: u32 },
        record_field: struct { pattern_id: checked.CheckedPatternId, field_read: RecordFieldReadSource, access: RecordFieldAccessInfo },
        record_read: struct { field_local: LIR.LocalId, field_rep: Plan.TypeRepId, field_read: RecordFieldReadSource, access: RecordFieldAccessInfo },
        record_rest: struct { pattern_id: checked.CheckedPatternId, field_read: RecordFieldReadSource, record_ty: checked.CheckedTypeId },
        record_rest_value: struct { rest_local: LIR.LocalId, field_read: RecordFieldReadSource, record_ty: checked.CheckedTypeId, rest_ty: checked.CheckedTypeId },
        /// Leave the nominal scopes a tuple or record destructure entered;
        /// a record's field reads are read first.
        leave_scope: struct { scope: NominalBackingFormalScope, field_read: ?RecordFieldReadSource },
        nominal_boundary: struct { backing_local: LIR.LocalId, source: LIR.LocalId, backing_rep: Plan.TypeRepId, nominal_rep: Plan.TypeRepId },
    };

    fn bindReassignPatternFromLocal(
        self: *ProcBodyBuilder,
        root: checked.CheckedPatternId,
        root_source: LIR.LocalId,
        reassigned_binders: []const checked.PatternBinderId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const allocator = self.parent.allocator;
        var actions: std.ArrayList(ReassignAction) = .empty;
        defer actions.deinit(allocator);
        errdefer {
            // Leave the scopes still open, innermost first, as the direct
            // binding's defers would.
            var index = actions.items.len;
            while (index > 0) {
                index -= 1;
                switch (actions.items[index]) {
                    .leave_scope => |leave| self.dropNominalBackingFormalScope(leave.scope),
                    .pattern, .binder, .tuple_field, .tuple_read, .record_field, .record_read, .record_rest, .record_rest_value, .nominal_boundary => {},
                }
            }
        }
        try actions.append(allocator, .{ .pattern = .{ .pattern_id = root, .source = root_source } });
        var continuation = next;
        while (actions.pop()) |action| switch (action) {
            .pattern => |item| {
                const source = item.source;
                const pattern = self.module.checked_bodies.pattern(item.pattern_id);
                switch (pattern.data) {
                    .assign => |binder| continuation = try self.bindReassignBinder(binder, source, reassigned_binders, continuation),
                    .as => |as| {
                        try actions.append(allocator, .{ .binder = .{ .binder = as.binder, .source = source } });
                        try actions.append(allocator, .{ .pattern = .{ .pattern_id = as.pattern, .source = source } });
                    },
                    .tuple => |items| {
                        const scope = try self.enterNominalWrapperFormalScopes(self.repForType(pattern.ty));
                        actions.append(allocator, .{ .leave_scope = .{ .scope = scope, .field_read = null } }) catch |err| {
                            self.dropNominalBackingFormalScope(scope);
                            return err;
                        };
                        for (items, 0..) |tuple_item, index| {
                            if (index > std.math.maxInt(u32)) {
                                boxyLowerInvariant("tuple reassign pattern index exceeded LIR field index range");
                            }
                            try actions.append(allocator, .{ .tuple_field = .{ .tuple_ty = pattern.ty, .pattern_id = tuple_item, .source = source, .field_index = @intCast(index) } });
                        }
                    },
                    .record_destructure => |destructs| {
                        if (!self.recordDestructureNeedsSource(destructs)) continue;
                        const scope = try self.enterNominalWrapperFormalScopes(self.repForType(pattern.ty));
                        const field_read = self.recordFieldReadSourceForType(source, pattern.ty) catch |err| {
                            self.dropNominalBackingFormalScope(scope);
                            return err;
                        };
                        actions.append(allocator, .{ .leave_scope = .{ .scope = scope, .field_read = field_read } }) catch |err| {
                            self.dropNominalBackingFormalScope(scope);
                            return err;
                        };
                        // Destructs are bound last first.
                        for (destructs) |destruct| {
                            switch (destruct.kind) {
                                .required,
                                .sub_pattern,
                                => |child_pattern| try actions.append(allocator, .{ .record_field = .{
                                    .pattern_id = child_pattern,
                                    .field_read = field_read,
                                    .access = self.recordFieldAccessInfo(self.repForType(pattern.ty), self.module, destruct.label),
                                } }),
                                .rest => |child_pattern| {
                                    if (!self.patternIsIgnored(child_pattern)) {
                                        try actions.append(allocator, .{ .record_rest = .{ .pattern_id = child_pattern, .field_read = field_read, .record_ty = pattern.ty } });
                                    }
                                },
                            }
                        }
                    },
                    .nominal => |nominal| {
                        const backing = self.module.checked_bodies.pattern(nominal.backing_pattern);
                        const backing_local = try self.addFrameLocalForType(backing.ty);
                        try actions.append(allocator, .{ .nominal_boundary = .{
                            .backing_local = backing_local,
                            .source = source,
                            .backing_rep = self.repForType(backing.ty),
                            .nominal_rep = self.repForType(pattern.ty),
                        } });
                        try actions.append(allocator, .{ .pattern = .{ .pattern_id = nominal.backing_pattern, .source = backing_local } });
                    },
                    .list => |list| {
                        if (list.patterns.len != 0) {
                            boxyLowerInvariant("refutable list pattern reached boxy irrefutable reassign binding");
                        }
                        if (list.rest) |rest| {
                            if (rest.pattern) |rest_pattern| try actions.append(allocator, .{ .pattern = .{ .pattern_id = rest_pattern, .source = source } });
                        }
                    },
                    .underscore => {},
                    .applied_tag,
                    .numeral_literal,
                    .str_literal,
                    .str_interpolation,
                    .runtime_error,
                    .pending,
                    => boxyLowerInvariant("refutable or pending checked pattern reached boxy reassign binding"),
                }
            },
            .binder => |item| continuation = try self.bindReassignBinder(item.binder, item.source, reassigned_binders, continuation),
            .tuple_field => |field| {
                if (self.patternIsIgnored(field.pattern_id)) continue;
                const pattern = self.module.checked_bodies.pattern(field.pattern_id);
                const field_local = try self.addFrameLocalForRepWithFreshDescriptor(self.repForType(pattern.ty));
                try actions.append(allocator, .{ .tuple_read = .{ .field_local = field_local, .source = field.source, .tuple_rep = self.repForType(field.tuple_ty), .field_index = field.field_index } });
                try actions.append(allocator, .{ .pattern = .{ .pattern_id = field.pattern_id, .source = field_local } });
            },
            .tuple_read => |read| continuation = try self.lowerTupleFieldReadInto(
                read.field_local,
                read.source,
                read.tuple_rep,
                read.field_index,
                continuation,
            ),
            .record_field => |field| {
                if (self.patternIsIgnored(field.pattern_id)) continue;
                const pattern = self.module.checked_bodies.pattern(field.pattern_id);
                const field_local = try self.addFrameLocalForType(pattern.ty);
                try actions.append(allocator, .{ .record_read = .{ .field_local = field_local, .field_rep = self.repForType(pattern.ty), .field_read = field.field_read, .access = field.access } });
                try actions.append(allocator, .{ .pattern = .{ .pattern_id = field.pattern_id, .source = field_local } });
            },
            .record_read => |read| continuation = try self.lowerRecordFieldReadInto(
                read.field_local,
                read.field_rep,
                read.field_read,
                read.access,
                continuation,
            ),
            .record_rest => |rest| {
                const pattern = self.module.checked_bodies.pattern(rest.pattern_id);
                const rest_local = try self.addFrameLocalForType(pattern.ty);
                try actions.append(allocator, .{ .record_rest_value = .{ .rest_local = rest_local, .field_read = rest.field_read, .record_ty = rest.record_ty, .rest_ty = pattern.ty } });
                try actions.append(allocator, .{ .pattern = .{ .pattern_id = rest.pattern_id, .source = rest_local } });
            },
            .record_rest_value => |rest| continuation = try self.lowerRecordRestValueInto(rest.rest_local, rest.field_read, rest.record_ty, rest.rest_ty, continuation),
            .leave_scope => |leave| {
                if (leave.field_read) |field_read| continuation = try self.prependRecordFieldReadSource(field_read, continuation);
                continuation = try self.leaveNominalBackingFormalScope(leave.scope, continuation);
            },
            .nominal_boundary => |boundary| continuation = try self.assignRepresentationBoundary(boundary.backing_local, boundary.source, boundary.backing_rep, boundary.nominal_rep, continuation),
        };
        return continuation;
    }

    fn bindReassignBinder(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        source: LIR.LocalId,
        reassigned_binders: []const checked.PatternBinderId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target = self.localForBinder(binder);
        if (target == source) return next;
        if (self.binderIsReassigned(reassigned_binders, binder)) {
            return try self.setLocalReplace(target, source, next);
        }
        return try self.assignLocal(target, source, next);
    }

    fn lowerRecordRestValueInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: RecordFieldReadSource,
        source_record_ty: checked.CheckedTypeId,
        rest_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const rep_id = self.repForType(rest_ty);
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        switch (rep.kind) {
            .empty_record => return try self.assignZst(target, next),
            .record,
            => {},
            .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .tag_union, .empty_tag_union => boxyLowerInvariant("record rest pattern child did not have a boxy record representation"),
        }

        const children = self.parent.plan.childSlice(rep.children);
        var field_count: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => field_count += 1,
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record rest representation had a non-record child role"),
            }
        }

        const field_locals = try self.parent.allocator.alloc(LIR.LocalId, field_count);
        defer self.parent.allocator.free(field_locals);
        const field_reps = try self.parent.allocator.alloc(Plan.TypeRepId, field_count);
        defer self.parent.allocator.free(field_reps);
        const field_accesses = try self.parent.allocator.alloc(RecordFieldAccessInfo, field_count);
        defer self.parent.allocator.free(field_accesses);

        var layout_index: usize = 0;
        const rest_view = procedureModuleById(self.parent.modules, rep.source_type.module);
        for (children) |child| {
            switch (child.role) {
                .record_field => |label| {
                    field_locals[layout_index] = try self.addFrameLocalForRep(child.rep);
                    field_reps[layout_index] = child.rep;
                    field_accesses[layout_index] = self.recordFieldAccessInfo(self.repForType(source_record_ty), rest_view, label);
                    layout_index += 1;
                },
                .record_ext => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => unreachable,
            }
        }

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(field_locals),
            .next = next,
        } }, self.origin);
        var index = field_count;
        while (index > 0) {
            index -= 1;
            continuation = try self.lowerRecordFieldReadInto(
                field_locals[index],
                field_reps[index],
                source,
                field_accesses[index],
                continuation,
            );
        }
        return continuation;
    }

    /// Initialize the locals `root` binds as uninitialized, before `next`.
    /// Each binding wraps the statements after it, so bindings are visited
    /// in reverse source order.
    fn lowerUninitializedPattern(
        self: *ProcBodyBuilder,
        root: checked.CheckedPatternId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const allocator = self.parent.allocator;
        const Action = union(enum) {
            pattern: checked.CheckedPatternId,
            binder: checked.PatternBinderId,
        };
        var actions: std.ArrayList(Action) = .empty;
        defer actions.deinit(allocator);
        try actions.append(allocator, .{ .pattern = root });
        var continuation = next;
        while (actions.pop()) |action| {
            const pattern_id = switch (action) {
                .binder => |binder| {
                    continuation = try self.initUninitializedLocal(self.localForBinder(binder), continuation);
                    continue;
                },
                .pattern => |pattern_id| pattern_id,
            };
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            switch (pattern.data) {
                .assign => continuation = try self.initUninitializedLocal(self.localForPattern(pattern_id), continuation),
                .as => |as| {
                    try actions.append(allocator, .{ .binder = as.binder });
                    try actions.append(allocator, .{ .pattern = as.pattern });
                },
                .tuple => |items| for (items) |item| try actions.append(allocator, .{ .pattern = item }),
                .record_destructure => |destructs| for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child_pattern| child_pattern,
                    };
                    try actions.append(allocator, .{ .pattern = child });
                },
                .nominal => |nominal| try actions.append(allocator, .{ .pattern = nominal.backing_pattern }),
                .list => |list| {
                    if (list.patterns.len != 0) {
                        boxyLowerInvariant("refutable list pattern reached boxy uninitialized binding");
                    }
                    if (list.rest) |rest| {
                        if (rest.pattern) |rest_pattern| try actions.append(allocator, .{ .pattern = rest_pattern });
                    }
                },
                .underscore,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                => {},
                .applied_tag,
                .runtime_error,
                .pending,
                => boxyLowerInvariant("refutable or pending checked pattern reached boxy uninitialized binding"),
            }
        }
        return continuation;
    }

    fn initUninitializedLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(target)) return next;
        return try self.parent.result.store.addCFStmt(.{ .init_uninitialized = .{
            .target = target,
            .next = next,
        } }, self.glueOrigin());
    }

    const IteratorStepShape = struct {
        module: ProcedureModuleView,
        step_ty: Plan.CheckedTypeIdentity,
        done_tag: names.TagNameId,
        one_tag: names.TagNameId,
        skip_tag: names.TagNameId,
        one_payload_ty: Plan.CheckedTypeIdentity,
        skip_payload_ty: Plan.CheckedTypeIdentity,
        one_item: checked.CheckedRecordField,
        one_rest: checked.CheckedRecordField,
        skip_rest: checked.CheckedRecordField,
    };

    fn lowerIteratorSkipBranch(
        self: *ProcBodyBuilder,
        step: IteratorStepShape,
        step_local: LIR.LocalId,
        variant_index: ?u32,
        iterator_param: LIR.LocalId,
        join_id: LIR.JoinPointId,
    ) Allocator.Error!LIR.CFStmtId {
        const payload_rep = self.repForTypeRef(step.skip_payload_ty);
        const payload = try self.addFrameLocalForRepWithFreshDescriptor(payload_rep);
        const payload_desc = try self.ensureTagPayloadTargetDescriptorLocal(payload, payload_rep);
        const rest = try self.addFrameLocalForRepWithFreshDescriptor(self.repForTypeRef(.{ .module = step.skip_payload_ty.module, .ty = step.skip_rest.ty }));

        var continuation = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, self.glueOrigin());
        continuation = try self.setLocalInitializeJoinParam(iterator_param, rest, continuation);
        continuation = try self.lowerRecordFieldFromLocalInto(rest, self.repForTypeRef(.{ .module = step.skip_payload_ty.module, .ty = step.skip_rest.ty }), payload, self.repForTypeRef(step.skip_payload_ty), step.module, step.skip_rest.name, continuation);
        return try self.readTagPayloadStructInto(payload, payload_rep, payload_desc, step_local, self.repForTypeRef(step.step_ty), step.skip_tag, variant_index, continuation);
    }

    fn readTagPayloadStructInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        target_desc: ?LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        variant_index: ?u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse
            boxyLowerInvariant("iterator tag payload read source was not a tag union representation");
        if (variant_index == null) {
            const source_payloads = try self.dynamicTagPayloadsForName(source_rep, tag_name);
            if (source_payloads.len != 1) {
                boxyLowerInvariant("iterator dynamic tag payload did not have one field");
            }
            return try self.assignDynamicTagPayloadPatternRead(
                target,
                target_rep,
                source,
                source_rep,
                tag_name,
                0,
                source_payloads[0].rep,
                next,
            );
        }
        return try self.assignConcreteTagPayloadRead(
            target,
            target_rep,
            target_desc,
            source,
            source_tag_rep,
            tag_name,
            variant_index.?,
            0,
            1,
            next,
        );
    }

    fn unresolvedIteratorDispatchStep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        plan: static_dispatch.IteratorForPlan,
        kind: Plan.IteratorCallKind,
        call: static_dispatch.IteratorDispatchCall,
        loop_iterator: ?LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        const dispatcher_rep = self.repForType(call.dispatcher_ty);
        const match = self.dictionaryMethodForRep(dispatcher_rep, call.method) orelse
            boxyLowerInvariant("unresolved iterator dispatch reached boxy lowering without a matching dictionary requirement");
        const dict_local = self.dictionaryLocalForRequirementOrNull(match.requirement) orelse
            boxyLowerInvariant("unresolved iterator dispatch reached boxy lowering without a bound dictionary local");
        if (!self.dictionaryBindingIsBound(match.requirement)) {
            boxyLowerInvariant("unresolved iterator dispatch reached boxy lowering with an unbound dictionary local");
        }
        const required_method = self.parent.plan.dictionaries.items[@backingInt(match.requirement)].fn_name;

        const operands = call.argsSlice(self.module.static_dispatch_plans);
        if (call.dispatcher_arg_index >= operands.len) {
            boxyLowerInvariant("unresolved iterator dispatch dispatcher argument index was outside the operand span");
        }

        const arg_locals = try self.parent.allocator.alloc(LIR.LocalId, operands.len);
        defer self.parent.allocator.free(arg_locals);
        const arg_types = try self.parent.allocator.alloc(Plan.CheckedTypeIdentity, operands.len);
        defer self.parent.allocator.free(arg_types);
        const arg_reps = try self.parent.allocator.alloc(Plan.TypeRepId, operands.len);
        defer self.parent.allocator.free(arg_reps);
        for (operands, arg_locals, arg_reps) |operand, *local, *arg_rep| {
            local.* = switch (operand) {
                .checked_expr => |expr| blk: {
                    const checked_expr = self.module.checked_bodies.expr(expr);
                    arg_rep.* = self.repForType(checked_expr.ty);
                    break :blk try self.addFrameLocalForType(checked_expr.ty);
                },
                .loop_iterator_state => blk: {
                    arg_rep.* = self.repForType(plan.iterator_ty);
                    const iterator = loop_iterator orelse
                        boxyLowerInvariant("iterator next dictionary dispatch reached boxy lowering without loop iterator state");
                    if (self.parent.result.store.getLocal(iterator).layout_idx != self.workerRuntimeLayoutForType(plan.iterator_ty).layoutIdx()) {
                        boxyLowerInvariant("iterator next dictionary dispatch loop state layout disagreed with iterator plan");
                    }
                    break :blk iterator;
                },
            };
        }
        for (operands, arg_types) |operand, *arg_type| {
            arg_type.* = switch (operand) {
                .checked_expr => |expr| .{ .module = self.module.key, .ty = self.module.checked_bodies.expr(expr).ty },
                .loop_iterator_state => .{ .module = self.module.key, .ty = plan.iterator_ty },
            };
        }
        const ret_type = Plan.CheckedTypeIdentity{ .module = self.module.key, .ty = switch (kind) {
            .iter => plan.iterator_ty,
            .next => plan.step_ty,
        } };
        const method_function_rep = self.dictionaryMethodFunctionRepForCall(call.callable_ty);
        const method_function = self.functionChildrenForRep(method_function_rep) orelse
            boxyLowerInvariant("iterator dictionary dispatch method representation was not a function");
        const hidden_desc_args = try self.dictionaryCallHiddenDescriptorArgs(
            method_function_rep,
            dispatcher_rep,
            match.requirement,
            call.dispatcher_arg_index,
            arg_types,
            arg_reps,
            ret_type,
        );
        defer self.parent.allocator.free(hidden_desc_args);
        var pre_arg_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer pre_arg_descriptor_initializers.deinit(self.parent.allocator);
        var call_arg_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer call_arg_descriptor_initializers.deinit(self.parent.allocator);
        const argument_desc_locals = try self.dictionaryCallArgumentDescriptorLocals(
            arg_reps,
            arg_locals,
            &call_arg_descriptor_initializers,
        );
        defer self.parent.allocator.free(argument_desc_locals);
        const hidden_desc_locals = try self.lowerDirectCallHiddenDescriptorArgs(hidden_desc_args, arg_locals, arg_reps, arg_reps);
        defer self.parent.allocator.free(hidden_desc_locals);
        try self.recordDirectCallResultDescriptorEnvironment(
            target,
            method_function.ret,
            hidden_desc_args,
            hidden_desc_locals,
        );

        const hidden_arg_locals = try self.parent.allocator.alloc(LIR.LocalId, hidden_desc_locals.len);
        defer self.parent.allocator.free(hidden_arg_locals);
        for (hidden_desc_locals, 0..) |hidden, index| {
            hidden_arg_locals[index] = hidden.local;
        }

        const result_desc_info = self.resultDescriptorForCallTarget(
            target,
            try self.dictionaryCallResultDescriptorRef(self.repForTypeRef(ret_type), hidden_desc_args, hidden_desc_locals),
        );
        if (result_desc_info.desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(target, desc);
        }

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_call_dict = .{
            .target = target,
            .dict = .{ .local = dict_local },
            .method = required_method,
            .method_slot = match.slot,
            .args = try self.parent.result.store.addLocalSpan(arg_locals),
            .arg_descs = try self.parent.result.store.addLocalSpan(argument_desc_locals),
            .hidden_args = try self.parent.result.store.addLocalSpan(hidden_arg_locals),
            .result_desc = result_desc_info.desc,
            .next = next,
        } }, self.glueOrigin());
        if (result_desc_info.materialize) |materialize| {
            const desc = materialize.materialize orelse
                boxyLowerInvariant("boxy iterator dictionary call result descriptor materialization had no descriptor");
            continuation = try self.prependDescriptorArgMaterialization(materialize, desc, continuation);
        }
        continuation = try self.prependDescriptorArgMaterializations(hidden_desc_locals, continuation);
        continuation = try self.prependDescriptorArgMaterializations(call_arg_descriptor_initializers.items, continuation);
        continuation = try self.prependDescriptorArgMaterializations(pre_arg_descriptor_initializers.items, continuation);
        var chain_items = std.ArrayList(ExprChainItem).empty;
        errdefer chain_items.deinit(self.parent.allocator);
        var index = operands.len;
        while (index > 0) {
            index -= 1;
            switch (operands[index]) {
                .checked_expr => |expr| try chain_items.append(self.parent.allocator, .{ .lower = .{ .expr = .{ .target = arg_locals[index], .expr_id = expr, .next = undefined } } }),
                .loop_iterator_state => {},
            }
        }
        return exprChain(try chain_items.toOwnedSlice(self.parent.allocator), continuation);
    }

    fn iteratorForPlan(
        self: *const ProcBodyBuilder,
        plan_id: static_dispatch.IteratorForPlanId,
    ) static_dispatch.IteratorForPlan {
        const raw = @backingInt(plan_id);
        if (raw >= self.module.static_dispatch_plans.iterator_for_plans.len) {
            boxyLowerInvariant("checked iterator for referenced a missing iterator dispatch plan");
        }
        return self.module.static_dispatch_plans.iterator_for_plans[raw];
    }

    fn iteratorStepShapeForTypeRef(self: *ProcBodyBuilder, step_ref: Plan.CheckedTypeIdentity) Allocator.Error!IteratorStepShape {
        const module = procedureModuleById(self.parent.modules, step_ref.module);
        const step_payload = resolvedTypePayload(module, step_ref.ty);
        const step_tag_union = switch (step_payload) {
            .tag_union => |tag_union| tag_union,
            .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("iterator next plan did not return a tag union"),
        };

        var done_tag: ?names.TagNameId = null;
        var one_tag: ?names.TagNameId = null;
        var skip_tag: ?names.TagNameId = null;
        var one_payload_ty: ?checked.CheckedTypeId = null;
        var skip_payload_ty: ?checked.CheckedTypeId = null;

        var seen = collections.DenseMap(checked.CheckedTypeId, void).init(self.parent.allocator);
        defer seen.deinit();

        var tags = step_tag_union.tags;
        var current: ?checked.CheckedTypeId = step_tag_union.ext;
        while (true) {
            for (tags) |tag| {
                const tag_args = tag.argsSlice(module.checked_types);
                const tag_text = module.canonical_names.tagLabelText(tag.name);
                if (std.mem.eql(u8, tag_text, "Done")) {
                    if (tag_args.len != 0) boxyLowerInvariant("iterator Done step carried payloads");
                    if (done_tag != null) boxyLowerInvariant("iterator step type had duplicate Done tags");
                    done_tag = tag.name;
                } else if (std.mem.eql(u8, tag_text, "One")) {
                    if (tag_args.len != 1) boxyLowerInvariant("iterator One step did not carry one payload");
                    if (one_tag != null) boxyLowerInvariant("iterator step type had duplicate One tags");
                    one_tag = tag.name;
                    one_payload_ty = tag_args[0];
                } else if (std.mem.eql(u8, tag_text, "Skip")) {
                    if (tag_args.len != 1) boxyLowerInvariant("iterator Skip step did not carry one payload");
                    if (skip_tag != null) boxyLowerInvariant("iterator step type had duplicate Skip tags");
                    skip_tag = tag.name;
                    skip_payload_ty = tag_args[0];
                }
            }

            const ext = current orelse break;
