    fn beginListMapCanReuse(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        args: []const checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!ExprStep {
        var map_output_elem: ?layout.Idx = null;
        const interchangeable = self.listMapLayoutsInterchangeable(args, &map_output_elem);
        if (!interchangeable.get(.u32) and !interchangeable.get(.u64)) {
            return exprDone(try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = .{ .i64_literal = .{
                    .value = 0,
                    .layout_idx = self.parent.result.store.getLocal(target).layout_idx,
                } },
                .next = next,
            } }, self.origin));
        }

        const lowered = try self.lowerExprsToTemps(args);
        defer self.parent.allocator.free(lowered);

        const continuation = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .list_map_can_reuse,
            .rc_effect = LIR.LowLevel.list_map_can_reuse.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(lowered),
            .interchangeable = interchangeable,
            .map_output_elem = map_output_elem,
            .next = next,
        } }, self.origin);
        return try self.loweredExprsChain(args, lowered, continuation);
    }

    fn listMapLayoutsInterchangeable(
        self: *ProcBodyBuilder,
        args: []const checked.CheckedExprId,
        output_layout: ?*?layout.Idx,
    ) layout.WidthValues(bool) {
        const none = layout.WidthValues(bool).both(false, false);
        if (!self.parent.options.list_in_place_map) return none;
        if (args.len != 2) boxyLowerInvariant("list_map_can_reuse reached boxy lowering with the wrong arity");

        const list_expr = self.module.checked_bodies.expr(args[0]);
        const list_rep = self.listRepForBoundary(self.repForType(list_expr.ty)) orelse
            boxyLowerInvariant("list_map_can_reuse input did not have a list representation");
        const in_elem_rep = self.repQuery().requiredSingleChild(list_rep, .list_elem).rep;
        const list_layout_idx = self.workerRuntimeLayoutForType(list_expr.ty).layoutIdx();
        const list_layout = self.parent.result.layouts.getLayout(list_layout_idx);
        if (list_layout.tag != .list) return none;
        const in_elem_idx = self.parent.result.layouts.runtimeRepresentationLayoutIdx(list_layout.getIdx());

        const transform_expr = self.module.checked_bodies.expr(args[1]);
        const out_ret_rep = self.functionReturnRepForType(transform_expr.ty);

        // The in-place branch temporarily stores untransformed and transformed
        // elements in the same allocation. Descriptor-governed elements may
        // use byte-identical box storage while requiring different RC header
        // shapes, so one list descriptor cannot safely describe that mixed
        // allocation. Fully concrete elements need only layout compatibility;
        // otherwise both sides must use the same identity representation.
        if ((!self.repIsFullyConcrete(in_elem_rep) or !self.repIsFullyConcrete(out_ret_rep)) and
            self.descriptorStorageRep(in_elem_rep) != self.descriptorStorageRep(out_ret_rep))
        {
            return none;
        }

        const out_elem_idx = self.parent.result.layouts.runtimeRepresentationLayoutIdx(
            self.workerRuntimeLayoutForRep(out_ret_rep).layoutIdx(),
        );
        if (output_layout) |out| out.* = out_elem_idx;

        return layout.WidthValues(bool).both(
            self.listMapInterchangeableAtWidth(in_elem_idx, out_elem_idx, .u32),
            self.listMapInterchangeableAtWidth(in_elem_idx, out_elem_idx, .u64),
        );
    }

    fn listMapInterchangeableAtWidth(
        self: *ProcBodyBuilder,
        in_elem_idx: layout.Idx,
        out_elem_idx: layout.Idx,
        target_usize: base.target.TargetUsize,
    ) bool {
        const layouts = &self.parent.result.layouts;
        const in_elem = layouts.getLayout(in_elem_idx);
        const in_size = layouts.sizeAt(in_elem, target_usize);
        if (in_size == 0) return false;

        const out_elem = layouts.getLayout(out_elem_idx);
        if (layouts.sizeAt(out_elem, target_usize) != in_size) return false;

        const ptr_width = target_usize.size();
        const in_alignment: u32 = @intCast(in_elem.alignment(target_usize).toByteUnits());
        const out_alignment: u32 = @intCast(out_elem.alignment(target_usize).toByteUnits());
        if (@max(ptr_width, in_alignment) != @max(ptr_width, out_alignment)) return false;

        if (layouts.layoutContainsRefcounted(in_elem) != layouts.layoutContainsRefcounted(out_elem)) return false;

        return true;
    }

    fn lowerExprsToTemps(
        self: *ProcBodyBuilder,
        args: []const checked.CheckedExprId,
    ) Allocator.Error![]LIR.LocalId {
        const lowered = try self.parent.allocator.alloc(LIR.LocalId, args.len);
        errdefer self.parent.allocator.free(lowered);
        for (args, lowered) |arg, *local| {
            const expr = self.module.checked_bodies.expr(arg);
            const rep = self.repForType(expr.ty);
            local.* = if (self.parent.layoutIsBoxStorage(self.workerRuntimeLayoutForRep(rep).layoutIdx()))
                try self.addFrameLocalForRepWithFreshDescriptor(rep)
            else
                try self.addFrameLocalForRep(rep);
        }
        return lowered;
    }

    fn lowerDictionaryOperandsToTemps(
        self: *ProcBodyBuilder,
        operands: []const Plan.CallOperand,
        reps: []const Plan.TypeRepId,
    ) Allocator.Error![]LIR.LocalId {
        if (operands.len != reps.len) {
            boxyLowerInvariant("boxy dictionary operand count disagreed with planned representations");
        }
        const lowered = try self.parent.allocator.alloc(LIR.LocalId, operands.len);
        errdefer self.parent.allocator.free(lowered);
        for (reps, lowered) |rep, *local| {
            local.* = try self.addFrameBoundaryTargetLocalForRep(rep);
        }
        return lowered;
    }

    fn lowerCallOperandsExpectedToTemps(
        self: *ProcBodyBuilder,
        operands: []const Plan.CallOperand,
        arg_types: []const Plan.CheckedTypeIdentity,
        actual_arg_reps: []const Plan.TypeRepId,
    ) Allocator.Error![]LIR.LocalId {
        if (operands.len != arg_types.len or operands.len != actual_arg_reps.len) {
            boxyLowerInvariant("boxy expected expression locals disagreed with source expression count");
        }
        const lowered = try self.parent.allocator.alloc(LIR.LocalId, operands.len);
        errdefer self.parent.allocator.free(lowered);
        for (actual_arg_reps, lowered) |actual_arg_rep, *local| {
            local.* = try self.addFrameBoundaryTargetLocalForRep(actual_arg_rep);
        }
        return lowered;
    }

    fn dictionaryCallHiddenDescriptorArgs(
        self: *ProcBodyBuilder,
        method_function_rep_id: Plan.TypeRepId,
        dispatcher_rep_id: Plan.TypeRepId,
        requirement_id: Plan.DictionaryRequirementId,
        dispatcher_arg_index: ?u32,
        arg_types: []const Plan.CheckedTypeIdentity,
        operand_arg_reps: []const Plan.TypeRepId,
        ret_type: Plan.CheckedTypeIdentity,
    ) Allocator.Error![]Plan.DirectCallHiddenDescriptorArg {
        const requirement = self.parent.plan.dictionaries.items[@backingInt(requirement_id)];
        const requirement_rep = self.repForTypeRef(requirement.fn_ty);
        // The dictionary slot owns the hidden-argument interface. A checked
        // invocation can instantiate its rows without removing interface slots.
        const method_function = self.functionChildrenForRep(requirement_rep) orelse
            boxyLowerInvariant("boxy dictionary requirement callable was not a function");
        const call_function = self.functionChildrenForRep(method_function_rep_id) orelse
            boxyLowerInvariant("boxy dictionary call method callable was not a function");
        if (call_function.arg_count != method_function.arg_count) {
            boxyLowerInvariant("boxy dictionary invocation disagreed with its requirement arity");
        }
        if (method_function.arg_count != arg_types.len or arg_types.len != operand_arg_reps.len) {
            boxyLowerInvariant("boxy dictionary call hidden descriptor mapping saw mismatched function arity");
        }

        var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
        defer params.deinit(self.parent.allocator);
        try self.collectHiddenDescriptorParamsForFunction(method_function, &params);
        if (params.items.len == 0) return try self.parent.allocator.alloc(Plan.DirectCallHiddenDescriptorArg, 0);

