            }
            const worker_function = self.parent.staticMethodFunctionForRep(requirement_rep) orelse
                boxyLowerInvariant("boxy dictionary call worker representation was not a method function");
            const requirement_function = self.parent.staticMethodFunctionForRep(requirement_rep) orelse
                boxyLowerInvariant("boxy dictionary call requirement representation was not a method function");
            if (worker_function.arg_count != requirement_function.arg_count) {
                boxyLowerInvariant("boxy dictionary call owner descriptor mapping saw mismatched function arity");
            }

            const worker_children = self.parent.plan.childSlice(
                self.parent.plan.representations.items[@backingInt(worker_function.rep)].children,
            );
            const requirement_children = self.parent.plan.childSlice(
                self.parent.plan.representations.items[@backingInt(requirement_function.rep)].children,
            );
            const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
            const requirement_args = requirement_children[requirement_function.args_start..][0..requirement_function.arg_count];
            if (requirement_args.len == 0) {
                boxyLowerInvariant("boxy dictionary method requirement had no owner argument");
            }
            const owner_requirement_rep = requirement_args[0].rep;
            var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
            defer seen.deinit();
            for (worker_args, requirement_args) |worker_arg, requirement_arg| {
                try self.parent.collectStaticDictionaryDescriptorSourcesForAlignedRep(
                    worker_arg.rep,
                    requirement_arg.rep,
                    owner_requirement_rep,
                    dispatcher_rep_id,
                    params.items,
                    .worker_hidden_params,
                    &owner_descriptor_sources,
                    &seen,
                );
            }
            try self.parent.collectStaticDictionaryDescriptorSourcesForAlignedRep(
                worker_function.ret,
                requirement_function.ret,
                owner_requirement_rep,
                dispatcher_rep_id,
                params.items,
                .worker_hidden_params,
                &owner_descriptor_sources,
                &seen,
            );
        }

        var pending = std.ArrayList(Plan.DirectCallHiddenDescriptorArg).empty;
        errdefer pending.deinit(self.parent.allocator);
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descriptor_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_descriptor_reps.deinit();
        var next_param: usize = 0;

        const method_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(method_function.rep)].children);
        const method_args = method_children[method_function.args_start..][0..method_function.arg_count];
        for (method_args, arg_types, operand_arg_reps, 0..) |method_arg, arg_type, operand_arg_rep, arg_index| {
            const call_arg_rep = self.repForTypeRef(arg_type);
            try self.collectDictionaryCallHiddenDescriptorArgs(
                method_arg.rep,
                call_arg_rep,
                operand_arg_rep,
                @intCast(arg_index),
                params.items,
                &next_param,
                &pending,
                &seen_reps,
                &seen_descriptor_reps,
            );
        }
        const ret_rep = self.repForTypeRef(ret_type);
        try self.collectDictionaryCallHiddenDescriptorArgs(
            method_function.ret,
            ret_rep,
            ret_rep,
            null,
            params.items,
            &next_param,
            &pending,
            &seen_reps,
            &seen_descriptor_reps,
        );

        if (next_param != params.items.len or pending.items.len != params.items.len) {
            boxyLowerInvariant("boxy dictionary call hidden descriptor mapping did not cover every method descriptor param");
        }

        if (dispatcher_arg_index) |raw_index| {
            const index: usize = @intCast(raw_index);
            const dispatcher_arg_rep = operand_arg_reps[index];
            const descriptor_rep = self.repQuery().descriptorArgumentIdentityRep(dispatcher_arg_rep);
            const descriptor_source_type = self.parent.plan.representations.items[@backingInt(descriptor_rep)].source_type;
            for (pending.items) |*arg| {
                if (owner_descriptor_sources.get(arg.worker_desc) == null) continue;
                arg.source_type = descriptor_source_type;
                arg.rep = descriptor_rep;
                arg.source_arg_index = raw_index;
                arg.source_value_rep = dispatcher_arg_rep;
            }
        }

        return try pending.toOwnedSlice(self.parent.allocator);
    }

    fn dictionaryMethodFunctionRepForCall(
        self: *ProcBodyBuilder,
        callable_ty: checked.CheckedTypeId,
    ) Plan.TypeRepId {
        return self.repForType(callable_ty);
    }

    fn collectHiddenDescriptorParamsForFunction(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
    ) Allocator.Error!void {
        return try self.collectHiddenDescriptorParamsForFunctionParts(function, pending, true);
    }

    fn collectHiddenDescriptorParamsForFunctionParts(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
        include_return: bool,
    ) Allocator.Error!void {
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();

        const children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(function.rep)].children);
        for (children[function.args_start..][0..function.arg_count]) |child| {
            try self.collectHiddenDescriptorParamsForRep(.runtime, child.rep, pending, &seen_reps, &seen_descs);
        }
        if (include_return) {
            try self.collectHiddenDescriptorParamsForRep(.runtime, function.ret, pending, &seen_reps, &seen_descs);
        }
    }

    /// Collect, in pre-order, the hidden descriptor parameters `root`
    /// carries. `.runtime` stops at erased callables and follows only
    /// children that carry a hidden descriptor; `.all` follows every child
    /// except shared backing templates.
    fn collectHiddenDescriptorParamsForRep(
        self: *ProcBodyBuilder,
        comptime scope: enum { all, runtime },
        root: Plan.TypeRepId,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, void),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var reps: std.ArrayList(Plan.TypeRepId) = .empty;
        defer reps.deinit(allocator);
        try reps.append(allocator, root);
        while (reps.pop()) |rep_id| {
            const rep_entry = try seen_reps.getOrPut(rep_id);
            if (rep_entry.found_existing) continue;

            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            if (rep.descriptor) |desc| {
                const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
                const identity_desc = self.parent.plan.representations.items[@backingInt(identity_rep)].descriptor orelse desc;
                const desc_entry = try seen_descs.getOrPut(identity_desc);
                if (!desc_entry.found_existing) {
                    try pending.append(allocator, .{
                        .source_type = rep.source_type,
                        .rep = rep_id,
                        .desc = desc,
                    });
                }
            }

            if (scope == .runtime and rep.kind == .erased_callable) continue;
            const children = self.parent.plan.childSlice(rep.children);
            var index = children.len;
            while (index > 0) {
                index -= 1;
                const skip = switch (scope) {
                    .runtime => !self.parent.plan.childCarriesHiddenDescriptor(rep_id, children[index]),
                    .all => self.parent.plan.childIsSharedBackingTemplate(rep_id, children[index]),
                };
                if (skip) continue;
                try reps.append(allocator, children[index].rep);
            }
        }
    }

    fn collectAllHiddenDescriptorParamsForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
    ) Allocator.Error!void {
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        try self.collectHiddenDescriptorParamsForRep(.all, rep_id, pending, &seen_reps, &seen_descs);
    }

    /// Collect, in pre-order, the hidden descriptor arguments a dictionary
    /// call passes for the worker representation `root_worker` at the call
    /// representation `root_call`.
    fn collectDictionaryCallHiddenDescriptorArgs(
        self: *ProcBodyBuilder,
        root_worker: Plan.TypeRepId,
        root_call: Plan.TypeRepId,
        source_value_rep: Plan.TypeRepId,
        source_arg_index: ?u32,
        params: []const Plan.HiddenDescriptorParam,
        next_param: *usize,
        pending: *std.ArrayList(Plan.DirectCallHiddenDescriptorArg),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        seen_descriptor_reps: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var pairs: std.ArrayList([2]Plan.TypeRepId) = .empty;
        defer pairs.deinit(allocator);
        try pairs.append(allocator, .{ root_worker, root_call });
        while (pairs.pop()) |pair| {
            const worker_rep_id = pair[0];
            const call_rep_id = pair[1];
            const rep_entry = try seen_reps.getOrPut(worker_rep_id);
            if (rep_entry.found_existing) continue;

            const worker_rep = self.parent.plan.representations.items[@backingInt(worker_rep_id)];
            const call_rep = self.parent.plan.representations.items[@backingInt(call_rep_id)];

            if (worker_rep.descriptor) |worker_desc| {
                const worker_identity = self.repQuery().descriptorArgumentIdentityRep(worker_rep_id);
                const identity_entry = try seen_descriptor_reps.getOrPut(worker_identity);
                if (!identity_entry.found_existing) {
                    if (next_param.* >= params.len or params[next_param.*].desc != worker_desc) {
                        boxyLowerInvariant("boxy dictionary call hidden descriptor order disagreed with method descriptor params");
                    }
                    next_param.* += 1;
                    const desc_arg_rep_id = self.repQuery().descriptorArgumentIdentityRep(call_rep_id);
                    const desc_arg_rep = self.parent.plan.representations.items[@backingInt(desc_arg_rep_id)];
                    try pending.append(allocator, .{
                        .worker_desc = worker_desc,
                        .worker_rep = worker_rep_id,
                        .source_type = desc_arg_rep.source_type,
                        .rep = desc_arg_rep_id,
                        .source_arg_index = source_arg_index,
                        .source_value_rep = source_value_rep,
                    });
                }
            }

            if (worker_rep.kind == .erased_callable) continue;
            if (worker_rep.children.len == 0) continue;

            // Children align with the structure the call's value stands for.
            var wrapper_bindings: Plan.CallWrapperBindings = .{};
            defer wrapper_bindings.deinit(allocator);
            const structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(allocator, worker_rep_id, call_rep_id, &wrapper_bindings);
            const through_wrapper = structure_call_rep_id != call_rep_id;
            const structure_rep = self.parent.plan.representations.items[@backingInt(structure_call_rep_id)];
            const children_start = pairs.items.len;
            defer std.mem.reverse([2]Plan.TypeRepId, pairs.items[children_start..]);

            if (structure_rep.kind == .empty_tag_union) {
                for (self.parent.plan.childSlice(worker_rep.children)) |worker_child| {
                    if (!self.parent.plan.childCarriesHiddenDescriptor(worker_rep_id, worker_child)) continue;
                    if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
                    try pairs.append(allocator, .{ worker_child.rep, call_rep_id });
                }
                continue;
            }

            const worker_children = self.parent.plan.childSlice(worker_rep.children);
            const call_children = self.parent.plan.childSlice(structure_rep.children);
            for (worker_children) |worker_child| {
                if (!self.parent.plan.childCarriesHiddenDescriptor(worker_rep_id, worker_child)) continue;
                if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
                if (self.namedQuery().rowInstantiationTarget(worker_rep_id, structure_call_rep_id, worker_child)) |structure_row_target| {
                    const row_target = if (structure_row_target == structure_call_rep_id)
                        call_rep_id
                    else
                        Plan.structureChildCallRep(&wrapper_bindings, through_wrapper, structure_row_target);
                    try pairs.append(allocator, .{ worker_child.rep, row_target });
                    continue;
                }
                if (self.namedQuery().findMatchingChildByRole(call_children, worker_child)) |call_child| {
                    try pairs.append(allocator, .{ worker_child.rep, Plan.structureChildCallRep(&wrapper_bindings, through_wrapper, call_child.rep) });
                    continue;
                }
                if (self.repQuery().structuralWrapperBackingRep(call_rep_id)) |call_backing| {
                    const backing_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(call_backing)].children);
                    if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |call_child| {
                        try pairs.append(allocator, .{ worker_child.rep, call_child.rep });
                        continue;
                    }
                }
                if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(worker_rep_id, worker_child)) {
                    try pairs.append(allocator, .{ worker_child.rep, call_rep_id });
                    continue;
                }
                if (worker_child.role == .tag_ext and call_children.len == 0 and call_rep.descriptor != null) {
                    try pairs.append(allocator, .{ worker_child.rep, call_rep_id });
                    continue;
                }
                boxyLowerInvariant("boxy dictionary call hidden descriptor mapping saw mismatched child roles");
            }
        }
    }

    fn lowerDirectCallHiddenDescriptorArgs(
        self: *ProcBodyBuilder,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        source_args: []const LIR.LocalId,
        source_arg_reps: []const Plan.TypeRepId,
        call_arg_reps: []const Plan.TypeRepId,
    ) Allocator.Error![]DescriptorArgLocal {
        if (source_arg_reps.len != source_args.len or call_arg_reps.len != source_args.len) {
            boxyLowerInvariant("boxy direct call hidden descriptor source metadata length mismatch");
        }
        const lowered = try self.parent.allocator.alloc(DescriptorArgLocal, hidden_args.len);
        errdefer self.parent.allocator.free(lowered);

        for (hidden_args, lowered, 0..) |arg, *local, index| {
            if (arg.source_descriptor_index) |source_index| {
                if (source_index >= index) {
                    boxyLowerInvariant("boxy descriptor source did not precede its result use");
                }
                // The source entry owns the initializer; the result parameter
                // passes the same immutable descriptor without another read or
                // materialization.
                local.* = .{ .local = lowered[source_index].local, .from_source_value = true };
                continue;
            }
            // A bare type parameter receives the descriptor of the caller
            // type the call substitutes for it: the operand's own descriptor
            // when the plan names one, otherwise the caller frame's. A
            // compound worker parameter is the worker representation
            // instantiated with those descriptors; it is materialized below,
            // once they are bound.
            if (self.directCallHiddenDescriptorUsesCallShape(arg)) {
                if (try self.sourceValueDescriptorLocalForHiddenArg(arg, source_args, source_arg_reps, call_arg_reps)) |source_desc| {
                    local.* = source_desc;
                    continue;
                }
            }
            if (self.directCallHiddenDescriptorUsesCallShape(arg)) {
                const identity_rep = self.descriptorStorageRep(arg.rep);
                const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
                const desc = rep.descriptor orelse {
                    local.* = .{ .local = try self.addFrameLocal(.opaque_ptr) };
                    continue;
                };
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |desc_local| {
                    if (self.localIsReadOnlyDescriptorInput(desc_local)) {
                        if (self.parent.result.store.getLocal(desc_local).layout_idx != .opaque_ptr) {
                            boxyLowerInvariant("boxy read-only hidden descriptor local was not opaque_ptr");
                        }
                        local.* = .{ .local = desc_local };
                        continue;
                    }
                }
                if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                    const desc_local = self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep) orelse
                        boxyLowerInvariant("bound boxy hidden descriptor arg had no matching local");
                    if (self.parent.result.store.getLocal(desc_local).layout_idx != .opaque_ptr) {
                        boxyLowerInvariant("boxy hidden descriptor local was not opaque_ptr");
                    }
                    local.* = .{ .local = desc_local };
                    continue;
                }
            }
            local.* = .{ .local = try self.addFrameLocal(.opaque_ptr) };
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);
        try self.bindDirectCallHiddenDescriptorLocals(hidden_args, lowered, false);

        for (hidden_args, lowered) |arg, *local| {
            if (local.from_source_value) continue;
            if (self.localIsReadOnlyDescriptorInput(local.local)) continue;

            if (local.materialize == null and self.directCallHiddenDescriptorUsesCallShape(arg)) {
                const identity_call_rep = self.descriptorStorageRep(arg.rep);
                const call_rep = self.parent.plan.representations.items[@backingInt(identity_call_rep)];
                if (call_rep.descriptor) |desc| {
                    if (self.descriptorSnapshotBoundLocalForRep(snapshot, desc, identity_call_rep)) |bound_local| {
                        if (bound_local != local.local) {
                            local.materialize = .{ .local = bound_local };
                        }
                        continue;
                    }
                }
                const materialization = try self.descriptorMaterializationForKnownRepExcludingLocal(
                    identity_call_rep,
                    local.local,
                );
                local.materialize = materialization.desc;
                local.captures = materialization.captures;
                continue;
            }

            if (local.materialize == null and !self.directCallHiddenDescriptorUsesCallShape(arg)) {
                const identity_worker_rep = self.descriptorStorageRep(arg.worker_rep);
                const materialization = try self.descriptorMaterializationForKnownRepExcludingLocal(
                    identity_worker_rep,
                    local.local,
                );
                local.materialize = materialization.desc;
                local.captures = materialization.captures;
                continue;
            }

            if (local.materialize == null) {
                const identity_rep = self.descriptorStorageRep(arg.rep);
                local.materialize = try self.parent.staticDescRefForRep(identity_rep);
            }
        }

        return lowered;
    }

    /// A planned argument source reads the original operand's own
    /// descriptor: the whole descriptor when the operand is the hidden
    /// representation, or the nested descriptor at the representation path
    /// from the operand to it.
    fn sourceValueDescriptorLocalForHiddenArg(
        self: *ProcBodyBuilder,
        hidden_arg: Plan.DirectCallHiddenDescriptorArg,
        source_args: []const LIR.LocalId,
        source_arg_reps: []const Plan.TypeRepId,
        call_arg_reps: []const Plan.TypeRepId,
    ) Allocator.Error!?DescriptorArgLocal {
        const source_arg_index = hidden_arg.source_arg_index orelse return null;
        const index: usize = @intCast(source_arg_index);
        if (index >= source_args.len or index >= source_arg_reps.len) {
            boxyLowerInvariant("boxy direct call hidden descriptor source argument index exceeded call arity");
        }
        const source = source_args[index];
        const source_rep = source_arg_reps[index];
        // The operand and the call's instantiated parameter are one checked
        // type, so either names the whole operand.
        const hidden_identity = self.descriptorStorageRep(hidden_arg.rep);
        const whole_operand = hidden_arg.whole_operand or
            self.descriptorStorageRep(source_rep) == hidden_identity or
            self.descriptorStorageRep(call_arg_reps[index]) == hidden_identity;
        if (!whole_operand) {
            const operand_position = hidden_arg.source_operand_rep orelse return null;
            return try self.sourceNestedDescriptorLocalForHiddenArg(source, source_rep, self.descriptorStorageRep(operand_position));
        }
        if (self.parent.result.store.getLocal(source).boxy_desc) |existing| {
            if (existing.localOrNull()) |existing_local| {
                return .{ .local = existing_local, .from_source_value = true };
            }
        }
        const materialization = try self.descriptorMaterializationForSourceStorageLocalRep(source, source_rep);
        return .{
            .local = try self.addFrameLocal(.opaque_ptr),
            .materialize = materialization.desc,
            .captures = materialization.captures,
            .from_source_value = true,
        };
    }

    fn sourceNestedDescriptorLocalForHiddenArg(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        hidden_rep: Plan.TypeRepId,
    ) Allocator.Error!?DescriptorArgLocal {
        const read_path = try self.descriptorReadPathForNestedRep(source_rep, hidden_rep) orelse return null;
        const source_desc = if (self.parent.result.store.getLocal(source).boxy_desc) |existing|
            DescriptorMaterialization{ .desc = existing }
        else
            try self.descriptorMaterializationForSourceRep(source_rep);
        return .{
            .local = try self.addFrameLocal(.opaque_ptr),
            .materialize = source_desc.desc,
            .read_path = read_path,
            .captures = source_desc.captures,
            .from_source_value = true,
        };
    }

    fn descriptorReadPathForNestedRep(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        nested_rep: Plan.TypeRepId,
    ) Allocator.Error!?Plan.Span {
        var read_path = std.ArrayList(DescriptorReadStep).empty;
        defer read_path.deinit(self.parent.allocator);
        var active = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer active.deinit();

        if (!try self.findDescriptorReadPath(
            source_rep,
            self.descriptorStorageRep(nested_rep),
            &read_path,
            &active,
        )) return null;
        if (read_path.items.len == 0) return null;
        return try self.parent.addDescriptorReadPath(read_path.items);
    }

    /// A representation whose descriptor read steps are being searched, in
    /// child order.
    const ReadPathFrame = struct {
        rep_id: Plan.TypeRepId,
        /// Whether a step toward this frame's current child is on the path.
        stepped: bool = false,
        kind: union(enum) {
            tag: struct {
                tag_rep_id: Plan.TypeRepId,
                /// The committed tag layout; a zero-sized union has none.
                tag_layout: ?layout.Layout,
                variant: usize = 0,
                payload: usize = 0,
                ext_index: usize = 0,
            },
            box: struct { visited: bool = false },
            nested: struct { slots: []ProcedureBuilder.NestedDescriptorSlot, position: usize = 0 },
        },
    };

    /// Find the first read path, in child order, from `root` to
    /// `target_rep_id`'s descriptor. `read_path` holds the steps taken;
    /// `active` holds the representations on the path, so a recursive type
    /// is not re-entered.
    fn findDescriptorReadPath(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        target_rep_id: Plan.TypeRepId,
        read_path: *std.ArrayList(DescriptorReadStep),
        active: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        var frames: std.ArrayList(ReadPathFrame) = .empty;
        defer {
            for (frames.items) |frame| {
                _ = active.remove(frame.rep_id);
                switch (frame.kind) {
                    .tag, .box => {},
                    .nested => |nested| allocator.free(nested.slots),
                }
            }
            frames.deinit(allocator);
        }
        if (try self.enterReadPath(root, target_rep_id, &frames, active)) |found| return found;
        while (frames.items.len != 0) {
            const top = &frames.items[frames.items.len - 1];
            if (top.stepped) {
                read_path.items.len -= 1;
                top.stepped = false;
            }
            const next = try self.nextReadPathStep(top) orelse {
                var done = frames.pop().?;
                _ = active.remove(done.rep_id);
                switch (done.kind) {
                    .tag, .box => {},
                    .nested => |*nested| allocator.free(nested.slots),
                }
                continue;
            };
            try read_path.append(allocator, next.step);
            top.stepped = true;
            if (try self.enterReadPath(next.rep, target_rep_id, &frames, active)) |found| {
                if (found) return true;
            }
        }
        return false;
    }

    /// Whether `rep_id` is the target (true) or already on the path (false);
    /// otherwise null, with its frame pushed.
    fn enterReadPath(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        target_rep_id: Plan.TypeRepId,
        frames: *std.ArrayList(ReadPathFrame),
        active: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!?bool {
        const allocator = self.parent.allocator;
        const current_rep_identity = self.descriptorStorageRep(rep_id);
        if (current_rep_identity == target_rep_id) return true;
        // An open record's descriptor describes the complete record its value
        // holds, whose nested positions its row's fields do not determine.
        if (self.repIsOpenRecord(current_rep_identity)) return false;

        const active_entry = try active.getOrPut(current_rep_identity);
        if (active_entry.found_existing) return false;
        errdefer _ = active.remove(current_rep_identity);

        if (self.tagVariantRepForBoundary(current_rep_identity)) |tag_rep_id| {
            const tag_rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
            const variants = self.parent.plan.tagVariantSlice(tag_rep.tag_variants);
            const descriptor_layout = self.parent.descriptorPayloadLayoutForRep(current_rep_identity);
            const descriptor_layout_value = self.parent.result.layouts.getLayout(descriptor_layout);
            const tag_layout = switch (descriptor_layout_value.tag) {
                .tag_union => descriptor_layout_value,
                .box => self.parent.result.layouts.getLayout(descriptor_layout_value.getIdx()),
                .zst => null,
                .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .ptr => boxyLowerInvariant("boxy descriptor read_path tag had a non-tag payload layout"),
            };
            if (tag_layout) |layout_value| {
                if (layout_value.tag != .tag_union) {
                    boxyLowerInvariant("boxy descriptor read_path tag box had a non-tag payload");
                }
                const tag_info = self.parent.result.layouts.getTagUnionInfo(layout_value);
                if (tag_info.variants.len < variants.len) {
                    boxyLowerInvariant("boxy descriptor read_path tag layout had too few variants");
                }
            } else if (variants.len != 1) {
                boxyLowerInvariant("boxy zero-sized tag descriptor read_path had multiple variants");
            }
            try frames.append(allocator, .{ .rep_id = current_rep_identity, .kind = .{ .tag = .{ .tag_rep_id = tag_rep_id, .tag_layout = tag_layout } } });
            return null;
        }

        const current_rep = self.parent.plan.representations.items[@backingInt(current_rep_identity)];
        if (current_rep.kind == .box and current_rep.declared_fields.len == 0) {
            try frames.append(allocator, .{ .rep_id = current_rep_identity, .kind = .{ .box = .{} } });
            return null;
        }

        var slots = std.ArrayList(ProcedureBuilder.NestedDescriptorSlot).empty;
        defer slots.deinit(allocator);
        try self.parent.appendNestedDescriptorSlots(
            current_rep_identity,
            self.parent.descriptorPayloadLayoutForRep(current_rep_identity),
            &slots,
        );
        const owned_slots = try slots.toOwnedSlice(allocator);
        errdefer allocator.free(owned_slots);
        try frames.append(allocator, .{ .rep_id = current_rep_identity, .kind = .{ .nested = .{ .slots = owned_slots } } });
        return null;
    }

    /// The next step a read path search tries from `frame`, or null once
    /// every step was tried.
    fn nextReadPathStep(self: *ProcBodyBuilder, frame: *ReadPathFrame) Allocator.Error!?struct { step: DescriptorReadStep, rep: Plan.TypeRepId } {
        switch (frame.kind) {
            .tag => |*tag| {
                const tag_rep = self.parent.plan.representations.items[@backingInt(tag.tag_rep_id)];
                const variants = self.parent.plan.tagVariantSlice(tag_rep.tag_variants);
                const variant_count: usize = if (tag.tag_layout == null) 1 else variants.len;
                while (tag.variant < variant_count) {
                    const variant = variants[tag.variant];
                    const variant_payload_layout: layout.Idx = if (tag.tag_layout) |layout_value|
                        self.parent.result.layouts.getTagUnionInfo(layout_value).variants.get(tag.variant).payload_layout
                    else
                        .zst;
                    const payloads = self.parent.plan.childSlice(variant.payloads);
                    while (tag.payload < payloads.len) {
                        const payload_index = tag.payload;
                        tag.payload += 1;
                        const field_layout = self.parent.tagVariantPayloadFieldLayout(
                            variant_payload_layout,
                            payload_index,
                            payloads.len,
                        );
                        const payload_rep = self.parent.tagPayloadStorageDescRepForLayout(
                            payloads[payload_index].rep,
                            field_layout,
                            true,
                        ) orelse continue;
                        return .{ .step = .{ .tag_payload = .{
                            .tag_name = try self.lirTagNameForVariant(variant),
                            .payload_index = @intCast(payload_index),
                        } }, .rep = payload_rep };
                    }
                    tag.variant += 1;
                    tag.payload = 0;
                }
                const children = self.parent.plan.childSlice(tag_rep.children);
                while (tag.ext_index < children.len) {
                    const child = children[tag.ext_index];
                    tag.ext_index += 1;
                    if (child.role != .tag_ext) continue;
                    const ext_identity = self.descriptorStorageRep(child.rep);
                    const ext_rep = self.parent.plan.representations.items[@backingInt(ext_identity)];
                    if (ext_identity == tag.tag_rep_id or ext_rep.kind == .empty_tag_union) continue;
                    return .{ .step = .tag_ext, .rep = child.rep };
                }
                return null;
            },
            .box => |*box| {
                if (box.visited) return null;
                box.visited = true;
                // A Box payload read is its own descriptor operation: Box
                // descriptors are box-self or payload-direct.
                const payload = self.parent.repQuery().requiredSingleChild(frame.rep_id, .box_payload);
                return .{ .step = .{ .box_payload = self.workerRuntimeLayoutForRep(frame.rep_id).layoutIdx() }, .rep = payload.rep };
            },
            .nested => |*nested| {
                if (nested.position == nested.slots.len) return null;
                const position = nested.position;
                nested.position += 1;
                return .{ .step = .{ .nested = @intCast(position) }, .rep = self.parent.nestedDescriptorSlotDescRep(nested.slots[position]) };
            },
        }
    }

    fn immediateNestedDescriptorIndexForRep(
        self: *ProcBodyBuilder,
        parent_rep_id: Plan.TypeRepId,
        nested_rep_id: Plan.TypeRepId,
    ) Allocator.Error!?u32 {
        const target_rep = self.descriptorStorageRep(nested_rep_id);
        if (self.repIsOpenRecord(parent_rep_id)) return null;
        var slots = std.ArrayList(ProcedureBuilder.NestedDescriptorSlot).empty;
        defer slots.deinit(self.parent.allocator);
        try self.parent.appendNestedDescriptorSlots(
            parent_rep_id,
            self.parent.descriptorPayloadLayoutForRep(parent_rep_id),
            &slots,
        );
        for (slots.items, 0..) |slot, position| {
            if (self.descriptorStorageRep(self.parent.nestedDescriptorSlotDescRep(slot)) == target_rep) return @intCast(position);
        }
        return null;
    }

    fn directCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
    ) Allocator.Error!ResultDescriptorSource {
        const identity_rep = self.parent.descriptorIdentityRep(result_rep);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor == null) return .{};
        if (rep.descriptor) |desc| {
            if (hidden_args.len != hidden_locals.len) {
                boxyLowerInvariant("boxy direct call result descriptor saw mismatched hidden descriptor locals");
            }
            for (hidden_args, hidden_locals) |arg, hidden| {
                if (arg.worker_desc == desc) return .{ .desc = .{ .local = hidden.local } };
            }
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        try self.bindDirectCallHiddenDescriptorLocals(hidden_args, hidden_locals, true);
        return try self.adapterDescriptorFromMaterialization(try self.descriptorMaterializationForSourceRep(identity_rep));
    }

    fn dictionaryCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
    ) Allocator.Error!ResultDescriptorSource {
        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        try self.bindDirectCallHiddenDescriptorLocals(hidden_args, hidden_locals, true);
        return try self.exactCallResultDescriptorRef(result_rep);
    }

    fn descriptorSnapshotBoundLocalForRep(
        self: *const ProcBodyBuilder,
        snapshot: DescriptorBindingsSnapshot,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const desc_index = @backingInt(desc);
        if (desc_index < snapshot.bound.len and
            snapshot.bound[desc_index] and
            desc_index < snapshot.local_reps.len and
            snapshot.local_reps[desc_index] == identity_rep)
        {
            if (desc_index >= snapshot.locals.len) {
                boxyLowerInvariant("boxy descriptor snapshot bound state had no local slot");
            }
            return snapshot.locals[desc_index] orelse
                boxyLowerInvariant("boxy descriptor snapshot marked a missing local as bound");
        }
        for (snapshot.rep_bindings) |binding| {
            if (binding.desc == desc and binding.rep == identity_rep and binding.bound) return binding.local;
        }
        return null;
    }

    fn exactCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        return try self.adapterDescriptorFromMaterialization(try self.descriptorMaterializationForExactResultRep(result_rep));
    }

    fn descriptorMaterializationForExactResultRep(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.descriptorStorageRep(result_rep);
        return if (self.repIsBareDynamic(identity_rep))
            try self.descriptorMaterializationForSourceRep(identity_rep)
        else
            try self.descriptorMaterializationForExactRep(result_rep);
    }

    fn erasedCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        out_desc: ?LIR.LocalId,
    ) Allocator.Error!ResultDescriptorSource {
        // An open record result is described by the record the callee
        // returns, which the caller's types do not determine.
        if (self.repIsOpenRecord(result_rep)) return .{};
        if (out_desc) |local| {
            if (self.descriptorTemplateForLocal(local)) |template| {
                return try self.adapterDescriptorFromMaterialization(template);
            }
            const exact = try self.exactCallResultDescriptorRef(result_rep);
            if (exact.desc) |desc| {
                if (desc.localOrNull() == local) {
                    boxyLowerInvariant("erased-call result descriptor aliased its output without an immutable template");
                }
            }
            return exact;
        }
        if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
            return .{ .desc = target_desc };
        }
        return try self.exactCallResultDescriptorRef(result_rep);
    }

    fn erasedCallResultCanUseTarget(
        self: *const ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        result_rep: Plan.TypeRepId,
    ) bool {
        const target_identity = self.descriptorStorageRep(target_rep);
        const result_identity = self.descriptorStorageRep(result_rep);
        if (target_identity != result_identity) return false;
        if (target_rep == result_rep) return true;
        return self.repIsFullyConcrete(target_identity);
    }

    /// Whether a call can deliver its result and that result's descriptor
    /// straight into `target`. A bare dynamic value is described only by the
    /// descriptor it arrives with, so a target whose descriptor local this
    /// frame may write takes the callee's in place of its own.
    fn callResultAdoptsCalleeDescriptor(
        self: *const ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
    ) bool {
        return self.repIsBareDynamic(target_rep) and self.callResultOutputDescriptorLocal(target) != null;
    }

    fn callResultOutputDescriptorLocal(
        self: *const ProcBodyBuilder,
        target: LIR.LocalId,
    ) ?LIR.LocalId {
        const desc = self.parent.result.store.getLocal(target).boxy_desc orelse return null;
        const local = desc.localOrNull() orelse return null;
        return if (self.localIsReadOnlyDescriptorInput(local)) null else local;
    }

    fn resultDescriptorForCallTarget(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        info: ResultDescriptorSource,
    ) ResultDescriptorSource {
        const desc = info.desc orelse return info;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return info;
        if (std.meta.eql(desc, target_desc)) return info;

        var result = info;
        result.desc = target_desc;
        const target_desc_local = target_desc.localOrNull() orelse {
            result.preserves_source_desc = false;
            return result;
        };
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, target_desc_local) != null) {
            result.materialize = null;
            result.preserves_source_desc = false;
            return result;
        }
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) {
            result.materialize = null;
            result.preserves_source_desc = false;
            return result;
        }
        if (info.materialize) |materialize| {
            const materialized_desc = materialize.materialize orelse
                boxyLowerInvariant("boxy call result descriptor materialization had no descriptor");
            const materialized_ref = LIR.BoxyDescRef{ .local = materialize.local };
            result.materialize = .{
                .local = target_desc_local,
                .materialize = if (std.meta.eql(desc, materialized_ref)) materialized_desc else desc,
                .read_path = if (std.meta.eql(desc, materialized_ref)) materialize.read_path else .{},
                .nested_index = if (std.meta.eql(desc, materialized_ref)) materialize.nested_index else null,
                .tag_ext = std.meta.eql(desc, materialized_ref) and materialize.tag_ext,
                .tag_residual_for = if (std.meta.eql(desc, materialized_ref)) materialize.tag_residual_for else null,
                .captures = if (std.meta.eql(desc, materialized_ref)) materialize.captures else LIR.LocalSpan.empty(),
            };
        } else {
            result.materialize = .{
                .local = target_desc_local,
                .materialize = desc,
            };
        }
        return result;
    }

    fn descriptorForConstructedTarget(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        constructed_desc: LIR.BoxyDescRef,
    ) Allocator.Error!ResultDescriptorSource {
        const existing = self.parent.result.store.getLocal(target).boxy_desc orelse {
            self.parent.result.store.setLocalBoxyDesc(target, constructed_desc);
            return .{ .desc = constructed_desc };
        };
        if (std.meta.eql(existing, constructed_desc)) {
            return .{ .desc = existing };
        }
        if (existing.localOrNull()) |existing_local| {
            if (!self.localIsReadOnlyDescriptorInput(existing_local)) {
                try self.recordDescriptorLocalTemplate(existing_local, .{ .desc = constructed_desc });
                return .{
                    .desc = existing,
                    .materialize = .{
                        .local = existing_local,
                        .materialize = constructed_desc,
                    },
                };
            }
        }
        return .{ .desc = existing };
    }

    fn descriptorForConstructedTargetMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        materialization: DescriptorMaterialization,
    ) Allocator.Error!ResultDescriptorSource {
        if (materialization.captures.len == 0) {
            return try self.descriptorForConstructedTarget(target, materialization.desc);
        }

        if (self.parent.result.store.getLocal(target).boxy_desc) |existing| {
            if (existing.localOrNull()) |existing_local| {
                if (!self.localIsReadOnlyDescriptorInput(existing_local)) {
                    try self.recordDescriptorLocalTemplate(existing_local, materialization);
                    return .{
                        .desc = existing,
                        .materialize = materialization.initializer(existing_local),
                    };
                }
            }
            return .{ .desc = existing };
        }

        const desc_local = try self.addFrameLocal(.opaque_ptr);
        const desc_ref = LIR.BoxyDescRef{ .local = desc_local };
        self.parent.result.store.setLocalBoxyDesc(target, desc_ref);
        try self.recordDescriptorLocalTemplate(desc_local, materialization);
        return .{
            .desc = desc_ref,
            .materialize = materialization.initializer(desc_local),
        };
    }

    fn stableDescriptorForConstructedValue(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.descriptor == null and !rep.contains_dynamic and
            self.parent.result.store.getLocal(target).boxy_desc == null) return .{};

        const materialization = try self.descriptorMaterializationForConstructedRep(rep_id);
        return try self.descriptorForConstructedTargetMaterialization(target, materialization);
    }

    fn constructedListDescriptorForElementLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        elem_desc_local: LIR.LocalId,
    ) Allocator.Error!ResultDescriptorSource {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor == null and
            self.parent.result.store.getLocal(target).boxy_desc == null) return .{};

        const elem_desc_ref = LIR.BoxyDescRef{ .local = elem_desc_local };
        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.append(self.parent.allocator, elem_desc_ref);

        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        const payload_layout = self.parent.result.store.getLocal(target).layout_idx;
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (!layoutIsList(layout_value)) {
            boxyLowerInvariant("constructed list descriptor target did not have list storage");
        }
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value) or rep.contains_dynamic,
            .shape = self.parent.descriptorShapeForRep(identity_rep),
            .nested_descs = .{ .start = nested_start, .len = 1 },
            .tag_variants = try self.parent.staticTagVariantsForRep(identity_rep, payload_layout),
            .tag_ext_desc = try self.parent.staticTagExtDescForRep(identity_rep),
            .field_names = try self.parent.staticFieldNamesForRep(identity_rep),
            .inspect_opaque = self.parent.repInspectsOpaque(identity_rep),
            .debug_checked_type = rep.source_type.ty,
        });
        const captures = [_]LIR.LocalId{elem_desc_local};
        return try self.descriptorForConstructedTargetMaterialization(target, .{
            .desc = .{ .static = desc_id },
            .captures = try self.parent.result.store.addLocalSpan(&captures),
        });
    }

    fn descriptorMaterializationForConstructedRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor) |desc| {
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| {
                if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                    return .{ .desc = .{ .local = local } };
                }
            }
            if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                return try self.descriptorMaterializationForKnownRep(identity_rep);
            }
        }
        return try self.descriptorMaterializationForKnownRep(identity_rep);
    }

    fn storageDescriptorForRepIfNeeded(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(rep_id) orelse return .{};
        return try self.adapterDescriptorFromMaterialization(try self.descriptorMaterializationForSourceRep(desc_rep));
    }

    fn descriptorRefForPayloadStorageTarget(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        if (self.parent.result.store.getLocal(target).boxy_desc) |desc| {
            return .{ .desc = desc };
        }
        return try self.storageDescriptorForRepIfNeeded(rep_id);
    }

    fn assignWorkerValueToTagPayloadStorage(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (target_layout == source_layout) return try self.assignLocal(target, source, next);

        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_is_box = source_layout_value.tag == .box or source_layout_value.tag == .box_of_zst or source_layout_value.tag == .erased_box;
        const target_is_box = target_layout_value.tag == .box or target_layout_value.tag == .box_of_zst or target_layout_value.tag == .erased_box;

        if (source_is_box and !target_is_box) {
            const source_desc = try self.descriptorRefForSourceLocalRep(source, rep_id);
            const target_desc_info = try self.descriptorRefForPayloadStorageTarget(target, rep_id);
            const target_desc = target_desc_info.desc orelse
                boxyLowerInvariant("boxy tag payload storage unbox had no target descriptor");
            self.parent.result.store.setLocalBoxyDesc(target, target_desc);
            const unbox = try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
                .target = target,
                .source = source,
                .source_desc = source_desc,
                .target_desc = target_desc,
                .target_layout = target_layout,
                .source_mode = .borrow,
                .next = next,
            } }, self.glueOrigin());
            return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, unbox);
        }

        if (!source_is_box and target_is_box) {
            const source_desc = try self.descriptorRefForSourceStorageLocalRep(source, rep_id);
            const target_desc_info = try self.descriptorRefForPayloadStorageTarget(target, rep_id);
            const target_desc = target_desc_info.desc orelse
                boxyLowerInvariant("boxy tag payload storage box had no target descriptor");
            self.parent.result.store.setLocalBoxyDesc(target, target_desc);
            const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = target,
                .payload = source,
                .payload_layout = source_layout,
                .source_desc = if (std.meta.eql(source_desc, target_desc)) null else source_desc,
                .payload_desc = target_desc,
                .payload_mode = .borrow,
                .next = next,
            } }, self.glueOrigin());
            return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, box);
        }

        boxyLowerInvariant("boxy tag payload storage conversion saw incompatible non-box layouts");
    }

    fn directCallHiddenDescriptorUsesCallShape(
        self: *ProcBodyBuilder,
        arg: Plan.DirectCallHiddenDescriptorArg,
    ) bool {
        const identity_worker_rep = self.descriptorStorageRep(arg.worker_rep);
        const worker_rep = self.parent.plan.representations.items[@backingInt(identity_worker_rep)];
        return (worker_rep.kind == .dynamic and worker_rep.children.len == 0 and worker_rep.tag_variants.len == 0) or
            self.repIsOpenRecord(identity_worker_rep);
    }

    fn bindDirectCallHiddenDescriptorLocals(
        self: *ProcBodyBuilder,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
        bind_worker_reps: bool,
    ) Allocator.Error!void {
        if (hidden_args.len != hidden_locals.len) {
            boxyLowerInvariant("boxy direct call hidden descriptor local count disagreed with hidden descriptor plan");
        }

        try self.ensureDescriptorLocals();
        var seen = collections.DenseMap(Plan.DescriptorRequirementId, LIR.LocalId).init(self.parent.allocator);
        defer seen.deinit();

        for (hidden_args, hidden_locals) |arg, hidden| {
            const entry = try seen.getOrPut(arg.worker_desc);
            if (entry.found_existing) {
                if (entry.value_ptr.* != hidden.local) {
                    boxyLowerInvariant("boxy direct call mapped one worker descriptor to two hidden locals");
                }
            } else {
                entry.value_ptr.* = hidden.local;
            }

            const local_rep = self.directCallHiddenDescriptorLocalRep(arg, hidden);
            try self.bindDescriptorRequirementLocalForRep(arg.worker_desc, local_rep, hidden.local, false);
            if (self.repOwnsDescriptor(local_rep, arg.worker_desc)) {
                try self.bindDescriptorIdentityLocalForRep(local_rep, hidden.local, false);
            }
            if (self.directCallHiddenDescriptorUsesCallShape(arg) and self.descriptorStorageRep(arg.worker_rep) != self.descriptorStorageRep(local_rep)) {
                if (!bind_worker_reps and try self.repQuery().repSubtreeContainsRep(local_rep, arg.worker_rep)) continue;
                try self.bindDescriptorRequirementLocalForRep(arg.worker_desc, arg.worker_rep, hidden.local, false);
                if (self.repOwnsDescriptor(arg.worker_rep, arg.worker_desc)) {
                    try self.bindDescriptorIdentityLocalForRep(arg.worker_rep, hidden.local, false);
                }
            }
        }
    }

    fn directCallHiddenDescriptorLocalRep(
        self: *ProcBodyBuilder,
        arg: Plan.DirectCallHiddenDescriptorArg,
        hidden: DescriptorArgLocal,
    ) Plan.TypeRepId {
        if (hidden.from_source_value or self.directCallHiddenDescriptorUsesCallShape(arg)) return arg.rep;
        return arg.worker_rep;
    }

    fn lowerDirectCallHiddenDictionaryArgs(
        self: *ProcBodyBuilder,
        hidden_args: []const Plan.DirectCallHiddenDictionaryArg,
    ) Allocator.Error![]DictionaryArgLocal {
        const lowered = try self.parent.allocator.alloc(DictionaryArgLocal, hidden_args.len);
        errdefer self.parent.allocator.free(lowered);

        for (hidden_args, lowered) |arg, *local| {
            const dict_ref = try self.dictionaryRefForPlannedSource(arg);
            local.* = switch (dict_ref.dict) {
                .local => |dict_local| blk: {
                    if (self.parent.result.store.getLocal(dict_local).layout_idx != .opaque_ptr) {
                        boxyLowerInvariant("boxy hidden dictionary local was not opaque_ptr");
                    }
                    break :blk .{ .local = dict_local };
                },
                .static => blk: {
                    const materialized = (try self.reserveDictionarySlotForSpan(arg.worker_dictionaries)) orelse try self.addFrameLocal(.opaque_ptr);
                    break :blk .{
                        .local = materialized,
                        .materialize = dict_ref.dict,
                        .captures = dict_ref.captures,
                    };
                },
                .runtime => boxyLowerInvariant("a runtime dictionary reference reached boxy lowering"),
            };
        }

        return lowered;
    }

    fn descriptorRefForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        if (try self.repDependsOnNominalFormals(identity_rep)) {
            const materialization = try self.descriptorMaterializationForKnownRep(identity_rep);
            if (materialization.captures.len != 0) {
                boxyLowerInvariant("boxy descriptor reading bound nominal formals needed captured descriptors");
            }
            return materialization.desc;
        }
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor) |desc| {
            if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| return .{ .local = local };
                if (try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep)) {
                    boxyLowerInvariant("boxy runtime-bound descriptor requirement had no matching local");
                }
            }
        }
        return try self.parent.staticDescRefForRep(identity_rep);
    }

    fn descriptorRefForSourceLocalRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        // A descriptor attached to the source local describes the actual
        // value and takes precedence over anything rep-derived—including
        // for representations that carry no descriptor requirement of their
        // own (fully known at this site).
        if (self.localEnvironmentDescriptorForRep(source, rep_id)) |local| return .{ .local = local };
        if (self.parent.result.store.getLocal(source).boxy_desc) |source_desc| return source_desc;
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        return try self.descriptorRefForKnownRep(identity_rep);
    }

    fn staticDescriptorPayloadLayout(
        self: *const ProcBodyBuilder,
        desc: LIR.BoxyDescRef,
    ) ?layout.Idx {
        return switch (desc) {
            .static => |desc_id| blk: {
                const index = @backingInt(desc_id);
                if (index >= self.parent.result.boxy_type_descs.items.len) {
                    boxyLowerInvariant("static boxy descriptor id exceeded descriptor table");
                }
                break :blk self.parent.result.boxy_type_descs.items[index].payload_layout;
            },
            .local,
            .runtime,
            .dict_method_arg,
            .dict_method_hidden,
            => null,
        };
    }

    fn descriptorRefForSourceStorageLocalRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (self.parent.result.store.getLocal(source).boxy_desc) |existing| {
            if (self.staticDescriptorPayloadLayout(existing)) |payload_layout| {
                if (payload_layout == source_layout) return existing;
            } else {
                return existing;
            }
        }
        if (self.localEnvironmentDescriptorForRep(source, rep_id)) |local| return .{ .local = local };

        const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(rep_id, source_layout, true) orelse
            boxyLowerInvariant("boxy tag payload storage source descriptor did not match source layout");
        const source_desc = try self.descriptorRefForKnownRep(source_desc_rep);
        self.parent.result.store.setLocalBoxyDesc(source, source_desc);
        return source_desc;
    }

    fn descriptorMaterializationForSourceStorageLocalRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (self.parent.result.store.getLocal(source).boxy_desc) |existing| {
            if (self.staticDescriptorPayloadLayout(existing)) |payload_layout| {
                if (payload_layout == source_layout) return .{ .desc = existing };
            } else {
                return .{ .desc = existing };
            }
        }
        if (self.localEnvironmentDescriptorForRep(source, rep_id)) |local| return .{ .desc = .{ .local = local } };

        const known = try self.descriptorMaterializationForKnownRep(rep_id);
        if (self.staticDescriptorPayloadLayout(known.desc)) |payload_layout| {
            if (payload_layout == source_layout) return known;
        }

        const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(rep_id, source_layout, true) orelse
            boxyLowerInvariant("boxy source descriptor materialization did not match source storage layout");
        return try self.descriptorMaterializationForKnownRep(source_desc_rep);
    }

    fn descriptorRefForLocalOrKnownRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        return self.parent.result.store.getLocal(source).boxy_desc orelse
            try self.descriptorRefForKnownRep(identity_rep);
    }

    /// Whether a constructed field local could carry a runtime descriptor. A
    /// field storage layout that is itself an aggregate (struct, box, list, tag
    /// union) can receive a descriptor when its value crosses a representation
    /// boundary, so an aggregate built from such fields needs a descriptor to
    /// release them.
    fn fieldLocalMayCarryDescriptor(self: *const ProcBodyBuilder, field_local: LIR.LocalId) bool {
        return self.parent.layoutNeedsNestedBoxyDesc(self.parent.result.store.getLocal(field_local).layout_idx);
    }

    fn aggregateFieldsMayCarryDescriptor(
        self: *const ProcBodyBuilder,
        fields: []const AggregateDescriptorField,
    ) bool {
        for (fields) |field| {
            if (self.fieldLocalMayCarryDescriptor(field.local)) return true;
        }
        return false;
    }

    fn constructedAggregateDescriptorForFields(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        fields: []const AggregateDescriptorField,
    ) Allocator.Error!ConstructedAggregateDescriptor {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor == null) {
            // A struct field can carry a runtime descriptor even when the
            // struct's own representation is concrete: a value converted across
            // a representation boundary threads its descriptor onto the field
            // locals, and ARC treats any descriptor-bearing local as
            // refcounted. Reconstructing such a struct concretely would leave
            // the aggregate with no descriptor, so ARC would drop it through
            // its concrete layout plan—which is a noop for the box-free
            // layout—and lose the release. Offer the representation's static
            // descriptor as a candidate the aggregate construction records; ARC
            // adopts it only when a field actually carries a descriptor, so
            // aggregates whose fields stay concrete keep the concrete plan.
            if (!self.aggregateFieldsMayCarryDescriptor(fields) and
                self.parent.result.store.getLocal(target).boxy_desc == null)
            {
                return .{};
            }
            return try self.constructedConcreteAggregateDescriptorForFields(target, identity_rep, fields);
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        var field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        errdefer field_initializers.deinit(self.parent.allocator);
        var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
        defer overrides.deinit(self.parent.allocator);

        for (fields) |field| {
            const field_layout = self.parent.result.store.getLocal(field.local).layout_idx;
            const target_desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(field.target_rep) orelse continue;
            // The field local holds the adapted value, stored as the target
            // representation lays it out. A bare type parameter has no storage
            // shape of its own, so there the value keeps the descriptor of the
            // payload that was boxed into it.
            const storage_rep = self.constructedFieldStorageRep(field);
            const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(storage_rep, field_layout, true) orelse
                boxyLowerInvariant("constructed aggregate source field had no storage descriptor representation");
            const desc_local = try self.prepareConstructedFieldDescriptorLocal(field.local, source_desc_rep, &field_initializers);
            try self.bindDescriptorIdentityLocalForRep(target_desc_rep, desc_local, false);
            const identity_desc_rep = self.parent.descriptorIdentityRep(target_desc_rep);
            var found = false;
            for (overrides.items) |override| {
                if (override.rep != identity_desc_rep) continue;
                found = true;
                break;
            }
            if (!found) {
                try overrides.append(self.parent.allocator, .{ .rep = identity_desc_rep, .local = desc_local });
            }
        }

        const materialization = try self.descriptorMaterializationForKnownRepWithOverrides(identity_rep, overrides.items);
        const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
        errdefer self.parent.allocator.free(initializers);

        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, materialization);
        return .{
            .desc = target_desc_info.desc,
            .field_initializers = initializers,
            .materialize = target_desc_info.materialize,
        };
    }

    fn constructedTagDescriptorForPayloadFields(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        fields: []const AggregateDescriptorField,
    ) Allocator.Error!ConstructedAggregateDescriptor {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor == null and !rep.contains_dynamic and
            self.parent.result.store.getLocal(target).boxy_desc == null and
            !self.aggregateFieldsMayCarryDescriptor(fields))
        {
            return .{};
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        var field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        errdefer field_initializers.deinit(self.parent.allocator);
        var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
        defer overrides.deinit(self.parent.allocator);

        for (fields) |field| {
            const field_layout = self.parent.result.store.getLocal(field.local).layout_idx;
            const target_desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(field.target_rep) orelse continue;
            // The field local holds the adapted value, stored as the target
            // representation lays it out. A bare type parameter has no storage
            // shape of its own, so there the value keeps the descriptor of the
            // payload that was boxed into it.
            const storage_rep = self.constructedFieldStorageRep(field);
            const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(storage_rep, field_layout, true) orelse
                boxyLowerInvariant("constructed tag source payload had no storage descriptor representation");
            const desc_local = try self.prepareConstructedFieldDescriptorLocal(field.local, source_desc_rep, &field_initializers);
            try self.bindDescriptorIdentityLocalForRep(target_desc_rep, desc_local, false);
            const identity_desc_rep = self.parent.descriptorIdentityRep(target_desc_rep);
            var found = false;
            for (overrides.items) |override| {
                if (override.rep != identity_desc_rep) continue;
                found = true;
                break;
            }
            if (!found) {
                try overrides.append(self.parent.allocator, .{ .rep = identity_desc_rep, .local = desc_local });
            }
        }

        const materialization = try self.descriptorMaterializationForKnownRepWithOverrides(identity_rep, overrides.items);
        const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
        errdefer self.parent.allocator.free(initializers);
        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, materialization);
        return .{
            .desc = target_desc_info.desc,
            .field_initializers = initializers,
            .materialize = target_desc_info.materialize,
        };
    }

    fn constructedConcreteAggregateDescriptorForFields(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        fields: []const AggregateDescriptorField,
    ) Allocator.Error!ConstructedAggregateDescriptor {
        var refs = std.ArrayList(LIR.BoxyDescRef).empty;
        defer refs.deinit(self.parent.allocator);
        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);
        var field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        errdefer field_initializers.deinit(self.parent.allocator);

        for (fields) |field| {
            const field_layout = self.parent.result.store.getLocal(field.local).layout_idx;
            const storage_rep = self.constructedFieldStorageRep(field);
            const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(storage_rep, field_layout, true) orelse
                boxyLowerInvariant("forced constructed field descriptor representation was not selected");
            if (!self.parent.layoutNeedsNestedBoxyDesc(field_layout) and
                self.parent.result.store.getLocal(field.local).boxy_desc == null)
            {
                // A field whose layout carries no runtime descriptor has a
                // known identity.
                const known = try self.descriptorRefForKnownRep(desc_rep);
                if (known.localOrNull()) |local| try appendUniqueLocal(self.parent.allocator, &captures, local);
                try refs.append(self.parent.allocator, known);
                continue;
            }
            const desc_local = try self.prepareConstructedFieldDescriptorLocal(field.local, desc_rep, &field_initializers);
            try refs.append(self.parent.allocator, .{ .local = desc_local });
            try appendUniqueLocal(self.parent.allocator, &captures, desc_local);
        }

        if (captures.items.len == 0) {
            const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
            errdefer self.parent.allocator.free(initializers);
            const target_desc_info = try self.descriptorForConstructedTargetMaterialization(
                target,
                try self.descriptorMaterializationForKnownRep(rep_id),
            );
            return .{
                .desc = target_desc_info.desc,
                .field_initializers = initializers,
                .materialize = target_desc_info.materialize,
            };
        }

        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.appendSlice(self.parent.allocator, refs.items);

        // The constructed value is described by its representation's static
        // descriptor, with each field's descriptor taken from the field value.
        var completed = self.parent.result.boxy_type_descs.items[@backingInt(try self.parent.typeDescForRep(rep_id))];
        if (completed.nested_descs.len != refs.items.len) {
            boxyLowerInvariant("constructed aggregate fields disagreed with its descriptor's nested positions");
        }
        completed.nested_descs = .{ .start = nested_start, .len = @intCast(refs.items.len) };
        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, completed);
        const capture_span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
        errdefer self.parent.allocator.free(initializers);
        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, .{
            .desc = .{ .static = desc_id },
            .captures = capture_span,
        });
        return .{
            .desc = target_desc_info.desc,
            .field_initializers = initializers,
            .materialize = target_desc_info.materialize,
        };
    }

    fn prepareConstructedFieldDescriptorLocal(
        self: *ProcBodyBuilder,
        value: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!LIR.LocalId {
        if (self.parent.result.store.getLocal(value).boxy_desc) |desc| {
            if (desc.localOrNull()) |local| return local;

            const desc_local = try self.addFrameLocal(.opaque_ptr);
            try initializers.append(self.parent.allocator, .{
                .local = desc_local,
                .materialize = desc,
            });
            return desc_local;
        }

        const initial = try self.descriptorMaterializationForKnownRep(rep_id);
        const desc_local = try self.addFrameLocal(.opaque_ptr);
        try self.recordDescriptorLocalTemplate(desc_local, initial);
        if (self.parent.layoutNeedsNestedBoxyDesc(self.parent.result.store.getLocal(value).layout_idx)) {
            self.parent.result.store.setLocalBoxyDesc(value, .{ .local = desc_local });
        }
        try initializers.append(self.parent.allocator, .{
            .local = desc_local,
            .materialize = initial.desc,
            .captures = initial.captures,
        });
        return desc_local;
    }

    fn descriptorMaterializationForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        return try self.descriptorMaterializationForKnownRepExcludingLocal(rep_id, null);
    }

    fn descriptorMaterializationForKnownRepExcludingLocal(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        excluded_local: ?LIR.LocalId,
    ) Allocator.Error!DescriptorMaterialization {
        // A bound formal is described by its actual.
        var identity_rep = self.parent.descriptorIdentityRep(root);
        while (self.nominalFormalActualBelow(self.nominal_formal_bindings.items.len, identity_rep)) |actual| {
            identity_rep = self.parent.descriptorIdentityRep(actual);
        }
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        // A type-wide binding describes the representation outside the active
        // formal scopes; one whose meaning depends on them is built here.
        if (rep.descriptor != null and !try self.repDependsOnNominalFormals(identity_rep)) {
            const desc = rep.descriptor.?;
            if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| {
                    if (local != excluded_local) {
                        return .{ .desc = .{ .local = local } };
                    }
                }
            }
        }
        // Static descriptors cannot see the formals enclosing nominal scopes
        // bind; the template path resolves them.
        if (!try self.repDependsOnNominalFormals(identity_rep) and !try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep)) {
            return .{
                .desc = try self.parent.staticDescRefForRep(identity_rep),
                .captures = LIR.LocalSpan.empty(),
            };
        }

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);

        var context = try self.initDescriptorTemplateContext(false);
        defer context.deinit(self.parent.allocator);
        context.excluded_local = excluded_local;

        const desc: LIR.BoxyDescRef = .{ .static = try self.descriptorTemplateTypeDescForRep(identity_rep, &captures, &context) };
        const span = if (captures.items.len == 0)
            LIR.LocalSpan{ .start = 0, .len = 0 }
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return .{
            .desc = desc,
            .captures = span,
        };
    }

    fn descriptorMaterializationForExactRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        // Formal bindings make the template specific to this procedure.
        const shareable = self.nominal_formal_bindings.items.len == 0;
        if (shareable) {
            if (self.parent.exact_template_desc_ids.get(rep_id)) |existing| {
                return .{ .desc = .{ .static = existing }, .captures = LIR.LocalSpan.empty() };
            }
        }

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);

        var context = try self.initDescriptorTemplateContext(true);
        defer context.deinit(self.parent.allocator);

        const desc_id = try self.descriptorTemplateTypeDescForRep(rep_id, &captures, &context);
        if (shareable and !context.read_bound_locals) {
            if (captures.items.len != 0) boxyLowerInvariant("boxy exact descriptor template captured a local it never read");
            try self.parent.exact_template_desc_ids.put(self.parent.allocator, rep_id, desc_id);
        }
        const span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return .{ .desc = .{ .static = desc_id }, .captures = span };
    }

    fn descriptorMaterializationForKnownRepWithOverrides(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        overrides: []const DescriptorTemplateOverride,
    ) Allocator.Error!DescriptorMaterialization {
        if (overrides.len == 0) return try self.descriptorMaterializationForKnownRep(rep_id);
        return try self.descriptorTemplateMaterializationForRep(rep_id, overrides);
    }

    /// The static-field view of an open record: the record its row names,
    /// which a field read or update projects the complete record onto.
    fn openRecordViewDescriptorSource(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!ResultDescriptorSource {
        return try self.adapterDescriptorFromMaterialization(try self.descriptorTemplateMaterializationForRep(rep_id, &.{}));
    }

    fn descriptorTemplateMaterializationForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        overrides: []const DescriptorTemplateOverride,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);
        var context = try self.initDescriptorTemplateContext(false);
        defer context.deinit(self.parent.allocator);

        for (overrides) |override| {
            const override_rep = self.parent.descriptorIdentityRep(override.rep);
            try context.forced_refs.put(self.parent.allocator, override_rep, override.local);
        }

        const desc: LIR.BoxyDescRef = .{ .static = try self.descriptorTemplateTypeDescForRep(identity_rep, &captures, &context) };
        const span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return .{ .desc = desc, .captures = span };
    }

    /// Whether describing `rep_id` as a template captures a bound
    /// descriptor local anywhere its template reaches. Which references are
    /// reached does not depend on visiting order.
    fn descriptorTemplateNeedsCapturesForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        const visited = try allocator.alloc(bool, self.parent.plan.representations.items.len);
        defer allocator.free(visited);
        @memset(visited, false);
        var pending: std.ArrayList(TemplateCaptureProbe) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, .{ .body = rep_id });
        while (pending.pop()) |probe| switch (probe) {
            .ref => |ref| {
                const identity_rep = self.parent.descriptorIdentityRep(ref.rep);
                const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
                if (rep.descriptor) |desc| {
                    if (ref.parent_desc == null or desc != ref.parent_desc.?) {
                        if (self.descriptorBindingIsBoundForRep(identity_rep) and
                            self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep) != null) return true;
                    }
                }
                try pending.append(allocator, .{ .body = identity_rep });
            },
            .body => |body_rep| try self.probeTemplateBodyCaptures(body_rep, visited, &pending),
        };
        return false;
    }

    /// One pending step of a template capture probe.
    const TemplateCaptureProbe = union(enum) {
        /// A reference to `rep` inside the descriptor for `parent_desc`.
        ref: struct { rep: Plan.TypeRepId, parent_desc: ?Plan.DescriptorRequirementId },
        /// The template body describing `rep`.
        body: Plan.TypeRepId,
    };

    /// Queue the references a template body describing `rep_id` makes.
    fn probeTemplateBodyCaptures(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        visited: []bool,
        pending: *std.ArrayList(TemplateCaptureProbe),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep_index = @backingInt(identity_rep);
        if (visited[rep_index]) return;
        visited[rep_index] = true;

        const rep = self.parent.plan.representations.items[rep_index];
        var substitutions = self.parent.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
        while (substitutions.next()) |substitution| {
            const formal_rep = substitution.formal_rep orelse continue;
            if (substitution.actual_rep != formal_rep) try pending.append(allocator, .{ .ref = .{ .rep = substitution.actual_rep, .parent_desc = rep.descriptor } });
        }
        const current_desc = rep.descriptor;
        const rep_layout = self.parent.layout_plan.rep_layouts[rep_index];
        const payload_layout = rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
        if (self.parent.descriptorBackingShapeRep(identity_rep)) |backing_rep| {
            try pending.append(allocator, .{ .body = backing_rep });
            return;
        }

        if (rep.declared_fields.len != 0) {
            for (self.parent.plan.declaredFieldSlice(rep.declared_fields)) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(field.rep, field_layout, force_field) orelse continue;
                try pending.append(allocator, .{ .ref = .{ .rep = desc_rep, .parent_desc = current_desc } });
            }
        } else {
            var record_field_index: usize = 0;
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (child.role == .tag_ext) continue;
                const field_layout = switch (child.role) {
                    .record_field => blk: {
                        const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                        record_field_index += 1;
                        break :blk field_layout;
                    },
                    .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                    .box_payload => self.parent.descriptorPayloadLayoutForRep(child.rep),
                    .list_elem => self.parent.listElementLayout(payload_layout),
                    .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
                };
                const force_desc = child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout);
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, force_desc) orelse continue;
                try pending.append(allocator, .{ .ref = .{ .rep = desc_rep, .parent_desc = current_desc } });
            }
        }

        const tag_rep_id = self.parent.tagVariantRepForDesc(identity_rep);
        const tag_rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
        if (tag_rep.kind == .bool_tag_union) return;

        // A row with no named variants still captures its extension descriptor,
        // independently of the storage layout used for its dynamic value.
        var found_ext: ?Plan.TypeRepId = null;
        for (self.parent.plan.childSlice(tag_rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            if (found_ext != null) boxyLowerInvariant("boxy descriptor capture probe saw duplicate tag extension children");
            found_ext = child.rep;
        }
        if (found_ext) |ext_rep_id| {
            const ext_rep = self.parent.plan.representations.items[@backingInt(ext_rep_id)];
            if (ext_rep_id != tag_rep_id and ext_rep.kind != .empty_tag_union) {
                try pending.append(allocator, .{ .ref = .{ .rep = ext_rep_id, .parent_desc = current_desc } });
            }
        }

        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        const tag_layout = switch (layout_value.tag) {
            .tag_union => layout_value,
            .box => self.parent.result.layouts.getLayout(layout_value.getIdx()),
            .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .ptr => return,
        };
        if (tag_layout.tag != .tag_union) return;
        const tag_info = self.parent.result.layouts.getTagUnionInfo(tag_layout);

        for (self.parent.plan.tagVariantSlice(tag_rep.tag_variants), 0..) |variant, variant_index| {
            const variant_payload_layout = tag_info.variants.get(variant_index).payload_layout;
            const payloads = self.parent.plan.childSlice(variant.payloads);
            for (payloads, 0..) |child, payload_index| {
                const field_layout = self.parent.tagVariantPayloadFieldLayout(variant_payload_layout, payload_index, payloads.len);
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, true) orelse continue;
                try pending.append(allocator, .{ .ref = .{ .rep = desc_rep, .parent_desc = current_desc } });
            }
        }
    }

    fn descriptorMaterializationForSourceRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor != null) {
            if (!self.descriptorBindingIsBoundForRep(identity_rep)) {
                return try self.descriptorMaterializationForKnownRep(identity_rep);
            }
        }
        return .{
            .desc = try self.descriptorRefForKnownRep(identity_rep),
            .captures = LIR.LocalSpan.empty(),
        };
    }

    fn prependDescriptorRebindForRepFromRep(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const reservation = try self.reserveDescriptorLocalForRepWithFresh(target_rep) orelse return next;
        const target_desc_local = reservation.local;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return next;
        const target_rep_info = self.parent.plan.representations.items[@backingInt(target_rep)];
        if (target_rep_info.descriptor != null) {
            if (self.descriptorBindingIsBoundForRep(target_rep)) return next;
        }
        const materialization = try self.descriptorMaterializationForSourceRep(source_rep);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = target_desc_local,
            .desc = materialization.desc,
            .captures = materialization.captures,
            .next = next,
        } }, self.glueOrigin());
    }

    fn initDescriptorTemplateContext(self: *ProcBodyBuilder, exact_storage: bool) Allocator.Error!DescriptorTemplateContext {
        var exact_reps: std.AutoHashMapUnmanaged(Plan.TypeRepId, Plan.TypeRepId) = .empty;
        errdefer exact_reps.deinit(self.parent.allocator);
        for (self.nominal_formal_bindings.items) |binding| {
            try exact_reps.put(self.parent.allocator, binding.formal, binding.actual);
        }
        return .{
            .ids = std.AutoHashMap(DescriptorTemplateDescKey, LIR.BoxyTypeDescId).init(self.parent.allocator),
            .env_ids = std.AutoHashMap(DescriptorTemplateEnvKey, DescriptorTemplateEnvId).init(self.parent.allocator),
            .bindings = std.ArrayList(DescriptorTemplateBinding).empty,
            .exact_reps = exact_reps,
            .exact_storage = exact_storage,
        };
    }

    fn descriptorTemplateExactRep(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        context: *const DescriptorTemplateContext,
    ) Plan.TypeRepId {
        if (!context.exact_storage and !self.repIsBareDynamic(rep_id)) return rep_id;

        var current = rep_id;
        var remaining = context.exact_reps.count();
        while (context.exact_reps.get(current)) |next| {
            if (remaining == 0) {
                boxyLowerInvariant("boxy exact descriptor substitutions contained a cycle");
            }
            current = next;
            remaining -= 1;
        }
        return current;
    }

    /// Bind this representation's nominal backing formals to the arguments it
    /// supplies, for the descriptors nested inside it.
    ///
    /// A backing shape is written once against its declaration's formals and
    /// reached once per instantiation, so one template can descend through the
    /// same nominal at two argument sets and each descent binds the formals its
    /// own way. The bindings therefore last exactly as long as the descent that
    /// made them, and the returned scope is what undoes them.
    fn pushDescriptorTemplateExactReps(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        context: *DescriptorTemplateContext,
    ) Allocator.Error!DescriptorTemplateScope {
        const scope = DescriptorTemplateScope{
            .bindings_start = context.bindings.items.len,
            .env = context.env,
        };

        var current = rep_id;
        for (0..self.parent.plan.representations.items.len) |_| {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            const bindings_start = context.bindings.items.len;
            // Resolve all arguments in the enclosing scope before binding this
            // declaration's formals. The next wrapper can reuse those formals.
            var substitutions = self.parent.plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
            while (substitutions.next()) |substitution| {
                const formal_rep = substitution.formal_rep orelse continue;
                const actual = self.descriptorTemplateExactRep(substitution.actual_rep, context);
                const outer = context.exact_reps.get(formal_rep);
                if (formal_rep == actual or outer == actual) continue;
                try context.bindings.append(self.parent.allocator, .{
                    .formal = formal_rep,
                    .outer = outer,
                    .actual = actual,
                });
            }
            try activateDescriptorTemplateBindings(self.parent.allocator, context, bindings_start);
            current = self.parent.descriptorBackingShapeRep(current) orelse return scope;
        }
        boxyLowerInvariant("cyclic exact descriptor storage wrapper");
    }

    /// Bind the formals of `context.bindings[bindings_start..]`, extending the
    /// environment by each binding.
    fn activateDescriptorTemplateBindings(
        allocator: Allocator,
        context: *DescriptorTemplateContext,
        bindings_start: usize,
    ) Allocator.Error!void {
        for (context.bindings.items[bindings_start..]) |binding| {
            try context.exact_reps.put(allocator, binding.formal, binding.actual);
            const key = DescriptorTemplateEnvKey{
                .parent = context.env,
                .formal = binding.formal,
                .actual = binding.actual,
            };
            const entry = try context.env_ids.getOrPut(key);
            if (!entry.found_existing) {
                entry.value_ptr.* = @fromBackingInt(@intCast(@as(u32, @intCast(context.env_ids.count()))));
            }
            context.env = entry.value_ptr.*;
        }
    }

    /// Restore the bindings and environment a descent replaced.
    fn popDescriptorTemplateExactReps(
        context: *DescriptorTemplateContext,
        scope: DescriptorTemplateScope,
    ) void {
        var index = context.bindings.items.len;
        while (index > scope.bindings_start) {
            index -= 1;
            const binding = context.bindings.items[index];
            context.restoreExactRep(binding.formal, binding.outer);
        }
        context.bindings.shrinkRetainingCapacity(scope.bindings_start);
        context.env = scope.env;
    }

    // A template descriptor is built from references to its components'
    // descriptors, and components follow type nesting, so each descriptor
    // still waiting on a component's reference is a frame on one heap-backed
    // stack. Frames reserve descriptor ids and append spans, names, and
    // method slots in the order a direct recursive build would.

    /// A template descriptor under construction.
    const TemplateDescFrame = struct {
        rep_id: Plan.TypeRepId,
        desc_id: LIR.BoxyTypeDescId,
        /// The template bindings this descriptor's descent made.
        scope: DescriptorTemplateScope,
        current_desc: ?Plan.DescriptorRequirementId,
        payload_layout: layout.Idx,
        phase: enum {
            nested_begin,
            nested,
            tag_begin,
            tag_ext_probe,
            tag_payloads,
            tag_ext,
            fields,
            inspect_hidden,
            inspect_arg_begin,
            inspect_arg,
            method_done,
        } = .nested_begin,
        /// Whether the frame's last requested reference is still due.
        awaiting: bool = false,
        nested_descs: LIR.BoxySpan = .{},
        tag_variants: LIR.BoxySpan = .{},
        tag_ext_desc: ?LIR.BoxyDescRef = null,
        field_names: LIR.BoxySpan = .{},
        method_index: usize = 0,
        methods: [3]ProcedureBuilder.DescriptorMethodParts = @splat(.{}),
        refs: std.ArrayList(LIR.BoxyDescRef) = .empty,
        slots: std.ArrayList(ProcedureBuilder.NestedDescriptorSlot) = .empty,
        index: usize = 0,
        /// The tag variants being described.
        tag: struct {
            tag_rep_id: Plan.TypeRepId = undefined,
            /// A zero-sized union's single variant is described alone.
            zst: bool = false,
            has_ext: bool = false,
            /// Whether the current variant has begun.
            started: bool = false,
            variant: usize = 0,
            payload: usize = 0,
            name: LIR.BoxyNameId = undefined,
            entries: std.ArrayList(LirProgram.BoxyTagVariant) = .empty,
            payload_descs: std.ArrayList(LirProgram.BoxyTagPayloadDesc) = .empty,
        } = .{},
        /// The bindings made for the inspect worker's argument descriptor.
        inspect_scope: ?DescriptorTemplateScope = null,

        fn deinit(self: *TemplateDescFrame, allocator: Allocator) void {
            self.refs.deinit(allocator);
            self.slots.deinit(allocator);
            self.tag.entries.deinit(allocator);
            self.tag.payload_descs.deinit(allocator);
        }
    };

    const TemplateStep = union(enum) {
        /// The frame needs the reference for `rep_id` next.
        request: Plan.TypeRepId,
        /// The frame finished with this descriptor and was popped.
        done: LIR.BoxyTypeDescId,
    };

    fn descriptorTemplateTypeDescForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxyTypeDescId {
        var frames: std.ArrayList(TemplateDescFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.deinit(self.parent.allocator);
            frames.deinit(self.parent.allocator);
        }
        errdefer unwindTemplateDescFrames(&frames, context);
        const first: ?LIR.BoxyDescRef = if (try self.beginTemplateTypeDesc(rep_id, &frames, context)) |existing|
            .{ .static = existing }
        else
            null;
        return (try self.runTemplateDescFrames(&frames, first, captures, context)).static;
    }

    /// Undo the template bindings of every unfinished descriptor, innermost
    /// first, as the direct build's scopes would.
    fn unwindTemplateDescFrames(frames: *std.ArrayList(TemplateDescFrame), context: *DescriptorTemplateContext) void {
        var index = frames.items.len;
        while (index > 0) {
            index -= 1;
            const frame = frames.items[index];
            if (frame.inspect_scope) |scope| popDescriptorTemplateExactReps(context, scope);
            popDescriptorTemplateExactReps(context, frame.scope);
        }
    }

    fn runTemplateDescFrames(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(TemplateDescFrame),
        first: ?LIR.BoxyDescRef,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxyDescRef {
        var delivered = first;
        while (frames.items.len != 0) {
            const parent_desc = frames.items[frames.items.len - 1].current_desc;
            switch (try self.stepTemplateDescFrame(frames, delivered, context)) {
                .request => |rep_id| delivered = try self.beginTemplateRef(rep_id, parent_desc, frames, captures, context),
                .done => |desc_id| delivered = .{ .static = desc_id },
            }
        }
        return delivered orelse boxyLowerInvariant("boxy descriptor template finished without a reference");
    }

    /// The reference for `rep_id` when it needs no new descriptor; otherwise
    /// null, with the frame that builds the descriptor pushed.
    fn beginTemplateRef(
        self: *ProcBodyBuilder,
        root_rep_id: Plan.TypeRepId,
        parent_desc: ?Plan.DescriptorRequirementId,
        frames: *std.ArrayList(TemplateDescFrame),
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!?LIR.BoxyDescRef {
        var rep_id = root_rep_id;
        while (true) {
            const exact_rep = self.descriptorTemplateExactRep(rep_id, context);
            if (exact_rep == rep_id) break;
            // A constructed value forces the descriptor of the position it
            // fills, which a nominal backing names by its formal. The value's
            // own descriptor describes its storage there, whatever descriptor
            // the formal's actual type carries.
            if (context.forced_refs.get(self.parent.descriptorIdentityRep(rep_id))) |local| {
                if (context.excluded_local != local) {
                    try appendUniqueLocal(self.parent.allocator, captures, local);
                    return .{ .local = local };
                }
            }
            rep_id = exact_rep;
        }
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const exact_payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(rep_id);
        const identity_payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(identity_rep);
        const shares_identity_storage = exact_payload_layout == identity_payload_layout;
        const may_reuse_whole_descriptor = !context.exact_storage or self.repIsBareDynamic(rep_id);
        // A local named by representation describes it under the bindings
        // where it was made. A nominal's backing is shared by every
        // instantiation, so a nested instantiation of the same nominal (a
        // `Dict` inside a `Dict`) reaches the same rep as a different value.
        const may_reuse_rep_local = shares_identity_storage and may_reuse_whole_descriptor and
            !try self.descriptorTemplateRebindsRep(identity_rep, context);
        if (may_reuse_rep_local) {
            if (context.forced_refs.get(identity_rep)) |local| {
                if (context.excluded_local == local) return try self.templateStaticRef(rep_id, frames, context);
                try appendUniqueLocal(self.parent.allocator, captures, local);
                return .{ .local = local };
            }
        }
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (may_reuse_rep_local) if (rep.descriptor) |desc| {
            if (parent_desc == null or desc != parent_desc.?) {
                context.read_bound_locals = true;
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| {
                    if (self.descriptorBindingIsBoundForRep(identity_rep) and context.excluded_local != local) {
                        try appendUniqueLocal(self.parent.allocator, captures, local);
                        return .{ .local = local };
                    }
                }
            }
        };
        return try self.templateStaticRef(rep_id, frames, context);
    }

    fn templateStaticRef(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        frames: *std.ArrayList(TemplateDescFrame),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const existing = try self.beginTemplateTypeDesc(rep_id, frames, context) orelse return null;
        return .{ .static = existing };
    }

    /// The template descriptor of `rep_id` when this environment already
    /// built it; otherwise null, with the frame that builds it pushed.
    fn beginTemplateTypeDesc(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        frames: *std.ArrayList(TemplateDescFrame),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!?LIR.BoxyTypeDescId {
        const scope = try self.pushDescriptorTemplateExactReps(rep_id, context);
        var scope_owned = true;
        defer if (scope_owned) popDescriptorTemplateExactReps(context, scope);
        if (context.root_env == null) context.root_env = context.env;
        const desc_key = DescriptorTemplateDescKey{ .rep = rep_id, .env = context.env };
        if (context.ids.get(desc_key)) |existing| return existing;

        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        try context.ids.put(desc_key, desc_id);
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, reserved_boxy_type_desc);
        try frames.append(self.parent.allocator, .{
            .rep_id = rep_id,
            .desc_id = desc_id,
            .scope = scope,
            .current_desc = self.parent.plan.representations.items[@backingInt(rep_id)].descriptor,
            .payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(rep_id),
        });
        scope_owned = false;
        return null;
    }

    /// The row extension a tag representation's template describes, if any.
    fn templateTagExtRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.kind == .bool_tag_union) return null;
        if (rep.tag_variants.len == 0 and rep.kind != .tag_union and rep.kind != .dynamic) return null;

        var found: ?Plan.TypeRepId = null;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            if (found != null) boxyLowerInvariant("boxy descriptor template tag representation had duplicate row extension children");
            found = child.rep;
        }
        const ext_rep_id = found orelse return null;
        if (ext_rep_id == rep_id) return null;
        const ext_rep = self.parent.plan.representations.items[@backingInt(ext_rep_id)];
        if (ext_rep.kind == .empty_tag_union) return null;
        return ext_rep_id;
    }

    /// The committed tag layout a template descriptor's variants follow.
    fn templateTagLayout(self: *ProcBodyBuilder, payload_layout: layout.Idx) ?layout.Layout {
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        const tag_layout = switch (layout_value.tag) {
            .tag_union => layout_value,
            .box => self.parent.result.layouts.getLayout(layout_value.getIdx()),
            .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .ptr => return null,
        };
        if (tag_layout.tag != .tag_union) return null;
        return tag_layout;
    }

    fn stepTemplateDescFrame(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(TemplateDescFrame),
        delivered: ?LIR.BoxyDescRef,
        context: *DescriptorTemplateContext,
    ) Allocator.Error!TemplateStep {
        const allocator = self.parent.allocator;
        const plan = self.parent.plan;
        const frame = &frames.items[frames.items.len - 1];
        var ref: ?LIR.BoxyDescRef = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("boxy descriptor template frame resumed without its reference")
        else
            null;
        frame.awaiting = false;
        const rep_id = frame.rep_id;
        while (true) switch (frame.phase) {
            .nested_begin => {
                var shape_rep = rep_id;
                while (self.parent.descriptorBackingShapeRep(shape_rep)) |backing_rep| shape_rep = backing_rep;
                frame.phase = .tag_begin;
                const shape = plan.representations.items[@backingInt(shape_rep)];
                if (try self.parent.staticGeneratedEvidenceNestedDescRefs(shape.kind)) |nested_descs| {
                    frame.nested_descs = nested_descs;
                    continue;
                }
                const shape_layout = self.parent.descriptorTemplatePayloadLayoutForRep(shape_rep);
                try self.parent.appendNestedDescriptorSlots(shape_rep, shape_layout, &frame.slots);
                if (frame.slots.items.len == 0) continue;
                frame.refs.clearRetainingCapacity();
                frame.index = 0;
                frame.phase = .nested;
            },
            .nested => {
                if (ref) |nested| {
                    try frame.refs.append(allocator, nested);
                    ref = null;
                }
                if (frame.index < frame.slots.items.len) {
                    const slot = frame.slots.items[frame.index];
                    frame.index += 1;
                    frame.awaiting = true;
                    return .{ .request = self.parent.nestedDescriptorSlotDescRep(slot) };
                }
                const start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
                try self.parent.result.boxy_desc_refs.appendSlice(allocator, frame.refs.items);
                frame.nested_descs = .{ .start = start, .len = @intCast(frame.refs.items.len) };
                frame.phase = .tag_begin;
            },
            .tag_begin => {
                frame.phase = .tag_ext;
                const layout_value = self.parent.result.layouts.getLayout(frame.payload_layout);
                if (layout_value.tag == .zst) {
                    const tag_rep_id = self.parent.tagVariantRepForDesc(rep_id);
                    const variants = plan.tagVariantSlice(plan.representations.items[@backingInt(tag_rep_id)].tag_variants);
                    if (variants.len == 0) continue;
                    if (variants.len != 1) {
                        boxyLowerInvariant("zero-sized boxy descriptor template had multiple tag variants");
                    }
                    frame.tag.tag_rep_id = tag_rep_id;
                    frame.tag.zst = true;
                    frame.phase = .tag_payloads;
                    continue;
                }
                if (self.templateTagLayout(frame.payload_layout) == null) continue;
                const tag_rep_id = self.parent.tagVariantRepForDesc(rep_id);
                const rep = plan.representations.items[@backingInt(tag_rep_id)];
                if (rep.kind == .bool_tag_union) {
                    frame.tag_variants = try self.parent.staticTagVariantsForRep(rep_id, frame.payload_layout);
                    continue;
                }
                if (rep.tag_variants.len == 0) continue;
                frame.tag.tag_rep_id = tag_rep_id;
                frame.phase = .tag_ext_probe;
                if (self.templateTagExtRep(tag_rep_id)) |ext_rep| {
                    frame.awaiting = true;
                    return .{ .request = ext_rep };
                }
            },
            .tag_ext_probe => {
                // Describing the row extension is what adds the layout's
                // extension variant.
                frame.tag.has_ext = ref != null;
                ref = null;
                const variants = plan.tagVariantSlice(plan.representations.items[@backingInt(frame.tag.tag_rep_id)].tag_variants);
                const tag_info = self.parent.result.layouts.getTagUnionInfo(self.templateTagLayout(frame.payload_layout).?);
                if (tag_info.variants.len != variants.len + @intFromBool(frame.tag.has_ext)) {
                    boxyLowerInvariant("boxy descriptor template variant count disagreed with committed layout");
                }
                frame.phase = .tag_payloads;
            },
            .tag_payloads => {
                const tag = &frame.tag;
                const variants = plan.tagVariantSlice(plan.representations.items[@backingInt(tag.tag_rep_id)].tag_variants);
                if (ref) |payload_desc| {
                    try tag.payload_descs.append(allocator, .{
                        .payload_index = @intCast(tag.payload - 1),
                        .desc = payload_desc,
                    });
                    ref = null;
                }
                while (tag.variant < variants.len) {
                    const variant = variants[tag.variant];
                    const payloads = plan.childSlice(variant.payloads);
                    const variant_payload_layout: layout.Idx = if (tag.zst)
                        .zst
                    else
                        self.parent.result.layouts.getTagUnionInfo(self.templateTagLayout(frame.payload_layout).?).variants.get(tag.variant).payload_layout;
                    if (!tag.started) {
                        tag.started = true;
                        tag.payload_descs.clearRetainingCapacity();
                        if (!tag.zst) tag.name = try self.parent.result.store.insertBoxyName(self.tagVariantNameText(variant));
                    }
                    while (tag.payload < payloads.len) {
                        const index = tag.payload;
                        tag.payload += 1;
                        const field_layout = self.parent.tagVariantPayloadFieldLayout(variant_payload_layout, index, payloads.len);
                        // Match the static descriptor path: a concrete tag payload may flow
                        // into a worker whose view of that payload is erased, so the
                        // descriptor template must be able to capture the runtime payload
                        // descriptor even when the payload's own representation would not
                        // otherwise require one.
                        const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(payloads[index].rep, field_layout, true) orelse continue;
                        frame.awaiting = true;
                        return .{ .request = desc_rep };
                    }
                    const payload_span: LIR.BoxySpan = if (tag.payload_descs.items.len == 0) .{} else span: {
                        const start: u32 = @intCast(self.parent.result.boxy_tag_payload_descs.items.len);
                        try self.parent.result.boxy_tag_payload_descs.appendSlice(allocator, tag.payload_descs.items);
                        break :span .{ .start = start, .len = @intCast(tag.payload_descs.items.len) };
                    };
                    if (tag.zst) {
                        const name = try self.parent.result.store.insertBoxyName(self.tagVariantNameText(variant));
                        const start: u32 = @intCast(self.parent.result.boxy_tag_variants.items.len);
                        try self.parent.result.boxy_tag_variants.append(allocator, .{
                            .name = name,
                            .discriminant = 0,
                            .payload_count = @intCast(payloads.len),
                            .payload_layout = .zst,
                            .payload_descs = payload_span,
                        });
                        frame.tag_variants = .{ .start = start, .len = 1 };
                    } else {
                        try tag.entries.append(allocator, .{
                            .name = tag.name,
                            .discriminant = @intCast(tag.variant),
                            .payload_count = @intCast(payloads.len),
                            .payload_layout = variant_payload_layout,
                            .payload_descs = payload_span,
                        });
                    }
                    tag.variant += 1;
                    tag.payload = 0;
                    tag.started = false;
                }
                if (!tag.zst) {
                    const start: u32 = @intCast(self.parent.result.boxy_tag_variants.items.len);
                    try self.parent.result.boxy_tag_variants.appendSlice(allocator, tag.entries.items);
                    frame.tag_variants = .{ .start = start, .len = @intCast(tag.entries.items.len) };
                }
                frame.phase = .tag_ext;
            },
            .tag_ext => {
                if (ref) |ext_desc| {
                    frame.tag_ext_desc = ext_desc;
                    ref = null;
                    frame.phase = .fields;
                    continue;
                }
                if (self.templateTagExtRep(self.parent.tagVariantRepForDesc(rep_id))) |ext_rep| {
                    frame.awaiting = true;
                    return .{ .request = ext_rep };
                }
                frame.phase = .fields;
            },
            .fields => {
                frame.field_names = try self.parent.staticFieldNamesForRep(rep_id);
                frame.methods[frame.method_index].method = try self.parent.descriptorMethodSlotForRep(rep_id, ProcedureBuilder.descriptor_method_kinds[frame.method_index]);
                frame.refs.clearRetainingCapacity();
                frame.index = 0;
                frame.phase = .inspect_hidden;
            },
            .inspect_hidden => {
                const args: []const Plan.DirectCallHiddenDescriptorArg = if (plan.descriptorMethodForRep(rep_id, ProcedureBuilder.descriptor_method_kinds[frame.method_index])) |inspect|
                    plan.directCallHiddenDescriptorArgSlice(inspect.hidden_desc_args)
                else
                    &.{};
                if (ref) |hidden| {
                    try frame.refs.append(allocator, hidden);
                    ref = null;
                }
                const identity_rep = self.parent.descriptorIdentityRep(rep_id);
                while (frame.index < args.len) {
                    const arg = args[frame.index];
                    frame.index += 1;
                    // The whole inspected value is described by the descriptor under
                    // construction.
                    if (self.parent.descriptorIdentityRep(arg.rep) == identity_rep) {
                        try frame.refs.append(allocator, .{ .static = frame.desc_id });
                        continue;
                    }
                    frame.awaiting = true;
                    return .{ .request = arg.rep };
                }
                frame.methods[frame.method_index].hidden = if (args.len == 0) .{} else try self.parent.appendStaticHiddenDescRefs(frame.refs.items);
                frame.phase = .inspect_arg_begin;
            },
            .inspect_arg_begin => {
                const inspect = plan.descriptorMethodForRep(rep_id, ProcedureBuilder.descriptor_method_kinds[frame.method_index]) orelse {
                    frame.phase = .method_done;
                    continue;
                };
                if (self.parent.descriptorMethodArgumentIsIdentity(inspect)) {
                    frame.methods[frame.method_index].args = try self.parent.appendDescriptorMethodArgRefs(inspect, .{ .static = frame.desc_id });
                    frame.phase = .method_done;
                    continue;
                }
                frame.inspect_scope = .{
                    .bindings_start = context.bindings.items.len,
                    .env = context.env,
                };
                for (plan.directCallHiddenDescriptorArgSlice(inspect.hidden_desc_args)) |arg| {
                    if (!self.repIsBareDynamic(arg.worker_rep)) continue;
                    try self.bindDescriptorTemplateExactRep(arg.worker_rep, arg.rep, context);
                }
                frame.phase = .inspect_arg;
                frame.awaiting = true;
                return .{ .request = self.parent.descriptorMethodWorkerArgRep(inspect) };
            },
            .inspect_arg => {
                const arg_ref = ref orelse boxyLowerInvariant("boxy descriptor template inspect argument had no reference");
                const method = plan.descriptorMethodForRep(rep_id, ProcedureBuilder.descriptor_method_kinds[frame.method_index]).?;
                frame.methods[frame.method_index].args = try self.parent.appendDescriptorMethodArgRefs(method, arg_ref);
                popDescriptorTemplateExactReps(context, frame.inspect_scope.?);
                frame.inspect_scope = null;
                frame.phase = .method_done;
            },
            .method_done => {
                if (frame.method_index != 0) frame.methods[frame.method_index].dictionaries = try self.parent.descriptorMethodDictRefs(rep_id, ProcedureBuilder.descriptor_method_kinds[frame.method_index]);
                frame.method_index += 1;
                if (frame.method_index == ProcedureBuilder.descriptor_method_kinds.len) return try self.finishTemplateDesc(frames, context);
                frame.phase = .fields;
            },
        };
    }

    /// Store the finished descriptor and leave its descent's bindings.
    fn finishTemplateDesc(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(TemplateDescFrame),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!TemplateStep {
        var frame = frames.pop().?;
        defer frame.deinit(self.parent.allocator);
        const rep_id = frame.rep_id;
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const layout_value = self.parent.result.layouts.getLayout(frame.payload_layout);
        self.parent.result.boxy_type_descs.items[@backingInt(frame.desc_id)] = .{
            .payload_layout = frame.payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value) or rep.contains_dynamic,
            .shape = self.parent.descriptorShapeForRep(rep_id),
            .nested_descs = frame.nested_descs,
            .tag_variants = frame.tag_variants,
            .tag_ext_desc = frame.tag_ext_desc,
            .field_names = frame.field_names,
            .inspect_opaque = self.parent.repInspectsOpaque(rep_id),
            .inspect_method = frame.methods[0].method,
            .inspect_hidden_descs = frame.methods[0].hidden,
            .inspect_arg_descs = frame.methods[0].args,
            .eq_method = frame.methods[1].method,
            .eq_hidden_descs = frame.methods[1].hidden,
            .eq_arg_descs = frame.methods[1].args,
            .eq_nested_dicts = frame.methods[1].dictionaries,
            .hash_method = frame.methods[2].method,
            .hash_hidden_descs = frame.methods[2].hidden,
            .hash_arg_descs = frame.methods[2].args,
            .hash_nested_dicts = frame.methods[2].dictionaries,
            .is_bool = self.parent.repDescribesBool(rep_id),
            .eq_rejected = self.parent.plan.descriptorMethodRejected(rep_id, .equality),
            .hash_rejected = self.parent.plan.descriptorMethodRejected(rep_id, .hash),
            .presence_slot_present_discriminant = rep.presence_slot_present_discriminant,
            .debug_checked_type = rep.source_type.ty,
        };
        popDescriptorTemplateExactReps(context, frame.scope);
        return .{ .done = frame.desc_id };
    }

    /// Whether describing `rep_id` here reads a formal that this template's
    /// descent has bound differently from the root's instantiation.
    fn descriptorTemplateRebindsRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        context: *const DescriptorTemplateContext,
    ) Allocator.Error!bool {
        const root_env = context.root_env orelse return false;
        if (context.env == root_env or context.bindings.items.len == 0) return false;
        // Which representations the walk reaches depends only on each
        // representation, so the answer does not depend on visiting order.
        const allocator = self.parent.allocator;
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(allocator);
        defer seen.deinit();
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, rep_id);
        const plan = self.parent.plan;
        while (pending.pop()) |current| {
            if ((try seen.getOrPut(current)).found_existing) continue;
            for (context.bindings.items) |binding| {
                if (binding.formal == current) return true;
            }
            const rep = plan.representations.items[@backingInt(current)];
            // A nested nominal rebinds its own formals: only its actuals can read
            // an enclosing binding.
            if (rep.kind == .nominal and rep.nominal_backing_arg_substitutions.len != 0) {
                var substitutions = plan.nominalBackingSubstitutions(rep.nominal_backing_arg_substitutions);
                while (substitutions.next()) |substitution| try pending.append(allocator, substitution.actual_rep);
                continue;
            }
            for (plan.childSlice(rep.children)) |child| {
                if (!Plan.childCarriesRuntimeDescriptor(child.role)) continue;
                try pending.append(allocator, child.rep);
            }
            for (plan.tagVariantSlice(rep.tag_variants)) |variant| {
                for (plan.childSlice(variant.payloads)) |payload| try pending.append(allocator, payload.rep);
            }
        }
        return false;
    }

    /// Bind one formal to its actual in the template environment; the
    /// caller's scope restores it.
    fn bindDescriptorTemplateExactRep(
        self: *const ProcBodyBuilder,
        formal: Plan.TypeRepId,
        actual_rep: Plan.TypeRepId,
        context: *DescriptorTemplateContext,
    ) Allocator.Error!void {
        const actual = self.descriptorTemplateExactRep(actual_rep, context);
        const outer = context.exact_reps.get(formal);
        if (formal == actual or outer == actual) return;
        try context.bindings.append(self.parent.allocator, .{
            .formal = formal,
            .outer = outer,
            .actual = actual,
        });
        try context.exact_reps.put(self.parent.allocator, formal, actual);
        const key = DescriptorTemplateEnvKey{
            .parent = context.env,
            .formal = formal,
            .actual = actual,
        };
        const entry = try context.env_ids.getOrPut(key);
        if (!entry.found_existing) {
            entry.value_ptr.* = @fromBackingInt(@intCast(@as(u32, @intCast(context.env_ids.count()))));
        }
        context.env = entry.value_ptr.*;
    }

    fn descriptorRefForRepIfNeeded(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact_rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (exact_rep.descriptor) |desc| {
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id)) |local| {
                return .{ .local = local };
            }
            if (identity_rep != rep_id) {
                return try self.descriptorRefForKnownRep(identity_rep);
            }
            if (self.descriptorBindingIsBoundForRep(rep_id)) {
                if (try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep)) {
                    boxyLowerInvariant("bound exact boxy descriptor requirement had no matching local");
                }
            }
            return try self.parent.staticDescRefForRep(rep_id);
        }

        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor == null) return null;
        return try self.descriptorRefForKnownRep(identity_rep);
    }

    /// The descriptor a representation-boundary conversion records for its
    /// concrete tag-union target local. A boundary target already carries the
    /// descriptor it was allocated with, and the release plan keys one
    /// descriptor per local, so the conversion reuses that descriptor. When the
    /// exact representation reserving the target local and the identity
    /// representation the boundary was dispatched on reserve distinct
    /// descriptor requirement locals, deriving afresh from the representation
    /// would record a second descriptor for the same local. Reusing the local's
    /// own descriptor keeps a single descriptor per local. A target with no
    /// recorded descriptor yet takes the representation-derived one, which is
    /// then recorded on the local.
    fn boundaryTargetDesc(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!?LIR.BoxyDescRef {
        if (self.parent.result.store.getLocal(target).boxy_desc) |existing| return existing;
        const derived = try self.descriptorRefForRepIfNeeded(target_rep) orelse return null;
        self.parent.result.store.setLocalBoxyDesc(target, derived);
        return derived;
    }

    fn dictionaryRefForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
    ) Allocator.Error!LIR.BoxyDictRef {
        const identity_rep = self.dictionaryIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.dictionaries.len != 0) {
            const first: Plan.DictionaryRequirementId = @fromBackingInt(@intCast(rep.dictionaries.start));
            if (self.dictionaryBindingIsBound(first)) {
                if (self.dictionaryLocalForRequirementOrNull(first)) |local| return .{ .local = local };
                boxyLowerInvariant("boxy runtime-bound dictionary requirement had no local");
            }
        }
        if (rep.kind == .dynamic) {
            // A dynamic representation has no owner to build a static
            // dictionary from; the requirement must be satisfied by the
            // enclosing worker's own dictionary binding (a recursive or
            // sibling generic call passing its dictionaries along).
            if (worker_dictionaries.len != 0) {
                const callee_first: Plan.DictionaryRequirementId = @fromBackingInt(@intCast(worker_dictionaries.start));
                if (self.dictionaryBindingIsBound(callee_first)) {
                    if (self.dictionaryLocalForRequirementOrNull(callee_first)) |local| return .{ .local = local };
                }
            }
            boxyLowerInvariant("boxy dynamic representation dictionary requirement was not bound in the enclosing worker");
        }
        return try self.parent.staticDictRefForRep(identity_rep, worker_dictionaries);
    }

    fn dictionaryRefForPlannedSource(
        self: *ProcBodyBuilder,
        arg: Plan.DirectCallHiddenDictionaryArg,
    ) Allocator.Error!FrameDictionary {
        return switch (arg.source) {
            .literal => |literal| .{ .dict = try self.literalReference(literal) },
            .bound_dictionaries => |dictionaries| .{ .dict = .{ .local = self.boundDictionaryLocal(dictionaries) } },
            .static_rep => |source_rep| try self.staticDictRefInFrame(
                source_rep,
                arg.worker_dictionaries,
                arg.method_evidence,
                arg.env,
            ),
        };
    }

    fn literalReference(self: *ProcBodyBuilder, argument: LiteralRequirements.Argument) Allocator.Error!LIR.BoxyDictRef {
        return switch (argument) {
            .result => |index| .{ .static = try self.parent.emitLiteralAccessor(index) },
            .parameter => |index| .{ .local = self.literal_locals.items[index] },
        };
    }

    fn lowerPlannedLiteralInto(self: *ProcBodyBuilder, target: LIR.LocalId, expr: checked.CheckedExprId, ty: checked.CheckedTypeId, next: LIR.CFStmtId) Allocator.Error!?LIR.CFStmtId {
        const evidence = if (self.parent.plan.literal_evidence) |*evidence| evidence else return null;
        const argument = evidence.sites.get(.{
            .source = .{ .module = self.module.key, .expr = expr },
            .worker = self.worker_layout.worker,
        }) orelse return null;
        const checked_expr = self.module.checked_bodies.expr(expr);
        const plan_id = switch (checked_expr.data) {
            .str_from_quote => |quote| quote.plan,
            .numeral => |numeral| numeral.plan,
            .interpolation => |interpolation| interpolation.plan,
            .pending, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .binop, .unary_minus, .unary_not, .field_access, .dispatch_call, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level, .closure, .lambda => unreachable,
        };
        const dispatch = self.staticDispatchPlan(plan_id);
        const result_desc = try self.exactCallResultDescriptorRef(self.repForType(ty));
        const body = try self.parent.result.store.addCFStmt(.{ .assign_call_dict = .{
            .target = target,
            .dict = try self.literalReference(argument),
            .method = dispatch.method,
            .method_slot = 0,
            .args = .empty(),
            .arg_descs = .empty(),
            .hidden_args = .empty(),
            .result_desc = result_desc.desc,
            .next = next,
        } }, self.origin);
        return try self.prependOptionalDescriptorMaterialization(result_desc.materialize, body);
    }

    fn prependDescriptorArgMaterializations(
        self: *ProcBodyBuilder,
        hidden_args: []const DescriptorArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const visit = try self.parent.allocator.alloc(DescriptorMaterializationVisit, hidden_args.len);
        defer self.parent.allocator.free(visit);
        @memset(visit, .pending);

        // Each materialized descriptor local's first argument position, so
        // dependencies resolve in constant time.
        var positions: std.AutoHashMapUnmanaged(LIR.LocalId, usize) = .empty;
        defer positions.deinit(self.parent.allocator);
        try positions.ensureTotalCapacity(self.parent.allocator, @intCast(hidden_args.len));
        for (hidden_args, 0..) |hidden, index| {
            if (hidden.materialize == null) continue;
            const entry = positions.getOrPutAssumeCapacity(hidden.local);
            if (!entry.found_existing) entry.value_ptr.* = index;
        }

        var order = std.ArrayList(usize).empty;
        defer order.deinit(self.parent.allocator);
        for (hidden_args, 0..) |_, index| {
            try self.appendHiddenDescriptorMaterializationOrder(hidden_args, &positions, index, visit, &order);
        }

        var continuation = next;
        var index = order.items.len;
        while (index > 0) {
            index -= 1;
            const hidden = hidden_args[order.items[index]];
            const desc = hidden.materialize orelse
                boxyLowerInvariant("boxy hidden descriptor materialization order included a descriptor with no materialization");
            continuation = try self.prependDescriptorArgMaterialization(hidden, desc, continuation);
        }
        return continuation;
    }

    fn prependDescriptorArgMaterialization(
        self: *ProcBodyBuilder,
        hidden: DescriptorArgLocal,
        desc: LIR.BoxyDescRef,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.localIsReadOnlyDescriptorInput(hidden.local)) {
            boxyLowerInvariant("boxy descriptor arg materialization targeted read-only descriptor input");
        }
        const read_path = self.parent.descriptorReadPathSlice(hidden.read_path);
        if (read_path.len == 0) {
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = hidden.local,
                .desc = desc,
                .nested_index = hidden.nested_index,
                .tag_ext = hidden.tag_ext,
                .tag_residual_for = hidden.tag_residual_for,
                .captures = hidden.captures,
                .next = next,
            } }, self.glueOrigin());
        }
        if (hidden.nested_index != null or hidden.tag_ext or hidden.tag_residual_for != null) {
            boxyLowerInvariant("boxy descriptor materialization combined a read_path path with a legacy read_path");
        }

        const intermediate_count = read_path.len - 1;
        const intermediates = try self.parent.allocator.alloc(LIR.LocalId, intermediate_count);
        defer self.parent.allocator.free(intermediates);
        for (intermediates) |*local| local.* = try self.addFrameLocal(.opaque_ptr);

        var continuation = next;
        var read_index = read_path.len;
        while (read_index > 0) {
            read_index -= 1;
            const target = if (read_index == read_path.len - 1)
                hidden.local
            else
                intermediates[read_index];
            const source_desc = if (read_index == 0)
                desc
            else
                LIR.BoxyDescRef{ .local = intermediates[read_index - 1] };
            const step = read_path[read_index];
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = target,
                .desc = source_desc,
                .nested_index = switch (step) {
                    .nested => |nested_index| nested_index,
                    .tag_payload, .tag_ext, .box_payload => null,
                },
                .box_payload_layout = switch (step) {
                    .box_payload => |box_layout| box_layout,
                    .nested, .tag_payload, .tag_ext => null,
                },
                .tag_payload = switch (step) {
                    .tag_payload => |payload| .{
                        .tag_name = payload.tag_name,
                        .payload_index = payload.payload_index,
                    },
                    .nested, .tag_ext, .box_payload => null,
                },
                .tag_ext = switch (step) {
                    .tag_ext => true,
                    .nested, .tag_payload, .box_payload => false,
                },
                .captures = if (read_index == 0) hidden.captures else LIR.LocalSpan.empty(),
                .next = continuation,
            } }, self.glueOrigin());
        }
        return continuation;
    }

    fn prependOptionalDescriptorMaterialization(
        self: *ProcBodyBuilder,
        maybe_hidden: ?DescriptorArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const hidden = maybe_hidden orelse return next;
        const desc = hidden.materialize orelse
            boxyLowerInvariant("optional descriptor materialization had no descriptor");
        return try self.prependDescriptorArgMaterialization(hidden, desc, next);
    }

    fn prependWorkerReturnDescriptorInitializers(
        self: *ProcBodyBuilder,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.prependDescriptorArgMaterializations(
            self.worker_return_descriptor_initializers.items,
            next,
        );
    }

    /// Append, dependencies first, the materialization order of the hidden
    /// descriptor `root` and each materialization it reads.
    fn appendHiddenDescriptorMaterializationOrder(
        self: *ProcBodyBuilder,
        hidden_args: []const DescriptorArgLocal,
        positions: *const std.AutoHashMapUnmanaged(LIR.LocalId, usize),
        root: usize,
        visit: []DescriptorMaterializationVisit,
        order: *std.ArrayList(usize),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        const Frame = struct { index: usize, stage: usize = 0 };
        var frames: std.ArrayList(Frame) = .empty;
        defer frames.deinit(allocator);
        var request: ?usize = root;
        while (true) {
            if (request) |index| {
                request = null;
                switch (visit[index]) {
                    .done => {},
                    .visiting => boxyLowerInvariant("boxy hidden descriptor materializations contained a dependency cycle"),
                    .pending => {
                        visit[index] = .visiting;
                        try frames.append(allocator, .{ .index = index });
                    },
                }
            }
            if (frames.items.len == 0) return;
            const top = &frames.items[frames.items.len - 1];
            const hidden = hidden_args[top.index];
            const materialize = hidden.materialize orelse {
                visit[top.index] = .done;
                frames.items.len -= 1;
                continue;
            };
            const captures = self.parent.result.store.getLocalSpan(hidden.captures);
            const stage = top.stage;
            top.stage += 1;
            // The descriptor it reads, then its residual target, then its
            // captures, are materialized before it.
            const read_local: ?LIR.LocalId = if (stage == 0)
                materialize.localOrNull()
            else if (stage == 1)
                if (hidden.tag_residual_for) |target_desc| target_desc.localOrNull() else null
            else if (stage - 2 < GuardedList.borrowLen(captures))
                GuardedList.at(captures, stage - 2)
            else {
                try order.append(allocator, top.index);
                visit[top.index] = .done;
                frames.items.len -= 1;
                continue;
            };
            const dependency_local: ?LIR.LocalId = if (read_local) |local|
                (if (stage < 2 and local == hidden.local) null else local)
            else
                null;
            if (dependency_local) |local| request = positions.get(local);
        }
    }

    fn prependHiddenDictionaryArgMaterialization(
        self: *ProcBodyBuilder,
        hidden_args: []const DictionaryArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        var index = hidden_args.len;
        while (index > 0) {
            index -= 1;
            const hidden = hidden_args[index];
            if (hidden.materialize) |dict| {
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_dict_ref = .{
                    .target = hidden.local,
                    .dict = dict,
                    .captures = hidden.captures,
                    .next = continuation,
                } }, self.glueOrigin());
            }
        }
        return continuation;
    }

    fn boolSwitchNoContinuation(
        self: *ProcBodyBuilder,
        cond: LIR.LocalId,
        true_body: LIR.CFStmtId,
        false_body: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const branches = [_]LIR.CFSwitchBranch{.{ .value = Common.bool_true_discriminant, .body = true_body }};
        return try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = cond,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = false_body,
            .continuation = null,
        } }, self.glueOrigin());
    }

    fn lowerInspectLocalInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.parent.result.store.getLocal(target).layout_idx != .str) {
            boxyLowerInvariant("boxy inspect target did not have Str layout");
        }
        return try self.lowerInspectRepLocalInto(target, source, self.repForType(checked_ty), next);
    }

    // Structural inspection //
    //
    // Inspecting a representation renders its components, and components
    // follow type nesting, so each rendering still waiting on a component's
    // rendering is a frame on one heap-backed stack. Renderings are built
    // from their continuation backward; frames allocate locals, join points,
    // and statements in the order a direct recursive build would.

    const InspectRequest = struct {
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    };

    const InspectStep = union(enum) {
        /// The frame needs this component rendering next.
        request: InspectRequest,
        /// The frame finished with this statement and was popped.
        done: LIR.CFStmtId,
    };

    /// A rendering concatenated from parts, rendered last first.
    const InspectPartsState = struct {
        target: LIR.LocalId,
        parts: []InspectPart,
        part_locals: []LIR.LocalId,
        remaining: usize,
        continuation: LIR.CFStmtId,
        pending_value: LIR.LocalId = undefined,

        fn deinit(self: InspectPartsState, allocator: Allocator) void {
            allocator.free(self.parts);
            allocator.free(self.part_locals);
        }
    };

    const InspectFrame = struct {
        /// Whether the frame's last requested rendering is still due.
        awaiting: bool = false,
        /// The rendering the frame needs before any of its own work.
        first: ?InspectRequest = null,
        state: union(enum) {
            nominal: struct {
                request: InspectRequest,
                scope: NominalBackingFormalScope,
                backing_rep: Plan.TypeRepId,
                backing: ?LIR.LocalId,
            },
            parts: InspectPartsState,
            tag: struct {
                request: InspectRequest,
                discriminant: LIR.LocalId,
                done: LIR.JoinPointId,
                branches: []LIR.CFSwitchBranch,
                index: usize = 0,
                variant: ?InspectPartsState = null,
            },
            presence: struct {
                request: InspectRequest,
                done: LIR.JoinPointId,
                present_discriminant: u32,
                missing_discriminant: u32,
                value: LIR.LocalId,
            },
            box: struct {
                request: InspectRequest,
                payload_rep: Plan.TypeRepId,
                payload: LIR.LocalId,
                prefix: LIR.LocalId,
            },
            list: struct {
                request: InspectRequest,
                elem: LIR.LocalId,
                index: LIR.LocalId,
                out: LIR.LocalId,
                len: LIR.LocalId,
                zero_index: LIR.LocalId,
                initial_out: LIR.LocalId,
                join_id: LIR.JoinPointId,
                done: LIR.LocalId,
                finish: LIR.CFStmtId,
                sep: LIR.LocalId,
                zero: LIR.LocalId,
                is_first: LIR.LocalId,
                with_sep: LIR.LocalId,
            },
        },
    };

    fn lowerInspectRepLocalInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const allocator = self.parent.allocator;
        var frames: std.ArrayList(InspectFrame) = .empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseInspectFrame(&frames.items[index]);
            }
            frames.deinit(allocator);
        }
        var result = try self.beginInspect(&frames, .{ .target = target, .source = source, .rep_id = rep_id, .next = next });
        while (frames.items.len != 0) {
            switch (try self.stepInspectFrame(&frames, result)) {
                .request => |request| result = try self.beginInspect(&frames, request),
                .done => |stmt| result = stmt,
            }
        }
        return result.?;
    }

    /// Free what an unfinished frame owns and leave the scope it holds, as
    /// the direct build's defers would.
    fn releaseInspectFrame(self: *ProcBodyBuilder, frame: *InspectFrame) void {
        const allocator = self.parent.allocator;
        switch (frame.state) {
            .presence, .box, .list => {},
            .nominal => |nominal| self.dropNominalBackingFormalScope(nominal.scope),
            .parts => |parts| parts.deinit(allocator),
            .tag => |tag| {
                allocator.free(tag.branches);
                if (tag.variant) |variant| variant.deinit(allocator);
            },
        }
    }

    fn pushInspectFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), state: @FieldType(InspectFrame, "state")) Allocator.Error!?LIR.CFStmtId {
        return try self.pushInspectFrameFirst(frames, state, null);
    }

    fn pushInspectFrameFirst(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(InspectFrame),
        state: @FieldType(InspectFrame, "state"),
        first: ?InspectRequest,
    ) Allocator.Error!?LIR.CFStmtId {
        var frame: InspectFrame = .{ .state = state, .first = first };
        frames.append(self.parent.allocator, frame) catch |err| {
            self.releaseInspectFrame(&frame);
            return err;
        };
        return null;
    }

    fn finishInspectFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), stmt: LIR.CFStmtId) InspectStep {
        var frame = frames.pop().?;
        switch (frame.state) {
            // A finished nominal rendering has left its scope already.
            .nominal => {},
            .parts, .tag, .presence, .box, .list => self.releaseInspectFrame(&frame),
        }
        return .{ .done = stmt };
    }

    /// The rendering of `request` when it needs no component rendering;
    /// otherwise null, with the frame that builds it pushed.
    fn beginInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), root: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        var request = root;
        while (true) {
            const target = request.target;
            const source = request.source;
            const rep_id = request.rep_id;
            const next = request.next;
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            switch (rep.kind) {
                .in_progress => boxyLowerInvariant("in-progress boxy representation reached inspect lowering"),
                .dynamic => return try self.lowerDescriptorInspectLocalsInto(target, source, rep_id, next),
                .erased_callable => return try self.assignStringBytesLiteral(target, "<function>", next),
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                => return try self.assignStringBytesLiteral(target, "<opaque>", next),
                .list => return try self.beginListInspect(frames, request),
                .box => {
                    const payload_rep = self.repQuery().requiredSingleChild(rep_id, .box_payload).rep;
                    const payload = try self.addFrameLocalForRep(payload_rep);
                    const prefix = try self.addFrameLocal(.str);
                    const rendered = try self.addFrameLocal(.str);
                    const with_value = try self.addFrameLocal(.str);
                    const suffix = try self.addFrameLocal(.str);

                    var continuation = try self.assignStrConcat(target, with_value, suffix, next);
                    continuation = try self.assignStringBytesLiteral(suffix, ")", continuation);
                    continuation = try self.assignStrConcat(with_value, prefix, rendered, continuation);
                    return try self.pushInspectFrameFirst(
                        frames,
                        .{ .box = .{ .request = request, .payload_rep = payload_rep, .payload = payload, .prefix = prefix } },
                        .{ .target = rendered, .source = payload, .rep_id = payload_rep, .next = continuation },
                    );
                },
                .primitive => |primitive| return try self.lowerPrimitiveInspectLocalsInto(target, source, rep_id, primitive, next),
                .bool_tag_union => return try self.lowerBoolInspectLocalsInto(target, source, next),
                .empty_record => return try self.assignStringBytesLiteral(target, "{}", next),
                .empty_tag_union => return try self.parent.result.store.addCFStmt(.{ .crash = .{
                    .msg = .{ .literal = try self.parent.result.store.insertString("uninhabited value reached Str.inspect") },
                } }, self.derivedOrigin()),
                .alias => {
                    request.rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep;
                    continue;
                },
                .nominal => |kind| switch (kind) {
                    .transparent => {
                        if (try self.lowerToInspectMethodInto(target, source, rep_id, next)) |method_call| return method_call;
                        return try self.beginNominalInspect(frames, request);
                    },
                    .opaque_nominal => return try self.lowerToInspectMethodInto(target, source, rep_id, next) orelse
                        try self.assignStringBytesLiteral(target, "<opaque>", next),
                    .builtin_other => return try self.beginNominalInspect(frames, request),
                },
                .record => return try self.beginRecordInspect(frames, request),
                .tuple => return try self.beginTupleInspect(frames, request),
                .tag_union => {
                    if (rep.presence_slot_present_discriminant != null) return try self.beginPresenceSlotInspect(frames, request);
                    if (self.tagUnionRepHasExtension(rep)) return try self.lowerDescriptorInspectLocalsInto(target, source, rep_id, next);
                    return try self.beginTagUnionInspect(frames, request);
                },
            }
        }
    }

    fn beginNominalInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), request: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        const scope = try self.enterNominalBackingFormalScope(request.rep_id);
        errdefer self.dropNominalBackingFormalScope(scope);
        const backing_rep = self.repQuery().requiredSingleChild(request.rep_id, .nominal_backing).rep;
        const backing: ?LIR.LocalId = if (self.parent.plan.representations.items[@backingInt(request.rep_id)].declared_fields.len == 0)
            null
        else
            try self.addFrameLocalForRep(backing_rep);
        try frames.append(self.parent.allocator, .{ .state = .{ .nominal = .{
            .request = request,
            .scope = scope,
            .backing_rep = backing_rep,
            .backing = backing,
        } } });
        return null;
    }

    /// Begin rendering `parts` into `target` before `next`: the statement
    /// when every part is a literal, or null with the parts frame pushed.
    fn beginInspectParts(self: *ProcBodyBuilder, target: LIR.LocalId, parts: []const InspectPart, next: LIR.CFStmtId) Allocator.Error!InspectPartsState {
        const allocator = self.parent.allocator;
        const owned_parts = try allocator.dupe(InspectPart, parts);
        errdefer allocator.free(owned_parts);
        const part_locals = try allocator.alloc(LIR.LocalId, parts.len);
        errdefer allocator.free(part_locals);
        for (part_locals) |*local| {
            local.* = try self.addFrameLocal(.str);
        }
        return .{
            .target = target,
            .parts = owned_parts,
            .part_locals = part_locals,
            .remaining = parts.len,
            .continuation = try self.concatStringLocalsInto(target, part_locals, next),
        };
    }

    /// Advance a parts rendering: the next part's component rendering, or
    /// null once every part is rendered.
    fn nextInspectPart(self: *ProcBodyBuilder, state: *InspectPartsState, delivered: ?LIR.CFStmtId) Allocator.Error!?InspectRequest {
        if (delivered) |rendered| {
            var continuation = rendered;
            const value = state.pending_value;
            if (!self.isZstLocal(value)) {
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = value,
                    .op = switch (state.parts[state.remaining]) {
                        .literal => unreachable,
                        .field => |field| .{ .field = .{
                            .source = field.source,
                            .field_idx = field.field_index,
                        } },
                        .tag_payload => |payload| if (payload.payload_index) |index| .{ .tag_payload = .{
                            .source = payload.source,
                            .payload_idx = index,
                            .variant_index = payload.variant_index,
                            .tag_discriminant = payload.variant_index,
                        } } else .{ .tag_payload_struct = .{
                            .source = payload.source,
                            .variant_index = payload.variant_index,
                            .tag_discriminant = payload.variant_index,
                        } },
                    },
                    .next = continuation,
                } }, self.derivedOrigin());
            }
            state.continuation = continuation;
        }
        while (state.remaining > 0) {
            state.remaining -= 1;
            const part_local = state.part_locals[state.remaining];
            switch (state.parts[state.remaining]) {
                .literal => |text| state.continuation = try self.assignStringBytesLiteral(part_local, text, state.continuation),
                .field => |field| {
                    state.pending_value = try self.addFrameLocalForRep(field.rep);
                    return .{ .target = part_local, .source = state.pending_value, .rep_id = field.rep, .next = state.continuation };
                },
                .tag_payload => |payload| {
                    state.pending_value = try self.addFrameLocalForRep(payload.rep);
                    return .{ .target = part_local, .source = state.pending_value, .rep_id = payload.rep, .next = state.continuation };
                },
            }
        }
        return null;
    }

    fn beginRecordInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), request: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@backingInt(request.rep_id)];
        const children = self.parent.plan.childSlice(rep.children);
        const field_count = recordEqualityFieldCount(children);
        if (field_count == 0) return try self.assignStringBytesLiteral(request.target, "{}", request.next);

        var parts = std.ArrayList(InspectPart).empty;
        defer parts.deinit(self.parent.allocator);
        try parts.append(self.parent.allocator, .{ .literal = "{ " });

        var field_index: u32 = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => |label| {
                    if (field_index != 0) try parts.append(self.parent.allocator, .{ .literal = ", " });
                    try parts.append(self.parent.allocator, .{ .literal = self.module.canonical_names.recordFieldLabelText(label) });
                    try parts.append(self.parent.allocator, .{ .literal = ": " });
                    try parts.append(self.parent.allocator, .{ .field = .{
                        .source = request.source,
                        .field_index = field_index,
                        .rep = child.rep,
                    } });
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record inspect representation had a non-record child role"),
            }
        }
        try parts.append(self.parent.allocator, .{ .literal = " }" });
        return try self.pushInspectFrame(frames, .{ .parts = try self.beginInspectParts(request.target, parts.items, request.next) });
    }

    fn beginTupleInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), request: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@backingInt(request.rep_id)];
        const children = self.parent.plan.childSlice(rep.children);
        if (children.len == 0) return try self.assignStringBytesLiteral(request.target, "()", request.next);

        var parts = std.ArrayList(InspectPart).empty;
        defer parts.deinit(self.parent.allocator);
        try parts.append(self.parent.allocator, .{ .literal = "(" });
        for (children, 0..) |child, ordinal| {
            switch (child.role) {
                .tuple_elem => |index| {
                    if (ordinal != 0) try parts.append(self.parent.allocator, .{ .literal = ", " });
                    if (index > std.math.maxInt(u32)) {
                        boxyLowerInvariant("tuple inspect element index exceeded LIR field index range");
                    }
                    try parts.append(self.parent.allocator, .{ .field = .{
                        .source = request.source,
                        .field_index = @intCast(index),
                        .rep = child.rep,
                    } });
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple inspect representation had a non-tuple child role"),
            }
        }
        try parts.append(self.parent.allocator, .{ .literal = ")" });
        return try self.pushInspectFrame(frames, .{ .parts = try self.beginInspectParts(request.target, parts.items, request.next) });
    }

    /// A tag variant's rendering: its name alone, or a parts rendering of
    /// its name and payloads.
    fn beginTagInspectVariant(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        variant: Plan.TagVariant,
        variant_index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!union(enum) { done: LIR.CFStmtId, parts: InspectPartsState } {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        if (payloads.len == 0) {
            return .{ .done = try self.assignStringBytesLiteral(target, self.tagVariantNameText(variant), next) };
        }

        var parts = std.ArrayList(InspectPart).empty;
        defer parts.deinit(self.parent.allocator);
        try parts.append(self.parent.allocator, .{ .literal = self.tagVariantNameText(variant) });
        try parts.append(self.parent.allocator, .{ .literal = "(" });
        for (payloads, 0..) |child, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("tag inspect payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag inspect variant payload span included a non-payload child"),
            }
            if (index != 0) try parts.append(self.parent.allocator, .{ .literal = ", " });
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("tag inspect payload index exceeded LIR payload index range");
            }
            try parts.append(self.parent.allocator, .{ .tag_payload = .{
                .source = source,
                .variant_index = variant_index,
                .payload_index = if (payloads.len == 1) null else @as(u32, @intCast(index)),
                .rep = child.rep,
            } });
        }
        try parts.append(self.parent.allocator, .{ .literal = ")" });
        return .{ .parts = try self.beginInspectParts(target, parts.items, next) };
    }

    fn beginTagUnionInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), request: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@backingInt(request.rep_id)];
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        if (variants.len == 0) {
            return try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString("uninhabited value reached Str.inspect") },
            } }, self.derivedOrigin());
        }
        if (variants.len == 1 and self.isZstLocal(request.source)) {
            return switch (try self.beginTagInspectVariant(request.target, request.source, variants[0], 0, request.next)) {
                .done => |stmt| stmt,
                .parts => |parts| try self.pushInspectFrame(frames, .{ .parts = parts }),
            };
        }

        const discriminant = try self.addFrameLocal(.u32);
        const done = self.freshJoinPointId();
        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
        return try self.pushInspectFrame(frames, .{ .tag = .{
            .request = request,
            .discriminant = discriminant,
            .done = done,
            .branches = branches,
        } });
    }

    fn beginPresenceSlotInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), request: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@backingInt(request.rep_id)];
        const present_discriminant = rep.presence_slot_present_discriminant orelse
            boxyLowerInvariant("presence-slot inspect lacked its Present discriminant");
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        const present_index: usize = present_discriminant;
        if (variants.len != 2 or present_index >= variants.len) {
            boxyLowerInvariant("presence-slot inspect did not have exactly two variants");
        }
        const present_payloads = self.parent.plan.childSlice(variants[present_index].payloads);
        if (present_payloads.len != 1) {
            boxyLowerInvariant("presence-slot inspect Present arm did not have one payload");
        }
        const payload_child = present_payloads[0];
        switch (payload_child.role) {
            .tag_payload => |payload| if (payload.tag != variants[present_index].name or payload.index != 0) {
                boxyLowerInvariant("presence-slot inspect payload did not match its Present variant");
            },
            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("presence-slot inspect Present arm had a non-payload child"),
        }

        const missing_discriminant: u32 = if (present_discriminant == 0) 1 else 0;
        if (variants[missing_discriminant].payloads.len != 0) {
            boxyLowerInvariant("presence-slot inspect Missing arm carried a payload");
        }

        const done = self.freshJoinPointId();
        const jump = try self.joinJump(done);
        const value = try self.addFrameLocalForRep(payload_child.rep);
        return try self.pushInspectFrameFirst(frames, .{ .presence = .{
            .request = request,
            .done = done,
            .present_discriminant = present_discriminant,
            .missing_discriminant = missing_discriminant,
            .value = value,
        } }, .{ .target = request.target, .source = value, .rep_id = payload_child.rep, .next = jump });
    }

    fn beginListInspect(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), request: InspectRequest) Allocator.Error!?LIR.CFStmtId {
        const elem_rep = self.repQuery().requiredSingleChild(request.rep_id, .list_elem).rep;
        const len = try self.addFrameLocal(.u64);
        const index = try self.addFrameLocal(.u64);
        const out = try self.addFrameLocal(.str);
        const zero_index = try self.addFrameLocal(.u64);
        const initial_out = try self.addFrameLocal(.str);
        const join_id = self.freshJoinPointId();

        const done = try self.addFrameLocal(.bool);
        const finish = try self.lowerListInspectFinish(request.target, out, request.next);

        const sep = try self.addFrameLocal(.str);
        const zero = try self.addFrameLocal(.u64);
        const is_first = try self.addFrameLocal(.bool);
        const elem = try self.addFrameLocalForRep(elem_rep);
        const elem_str = try self.addFrameLocal(.str);
        const with_sep = try self.addFrameLocal(.str);
        const next_out = try self.addFrameLocal(.str);
        const one = try self.addFrameLocal(.u64);
        const next_index = try self.addFrameLocal(.u64);

        var continuation = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, self.derivedOrigin());
        continuation = try self.setLocalInitializeJoinParam(out, next_out, continuation);
        continuation = try self.setLocalInitializeJoinParam(index, next_index, continuation);
        continuation = try self.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, continuation);
        continuation = try self.assignIntLiteral(one, 1, continuation);
        continuation = try self.assignStrConcat(next_out, with_sep, elem_str, continuation);
        return try self.pushInspectFrameFirst(frames, .{ .list = .{
            .request = request,
            .elem = elem,
            .index = index,
            .out = out,
            .len = len,
            .zero_index = zero_index,
            .initial_out = initial_out,
            .join_id = join_id,
            .done = done,
            .finish = finish,
            .sep = sep,
            .zero = zero,
            .is_first = is_first,
            .with_sep = with_sep,
        } }, .{ .target = elem_str, .source = elem, .rep_id = elem_rep, .next = continuation });
    }

    fn stepInspectFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(InspectFrame), delivered: ?LIR.CFStmtId) Allocator.Error!InspectStep {
        const frame = &frames.items[frames.items.len - 1];
        if (frame.first) |first| {
            frame.first = null;
            frame.awaiting = true;
            return .{ .request = first };
        }
        const child: ?LIR.CFStmtId = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("boxy inspect frame resumed without its component rendering")
        else
            null;
        frame.awaiting = false;
        switch (frame.state) {
            .nominal => |nominal| {
                const request = nominal.request;
                const rendered = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{ .target = request.target, .source = nominal.backing orelse request.source, .rep_id = nominal.backing_rep, .next = request.next } };
                };
                const lowered = if (nominal.backing) |backing|
                    try self.assignRepresentationBoundary(backing, request.source, nominal.backing_rep, request.rep_id, rendered)
                else
                    rendered;
                return self.finishInspectFrame(frames, try self.leaveNominalBackingFormalScope(nominal.scope, lowered));
            },
            .parts => |*parts| {
                if (try self.nextInspectPart(parts, child)) |request| {
                    frame.awaiting = true;
                    return .{ .request = request };
                }
                return self.finishInspectFrame(frames, parts.continuation);
            },
            .tag => |*tag| {
                const request = tag.request;
                const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(request.rep_id)].tag_variants);
                var delivered_part = child;
                while (true) {
                    if (tag.variant) |*variant| {
                        if (try self.nextInspectPart(variant, delivered_part)) |component| {
                            frame.awaiting = true;
                            return .{ .request = component };
                        }
                        tag.branches[tag.index] = .{ .value = @intCast(tag.index), .body = variant.continuation };
                        variant.deinit(self.parent.allocator);
                        tag.variant = null;
                        tag.index += 1;
                    }
                    delivered_part = null;
                    if (tag.index == variants.len) break;
                    if (tag.index > std.math.maxInt(u32)) {
                        boxyLowerInvariant("tag inspect variant index exceeded LIR variant range");
                    }
                    switch (try self.beginTagInspectVariant(request.target, request.source, variants[tag.index], @intCast(tag.index), try self.joinJump(tag.done))) {
                        .done => |stmt| {
                            tag.branches[tag.index] = .{ .value = @intCast(tag.index), .body = stmt };
                            tag.index += 1;
                        },
                        .parts => |parts| tag.variant = parts,
                    }
                }
                const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error, self.derivedOrigin());
                const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
                    .cond = tag.discriminant,
                    .branches = try self.parent.result.store.addCFSwitchBranches(tag.branches),
                    .default_branch = bad_discriminant,
                    .continuation = null,
                } }, self.derivedOrigin());
                const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = tag.discriminant,
                    .op = .{ .discriminant = .{ .source = request.source } },
                    .next = switch_stmt,
                } }, self.derivedOrigin());
                return self.finishInspectFrame(frames, try self.derivedResultJoin(tag.done, request.target, request.next, read_discriminant));
            },
            .presence => |presence| {
                const request = presence.request;
                var present_body = child.?;
                if (!self.isZstLocal(presence.value)) {
                    present_body = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                        .target = presence.value,
                        .op = .{ .tag_payload_struct = .{
                            .source = request.source,
                            .variant_index = presence.present_discriminant,
                            .tag_discriminant = presence.present_discriminant,
                        } },
                        .next = present_body,
                    } }, self.derivedOrigin());
                }
                const missing_body = try self.assignStringBytesLiteral(request.target, "<missing>", try self.joinJump(presence.done));
                const branches = [_]LIR.CFSwitchBranch{
                    .{ .value = presence.missing_discriminant, .body = missing_body },
                    .{ .value = presence.present_discriminant, .body = present_body },
                };
                const discriminant = try self.addFrameLocal(.u32);
                const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
                    .cond = discriminant,
                    .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
                    .default_branch = try self.parent.result.store.addCFStmt(.runtime_error, self.derivedOrigin()),
                    .continuation = null,
                } }, self.derivedOrigin());
                const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = discriminant,
                    .op = .{ .discriminant = .{ .source = request.source } },
                    .next = switch_stmt,
                } }, self.derivedOrigin());
                return self.finishInspectFrame(frames, try self.derivedResultJoin(presence.done, request.target, request.next, read_discriminant));
            },
            .box => |box| {
                const request = box.request;
                var continuation = try self.assignBoxBoundary(
                    box.payload,
                    request.source,
                    box.payload_rep,
                    .box_unbox,
                    child.?,
                );
                continuation = try self.assignStringBytesLiteral(box.prefix, "Box(", continuation);
                return self.finishInspectFrame(frames, continuation);
            },
            .list => |list| {
                const request = list.request;
                var continuation = child.?;
                if (!self.isZstLocal(list.elem)) {
                    continuation = try self.assignBinaryLowLevel(list.elem, .list_get_unsafe, request.source, list.index, continuation);
                }
                continuation = try self.assignStrConcat(list.with_sep, list.out, list.sep, continuation);

                const empty_sep = try self.assignStringBytesLiteral(list.sep, "", continuation);
                const comma_sep = try self.assignStringBytesLiteral(list.sep, ", ", continuation);
                const sep_switch = try self.boolSwitchNoContinuation(list.is_first, empty_sep, comma_sep);
                const compare_first = try self.assignBinaryLowLevel(list.is_first, .num_is_eq, list.index, list.zero, sep_switch);
                const step = try self.assignIntLiteral(list.zero, 0, compare_first);

                const switch_stmt = try self.boolSwitchNoContinuation(list.done, list.finish, step);
                const body = try self.assignBinaryLowLevel(list.done, .num_is_eq, list.index, list.len, switch_stmt);

                var initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = list.join_id } }, self.derivedOrigin());
                initial_jump = try self.setLocalInitializeJoinParam(list.out, list.initial_out, initial_jump);
                initial_jump = try self.setLocalInitializeJoinParam(list.index, list.zero_index, initial_jump);
                initial_jump = try self.assignStringBytesLiteral(list.initial_out, "[", initial_jump);
                initial_jump = try self.assignIntLiteral(list.zero_index, 0, initial_jump);
                initial_jump = try self.assignUnaryLowLevel(list.len, .list_len, request.source, initial_jump);

                return self.finishInspectFrame(frames, try self.parent.result.store.addCFStmt(.{ .join = .{
                    .id = list.join_id,
                    .params = try self.joinParamSpan(&[_]LIR.LocalId{ list.index, list.out }),
                    .body = body,
                    .remainder = initial_jump,
                } }, self.derivedOrigin()));
            },
        }
    }

    fn lowerToInspectMethodInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const worker_id = self.parent.inspectOverrideWorkerForRep(rep_id) orelse return null;
        return try self.lowerToInspectWorkerInto(target, source, worker_id, next);
    }

    fn lowerToInspectWorkerInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        worker_id: Plan.WorkerPlanId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.parent.plan.workers.items[@backingInt(worker_id)];
        if (worker.hidden_descs.len != 0 or worker.hidden_dicts.len != 0) {
            boxyLowerInvariant("boxy to_inspect method worker carried hidden parameters");
        }

        const function = checkedFunctionPayload(procedureModuleById(self.parent.modules, worker.checked_type.module), worker.checked_type.ty);
        if (function.args.len != 1) {
            boxyLowerInvariant("boxy to_inspect method worker had unexpected arity");
        }
        const arg_types = [_]Plan.CheckedTypeIdentity{.{ .module = worker.checked_type.module, .ty = function.args[0] }};
        const source_args = [_]LIR.LocalId{source};
        const call = try self.lowerWorkerCallLocalsInto(
            target,
            .{ .module = worker.checked_type.module, .ty = function.ret },
            &arg_types,
            &arg_types,
            &source_args,
            null,
            null,
            null,
            worker_id,
            &.{},
            &.{},
            next,
        );
        return call;
    }

    /// Feed `value` into `hasher` by `rep_id`'s descriptor at runtime.
    fn lowerDescriptorHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const desc = try self.descriptorRefForSourceLocalRep(value, rep_id);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_hash = .{
            .target = target,
            .value = value,
            .hasher = hasher,
            .desc = desc,
            .next = next,
        } }, self.derivedOrigin());
    }

    /// Compare `lhs` and `rhs`, which share `rep_id`'s descriptor, by that
    /// descriptor at runtime.
    fn lowerDescriptorEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const desc = try self.descriptorRefForSourceLocalRep(lhs, rep_id);
        const raw = if (negated) try self.addFrameLocal(.bool) else target;
        const after = if (negated) try self.negateBoolInto(target, raw, next) else next;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_eq = .{
            .target = raw,
            .lhs = lhs,
            .rhs = rhs,
            .desc = desc,
            .next = after,
        } }, self.derivedOrigin());
    }

    fn lowerDescriptorInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_desc = try self.descriptorRefForSourceLocalRep(source, rep_id);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_inspect = .{
            .target = target,
            .source = source,
            .source_desc = source_desc,
            .source_mode = .borrow,
            .next = next,
        } }, self.derivedOrigin());
    }

    fn tagUnionRepHasExtension(self: *const ProcBodyBuilder, rep: Plan.TypeRepresentation) bool {
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role == .tag_ext) return true;
        }
        return false;
    }

    fn lowerPrimitiveInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        primitive: checked.CheckedPrimitive,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const op = switch (Common.primitiveInspectLowering(primitive)) {
            .low_level => |op| op,
            .bool_tag_union => return try self.lowerBoolInspectLocalsInto(target, source, next),
            .builtin_method => {
                const method = self.parent.plan.descriptorMethodForRep(rep_id, .inspect) orelse
                    boxyLowerInvariant("primitive inspect had no planned to_inspect worker");
                return try self.lowerToInspectWorkerInto(target, source, method.worker, next);
            },
        };
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = op,
            .rc_effect = op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{source}),
            .next = next,
        } }, self.derivedOrigin());
    }

    fn lowerBoolInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const false_body = try self.assignStringBytesLiteral(target, "False", next);
        const true_body = try self.assignStringBytesLiteral(target, "True", next);
        const discriminant = try self.addFrameLocal(.u32);
        const branches = [_]LIR.CFSwitchBranch{.{ .value = Common.bool_true_discriminant, .body = true_body }};
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = false_body,
            .continuation = null,
        } }, self.derivedOrigin());
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } }, self.derivedOrigin());
    }

    fn lowerListInspectFinish(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        out: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const close = try self.addFrameLocal(.str);
        const concat = try self.assignStrConcat(target, out, close, next);
        return try self.assignStringBytesLiteral(close, "]", concat);
    }

    fn concatStringLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        parts: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        switch (parts.len) {
            0 => return try self.assignStringBytesLiteral(target, "", next),
            1 => return try self.assignLocal(target, parts[0], next),
            else => {},
        }

        const concat_results = try self.parent.allocator.alloc(LIR.LocalId, parts.len - 1);
        defer self.parent.allocator.free(concat_results);
        for (concat_results[0 .. concat_results.len - 1]) |*local| {
            local.* = try self.addFrameLocal(.str);
        }
        concat_results[concat_results.len - 1] = target;

        var continuation = next;
        var concat_index = concat_results.len;
        while (concat_index > 0) {
            concat_index -= 1;
            const lhs = if (concat_index == 0) parts[0] else concat_results[concat_index - 1];
            const rhs = parts[concat_index + 1];
            continuation = try self.assignStrConcat(concat_results[concat_index], lhs, rhs, continuation);
        }
        return continuation;
    }

    fn assignStrConcat(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .str_concat,
            .rc_effect = LIR.LowLevel.str_concat.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ lhs, rhs }),
            .next = next,
        } }, self.origin);
    }

    // Structural equality //
    //
    // Equality over a representation compares its components, and components
    // follow type nesting, so each comparison still waiting on a component's
    // comparison is a frame on one heap-backed stack. Comparisons are built
    // from their continuation backward; frames allocate locals, join points,
    // and statements in the order a direct recursive build would.

    const EqRequest = struct {
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    };

    const EqStep = union(enum) {
        /// The frame needs this component comparison next.
        request: EqRequest,
        /// The frame finished with this statement and was popped.
        done: LIR.CFStmtId,
    };

    /// A comparison waiting on its components' comparisons.
    const EqFrame = struct {
        /// Whether the frame's last requested comparison is still due.
        awaiting: bool = false,
        state: union(enum) {
            /// Compare at another representation, then convert both
            /// operands into it.
            convert: struct { request: EqRequest, lhs_actual: LIR.LocalId, rhs_actual: LIR.LocalId, actual: Plan.TypeRepId },
            /// Compare the box payloads, then unbox both operands.
            unbox: struct { request: EqRequest, lhs_payload: LIR.LocalId, rhs_payload: LIR.LocalId, payload_rep: Plan.TypeRepId },
            nominal: struct {
                request: EqRequest,
                scope: NominalBackingFormalScope,
                backing_rep: Plan.TypeRepId,
                /// The backing operands, when the nominal's declared fields
                /// store differently from its backing.
                backing: ?struct { lhs: LIR.LocalId, rhs: LIR.LocalId } = null,
            },
            /// A record's fields or a tuple's elements, last first.
            fields: struct {
                request: EqRequest,
                kind: enum { record, tuple },
                done: LIR.JoinPointId,
                current: LIR.CFStmtId,
                failed: LIR.CFStmtId,
                remaining: usize,
                field_index: u32,
                pending: struct { lhs_field: LIR.LocalId, rhs_field: LIR.LocalId, field_index: u32 } = undefined,
            },
            tag: *EqTagState,
        },
    };

    /// A tag union comparison: one switch branch per variant, each comparing
    /// its payloads last first.
    const EqTagState = struct {
        request: EqRequest,
        done: LIR.JoinPointId,
        success: LIR.CFStmtId,
        failed: LIR.CFStmtId,
        lhs_disc: LIR.LocalId,
        rhs_disc: LIR.LocalId,
        same_disc: LIR.LocalId,
        branches: []LIR.CFSwitchBranch,
        variant: usize = 0,
        /// The current variant's payloads still to compare.
        remaining: usize = 0,
        started: bool = false,
        current: LIR.CFStmtId = undefined,
        source_has_payload_desc: bool = false,
        pending: struct { child: Plan.RepChild, lhs_payload: ExtractedTagPayloadLocal, rhs_payload: ExtractedTagPayloadLocal, index: usize } = undefined,
    };

    fn lowerEqRepLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const allocator = self.parent.allocator;
        var frames: std.ArrayList(EqFrame) = .empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseEqFrame(&frames.items[index]);
            }
            frames.deinit(allocator);
        }
        var value = try self.beginEq(&frames, .{ .target = target, .lhs = lhs, .rhs = rhs, .rep_id = rep_id, .negated = negated, .next = next });
        while (frames.items.len != 0) {
            switch (try self.stepEqFrame(&frames, value)) {
                .request => |request| value = try self.beginEq(&frames, request),
                .done => |stmt| value = stmt,
            }
        }
        return value.?;
    }

    /// Free what an unfinished frame owns and leave the scope it holds, as
    /// the direct build's defers would.
    fn releaseEqFrame(self: *ProcBodyBuilder, frame: *EqFrame) void {
        switch (frame.state) {
            .convert, .unbox, .fields => {},
            .nominal => |nominal| self.dropNominalBackingFormalScope(nominal.scope),
            .tag => |state| {
                self.parent.allocator.free(state.branches);
                self.parent.allocator.destroy(state);
            },
        }
    }

    /// The comparison of `request` when it needs no component comparison;
    /// otherwise null, with the frame that builds it pushed.
    fn beginEq(self: *ProcBodyBuilder, frames: *std.ArrayList(EqFrame), root: EqRequest) Allocator.Error!?LIR.CFStmtId {
        var request = root;
        while (true) {
            const target = request.target;
            const lhs = request.lhs;
            const rhs = request.rhs;
            const rep_id = request.rep_id;
            const negated = request.negated;
            const next = request.next;
            switch (try self.derivedStep(.equality, rep_id)) {
                .expand => {},
                .call => |index| return try self.lowerDerivedEqCallInto(target, lhs, rhs, index, negated, next),
                .scheme_dictionary => |requirement| return try self.lowerDerivedEqDictionaryCallInto(target, lhs, rhs, rep_id, requirement, negated, next),
                .descriptor => return try self.lowerDescriptorEqLocalsInto(target, lhs, rhs, rep_id, negated, next),
                .checked_error => return try self.lowerCheckedErrorDispatchInto("method dispatch failed to check"),
                .helper => {
                    if (!negated) return try self.lowerDerivedHelperCallInto(.equality, target, lhs, rhs, rep_id, next);
                    const raw = try self.addFrameLocal(.bool);
                    return try self.lowerDerivedHelperCallInto(.equality, raw, lhs, rhs, rep_id, try self.negateBoolInto(target, raw, next));
                },
                .convert => |actual| {
                    const lhs_actual = try self.addFrameLocalForRep(actual);
                    const rhs_actual = try self.addFrameLocalForRep(actual);
                    return try self.pushEqFrame(frames, .{ .convert = .{ .request = request, .lhs_actual = lhs_actual, .rhs_actual = rhs_actual, .actual = actual } });
                },
                .unbox => |payload_rep| {
                    const lhs_payload = try self.addFrameLocalForRep(payload_rep);
                    const rhs_payload = try self.addFrameLocalForRep(payload_rep);
                    return try self.pushEqFrame(frames, .{ .unbox = .{ .request = request, .lhs_payload = lhs_payload, .rhs_payload = rhs_payload, .payload_rep = payload_rep } });
                },
            }
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            switch (rep.kind) {
                .in_progress => boxyLowerInvariant("in-progress boxy representation reached structural equality lowering"),
                .erased_callable => boxyLowerInvariant("erased callable structural equality reached boxy lowering"),
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                => boxyLowerInvariant("compiler-owned encoding evidence reached structural equality lowering"),
                .dynamic,
                .list,
                .box,
                => boxyLowerInvariant("derived equality expanded a component its step dispatches"),
                .primitive => |primitive| return try self.lowerPrimitiveEqLocalsInto(target, lhs, rhs, primitive, negated, next),
                .bool_tag_union => return try self.lowerBoolEqLocalsInto(target, lhs, rhs, negated, next),
                .empty_record,
                .empty_tag_union,
                => return try self.assignBoolLiteral(target, !negated, next),
                .alias => {
                    request.rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep;
                    continue;
                },
                .nominal => {
                    const scope = try self.enterNominalBackingFormalScope(rep_id);
                    errdefer self.dropNominalBackingFormalScope(scope);
                    const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
                    const backing: @FieldType(@FieldType(@FieldType(EqFrame, "state"), "nominal"), "backing") = if (rep.declared_fields.len == 0) null else backing: {
                        const backing_layout = self.workerRuntimeLayoutForRep(backing_rep).layoutIdx();
                        const lhs_backing = try self.addFrameLocal(backing_layout);
                        const rhs_backing = try self.addFrameLocal(backing_layout);
                        break :backing .{ .lhs = lhs_backing, .rhs = rhs_backing };
                    };
                    try frames.append(self.parent.allocator, .{ .state = .{ .nominal = .{
                        .request = request,
                        .scope = scope,
                        .backing_rep = backing_rep,
                        .backing = backing,
                    } } });
                    return null;
                },
                .record, .tuple => {
                    const done = self.freshJoinPointId();
                    const current = try self.assignBoolLiteral(target, !negated, try self.joinJump(done));
                    const failed = try self.assignBoolLiteral(target, negated, try self.joinJump(done));
                    const children = self.parent.plan.childSlice(rep.children);
                    return try self.pushEqFrame(frames, .{ .fields = .{
                        .request = request,
                        .kind = if (rep.kind == .record) .record else .tuple,
                        .done = done,
                        .current = current,
                        .failed = failed,
                        .remaining = children.len,
                        .field_index = if (rep.kind == .record) recordEqualityFieldCount(children) else 0,
                    } });
                },
                .tag_union => {
                    if (self.isZstLocal(lhs) and self.isZstLocal(rhs)) {
                        return try self.assignBoolLiteral(target, !negated, next);
                    }
                    const done = self.freshJoinPointId();
                    const success = try self.assignBoolLiteral(target, !negated, try self.joinJump(done));
                    const failed = try self.assignBoolLiteral(target, negated, try self.joinJump(done));
                    const lhs_disc = try self.addFrameLocal(.u32);
                    const rhs_disc = try self.addFrameLocal(.u32);
                    const same_disc = try self.addFrameLocal(.bool);
                    const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                    const state = try self.parent.allocator.create(EqTagState);
                    errdefer self.parent.allocator.destroy(state);
                    const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
                    state.* = .{
                        .request = request,
                        .done = done,
                        .success = success,
                        .failed = failed,
                        .lhs_disc = lhs_disc,
                        .rhs_disc = rhs_disc,
                        .same_disc = same_disc,
                        .branches = branches,
                    };
                    return try self.pushEqFrame(frames, .{ .tag = state });
                },
            }
        }
    }

    fn pushEqFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(EqFrame), state: @FieldType(EqFrame, "state")) Allocator.Error!?LIR.CFStmtId {
        var frame: EqFrame = .{ .state = state };
        frames.append(self.parent.allocator, frame) catch |err| {
            self.releaseEqFrame(&frame);
            return err;
        };
        return null;
    }

    fn finishEqFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(EqFrame), stmt: LIR.CFStmtId) EqStep {
        var frame = frames.pop().?;
        switch (frame.state) {
            // A finished nominal comparison has left its scope already.
            .nominal => {},
            .convert, .unbox, .fields, .tag => self.releaseEqFrame(&frame),
        }
        return .{ .done = stmt };
    }

    fn stepEqFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(EqFrame), delivered: ?LIR.CFStmtId) Allocator.Error!EqStep {
        const frame = &frames.items[frames.items.len - 1];
        const child: ?LIR.CFStmtId = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("boxy equality frame resumed without its component comparison")
        else
            null;
        frame.awaiting = false;
        switch (frame.state) {
            .convert => |convert| {
                const request = convert.request;
                const continuation = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{ .target = request.target, .lhs = convert.lhs_actual, .rhs = convert.rhs_actual, .rep_id = convert.actual, .negated = request.negated, .next = request.next } };
                };
                const after_rhs = try self.assignRepresentationBoundary(convert.rhs_actual, request.rhs, convert.actual, request.rep_id, continuation);
                return self.finishEqFrame(frames, try self.assignRepresentationBoundary(convert.lhs_actual, request.lhs, convert.actual, request.rep_id, after_rhs));
            },
            .unbox => |unbox| {
                const request = unbox.request;
                const continuation = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{ .target = request.target, .lhs = unbox.lhs_payload, .rhs = unbox.rhs_payload, .rep_id = unbox.payload_rep, .negated = request.negated, .next = request.next } };
                };
                const after_rhs = try self.assignBoxBoundary(unbox.rhs_payload, request.rhs, unbox.payload_rep, .box_unbox, continuation);
                return self.finishEqFrame(frames, try self.assignBoxBoundary(unbox.lhs_payload, request.lhs, unbox.payload_rep, .box_unbox, after_rhs));
            },
            .nominal => |nominal| {
                const request = nominal.request;
                const lowered_child = child orelse {
                    frame.awaiting = true;
                    const operands = nominal.backing orelse return .{ .request = .{ .target = request.target, .lhs = request.lhs, .rhs = request.rhs, .rep_id = nominal.backing_rep, .negated = request.negated, .next = request.next } };
                    return .{ .request = .{ .target = request.target, .lhs = operands.lhs, .rhs = operands.rhs, .rep_id = nominal.backing_rep, .negated = request.negated, .next = request.next } };
                };
                const lowered = if (nominal.backing) |operands| lowered: {
                    const after_rhs = try self.assignRepresentationBoundary(operands.rhs, request.rhs, nominal.backing_rep, request.rep_id, lowered_child);
                    break :lowered try self.assignRepresentationBoundary(operands.lhs, request.lhs, nominal.backing_rep, request.rep_id, after_rhs);
                } else lowered_child;
                const stmt = try self.leaveNominalBackingFormalScope(nominal.scope, lowered);
                return self.finishEqFrame(frames, stmt);
            },
            .fields => |*fields| {
                const request = fields.request;
                if (child) |compare| {
                    var current = compare;
                    const pending = fields.pending;
                    if (!self.isZstLocal(pending.rhs_field)) {
                        current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                            .target = pending.rhs_field,
                            .op = .{ .field = .{
                                .source = request.rhs,
                                .field_idx = pending.field_index,
                            } },
                            .next = current,
                        } }, self.derivedOrigin());
                    }
                    if (!self.isZstLocal(pending.lhs_field)) {
                        current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                            .target = pending.lhs_field,
                            .op = .{ .field = .{
                                .source = request.lhs,
                                .field_idx = pending.field_index,
                            } },
                            .next = current,
                        } }, self.derivedOrigin());
                    }
                    fields.current = current;
                }
                const children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(request.rep_id)].children);
                while (fields.remaining > 0) {
                    fields.remaining -= 1;
                    const field = children[fields.remaining];
                    const field_index: u32 = switch (fields.kind) {
                        .record => switch (field.role) {
                            .record_field => field_index: {
                                fields.field_index -= 1;
                                break :field_index fields.field_index;
                            },
                            .record_ext => {
                                self.requireEmptyRecordExtension(field.rep);
                                continue;
                            },
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record equality representation had a non-record child role"),
                        },
                        .tuple => switch (field.role) {
                            .tuple_elem => |index| field_index: {
                                if (index > std.math.maxInt(u32)) {
                                    boxyLowerInvariant("tuple equality element index exceeded LIR field index range");
                                }
                                break :field_index @intCast(index);
                            },
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple equality representation had a non-tuple child role"),
                        },
                    };
                    const lhs_field = try self.addFrameLocalForRep(field.rep);
                    const rhs_field = try self.addFrameLocalForRep(field.rep);
                    const eq = try self.addFrameLocal(.bool);
                    const on_compared = try self.boolSwitchNoContinuation(eq, fields.current, fields.failed);
                    fields.pending = .{ .lhs_field = lhs_field, .rhs_field = rhs_field, .field_index = field_index };
                    frame.awaiting = true;
                    return .{ .request = .{ .target = eq, .lhs = lhs_field, .rhs = rhs_field, .rep_id = field.rep, .negated = false, .next = on_compared } };
                }
                return self.finishEqFrame(frames, try self.derivedResultJoin(fields.done, request.target, request.next, fields.current));
            },
            .tag => |state| {
                if (child) |compare| try self.finishEqTagPayload(state, compare);
                if (try self.nextEqTagPayload(state)) |request| {
                    frame.awaiting = true;
                    return .{ .request = request };
                }
                return self.finishEqFrame(frames, try self.finishEqTag(state));
            },
        }
    }

    /// The next payload comparison of a tag union comparison, or null once
    /// every variant's branch is built.
    fn nextEqTagPayload(self: *ProcBodyBuilder, state: *EqTagState) Allocator.Error!?EqRequest {
        const request = state.request;
        const rep = self.parent.plan.representations.items[@backingInt(request.rep_id)];
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        while (state.variant < variants.len) {
            const variant = variants[state.variant];
            const payloads = self.parent.plan.childSlice(variant.payloads);
            if (!state.started) {
                if (state.variant > std.math.maxInt(u32)) {
                    boxyLowerInvariant("tag-union equality variant index exceeded LIR variant range");
                }
                state.started = true;
                state.current = state.success;
                state.remaining = payloads.len;
                state.source_has_payload_desc = rep.descriptor != null or
                    self.parent.result.store.getLocal(request.lhs).boxy_desc != null or
                    self.parent.result.store.getLocal(request.rhs).boxy_desc != null;
            }
            if (state.remaining > 0) {
                state.remaining -= 1;
                const i = state.remaining;
                const payload_child = payloads[i];
                switch (payload_child.role) {
                    .tag_payload => |payload| {
                        if (payload.tag != variant.name or payload.index != @as(u32, @intCast(i))) {
                            boxyLowerInvariant("tag equality payload span did not match its payload child roles");
                        }
                    },
                    .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag equality variant payload span included a non-payload child"),
                }
                const lhs_payload = try self.addExtractedTagPayloadLocal(payload_child.rep, state.source_has_payload_desc);
                const rhs_payload = try self.addExtractedTagPayloadLocal(payload_child.rep, state.source_has_payload_desc);
                const eq = try self.addFrameLocal(.bool);
                const on_compared = try self.boolSwitchNoContinuation(eq, state.current, state.failed);
                state.pending = .{ .child = payload_child, .lhs_payload = lhs_payload, .rhs_payload = rhs_payload, .index = i };
                return .{ .target = eq, .lhs = lhs_payload.local, .rhs = rhs_payload.local, .rep_id = payload_child.rep, .negated = false, .next = on_compared };
            }
            state.branches[state.variant] = .{
                .value = @intCast(state.variant),
                .body = state.current,
            };
            state.variant += 1;
            state.started = false;
        }
        return null;
    }

    /// Read one payload pair for its comparison, extending the variant's
    /// branch backward.
    fn finishEqTagPayload(self: *ProcBodyBuilder, state: *EqTagState, compare: LIR.CFStmtId) Allocator.Error!void {
        const request = state.request;
        const rep = self.parent.plan.representations.items[@backingInt(request.rep_id)];
        const variant = self.parent.plan.tagVariantSlice(rep.tag_variants)[state.variant];
        const payloads = self.parent.plan.childSlice(variant.payloads);
        const pending = state.pending;
        if (pending.index > std.math.maxInt(u32)) {
            boxyLowerInvariant("tag equality payload index exceeded LIR payload index range");
        }
        var current = try self.assignConcreteTagPayloadRead(
            pending.rhs_payload.local,
            pending.child.rep,
            pending.rhs_payload.desc_local,
            request.rhs,
            request.rep_id,
            variant.name,
            @intCast(state.variant),
            @intCast(pending.index),
            payloads.len,
            compare,
        );
        current = try self.assignConcreteTagPayloadRead(
            pending.lhs_payload.local,
            pending.child.rep,
            pending.lhs_payload.desc_local,
            request.lhs,
            request.rep_id,
            variant.name,
            @intCast(state.variant),
            @intCast(pending.index),
            payloads.len,
            current,
        );
        state.current = current;
    }

    /// The tag union comparison once every variant's branch is built.
    fn finishEqTag(self: *ProcBodyBuilder, state: *EqTagState) Allocator.Error!LIR.CFStmtId {
        const request = state.request;
        const payload_switch = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = state.lhs_disc,
            .branches = try self.parent.result.store.addCFSwitchBranches(state.branches),
            .default_branch = state.failed,
            .continuation = null,
        } }, self.derivedOrigin());
        const disc_switch = try self.boolSwitchNoContinuation(state.same_disc, payload_switch, state.failed);
        const compare_disc = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = state.same_disc,
            .op = .num_is_eq,
            .rc_effect = LIR.LowLevel.num_is_eq.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ state.lhs_disc, state.rhs_disc }),
            .next = disc_switch,
        } }, self.derivedOrigin());
        const read_rhs = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = state.rhs_disc,
            .op = .{ .discriminant = .{ .source = request.rhs } },
            .next = compare_disc,
        } }, self.derivedOrigin());
        const read_lhs = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = state.lhs_disc,
            .op = .{ .discriminant = .{ .source = request.lhs } },
            .next = read_rhs,
        } }, self.derivedOrigin());
        return try self.derivedResultJoin(state.done, request.target, request.next, read_lhs);
    }

    /// How a derived method handles one component.
    const DerivedStep = union(enum) {
        /// Lower the component's structure in place.
        expand,
        /// Call the component type's own method; see
        /// `ProgramPlan.derived_component_calls`.
        call: u32,
        /// Call through the frame's dictionary for this scheme requirement.
        scheme_dictionary: Plan.DictionaryRequirementId,
        /// Compare or hash by the operands' runtime descriptor.
        descriptor,
        /// Call the recursive helper for this union.
        helper,
        /// Read the component at this representation first: a formal's
        /// actual, or a sealed variable's sealed type.
        convert: Plan.TypeRepId,
        /// Read the box's payload first.
        unbox: Plan.TypeRepId,
        /// The component's own method is a rejected declaration: the
        /// comparison is a checked-error crash.
        checked_error,
    };

    fn derivedStep(self: *ProcBodyBuilder, method: Plan.DerivedMethod, rep_id: Plan.TypeRepId) Allocator.Error!DerivedStep {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        switch (rep.kind) {
            .dynamic => {
                const context = self.derived_context orelse
                    boxyLowerInvariant("derived method reached a type variable outside a derivation");
                // A formal holds its actual, and a sealed variable its sealed
                // type; the value converts straight to what the chain ends at.
                var resolved = rep_id;
                while (true) {
                    const current = self.parent.plan.representations.items[@backingInt(resolved)];
                    if (current.kind != .dynamic) break;
                    if (self.nominalFormalActualAbove(context.bindings_start, resolved)) |actual| {
                        resolved = actual;
                    } else if (current.sealed_default) |sealed| {
                        resolved = sealed;
                    } else break;
                }
                if (resolved != rep_id) return .{ .convert = resolved };
                return derivedDecisionStep(try self.derivedComponentDecisionFor(method, rep_id));
            },
            .list, .nominal => return derivedDecisionStep(try self.derivedComponentDecisionFor(method, rep_id)),
            .box => return .{ .unbox = self.repQuery().requiredSingleChild(rep_id, .box_payload).rep },
            .tag_union => {
                if (self.derived_context == null) return .expand;
                // A recursive helper's own body expands its union once.
                if (self.derived_expanding == rep_id) {
                    self.derived_expanding = null;
                    return .expand;
                }
                return if (try self.parent.repOnRuntimeCycle(rep_id)) .helper else .expand;
            },
            .in_progress,
            .primitive,
            .bool_tag_union,
            .erased_callable,
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            .empty_record,
            .alias,
            .record,
            .tuple,
            .empty_tag_union,
            => return .expand,
        }
    }

    fn derivedDecisionStep(decision: Plan.DerivedComponentDecision) DerivedStep {
        return switch (decision) {
            .structural => .expand,
            .call => |index| .{ .call = index },
            .scheme_dictionary => |requirement| .{ .scheme_dictionary = requirement },
            .descriptor => .descriptor,
            .shared_closed => |closed| .{ .convert = closed },
            .checked_error => .checked_error,
        };
    }

    /// The derived-method formal environment the bindings of the derivation
    /// being lowered form.
    fn currentDerivedEnv(self: *ProcBodyBuilder, context: DerivedContext) Allocator.Error!u32 {
        const ordered = try Plan.orderedDerivedEnv(self.parent.allocator, self.nominal_formal_bindings.items[context.bindings_start..]);
        defer self.parent.allocator.free(ordered);
        return self.parent.plan.findDerivedEnv(ordered) orelse
            boxyLowerInvariant("derived method reached formal bindings planning did not record");
    }

    /// Call the recursive helper performing `method` over the union `rep_id`,
    /// passing this frame's descriptors and dictionaries the helper reads.
    fn lowerDerivedHelperCallInto(
        self: *ProcBodyBuilder,
        method: Plan.DerivedMethod,
        target: LIR.LocalId,
        first: LIR.LocalId,
        second: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const context = self.derived_context orelse
            boxyLowerInvariant("derived method helper call outside a derivation");
        const env = try self.currentDerivedEnv(context);
        const index = try self.parent.derivedHelperIndex(
            method,
            rep_id,
            context.frame,
            env,
            self.parent.result.store.getLocal(second).layout_idx,
            self.parent.result.store.getLocal(target).layout_idx,
        );
        const helper = self.parent.derived_helpers.items[index];
        var args = std.ArrayList(LIR.LocalId).empty;
        defer args.deinit(self.parent.allocator);
        try args.appendSlice(self.parent.allocator, &.{ first, second });
        var operand_desc: ?struct { local: LIR.LocalId, desc: LIR.BoxyDescRef } = null;
        if (helper.shape.operand_desc) {
            const desc = try self.descriptorRefForLocalOrKnownRep(first, rep_id);
            const local = desc.localOrNull() orelse local: {
                const local = try self.addFrameLocal(.opaque_ptr);
                operand_desc = .{ .local = local, .desc = desc };
                break :local local;
            };
            try args.append(self.parent.allocator, local);
        }
        for (helper.shape.variables) |variable| {
            try args.append(self.parent.allocator, self.descriptorLocalForRepOrNull(variable) orelse
                boxyLowerInvariant("derived method helper read a frame type variable without a descriptor local"));
        }
        for (helper.shape.dictionaries) |dictionaries| {
            try args.append(self.parent.allocator, self.boundDictionaryLocal(dictionaries));
        }
        const call = try self.parent.result.store.addCFStmt(.{ .assign_call = .{
            .target = target,
            .proc = helper.proc,
            .args = try self.parent.result.store.addLocalSpan(args.items),
            .next = next,
        } }, self.derivedOrigin());
        const materialize = operand_desc orelse return call;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = materialize.local,
            .desc = materialize.desc,
            .next = call,
        } }, self.derivedOrigin());
    }

    fn lowerPrimitiveEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        primitive: checked.CheckedPrimitive,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (primitive == .bool) {
            return try self.lowerBoolEqLocalsInto(target, lhs, rhs, negated, next);
        }

        switch (primitive) {
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => {
                const lhs_bits = try self.addFrameLocal(.u128);
                const rhs_bits = try self.addFrameLocal(.u128);
                const compare = try self.lowerScalarEqLocalsInto(target, lhs_bits, rhs_bits, .num_is_eq, negated, next);
                const lower_rhs = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                    .target = rhs_bits,
                    .op = .simd_to_u128_bits,
                    .rc_effect = LIR.LowLevel.simd_to_u128_bits.rcEffect(),
                    .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{rhs}),
                    .next = compare,
                } }, self.derivedOrigin());
                return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                    .target = lhs_bits,
                    .op = .simd_to_u128_bits,
                    .rc_effect = LIR.LowLevel.simd_to_u128_bits.rcEffect(),
                    .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{lhs}),
                    .next = lower_rhs,
                } }, self.derivedOrigin());
            },
            .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => {},
        }

        const eq_op: LIR.LowLevel = switch (primitive) {
            .str => .str_is_eq,
            .u8,
            .i8,
            .u16,
            .i16,
            .u32,
            .i32,
            .u64,
            .i64,
            .u128,
            .i128,
            .f32,
            .f64,
            .dec,
            => .num_is_eq,
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => unreachable,
            .bool => unreachable,
        };
        return try self.lowerScalarEqLocalsInto(target, lhs, rhs, eq_op, negated, next);
    }

    /// Compare two scalars with `eq_op`, negating the result when asked.
    fn lowerScalarEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        eq_op: LIR.LowLevel,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const args = [_]LIR.LocalId{ lhs, rhs };
        if (!negated) {
            return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                .target = target,
                .op = eq_op,
                .rc_effect = eq_op.rcEffect(),
                .args = try self.parent.result.store.addLocalSpan(&args),
                .next = next,
            } }, self.derivedOrigin());
        }

        const raw = try self.addFrameLocal(.bool);
        const not_stmt = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .bool_not,
            .rc_effect = LIR.LowLevel.bool_not.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{raw}),
            .next = next,
        } }, self.derivedOrigin());
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = raw,
            .op = eq_op,
            .rc_effect = eq_op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&args),
            .next = not_stmt,
        } }, self.derivedOrigin());
    }

    fn lowerBoolEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const lhs_disc = try self.addFrameLocal(.u32);
        const rhs_disc = try self.addFrameLocal(.u32);
        const compare = try self.lowerScalarEqLocalsInto(target, lhs_disc, rhs_disc, .num_is_eq, negated, next);
        const read_rhs = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = rhs_disc,
            .op = .{ .discriminant = .{ .source = rhs } },
            .next = compare,
        } }, self.derivedOrigin());
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = lhs_disc,
            .op = .{ .discriminant = .{ .source = lhs } },
            .next = read_rhs,
        } }, self.derivedOrigin());
    }

    /// Merge a derived method's branches, each of which wrote `target` and
    /// jumped to `id`, before `next`.
    fn derivedResultJoin(
        self: *ProcBodyBuilder,
        id: LIR.JoinPointId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
        remainder: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const params = [_]LIR.LocalId{target};
        return try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = id,
            .params = try self.joinParamSpan(&params),
            .body = next,
            .remainder = remainder,
        } }, self.derivedOrigin());
    }

    /// Lower `body` as a derived method over `rep_id` whose component
    /// decisions were planned for this worker's frame.
    fn enterDerivedContext(self: *ProcBodyBuilder, worker: ?Plan.WorkerPlanId, rep_id: Plan.TypeRepId) Allocator.Error!?DerivedContext {
        const outer = self.derived_context;
        self.derived_context = .{
            .frame = try self.parent.plan.derivedFrame(self.parent.allocator, worker, rep_id, 0),
            .bindings_start = self.nominal_formal_bindings.items.len,
        };
        return outer;
    }

    /// The planned decision for a list, nominal, or type-variable component
    /// of the derived method being lowered, under the formal bindings its
    /// enclosing nominal backings bind.
    fn derivedComponentDecisionFor(
        self: *ProcBodyBuilder,
        method: Plan.DerivedMethod,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!Plan.DerivedComponentDecision {
        const context = self.derived_context orelse
            boxyLowerInvariant("derived method component was lowered outside a derivation");
        const env = try self.currentDerivedEnv(context);
        return self.parent.plan.derivedComponentDecision(.{ .frame = context.frame, .method = method, .rep = rep_id, .env = env }) orelse
            boxyLowerInvariant("derived method reached a component without a planned decision");
    }

    fn nominalFormalActualAbove(self: *const ProcBodyBuilder, start: usize, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var index = self.nominal_formal_bindings.items.len;
        while (index > start) {
            index -= 1;
            const binding = self.nominal_formal_bindings.items[index];
            if (binding.formal == rep_id) return binding.actual;
        }
        return null;
    }

    /// Call a component type's own method worker, as a derived method's
    /// component comparison.
    fn lowerDerivedComponentCallInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        args: []const LIR.LocalId,
        index: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const call = self.parent.plan.derived_component_calls.items[index];
        return try self.lowerWorkerCallLocalsInto(
            target,
            call.ret_type,
            &call.arg_types,
            &call.arg_types,
            args,
            null,
            null,
            null,
            call.worker,
            self.parent.plan.directCallHiddenDescriptorArgSlice(call.hidden_desc_args),
            self.parent.plan.directCallHiddenDictionaryArgSlice(call.hidden_dict_args),
            next,
        );
    }

    /// Call a type-variable component's method through the frame's
    /// dictionary for the scheme requirement checking gave it.
    fn lowerDerivedDictionaryCallInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        args: []const LIR.LocalId,
        component_rep: Plan.TypeRepId,
        requirement_id: Plan.DictionaryRequirementId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const dict_local = self.dictionaryLocalForRequirementOrNull(requirement_id) orelse
            boxyLowerInvariant("derived method reached a scheme requirement without a bound dictionary local");
        if (!self.dictionaryBindingIsBound(requirement_id)) {
            boxyLowerInvariant("derived method reached a scheme requirement with an unbound dictionary local");
        }
        const requirement = self.parent.plan.dictionaries.items[@backingInt(requirement_id)];
        const requirement_rep = self.repForTypeRef(requirement.fn_ty);
        const function = self.functionChildrenForRep(requirement_rep) orelse
            boxyLowerInvariant("derived method scheme requirement was not a function");
        if (function.arg_count != args.len) {
            boxyLowerInvariant("derived method scheme requirement arity disagreed with its component call");
        }
        const children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(function.rep)].children);
        const arg_reps = try self.parent.allocator.alloc(Plan.TypeRepId, args.len);
        defer self.parent.allocator.free(arg_reps);
        const arg_types = try self.parent.allocator.alloc(Plan.CheckedTypeIdentity, args.len);
        defer self.parent.allocator.free(arg_types);
        // The requirement is written in the scheme's variable; the derived
        // value is that variable's component, described by this frame.
        const component_type = self.parent.plan.representations.items[@backingInt(component_rep)].source_type;
        const dispatcher_rep = children[function.args_start].rep;
        for (children[function.args_start..][0..function.arg_count], arg_reps, arg_types, args) |child, *arg_rep, *arg_type, arg| {
            const is_dispatcher = child.rep == dispatcher_rep;
            arg_rep.* = if (is_dispatcher) component_rep else child.rep;
            arg_type.* = if (is_dispatcher) component_type else child.source_type;
            if (self.parent.result.store.getLocal(arg).layout_idx != self.workerRuntimeLayoutForRep(arg_rep.*).layoutIdx()) {
                boxyLowerInvariant("derived method component argument layout disagreed with its scheme requirement");
            }
        }
        const ret_type = self.parent.plan.representations.items[@backingInt(function.ret)].source_type;
        const hidden_desc_args = try self.dictionaryCallHiddenDescriptorArgs(
            requirement_rep,
            arg_reps[0],
            requirement_id,
            0,
            arg_types,
            arg_reps,
            ret_type,
        );
        defer self.parent.allocator.free(hidden_desc_args);
        var arg_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer arg_descriptor_initializers.deinit(self.parent.allocator);
        const argument_desc_locals = try self.dictionaryCallArgumentDescriptorLocals(arg_reps, args, &arg_descriptor_initializers);
        defer self.parent.allocator.free(argument_desc_locals);
        const hidden_desc_locals = try self.lowerDirectCallHiddenDescriptorArgs(hidden_desc_args, args, arg_reps, arg_reps);
        defer self.parent.allocator.free(hidden_desc_locals);
        const hidden_arg_locals = try self.parent.allocator.alloc(LIR.LocalId, hidden_desc_locals.len);
        defer self.parent.allocator.free(hidden_arg_locals);
        for (hidden_desc_locals, hidden_arg_locals) |hidden, *local| local.* = hidden.local;

        const result_desc_info = self.resultDescriptorForCallTarget(
            target,
            try self.dictionaryCallResultDescriptorRef(function.ret, hidden_desc_args, hidden_desc_locals),
        );
        if (result_desc_info.desc) |desc| {
            if (self.parent.result.store.getLocal(target).boxy_desc == null) self.parent.result.store.setLocalBoxyDesc(target, desc);
        }
        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_call_dict = .{
            .target = target,
            .dict = .{ .local = dict_local },
            .method = requirement.fn_name,
            .method_slot = requirement.slot,
            .args = try self.parent.result.store.addLocalSpan(args),
            .arg_descs = try self.parent.result.store.addLocalSpan(argument_desc_locals),
            .hidden_args = try self.parent.result.store.addLocalSpan(hidden_arg_locals),
            .result_desc = result_desc_info.desc,
            .next = next,
        } }, self.derivedOrigin());
        if (result_desc_info.materialize) |materialize| {
            const desc = materialize.materialize orelse
                boxyLowerInvariant("derived method dictionary call result descriptor materialization had no descriptor");
            continuation = try self.prependDescriptorArgMaterialization(materialize, desc, continuation);
        }
        continuation = try self.prependDescriptorArgMaterializations(hidden_desc_locals, continuation);
        return try self.prependDescriptorArgMaterializations(arg_descriptor_initializers.items, continuation);
    }

    fn lowerDerivedEqCallInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        index: u32,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!negated) return try self.lowerDerivedComponentCallInto(target, &.{ lhs, rhs }, index, next);
        const raw = try self.addFrameLocal(.bool);
        return try self.lowerDerivedComponentCallInto(raw, &.{ lhs, rhs }, index, try self.negateBoolInto(target, raw, next));
    }

    fn lowerDerivedEqDictionaryCallInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        component_rep: Plan.TypeRepId,
        requirement: Plan.DictionaryRequirementId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!negated) return try self.lowerDerivedDictionaryCallInto(target, &.{ lhs, rhs }, component_rep, requirement, next);
        const raw = try self.addFrameLocal(.bool);
        return try self.lowerDerivedDictionaryCallInto(raw, &.{ lhs, rhs }, component_rep, requirement, try self.negateBoolInto(target, raw, next));
    }

    fn negateBoolInto(self: *ProcBodyBuilder, target: LIR.LocalId, source: LIR.LocalId, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .bool_not,
            .rc_effect = LIR.LowLevel.bool_not.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{source}),
            .next = next,
        } }, self.derivedOrigin());
    }

    // Structural hashing //
    //
    // Hashing a representation hashes its components, and components follow
    // type nesting, so each hash still waiting on a component's hash is a
    // frame on one heap-backed stack. Hashes are built from their
    // continuation backward; frames allocate locals, join points, and
    // statements in the order a direct recursive build would.

    const HashRequest = struct {
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    };

    const HashStep = union(enum) {
        /// The frame needs this component hash next.
        request: HashRequest,
        /// The frame finished with this statement and was popped.
        done: LIR.CFStmtId,
    };

    const HashComponent = struct {
        rep: Plan.TypeRepId,
        field_index: u32,
    };

    /// One tag variant's hash: its discriminant, then its payloads last
    /// first.
    const HashVariantState = struct {
        request: HashRequest,
        variant: Plan.TagVariant,
        variant_index: u32,
        after_discriminant: LIR.LocalId,
        intermediate_hashers: []LIR.LocalId = &.{},
        source_has_payload_desc: bool = false,
        remaining: usize,
        current: LIR.CFStmtId,
        pending: ExtractedTagPayloadLocal = undefined,
    };

    const HashFrame = struct {
        /// Whether the frame's last requested hash is still due.
        awaiting: bool = false,
        state: union(enum) {
            convert: struct { request: HashRequest, converted: LIR.LocalId, actual: Plan.TypeRepId },
            unbox: struct { request: HashRequest, payload: LIR.LocalId, payload_rep: Plan.TypeRepId },
            nominal: struct {
                request: HashRequest,
                scope: NominalBackingFormalScope,
                backing_rep: Plan.TypeRepId,
                backing: ?LIR.LocalId,
            },
            /// A record's fields or a tuple's elements, last first.
            fields: struct {
                request: HashRequest,
                components: []HashComponent,
                intermediate_hashers: []LIR.LocalId,
                remaining: usize,
                current: LIR.CFStmtId,
                pending_field: LIR.LocalId = undefined,
            },
            variant: HashVariantState,
            tag: struct {
                request: HashRequest,
                discriminant: LIR.LocalId,
                done: LIR.JoinPointId,
                branches: []LIR.CFSwitchBranch,
                index: usize = 0,
                variant: ?HashVariantState = null,
            },
        },
    };

    fn lowerHashRepLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const allocator = self.parent.allocator;
        var frames: std.ArrayList(HashFrame) = .empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseHashFrame(&frames.items[index]);
            }
            frames.deinit(allocator);
        }
        var result = try self.beginHash(&frames, .{ .target = target, .value = value, .hasher = hasher, .rep_id = rep_id, .next = next });
        while (frames.items.len != 0) {
            switch (try self.stepHashFrame(&frames, result)) {
                .request => |request| result = try self.beginHash(&frames, request),
                .done => |stmt| result = stmt,
            }
        }
        return result.?;
    }

    /// Free what an unfinished frame owns and leave the scope it holds, as
    /// the direct build's defers would.
    fn releaseHashFrame(self: *ProcBodyBuilder, frame: *HashFrame) void {
        const allocator = self.parent.allocator;
        switch (frame.state) {
            .convert, .unbox => {},
            .nominal => |nominal| self.dropNominalBackingFormalScope(nominal.scope),
            .fields => |fields| {
                allocator.free(fields.components);
                allocator.free(fields.intermediate_hashers);
            },
            .variant => |variant| allocator.free(variant.intermediate_hashers),
            .tag => |tag| {
                allocator.free(tag.branches);
                if (tag.variant) |variant| allocator.free(variant.intermediate_hashers);
            },
        }
    }

    fn pushHashFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(HashFrame), state: @FieldType(HashFrame, "state")) Allocator.Error!?LIR.CFStmtId {
        var frame: HashFrame = .{ .state = state };
        frames.append(self.parent.allocator, frame) catch |err| {
            self.releaseHashFrame(&frame);
            return err;
        };
        return null;
    }

    fn finishHashFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(HashFrame), stmt: LIR.CFStmtId) HashStep {
        var frame = frames.pop().?;
        switch (frame.state) {
            // A finished nominal hash has left its scope already.
            .nominal => {},
            .convert, .unbox, .fields, .variant, .tag => self.releaseHashFrame(&frame),
        }
        return .{ .done = stmt };
    }

    /// The hash of `request` when it needs no component hash; otherwise
    /// null, with the frame that builds it pushed.
    fn beginHash(self: *ProcBodyBuilder, frames: *std.ArrayList(HashFrame), root: HashRequest) Allocator.Error!?LIR.CFStmtId {
        const allocator = self.parent.allocator;
        var request = root;
        while (true) {
            const target = request.target;
            const value = request.value;
            const hasher = request.hasher;
            const rep_id = request.rep_id;
            const next = request.next;
            switch (try self.derivedStep(.hash, rep_id)) {
                .expand => {},
                .call => |index| return try self.lowerDerivedComponentCallInto(target, &.{ value, hasher }, index, next),
                .scheme_dictionary => |requirement| return try self.lowerDerivedDictionaryCallInto(target, &.{ value, hasher }, rep_id, requirement, next),
                .descriptor => return try self.lowerDescriptorHashLocalsInto(target, value, hasher, rep_id, next),
                .checked_error => return try self.lowerCheckedErrorDispatchInto("method dispatch failed to check"),
                .helper => return try self.lowerDerivedHelperCallInto(.hash, target, value, hasher, rep_id, next),
                .convert => |actual| {
                    const converted = try self.addFrameLocalForRep(actual);
                    return try self.pushHashFrame(frames, .{ .convert = .{ .request = request, .converted = converted, .actual = actual } });
                },
                .unbox => |payload_rep| {
                    const payload = try self.addFrameLocalForRep(payload_rep);
                    return try self.pushHashFrame(frames, .{ .unbox = .{ .request = request, .payload = payload, .payload_rep = payload_rep } });
                },
            }
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            switch (rep.kind) {
                .in_progress => boxyLowerInvariant("in-progress boxy representation reached structural hash lowering"),
                .erased_callable => boxyLowerInvariant("erased callable structural hash reached boxy lowering"),
                .generated_field,
                .generated_field_names,
                .generated_tag_union_spec,
                => boxyLowerInvariant("compiler-owned encoding evidence reached structural hash lowering"),
                .dynamic,
                .list,
                .box,
                => boxyLowerInvariant("derived hash expanded a component its step dispatches"),
                .primitive => |primitive| return try self.lowerPrimitiveHashLocalsInto(target, value, hasher, primitive, next),
                .bool_tag_union => return try self.lowerPrimitiveHashLocalsInto(target, value, hasher, .bool, next),
                .empty_record,
                .empty_tag_union,
                => return try self.assignLocal(target, hasher, next),
                .alias => {
                    request.rep_id = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep;
                    continue;
                },
                .nominal => {
                    const scope = try self.enterNominalBackingFormalScope(rep_id);
                    errdefer self.dropNominalBackingFormalScope(scope);
                    const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
                    const backing: ?LIR.LocalId = if (rep.declared_fields.len == 0) null else try self.addFrameLocalForRep(backing_rep);
                    try frames.append(allocator, .{ .state = .{ .nominal = .{
                        .request = request,
                        .scope = scope,
                        .backing_rep = backing_rep,
                        .backing = backing,
                    } } });
                    return null;
                },
                .record, .tuple => {
                    const children = self.parent.plan.childSlice(rep.children);
                    const components = if (rep.kind == .record)
                        try self.recordHashComponents(children)
                    else
                        try self.tupleHashComponents(children);
                    errdefer allocator.free(components);
                    if (components.len == 0) {
                        allocator.free(components);
                        return try self.assignLocal(target, hasher, next);
                    }
                    const intermediate_hashers = try self.intermediateHashers(hasher, components.len);
                    return try self.pushHashFrame(frames, .{ .fields = .{
                        .request = request,
                        .components = components,
                        .intermediate_hashers = intermediate_hashers,
                        .remaining = components.len,
                        .current = next,
                    } });
                },
                .tag_union => {
                    const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                    if (variants.len == 1 and self.isZstLocal(value)) {
                        return try self.pushHashFrame(frames, .{ .variant = try self.beginHashVariant(request, variants[0], 0) });
                    }
                    const discriminant = try self.addFrameLocal(.u32);
                    const done = self.freshJoinPointId();
                    const branches = try allocator.alloc(LIR.CFSwitchBranch, variants.len);
                    return try self.pushHashFrame(frames, .{ .tag = .{
                        .request = request,
                        .discriminant = discriminant,
                        .done = done,
                        .branches = branches,
                    } });
                },
            }
        }
    }

    /// The hashers a chain of `count` component hashes threads between its
    /// input and output hashers.
    fn intermediateHashers(self: *ProcBodyBuilder, hasher: LIR.LocalId, count: usize) Allocator.Error![]LIR.LocalId {
        const hasher_layout = self.parent.result.store.getLocal(hasher).layout_idx;
        const intermediate_hashers = try self.parent.allocator.alloc(LIR.LocalId, count - 1);
        errdefer self.parent.allocator.free(intermediate_hashers);
        for (intermediate_hashers) |*local| {
            local.* = try self.addFrameLocal(hasher_layout);
        }
        return intermediate_hashers;
    }

    fn recordHashComponents(self: *ProcBodyBuilder, children: []const Plan.RepChild) Allocator.Error![]HashComponent {
        const components = try self.parent.allocator.alloc(HashComponent, recordEqualityFieldCount(children));
        var field_index: u32 = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => {
                    components[field_index] = .{
                        .rep = child.rep,
                        .field_index = field_index,
                    };
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record hash representation had a non-record child role"),
            }
        }
        return components;
    }

    fn tupleHashComponents(self: *ProcBodyBuilder, children: []const Plan.RepChild) Allocator.Error![]HashComponent {
        const components = try self.parent.allocator.alloc(HashComponent, children.len);
        for (children, components) |child, *component| {
            switch (child.role) {
                .tuple_elem => |index| {
                    if (index > std.math.maxInt(u32)) {
                        boxyLowerInvariant("tuple hash element index exceeded LIR field index range");
                    }
                    component.* = .{
                        .rep = child.rep,
                        .field_index = @intCast(index),
                    };
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple hash representation had a non-tuple child role"),
            }
        }
        return components;
    }

    fn stepHashFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(HashFrame), delivered: ?LIR.CFStmtId) Allocator.Error!HashStep {
        const frame = &frames.items[frames.items.len - 1];
        const child: ?LIR.CFStmtId = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("boxy hash frame resumed without its component hash")
        else
            null;
        frame.awaiting = false;
        switch (frame.state) {
            .convert => |convert| {
                const request = convert.request;
                const hash = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{ .target = request.target, .value = convert.converted, .hasher = request.hasher, .rep_id = convert.actual, .next = request.next } };
                };
                return self.finishHashFrame(frames, try self.assignRepresentationBoundary(convert.converted, request.value, convert.actual, request.rep_id, hash));
            },
            .unbox => |unbox| {
                const request = unbox.request;
                const hash = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{ .target = request.target, .value = unbox.payload, .hasher = request.hasher, .rep_id = unbox.payload_rep, .next = request.next } };
                };
                return self.finishHashFrame(frames, try self.assignBoxBoundary(unbox.payload, request.value, unbox.payload_rep, .box_unbox, hash));
            },
            .nominal => |nominal| {
                const request = nominal.request;
                const hash = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{ .target = request.target, .value = nominal.backing orelse request.value, .hasher = request.hasher, .rep_id = nominal.backing_rep, .next = request.next } };
                };
                const lowered = if (nominal.backing) |backing|
                    try self.assignRepresentationBoundary(backing, request.value, nominal.backing_rep, request.rep_id, hash)
                else
                    hash;
                return self.finishHashFrame(frames, try self.leaveNominalBackingFormalScope(nominal.scope, lowered));
            },
            .fields => |*fields| {
                const request = fields.request;
                if (child) |hash| {
                    var current = hash;
                    const component = fields.components[fields.remaining];
                    if (!self.isZstLocal(fields.pending_field)) {
                        current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                            .target = fields.pending_field,
                            .op = .{ .field = .{
                                .source = request.value,
                                .field_idx = component.field_index,
                            } },
                            .next = current,
                        } }, self.derivedOrigin());
                    }
                    fields.current = current;
                }
                if (fields.remaining == fields.components.len) {
                    const hasher_layout = self.parent.result.store.getLocal(request.hasher).layout_idx;
                    if (self.parent.result.store.getLocal(request.target).layout_idx != hasher_layout) {
                        boxyLowerInvariant("structural hash target layout differed from input hasher layout");
                    }
                }
                if (fields.remaining == 0) return self.finishHashFrame(frames, fields.current);
                fields.remaining -= 1;
                const i = fields.remaining;
                const input_hasher = if (i == 0) request.hasher else fields.intermediate_hashers[i - 1];
                const output_hasher = if (i == fields.components.len - 1) request.target else fields.intermediate_hashers[i];
                const component = fields.components[i];
                fields.pending_field = try self.addFrameLocalForRep(component.rep);
                frame.awaiting = true;
                return .{ .request = .{ .target = output_hasher, .value = fields.pending_field, .hasher = input_hasher, .rep_id = component.rep, .next = fields.current } };
            },
            .variant => |*variant| {
                if (child) |hash| try self.finishHashVariantPayload(variant, hash);
                if (try self.nextHashVariantPayload(variant)) |request| {
                    frame.awaiting = true;
                    return .{ .request = request };
                }
                return self.finishHashFrame(frames, try self.finishHashVariant(variant));
            },
            .tag => |*tag| {
                const request = tag.request;
                const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(request.rep_id)].tag_variants);
                if (child) |hash| try self.finishHashVariantPayload(&tag.variant.?, hash);
                while (true) {
                    if (tag.variant) |*variant| {
                        if (try self.nextHashVariantPayload(variant)) |component| {
                            frame.awaiting = true;
                            return .{ .request = component };
                        }
                        tag.branches[tag.index] = .{
                            .value = @intCast(tag.index),
                            .body = try self.finishHashVariant(variant),
                        };
                        self.parent.allocator.free(variant.intermediate_hashers);
                        tag.variant = null;
                        tag.index += 1;
                    }
                    if (tag.index == variants.len) break;
                    if (tag.index > std.math.maxInt(u32)) {
                        boxyLowerInvariant("tag-union hash variant index exceeded LIR variant range");
                    }
                    tag.variant = try self.beginHashVariant(.{
                        .target = request.target,
                        .value = request.value,
                        .hasher = request.hasher,
                        .rep_id = request.rep_id,
                        .next = try self.joinJump(tag.done),
                    }, variants[tag.index], @intCast(tag.index));
                }
                const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error, self.derivedOrigin());
                const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
                    .cond = tag.discriminant,
                    .branches = try self.parent.result.store.addCFSwitchBranches(tag.branches),
                    .default_branch = bad_discriminant,
                    .continuation = null,
                } }, self.derivedOrigin());
                const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = tag.discriminant,
                    .op = .{ .discriminant = .{ .source = request.value } },
                    .next = switch_stmt,
                } }, self.derivedOrigin());
                return self.finishHashFrame(frames, try self.derivedResultJoin(tag.done, request.target, request.next, read_discriminant));
            },
        }
    }

    /// Begin one tag variant's hash, which `request.next` follows.
    fn beginHashVariant(self: *ProcBodyBuilder, request: HashRequest, variant: Plan.TagVariant, variant_index: u32) Allocator.Error!HashVariantState {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        const hasher_layout = self.parent.result.store.getLocal(request.hasher).layout_idx;
        const after_discriminant = if (payloads.len == 0) request.target else try self.addFrameLocal(hasher_layout);
        for (payloads, 0..) |child, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("tag hash payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag hash variant payload span included a non-payload child"),
            }
        }
        var state: HashVariantState = .{
            .request = request,
            .variant = variant,
            .variant_index = variant_index,
            .after_discriminant = after_discriminant,
            .remaining = payloads.len,
            .current = request.next,
        };
        if (payloads.len != 0) {
            state.source_has_payload_desc = self.parent.plan.representations.items[@backingInt(request.rep_id)].descriptor != null or
                self.parent.result.store.getLocal(request.value).boxy_desc != null;
            state.intermediate_hashers = try self.intermediateHashers(after_discriminant, payloads.len);
        }
        return state;
    }

    /// The next payload hash of a variant, or null once every payload is
    /// hashed.
    fn nextHashVariantPayload(self: *ProcBodyBuilder, state: *HashVariantState) Allocator.Error!?HashRequest {
        if (state.remaining == 0) return null;
        const payloads = self.parent.plan.childSlice(state.variant.payloads);
        state.remaining -= 1;
        const i = state.remaining;
        const input_hasher = if (i == 0) state.after_discriminant else state.intermediate_hashers[i - 1];
        const output_hasher = if (i == payloads.len - 1) state.request.target else state.intermediate_hashers[i];
        const payload = payloads[i];
        state.pending = try self.addExtractedTagPayloadLocal(payload.rep, state.source_has_payload_desc);
        return .{ .target = output_hasher, .value = state.pending.local, .hasher = input_hasher, .rep_id = payload.rep, .next = state.current };
    }

    /// Read one payload for its hash, extending the variant's hash backward.
    fn finishHashVariantPayload(self: *ProcBodyBuilder, state: *HashVariantState, hash: LIR.CFStmtId) Allocator.Error!void {
        const payloads = self.parent.plan.childSlice(state.variant.payloads);
        const i = state.remaining;
        const payload = payloads[i];
        if (i > std.math.maxInt(u32)) {
            boxyLowerInvariant("tag hash payload index exceeded LIR payload index range");
        }
        state.current = try self.assignConcreteTagPayloadRead(
            state.pending.local,
            payload.rep,
            state.pending.desc_local,
            state.request.value,
            state.request.rep_id,
            state.variant.name,
            state.variant_index,
            @intCast(i),
            payloads.len,
            hash,
        );
    }

    /// The variant's hash once its payloads are hashed: the discriminant
    /// written first.
    fn finishHashVariant(self: *ProcBodyBuilder, state: *HashVariantState) Allocator.Error!LIR.CFStmtId {
        const discriminant_value = try self.addFrameLocal(.u64);
        const current = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = state.after_discriminant,
            .op = .hasher_write_u64,
            .rc_effect = LIR.LowLevel.hasher_write_u64.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ state.request.hasher, discriminant_value }),
            .next = state.current,
        } }, self.derivedOrigin());
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = discriminant_value,
            .value = .{ .i128_literal = .{
                .value = state.variant_index,
                .layout_idx = .u64,
            } },
            .next = current,
        } }, self.derivedOrigin());
    }

    fn lowerPrimitiveHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        primitive: checked.CheckedPrimitive,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const op = Common.hasherWriteOp(primitive);
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = op,
            .rc_effect = op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ hasher, value }),
            .next = next,
        } }, self.derivedOrigin());
    }

    fn joinJump(self: *ProcBodyBuilder, join_id: LIR.JoinPointId) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } }, self.glueOrigin());
    }

    fn freshJoinPointId(self: *ProcBodyBuilder) LIR.JoinPointId {
        const id: LIR.JoinPointId = @fromBackingInt(@intCast(self.next_join_point));
        self.next_join_point += 1;
        return id;
    }

    const DynamicLiteralTarget = struct {
        payload_layout: layout.Idx,
        payload_desc: LIR.BoxyDescRef,
    };

    /// The runtime descriptor reference of a dynamic-storage literal target
    /// whose payload layout is not statically known, or null when the target
    /// is concrete or statically described.
    fn dynamicLiteralRuntimeDesc(self: *ProcBodyBuilder, target: LIR.LocalId) ?LIR.BoxyDescRef {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.layoutIsBoxyDynamicStorage(target_layout)) return null;
        const payload_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return null;
        return switch (payload_desc) {
            .static => null,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => payload_desc,
        };
    }

    fn dynamicLiteralTarget(self: *ProcBodyBuilder, target: LIR.LocalId) ?DynamicLiteralTarget {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.layoutIsBoxyDynamicStorage(target_layout)) return null;

        const payload_desc = self.parent.result.store.getLocal(target).boxy_desc orelse
            boxyLowerInvariant("boxy dynamic literal target had no payload descriptor");
        const payload_layout = switch (payload_desc) {
            .static => |desc_id| self.parent.result.boxy_type_descs.items[@backingInt(desc_id)].payload_layout,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy dynamic literal target used a runtime descriptor without a concrete literal payload layout"),
        };
        if (payload_layout == target_layout) {
            boxyLowerInvariant("boxy dynamic literal target descriptor resolved to dynamic storage");
        }
        return .{
            .payload_layout = payload_layout,
            .payload_desc = payload_desc,
        };
    }

    /// Like `dynamicLiteralTarget`, but for literals whose payload layout the
    /// literal kind already fixes statically (str, f32, f64). A runtime-only
    /// descriptor conveys the target's representation at runtime and cannot
    /// supply the payload layout, so the known layout is used to box against it.
    fn dynamicLiteralTargetForLayout(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        known_payload_layout: layout.Idx,
    ) ?DynamicLiteralTarget {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.layoutIsBoxyDynamicStorage(target_layout)) return null;

        const payload_desc = self.parent.result.store.getLocal(target).boxy_desc orelse
            boxyLowerInvariant("boxy dynamic literal target had no payload descriptor");
        const payload_layout = switch (payload_desc) {
            .static => |desc_id| self.parent.result.boxy_type_descs.items[@backingInt(desc_id)].payload_layout,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => known_payload_layout,
        };
        if (payload_layout == target_layout) {
            boxyLowerInvariant("boxy dynamic literal target descriptor resolved to dynamic storage");
        }
        return .{
            .payload_layout = payload_layout,
            .payload_desc = payload_desc,
        };
    }

    fn assignBoxedLiteralPayload(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        payload: LIR.LocalId,
        info: DynamicLiteralTarget,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
            .target = target,
            .payload = payload,
            .payload_layout = info.payload_layout,
            .payload_desc = info.payload_desc,
            .payload_mode = .move,
            .next = next,
        } }, self.origin);
    }

    fn assignCheckedNumeralLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        checked_ty: checked.CheckedTypeId,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const default_layout = builtinNumeralLayoutForType(self.module, checked_ty);
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            const exact = self.module.module_env.exactNumeral(literal);
            const value: LIR.LiteralValue = switch (default_layout) {
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128 => .{ .boxy_dynamic_num_literal = .{
                    .value = exactIntBitsForLayout(exact, default_layout) orelse return try self.invalidNumeralLiteral(),
                    .desc = desc_ref,
                    .default_layout = default_layout,
                } },
                .f32, .f64, .dec => .{ .boxy_dynamic_frac_literal = .{
                    .dec_bits = (try exact_numeral.decBits(self.parent.allocator, exact)) orelse return try self.invalidNumeralLiteral(),
                    .desc = desc_ref,
                    .default_layout = default_layout,
                } },
                .bool, .str, .opaque_ptr, .zst, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, _ => boxyLowerInvariant("builtin numeral resolved to a non-numeric layout"),
            };
            const assigned = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = value,
                .next = next,
            } }, self.origin);
            return try self.prependLiteralTargetDescriptorMaterialization(target, assigned);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            const payload = try self.addFrameLocal(info.payload_layout);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.assignExactNumeralPayload(payload, info.payload_layout, literal, box);
        }
        return try self.assignExactNumeralPayload(
            target,
            self.parent.result.store.getLocal(target).layout_idx,
            literal,
            next,
        );
    }

    fn assignExactNumeralPayload(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        payload_layout: layout.Idx,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const exact = self.module.module_env.exactNumeral(literal);
        return switch (payload_layout) {
            .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128 => blk: {
                const value = exactIntBitsForLayout(exact, payload_layout) orelse
                    break :blk try self.invalidNumeralLiteral();
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                    .target = target,
                    .value = .{ .i128_literal = .{ .value = value, .layout_idx = payload_layout } },
                    .next = next,
                } }, self.origin);
            },
            .f32 => try self.assignF32Literal(target, try exact_numeral.floatBits(f32, self.parent.allocator, exact), next),
            .f64 => try self.assignF64Literal(target, try exact_numeral.floatBits(f64, self.parent.allocator, exact), next),
            .dec => blk: {
                const bits = (try exact_numeral.decBits(self.parent.allocator, exact)) orelse
                    break :blk try self.invalidNumeralLiteral();
                break :blk try self.assignDecLiteral(target, .{ .num = bits }, next);
            },
            .bool, .str, .opaque_ptr, .zst, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, _ => boxyLowerInvariant("checked numeral reached a non-numeric Boxy payload layout"),
        };
    }

    fn invalidNumeralLiteral(self: *ProcBodyBuilder) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .crash = .{
            .msg = .{ .literal = try self.parent.result.store.insertString("invalid numeric literal") },
        } }, self.origin);
    }

    fn appendLiteralPayloadDesc(
        self: *ProcBodyBuilder,
        payload_layout: layout.Idx,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value),
            .shape = .primitive,
            .debug_checked_type = checked_ty,
        });
        return .{ .static = desc_id };
    }

    fn builtinNumeralLayoutForType(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) layout.Idx {
        const builtin = checkedBuiltinNominalForType(module, checked_ty) orelse
            boxyLowerInvariant("builtin numeral had no checked builtin nominal type");
        return switch (builtin) {
            .u8 => .u8,
            .i8 => .i8,
            .u16 => .u16,
            .i16 => .i16,
            .u32 => .u32,
            .i32 => .i32,
            .u64 => .u64,
            .i64 => .i64,
            .u128 => .u128,
            .i128 => .i128,
            .f32 => .f32,
            .f64 => .f64,
            .dec => .dec,
            .bool, .try_, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .list, .box, .dict, .set, .iter, .stream, .parse_tag_union_spec, .fields, .field, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => boxyLowerInvariant("numeral had a non-numeric checked builtin nominal type"),
        };
    }

    fn exactIntBitsForLayout(exact: exact_numeral.Exact, payload_layout: layout.Idx) ?i128 {
        const target: exact_numeral.Target = switch (payload_layout) {
            .u8 => .u8,
            .i8 => .i8,
            .u16 => .u16,
            .i16 => .i16,
            .u32 => .u32,
            .i32 => .i32,
            .u64 => .u64,
            .i64 => .i64,
            .u128 => .u128,
            .i128 => .i128,
            .bool, .str, .f32, .f64, .dec, .opaque_ptr, .zst, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, _ => boxyLowerInvariant("integer numeral requested bits for a non-integer layout"),
        };
        const bits = exact_numeral.intBits(exact, target) orelse return null;
        return switch (bits) {
            .i128 => |value| value,
            .u128 => |value| @bitCast(value),
        };
    }

    const GeneratedNumeralField = enum {
        is_negative,
        digits_before_pt,
        digits_after_pt,
        digits_after_pt_count,
    };

    fn lowerGeneratedNumeralInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!literal.isMaterialized()) {
            boxyLowerInvariant("generated Numeral call operand was not materialized");
        }
        const literal_variant = self.generatedParserTagVariant(target_rep, "Literal");
        const payloads = self.parent.plan.childSlice(literal_variant.variant.payloads);
        if (payloads.len != 1) {
            boxyLowerInvariant("Numeral Literal tag did not have one record payload");
        }
        const record_rep = payloads[0].rep;
        const record = try self.addFrameBoundaryTargetLocalForRep(record_rep);
        const assign_tag = try self.assignGeneratedParserTag(
            target,
            target_rep,
            literal_variant,
            record,
            record_rep,
            next,
        );
        return try self.lowerGeneratedNumeralRecordInto(record, record_rep, literal, assign_tag);
    }

    fn lowerGeneratedNumeralRecordInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const record_rep = self.recordRepForBoundary(target_rep) orelse
            boxyLowerInvariant("Numeral Literal payload was not a record representation");
        const rep = self.parent.plan.representations.items[@backingInt(record_rep)];
        const view = procedureModuleById(self.parent.modules, rep.source_type.module);
        const payload_layout = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => self.parent.result.store.getLocal(target).layout_idx,
            .dynamic_box => self.parent.layout_plan.rep_layouts[@backingInt(record_rep)].descriptor_payload_layout orelse
                boxyLowerInvariant("dynamic Numeral record had no payload layout"),
        };
        const payload = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => target,
            .dynamic_box => try self.addFrameLocal(payload_layout),
        };
        const payload_layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag != .struct_) {
            boxyLowerInvariant("Numeral Literal record did not have a struct payload layout");
        }

        var fields: [4]LIR.LocalId = undefined;
        var field_reps: [4]Plan.TypeRepId = undefined;
        var field_kinds: [4]GeneratedNumeralField = undefined;
        var count: usize = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            const label = switch (child.role) {
                .record_field => |label| label,
                .record_ext => {
                    self.requireEmptyRecordExtension(child.rep);
                    continue;
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("Numeral record representation had a non-record child"),
            };
            if (count >= fields.len) boxyLowerInvariant("Numeral record had too many fields");
            const field_text = view.canonical_names.recordFieldLabelText(label);
            field_kinds[count] = if (std.mem.eql(u8, field_text, "is_negative"))
                .is_negative
            else if (std.mem.eql(u8, field_text, "digits_before_pt"))
                .digits_before_pt
            else if (std.mem.eql(u8, field_text, "digits_after_pt"))
                .digits_after_pt
            else if (std.mem.eql(u8, field_text, "digits_after_pt_count"))
                .digits_after_pt_count
            else
                boxyLowerInvariant("Numeral record contained an unexpected field");
            field_reps[count] = child.rep;
            fields[count] = try self.addFrameLocal(self.parent.recordPayloadFieldLayout(payload_layout, @intCast(count)));
            count += 1;
        }
        if (count != fields.len) boxyLowerInvariant("Numeral record did not have four fields");

        var descriptor_fields: [4]AggregateDescriptorField = undefined;
        for (fields, field_reps, &descriptor_fields) |field, field_rep, *descriptor_field| {
            descriptor_field.* = .{
                .local = field,
                .target_rep = field_rep,
                .source_rep = field_rep,
            };
        }
        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, target_rep, &descriptor_fields);
        defer aggregate_desc.deinit(self.parent.allocator);
        var continuation = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => next,
            .dynamic_box => blk: {
                const payload_desc = aggregate_desc.desc orelse
                    boxyLowerInvariant("dynamic Numeral record had no descriptor");
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = payload,
                    .payload_layout = payload_layout,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.derivedOrigin());
            },
        };
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload,
            .fields = try self.parent.result.store.addLocalSpan(&fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = continuation,
        } }, self.derivedOrigin());

        const before = self.module.module_env.numeralDigitsBefore(literal);
        const after = self.module.module_env.numeralDigitsAfter(literal);
        var index = fields.len;
        while (index > 0) {
            index -= 1;
            continuation = switch (field_kinds[index]) {
                .is_negative => try self.assignBoolLiteral(fields[index], literal.isNegative(), continuation),
                .digits_before_pt => try self.lowerGeneratedNumeralU8ListInto(fields[index], field_reps[index], before, continuation),
                .digits_after_pt => try self.lowerGeneratedNumeralU8ListInto(fields[index], field_reps[index], after, continuation),
                .digits_after_pt_count => try self.assignIntLiteral(fields[index], @intCast(literal.after_decimal_digit_count), continuation),
            };
        }
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        return try self.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    fn lowerGeneratedNumeralU8ListInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        values: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const list_rep = self.listRepForBoundary(target_rep) orelse
            boxyLowerInvariant("Numeral digit field was not a list representation");
        const elem_rep = self.repQuery().requiredSingleChild(list_rep, .list_elem).rep;
        if (self.workerRuntimeLayoutForRep(elem_rep).layoutIdx() != .u8 or self.localListElemLayout(target) != .u8) {
            boxyLowerInvariant("Numeral digit field was not a List(U8)");
        }
        const elems = try self.parent.allocator.alloc(LIR.LocalId, values.len);
        defer self.parent.allocator.free(elems);
        for (elems) |*elem| elem.* = try self.addFrameLocal(.u8);

        const desc_info = try self.stableDescriptorForConstructedValue(target, target_rep);
        if (desc_info.desc) |desc| self.parent.result.store.setLocalBoxyDesc(target, desc);
        var continuation = try self.assignList(target, elems, next);
        continuation = try self.prependOptionalDescriptorMaterialization(desc_info.materialize, continuation);
        var index = elems.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.assignIntLiteral(elems[index], values[index], continuation);
        }
        return continuation;
    }

    /// Lower a builtin from_numeral conversion when no compile-time root was
    /// recorded for the expression.
    fn lowerNumFromNumeralInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const plan = self.staticDispatchPlan(maybe_plan);
        const operands = plan.argsSlice(self.module.static_dispatch_plans);
        if (operands.len != 1) {
            boxyLowerInvariant("from_numeral plan did not carry exactly one operand");
        }
        const literal = switch (operands[0]) {
            .generated_numeral => |lit| lit,
            .checked_expr, .generated_interpolation_segments, .generated_quote => boxyLowerInvariant("from_numeral plan operand was not a generated numeral"),
        };
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            const exact = self.module.module_env.exactNumeral(literal);
            const value: LIR.LiteralValue = if (exact.is_fractional) .{ .boxy_dynamic_frac_literal = .{
                .dec_bits = (try exact_numeral.decBits(self.parent.allocator, exact)) orelse
                    return try self.invalidNumeralLiteral(),
                .desc = desc_ref,
                .default_layout = .dec,
            } } else .{ .boxy_dynamic_num_literal = .{
                .value = exactIntBitsForLayout(exact, if (exact.is_negative) .i128 else .u128) orelse
                    return try self.invalidNumeralLiteral(),
                .desc = desc_ref,
                .default_layout = .dec,
            } };
            const assigned = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = value,
                .next = next,
            } }, self.origin);
            return try self.prependLiteralTargetDescriptorMaterialization(target, assigned);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            const payload = try self.addFrameLocal(info.payload_layout);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.assignExactNumeralPayload(payload, info.payload_layout, literal, box);
        }
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        return try self.assignExactNumeralPayload(target, target_layout, literal, next);
    }

    fn prependLiteralTargetDescriptorMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return next;
        const local = target_desc.localOrNull() orelse return next;
        if (self.localIsReadOnlyDescriptorInput(local)) return next;
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) return next;

        const template = self.descriptorTemplateForLocal(local) orelse {
            if (self.localIsDescriptorSlot(local)) return next;
            boxyLowerInvariant("dynamic literal target descriptor had no explicit producer template");
        };
        if (template.desc.localOrNull() == local) {
            boxyLowerInvariant("dynamic literal target descriptor producer referenced its own target");
        }
        return try self.prependDescriptorArgMaterialization(.{
            .local = local,
            .materialize = template.desc,
            .captures = template.captures,
        }, template.desc, next);
    }

    fn assignIntLiteral(self: *ProcBodyBuilder, target: LIR.LocalId, value: i128, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            // The target's numeric representation is only known through the
            // runtime descriptor; the literal encodes itself against it.
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = .{ .boxy_dynamic_num_literal = .{
                    .value = value,
                    .desc = desc_ref,
                    .default_layout = .dec,
                } },
                .next = next,
            } }, self.origin);
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            const payload = try self.addFrameLocal(info.payload_layout);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .i128_literal = .{
                    .value = value,
                    .layout_idx = info.payload_layout,
                } },
                .next = box,
            } }, self.origin);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .i128_literal = .{
                .value = value,
                .layout_idx = self.parent.result.store.getLocal(target).layout_idx,
            } },
            .next = next,
        } }, self.origin);
    }

    fn assignF32Literal(self: *ProcBodyBuilder, target: LIR.LocalId, value: f32, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralTargetForLayout(target, .f32)) |info| {
            if (info.payload_layout != .f32) {
                boxyLowerInvariant("boxy dynamic f32 literal descriptor did not resolve to f32 payload layout");
            }
            const payload = try self.addFrameLocal(.f32);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .f32_literal = value },
                .next = box,
            } }, self.origin);
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .f32_literal = value },
            .next = next,
        } }, self.origin);
    }

    fn assignF64Literal(self: *ProcBodyBuilder, target: LIR.LocalId, value: f64, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralTargetForLayout(target, .f64)) |info| {
            if (info.payload_layout != .f64) {
                boxyLowerInvariant("boxy dynamic f64 literal descriptor did not resolve to f64 payload layout");
            }
            const payload = try self.addFrameLocal(.f64);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .f64_literal = value },
                .next = box,
            } }, self.origin);
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .f64_literal = value },
            .next = next,
        } }, self.origin);
    }

    fn assignConstScalar(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        scalar: checked.ConstScalar,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (scalar) {
            .i8, .i16, .i32, .i64, .i128, .u8, .u16, .u32, .u64 => |value| try self.assignIntLiteral(target, value, next),
            .u128 => |value| try self.assignIntLiteral(target, @bitCast(value), next),
            .f32_bits => |bits| try self.assignF32Literal(target, @bitCast(bits), next),
            .f64_bits => |bits| try self.assignF64Literal(target, @bitCast(bits), next),
            .dec_bits => |bits| try self.assignDecLiteral(target, .{ .num = bits }, next),
        };
    }

    fn assignStringLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        literal_id: checked.CheckedStringLiteralId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const text = self.module.checked_bodies.stringLiteral(literal_id);
        return try self.assignStringBytesLiteral(target, text, next);
    }

    fn lirStrLiteral(
        self: *ProcBodyBuilder,
        literal_id: checked.CheckedStringLiteralId,
    ) Allocator.Error!LIR.StrLiteral {
        const text = self.module.checked_bodies.stringLiteral(literal_id);
        return try self.parent.result.store.insertStringView(text, 0, @intCast(text.len));
    }

    fn assignStringBytesLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        text: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignStringBytesView(target, text, 0, @intCast(text.len), next);
    }

    fn assignStringBytesView(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        backing: []const u8,
        offset: u32,
        len: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralTargetForLayout(target, .str)) |info| {
            if (info.payload_layout != .str) {
                boxyLowerInvariant("boxy dynamic string literal descriptor did not resolve to string payload layout");
            }
            const payload = try self.addFrameLocal(.str);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .str_literal = try self.parent.result.store.insertStringView(backing, offset, len) },
                .next = box,
            } }, self.origin);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .str_literal = try self.parent.result.store.insertStringView(backing, offset, len) },
            .next = next,
        } }, self.origin);
    }

    fn assignBoolLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const variant = Common.boolDiscriminant(value);
        return try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
            .target = target,
            .variant_index = variant,
            .discriminant = variant,
            .payload = null,
            .next = next,
        } }, self.origin);
    }

    fn assignZst(self: *ProcBodyBuilder, target: LIR.LocalId, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = LIR.LocalSpan.empty(),
            .next = next,
        } }, self.origin);
    }

    fn assignList(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        elems: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_list = .{
            .target = target,
            .elems = try self.parent.result.store.addLocalSpan(elems),
            .next = next,
        } }, self.origin);
    }

    fn assignLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (try self.assignToFixedDescriptorBoundary(target, source, next)) |adapted| return adapted;
        const assign = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .local = source },
            .next = next,
        } }, self.origin);
        var transferred = try self.prependSetLocalDescriptorTransfer(target, source, .replace_existing, assign);
        transferred = try self.prependLocalDescriptorEnvironmentTransfer(target, source, .replace_existing, transferred);
        try self.recordTransferredLocalDescriptorEnvironment(target, source);
        return transferred;
    }

    fn assignLocalFromRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try self.assignLocal(target, source, next);
        if (self.parent.result.store.getLocal(source).boxy_desc != null) return continuation;

        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return continuation;
        const target_desc_local = target_desc.localOrNull() orelse return continuation;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return continuation;

        const materialization = try self.descriptorMaterializationForSourceStorageLocalRep(source, source_rep);
        continuation = try self.prependDescriptorArgMaterialization(materialization.initializer(target_desc_local), materialization.desc, continuation);
        return continuation;
    }

    fn assignToFixedDescriptorBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return null;
        const source_desc = self.parent.result.store.getLocal(source).boxy_desc orelse return null;
        if (std.meta.eql(target_desc, source_desc)) return null;

        const target_is_fixed = if (target_desc.localOrNull()) |local|
            self.localIsReadOnlyDescriptorInput(local)
        else
            true;
        if (!target_is_fixed) return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const adapter = try self.internMoveAdapter(.materialize, source_layout, target_layout);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
            .target = target,
            .source = source,
            .adapter = adapter,
            .source_desc = source_desc,
            .target_desc = target_desc,
            .source_mode = .move,
            .next = next,
        } }, self.glueOrigin());
    }

    fn assignNominalBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (target_layout == source_layout) {
            return if (target == source) next else try self.assignLocal(target, source, next);
        }

        if (self.isZstLocal(target)) {
            if (!self.isZstLocal(source)) {
                boxyLowerInvariant("nominal boundary tried to store non-zero-sized source into zero-sized target");
            }
            return try self.assignZst(target, next);
        }

        // A concrete non-box value crossing into dynamic box storage must be
        // boxed, not reinterpreted; the descriptor records the payload layout.
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        const target_is_box = target_layout_value.tag == .box or target_layout_value.tag == .box_of_zst or target_layout_value.tag == .erased_box;
        const source_is_box = source_layout_value.tag == .box or source_layout_value.tag == .box_of_zst or source_layout_value.tag == .erased_box;
        const source_is_list = source_layout_value.tag == .list or source_layout_value.tag == .list_of_zst;
        if (target_is_box and !source_is_box and !source_is_list) {
            const desc_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len))));
            try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
                .payload_layout = source_layout,
                .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(source_layout_value),
                .shape = LirProgram.BoxyDescShape.forStorage(source_layout_value),
            });
            const payload_desc = LIR.BoxyDescRef{ .static = desc_id };
            self.parent.result.store.setLocalBoxyDesc(target, payload_desc);
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = target,
                .payload = source,
                .payload_layout = source_layout,
                .payload_desc = payload_desc,
                .payload_mode = .move,
                .next = next,
            } }, self.glueOrigin());
        }

        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .nominal = .{ .backing_ref = source } },
            .next = next,
        } }, self.glueOrigin());
    }

    fn assignErasedCallableBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_function: FunctionChildren,
        source_function: FunctionChildren,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!try self.callableBoundaryNeedsAdapter(target_function, source_function)) {
            return if (target == source) next else try self.assignLocal(target, source, next);
        }

        const adapter = try self.emitCallableAdapterProc(source_function, target_function);
        const descriptor_captures = try self.collectCallableAdapterDescriptorCaptures(source_function, target_function);
        defer self.parent.allocator.free(descriptor_captures);

        const capture_local = try self.addFrameLocal(adapter.capture_layout);
        const capture_fields = try self.parent.allocator.alloc(LIR.LocalId, 1 + descriptor_captures.len);
        defer self.parent.allocator.free(capture_fields);
        const capture_needs_materialization = try self.parent.allocator.alloc(bool, descriptor_captures.len);
        defer self.parent.allocator.free(capture_needs_materialization);
        capture_fields[0] = source;

        var descriptor_materializations = std.ArrayList(DescriptorArgLocal).empty;
        defer descriptor_materializations.deinit(self.parent.allocator);
        var result_desc_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer result_desc_initializers.deinit(self.parent.allocator);

        const descriptor_snapshot = try self.snapshotDescriptorBindings();
        defer descriptor_snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(descriptor_snapshot);
        try self.bindLocalDescriptorEnvironment(source);

        for (descriptor_captures, 0..) |capture, index| {
            const desc_index = @backingInt(capture.desc);
            if (desc_index >= self.descriptor_locals.len) {
                boxyLowerInvariant("boxy callable adapter capture descriptor exceeded descriptor table");
            }
            const materializes_capture_rep =
                self.descriptorStorageRep(capture.materialize_rep) == self.descriptorStorageRep(capture.rep);
            const force_materialize_self_tag_descriptor =
                materializes_capture_rep and self.tagVariantRepForBoundary(capture.rep) != null;
            if (!force_materialize_self_tag_descriptor) {
                if (self.localEnvironmentDescriptorForRequirementAndRep(
                    source,
                    capture.desc,
                    capture.rep,
                )) |local| {
                    capture_fields[1 + index] = local;
                    capture_needs_materialization[index] = false;
                    continue;
                }
                if (materializes_capture_rep) {
                    if (self.descriptorLocalForRequirementAndRepOrNull(capture.desc, capture.rep)) |local| {
                        if (self.descriptorLocalAvailableFromSource(source, local)) {
                            capture_fields[1 + index] = local;
                            capture_needs_materialization[index] = false;
                            continue;
                        }
                    }
                }
                if (self.localEnvironmentDescriptorForRequirementAndRep(
                    source,
                    capture.desc,
                    capture.materialize_rep,
                )) |local| {
                    capture_fields[1 + index] = local;
                    capture_needs_materialization[index] = false;
                    continue;
                }
                if (self.descriptorLocalForRequirementAndRepOrNull(capture.desc, capture.materialize_rep)) |local| {
                    if (self.descriptorLocalAvailableFromSource(source, local)) {
                        capture_fields[1 + index] = local;
                        capture_needs_materialization[index] = false;
                        continue;
                    }
                }
                // The capture requirement belongs to the adapted function,
                // while materialize_rep belongs to the enclosing frame and can
                // therefore have a different requirement id. Reuse the frame
                // rep's explicit descriptor binding when it exists; rebuilding
                // its descriptor can lose the exact runtime box allocation
                // identity already established at the call site.
                if (self.descriptorLocalForRepOrNull(capture.materialize_rep)) |local| {
                    if (self.descriptorLocalAvailableFromSource(source, local)) {
                        capture_fields[1 + index] = local;
                        capture_needs_materialization[index] = false;
                        continue;
                    }
                }
            }

            capture_fields[1 + index] = try self.addFrameLocal(.opaque_ptr);
            capture_needs_materialization[index] = true;
        }

        // Every fresh capture copies a descriptor out of the enclosing frame,
        // so its materialization is chosen before the capture locals describe
        // those representations inside the adapter window.
        for (descriptor_captures, capture_fields[1..], capture_needs_materialization) |capture, local, needs_materialization| {
            if (!needs_materialization) continue;
            // A template dictionary's adapter binds the building frame's type
            // variables; a representation naming them is described through
            // those bindings.
            const materialization: DescriptorMaterialization = if (self.template_frame_descriptors and
                try self.descriptorTemplateNeedsCapturesForKnownRep(capture.materialize_rep))
                try self.descriptorMaterializationForSourceRep(capture.materialize_rep)
            else if (self.static_descriptor_materialization_scope) |scope|
                .{ .desc = try self.parent.staticDescRefForWorkerRepWithSourceMap(
                    capture.materialize_rep,
                    scope.sources.get(capture.desc),
                    scope.sources,
                    scope.context,
                ) }
            else
                try self.descriptorMaterializationForSourceRep(capture.materialize_rep);
            try descriptor_materializations.append(self.parent.allocator, materialization.initializer(local));
        }
        for (descriptor_captures, capture_fields[1..], capture_needs_materialization) |capture, local, needs_materialization| {
            if (!needs_materialization) continue;
            try self.setDescriptorRequirementLocalForRep(capture.desc, capture.materialize_rep, local);
            try self.setDescriptorRequirementLocalForRep(capture.desc, capture.rep, local);
        }

        var target_capture_index = descriptor_captures.len;
        while (target_capture_index > 0) {
            target_capture_index -= 1;
            try self.bindDescriptorCaptureTargetLocal(
                descriptor_captures[target_capture_index],
                capture_fields[1 + target_capture_index],
                &result_desc_initializers,
            );
        }

        const result_desc = try self.exactCallResultDescriptorRef(target_function.ret);
        try self.appendResultDescriptorInitializers(&result_desc_initializers, result_desc);

        var callable_bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer callable_bindings.deinit(self.parent.allocator);
        for (descriptor_captures, capture_fields[1..]) |capture, local| {
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, capture.desc, capture.rep, local);
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, capture.desc, capture.materialize_rep, local);
        }
        try self.recordLocalDescriptorEnvironment(target, target_function.rep, callable_bindings.items);

        if (self.parent.needsFrozenCallableRecipes()) {
            const fields = try self.parent.allocator.alloc(ProcedureBuilder.FrozenCaptureRecipe, 1 + descriptor_captures.len);
            defer self.parent.allocator.free(fields);
            fields[0] = .{ .value = source_function.rep };
            for (descriptor_captures, fields[1..]) |capture, *field| field.* = .{ .descriptor = .{ .worker_rep = capture.materialize_rep, .source_rep = capture.materialize_rep } };
            try self.parent.recordFrozenCallable(self.worker_layout.worker, self.literal_initializer, source_function.rep, target_function.rep, adapter.proc, adapter.capture_layout, self.erasedCallableOnDrop(adapter.capture_layout), target_function.ret, fields);
        }

        const assign_callable = try self.parent.result.store.addCFStmt(.{ .assign_packed_erased_fn = .{
            .target = target,
            .proc = adapter.proc,
            .capture = capture_local,
            .capture_layout = adapter.capture_layout,
            .on_drop = self.erasedCallableOnDrop(adapter.capture_layout),
            .result_desc = result_desc.desc,
            .next = next,
        } }, self.glueOrigin());

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = capture_local,
            .fields = try self.parent.result.store.addLocalSpan(capture_fields),
            .next = assign_callable,
        } }, self.glueOrigin());
        continuation = try self.prependDescriptorArgMaterializations(result_desc_initializers.items, continuation);

        return try self.prependDescriptorArgMaterializations(descriptor_materializations.items, continuation);
    }

    fn callableBoundaryNeedsAdapter(
        self: *ProcBodyBuilder,
        target_function: FunctionChildren,
        source_function: FunctionChildren,
    ) Allocator.Error!bool {
        if (target_function.arg_count != source_function.arg_count) {
            boxyLowerInvariant("boxy erased callable boundary saw mismatched function arity");
        }

        const target_args = self.functionArgChildren(target_function);
        const source_args = self.functionArgChildren(source_function);
        for (target_args, source_args) |target_arg, source_arg| {
            if (!try self.callableValueBoundaryIsDirect(target_arg.rep, source_arg.rep)) return true;
        }

        return !try self.callableValueBoundaryIsDirect(target_function.ret, source_function.ret);
    }

    fn repsUseSameDynamicBoxStorage(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        const target_runtime = self.workerRuntimeLayoutForRep(self.descriptorStorageRep(target_rep));
        const source_runtime = self.workerRuntimeLayoutForRep(self.descriptorStorageRep(source_rep));
        return switch (target_runtime) {
            .dynamic_box => |target_dynamic| switch (source_runtime) {
                .dynamic_box => |source_dynamic| target_dynamic.storage_layout == source_dynamic.storage_layout,
                .concrete => false,
            },
            .concrete => false,
        };
    }

    fn repsUseSameBoxStorage(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        const target_layout = self.workerRuntimeLayoutForRep(target_rep).layoutIdx();
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        const target_is_box = switch (self.parent.result.layouts.getLayout(target_layout).tag) {
            .box, .box_of_zst, .erased_box => true,
            .scalar, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => false,
        };
        return target_is_box and switch (self.parent.result.layouts.getLayout(source_layout).tag) {
            .box, .box_of_zst, .erased_box => true,
            .scalar, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => false,
        };
    }

    /// Whether a field crossing a representation boundary keeps its target
    /// template's static descriptor: neither side's representation carries
    /// runtime-determined identity, and the field crosses unchanged.
    fn boundaryFieldKeepsStaticDescriptor(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        const reps = self.parent.plan.representations.items;
        return !reps[@backingInt(target_rep)].contains_dynamic and
            !reps[@backingInt(source_rep)].contains_dynamic and
            self.representationBoundaryIsDirect(target_rep, source_rep);
    }

    fn representationBoundaryIsDirect(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        if (self.workerRuntimeLayoutForRep(target_rep).layoutIdx() != self.workerRuntimeLayoutForRep(source_rep).layoutIdx()) {
            return false;
        }
        if (self.repIsFullyConcrete(target_rep) and self.repIsFullyConcrete(source_rep)) return true;
        return target_rep == source_rep and
            self.descriptorStorageRep(target_rep) == self.descriptorStorageRep(source_rep);
    }

    /// Whether a value crossing between a callable's two sides needs no
    /// conversion. An argument, or a function-typed result that is itself
    /// called later, reaches an erased call, which passes each argument's
    /// descriptors keyed by that argument's descriptor positions, so the two
    /// sides must agree on them.
    fn callableValueBoundaryIsDirect(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        if (!self.representationBoundaryIsDirect(target_rep, source_rep)) return false;
        if (target_rep == source_rep) return true;
        if (!self.repIsFullyConcrete(target_rep) or !self.repIsFullyConcrete(source_rep)) return false;
        return !try self.repHasHiddenDescriptorParams(target_rep) and
            !try self.repHasHiddenDescriptorParams(source_rep);
    }

    fn repHasHiddenDescriptorParams(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!bool {
        var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
        defer params.deinit(self.parent.allocator);
        try self.collectAllHiddenDescriptorParamsForRep(rep_id, &params);
        return params.items.len != 0;
    }

    /// The adapter from `source_function` to `target_function`, reserving its
    /// header and queueing its body at the first use.
    fn emitCallableAdapterProc(
        self: *ProcBodyBuilder,
        source_function: FunctionChildren,
        target_function: FunctionChildren,
    ) Allocator.Error!CallableAdapterCacheEntry {
        if (source_function.arg_count != target_function.arg_count) {
            boxyLowerInvariant("boxy callable adapter requested for mismatched function arity");
        }

        const descriptor_captures = try self.collectCallableAdapterDescriptorCaptures(source_function, target_function);
        var captures_owned = true;
        defer if (captures_owned) self.parent.allocator.free(descriptor_captures);
        cached: for (self.parent.callable_adapter_cache.items) |entry| {
            if (entry.source_rep != source_function.rep or entry.target_rep != target_function.rep) continue;
            if (entry.materialize_reps.len != descriptor_captures.len) continue;
            for (entry.materialize_reps, descriptor_captures) |materialize_rep, capture| {
                if (materialize_rep != capture.materialize_rep) continue :cached;
            }
            return entry;
        }
        const materialize_reps = try self.parent.allocator.alloc(Plan.TypeRepId, descriptor_captures.len);
        errdefer self.parent.allocator.free(materialize_reps);
        for (materialize_reps, descriptor_captures) |*materialize_rep, capture| materialize_rep.* = capture.materialize_rep;

        const source_closure_layout = self.workerRuntimeLayoutForRep(source_function.rep).layoutIdx();
        const capture_layout = try self.callableAdapterCaptureLayout(source_closure_layout, descriptor_captures.len);
        const saved_tail_builder = self.parent.result.store.tail_call_builder;
        self.parent.result.store.tail_call_builder = null;
        defer self.parent.result.store.tail_call_builder = saved_tail_builder;
        const job = try self.parent.allocator.create(ProcedureBuilder.CallableAdapterJob);
        var job_owned = true;
        errdefer if (job_owned) self.parent.allocator.destroy(job);
        job.adapter_proc = ProcBodyBuilder.initSyntheticAdapter(self.parent, self.module, self.worker_layout, self.scaffoldOrigin());
        job.descriptor_captures = &.{};
        job.target_arg_locals = &.{};
        job.descriptor_locals = &.{};
        job.capture_descriptor_initializers = .empty;
        errdefer if (job_owned) job.deinit(self.parent.allocator);
        job.descriptor_captures = descriptor_captures;
        captures_owned = false;
        const adapter_proc = &job.adapter_proc;

        const source_closure = try adapter_proc.addFrameLocal(source_closure_layout);
        const target_args = self.functionArgChildren(target_function);
        job.target_arg_locals = try self.parent.allocator.alloc(LIR.LocalId, target_function.arg_count);
        for (target_args, job.target_arg_locals) |arg, *local| {
            local.* = try adapter_proc.addArgLocalForRep(arg.rep);
        }
        const capture_arg = try adapter_proc.addArgLocal(.opaque_ptr);
        job.descriptor_locals = try self.parent.allocator.alloc(LIR.LocalId, descriptor_captures.len);
        for (descriptor_captures, job.descriptor_locals) |capture, *local| {
            local.* = try adapter_proc.addFrameLocal(.opaque_ptr);
            try adapter_proc.bindDescriptorCaptureSourceLocal(capture, local.*);
        }
        var capture_index = descriptor_captures.len;
        while (capture_index > 0) {
            capture_index -= 1;
            try adapter_proc.bindDescriptorCaptureTargetLocal(
                descriptor_captures[capture_index],
                job.descriptor_locals[capture_index],
                &job.capture_descriptor_initializers,
            );
        }
        const erased_arg_desc_params = try adapter_proc.bindErasedArgumentDescriptorParams(target_function);
        const erased_reuse_arg = try adapter_proc.addArgLocal(try self.parent.result.layouts.insertErasedCallable());

        const ret_layout = adapter_proc.workerRuntimeLayoutForRep(target_function.ret).layoutIdx();
        const ret_local = try adapter_proc.addFrameLocalForRepWithFreshDescriptor(target_function.ret);
        const args_span = try self.parent.result.store.addLocalSpan(adapter_proc.arg_locals.items);
        const proc_symbol = self.parent.symbols.fresh();
        const proc_id = try self.parent.result.store.addProcSpec(.{
            .name = lirSymbol(proc_symbol),
            .identity = LIR.ProcIdentity.programLocal("boxy", @backingInt(proc_symbol)),
            .args = args_span,
            .body = null,
            .ret_layout = ret_layout,
            .abi = .erased_callable,
            .erased_reuse_arg = erased_reuse_arg,
            .erased_call_args = try adapter_proc.erasedCallArgsPlan(job.target_arg_locals),
            .boxy_runtime_entry = true,
            .stack_probe = self.parent.stackProbeForProc(args_span, LIR.LocalSpan.empty(), ret_layout),
        }, adapter_proc.origin.loc);
        const cache_len = self.parent.callable_adapter_cache.items.len;
        errdefer self.parent.callable_adapter_cache.shrinkRetainingCapacity(cache_len);
        const cache_entry = CallableAdapterCacheEntry{
            .source_rep = source_function.rep,
            .target_rep = target_function.rep,
            .materialize_reps = materialize_reps,
            .proc = proc_id,
            .capture_layout = capture_layout,
        };
        try self.parent.callable_adapter_cache.append(self.parent.allocator, cache_entry);
        job.proc_id = proc_id;
        job.source_function = source_function;
        job.target_function = target_function;
        job.capture_layout = capture_layout;
        job.source_closure = source_closure;
        job.capture_arg = capture_arg;
        job.erased_arg_desc_params = erased_arg_desc_params;
        job.ret_local = ret_local;
        job.ret_layout = ret_layout;
        job.args_span = args_span;
        try self.parent.appendProcJob(.{ .callable_adapter = job });
        job_owned = false;
        return cache_entry;
    }

    fn callableAdapterArgumentDescriptorCaptureOffsets(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        descriptor_captures: []const CallableAdapterDescriptorCapture,
        capture_layout_idx: layout.Idx,
    ) Allocator.Error!LIR.BoxySpan {
        const capture_layout = self.parent.result.layouts.getLayout(capture_layout_idx);
        if (capture_layout.tag != .struct_) {
            boxyLowerInvariant("boxy callable adapter argument descriptors required struct capture storage");
        }
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        const start = self.parent.result.boxy_erased_arg_desc_offsets.items.len;
        for (self.functionArgChildren(function), 0..) |arg, arg_index| {
            var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer params.deinit(self.parent.allocator);
            try self.collectHiddenDescriptorParamsForRep(.all, arg.rep, &params, &seen_reps, &seen_descs);
            for (params.items, 0..) |param, descriptor_index| {
                if (arg_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy callable adapter argument descriptor key exceeded its index range");
                }
                if (descriptor_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy callable adapter argument descriptor index exceeded its key range");
                }
                const source = try self.erasedArgumentDescriptorParamSource(params.items, descriptor_index);
                if (source.read != .call_key) continue;
                var capture_index: ?u32 = null;
                for (descriptor_captures, 0..) |capture, index| {
                    if (capture.desc != param.desc) continue;
                    if (self.descriptorStorageRep(capture.rep) != self.descriptorStorageRep(param.rep) and
                        self.descriptorStorageRep(capture.materialize_rep) != self.descriptorStorageRep(param.rep))
                    {
                        continue;
                    }
                    if (capture_index != null) {
                        boxyLowerInvariant("boxy callable adapter argument descriptor matched multiple capture fields");
                    }
                    capture_index = @intCast(index + 1);
                }
                const index = capture_index orelse
                    boxyLowerInvariant("boxy callable adapter argument descriptor had no exact capture field");
                try self.parent.result.boxy_erased_arg_desc_offsets.append(
                    self.parent.allocator,
                    .{
                        .key = .{
                            .arg_index = @intCast(arg_index),
                            .descriptor_index = @intCast(descriptor_index),
                        },
                        .offset = self.parent.result.layouts.getStructFieldOffsetByOriginalIndex(capture_layout.getStruct().idx, index),
                    },
                );
            }
        }
        return .{
            .start = @intCast(start),
            .len = @intCast(self.parent.result.boxy_erased_arg_desc_offsets.items.len - start),
        };
    }

    /// Every descriptor requirement in either callable signature becomes one
    /// adapter capture. A requirement of the callee side of a planned call
    /// boundary is materialized from the caller representation the call's
    /// substitution names for it; every other requirement is described by the
    /// enclosing frame's own descriptor for that representation.
    fn collectCallableAdapterDescriptorCaptures(
        self: *ProcBodyBuilder,
        source_function: FunctionChildren,
        target_function: FunctionChildren,
    ) Allocator.Error![]CallableAdapterDescriptorCapture {
        var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
        defer params.deinit(self.parent.allocator);
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        for ([_]FunctionChildren{ target_function, source_function }) |function| {
            for (self.functionArgChildren(function)) |arg| {
                try self.collectHiddenDescriptorParamsForRep(.all, arg.rep, &params, &seen_reps, &seen_descs);
            }
            try self.collectHiddenDescriptorParamsForRep(.all, function.ret, &params, &seen_reps, &seen_descs);
        }

        const captures = try self.parent.allocator.alloc(CallableAdapterDescriptorCapture, params.items.len);
        for (params.items, captures) |param, *capture| {
            capture.* = .{
                .desc = param.desc,
                .rep = param.rep,
                .materialize_rep = self.callBoundarySubstitutedRep(param.rep),
                .source_type = param.source_type,
            };
        }
        return captures;
    }

    /// The caller representation the active call boundary substitutes for
    /// a callee worker representation, or the representation itself when it
    /// already belongs to the enclosing frame.
    fn callBoundarySubstitutedRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
        for (self.call_boundary_substitution) |arg| {
            if (self.repQuery().descriptorArgumentIdentityRep(arg.worker_rep) == identity_rep) return arg.rep;
        }
        return rep_id;
    }

    fn callableAdapterCaptureLayout(
        self: *ProcBodyBuilder,
        source_closure_layout: layout.Idx,
        descriptor_count: usize,
    ) Allocator.Error!layout.Idx {
        const fields = try self.parent.allocator.alloc(layout.StructField, 1 + descriptor_count);
        defer self.parent.allocator.free(fields);
        fields[0] = .{ .index = 0, .layout = source_closure_layout };
        for (fields[1..], 0..) |*field, index| {
            if (index + 1 > std.math.maxInt(u32)) {
                boxyLowerInvariant("boxy callable adapter capture field index exceeded layout range");
            }
            field.* = .{
                .index = @intCast(index + 1),
                .layout = .opaque_ptr,
            };
        }
        return try self.parent.result.layouts.putStructFields(fields);
    }

    fn prependCallableAdapterCaptureBindings(
        self: *ProcBodyBuilder,
        capture_arg: LIR.LocalId,
        capture_layout: layout.Idx,
        source_closure: LIR.LocalId,
        descriptor_locals: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const capture_value = try self.addFrameLocal(capture_layout);
        var continuation = next;
        var index = descriptor_locals.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.prependErasedCaptureSlotRead(descriptor_locals[index], capture_value, @intCast(index + 1), continuation);
        }
        continuation = try self.prependErasedCaptureSlotRead(source_closure, capture_value, 0, continuation);

        const args = [_]LIR.LocalId{capture_arg};
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = capture_value,
            .op = .erased_capture_load,
            .rc_effect = LIR.LowLevel.erased_capture_load.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&args),
            .next = continuation,
        } }, self.scaffoldOrigin());
    }

    fn bindDescriptorCaptureSourceLocal(
        self: *ProcBodyBuilder,
        capture: CallableAdapterDescriptorCapture,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        try self.ensureDescriptorLocals();
        try self.markReadOnlyDescriptorInput(local);
        const source_rep = capture.materialize_rep;
        try self.bindDescriptorRequirementLocalForRep(capture.desc, source_rep, local, false);
        try self.bindDescriptorIdentityLocalForRep(source_rep, local, false);
    }

    fn bindDescriptorCaptureTargetLocal(
        self: *ProcBodyBuilder,
        capture: CallableAdapterDescriptorCapture,
        source_local: LIR.LocalId,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!void {
        const source_rep = capture.materialize_rep;
        const target_local = if (self.representationBoundaryIsDirect(capture.rep, source_rep))
            source_local
        else adapted: {
            const adapted_info = try self.adapterDescriptorForCallBoundary(
                capture.rep,
                source_rep,
                .{ .desc = .{ .local = source_local } },
                initializers,
            );
            try self.appendResultDescriptorInitializers(initializers, adapted_info);
            const adapted_desc = adapted_info.desc orelse
                boxyLowerInvariant("boxy callable adapter capture produced no target descriptor");
            break :adapted adapted_desc.localOrNull() orelse materialize: {
                const local = try self.addFrameLocal(.opaque_ptr);
                try initializers.append(self.parent.allocator, .{
                    .local = local,
                    .materialize = adapted_desc,
                });
                break :materialize local;
            };
        };

        try self.bindDescriptorRequirementLocalForRep(capture.desc, capture.rep, target_local, true);
        try self.bindDescriptorIdentityLocalForRep(capture.rep, target_local, true);
    }

    fn repOwnsDescriptor(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
    ) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        return if (rep.descriptor) |rep_desc| rep_desc == desc else false;
    }

    fn repOwnsShapeDescriptor(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
    ) bool {
        const identity_rep = self.descriptorShapeIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        return if (rep.descriptor) |rep_desc| rep_desc == desc else false;
    }

    fn descriptorShapeIdentityRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.descriptor != null) return rep_id;
        return self.parent.descriptorIdentityRep(rep_id);
    }

    fn appendLocalDescriptorEnvironmentBinding(
        self: *ProcBodyBuilder,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        for (bindings.items) |binding| {
            if (binding.desc != desc or self.descriptorStorageRep(binding.rep) != identity_rep) continue;
            // One checked type variable can occur in multiple values of an
            // aggregate. Its requirement and storage identity prove that the
            // runtime descriptor is shared, so retain the first binding.
            return;
        }
        try bindings.append(self.parent.allocator, .{
            .desc = desc,
            .rep = identity_rep,
            .local = local,
        });
    }

    fn appendDescriptorIdentityLocalEnvironmentBinding(
        self: *ProcBodyBuilder,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        if (!self.repOwnsDescriptor(rep_id, desc)) return;
        const identity_rep = self.descriptorStorageRep(rep_id);
        try self.appendLocalDescriptorEnvironmentBinding(bindings, desc, identity_rep, local);
    }

    fn recordLocalDescriptorEnvironment(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        bindings: []const LocalDescriptorEnvironmentBinding,
    ) Allocator.Error!void {
        if (bindings.len == 0) return;
        const owned = try self.parent.allocator.dupe(LocalDescriptorEnvironmentBinding, bindings);
        errdefer self.parent.allocator.free(owned);
        for (self.local_descriptor_environments.items) |*env| {
            if (env.local != local) continue;
            self.parent.allocator.free(env.bindings);
            env.* = .{
                .local = local,
                .rep = rep_id,
                .bindings = owned,
            };
            return;
        }
        try self.local_descriptor_environments.append(self.parent.allocator, .{
            .local = local,
            .rep = rep_id,
            .bindings = owned,
        });
    }

    fn recordAggregateLocalDescriptorEnvironment(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        fields: []const LIR.LocalId,
    ) Allocator.Error!void {
        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        for (fields) |field| {
            const env = self.localDescriptorEnvironmentForLocal(field) orelse continue;
            for (env.bindings) |binding| {
                try self.appendLocalDescriptorEnvironmentBinding(&bindings, binding.desc, binding.rep, binding.local);
            }
        }
        try self.recordLocalDescriptorEnvironment(target, target_rep, bindings.items);
    }

    fn recordDirectCallResultDescriptorEnvironment(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
    ) Allocator.Error!void {
        if (hidden_args.len != hidden_locals.len) {
            boxyLowerInvariant("boxy direct call result descriptor environment saw mismatched hidden args");
        }
        if (hidden_args.len == 0) return;

        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        for (hidden_args, hidden_locals) |arg, hidden| {
            // The result's environment describes only types inside the result.
            if (!try self.repQuery().repSubtreeContainsRep(result_rep, arg.worker_rep)) continue;
            const local_rep = self.directCallHiddenDescriptorLocalRep(arg, hidden);
            try self.appendLocalDescriptorEnvironmentBinding(&bindings, arg.worker_desc, local_rep, hidden.local);
            try self.appendDescriptorIdentityLocalEnvironmentBinding(&bindings, arg.worker_desc, local_rep, hidden.local);
            if (self.directCallHiddenDescriptorUsesCallShape(arg) and
                self.descriptorStorageRep(arg.worker_rep) != self.descriptorStorageRep(local_rep))
            {
                try self.appendLocalDescriptorEnvironmentBinding(&bindings, arg.worker_desc, arg.worker_rep, hidden.local);
                try self.appendDescriptorIdentityLocalEnvironmentBinding(&bindings, arg.worker_desc, arg.worker_rep, hidden.local);
            }
        }
        try self.recordLocalDescriptorEnvironment(local, result_rep, bindings.items);
    }

    fn localDescriptorEnvironmentForLocal(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
    ) ?LocalDescriptorEnvironment {
        var index = self.local_descriptor_environments.items.len;
        while (index > 0) {
            index -= 1;
            const env = self.local_descriptor_environments.items[index];
            if (env.local == local) return env;
        }
        return null;
    }

    fn localEnvironmentDescriptorForRep(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const env = self.localDescriptorEnvironmentForLocal(local) orelse return null;
        const identity_rep = self.descriptorStorageRep(rep_id);
        var found: ?LIR.LocalId = null;
        for (env.bindings) |binding| {
            if (self.descriptorStorageRep(binding.rep) != identity_rep) continue;
            if (found != null and found.? != binding.local) {
                boxyLowerInvariant("boxy local descriptor environment had multiple identities for one representation");
            }
            found = binding.local;
        }
        return found;
    }

    fn localEnvironmentDescriptorForRequirementAndRep(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const env = self.localDescriptorEnvironmentForLocal(local) orelse return null;
        const identity_rep = self.descriptorStorageRep(rep_id);
        var found: ?LIR.LocalId = null;
        for (env.bindings) |binding| {
            if (binding.desc != desc or self.descriptorStorageRep(binding.rep) != identity_rep) continue;
            if (found != null and found.? != binding.local) {
                boxyLowerInvariant("boxy local descriptor environment had multiple bindings for one exact requirement");
            }
            found = binding.local;
        }
        return found;
    }

    fn bindLocalDescriptorEnvironment(self: *ProcBodyBuilder, local: LIR.LocalId) Allocator.Error!void {
        const env = self.localDescriptorEnvironmentForLocal(local) orelse return;
        try self.ensureDescriptorLocals();
        for (env.bindings) |binding| {
            try self.bindDescriptorRequirementLocalForRep(binding.desc, binding.rep, binding.local, false);
        }
    }

    fn descriptorLocalAvailableFromSource(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        descriptor_local: LIR.LocalId,
    ) bool {
        if (self.localIsReadOnlyDescriptorInput(descriptor_local)) return true;
        if (self.parent.result.store.getLocal(source).boxy_desc) |desc| {
            if (desc.localOrNull() == descriptor_local) return true;
        }
        const env = self.localDescriptorEnvironmentForLocal(source) orelse return false;
        for (env.bindings) |binding| {
            if (binding.local == descriptor_local) return true;
        }
        return false;
    }

    fn propagateLocalDescriptorEnvironmentToField(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
    ) Allocator.Error!void {
        const env = self.localDescriptorEnvironmentForLocal(source) orelse return;
        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        for (env.bindings) |binding| {
            if (!try self.repSubtreeContainsDescriptor(target_rep, binding.desc)) continue;
            try self.appendLocalDescriptorEnvironmentBinding(&bindings, binding.desc, binding.rep, binding.local);
        }
        try self.recordLocalDescriptorEnvironment(target, target_rep, bindings.items);

        const identity_target = self.descriptorStorageRep(target_rep);
        const target_info = self.parent.plan.representations.items[@backingInt(identity_target)];
        const target_desc = target_info.descriptor orelse return;
        for (bindings.items) |binding| {
            if (binding.desc == target_desc and self.descriptorStorageRep(binding.rep) == identity_target) {
                self.parent.result.store.setLocalBoxyDesc(target, .{ .local = binding.local });
                return;
            }
        }
    }

    fn recordDescriptorEnvironmentFromDescriptorLocal(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        desc_local: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.recordDescriptorEnvironmentFromDescriptorRef(
            local,
            rep_id,
            .{ .local = desc_local },
            next,
        );
    }

    fn recordDescriptorEnvironmentFromDescriptorRef(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        var initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer initializers.deinit(self.parent.allocator);
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();

        try self.collectDescriptorEnvironmentForRep(
            rep_id,
            desc_ref,
            &bindings,
            &initializers,
            &seen,
        );
        try self.recordLocalDescriptorEnvironment(local, rep_id, bindings.items);
        return try self.prependDescriptorArgMaterializations(initializers.items, next);
    }

    fn collectShapeDescriptorEnvironmentForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const identity_rep = self.descriptorShapeIdentityRep(rep_id);
        return try self.collectDescriptorEnvironmentForIdentityRep(identity_rep, desc_ref, bindings, initializers, seen);
    }

    /// One pending step of a descriptor environment walk.
    const DescriptorEnvironmentAction = union(enum) {
        /// Bind the descriptors of an identity representation described by
        /// `desc_ref`.
        visit: struct { identity_rep: Plan.TypeRepId, desc_ref: LIR.BoxyDescRef },
        /// Read one nested descriptor out of `parent_desc`, then walk it.
        nested: struct { nested_rep: Plan.TypeRepId, parent_desc: LIR.BoxyDescRef, nested_index: u32 },
    };

    fn collectDescriptorEnvironmentForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        return try self.collectDescriptorEnvironmentForIdentityRep(self.descriptorStorageRep(rep_id), desc_ref, bindings, initializers, seen);
    }

    /// Bind, in pre-order, the descriptor requirements `root` and the nested
    /// descriptors it carries name, reading each nested descriptor into a
    /// local of its own.
    fn collectDescriptorEnvironmentForIdentityRep(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        root_desc_ref: LIR.BoxyDescRef,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var actions: std.ArrayList(DescriptorEnvironmentAction) = .empty;
        defer actions.deinit(allocator);
        try actions.append(allocator, .{ .visit = .{ .identity_rep = root, .desc_ref = root_desc_ref } });
        while (actions.pop()) |action| switch (action) {
            .nested => |nested| {
                const nested_local = try self.addFrameLocal(.opaque_ptr);
                switch (nested.parent_desc) {
                    .static => {
                        const materialization = try self.descriptorMaterializationForKnownRep(nested.nested_rep);
                        try initializers.append(allocator, materialization.initializer(nested_local));
                    },
                    .local, .runtime, .dict_method_arg, .dict_method_hidden => try initializers.append(allocator, .{
                        .local = nested_local,
                        .materialize = nested.parent_desc,
                        .nested_index = nested.nested_index,
                    }),
                }
                try actions.append(allocator, .{ .visit = .{
                    .identity_rep = self.descriptorStorageRep(nested.nested_rep),
                    .desc_ref = .{ .local = nested_local },
                } });
            },
            .visit => |visit| {
                var identity_rep = visit.identity_rep;
                const desc_ref = visit.desc_ref;
                // A wrapper's backing shape shares its descriptor.
                while (true) {
                    const seen_entry = try seen.getOrPut(identity_rep);
                    if (seen_entry.found_existing) break;

                    if (desc_ref.localOrNull()) |local| {
                        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
                        if (rep.descriptor) |desc| {
                            try self.appendLocalDescriptorEnvironmentBinding(bindings, desc, identity_rep, local);
                        }
                    }

                    if (self.parent.descriptorBackingShapeRep(identity_rep)) |backing_rep| {
                        identity_rep = self.descriptorStorageRep(backing_rep);
                        continue;
                    }

                    if (self.repIsOpenRecord(identity_rep)) break;
                    var slots = std.ArrayList(ProcedureBuilder.NestedDescriptorSlot).empty;
                    defer slots.deinit(allocator);
                    try self.parent.appendNestedDescriptorSlots(
                        identity_rep,
                        self.parent.descriptorPayloadLayoutForRep(identity_rep),
                        &slots,
                    );
                    var position = slots.items.len;
                    while (position > 0) {
                        position -= 1;
                        const slot = slots.items[position];
                        // Only a child whose stored value carries a runtime descriptor can
                        // bind descriptor requirements.
                        if (!self.parent.nestedDescriptorSlotCarriesRuntimeDesc(slot)) continue;
                        try actions.append(allocator, .{ .nested = .{
                            .nested_rep = self.parent.nestedDescriptorSlotDescRep(slot),
                            .parent_desc = desc_ref,
                            .nested_index = @intCast(position),
                        } });
                    }
                    break;
                }
            },
        };
    }

    fn repSubtreeContainsDescriptor(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
    ) Allocator.Error!bool {
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.repSubtreeContainsDescriptorInner(rep_id, desc, &seen);
    }

    fn repSubtreeContainsDescriptorInner(
        self: *ProcBodyBuilder,
        root: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |rep_id| {
            const entry = try seen.getOrPut(rep_id);
            if (entry.found_existing) continue;
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            if (rep.descriptor == desc) return true;
            for (self.parent.plan.childSlice(rep.children)) |child| try pending.append(allocator, child.rep);
            for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
                for (self.parent.plan.childSlice(variant.payloads)) |payload| try pending.append(allocator, payload.rep);
            }
        }
        return false;
    }

    fn setDescriptorRequirementLocalForRep(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        try self.ensureDescriptorLocals();
        const desc_index = @backingInt(desc);
        if (desc_index >= self.descriptor_locals.len or desc_index >= self.descriptor_local_reps.len) {
            boxyLowerInvariant("boxy descriptor binding exceeded descriptor table");
        }
        const identity_rep = self.descriptorStorageRep(rep_id);
        if (self.descriptor_locals[desc_index] == null or
            self.descriptor_local_reps[desc_index] == null or
            self.descriptor_local_reps[desc_index].? == identity_rep)
        {
            const preserves = self.descriptor_locals[desc_index] == local and
                self.descriptor_local_reps[desc_index] == identity_rep;
            const preserves_bound = preserves and self.descriptor_bound[desc_index];
            const preserves_evidence = preserves and self.descriptor_evidence_bound[desc_index];
            self.descriptor_locals[desc_index] = local;
            self.descriptor_local_reps[desc_index] = identity_rep;
            self.descriptor_bound[desc_index] = preserves_bound;
            self.descriptor_evidence_bound[desc_index] = preserves_evidence;
            return;
        }

        if (self.descriptorRepBindingIndex(desc, identity_rep)) |index| {
            const existing = self.descriptor_rep_bindings.items[index];
            self.descriptor_rep_bindings.items[index] = .{
                .desc = desc,
                .rep = identity_rep,
                .local = local,
                .bound = existing.local == local and existing.bound,
                .evidence_bound = existing.local == local and existing.evidence_bound,
            };
            return;
        }
        try self.descriptor_rep_bindings.append(self.parent.allocator, .{
            .desc = desc,
            .rep = identity_rep,
            .local = local,
            .bound = false,
            .evidence_bound = false,
        });
    }

    fn markDescriptorRequirementBoundForRep(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const desc_index = @backingInt(desc);
        if (desc_index < self.descriptor_local_reps.len and self.descriptor_local_reps[desc_index] == identity_rep) {
            self.descriptor_bound[desc_index] = true;
            self.descriptor_evidence_bound[desc_index] = true;
            return;
        }
        if (self.descriptorRepBindingIndex(desc, identity_rep)) |index| {
            self.descriptor_rep_bindings.items[index].bound = true;
            self.descriptor_rep_bindings.items[index].evidence_bound = true;
            return;
        }
        boxyLowerInvariant("boxy descriptor bound marker had no representation-local binding");
    }

    fn bindDescriptorRequirementLocalForRep(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
        bind_slot: bool,
    ) Allocator.Error!void {
        try self.ensureDescriptorLocals();
        const desc_index = @backingInt(desc);
        if (desc_index >= self.descriptor_locals.len or desc_index >= self.descriptor_slot_reps.len) {
            boxyLowerInvariant("boxy descriptor binding exceeded descriptor table");
        }
        if (bind_slot) {
            self.descriptor_slots[desc_index] = local;
            self.descriptor_slot_reps[desc_index] = self.descriptorStorageRep(rep_id);
        }
        try self.setDescriptorRequirementLocalForRep(desc, rep_id, local);
        self.markDescriptorRequirementBoundForRep(desc, rep_id);
    }

    fn bindDescriptorIdentityLocalForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
        bind_slot: bool,
    ) Allocator.Error!void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        const desc = rep.descriptor orelse return;
        try self.bindDescriptorRequirementLocalForRep(desc, identity_rep, local, bind_slot);
    }

    fn functionArgChildren(self: *ProcBodyBuilder, function: FunctionChildren) []const Plan.RepChild {
        const rep = self.parent.plan.representations.items[@backingInt(function.rep)];
        const children = self.parent.plan.childSlice(rep.children);
        return children[function.args_start..][0..function.arg_count];
    }

    /// A representation is fully concrete when its value carries no
    /// descriptor-driven storage: it needs neither a static descriptor nor any
    /// dynamically boxed field. Such a value's reference counting is entirely
    /// determined by its layout, so two fully-concrete values with byte-identical
    /// layouts are interchangeable without any conversion.
    fn repIsFullyConcrete(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        return rep.descriptor == null and !rep.contains_dynamic;
    }

    fn repsHaveSameSourceType(
        self: *const ProcBodyBuilder,
        a: Plan.TypeRepId,
        b: Plan.TypeRepId,
    ) bool {
        const identity_a = self.descriptorStorageRep(a);
        const identity_b = self.descriptorStorageRep(b);
        const a_rep = self.parent.plan.representations.items[@backingInt(identity_a)];
        const b_rep = self.parent.plan.representations.items[@backingInt(identity_b)];
        return planTypeRefEql(a_rep.source_type, b_rep.source_type);
    }

    /// The representation that describes a constructed aggregate field's
    /// stored bytes: the target's, except at a bare type parameter, whose
    /// erased box holds the supplying payload as the source describes it.
    fn constructedFieldStorageRep(self: *const ProcBodyBuilder, field: AggregateDescriptorField) Plan.TypeRepId {
        return if (self.repIsBareDynamic(field.target_rep)) field.source_rep else field.target_rep;
    }

    /// A record whose row is still open. Its box holds the complete record
    /// the value was built from, which only the value's own descriptor
    /// describes; the representation's fields are a view of that record.
    fn repIsOpenRecord(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        return self.parent.plan.repIsOpenRecord(self.descriptorStorageRep(rep_id));
    }

    /// A bare dynamic representation carries no structural payload shape of
    /// its own. When a concrete value is boxed into it, the source descriptor is
    /// the only explicit description of the allocation that was actually made.
    fn repIsBareDynamic(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        return rep.kind == .dynamic and
            rep.children.len == 0 and
            rep.declared_fields.len == 0 and
            rep.tag_variants.len == 0;
    }

    /// Whether a value laid out as `a` can be reinterpreted as a value laid out
    /// as `b` with no byte-level conversion: the two layouts have the same tag,
    /// size, and recursively-interchangeable children. Distinct recursive size
    /// cycles are interned under distinct indices, so a seen set pairs the two
    /// cycles and treats a re-encountered pair as already matched.
    fn boundaryLayoutsInterchangeable(
        self: *ProcBodyBuilder,
        a: layout.Idx,
        b: layout.Idx,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.boundaryLayoutsInterchangeableInner(a, b, &seen);
    }

    /// Whether two layouts are interchangeable across a boundary: every
    /// layout pair they reach agrees. A pair already seen agrees unless some
    /// other position proves otherwise, which is how recursive layouts
    /// terminate.
    fn boundaryLayoutsInterchangeableInner(
        self: *ProcBodyBuilder,
        root_a: layout.Idx,
        root_b: layout.Idx,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        const layouts = &self.parent.result.layouts;
        var pending: std.ArrayList([2]layout.Idx) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, .{ root_a, root_b });
        while (pending.pop()) |pair| {
            const a = pair[0];
            const b = pair[1];
            if (a == b) continue;

            const a_layout = layouts.getLayout(a);
            const b_layout = layouts.getLayout(b);
            if (a_layout.tag != b_layout.tag) return false;
            if (layouts.layoutSize(a_layout) != layouts.layoutSize(b_layout)) return false;

            const key = (@as(u64, @backingInt(a)) << 32) | @as(u64, @backingInt(b));
            if ((try seen.getOrPut(key)).found_existing) continue;

            switch (a_layout.tag) {
                .scalar => if (!std.meta.eql(a_layout.getScalar(), b_layout.getScalar())) return false,
                .zst, .erased_box => {},
                .box, .box_of_zst => try pending.append(allocator, .{
                    layouts.getBoxInfo(a_layout).elem_layout_idx,
                    layouts.getBoxInfo(b_layout).elem_layout_idx,
                }),
                .list, .list_of_zst => try pending.append(allocator, .{
                    layouts.getListInfo(a_layout).elem_layout_idx,
                    layouts.getListInfo(b_layout).elem_layout_idx,
                }),
                .struct_ => {
                    const a_info = layouts.getStructInfo(a_layout);
                    const b_info = layouts.getStructInfo(b_layout);
                    if (a_info.fields.len != b_info.fields.len) return false;
                    var i: u32 = 0;
                    while (i < a_info.fields.len) : (i += 1) {
                        const a_field = a_info.fields.get(i);
                        const b_field = b_info.fields.get(i);
                        if (a_field.is_padding != b_field.is_padding) return false;
                        try pending.append(allocator, .{ a_field.layout, b_field.layout });
                    }
                },
                .tag_union => {
                    const a_info = layouts.getTagUnionInfo(a_layout);
                    const b_info = layouts.getTagUnionInfo(b_layout);
                    if (a_info.variants.len != b_info.variants.len) return false;
                    if (a_info.discriminant_offset != b_info.discriminant_offset) return false;
                    var i: u32 = 0;
                    while (i < a_info.variants.len) : (i += 1) {
                        try pending.append(allocator, .{
                            a_info.variants.get(i).payload_layout,
                            b_info.variants.get(i).payload_layout,
                        });
                    }
                },
                .closure, .erased_callable, .ptr => return false,
            }
        }
        return true;
    }

    fn assignRepresentationBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignRepresentationBoundaryWithSourceMode(
            target,
            source,
            target_rep,
            source_rep,
            .borrow,
            next,
        );
    }

    fn assignRepresentationBoundaryConsumingSource(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignRepresentationBoundaryWithSourceMode(
            target,
            source,
            target_rep,
            source_rep,
            .move,
            next,
        );
    }

    /// One representation boundary: convert `source` at `source_rep` into
    /// `target` at `target_rep`, then continue with `next`.
    const BoundaryRequest = struct {
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    };

    const BoundaryStep = union(enum) {
        /// The boundary whose statement the top frame receives next.
        request: BoundaryRequest,
        /// A frame was pushed and has not yet run.
        pushed,
        /// The statement the top frame receives next, or the whole result
        /// when no frame is left.
        done: LIR.CFStmtId,
    };

    /// A boundary waiting on its components' boundaries.
    const BoundaryFrame = struct {
        /// Whether the frame's last requested boundary is still due.
        awaiting: bool = false,
        state: union(enum) {
            /// Structure adapted inside the target's nominal formal scopes.
            scope: NominalBackingFormalScope,
            /// Convert into the actual an enclosing nominal scope binds the
            /// target's formal to, then box that.
            bound_dynamic: struct { request: BoundaryRequest, converted: LIR.LocalId, actual: Plan.TypeRepId },
            /// A presence slot's Present payload converted into the value.
            presence: struct {
                request: BoundaryRequest,
                slot: PresenceSlotVariants,
                payload: GeneratedParserTagPayload,
                stored_converted: bool = false,
            },
            record: RecordBoundaryState,
            list: ListBoundaryState,
            tag_union: TagUnionBoundaryState,
            payloads: TagPayloadBoundaryState,
        },
    };

    /// A record converted field by field, last field first.
    const RecordBoundaryState = struct {
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        /// The record the fields are read from: the source itself, or the
        /// payload unboxed from it.
        fields_source: LIR.LocalId,
        source_record_rep: Plan.TypeRepId,
        target_fields: []LIR.LocalId = &.{},
        source_fields: []LIR.LocalId = &.{},
        target_field_reps: []Plan.TypeRepId = &.{},
        source_field_reps: []Plan.TypeRepId = &.{},
        source_field_indices: []u32 = &.{},
        aggregate_desc: ConstructedAggregateDescriptor = .{},
        /// The field being converted; the fields after it are done.
        remaining: usize = 0,
        current: LIR.CFStmtId = undefined,
        /// The dynamic source box the fields' record is unboxed from.
        unbox: ?struct {
            source: LIR.LocalId,
            source_rep: Plan.TypeRepId,
            payload_desc: ?LIR.BoxyDescRef,
            payload_layout: layout.Idx,
        },
    };

    /// A list converted element by element in a loop whose step converts
    /// one element.
    const ListBoundaryState = struct {
        request: BoundaryRequest,
        target_elem_rep: Plan.TypeRepId,
        source_elem_rep: Plan.TypeRepId,
        target_elem_desc_local: ?LIR.LocalId,
        len: LIR.LocalId,
        capacity: LIR.LocalId,
        index: LIR.LocalId,
        zero: LIR.LocalId,
        initial_list: LIR.LocalId,
        acc: LIR.LocalId,
        elem_desc_initializers: std.ArrayList(DescriptorArgLocal),
        target_elem_desc_info: ResultDescriptorSource,
        target_desc_info: ResultDescriptorSource,
        join_id: LIR.JoinPointId,
        done: LIR.LocalId,
        /// The loop body's exit once every element is converted.
        finish: LIR.CFStmtId,
        /// The step's statements after the element's boundary.
        step_next: LIR.CFStmtId,
        source_elem: LIR.LocalId,
        target_elem: LIR.LocalId,
        source_elem_desc_info: ResultDescriptorSource,
        next_index: LIR.LocalId,
        one: LIR.LocalId,
    };

    /// A concrete tag union converted by a switch with one branch per source
    /// variant, first variant first.
    const TagUnionBoundaryState = struct {
        request: BoundaryRequest,
        kind: enum { concrete, dynamic },
        source_tag_rep: Plan.TypeRepId,
        source_variants: []const Plan.TagVariant,
        /// The concrete target's variants.
        target_variants: []const Plan.TagVariant = &.{},
        branches: []LIR.CFSwitchBranch,
        /// The source variant whose branch is being built.
        variant: usize = 0,
        /// The concrete target's branch for a variant it excludes.
        unreachable_source_variant: LIR.CFStmtId = undefined,
        /// The concrete target's nominal wrapper formal scopes.
        scope: ?NominalBackingFormalScope = null,
    };

    /// One tag variant's payloads converted last first, each read from the
    /// source tag before its conversion.
    const TagPayloadBoundaryState = struct {
        target_locals: []LIR.LocalId,
        source_locals: []ExtractedTagPayloadLocal,
        target_children: []const Plan.RepChild,
        source_children: []const Plan.RepChild,
        source: LIR.LocalId,
        source_tag_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        variant_index: u32,
        /// The payload being converted; the payloads after it are done.
        remaining: usize,
        current: LIR.CFStmtId,
        /// The constructed concrete tag's descriptor, whose field
        /// initializers run before the payload reads.
        tag_desc: ?ConstructedAggregateDescriptor = null,
    };

    fn assignRepresentationBoundaryWithSourceMode(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        dynamic_box_source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const allocator = self.parent.allocator;
        var frames: std.ArrayList(BoundaryFrame) = .empty;
        defer {
            var index = frames.items.len;
            while (index > 0) {
                index -= 1;
                self.releaseBoundaryFrame(&frames.items[index]);
            }
            frames.deinit(allocator);
        }
        var step = try self.beginBoundary(&frames, .{
            .target = target,
            .source = source,
            .target_rep = target_rep,
            .source_rep = source_rep,
            .mode = dynamic_box_source_mode,
            .next = next,
        });
        while (true) {
            switch (step) {
                .request => |request| step = try self.beginBoundary(&frames, request),
                .pushed => step = try self.stepBoundaryFrame(&frames, null),
                .done => |stmt| {
                    if (frames.items.len == 0) return stmt;
                    step = try self.stepBoundaryFrame(&frames, stmt);
                },
            }
        }
    }

    /// Free what an unfinished frame owns and leave the scope it holds, as
    /// the direct build's defers would.
    fn releaseBoundaryFrame(self: *ProcBodyBuilder, frame: *BoundaryFrame) void {
        const allocator = self.parent.allocator;
        switch (frame.state) {
            .scope => |scope| self.dropNominalBackingFormalScope(scope),
            .bound_dynamic, .presence => {},
            .record => |state| {
                allocator.free(state.target_fields);
                allocator.free(state.source_fields);
                allocator.free(state.target_field_reps);
                allocator.free(state.source_field_reps);
                allocator.free(state.source_field_indices);
                state.aggregate_desc.deinit(allocator);
            },
            .list => |*state| state.elem_desc_initializers.deinit(allocator),
            .tag_union => |state| {
                allocator.free(state.branches);
                if (state.scope) |scope| self.dropNominalBackingFormalScope(scope);
            },
            .payloads => |state| {
                allocator.free(state.target_locals);
                allocator.free(state.source_locals);
                if (state.tag_desc) |tag_desc| tag_desc.deinit(allocator);
            },
        }
    }

    fn pushBoundaryFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), frame: BoundaryFrame) Allocator.Error!void {
        var owned = frame;
        frames.append(self.parent.allocator, owned) catch |err| {
            self.releaseBoundaryFrame(&owned);
            return err;
        };
    }

    fn finishBoundaryFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), stmt: LIR.CFStmtId) BoundaryStep {
        var frame = frames.pop().?;
        self.releaseBoundaryFrame(&frame);
        return .{ .done = stmt };
    }

    fn beginBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!BoundaryStep {
        const target = request.target;
        const source = request.source;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const dynamic_box_source_mode = request.mode;
        const next = request.next;
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const identity_target_rep = self.descriptorStorageRep(target_rep);
        const identity_source_rep = self.descriptorStorageRep(source_rep);
        if (target_layout == source_layout and
            identity_target_rep == identity_source_rep and
            (target_rep == source_rep or
                (self.repIsFullyConcrete(target_rep) and self.repIsFullyConcrete(source_rep))))
        {
            return .{ .done = if (target == source) next else try self.assignLocalFromRep(target, source, source_rep, next) };
        }

        // Alternative-pattern remapping can bind a generic payload local to a
        // concrete representative binder. Preserve the local's explicit
        // dynamic-box storage classification before descriptor identity
        // selection makes the two descriptor identity reps look concrete.
        if (self.parent.layoutIsBoxStorage(source_layout) and
            !self.parent.layoutIsBoxStorage(target_layout) and
            self.parent.result.store.getLocal(source).boxy_desc != null)
        {
            return .{ .done = try self.assignDynamicBoxStorageToConcrete(
                target,
                source,
                identity_target_rep,
                identity_source_rep,
                dynamic_box_source_mode,
                next,
            ) };
        }

        // Two representations of the same source-level recursive type can be
        // structurally identical but receive distinct rep ids and distinct, yet
        // byte-identical, layout indices because the layout store interns each
        // recursive size cycle separately. Converting one into the other
        // field-by-field would recurse forever through the shared cycle. When
        // layout interchangeability proves the byte layouts identical, and
        // either layout-only RC or source-type identity proves the descriptor
        // interpretation is identical, relabelling the local is the boundary.
        const layouts_interchangeable = target_layout != source_layout and
            try self.boundaryLayoutsInterchangeable(target_layout, source_layout);
        const relabel_is_safe =
            (self.repIsFullyConcrete(identity_target_rep) and self.repIsFullyConcrete(identity_source_rep)) or
            self.repsHaveSameSourceType(identity_target_rep, identity_source_rep);
        if (layouts_interchangeable and relabel_is_safe) {
            const source_desc = self.parent.result.store.getLocal(source).boxy_desc;
            const target_desc = self.parent.result.store.getLocal(target).boxy_desc;
            return .{ .done = try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
                .target = target,
                .source = source,
                .adapter = try self.internAdapter(
                    .relabel,
                    source_layout,
                    target_layout,
                    dynamic_box_source_mode == .move,
                ),
                .source_desc = source_desc,
                .target_desc = target_desc,
                .source_mode = dynamic_box_source_mode,
                .next = next,
            } }, self.glueOrigin()) };
        }

        if (target_layout == source_layout) {
            if (self.functionChildrenForRep(identity_target_rep)) |target_function| {
                if (self.functionChildrenForRep(identity_source_rep)) |source_function| {
                    const scope = self.beginNominalBackingFormalScope();
                    errdefer self.dropNominalBackingFormalScope(scope);
                    try self.bindNominalWrapperFormalsInScope(source_rep);
                    try self.bindNominalWrapperFormalsInScope(target_rep);
                    const body = try self.assignErasedCallableBoundary(target, source, target_function, source_function, next);
                    return .{ .done = try self.leaveNominalBackingFormalScope(scope, body) };
                }
            }
        }

        // Adapting structure reaches into a nominal's shared backing template;
        // the target's formals describe that storage by the actuals this use
        // supplies, so the adapter runs inside the target's formal scopes.
        const scope = try self.enterNominalWrapperFormalScopes(target_rep);
        try self.pushBoundaryFrame(frames, .{ .awaiting = true, .state = .{ .scope = scope } });
        return try self.beginStructuralBoundary(frames, request, identity_target_rep, identity_source_rep, source_layout);
    }

    fn beginStructuralBoundary(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(BoundaryFrame),
        request: BoundaryRequest,
        identity_target_rep: Plan.TypeRepId,
        identity_source_rep: Plan.TypeRepId,
        source_layout: layout.Idx,
    ) Allocator.Error!BoundaryStep {
        const target = request.target;
        const source = request.source;
        const next = request.next;
        const identity_request: BoundaryRequest = .{
            .target = target,
            .source = source,
            .target_rep = identity_target_rep,
            .source_rep = identity_source_rep,
            .mode = request.mode,
            .next = next,
        };
        switch (self.workerRuntimeLayoutForRep(identity_target_rep)) {
            .dynamic_box => switch (self.workerRuntimeLayoutForRep(identity_source_rep)) {
                .dynamic_box => {
                    if (try self.beginDynamicTagUnionToDynamicBoundary(identity_request)) |step| return step;
                    return .{ .done = try self.assignDynamicBoxToDynamicBoundary(target, source, identity_target_rep, identity_source_rep, next) };
                },
                .concrete => {
                    if (try self.beginConcreteToBoundDynamicBoundary(frames, identity_request)) |step| return step;
                    if (try self.beginConcreteTagUnionToDynamicBoundary(frames, identity_request)) |step| return step;
                    const source_info = if (self.parent.result.store.getLocal(source).boxy_desc) |desc|
                        ResultDescriptorSource{ .desc = desc }
                    else
                        try self.adapterDescriptorFromMaterialization(try self.descriptorMaterializationForSourceRep(identity_source_rep));
                    const source_desc = source_info.desc orelse
                        boxyLowerInvariant("boxy concrete-to-dynamic source descriptor was not available");
                    const rep_payload_desc = if (self.descriptorBindingIsBoundForRep(identity_target_rep))
                        try self.descriptorRefForRepIfNeeded(identity_target_rep)
                    else
                        null;
                    const desc_for_payload = if (rep_payload_desc != null and !self.repIsBareDynamic(identity_target_rep) and !self.repIsOpenRecord(identity_target_rep))
                        rep_payload_desc.?
                    else
                        source_desc;
                    const existing_target_desc = self.parent.result.store.getLocal(target).boxy_desc;
                    const payload_desc = existing_target_desc orelse desc_for_payload;
                    if (existing_target_desc == null) {
                        self.parent.result.store.setLocalBoxyDesc(target, payload_desc);
                    }
                    const writable_target_desc = if (existing_target_desc) |desc| blk_desc: {
                        const local = desc.localOrNull() orelse break :blk_desc null;
                        if (self.localIsReadOnlyDescriptorInput(local)) break :blk_desc null;
                        break :blk_desc desc;
                    } else null;
                    const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                        .target = target,
                        .payload = source,
                        .payload_layout = source_layout,
                        .source_desc = if (std.meta.eql(source_desc, desc_for_payload)) null else source_desc,
                        .payload_desc = payload_desc,
                        .payload_mode = .move,
                        .next = next,
                    } }, self.glueOrigin());
                    var continuation = box;
                    if (writable_target_desc) |desc| {
                        if (!std.meta.eql(desc, desc_for_payload)) {
                            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                                .target = desc.localOrNull() orelse
                                    boxyLowerInvariant("boxy target descriptor local disappeared"),
                                .desc = desc_for_payload,
                                .next = continuation,
                            } }, self.glueOrigin());
                        }
                    }
                    if (source_info.materialize) |materialize| {
                        continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                            .target = materialize.local,
                            .desc = materialize.materialize orelse
                                boxyLowerInvariant("boxy concrete-to-dynamic source descriptor materialization had no descriptor"),
                            .nested_index = materialize.nested_index,
                            .tag_ext = materialize.tag_ext,
                            .tag_residual_for = materialize.tag_residual_for,
                            .captures = materialize.captures,
                            .next = continuation,
                        } }, self.glueOrigin());
                    }
                    return .{ .done = continuation };
                },
            },
            .concrete => switch (self.workerRuntimeLayoutForRep(identity_source_rep)) {
                .dynamic_box => {
                    if (try self.beginDynamicRecordToConcreteBoundary(frames, identity_request)) |step| return step;
                    const source_desc = try self.descriptorRefForSourceLocalRep(source, identity_source_rep);
                    const target_desc_info = try self.storageDescriptorForRepIfNeeded(identity_target_rep);
                    // A `.dynamic`-rep target reports no static storage descriptor,
                    // but when its unboxed storage layout carries an erased
                    // `erased_box` the value must still be reference-counted through
                    // a descriptor (a layout-driven concrete RC walk cannot align
                    // the box's allocation). The unboxed storage has the same shape
                    // as the box payload, so reuse the source box's descriptor.
                    var selected_target_desc = target_desc_info;
                    if (selected_target_desc.desc == null and self.repContainsDynamicStorage(identity_target_rep)) {
                        selected_target_desc.desc = source_desc;
                    }
                    const resolved_target_desc = self.resultDescriptorForCallTarget(target, selected_target_desc);
                    if (self.parent.result.store.getLocal(target).boxy_desc == null) {
                        if (resolved_target_desc.desc) |desc| {
                            self.parent.result.store.setLocalBoxyDesc(target, desc);
                        }
                    }
                    const adapt = try self.assignDynamicBoxMaterialization(
                        target,
                        source,
                        source_desc,
                        resolved_target_desc.desc,
                        request.mode,
                        next,
                    );
                    return .{ .done = try self.prependOptionalDescriptorMaterialization(resolved_target_desc.materialize, adapt) };
                },
                .concrete => {
                    if (try self.beginPresenceSlotToValueBoundary(frames, identity_request)) |step| return step;
                    if (try self.beginListRepresentationBoundary(frames, identity_request)) |step| return step;
                    if (try self.assignSingletonZstTagToConcreteBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted| {
                        return .{ .done = adapted };
                    }
                    if (try self.beginConcreteTagUnionToConcreteBoundary(frames, identity_request)) |step| return step;
                    if (try self.assignConcreteTagUnionToScalarBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted| {
                        return .{ .done = adapted };
                    }
                    if (try self.beginConcreteRecordToConcreteBoundary(frames, identity_request)) |step| return step;
                    return .{ .done = try self.assignDescriptorAwareNominalBoundary(
                        target,
                        source,
                        request.target_rep,
                        request.source_rep,
                        request.mode,
                        next,
                    ) };
                },
            },
        }
    }

    fn stepBoundaryFrame(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), delivered: ?LIR.CFStmtId) Allocator.Error!BoundaryStep {
        // A tag union frame pushes at most one variant frame per step, so the
        // top frame stays in place.
        try frames.ensureUnusedCapacity(self.parent.allocator, 1);
        const frame = &frames.items[frames.items.len - 1];
        const child: ?LIR.CFStmtId = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("boxy boundary frame resumed without its component boundary")
        else if (delivered != null)
            boxyLowerInvariant("boxy boundary frame received a boundary it did not request")
        else
            null;
        frame.awaiting = false;
        switch (frame.state) {
            .scope => |scope| {
                const body = child orelse boxyLowerInvariant("boxy boundary scope frame ran before its structure");
                const stmt = try self.leaveNominalBackingFormalScope(scope, body);
                frames.items.len -= 1;
                return .{ .done = stmt };
            },
            .bound_dynamic => |bound| {
                const request = bound.request;
                const boxed = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{
                        .target = request.target,
                        .source = bound.converted,
                        .target_rep = request.target_rep,
                        .source_rep = bound.actual,
                        .mode = .borrow,
                        .next = request.next,
                    } };
                };
                frames.items.len -= 1;
                return .{ .request = .{
                    .target = bound.converted,
                    .source = request.source,
                    .target_rep = bound.actual,
                    .source_rep = request.source_rep,
                    .mode = .borrow,
                    .next = boxed,
                } };
            },
            .presence => |*presence| {
                const request = presence.request;
                const payload = presence.payload;
                const converted = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{
                        .target = request.target,
                        .source = payload.local,
                        .target_rep = request.target_rep,
                        .source_rep = payload.child.rep,
                        .mode = .borrow,
                        .next = request.next,
                    } };
                };
                if (!presence.stored_converted and payload.local != payload.stored) {
                    presence.stored_converted = true;
                    frame.awaiting = true;
                    return .{ .request = .{
                        .target = payload.local,
                        .source = payload.stored,
                        .target_rep = payload.child.rep,
                        .source_rep = payload.stored_rep,
                        .mode = .borrow,
                        .next = converted,
                    } };
                }
                const present_body = try self.readGeneratedParserStoredTagPayload(request.source, presence.slot.present, payload, converted);
                const missing_body = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin());
                const variants = [_]ProcedureBuilder.GeneratedParserTagVariant{presence.slot.present};
                const bodies = [_]LIR.CFStmtId{present_body};
                const stmt = try self.generatedParserTagDispatch(request.source, request.source_rep, &variants, &bodies, missing_body);
                return self.finishBoundaryFrame(frames, stmt);
            },
            .record => |*state| {
                if (child) |converted| {
                    const index = state.remaining;
                    const read_field = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                        .target = state.source_fields[index],
                        .op = .{ .field = .{
                            .source = state.fields_source,
                            .field_idx = state.source_field_indices[index],
                        } },
                        .next = converted,
                    } }, self.glueOrigin());
                    state.current = try self.prependRecordFieldDescriptorBind(
                        state.source_fields[index],
                        state.fields_source,
                        state.source_record_rep,
                        state.source_field_indices[index],
                        read_field,
                    );
                }
                if (state.remaining > 0) {
                    state.remaining -= 1;
                    const index = state.remaining;
                    try self.propagateLocalDescriptorEnvironmentToField(state.source_fields[index], state.source_field_reps[index], state.fields_source);
                    frame.awaiting = true;
                    return .{ .request = .{
                        .target = state.target_fields[index],
                        .source = state.source_fields[index],
                        .target_rep = state.target_field_reps[index],
                        .source_rep = state.source_field_reps[index],
                        .mode = .borrow,
                        .next = state.current,
                    } };
                }
                return self.finishBoundaryFrame(frames, try self.finishRecordBoundary(state));
            },
            .list => |*state| {
                const converted = child orelse {
                    frame.awaiting = true;
                    return .{ .request = .{
                        .target = state.target_elem,
                        .source = state.source_elem,
                        .target_rep = state.target_elem_rep,
                        .source_rep = state.source_elem_rep,
                        .mode = .borrow,
                        .next = state.step_next,
                    } };
                };
                return self.finishBoundaryFrame(frames, try self.finishListBoundary(state, converted));
            },
            .tag_union => |*state| {
                if (child) |body| {
                    state.branches[state.variant].body = body;
                    state.variant += 1;
                }
                while (state.variant < state.source_variants.len) {
                    const step = switch (state.kind) {
                        .concrete => try self.beginConcreteTagVariantToConcrete(frames, state),
                        .dynamic => try self.beginConcreteTagVariantToDynamic(frames, state),
                    };
                    switch (step) {
                        .done => |body| {
                            state.branches[state.variant].body = body;
                            state.variant += 1;
                        },
                        .pushed => {
                            frame.awaiting = true;
                            return .pushed;
                        },
                        .request => boxyLowerInvariant("boxy tag variant boundary requested a boundary before pushing its frame"),
                    }
                }
                return self.finishBoundaryFrame(frames, try self.finishTagUnionBoundary(state));
            },
            .payloads => |*state| {
                if (child) |converted| {
                    const index = state.remaining;
                    state.current = try self.assignConcreteTagPayloadRead(
                        state.source_locals[index].local,
                        state.source_children[index].rep,
                        state.source_locals[index].desc_local,
                        state.source,
                        state.source_tag_rep,
                        state.tag_name,
                        state.variant_index,
                        @intCast(index),
                        state.source_children.len,
                        converted,
                    );
                }
                if (state.remaining > 0) {
                    state.remaining -= 1;
                    const index = state.remaining;
                    frame.awaiting = true;
                    return .{ .request = .{
                        .target = state.target_locals[index],
                        .source = state.source_locals[index].local,
                        .target_rep = state.target_children[index].rep,
                        .source_rep = state.source_children[index].rep,
                        .mode = .borrow,
                        .next = state.current,
                    } };
                }
                const body = if (state.tag_desc) |tag_desc|
                    try self.prependDescriptorArgMaterializations(tag_desc.field_initializers, state.current)
                else
                    state.current;
                return self.finishBoundaryFrame(frames, body);
            },
        }
    }

    /// A still-undetermined record field is stored as its presence slot; where
    /// checking made the field required, the value is the slot's Present
    /// payload, converted to the target's representation like any other
    /// value. The field is required at this type, so the slot is never
    /// Missing.
    fn beginPresenceSlotToValueBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const slot = self.presenceSlotVariants(request.source_rep) orelse return null;
        if (self.presenceSlotVariants(request.target_rep) != null) return null;
        const payload = try self.generatedParserSingleTagPayloadLocal(slot.present);
        try self.pushBoundaryFrame(frames, .{ .state = .{ .presence = .{ .request = request, .slot = slot, .payload = payload } } });
        return .pushed;
    }

    /// A dynamic target whose formal an enclosing nominal scope binds to a
    /// known actual stores that actual's own representation. When the source
    /// stores the actual differently, convert it into the actual's
    /// representation first, then box that.
    fn beginConcreteToBoundDynamicBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const actual = self.nominalFormalActualBelow(self.nominal_formal_bindings.items.len, request.target_rep) orelse return null;
        if (self.repIsBareDynamic(actual)) return null;
        if (self.descriptorStorageRep(actual) == request.source_rep or
            self.representationBoundaryIsDirect(actual, request.source_rep)) return null;
        const converted = try self.addFrameBoundaryTargetLocalForRep(actual);
        try self.pushBoundaryFrame(frames, .{ .state = .{ .bound_dynamic = .{ .request = request, .converted = converted, .actual = actual } } });
        return .pushed;
    }

    fn beginDynamicRecordToConcreteBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const source = request.source;
        const source_rep = request.source_rep;
        const source_record_rep = self.recordRepForBoundary(source_rep) orelse return null;
        const target_record_rep = self.recordRepForBoundary(request.target_rep) orelse return null;
        if (source_record_rep == target_record_rep) return null;

        const source_record = self.parent.plan.representations.items[@backingInt(source_record_rep)];
        const target_record = self.parent.plan.representations.items[@backingInt(target_record_rep)];
        if (source_record.kind != .dynamic) return null;
        // An open record's fields beyond its row are known only to its
        // runtime descriptor, which the unboxing boundary reads them through.
        if (self.repIsOpenRecord(source_record_rep)) return null;
        switch (target_record.kind) {
            .record => {},
            .dynamic => if (!self.repHasRecordFieldChildrenForBoundary(target_record)) return null,
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
        }

        const source_payload_layout = self.parent.layout_plan.rep_layouts[@backingInt(source_record_rep)].descriptor_payload_layout orelse
            boxyLowerInvariant("dynamic record boundary source had no descriptor payload layout");
        const target_field_count = self.recordFieldCount(self.parent.plan.childSlice(target_record.children));
        if (target_field_count == 0) return null;

        const source_payload = try self.addFrameLocal(source_payload_layout);
        // The unboxed source payload lives past the field conversions and is then
        // dropped. When it carries an `erased_box` it must be
        // reference-counted through a descriptor, so tag it with the source box's
        // descriptor (which describes exactly this payload shape).
        const source_payload_desc: ?LIR.BoxyDescRef = if (self.repContainsDynamicStorage(source_record_rep))
            try self.descriptorRefForSourceLocalRep(source, source_rep)
        else
            null;
        if (source_payload_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(source_payload, desc);
        }
        return try self.beginRecordFieldsBoundary(frames, request, target_record, target_field_count, .{
            .target = request.target,
            .target_rep = request.target_rep,
            .fields_source = source_payload,
            .source_record_rep = source_record_rep,
            .unbox = .{
                .source = source,
                .source_rep = source_rep,
                .payload_desc = source_payload_desc,
                .payload_layout = source_payload_layout,
            },
        }, "dynamic");
    }

    fn beginConcreteRecordToConcreteBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const target = request.target;
        const source = request.source;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const next = request.next;
        if (target_rep == source_rep) return null;

        const source_record_rep = self.recordRepForBoundary(source_rep) orelse return null;
        const target_record_rep = self.recordRepForBoundary(target_rep) orelse return null;
        if (source_record_rep == target_record_rep) {
            // The same backing record rep can be laid out at two different byte
            // layouts: a transparent nominal that opts into declared field order
            // reserves unnamed padding its structural backing omits (z@0, pad@4,
            // a@8 vs the structural a@0, z@4). A flat nominal reinterpret would
            // land each field at the wrong host-visible offset, so when the byte
            // layouts differ the fields must be repositioned by their identity
            // index; when the layouts already match a plain reinterpret suffices.
            const target_layout = self.parent.result.store.getLocal(target).layout_idx;
            const source_layout = self.parent.result.store.getLocal(source).layout_idx;
            if (target_layout == source_layout) return null;
        }

        // The runtime descriptor of an open record owns its complete field set.
        // Its row's named fields cannot describe that source payload.
        if (self.repIsOpenRecord(source_record_rep)) return null;
        const source_record = self.parent.plan.representations.items[@backingInt(source_record_rep)];
        const target_record = self.parent.plan.representations.items[@backingInt(target_record_rep)];
        switch (source_record.kind) {
            .record => {},
            .dynamic => if (!self.repHasRecordFieldChildrenForBoundary(source_record)) return null,
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
        }
        switch (target_record.kind) {
            .record => {},
            .dynamic => if (!self.repHasRecordFieldChildrenForBoundary(target_record)) return null,
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
        }
        const boxed_source_layout = self.workerRuntimeLayoutForRep(source_record_rep).layoutIdx();
        const boxed_source_layout_value = self.parent.result.layouts.getLayout(boxed_source_layout);
        const source_backing_is_box = switch (boxed_source_layout_value.tag) {
            .box, .box_of_zst, .erased_box => true,
            .scalar, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => false,
        };
        // A plan-dynamic record whose backing is concrete at this site (fully
        // known instantiation) converts field-by-field like a concrete record;
        // only genuinely boxed backings take the box round-trip.
        if ((source_record.kind == .dynamic or target_record.kind == .dynamic) and source_backing_is_box) {
            const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
            try self.bindConstructedTargetDescriptor(target, target_rep);
            const target_desc = try self.constructedTargetDescForRep(target_rep);
            const target_layout = self.parent.result.store.getLocal(target).layout_idx;
            const source_layout = self.parent.result.store.getLocal(source).layout_idx;
            const boxed_source = try self.addFrameLocal(boxed_source_layout);
            self.parent.result.store.setLocalBoxyDesc(boxed_source, source_desc);
            var continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
                .target = target,
                .source = boxed_source,
                .source_desc = source_desc,
                .target_desc = target_desc,
                .target_layout = target_layout,
                .source_mode = .move,
                .next = next,
            } }, self.glueOrigin());
            continuation = try self.prependConstructedDescriptorRebindForRep(target_rep, continuation);
            return .{ .done = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = boxed_source,
                .payload = source,
                .payload_layout = source_layout,
                .payload_desc = source_desc,
                .payload_mode = .borrow,
                .next = continuation,
            } }, self.glueOrigin()) };
        }

        const target_field_count = self.recordFieldCount(self.parent.plan.childSlice(target_record.children));
        if (target_field_count == 0) return null;
        return try self.beginRecordFieldsBoundary(frames, request, target_record, target_field_count, .{
            .target = target,
            .target_rep = target_rep,
            .fields_source = source,
            .source_record_rep = source_record_rep,
            .unbox = null,
        }, "concrete");
    }

    /// Reserve each target field's conversion and build the record's
    /// construction, then push the frame that converts the fields.
    fn beginRecordFieldsBoundary(
        self: *ProcBodyBuilder,
        frames: *std.ArrayList(BoundaryFrame),
        request: BoundaryRequest,
        target_record: Plan.TypeRepresentation,
        target_field_count: usize,
        initial: RecordBoundaryState,
        comptime kind: []const u8,
    ) Allocator.Error!BoundaryStep {
        const allocator = self.parent.allocator;
        var frame: BoundaryFrame = .{ .state = .{ .record = initial } };
        errdefer self.releaseBoundaryFrame(&frame);
        const state = &frame.state.record;
        state.target_fields = try allocator.alloc(LIR.LocalId, target_field_count);
        state.source_fields = try allocator.alloc(LIR.LocalId, target_field_count);
        state.target_field_reps = try allocator.alloc(Plan.TypeRepId, target_field_count);
        state.source_field_reps = try allocator.alloc(Plan.TypeRepId, target_field_count);
        state.source_field_indices = try allocator.alloc(u32, target_field_count);

        var field_index: usize = 0;
        for (self.parent.plan.childSlice(target_record.children)) |target_child| {
            switch (target_child.role) {
                .record_field => |target_label| {
                    const source_field = self.findRecordFieldByLabel(state.source_record_rep, procedureModuleById(self.parent.modules, target_child.source_type.module), target_label) orelse
                        boxyLowerInvariant(kind ++ " record boundary source was missing target field");
                    state.target_fields[field_index] = if (self.representationBoundaryIsDirect(target_child.rep, source_field.rep))
                        try self.addFrameLocalForRep(target_child.rep)
                    else
                        try self.addFrameBoundaryTargetLocalForRep(target_child.rep);
                    state.source_fields[field_index] = try self.addFrameLocalForRep(source_field.rep);
                    state.target_field_reps[field_index] = target_child.rep;
                    state.source_field_reps[field_index] = source_field.rep;
                    state.source_field_indices[field_index] = source_field.index;
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(target_child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant(kind ++ " record boundary target had non-record child role"),
            }
        }
        if (field_index != target_field_count) {
            boxyLowerInvariant(kind ++ " record boundary field count disagreed with target record children");
        }

        const descriptor_fields = try allocator.alloc(AggregateDescriptorField, target_field_count);
        defer allocator.free(descriptor_fields);
        for (state.target_fields, state.target_field_reps, state.source_field_reps, descriptor_fields) |field_local, target_field_rep, source_field_rep, *field| {
            field.* = .{
                .local = field_local,
                .target_rep = target_field_rep,
                // This local is the boundary output, not the original field.
                .source_rep = if (self.representationBoundaryIsDirect(target_field_rep, source_field_rep))
                    source_field_rep
                else
                    target_field_rep,
            };
        }
        state.aggregate_desc = try self.constructedAggregateDescriptorForFields(state.target, state.target_rep, descriptor_fields);

        const assign_struct = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = state.target,
            .fields = try self.parent.result.store.addLocalSpan(state.target_fields),
            .contents_desc = state.aggregate_desc.contents_desc,
            .next = request.next,
        } }, self.glueOrigin());
        state.current = try self.prependOptionalDescriptorMaterialization(state.aggregate_desc.materialize, assign_struct);
        state.remaining = target_field_count;
        try frames.append(allocator, frame);
        return .pushed;
    }

    fn finishRecordBoundary(self: *ProcBodyBuilder, state: *const RecordBoundaryState) Allocator.Error!LIR.CFStmtId {
        try self.recordAggregateLocalDescriptorEnvironment(state.target, state.target_rep, state.target_fields);
        const fields_ready = if (state.unbox) |unbox|
            try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
                .target = state.fields_source,
                .source = unbox.source,
                .source_desc = try self.descriptorRefForSourceLocalRep(unbox.source, unbox.source_rep),
                .target_desc = unbox.payload_desc,
                .target_layout = unbox.payload_layout,
                .source_mode = .borrow,
                .next = state.current,
            } }, self.glueOrigin())
        else
            state.current;
        return try self.prependDescriptorArgMaterializations(state.aggregate_desc.field_initializers, fields_ready);
    }

    fn beginListRepresentationBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const allocator = self.parent.allocator;
        const target = request.target;
        const source = request.source;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const target_list_rep = self.listRepForBoundary(target_rep) orelse return null;
        const source_list_rep = self.listRepForBoundary(source_rep) orelse return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (!layoutIsList(target_layout_value) or !layoutIsList(source_layout_value)) return null;

        const target_elem = self.repQuery().requiredSingleChild(target_list_rep, .list_elem);
        const source_elem = self.repQuery().requiredSingleChild(source_list_rep, .list_elem);
        // This list owns its element descriptor identity. A representation's
        // existing descriptor local can still describe live source values.
        const target_elem_desc_local = if (self.parent.plan.representations.items[@backingInt(target_elem.rep)].descriptor != null or
            self.parent.layoutNeedsNestedBoxyDesc(self.parent.listElementLayout(target_layout)))
            try self.addFrameLocal(.opaque_ptr)
        else
            null;

        const len = try self.addFrameLocal(.u64);
        const capacity = try self.addFrameLocal(.u64);
        const index = try self.addFrameLocal(.u64);
        const zero = try self.addFrameLocal(.u64);
        const initial_list = try self.addFrameLocal(target_layout);
        const acc = try self.addFrameLocal(target_layout);
        const source_elem_desc_info = try self.descriptorForSourceListElement(source, source_list_rep, source_elem.rep);
        var frame: BoundaryFrame = .{ .state = .{ .list = .{
            .request = request,
            .target_elem_rep = target_elem.rep,
            .source_elem_rep = source_elem.rep,
            .target_elem_desc_local = target_elem_desc_local,
            .len = len,
            .capacity = capacity,
            .index = index,
            .zero = zero,
            .initial_list = initial_list,
            .acc = acc,
            .elem_desc_initializers = .empty,
            .target_elem_desc_info = undefined,
            .target_desc_info = undefined,
            .join_id = undefined,
            .done = undefined,
            .finish = undefined,
            .step_next = undefined,
            .source_elem = undefined,
            .target_elem = undefined,
            .source_elem_desc_info = undefined,
            .next_index = undefined,
            .one = undefined,
        } } };
        var pushed = false;
        defer if (!pushed) self.releaseBoundaryFrame(&frame);
        const state = &frame.state.list;
        try self.appendResultDescriptorInitializers(&state.elem_desc_initializers, source_elem_desc_info);
        // Storage conversion needs a target-shaped item descriptor, which
        // differs from the source's when the item storage layouts differ.
        // Materialize once outside the loop, including for an empty list.
        state.target_elem_desc_info = if (target_elem_desc_local != null and self.parent.listElementLayout(source_layout) != self.parent.listElementLayout(target_layout))
            try self.adapterDescriptorForCallBoundary(target_elem.rep, source_elem.rep, source_elem_desc_info, &state.elem_desc_initializers)
        else
            source_elem_desc_info;
        try self.appendResultDescriptorInitializers(&state.elem_desc_initializers, state.target_elem_desc_info);
        state.target_desc_info = if (target_elem_desc_local) |elem_desc_local|
            try self.constructedListDescriptorForElementLocal(target, target_rep, elem_desc_local)
        else
            try self.stableDescriptorForConstructedValue(target, target_rep);
        if (state.target_desc_info.desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(target, desc);
            self.parent.result.store.setLocalBoxyDesc(initial_list, desc);
            self.parent.result.store.setLocalBoxyDesc(acc, desc);
        }
        state.join_id = self.freshJoinPointId();

        // The loop body: finish when the index reaches the length, otherwise
        // step.
        state.done = try self.addFrameLocal(.bool);
        state.finish = try self.assignLocal(target, acc, request.next);

        // The loop step: convert one element and append it.
        const source_list_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_list_layout = self.parent.result.store.getLocal(acc).layout_idx;
        const source_storage_layout = self.parent.listElementLayout(source_list_layout);
        const target_storage_layout = self.parent.listElementLayout(target_list_layout);
        const source_worker_layout = self.workerRuntimeLayoutForRep(source_elem.rep).layoutIdx();
        const requires_storage_adapter = source_storage_layout != source_worker_layout or
            source_storage_layout != target_storage_layout;
        state.source_elem = try self.addFrameLocal(if (requires_storage_adapter)
            source_storage_layout
        else
            source_worker_layout);
        state.target_elem = if (requires_storage_adapter)
            try self.addFrameLocal(target_storage_layout)
        else if (self.representationBoundaryIsDirect(target_elem.rep, source_elem.rep) or
            self.repsUseSameDynamicBoxStorage(target_elem.rep, source_elem.rep))
            state.source_elem
        else if (target_elem_desc_local != null)
            // The enclosing list owns this element descriptor. Reserve the
            // value with that descriptor instead of creating a second identity.
            try self.addFrameLocal(target_storage_layout)
        else
            try self.addFrameBoundaryTargetLocalForRep(target_elem.rep);
        if (state.target_elem != state.source_elem) {
            if (target_elem_desc_local) |desc_local| {
                self.parent.result.store.setLocalBoxyDesc(state.target_elem, .{ .local = desc_local });
            }
        }
        state.source_elem_desc_info = try self.descriptorForSourceListElement(source, source_rep, source_elem.rep);
        const source_elem_desc = state.source_elem_desc_info.desc orelse
            boxyLowerInvariant("boxy list boundary source element descriptor had no descriptor");
        self.parent.result.store.setLocalBoxyDesc(state.source_elem, source_elem_desc);
        const next_acc = try self.addFrameLocal(self.parent.result.store.getLocal(acc).layout_idx);
        if (self.parent.result.store.getLocal(acc).boxy_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(next_acc, desc);
        }
        state.one = try self.addFrameLocal(.u64);
        state.next_index = try self.addFrameLocal(.u64);

        var continuation = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = state.join_id } }, self.glueOrigin());
        continuation = try self.setLocalInitializeJoinParam(acc, next_acc, continuation);
        continuation = try self.setLocalInitializeJoinParam(index, state.next_index, continuation);
        continuation = try self.assignListAppendMovingElement(next_acc, acc, state.target_elem, continuation);
        if (requires_storage_adapter) {
            const source_desc = state.source_elem_desc_info.desc orelse
                boxyLowerInvariant("contextual list element storage had no exact source descriptor");
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
                .target = state.target_elem,
                .source = state.source_elem,
                .adapter = try self.internMoveAdapter(
                    if (source_storage_layout == target_storage_layout) .relabel else .materialize,
                    source_storage_layout,
                    target_storage_layout,
                ),
                .source_desc = source_desc,
                .target_desc = if (target_elem_desc_local) |local| .{ .local = local } else try self.parent.staticDescRefForRep(target_elem.rep),
                .source_mode = .move,
                .next = continuation,
            } }, self.glueOrigin());
        } else if (state.target_elem != state.source_elem) {
            state.step_next = continuation;
            try frames.append(allocator, frame);
            pushed = true;
            return .pushed;
        }
        return .{ .done = try self.finishListBoundary(state, continuation) };
    }

    /// Finish the list loop from its step's statements from the element's
    /// read onward.
    fn finishListBoundary(self: *ProcBodyBuilder, state: *const ListBoundaryState, step_continuation: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        const source = state.request.source;
        var continuation = try self.assignBinaryLowLevel(state.source_elem, .list_get_unsafe, source, state.index, step_continuation);
        continuation = try self.prependOptionalDescriptorMaterialization(state.source_elem_desc_info.materialize, continuation);
        continuation = try self.assignBinaryLowLevel(state.next_index, .num_int_add_crash_on_overflow, state.index, state.one, continuation);
        const step = try self.assignU64Literal(state.one, 1, continuation);
        const switch_stmt = try self.boolSwitchNoContinuation(state.done, state.finish, step);
        const body = try self.assignBinaryLowLevel(state.done, .num_is_eq, state.index, state.len, switch_stmt);

        var initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = state.join_id } }, self.glueOrigin());
        initial_jump = try self.setLocalInitializeJoinParam(state.acc, state.initial_list, initial_jump);
        initial_jump = try self.setLocalInitializeJoinParam(state.index, state.zero, initial_jump);
        initial_jump = try self.assignU64Literal(state.zero, 0, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(state.initial_list, .list_with_capacity, state.capacity, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(state.capacity, .list_capacity, source, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(state.len, .list_len, source, initial_jump);
        initial_jump = try self.prependOptionalDescriptorMaterialization(state.target_desc_info.materialize, initial_jump);
        if (state.target_elem_desc_local) |elem_desc_local| {
            const target_elem_desc = state.target_elem_desc_info.desc orelse
                boxyLowerInvariant("boxy list boundary initial element descriptor had no target descriptor");
            initial_jump = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = elem_desc_local,
                .desc = target_elem_desc,
                .next = initial_jump,
            } }, self.glueOrigin());
            initial_jump = try self.prependDescriptorArgMaterializations(state.elem_desc_initializers.items, initial_jump);
        }
        initial_jump = try self.prependConstructedDescriptorRebindForRep(state.request.source_rep, initial_jump);

        return try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = state.join_id,
            .params = try self.joinParamSpan(&[_]LIR.LocalId{ state.index, state.acc }),
            .body = body,
            .remainder = initial_jump,
        } }, self.glueOrigin());
    }

    fn beginConcreteTagUnionToConcreteBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const target = request.target;
        const source = request.source;
        const target_tag_rep = self.tagVariantRepForBoundary(request.target_rep) orelse return null;
        const source_tag_rep = self.tagVariantRepForBoundary(request.source_rep) orelse return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (target_layout_value.tag != .tag_union or source_layout_value.tag != .tag_union) return null;

        // Equal-layout tag unions can preserve the source value and its exact
        // descriptor when the planned representations prove that every source
        // payload uses storage accepted by the target. This is an explicit
        // descriptor transfer, not a representation-identity shortcut: the
        // target's reserved descriptor local is initialized by assignLocal.
        if (target_layout == source_layout and
            self.parent.result.store.getLocal(source).boxy_desc != null and
            try self.repsCanReuseSourceDescriptor(source_tag_rep, target_tag_rep))
        {
            return .{ .done = try self.assignLocal(target, source, request.next) };
        }

        const target_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(target_tag_rep)].tag_variants);
        const source_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(source_tag_rep)].tag_variants);
        if (target_variants.len == 0 or source_variants.len == 0) return null;

        // Checked row coercions can widen or narrow a concrete tag union. Prove
        // that one row is a subset of the other before emitting either form;
        // partially overlapping rows would indicate invalid producer data.
        var source_has_excluded_variant = false;
        for (source_variants) |source_variant| {
            const source_name = self.tagVariantNameText(source_variant);
            for (target_variants) |target_variant| {
                if (std.mem.eql(u8, source_name, self.tagVariantNameText(target_variant))) break;
            } else {
                source_has_excluded_variant = true;
            }
        }
        var target_has_added_variant = false;
        for (target_variants) |target_variant| {
            const target_name = self.tagVariantNameText(target_variant);
            for (source_variants) |source_variant| {
                if (std.mem.eql(u8, target_name, self.tagVariantNameText(source_variant))) break;
            } else {
                target_has_added_variant = true;
            }
        }
        if (source_has_excluded_variant and target_has_added_variant) {
            boxyLowerInvariant("boxy concrete tag boundary rows overlapped without a subset relationship");
        }
        // The target's payloads are written against the formals of the nominal
        // wrappers `tagVariantRepForBoundary` passed through.
        const scope = try self.enterNominalWrapperFormalScopes(request.target_rep);
        var frame: BoundaryFrame = .{ .state = .{ .tag_union = .{
            .request = request,
            .kind = .concrete,
            .source_tag_rep = source_tag_rep,
            .source_variants = source_variants,
            .target_variants = target_variants,
            .branches = &.{},
            .scope = scope,
        } } };
        errdefer self.releaseBoundaryFrame(&frame);
        frame.state.tag_union.unreachable_source_variant = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin());
        frame.state.tag_union.branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, source_variants.len);
        try frames.append(self.parent.allocator, frame);
        return .pushed;
    }

    /// Begin the current source variant's branch of a concrete target.
    fn beginConcreteTagVariantToConcrete(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), state: *TagUnionBoundaryState) Allocator.Error!BoundaryStep {
        const source_index = state.variant;
        const source_variant = state.source_variants[source_index];
        if (source_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("boxy concrete-to-concrete tag adapter variant index exceeded LIR variant range");
        }
        state.branches[source_index].value = @intCast(source_index);
        const target_match: ?struct { variant: Plan.TagVariant, index: u32 } = blk: {
            const source_name = self.tagVariantNameText(source_variant);
            for (state.target_variants, 0..) |target_candidate, candidate_index| {
                if (!std.mem.eql(u8, source_name, self.tagVariantNameText(target_candidate))) continue;
                if (candidate_index > std.math.maxInt(u32)) {
                    boxyLowerInvariant("boxy concrete-to-concrete tag adapter target variant index exceeded LIR variant range");
                }
                break :blk .{ .variant = target_candidate, .index = @intCast(candidate_index) };
            }
            break :blk null;
        };
        const target_variant_match = target_match orelse return .{ .done = state.unreachable_source_variant };
        const target_variant = target_variant_match.variant;
        const target_variant_index = target_variant_match.index;
        const target = state.request.target;
        const target_rep = state.request.target_rep;
        const source = state.request.source;
        const source_tag_rep = state.source_tag_rep;
        const next = state.request.next;
        const allocator = self.parent.allocator;

        const target_payloads = self.parent.plan.childSlice(target_variant.payloads);
        const source_payloads = self.parent.plan.childSlice(source_variant.payloads);
        if (target_payloads.len != source_payloads.len) {
            boxyLowerInvariant("boxy concrete tag adapter saw payload count mismatch between source and target variants");
        }

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (target_payloads.len == 0 or
            self.parent.result.layouts.isZeroSized(self.parent.result.layouts.getLayout(self.tagUnionPayloadLayout(target_layout, target_variant_index))))
        {
            const target_desc_info = try self.stableDescriptorForConstructedValue(target, target_rep);
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = target_desc_info.desc,
                .variant_index = target_variant_index,
                .discriminant = target_variant_index,
                .payload = null,
                .next = next,
            } }, self.glueOrigin());
            return .{ .done = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, assign_tag) };
        }

        const target_payload = try self.addFrameLocal(self.tagUnionPayloadLayout(target_layout, target_variant_index));
        const source_has_payload_desc = self.parent.plan.representations.items[@backingInt(source_tag_rep)].descriptor != null or
            self.parent.result.store.getLocal(source).boxy_desc != null;

        var frame: BoundaryFrame = .{ .state = .{ .payloads = .{
            .target_locals = &.{},
            .source_locals = &.{},
            .target_children = target_payloads,
            .source_children = source_payloads,
            .source = source,
            .source_tag_rep = source_tag_rep,
            .tag_name = source_variant.name,
            .variant_index = @intCast(source_index),
            .remaining = target_payloads.len,
            .current = undefined,
        } } };
        errdefer self.releaseBoundaryFrame(&frame);
        const payloads = &frame.state.payloads;
        payloads.target_locals = try allocator.alloc(LIR.LocalId, target_payloads.len);
        payloads.source_locals = try allocator.alloc(ExtractedTagPayloadLocal, source_payloads.len);

        if (target_payloads.len == 1) {
            payloads.target_locals[0] = target_payload;
            payloads.source_locals[0] = try self.addExtractedTagPayloadLocal(source_payloads[0].rep, source_has_payload_desc);
            const descriptor_fields = [_]AggregateDescriptorField{.{
                .local = target_payload,
                .target_rep = target_payloads[0].rep,
                .source_rep = source_payloads[0].rep,
            }};
            payloads.tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, &descriptor_fields);
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = payloads.tag_desc.?.desc,
                .variant_index = target_variant_index,
                .discriminant = target_variant_index,
                .payload = target_payload,
                .next = next,
            } }, self.glueOrigin());
            payloads.current = try self.prependOptionalDescriptorMaterialization(payloads.tag_desc.?.materialize, assign_tag);
            try frames.append(allocator, frame);
            return .pushed;
        }

        const target_payload_layout = self.parent.result.store.getLocal(target_payload).layout_idx;
        for (payloads.target_locals, 0..) |*local, index| {
            local.* = try self.addFrameLocal(try self.aggregateFieldLayout(target_payload_layout, index));
        }
        for (source_payloads, payloads.source_locals) |child, *local| {
            local.* = try self.addExtractedTagPayloadLocal(child.rep, source_has_payload_desc);
        }

        const descriptor_fields = try allocator.alloc(AggregateDescriptorField, target_payloads.len);
        defer allocator.free(descriptor_fields);
        for (payloads.target_locals, target_payloads, source_payloads, descriptor_fields) |field_local, target_child, source_child, *field| {
            field.* = .{
                .local = field_local,
                .target_rep = target_child.rep,
                .source_rep = source_child.rep,
            };
        }
        payloads.tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, descriptor_fields);
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
            .target = target,
            .target_desc = payloads.tag_desc.?.desc,
            .variant_index = target_variant_index,
            .discriminant = target_variant_index,
            .payload = target_payload,
            .next = next,
        } }, self.glueOrigin());
        const continuation = try self.prependOptionalDescriptorMaterialization(payloads.tag_desc.?.materialize, assign_tag);
        payloads.current = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target_payload,
            .fields = try self.parent.result.store.addLocalSpan(payloads.target_locals),
            .next = continuation,
        } }, self.glueOrigin());
        try frames.append(allocator, frame);
        return .pushed;
    }

    fn beginConcreteTagUnionToDynamicBoundary(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const target = request.target;
        const source = request.source;
        const target_rep = request.target_rep;
        const source_rep = request.source_rep;
        const next = request.next;
        if (!self.repHasTagDomain(target_rep)) return null;
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse return null;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (source_layout_value.tag != .tag_union) return null;

        const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(source_tag_rep)].tag_variants);
        if (variants.len == 0) return null;
        var all_variants_have_no_payload = true;
        for (variants) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            if (source_payloads.len != 0) all_variants_have_no_payload = false;
            var seen_payloads = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer seen_payloads.deinit();
            const target_payloads = (try self.dynamicTagPayloadsForTextInner(target_rep, self.tagVariantNameText(variant), &seen_payloads)) orelse return null;
            if (source_payloads.len != target_payloads.len) return null;
        }
        // Reusing the concrete source descriptor relabels the source value's box
        // as the open target without rewriting it. When the open row's storage
        // is wider than the concrete tag, reading the relabelled box through the
        // open descriptor runs past the boxed allocation. For payloadless
        // variants the per-variant conversion below rebuilds the open tag
        // exactly, so decline the relabel there and let it run.
        const target_payload_layout = self.parent.descriptorPayloadLayoutForRep(target_rep);
        const source_storage_size = self.parent.result.layouts.layoutSize(self.parent.result.layouts.getLayout(source_layout));
        const target_storage_size = self.parent.result.layouts.layoutSize(self.parent.result.layouts.getLayout(target_payload_layout));
        const relabel_would_overread = all_variants_have_no_payload and source_storage_size < target_storage_size;
        if (!relabel_would_overread and
            self.tagDomainHasOpenExtension(target_rep) and
            try self.concreteTagUnionBoundaryCanReuseSourceDescriptor(target_rep, source_tag_rep, variants))
        {
            const source_desc = try self.descriptorRefForSourceStorageLocalRep(source, source_rep);
            const existing_target_desc = self.parent.result.store.getLocal(target).boxy_desc;
            const can_initialize_target_desc = if (existing_target_desc) |existing|
                std.meta.eql(existing, source_desc) or
                    if (existing.localOrNull()) |local| !self.localIsReadOnlyDescriptorInput(local) else false
            else
                true;
            if (can_initialize_target_desc) {
                const target_desc_info = self.resultDescriptorForCallTarget(target, .{ .desc = source_desc });
                const target_desc = target_desc_info.desc orelse
                    boxyLowerInvariant("boxy concrete tag relabel had no target descriptor");
                if (existing_target_desc == null) {
                    self.parent.result.store.setLocalBoxyDesc(target, target_desc);
                }
                const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = source,
                    .payload_layout = source_layout,
                    .source_desc = source_desc,
                    .payload_desc = target_desc,
                    .payload_mode = .move,
                    .next = next,
                } }, self.glueOrigin());
                return .{ .done = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, box) };
            }
        }

        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
        try self.pushBoundaryFrame(frames, .{ .state = .{ .tag_union = .{
            .request = request,
            .kind = .dynamic,
            .source_tag_rep = source_tag_rep,
            .source_variants = variants,
            .branches = branches,
        } } });
        return .pushed;
    }

    /// Begin the current source variant's branch of a dynamic target.
    fn beginConcreteTagVariantToDynamic(self: *ProcBodyBuilder, frames: *std.ArrayList(BoundaryFrame), state: *TagUnionBoundaryState) Allocator.Error!BoundaryStep {
        const variant_position = state.variant;
        if (variant_position > std.math.maxInt(u32)) {
            boxyLowerInvariant("boxy concrete-to-dynamic tag adapter variant index exceeded LIR variant range");
        }
        state.branches[variant_position].value = @intCast(variant_position);
        const variant = state.source_variants[variant_position];
        const variant_index: u32 = @intCast(variant_position);
        const target = state.request.target;
        const target_rep = state.request.target_rep;
        const source = state.request.source;
        const source_tag_rep = state.source_tag_rep;
        const allocator = self.parent.allocator;

        try self.bindConstructedTargetDescriptor(target, target_rep);
        const target_desc = try self.constructedTargetDescForRep(target_rep);
        const tag_name = try self.lirTagNameForVariant(variant);
        const source_payloads = self.parent.plan.childSlice(variant.payloads);
        const target_payloads = try self.dynamicTagPayloadsForVariantName(target_rep, variant);
        if (source_payloads.len != target_payloads.len) {
            boxyLowerInvariant("boxy concrete-to-dynamic tag adapter saw payload count mismatch between source and target variants");
        }
        if (target_payloads.len == 0) {
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                .target = target,
                .target_desc = target_desc,
                .tag_name = tag_name,
                .next = state.request.next,
            } }, self.glueOrigin());
            return .{ .done = try self.prependConstructedDescriptorRebindForRep(target_rep, assign_tag) };
        }

        const payload = try self.dynamicTagPayloadLocalForChildren(target_payloads);
        const payload_desc = if (payload.desc_rep) |payload_rep| try self.descriptorRefForKnownRep(payload_rep) else null;
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
            .target = target,
            .target_desc = target_desc,
            .tag_name = tag_name,
            .payload = payload.local,
            .payload_layout = payload.layout_idx,
            .payload_desc = payload_desc,
            .payload_mode = .move,
            .next = state.request.next,
        } }, self.glueOrigin());
        const continuation = try self.prependConstructedDescriptorRebindForRep(target_rep, assign_tag);
        const source_has_payload_desc = self.parent.plan.representations.items[@backingInt(source_tag_rep)].descriptor != null or
            self.parent.result.store.getLocal(source).boxy_desc != null;

        var frame: BoundaryFrame = .{ .state = .{ .payloads = .{
            .target_locals = &.{},
            .source_locals = &.{},
            .target_children = target_payloads,
            .source_children = source_payloads,
            .source = source,
            .source_tag_rep = source_tag_rep,
            .tag_name = variant.name,
            .variant_index = variant_index,
            .remaining = source_payloads.len,
            .current = continuation,
        } } };
        errdefer self.releaseBoundaryFrame(&frame);
        const payloads = &frame.state.payloads;
        payloads.source_locals = try allocator.alloc(ExtractedTagPayloadLocal, source_payloads.len);
        payloads.target_locals = try allocator.alloc(LIR.LocalId, target_payloads.len);

        if (target_payloads.len == 1) {
            payloads.source_locals[0] = try self.addExtractedTagPayloadLocal(source_payloads[0].rep, source_has_payload_desc);
            payloads.target_locals[0] = payload.local;
            try frames.append(allocator, frame);
            return .pushed;
        }

        for (source_payloads, payloads.source_locals) |source_payload, *field| {
            field.* = try self.addExtractedTagPayloadLocal(source_payload.rep, source_has_payload_desc);
        }
        for (target_payloads, payloads.target_locals) |target_payload, *field| {
            field.* = try self.addFrameLocalForRep(target_payload.rep);
        }
        payloads.current = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload.local,
            .fields = try self.parent.result.store.addLocalSpan(payloads.target_locals),
            .next = continuation,
        } }, self.glueOrigin());
        try frames.append(allocator, frame);
        return .pushed;
    }

    fn finishTagUnionBoundary(self: *ProcBodyBuilder, state: *TagUnionBoundaryState) Allocator.Error!LIR.CFStmtId {
        // Both kinds branch on every variant of the concrete source, so the
        // switch cannot miss and its last variant is the default.
        if (state.branches.len != state.source_variants.len or state.branches.len == 0) {
            boxyLowerInvariant("boxy tag boundary did not branch on every source variant");
        }
        const last = state.branches.len - 1;
        const discriminant = try self.addFrameLocal(.u32);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(state.branches[0..last]),
            .default_branch = state.branches[last].body,
            .continuation = null,
        } }, self.glueOrigin());
        const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = state.request.source } },
            .next = switch_stmt,
        } }, self.glueOrigin());
        const scope = state.scope orelse return read_discriminant;
        const stmt = try self.leaveNominalBackingFormalScope(scope, read_discriminant);
        state.scope = null;
        return stmt;
    }

    fn beginDynamicTagUnionToDynamicBoundary(self: *ProcBodyBuilder, request: BoundaryRequest) Allocator.Error!?BoundaryStep {
        const target_rep = request.target_rep;
        if (!self.repHasTagDomain(target_rep)) return null;
        const source_tag_rep = self.tagVariantRepForBoundary(request.source_rep) orelse return null;
        if (self.tagDomainHasOpenExtension(source_tag_rep) and
            try self.tagDomainDescriptorCanFlowTo(source_tag_rep, target_rep))
        {
            return null;
        }
        const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@backingInt(source_tag_rep)].tag_variants);
        if (variants.len == 0) return null;
        for (variants) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            const target_payloads = (try self.dynamicTagPayloadsForRepTagNameOrNull(target_rep, source_tag_rep, variant.name)) orelse return null;
            if (source_payloads.len != target_payloads.len) return null;
        }
        // A row-polymorphic source can carry its active variant in a runtime
        // extension descriptor, so enumerating only the source rep's local
        // variants is not exhaustive. The explicit adapter specializes the
        // target descriptor from the exact source descriptor and materializes
        // every local or extension variant through that descriptor pair.
        if (try self.plannedCallBoundaryLowersStructure(request.target, request.source, target_rep, request.source_rep)) {
            return .{ .request = .{
                .target = request.target,
                .source = request.source,
                .target_rep = target_rep,
                .source_rep = request.source_rep,
                .mode = .move,
                .next = request.next,
            } };
        }
        return .{ .done = try self.assignRuntimeAdapterBoundary(request.target, request.source, target_rep, request.source_rep, .move, request.next) };
    }

    fn assignDescriptorAwareNominalBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc;
        const source_desc = self.parent.result.store.getLocal(source).boxy_desc;
        if (target_desc) |desc| {
            if (desc.localOrNull()) |target_desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(target_desc_local) and
                    (source_desc == null or !std.meta.eql(desc, source_desc.?)))
                {
                    // A runtime adapter cannot convert a callable; a value
                    // holding one crosses its nominal wrappers into their
                    // backings, whose structure lowering converts, wrapping
                    // each callable in an adapter.
                    if (try self.repHoldsCallableInStructure(target_rep) or
                        try self.repHoldsCallableInStructure(source_rep))
                    {
                        const target_backing = self.nominalWrapperBackingRep(target_rep);
                        const source_backing = self.nominalWrapperBackingRep(source_rep);
                        if (target_backing == target_rep and source_backing == source_rep) {
                            boxyLowerInvariant("boxy callable-holding nominal boundary had no nominal wrapper to cross");
                        }
                        const scope = try self.enterNominalWrapperFormalScopes(target_rep);
                        errdefer self.dropNominalBackingFormalScope(scope);
                        const body = try self.assignRepresentationBoundaryWithSourceMode(
                            target,
                            source,
                            target_backing,
                            source_backing,
                            source_mode,
                            next,
                        );
                        return try self.leaveNominalBackingFormalScope(scope, body);
                    }
                    return try self.assignRuntimeAdapterBoundary(
                        target,
                        source,
                        target_rep,
                        source_rep,
                        source_mode,
                        next,
                    );
                }
            }
        }
        return try self.assignNominalBoundary(target, source, next);
    }

    fn assignDynamicBoxStorageToConcrete(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
        const target_desc_info = try self.storageDescriptorForRepIfNeeded(target_rep);
        var selected_target_desc = target_desc_info;
        if (selected_target_desc.desc == null and self.repContainsDynamicStorage(target_rep)) {
            if (self.parent.result.store.getLocal(target).boxy_desc == null) {
                selected_target_desc.desc = source_desc;
            }
        }
        const resolved_target_desc = self.resultDescriptorForCallTarget(target, selected_target_desc);
        if (self.parent.result.store.getLocal(target).boxy_desc == null) {
            if (resolved_target_desc.desc) |desc| {
                self.parent.result.store.setLocalBoxyDesc(target, desc);
            }
        }
        const adapt = try self.assignDynamicBoxMaterialization(
            target,
            source,
            source_desc,
            resolved_target_desc.desc,
            source_mode,
            next,
        );
        return try self.prependOptionalDescriptorMaterialization(resolved_target_desc.materialize, adapt);
    }

    fn assignDynamicBoxMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_desc: LIR.BoxyDescRef,
        target_desc: ?LIR.BoxyDescRef,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
            .target = target,
            .source = source,
            .adapter = try self.internAdapter(
                .materialize,
                source_layout,
                target_layout,
                source_mode == .move,
            ),
            .source_desc = source_desc,
            .target_desc = target_desc,
            .source_mode = source_mode,
            .next = next,
        } }, self.glueOrigin());
    }

    fn assignDynamicBoxToDynamicBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
        if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
            if (target_desc.localOrNull()) |target_desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(target_desc_local)) {
                    if (target == source) {
                        if (std.meta.eql(target_desc, source_desc)) return next;
                        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                            .target = target_desc_local,
                            .desc = source_desc,
                            .next = next,
                        } }, self.glueOrigin());
                    }
                    if (self.parent.result.store.getLocal(source).boxy_desc == null) {
                        self.parent.result.store.setLocalBoxyDesc(source, source_desc);
                    }
                    return try self.assignLocal(target, source, next);
                }
            }
            // The target's descriptor is a fixed boundary identity. Preserve
            // it and materialize the source through the planned adapter instead
            // of trying to attach the source's descriptor to the target local.
            return try self.assignLocal(target, source, next);
        }
        if (!self.descriptorBindingIsBoundForRep(target_rep)) {
            if (try self.reserveDescriptorLocalForRep(target_rep)) |reserved_target_desc| {
                var target_desc = reserved_target_desc;
                if (self.localIsReadOnlyDescriptorInput(target_desc)) {
                    target_desc = try self.addFrameLocal(.opaque_ptr);
                }
                self.parent.result.store.setLocalBoxyDesc(target, .{ .local = target_desc });
                const rebind = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                    .target = target_desc,
                    .desc = source_desc,
                    .next = if (target == source) next else try self.assignLocal(target, source, next),
                } }, self.glueOrigin());
                return rebind;
            }
        }
        self.parent.result.store.setLocalBoxyDesc(target, source_desc);
        return if (target == source) next else try self.assignLocal(target, source, next);
    }

    fn descriptorForSourceListElement(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_list_rep: Plan.TypeRepId,
        source_elem_rep: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const identity_list_rep = self.descriptorStorageRep(source_list_rep);
        const identity_elem_rep = self.descriptorStorageRep(source_elem_rep);
        if (try self.sourceNestedDescriptorLocalForHiddenArg(source, identity_list_rep, identity_elem_rep)) |nested| {
            return .{
                .desc = .{ .local = nested.local },
                .materialize = nested,
            };
        }

        const materialization = try self.descriptorMaterializationForSourceRep(identity_elem_rep);
        if (materialization.captures.len == 0) {
            return .{ .desc = materialization.desc };
        }

        const desc_local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .desc = .{ .local = desc_local },
            .materialize = materialization.initializer(desc_local),
        };
    }

    fn assignSingletonZstTagToConcreteBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        if (!self.isZstLocal(source)) return null;

        const target_tag_rep = self.tagVariantRepForBoundary(target_rep) orelse return null;
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        if (target_layout_value.tag != .tag_union) return null;

        const source_rep_info = self.parent.plan.representations.items[@backingInt(source_tag_rep)];
        const source_variants = self.parent.plan.tagVariantSlice(source_rep_info.tag_variants);
        if (source_variants.len != 1) return null;
        const source_variant = source_variants[0];
        if (self.parent.plan.childSlice(source_variant.payloads).len != 0) return null;

        const target_rep_info = self.parent.plan.representations.items[@backingInt(target_tag_rep)];
        const target_variants = self.parent.plan.tagVariantSlice(target_rep_info.tag_variants);
        const source_name = self.tagVariantNameText(source_variant);

        for (target_variants, 0..) |target_variant, index| {
            if (!std.mem.eql(u8, source_name, self.tagVariantNameText(target_variant))) continue;
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("singleton tag widening target variant index exceeded LIR variant range");
            }
            if (self.parent.plan.childSlice(target_variant.payloads).len != 0) return null;
            if (self.isZstLocal(target)) return try self.assignZst(target, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = try self.boundaryTargetDesc(target, target_rep),
                .variant_index = @intCast(index),
                .discriminant = @intCast(index),
                .payload = null,
                .next = next,
            } }, self.glueOrigin());
        }

        return null;
    }

    /// Adapt a concrete tag union into a target whose every payload is
    /// zero-sized, so its layout collapsed to a bare scalar discriminant.
    /// Concrete tag-union layouts on both sides order variants the same way
    /// (alphabetically, over the same checked tag set), so the discriminant
    /// carries over positionally; only its byte position and width change.
    fn assignConcreteTagUnionToScalarBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (source_layout_value.tag != .tag_union) return null;
        switch (target_layout_value.tag) {
            .scalar => {},
            .tag_union => {
                // Only a target whose variants all have zero-sized payloads is
                // a bare discriminant; other unions need payload conversion.
                const target_info = self.parent.result.layouts.getTagUnionInfo(target_layout_value);
                var variant_index: u32 = 0;
                while (variant_index < target_info.variants.len) : (variant_index += 1) {
                    const payload_layout = target_info.variants.get(variant_index).payload_layout;
                    if (!self.parent.result.layouts.isZeroSized(self.parent.result.layouts.getLayout(payload_layout))) return null;
                }
            },
            .box, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .ptr => return null,
        }

        const source_tag_count = self.checkedTagUnionCountForBoundary(source_rep) orelse return null;
        const target_tag_count = self.checkedTagUnionCountForBoundary(target_rep) orelse return null;
        if (source_tag_count != target_tag_count) return null;
        const source_layout_info = self.parent.result.layouts.getTagUnionInfo(source_layout_value);
        if (source_layout_info.variants.len != source_tag_count) return null;

        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, source_tag_count);
        defer self.parent.allocator.free(branches);
        for (branches, 0..) |*branch, index| {
            branch.* = .{
                .value = @intCast(index),
                .body = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                    .target = target,
                    .value = .{ .i64_literal = .{
                        .value = @intCast(index),
                        .layout_idx = target_layout,
                    } },
                    .next = next,
                } }, self.glueOrigin()),
            };
        }

        const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error, self.glueOrigin());
        const discriminant = try self.addFrameLocal(.u32);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = bad_discriminant,
            .continuation = null,
        } }, self.glueOrigin());
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } }, self.glueOrigin());
    }

    /// The number of tags in the checked tag-union type behind this
    /// representation, following alias and transparent-nominal wrappers, or
    /// null when the representation does not resolve to a closed checked tag
    /// union.
    fn checkedTagUnionCountForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?usize {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tag_union => {
                    const view = procedureModuleById(self.parent.modules, rep.source_type.module);
                    var ty = rep.source_type.ty;
                    while (true) {
                        switch (view.checked_types.payload(ty)) {
                            .alias => |alias| ty = alias.backing,
                            .tag_union => |tag_union| return tag_union.tags.len,
                            .pending, .err, .flex, .rigid, .record, .tuple, .nominal, .function, .empty_record, .empty_tag_union => return null,
                        }
                    }
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return null,
            }
        }
    }

    fn concreteTagUnionBoundaryCanReuseSourceDescriptor(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_tag_rep: Plan.TypeRepId,
        variants: []const Plan.TagVariant,
    ) Allocator.Error!bool {
        for (variants) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            const target_payloads = (try self.dynamicTagPayloadsForRepTagNameOrNull(target_rep, source_tag_rep, variant.name)) orelse {
                return false;
            };
            if (source_payloads.len != target_payloads.len) {
                return false;
            }
            for (source_payloads, target_payloads) |source_payload, target_payload| {
                const identity_source = self.descriptorStorageRep(source_payload.rep);
                const identity_target = self.descriptorStorageRep(target_payload.rep);
                // Relabelling reuses the source value's bytes and descriptor
                // under the target rep's identity, so it is only sound when the
                // source and target agree on how each payload field is stored.
                // A worker can return a tag whose payload fields are erased
                // (`erased_box`) while the dynamic target realizes them inline
                // (a fully-concrete instantiation, e.g. `Ok(val, input)` at a
                // call site where both are `Str`). Reusing the erased source
                // descriptor there would leave the boxed fields where the
                // target expects inline bytes, so require matching storage and
                // otherwise let the per-variant construct materialize the fields.
                if (self.repStoredAsDynamicBox(identity_source) != self.repStoredAsDynamicBox(identity_target)) return false;
                if (!try self.repsCanReuseSourceDescriptor(identity_source, identity_target)) return false;
            }
        }
        return true;
    }

    fn repStoredAsDynamicBox(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        return switch (self.workerRuntimeLayoutForRep(rep_id)) {
            .dynamic_box => true,
            .concrete => false,
        };
    }

    fn repsCanReuseSourceDescriptor(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.repsCanReuseSourceDescriptorInner(source_rep, target_rep, &seen);
    }

    /// Whether a source descriptor can describe the target: every pair the
    /// two reach agrees. A pair already seen agrees unless some other
    /// position proves otherwise, which is how recursive types terminate.
    fn repsCanReuseSourceDescriptorInner(
        self: *ProcBodyBuilder,
        root_source: Plan.TypeRepId,
        root_target: Plan.TypeRepId,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList([2]Plan.TypeRepId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, .{ root_source, root_target });
        while (pending.pop()) |pair| {
            const identity_source = self.descriptorStorageRep(pair[0]);
            const identity_target = self.descriptorStorageRep(pair[1]);
            if (identity_source == identity_target) continue;

            const key = (@as(u64, @backingInt(identity_source)) << 32) | @as(u64, @backingInt(identity_target));
            const entry = try seen.getOrPut(key);
            if (entry.found_existing) continue;

            const source = self.parent.plan.representations.items[@backingInt(identity_source)];
            const target = self.parent.plan.representations.items[@backingInt(identity_target)];
            switch (source.kind) {
                .dynamic => {},
                .primitive => |source_primitive| switch (target.kind) {
                    .primitive => |target_primitive| if (source_primitive != target_primitive) return false,
                    .in_progress, .dynamic, .bool_tag_union, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return false,
                },
                .bool_tag_union => if (target.kind != .bool_tag_union) return false,
                .empty_record => if (target.kind != .empty_record) return false,
                .empty_tag_union => if (target.kind != .empty_tag_union) return false,
                .tag_union => switch (target.kind) {
                    .tag_union => {
                        const target_variants = self.parent.plan.tagVariantSlice(target.tag_variants);
                        for (self.parent.plan.tagVariantSlice(source.tag_variants)) |source_variant| {
                            const source_name = self.tagVariantNameText(source_variant);
                            const target_variant = for (target_variants) |candidate| {
                                if (std.mem.eql(u8, source_name, self.tagVariantNameText(candidate))) break candidate;
                            } else return false;
                            const source_payloads = self.parent.plan.childSlice(source_variant.payloads);
                            const target_payloads = self.parent.plan.childSlice(target_variant.payloads);
                            if (source_payloads.len != target_payloads.len) return false;
                            for (source_payloads, target_payloads) |source_payload, target_payload| {
                                try pending.append(allocator, .{ source_payload.rep, target_payload.rep });
                            }
                        }
                    },
                    .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return false,
                },
                .list => switch (target.kind) {
                    .list => try pending.append(allocator, .{
                        self.repQuery().requiredSingleChild(identity_source, .list_elem).rep,
                        self.repQuery().requiredSingleChild(identity_target, .list_elem).rep,
                    }),
                    .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .tuple, .nominal, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return false,
                },
                .in_progress, .erased_callable, .alias, .record, .tuple, .nominal, .box, .generated_field, .generated_field_names, .generated_tag_union_spec => return false,
            }
        }
        return true;
    }

    fn tagDomainHasOpenExtension(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) bool {
        const ext_rep_id = self.tagDomainExtensionRep(rep_id) orelse return false;
        return !self.repIsEmptyTagUnion(ext_rep_id);
    }

    fn tagDomainExtensionRep(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) ?Plan.TypeRepId {
        const tag_rep_id = self.tagDomainRep(rep_id) orelse return null;
        const rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            return child.rep;
        }
        return null;
    }

    fn repIsEmptyTagUnion(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) bool {
        const identity = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity)];
        return rep.kind == .empty_tag_union;
    }

    fn tagDomainDescriptorCanFlowTo(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.tagDomainDescriptorCanFlowToInner(source_rep, target_rep, &seen);
    }

    /// Whether a source tag domain's descriptor can flow to the target:
    /// the source row and each of its extensions in turn.
    fn tagDomainDescriptorCanFlowToInner(
        self: *ProcBodyBuilder,
        root_source: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        var source_rep = root_source;
        while (true) {
            const identity_source = self.descriptorStorageRep(source_rep);
            const identity_target = self.descriptorStorageRep(target_rep);
            const key = (@as(u64, @backingInt(identity_source)) << 32) | @as(u64, @backingInt(identity_target));
            const entry = try seen.getOrPut(key);
            if (entry.found_existing) return true;

            const source_tag_rep = self.tagDomainRep(identity_source) orelse
                return self.targetAcceptsUnconstrainedDynamicTagDescriptor(identity_target);
            if (self.tagDomainRep(identity_target) == null) {
                return self.targetAcceptsUnconstrainedDynamicTagDescriptor(identity_target);
            }

            const source_rep_value = self.parent.plan.representations.items[@backingInt(source_tag_rep)];
            for (self.parent.plan.tagVariantSlice(source_rep_value.tag_variants)) |variant| {
                const source_payloads = self.parent.plan.childSlice(variant.payloads);
                if (try self.dynamicTagPayloadsForRepTagNameOrNull(identity_target, source_tag_rep, variant.name)) |target_payloads| {
                    if (!try self.tagPayloadsCanReuseDescriptor(source_payloads, target_payloads, seen)) return false;
                } else if (!self.targetTagDomainHasUnconstrainedExtension(identity_target)) {
                    return false;
                }
            }

            const source_ext = self.tagDomainExtensionRep(source_tag_rep) orelse return true;
            if (self.repIsEmptyTagUnion(source_ext)) return true;
            source_rep = source_ext;
        }
    }

    fn tagPayloadsCanReuseDescriptor(
        self: *ProcBodyBuilder,
        source_payloads: []const Plan.RepChild,
        target_payloads: []const Plan.RepChild,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        if (source_payloads.len != target_payloads.len) return false;
        for (source_payloads, target_payloads) |source_payload, target_payload| {
            const identity_source = self.descriptorStorageRep(source_payload.rep);
            const identity_target = self.descriptorStorageRep(target_payload.rep);
            if (!try self.repsCanReuseSourceDescriptorInner(identity_source, identity_target, seen)) return false;
        }
        return true;
    }

    /// Whether the target, or some extension along its row, is an
    /// unconstrained dynamic tag row.
    fn targetAcceptsUnconstrainedDynamicTagDescriptor(
        self: *const ProcBodyBuilder,
        root: Plan.TypeRepId,
    ) bool {
        var target_rep = root;
        while (true) {
            const identity_target = self.descriptorStorageRep(target_rep);
            const target = self.parent.plan.representations.items[@backingInt(identity_target)];
            if (target.kind == .dynamic and target.tag_variants.len == 0 and target.children.len == 0) return true;
            target_rep = self.tagDomainExtensionRep(identity_target) orelse return false;
        }
    }

    fn targetTagDomainHasUnconstrainedExtension(
        self: *const ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
    ) bool {
        const ext_rep = self.tagDomainExtensionRep(target_rep) orelse return false;
        return self.targetAcceptsUnconstrainedDynamicTagDescriptor(ext_rep);
    }

    fn repHasTagDomain(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const tag_rep_id = self.tagDomainRep(rep_id) orelse return false;
        const rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
        if (rep.tag_variants.len != 0) return true;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            const ext_rep = self.parent.plan.representations.items[@backingInt(child.rep)];
            return ext_rep.kind != .empty_tag_union;
        }
        return false;
    }

    fn tagDomainHasLocalVariant(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        tag_name: names.TagNameId,
    ) bool {
        const tag_rep_id = self.tagDomainRep(rep_id) orelse return false;
        const rep = self.parent.plan.representations.items[@backingInt(tag_rep_id)];
        const expected_name = self.module.canonical_names.tagLabelText(tag_name);
        for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
            if (std.mem.eql(u8, expected_name, self.tagVariantNameText(variant))) return true;
        }
        return false;
    }

    fn tagDomainRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tag_union, .dynamic => return current,
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return null,
            }
        }
    }

    fn assignConcreteTagPayloadRead(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        target_desc: ?LIR.LocalId,
        source: LIR.LocalId,
        source_tag_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        variant_index: u32,
        payload_index: u32,
        payload_count: usize,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const tag_rep = self.parent.plan.representations.items[@backingInt(source_tag_rep)];
        var after_read = next;
        if (target_desc) |desc_local| {
            after_read = try self.recordDescriptorEnvironmentFromDescriptorLocal(
                target,
                self.parent.tagPayloadStorageDescRep(target_rep),
                desc_local,
                after_read,
            );
        }
        // A closed checked row can still use generic source storage.
        if (tag_rep.descriptor != null or target_desc != null or self.parent.result.store.getLocal(source).boxy_desc != null) {
            const writable_target_desc = if (target_desc) |desc_local|
                if (self.localIsReadOnlyDescriptorInput(desc_local)) null else desc_local
            else
                null;
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag_payload = .{
                .target = target,
                .target_desc = writable_target_desc,
                .source = source,
                .source_desc = try self.descriptorRefForLocalOrKnownRep(source, source_tag_rep),
                .tag_name = try self.lirTagNameForRep(source_tag_rep, tag_name),
                .payload_index = payload_index,
                .source_mode = .copy,
                .next = after_read,
            } }, self.glueOrigin());
        }

        if (self.isZstLocal(target)) return try self.assignZst(target, after_read);
        // A recursive payload is stored boxed; read the stored field, then
        // convert it to the payload's own layout.
        const field_layout = self.parent.tagVariantPayloadFieldLayout(
            self.tagUnionPayloadLayout(self.parent.result.store.getLocal(source).layout_idx, variant_index),
            payload_index,
            payload_count,
        );
        if (field_layout != self.parent.result.store.getLocal(target).layout_idx) {
            const stored = try self.addFrameLocal(field_layout);
            const convert = try self.assignWorkerValueToTagPayloadStorage(target, stored, target_rep, after_read);
            return try self.assignConcreteTagPayloadReadAs(stored, source, variant_index, payload_index, payload_count, convert);
        }
        return try self.assignConcreteTagPayloadReadAs(target, source, variant_index, payload_index, payload_count, after_read);
    }

    fn assignConcreteTagPayloadReadAs(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        variant_index: u32,
        payload_index: u32,
        payload_count: usize,
        after_read: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (payload_count == 1) {
            return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = target,
                .op = .{ .tag_payload_struct = .{
                    .source = source,
                    .variant_index = variant_index,
                    .tag_discriminant = variant_index,
                } },
                .next = after_read,
            } }, self.glueOrigin());
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .tag_payload = .{
                .source = source,
                .payload_idx = @intCast(payload_index),
                .variant_index = variant_index,
                .tag_discriminant = variant_index,
            } },
            .next = after_read,
        } }, self.glueOrigin());
    }

    fn setLocalReplace(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(target)) return next;
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx) {
            boxyLowerInvariant("boxy reassignment required explicit box/adapt lowering before set_local");
        }
        const write_value = try self.parent.result.store.addCFStmt(.{ .set_local = .{
            .target = target,
            .value = source,
            .mode = .replace_existing,
            .next = next,
        } }, self.origin);
        var transferred = try self.prependSetLocalDescriptorTransfer(target, source, .replace_existing, write_value);
        transferred = try self.prependLocalDescriptorEnvironmentTransfer(target, source, .replace_existing, transferred);
        try self.recordTransferredLocalDescriptorEnvironment(target, source);
        return transferred;
    }

    fn setLocalInitializeJoinParam(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx) {
            boxyLowerInvariant("boxy join parameter initialization required matching layouts");
        }
        const write_value = try self.parent.result.store.addCFStmt(.{ .set_local = .{
            .target = target,
            .value = source,
            .mode = .initialize_join_param,
            .next = next,
        } }, self.glueOrigin());
        var transferred = try self.prependSetLocalDescriptorTransfer(target, source, .initialize_join_param, write_value);
        transferred = try self.prependLocalDescriptorEnvironmentTransfer(target, source, .initialize_join_param, transferred);
        try self.recordTransferredLocalDescriptorEnvironment(target, source);
        return transferred;
    }

    fn setLocalInitializeJoinParamFromRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try self.setLocalInitializeJoinParam(target, source, next);
        if (self.parent.result.store.getLocal(source).boxy_desc != null) return continuation;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return continuation;
        const target_desc_local = target_desc.localOrNull() orelse return continuation;
        const materialization = try self.descriptorMaterializationForSourceStorageLocalRep(source, source_rep);
        continuation = try self.prependDescriptorArgMaterialization(materialization.initializer(target_desc_local), materialization.desc, continuation);
        return continuation;
    }

    fn prependLocalDescriptorEnvironmentTransfer(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        mode: LIR.SetLocalWriteMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_env = self.localDescriptorEnvironmentForLocal(target) orelse return next;
        const source_env = self.localDescriptorEnvironmentForLocal(source) orelse return next;
        var continuation = next;
        // One descriptor local can serve several bindings (a nominal and its
        // backing share their descriptor), so each target local is written
        // once, from the source binding of any representation it serves.
        var written = std.ArrayList(LIR.LocalId).empty;
        defer written.deinit(self.parent.allocator);
        var unmatched = std.ArrayList(LIR.LocalId).empty;
        defer unmatched.deinit(self.parent.allocator);
        for (target_env.bindings) |target_binding| {
            var source_local: ?LIR.LocalId = null;
            for (source_env.bindings) |source_binding| {
                if (source_binding.desc != target_binding.desc or
                    self.descriptorStorageRep(source_binding.rep) != self.descriptorStorageRep(target_binding.rep))
                {
                    continue;
                }
                if (source_local != null and source_local.? != source_binding.local) {
                    boxyLowerInvariant("boxy local descriptor transfer had multiple source locals for one target binding");
                }
                source_local = source_binding.local;
            }
            const value = source_local orelse {
                try unmatched.append(self.parent.allocator, target_binding.local);
                continue;
            };
            if (std.mem.findScalar(LIR.LocalId, written.items, target_binding.local) != null) continue;
            try written.append(self.parent.allocator, target_binding.local);
            if (value == target_binding.local) continue;
            if (self.localIsReadOnlyDescriptorInput(target_binding.local)) {
                boxyLowerInvariant("boxy local descriptor transfer targeted a read-only descriptor input");
            }
            continuation = try self.parent.result.store.addCFStmt(.{ .set_local = .{
                .target = target_binding.local,
                .value = value,
                .mode = mode,
                .next = continuation,
            } }, self.glueOrigin());
        }
        for (unmatched.items) |local| {
            if (std.mem.findScalar(LIR.LocalId, written.items, local) == null) {
                boxyLowerInvariant("boxy local descriptor transfer source was missing a target binding");
            }
        }
        return continuation;
    }

    fn recordTransferredLocalDescriptorEnvironment(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
    ) Allocator.Error!void {
        const env = self.localDescriptorEnvironmentForLocal(source) orelse return;
        if (self.localDescriptorEnvironmentForLocal(target) != null) return;
        const source_desc_local = if (self.parent.result.store.getLocal(source).boxy_desc) |desc| desc.localOrNull() else null;
        const target_desc_local = if (self.parent.result.store.getLocal(target).boxy_desc) |desc| desc.localOrNull() else null;
        const has_direct_transfer = source_desc_local != null and target_desc_local != null and source_desc_local != target_desc_local;
        if (!has_direct_transfer and self.descriptor_transfer_aliases.items.len == 0) {
            try self.recordLocalDescriptorEnvironment(target, env.rep, env.bindings);
            return;
        }

        const transferred = try self.parent.allocator.alloc(LocalDescriptorEnvironmentBinding, env.bindings.len);
        defer self.parent.allocator.free(transferred);
        for (env.bindings, transferred) |binding, *mapped| {
            mapped.* = binding;
            if (has_direct_transfer and binding.local == source_desc_local.?) mapped.local = target_desc_local.?;
            mapped.local = self.transferredDescriptorAlias(mapped.local);
        }
        try self.recordLocalDescriptorEnvironment(target, env.rep, transferred);
    }

    fn prependSetLocalDescriptorTransfer(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        mode: LIR.SetLocalWriteMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const maybe_source_desc = self.parent.result.store.getLocal(source).boxy_desc;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse {
            const source_desc = maybe_source_desc orelse return next;
            self.parent.result.store.setLocalBoxyDesc(target, source_desc);
            return next;
        };
        const target_desc_local = target_desc.localOrNull() orelse return next;
        const source_desc = maybe_source_desc orelse return next;
        if (std.meta.eql(target_desc, source_desc)) return next;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return next;
        try self.markDescriptorLocalBound(target_desc_local);
        const source_desc_local = source_desc.localOrNull() orelse {
            const local = try self.addFrameLocal(.opaque_ptr);
            const transfer = try self.parent.result.store.addCFStmt(.{ .set_local = .{
                .target = target_desc_local,
                .value = local,
                .mode = mode,
                .next = next,
            } }, self.glueOrigin());
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = local,
                .desc = source_desc,
                .next = transfer,
            } }, self.glueOrigin());
        };
        try self.recordDescriptorTransferAlias(source_desc_local, target_desc_local);
        return try self.parent.result.store.addCFStmt(.{ .set_local = .{
            .target = target_desc_local,
            .value = source_desc_local,
            .mode = mode,
            .next = next,
        } }, self.glueOrigin());
    }

    fn recordDescriptorTransferAlias(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        target: LIR.LocalId,
    ) Allocator.Error!void {
        if (source == target) return;
        for (self.descriptor_transfer_aliases.items) |*alias| {
            if (alias.source != source) continue;
            alias.target = target;
            return;
        }
        try self.descriptor_transfer_aliases.append(self.parent.allocator, .{ .source = source, .target = target });
    }

    fn transferredDescriptorAlias(self: *const ProcBodyBuilder, local: LIR.LocalId) LIR.LocalId {
        var current = local;
        var depth: usize = 0;
        while (depth < self.descriptor_transfer_aliases.items.len) : (depth += 1) {
            var changed = false;
            for (self.descriptor_transfer_aliases.items) |alias| {
                if (alias.source != current) continue;
                current = alias.target;
                changed = true;
                break;
            }
            if (!changed) break;
        }
        return current;
    }

    /// A var's descriptor local is introduced by its declaration. Statements
    /// are lowered last to first, so a reassignment already lowered marked it
    /// initialized; before the declaration nothing has, and the declaration's
    /// value initializes it.
    fn forgetVarDescriptorInitialization(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) void {
        switch (self.module.checked_bodies.pattern(pattern_id).data) {
            .assign => {},
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => return,
        }
        const desc = self.parent.result.store.getLocal(self.localForPattern(pattern_id)).boxy_desc orelse return;
        const local = desc.localOrNull() orelse return;
        if (self.descriptorTemplateForLocal(local) == null) return;
        const index = std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) orelse return;
        _ = self.runtime_initialized_descriptor_locals.orderedRemove(index);
    }

    fn markDescriptorLocalBound(self: *ProcBodyBuilder, local: LIR.LocalId) Allocator.Error!void {
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) == null) {
            try self.runtime_initialized_descriptor_locals.append(self.parent.allocator, local);
        }
        for (self.descriptor_locals, 0..) |maybe_local, index| {
            if (maybe_local == local) self.descriptor_bound[index] = true;
        }
        for (self.descriptor_slots, 0..) |maybe_local, index| {
            if (maybe_local == local) self.descriptor_bound[index] = true;
        }
        for (self.descriptor_rep_bindings.items) |*binding| {
            if (binding.local == local) binding.bound = true;
        }
    }

    fn joinParamSpan(
        self: *ProcBodyBuilder,
        values: []const LIR.LocalId,
    ) Allocator.Error!LIR.LocalSpan {
        var params = std.ArrayList(LIR.LocalId).empty;
        defer params.deinit(self.parent.allocator);
        for (values) |value| {
            try params.append(self.parent.allocator, value);
            if (self.parent.result.store.getLocal(value).boxy_desc) |desc| {
                if (desc.localOrNull()) |desc_local| {
                    if (std.mem.findScalar(LIR.LocalId, params.items, desc_local) == null) {
                        try params.append(self.parent.allocator, desc_local);
                    }
                }
            }
            if (self.localDescriptorEnvironmentForLocal(value)) |env| {
                for (env.bindings) |binding| {
                    if (std.mem.findScalar(LIR.LocalId, params.items, binding.local) == null) {
                        try params.append(self.parent.allocator, binding.local);
                    }
                }
            }
        }
        return try self.parent.result.store.addLocalSpan(params.items);
    }

    fn addArgLocal(self: *ProcBodyBuilder, layout_idx: @import("layout").Idx) Allocator.Error!LIR.LocalId {
        const local = try self.parent.addLocal(layout_idx);
        try self.arg_locals.append(self.parent.allocator, local);
        try self.frame_locals.append(self.parent.allocator, local);
        return local;
    }

    fn addArgLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const initial_desc = if (self.erased_argument_descriptors) null else try self.initialDescriptorRefForRep(rep_id);
        const local = try self.parent.addLocalWithBoxyDesc(layout_idx, initial_desc);
        try self.arg_locals.append(self.parent.allocator, local);
        try self.frame_locals.append(self.parent.allocator, local);
        return local;
    }

    fn addFrameLocal(self: *ProcBodyBuilder, layout_idx: @import("layout").Idx) Allocator.Error!LIR.LocalId {
        const local = try self.parent.addLocal(layout_idx);
        try self.frame_locals.append(self.parent.allocator, local);
        return local;
    }

    fn addFrameLocalForType(self: *ProcBodyBuilder, ty: checked.CheckedTypeId) Allocator.Error!LIR.LocalId {
        const rep_id = self.repForType(ty);
        return try self.addFrameLocalForRep(rep_id);
    }

    fn addFrameLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact = self.parent.plan.representations.items[@backingInt(rep_id)];
        const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
        var desc: ?LIR.BoxyDescRef = null;
        if (exact.descriptor == null and
            (exact.contains_dynamic or identity.contains_dynamic) and
            !self.parent.layoutIsBoxStorage(layout_idx) and
            self.parent.layoutNeedsNestedBoxyDesc(layout_idx))
        {
            desc = .{ .local = try self.addFrameLocal(.opaque_ptr) };
        } else {
            desc = try self.frameDescriptorRefForRep(rep_id);
            if (desc == null and self.repContainsDynamicStorage(rep_id)) {
                desc = try self.parent.staticDescRefForRep(identity_rep);
            }
        }
        const local = try self.addFrameLocal(layout_idx);
        if (desc) |desc_ref| self.parent.result.store.setLocalBoxyDesc(local, desc_ref);
        return local;
    }

    fn addGeneratedParserOutputLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        if (!self.parent.layoutNeedsNestedBoxyDesc(layout_idx)) return try self.addFrameLocalForRep(rep_id);
        return try self.addFrameLocalForRepWithRequiredFreshDescriptor(rep_id);
    }

    fn ensureGeneratedParserOutputDescriptorForRep(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!void {
        const layout_idx = self.parent.result.store.getLocal(local).layout_idx;
        if (!self.parent.layoutNeedsNestedBoxyDesc(layout_idx)) return;
        if (self.parent.result.store.getLocal(local).boxy_desc) |desc| {
            if (desc.localOrNull()) |desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(desc_local)) return;
            }
        }

        const desc_local = try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(local, .{ .local = desc_local });
        try self.recordDescriptorLocalTemplate(
            desc_local,
            try self.descriptorMaterializationForExactRep(rep_id),
        );
    }

    fn addFrameLocalForRepWithFreshDescriptor(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const local = try self.addFrameLocal(layout_idx);
        const identity_rep = self.descriptorStorageRep(rep_id);
        const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (identity.descriptor != null or
            (identity.contains_dynamic and self.parent.layoutNeedsNestedBoxyDesc(layout_idx)))
        {
            const desc_local = try self.addFrameLocal(.opaque_ptr);
            self.parent.result.store.setLocalBoxyDesc(local, .{ .local = desc_local });
        } else if (self.repContainsDynamicStorage(rep_id)) {
            self.parent.result.store.setLocalBoxyDesc(local, try self.parent.staticDescRefForRep(identity_rep));
        } else if (try self.descriptorRefForRepIfNeeded(rep_id)) |desc| {
            switch (desc) {
                .static => self.parent.result.store.setLocalBoxyDesc(local, desc),
                .local,
                .runtime,
                .dict_method_arg,
                .dict_method_hidden,
                => self.parent.result.store.setLocalBoxyDesc(local, .{ .local = try self.addFrameLocal(.opaque_ptr) }),
            }
        }
        if (self.parent.result.store.getLocal(local).boxy_desc) |desc| {
            if (desc.localOrNull()) |desc_local| {
                try self.recordDescriptorLocalTemplate(
                    desc_local,
                    try self.descriptorMaterializationForExactRep(rep_id),
                );
            }
        }
        return local;
    }

    fn addFrameLocalForRepWithRequiredFreshDescriptor(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const local = try self.addFrameLocal(self.workerRuntimeLayoutForRep(rep_id).layoutIdx());
        const desc_local = try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(local, .{ .local = desc_local });
        try self.recordDescriptorLocalTemplate(
            desc_local,
            try self.descriptorMaterializationForExactRep(rep_id),
        );
        return local;
    }

    fn frameDescriptorRefForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!?LIR.BoxyDescRef {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.descriptor != null) {
            const local = try self.reserveDescriptorLocalForRep(rep_id) orelse
                boxyLowerInvariant("boxy descriptor-bearing frame representation had no descriptor local");
            return .{ .local = local };
        }
        return try self.descriptorRefForRepIfNeeded(rep_id);
    }

    fn initialDescriptorRefForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!?LIR.BoxyDescRef {
        const identity_rep = self.descriptorStorageRep(rep_id);
        if (self.parent.plan.representations.items[@backingInt(identity_rep)].descriptor != null) return null;
        return try self.descriptorRefForRepIfNeeded(rep_id);
    }

    fn addStructuralEqOperandLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        return try self.addFrameLocalForRepWithFreshDescriptor(rep_id);
    }

    fn addFrameBoundaryTargetLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const runtime = self.workerRuntimeLayoutForRep(rep_id);
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact = self.parent.plan.representations.items[@backingInt(rep_id)];
        const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
        const desc: ?LIR.BoxyDescRef = if (self.parent.layoutIsBoxStorage(runtime.layoutIdx()) or
            exact.descriptor != null or identity.descriptor != null or
            ((exact.contains_dynamic or identity.contains_dynamic) and
                self.parent.layoutNeedsNestedBoxyDesc(runtime.layoutIdx())))
            .{ .local = try self.addFrameLocal(.opaque_ptr) }
        else if (self.repContainsDynamicStorage(rep_id))
            try self.parent.staticDescRefForRep(identity_rep)
        else
            null;
        const local = try self.addFrameLocal(runtime.layoutIdx());
        if (desc) |desc_ref| self.parent.result.store.setLocalBoxyDesc(local, desc_ref);
        if (desc) |desc_ref| {
            if (desc_ref.localOrNull()) |desc_local| {
                try self.recordDescriptorLocalTemplate(
                    desc_local,
                    try self.boundaryDescriptorLocalTemplate(rep_id, desc_local),
                );
            }
        }
        return local;
    }

    /// The initializer template for a fresh call-boundary descriptor local.
    /// When this worker already holds the representation's descriptor
    /// requirement in an evidence-bound local—a hidden descriptor argument
    /// (or prologue-rebuilt argument root) carrying the checker's dispatch
    /// evidence for the value's type—that explicit descriptor is the value's
    /// runtime type and seeds the boundary local. Only a representation whose
    /// requirement holds no evidence in this worker falls back to its exact
    /// static template. Without this precedence a value produced *into* the
    /// boundary local (a numeric literal in a generic worker) would be
    /// described by an erased static template even though the caller passed
    /// the concrete descriptor.
    ///
    /// The evidence-bound query (not plain boundness) is load-bearing: a
    /// binding whose local was merely marked bound by a mid-body descriptor
    /// write (a call output or set-local transfer in a LATER-executing
    /// statement, still visible here because lowering runs in reverse
    /// execution order) must not seed this template—the copy it would emit
    /// executes before that write and would read an uninitialized descriptor.
    fn boundaryDescriptorLocalTemplate(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc_local: LIR.LocalId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        if (rep.descriptor) |requirement| {
            if (self.descriptorBindingIsEvidenceBoundForRep(identity_rep)) {
                if (self.descriptorLocalForRequirementAndRepOrNull(requirement, identity_rep)) |bound| {
                    if (bound != desc_local) {
                        return .{ .desc = .{ .local = bound } };
                    }
                }
            }
        }
        return try self.descriptorMaterializationForExactRep(rep_id);
    }

    fn addFrameLocalForRuntimeRep(
        self: *ProcBodyBuilder,
        runtime: Layouts.RuntimeLayout,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.LocalId {
        if (runtime.layoutIdx() == self.workerRuntimeLayoutForRep(rep_id).layoutIdx()) {
            return try self.addFrameLocalForRep(rep_id);
        }
        const desc = try self.frameDescriptorRefForRep(rep_id);
        const local = try self.addFrameLocal(runtime.layoutIdx());
        if (desc) |desc_ref| self.parent.result.store.setLocalBoxyDesc(local, desc_ref);
        return local;
    }

    fn addWorkerReturnLocal(self: *ProcBodyBuilder, fresh_descriptor: bool) Allocator.Error!LIR.LocalId {
        const worker = self.parent.plan.workers.items[@backingInt(self.worker_layout.worker)];
        const function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy worker return local requested for a non-function worker");
        // A bound return descriptor is an input template, not mutable storage
        // for the exact descriptor produced by this invocation. The body may
        // refine dynamic positions while constructing its result, so workers
        // that return a runtime descriptor always need an independent
        // descriptor local.
        const local = if (fresh_descriptor)
            try self.addFrameLocalForRepWithFreshDescriptor(function.ret)
        else
            try self.addFrameLocalForRep(function.ret);
        // An open record result is described by the value the body returns,
        // which no template over the row's own fields can describe.
        if (fresh_descriptor and !self.repIsOpenRecord(function.ret)) {
            if (self.parent.result.store.getLocal(local).boxy_desc) |desc| {
                if (desc.localOrNull()) |desc_local| {
                    const materialization = try self.descriptorMaterializationForExactResultRep(function.ret);
                    if (materialization.desc.localOrNull() == desc_local) {
                        boxyLowerInvariant("boxy worker return descriptor initializer referenced its own target");
                    }
                    try self.worker_return_descriptor_initializers.append(self.parent.allocator, materialization.initializer(desc_local));
                    try appendUniqueLocal(
                        self.parent.allocator,
                        &self.runtime_initialized_descriptor_locals,
                        desc_local,
                    );
                }
            }
        }
        if (self.parent.result.store.getLocal(local).layout_idx != self.workerReturnLayout()) {
            boxyLowerInvariant("boxy worker return representation layout disagreed with worker layout plan");
        }
        return local;
    }

    fn markLocalDescriptorForType(self: *ProcBodyBuilder, local: LIR.LocalId, ty: checked.CheckedTypeId) Allocator.Error!void {
        const rep_id = self.repForType(ty);
        try self.markLocalDescriptorForRep(local, rep_id);
    }

    fn markLocalDescriptorForRep(self: *ProcBodyBuilder, local: LIR.LocalId, rep_id: Plan.TypeRepId) Allocator.Error!void {
        if (self.parent.result.store.getLocal(local).boxy_desc != null) return;
        const desc_ref = try self.descriptorRefForRepIfNeeded(rep_id);
        if (desc_ref) |desc| {
            self.parent.result.store.setLocalBoxyDesc(local, desc);
        }
    }

    fn mutableDescriptorLocalForValue(self: *ProcBodyBuilder, value: LIR.LocalId) Allocator.Error!LIR.LocalId {
        if (self.parent.result.store.getLocal(value).boxy_desc) |desc| {
            return desc.localOrNull() orelse
                boxyLowerInvariant("boxy runtime descriptor initialization targeted a statically described value");
        }
        const local = try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(value, .{ .local = local });
        return local;
    }

    fn ensureTagPayloadTargetDescriptorLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        payload_rep: Plan.TypeRepId,
    ) Allocator.Error!?LIR.LocalId {
        if (!self.parent.repNeedsTagPayloadDesc(payload_rep)) return null;
        return try self.mutableDescriptorLocalForValue(target);
    }

    fn ensureBinderLocals(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.binder_locals.len != 0) return;
        self.binder_locals = try self.parent.allocator.alloc(?LIR.LocalId, self.module.checked_bodies.patternBinderCount());
        errdefer self.parent.allocator.free(self.binder_locals);
        self.binder_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.module.checked_bodies.patternBinderCount());
        @memset(self.binder_locals, null);
        @memset(self.binder_reps, null);
    }

    fn ensureDescriptorLocals(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.descriptor_locals.len != 0) return;
        self.descriptor_locals = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_locals);
        self.descriptor_local_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_local_reps);
        self.descriptor_bound = try self.parent.allocator.alloc(bool, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_bound);
        self.descriptor_evidence_bound = try self.parent.allocator.alloc(bool, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_evidence_bound);
        self.descriptor_slots = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_slots);
        self.descriptor_slot_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.parent.plan.descriptors.items.len);
        @memset(self.descriptor_locals, null);
        @memset(self.descriptor_local_reps, null);
        @memset(self.descriptor_bound, false);
        @memset(self.descriptor_evidence_bound, false);
        @memset(self.descriptor_slots, null);
        @memset(self.descriptor_slot_reps, null);
    }

    fn ensureDictionaryLocals(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.dictionary_locals.len != 0) return;
        self.dictionary_locals = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.dictionaries.items.len);
        errdefer self.parent.allocator.free(self.dictionary_locals);
        self.dictionary_bound = try self.parent.allocator.alloc(bool, self.parent.plan.dictionaries.items.len);
        errdefer self.parent.allocator.free(self.dictionary_bound);
        self.dictionary_slots = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.dictionaries.items.len);
        @memset(self.dictionary_locals, null);
        @memset(self.dictionary_bound, false);
        @memset(self.dictionary_slots, null);
    }

    fn descriptorRepBindingIndex(
        self: *const ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        identity_rep: Plan.TypeRepId,
    ) ?usize {
        for (self.descriptor_rep_bindings.items, 0..) |binding, index| {
            if (binding.desc == desc and binding.rep == identity_rep) return index;
        }
        return null;
    }

    fn descriptorLocalForRequirementAndRepOrNull(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const desc_index = @backingInt(desc);
        if (desc_index < self.descriptor_locals.len) {
            if (self.descriptor_locals[desc_index]) |local| {
                if (desc_index >= self.descriptor_local_reps.len) {
                    boxyLowerInvariant("boxy descriptor local representation table was missing an entry");
                }
                const local_rep = self.descriptor_local_reps[desc_index] orelse
                    boxyLowerInvariant("boxy descriptor local had no representation binding");
                if (local_rep == identity_rep) return local;
            }
        }

        if (self.descriptorRepBindingIndex(desc, identity_rep)) |index| {
            return self.descriptor_rep_bindings.items[index].local;
        }
        return null;
    }

    fn descriptorLocalForRepOrNull(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        const desc = rep.descriptor orelse return null;
        return self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep);
    }

    fn descriptorBindingIsBoundForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        const desc = rep.descriptor orelse return true;
        const desc_index = @backingInt(desc);
        if (desc_index < self.descriptor_bound.len and self.descriptor_bound[desc_index]) {
            if (desc_index >= self.descriptor_local_reps.len) return false;
            if (self.descriptor_local_reps[desc_index] == identity_rep) return true;
        }
        for (self.descriptor_rep_bindings.items) |binding| {
            if (binding.desc == desc and binding.rep == identity_rep) return binding.bound;
        }
        return false;
    }

    /// Like `descriptorBindingIsBoundForRep`, but true only when the binding
    /// was bound as *evidence* (`markDescriptorRequirementBoundForRep`) rather
    /// than by a mid-body descriptor write (`markDescriptorLocalBound`).
    /// Evidence binds are either established in the worker prologue or inside
    /// a descriptor-binding snapshot window whose initializer is prepended
    /// above everything lowered while the bind is visible, so an evidence
    /// binding's local is always initialized at runtime before any code that
    /// observed the bind executes. Write marks carry no such ordering
    /// guarantee: lowering visits statements in reverse execution order, so a
    /// write mark from a later-executing statement stays visible while
    /// earlier-executing statements are lowered.
    fn descriptorBindingIsEvidenceBoundForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@backingInt(identity_rep)];
        const desc = rep.descriptor orelse return true;
        const desc_index = @backingInt(desc);
        if (desc_index < self.descriptor_evidence_bound.len and self.descriptor_evidence_bound[desc_index]) {
            if (desc_index >= self.descriptor_local_reps.len) return false;
            if (self.descriptor_local_reps[desc_index] == identity_rep) return true;
        }
        for (self.descriptor_rep_bindings.items) |binding| {
            if (binding.desc == desc and binding.rep == identity_rep) return binding.evidence_bound;
        }
        return false;
    }

    fn dictionaryLocalForRequirementOrNull(
        self: *const ProcBodyBuilder,
        dict: Plan.DictionaryRequirementId,
    ) ?LIR.LocalId {
        const dict_index = @backingInt(dict);
        if (dict_index >= self.dictionary_locals.len) return null;
        return self.dictionary_locals[dict_index];
    }

    fn dictionaryBindingIsBound(self: *const ProcBodyBuilder, dict: Plan.DictionaryRequirementId) bool {
        const dict_index = @backingInt(dict);
        if (dict_index >= self.dictionary_bound.len) return false;
        return self.dictionary_bound[dict_index];
    }

    /// Bind a template dictionary method adapter's frame-supplied
    /// requirement descriptors to their requirement identities.
    fn bindFrameRequirementDescriptors(
        self: *ProcBodyBuilder,
        descs: []const FrameRequirementDescriptor,
        locals: []const LIR.LocalId,
        include_requirement: bool,
    ) Allocator.Error!void {
        if (descs.len == 0) return;
        try self.ensureDescriptorLocals();
        for (descs, locals) |desc, local| {
            if (desc.kind == .requirement and !include_requirement) continue;
            try self.bindDescriptorRequirementLocalForRep(desc.desc, desc.rep, local, true);
            if (self.repOwnsDescriptor(desc.rep, desc.desc)) {
                try self.bindDescriptorIdentityLocalForRep(desc.rep, local, true);
            }
        }
    }

    const DetachedDescriptorScope = struct {
        outer_bindings: DescriptorBindingsSnapshot,
        outer_static: ?StaticDescriptorMaterializationScope,
        static: StaticDescriptorMaterializationScope,
    };

    /// Lower a region whose descriptors come only from `static`, apart from
    /// every descriptor this frame has bound.
    fn enterDetachedDescriptorScope(
        self: *ProcBodyBuilder,
        static: StaticDescriptorMaterializationScope,
    ) Allocator.Error!DetachedDescriptorScope {
        const outer_bindings = try self.snapshotDescriptorBindings();
        @memset(self.descriptor_locals, null);
        @memset(self.descriptor_local_reps, null);
        @memset(self.descriptor_bound, false);
        @memset(self.descriptor_evidence_bound, false);
        @memset(self.descriptor_slots, null);
        @memset(self.descriptor_slot_reps, null);
        self.descriptor_rep_bindings.items.len = 0;
        const outer_static = self.static_descriptor_materialization_scope;
        self.static_descriptor_materialization_scope = static;
        return .{ .outer_bindings = outer_bindings, .outer_static = outer_static, .static = static };
    }

    /// End `scope` around `body`: initialize the descriptor slots the region
    /// used from its static sources, then restore the frame's bindings.
    fn leaveDetachedDescriptorScope(
        self: *ProcBodyBuilder,
        scope: DetachedDescriptorScope,
        body: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        defer scope.outer_bindings.deinit(self.parent.allocator);
        const continuation = try self.prependStaticDescriptorMaterializationsForSlotsWithSources(
            scope.static.sources,
            scope.static.context,
            body,
        );
        self.restoreDescriptorBindings(scope.outer_bindings);
        self.static_descriptor_materialization_scope = scope.outer_static;
        return continuation;
    }

    /// Whether a static method's requirement type and its worker describe
    /// values with one descriptor requirement.
    fn staticMethodSidesShareDescriptors(
        self: *ProcBodyBuilder,
        requirement_function: ProcedureBuilder.StaticMethodFunction,
        worker_id: Plan.WorkerPlanId,
    ) Allocator.Error!bool {
        var requirement_params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
        defer requirement_params.deinit(self.parent.allocator);
        try self.collectAllHiddenDescriptorParamsForRep(requirement_function.rep, &requirement_params);
        const worker = self.parent.plan.workers.items[@backingInt(worker_id)];
        for (self.parent.plan.hiddenDescriptorParamSlice(worker.hidden_descs)) |worker_param| {
            for (requirement_params.items) |requirement_param| {
                if (requirement_param.desc == worker_param.desc) return true;
            }
        }
        return false;
    }

    fn snapshotDescriptorBindings(self: *ProcBodyBuilder) Allocator.Error!DescriptorBindingsSnapshot {
        try self.ensureDescriptorLocals();
        const locals = try self.parent.allocator.dupe(?LIR.LocalId, self.descriptor_locals);
        errdefer self.parent.allocator.free(locals);
        const local_reps = try self.parent.allocator.dupe(?Plan.TypeRepId, self.descriptor_local_reps);
        errdefer self.parent.allocator.free(local_reps);
        const bound = try self.parent.allocator.dupe(bool, self.descriptor_bound);
        errdefer self.parent.allocator.free(bound);
        const evidence_bound = try self.parent.allocator.dupe(bool, self.descriptor_evidence_bound);
        errdefer self.parent.allocator.free(evidence_bound);
        const slots = try self.parent.allocator.dupe(?LIR.LocalId, self.descriptor_slots);
        errdefer self.parent.allocator.free(slots);
        const slot_reps = try self.parent.allocator.dupe(?Plan.TypeRepId, self.descriptor_slot_reps);
        errdefer self.parent.allocator.free(slot_reps);
        const rep_bindings = try self.parent.allocator.dupe(DescriptorRepBinding, self.descriptor_rep_bindings.items);
        return .{
            .locals = locals,
            .local_reps = local_reps,
            .bound = bound,
            .evidence_bound = evidence_bound,
            .slots = slots,
            .slot_reps = slot_reps,
            .rep_bindings = rep_bindings,
            .runtime_initialized_len = self.runtime_initialized_descriptor_locals.items.len,
        };
    }

    fn restoreDescriptorBindings(self: *ProcBodyBuilder, snapshot: DescriptorBindingsSnapshot) void {
        if (snapshot.locals.len != self.descriptor_locals.len or
            snapshot.local_reps.len != self.descriptor_local_reps.len or
            snapshot.bound.len != self.descriptor_bound.len or
            snapshot.evidence_bound.len != self.descriptor_evidence_bound.len or
            snapshot.slots.len != self.descriptor_slots.len or
            snapshot.slot_reps.len != self.descriptor_slot_reps.len)
        {
            boxyLowerInvariant("boxy descriptor binding snapshot length disagreed with active descriptor table");
        }
        @memcpy(self.descriptor_locals, snapshot.locals);
        @memcpy(self.descriptor_local_reps, snapshot.local_reps);
        @memcpy(self.descriptor_bound, snapshot.bound);
        @memcpy(self.descriptor_evidence_bound, snapshot.evidence_bound);
        @memcpy(self.descriptor_slots, snapshot.slots);
        @memcpy(self.descriptor_slot_reps, snapshot.slot_reps);
        self.descriptor_rep_bindings.items.len = snapshot.rep_bindings.len;
        @memcpy(self.descriptor_rep_bindings.items, snapshot.rep_bindings);
        self.runtime_initialized_descriptor_locals.items.len = snapshot.runtime_initialized_len;
    }

    fn reserveDescriptorLocalForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.LocalId {
        const reservation = try self.reserveDescriptorLocalForRepWithFresh(rep_id);
        return if (reservation) |reserved| reserved.local else null;
    }

    fn reserveDescriptorLocalForRepWithFresh(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?DescriptorLocalReservation {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.descriptor != null and try self.repDependsOnNominalFormals(rep_id)) {
            const identity_rep = self.descriptorStorageRep(rep_id);
            for (self.scoped_descriptor_locals.items[self.scoped_descriptor_locals_start..]) |scoped| {
                if (scoped.rep == identity_rep) return .{ .local = scoped.local, .fresh = false, .scoped = true };
            }
            const local = try self.addFrameLocal(.opaque_ptr);
            try self.scoped_descriptor_locals.append(self.parent.allocator, .{ .rep = identity_rep, .local = local });
            return .{ .local = local, .fresh = true, .scoped = true };
        }
        if (rep.descriptor) |desc| {
            try self.ensureDescriptorLocals();
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id)) |local| {
                return .{ .local = local, .fresh = false };
            }
        }
        const reservation = try self.reserveDescriptorSlotForRepWithFresh(rep_id);
        if (reservation) |reserved| {
            const desc = rep.descriptor orelse unreachable;
            try self.setDescriptorRequirementLocalForRep(desc, rep_id, reserved.local);
        }
        return reservation;
    }

    fn reserveRuntimeDescriptorLocalForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.LocalId {
        const reservation = try self.reserveDescriptorLocalForRepWithFresh(rep_id);
        if (reservation) |reserved| {
            if (reserved.scoped) return reserved.local;
            const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
            const desc = rep.descriptor orelse unreachable;
            if (!reserved.fresh and self.localIsReadOnlyDescriptorInput(reserved.local)) {
                const desc_index = @backingInt(desc);
                const identity_rep = self.descriptorStorageRep(rep_id);
                const local = try self.addFrameLocal(.opaque_ptr);
                self.descriptor_slots[desc_index] = local;
                self.descriptor_slot_reps[desc_index] = identity_rep;
                try self.setDescriptorRequirementLocalForRep(desc, identity_rep, local);
                self.markDescriptorRequirementBoundForRep(desc, identity_rep);
                return local;
            }
            self.markDescriptorRequirementBoundForRep(desc, rep_id);
            return reserved.local;
        }
        return null;
    }

    fn reserveDescriptorSlotForRepWithFresh(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?DescriptorLocalReservation {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const desc = rep.descriptor orelse return null;
        try self.ensureDescriptorLocals();
        const desc_index = @backingInt(desc);
        if (desc_index >= self.descriptor_slots.len or desc_index >= self.descriptor_slot_reps.len) {
            boxyLowerInvariant("boxy descriptor requirement index exceeded descriptor local table");
        }
        const identity_rep = self.descriptorStorageRep(rep_id);
        if (self.descriptor_slots[desc_index]) |existing| {
            const slot_rep = self.descriptor_slot_reps[desc_index] orelse
                boxyLowerInvariant("boxy descriptor slot had no representation binding");
            if (slot_rep == identity_rep) return .{ .local = existing, .fresh = false };
        }
        const local = try self.addFrameLocal(.opaque_ptr);
        self.descriptor_slots[desc_index] = local;
        self.descriptor_slot_reps[desc_index] = identity_rep;
        return .{ .local = local, .fresh = true };
    }

    fn reserveDictionarySlotForSpan(
        self: *ProcBodyBuilder,
        span: Plan.Span,
    ) Allocator.Error!?LIR.LocalId {
        const reservation = try self.reserveDictionarySlotForSpanWithFresh(span);
        return if (reservation) |reserved| reserved.local else null;
    }

    fn reserveDictionarySlotForSpanWithFresh(
        self: *ProcBodyBuilder,
        span: Plan.Span,
    ) Allocator.Error!?DescriptorLocalReservation {
        if (span.len == 0) return null;
        try self.ensureDictionaryLocals();
        const dict_index: usize = @intCast(span.start);
        if (dict_index >= self.dictionary_slots.len) {
            boxyLowerInvariant("boxy dictionary requirement index exceeded dictionary local table");
        }
        if (self.dictionary_slots[dict_index]) |existing| return .{ .local = existing, .fresh = false };
        const local = try self.addFrameLocal(.opaque_ptr);
        var offset: u32 = 0;
        while (offset < span.len) : (offset += 1) {
            const index: usize = @intCast(span.start + offset);
            self.dictionary_slots[index] = local;
        }
        return .{ .local = local, .fresh = true };
    }

    fn reserveDescriptorLocalForType(
        self: *ProcBodyBuilder,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?LIR.LocalId {
        return try self.reserveDescriptorLocalForRep(self.repForType(ty));
    }

    fn reserveRuntimeDescriptorLocalForType(
        self: *ProcBodyBuilder,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?LIR.LocalId {
        return try self.reserveRuntimeDescriptorLocalForRep(self.repForType(ty));
    }

    fn bindRuntimeDescriptorLocalForValueType(
        self: *ProcBodyBuilder,
        value: LIR.LocalId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?LIR.LocalId {
        if (self.parent.result.store.getLocal(value).boxy_desc) |value_desc| {
            if (value_desc.localOrNull()) |desc_local| {
                return desc_local;
            }
        }

        const layout_idx = self.parent.result.store.getLocal(value).layout_idx;
        const descriptor_sensitive_storage = self.parent.layoutIsBoxStorage(layout_idx);
        if (!descriptor_sensitive_storage) return null;

        const desc_local = try self.reserveRuntimeDescriptorLocalForType(ty) orelse
            try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(value, .{ .local = desc_local });
        return desc_local;
    }

    fn prependConstructedDescriptorRebindForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const desc = rep.descriptor orelse return next;
        const local = self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id) orelse return next;
        if (self.localIsReadOnlyDescriptorInput(local)) return next;
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) return next;
        if (self.descriptorBindingIsBoundForRep(rep_id)) return next;
        const materialization = try self.descriptorMaterializationForKnownRep(rep_id);
        if (materialization.captures.len == 0) return next;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = local,
            .desc = materialization.desc,
            .captures = materialization.captures,
            .next = next,
        } }, self.glueOrigin());
    }

    fn prependStaticDescriptorMaterializationsForSlots(
        self: *ProcBodyBuilder,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.prependStaticDescriptorMaterializationsForScopedSlots(null, next);
    }

    fn prependStaticDescriptorMaterializationsForSlotsWithSources(
        self: *ProcBodyBuilder,
        sources: *const StaticDescriptorSourceMap,
        context: *StaticDescInstantiationContext,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        if (self.descriptor_slots.len == 0) return continuation;

        var index = self.descriptor_slots.len;
        while (index > 0) {
            index -= 1;
            const local = self.descriptor_slots[index] orelse continue;
            const slot_rep = self.descriptor_slot_reps[index] orelse
                boxyLowerInvariant("boxy descriptor slot materialization had no representation binding");
            if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) continue;
            if (self.descriptorBindingIsBoundForRep(slot_rep)) continue;
            if (self.localIsReadOnlyDescriptorInput(local)) continue;
            // A template dictionary's adapter binds the building frame's type
            // variables; a representation naming them is described through
            // those bindings.
            if (self.template_frame_descriptors and try self.descriptorTemplateNeedsCapturesForKnownRep(slot_rep)) {
                const materialization = try self.descriptorMaterializationForKnownRep(slot_rep);
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                    .target = local,
                    .desc = materialization.desc,
                    .captures = materialization.captures,
                    .next = continuation,
                } }, self.glueOrigin());
                continue;
            }
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = local,
                .desc = try self.parent.staticDescRefForWorkerRepWithSourceMap(
                    slot_rep,
                    null,
                    sources,
                    context,
                ),
                .next = continuation,
            } }, self.glueOrigin());
        }
        return continuation;
    }

    fn prependStaticDescriptorMaterializationsForScopedSlots(
        self: *ProcBodyBuilder,
        outer: ?*const DescriptorBindingsSnapshot,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        if (self.descriptor_slots.len == 0) return continuation;

        // A slot's template may capture another slot, so the static
        // initializers, which capture nothing, run before all the others.
        var static_inits = std.ArrayList(struct { local: LIR.LocalId, desc: LIR.BoxyDescRef }).empty;
        defer static_inits.deinit(self.parent.allocator);
        var index = self.descriptor_slots.len;
        while (index > 0) {
            index -= 1;
            const local = self.descriptor_slots[index] orelse continue;
            const slot_rep = self.descriptor_slot_reps[index] orelse
                boxyLowerInvariant("boxy descriptor slot materialization had no representation binding");
            if (outer) |snapshot| {
                if (snapshot.slots[index] == local and snapshot.slot_reps[index] == slot_rep) continue;
            }
            // A write mark comes from a statement that may execute after code
            // that already reads this slot, so only evidence binds, which are
            // initialized before anything that observes them, skip the slot.
            if (self.descriptorBindingIsEvidenceBoundForRep(slot_rep)) continue;
            if (self.localIsReadOnlyDescriptorInput(local)) continue;
            // A slot a body statement writes is read by templates initialized
            // here before that write executes. When its representation's
            // descriptor is static, it is initialized here as well.
            const runtime_initialized = std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null;
            const materialization = if (runtime_initialized)
                try self.descriptorMaterializationForKnownRepExcludingLocal(slot_rep, local)
            else
                try self.descriptorMaterializationForKnownRep(slot_rep);
            if (materialization.captures.len == 0 and materialization.desc == .static) {
                try static_inits.append(self.parent.allocator, .{ .local = local, .desc = materialization.desc });
                continue;
            }
            if (runtime_initialized) continue;
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = local,
                .desc = materialization.desc,
                .captures = materialization.captures,
                .next = continuation,
            } }, self.glueOrigin());
        }
        var static_index = static_inits.items.len;
        while (static_index > 0) {
            static_index -= 1;
            const static_init = static_inits.items[static_index];
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = static_init.local,
                .desc = static_init.desc,
                .next = continuation,
            } }, self.glueOrigin());
        }
        return continuation;
    }

    fn markReadOnlyDescriptorInput(self: *ProcBodyBuilder, local: LIR.LocalId) Allocator.Error!void {
        try appendUniqueLocal(self.parent.allocator, &self.read_only_descriptor_inputs, local);
    }

    fn localIsReadOnlyDescriptorInput(self: *const ProcBodyBuilder, local: LIR.LocalId) bool {
        for (self.read_only_descriptor_inputs.items) |input| {
            if (input == local) return true;
        }
        return false;
    }

    fn localIsDescriptorSlot(self: *const ProcBodyBuilder, local: LIR.LocalId) bool {
        for (self.descriptor_slots) |maybe_local| {
            if (maybe_local == local) return true;
        }
        return false;
    }

    fn descriptorSourceRep(
        self: *const ProcBodyBuilder,
        source: ResultDescriptorSource,
        planned_rep: Plan.TypeRepId,
    ) Plan.TypeRepId {
        const desc = source.desc orelse return planned_rep;
        const local = desc.localOrNull() orelse return planned_rep;
        var source_rep: ?Plan.TypeRepId = null;
        for (self.descriptor_slots, self.descriptor_slot_reps) |maybe_slot, maybe_rep| {
            if (maybe_slot != local) continue;
            const rep = maybe_rep orelse
                boxyLowerInvariant("boxy descriptor slot had no representation binding");
            if (source_rep) |existing| {
                if (existing != rep) {
                    boxyLowerInvariant("boxy descriptor local had conflicting exact representation bindings");
                }
            } else {
                source_rep = rep;
            }
        }
        return source_rep orelse planned_rep;
    }

    fn reservePatternBindings(self: *ProcBodyBuilder, root: checked.CheckedPatternId) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(checked.CheckedPatternId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |pattern_id| {
            try self.ensureBinderLocals();
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            const children_start = pending.items.len;
            switch (pattern.data) {
                .assign => |binder| {
                    try self.reserveBinderLocal(binder, pattern.ty);
                    _ = try self.reserveDescriptorLocalForType(pattern.ty);
                },
                .as => |as| {
                    try self.reserveBinderLocal(as.binder, pattern.ty);
                    _ = try self.reserveDescriptorLocalForType(pattern.ty);
                    try pending.append(allocator, as.pattern);
                },
                .tuple => |items| try pending.appendSlice(allocator, items),
                .record_destructure => |destructs| {
                    for (destructs) |destruct| {
                        switch (destruct.kind) {
                            .required,
                            .sub_pattern,
                            .rest,
                            => |child| try pending.append(allocator, child),
                        }
                    }
                },
                .nominal => |nominal| try pending.append(allocator, nominal.backing_pattern),
                .applied_tag => |tag| try pending.appendSlice(allocator, tag.args),
                .list => |list| {
                    try pending.appendSlice(allocator, list.patterns);
                    if (list.rest) |rest| {
                        if (rest.pattern) |rest_pattern| try pending.append(allocator, rest_pattern);
                    }
                },
                .str_interpolation => |str| {
                    for (str.steps) |step| {
                        if (step.capture) |capture| try pending.append(allocator, capture);
                    }
                },
                .underscore,
                .numeral_literal,
                .str_literal,
                => {},
                .runtime_error,
                .pending,
                => boxyLowerInvariant("refutable or pending checked pattern reached boxy irrefutable binder reservation"),
            }
            std.mem.reverse(checked.CheckedPatternId, pending.items[children_start..]);
        }
    }

    fn requireIrrefutableTagPattern(
        self: *ProcBodyBuilder,
        ty: checked.CheckedTypeId,
        name: names.TagNameId,
        args: []const checked.CheckedPatternId,
    ) Allocator.Error!void {
        var current = self.repForType(ty);
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => boxyLowerInvariant("irrefutable tag pattern had an opaque nominal representation"),
                },
                .tag_union => {
                    const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                    if (variants.len != 1) {
                        boxyLowerInvariant("refutable tag pattern reached boxy irrefutable binder lowering");
                    }
                    const variant = self.tagVariant(rep, name);
                    if (variant.index != 0) {
                        boxyLowerInvariant("single-variant tag pattern had a nonzero variant index");
                    }
                    return try self.validateTagPatternPayloads(variant.name, variant.payloads, args);
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("irrefutable tag pattern did not have a tag-union representation"),
            }
        }
    }

    fn reserveMatchPatternBindings(self: *ProcBodyBuilder, root: checked.CheckedPatternId) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(checked.CheckedPatternId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |pattern_id| {
            try self.ensureBinderLocals();
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            const children_start = pending.items.len;
            switch (pattern.data) {
                .assign => |binder| {
                    try self.reserveMatchBinderLocal(binder, pattern.ty);
                },
                .as => |as| {
                    try self.reserveMatchBinderLocal(as.binder, pattern.ty);
                    try pending.append(allocator, as.pattern);
                },
                .applied_tag => |tag| try pending.appendSlice(allocator, tag.args),
                .tuple => |items| try pending.appendSlice(allocator, items),
                .record_destructure => |destructs| {
                    for (destructs) |destruct| {
                        switch (destruct.kind) {
                            .required,
                            .sub_pattern,
                            .rest,
                            => |child| try pending.append(allocator, child),
                        }
                    }
                },
                .nominal => |nominal| try pending.append(allocator, nominal.backing_pattern),
                .list => |list| {
                    try pending.appendSlice(allocator, list.patterns);
                    if (list.rest) |rest| {
                        if (rest.pattern) |rest_pattern| try pending.append(allocator, rest_pattern);
                    }
                },
                .str_interpolation => |str| {
                    for (str.steps) |step| {
                        if (step.capture) |capture| try pending.append(allocator, capture);
                    }
                },
                .underscore,
                .numeral_literal,
                .str_literal,
                => {},
                .runtime_error,
                .pending,
                => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match binder reservation"),
            }
            std.mem.reverse(checked.CheckedPatternId, pending.items[children_start..]);
        }
    }

    /// Reserve, in pre-order, the binders `root` binds from a source of
    /// representation `root_source_rep`.
    fn reserveMatchPatternBindingsFromRep(
        self: *ProcBodyBuilder,
        root: checked.CheckedPatternId,
        root_source_rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        const Pending = struct { pattern_id: checked.CheckedPatternId, source_rep: Plan.TypeRepId };
        var pending: std.ArrayList(Pending) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, .{ .pattern_id = root, .source_rep = root_source_rep });
        while (pending.pop()) |item| {
            const pattern_id = item.pattern_id;
            const source_rep = item.source_rep;
            try self.ensureBinderLocals();
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            const pattern_rep = self.repForType(pattern.ty);
            if (pattern_rep == source_rep or
                self.workerRuntimeLayoutForRep(pattern_rep).layoutIdx() == self.workerRuntimeLayoutForRep(source_rep).layoutIdx())
            {
                try self.reserveMatchPatternBindings(pattern_id);
                continue;
            }

            const children_start = pending.items.len;
            switch (pattern.data) {
                .assign => |binder| try self.reserveMatchBinderLocalForRep(binder, source_rep),
                .as => |as| {
                    try self.reserveMatchBinderLocalForRep(as.binder, source_rep);
                    try pending.append(allocator, .{ .pattern_id = as.pattern, .source_rep = source_rep });
                },
                .applied_tag => |tag| {
                    const tag_rep = self.tagPatternRepForBoundary(source_rep) orelse
                        boxyLowerInvariant("boxy tag pattern binder source had no tag representation");
                    const rep = self.parent.plan.representations.items[@backingInt(tag_rep)];
                    const payloads = switch (rep.kind) {
                        .dynamic => try self.dynamicTagPayloadsForName(tag_rep, tag.name),
                        .tag_union => self.parent.plan.childSlice(self.tagVariant(rep, tag.name).payloads),
                        .bool_tag_union => &.{},
                        .in_progress, .primitive, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("boxy tag pattern binder source was not a tag representation"),
                    };
                    if (payloads.len != tag.args.len) {
                        boxyLowerInvariant("boxy tag pattern binder payload count disagreed with its source representation");
                    }
                    for (tag.args, payloads) |arg, payload| {
                        try pending.append(allocator, .{ .pattern_id = arg, .source_rep = payload.rep });
                    }
                },
                .underscore,
                .numeral_literal,
                .str_literal,
                => {},
                .pending, .nominal, .record_destructure, .list, .tuple, .str_interpolation, .runtime_error => try self.reserveMatchPatternBindings(pattern_id),
            }
            std.mem.reverse(Pending, pending.items[children_start..]);
        }
    }

    fn reserveMatchPatternDescriptors(
        self: *ProcBodyBuilder,
        root: checked.CheckedPatternId,
        remaps: []const checked.CheckedAlternativeBinderRemap,
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(checked.CheckedPatternId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |pattern_id| {
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            const children_start = pending.items.len;
            switch (pattern.data) {
                .assign => |binder| {
                    const representative = self.matchBinderRepresentative(binder, remaps);
                    _ = try self.bindRuntimeDescriptorLocalForValueType(
                        self.localForBinder(representative),
                        self.binderType(representative),
                    );
                },
                .as => |as| {
                    const representative = self.matchBinderRepresentative(as.binder, remaps);
                    _ = try self.bindRuntimeDescriptorLocalForValueType(
                        self.localForBinder(representative),
                        self.binderType(representative),
                    );
                    try pending.append(allocator, as.pattern);
                },
                .applied_tag => |tag| try pending.appendSlice(allocator, tag.args),
                .tuple => |items| try pending.appendSlice(allocator, items),
                .record_destructure => |destructs| {
                    for (destructs) |destruct| {
                        switch (destruct.kind) {
                            .required,
                            .sub_pattern,
                            .rest,
                            => |child| try pending.append(allocator, child),
                        }
                    }
                },
                .nominal => |nominal| try pending.append(allocator, nominal.backing_pattern),
                .list => |list| {
                    try pending.appendSlice(allocator, list.patterns);
                    if (list.rest) |rest| {
                        if (rest.pattern) |rest_pattern| try pending.append(allocator, rest_pattern);
                    }
                },
                .str_interpolation => |str| {
                    for (str.steps) |step| {
                        if (step.capture) |capture| try pending.append(allocator, capture);
                    }
                },
                .underscore,
                .numeral_literal,
                .str_literal,
                => {},
                .runtime_error,
                .pending,
                => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match descriptor reservation"),
            }
            std.mem.reverse(checked.CheckedPatternId, pending.items[children_start..]);
        }
    }

    fn patternIsIgnored(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) bool {
        return switch (self.module.checked_bodies.pattern(pattern_id).data) {
            .underscore => true,
            .pending, .assign, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => false,
        };
    }

    /// Whether some value fails to match `root`. Which subpatterns are
    /// reached does not depend on visiting order.
    fn patternCanMiss(self: *ProcBodyBuilder, root: checked.CheckedPatternId) Allocator.Error!bool {
        return self.patternFromRepCanMiss(root, self.repForType(self.module.checked_bodies.pattern(root).ty));
    }

    /// Miss analysis uses the same producer-owned constructor universe as
    /// pattern lowering, even when a contextual child has a selected-only row.
    fn patternFromRepCanMiss(
        self: *ProcBodyBuilder,
        root: checked.CheckedPatternId,
        root_source_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        const allocator = self.parent.allocator;
        const Pending = struct { pattern: checked.CheckedPatternId, source_rep: Plan.TypeRepId };
        var pending: std.ArrayList(Pending) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, .{ .pattern = root, .source_rep = root_source_rep });
        while (pending.pop()) |item| {
            const pattern = self.module.checked_bodies.pattern(item.pattern);
            switch (pattern.data) {
                .assign,
                .underscore,
                => {},
                .as => |as| try pending.append(allocator, .{ .pattern = as.pattern, .source_rep = item.source_rep }),
                .tuple => |items| for (items) |child| {
                    try pending.append(allocator, .{ .pattern = child, .source_rep = self.repForType(self.module.checked_bodies.pattern(child).ty) });
                },
                .record_destructure => |destructs| for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child| child,
                    };
                    try pending.append(allocator, .{ .pattern = child, .source_rep = self.repForType(self.module.checked_bodies.pattern(child).ty) });
                },
                .nominal => |nominal| {
                    const nominal_rep = self.repForType(pattern.ty);
                    const backing = self.module.checked_bodies.pattern(nominal.backing_pattern);
                    try pending.append(allocator, .{
                        .pattern = nominal.backing_pattern,
                        .source_rep = self.nominalPatternSourceRep(nominal_rep) orelse self.repForType(backing.ty),
                    });
                },
                .applied_tag => |tag| {
                    const tag_rep = self.tagPatternRepForBoundary(item.source_rep) orelse {
                        const source_identity = self.descriptorStorageRep(item.source_rep);
                        if (self.parent.plan.representations.items[@backingInt(source_identity)].kind != .dynamic) {
                            boxyLowerInvariant("boxy tag pattern producer had no tag representation during miss analysis");
                        }
                        return true;
                    };
                    const rep = self.parent.plan.representations.items[@backingInt(tag_rep)];
                    switch (rep.kind) {
                        .bool_tag_union => {
                            if (tag.args.len != 0) {
                                boxyLowerInvariant("builtin Bool match pattern carried a payload during miss analysis");
                            }
                            _ = self.boolVariantIndex(tag.name);
                            return true;
                        },
                        .tag_union => {
                            const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                            const payloads = self.parent.plan.childSlice(self.tagVariant(rep, tag.name).payloads);
                            if (payloads.len != tag.args.len) {
                                boxyLowerInvariant("tag match pattern payload count disagreed during miss analysis");
                            }
                            if (variants.len > 1) return true;
                            for (tag.args, payloads) |arg, payload| {
                                try pending.append(allocator, .{ .pattern = arg, .source_rep = payload.rep });
                            }
                        },
                        .dynamic => {
                            if ((try self.dynamicTagPayloadsForName(tag_rep, tag.name)).len != tag.args.len) {
                                boxyLowerInvariant("dynamic tag match pattern payload count disagreed during miss analysis");
                            }
                            return true;
                        },
                        .in_progress, .primitive, .erased_callable, .alias, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("tag match producer representation was not a tag union during miss analysis"),
                    }
                },
                .list,
                .str_interpolation,
                .numeral_literal,
                .str_literal,
                => return true,
                .runtime_error,
                .pending,
                => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match miss analysis"),
            }
        }
        return false;
    }

    fn reserveReassignPatternBindings(self: *ProcBodyBuilder, root: checked.CheckedPatternId) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var pending: std.ArrayList(checked.CheckedPatternId) = .empty;
        defer pending.deinit(allocator);
        try pending.append(allocator, root);
        while (pending.pop()) |pattern_id| {
            try self.ensureBinderLocals();
            const pattern = self.module.checked_bodies.pattern(pattern_id);
            const children_start = pending.items.len;
            switch (pattern.data) {
                .assign => |binder| {
                    try self.reserveBinderLocalIfFresh(binder, pattern.ty);
                    _ = try self.reserveDescriptorLocalForType(pattern.ty);
                },
                .as => |as| {
                    try self.reserveBinderLocalIfFresh(as.binder, pattern.ty);
                    _ = try self.reserveDescriptorLocalForType(pattern.ty);
                    try pending.append(allocator, as.pattern);
                },
                .tuple => |items| try pending.appendSlice(allocator, items),
                .record_destructure => |destructs| {
                    for (destructs) |destruct| {
                        switch (destruct.kind) {
                            .required,
                            .sub_pattern,
                            .rest,
                            => |child| try pending.append(allocator, child),
                        }
                    }
                },
                .nominal => |nominal| try pending.append(allocator, nominal.backing_pattern),
                .list => |list| {
                    if (list.patterns.len != 0) {
                        boxyLowerInvariant("refutable list pattern reached boxy reassign binder reservation");
                    }
                    if (list.rest) |rest| {
                        if (rest.pattern) |rest_pattern| try pending.append(allocator, rest_pattern);
                    }
                },
                .underscore,
                .numeral_literal,
                .str_literal,
                .str_interpolation,
                => {},
                .applied_tag,
                .runtime_error,
                .pending,
                => boxyLowerInvariant("refutable or pending checked pattern reached boxy reassign binder reservation"),
            }
            std.mem.reverse(checked.CheckedPatternId, pending.items[children_start..]);
        }
    }

    fn bindPatternToLocal(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId, local: LIR.LocalId) void {
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| self.bindLocal(binder, local),
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => boxyLowerInvariant("boxy pattern required pattern lowering before it was emitted"),
        }
    }

    fn reserveBinderLocal(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        const rep = self.repForType(ty);
        const local = if (self.parent.layoutIsBoxStorage(self.workerRuntimeLayoutForRep(rep).layoutIdx()))
            try self.addFrameLocalForRepWithFreshDescriptor(rep)
        else
            try self.addFrameLocalForRep(rep);
        self.bindLocal(binder, local);
    }

    fn reserveMatchBinderLocal(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        return try self.reserveMatchBinderLocalForRep(binder, self.repForType(ty));
    }

    fn reserveMatchBinderLocalForRep(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        const local = try self.addFrameLocalForRepWithFreshDescriptor(rep);
        self.bindLocalForRep(binder, local, rep);
    }

    fn reserveBinderLocalIfFresh(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        if (self.binderLocalOrNull(binder) != null) return;
        try self.reserveBinderLocal(binder, ty);
    }

    fn bindLocal(self: *ProcBodyBuilder, binder: checked.PatternBinderId, local: LIR.LocalId) void {
        const index = @backingInt(binder);
        if (index >= self.binder_locals.len) boxyLowerInvariant("boxy pattern referenced a missing pattern binder");
        if (self.binder_locals[index] != null) boxyLowerInvariant("boxy pattern bound the same pattern binder more than once");
        self.binder_locals[index] = local;
    }

    fn bindLocalForRep(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        local: LIR.LocalId,
        rep: Plan.TypeRepId,
    ) void {
        self.bindLocal(binder, local);
        const index = @backingInt(binder);
        if (index >= self.binder_reps.len) boxyLowerInvariant("boxy pattern referenced a missing binder representation");
        self.binder_reps[index] = rep;
    }

    fn binderLocalOrNull(self: *const ProcBodyBuilder, binder: checked.PatternBinderId) ?LIR.LocalId {
        const index = @backingInt(binder);
        if (index >= self.binder_locals.len) boxyLowerInvariant("boxy pattern referenced a missing pattern binder");
        return self.binder_locals[index];
    }

    fn binderStorageRep(self: *ProcBodyBuilder, binder: checked.PatternBinderId) Plan.TypeRepId {
        const index = @backingInt(binder);
        if (index >= self.binder_reps.len) boxyLowerInvariant("boxy binder representation lookup referenced a missing binder");
        return self.binder_reps[index] orelse self.repForType(self.binderType(binder));
    }

    fn binderIsReassigned(
        _: *const ProcBodyBuilder,
        reassigned_binders: []const checked.PatternBinderId,
        binder: checked.PatternBinderId,
    ) bool {
        for (reassigned_binders) |reassigned| {
            if (reassigned == binder) return true;
        }
        return false;
    }

    fn localForBinder(self: *ProcBodyBuilder, binder: checked.PatternBinderId) LIR.LocalId {
        const binder_index = @backingInt(binder);
        if (binder_index >= self.binder_locals.len) boxyLowerInvariant("boxy local lookup referenced a missing binder local");
        return self.binder_locals[binder_index] orelse
            boxyLowerInvariant("boxy local lookup referenced a binder before it was bound");
    }

    fn localForPattern(self: *ProcBodyBuilder, pattern: checked.CheckedPatternId) LIR.LocalId {
        const pattern_index = @backingInt(pattern);
        if (pattern_index >= self.module.checked_bodies.pattern_binder_by_pattern.len) {
            boxyLowerInvariant("boxy local lookup referenced a pattern without binder metadata");
        }
        const binder = self.module.checked_bodies.pattern_binder_by_pattern[pattern_index] orelse
            boxyLowerInvariant("boxy local lookup referenced a non-binding pattern");
        return self.localForBinder(binder);
    }

    fn resolvedValueRecord(self: *const ProcBodyBuilder, ref_id: checked.ResolvedValueRefId) checked.ResolvedValueRefRecord {
        return resolvedValueRecordInModule(self.module, ref_id);
    }

    fn resolvedValueRecordInModule(module: ProcedureModuleView, ref_id: checked.ResolvedValueRefId) checked.ResolvedValueRefRecord {
        const raw = @backingInt(ref_id);
        if (raw >= module.resolved_value_refs.records.len) {
            boxyLowerInvariant("checked lookup referenced a missing resolved value");
        }
        return module.resolved_value_refs.records[raw];
    }

    fn workerReturnLayout(self: *const ProcBodyBuilder) @import("layout").Idx {
        if (self.worker_layout.ret) |ret| return ret.layoutIdx();
        return self.worker_layout.value.layoutIdx();
    }

    fn repForType(self: *const ProcBodyBuilder, ty: checked.CheckedTypeId) Plan.TypeRepId {
        var contextual_rep: ?Plan.TypeRepId = null;
        for (self.lambda_arg_patterns, self.lambda_arg_worker_reps) |pattern_id, worker_rep| {
            if (self.module.checked_bodies.pattern(pattern_id).ty != ty) continue;
            if (contextual_rep) |existing| {
                if (existing != worker_rep) {
                    boxyLowerInvariant("one checked lambda parameter type mapped to conflicting worker representations");
                }
            } else {
                contextual_rep = worker_rep;
            }
        }
        if (contextual_rep) |rep| return rep;
        return self.repForModuleType(self.module, ty);
    }

    fn repForModuleType(self: *const ProcBodyBuilder, module: ProcedureModuleView, ty: checked.CheckedTypeId) Plan.TypeRepId {
        return self.parent.plan.repForSourceType(.{ .module = module.key, .ty = ty }) orelse {
            boxyLowerInvariant("checked body referenced a type missing from the boxy representation plan");
        };
    }

    fn repForTypeRef(self: *const ProcBodyBuilder, type_ref: Plan.CheckedTypeIdentity) Plan.TypeRepId {
        return self.parent.plan.repForSourceType(type_ref) orelse
            boxyLowerInvariant("checked body referenced a type ref missing from the boxy representation plan");
    }

    fn workerRuntimeLayoutForType(self: *const ProcBodyBuilder, ty: checked.CheckedTypeId) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@backingInt(self.repForType(ty))].worker;
    }

    fn workerRuntimeLayoutForTypeRef(self: *const ProcBodyBuilder, type_ref: Plan.CheckedTypeIdentity) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@backingInt(self.repForTypeRef(type_ref))].worker;
    }

    fn workerRuntimeLayoutForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@backingInt(rep_id)].worker;
    }

    fn localUsesWorkerLayoutForRep(self: *const ProcBodyBuilder, local: LIR.LocalId, rep_id: Plan.TypeRepId) bool {
        return self.parent.result.store.getLocal(local).layout_idx == self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
    }

    fn tagPayloadStorageLayoutForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) layout.Idx {
        const desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(rep_id) orelse
            return self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const rep_layout = self.parent.layout_plan.rep_layouts[@backingInt(desc_rep)];
        return rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
    }

    fn aggregateFieldLayout(
        self: *const ProcBodyBuilder,
        aggregate_layout: layout.Idx,
        field_index: usize,
    ) Allocator.Error!layout.Idx {
        if (field_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("aggregate field index exceeded LIR layout field range");
        }
        const aggregate = self.parent.result.layouts.getLayout(aggregate_layout);
        return switch (aggregate.tag) {
            .struct_ => self.parent.result.layouts.getStructFieldLayoutByOriginalIndex(
                aggregate.getStruct().idx,
                @intCast(field_index),
            ),
            .zst => .zst,
            .scalar, .box, .box_of_zst, .erased_box, .list, .list_of_zst, .closure, .erased_callable, .tag_union, .ptr => boxyLowerInvariant("aggregate field layout requested for non-struct layout"),
        };
    }

    fn hostRuntimeLayoutForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Layouts.RuntimeLayout {
        return .{ .concrete = self.parent.layout_plan.rep_layouts[@backingInt(rep_id)].worker.layoutIdx() };
    }

    fn descriptorStorageRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => {
                        if (rep.declared_fields.len != 0 or
                            rep.nominal_backing_arg_substitutions.len != 0) return current;
                        current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep;
                    },
                    .opaque_nominal, .builtin_other => return current,
                },
                .box => {
                    const child = self.repQuery().requiredSingleChild(current, .box_payload).rep;
                    if (self.workerRuntimeLayoutForRep(current).layoutIdx() != self.workerRuntimeLayoutForRep(child).layoutIdx()) return current;
                    current = child;
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return current,
            }
        }
    }

    fn repContainsDynamicStorage(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact = self.parent.plan.representations.items[@backingInt(rep_id)];
        const identity = self.parent.plan.representations.items[@backingInt(identity_rep)];
        return exact.contains_dynamic or identity.contains_dynamic;
    }

    fn dictionaryIdentityRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        // A transparent nominal owns the method namespace its dictionary slots
        // dispatch through, so only aliases are unwrapped; the nominal identity
        // is preserved for method resolution.
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            if (rep.kind != .alias) return current;
            current = self.repQuery().requiredSingleChild(current, .alias_backing).rep;
        }
    }

    fn tagVariantRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        return self.tagRepForBoundary(rep_id, false);
    }

    fn tagPatternRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        return self.tagRepForBoundary(rep_id, true);
    }

    fn tagRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId, include_bool: bool) ?Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tag_union, .dynamic => {
                    if (rep.tag_variants.len == 0) return null;
                    return current;
                },
                .bool_tag_union => return if (include_bool) current else null,
                .in_progress, .primitive, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return null,
            }
        }
    }

    fn listRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .list => return current,
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn tupleRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tuple => return current,
                .dynamic => {
                    var has_element = false;
                    for (self.parent.plan.childSlice(rep.children)) |child| {
                        switch (child.role) {
                            .tuple_elem => has_element = true,
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => return null,
                        }
                    }
                    return if (has_element) current else null;
                },
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn declaredAggregateRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            if (rep.declared_fields.len != 0) return current;
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn functionReturnRepForType(self: *const ProcBodyBuilder, ty: checked.CheckedTypeId) Plan.TypeRepId {
        return self.functionReturnRepForRep(self.repForType(ty));
    }

    const FunctionChildren = struct {
        rep: Plan.TypeRepId,
        args_start: u32,
        arg_count: u32,
        ret: Plan.TypeRepId,
    };

    fn functionChildrenForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?FunctionChildren {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => return null,
                },
                .erased_callable => {
                    const children = self.parent.plan.childSlice(rep.children);
                    var args_start: ?u32 = null;
                    var arg_count: u32 = 0;
                    var ret: ?Plan.TypeRepId = null;
                    for (children, 0..) |child, i| {
                        switch (child.role) {
                            .function_arg => {
                                if (args_start == null) args_start = @intCast(i);
                                arg_count += 1;
                            },
                            .function_ret => ret = child.rep,
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .tag_payload, .tag_ext, .list_elem, .box_payload => {},
                        }
                    }
                    return .{
                        .rep = current,
                        .args_start = args_start orelse 0,
                        .arg_count = arg_count,
                        .ret = ret orelse boxyLowerInvariant("function representation had no return child"),
                    };
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    /// Each hidden descriptor captured by a callable value comes from the
    /// planned hidden descriptor argument of this use: the caller
    /// representation the use's substitution names for that worker
    /// descriptor.
    fn erasedCaptureDescriptorSourcesForFunctionUse(
        self: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        captures: []const Plan.ErasedCapture,
        planned_hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
    ) Allocator.Error![]ErasedCaptureDescriptorSource {
        const result = try self.parent.allocator.alloc(ErasedCaptureDescriptorSource, captures.len);
        errdefer self.parent.allocator.free(result);
        for (captures, result) |capture, *source| {
            source.* = .{ .rep = capture.rep };
        }

        const worker = self.parent.plan.workers.items[@backingInt(worker_id)];
        const params = self.parent.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        if (params.len == 0) return result;
        if (planned_hidden_args.len != params.len) {
            boxyLowerInvariant("boxy callable value use had no planned hidden descriptor arguments");
        }
        for (captures, result) |capture, *source| {
            if (capture.kind != .hidden_desc) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("boxy hidden descriptor erased capture had no descriptor requirement");
            var found: ?Plan.TypeRepId = null;
            for (planned_hidden_args) |arg| {
                if (arg.worker_desc != desc) continue;
                if (found != null and found.? != arg.rep) {
                    boxyLowerInvariant("boxy callable use planned conflicting descriptor capture sources");
                }
                found = arg.rep;
            }
            source.rep = found orelse
                boxyLowerInvariant("boxy callable use did not plan a descriptor capture source");
        }
        return result;
    }

    /// The value-side representation of each dictionary capture that the use's
    /// planned dictionary arguments do not supply.
    fn erasedCaptureDictionaryRepsForFunctionUse(
        self: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        value_function: FunctionChildren,
        captures: []const Plan.ErasedCapture,
        planned_dict_count: usize,
    ) Allocator.Error![]Plan.TypeRepId {
        const result = try self.parent.allocator.alloc(Plan.TypeRepId, captures.len);
        errdefer self.parent.allocator.free(result);
        for (captures, result) |capture, *rep| {
            rep.* = capture.rep;
        }

        const worker = self.parent.plan.workers.items[@backingInt(worker_id)];
        const params = self.parent.plan.hiddenDictionaryParamSlice(worker.hidden_dicts);
        if (params.len == 0 or planned_dict_count >= params.len) return result;

        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy erased callable with hidden dictionaries was not a function worker");
        if (worker_function.arg_count != value_function.arg_count) {
            boxyLowerInvariant("boxy erased callable dictionary mapping saw mismatched function arity");
        }

        var mapped = collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId).init(self.parent.allocator);
        defer mapped.deinit();
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();

        const worker_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(worker_function.rep)].children);
        const value_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(value_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
        const value_args = value_children[value_function.args_start..][0..value_function.arg_count];
        for (worker_args, value_args) |worker_child, value_child| {
            try self.collectErasedCaptureDictionaryReps(worker_child.rep, value_child.rep, &mapped, &seen);
        }
        try self.collectErasedCaptureDictionaryReps(worker_function.ret, value_function.ret, &mapped, &seen);

        for (captures, result) |capture, *rep| {
            if (capture.kind != .hidden_dict) continue;
            if (capture.body_dictionary) continue;
            rep.* = mapped.get(capture.rep) orelse
                boxyLowerInvariant("boxy erased callable dictionary mapping did not cover a hidden dictionary capture");
        }
        return result;
    }

    /// Map, in pre-order, each worker representation carrying dictionaries
    /// to the value representation at its position.
    fn collectErasedCaptureDictionaryReps(
        self: *ProcBodyBuilder,
        root_worker: Plan.TypeRepId,
        root_value: Plan.TypeRepId,
        mapped: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
        seen_rep_pairs: *std.AutoHashMap(u64, void),
    ) Allocator.Error!void {
        const allocator = self.parent.allocator;
        var pairs: std.ArrayList([2]Plan.TypeRepId) = .empty;
        defer pairs.deinit(allocator);
        try pairs.append(allocator, .{ root_worker, root_value });
        while (pairs.pop()) |pair| {
            const worker_rep_id = pair[0];
            const effective_value_rep_id = pair[1];
            const pair_key = (@as(u64, @backingInt(worker_rep_id)) << 32) |
                @as(u64, @backingInt(effective_value_rep_id));
            const entry = try seen_rep_pairs.getOrPut(pair_key);
            if (entry.found_existing) continue;

            const worker_rep = self.parent.plan.representations.items[@backingInt(worker_rep_id)];
            const value_rep = self.parent.plan.representations.items[@backingInt(effective_value_rep_id)];

            if (worker_rep.dictionaries.len != 0) {
                const mapped_rep = self.repQuery().dictionaryArgumentIdentityRep(effective_value_rep_id);
                const put = try mapped.getOrPut(worker_rep_id);
                if (put.found_existing and put.value_ptr.* != mapped_rep) {
                    boxyLowerInvariant("boxy erased callable dictionary mapping assigned one worker rep to two reps");
                }
                put.value_ptr.* = mapped_rep;
            }

            if (worker_rep.children.len == 0) continue;

            // Children align with the structure the call's value stands for.
            var wrapper_bindings: Plan.CallWrapperBindings = .{};
            defer wrapper_bindings.deinit(self.parent.allocator);
            const children_start = pairs.items.len;
            defer std.mem.reverse([2]Plan.TypeRepId, pairs.items[children_start..]);
            const structure_call_rep_id = try self.repQuery().bindCallWrappedStructure(self.parent.allocator, worker_rep_id, effective_value_rep_id, &wrapper_bindings);
            const through_wrapper = structure_call_rep_id != effective_value_rep_id;
            const structure_rep = self.parent.plan.representations.items[@backingInt(structure_call_rep_id)];

            if (structure_rep.kind == .empty_tag_union) {
                for (self.parent.plan.childSlice(worker_rep.children)) |worker_child| {
                    if (self.parent.plan.childIsSharedBackingTemplate(worker_rep_id, worker_child)) continue;
                    if (!try self.repQuery().repSubtreeHasDictionary(worker_child.rep)) continue;
                    try pairs.append(allocator, .{ worker_child.rep, effective_value_rep_id });
                }
                continue;
            }

            const worker_children = self.parent.plan.childSlice(worker_rep.children);
            const value_children = self.parent.plan.childSlice(structure_rep.children);
            for (worker_children) |worker_child| {
                if (self.parent.plan.childIsSharedBackingTemplate(worker_rep_id, worker_child)) continue;
                if (!try self.repQuery().repSubtreeHasDictionary(worker_child.rep)) continue;
                if (self.namedQuery().rowInstantiationTarget(worker_rep_id, structure_call_rep_id, worker_child)) |structure_row_target| {
                    const row_target = if (structure_row_target == structure_call_rep_id)
                        effective_value_rep_id
                    else
                        Plan.structureChildCallRep(&wrapper_bindings, through_wrapper, structure_row_target);
                    try pairs.append(allocator, .{ worker_child.rep, row_target });
                    continue;
                }
                if (self.namedQuery().findMatchingChildByRole(value_children, worker_child)) |value_child| {
                    try pairs.append(allocator, .{ worker_child.rep, Plan.structureChildCallRep(&wrapper_bindings, through_wrapper, value_child.rep) });
                    continue;
                }
                if (self.repQuery().structuralWrapperBackingRep(effective_value_rep_id)) |value_backing| {
                    const backing_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@backingInt(value_backing)].children);
                    if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |value_child| {
                        try pairs.append(allocator, .{ worker_child.rep, value_child.rep });
                        continue;
                    }
                }
                if (try self.repQuery().workerChildCanMatchUnwrappedCallRepForDictionaries(worker_rep_id, worker_child)) {
                    try pairs.append(allocator, .{ worker_child.rep, effective_value_rep_id });
                    continue;
                }
                if (worker_child.role == .tag_ext and value_children.len == 0 and value_rep.dictionaries.len != 0) {
                    try pairs.append(allocator, .{ worker_child.rep, effective_value_rep_id });
                    continue;
                }
                boxyLowerInvariant("boxy erased callable dictionary mapping saw mismatched child roles");
            }
        }
    }

    fn functionReturnRepForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => boxyLowerInvariant("opaque or unsupported nominal reached function return layout lowering"),
                },
                .erased_callable => {
                    for (self.parent.plan.childSlice(rep.children)) |child| {
                        switch (child.role) {
                            .function_ret => return child.rep,
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .tag_payload, .tag_ext, .list_elem, .box_payload => {},
                        }
                    }
                    boxyLowerInvariant("function representation had no return child");
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("list_map_can_reuse transform argument is not a function"),
            }
        }
    }

    fn requireEmptyRecordExtension(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) void {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        if (rep.kind != .empty_record) {
            boxyLowerInvariant("open record representation reached boxy body lowering without an explicit closed row");
        }
    }

    fn recordEqualityFieldCount(children: []const Plan.RepChild) u32 {
        var count: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => count += 1,
                .record_ext => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record equality representation had a non-record child role"),
            }
        }
        if (count > std.math.maxInt(u32)) {
            boxyLowerInvariant("record equality field count exceeded LIR field index range");
        }
        return @intCast(count);
    }

    const RecordFieldAccessInfo = struct {
        record_rep: Plan.TypeRepId,
        field_idx: u32,
        field_rep: Plan.TypeRepId,
        field_kind: checked.CheckedFieldKind.Tag,
    };

    const MatchedRecordField = struct {
        index: u32,
        rep: Plan.TypeRepId,
    };

    fn recordRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .record,
                => return current,
                .dynamic => return if (self.repHasRecordFieldChildrenForBoundary(rep)) current else null,
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent,
                    .builtin_other,
                    => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn recordFieldCount(self: *const ProcBodyBuilder, children: []const Plan.RepChild) usize {
        var count: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => count += 1,
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record boundary representation had a non-record child role"),
            }
        }
        return count;
    }

    fn findRecordFieldByLabel(
        self: *const ProcBodyBuilder,
        record_rep_id: Plan.TypeRepId,
        target_view: ProcedureModuleView,
        target_label: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
    ) ?MatchedRecordField {
        const rep = self.parent.plan.representations.items[@backingInt(record_rep_id)];
        var index: u32 = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => |source_label| {
                    if (Plan.recordFieldNameMatches(viewNames(procedureModuleById(self.parent.modules, child.source_type.module)), source_label, viewNames(target_view), target_label)) {
                        return .{
                            .index = index,
                            .rep = child.rep,
                        };
                    }
                    index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record boundary source had a non-record child role"),
            }
        }
        return null;
    }

    fn repHasRecordFieldChildrenForBoundary(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
    ) bool {
        var has_field = false;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => has_field = true,
                .record_ext => {
                    const ext = self.parent.plan.representations.items[@backingInt(child.rep)];
                    if (ext.kind != .empty_record) return false;
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => return false,
            }
        }
        return has_field;
    }

    fn recordFieldAccessInfo(
        self: *const ProcBodyBuilder,
        receiver_rep_id: Plan.TypeRepId,
        access_view: ProcedureModuleView,
        field_name: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
    ) RecordFieldAccessInfo {
        // Aliases and transparent nominals read their backing's fields.
        var record_rep_id = receiver_rep_id;
        const rep = while (true) {
            const current = self.parent.plan.representations.items[@backingInt(record_rep_id)];
            switch (current.kind) {
                .record,
                => break current,
                .dynamic => {
                    if (!self.repHasRecordFieldChildren(current)) {
                        boxyLowerInvariant("record field access receiver did not have known boxy record fields");
                    }
                    break current;
                },
                .alias => record_rep_id = self.repQuery().requiredSingleChild(record_rep_id, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent,
                    .builtin_other,
                    => record_rep_id = self.repQuery().requiredSingleChild(record_rep_id, .nominal_backing).rep,
                    .opaque_nominal => boxyLowerInvariant("opaque nominal record field access reached boxy lowering"),
                },
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => {
                    boxyLowerInvariant("record field access receiver did not have a boxy record representation");
                },
            }
        };

        var index: u32 = 0;
        const source_view = procedureModuleById(self.parent.modules, rep.source_type.module);
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => |label| {
                    if (Plan.recordFieldNameMatches(viewNames(source_view), label, viewNames(access_view), field_name)) {
                        return .{
                            .record_rep = record_rep_id,
                            .field_idx = index,
                            .field_rep = child.rep,
                            .field_kind = child.record_field_kind.tag,
                        };
                    }
                    index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record field access representation had a non-record child role"),
            }
        }
        boxyLowerInvariant("record field access referenced a field outside its checked type representation");
    }

    /// Position of record field `field_idx` in its record descriptor's
    /// nested descriptors: its payload field index.
    fn recordFieldNestedDescriptorIndex(
        self: *const ProcBodyBuilder,
        record_rep_id: Plan.TypeRepId,
        field_idx: u32,
    ) u32 {
        const rep = self.parent.plan.representations.items[@backingInt(record_rep_id)];
        if (rep.declared_fields.len != 0) {
            for (self.parent.plan.declaredFieldSlice(rep.declared_fields)) |field| {
                if (field.index == field_idx) return field_idx;
            }
            boxyLowerInvariant("record field descriptor lookup referenced a field outside declared field order");
        }

        var index: u32 = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => {
                    if (index == field_idx) return field_idx;
                    index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record field descriptor lookup representation had a non-record child role"),
            }
        }
        boxyLowerInvariant("record field descriptor lookup referenced a field outside its representation");
    }

    /// Whether the value stored in field `field_idx` of `rep_id`'s payload
    /// carries a runtime descriptor, rather than having only a static identity.
    fn payloadFieldCarriesRuntimeDesc(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        field_idx: u32,
    ) bool {
        const field_layout = self.parent.recordPayloadFieldLayout(self.parent.descriptorPayloadLayoutForRep(rep_id), field_idx);
        return self.parent.layoutIsBoxStorage(field_layout) or self.parent.layoutNeedsNestedBoxyDesc(field_layout);
    }

    /// Position of tuple element `elem_index` in its tuple descriptor's nested
    /// descriptors: its element index.
    fn tupleElemNestedDescriptorIndex(
        self: *const ProcBodyBuilder,
        tuple_rep_id: Plan.TypeRepId,
        elem_index: u32,
    ) u32 {
        const rep = self.parent.plan.representations.items[@backingInt(tuple_rep_id)];
        for (self.parent.plan.childSlice(rep.children)) |child| {
            const index = switch (child.role) {
                .tuple_elem => |index| index,
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple descriptor lookup representation had a non-tuple child role"),
            };
            if (index == elem_index) return elem_index;
        }
        boxyLowerInvariant("tuple descriptor lookup referenced an element outside its representation");
    }

    fn repHasRecordFieldChildren(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
    ) bool {
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => return true,
                .record_ext => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record field access representation had a non-record child role"),
            }
        }
        return false;
    }

    const TagVariantLookup = struct {
        index: u32,
        name: names.TagNameId,
        name_module: checked.ModuleId,
        payloads: Plan.Span,
    };

    fn tagVariantForTypeRef(
        self: *const ProcBodyBuilder,
        type_ref: Plan.CheckedTypeIdentity,
        name: names.TagNameId,
    ) TagVariantLookup {
        const requested_module = procedureModuleById(self.parent.modules, type_ref.module);
        var current = self.repForTypeRef(type_ref);
        while (true) {
            const rep = self.parent.plan.representations.items[@backingInt(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => boxyLowerInvariant("opaque or builtin nominal reached iterator tag-variant lookup"),
                },
                .tag_union,
                .dynamic,
                => return self.tagVariantForModule(rep, requested_module, name),
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("iterator step type did not have a boxy tag-union representation"),
            }
        }
    }

    fn tagVariant(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
        name: names.TagNameId,
    ) TagVariantLookup {
        return self.tagVariantForModule(rep, self.module, name);
    }

    fn tagVariantForModule(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
        requested_module: ProcedureModuleView,
        name: names.TagNameId,
    ) TagVariantLookup {
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        for (variants, 0..) |variant, index| {
            if (!self.tagVariantNameMatches(variant, requested_module, name)) continue;
            if (index > std.math.maxInt(u32)) {
                boxyLowerInvariant("tag variant index exceeded LIR variant range");
            }
            return .{
                .index = @intCast(index),
                .name = variant.name,
                .name_module = variant.name_module,
                .payloads = variant.payloads,
            };
        }
        boxyLowerInvariant("tag expression referenced a variant outside its checked type representation");
    }

    fn tagVariantNameMatches(
        self: *const ProcBodyBuilder,
        variant: Plan.TagVariant,
        requested_module: ProcedureModuleView,
        requested_name: names.TagNameId,
    ) bool {
        return std.mem.eql(
            u8,
            self.tagVariantNameText(variant),
            requested_module.canonical_names.tagLabelText(requested_name),
        );
    }

    fn tagVariantNameText(self: *const ProcBodyBuilder, variant: Plan.TagVariant) []const u8 {
        const module = procedureModuleById(self.parent.modules, variant.name_module);
        return module.canonical_names.tagLabelText(variant.name);
    }

    fn lirTagName(
        self: *ProcBodyBuilder,
        tag_name: names.TagNameId,
    ) Allocator.Error!LIR.BoxyNameId {
        return try self.parent.result.store.insertBoxyName(self.module.canonical_names.tagLabelText(tag_name));
    }

    fn lirTagNameForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        tag_name: names.TagNameId,
    ) Allocator.Error!LIR.BoxyNameId {
        const rep = self.parent.plan.representations.items[@backingInt(rep_id)];
        const module = procedureModuleById(self.parent.modules, rep.source_type.module);
        return try self.parent.result.store.insertBoxyName(module.canonical_names.tagLabelText(tag_name));
    }

    fn lirTagNameForVariant(
        self: *ProcBodyBuilder,
        variant: Plan.TagVariant,
    ) Allocator.Error!LIR.BoxyNameId {
        return try self.parent.result.store.insertBoxyName(self.tagVariantNameText(variant));
    }

    fn lirTagNameForLookup(
        self: *ProcBodyBuilder,
        variant: TagVariantLookup,
    ) Allocator.Error!LIR.BoxyNameId {
        const module = procedureModuleById(self.parent.modules, variant.name_module);
        return try self.parent.result.store.insertBoxyName(module.canonical_names.tagLabelText(variant.name));
    }

    fn boolVariantIndex(self: *const ProcBodyBuilder, name: names.TagNameId) u32 {
        return Common.boolTagDiscriminant(self.module.canonical_names.tagLabelText(name)) orelse
            boxyLowerInvariant("builtin Bool tag expression referenced a non-Bool tag");
    }

    fn tagUnionPayloadLayout(self: *const ProcBodyBuilder, tag_union_layout_idx: layout.Idx, variant_index: u32) layout.Idx {
        const tag_union_layout = self.parent.result.layouts.getLayout(tag_union_layout_idx);
        return switch (tag_union_layout.tag) {
            .tag_union => blk: {
                const data = self.parent.result.layouts.getTagUnionData(tag_union_layout.getTagUnion().idx);
                const variants = self.parent.result.layouts.getTagUnionVariants(data);
                if (variant_index >= variants.len) {
                    boxyLowerInvariant("tag payload variant exceeded committed tag-union layout");
                }
                break :blk variants.get(@intCast(variant_index)).payload_layout;
            },
            .zst, .scalar => .zst,
            .box, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .ptr => boxyLowerInvariant("tag payload operation expected tag-union layout"),
        };
    }

    fn localListElemLayout(self: *const ProcBodyBuilder, local: LIR.LocalId) layout.Idx {
        const list_layout_idx = self.parent.result.store.getLocal(local).layout_idx;
        const list_layout = self.parent.result.layouts.getLayout(list_layout_idx);
        return switch (list_layout.tag) {
            .list => list_layout.getIdx(),
            .list_of_zst => .zst,
            .scalar, .box, .box_of_zst, .erased_box, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => boxyLowerInvariant("list expression target was not a list layout"),
        };
    }

    fn layoutIsBoxyDynamicStorage(self: *const ProcBodyBuilder, layout_idx: layout.Idx) bool {
        return self.parent.result.layouts.getLayout(layout_idx).tag == .erased_box;
    }

    fn isZstLocal(self: *const ProcBodyBuilder, local: LIR.LocalId) bool {
        return self.parent.result.layouts.isZeroSized(
            self.parent.result.layouts.getLayout(self.parent.result.store.getLocal(local).layout_idx),
        );
    }
};

fn constListElemType(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    const nominal = resolvedNominalPayload(module, checked_ty);
    if (nominal.builtin != .list or nominal.args.len != 1) {
        boxyLowerInvariant("ConstStore list restored with a non-list checked type");
    }
    return nominal.args[0];
}

fn constBoxPayloadType(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    const nominal = resolvedNominalPayload(module, checked_ty);
    if (nominal.builtin != .box or nominal.args.len != 1) {
        boxyLowerInvariant("ConstStore box restored with a non-Box checked type");
    }
    return nominal.args[0];
}

fn checkedFunctionPayload(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedFunctionType {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .function => |function| function,
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("checked intrinsic wrapper did not have a function type"),
    };
}

fn constTupleItemTypes(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) []const checked.CheckedTypeId {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .tuple => |items| items,
        .pending, .err, .flex, .rigid, .alias, .record, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore tuple restored with a non-tuple checked type"),
    };
}

fn constRecordFields(allocator: Allocator, module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) Allocator.Error![]checked.CheckedRecordField {
    var fields = std.ArrayList(checked.CheckedRecordField).empty;
    errdefer fields.deinit(allocator);

    var seen = collections.DenseMap(checked.CheckedTypeId, void).init(allocator);
    defer seen.deinit();

    var current: ?checked.CheckedTypeId = checked_ty;
    while (current) |ty| {
        const entry = try seen.getOrPut(ty);
        if (entry.found_existing) {
            current = null;
            break;
        }

        switch (resolvedTypePayload(module, ty)) {
            .record => |record| {
                try fields.appendSlice(allocator, record.fields);
                current = record.ext;
            },
            .empty_record => current = null,
            .alias => |alias| current = alias.backing,
            .flex, .rigid => |variable| {
                if (variable.row_default != .empty_record) {
                    boxyLowerInvariant("ConstStore record restored with an open checked row");
                }
                current = null;
            },
            .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore record restored with a non-record checked type"),
        }
    }

    const SortContext = struct {
        names: *const names.CanonicalNameStore,

        fn lessThan(context: @This(), lhs: checked.CheckedRecordField, rhs: checked.CheckedRecordField) bool {
            return context.names.recordFieldLabelTextLessThan(lhs.name, rhs.name);
        }
    };
    std.mem.sort(checked.CheckedRecordField, fields.items, SortContext{ .names = module.canonical_names }, SortContext.lessThan);
    return try fields.toOwnedSlice(allocator);
}

fn constRowExtensionIsClosed(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId, expected: checked.RowDefault) void {
    var current = checked_ty;
    const closed = while (true) {
        switch (resolvedTypePayload(module, current)) {
            .empty_record => break expected == .empty_record,
            .empty_tag_union => break expected == .empty_tag_union,
            .alias => |alias| current = alias.backing,
            .flex, .rigid => |variable| break variable.row_default == expected,
            .record => |record| if (expected == .empty_record) {
                current = record.ext;
            } else break false,
            .tag_union => |tag_union| if (expected == .empty_tag_union) {
                current = tag_union.ext;
            } else break false,
            .pending, .err, .tuple, .nominal, .function => boxyLowerInvariant("ConstStore record restored with a non-record checked type"),
        }
    };
    if (!closed) boxyLowerInvariant("ConstStore value restored with an open checked row");
}

fn constRecordFieldIndex(fields: []const checked.CheckedRecordField, label: names.RecordFieldLabelId) ?usize {
    for (fields, 0..) |field, index| {
        if (field.name == label) return index;
    }
    return null;
}

fn checkedRecordFieldByName(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId, field_name: []const u8) checked.CheckedRecordField {
    var current = checked_ty;
    while (true) {
        switch (resolvedTypePayload(module, current)) {
            .record => |record| {
                for (record.fields) |field| {
                    if (std.mem.eql(u8, module.canonical_names.recordFieldLabelText(field.name), field_name)) return field;
                }
                current = record.ext;
            },
            .empty_record => break,
            .pending, .err, .flex, .rigid, .alias, .tuple, .nominal, .function, .tag_union, .empty_tag_union => boxyLowerInvariant("generated record field lookup received a non-record type"),
        }
    }
    boxyLowerInvariant("generated record field lookup was missing a required field");
}

const ConstTagPayloadTypes = struct {
    name: names.TagNameId,
    payload_tys: []const checked.CheckedTypeId,
};

fn constTagPayloadTypes(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
    tag_name: []const u8,
) ConstTagPayloadTypes {
    switch (resolvedTypePayload(module, checked_ty)) {
        .tag_union => {},
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("ConstStore tag restored with a non-tag-union checked type"),
    }
    constRowExtensionIsClosed(module, checked_ty, .empty_tag_union);
    // A closed row's tags can span several row segments.
    var current = checked_ty;
    while (true) {
        const tag_union = switch (resolvedTypePayload(module, current)) {
            .tag_union => |tag_union| tag_union,
            .alias => |alias| {
                current = alias.backing;
                continue;
            },
            .pending, .err, .flex, .rigid, .record, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("ConstStore tag name was missing from checked tag-union type"),
        };
        for (tag_union.tags) |tag| {
            if (std.mem.eql(u8, module.canonical_names.tagLabelText(tag.name), tag_name)) {
                return .{
                    .name = tag.name,
                    .payload_tys = tag.argsSlice(module.checked_types),
                };
            }
        }
        current = tag_union.ext;
    }
}

/// Like `constTagPayloadTypes`, but for restoration into a dynamic (open-row)
/// representation, where openness is fine: the named tag is searched through
/// the row's extension chain instead of demanding a closed row.
fn constTagPayloadTypesAllowOpen(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
    tag_name: []const u8,
) ConstTagPayloadTypes {
    var current = checked_ty;
    while (true) {
        const tag_union = switch (resolvedTypePayload(module, current)) {
            .tag_union => |tag_union| tag_union,
            .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("ConstStore tag name was missing from checked tag-union row"),
        };
        for (tag_union.tags) |tag| {
            if (std.mem.eql(u8, module.canonical_names.tagLabelText(tag.name), tag_name)) {
                return .{
                    .name = tag.name,
                    .payload_tys = tag.argsSlice(module.checked_types),
                };
            }
        }
        current = tag_union.ext;
    }
}

fn resolvedNominalPayload(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedNominalType {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .nominal => |nominal| nominal,
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore nominal child lookup reached a non-nominal checked type"),
    };
}

/// The checked type at a nominal representation's backing. A checked nominal
/// names its backing template. Any other checked type is already the
/// structure that the nominal instantiates at this position, as when an
/// unannotated worker's structural row is instantiated by a call's `Try`.
fn checkedTypeAtNominalBacking(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .nominal => resolvedNominalBacking(module, checked_ty),
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => checked_ty,
    };
}

fn resolvedNominalBacking(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    const nominal = resolvedNominalPayload(module, checked_ty);
    return module.checked_types.nominalBackingTemplateForPayload(nominal) orelse
        boxyLowerInvariant("boxy lowering requested the backing of an opaque nominal type");
}

fn checkedBuiltinNominalForType(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
) ?checked.CheckedBuiltinNominal {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .nominal => |nominal| nominal.builtin,
        .pending, .err, .flex, .rigid, .alias, .record, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => null,
    };
}

fn generatedEncoderKeyMethodForType(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
) ?[]const u8 {
    return Plan.generatedCodecScalarMethod(checkedBuiltinNominalForType(module, checked_ty) orelse return null, "encode_key_");
}

fn resolvedTypePayload(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypePayload {
    var current = checked_ty;
    while (true) {
        const payload = module.checked_types.payload(current);
        switch (payload) {
            .pending => boxyLowerInvariant("pending checked type reached boxy const lowering"),
            .err => boxyLowerInvariant("checked error type reached boxy const lowering"),
            .alias => |alias| {
                current = alias.backing;
                continue;
            },
            .flex, .rigid, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => return payload,
        }
    }
}

fn appendRequestedLayouts(
    allocator: Allocator,
    modules: Common.CheckedModules,
    roots: Common.RootRequests,
    plan: *const Plan.ProgramPlan,
    layout_plan: *const Layouts.LayoutPlan,
    procedure_builder: *ProcedureBuilder,
    result: *LirProgram.Result,
) Allocator.Error!void {
    const request_count = roots.layout_requests.len + roots.static_data_requests.len;
    if (request_count == 0) return;
    const root_rep_start = plan.roots.items.len;
    if (plan.root_reps.items.len < root_rep_start + request_count) {
        boxyLowerInvariant("boxy plan root representations did not cover requested layouts");
    }

    var const_plans = try ConstPlanBuilder.init(allocator, modules, plan, layout_plan, procedure_builder, result);
    defer const_plans.deinit();

    const root_types = modules.root.module.checked_types.view();
    for (roots.layout_requests, 0..) |checked_type, index| {
        const rep_id = plan.hostRepFor(plan.root_reps.items[root_rep_start + index]);
        try result.requested_layouts.append(allocator, .{
            .ty = root_types.rootKey(checked_type),
            .checked_type = checked_type,
            .layout_idx = layout_plan.rep_layouts[@backingInt(rep_id)].worker.layoutIdx(),
            .plan = try const_plans.constPlanForRep(rep_id),
        });
    }
    for (roots.static_data_requests, 0..) |request, index| {
        const checked_type = request.checked_type;
        const rep_id = plan.root_reps.items[root_rep_start + roots.layout_requests.len + index];
        try result.requested_layouts.append(allocator, .{
            .ty = root_types.rootKey(checked_type),
            .checked_type = checked_type,
            .layout_idx = layout_plan.rep_layouts[@backingInt(plan.hostRepFor(rep_id))].worker.layoutIdx(),
            .plan = try const_plans.constPlanForRep(rep_id),
        });
    }
}

const ConstPlanBuilder = struct {
    allocator: Allocator,
    modules: Common.CheckedModules,
    plan: *const Plan.ProgramPlan,
    layout_plan: *const Layouts.LayoutPlan,
    procedure_builder: *ProcedureBuilder,
    result: *LirProgram.Result,
    by_rep: []?LirProgram.ConstPlanId,
    runtime_sets: std.ArrayList(struct { rep: Plan.TypeRepId, key: u32, set: LirProgram.ErasedFnsId }) = .empty,

    active_context: ?u32 = null,
    active_boundary: ?*const StaticDescriptorSourceMap = null,
    contextual_plans: std.AutoHashMapUnmanaged(struct { rep: Plan.TypeRepId, context: u32 }, LirProgram.ConstPlanId) = .empty,

    fn callableKey(self: *ConstPlanBuilder, rep: Plan.TypeRepId) u32 {
        const evidence = &self.plan.literal_evidence.?;
        return if (self.active_context) |ctx| evidence.freeze_contexts.items[ctx].callable_types.get(rep).? else evidence.callable_types.get(rep).?;
    }

    /// The descriptor a frozen callable's descriptor capture holds: the one its
    /// creating frame built. A static descriptor built from none of the frame's
    /// bindings is held as is, and a closed source representation described
    /// the capture exactly. Otherwise the frame's bindings filled a generic
    /// source representation: in its own storage, instantiated by the closed
    /// type the active freeze context gives a capture the callable reads as a
    /// bare variable, and otherwise sharing the callable's representation of
    /// the capture, which the context closes.
    fn frozenCaptureDescriptor(self: *ConstPlanBuilder, capture: ProcedureBuilder.FrozenDescriptorCapture) Allocator.Error!LIR.BoxyTypeDescId {
        if (capture.exact) |id| return id;
        const source = self.plan.representations.items[@backingInt(capture.source_rep)];
        if (!source.contains_dynamic and source.kind != .dynamic) return try self.procedure_builder.typeDescForRep(capture.source_rep);
        if (self.contextClosedRep(capture.worker_rep)) |closed| {
            // The callable reads the capture as a bare variable the context
            // closes; the value keeps its creating representation's storage,
            // whose variables the closed type instantiates.
            var sources = StaticDescriptorSourceMap{};
            defer sources.deinit(self.allocator);
            var seen = std.AutoHashMap(u64, void).init(self.allocator);
            defer seen.deinit();
            try self.procedure_builder.collectStaticDescriptorSourcesForWorkerSource(capture.source_rep, closed, &.{}, .all_worker_descriptors, &sources, &seen);
            var context = StaticDescInstantiationContext{};
            defer context.deinit(self.allocator);
            return try self.procedure_builder.typeDescForWorkerRepWithSourceMap(capture.source_rep, null, &sources, &context);
        }
        return try self.closedDescriptor(capture.worker_rep);
    }

    /// The closed representation the active freeze context binds a bare
    /// variable representation to.
    fn contextClosedRep(self: *ConstPlanBuilder, rep: Plan.TypeRepId) ?Plan.TypeRepId {
        const ctx = self.active_context orelse return null;
        const info = self.plan.representations.items[@backingInt(rep)];
        if (info.kind != .dynamic) return null;
        const desc = info.descriptor orelse return null;
        const evidence = &self.plan.literal_evidence.?;
        const span = evidence.freeze_contexts.items[ctx].bindings;
        for (evidence.bindings.items[span.start..][0..span.len]) |binding| {
            if (self.plan.representations.items[@backingInt(binding.scheme_rep)].descriptor == desc) return binding.site_rep;
        }
        return null;
    }

    fn closedDescriptor(self: *ConstPlanBuilder, rep: Plan.TypeRepId) Allocator.Error!LIR.BoxyTypeDescId {
        var sources = StaticDescriptorSourceMap{};
        defer sources.deinit(self.allocator);
        if (self.active_context) |ctx| {
            const evidence = &self.plan.literal_evidence.?;
            const span = evidence.freeze_contexts.items[ctx].bindings;
            for (evidence.bindings.items[span.start..][0..span.len]) |binding| {
                if (self.plan.representations.items[@backingInt(binding.scheme_rep)].descriptor) |desc| try sources.put(self.allocator, desc, binding.site_rep);
            }
        }
        if (self.active_boundary) |boundary| {
            // The active freeze context binds its descriptors to the context's
            // closed instance; the boundary describes the descriptors it
            // leaves unbound.
            for (boundary.entries.items) |entry| {
                if (sources.get(entry.worker_desc) != null) continue;
                try sources.put(self.allocator, entry.worker_desc, entry.source_rep);
            }
        }
        var context = StaticDescInstantiationContext{};
        defer context.deinit(self.allocator);
        return try self.procedure_builder.typeDescForWorkerRepWithSourceMap(rep, null, &sources, &context);
    }

    /// Shared read-only queries over the representation plan.
    fn repQuery(self: *const ConstPlanBuilder) Plan.RepQuery {
        return .{ .plan = self.plan, .allocator = self.allocator };
    }

    fn init(
        allocator: Allocator,
        modules: Common.CheckedModules,
        plan: *const Plan.ProgramPlan,
        layout_plan: *const Layouts.LayoutPlan,
        procedure_builder: *ProcedureBuilder,
        result: *LirProgram.Result,
    ) Allocator.Error!ConstPlanBuilder {
        const by_rep = try allocator.alloc(?LirProgram.ConstPlanId, plan.representations.items.len);
        @memset(by_rep, null);
        return .{
            .allocator = allocator,
            .modules = modules,
            .plan = plan,
            .layout_plan = layout_plan,
            .procedure_builder = procedure_builder,
            .result = result,
            .by_rep = by_rep,
        };
    }

    fn deinit(self: *ConstPlanBuilder) void {
        self.contextual_plans.deinit(self.allocator);
        self.runtime_sets.deinit(self.allocator);
        self.allocator.free(self.by_rep);
        self.* = undefined;
    }

    // A representation's constant plan is built from its children's plans,
    // and children follow type nesting, so each plan still waiting on a
    // child's is a frame on one heap-backed stack. Frames allocate plan ids
    // and erased callable sets in the order a direct recursive build would.

    /// A constant plan waiting on its children's plans.
    const ConstPlanFrame = struct {
        rep_id: Plan.TypeRepId,
        /// The plan this frame fills; an alias has none of its own.
        id: LirProgram.ConstPlanId = undefined,
        /// Whether the frame's last requested child plan is still due.
        awaiting: bool = false,
        state: union(enum) {
            /// An alias shares its backing's plan.
            alias,
            dynamic: struct { saved_context: ?u32 = null, site_rep: Plan.TypeRepId = undefined },
            list,
            box,
            named,
            fields: struct {
                kind: StructPlanKind,
                role_tag: std.meta.Tag(Plan.ChildRole),
                plans: []LirProgram.ConstPlanId,
                child: usize = 0,
                cursor: usize = 0,
            },
            tag: struct {
                variants: []LirProgram.ConstTagVariant,
                initialized: usize = 0,
                /// The payload plans of `variants[initialized]` once begun.
                payloads: ?[]LirProgram.ConstPlanId = null,
                name: []u8 = &.{},
                payload: usize = 0,
            },
            erased: *ErasedFnsBuild,
        },

        fn deinit(self: *ConstPlanFrame, allocator: Allocator) void {
            switch (self.state) {
                .alias, .dynamic, .list, .box, .named => {},
                .fields => |fields| allocator.free(fields.plans),
                .tag => |tag| {
                    for (tag.variants[0..tag.initialized]) |variant| {
                        allocator.free(variant.name);
                        allocator.free(variant.payloads);
                    }
                    allocator.free(tag.variants);
                    if (tag.payloads) |payloads| {
                        allocator.free(tag.name);
                        allocator.free(payloads);
                    }
                },
                .erased => |build| {
                    build.deinit(allocator);
                    allocator.destroy(build);
                },
            }
        }
    };

    /// An erased callable set's entries, built static function by static
    /// function.
    const ErasedFnsBuild = struct {
        entries: std.ArrayList(LirProgram.ErasedFn) = .empty,
        static_index: usize = 0,
        /// The static function whose capture plans are being built.
        current: ?struct {
            entry_proc: LIR.LirProcSpecId,
            static_fn: Plan.StaticFnPlan,
            fn_value: check.ConstStore.ConstFn,
            worker_captures: []const Plan.ErasedCapture,
            slots: []LirProgram.CaptureSlot,
            slot_count: usize = 0,
            capture_index: usize = 0,
        } = null,

        fn deinit(self: *ErasedFnsBuild, allocator: Allocator) void {
            for (self.entries.items) |entry| {
                if (entry.captures.len != 0) allocator.free(entry.captures);
            }
            self.entries.deinit(allocator);
            if (self.current) |current| allocator.free(current.slots);
        }
    };

    const ConstPlanStep = union(enum) {
        /// The frame needs this representation's plan next.
        request: Plan.TypeRepId,
        /// The frame finished with this plan and was popped.
        done: LirProgram.ConstPlanId,
    };

    fn constPlanForRep(self: *ConstPlanBuilder, root: Plan.TypeRepId) Allocator.Error!LirProgram.ConstPlanId {
        const saved_context = self.active_context;
        errdefer self.active_context = saved_context;
        var frames: std.ArrayList(ConstPlanFrame) = .empty;
        defer {
            for (frames.items) |*frame| frame.deinit(self.allocator);
            frames.deinit(self.allocator);
        }
        var value = try self.beginConstPlan(root, &frames);
        while (frames.items.len != 0) {
            switch (try self.stepConstPlanFrame(&frames, value)) {
                .request => |rep_id| value = try self.beginConstPlan(rep_id, &frames),
                .done => |id| value = id,
            }
        }
        return value.?;
    }

    fn memoizeConstPlan(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId, id: LirProgram.ConstPlanId) Allocator.Error!void {
        if (self.active_context) |ctx| {
            try self.contextual_plans.put(self.allocator, .{ .rep = rep_id, .context = ctx }, id);
        } else {
            self.by_rep[@backingInt(rep_id)] = id;
        }
    }

    /// The plan of `rep_id` when already known or built without children;
    /// otherwise null, with the frame that builds it pushed.
    fn beginConstPlan(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId, frames: *std.ArrayList(ConstPlanFrame)) Allocator.Error!?LirProgram.ConstPlanId {
        const index = @backingInt(rep_id);
        if (self.active_context) |ctx| {
            if (self.contextual_plans.get(.{ .rep = rep_id, .context = ctx })) |existing| return existing;
        } else if (self.by_rep[index]) |existing| return existing;

        const rep = self.plan.representations.items[index];
        if (rep.kind == .alias) {
            try frames.append(self.allocator, .{ .rep_id = rep_id, .state = .alias });
            return null;
        }

        const id: LirProgram.ConstPlanId = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.const_plans.items.len))));
        try self.result.const_plans.append(self.allocator, .pending);
        try self.memoizeConstPlan(rep_id, id);

        const leaf: LirProgram.ConstPlan = switch (rep.kind) {
            .in_progress => boxyLowerInvariant("in-progress boxy representation reached const plan output"),
            .alias => unreachable,
            .dynamic => return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .{ .dynamic = .{} } }),
            .erased_callable => {
                const build = try self.allocator.create(ErasedFnsBuild);
                build.* = .{};
                return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .{ .erased = build } });
            },
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => boxyLowerInvariant("compiler-owned encoding evidence reached const planning before generated codec restoration"),
            .primitive => |primitive| switch (primitive) {
                .str => .str,
                .bool, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => .scalar,
            },
            .bool_tag_union => .{ .named = .{
                .named_type = .{
                    .module = moduleDigestFromId(rep.source_type.module),
                    .ty = rep.source_type.ty,
                },
                .backing = try self.appendLeafPlan(try self.boolTagUnionConstPlan(rep)),
            } },
            .empty_record,
            .empty_tag_union,
            => .zst,
            .list => return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .list }),
            .box => return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .box }),
            .record => return try self.pushStructConstPlanFrame(frames, rep_id, id, .record_field, .record),
            .tuple => return try self.pushStructConstPlanFrame(frames, rep_id, id, .tuple_elem, .tuple),
            .tag_union => {
                const variants = try self.allocator.alloc(LirProgram.ConstTagVariant, rep.tag_variants.len);
                errdefer self.allocator.free(variants);
                return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .{ .tag = .{ .variants = variants } } });
            },
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .named }),
                .opaque_nominal => boxyLowerInvariant("opaque nominal reached const plan output before opaque static-data support"),
            },
        };
        self.result.const_plans.items[@backingInt(id)] = leaf;
        return id;
    }

    fn pushConstPlanFrame(self: *ConstPlanBuilder, frames: *std.ArrayList(ConstPlanFrame), frame: ConstPlanFrame) Allocator.Error!?LirProgram.ConstPlanId {
        var pending = frame;
        frames.append(self.allocator, pending) catch |err| {
            pending.deinit(self.allocator);
            return err;
        };
        return null;
    }

    fn pushStructConstPlanFrame(
        self: *ConstPlanBuilder,
        frames: *std.ArrayList(ConstPlanFrame),
        rep_id: Plan.TypeRepId,
        id: LirProgram.ConstPlanId,
        role_tag: std.meta.Tag(Plan.ChildRole),
        kind: StructPlanKind,
    ) Allocator.Error!?LirProgram.ConstPlanId {
        const rep = self.plan.representations.items[@backingInt(rep_id)];
        var count: usize = 0;
        for (self.plan.childSlice(rep.children)) |child| {
            if (std.meta.activeTag(child.role) == role_tag) count += 1;
        }
        const plans = try self.allocator.alloc(LirProgram.ConstPlanId, count);
        errdefer self.allocator.free(plans);
        return try self.pushConstPlanFrame(frames, .{ .rep_id = rep_id, .id = id, .state = .{ .fields = .{
            .kind = kind,
            .role_tag = role_tag,
            .plans = plans,
        } } });
    }

    fn finishConstPlanFrame(self: *ConstPlanBuilder, frames: *std.ArrayList(ConstPlanFrame), plan: LirProgram.ConstPlan) ConstPlanStep {
        var frame = frames.pop().?;
        self.result.const_plans.items[@backingInt(frame.id)] = plan;
        frame.deinit(self.allocator);
        return .{ .done = frame.id };
    }

    fn stepConstPlanFrame(self: *ConstPlanBuilder, frames: *std.ArrayList(ConstPlanFrame), delivered: ?LirProgram.ConstPlanId) Allocator.Error!ConstPlanStep {
        const frame = &frames.items[frames.items.len - 1];
        const child_plan: ?LirProgram.ConstPlanId = if (frame.awaiting)
            delivered orelse boxyLowerInvariant("boxy const plan frame resumed without its child plan")
        else
            null;
        frame.awaiting = false;
        const rep_id = frame.rep_id;
        switch (frame.state) {
            .alias => {
                const child = child_plan orelse {
                    frame.awaiting = true;
                    return .{ .request = self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep };
                };
                try self.memoizeConstPlan(rep_id, child);
                var finished = frames.pop().?;
                finished.deinit(self.allocator);
                return .{ .done = child };
            },
            .dynamic => |*dynamic| {
                if (child_plan) |payload| {
                    self.active_context = dynamic.saved_context;
                    return self.finishConstPlanFrame(frames, .{ .boxy_box = .{
                        .payload = payload,
                        .layout_idx = self.layout_plan.rep_layouts[@backingInt(dynamic.site_rep)].worker.layoutIdx(),
                    } });
                }
                const ctx = self.active_context orelse boxyLowerInvariant("dynamic frozen value lacked its closed worker environment");
                const evidence = &self.plan.literal_evidence.?;
                const span = evidence.freeze_contexts.items[ctx].bindings;
                for (evidence.bindings.items[span.start..][0..span.len]) |binding| {
                    if (binding.scheme_rep != rep_id) continue;
                    dynamic.saved_context = self.active_context;
                    dynamic.site_rep = binding.site_rep;
                    self.active_context = null;
                    frame.awaiting = true;
                    return .{ .request = binding.site_rep };
                }
                boxyLowerInvariant("dynamic frozen value lacked a checked substitution");
            },
            .list, .box, .named => {
                const role: Plan.ChildRole = switch (frame.state) {
                    .list => .list_elem,
                    .box => .box_payload,
                    .named => .nominal_backing,
                    .alias, .dynamic, .fields, .tag, .erased => unreachable,
                };
                const child = child_plan orelse {
                    frame.awaiting = true;
                    return .{ .request = self.repQuery().requiredSingleChild(rep_id, role).rep };
                };
                const rep = self.plan.representations.items[@backingInt(rep_id)];
                return self.finishConstPlanFrame(frames, switch (frame.state) {
                    .list => .{ .list = child },
                    .box => .{ .box = child },
                    .named => .{ .named = .{
                        .named_type = .{
                            .module = moduleDigestFromId(rep.source_type.module),
                            .ty = rep.source_type.ty,
                        },
                        .backing = child,
                    } },
                    .alias, .dynamic, .fields, .tag, .erased => unreachable,
                });
            },
            .fields => |*fields| {
                if (child_plan) |plan| {
                    fields.plans[fields.cursor] = plan;
                    fields.cursor += 1;
                }
                const children = self.plan.childSlice(self.plan.representations.items[@backingInt(rep_id)].children);
                while (fields.child < children.len) {
                    const child = children[fields.child];
                    fields.child += 1;
                    if (std.meta.activeTag(child.role) != fields.role_tag) continue;
                    frame.awaiting = true;
                    return .{ .request = child.rep };
                }
                // The finished plan owns the plans.
                const plans = fields.plans;
                fields.plans = &.{};
                return self.finishConstPlanFrame(frames, switch (fields.kind) {
                    .tuple => .{ .tuple = plans },
                    .record => .{ .record = plans },
                });
            },
            .tag => |*tag| {
                const tag_variants = self.plan.tagVariantSlice(self.plan.representations.items[@backingInt(rep_id)].tag_variants);
                if (child_plan) |plan| {
                    tag.payloads.?[tag.payload] = plan;
                    tag.payload += 1;
                }
                while (tag.initialized < tag_variants.len) {
                    const variant = tag_variants[tag.initialized];
                    const payload_children = self.plan.childSlice(variant.payloads);
                    if (tag.payloads == null) {
                        const variant_names = procedureModuleById(self.modules, variant.name_module).canonical_names;
                        tag.name = try self.allocator.dupe(u8, variant_names.tagLabelText(variant.name));
                        errdefer self.allocator.free(tag.name);
                        tag.payloads = try self.allocator.alloc(LirProgram.ConstPlanId, payload_children.len);
                        tag.payload = 0;
                    }
                    if (tag.payload < payload_children.len) {
                        const child = payload_children[tag.payload];
                        switch (child.role) {
                            .tag_payload => |payload| {
                                if (payload.tag != variant.name or payload.index != tag.payload) {
                                    boxyLowerInvariant("tag variant payload span did not match its payload child roles");
                                }
                            },
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag variant payload span included a non-payload child"),
                        }
                        frame.awaiting = true;
                        return .{ .request = child.rep };
                    }
                    tag.variants[tag.initialized] = .{
                        .name = tag.name,
                        .checked_name = variant.name,
                        .discriminant = @intCast(tag.initialized),
                        .payloads = tag.payloads.?,
                    };
                    tag.initialized += 1;
                    tag.payloads = null;
                    tag.name = &.{};
                }
                // The finished plan owns the variants.
                const variants = tag.variants;
                tag.variants = &.{};
                tag.initialized = 0;
                return self.finishConstPlanFrame(frames, .{ .tag_union = variants });
            },
            .erased => |build| {
                if (try self.stepErasedFns(rep_id, build, child_plan)) |request| {
                    frame.awaiting = true;
                    return .{ .request = request };
                }
                return self.finishConstPlanFrame(frames, .{ .erased_fn = try self.finishErasedFns(rep_id, build) });
            },
        }
    }

    /// Advance an erased callable set's build: the next capture
    /// representation whose plan it needs, or null once every static
    /// function's entry is built.
    fn stepErasedFns(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId, build: *ErasedFnsBuild, delivered: ?LirProgram.ConstPlanId) Allocator.Error!?Plan.TypeRepId {
        if (delivered) |plan| {
            const current = &build.current.?;
            current.slots[current.slot_count].plan = plan;
            current.slot_count += 1;
        }
        while (true) {
            if (build.current) |*current| {
                while (current.capture_index < current.worker_captures.len) {
                    const field_index = current.capture_index;
                    current.capture_index += 1;
                    const capture = current.worker_captures[field_index];
                    if (capture.kind != .captured_value) continue;
                    const capture_id = capture.capture_id orelse
                        boxyLowerInvariant("static erased callable value capture had no checked capture id");
                    var stored_capture: ?check.ConstStore.ConstCapture = null;
                    for (current.fn_value.captures) |candidate| {
                        if (std.meta.eql(candidate.id, capture_id)) {
                            stored_capture = candidate;
                            break;
                        }
                    }
                    const source_capture = stored_capture orelse
                        boxyLowerInvariant("static erased callable capture was absent from ConstStore function");
                    current.slots[current.slot_count] = .{
                        .id = source_capture.id,
                        .slot = @intCast(field_index),
                        .ty = source_capture.ty,
                        .plan = undefined,
                        .storage = .value,
                    };
                    return capture.rep;
                }
                try build.entries.append(self.allocator, .{
                    .entry = current.entry_proc,
                    .capture_layout = self.layout_plan.workerLayoutFor(current.static_fn.worker).erased_capture_layout,
                    .template = .{
                        .fn_def = current.fn_value.fn_def,
                        .source_fn_ty = current.fn_value.source_fn_ty,
                        .source_fn_key = current.fn_value.source_fn_key,
                    },
                    .captures = current.slots,
                });
                build.current = null;
            }
            const static_fn = next: while (build.static_index < self.plan.static_fns.items.len) {
                const candidate = self.plan.static_fns.items[build.static_index];
                build.static_index += 1;
                if (candidate.rep != rep_id) {
                    if (!self.procedure_builder.needsFrozenCallableRecipes() or self.callableKey(candidate.rep) != self.callableKey(rep_id)) continue;
                }
                break :next candidate;
            } else return null;
            const entry_proc = try self.procedure_builder.reserveErasedWorkerProc(static_fn.worker);
            var duplicate = false;
            for (build.entries.items) |entry| {
                if (entry.entry == entry_proc) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) continue;

            const worker = self.plan.workers.items[@backingInt(static_fn.worker)];
            const worker_captures = self.plan.erasedCaptureSlice(worker.erased_captures);
            const store_module = procedureModuleById(self.modules, static_fn.store_module);
            const fn_value = store_module.const_store.getFn(static_fn.fn_id);

            var value_capture_count: usize = 0;
            for (worker_captures) |capture| {
                switch (capture.kind) {
                    .captured_value => value_capture_count += 1,
                    .hidden_desc, .hidden_dict, .hidden_literal => boxyLowerInvariant("static erased callable required hidden descriptor or dictionary captures"),
                }
            }
            if (value_capture_count != fn_value.captures.len) {
                boxyLowerInvariant("static erased callable capture plan disagreed with ConstStore captures");
            }
            build.current = .{
                .entry_proc = entry_proc,
                .static_fn = static_fn,
                .fn_value = fn_value,
                .worker_captures = worker_captures,
                .slots = try self.allocator.alloc(LirProgram.CaptureSlot, value_capture_count),
            };
        }
    }

    /// Record a finished erased callable set, or the runtime set it shares.
    fn finishErasedFns(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId, build: *ErasedFnsBuild) Allocator.Error!LirProgram.ErasedFnsId {
        if (self.procedure_builder.needsFrozenCallableRecipes()) {
            for (self.runtime_sets.items) |existing| if (self.callableKey(rep_id) == existing.key) return existing.set;
        }
        try self.result.erased_fns.ensureUnusedCapacity(self.allocator, 1);
        const owned_entries = try build.entries.toOwnedSlice(self.allocator);
        const id: LirProgram.ErasedFnsId = @fromBackingInt(@intCast(self.result.erased_fns.items.len));
        self.result.erased_fns.appendAssumeCapacity(.{
            .layout = self.layout_plan.rep_layouts[@backingInt(rep_id)].worker.layoutIdx(),
            .entries = owned_entries,
        });
        if (self.procedure_builder.needsFrozenCallableRecipes()) try self.runtime_sets.append(self.allocator, .{ .rep = rep_id, .key = self.callableKey(rep_id), .set = id });
        return id;
    }

    fn appendLeafPlan(self: *ConstPlanBuilder, plan: LirProgram.ConstPlan) Allocator.Error!LirProgram.ConstPlanId {
        const id: LirProgram.ConstPlanId = @fromBackingInt(@intCast(@as(u32, @intCast(self.result.const_plans.items.len))));
        try self.result.const_plans.append(self.allocator, plan);
        return id;
    }

    fn boolTagUnionConstPlan(self: *ConstPlanBuilder, rep: Plan.TypeRepresentation) Allocator.Error!LirProgram.ConstPlan {
        const module = procedureModuleById(self.modules, rep.source_type.module);
        const nominal = resolvedNominalPayload(module, rep.source_type.ty);
        const backing = module.checked_types.nominalBackingTemplateForPayload(nominal) orelse
            boxyLowerInvariant("boxy const planning requested the backing of an opaque nominal type");
        const tag_union = switch (resolvedTypePayload(module, backing)) {
            .tag_union => |tag_union| tag_union,
            .pending, .err, .flex, .rigid, .alias, .record, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("Bool nominal backing was not a checked tag union"),
        };
        const variants = try self.allocator.alloc(LirProgram.ConstTagVariant, tag_union.tags.len);
        var initialized: usize = 0;
        errdefer {
            for (variants[0..initialized]) |variant| self.allocator.free(variant.name);
            self.allocator.free(variants);
        }
        for (tag_union.tags, variants) |tag, *variant| {
            if (tag.argsSlice(module.checked_types).len != 0) {
                boxyLowerInvariant("Bool checked tag carried a payload");
            }
            const name_text = module.canonical_names.tagLabelText(tag.name);
            const discriminant = Common.boolTagDiscriminant(name_text) orelse
                boxyLowerInvariant("Bool checked tag union contained a non-boolean tag");
            variant.* = .{
                .name = try self.allocator.dupe(u8, name_text),
                .checked_name = tag.name,
                .discriminant = discriminant,
            };
            initialized += 1;
        }
        return .{ .tag_union = variants };
    }

    fn finishRuntimeCallables(self: *ConstPlanBuilder) Allocator.Error!void {
        var set_cursor: usize = 0;
        while (set_cursor < self.runtime_sets.items.len) : (set_cursor += 1) {
            const demand = self.runtime_sets.items[set_cursor];
            var entries = std.ArrayList(LirProgram.ErasedFn).empty;
            errdefer {
                for (entries.items) |entry| {
                    if (entry.boxy) |boxy| self.allocator.free(boxy.captures);
                    self.allocator.free(entry.captures);
                }
                entries.deinit(self.allocator);
            }
            const existing = self.result.erased_fns.items[@backingInt(demand.set)].entries;
            try entries.appendSlice(self.allocator, existing);
            self.allocator.free(existing);
            self.result.erased_fns.items[@backingInt(demand.set)].entries = &.{};
            var cursor: usize = 0;
            while (cursor < self.procedure_builder.frozen_callable_recipes.items.len) : (cursor += 1) {
                const recipe = self.procedure_builder.frozen_callable_recipes.items[cursor];
                for (self.plan.literal_evidence.?.freeze_contexts.items, 0..) |context, context_index| {
                    if (context.worker != recipe.worker) continue;
                    if (!std.meta.eql(context.literal_initializer, recipe.literal_initializer)) continue;
                    self.active_context = @intCast(context_index);
                    defer self.active_context = null;
                    // An adapter's wrapped value retains the source worker's
                    // declared erased ABI. Its own captured descriptors select
                    // the closed instance when that inner value is frozen.
                    if (demand.key != self.callableKey(recipe.rep) and demand.key != self.plan.literal_evidence.?.callable_types.get(recipe.rep).?) continue;
                    var boundary = StaticDescriptorSourceMap{};
                    defer boundary.deinit(self.allocator);
                    if (recipe.source_rep != recipe.rep) {
                        var seen = std.AutoHashMap(u64, void).init(self.allocator);
                        defer seen.deinit();
                        try self.procedure_builder.collectStaticDescriptorSourcesForWorkerSource(recipe.source_rep, recipe.rep, &.{}, .all_worker_descriptors, &boundary, &seen);
                        var retained: usize = 0;
                        for (boundary.entries.items) |entry| {
                            if (self.plan.representations.items[@backingInt(entry.source_rep)].descriptor == entry.worker_desc) continue;
                            boundary.entries.items[retained] = entry;
                            retained += 1;
                        }
                        boundary.entries.shrinkRetainingCapacity(retained);
                    }
                    self.active_boundary = &boundary;
                    defer self.active_boundary = null;
                    const has_contents = recipe.on_drop == .boxy_capture;
                    const fields = try self.allocator.alloc(LirProgram.BoxyFrozenCapture, recipe.fields.len + @intFromBool(has_contents));
                    errdefer self.allocator.free(fields);
                    for (recipe.fields, fields[0..recipe.fields.len], 0..) |field, *out, slot| {
                        out.* = .{ .slot = @intCast(slot), .value = switch (field) {
                            .value => |rep| .{ .value = try self.constPlanForRep(rep) },
                            .descriptor => |descriptor| .{ .descriptor = try self.frozenCaptureDescriptor(descriptor) },
                            .dictionary => |span| blk: {
                                for (self.plan.directCallHiddenDictionaryArgSlice(context.dictionaries)) |arg| {
                                    if (!std.meta.eql(arg.worker_dictionaries, span)) continue;
                                    break :blk .{ .dictionary = (try self.procedure_builder.staticDictRefForRepWithEvidence(arg.rep, arg.worker_dictionaries, arg.method_evidence, arg.env)).static };
                                }
                                boxyLowerInvariant("frozen dictionary capture lacked its checked evidence");
                            },
                            .literal => |ordinal| blk: {
                                const args = self.plan.directCallHiddenDictionaryArgSlice(context.dictionaries);
                                var index: u32 = 0;
                                for (args) |arg| {
                                    if (arg.source != .literal) continue;
                                    if (index == ordinal) break :blk .{ .dictionary = try self.procedure_builder.emitLiteralAccessor(arg.source.literal.result) };
                                    index += 1;
                                }
                                boxyLowerInvariant("frozen literal capture lacked its closed value");
                            },
                        } };
                    }
                    if (has_contents) {
                        // Resolve descriptors before appending the contiguous field span.
                        var refs = std.ArrayList(LIR.BoxyDescRef).empty;
                        defer refs.deinit(self.allocator);
                        for (recipe.fields) |field| try refs.append(self.allocator, .{ .static = switch (field) {
                            .value => |rep| try self.closedDescriptor(rep),
                            .descriptor, .dictionary, .literal => try self.procedure_builder.internalPointerTypeDesc(),
                        } });
                        try refs.append(self.allocator, .{ .static = try self.procedure_builder.internalPointerTypeDesc() });
                        const nested_start: u32 = @intCast(self.result.boxy_desc_refs.items.len);
                        try self.result.boxy_desc_refs.appendSlice(self.allocator, refs.items);
                        const desc: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(self.result.boxy_type_descs.items.len));
                        try self.result.boxy_type_descs.append(self.allocator, .{
                            .payload_layout = recipe.capture_layout,
                            .contains_refcounted = self.result.layouts.layoutContainsRefcounted(self.result.layouts.getLayout(recipe.capture_layout)),
                            .shape = .internal,
                            .nested_descs = .{ .start = nested_start, .len = @intCast(refs.items.len) },
                        });
                        fields[recipe.fields.len] = .{ .slot = @intCast(recipe.fields.len), .value = .{ .contents_descriptor = desc } };
                    }
                    var key = recipe.key;
                    var hash = base.Sha256.init(.{});
                    hash.update(&key);
                    const identity: u32 = @intCast(context_index);
                    hash.update(std.mem.asBytes(&identity));
                    hash.final(&key);
                    try entries.append(self.allocator, .{
                        .entry = recipe.entry,
                        .capture_layout = recipe.capture_layout,
                        .on_drop = .none,
                        .boxy = .{ .key = key, .result_desc = try self.closedDescriptor(recipe.result_rep), .captures = fields },
                    });
                    const entry_spec = self.result.store.getProcSpecPtr(recipe.entry);
                    if (entry_spec.static_erased_capture_layout) |recorded| {
                        if (recorded != recipe.capture_layout) boxyLowerInvariant("frozen erased worker had two capture layouts");
                    } else entry_spec.static_erased_capture_layout = recipe.capture_layout;
                }
            }
            self.result.erased_fns.items[@backingInt(demand.set)].entries = try entries.toOwnedSlice(self.allocator);
        }
    }

    const StructPlanKind = enum {
        tuple,
        record,
    };
};

fn planTypeRefEql(a: Plan.CheckedTypeIdentity, b: Plan.CheckedTypeIdentity) bool {
    return a.ty == b.ty and checked_moduleKeyEqual(a.module, b.module);
}

fn planExprRefEql(a: Plan.CheckedExprIdentity, b: Plan.CheckedExprIdentity) bool {
    return a.expr == b.expr and checked_moduleKeyEqual(a.module, b.module);
}

fn optionalPlanTypeRefEql(a: ?Plan.CheckedTypeIdentity, b: ?Plan.CheckedTypeIdentity) bool {
    if (a) |a_value| return if (b) |b_value| planTypeRefEql(a_value, b_value) else false;
    return b == null;
}

/// The format method (`prefix` plus the scalar's name) that reads or writes a
/// scalar representation, looking through aliases.
fn generatedCodecScalarMethodForRep(plan: *const Plan.ProgramPlan, root: Plan.TypeRepId, comptime prefix: []const u8) ?[]const u8 {
    var rep_id = root;
    while (true) return switch (plan.representations.items[@backingInt(rep_id)].kind) {
        .alias => {
            rep_id = requiredPlanChild(plan, rep_id, .alias_backing).rep;
            continue;
        },
        .primitive => |primitive| switch (primitive) {
            .str => prefix ++ "str",
            .u8 => prefix ++ "u8",
            .i8 => prefix ++ "i8",
            .u16 => prefix ++ "u16",
            .i16 => prefix ++ "i16",
            .u32 => prefix ++ "u32",
            .i32 => prefix ++ "i32",
            .u64 => prefix ++ "u64",
            .i64 => prefix ++ "i64",
            .u128 => prefix ++ "u128",
            .i128 => prefix ++ "i128",
            .dec => prefix ++ "dec",
            .f32 => prefix ++ "f32",
            .f64 => prefix ++ "f64",
            .bool => prefix ++ "bool",
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => null,
        },
        .bool_tag_union => prefix ++ "bool",
        .in_progress, .dynamic, .erased_callable, .record, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => null,
    };
}

fn requiredPlanChild(
    plan: *const Plan.ProgramPlan,
    rep_id: Plan.TypeRepId,
    role: Plan.ChildRole,
) Plan.RepChild {
    const rep = plan.representations.items[@backingInt(rep_id)];
    for (plan.childSlice(rep.children)) |child| {
        if (Plan.sameChildRoleKind(child.role, role)) return child;
    }
    boxyLowerInvariant("generated codec representation was missing a required child");
}

fn hiddenDescriptorParamContains(
    params: []const Plan.HiddenDescriptorParam,
    desc: Plan.DescriptorRequirementId,
) bool {
    for (params) |param| {
        if (param.desc == desc) return true;
    }
    return false;
}

fn hiddenDescriptorParamIndex(
    params: []const Plan.HiddenDescriptorParam,
    desc: Plan.DescriptorRequirementId,
) ?u32 {
    for (params, 0..) |param, index| {
        if (param.desc == desc) return @intCast(index);
    }
    return null;
}

fn layoutIsList(value: layout.Layout) bool {
    return value.tag == .list or value.tag == .list_of_zst;
}

fn appendUniqueLocal(allocator: Allocator, list: *std.ArrayList(LIR.LocalId), local: LIR.LocalId) Allocator.Error!void {
    for (list.items) |existing| {
        if (existing == local) return;
    }
    try list.append(allocator, local);
}

fn moduleDigestFromId(key: checked.ModuleId) names.CheckedModuleDigest {
    return .{ .bytes = key.bytes };
}

fn lirSymbol(symbol: Common.Symbol) LIR.Symbol {
    return LIR.Symbol.fromRaw(@intCast(@backingInt(symbol)));
}

fn boxyLowerInvariant(comptime message: []const u8) noreturn {
    if (comptime zig_builtin.mode == .debug and zig_builtin.target.os.tag == .freestanding) {
        base.invariant("{s}", .{"boxy lower invariant violated: " ++ message});
    } else if (comptime zig_builtin.mode == .debug) {
        base.invariant("boxy lower invariant violated: {s}", .{message});
    }
    unreachable;
}

test "boxy call adapters distinguish static templates from runtime descriptors" {
    const static_id: LIR.BoxyTypeDescId = @fromBackingInt(@intCast(fixtureTableIndex(0)));
    try std.testing.expectEqual(
        ProcBodyBuilder.DescriptorMaterialization{ .desc = .{ .static = static_id } },
        ProcBodyBuilder.resultDescriptorTemplate(.{ .desc = .{ .static = static_id } }).?,
    );
    try std.testing.expect(ProcBodyBuilder.resultDescriptorTemplate(.{
        .desc = .{ .local = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .template = .{ .desc = .{ .runtime = 0 } },
    }) == null);
}

test "descriptor materialization captures close over recursive template graphs" {
    const gpa = std.testing.allocator;
    var result = try LirProgram.Result.init(gpa, .native);
    defer result.deinit();

    const captured = try result.store.addLocal(.{ .layout_idx = .opaque_ptr });
    const target = try result.store.addLocal(.{ .layout_idx = .opaque_ptr });
    try result.boxy_desc_refs.appendSlice(gpa, &.{
        .{ .static = @fromBackingInt(@intCast(1)) },
        .{ .static = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .{ .local = captured },
    });
    try result.boxy_type_descs.appendSlice(gpa, &.{
        .{
            .payload_layout = .opaque_ptr,
            .contains_refcounted = false,
            .shape = .internal,
            .nested_descs = .{ .start = 0, .len = 1 },
        },
        .{
            .payload_layout = .opaque_ptr,
            .contains_refcounted = false,
            .shape = .internal,
            .nested_descs = .{ .start = 1, .len = 2 },
        },
    });

    const ret = try result.store.addCFStmt(.{ .ret = .{ .value = target } }, ProcedureBuilder.constructlessOrigin(.scaffold));
    const materialize = try result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
        .target = target,
        .desc = .{ .static = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .next = ret,
    } }, ProcedureBuilder.constructlessOrigin(.scaffold));
    _ = try result.store.addProcSpec(.{
        .name = LIR.Symbol.fromRaw(0),
        .identity = LIR.ProcIdentity.forTest(1),
        .args = LIR.LocalSpan.empty(),
        .frame_locals = try result.store.addLocalSpan(&.{ captured, target }),
        .body = materialize,
        .ret_layout = .opaque_ptr,
    }, .none);

    var builder = ProcedureBuilder.init(gpa, undefined, undefined, undefined, undefined, &result, .{});
    try builder.finalizeDescriptorMaterializationCaptures();

    const assign = result.store.getCFStmt(materialize).assign_boxy_desc_ref;
    const captures = result.store.getLocalSpan(assign.captures);
    try std.testing.expectEqual(@as(usize, 1), GuardedList.borrowLen(captures));
    try std.testing.expectEqual(captured, GuardedList.at(captures, 0));
}

test "boxy lowerer returns an empty LIR program for an empty plan" {
    const gpa = std.testing.allocator;

    var canonical_names = names.CanonicalNameStore.init(gpa);
    const module_name = try canonical_names.internModuleName("Test");
    var module_env = try can.ModuleEnv.init(gpa, "");
    defer module_env.deinit();
    var artifact = checked.CheckedModuleArtifact{
        .key = .{},
        .canonical_names = canonical_names,
        .module_identity = .{
            .module_idx = 0,
            .module_name = module_name,
            .display_module_name = module_name,
            .kind = .package,
        },
        .checking_context_identity = .{},
        .module_env = .{ .checked_source = &module_env },
        .exports = .{},
        .provides_requires = .{},
        .method_registry = .{},
        .static_dispatch_plans = .{},
        .resolved_value_refs = .{},
        .checked_procedure_templates = .{},
        .top_level_procedure_bindings = .{},
        .root_requests = .{},
        .hosted_procs = .{},
        .platform_required_declarations = .{},
        .platform_required_bindings = .{},
        .interface_capabilities = .{},
        .compile_time_roots = .{},
        .top_level_values = .{},
        .hoisted_constants = .{},
        .const_templates = .{},
        .const_store = check.ConstStore.ConstStore.init(gpa),
    };
    defer {
        artifact.const_store.deinit();
        artifact.canonical_names.deinit();
    }
    var plan = Plan.ProgramPlan.init(gpa);
    defer plan.deinit();

    var out = try run(gpa, .{ .root = .{ .module = &artifact, .roots = &artifact.root_requests } }, .{}, &plan, .{});
    defer out.deinit();

    try std.testing.expectEqual(@as(usize, 0), out.lir_result.store.procSpecCount());
    try std.testing.expectEqual(@as(usize, 0), out.lir_result.root_procs.items.len);
}

fn expectResolvedWorkerCheckedExpr(
    worker: ResolvedWorker,
    expected_body: ?checked.CheckedBodyId,
    expected_root: checked.CheckedExprId,
) error{ TestExpectedEqual, TestUnexpectedResult }!void {
    const body = switch (worker.body) {
        .checked_expr => |checked_body| checked_body,
        .intrinsic, .hosted, .unimplemented, .const_crash, .generated_codec, .generated_field_iterator => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(expected_body, body.body_id);
    try std.testing.expectEqual(expected_root, body.root_expr);
}

test "boxy lowerer resolves procedure-template workers to checked bodies" {
    const gpa = std.testing.allocator;

    var checked_module = minimalCheckedArtifact(gpa);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(gpa);
    defer checked_module.checked_bodies.deinit(gpa);

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.bodies.append(gpa, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .root_expr = @fromBackingInt(@intCast(3)),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @fromBackingInt(@intCast(9)), @fromBackingInt(@intCast(fixtureTableIndex(0)))),
    };
    checked_module.checked_procedure_templates = .{ .templates = .{ .items = &templates, .capacity = templates.len, .pointer_stability = .{} } };

    var plan = Plan.ProgramPlan.init(gpa);
    defer plan.deinit();
    try plan.workers.append(gpa, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .root_request = dummyRootRequest(),
        .source = .{ .procedure_template = template_ref },
        .checked_type = .{ .ty = @fromBackingInt(@intCast(9)) },
        .rep = @fromBackingInt(@intCast(fixtureTableIndex(0))),
    });

    var resolved = try ResolvedWorkers.init(gpa, .{ .root = .{ .module = &checked_module, .roots = undefined } }, &plan);
    defer resolved.deinit();

    try std.testing.expectEqual(@as(usize, 1), resolved.items.len);
    try std.testing.expectEqual(@as(Plan.WorkerPlanId, @fromBackingInt(@intCast(fixtureTableIndex(0)))), resolved.items[0].worker);
    try std.testing.expect(names.procedureTemplateRefEql(
        template_ref,
        resolved.items[0].template_ref orelse return error.TestUnexpectedResult,
    ));
    try expectResolvedWorkerCheckedExpr(resolved.items[0], @fromBackingInt(@intCast(fixtureTableIndex(0))), @fromBackingInt(@intCast(3)));
}

test "boxy lowerer resolves top-level direct bindings to checked bodies" {
    const gpa = std.testing.allocator;

    var checked_module = minimalCheckedArtifact(gpa);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(gpa);
    defer checked_module.checked_bodies.deinit(gpa);

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.bodies.append(gpa, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .root_expr = @fromBackingInt(@intCast(5)),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @fromBackingInt(@intCast(7)), @fromBackingInt(@intCast(fixtureTableIndex(0)))),
    };
    checked_module.checked_procedure_templates = .{ .templates = .{ .items = &templates, .capacity = templates.len, .pointer_stability = .{} } };

    var bindings = [_]checked.TopLevelProcedureBinding{
        .{
            .source_scheme = typeSchemeKey(1),
            .body = .{ .direct_template = .{
                .proc_value = procedureValueRef(template_ref),
                .template = .{ .checked = template_ref },
            } },
        },
    };
    checked_module.top_level_procedure_bindings = .{ .bindings = .{ .items = &bindings, .capacity = bindings.len, .pointer_stability = .{} } };

    var plan = Plan.ProgramPlan.init(gpa);
    defer plan.deinit();
    try plan.workers.append(gpa, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
