test "boxy lowerer restores top-level consts from resolved local lookups" {
    try expectBoxyTopLevelConstLookup(.local, .value);
}

test "boxy lowerer restores top-level consts from resolved external lookups" {
    try expectBoxyTopLevelConstLookup(.external, .value);
}

test "boxy lowerer restores a checked-error top-level const as a checked-error crash" {
    try expectBoxyTopLevelConstLookup(.local, .checked_error);
    try expectBoxyTopLevelConstLookup(.external, .checked_error);
}

const ConstLookupExprKind = enum {
    local,
    external,
};

/// What the looked-up constant's root stored: the value 5, or the checked
/// error its evaluation stopped at.
const ConstLookupStoredKind = enum {
    value,
    checked_error,
};

fn expectBoxyTopLevelConstLookup(kind: ConstLookupExprKind, stored: ConstLookupStoredKind) (Allocator.Error || error{ TestExpectedEqual, TestUnexpectedResult })!void {
    const gpa = std.testing.allocator;

    var checked_module = minimalCheckedArtifact(gpa);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(gpa);
    defer checked_module.checked_bodies.deinit(gpa);
    checked_module.const_templates = .{};
    defer checked_module.const_templates.deinit(gpa);
    checked_module.const_store = check.ConstStore.ConstStore.init(gpa);
    defer checked_module.const_store.deinit();

    try checked_module.checked_types.payloads.append(gpa, .{
        .nominal = builtinNominal(.u64, @fromBackingInt(@intCast(fixtureTableIndex(0))), .{}),
    });
    try checked_module.checked_types.payloads.append(gpa, .{
        .function = .{
            .kind = .pure,
            .args = .{},
            .ret = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        },
    });

    const const_ref = try checked_module.const_templates.reserveTopLevel(
        gpa,
        checked_module.key,
        0,
        @fromBackingInt(@intCast(fixtureTableIndex(0))),
        typeSchemeKey(7),
    );
    const const_node = switch (stored) {
        .value => try checked_module.const_store.append(.{ .scalar = .{ .u64 = 5 } }),
        .checked_error => blk: {
            const message = "method dispatch failed to check";
            const data = try checked_module.const_store.addBlobData(message);
            break :blk try checked_module.const_store.append(.{ .checked_error = .{
                .data = data,
                .offset = 0,
                .len = message.len,
            } });
        },
    };
    const root_type = try checked_module.const_store.type_store.append(.{ .primitive = .u64 });
    checked_module.const_templates.fillStoredConst(const_ref, .{ .node = const_node, .root_type = root_type });
    var compile_time_roots = [_]checked.CompileTimeRoot{.{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .module_idx = 0,
        .kind = .constant,
        .source = .{ .def = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .pattern = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .expr = @fromBackingInt(@intCast(1)),
        .checked_type = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .request_eligibility = .eligible,
        .payload = .{ .const_node = const_node },
    }};
    checked_module.compile_time_roots = .{ .roots = &compile_time_roots };

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.stored_exprs.append(gpa, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .ty = @fromBackingInt(@intCast(1)),
        .source_region = base.Region.zero(),
        .data = .{ .lambda = .{ .args = .{}, .body = @fromBackingInt(@intCast(1)) } },
    });
    try checked_module.checked_bodies.stored_exprs.append(gpa, .{
        .id = @fromBackingInt(@intCast(1)),
        .ty = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .source_region = base.Region.zero(),
        .data = switch (kind) {
            .local => .{ .lookup_local = .{
                .pattern = @fromBackingInt(@intCast(fixtureTableIndex(0))),
                .resolved = @fromBackingInt(@intCast(fixtureTableIndex(0))),
            } },
            .external => .{ .lookup_external = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        },
    });
    try checked_module.checked_bodies.bodies.append(gpa, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .root_expr = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @fromBackingInt(@intCast(1)), @fromBackingInt(@intCast(fixtureTableIndex(0)))),
    };
    checked_module.checked_procedure_templates = .{ .templates = .{ .items = &templates, .capacity = templates.len, .pointer_stability = .{} } };

    var resolved_records = [_]checked.ResolvedValueRefRecord{
        .{
            .expr = @fromBackingInt(@intCast(1)),
            .ref = .{ .top_level_const = .{
                .const_ref = const_ref,
                .requested_source_ty_template = canonicalTypeKey(1),
                .requested_source_ty_payload = @fromBackingInt(@intCast(fixtureTableIndex(0))),
            } },
            .checked_ty = @fromBackingInt(@intCast(fixtureTableIndex(0))),
            .scope_depth = 0,
        },
    };
    var refs_by_expr = [_]?checked.ResolvedValueRefId{
        null,
        @as(checked.ResolvedValueRefId, @fromBackingInt(@intCast(fixtureTableIndex(0)))),
    };
    checked_module.resolved_value_refs = .{
        .records = &resolved_records,
        .by_checked_expr = &refs_by_expr,
    };

    const root = checked.RootRequest{
        .order = 0,
        .module_idx = 0,
        .kind = .runtime_entrypoint,
        .source = .{ .def = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .checked_type = @fromBackingInt(@intCast(1)),
        .abi = .roc,
        .exposure = .private,
        .procedure_template = template_ref,
    };
    var plan = try Plan.analyzeProgram(gpa, .{
        .root_module = .{ .module = &checked_module, .roots = undefined },
        .roots = &.{root},
    }, .{});
    defer plan.deinit();

    var out = try run(
        gpa,
        .{ .root = .{ .module = &checked_module, .roots = undefined } },
        .{},
        &plan,
        .{},
    );
    defer out.deinit();

    const proc = out.lir_result.store.getProcSpec(out.lir_result.root_procs.items[0]);
    const body = out.lir_result.store.getCFStmt(proc.body orelse return error.TestUnexpectedResult);
    switch (stored) {
        .value => {},
        .checked_error => {
            try std.testing.expect(body == .crash and body.crash.checked_error);
            return;
        },
    }
    const assign = body.assign_literal;
    switch (assign.value) {
        .i128_literal => |literal| {
            try std.testing.expectEqual(@as(i128, 5), literal.value);
            try std.testing.expectEqual(@as(@TypeOf(literal.layout_idx), .u64), literal.layout_idx);
        },
        .i64_literal, .f64_literal, .f32_literal, .dec_literal, .str_literal, .boxy_dynamic_num_literal, .boxy_dynamic_frac_literal, .static_data, .bytes_literal, .proc_ref => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(LIR.CFStmt{ .ret = .{ .value = assign.target } }, out.lir_result.store.getCFStmt(assign.next));
}

