    try std.testing.expectEqual(@as(usize, 1), plan.workers.items.len);
    try std.testing.expectEqual(plan.roots.items[0].worker, plan.directWorkerForCall(
        .{ .module = checked_module.key, .expr = @fromBackingInt(@intCast(1)) },
        plan.roots.items[0].worker,
    ) orelse return error.TestUnexpectedResult);

    var out = try run(
        gpa,
        .{ .root = .{ .module = &checked_module, .roots = undefined } },
        .{},
        &plan,
        .{},
    );
    defer out.deinit();

    try std.testing.expectEqual(@as(usize, 1), out.lir_result.root_procs.items.len);
    try std.testing.expectEqual(@as(usize, 1), out.lir_result.store.procSpecCount());

    const proc_id = out.lir_result.root_procs.items[0];
    const proc = out.lir_result.store.getProcSpec(proc_id);
    const body = skipLeadingDescriptorInitializers(
        &out.lir_result.store,
        proc.body orelse return error.TestUnexpectedResult,
    );
    const call = out.lir_result.store.getCFStmt(body).assign_call;
    try std.testing.expectEqual(proc_id, call.proc);
    try std.testing.expect(call.args.isEmpty());
    // A U64 result carries no descriptor, so the call to the unfinished
    // worker needs no provisional descriptor form.
    try std.testing.expect(call.out_desc == null);
    try std.testing.expectEqual(LIR.CFStmt{ .ret = .{ .value = call.target } }, out.lir_result.store.getCFStmt(call.next));
}

