    const root = checked.RootRequest{
        .order = 0,
        .module_idx = 0,
        .kind = .runtime_entrypoint,
        .source = .{ .def = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .checked_type = @fromBackingInt(@intCast(2)),
        .abi = .roc,
        .exposure = .private,
        .procedure_template = template_ref,
    };
