        .order = 0,
        .module_idx = 0,
        .kind = .runtime_entrypoint,
        .source = .{ .def = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .checked_type = @fromBackingInt(@intCast(3)),
        .abi = .roc,
        .exposure = .private,
