test "boxy lowerer emits const plans for zero-payload tag variants" {
    const gpa = std.testing.allocator;

    var checked_module = minimalCheckedArtifact(gpa);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(gpa);

    const tag_a = try checked_module.canonical_names.internTagLabel("A");
    const tag_b = try checked_module.canonical_names.internTagLabel("B");

    try checked_module.checked_types.roots.append(gpa, .{ .id = @fromBackingInt(@intCast(fixtureTableIndex(0))), .key = typeKey(0) });
    try checked_module.checked_types.roots.append(gpa, .{ .id = @fromBackingInt(@intCast(1)), .key = typeKey(1) });
    try checked_module.checked_types.roots.append(gpa, .{ .id = @fromBackingInt(@intCast(2)), .key = typeKey(2) });
    try checked_module.checked_types.type_id_pool.append(gpa, @fromBackingInt(@intCast(fixtureTableIndex(0))));
    try checked_module.checked_types.tag_pool.append(gpa, .{ .name = tag_a, .args_start = 0, .args_len = 0 });
    try checked_module.checked_types.tag_pool.append(gpa, .{ .name = tag_b, .args_start = 0, .args_len = 1 });
    try checked_module.checked_types.payloads.append(gpa, .{
        .nominal = builtinNominal(.u64, @fromBackingInt(@intCast(fixtureTableIndex(0))), .{}),
    });
    try checked_module.checked_types.payloads.append(gpa, .empty_tag_union);
    try checked_module.checked_types.payloads.append(gpa, .{
        .tag_union = .{ .tags = .{ .start = 0, .len = 2 }, .ext = @fromBackingInt(@intCast(1)) },
    });

    var plan = try Plan.analyzeProgram(gpa, .{
        .root_module = .{ .module = &checked_module, .roots = undefined },
        .layout_requests = &.{@as(checked.CheckedTypeId, @fromBackingInt(@intCast(2)))},
    }, .{});
    defer plan.deinit();

    var out = try run(
        gpa,
        .{ .root = .{ .module = &checked_module, .roots = undefined } },
        .{ .layout_requests = &.{@as(checked.CheckedTypeId, @fromBackingInt(@intCast(2)))} },
        &plan,
        .{},
    );
    defer out.deinit();

    try std.testing.expectEqual(@as(usize, 1), out.lir_result.requested_layouts.items.len);
    const requested = out.lir_result.requested_layouts.items[0];
    const const_plan = out.lir_result.const_plans.items[@backingInt(requested.plan)];
    switch (const_plan) {
        .tag_union => |variants| {
            try std.testing.expectEqual(@as(usize, 2), variants.len);
            try std.testing.expectEqualStrings("A", variants[0].name);
            try std.testing.expectEqual(tag_a, variants[0].checked_name);
            try std.testing.expectEqual(@as(u32, 0), variants[0].discriminant);
            try std.testing.expectEqual(@as(usize, 0), variants[0].payloads.len);
            try std.testing.expectEqualStrings("B", variants[1].name);
            try std.testing.expectEqual(tag_b, variants[1].checked_name);
            try std.testing.expectEqual(@as(u32, 1), variants[1].discriminant);
            try std.testing.expectEqual(@as(usize, 1), variants[1].payloads.len);
        },
        .pending, .layout_only, .zst, .scalar, .str, .list, .box, .boxy_box, .tuple, .record, .named, .fn_value, .erased_fn => return error.TestUnexpectedResult,
    }
}

/// A shared empty ModuleEnv for test checked_modules, so lowering paths that read
/// through the checked_module's module environment (e.g. the hosted-entry section
/// scan) see valid empty data instead of undefined memory. Allocated once
/// from the page allocator so the testing allocator's leak detection stays
/// clean.
fn testEmptyModuleEnv() *can.ModuleEnv {
    const S = struct {
        var env: ?*can.ModuleEnv = null;
    };
    if (S.env) |existing| return existing;
    const page_allocator = std.heap.page_allocator;
    const env = page_allocator.create(can.ModuleEnv) catch unreachable;
    env.* = can.ModuleEnv.init(page_allocator, "") catch unreachable;
    env.initCIRFields("Test") catch unreachable;
    S.env = env;
    return env;
}

fn minimalCheckedArtifact(allocator: Allocator) checked.CheckedModuleArtifact {
    return .{
        .key = moduleKey(1),
        .canonical_names = names.CanonicalNameStore.init(allocator),
        .module_identity = testModuleIdentity(),
        .checking_context_identity = .{},
        .module_env = .{ .checked_source = testEmptyModuleEnv() },
        .exports = .{},
        .provides_requires = .{},
        .method_registry = .{},
        .static_dispatch_plans = .{},
        .resolved_value_refs = .{},
        .checked_procedure_templates = .{},
        .top_level_procedure_bindings = .{},
        .root_requests = .{},
        .hosted_procs = .{},
        .platform_required_declarations = .{},
        .platform_required_bindings = .{},
        .interface_capabilities = .{},
        .compile_time_roots = .{},
        .top_level_values = .{},
        .hoisted_constants = .{},
        .const_templates = .{},
        .const_store = check.ConstStore.ConstStore.init(allocator),
    };
}

fn testModuleIdentity() checked.ModuleIdentity {
    return .{
        .module_idx = 0,
        .module_name = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .display_module_name = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .kind = .module,
    };
}

fn moduleKey(byte: u8) checked.ModuleId {
    var key = checked.ModuleId{};
    key.bytes[0] = byte;
    return key;
}

fn typeKey(byte: u8) names.TypeDigest {
    var key = names.TypeDigest{};
    key.bytes[0] = byte;
    return key;
}

fn canonicalTypeKey(byte: u8) names.CanonicalTypeKey {
    var key = names.CanonicalTypeKey{};
    key.bytes[0] = byte;
    return key;
}

fn typeSchemeKey(byte: u8) names.CanonicalTypeSchemeKey {
    var key = names.CanonicalTypeSchemeKey{};
    key.bytes[0] = byte;
    return key;
}

fn testIntNumeral(value: u128) Allocator.Error!can.ModuleEnv.NumeralLiteral {
    return recordTestNumeral(value, 0, 0, false, false);
}

fn testSmallDecNumeral(value: can.CIR.SmallDecValue) Allocator.Error!can.ModuleEnv.NumeralLiteral {
    var divisor: u128 = 1;
    for (0..value.denominator_power_of_ten) |_| divisor *= 10;

    const magnitude: u128 = @intCast(if (value.numerator < 0) -@as(i32, value.numerator) else value.numerator);
    return recordTestNumeral(
        magnitude / divisor,
        magnitude % divisor,
        value.denominator_power_of_ten,
        value.numerator < 0,
        true,
    );
}

fn recordTestNumeral(
    before: u128,
    after: u128,
    scale: u8,
    is_negative: bool,
    is_fractional: bool,
) Allocator.Error!can.ModuleEnv.NumeralLiteral {
    var before_buffer: [16]u8 = undefined;
    var after_buffer: [16]u8 = undefined;
    const before_digits = base256Digits(before, &before_buffer);
    const after_digits = if (scale == 0) &.{} else base256Digits(after, &after_buffer);
    const env = testEmptyModuleEnv();
    const node = @as(can.CIR.Node.Idx, @fromBackingInt(@intCast(fixtureTableIndex(0))));
    try env.recordNumeralLiteral(
        node,
        before_digits,
        after_digits,
        scale,
        is_negative,
        is_fractional,
        is_fractional,
        true,
    );
    return env.numeralLiteralForNode(node) orelse unreachable;
}

fn base256Digits(value: u128, buffer: *[16]u8) []const u8 {
    var remaining = value;
    var len: usize = 0;
    while (true) {
        buffer.*[buffer.len - 1 - len] = @truncate(remaining);
        len += 1;
        remaining >>= 8;
        if (remaining == 0) return buffer.*[buffer.len - len ..];
    }
}

const ListMapCanReuseTransformRet = enum {
    u64,
    u8,
    distinct_dynamic,
};

fn lowerListMapCanReuseFixture(
    allocator: Allocator,
    transform_ret: ListMapCanReuseTransformRet,
    options: Options,
) Allocator.Error!Output {
    var checked_module = minimalCheckedArtifact(allocator);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(allocator);
    defer checked_module.checked_bodies.deinit(allocator);

    const transform_ret_ty: checked.CheckedTypeId = switch (transform_ret) {
        .u64 => @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .u8, .distinct_dynamic => @fromBackingInt(@intCast(1)),
    };

    try checked_module.checked_types.type_id_pool.appendSlice(allocator, &.{
        @as(checked.CheckedTypeId, @fromBackingInt(@intCast(fixtureTableIndex(0)))), // List(U64) element.
        @as(checked.CheckedTypeId, @fromBackingInt(@intCast(fixtureTableIndex(0)))), // Transform argument.
        @as(checked.CheckedTypeId, @fromBackingInt(@intCast(2))), // Root list argument.
        @as(checked.CheckedTypeId, @fromBackingInt(@intCast(3))), // Root transform argument.
    });
    if (transform_ret == .distinct_dynamic) {
        try checked_module.checked_types.payloads.append(allocator, .{ .flex = .{} });
        try checked_module.checked_types.payloads.append(allocator, .{ .flex = .{} });
    } else {
        try checked_module.checked_types.payloads.append(allocator, .{
            .nominal = builtinNominal(.u64, @fromBackingInt(@intCast(fixtureTableIndex(0))), .{}),
        });
        try checked_module.checked_types.payloads.append(allocator, .{
            .nominal = builtinNominal(.u8, @fromBackingInt(@intCast(1)), .{}),
        });
    }
    try checked_module.checked_types.payloads.append(allocator, .{
        .nominal = builtinNominal(.list, @fromBackingInt(@intCast(2)), .{ .start = 0, .len = 1 }),
    });
    try checked_module.checked_types.payloads.append(allocator, .{
        .function = .{
            .kind = .pure,
            .args = .{ .start = 1, .len = 1 },
            .ret = transform_ret_ty,
        },
    });
    try checked_module.checked_types.payloads.append(allocator, .{
        .function = .{
            .kind = .pure,
            .args = .{ .start = 2, .len = 2 },
            .ret = @fromBackingInt(@intCast(1)),
        },
    });

    try checked_module.checked_bodies.pattern_binders.append(allocator, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .pattern = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .reassignable = false,
    });
    try checked_module.checked_bodies.pattern_binders.append(allocator, .{
        .id = @fromBackingInt(@intCast(1)),
        .pattern = @fromBackingInt(@intCast(1)),
        .reassignable = false,
    });
    try checked_module.checked_bodies.pattern_binder_by_pattern.appendSlice(allocator, &.{
        @as(?checked.PatternBinderId, @fromBackingInt(@intCast(fixtureTableIndex(0)))),
        @as(?checked.PatternBinderId, @fromBackingInt(@intCast(1))),
    });
    try checked_module.checked_bodies.pattern_id_pool.appendSlice(allocator, &.{
        @as(checked.CheckedPatternId, @fromBackingInt(@intCast(fixtureTableIndex(0)))),
        @as(checked.CheckedPatternId, @fromBackingInt(@intCast(1))),
    });
    try checked_module.checked_bodies.stored_patterns.append(allocator, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .ty = @fromBackingInt(@intCast(2)),
        .source_region = base.Region.zero(),
        .data = .{ .assign = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
    });
    try checked_module.checked_bodies.stored_patterns.append(allocator, .{
        .id = @fromBackingInt(@intCast(1)),
        .ty = @fromBackingInt(@intCast(3)),
        .source_region = base.Region.zero(),
        .data = .{ .assign = @fromBackingInt(@intCast(1)) },
    });

    try checked_module.checked_bodies.expr_id_pool.appendSlice(allocator, &.{
        @as(checked.CheckedExprId, @fromBackingInt(@intCast(2))),
        @as(checked.CheckedExprId, @fromBackingInt(@intCast(3))),
    });

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .ty = @fromBackingInt(@intCast(4)),
        .source_region = base.Region.zero(),
        .data = .{ .lambda = .{ .args = .{ .start = 0, .len = 2 }, .body = @fromBackingInt(@intCast(1)) } },
    });
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @fromBackingInt(@intCast(1)),
        .ty = @fromBackingInt(@intCast(1)),
        .source_region = base.Region.zero(),
        .data = .{ .run_low_level = .{
            .op = .list_map_can_reuse,
            .args = .{ .start = 0, .len = 2 },
        } },
    });
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @fromBackingInt(@intCast(2)),
        .ty = @fromBackingInt(@intCast(2)),
        .source_region = base.Region.zero(),
        .data = .{ .lookup_local = .{ .pattern = @fromBackingInt(@intCast(fixtureTableIndex(0))), .resolved = null } },
    });
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @fromBackingInt(@intCast(3)),
        .ty = @fromBackingInt(@intCast(3)),
        .source_region = base.Region.zero(),
        .data = .{ .lookup_local = .{ .pattern = @fromBackingInt(@intCast(1)), .resolved = null } },
    });
    try checked_module.checked_bodies.bodies.append(allocator, .{
        .id = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .root_expr = @fromBackingInt(@intCast(fixtureTableIndex(0))),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @fromBackingInt(@intCast(4)), @fromBackingInt(@intCast(fixtureTableIndex(0)))),
    };
    checked_module.checked_procedure_templates = .{ .templates = .{ .items = &templates, .capacity = templates.len, .pointer_stability = .{} } };

    const root = checked.RootRequest{
        .order = 0,
        .module_idx = 0,
        .kind = .runtime_entrypoint,
        .source = .{ .def = @fromBackingInt(@intCast(fixtureTableIndex(0))) },
        .checked_type = @fromBackingInt(@intCast(4)),
        .abi = .roc,
        .exposure = .private,
        .procedure_template = template_ref,
    };
    var plan = try Plan.analyzeProgram(allocator, .{
        .root_module = .{ .module = &checked_module, .roots = undefined },
        .roots = &.{root},
    }, .{});
    defer plan.deinit();

    return try run(
        allocator,
        .{ .root = .{ .module = &checked_module, .roots = undefined } },
        .{},
        &plan,
        options,
    );
}

fn expectListMapCanReuseFalse(out: *Output) error{ TestExpectedEqual, TestUnexpectedResult }!void {
    const proc = out.lir_result.store.getProcSpec(out.lir_result.root_procs.items[0]);
    const body = skipLeadingDescriptorInitializers(
        &out.lir_result.store,
        proc.body orelse return error.TestUnexpectedResult,
    );
    const literal = out.lir_result.store.getCFStmt(body).assign_literal;
    switch (literal.value) {
        .i64_literal => |value| {
            try std.testing.expectEqual(@as(i64, 0), value.value);
            try std.testing.expectEqual(out.lir_result.store.getLocal(literal.target).layout_idx, value.layout_idx);
        },
        .i128_literal, .f64_literal, .f32_literal, .dec_literal, .str_literal, .boxy_dynamic_num_literal, .boxy_dynamic_frac_literal, .static_data, .bytes_literal, .proc_ref => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(LIR.CFStmt{ .ret = .{ .value = literal.target } }, out.lir_result.store.getCFStmt(literal.next));
}

fn skipLeadingDescriptorInitializers(store: *const LirStore, start: LIR.CFStmtId) LIR.CFStmtId {
    var cursor = start;
    while (true) {
        cursor = switch (store.getCFStmt(cursor)) {
            .assign_boxy_desc_ref => |assign| assign.next,
            .init_uninitialized, .assign_ref, .assign_literal, .assign_call, .assign_call_erased, .assign_packed_erased_fn, .assign_boxy_dict_ref, .assign_boxy_box, .assign_boxy_record_update, .assign_boxy_reuse_box, .assign_boxy_unbox, .assign_boxy_adapt, .assign_boxy_inspect, .assign_boxy_eq, .assign_boxy_hash, .assign_boxy_tag, .assign_boxy_tag_payload, .boxy_tag_match, .assign_call_dict, .assign_low_level, .assign_list, .assign_struct, .assign_tag, .store_struct, .store_tag, .set_local, .debug, .expect, .expect_err, .runtime_error, .comptime_exhaustiveness_failed, .comptime_branch_taken, .incref, .decref, .decref_if_initialized, .free, .switch_stmt, .switch_initialized_payload, .str_match, .str_match_set, .loop_continue, .loop_break, .join, .jump, .ret, .crash => return cursor,
        };
    }
}

fn procedureTemplateRef(key: checked.CheckedModuleArtifactKey, raw_template_id: u32) names.ProcedureTemplateRef {
    return .{
        .artifact = .{ .bytes = key.bytes },
        .proc_base = @fromBackingInt(@intCast(raw_template_id)),
        .template = @fromBackingInt(@intCast(raw_template_id)),
    };
}

fn namedProcedureTemplateRef(
    checked_module: *checked.CheckedModuleArtifact,
    raw_template_id: u32,
    proc_name: []const u8,
) Allocator.Error!names.ProcedureTemplateRef {
    const module_name = try checked_module.canonical_names.internModuleName("Test");
    const export_name = try checked_module.canonical_names.internExportName(proc_name);
    const proc_base = try checked_module.canonical_names.internProcBase(.{
        .module_name = module_name,
        .export_name = export_name,
        .kind = .checked_source,
        .ordinal = raw_template_id,
        .source_def_idx = raw_template_id,
    });
    return .{
        .artifact = .{ .bytes = checked_module.key.bytes },
        .proc_base = proc_base,
        .template = @fromBackingInt(@intCast(raw_template_id)),
    };
}

fn procedureValueRef(template: names.ProcedureTemplateRef) names.ProcedureValueRef {
    return .{
        .artifact = template.artifact,
        .proc_base = template.proc_base,
    };
}

fn checkedTemplate(
    template_ref: names.ProcedureTemplateRef,
    checked_fn_root: checked.CheckedTypeId,
    body: checked.CheckedBodyId,
) checked.CheckedProcedureTemplate {
    return .{
        .proc_base = template_ref.proc_base,
        .template_id = template_ref.template,
        .body = .{ .checked_body = body },
        .checked_fn_scheme = typeSchemeKey(9),
        .checked_fn_root = checked_fn_root,
        .static_dispatch_plans = .{},
        .direct_dispatch_plans = .{},
        .dispatch_relations = .{},
        .resolved_value_refs = .{},
        .top_level_value_uses = .{},
        .nested_proc_sites = .{},
        .target = .roc,
    };
}

